package com.shmayvan.slayerledger;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import lombok.*;
import net.runelite.client.ui.*;

/**
 * The advisor card of {@link SlayerLedgerPanel} (V2 plan 6 and 8, DESIGN_PRINCIPLES.md 3.5): the second
 * raised card, under the live section, shown while a task is assigned and the account's history is loaded. It shows
 * the model's plan to show ({@link LedgerHistoryModel#plan}) and works nothing out itself. Top to bottom:
 * <ol>
 * <li>the title, what the plan is based on ({@code Based on 6 Dust devils tasks}), on at most two lines;</li>
 * <li>the note, on parchment: a Konar task's note when its area has no task yet; the recommendation, the fastest
 * setup (name, on at most two lines, and sample size, {@code based on 1 task} for a thin recommendation; its time for
 * the kills left, and a Bring grid of at most 8 items with {@code +N more}, whose tooltip lists the rest); the All
 * setups line.</li>
 * </ol>
 * Without history the card has one line ({@link TaskPlanText#noHistoryLine}). Bundle C (owner decision
 * 2026-11-16) keeps the card as it is through the task: it no longer collapses after the first kill. Every word comes
 * from {@link TaskPlanText} and every number from {@link LedgerFormat}.
 *
 * <p>It is rebuilt only when the plan shown changes. The panel's refresh ({@link #refresh}, also run by its timer)
 * only reads the tracker for the task and never asks the model for the plan; the model's changes
 * ({@link #modelChanged}) read the plan. While the plan for the current inputs is worked out
 * ({@link LedgerHistoryModel#plan} is {@code null}, as after a kill) the card keeps the plan it shows, as long as the
 * plan is the current assignment's ({@link TaskPlan#isFor}: creature, name, task type and assigned area). A reading
 * of no task only hides the card: the count can read 0 for a tick or two
 * ({@link SessionTracker#MAX_TRANSIENT_ZERO_OBSERVATIONS}), and when the same assignment is back no model change says
 * so, since its plan is the same. Nothing in it asks for width: long names are {@link FitLabel}s, and the title,
 * option names and sentences are broken into lines at the card's fixed width. EDT only.</p>
 */
final class AdvisorCardSection
{
	/** Space between the card's parts. */
	private static final int GAP = 6;
	/** Space inside the note's 1 px edge: the card's 199 px less 2 x 6 leaves 187, room for a 184 px grid row. */
	private static final int NOTE_PADDING = 5;
	/**
	 * The width a sentence on the card wraps at: the sidebar's fixed content width less the card's frame, 199 px
	 * (DESIGN_PRINCIPLES.md 3.1).
	 */
	private static final int CARD_WRAP_WIDTH = PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET
		- 2 * LedgerTheme.CARD_PADDING;
	/** The width a sentence on the note wraps at: the card's less the note's edge and padding, 187 px. */
	private static final int NOTE_WRAP_WIDTH = CARD_WRAP_WIDTH - 2 * (1 + NOTE_PADDING);
	/**
	 * The lines the title and an option's name may take; past them the last is cut short with {@code …}, the whole
	 * text in the tooltip.
	 */
	private static final int MAX_NAME_LINES = 2;
	/** The Bring grids' title. */
	static final String BRING_TITLE = "Bring";

	/**
	 * One of the note's Bring grids and the items it shows, with its {@code +N more} label and the items that lists,
	 * so new item names only rename them.
	 */
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class BringGrid
	{
		private final ItemGridView grid;
		private final List<TaskPlan.BringItem> items;
		/** {@code +N more}, or {@code null} when the grid shows every item. */
		private final JLabel more;
		private final List<TaskPlan.BringItem> rest;
	}

	private final LedgerHistoryModel model;
	private final SessionTracker tracker;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Draws the Bring grids' icons. */
	private final ItemIcons icons;

	/** The card's row of the panel, with the gap above it: hidden as one, so a hidden card leaves no gap. */
	private final JPanel block = new JPanel(new BorderLayout());
	/** The raised card: the title and the note. */
	private final JPanel card = new JPanel();
	/** {@code Based on 6 Dust devils tasks}, one label a line. */
	private final JPanel title = column("advisor.title");
	/** The note's Bring grids as last built. */
	private final List<BringGrid> bringGrids = new ArrayList<>();

	/**
	 * The plan in the card, or {@code null} for none; kept, hidden, while no task is read, for the same assignment
	 * coming back.
	 */
	private TaskPlan shownPlan;
	/** The spot and option names shown, so a region's new name rebuilds the card only when it changes one. */
	private List<String> shownNames = Collections.emptyList();
	/** How many times the card's content was built ({@link #getBuildCount}). */
	private int builds;

	/**
	 * @param icons draws the Bring grids' item icons
	 */
	AdvisorCardSection(LedgerHistoryModel model, SessionTracker tracker, Runnable relayout, ItemIcons icons)
	{
		this.model = model;
		this.tracker = tracker;
		this.relayout = relayout;
		this.icons = icons;
		// Names for tests, which find the parts by them; no visible effect.
		block.setName("advisor");
		card.setName("advisorCard");
	}

	/** Adds the card's row to {@code content}, hidden until there is a plan to show. */
	void addTo(JPanel content)
	{
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		LedgerTheme.styleCard(card);
		block.setOpaque(false);
		block.add(card, BorderLayout.CENTER);
		block.setVisible(false);
		// Often hidden: it carries its own gap, so it leaves none then.
		SlayerLedgerPanel.addHideableRow(content, block);
	}

	/**
	 * The panel's refresh (its timer, a panel action, new live values) and the model's
	 * {@link LedgerHistoryModel.Change#LIVE} (the live inputs changed, so a task read with the panel hidden is seen):
	 * hides the card without a task, and shows it again with the plan it kept when the same assignment is back. Reads
	 * nothing of the model but whether its history is loaded, and rebuilds only when the plan it keeps is not the
	 * current assignment's.
	 */
	void refresh()
	{
		update(false);
	}

	/** A change of the history model: reads the plan to show again, and rebuilds if it changed. */
	void modelChanged()
	{
		update(true);
	}

	/**
	 * Item names arrived: renames the Bring grids' items (each grid redraws only if a name changed) and the items their
	 * {@code +N more} lists.
	 */
	void itemNamesChanged()
	{
		for (BringGrid bring : bringGrids)
		{
			bring.grid.setRows(bringRows(bring.items));
			if (bring.more != null)
			{
				bring.more.setToolTipText(bringMoreTooltip(bring.rest));
			}
		}
	}

	/** Region names arrived or were forgotten: rebuilds the card if a spot it names is called something else now. */
	void locationNamesChanged()
	{
		if (shownPlan != null && !names(shownPlan).equals(shownNames))
		{
			rebuild(shownPlan);
		}
	}

	/**
	 * Shows what the card should show now. With {@code readModel} the plan to show is read from the model (on its
	 * changes); without, only the tracker is (on the panel's refresh), and the plan shown is kept while it is the
	 * current assignment's.
	 */
	private void update(boolean readModel)
	{
		if (!model.isLoaded())
		{
			// Logged out, loading or another account's history: nothing of the last assignment is kept.
			show(null);
			return;
		}
		if (!tracker.isTaskObserved() || tracker.getCurrentRemaining() <= 0)
		{
			// No task, or the count reading 0 for a tick or two: only hidden. The plan stays for the same assignment,
			// whose return no model change announces (its plan is the same).
			setShown(false);
			return;
		}
		int creatureId = tracker.getCurrentCreatureId();
		String monster = tracker.getCurrentMonster();
		TaskContext context = tracker.getCurrentContext();
		TaskPlan plan = shownPlan;
		if (readModel)
		{
			// Null while the plan for the current inputs is worked out (a kill): the plan shown stays until it is back.
			TaskPlan current = model.plan();
			plan = current != null ? current : plan;
		}
		if (plan != null && !plan.isFor(creatureId, monster, TaskType.of(context.getMaster(), creatureId),
			context.getLocation()))
		{
			// Another assignment's plan (another creature, task type or Konar area): hidden until this one's is ready.
			plan = null;
		}
		show(plan);
	}

	/** Rebuilds the card if the plan it should show changed, and shows it while it has a plan. */
	private void show(TaskPlan plan)
	{
		if (plan != shownPlan)
		{
			rebuild(plan);
		}
		setShown(plan != null);
	}

	/** Shows or hides the card's row, with the gap above it. */
	private void setShown(boolean shown)
	{
		if (block.isVisible() != shown)
		{
			block.setVisible(shown);
			relayout.run();
		}
	}

	/** Builds the card for {@code plan}, or empties it for none. */
	private void rebuild(TaskPlan plan)
	{
		shownPlan = plan;
		card.removeAll();
		bringGrids.clear();
		shownNames = Collections.emptyList();
		if (plan != null)
		{
			builds++;
			requestRegionNames(plan);
			shownNames = names(plan);
			build(plan);
		}
		card.revalidate();
		card.repaint();
		relayout.run();
	}

	/** The card's content: with history the title and the note, else the one line. */
	private void build(TaskPlan plan)
	{
		String task = taskName(plan);
		if (!plan.hasHistory())
		{
			card.add(wrapped("advisor.noHistory", TaskPlanText.noHistoryLine(task, plan), LedgerTheme.LABEL,
				CARD_WRAP_WIDTH));
			return;
		}
		String text = TaskPlanText.cardTitle(task, plan.getAllSetups().getTasks());
		title.removeAll();
		FontMetrics bold = title.getFontMetrics(LedgerTheme.boldFont());
		for (String line : TaskPlanText.wrap(text, CARD_WRAP_WIDTH, CARD_WRAP_WIDTH, MAX_NAME_LINES, bold::stringWidth))
		{
			title.add(fitLine("advisor.title.line", line, LedgerTheme.boldFont(), LedgerTheme.HEADING));
		}
		title.setToolTipText(html(Collections.singletonList(text)));
		card.add(title);
		card.add(gapped(buildNote(plan, task), GAP));
	}

	/** The parchment note: the Konar note, the recommendation and All setups. */
	private JPanel buildNote(TaskPlan plan, String task)
	{
		JPanel note = column("advisor.note");
		note.setOpaque(true);
		note.setBackground(LedgerTheme.PARCHMENT);
		note.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LedgerTheme.PARCHMENT_EDGE, 1),
			BorderFactory.createEmptyBorder(NOTE_PADDING, NOTE_PADDING, NOTE_PADDING, NOTE_PADDING)));
		boolean perKill = !plan.hasKillsLeft();
		if (plan.isAreaFallback())
		{
			addPart(note, wrapped("advisor.areaNote", TaskPlanText.areaFallback(TaskPlanText.shortSpotName(
				plan.getAreaSpot(), model.spots(), regionNames())), LedgerTheme.MUTED_INK, NOTE_WRAP_WIDTH), 0);
		}
		TaskPlan.Option best = plan.getRecommendation();
		if (best == null)
		{
			JLabel unknown = smallLabel(TaskPlanText.SETUP_UNKNOWN, LedgerTheme.MUTED_INK);
			unknown.setName("advisor.setupUnknown");
			addPart(note, unknown, GAP);
		}
		else
		{
			addPart(note, optionBlock("advisor.recommendation", best, plan.isRecommendationThin(), task, perKill), GAP);
		}
		TaskPlan.Summary all = plan.getAllSetups();
		addPart(note, line("advisor.allSetups", TaskPlanText.allSetups(all), TaskPlanText.time(all.getTime(), perKill),
			LedgerTheme.INK, LedgerTheme.INK), GAP);
		return note;
	}

	/**
	 * The recommendation's block: its name and sample size ({@code based on 1 task} when {@code thin}), its time for
	 * the kills left, then with the kills left known what to bring.
	 */
	private JPanel optionBlock(String name, TaskPlan.Option option, boolean thin, String task, boolean perKill)
	{
		JPanel block = column(name);
		String optionName = TaskPlanText.optionName(option, task, model.spots(), regionNames());
		String tasks = TaskPlanText.optionTasks(option, thin);
		JPanel head = optionHead(name, optionName, tasks);
		head.setToolTipText(html(Arrays.asList(optionName, tasks)));
		addPart(block, head, 0);

		JLabel time = LedgerTheme.label(TaskPlanText.time(option.getTime(), perKill), LedgerTheme.boldFont(),
			LedgerTheme.INK);
		time.setName(name + ".time");
		addPart(block, time, 1);
		if (!perKill)
		{
			ItemGridView grid = new ItemGridView(BRING_TITLE, false, LedgerTheme.PARCHMENT, icons);
			grid.setName(name + ".bring");
			grid.useParchment(this::bringTooltip);
			grid.setAlignmentX(Component.LEFT_ALIGNMENT);
			grid.setRows(bringRows(option.getBring()));
			addPart(block, grid, 3);
			JLabel more = null;
			if (option.getBringMore() > 0)
			{
				// The grid shows the first items only: the rest are listed in the label's tooltip.
				more = smallLabel(TaskPlanText.bringMore(option.getBringMore()), LedgerTheme.MUTED_INK);
				more.setName(name + ".bringMore");
				more.setToolTipText(bringMoreTooltip(option.getBringRest()));
				addPart(block, more, 2);
			}
			bringGrids.add(new BringGrid(grid, option.getBring(), more, option.getBringRest()));
			Set<Integer> ids = new HashSet<>();
			for (TaskPlan.BringItem item : option.getBring())
			{
				ids.add(item.getItemId());
			}
			for (TaskPlan.BringItem item : option.getBringRest())
			{
				ids.add(item.getItemId());
			}
			if (!ids.isEmpty())
			{
				model.requestItemNames(ids);
			}
		}
		return block;
	}

	/**
	 * An option's name in Bold on at most two lines, the first beside its sample size {@code tasks} on the right (the
	 * room it leaves), the second the note's full width: {@code Cannon, melee, Smoke  3 tasks} / {@code Dungeon}.
	 * Past two lines the second is cut short with {@code …}. Named {@code name.head}; each name line
	 * {@code name.name}, the sample size {@code name.tasks}.
	 */
	private JPanel optionHead(String name, String optionName, String tasks)
	{
		JPanel head = column(name + ".head");
		JLabel tasksLabel = smallLabel(tasks, LedgerTheme.MUTED_INK);
		tasksLabel.setName(name + ".tasks");
		FontMetrics bold = head.getFontMetrics(LedgerTheme.boldFont());
		int firstWidth = NOTE_WRAP_WIDTH - GAP - tasksLabel.getPreferredSize().width;
		List<String> lines = TaskPlanText.wrap(optionName, firstWidth, NOTE_WRAP_WIDTH, MAX_NAME_LINES,
			bold::stringWidth);
		JPanel first = new JPanel(new BorderLayout(GAP, 0));
		first.setOpaque(false);
		first.setAlignmentX(Component.LEFT_ALIGNMENT);
		first.add(fitLine(name + ".name", lines.isEmpty() ? "" : lines.get(0), LedgerTheme.boldFont(),
			LedgerTheme.INK), BorderLayout.CENTER);
		first.add(tasksLabel, BorderLayout.EAST);
		head.add(first);
		for (String line : lines.subList(Math.min(1, lines.size()), lines.size()))
		{
			head.add(fitLine(name + ".name", line, LedgerTheme.boldFont(), LedgerTheme.INK));
		}
		return head;
	}

	/** One line of a wrapped text, named {@code name}: a {@link FitLabel}, cut short if it ever has less room. */
	private static FitLabel fitLine(String name, String text, Font font, Color color)
	{
		FitLabel label = new FitLabel(text);
		label.setName(name);
		label.setFont(font);
		label.setForeground(color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/** The Bring grid's rows: each item in whole items, at its GE value, named as far as names are known. */
	private List<ItemDetails.Row> bringRows(List<TaskPlan.BringItem> items)
	{
		List<ItemDetails.Row> rows = new ArrayList<>();
		for (TaskPlan.BringItem item : items)
		{
			rows.add(ItemDetails.Row.builder()
				.itemId(item.getItemId())
				.name(ItemDetails.displayName(item.getItemId(), model::itemName, false))
				.quantity(item.getQuantity())
				.unit(ItemDetails.Unit.ITEMS)
				.value(item.getValue())
				.priceName("GE")
				.build());
		}
		return rows;
	}

	/** A Bring icon's tooltip: its full name, the amount and its GE value ({@link TaskPlanText#bringTooltip}). */
	private String bringTooltip(ItemDetails.Row row)
	{
		return html(TaskPlanText.bringTooltip(row.getName(), row.getQuantity(), row.getValue()));
	}

	/**
	 * The {@code +N more} label's tooltip: each of {@code rest}, the items past the grid's, on its own line, worded as
	 * the icons' tooltips ({@link TaskPlanText#bringMoreLine}) and named as the grid names its items.
	 */
	private String bringMoreTooltip(List<TaskPlan.BringItem> rest)
	{
		List<String> lines = new ArrayList<>();
		for (ItemDetails.Row row : bringRows(rest))
		{
			lines.add(TaskPlanText.bringMoreLine(row.getName(), row.getQuantity(), row.getValue()));
		}
		return html(lines);
	}

	/** Asks for the player's names of the unlisted regions the plan's spots are in, so they are named once known. */
	private void requestRegionNames(TaskPlan plan)
	{
		Set<Integer> regions = new HashSet<>();
		for (String spot : spotKeys(plan))
		{
			Integer region = SlayerSpots.keyRegion(spot);
			if (region != null)
			{
				regions.add(region);
			}
		}
		if (!regions.isEmpty())
		{
			model.requestLocationNames(regions);
		}
	}

	/** The names of the plan's spots as shown now, which a region's name may change. */
	private List<String> names(TaskPlan plan)
	{
		List<String> names = new ArrayList<>();
		for (String spot : spotKeys(plan))
		{
			names.add(TaskPlanText.shortSpotName(spot, model.spots(), regionNames()));
		}
		return names;
	}

	/** The spots the card names: the assigned area's and the recommendation's. */
	private static List<String> spotKeys(TaskPlan plan)
	{
		List<String> spots = new ArrayList<>();
		if (plan.getAreaSpot() != null)
		{
			spots.add(plan.getAreaSpot());
		}
		if (plan.getRecommendation() != null)
		{
			spots.add(plan.getRecommendation().getSpot());
		}
		return spots;
	}

	/**
	 * The plan's task name as the sidebar shows it: from the plan, not the tracker, so a rebuild while no task is read
	 * (the card hidden, its plan kept) still names the task.
	 */
	private static String taskName(TaskPlan plan)
	{
		return LedgerRecord.displayName(plan.getTask(), plan.getCreatureId());
	}

	/** The player's names for map regions ({@link LedgerHistoryModel#locationName}). */
	private IntFunction<String> regionNames()
	{
		return model::locationName;
	}

	/** A vertical box named {@code name}, transparent, left-aligned in its parent. */
	private static JPanel column(String name)
	{
		JPanel column = new JPanel();
		column.setName(name);
		column.setLayout(new BoxLayout(column, BoxLayout.Y_AXIS));
		column.setOpaque(false);
		column.setAlignmentX(Component.LEFT_ALIGNMENT);
		return column;
	}

	/**
	 * A line named {@code name}: {@code left} cut short with {@code …} when it doesn't fit ({@link FitLabel}),
	 * {@code right} right-aligned; both in Small.
	 */
	private static JPanel line(String name, String left, String right, Color leftColor, Color rightColor)
	{
		JPanel line = new JPanel(new BorderLayout(GAP, 0));
		line.setName(name);
		line.setOpaque(false);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		FitLabel leftLabel = new FitLabel(left);
		leftLabel.setFont(LedgerTheme.smallFont());
		leftLabel.setForeground(leftColor);
		line.add(leftLabel, BorderLayout.CENTER);
		line.add(smallLabel(right, rightColor), BorderLayout.EAST);
		return line;
	}

	private static JLabel smallLabel(String text, Color color)
	{
		JLabel label = LedgerTheme.label(text, LedgerTheme.smallFont(), color);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/**
	 * A sentence in Small broken into lines that fit {@code width} px ({@link TaskPlanText#wrap}, measured in the
	 * font), one {@link FitLabel} each, named {@code name}: the no-history line and the Konar note. The sidebar's width
	 * is fixed, so the lines are worked out once; each line still asks for no width and is cut short if it ever had
	 * less room.
	 */
	private static JPanel wrapped(String name, String text, Color color, int width)
	{
		JPanel lines = column(name);
		FontMetrics metrics = lines.getFontMetrics(LedgerTheme.smallFont());
		for (String line : TaskPlanText.wrap(text, width, metrics::stringWidth))
		{
			FitLabel label = new FitLabel(line);
			label.setFont(LedgerTheme.smallFont());
			label.setForeground(color);
			label.setAlignmentX(Component.LEFT_ALIGNMENT);
			lines.add(label);
		}
		return lines;
	}

	/** Adds {@code part} to {@code column} with {@code gap} px above it, unless it is the first. */
	private static void addPart(JPanel column, JComponent part, int gap)
	{
		if (column.getComponentCount() > 0 && gap > 0)
		{
			column.add(Box.createVerticalStrut(gap));
		}
		part.setAlignmentX(Component.LEFT_ALIGNMENT);
		column.add(part);
	}

	/** {@code part} in a transparent holder with {@code gap} px of space above it, left-aligned. */
	private static JComponent gapped(JComponent part, int gap)
	{
		JPanel holder = new JPanel(new BorderLayout());
		holder.setOpaque(false);
		holder.setAlignmentX(Component.LEFT_ALIGNMENT);
		holder.setBorder(BorderFactory.createEmptyBorder(gap, 0, 0, 0));
		holder.add(part, BorderLayout.CENTER);
		return holder;
	}


	/** Plain-text lines as an HTML tooltip, each escaped. */
	private static String html(List<String> lines)
	{
		List<String> escaped = new ArrayList<>();
		for (String line : lines)
		{
			escaped.add(LedgerHistory.escapeHtml(line));
		}
		return "<html>" + String.join("<br>", escaped) + "</html>";
	}

	/**
	 * How many times the card's content was built. Performance seam: tests assert this doesn't grow on the refresh
	 * timer.
	 */
	int getBuildCount()
	{
		return builds;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * A Slayer assignment that ended without a saved session: skipped, blocked, reset, completed while no session was
 * tracked, or ended for a reason the plugin couldn't tell ({@link AssignmentOutcome}). Stored in the ledger file's
 * {@code assignments} list ({@link LedgerStore}), next to the records but never among them, and serialized with Gson
 * like {@link LedgerRecord}: {@code null} fields are left out when writing and missing fields read as {@code null}.
 *
 * <p><b>An entry is not a played task.</b> It has no kills, time, loot or supplies, and it never counts anywhere
 * played tasks do: the history list and its totals, the Monster filter, the saved-task count, the time-left estimate
 * ({@link TaskTimeEstimate}) and today's prices only ever see {@link LedgerRecord}s. Phase 3 (per-monster averages
 * and new-task estimates) must also use the records only and ignore these entries (owner decision).</p>
 *
 * <p>Added to schema 2 as an optional list (no schema bump), following the precedent of the optional
 * {@link LedgerRecord} fields: a file without it loads with no entries, and is written back without the field until
 * an entry is added. An older build would read such a file and drop the list on its next write.</p>
 */
@Data
public class AssignmentEntry
{
	/** Random id, so the entry can be deleted from the history. */
	private String id;
	/** Task name, or {@code null} when the lookup failed. */
	private String monster;
	/** Slayer task creature key ({@link SessionTracker#creatureKey}), or {@code null} when unknown. */
	private Integer creatureId;
	/** Assigned task size, or {@code null} when unknown. */
	private Integer originalAmount;
	/** SLAYER_MASTER value, as in {@link LedgerRecord#getSlayerMaster()}; {@code null} when unknown. */
	private Integer slayerMaster;
	/** SLAYER_AREA value (Konar), or {@code null}. */
	private Integer slayerArea;
	/** The area's name, or {@code null}. */
	private String taskLocation;
	/** When the assignment was first seen to have ended (epoch ms). */
	private long endedAt;
	/** How it ended; {@code null} reads as {@link AssignmentOutcome#UNKNOWN} (for example an outcome from a newer build, which this build also writes back as {@code null}, so a downgrade loses it). */
	private AssignmentOutcome outcome;
	/**
	 * Slayer points after the end minus points before it (negative when points were spent), or {@code null} when not
	 * observed (no reading before the end).
	 */
	private Integer pointsChange;

	/** The assignment's master and area as a {@link TaskContext} (no rewards). */
	TaskContext context()
	{
		return TaskContext.of(slayerMaster, slayerArea, taskLocation, null, null);
	}
}

package com.shmayvan.slayerledger;

import java.time.*;
import java.time.format.*;
import java.util.*;

/**
 * Pure rules and formatting for the assignment entries ({@link AssignmentEntry}): the bound on how many are kept, the
 * check against saved records, the order and the "Skipped / blocked" section's text. No Swing, client or file access.
 *
 * <p>Entries are never mixed with {@link LedgerRecord}s: nothing here, or anywhere else, counts them as played tasks
 * (see {@link AssignmentEntry}).</p>
 */
final class AssignmentLog
{
	/** At most this many entries are kept; adding one more drops the oldest (by end time). */
	static final int MAX_ENTRIES = 500;
	/** Separator between the parts of a row's second line, as in {@code 10/26/26 \u00b7 Duradel/Kuradal}. */
	static final String SEPARATOR = " \u00b7 ";

	/** Newest first by end time; ties broken by id, for a stable order. */
	static final Comparator<AssignmentEntry> NEWEST_FIRST = Comparator
		.comparingLong(AssignmentEntry::getEndedAt).reversed()
		.thenComparing(e -> e.getId() == null ? "" : e.getId());

	private AssignmentLog()
	{
	}

	/**
	 * {@code entries} with {@code entry} added (unless one with the same id is already there), keeping only the newest
	 * {@link #MAX_ENTRIES}; the order on disk is oldest first.
	 */
	static List<AssignmentEntry> add(Collection<AssignmentEntry> entries, AssignmentEntry entry)
	{
		final List<AssignmentEntry> result = sortNewestFirst(entries);
		if (entry != null && (entry.getId() == null
			|| result.stream().noneMatch(e -> entry.getId().equals(e.getId()))))
		{
			result.add(entry);
			result.sort(NEWEST_FIRST);
		}
		while (result.size() > MAX_ENTRIES)
		{
			result.remove(result.size() - 1);
		}
		final List<AssignmentEntry> oldestFirst = new ArrayList<>(result.size());
		for (int i = result.size() - 1; i >= 0; i--)
		{
			oldestFirst.add(result.get(i));
		}
		return oldestFirst;
	}

	/** Copy without nulls, newest first. */
	static List<AssignmentEntry> sortNewestFirst(Collection<AssignmentEntry> entries)
	{
		final List<AssignmentEntry> sorted = new ArrayList<>();
		if (entries != null)
		{
			for (AssignmentEntry e : entries)
			{
				if (e != null)
				{
					sorted.add(e);
				}
			}
		}
		sorted.sort(NEWEST_FIRST);
		return sorted;
	}

	/**
	 * Whether the saved records suggest that an assignment the plugin didn't watch from its start
	 * ({@link AssignmentWatch.Ended#isCheckRecords()}) was played in an earlier run: the newest record is a partial
	 * (not completed) session of the same creature key with the same assigned size (when both are known). A partial
	 * session doesn't end its assignment, so the assignment it belonged to can still be the one that just ended. Errs
	 * towards "played": a missing entry is better than one for a task that was played.
	 */
	static boolean playedBefore(Collection<LedgerRecord> records, AssignmentEntry entry)
	{
		if (records == null || entry == null || entry.getCreatureId() == null)
		{
			return false;
		}
		final List<LedgerRecord> sorted = LedgerHistory.sortNewestFirst(records);
		if (sorted.isEmpty())
		{
			return false;
		}
		final LedgerRecord newest = sorted.get(0);
		return !newest.isCompleted() && Objects.equals(newest.getCreatureId(), entry.getCreatureId())
			&& (newest.getOriginalAmount() == null || entry.getOriginalAmount() == null
			|| newest.getOriginalAmount().equals(entry.getOriginalAmount()));
	}

	// ---- Display ----

	/** Date of a row, in the locale's short style. */
	static DateTimeFormatter shortDate(ZoneId zone)
	{
		return DateTimeFormatter.ofLocalizedDate(FormatStyle.SHORT).withZone(zone);
	}

	/** Task name, or {@link LedgerHistory#UNKNOWN_MONSTER}. */
	static String monster(AssignmentEntry entry)
	{
		final String monster = entry.getMonster();
		return monster == null || monster.isEmpty() ? LedgerHistory.UNKNOWN_MONSTER : monster;
	}

	/**
	 * The row's HTML tooltip: the task, the outcome, the end time, then the master, type, assigned amount and point
	 * change, each only when known.
	 */
	static String tooltip(AssignmentEntry entry, DateTimeFormatter dateTime)
	{
		final StringBuilder sb = new StringBuilder("<html>");
		sb.append(LedgerHistory.escapeHtml(monster(entry)));
		sb.append("<br>").append(AssignmentOutcome.orUnknown(entry.getOutcome()).getDescription());
		if (entry.getEndedAt() > 0)
		{
			sb.append("<br>Ended: ").append(dateTime.format(Instant.ofEpochMilli(entry.getEndedAt())));
		}
		if (SlayerMaster.isKnown(entry.getSlayerMaster()))
		{
			sb.append("<br>").append(LedgerHistory.escapeHtml(LedgerHistory.formatMaster(entry.getSlayerMaster())));
		}
		final TaskType type = TaskType.of(entry.getSlayerMaster(), entry.getCreatureId());
		if (type != null)
		{
			sb.append("<br>").append(LedgerHistory.escapeHtml(LedgerHistory.formatTaskType(type,
				entry.getTaskLocation())));
		}
		if (entry.getOriginalAmount() != null && entry.getOriginalAmount() > 0)
		{
			sb.append("<br>Assigned: ").append(entry.getOriginalAmount());
		}
		if (entry.getPointsChange() != null)
		{
			sb.append("<br>Points: ").append(formatPointsChange(entry.getPointsChange()));
		}
		return sb.append("</html>").toString();
	}

	/** A signed point change: {@code -30}, {@code +18}, {@code 0}. */
	static String formatPointsChange(int change)
	{
		return change > 0 ? "+" + change : Integer.toString(change);
	}

	/** Text of the delete confirmation dialog. */
	static String deleteConfirmation(AssignmentEntry entry)
	{
		return String.format("Delete this %s entry (%s)? This can't be undone.", monster(entry),
			AssignmentOutcome.orUnknown(entry.getOutcome()).getLabel().toLowerCase(Locale.ROOT));
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * How a Slayer assignment ended without a saved session (see {@link AssignmentEntry}), worked out from what changed
 * around its end. Pure; no RuneLite types.
 *
 * <p>The signals, compared between the last settled tick the assignment was active and the end of the decision
 * window ({@link AssignmentWatch}):</p>
 * <ul>
 *     <li>a task completion ({@link CompletionSignal}: one completion counter went up by exactly one);</li>
 *     <li>the change in Slayer points (the SLAYER_POINTS varbit);</li>
 *     <li>whether any of the blocked-task values changed (the SLAYER_REWARDS_BLOCKED* varps and the per-master
 *     SLAYER_BLOCKED_* varbits the plugin reads);</li>
 *     <li>whether a completion counter (task streak) went down.</li>
 * </ul>
 *
 * <p>Cancel and block costs vary by master (OSRS wiki "Slayer Rewards", read 2026-10-26: cancel 30-100, block
 * 40-120), so no amount is assumed: any drop in points counts as points spent, and the observed change is stored.
 * The blocked-task values are not decoded (which slot holds which task is not documented in the API); only "one of
 * them changed at the same moment" is used. When the signals don't fit one outcome cleanly, the outcome is
 * {@link #UNKNOWN}: never a guess.</p>
 */
@Getter
@AllArgsConstructor
enum AssignmentOutcome
{
	/** Cancelled for points: points went down, no block changed, no completion, no streak drop. */
	SKIPPED("Skipped", "Skipped (cancelled for points)"),
	/** Blocked: points went down and a blocked-task value changed, no completion, no streak drop. */
	BLOCKED("Blocked", "Blocked"),
	/** Replaced with the streak reset (a Turael or Spria reset): a streak went down and no points were spent. */
	RESET("Reset", "Reset (streak reset, no points spent)"),
	/** Completed without a session: a completion was signalled, and no streak went down. */
	COMPLETED("Completed (untracked)", "Completed without a tracked session"),
	/** The signals fit none of the above (or are missing). */
	UNKNOWN("Ended", "Ended (reason unknown)");

	/** Short label for the history row, e.g. "Skipped". */
	private final String label;
	/** Longer text for the row's tooltip, e.g. "Ended (reason unknown)". */
	private final String description;

	/** A saved outcome, or {@link #UNKNOWN} for {@code null} (for example a value written by a newer build). */
	static AssignmentOutcome orUnknown(AssignmentOutcome outcome)
	{
		return outcome == null ? UNKNOWN : outcome;
	}

	/**
	 * @param completed           whether a task completion was signalled around the end
	 * @param pointsChange        points after minus points before, or {@code null} when either reading is missing
	 * @param blockedValuesChanged whether any blocked-task value changed
	 * @param streakDropped       whether any completion counter went down
	 * @return the outcome; {@link #UNKNOWN} whenever the signals are ambiguous
	 */
	static AssignmentOutcome classify(boolean completed, Integer pointsChange, boolean blockedValuesChanged,
		boolean streakDropped)
	{
		if (completed)
		{
			// A completion with a streak reset (or a block) at the same moment doesn't fit one story.
			return streakDropped || blockedValuesChanged ? UNKNOWN : COMPLETED;
		}
		if (pointsChange == null || streakDropped && pointsChange != 0)
		{
			return UNKNOWN;
		}
		if (pointsChange < 0)
		{
			return blockedValuesChanged ? BLOCKED : SKIPPED;
		}
		if (pointsChange == 0 && streakDropped && !blockedValuesChanged)
		{
			return RESET;
		}
		// Points went up without a completion, a block with no points spent, or nothing changed at all.
		return UNKNOWN;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * One "Skipped / blocked" row: its entry, the monster's name and the HTML tooltip. The outcome word, date and master
 * shown on the row come from the entry ({@link AssignmentsSection}).
 */
@Getter
@AllArgsConstructor(access = AccessLevel.PACKAGE)
final class AssignmentRow
{
	private final AssignmentEntry entry;
	private final String monster;
	private final String tooltip;
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Watches Slayer assignments on the plugin's settled ticks and reports each one that ended without a session as an
 * {@link AssignmentEntry} (skipped, blocked, reset, completed while untracked, or ended for an unknown reason; see
 * {@link AssignmentOutcome}). Pure (no RuneLite types) and not thread-safe; the plugin uses it on the client thread
 * only, every settled tick, whether or not a session is running. It only reads; it never acts.
 *
 * <p><b>Played assignments.</b> An assignment that any session held (the creature keys from
 * {@link SessionTracker#takeSessionTaskKeys()}: started, adopted, restored, paused, or held for late loot) is played,
 * and never reported, whether that session was saved as completed, as partial, or discarded. Played-ness is only
 * known for what this plugin run saw: an assignment first seen at a login or plugin start ("not witnessed from its
 * start") may have had a session in an earlier run, so its entry is marked {@link Ended#isCheckRecords()} and the
 * plugin skips it when the newest saved record looks like the same assignment ({@link AssignmentLog#playedBefore}).</p>
 *
 * <p><b>Ending.</b> The assignment ends on the first settled tick it is no longer current: the task count reads 0, or
 * another task (another creature key, name or assigned size) is current. The outcome is decided
 * {@link #END_WINDOW_TICKS} ticks later, comparing the readings on the last tick it was active with the readings then,
 * so points or a streak that arrive a tick late still count. If the count reads 0 and the same task comes back first
 * (a transient zero, as {@link SessionTracker} also allows), nothing ended. An end by a 0 count whose outcome is
 * {@link AssignmentOutcome#UNKNOWN} waits until another task appears (and is dropped if the same task comes back with
 * no more kills left than before), as the tracker treats a long zero gap.</p>
 *
 * <p><b>Logins, hops and lost connections</b> ({@link #reset()}): any undecided end is dropped, and the first reading
 * afterwards only re-reads the baseline, as for {@link CompletionSignal} and {@link TaskRewards}, so a login resync
 * never produces an entry. The current assignment is remembered across it (an assignment still active at logout has
 * not ended): if the task after the login is the same one, it keeps its played flag; otherwise the old one ended while
 * the plugin wasn't watching and is forgotten without an entry. While the count still reads 0 after a login, the
 * baseline waits up to {@link #SYNC_MAX_TICKS} ticks for the task, like the restore check.</p>
 */
final class AssignmentWatch
{
	/** Ticks after the end at which the outcome is decided. One more than the tracker's transient-zero allowance. */
	static final int END_WINDOW_TICKS = SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS + 1;
	/** Ticks a post-login baseline waits for a non-zero task count before deciding there is no task. */
	static final int SYNC_MAX_TICKS = SessionTracker.RESTORE_SYNC_MAX_TICKS;

	/** One settled tick's reading of the task and the values the outcome is decided from; see {@link #builder()}. */
	static final class Reading
	{
		private final String monster;
		private final int creatureId;
		private final int remaining;
		private final int originalAmount;
		private final TaskContext context;
		private final Values values;
		private final boolean completionSignaled;

		private Reading(Builder b)
		{
			this.monster = b.monster;
			this.creatureId = b.creatureId;
			this.remaining = Math.max(0, b.remaining);
			this.originalAmount = b.originalAmount > 0 ? b.originalAmount : SessionTracker.UNKNOWN_AMOUNT;
			this.context = b.context == null ? TaskContext.NONE : b.context;
			this.values = new Values(b.points, b.counters, b.blockedValues);
			this.completionSignaled = b.completionSignaled;
		}

		/** A builder starting from no task: no creature, unknown size, no counters or blocked values. */
		static Builder builder()
		{
			return new Builder();
		}

		/** Builds a {@link Reading}. */
		static final class Builder
		{
			private String monster;
			private int creatureId = SessionTracker.NO_CREATURE;
			private int remaining;
			private int originalAmount = SessionTracker.UNKNOWN_AMOUNT;
			private TaskContext context;
			private int points;
			private int[] counters;
			private int[] blockedValues;
			private boolean completionSignaled;

			private Builder()
			{
			}

			/** Task name, or {@code null} when there is no task or the lookup failed. */
			Builder monster(String monster)
			{
				this.monster = monster;
				return this;
			}

			/** Creature key, or {@link SessionTracker#NO_CREATURE}. */
			Builder creatureId(int creatureId)
			{
				this.creatureId = creatureId;
				return this;
			}

			/** SLAYER_COUNT (0 when there is no task). */
			Builder remaining(int remaining)
			{
				this.remaining = remaining;
				return this;
			}

			/** Assigned size, or {@link SessionTracker#UNKNOWN_AMOUNT}. */
			Builder originalAmount(int originalAmount)
			{
				this.originalAmount = originalAmount;
				return this;
			}

			/** Master and area ({@link TaskContext#assignment}), or {@code null}. */
			Builder context(TaskContext context)
			{
				this.context = context;
				return this;
			}

			/** SLAYER_POINTS. */
			Builder points(int points)
			{
				this.points = points;
				return this;
			}

			/** The completion counters, as passed to {@link CompletionSignal#update}. */
			Builder counters(int[] counters)
			{
				this.counters = counters;
				return this;
			}

			/** Every blocked-task varp and varbit, in the same order every tick. */
			Builder blockedValues(int[] blockedValues)
			{
				this.blockedValues = blockedValues;
				return this;
			}

			/** {@link CompletionSignal#update}'s result for this tick. */
			Builder completionSignaled(boolean completionSignaled)
			{
				this.completionSignaled = completionSignaled;
				return this;
			}

			Reading build()
			{
				return new Reading(this);
			}
		}

		private boolean hasTask()
		{
			return remaining > 0;
		}
	}

	/** An ended assignment to store. */
	@Getter
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Ended
	{
		private final AssignmentEntry entry;
		/**
		 * Whether the assignment wasn't watched from its start, so a session in an earlier plugin run can't be ruled
		 * out: store it only if {@link AssignmentLog#playedBefore} says the saved records don't show one.
		 */
		private final boolean checkRecords;
	}

	/** Points, completion counters and blocked-task values at one reading. */
	private static final class Values
	{
		private final int points;
		private final int[] counters;
		private final int[] blocked;

		private Values(int points, int[] counters, int[] blocked)
		{
			this.points = points;
			this.counters = counters == null ? new int[0] : counters.clone();
			this.blocked = blocked == null ? new int[0] : blocked.clone();
		}
	}

	/** An assignment as watched. */
	private static final class Assignment
	{
		private String monster;
		private final int creatureId;
		private int originalAmount;
		private TaskContext context;
		private int remaining;
		private final boolean witnessedStart;
		private boolean played;
		/** Readings on the last tick the assignment was current. */
		private Values lastActive;
		/** Whether a completion was signalled on that tick. */
		private boolean completionOnLastActive;

		private Assignment(Reading r, boolean witnessedStart)
		{
			this.monster = r.monster;
			this.creatureId = r.creatureId;
			this.originalAmount = r.originalAmount;
			this.context = r.context;
			this.remaining = r.remaining;
			this.witnessedStart = witnessedStart;
			this.lastActive = r.values;
			this.completionOnLastActive = r.completionSignaled;
		}

		/** Same task: creature key, name (when both known) and assigned size (when both known). */
		private boolean sameTask(Reading r)
		{
			return r.hasTask() && r.creatureId == creatureId
				&& (r.monster == null || monster == null || r.monster.equals(monster))
				&& (r.originalAmount == SessionTracker.UNKNOWN_AMOUNT || originalAmount == SessionTracker.UNKNOWN_AMOUNT
				|| r.originalAmount == originalAmount);
		}

		/** The same task after a gap (a login, or a long zero): also no more kills left than before. */
		private boolean sameTaskAfterGap(Reading r)
		{
			return sameTask(r) && r.remaining <= remaining;
		}

		/** Takes this tick's reading of the same task. */
		private void refresh(Reading r)
		{
			if (monster == null)
			{
				monster = r.monster;
			}
			if (originalAmount == SessionTracker.UNKNOWN_AMOUNT)
			{
				originalAmount = r.originalAmount;
			}
			context = context.fillAssignment(r.context);
			remaining = r.remaining;
			lastActive = r.values;
			completionOnLastActive = r.completionSignaled;
		}
	}

	/** An assignment that has ended, waiting for its outcome. */
	private static final class Pending
	{
		private final Assignment assignment;
		private final long endedAt;
		private final boolean endedByZero;
		private boolean completion;
		private int ticks;
		/** Readings at the end of the window, once an unknown outcome waits for the next task; else {@code null}. */
		private Values frozen;

		private Pending(Assignment assignment, long endedAt, boolean endedByZero, boolean completion)
		{
			this.assignment = assignment;
			this.endedAt = endedAt;
			this.endedByZero = endedByZero;
			this.completion = completion;
		}
	}

	/** The current assignment, or {@code null}; kept across {@link #reset()}. */
	private Assignment current;
	/** The ended assignment waiting for its outcome, or {@code null}. */
	private Pending pending;
	/** Whether the next readings only set the baseline (after construction, {@link #reset()} or {@link #forget()}). */
	private boolean syncing = true;
	/** Zero-count readings while syncing. */
	private int syncTicks;

	/** After a login, hop or lost connection: drops an undecided end, keeps the current assignment; see the class. */
	void reset()
	{
		pending = null;
		syncing = true;
		syncTicks = 0;
	}

	/** After an account change: forgets everything, including the current assignment. */
	void forget()
	{
		reset();
		current = null;
	}

	/**
	 * Takes one settled tick's reading.
	 *
	 * @param r               this tick's reading
	 * @param sessionTaskKeys {@link SessionTracker#takeSessionTaskKeys()} for this tick: creature keys of tasks a
	 *                        session held since the last tick
	 * @param now             the time (epoch ms), used as the end time of an assignment that ends on this tick
	 * @return the assignments to store (usually none)
	 */
	List<Ended> update(Reading r, Set<Integer> sessionTaskKeys, long now)
	{
		markPlayed(sessionTaskKeys);
		if (syncing)
		{
			sync(r);
			markPlayed(sessionTaskKeys);
			return Collections.emptyList();
		}

		final List<Ended> ended = new ArrayList<>(1);
		if (pending != null && current == null && pending.endedByZero && !pending.completion
			&& (pending.frozen == null ? pending.assignment.sameTask(r) : pending.assignment.sameTaskAfterGap(r)))
		{
			// A transient zero: the same task is back, so it never ended.
			current = pending.assignment;
			current.refresh(r);
			pending = null;
		}
		else if (current != null && current.sameTask(r))
		{
			current.refresh(r);
		}
		else if (current != null)
		{
			if (pending != null)
			{
				// Another end before the last one was decided: decide that one now, by the readings just before this
				// second change, so the second assignment's points or streak don't count for the first.
				add(ended, pending, current.lastActive);
			}
			pending = new Pending(current, now, !r.hasTask(), current.completionOnLastActive || r.completionSignaled);
			current = r.hasTask() ? new Assignment(r, true) : null;
			markPlayed(sessionTaskKeys);
			return ended;
		}
		else if (r.hasTask())
		{
			current = new Assignment(r, true);
			if (pending != null && pending.frozen != null)
			{
				// Another task after a long zero: the old one ended, reason unknown.
				add(ended, pending, pending.frozen);
				pending = null;
			}
		}

		if (pending != null && pending.frozen == null)
		{
			pending.ticks++;
			pending.completion |= r.completionSignaled;
			if (pending.ticks >= END_WINDOW_TICKS)
			{
				if (pending.endedByZero && current == null && outcome(pending, r.values) == AssignmentOutcome.UNKNOWN)
				{
					pending.frozen = r.values;
				}
				else
				{
					add(ended, pending, r.values);
					pending = null;
				}
			}
		}
		markPlayed(sessionTaskKeys);
		return ended;
	}

	private void sync(Reading r)
	{
		if (r.hasTask())
		{
			if (current != null && current.sameTaskAfterGap(r))
			{
				current.refresh(r);
			}
			else
			{
				// A new assignment, or the old one ended while the plugin wasn't watching: no entry either way.
				current = new Assignment(r, false);
			}
			syncing = false;
		}
		else if (++syncTicks >= SYNC_MAX_TICKS)
		{
			current = null;
			syncing = false;
		}
	}

	private void markPlayed(Set<Integer> keys)
	{
		if (keys == null || keys.isEmpty())
		{
			return;
		}
		if (current != null && keys.contains(current.creatureId))
		{
			current.played = true;
		}
		if (pending != null && keys.contains(pending.assignment.creatureId))
		{
			pending.assignment.played = true;
		}
	}

	private static AssignmentOutcome outcome(Pending p, Values now)
	{
		final Values before = p.assignment.lastActive;
		boolean streakDropped = false;
		final int n = Math.min(before.counters.length, now.counters.length);
		for (int i = 0; i < n; i++)
		{
			if (now.counters[i] < before.counters[i])
			{
				streakDropped = true;
				break;
			}
		}
		return AssignmentOutcome.classify(p.completion, now.points - before.points,
			!Arrays.equals(before.blocked, now.blocked), streakDropped);
	}

	/** Adds the pending assignment's entry, unless a session held it. */
	private static void add(List<Ended> ended, Pending p, Values now)
	{
		final Assignment a = p.assignment;
		if (a.played)
		{
			return;
		}
		final AssignmentEntry entry = new AssignmentEntry();
		entry.setId(UUID.randomUUID().toString());
		entry.setMonster(a.monster);
		entry.setCreatureId(a.creatureId == SessionTracker.NO_CREATURE ? null : a.creatureId);
		entry.setOriginalAmount(a.originalAmount == SessionTracker.UNKNOWN_AMOUNT ? null : a.originalAmount);
		entry.setSlayerMaster(a.context.getMaster());
		entry.setSlayerArea(a.context.getArea());
		entry.setTaskLocation(a.context.getLocation());
		entry.setEndedAt(p.endedAt);
		entry.setOutcome(outcome(p, now));
		entry.setPointsChange(now.points - a.lastActive.points);
		ended.add(new Ended(entry, !a.witnessedStart));
	}


	/** Test seam: whether an assignment is being watched now. */
	boolean hasCurrent()
	{
		return current != null;
	}

	/** Test seam: whether an ended assignment waits for its outcome. */
	boolean hasPending()
	{
		return pending != null;
	}

	@Override
	public String toString()
	{
		return "AssignmentWatch(current=" + (current == null ? null : current.creatureId) + ", pending="
			+ (pending == null ? null : pending.assignment.creatureId) + ", syncing=" + syncing + ")";
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.awt.event.*;
import java.time.*;
import java.time.format.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import javax.swing.border.*;
import lombok.*;

/**
 * The collapsed "Skipped / blocked" section of {@link SlayerLedgerPanel}: assignments that ended without a saved
 * session, which never count as played tasks. Rows ({@link LedgerHistoryModel#assignmentRows}) are built only while the
 * section is open and its "Skipped / blocked" setting shows it. EDT only.
 *
 * <p>Look A (DESIGN_PRINCIPLES.md 3.3, 3.8): a quiet log, flat on the page. Each entry is two lines in
 * Small: the task's icon ({@link TaskIcons}, or an empty slot of the same size for a name that is no known task;
 * asked for only as the rows are built) and the monster, with the outcome word on the right, both in
 * {@link LedgerTheme#LABEL}; then the date and the master in {@link LedgerTheme#HINT}, each only when known. The row
 * takes {@link LedgerTheme#HOVER} under the mouse, since it has a right-click menu; every text colour keeps 4.5:1 on
 * both backgrounds.</p>
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class AssignmentsSection
{
	/** Shown instead of the rows while there are none (DESIGN_PRINCIPLES.md 3.9: plain, one line). */
	static final String EMPTY_TEXT = "No skipped or blocked tasks yet.";

	private final LedgerHistoryModel model;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Parent of the delete confirmation. */
	private final Component dialogParent;
	/** Deletes the entry with the given id from the account's log, after the player confirmed it. */
	private final BiConsumer<Long, String> delete;
	/** Draws the rows' task icons. */
	private final ItemIcons icons;

	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	private final JLabel title = new JLabel();
	private final JLabel toggle = new JLabel();
	private final JPanel body = new JPanel();
	/**
	 * What the rows are and how to delete one, on two lines that each fit the sidebar (as one line it needs 248 px of
	 * the 213); shown only above rows.
	 */
	private final JPanel hint = new JPanel(new GridLayout(2, 1, 0, 0));
	private final JPanel list = new JPanel();
	/** Whether the section is open; collapsed whenever the panel is created (owner decision). */
	private boolean expanded;
	/** How many times the rows were built. */
	private int builds;
	/** The "Skipped / blocked" setting; while off, no rows are built. The panel hides the components. */
	private boolean shown = true;

	/** Adds the header and the body to {@code content}, collapsed. */
	void addTo(JPanel content)
	{
		// Names for tests, which find the parts by them; no visible effect.
		header.setName("assignments.header");
		title.setName("assignments.title");
		toggle.setName("assignments.toggle");
		body.setName("assignments.body");
		hint.setName("assignments.hint");
		list.setName("assignments.list");
		// A section header (DESIGN_PRINCIPLES.md 3.3).
		LedgerTheme.styleSectionHeader(header, title, toggle);
		header.add(title, BorderLayout.WEST);
		header.add(toggle, BorderLayout.EAST);
		header.setToolTipText("<html>Assignments that ended without a saved session: skipped, blocked,"
			+ " reset,<br>or completed while no session was tracked. They don't count as played tasks.</html>");
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggle();
			}
		});
		SlayerLedgerPanel.addRow(content, header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(LedgerTheme.PAGE);
		hint.setOpaque(false);
		hint.add(LedgerTheme.label("Not counted as played tasks.", LedgerTheme.smallFont(), LedgerTheme.HINT));
		hint.add(LedgerTheme.label("Right-click an entry to delete it.", LedgerTheme.smallFont(), LedgerTheme.HINT));
		hint.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		hint.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(hint);
		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(LedgerTheme.PAGE);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);
		body.add(list);
		SlayerLedgerPanel.addRow(content, body);
		rebuild();
	}

	/** Opens or closes the section, as a click on its header does. */
	void toggle()
	{
		expanded = !expanded;
		rebuild();
	}

	/**
	 * Applies the "Skipped / blocked" setting: hidden, the section drops its rows and builds none; shown again, it
	 * is rebuilt at once if it was open.
	 */
	void setShown(boolean value)
	{
		if (shown != value)
		{
			shown = value;
			rebuild();
		}
	}

	/**
	 * Shows the section as it now is: the title with the count, and while open and shown, the rows, or one plain line
	 * without any.
	 */
	void rebuild()
	{
		title.setText("Skipped / blocked (" + model.assignments().size() + ")");
		toggle.setText(expanded ? "Hide" : "Show");
		body.setVisible(expanded);
		list.removeAll();
		// No rows while collapsed or hidden.
		if (expanded && shown)
		{
			builds++;
			boolean empty = model.assignments().isEmpty();
			hint.setVisible(!empty);
			if (empty)
			{
				JLabel none = LedgerTheme.label(EMPTY_TEXT, LedgerTheme.smallFont(), LedgerTheme.LABEL);
				// A name for tests; no visible effect.
				none.setName("assignments.empty");
				none.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
				none.setAlignmentX(Component.LEFT_ALIGNMENT);
				list.add(none);
			}
			DateTimeFormatter date = AssignmentLog.shortDate(ZoneId.systemDefault());
			for (AssignmentRow entry : model.assignmentRows())
			{
				JPanel row = row(model.account(), entry, date);
				row.setAlignmentX(Component.LEFT_ALIGNMENT);
				list.add(row);
			}
		}
		relayout.run();
	}

	/**
	 * One entry: the task's icon and the monster, cut short with {@code …} when it doesn't fit (the tooltip has it
	 * whole), with the outcome word on the right; under the name, the date and the master
	 * ({@link #details}). Hover shows the row can be right-clicked.
	 */
	private JPanel row(long account, AssignmentRow shownRow, DateTimeFormatter date)
	{
		AssignmentEntry entry = shownRow.getEntry();
		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
		row.setOpaque(true);
		row.setBackground(LedgerTheme.PAGE);
		row.setBorder(BorderFactory.createEmptyBorder(3, 0, 3, 0));
		row.setToolTipText(shownRow.getTooltip());

		FitLabel name = new FitLabel(shownRow.getMonster());
		// A name for tests, which read the icon and the text as shown from it; no visible effect.
		name.setName("assignments.name");
		name.setFont(LedgerTheme.smallFont());
		name.setForeground(LedgerTheme.LABEL);
		SmallItemIcon.applyTask(icons, name, entry.getMonster());
		JLabel outcome = LedgerTheme.label(AssignmentOutcome.orUnknown(entry.getOutcome()).getLabel(),
			LedgerTheme.smallFont(), LedgerTheme.LABEL);
		row.add(line(name, outcome));

		String details = details(entry, date);
		if (!details.isEmpty())
		{
			FitLabel second = new FitLabel(details);
			second.setFont(LedgerTheme.smallFont());
			second.setForeground(LedgerTheme.HINT);
			// Under the name, past the icon's slot.
			second.setBorder(BorderFactory.createEmptyBorder(0, ItemListView.ICON_WIDTH + name.getIconTextGap(), 0, 0));
			row.add(line(second, null));
		}

		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		JMenuItem deleteItem = new JMenuItem("Delete entry");
		// LedgerStore.deleteAssignment matches by id; an entry without one cannot be targeted safely.
		deleteItem.setEnabled(entry.getId() != null);
		deleteItem.addActionListener(e -> confirmDelete(account, entry));
		menu.add(deleteItem);
		row.setComponentPopupMenu(menu);

		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(LedgerTheme.HOVER);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(LedgerTheme.PAGE);
			}
		});
		return row;
	}

	/**
	 * One line of a row: {@code left} fills it (cut short if too long), {@code right}, if any, is right-aligned. Both
	 * use the row's right-click menu.
	 */
	private static JPanel line(JComponent left, JComponent right)
	{
		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setOpaque(false);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		line.setInheritsPopupMenu(true);
		left.setInheritsPopupMenu(true);
		line.add(left, BorderLayout.CENTER);
		if (right != null)
		{
			right.setInheritsPopupMenu(true);
			line.add(right, BorderLayout.EAST);
		}
		return line;
	}

	/**
	 * A row's second line, the date the assignment ended and its master, each only when known:
	 * {@code 10/26/26 · Duradel/Kuradal}; empty when neither is.
	 */
	private static String details(AssignmentEntry entry, DateTimeFormatter date)
	{
		List<String> parts = new ArrayList<>();
		if (entry.getEndedAt() > 0)
		{
			parts.add(date.format(Instant.ofEpochMilli(entry.getEndedAt())));
		}
		String master = SlayerMaster.displayName(entry.getSlayerMaster());
		if (master != null)
		{
			parts.add(master);
		}
		return String.join(AssignmentLog.SEPARATOR, parts);
	}

	/** Asks before deleting an assignment entry; Cancel or closing the dialog does nothing. */
	private void confirmDelete(long account, AssignmentEntry entry)
	{
		String[] options = {"Delete", "Cancel"};
		int choice = JOptionPane.showOptionDialog(dialogParent, AssignmentLog.deleteConfirmation(entry),
			"Slayer Ledger", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]);
		if (choice != 0 || entry.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		delete.accept(account, entry.getId());
	}

	/** How many times the rows were built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBuildCount()
	{
		return builds;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;

/**
 * The style of one of the player's attacks (V2 plan 4.3), decided when its animation starts, from the animation
 * and the worn weapon. Pure: the plugin reads the animation, the worn weapon's equipment stats and the player's target
 * once per game tick and passes the numbers; ids are the RuneLite 1.13.4 gameval constants.
 *
 * <ul>
 * <li><b>Barrage</b>: the multi-target Ancient Magicks cast, {@link #BARRAGE_ANIMATIONS}: {@code ZAROS_VERTICAL_CASTING}
 * (1979) with its walking ({@code _WALKMERGE}, 10092) and priority ({@code _PRIORITY}, 7753) variants. Burst and Barrage
 * share these animations, so both count as Barrage.</li>
 * <li><b>Magic</b>: any other spell's cast, {@link #SPELL_ANIMATIONS}: Rush and Blitz ({@code ZAROS_CASTING}, 1978, and
 * {@code ZAROS_CASTING_WALKMERGE}, 10091), the standard spellbook's strike, bolt and blast, wave and surge casts (with and
 * without a staff, standing and walking), Crumble Undead, Iban Blast, Magic Dart, the god spells and the Arceuus
 * offensive spells (grasp and demonbane). A spell cast is Magic whatever weapon is worn, so a spell autocast from a
 * staff that also has melee bonuses (a staff of the dead, Ahrim's staff) is still Magic.</li>
 * <li>Any other animation: the worn weapon's style ({@link #weaponStyle}): Melee, Ranged or Magic.</li>
 * </ul>
 *
 * <p>Eating and drinking ({@code HUMAN_EAT}, 829, {@link #NOT_ATTACKS}) is never an attack. The plugin counts an
 * animation as an attack only when it starts (frame 0, as {@link ChargedWeaponUsage} counts attacks) while the player is
 * interacting with an NPC, so loading a cannon or picking an item up is not one, and only when the player gained XP in
 * one of {@link #ATTACK_XP_SKILLS} on that tick, so a block (the player's defend animation when an NPC hits them) is
 * not one either. A Burst or Barrage and a chinchompa also hit the NPCs around their target ({@link #splashes}).</p>
 */
final class AttackStyles
{
	/** The multi-target Ancient Magicks (Burst and Barrage) cast animations. */
	static final Set<Integer> BARRAGE_ANIMATIONS = ids(AnimationID.ZAROS_VERTICAL_CASTING,
		AnimationID.ZAROS_VERTICAL_CASTING_WALKMERGE, AnimationID.ZAROS_VERTICAL_CASTING_PRIORITY);

	/** Other spells' cast animations: Rush and Blitz, and the standard and Arceuus combat spells. */
	static final Set<Integer> SPELL_ANIMATIONS = ids(
		// Ancient Magicks' single-target spells (Rush and Blitz).
		AnimationID.ZAROS_CASTING, AnimationID.ZAROS_CASTING_WALKMERGE,
		// Strike, bolt and blast.
		AnimationID.HUMAN_CASTSTRIKE, AnimationID.HUMAN_CASTSTRIKE_STAFF, AnimationID.HUMAN_CASTSTRIKE_WALKMERGE,
		AnimationID.HUMAN_CASTSTRIKE_STAFF_WALKMERGE,
		// Wave (also a trident's and a Sanguinesti staff's cast) and surge.
		AnimationID.HUMAN_CASTWAVE, AnimationID.HUMAN_CASTWAVE_STAFF, AnimationID.HUMAN_CASTWAVE_WALKMERGE,
		AnimationID.HUMAN_CASTWAVE_STAFF_WALKMERGE, AnimationID.HUMAN_CAST_SURGE, AnimationID.HUMAN_CAST_SURGE_WALKMERGE,
		// Crumble Undead, Iban Blast, Magic Dart and the god spells.
		AnimationID.HUMAN_CASTCRUMBLEUNDEAD, AnimationID.HUMAN_CASTCRUMBLEUNDEAD_STAFF, AnimationID.HUMAN_CASTIBANBLAST,
		AnimationID.SLAYER_MAGICDART_CAST, AnimationID.HUMAN_CASTING,
		// Arceuus grasp and demonbane spells.
		AnimationID.HUMAN_SPELLCAST_GRASP, AnimationID.HUMAN_SPELLCAST_DEMONBANE);

	/** Animations that are never an attack: eating and drinking. */
	static final Set<Integer> NOT_ATTACKS = ids(AnimationID.HUMAN_EAT);

	/**
	 * The chinchompas (grey, red and black; RuneLite 1.13.4's gameval {@code ItemID}), whose attacks also hit up to 11
	 * or 12 NPCs in a 3x3 area around their target in multicombat (OSRS Wiki, "Black chinchompa").
	 */
	static final Set<Integer> CHINCHOMPAS = ids(ItemID.CHINCHOMPA_CAPTURED, ItemID.CHINCHOMPA_BIG_CAPTURED,
		ItemID.CHINCHOMPA_BLACK);

	/**
	 * The skills whose XP gained on an animation's first tick confirms it is an attack. Every attack of the
	 * player's that hits gains some on its own tick, before its hitsplat: Hitpoints XP for any damage dealt, with the
	 * Attack, Strength or Defence XP of melee, and a spell's base Magic XP even when it splashes. Ranged XP alone is
	 * left out: the cannon gains it on its own, with no Hitpoints XP (OSRS Wiki, "Dwarf multicannon"), while the
	 * player's own ranged attack that hits gains Hitpoints XP with it. An attack that misses gains nothing, and its 0
	 * hitsplat then gets no style. A block gains nothing either.
	 */
	static final Skill[] ATTACK_XP_SKILLS = {Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.MAGIC, Skill.HITPOINTS};

	/** No animation. */
	static final int NO_ANIMATION = -1;

	private AttackStyles()
	{
	}

	private static Set<Integer> ids(int... ids)
	{
		final Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return Collections.unmodifiableSet(set);
	}

	/** Whether {@code animationId} may start an attack: an animation, and not eating or drinking. */
	static boolean mayBeAttack(int animationId)
	{
		return animationId != NO_ANIMATION && !NOT_ATTACKS.contains(animationId);
	}

	/** Whether {@code animationId} is a spell's cast ({@link #BARRAGE_ANIMATIONS} or {@link #SPELL_ANIMATIONS}). */
	static boolean isSpell(int animationId)
	{
		return BARRAGE_ANIMATIONS.contains(animationId) || SPELL_ANIMATIONS.contains(animationId);
	}

	/**
	 * Whether an attack starting with {@code animationId} while {@code weaponId} is wielded also hits the NPCs around its
	 * target: a Burst or Barrage cast ({@link #BARRAGE_ANIMATIONS}), or a throw of {@link #CHINCHOMPAS} (any other spell
	 * cast while holding them hits its target alone).
	 */
	static boolean splashes(int animationId, int weaponId)
	{
		return BARRAGE_ANIMATIONS.contains(animationId)
			|| (!SPELL_ANIMATIONS.contains(animationId) && CHINCHOMPAS.contains(weaponId));
	}

	/**
	 * The style of an attack starting with {@code animationId}: Barrage or Magic for a spell's cast, otherwise
	 * {@code weaponStyle}.
	 *
	 * @param weaponStyle the worn weapon's style ({@link #weaponStyle}), or {@code null} when not known
	 * @return the style, or {@code null} when neither the animation nor the weapon tells it
	 */
	static SetupStyle attackStyle(int animationId, SetupStyle weaponStyle)
	{
		if (BARRAGE_ANIMATIONS.contains(animationId))
		{
			return SetupStyle.BARRAGE;
		}
		if (SPELL_ANIMATIONS.contains(animationId))
		{
			return SetupStyle.MAGIC;
		}
		return weaponStyle;
	}

	/**
	 * A weapon's style from its equipment stats (RuneLite's {@code ItemManager.getItemStats}, whose bonuses are the OSRS
	 * Wiki's): <b>Ranged</b> when it has a ranged strength bonus, or a ranged attack bonus above each of its melee and
	 * magic attack bonuses; otherwise <b>Magic</b> when its magic attack bonus is above each of its melee and ranged
	 * ones; otherwise <b>Melee</b>.
	 *
	 * <p>So the blowpipe, bows, crossbows, darts, knives and chinchompas are Ranged (darts have no ranged attack bonus,
	 * only ranged strength), tridents and powered staves are Magic, and so are staves without melee bonuses (a kodai
	 * wand, a nightmare staff). A staff with melee bonuses above its magic one (a staff of the dead, Ahrim's or the
	 * ancient staff) is Melee: it attacks in melee unless it casts, and a cast is told by its animation
	 * ({@link #attackStyle}). Checked against the OSRS Wiki's bonuses of common Slayer weapons on 2026-11-09 (listed
	 * in {@code docs/COUNTING_RULES.md}, "Setup tags"; {@code AttackStylesTest} keeps them).</p>
	 */
	static SetupStyle weaponStyle(int stab, int slash, int crush, int magic, int range, int rangedStrength)
	{
		final int melee = Math.max(stab, Math.max(slash, crush));
		if (rangedStrength > 0 || range > Math.max(melee, magic))
		{
			return SetupStyle.RANGED;
		}
		if (magic > Math.max(melee, range))
		{
			return SetupStyle.MAGIC;
		}
		return SetupStyle.MELEE;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;

/**
 * Decides which bank openings start a new bank trip. Pure: the plugin passes in the interface events and tick numbers
 * it sees on the client thread, and adds a trip to the session when {@link #bankOpened} says so. Not thread-safe.
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>A bank interface ({@link #isBankInterface}: the bank, a deposit box or group storage, the same interfaces
 *     {@link SupplyExclusions} leaves out of supply counting) opening while the session is RUNNING is a trip.</li>
 *     <li>Opening one again within {@link #SAME_TRIP_TICKS} game ticks of the last time one was open (opened or closed)
 *     is the same trip, so going back for a forgotten item, or from a deposit box to the bank, counts once.</li>
 *     <li>Opening a bank while paused or with no session is never a trip, but still starts the window, so re-opening
 *     right after resuming does not count either.</li>
 *     <li>The window belongs to one session: the first opening in a new session always counts.</li>
 * </ul>
 * The trip count itself is kept by {@link SessionTracker} (RUNNING only, cleared when the session ends).
 */
final class BankTripCounter
{
	/** Re-opening a bank within this many game ticks (30 seconds) of it last being open is the same trip. */
	static final int SAME_TRIP_TICKS = 50;

	private static final int[] BANK_INTERFACES = SupplyExclusions.bankInterfaces();

	/** Last tick a bank interface was opened or closed, or {@code null} for none. */
	private Integer lastBankTick;
	/** Session (running or stopped) active when a bank was last opened, or {@code null} for none. */
	private String lastSessionId;

	/** Whether {@code groupId} is the bank, a deposit box or group storage. */
	static boolean isBankInterface(int groupId)
	{
		for (int group : BANK_INTERFACES)
		{
			if (group == groupId)
			{
				return true;
			}
		}
		return false;
	}

	/** A copy of the bank interface group ids. */
	static int[] bankInterfaces()
	{
		return BANK_INTERFACES.clone();
	}

	/**
	 * A bank interface opened on {@code tick}.
	 *
	 * @param running   whether the session is RUNNING
	 * @param sessionId the active session's id, or {@code null} when there is none
	 * @return whether this opening is a new trip to add to the running session
	 */
	boolean bankOpened(int tick, boolean running, String sessionId)
	{
		final boolean sameTrip = withinWindow(tick) && Objects.equals(sessionId, lastSessionId);
		lastBankTick = tick;
		lastSessionId = sessionId;
		return running && sessionId != null && !sameTrip;
	}

	/** A bank interface closed on {@code tick}; the same-trip window runs from here. */
	void bankClosed(int tick)
	{
		if (lastBankTick != null)
		{
			lastBankTick = tick;
		}
	}

	/** Forgets the last bank visit (plugin start). */
	void reset()
	{
		lastBankTick = null;
		lastSessionId = null;
	}

	/**
	 * Whether {@code tick} is within the window of the last visit. A tick before the last visit (the tick count
	 * restarted, for example after a login) is outside it.
	 */
	private boolean withinWindow(int tick)
	{
		return lastBankTick != null && tick >= lastBankTick && (long) tick - lastBankTick <= SAME_TRIP_TICKS;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * What the toxic blowpipe holds, for the overlay's supply runway: its darts and Zulrah's scales as its last check
 * message said ({@link BlowpipeMessage}), less the darts and scales counted as used since ({@link ChargedWeaponUsage}).
 * The client shows no live count, so until a check message is seen the contents are not known. Pure; the plugin uses
 * it on the client thread only.
 *
 * <p>The plugin keeps the contents across a time without a task and across End task, when shots aren't counted (so
 * darts fired then are not taken out), and forgets them when darts or scales are loaded, on Unload or Uncharge, at
 * logout and when the account changes.</p>
 */
@Getter
final class BlowpipeContents
{
	/** An amount not known. */
	static final long UNKNOWN = -1;

	/** The darts' item id, or {@link ChargedWeaponUsage#NO_ITEM} with none or an unknown type. */
	private int dartId = ChargedWeaponUsage.NO_ITEM;
	/** Darts inside, or {@link #UNKNOWN}. */
	private long darts = UNKNOWN;
	/** Zulrah's scales inside, or {@link #UNKNOWN}. */
	private long scales = UNKNOWN;

	/**
	 * A blowpipe message: a check message sets the darts (type and count) and scales; a message that it holds no darts
	 * sets the darts to none, and the scales to none too when it says so, else keeps them.
	 */
	void messageSeen(BlowpipeMessage.Darts message)
	{
		if (message == null)
		{
			return;
		}
		if (!message.isLoaded())
		{
			dartId = ChargedWeaponUsage.NO_ITEM;
			darts = 0;
		}
		else if (message.getDartCount() >= 0)
		{
			dartId = message.getDartId();
			darts = message.getDartId() == ChargedWeaponUsage.NO_ITEM ? UNKNOWN : message.getDartCount();
		}
		if (message.getScales() >= 0)
		{
			scales = message.getScales();
		}
	}

	/** Takes what one tick's shot used ({@link ChargedWeaponUsage#update}: item id to amount) out of the contents. */
	void used(Map<Integer, Integer> used)
	{
		if (used == null || used.isEmpty())
		{
			return;
		}
		final Integer usedScales = used.get(SupplyRunway.ZULRAH_SCALES);
		if (usedScales != null && scales > 0)
		{
			scales = Math.max(0, scales - usedScales);
		}
		final Integer usedDarts = dartId == ChargedWeaponUsage.NO_ITEM ? null : used.get(dartId);
		if (usedDarts != null && darts > 0)
		{
			darts = Math.max(0, darts - usedDarts);
		}
	}

	/** The blowpipe has no Zulrah's scales left ({@link BlowpipeMessage#isOutOfScales}); its darts are as they were. */
	void outOfScales()
	{
		scales = 0;
	}

	/** Forgets the contents: darts or scales were loaded, it was unloaded or uncharged, or it may be another one. */
	void forget()
	{
		dartId = ChargedWeaponUsage.NO_ITEM;
		darts = UNKNOWN;
		scales = UNKNOWN;
	}

	/** Whether both the darts and the scales are known. */
	boolean isKnown()
	{
		return darts != UNKNOWN && scales != UNKNOWN;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.regex.*;
import lombok.*;
import net.runelite.api.gameval.*;

/**
 * Reads the toxic blowpipe's dart type from game messages. Pure; tags and markup are stripped by
 * {@link GameMessageText}.
 *
 * <p>Checking the blowpipe (and, reportedly, adding darts or scales) sends
 * {@code Darts: <name> x <n>. Scales: <n> (<pct>%).} or {@code Darts: None. Scales: ...}, with the values coloured.
 * Tags are stripped before matching; numbers may contain commas. The messages below, from geheur/weapon-charges'
 * recorded game messages, mean the blowpipe has no darts:</p>
 * <ul>
 *     <li>{@code Your blowpipe has run out of darts.}</li>
 *     <li>{@code Your blowpipe has run out of scales and darts.}</li>
 *     <li>{@code Your blowpipe contains no darts.}</li>
 *     <li>{@code Your blowpipe needs to be charged with Zulrah's scales and loaded with darts.}</li>
 *     <li>{@code The blowpipe has no darts in it.} (unloading an empty blowpipe)</li>
 * </ul>
 * The second and fourth also mean it has no Zulrah's scales, and {@code Your blowpipe needs to be charged with Zulrah's
 * scales.} means it has none, saying nothing about its darts ({@link #isOutOfScales}).
 */
final class BlowpipeMessage
{
	private static final Pattern CHECK = Pattern.compile(
		"^Darts: (?:None|(.+?) x ([\\d,]+))\\. Scales: ([\\d,]+) \\(([\\d.]+)%\\)\\.$");

	private static final String[] NO_DARTS = {
		"Your blowpipe has run out of darts.",
		"Your blowpipe has run out of scales and darts.",
		"Your blowpipe contains no darts.",
		"Your blowpipe needs to be charged with Zulrah's scales and loaded with darts.",
		"The blowpipe has no darts in it.",
	};

	/** The {@link #NO_DARTS} messages that also mean the blowpipe has no Zulrah's scales. */
	private static final List<String> NO_DARTS_OR_SCALES = Arrays.asList(
		"Your blowpipe has run out of scales and darts.",
		"Your blowpipe needs to be charged with Zulrah's scales and loaded with darts.");

	/** The blowpipe has no Zulrah's scales; its darts are not mentioned. */
	private static final String NO_SCALES = "Your blowpipe needs to be charged with Zulrah's scales.";

	/** Dart names as the check message shows them (lower case), to item ids. */
	private static final Map<String, Integer> DARTS = darts();

	private static Map<String, Integer> darts()
	{
		final Map<String, Integer> darts = new HashMap<>();
		darts.put("bronze dart", ItemID.BRONZE_DART);
		darts.put("iron dart", ItemID.IRON_DART);
		darts.put("steel dart", ItemID.STEEL_DART);
		darts.put("black dart", ItemID.BLACK_DART);
		darts.put("mithril dart", ItemID.MITHRIL_DART);
		darts.put("adamant dart", ItemID.ADAMANT_DART);
		darts.put("rune dart", ItemID.RUNE_DART);
		darts.put("amethyst dart", ItemID.AMETHYST_DART);
		darts.put("dragon dart", ItemID.DRAGON_DART);
		return Collections.unmodifiableMap(darts);
	}

	/** What a blowpipe message says about the darts inside. */
	@Value
	static class Darts
	{
		/** Whether the blowpipe holds darts. */
		boolean loaded;
		/**
		 * The dart item id, or {@link ChargedWeaponUsage#NO_ITEM} if the blowpipe holds no darts or holds a dart type
		 * this class doesn't know.
		 */
		int dartId;
		/** Darts inside, if the message says (a check message), else -1. */
		int dartCount;
		/** Zulrah's scales inside, if the message says (a check message, or 0 for none), else -1. */
		int scales;
	}

	private BlowpipeMessage()
	{
	}

	/** Whether {@code itemId} is one of the darts the blowpipe takes (the ones its check message names). */
	static boolean isDart(int itemId)
	{
		return DARTS.containsValue(itemId);
	}

	/** The dart item id for a dart name as the check message shows it ("Rune dart"), or {@code NO_ITEM}. */
	static int dartId(String name)
	{
		return DARTS.getOrDefault(name.trim().toLowerCase(Locale.ROOT), ChargedWeaponUsage.NO_ITEM);
	}

	/**
	 * Parses a game message, possibly with tags.
	 *
	 * @return what it says about the blowpipe's darts, or {@code null} if it isn't a blowpipe dart message
	 */
	static Darts parse(String message)
	{
		if (message == null)
		{
			return null;
		}
		final String text = GameMessageText.plain(message);
		final Matcher matcher = CHECK.matcher(text);
		if (matcher.matches())
		{
			final int scales = number(matcher.group(3));
			if (matcher.group(1) == null)
			{
				return new Darts(false, ChargedWeaponUsage.NO_ITEM, 0, scales);
			}
			return new Darts(true, dartId(matcher.group(1)), number(matcher.group(2)), scales);
		}
		for (String noDarts : NO_DARTS)
		{
			if (noDarts.equals(text))
			{
				return new Darts(false, ChargedWeaponUsage.NO_ITEM, 0, NO_DARTS_OR_SCALES.contains(text) ? 0 : -1);
			}
		}
		return null;
	}

	/**
	 * Whether a game message, possibly with tags, says the blowpipe has no Zulrah's scales without saying anything
	 * about its darts ({@code Your blowpipe needs to be charged with Zulrah's scales.}). The messages that say it has
	 * neither are {@link #parse}'s.
	 */
	static boolean isOutOfScales(String message)
	{
		return message != null && NO_SCALES.equals(GameMessageText.plain(message));
	}

	private static int number(String digits)
	{
		try
		{
			return Integer.parseInt(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

