package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;
import net.runelite.client.util.*;

/**
 * The core Ground Items plugin's hidden-items list, parsed, so Slayer Ledger hides the same items from its loot:
 * they are left out of the "Loot received" grids and out of the loot value. Pure: item names are passed in. Read only;
 * Slayer Ledger never writes Ground Items' settings.
 *
 * <p>Rules, as {@code GroundItemsPlugin} (RuneLite 1.13.4) applies its lists:</p>
 * <ul>
 *     <li>Each list is split on commas with RuneLite's {@link Text#fromCSV}: entries are trimmed and blank ones
 *     skipped.</li>
 *     <li>An entry with {@code *} is a wildcard, matched with RuneLite's {@link WildcardMatcher} ({@code *} matches
 *     any run of characters); any other entry must equal the item's name. Both ignore case.</li>
 *     <li>The highlighted list overrides the hidden one: an exact highlighted entry beats any hidden entry, and a
 *     wildcard highlighted entry beats a wildcard hidden entry, but an exact hidden entry beats a wildcard highlighted
 *     one ({@code GroundItemsPlugin.isHiddenOrHighlighted}).</li>
 *     <li>An entry with a quantity condition ("Coins &lt; 1000", "Bones &gt; 5") is ignored, in either list. Ground
 *     Items checks it against each stack on the ground; Slayer Ledger keeps only a task's totals, so it can't tell
 *     which drops the condition held for. "Name &gt; 0" has no condition (it holds for every stack).</li>
 *     <li>The name matched is the item's own name. A noted item's name is its unnoted item's name, so a note matches
 *     like the item.</li>
 *     <li>A list never edited reads as {@code null} from the config; Ground Items then uses its built-in default
 *     ({@link #DEFAULT_HIDDEN_ITEMS}), and so does Slayer Ledger.</li>
 * </ul>
 *
 * <p>Immutable, so a parsed list can be shared between threads; equal lists are {@link #equals equal}.</p>
 */
@EqualsAndHashCode
@ToString
@AllArgsConstructor(access = AccessLevel.PRIVATE)
final class GroundItemsHidden
{
	/** Ground Items' config group ({@code GroundItemsConfig.GROUP}). */
	static final String GROUP = "grounditems";
	/** Ground Items' hidden-items key. */
	static final String HIDDEN_ITEMS_KEY = "hiddenItems";
	/** Ground Items' highlighted-items key. */
	static final String HIGHLIGHTED_ITEMS_KEY = "highlightedItems";
	/**
	 * Ground Items' built-in hidden list ({@code GroundItemsConfig.getHiddenItems()} in RuneLite 1.13.4), used while
	 * the setting was never edited. Recheck it when the RuneLite version is raised.
	 */
	static final String DEFAULT_HIDDEN_ITEMS = "Vial, Ashes, Coins, Bones, Bucket, Jug, Seaweed";
	/** The config group RuneLite keeps every plugin's on/off state in ({@code RuneLiteConfig.GROUP_NAME}). */
	static final String PLUGIN_ENABLED_GROUP = "runelite";
	/** Ground Items' on/off key: its class name in lower case ({@code PluginManager.isPluginEnabled}). */
	static final String PLUGIN_ENABLED_KEY = "grounditemsplugin";

	/** Hides nothing. */
	static final GroundItemsHidden NONE = new GroundItemsHidden(Collections.emptyList(), Collections.emptyList());

	/** No match, a wildcard match and an exact match, in Ground Items' order of strength. */
	private static final int NO_MATCH = 0;
	private static final int WILDCARD = 1;
	private static final int EXACT = 2;

	private final List<Entry> hidden;
	private final List<Entry> highlighted;

	/**
	 * What Slayer Ledger hides: nothing while its "Hide Ground Items' hidden items" setting is off or the Ground Items
	 * plugin is turned off, otherwise Ground Items' lists ({@link #parse}).
	 *
	 * @param settingOn          Slayer Ledger's setting
	 * @param groundItemsEnabled Ground Items' on/off value from the config ({@link #PLUGIN_ENABLED_KEY}); {@code null}
	 *                           (never changed) is on, as Ground Items is on by default
	 * @param hiddenSetting      Ground Items' hidden list, or {@code null} when never edited
	 * @param highlightedSetting Ground Items' highlighted list, or {@code null} when never edited
	 */
	static GroundItemsHidden effective(boolean settingOn, String groundItemsEnabled, String hiddenSetting,
		String highlightedSetting)
	{
		if (!settingOn || groundItemsEnabled != null && !Boolean.parseBoolean(groundItemsEnabled))
		{
			return NONE;
		}
		return parse(hiddenSetting, highlightedSetting);
	}

	/**
	 * Parses Ground Items' lists; see the class rules.
	 *
	 * @param hiddenSetting      the hidden list; {@code null} (never edited) is {@link #DEFAULT_HIDDEN_ITEMS}
	 * @param highlightedSetting the highlighted list; {@code null} (never edited) is empty, its default
	 */
	static GroundItemsHidden parse(String hiddenSetting, String highlightedSetting)
	{
		List<Entry> hidden = entries(hiddenSetting == null ? DEFAULT_HIDDEN_ITEMS : hiddenSetting);
		if (hidden.isEmpty())
		{
			return NONE;
		}
		return new GroundItemsHidden(hidden, entries(highlightedSetting == null ? "" : highlightedSetting));
	}

	/** Whether nothing is hidden, so no item names need to be looked up. */
	boolean isEmpty()
	{
		return hidden.isEmpty();
	}

	/**
	 * Whether Ground Items hides an item named {@code name} (its own name; a note's is the unnoted item's); {@code null}
	 * (unknown) never is.
	 */
	boolean hides(String name)
	{
		if (name == null || hidden.isEmpty())
		{
			return false;
		}
		int highlight = match(highlighted, name);
		if (highlight == EXACT)
		{
			return false;
		}
		int hide = match(hidden, name);
		return hide == EXACT || hide == WILDCARD && highlight != WILDCARD;
	}

	/** Ground Items' {@code ItemList.matches}: an exact entry first, then a wildcard one. */
	private static int match(List<Entry> entries, String name)
	{
		for (Entry e : entries)
		{
			if (!e.wildcard && e.name.equalsIgnoreCase(name))
			{
				return EXACT;
			}
		}
		for (Entry e : entries)
		{
			if (e.wildcard && WildcardMatcher.matches(e.name, name))
			{
				return WILDCARD;
			}
		}
		return NO_MATCH;
	}

	/** The list's entries without a quantity condition, in order. */
	private static List<Entry> entries(String setting)
	{
		List<Entry> result = new ArrayList<>();
		for (String raw : Text.fromCSV(setting))
		{
			Entry entry = Entry.parse(raw);
			if (entry != null && !result.contains(entry))
			{
				result.add(entry);
			}
		}
		return Collections.unmodifiableList(result);
	}

	/** One entry of a list: a name or wildcard pattern. */
	@EqualsAndHashCode
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Entry
	{
		private final String name;
		private final boolean wildcard;

		/**
		 * Parses an entry as {@code ItemThreshold.fromName} does: a trailing {@code < n} or {@code > n} is a quantity
		 * condition. Returns {@code null} for an empty entry or one with a condition (see the class rules).
		 */
		static Entry parse(String entry)
		{
			if (entry == null || entry.isEmpty())
			{
				return null;
			}
			boolean wildcard = entry.contains("*");
			String name = entry;
			for (int i = entry.length() - 1; i >= 0; i--)
			{
				char c = entry.charAt(i);
				if (c >= '0' && c <= '9' || Character.isWhitespace(c))
				{
					continue;
				}
				if ((c == '<' || c == '>') && i + 1 < entry.length())
				{
					int quantity;
					try
					{
						quantity = Integer.parseInt(entry.substring(i + 1).trim());
					}
					catch (NumberFormatException e)
					{
						// Ground Items then counts it as "> 0", which every stack meets.
						quantity = 0;
						c = '>';
					}
					if (c == '<' || quantity != 0)
					{
						return null;
					}
					name = entry.substring(0, i);
				}
				break;
			}
			name = name.trim();
			return name.isEmpty() ? null : new Entry(name, wildcard);
		}

		@Override
		public String toString()
		{
			return name;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * The loot item ids Ground Items' hidden list hides, as worked out from their names by
 * {@link HiddenLootResolver}. Every one is left out of the "Loot received" grids ({@link #visibleRows}); every one
 * but coins is also left out of the loot value (and so profit) wherever loot is valued ({@link #valued}). Coins always
 * count in the value (owner decision, 2026-10-28): only {@link ItemValuation#COINS} drops as loot, the other coin-like
 * ids in the item list (fake, Mage Training Arena) never do. Ids are as tallied, so a noted id is listed on its own.
 * Stored loot is never changed: this is applied when loot is valued or shown.
 *
 * <p>Immutable, so it can be handed to the views worked out off the EDT; equal sets are {@link #equals equal}.</p>
 */
@EqualsAndHashCode
@ToString
final class HiddenLoot
{
	/** Hides nothing. */
	static final HiddenLoot NONE = new HiddenLoot(Collections.emptySet());

	/** Hidden from view. */
	private final Set<Integer> ids;
	/** Left out of the value: {@link #ids} without coins. */
	@EqualsAndHashCode.Exclude
	@ToString.Exclude
	private final Set<Integer> valueIds;

	private HiddenLoot(Set<Integer> ids)
	{
		this.ids = ids;
		if (ids.contains(ItemValuation.COINS))
		{
			Set<Integer> withoutCoins = new TreeSet<>(ids);
			withoutCoins.remove(ItemValuation.COINS);
			valueIds = Collections.unmodifiableSet(withoutCoins);
		}
		else
		{
			valueIds = ids;
		}
	}

	/** The ids in {@code ids} ({@code null} ones skipped); {@link #NONE} when there are none. */
	static HiddenLoot of(Collection<Integer> ids)
	{
		Set<Integer> set = new TreeSet<>();
		if (ids != null)
		{
			for (Integer id : ids)
			{
				if (id != null)
				{
					set.add(id);
				}
			}
		}
		return set.isEmpty() ? NONE : new HiddenLoot(Collections.unmodifiableSet(set));
	}

	/** Whether nothing is hidden from view. */
	boolean isEmpty()
	{
		return ids.isEmpty();
	}

	/**
	 * {@code loot} as valued: without the hidden items except coins. A new tally, or {@code loot} itself when nothing
	 * in it is left out of the value. Never changes it.
	 */
	ItemTally valued(ItemTally loot)
	{
		if (loot == null || !leavesOutAny(loot.itemIds()))
		{
			return loot;
		}
		ItemTally kept = new ItemTally();
		for (int id : loot.itemIds())
		{
			if (!valueIds.contains(id))
			{
				kept.add(id, loot.get(id));
			}
		}
		return kept;
	}

	/** Whether any of {@code itemIds} is left out of the value (a hidden item other than coins). */
	boolean leavesOutAny(Collection<Integer> itemIds)
	{
		if (valueIds.isEmpty() || itemIds == null)
		{
			return false;
		}
		for (Integer id : itemIds)
		{
			if (id != null && valueIds.contains(id))
			{
				return true;
			}
		}
		return false;
	}

	/** The rows of items not hidden from view, in order; coins are hidden like any other item. */
	List<ItemDetails.Row> visibleRows(List<ItemDetails.Row> rows)
	{
		if (ids.isEmpty())
		{
			return rows;
		}
		List<ItemDetails.Row> kept = new ArrayList<>(rows.size());
		for (ItemDetails.Row row : rows)
		{
			if (!ids.contains(row.getItemId()))
			{
				kept.add(row);
			}
		}
		return kept;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;

/**
 * Works out which loot item ids Ground Items' hidden list ({@link GroundItemsHidden}) hides, from the items' names
 *. Each id is matched once per list: the answer is kept until the list changes ({@link #setList}), so the
 * wildcard matching does not run per tick or per row. An id whose name is unknown is not hidden, and is matched again
 * once its name is known.
 *
 * <p>Not thread-safe: each owner uses its own, on one thread (the plugin's on the client thread, the history model's
 * on the EDT).</p>
 */
final class HiddenLootResolver
{
	private GroundItemsHidden list = GroundItemsHidden.NONE;
	/** Whether each id matched so far hides, for {@link #list}. */
	private final Map<Integer, Boolean> matched = new HashMap<>();

	/** The list matched against. */
	GroundItemsHidden list()
	{
		return list;
	}

	/** Matches against {@code newList} from now on ({@code null} is none); returns whether it changed. */
	boolean setList(GroundItemsHidden newList)
	{
		GroundItemsHidden l = newList == null ? GroundItemsHidden.NONE : newList;
		if (l.equals(list))
		{
			return false;
		}
		list = l;
		matched.clear();
		return true;
	}

	/**
	 * The hidden ones of {@code itemIds}.
	 *
	 * @param names an item's own name (a note's is the unnoted item's), or {@code null} while unknown; a lookup that
	 *              throws counts as unknown. Only called for ids not matched yet.
	 */
	HiddenLoot resolve(Collection<Integer> itemIds, IntFunction<String> names)
	{
		if (list.isEmpty() || itemIds == null)
		{
			return HiddenLoot.NONE;
		}
		Set<Integer> hidden = new TreeSet<>();
		for (Integer id : itemIds)
		{
			if (id == null)
			{
				continue;
			}
			Boolean hides = matched.get(id);
			if (hides == null)
			{
				String name;
				try
				{
					name = names.apply(id);
				}
				catch (RuntimeException e)
				{
					name = null;
				}
				if (name == null)
				{
					continue;
				}
				hides = list.hides(name);
				matched.put(id, hides);
			}
			if (hides)
			{
				hidden.add(id);
			}
		}
		return HiddenLoot.of(hidden);
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;
import lombok.*;

/**
 * The Task history's filters: Monster, Location and Slayer master, each {@link LedgerHistory#ALL} or one value.
 * A record is shown when it matches every filter set (AND). Each filter's choices are the values in the records, so a
 * choice that matches nothing alone never appears; together the filters can still match nothing. Immutable and pure
 * (no Swing or RuneLite types).
 *
 * <ul>
 *   <li><b>Monster</b>: {@link LedgerHistory#monster} (the record's group name: Catacombs variant, cannon), exactly.</li>
 *   <li><b>Location</b>: the record's Slayer spot ({@link SlayerSpots#recordSpot}), so a task renamed on its own
 *   still groups with its spot's other tasks; each choice is shown as the location name
 *   ({@link TaskLocation#recordLocation}) of its newest record without a name of its own ({@link #locationChoices}).
 *   A record without a spot but with a name of its own (an older task named by hand, or an older Konar task with no
 *   region) groups by that name, compared by {@link TaskLocation#matchKey}; one with neither is
 *   {@link #NO_LOCATION}, shown as {@link #NO_LOCATION_LABEL}.</li>
 *   <li><b>Master</b>: {@link SlayerMaster#displayName} of the master who assigned the task; {@link #UNKNOWN_MASTER}
 *   for a record without one or with a value not in {@link SlayerMaster}'s table.</li>
 * </ul>
 *
 * <p>The setup filters (V2 plan 5) are {@link #ANY_LABEL "Any"} ({@code null}) or one value, each with a fixed
 * list of choices: <b>Task type</b> ({@link #TASK_TYPE_CHOICES}, {@link TaskType#of} the record's master and creature
 * key), <b>Cannon</b> ({@link #CANNON_CHOICES}), <b>Style</b> ({@link #STYLE_CHOICES}) and <b>Gear</b>
 * ({@link #GEAR_CHOICES}), the last three the record's effective tags ({@link SetupTags#of}: the player's override,
 * else the detected value). A record whose value is unknown (no task type, an Unknown style or gear) matches only
 * "Any", and an estimated value is its value ({@code ~Barrage} is Barrage). Set them with {@link #withTaskType},
 * {@link #withCannon}, {@link #withStyle} and {@link #withGear}.</p>
 */
final class HistoryFilter
{
	/** How the setup filters show "no filter" ({@code null}). */
	static final String ANY_LABEL = "Any";
	/** The Task type filter's choices, in order; {@code null} is "Any". Unmodifiable. */
	static final List<TaskType> TASK_TYPE_CHOICES = choices(null, TaskType.REGULAR, TaskType.KONAR,
		TaskType.WILDERNESS, TaskType.BOSS);
	/** The Cannon filter's choices, in order: "Any" ({@code null}), "Yes", "No". Unmodifiable. */
	static final List<Boolean> CANNON_CHOICES = choices(null, Boolean.TRUE, Boolean.FALSE);
	/** The Style filter's choices, in order; {@code null} is "Any" (Unknown is not a choice). Unmodifiable. */
	static final List<SetupStyle> STYLE_CHOICES = choices(null, SetupStyle.MELEE, SetupStyle.RANGED,
		SetupStyle.BARRAGE, SetupStyle.MAGIC, SetupStyle.MIXED);
	/** The Gear filter's choices, in order; {@code null} is "Any" (Unknown is not a choice). Unmodifiable. */
	static final List<GearFocus> GEAR_CHOICES = choices(null, GearFocus.PRAYER, GearFocus.STRENGTH, GearFocus.MIXED);

	/**
	 * Location choice of the records without a location (older records without a region), shown as
	 * {@link #NO_LOCATION_LABEL}. Empty, so it never equals a spot or a name key.
	 */
	static final String NO_LOCATION = "";
	/** How the Location filter shows {@link #NO_LOCATION}. */
	static final String NO_LOCATION_LABEL = "No location";
	/**
	 * Start of the Location choice of records without a spot that have a name of their own: {@code name:} and the name's
	 * {@link TaskLocation#matchKey}. Spot keys never contain it (table ids have no colon; unlisted regions' keys start
	 * {@link SlayerSpots#REGION_PREFIX}).
	 */
	static final String NAME_PREFIX = "name:";
	/**
	 * Master choice of the records whose master is not known. Shown as it is: masters' names come from
	 * {@link SlayerMaster}'s table, so none can be the same.
	 */
	static final String UNKNOWN_MASTER = "Unknown master";

	/** Alphabetical, ignoring case first, as the Monster filter sorts. */
	private static final Comparator<String> ALPHABETICAL = String.CASE_INSENSITIVE_ORDER
		.thenComparing(Comparator.naturalOrder());

	private final String monster;
	private final String location;
	private final String master;
	/** The Task type choice, or {@code null} for "Any". */
	private final TaskType taskType;
	/** The Cannon choice, or {@code null} for "Any". */
	private final Boolean cannon;
	/** The Style choice, or {@code null} for "Any"; never {@link SetupStyle#UNKNOWN}. */
	private final SetupStyle style;
	/** The Gear choice, or {@code null} for "Any"; never {@link GearFocus#UNKNOWN}. */
	private final GearFocus gear;

	/**
	 * The Monster, Location and Master filters, with every setup filter "Any".
	 *
	 * @param monster  a Monster choice, or {@code null} for "All"
	 * @param location a Location choice ({@link #locationKey}; {@link #NO_LOCATION} included), or {@code null} for "All"
	 * @param master   a Master choice ({@link #UNKNOWN_MASTER} included), or {@code null} for "All"
	 */
	HistoryFilter(String monster, String location, String master)
	{
		this(monster, location, master, null, null, null, null);
	}

	private HistoryFilter(String monster, String location, String master, TaskType taskType, Boolean cannon,
		SetupStyle style, GearFocus gear)
	{
		this.monster = monster;
		this.location = location;
		this.master = master;
		this.taskType = taskType;
		this.cannon = cannon;
		this.style = style == SetupStyle.UNKNOWN ? null : style;
		this.gear = gear == GearFocus.UNKNOWN ? null : gear;
	}

	/** This filter with the Task type choice {@code type} ({@code null}: "Any"). */
	HistoryFilter withTaskType(TaskType type)
	{
		return new HistoryFilter(monster, location, master, type, cannon, style, gear);
	}

	/** This filter with the Cannon choice {@code withCannon} ({@code null}: "Any"). */
	HistoryFilter withCannon(Boolean withCannon)
	{
		return new HistoryFilter(monster, location, master, taskType, withCannon, style, gear);
	}

	/** This filter with the Style choice {@code choice} ({@code null}, and Unknown, which is no choice: "Any"). */
	HistoryFilter withStyle(SetupStyle choice)
	{
		return new HistoryFilter(monster, location, master, taskType, cannon, choice, gear);
	}

	/** This filter with the Gear choice {@code choice} ({@code null}, and Unknown, which is no choice: "Any"). */
	HistoryFilter withGear(GearFocus choice)
	{
		return new HistoryFilter(monster, location, master, taskType, cannon, style, choice);
	}

	/** How the Monster and Master filters show {@code choice}: {@link #NO_LOCATION_LABEL} for {@link #NO_LOCATION}. */
	static String label(String choice)
	{
		return NO_LOCATION.equals(choice) ? NO_LOCATION_LABEL : choice;
	}

	/**
	 * How a setup filter shows {@code choice}: {@link #ANY_LABEL} for {@code null}, "Yes" or "No" for a cannon choice
	 * ({@link SetupTags#cannonLabel}), and a type's, style's or gear focus's own label ("Konar", "Barrage", "Prayer").
	 */
	static String setupLabel(Object choice)
	{
		if (choice == null)
		{
			return ANY_LABEL;
		}
		if (choice instanceof Boolean)
		{
			return SetupTags.cannonLabel((Boolean) choice);
		}
		if (choice instanceof SetupStyle)
		{
			return ((SetupStyle) choice).getLabel();
		}
		if (choice instanceof GearFocus)
		{
			return ((GearFocus) choice).getLabel();
		}
		return choice.toString();
	}

	@SafeVarargs
	private static <T> List<T> choices(T... values)
	{
		return Collections.unmodifiableList(Arrays.asList(values));
	}

	/**
	 * A record's Location choice: its spot's key ({@link SlayerSpots#recordSpot}), else {@link #NAME_PREFIX} and its own
	 * name's {@link TaskLocation#matchKey}, else {@link #NO_LOCATION}.
	 */
	static String locationKey(LedgerRecord record, SlayerSpots spots, IntFunction<String> regionNames)
	{
		final SlayerSpots table = spots == null ? SlayerSpots.NONE : spots;
		final String spot = table.recordSpot(record);
		if (spot != null)
		{
			return spot;
		}
		final String name = TaskLocation.recordLocation(record, regionNames, table);
		return name == null ? NO_LOCATION : NAME_PREFIX + TaskLocation.matchKey(name);
	}

	/** The master who assigned the task, as the Master filter lists it: {@link #UNKNOWN_MASTER} when not known. */
	static String master(LedgerRecord record)
	{
		return SlayerMaster.hasName(record.getSlayerMaster()) ? SlayerMaster.displayName(record.getSlayerMaster())
			: UNKNOWN_MASTER;
	}

	/**
	 * The Location filter's choices: {@link LedgerHistory#ALL}, each location key in the records ({@link #locationKey})
	 * alphabetically by its label, then {@link #NO_LOCATION} when a record has none. Each key's label is the location
	 * name of its newest record without a name of its own (records are newest first): its region's name or the table's
	 * name, since a per-task rename names that task only (V2 plan 4.5). Only when every record of the key has its own
	 * name (1.x tasks named by hand) is it the newest record's own name. {@link #NO_LOCATION}'s is
	 * {@link #NO_LOCATION_LABEL}.
	 */
	static LocationChoices locationChoices(Collection<LedgerRecord> records, SlayerSpots spots,
		IntFunction<String> regionNames)
	{
		// Each key's newest known name from a record without a name of its own, and from one with.
		final Set<String> found = new HashSet<>();
		final Map<String, String> placeNames = new HashMap<>();
		final Map<String, String> ownNames = new HashMap<>();
		boolean none = false;
		for (LedgerRecord record : records)
		{
			if (record == null)
			{
				continue;
			}
			final String key = locationKey(record, spots, regionNames);
			if (NO_LOCATION.equals(key))
			{
				none = true;
				continue;
			}
			found.add(key);
			final String name = TaskLocation.recordLocation(record, regionNames, spots);
			if (name != null)
			{
				final boolean ownName = TaskLocation.normalizeName(record.getLocation()) != null;
				(ownName ? ownNames : placeNames).putIfAbsent(key, name);
			}
		}
		final Map<String, String> labels = new HashMap<>();
		for (String key : found)
		{
			final String place = placeNames.get(key);
			final String own = ownNames.get(key);
			labels.put(key, place != null ? place : own != null ? own : TaskLocation.UNKNOWN);
		}
		final List<String> keys = new ArrayList<>(labels.keySet());
		keys.sort(Comparator.comparing((String key) -> labels.get(key), ALPHABETICAL)
			.thenComparing(Comparator.naturalOrder()));
		final List<String> options = new ArrayList<>(keys.size() + 2);
		options.add(LedgerHistory.ALL);
		options.addAll(keys);
		final Map<String, String> allLabels = new HashMap<>(labels);
		if (none)
		{
			options.add(NO_LOCATION);
			allLabels.put(NO_LOCATION, NO_LOCATION_LABEL);
		}
		return new LocationChoices(options, allLabels);
	}

	/**
	 * Master choices: {@link LedgerHistory#ALL}, each master in the records alphabetically, then
	 * {@link #UNKNOWN_MASTER} when a record's master is not known.
	 */
	static List<String> masterOptions(Collection<LedgerRecord> records)
	{
		List<String> names = new ArrayList<>();
		boolean unknown = false;
		for (LedgerRecord record : records)
		{
			if (record == null)
			{
				continue;
			}
			String name = master(record);
			if (UNKNOWN_MASTER.equals(name))
			{
				unknown = true;
			}
			else
			{
				names.add(name);
			}
		}
		TreeSet<String> sorted = new TreeSet<>(ALPHABETICAL);
		sorted.addAll(names);
		List<String> options = new ArrayList<>(sorted.size() + 2);
		options.add(LedgerHistory.ALL);
		options.addAll(sorted);
		if (unknown)
		{
			options.add(UNKNOWN_MASTER);
		}
		return options;
	}

	/**
	 * The Location choice to keep after the choices change ({@code options} start with "All"): {@code selection} while
	 * it is still a choice (a spot keeps its key when its tasks are renamed), otherwise {@code null} ("All").
	 */
	static String keepLocation(List<String> options, String selection)
	{
		return selection != null && options.subList(Math.min(1, options.size()), options.size()).contains(selection)
			? selection : null;
	}

	/** Whether {@code record} matches every filter set. */
	boolean matches(LedgerRecord record, SlayerSpots spots, IntFunction<String> regionNames)
	{
		if (monster != null && !monster.equals(LedgerHistory.monster(record)))
		{
			return false;
		}
		if (master != null && !master.equals(master(record)))
		{
			return false;
		}
		if (!matchesSetup(record))
		{
			return false;
		}
		return location == null || location.equals(locationKey(record, spots, regionNames));
	}

	/**
	 * Whether {@code record} matches the setup filters (Task type, Cannon, Style, Gear): each "Any", or the record's
	 * value. An unknown value matches only "Any"; an estimated value counts as its value.
	 */
	boolean matchesSetup(LedgerRecord record)
	{
		if (taskType != null && taskType != TaskType.of(record.getSlayerMaster(), record.getCreatureId()))
		{
			return false;
		}
		if (cannon == null && style == null && gear == null)
		{
			return true;
		}
		final SetupTags tags = SetupTags.of(record);
		return (cannon == null || cannon == tags.isCannon()) && (style == null || style == tags.getStyle())
			&& (gear == null || gear == tags.getGear());
	}

	/** The records matching every filter set, in their order; nulls are left out. */
	List<LedgerRecord> apply(List<LedgerRecord> records, SlayerSpots spots, IntFunction<String> regionNames)
	{
		List<LedgerRecord> result = new ArrayList<>();
		for (LedgerRecord record : records)
		{
			if (record != null && matches(record, spots, regionNames))
			{
				result.add(record);
			}
		}
		return result;
	}

	/** The Location filter's choices and how each is shown. Immutable. */
	@Getter
	static final class LocationChoices
	{
		/** {@link LedgerHistory#ALL}, the location keys, then {@link #NO_LOCATION} if any record has none. */
		private final List<String> options;
		/** Each key's label (not {@link LedgerHistory#ALL}'s). */
		private final Map<String, String> labels;

		private LocationChoices(List<String> options, Map<String, String> labels)
		{
			this.options = Collections.unmodifiableList(options);
			this.labels = Collections.unmodifiableMap(labels);
		}

		/** How the filter shows {@code key}: its label, else the key itself ("All"). */
		String label(String key)
		{
			final String label = labels.get(key);
			return label != null ? label : key;
		}
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.awt.event.*;
import java.awt.font.*;
import java.time.*;
import java.time.format.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import javax.swing.border.*;
import lombok.*;

/**
 * The "Task history" section of {@link SlayerLedgerPanel}, in look A (DESIGN_PRINCIPLES.md 3.7): a flat
 * section header, the filters, the hints, the error line and one flat row per saved task, valued at today's prices
 *, with its item details below it while open and a right-click menu to edit or delete it. The rows are rebuilt
 * from the history model's records only when they, their pricing, the filters or the names they show change; while
 * views wait for today's prices the rows shown stay. EDT only.
 *
 * <p>Rows: two lines on the page, separated by a 1 px rule, with the hover background ({@link LedgerTheme#HOVER})
 * under the mouse. Left, the task's icon ({@link TaskIcons}, from the record's assigned name, so a Catacombs
 * variant or cannon task shows its task's; an empty slot of the same size otherwise) and its name
 * ({@link LedgerHistory#monster}: the variant, {@code (cannon)}), then in Small {@link LedgerHistory#PARTIAL} for a
 * partial task (the only status a row names), the date, the location's short form ({@link TaskLocation#shortName}) and
 * one game image per effective setup tag ({@link SetupTagIcons#tags}, as the overlay and the live card's toggles show
 * it, from {@link SetupImages}; the row shows its tooltip over it). Right, the active
 * time ({@link LedgerFormat#duration}) and the profit, signed and coloured ({@link LedgerFormat#signed}, {@code ~} when
 * approximate). Nothing asks for width: the name and the second line are {@link FitLabel}s cut short with {@code \u2026},
 * and the tooltip ({@link LedgerHistory#historyRowTooltip}) starts with the full name, the date and time, the exact
 * active time, the kills and the XP. Only the row listens to the mouse, so its click, hover and menu work over every
 * part of it. The icons are asked for only as rows are built, never on the refresh timer.</p>
 *
 * <p>Filters (V2 plan 5, {@link HistoryFilter}): Monster, Location, Master and Task type always show; Cannon,
 * Style and Gear sit behind a {@code More filters} toggle, which opens by itself when one of them is set and stays as
 * the player left it while the section exists. They combine. Monster, Location and Master list only the values in the
 * account's records; their choices are rebuilt when the records change and when region names arrive or are forgotten
 * (a record's location may be its region's name), never on the refresh timer, and a selected value that is gone goes
 * back to "All". The Location filter's choices are spots, each shown by its newest task's location name. The
 * setup filters have fixed choices, "Any" first. While any filter is set the header counts them ({@code Task history \u00b7
 * 2 filters}), and {@code Clear filters} shows beside the {@code More filters} toggle.</p>
 *
 * <p>Paging: at most {@link #PAGE_SIZE} rows are built at first, with a "Show N more" button below them that
 * adds the next {@link #PAGE_SIZE} (ignored while the rows wait for today's prices). Choosing another value in a
 * filter (or a filter dropping the selected one), clearing the filters and another account's history go back to the
 * first page; reloads of the same account's records (a save, an edit, a delete, new prices or names) keep the rows the
 * player has opened up. A row's tooltip is built the first time it is asked for, not with the row.</p>
 */
final class HistoryListSection
{
	/** Changes one value of a saved record: {@code (account, record id, new value)}. */
	@FunctionalInterface
	interface RecordEdit
	{
		void apply(long account, String recordId, String value);
	}

	/** Sets a saved record's setup overrides: {@code (account, record id, overrides)}. */
	@FunctionalInterface
	interface SetupEdit
	{
		void apply(long account, String recordId, SetupOverrides overrides);
	}

	/** The section header's title. */
	static final String TITLE = "Task history";
	/** Shown instead of the rows while the account has no saved task (DESIGN_PRINCIPLES.md 3.9). */
	static final String NO_HISTORY = "No saved tasks yet. Finished tasks show up here.";
	/** Shown instead of the rows when the filters together match none of the saved tasks, with {@link #CLEAR_FILTERS}. */
	static final String NO_MATCHES = "No tasks match these filters.";
	/** The link that sets every filter back to All or Any. */
	static final String CLEAR_FILTERS = "Clear filters";
	/** The toggle that shows the setup filters (Cannon, Style, Gear). */
	static final String MORE_FILTERS = "More filters";
	/** The same toggle while they show. */
	static final String HIDE_MORE_FILTERS = "Hide more filters";
	/** The hint under the filters, naming every right-click menu item (HTML, so it wraps in the narrow sidebar). */
	static final String EDIT_HINT = "<html>Right-click a task to edit its note, location or setup, or delete it.</html>";
	/** The right-click menu item that opens a saved task's setup dialog. */
	static final String SETUP_MENU_ITEM = "Setup\u2026";
	/**
	 * The right-click menu item that renames a region the spot table doesn't list, for every task there; only
	 * on such a task.
	 */
	static final String RENAME_PLACE_MENU_ITEM = "Rename place (all its tasks)";
	/** Rows shown at first, and added by each click on {@link #showMoreButton}. */
	static final int PAGE_SIZE = 25;
	/** Between the date and the location on a row's second line. */
	static final String SEPARATOR = " \u00b7 ";

	/** Space between a row's left and right parts, and around the hover background. */
	private static final int GAP = 6;
	/** Space between the parts of a row's second line, and between its tag icons. */
	private static final int SMALL_GAP = 2;
	/** A row's padding inside its hover background. */
	private static final int ROW_PADDING = 4;
	/** Sizes every filter box alike, from a short name, so a long name never widens the sidebar. */
	private static final String FILTER_PROTOTYPE = "Abyssal demons";

	private final LedgerHistoryModel model;
	/**
	 * Deletes a saved record, after the player confirmed it: {@code (account, record id)}. The panel also drops a
	 * notice about that record first.
	 */
	private final BiConsumer<Long, String> deleteRecord;
	/** Saves a record's new note ({@code null} removes it). */
	private final RecordEdit editNote;
	/** Saves a record's new location name ({@code null} removes it). */
	private final RecordEdit editLocation;
	/** Saves a record's setup overrides (each {@code null} clears one). */
	private final SetupEdit editSetup;
	/**
	 * Renames a region the spot table doesn't list for every task there ({@code (region, name)}); {@code true}
	 * when the name was taken. None until {@link #setRenamePlace}.
	 */
	@Setter
	private BiPredicate<Integer, String> renamePlace = (region, name) -> false;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Parent of the dialogs. */
	private final Component dialogParent;
	/** Draws the task and tag icons of the rows and the item and skill icons of a row's details. */
	private final SidebarIcons icons;
	/** The shown rows' tag icons whose image has not arrived yet, by image; forgotten when the rows are cleared. */
	private final Map<SetupTagIcons.Icon, List<JLabel>> waitingTags = new EnumMap<>(SetupTagIcons.Icon.class);

	/** The section header's title, with the number of filters set ({@link #headerText}). */
	private final JLabel titleLabel = new JLabel(TITLE);
	/** In the header while a filter is set: sets every filter back to All or Any. */
	private final JButton clearButton = new JButton(CLEAR_FILTERS);

	private final FilterChoice monsterFilter = new FilterChoice("history.filter", "Show only tasks for this monster",
		HistoryFilter::label);
	/** The Location filter's choices are spot keys ({@link HistoryFilter#locationKey}), shown by their labels. */
	private HistoryFilter.LocationChoices locationChoices;
	private final FilterChoice locationFilter = new FilterChoice("history.locationFilter",
		"Show only tasks at this location", key -> locationChoices == null ? HistoryFilter.label(key)
		: locationChoices.label(key));
	private final FilterChoice masterFilter = new FilterChoice("history.masterFilter",
		"Show only tasks from this Slayer master", HistoryFilter::label);
	private final SetupFilter<TaskType> taskTypeFilter = new SetupFilter<>("history.taskTypeFilter",
		"Show only tasks of this type", HistoryFilter.TASK_TYPE_CHOICES);
	private final SetupFilter<Boolean> cannonFilter = new SetupFilter<>("history.cannonFilter",
		"Show only tasks with or without a cannon", HistoryFilter.CANNON_CHOICES);
	private final SetupFilter<SetupStyle> styleFilter = new SetupFilter<>("history.styleFilter",
		"Show only tasks of this attack style", HistoryFilter.STYLE_CHOICES);
	private final SetupFilter<GearFocus> gearFilter = new SetupFilter<>("history.gearFilter",
		"Show only tasks with this gear focus", HistoryFilter.GEAR_CHOICES);
	/** Shows or hides the setup filters; see {@link #moreOpen}. */
	private final JButton moreToggle = new JButton(MORE_FILTERS);
	/**
	 * Whether the setup filters (Cannon, Style, Gear) show: opened and closed by {@link #moreToggle}, and opened when one
	 * of them is set. Kept while the section exists, also across accounts.
	 */
	private boolean moreOpen;

	private final JPanel list = new JPanel();
	/** Shown instead of the rows: {@link #emptyLabel}, with {@link #emptyClearButton} when no task matches. */
	private final JPanel emptyBlock = new JPanel();
	private final JLabel emptyLabel = new JLabel();
	/** Under {@link #NO_MATCHES}: sets every filter back to All or Any. */
	private final JButton emptyClearButton = new JButton(CLEAR_FILTERS);
	private final JLabel errorLabel = new JLabel();
	/** Account whose history the section last showed, so another account's selection and open rows are forgotten. */
	private long shownAccount = SessionTracker.NO_ACCOUNT;
	/** Keys ({@link #recordKey}) of the history rows whose item details are open. */
	private final Set<String> expandedRecords = new HashSet<>();
	/** XP lists of open history rows showing all their skills ("+N more" clicked), by record key and list title. */
	private final Set<String> listsShowingAll = new HashSet<>();
	/** Below the shown rows while more of the filtered records are left: adds {@link #PAGE_SIZE} rows. */
	private final JButton showMoreButton = new JButton();
	/** How many of the filtered records get a row: a multiple of {@link #PAGE_SIZE}. */
	private int shownLimit = PAGE_SIZE;
	/** How many times the history rows were built. */
	private int builds;

	HistoryListSection(LedgerHistoryModel model, BiConsumer<Long, String> deleteRecord, RecordEdit editNote,
		RecordEdit editLocation, SetupEdit editSetup, Component dialogParent, Runnable relayout, SidebarIcons icons)
	{
		this.model = model;
		this.deleteRecord = deleteRecord;
		this.editNote = editNote;
		this.editLocation = editLocation;
		this.editSetup = editSetup;
		this.dialogParent = dialogParent;
		this.relayout = relayout;
		this.icons = icons;
		icons.getSetup().addListener(this::tagImageArrived, list::repaint);
	}

	/** Adds the header, the filters, the hints, the error line and the (empty) list to {@code content}. */
	void addTo(JPanel content)
	{
		// A flat section header (DESIGN_PRINCIPLES.md 3.3), counting the filters set.
		JPanel header = new JPanel(new BorderLayout(GAP, 0));
		header.setName("history.header");
		titleLabel.setName("history.title");
		LedgerTheme.styleSectionHeader(header, titleLabel, null);
		header.add(titleLabel, BorderLayout.WEST);
		SlayerLedgerPanel.addRow(content, header);

		// One labelled row per filter, the labels in one column; the setup filters behind the toggle.
		JPanel filters = new JPanel(new GridBagLayout());
		filters.setName("history.filters");
		filters.setBackground(LedgerTheme.PAGE);
		int row = 0;
		monsterFilter.addTo(filters, "Monster", row++);
		locationFilter.addTo(filters, "Location", row++);
		masterFilter.addTo(filters, "Master", row++);
		taskTypeFilter.addTo(filters, "Task type", row++);
		moreToggle.setName("history.moreFilters");
		styleLink(moreToggle, LedgerTheme.LABEL);
		Font underlined = LedgerTheme.smallFont().deriveFont(Collections.singletonMap(TextAttribute.UNDERLINE,
			TextAttribute.UNDERLINE_ON));
		moreToggle.setFont(underlined);
		moreToggle.addActionListener(e -> setMoreOpen(!moreOpen));
		// Clear filters beside the toggle, under the filters it clears, while a filter is set: beside the header's
		// "Task history \u00b7 2 filters" (Bold, 148 px) it would not fit the sidebar's 213 px.
		clearButton.setName("history.clearFilters");
		styleLink(clearButton, LedgerTheme.LABEL);
		clearButton.setFont(underlined);
		clearButton.setToolTipText("Show every task: set each filter back to All or Any");
