		emptyBlock.setLayout(new BoxLayout(emptyBlock, BoxLayout.Y_AXIS));
		emptyBlock.setOpaque(false);
		emptyBlock.setBorder(BorderFactory.createEmptyBorder(6, ROW_PADDING, 6, ROW_PADDING));
		emptyBlock.setAlignmentX(Component.LEFT_ALIGNMENT);
		emptyLabel.setName("history.empty");
		emptyLabel.setForeground(LedgerTheme.LABEL);
		emptyLabel.setFont(LedgerTheme.smallFont());
		emptyLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		emptyBlock.add(emptyLabel);
		emptyClearButton.setName("history.empty.clear");
		styleLink(emptyClearButton, LedgerTheme.LABEL);
		emptyClearButton.setFont(moreToggle.getFont());
		emptyClearButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		emptyClearButton.addActionListener(e -> clearFilters());
		emptyBlock.add(emptyClearButton);
		showMoreButton.setName("history.showMore");
		showMoreButton.setFocusable(false);
		showMoreButton.setAlignmentX(Component.LEFT_ALIGNMENT);
		SlayerLedgerPanel.styleTextButton(showMoreButton);
		showMoreButton.addActionListener(e ->
		{
			if (model.isWaitingForCurrentPrices())
			{
				// The rows stay until today's prices arrive; a click now would not show, so clicks don't pile up.
				return;
			}
			shownLimit += PAGE_SIZE;
			rebuild();
		});
		SlayerLedgerPanel.addRow(content, list);
	}

	/** Forgets the selection and open rows of another account's history; the setup filters' toggle stays. */
	void forgetOtherAccount()
	{
		if (model.account() != shownAccount)
		{
			shownAccount = model.account();
			monsterFilter.selection = null;
			locationFilter.selection = null;
			masterFilter.selection = null;
			resetFixedFilters();
			shownLimit = PAGE_SIZE;
			expandedRecords.clear();
			listsShowingAll.clear();
			updateHeader();
		}
	}

	/**
	 * Shows a non-modal error above the history list (for example a failed delete) until the next successful refresh
	 * or the next delete. Ignored if {@code account}'s history is no longer shown.
	 */
	void showError(long account, String message)
	{
		if (account != model.account())
		{
			return;
		}
		errorLabel.setText("<html>" + LedgerHistory.escapeHtml(message) + "</html>");
		errorLabel.setVisible(true);
		relayout.run();
	}

	void clearError()
	{
		if (errorLabel.isVisible())
		{
			errorLabel.setVisible(false);
			relayout.run();
		}
	}

	/**
	 * Rebuilds the filters' choices from the records (and the region names known), keeping each selection while its
	 * value remains. Without records (logged out, loading, a load failure, none saved) every filter goes back to All or
	 * Any, so the header never counts filters over an empty list. Region names not known yet are asked for; their
	 * records' locations follow once they arrive ({@link #locationNamesChanged}).
	 */
	void rebuildFilter()
	{
		List<LedgerRecord> records = model.records();
		model.requestLocationNames(unnamedRegions(records));
		boolean changed = monsterFilter.setOptions(LedgerHistory.filterOptions(records), LedgerHistory::keepSelection);
		// The labels first: the box shows the choices by them.
		locationChoices = HistoryFilter.locationChoices(records, model.spots(), model::locationName);
		changed |= locationFilter.setOptions(locationChoices.getOptions(), HistoryFilter::keepLocation);
		changed |= masterFilter.setOptions(HistoryFilter.masterOptions(records), LedgerHistory::keepSelection);
		boolean any = !records.isEmpty();
		if (!any)
		{
			// The fixed choices stay, but there is nothing for them to filter.
			changed |= resetFixedFilters();
		}
		if (changed)
		{
			// A selected value is gone: "All" or "Any", from its first page.
			shownLimit = PAGE_SIZE;
		}
		for (JComboBox<?> box : Arrays.asList(monsterFilter.box, locationFilter.box, masterFilter.box,
			taskTypeFilter.box, cannonFilter.box, styleFilter.box, gearFilter.box))
		{
			box.setEnabled(any);
		}
		updateHeader();
	}

	/**
	 * Region names arrived (one changed) or were forgotten: records' locations may differ, so the Location filter's
	 * choices are rebuilt, then the rows.
	 */
	void locationNamesChanged()
	{
		rebuildFilter();
		if (!model.records().isEmpty())
		{
			rebuild();
		}
	}

	/** The regions of the records without a location name of their own: they show their region's name, if any. */
	private static Set<Integer> unnamedRegions(List<LedgerRecord> records)
	{
		Set<Integer> regions = new HashSet<>();
		for (LedgerRecord record : records)
		{
			if (record.getLocation() == null && record.getLocationRegion() != null)
			{
				regions.add(record.getLocationRegion());
			}
		}
		return regions;
	}

	/** The filters as selected now. */
	private HistoryFilter selectedFilter()
	{
		return new HistoryFilter(monsterFilter.selection, locationFilter.selection, masterFilter.selection)
			.withTaskType(taskTypeFilter.selection).withCannon(cannonFilter.selection)
			.withStyle(styleFilter.selection).withGear(gearFilter.selection);
	}

	/** The setup filters behind {@link #moreToggle}: Cannon, Style and Gear. */
	private List<SetupFilter<?>> setupFilters()
	{
		return Arrays.asList(cannonFilter, styleFilter, gearFilter);
	}

	/**
	 * Sets the filters with fixed choices (Task type and the setup filters) back to Any, without their change events;
	 * returns whether any was set.
	 */
	private boolean resetFixedFilters()
	{
		boolean wasSet = false;
		for (SetupFilter<?> filter : Arrays.asList(taskTypeFilter, cannonFilter, styleFilter, gearFilter))
		{
			wasSet |= filter.selection != null;
			filter.reset();
		}
		return wasSet;
	}

	/** How many filters are set (not All or Any). */
	private int filtersSet()
	{
		int set = 0;
		for (Object selection : Arrays.asList(monsterFilter.selection, locationFilter.selection,
			masterFilter.selection, taskTypeFilter.selection, cannonFilter.selection, styleFilter.selection,
			gearFilter.selection))
		{
			if (selection != null)
			{
				set++;
			}
		}
		return set;
	}

	/** {@link #TITLE}, with {@code \u00b7 2 filters} while filters are set (DESIGN_PRINCIPLES.md 3.7). */
	static String headerText(int filtersSet)
	{
		return filtersSet <= 0 ? TITLE
			: TITLE + SEPARATOR + filtersSet + (filtersSet == 1 ? " filter" : " filters");
	}

	/** Shows how many filters are set in the header, with {@link #CLEAR_FILTERS} while any is. */
	private void updateHeader()
	{
		int set = filtersSet();
		titleLabel.setText(headerText(set));
		if (clearButton.isVisible() != set > 0)
		{
			clearButton.setVisible(set > 0);
			relayout.run();
		}
		showMoreFilters();
	}

	/** A filter's choice changed: the header, then the rows. */
	private void filtersChanged()
	{
		updateHeader();
		rebuild();
	}

	/** Sets every filter back to All or Any, from the first page, as {@link #CLEAR_FILTERS} does. */
	void clearFilters()
	{
		if (filtersSet() == 0)
		{
			return;
		}
		monsterFilter.select(null);
		locationFilter.select(null);
		masterFilter.select(null);
		resetFixedFilters();
		shownLimit = PAGE_SIZE;
		filtersChanged();
	}

	/** Opens or closes the setup filters, as {@link #moreToggle} does. */
	private void setMoreOpen(boolean open)
	{
		if (moreOpen != open)
		{
			moreOpen = open;
			showMoreFilters();
			relayout.run();
		}
	}

	/** Shows the setup filters while {@link #moreOpen}, and the toggle's text: how many are set while hidden. */
	private void showMoreFilters()
	{
		int hiddenSet = 0;
		for (SetupFilter<?> filter : setupFilters())
		{
			filter.setShown(moreOpen);
			if (filter.selection != null)
			{
				hiddenSet++;
			}
		}
		moreToggle.setText(moreOpen ? HIDE_MORE_FILTERS
			: hiddenSet > 0 ? MORE_FILTERS + " (" + hiddenSet + " set)" : MORE_FILTERS);
	}

	/**
	 * Rebuilds the first {@link #shownLimit} rows of the filtered records and the "Show N more" button below them, or
	 * shows why there are none ({@link #emptyMessage}, or {@link #NO_MATCHES} when the filters together match no task);
	 * while prices are awaited the rows stay. Region names are asked for every record, as the Location filter needs
	 * them.
	 */
	void rebuild()
	{
		if (model.records().isEmpty())
		{
			showEmpty(emptyMessage(), false);
			return;
		}
		if (model.isWaitingForCurrentPrices())
		{
			// The rows shown stay until the prices asked for arrive; the model then has them rebuilt (PRICED_VIEWS).
			return;
		}
		builds++;
		clearRows();
		ZoneId zone = ZoneId.systemDefault();
		RowFormat format = new RowFormat(LedgerHistory.shortDate(zone), LedgerHistory.shortDateTime(zone));
		Map<Integer, Long> prices = model.shownPrices();
		Set<Integer> names = new HashSet<>();
		List<LedgerRecord> filtered = selectedFilter().apply(model.records(), model.spots(), model::locationName);
		model.requestLocationNames(unnamedRegions(model.records()));
		if (filtered.isEmpty())
		{
			showEmpty(NO_MATCHES, true);
			return;
		}
		int shown = Math.min(shownLimit, filtered.size());
		for (LedgerRecord record : filtered.subList(0, shown))
		{
			HistoryPricing.Values values = HistoryPricing.value(record, model.lootPriceMode(), prices,
				model.hiddenLoot());
			JPanel row = row(model.account(), record, values, format, list.getComponentCount() == 0);
			row.setAlignmentX(Component.LEFT_ALIGNMENT);
			list.add(row);
			String key = recordKey(record);
			if (expandedRecords.contains(key))
			{
				JPanel details = details(record, values, prices, names);
				details.setAlignmentX(Component.LEFT_ALIGNMENT);
				list.add(details);
			}
		}
		int left = filtered.size() - shown;
		if (left > 0)
		{
			showMoreButton.setText("Show " + Math.min(PAGE_SIZE, left) + " more");
			showMoreButton.setToolTipText("Showing " + shown + " of " + filtered.size() + " tasks");
			list.add(Box.createVerticalStrut(GAP));
			list.add(showMoreButton);
		}
		model.requestItemNames(names);
		list.revalidate();
		list.repaint();
	}

	/** Rebuilds the rows once item names arrive, while any row's item details are open. */
	void itemNamesChanged()
	{
		if (!expandedRecords.isEmpty() && !model.records().isEmpty())
		{
			rebuild();
		}
	}

	/**
	 * What the list shows without records: the model's message when it has one (logged out, loading, a load failure),
	 * so a redraw (another Loot price, for example) never replaces it; {@link SlayerLedgerPanel#LOGGED_OUT_MESSAGE}
	 * before any history was shown; {@link #NO_HISTORY} for an account with no saved task.
	 */
	private String emptyMessage()
	{
		String message = model.historyMessage();
		if (message != null)
		{
			return message;
		}
		return model.isLoaded() ? NO_HISTORY : SlayerLedgerPanel.LOGGED_OUT_MESSAGE;
	}

	/** Clears the rows and shows {@code message} instead, with {@link #CLEAR_FILTERS} under it when {@code clear}. */
	private void showEmpty(String message, boolean clear)
	{
		clearRows();
		// HTML, so the sentence wraps in the narrow sidebar.
		emptyLabel.setText("<html>" + LedgerHistory.escapeHtml(message) + "</html>");
		emptyClearButton.setVisible(clear);
		list.add(emptyBlock);
		list.revalidate();
		list.repaint();
	}

	private void clearRows()
	{
		list.removeAll();
		waitingTags.clear();
	}

	/** A setup tag's image arrived: drawn on the shown rows' icons that wait for it. */
	private void tagImageArrived(SetupTagIcons.Icon image)
	{
		List<JLabel> waiting = waitingTags.remove(image);
		if (waiting != null)
		{
			for (JLabel label : waiting)
			{
				SmallItemIcon.applyTag(icons.getSetup(), label, image);
			}
		}
	}

	/** Identifies a record across reloads: its id, or its times for a record without one. */
	static String recordKey(LedgerRecord record)
	{
		return record.getId() != null ? "id:" + record.getId()
			: "t:" + record.getStartedAt() + ":" + record.getEndedAt();
	}

	/** Opens or closes the item details below a saved task, as a click on its row does. */
	private void toggleDetails(LedgerRecord record)
	{
		String key = recordKey(record);
		if (!expandedRecords.remove(key))
		{
			expandedRecords.add(key);
		}
		else
		{
			listsShowingAll.removeIf(k -> k.startsWith(key + "|"));
		}
		rebuild();
	}

	/**
	 * The item details below an open history row, in look A: the task's supplies and loot as item icons under
	 * nested sub-headers, quieter than the row's name above them as Overall totals' are ({@link
	 * TitledListView#useNestedSubHeader}; DESIGN_PRINCIPLES.md 3.8), with their values on the right in Small in
	 * {@link LedgerTheme#LABEL}, at the prices its row shows (today's GE prices with the saved high-alchemy values, as
	 * {@link HistoryPricing} values the totals), then its XP; or {@link ItemDetails#NO_ITEM_DETAILS} for a task saved
	 * before items were tracked. Ids whose names are needed are added to {@code names}.
	 */
	private JPanel details(LedgerRecord record, HistoryPricing.Values values, Map<Integer, Long> prices,
		Set<Integer> names)
	{
		JPanel details = new JPanel();
		details.setName("history.details");
		details.setLayout(new BoxLayout(details, BoxLayout.Y_AXIS));
		details.setBackground(LedgerTheme.PAGE);
		details.setBorder(BorderFactory.createEmptyBorder(0, ROW_PADDING, 8, ROW_PADDING));
		ItemDetails items = ItemDetails.of(record);
		if (items == null)
		{
			details.add(detailsLabel(ItemDetails.NO_ITEM_DETAILS));
			addXp(details, record);
			return details;
		}
		items = items.withGePrices(prices);
		details.add(detailsLabel(SlayerLedgerPanel.ITEMS_AT_CURRENT_PRICES));
		String tooltip = LedgerHistory.valuesTooltip(values);
		ItemGridView supplies = new ItemGridView("Supplies used", false, LedgerTheme.PAGE, icons.getItems());
		supplies.useNestedSubHeader();
		// One cell per potion, though a record may hold one under two dose variants.
		supplies.setRows(items.supplyGridRows(model::itemName));
		supplies.setHeaderValue(LedgerFormat.amount(values.getSuppliesGe(), values.isSuppliesApproximate()),
			LedgerTheme.LABEL, tooltip);
		ItemGridView loot = new ItemGridView("Loot received", false, LedgerTheme.PAGE, icons.getItems());
		loot.useNestedSubHeader();
		// Without the items Ground Items hides, as the loot value leaves them out.
		loot.setRows(items.withNatureRunePrice(model.natureRunePrice()).lootRows(model.lootPriceMode(),
			model::itemName), model.hiddenLoot());
		loot.setHeaderValue(LedgerFormat.amount(values.getLootValue(), values.isLootApproximate()), LedgerTheme.LABEL,
			tooltip);
		addDetailsList(details, supplies);
		addDetailsList(details, loot);
		names.addAll(items.itemIds());
		addXp(details, record);
		return details;
	}

	/**
	 * Adds a saved task's XP, skill by skill with XP per hour of its active time, below its items, under a nested
	 * sub-header like the item grids' with the task's XP per hour on the right; nothing for a task with no XP (or saved
	 * before XP was tracked).
	 */
	private void addXp(JPanel details, LedgerRecord record)
	{
		List<SkillXp.Row> rows = SkillXp.rows(record.getXpGained(), record.getActiveMillis());
		if (rows.isEmpty())
		{
			return;
		}
		ItemListView xp = new ItemListView(SkillXp.LIST_TITLE, false, LedgerTheme.PAGE, SkillXp.LIST_NOUN,
			icons.getSkills());
		xp.useNestedSubHeader();
		xp.setRows(rows);
		Long rate = SkillXp.perHour(SkillXp.total(record.getXpGained()), record.getActiveMillis());
		xp.setHeaderValue(rate == null ? "" : LedgerFormat.amount(rate) + "/h", LedgerTheme.LABEL,
			rate == null ? null : "XP per hour of active time");
		// Keeps whether the list shows all its skills ("+N more") across rebuilds.
		String listKey = recordKey(record) + "|" + SkillXp.LIST_TITLE;
		xp.setShowAll(listsShowingAll.contains(listKey), shown ->
		{
			if (shown)
			{
				listsShowingAll.add(listKey);
			}
			else
			{
				listsShowingAll.remove(listKey);
			}
		});
		addDetailsList(details, xp);
	}

	/** Adds one list (item icons or XP) to a row's details. */
	private static void addDetailsList(JPanel details, TitledListView<?> itemList)
	{
		itemList.setOpaque(false);
		itemList.setAlignmentX(Component.LEFT_ALIGNMENT);
		itemList.setBorder(BorderFactory.createEmptyBorder(GAP, 0, 0, 0));
		details.add(itemList);
	}

	private static JLabel detailsLabel(String text)
	{
		JLabel label = LedgerTheme.label(text, LedgerTheme.smallFont(), LedgerTheme.HINT);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	/** The two date formats of a rebuild: the rows' dates and the tooltips' dates with times. */
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class RowFormat
	{
		private final DateTimeFormatter date;
		private final DateTimeFormatter dateTime;
	}

	/**
	 * A saved task's row: two lines on the page ({@link RowPanel}), its tooltip built when first asked for, a left
	 * click opening its details and a right click its edit menu.
	 */
	private JPanel row(long account, LedgerRecord record, HistoryPricing.Values values, RowFormat format,
		boolean first)
	{
		// Exact values, which prices are shown, the full name, date and time, kills, XP, location and counts: built
		// when first asked for.
		RowPanel row = new RowPanel(() -> LedgerHistory.historyRowTooltip(record, values, recordLocation(record),
			LedgerHistory.formatEndedAt(record, format.dateTime)));
		row.setName("history.row");
		row.setBackground(LedgerTheme.PAGE);
		// A 1 px rule between rows (DESIGN_PRINCIPLES.md 3.3), drawn over the hover background too.
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(first ? 0 : 1, 0, 0, 0, LedgerTheme.BEVEL_INNER),
			BorderFactory.createEmptyBorder(ROW_PADDING, ROW_PADDING, ROW_PADDING, ROW_PADDING)));

		row.name.setText(LedgerHistory.monster(record));
		SmallItemIcon.applyTask(icons.getItems(), row.name, record.getMonster());
		row.duration.setText(LedgerFormat.duration(record.getActiveMillis()));
		if (!record.isCompleted())
		{
			row.addStatus(LedgerHistory.PARTIAL);
		}
		row.when.setText(secondLine(LedgerHistory.formatEndedAt(record, format.date),
			TaskLocation.shortName(record, model::locationName, model.spots())));
		Long profit = values.getProfit();
		row.profit.setText(LedgerFormat.signed(profit, values.isProfitApproximate()));
		row.profit.setForeground(profit == null || profit == 0 ? LedgerTheme.VALUE
			: profit > 0 ? LedgerTheme.GOOD : LedgerTheme.ALERT);

		row.addMouseListener(rowMouse(row, record));
		for (SetupTagIcons.Tag tag : SetupTagIcons.tags(SetupTags.of(record)))
		{
			JLabel icon = row.addTag(tag);
			// The game image, as the overlay and the live card's toggles show it; a sprite arrives later.
			if (!SmallItemIcon.applyTag(icons.getSetup(), icon, tag.getIcon()))
			{
				waitingTags.computeIfAbsent(tag.getIcon(), image -> new ArrayList<>()).add(icon);
			}
		}
		row.setComponentPopupMenu(menu(account, record));
		return row;
	}

	/**
	 * The second line's text: the date, then the location after {@link #SEPARATOR} when one is known; the location
	 * alone without a date.
	 */
	static String secondLine(String date, String location)
	{
		boolean dated = date != null && !LedgerHistory.NO_VALUE.equals(date);
		if (location == null)
		{
			return dated ? date : LedgerHistory.NO_VALUE;
		}
		return dated ? date + SEPARATOR + location : location;
	}

	/**
	 * A row's mouse: a single left click opens or closes the task's items (once per double click; a right click opens
	 * the menu), and the hover background shows from when the mouse enters the row until it leaves it. No part of the
	 * row listens to the mouse, its tag icons included ({@link RowPanel#getToolTipText(MouseEvent)} serves their
	 * tooltips), so moving over them is no exit; any exit clears the hover, also one at a point still inside the row,
	 * as when the right-click menu or a dialog takes the mouse.
	 */
	private MouseAdapter rowMouse(JPanel row, LedgerRecord record)
	{
		return new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 1)
				{
					toggleDetails(record);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				row.setBackground(LedgerTheme.HOVER);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				row.setBackground(LedgerTheme.PAGE);
			}
		};
	}

	/** A row's right-click menu, as in core LootTrackerBox: the note, the location, the setup and delete. */
	private JPopupMenu menu(long account, LedgerRecord record)
	{
		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new EmptyBorder(5, 5, 5, 5));
		JMenuItem editNoteItem = new JMenuItem("Edit note");
		// LedgerStore.updateNote matches by id, like delete.
		editNoteItem.setEnabled(record.getId() != null);
		editNoteItem.addActionListener(e -> promptEditNote(account, record));
		menu.add(editNoteItem);
		JMenuItem editLocationItem = new JMenuItem("Edit location");
		// LedgerStore.updateLocation matches by id, like the note.
		editLocationItem.setEnabled(record.getId() != null);
		editLocationItem.addActionListener(e -> promptEditLocation(account, record));
		menu.add(editLocationItem);
		Integer unlisted = SlayerSpots.keyRegion(model.spots().recordSpot(record));
		if (unlisted != null)
		{
			// A region the spot table doesn't list is a place of its own, which the player names.
			JMenuItem renamePlaceItem = new JMenuItem(RENAME_PLACE_MENU_ITEM);
			renamePlaceItem.addActionListener(e -> promptRenamePlace(unlisted));
			menu.add(renamePlaceItem);
		}
		JMenuItem editSetupItem = new JMenuItem(SETUP_MENU_ITEM);
		// LedgerStore.updateSetup matches by id, like the note.
		editSetupItem.setEnabled(record.getId() != null);
		editSetupItem.addActionListener(e -> promptEditSetup(account, record));
		menu.add(editSetupItem);
		JMenuItem delete = new JMenuItem("Delete task");
		// LedgerStore.delete matches by id; a record without one cannot be targeted safely.
		delete.setEnabled(record.getId() != null);
		delete.addActionListener(e -> confirmDelete(account, record));
		menu.add(delete);
		return menu;
	}

	/** Asks before deleting a saved record; Cancel or closing the dialog does nothing. */
	private void confirmDelete(long account, LedgerRecord record)
	{
		String[] options = {"Delete", "Cancel"};
		int choice = JOptionPane.showOptionDialog(dialogParent, LedgerHistory.deleteConfirmation(record),
			"Slayer Ledger", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE, null, options, options[1]);
		if (choice != 0 || record.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		clearError();
		deleteRecord.accept(account, record.getId());
	}

	/** Asks for a saved record's new note; Cancel or closing the dialog changes nothing, an empty note removes it. */
	private void promptEditNote(long account, LedgerRecord record)
	{
		Object input = JOptionPane.showInputDialog(dialogParent, LedgerHistory.editNotePrompt(record), "Slayer Ledger",
			JOptionPane.PLAIN_MESSAGE, null, null, record.getNote() == null ? "" : record.getNote());
		if (input == null || record.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		String note = TaskNote.normalize(input.toString());
		if (Objects.equals(note, record.getNote()))
		{
			return;
		}
		clearError();
		editNote.apply(account, record.getId(), note);
	}

	/**
	 * Asks for a saved record's own location name, starting from the one shown; Cancel or closing the dialog changes
	 * nothing, an empty name removes the record's own name (it then shows its spot's name, or "Unknown"), and the name
	 * already shown is not saved as its own. The record keeps its spot.
	 */
	private void promptEditLocation(long account, LedgerRecord record)
	{
		String shown = recordLocation(record);
		Object input = JOptionPane.showInputDialog(dialogParent, TaskLocation.editPrompt(record), "Slayer Ledger",
			JOptionPane.PLAIN_MESSAGE, null, null, TaskLocation.UNKNOWN.equals(shown) ? "" : shown);
		if (input == null || record.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		String location = TaskLocation.normalizeName(input.toString());
		if (Objects.equals(location, record.getLocation())
			|| (record.getLocation() == null && Objects.equals(location, shown)))
		{
			// Unchanged; a name it shows from its spot stays its spot's, so it follows a later rename.
			return;
		}
		clearError();
		editLocation.apply(account, record.getId(), location);
	}

	/**
	 * Asks for the name of {@code region}, a region the spot table doesn't list, for every task there, starting
	 * from its name now; Cancel, closing the dialog, an empty name or the same name change nothing.
	 */
	private void promptRenamePlace(int region)
	{
		String current = model.locationName(region);
		Object input = JOptionPane.showInputDialog(dialogParent, TaskLocation.renamePrompt(region), "Slayer Ledger",
			JOptionPane.PLAIN_MESSAGE, null, null, current == null ? "" : current);
		if (input == null)
		{
			return;
		}
		String name = TaskLocation.normalizeName(input.toString());
		if (name == null || name.equals(current))
		{
			return;
		}
		clearError();
		renamePlace.test(region, name);
	}

	/**
	 * Asks for a saved record's setup overrides: one choice per tag, cannon, style and gear, whose first choice
	 * clears the override and shows the detected value. Cancel or closing the dialog changes nothing; OK saves the
	 * choices when they differ from the record's overrides.
	 */
	private void promptEditSetup(long account, LedgerRecord record)
	{
		final SetupTags tags = SetupTags.of(record);
		final SetupOverrides current = tags.getOverrides();
		final JComboBox<SetupChoices.Choice<Boolean>> cannon = setupBox("history.setup.cannon",
			SetupChoices.cannon(tags), current.getCannon());
		final JComboBox<SetupChoices.Choice<SetupStyle>> style = setupBox("history.setup.style",
			SetupChoices.style(tags), current.getStyle());
		final JComboBox<SetupChoices.Choice<GearFocus>> gear = setupBox("history.setup.gear",
			SetupChoices.gear(tags), current.getGear());

		JPanel form = new JPanel(new GridBagLayout());
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = 0;
		c.gridwidth = 2;
		c.anchor = GridBagConstraints.WEST;
		c.insets = new Insets(0, 0, 6, 0);
		form.add(new JLabel(SetupChoices.prompt(record)), c);
		c.gridwidth = 1;
		c.insets = new Insets(2, 0, 2, 6);
		addSetupRow(form, c, "Cannon", cannon);
		addSetupRow(form, c, "Style", style);
		addSetupRow(form, c, "Gear", gear);

		int answer = JOptionPane.showConfirmDialog(dialogParent, form, "Slayer Ledger", JOptionPane.OK_CANCEL_OPTION,
			JOptionPane.PLAIN_MESSAGE);
		if (answer != JOptionPane.OK_OPTION || record.getId() == null || account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		final SetupOverrides chosen = SetupOverrides.of(chosen(cannon), chosen(style), chosen(gear));
		if (chosen.equals(current))
		{
			return;
		}
		clearError();
		editSetup.apply(account, record.getId(), chosen);
	}

	private static <T> JComboBox<SetupChoices.Choice<T>> setupBox(String name, List<SetupChoices.Choice<T>> choices,
		T override)
	{
		final DefaultComboBoxModel<SetupChoices.Choice<T>> boxModel = new DefaultComboBoxModel<>();
		for (SetupChoices.Choice<T> choice : choices)
		{
			boxModel.addElement(choice);
		}
		final JComboBox<SetupChoices.Choice<T>> box = new JComboBox<>(boxModel);
		box.setName(name);
		box.setSelectedIndex(SetupChoices.indexOf(choices, override));
		return box;
	}

	private static void addSetupRow(JPanel form, GridBagConstraints c, String label, JComboBox<?> box)
	{
		c.gridy++;
		c.gridx = 0;
		c.weightx = 0;
		c.fill = GridBagConstraints.NONE;
		form.add(new JLabel(label), c);
		c.gridx = 1;
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		form.add(box, c);
	}

	/** The override a setup box's selected choice sets, or {@code null} to clear it. */
	private static <T> T chosen(JComboBox<SetupChoices.Choice<T>> box)
	{
		final int index = box.getSelectedIndex();
		return index < 0 ? null : box.getItemAt(index).getValue();
	}

	/** A saved record's location as the history shows it ({@link TaskLocation#displayName}). */
	private String recordLocation(LedgerRecord record)
	{
		return TaskLocation.displayName(record, model::locationName, model.spots());
	}

	/**
	 * Styles {@code button} as a text link of the page: Small text in {@code color}, no frame or fill, a hand cursor,
	 * and still focusable, so the keyboard reaches it (Space presses it).
	 */
	private static void styleLink(JButton button, Color color)
	{
		button.setFont(LedgerTheme.smallFont());
		button.setForeground(color);
		button.setContentAreaFilled(false);
		button.setOpaque(false);
		button.setFocusPainted(false);
		button.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	/** Adds a filter's label and box as row {@code row} of {@code filters} (a {@link GridBagLayout}). */
	private static JLabel addFilterRow(JPanel filters, String label, JComboBox<String> box, int row)
	{
		JLabel text = LedgerTheme.label(label, LedgerTheme.smallFont(), LedgerTheme.LABEL);
		int top = row == 0 ? 0 : 4;
		GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = row;
		c.anchor = GridBagConstraints.WEST;
		c.insets = new Insets(top, 0, 0, GAP);
		filters.add(text, c);
		c.gridx = 1;
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		c.insets = new Insets(top, 0, 0, 0);
		filters.add(box, c);
		return text;
	}

	/** A filter box in look A: the stone of a card behind RuneLite's own drawing, sized from a short name. */
	private static void styleFilterBox(JComboBox<String> box, String name)
	{
		box.setName(name);
		box.setFocusable(false);
		box.setBackground(LedgerTheme.CARD);
		box.setForeground(LedgerTheme.VALUE);
		// Sized from a short name, not the longest choice, so a long one never widens the sidebar.
		box.setPrototypeDisplayValue(FILTER_PROTOTYPE);
	}

	/**
	 * One filter's labelled drop-down and its selection: Monster, Location or Master, whose choices are the
	 * values in the records. Sized from a short prototype, so a long name never widens the sidebar: it is cut short in
	 * the closed box, whose tooltip names the selected value in full, while the open list widens to fit it
	 * ({@link ComboPopupWidener}). Choices show as its labeler names them.
	 */
	private final class FilterChoice
	{
		private final JComboBox<String> box = new JComboBox<>();
		/** What the filter does: the start of the box's tooltip. */
		private final String description;
		/** The choices shown, {@link LedgerHistory#ALL} first. */
		private List<String> options = Collections.singletonList(LedgerHistory.ALL);
		/** Selected value, or {@code null} for "All". */
		private String selection;
		/** How a choice is shown ("No location" is not a real name; a Location choice is a spot key). */
		private final Function<String, String> labeler;
		/** True while the box's model is being rebuilt, so its change events are ignored. */
		private boolean updating;

		@SuppressWarnings("unchecked")
		private FilterChoice(String name, String description, Function<String, String> labeler)
		{
			this.description = description;
			this.labeler = labeler;
			styleFilterBox(box, name);
			// The look and feel's renderer, given each choice's label ("No location" is not a real name; a
			// Location choice is a spot key).
			ListCellRenderer<Object> renderer = (ListCellRenderer<Object>) box.getRenderer();
			box.setRenderer((JList<? extends String> list, String value, int index, boolean selected, boolean focus) ->
				renderer.getListCellRendererComponent(list, value == null ? null : labeler.apply(value), index,
					selected, focus));
			ComboPopupWidener.install(box, ComboPopupWidener.MAX_WIDTH);
			box.setModel(new DefaultComboBoxModel<>(options.toArray(new String[0])));
			updateTooltip();
			box.addActionListener(e ->
			{
				if (updating)
				{
					return;
				}
				int index = box.getSelectedIndex();
				String chosen = index <= 0 ? null : box.getItemAt(index);
				if (!Objects.equals(chosen, selection))
				{
					// Another value: back to the first page.
					shownLimit = PAGE_SIZE;
				}
				selection = chosen;
				updateTooltip();
				filtersChanged();
			});
		}

		/** Adds the label and the box as row {@code row} of {@code filters} (a {@link GridBagLayout}). */
		private void addTo(JPanel filters, String label, int row)
		{
			addFilterRow(filters, label, box, row);
		}

		/** Selects {@code value} ({@code null}: "All") without its change event, as Clear filters does. */
		private void select(String value)
		{
			selection = value;
			updating = true;
			try
			{
				box.setSelectedItem(value == null ? LedgerHistory.ALL : value);
			}
			finally
			{
				updating = false;
			}
			updateTooltip();
		}

		/**
		 * Shows {@code newOptions}, keeping the selection as {@code keep} decides ({@code (options, selection)} to the
		 * value kept, {@code null} for "All"). The box's model is replaced only when the choices changed, so an open
		 * list is not disturbed.
		 *
		 * @return whether the selection was dropped (not when only its label changed)
		 */
		private boolean setOptions(List<String> newOptions, BiFunction<List<String>, String, String> keep)
		{
			String kept = keep.apply(newOptions, selection);
			boolean changed = !Objects.equals(kept, selection);
			selection = kept;
			updating = true;
			try
			{
				if (!newOptions.equals(options))
				{
					options = newOptions;
					box.setModel(new DefaultComboBoxModel<>(newOptions.toArray(new String[0])));
				}
				box.setSelectedItem(selection == null ? LedgerHistory.ALL : selection);
			}
			finally
			{
				updating = false;
			}
			// A label may have changed with the same choices.
			box.repaint();
			updateTooltip();
			return changed;
		}

		/** The description, and the selected value in full (the box may cut it short). */
		private void updateTooltip()
		{
			box.setToolTipText(selection == null ? description
				: "<html>" + LedgerHistory.escapeHtml(description) + ":<br>"
				+ LedgerHistory.escapeHtml(labeler.apply(selection)) + "</html>");
		}
	}

	/**
	 * A setup filter's labelled drop-down (V2 plan 5): Task type, Cannon, Style or Gear, with fixed choices
	 * ({@link HistoryFilter#TASK_TYPE_CHOICES} and so on, {@code null} first for "Any"), shown as
	 * {@link HistoryFilter#setupLabel} names them. Setting Cannon, Style or Gear opens the setup filters
	 * ({@link #moreOpen}).
	 *
	 * @param <T> what a choice is
	 */
	private final class SetupFilter<T>
	{
		private final JComboBox<String> box = new JComboBox<>();
		private final List<T> choices;
		/** What the filter does: the start of the box's tooltip. */
		private final String description;
		/** The label beside the box, hidden with it. */
		private JLabel label;
		/** Selected value, or {@code null} for "Any". */
		private T selection;
		/** True while the box is set programmatically, so its change events are ignored. */
		private boolean updating;

		private SetupFilter(String name, String description, List<T> choices)
		{
			this.choices = choices;
			this.description = description;
			styleFilterBox(box, name);
			List<String> labels = new ArrayList<>(choices.size());
			for (T choice : choices)
			{
				labels.add(HistoryFilter.setupLabel(choice));
			}
			box.setModel(new DefaultComboBoxModel<>(labels.toArray(new String[0])));
			updateTooltip();
			box.addActionListener(e ->
			{
				if (updating)
				{
					return;
				}
				int index = box.getSelectedIndex();
				T chosen = index <= 0 ? null : choices.get(index);
				if (Objects.equals(chosen, selection))
				{
					return;
				}
				// Another value: back to the first page.
				shownLimit = PAGE_SIZE;
				selection = chosen;
				updateTooltip();
				if (chosen != null && setupFilters().contains(this))
				{
					setMoreOpen(true);
				}
				filtersChanged();
			});
		}

		/** Adds the label and the box as row {@code row} of {@code filters} (a {@link GridBagLayout}). */
		private void addTo(JPanel filters, String text, int row)
		{
			label = addFilterRow(filters, text, box, row);
		}

		/** Shows or hides the label and the box. */
		private void setShown(boolean shown)
		{
			box.setVisible(shown);
			if (label != null)
			{
				label.setVisible(shown);
			}
		}

		/** Back to "Any", without the change event. */
		private void reset()
		{
			selection = null;
			updating = true;
			try
			{
				box.setSelectedIndex(0);
			}
			finally
			{
				updating = false;
			}
			updateTooltip();
		}

		/** The description, and the selected value. */
		private void updateTooltip()
		{
			box.setToolTipText(selection == null ? description
				: "<html>" + LedgerHistory.escapeHtml(description) + ":<br>"
				+ LedgerHistory.escapeHtml(HistoryFilter.setupLabel(selection)) + "</html>");
		}
	}

	/**
	 * A history row: two lines (DESIGN_PRINCIPLES.md 3.7). The first has the task's icon and name, cut short to leave
	 * room for the active time on the right; the second the status word (partial tasks only), the date and location,
	 * cut short to leave room for the tag icons right after it and the profit on the right. It asks for no width of its
	 * own, so it never widens the sidebar, and builds its tooltip the first time Swing (or a test) asks for it, then
	 * keeps it: the rows are rebuilt whenever what a tooltip shows changes (the records, their pricing, region names).
	 * Over a tag icon its tooltip is the tag's instead ({@link #getToolTipText(MouseEvent)}).
	 */
	private static final class RowPanel extends JPanel
	{
		private final transient Supplier<String> tooltip;
		private String text;
		/** Each tag icon's tooltip ({@link SetupTagIcons.Tag#getTooltip}), by icon. */
		private final Map<Component, String> tagTooltips = new HashMap<>();
		/** The task's icon and name: Plain, value colour. */
		private final FitLabel name = new FitLabel();
		/** The active time: Plain, value colour. */
		private final JLabel duration = new JLabel();
		/** {@link LedgerHistory#PARTIAL} for a partial task, else {@code null}. */
		private JLabel status;
		/** The date and location: Small, label colour. */
		private final FitLabel when = new FitLabel();
		/** The setup tags' icons ({@link SetupTagIcons}), after {@link #when}. */
		private final JPanel tags = new JPanel();
		/** The profit, signed: Plain, coloured by its sign. */
		private final JLabel profit = new JLabel();

		private RowPanel(Supplier<String> tooltip)
		{
			this.tooltip = tooltip;
			setLayout(new RowLayout());
			// What setToolTipText does, without building the text.
			ToolTipManager.sharedInstance().registerComponent(this);
			// Names for tests, which read the parts by them; no visible effect.
			name.setName("history.name");
			duration.setName("history.duration");
			when.setName("history.when");
			tags.setName("history.tags");
			profit.setName("history.profit");
			name.setFont(LedgerTheme.plainFont());
			name.setForeground(LedgerTheme.VALUE);
			duration.setFont(LedgerTheme.plainFont());
			duration.setForeground(LedgerTheme.VALUE);
			when.setFont(LedgerTheme.smallFont());
			when.setForeground(LedgerTheme.LABEL);
			profit.setFont(LedgerTheme.plainFont());
			tags.setOpaque(false);
			tags.setLayout(new BoxLayout(tags, BoxLayout.X_AXIS));
			tags.setInheritsPopupMenu(true);
			for (JComponent part : new JComponent[]{name, duration, when, tags, profit})
			{
				part.setInheritsPopupMenu(true);
				add(part);
			}
		}

		/** Adds the status word before the date: the only status a row names, so it is never colour alone. */
		private void addStatus(String word)
		{
			status = LedgerTheme.label(word, LedgerTheme.smallFont(), LedgerTheme.VALUE);
			status.setName("history.status");
			status.setInheritsPopupMenu(true);
			add(status);
		}

		/**
		 * Adds one setup tag's icon slot and returns it, for its image ({@link SmallItemIcon#applyTag}). The icon has no
		 * tooltip or listener of its own, which would take the mouse from the row (its click, hover and menu): the row
		 * shows the tag's tooltip while the mouse is over it.
		 */
		private JLabel addTag(SetupTagIcons.Tag tag)
		{
			JLabel icon = new JLabel();
			icon.setName("history.tag");
			Dimension size = new Dimension(SmallItemIcon.TAG_SIZE, SmallItemIcon.TAG_SIZE);
			icon.setPreferredSize(size);
			icon.setMinimumSize(size);
			icon.setMaximumSize(size);
			icon.setInheritsPopupMenu(true);
			tagTooltips.put(icon, tag.getTooltip());
			if (tags.getComponentCount() > 0)
			{
				tags.add(Box.createHorizontalStrut(SMALL_GAP));
			}
			tags.add(icon);
			return icon;
		}

		@Override
		public String getToolTipText()
		{
			if (text == null)
			{
				text = tooltip.get();
			}
			return text;
		}

		/** Over a tag icon, the tag's tooltip ({@code Barrage (estimated)}); anywhere else, the row's. */
		@Override
		public String getToolTipText(MouseEvent event)
		{
			if (event != null)
			{
				// The deepest part shown at the point: a tag icon cut off by the line's end is not there.
				String tag = tagTooltips.get(SwingUtilities.getDeepestComponentAt(this, event.getX(), event.getY()));
				if (tag != null)
				{
					return tag;
				}
			}
			return getToolTipText();
		}

		/** Any width the list gives it, its own height. */
		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}

		/** Lays out the two lines; see {@link RowPanel}. */
		private final class RowLayout implements LayoutManager
		{
			@Override
			public void addLayoutComponent(String key, Component component)
			{
			}

			@Override
			public void removeLayoutComponent(Component component)
			{
			}

			/** No width of its own; the two lines' height. */
			@Override
			public Dimension preferredLayoutSize(Container parent)
			{
				Insets insets = parent.getInsets();
				return new Dimension(insets.left + insets.right,
					insets.top + firstHeight() + SMALL_GAP + secondHeight() + insets.bottom);
			}

			@Override
			public Dimension minimumLayoutSize(Container parent)
			{
				return preferredLayoutSize(parent);
			}

			@Override
			public void layoutContainer(Container parent)
			{
				Insets insets = parent.getInsets();
				int left = insets.left;
				int right = parent.getWidth() - insets.right;
				int y = insets.top;

				int first = firstHeight();
				int durationX = place(duration, right - duration.getPreferredSize().width, y, first, Integer.MAX_VALUE);
				place(name, left, y, first, Math.max(0, durationX - GAP - left));

				y += first + SMALL_GAP;
				int second = secondHeight();
				int profitX = place(profit, right - profit.getPreferredSize().width, y, second, Integer.MAX_VALUE);
				int end = profitX - GAP;
				int x = left;
				if (status != null)
				{
					int statusWidth = Math.min(status.getPreferredSize().width, Math.max(0, end - x));
					place(status, x, y, second, statusWidth);
					x += statusWidth + SMALL_GAP;
				}
				int tagsWidth = tags.getComponentCount() == 0 ? 0 : tags.getPreferredSize().width;
				int room = end - x - (tagsWidth > 0 ? tagsWidth + SMALL_GAP : 0);
				int textWidth = Math.max(0, Math.min(naturalWidth(when), room));
				place(when, x, y, second, textWidth);
				x += textWidth + (textWidth > 0 ? SMALL_GAP : 0);
				place(tags, x, y, second, Math.max(0, Math.min(tagsWidth, end - x)));
			}

			/**
			 * Puts {@code part} at {@code x} on the line at {@code y} of {@code height}, centred, at most {@code width}
			 * wide (its preferred width otherwise); returns {@code x}.
			 */
			private int place(Component part, int x, int y, int height, int width)
			{
				Dimension size = part.getPreferredSize();
				int partHeight = Math.min(height, size.height);
				int partWidth = width == Integer.MAX_VALUE ? size.width : width;
				part.setBounds(x, y + (height - partHeight) / 2, partWidth, partHeight);
				return x;
			}

			private int firstHeight()
			{
				return Math.max(name.getPreferredSize().height, duration.getPreferredSize().height);
			}

			private int secondHeight()
			{
				int height = Math.max(when.getPreferredSize().height, profit.getPreferredSize().height);
				height = Math.max(height, tags.getComponentCount() == 0 ? 0 : SmallItemIcon.TAG_SIZE);
				return status == null ? height : Math.max(height, status.getPreferredSize().height);
			}
		}

		/** The width {@code label}'s whole text takes in its font: what a {@link FitLabel} needs not to cut it. */
		private static int naturalWidth(FitLabel label)
		{
			FontMetrics metrics = label.getFontMetrics(label.getFont());
			Insets insets = label.getInsets();
			return metrics.stringWidth(label.getFullText()) + insets.left + insets.right;
		}
	}

	/** How many times the rows were built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBuildCount()
	{
		return builds;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Pure valuation of a saved {@link LedgerRecord} for the task history, in a {@link LootPriceMode} and at today's GE
 * prices. No RuneLite dependencies; records are never changed.
 *
 * <p>Every saved task the sidebar shows is valued at today's prices (there is no "saved prices" view any more).
 * The prices saved with a task are still read in two places: its high-alchemy values (which never change), and a
 * {@code null} {@code currentGe}, which values a record at the prices saved with it. In the plugin only the
 * task-complete chat line does that, for the record it has just saved: those prices are today's.</p>
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>A record saved before values were tracked ({@link LedgerHistory#isValued}) has no values, whatever the
 *     mode or prices.</li>
 *     <li><b>Today's prices.</b> The loot and supplies GE totals are recomputed from the record's items at
 *     {@code currentGe} (unit GE prices keyed by the id as tallied); items missing from it are unpriced (the total is
 *     marked {@code ~}), and loot items at 0 count at their high-alchemy value ({@link LootPricing}). High-alchemy
 *     values never change, so the record's stored high-alchemy unit values and totals are used. Supplies stay per
 *     dose or bite. This holds for every record with loot or supply items, also one saved without per-item prices
 *     (neither {@code unitGePrices} nor {@code unitHaPrices}): its GE values are recomputed the same way, and its
 *     high-alchemy values are its saved totals (it has no high-alchemy unit values), as {@link ItemDetails} shows
 *     its items. In High alch mode the loot value of a record with loot items but no {@code unitHaPrices} is that
 *     saved total marked {@code ~}, every loot item counting as unpriced, as its item details show them.</li>
 *     <li><b>Tasks saved without items</b> (no loot or supply items, only totals) can't be revalued: at today's
 *     prices they keep their saved totals ({@link Values#isSavedTotals()}), and a non-zero GE total is marked
 *     {@code ~} because it is not at today's prices. Their high-alchemy total is exact, as high-alchemy values never
 *     change. A record without items whose saved GE totals are 0 has nothing to revalue: it is valued at today's
 *     prices (all 0).</li>
 *     <li><b>Saved prices</b> ({@code currentGe} {@code null}). Supplies and high-alchemy totals are the record's
 *     stored totals. A record with unit prices and items has its loot GE value recomputed per item from its
 *     {@code unitGePrices} and {@code unitHaPrices} ({@link LootPricing}), so an item saved with a GE price of 0
 *     counts at its high-alchemy value; the stored {@code lootGeValue} is left as saved. Any other record uses its
 *     stored loot GE total.</li>
 *     <li>Supplies are always valued at GE prices. Profit is the loot value in the mode minus the supplies.</li>
 *     <li><b>Hidden loot</b>. Loot items Ground Items hides ({@link HiddenLoot}), except coins, are left out of
 *     every loot value and of the unpriced counts, as if they had not dropped; the record itself is unchanged.
 *     They can only be left out where loot is valued per item: a record saved without items keeps its stored
 *     totals, and one saved without high-alchemy unit values its stored high-alchemy total, hidden items
 *     included.</li>
 * </ul>
 */
final class HistoryPricing
{
	/** A record's values as shown in the history. Immutable; build one with {@link #builder()}. */
	@Builder
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	@Getter
	static final class Values
	{
		private final LootPriceMode mode;
		/**
		 * Whether the GE values use today's prices: always, but for a {@code null} {@code currentGe} and a record
		 * that can't be revalued ({@link #isSavedTotals()}).
		 */
		private final boolean currentPrices;
		/**
		 * Whether today's prices were asked for but the record kept no loot or supply items to value, only a non-zero
		 * saved GE total, so its saved totals are used instead; a non-zero one is marked approximate ({@code ~}).
		 */
		private final boolean savedTotals;
		/** Loot value in {@link #getMode()}, or {@code null} when not valued. */
		private final Long lootValue;
		/** Loot value in {@link LootPriceMode#GE} ({@link LootPricing}), or {@code null} when not valued. */
		private final Long lootGe;
		private final Long lootHa;
		/** Supplies GE value: 0 for a valued record without supplies, {@code null} when not valued. */
		private final Long suppliesGe;
		private final Long suppliesHa;
		/** Distinct loot items whose price in {@link #getMode()} was unavailable. */
		private final int lootUnpriced;
		/** Distinct loot items whose GE price was unavailable, so {@link #getLootGe()} is approximate. */
		private final int lootGeUnpriced;
		/** Distinct supply items whose GE price was unavailable. */
		private final int suppliesUnpriced;

		/** Whether the record has values at all (it was saved after values were tracked). */
		boolean isValued()
		{
			return lootValue != null;
		}

		/**
		 * Whether {@link #getLootValue()} is approximate (shown with {@code ~}): some item had no price, or it is a
		 * non-zero saved GE total ({@link #isSavedTotals()}; high-alchemy values never change).
		 */
		boolean isLootApproximate()
		{
			return lootUnpriced > 0 || (savedTotals && mode != LootPriceMode.HIGH_ALCH && isNonZero(lootValue));
		}

		/** Whether {@link #getSuppliesGe()} is approximate: some item had no price, or a non-zero saved total. */
		boolean isSuppliesApproximate()
		{
			return suppliesUnpriced > 0 || (savedTotals && isNonZero(suppliesGe));
		}

		private static boolean isNonZero(Long value)
		{
			return value != null && value != 0;
		}

		/** Loot value minus supplies, or {@code null} when not valued. */
		Long getProfit()
		{
			return LedgerHistory.profit(lootValue, suppliesGe);
		}

		/** Whether {@link #getProfit()} is approximate. */
		boolean isProfitApproximate()
		{
			return isLootApproximate() || isSuppliesApproximate();
		}
	}

	private HistoryPricing()
	{
	}

	/**
	 * {@code record}'s values in {@code mode}; see the class rules.
	 *
	 * @param currentGe today's GE unit prices keyed by the id as tallied (an item without an entry has no price), or
	 *                  {@code null} to use the prices saved with the record
	 */
	static Values value(LedgerRecord record, LootPriceMode mode, Map<Integer, Long> currentGe)
	{
		return value(record, mode, currentGe, HiddenLoot.NONE);
	}

	/**
	 * {@code record}'s values in {@code mode}, without the loot items {@code hidden} hides (coins always count); see
	 * the class rules.
	 *
	 * @param currentGe today's GE unit prices keyed by the id as tallied (an item without an entry has no price), or
	 *                  {@code null} to use the prices saved with the record
	 * @param hidden    loot items left out of the values; {@code null} is none
	 */
	static Values value(LedgerRecord record, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
	{
		final LootPriceMode lootMode = mode == null ? LootPriceMode.GE : mode;
		if (!LedgerHistory.isValued(record))
		{
			return Values.builder().mode(lootMode).currentPrices(currentGe != null).build();
		}
		final ItemTally allLoot = ItemTally.fromMap(record.getLoot());
		final ItemTally loot = hidden == null ? allLoot : hidden.valued(allLoot);
		// Whether some loot is left out; only then are the saved totals and counts worked out again per item.
		final boolean hiding = loot != allLoot;
		final ItemTally supplies = record.getSupplies() == null ? null : ItemTally.fromMap(record.getSupplies());
		final Map<Integer, Long> ha = record.getUnitHaPrices();
		final boolean hasUnitPrices = record.getUnitGePrices() != null || ha != null;
		// Today's prices value the record's items; a record without any keeps its saved totals, when there are any.
		final boolean hasItems = !allLoot.isEmpty() || (supplies != null && !supplies.isEmpty());
		final boolean savedTotals = currentGe != null && !hasItems && hasSavedGeTotal(record);
		final boolean current = currentGe != null && !savedTotals;
		final long lootHa = hiding && ha != null ? ItemValuation.total(loot, ha)
			: record.getLootHaValue() != null ? record.getLootHaValue() : 0;
		final long suppliesHa = record.getSuppliesHaValue() != null ? record.getSuppliesHaValue() : 0;

		final long lootGe;
		final long suppliesGe;
		final int lootGeUnpriced;
		final int suppliesUnpriced;
		if (current)
		{
			lootGe = LootPricing.total(loot, LootPriceMode.GE, currentGe, ha, null);
			suppliesGe = ItemValuation.total(supplies, currentGe, record.getSupplyDoses());
			lootGeUnpriced = ItemValuation.countUnpriced(loot, currentGe);
			suppliesUnpriced = ItemValuation.countUnpriced(supplies, currentGe);
		}
		else
		{
			final Map<Integer, Long> ge = record.getUnitGePrices();
			final boolean perItem = hasUnitPrices && hasItems;
			lootGe = perItem ? LootPricing.total(loot, LootPriceMode.GE, ge, ha, null) : record.getLootGeValue();
			suppliesGe = LedgerHistory.suppliesGe(record);
			lootGeUnpriced = hiding && perItem ? ItemValuation.countUnpriced(loot, ge)
				: LedgerHistory.lootUnpriced(record);
			suppliesUnpriced = LedgerHistory.suppliesUnpriced(record);
		}

		long lootValue;
		int lootUnpriced;
		switch (lootMode)
		{
			case HIGH_ALCH:
				lootValue = lootHa;
				// Without high-alchemy unit values every loot item is unpriced, as its details show it, so the saved
				// high-alchemy total of a record with loot items is marked ~.
				lootUnpriced = ItemValuation.countUnpriced(loot, ha);
				break;
			default:
				lootValue = lootGe;
				lootUnpriced = lootGeUnpriced;
				break;
		}
		return Values.builder()
			.mode(lootMode)
			.currentPrices(current)
			.savedTotals(savedTotals)
			.lootValue(lootValue)
			.lootGe(lootGe)
			.lootHa(lootHa)
			.suppliesGe(suppliesGe)
			.suppliesHa(suppliesHa)
			.lootUnpriced(lootUnpriced)
			.lootGeUnpriced(lootGeUnpriced)
			.suppliesUnpriced(suppliesUnpriced)
			.build();
	}

	/** Whether {@code record} was saved with a non-zero loot or supplies GE total. */
	private static boolean hasSavedGeTotal(LedgerRecord record)
	{
		final Long lootGe = record.getLootGeValue();
		final Long suppliesGe = record.getSuppliesGeValue();
		return (lootGe != null && lootGe != 0) || (suppliesGe != null && suppliesGe != 0);
	}

	/** Every distinct item id in the loot and supplies of {@code records}, for one batched price lookup. */
	static Set<Integer> itemIds(Collection<LedgerRecord> records)
	{
		Set<Integer> ids = new TreeSet<>();
		for (LedgerRecord r : records)
		{
			if (r == null)
			{
				continue;
			}
			addKeys(ids, r.getLoot());
			addKeys(ids, r.getSupplies());
		}
		return ids;
	}

	private static void addKeys(Set<Integer> into, Map<Integer, Long> map)
	{
		if (map == null)
		{
			return;
		}
		for (Integer id : map.keySet())
		{
			if (id != null)
			{
				into.add(id);
			}
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import lombok.*;

/**
 * How the shown history is valued (split from {@link LedgerHistoryModel}): the "Loot price" mode, today's GE
 * prices received and asked for, the wait for them and its expiry, and {@link #valuationVersion}, bumped whenever
 * any of these changes what the history is worth. Saved tasks are always valued at today's prices (the rules
 * are {@link HistoryPricing}'s).
 *
 * <p>Threading: EDT only, like the model that owns it; the exception is {@link #isWaitingForCurrentPrices}, which reads
 * one volatile field. It only keeps the state: the model decides what a change means (dropping the statistics,
 * asking for the advisor's plan again) and tells its listener. Callers write through the model.</p>
 */
final class HistoryValuation
{
	/**
	 * How long the views valued at today's prices wait for the prices asked for before they are redrawn with the
	 * prices there are.
	 */
	static final long CURRENT_PRICES_WAIT_MILLIS = 3_000;

	/** Asks the plugin for today's GE prices of item ids (EDT). */
	private final Consumer<Set<Integer>> currentPriceRequests;
	/** How loot is valued (the "Loot price" setting). */
	private LootPriceMode lootPriceMode;
	/**
	 * Today's GE unit prices received from the plugin this session, by item id as tallied; items whose price was
	 * unavailable have no entry (and are asked for again when the records change).
	 */
	private final Map<Integer, Long> currentPrices = new HashMap<>();
	/** {@link #currentPrices}, read-only, as handed to the views. */
	private final Map<Integer, Long> shownPrices = Collections.unmodifiableMap(currentPrices);
	/** Ids asked for whose answer has not arrived yet, so they are not asked for twice. */
	private final Set<Integer> currentPricesPending = new HashSet<>();
	/**
	 * While the views wait for today's prices: ids whose answer came back without a price and that the plugin is
	 * looking up again ({@link PriceRetry}), for example because RuneLite's price list had not loaded yet at client
	 * start. The wait goes on until they arrive too, or the wait runs out; emptied whenever the wait ends.
	 */
	private final Set<Integer> currentPricesRetrying = new HashSet<>();
	/**
	 * Whether the views valued at today's prices keep what they show until the prices asked for arrive, instead of
	 * briefly showing {@code ~} and lower totals for the items not priced yet. Never longer than
	 * {@link #CURRENT_PRICES_WAIT_MILLIS}. Written on the EDT only; volatile so the plugin may check it on the client
	 * thread ({@link #isWaitingForCurrentPrices}).
	 */
	@Getter
	private volatile boolean waitingForCurrentPrices;
	/** When {@link #waitingForCurrentPrices} began ({@link System#nanoTime}). */
	private long waitingForCurrentPricesSince;
	/**
	 * Loot items left out of the loot value, worked out by the model from Ground Items' hidden list and the
	 * item names.
	 */
	private HiddenLoot hiddenLoot = HiddenLoot.NONE;
	/** Bumped whenever how the history is valued changes: the mode, today's prices or the hidden loot. */
	private long valuationVersion;

	/**
	 * @param lootPriceMode        the "Loot price" mode; {@code null} is GE
	 * @param currentPriceRequests asks the plugin for today's GE prices of item ids (EDT)
	 */
	HistoryValuation(LootPriceMode lootPriceMode, Consumer<Set<Integer>> currentPriceRequests)
	{
		this.lootPriceMode = lootPriceMode == null ? LootPriceMode.GE : lootPriceMode;
		this.currentPriceRequests = currentPriceRequests;
	}

	LootPriceMode lootPriceMode()
	{
		return lootPriceMode;
	}

	/** Sets the "Loot price" mode ({@code null} is GE); returns whether it changed, which bumps the version. */
	boolean setLootPriceMode(LootPriceMode mode)
	{
		LootPriceMode newMode = mode == null ? LootPriceMode.GE : mode;
		if (newMode == lootPriceMode)
		{
			return false;
		}
		lootPriceMode = newMode;
		valuationVersion++;
		return true;
	}

	/** Loot items left out of the loot value; never {@code null}. */
	HiddenLoot hiddenLoot()
	{
		return hiddenLoot;
	}

	/**
	 * Sets the loot items left out of the loot value ({@code null} is none); returns whether they changed, which bumps
	 * the version.
	 */
	boolean setHiddenLoot(HiddenLoot hidden)
	{
		HiddenLoot h = hidden == null ? HiddenLoot.NONE : hidden;
		if (h.equals(hiddenLoot))
		{
			return false;
		}
		hiddenLoot = h;
		valuationVersion++;
		return true;
	}

	/**
	 * Today's GE prices to value the history at: read-only, never {@code null}, and changing as prices arrive (copy it
	 * to keep it). An item without an entry has no price yet, so it is left out and its total marked {@code ~}.
	 */
	Map<Integer, Long> shownPrices()
	{
		return shownPrices;
	}

	/**
	 * Asks the plugin (once, in one batch) for today's GE price of every item in {@code records} that has none yet and
	 * is not already asked for.
	 */
	void requestCurrentPrices(List<LedgerRecord> records)
	{
		Set<Integer> ids = HistoryPricing.itemIds(records);
		ids.removeAll(currentPrices.keySet());
		ids.removeAll(currentPricesPending);
		if (!ids.isEmpty())
		{
			currentPricesPending.addAll(ids);
			currentPriceRequests.accept(ids);
		}
	}

	/**
	 * Adds today's GE prices the plugin looked up ({@code prices}, for those of {@code requested} that it found);
	 * {@code requested} is no longer pending. While the views wait for prices, the ids of {@code retrying} (those the
	 * plugin looks up again, {@link PriceRetry}) keep the wait going until they arrive ({@link #isWaitOver}). Bumps
	 * the version, so the cached views are worked out again, only when some price is new or changed; returns whether
	 * it did.
	 *
	 * @param retrying ids of {@code requested} that came back without a price and are looked up again; may be empty
	 */
	boolean addCurrentPrices(Set<Integer> requested, Map<Integer, Long> prices, Set<Integer> retrying)
	{
		currentPricesPending.removeAll(requested);
		currentPricesRetrying.removeAll(prices.keySet());
		if (waitingForCurrentPrices)
		{
			for (Integer id : retrying)
			{
				if (!prices.containsKey(id))
				{
					currentPricesRetrying.add(id);
				}
			}
		}
		boolean changed = false;
		for (Map.Entry<Integer, Long> e : prices.entrySet())
		{
			Long old = currentPrices.put(e.getKey(), e.getValue());
			changed |= !Objects.equals(e.getValue(), old);
		}
		if (changed)
		{
			valuationVersion++;
		}
		return changed;
	}

	/** Whether some prices asked for have not arrived yet. */
	boolean isCurrentPricesPending()
	{
		return !currentPricesPending.isEmpty();
	}

	/**
	 * Whether a wait for today's prices may end: every price asked for has been answered, and none that came back
	 * unavailable is still being looked up again.
	 */
	boolean isWaitOver()
	{
		return currentPricesPending.isEmpty() && currentPricesRetrying.isEmpty();
	}

	/**
	 * After {@link #requestCurrentPrices}: whether the views valued at today's prices should keep what they show until
	 * the prices asked for arrive (some asked for are on their way, or, in a wait that already began, are being looked
	 * up again). Starts the wait, or keeps one that already began; ends it otherwise.
	 */
	boolean waitForCurrentPrices()
	{
		if (isWaitOver())
		{
			stopWaiting();
			return false;
		}
		if (!waitingForCurrentPrices)
		{
			waitingForCurrentPrices = true;
			waitingForCurrentPricesSince = System.nanoTime();
		}
		return true;
	}

	/** Ends any wait for today's prices; the prices being looked up again no longer hold anything back. */
	void stopWaiting()
	{
		waitingForCurrentPrices = false;
		currentPricesRetrying.clear();
	}

	/**
	 * Whether a wait for today's prices has lasted {@link #CURRENT_PRICES_WAIT_MILLIS} (an answer never came, or a
	 * price looked up again was still unavailable); if so, the pending ids are forgotten so the missing prices may be
	 * asked for again, and the caller ends the wait.
	 */
	boolean currentPricesWaitExpired()
	{
		if (waitingForCurrentPrices && System.nanoTime() - waitingForCurrentPricesSince
			>= TimeUnit.MILLISECONDS.toNanos(CURRENT_PRICES_WAIT_MILLIS))
		{
			currentPricesPending.clear();
			currentPricesRetrying.clear();
			return true;
		}
		return false;
	}

	/** Test seam: lets a wait for today's prices run out at once, as if no answer came in time. */
	void expireCurrentPricesWait()
	{
		waitingForCurrentPricesSince -= TimeUnit.MILLISECONDS.toNanos(CURRENT_PRICES_WAIT_MILLIS);
	}

	/** Bumped whenever how the history is valued changes: the mode, today's prices or the hidden loot. */
	long valuationVersion()
	{
		return valuationVersion;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;
import net.runelite.client.util.*;

/**
 * The player's "Ignored loot" setting, parsed: items left out of kill loot when it is captured. Pure: names are passed
 * in by the plugin, which reads them from item compositions on the client thread.
 *
 * <p>The setting is a comma-separated list. An entry of only digits is an item id; any other entry is an item name,
 * matched case-insensitively, in which {@code *} matches any run of characters (RuneLite's {@link WildcardMatcher}, as
 * used by the core Ground Items plugin). Blank entries are skipped. A noted item matches through its unnoted item: its
 * unnoted id and name.</p>
 *
 * <p>Immutable, so a parsed list can be shared between threads.</p>
 */
@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
final class IgnoredLoot
{
	/** Ignores nothing. */
	static final IgnoredLoot NONE = new IgnoredLoot(Collections.emptySet(), Collections.emptyList());

	private final Set<Integer> ids;
	/** Name patterns, lower-cased and trimmed. */
	private final List<String> names;

	/**
	 * Parses the setting.
	 *
	 * @param setting the comma-separated list, or {@code null}
	 */
	static IgnoredLoot parse(String setting)
	{
		if (setting == null || setting.trim().isEmpty())
		{
			return NONE;
		}
		final Set<Integer> ids = new HashSet<>();
		final List<String> names = new ArrayList<>();
		for (String raw : setting.split(","))
		{
			final String entry = raw.trim();
			if (entry.isEmpty())
			{
				continue;
			}
			if (entry.chars().allMatch(c -> c >= '0' && c <= '9'))
			{
				try
				{
					ids.add(Integer.parseInt(entry));
					continue;
				}
				catch (NumberFormatException e)
				{
					// Too large to be an item id; then it can only match a name.
				}
			}
			final String name = entry.toLowerCase(Locale.ROOT);
			if (!names.contains(name))
			{
				names.add(name);
			}
		}
		if (ids.isEmpty() && names.isEmpty())
		{
			return NONE;
		}
		return new IgnoredLoot(Collections.unmodifiableSet(ids), Collections.unmodifiableList(names));
	}

	/** Whether nothing is ignored (so no item names need to be looked up). */
	boolean isEmpty()
	{
		return ids.isEmpty() && names.isEmpty();
	}

	/** Whether any entry is a name (so item names need to be looked up). */
	boolean hasNames()
	{
		return !names.isEmpty();
	}

	/**
	 * Whether a dropped item is ignored.
	 *
	 * @param itemId         the item id as dropped (possibly noted)
	 * @param unnotedId      the unnoted item's id ({@code itemId} itself when not noted)
	 * @param unnotedName    the unnoted item's name, or {@code null} when unknown (then only ids can match)
	 */
	boolean ignores(int itemId, int unnotedId, String unnotedName)
	{
		if (ids.contains(itemId) || ids.contains(unnotedId))
		{
			return true;
		}
		if (unnotedName == null)
		{
			return false;
		}
		final String name = unnotedName.trim();
		for (String pattern : names)
		{
			if (WildcardMatcher.matches(pattern, name))
			{
				return true;
			}
		}
		return false;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Pure: a task's supplies and loot item by item, for the panel's item grids. No RuneLite dependencies; item
 * names come from an injected {@link ItemNames} (the plugin resolves them through {@code ItemManager} on the client
 * thread, and the panel passes what it has received).
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>One row per item id as tallied (a noted drop is its own row). Quantities in doses, bites or charges (ids in
 *     the supply doses, see {@link LedgerRecord#getSupplyDoses()}) show as "N doses", "N bites" or "N charges"; the
 *     word comes from {@link SupplyTracker#MULTI_BITE_FOOD} and {@link SupplyTracker#CHARGED_ITEMS}, any other is a
 *     potion. Their names drop the "(4)" dose or charge suffix of the item they are keyed by. The live and history
 *     supplies grids show one row per potion ({@link #supplyGridRows}).</li>
 *     <li>Supplies are valued at GE prices, per dose, bite or charge ({@link ItemValuation#total(ItemTally, Map, Map)});
 *     loot in the {@link LootPriceMode}, with a GE price of 0 at high alch ({@link LootPricing}). The values are the
 *     same per-item amounts the totals add up. An item without the price shows as unavailable in its tooltip.</li>
 *     <li>Rows are sorted by value, highest first; unpriced rows come last; ties by name (ignoring case), then id.</li>
 *     <li>A loot row gets the alch hint ({@link #ALCH_MARKER}) when its high alch unit value, less the nature rune
 *     the cast uses, is above its GE unit price ({@link #alchBeatsGe}). Untradeables (GE 0), items without either
 *     price, and every item while the nature rune price is unknown never get it.</li>
 *     <li>The panel shows every row as an item icon ({@link ItemGridView}). A text list (the XP lists) shows at most
 *     {@link #MAX_ROWS} rows until the player asks for all ({@link #visible}).</li>
 * </ul>
 *
 * <p>Immutable.</p>
 */
@EqualsAndHashCode
@ToString
final class ItemDetails
{
	/** Rows a text list ({@link ItemListView}, the XP lists) shows before "+N more". */
	static final int MAX_ROWS = 10;
	/** Value of an item whose price is unavailable. */
	static final String UNPRICED = "?";
	/** Shown for a saved task that has no item data (saved before loot and supplies were tracked). */
	static final String NO_ITEM_DETAILS = "No item details";
	/**
	 * Names the alch hint in the tooltip of a loot item whose high alch value beats its GE price (its icon has an
	 * orange border). Not "(HA)", which the panel uses for the "Loot price" setting.
	 */
	static final String ALCH_MARKER = "(alch)";
	/** Details without any items. */
	static final ItemDetails EMPTY = new ItemDetails(null, null, null, null, null, null);

	/** Item names, as far as they are known. */
	interface ItemNames
	{
		/** The item's name, or {@code null} while it is unknown. */
		String name(int itemId);
	}

	/** How a row's quantity is counted. */
	@Getter
	@AllArgsConstructor
	enum Unit
	{
		ITEMS(null, null),
		DOSES("dose", "doses"),
		BITES("bite", "bites"),
		CHARGES("charge", "charges");

		/** The word for one ("dose"), or {@code null} for {@link #ITEMS}. */
		private final String one;
		/** The word for several ("doses"), or {@code null} for {@link #ITEMS}. */
		private final String many;
	}

	/** One line of an item list. */
	@Value
	@Builder(toBuilder = true)
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static class Row
	{
		int itemId;
		/** Name to show (never {@code null}). */
		String name;
		long quantity;
		Unit unit;
		/** Value of the whole quantity, or {@code null} when the price is unavailable. */
		Long value;
		/** What {@link #value} is: "GE" or "high alch". */
		String priceName;
		/** GE unit price (per item, not per dose) as saved or looked up, or {@code null} when unavailable. */
		Long unitGe;
		/** High alch unit value, or {@code null} when unavailable. */
		Long unitHa;
		/** Doses (bites, charges) in one item for {@link #unitGe}, or {@code null}. */
		Integer dosesPerItem;
		/**
		 * Whether to show the alch hint (the icon's orange border, and {@link #ALCH_MARKER} in the tooltip): loot whose
		 * high alch value beats its GE price.
		 */
		boolean alchHint;
		/**
		 * Whether {@link #value} leaves out part of the quantity, whose price was unavailable: only in rows summed over
		 * several tasks ({@link ItemSums}), when some of them had the price and others not.
		 */
		boolean approximate;

		/** "x14", or "22 doses" for an item counted in doses, bites or charges. */
		String quantityText()
		{
			if (unit == Unit.ITEMS)
			{
				return "x" + LedgerHistory.formatAmount(quantity, false);
			}
			return LedgerHistory.formatAmount(quantity, false) + " " + (quantity == 1 ? unit.one : unit.many);
		}

		/** The value without " gp" (as in history rows), or {@link #UNPRICED}. */
		String valueText()
		{
			return value == null ? UNPRICED : LedgerHistory.formatAmount(value, approximate);
		}

		/**
		 * HTML tooltip of the item's icon: the full name, the exact quantity and value, the unit prices and, if shown,
		 * the alch hint.
		 */
		String tooltip()
		{
			StringBuilder sb = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(name));
			sb.append("<br>Quantity: ").append(String.format("%,d", quantity));
			if (unit != Unit.ITEMS)
			{
				sb.append(' ').append(quantity == 1 ? unit.one : unit.many);
			}
			sb.append("<br>Value (").append(priceName).append("): ")
				.append(value == null ? "unavailable"
					: (approximate ? LedgerHistory.APPROXIMATE : "") + LedgerHistory.formatGpExact(value));
			sb.append("<br>GE: ").append(geText());
			sb.append("<br>High alch: ").append(unitHa == null ? "unavailable" : LedgerHistory.formatGpExact(unitHa)
				+ " each");
			if (alchHint)
			{
				sb.append("<br>").append(ALCH_MARKER).append(" High alch, less a nature rune, is worth more than")
					.append("<br>the GE price. GE tax not included.");
			}
			return sb.append("</html>").toString();
		}

		private String geText()
		{
			if (unitGe == null)
			{
				return "unavailable";
			}
			if (unitGe == 0)
			{
				return "untradeable";
			}
			String each = LedgerHistory.formatGpExact(unitGe) + " each";
			if (dosesPerItem != null && unit != Unit.ITEMS)
			{
				return each + " (" + dosesPerItem + " " + (dosesPerItem == 1 ? unit.one : unit.many) + ")";
			}
			return each;
		}
	}

	/** Highest value first; unpriced last; then by name ignoring case, then id. */
	static final Comparator<Row> BY_VALUE = Comparator
		.comparing((Row r) -> r.getValue() == null)
		.thenComparing(r -> r.getValue() == null ? 0L : r.getValue(), Comparator.reverseOrder())
		.thenComparing(Row::getName, String.CASE_INSENSITIVE_ORDER)
		.thenComparingInt(Row::getItemId);

	private final Map<Integer, Long> loot;
	private final Map<Integer, Long> supplies;
	private final Map<Integer, Integer> doses;
	private final Map<Integer, Long> ge;
	private final Map<Integer, Long> ha;
	/** The GE price of the nature rune a high alch uses, or {@code null} while unknown (then no alch hint). */
	@EqualsAndHashCode.Exclude
	private final Long natureRunePrice;

	private ItemDetails(Map<Integer, Long> loot, Map<Integer, Long> supplies, Map<Integer, Integer> doses,
		Map<Integer, Long> ge, Map<Integer, Long> ha, Long natureRunePrice)
	{
		this.loot = copy(loot);
		this.supplies = copy(supplies);
		this.doses = copy(doses);
		this.ge = copy(ge);
		this.ha = copy(ha);
		this.natureRunePrice = natureRunePrice;
	}

	/**
	 * A live session's items: its tallies and the unit prices it is valued at (keyed by the id as tallied, as in
	 * {@link ItemValuation.UnitPrices}). Everything is copied.
	 */
	static ItemDetails of(ItemTally loot, ItemTally supplies, Map<Integer, Integer> doses, Map<Integer, Long> ge,
		Map<Integer, Long> ha)
	{
		return new ItemDetails(loot == null ? null : loot.toMap(), supplies == null ? null : supplies.toMap(), doses,
			ge, ha, null);
	}

	/**
	 * A saved task's items at the prices saved with it, or {@code null} when it has no item data: saved before loot
	 * and supplies were tracked (not valued, and neither loot nor supplies stored).
	 */
	static ItemDetails of(LedgerRecord record)
	{
		if (record == null || !LedgerHistory.isValued(record) && record.getLoot() == null
			&& record.getSupplies() == null)
		{
			return null;
		}
		return new ItemDetails(record.getLoot(), record.getSupplies(), record.getSupplyDoses(),
			record.getUnitGePrices(), record.getUnitHaPrices(), null);
	}

	/**
	 * These items at other GE unit prices ({@code currentGe}, keyed by the id as tallied; an id without an entry has no
	 * price), as the history values them at today's prices ({@link HistoryPricing}); the high alch values stay.
	 */
	ItemDetails withGePrices(Map<Integer, Long> currentGe)
	{
		return new ItemDetails(loot, supplies, doses, currentGe, ha, natureRunePrice);
	}

	/** These items with the nature rune's GE price for the alch hint ({@code null} or not positive: unknown). */
	ItemDetails withNatureRunePrice(Long price)
	{
		return new ItemDetails(loot, supplies, doses, ge, ha, price != null && price > 0 ? price : null);
	}

	/** Every item id in the loot and supplies, for one name lookup. */
	Set<Integer> itemIds()
	{
		Set<Integer> ids = new TreeSet<>(loot.keySet());
		ids.addAll(supplies.keySet());
		return ids;
	}

	boolean hasLoot()
	{
		return !loot.isEmpty();
	}

	boolean hasSupplies()
	{
		return !supplies.isEmpty();
	}

	/** The supplies, valued at GE prices per dose, bite or charge, sorted by {@link #BY_VALUE}. */
	List<Row> supplyRows(ItemNames names)
	{
		List<Row> rows = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : supplies.entrySet())
		{
			int id = e.getKey();
			Integer perItem = doses.get(id);
			Unit unit = perItem == null ? Unit.ITEMS : doseUnit(id);
			Long unitGe = ge.get(id);
			rows.add(Row.builder()
				.itemId(id)
				.name(displayName(id, names, unit != Unit.ITEMS))
				.quantity(e.getValue())
				.unit(unit)
				.value(value(id, e.getValue(), unitGe, doses))
				.priceName("GE")
				.unitGe(unitGe)
				.unitHa(ha.get(id))
				.dosesPerItem(perItem)
				.alchHint(false)
				.build());
		}
		rows.sort(BY_VALUE);
		return rows;
	}

	/**
	 * The supplies grid's rows (the live task's and a history task's details): {@link #supplyRows} with each
	 * potion family's rows merged into one. A record can hold one potion under two ids, because a potion is counted
	 * under the variant with the most doses seen so far ({@link SupplyTracker}), and that moves when a higher-dose
	 * variant is first seen mid-task: Prayer potion as 139 (3 doses) and 2434 (4 doses), say. The merged row has the
	 * family's doses summed, the id with the most doses in one potion (on a tie the lower id), whose icon, unit prices
	 * and doses per potion it shows, and the rows' values summed; with some of them unpriced it is marked approximate,
	 * with all of them unpriced it has none. The family is {@link #potionFamily}, the advisor's rule
	 * ({@link TaskPlanner#potionFamilies}); a potion whose name isn't known yet stays on its own until it is. What is
	 * saved is not changed. Sorted by {@link #BY_VALUE}.
	 */
	List<Row> supplyGridRows(ItemNames names)
	{
		final List<Row> rows = supplyRows(names);
		final Map<String, List<Row>> families = new TreeMap<>();
		final List<Row> result = new ArrayList<>(rows.size());
		for (Row row : rows)
		{
			final String family = row.getUnit() == Unit.DOSES ? potionFamily(row.getItemId(), names) : null;
			if (family == null)
			{
				result.add(row);
			}
			else
			{
				families.computeIfAbsent(family, k -> new ArrayList<>()).add(row);
			}
		}
		for (List<Row> family : families.values())
		{
			result.add(family.size() == 1 ? family.get(0) : merged(family, names));
		}
		result.sort(BY_VALUE);
		return result;
	}

	/** One row for a potion family's rows ({@link #supplyGridRows}). */
	private static Row merged(List<Row> family, ItemNames names)
	{
		Row shown = family.get(0);
		long quantity = 0;
		long value = 0;
		int priced = 0;
		for (Row row : family)
		{
			final int doses = row.getDosesPerItem() == null ? 0 : row.getDosesPerItem();
			final int shownDoses = shown.getDosesPerItem() == null ? 0 : shown.getDosesPerItem();
			if (doses > shownDoses || doses == shownDoses && row.getItemId() < shown.getItemId())
			{
				shown = row;
			}
			quantity = saturatedAdd(quantity, row.getQuantity());
			if (row.getValue() != null)
			{
				value = saturatedAdd(value, row.getValue());
				priced++;
			}
		}
		return shown.toBuilder()
			.name(displayName(shown.getItemId(), names, true))
			.quantity(quantity)
			.value(priced == 0 ? null : value)
			.approximate(priced > 0 && priced < family.size())
			.build();
	}

	/**
	 * A potion's family, the advisor's rule ({@link TaskPlanner#potionFamilies}): for an id counted in doses (in a
	 * record's supply doses, {@link LedgerRecord#getSupplyDoses}) that is a potion (not the bites or charges of
	 * {@link #doseUnit}) and whose name {@code names} knows, that name without its dose suffix ({@link #displayName}),
	 * lower case, as {@link SupplyTracker} names a potion's family: "Prayer potion(4)" and "Prayer potion(3)" are both
	 * "prayer potion". {@code null} otherwise; the caller checks that the id is counted in doses.
	 */
	static String potionFamily(int itemId, ItemNames names)
	{
		if (names == null || doseUnit(itemId) != Unit.DOSES)
		{
			return null;
		}
		final String name = names.name(itemId);
		if (name == null || name.trim().isEmpty())
		{
			return null;
		}
		return displayName(itemId, names, true).trim().toLowerCase(Locale.ROOT);
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** The loot, valued in {@code mode} ({@link LootPricing}), sorted by {@link #BY_VALUE}, with the alch hint. */
	List<Row> lootRows(LootPriceMode mode, ItemNames names)
	{
		LootPriceMode lootMode = mode == null ? LootPriceMode.GE : mode;
		Map<Integer, Long> prices = LootPricing.unitPrices(lootMode, ge, ha);
		String priceName = lootMode == LootPriceMode.HIGH_ALCH ? "high alch" : "GE";
		List<Row> rows = new ArrayList<>();
		for (Map.Entry<Integer, Long> e : loot.entrySet())
		{
			int id = e.getKey();
			Long unitGe = ge.get(id);
			Long unitHa = ha.get(id);
			rows.add(Row.builder()
				.itemId(id)
				.name(displayName(id, names, false))
				.quantity(e.getValue())
				.unit(Unit.ITEMS)
				.value(value(id, e.getValue(), prices.get(id), null))
				.priceName(priceName)
				.unitGe(unitGe)
				.unitHa(unitHa)
				.dosesPerItem(null)
				.alchHint(alchBeatsGe(unitGe, unitHa, natureRunePrice))
				.build());
		}
		rows.sort(BY_VALUE);
		return rows;
	}

	/**
	 * Whether alching beats selling: the high alch unit value, less the nature rune the cast uses, is above a known,
	 * non-zero GE unit price. An untradeable item (GE 0, already valued at high alch), an item missing either price,
	 * and any item while the nature rune price is unknown never qualify. The GE tax is not counted.
	 */
	static boolean alchBeatsGe(Long unitGe, Long unitHa, Long natureRunePrice)
	{
		return unitGe != null && unitHa != null && natureRunePrice != null && unitGe > 0
			&& unitHa - natureRunePrice > unitGe;
	}

	/**
	 * Rows worked out without names ({@link ItemSums#rows()}, Overall totals), as {@link #supplyRows} or
	 * {@link #lootRows} would show them: named through {@code names} and, for {@code loot}, given the alch hint at
	 * {@code natureRunePrice} ({@code null} or not positive: unknown, no hint). Sorted by {@link #BY_VALUE}.
	 */
	static List<Row> named(List<Row> rows, ItemNames names, Long natureRunePrice, boolean loot)
	{
		Long nature = natureRunePrice != null && natureRunePrice > 0 ? natureRunePrice : null;
		List<Row> result = new ArrayList<>(rows.size());
		for (Row row : rows)
		{
			result.add(row.toBuilder()
				.name(displayName(row.getItemId(), names, row.getUnit() != Unit.ITEMS))
				.alchHint(loot && alchBeatsGe(row.getUnitGe(), row.getUnitHa(), nature))
				.build());
		}
		result.sort(BY_VALUE);
		return result;
	}

	/** The rows to show: all of them when {@code showAll}, otherwise the first {@link #MAX_ROWS}. */
	static <T> List<T> visible(List<T> rows, boolean showAll)
	{
		if (showAll || rows.size() <= MAX_ROWS)
		{
			return rows;
		}
		return rows.subList(0, MAX_ROWS);
	}

	/** Rows left out by {@link #visible} when not showing all (0 when they all fit). */
	static int hiddenCount(int rows)
	{
		return Math.max(0, rows - MAX_ROWS);
	}

	/** The quantity word of a dose-counted supply id: bites, charges, or doses (potions). */
	static Unit doseUnit(int itemId)
	{
		if (SupplyTracker.MULTI_BITE_FOOD.containsKey(itemId))
		{
			return Unit.BITES;
		}
		if (SupplyTracker.CHARGED_ITEMS.containsKey(itemId) || SlayerBracelets.BRACELETS.contains(itemId))
		{
			return Unit.CHARGES;
		}
		return Unit.DOSES;
	}

	/**
	 * The name to show: the looked-up name, without a trailing "(4)" for an item counted in doses, bites or charges
	 * (its row counts doses, not that item); "Item &lt;id&gt;" while the name is unknown.
	 */
	static String displayName(int itemId, ItemNames names, boolean perDose)
	{
		String name = names == null ? null : names.name(itemId);
		if (name == null || name.trim().isEmpty())
		{
			return "Item " + itemId;
		}
		if (perDose)
		{
			String stripped = name.replaceFirst("(\\s*\\([a-z]?\\d+\\)|\\s+\\d+)$", "");
			return stripped.isEmpty() ? name : stripped;
		}
		return name;
	}

	/** One item's value as the totals count it, or {@code null} without a unit price. */
	private static Long value(int id, long quantity, Long unitPrice, Map<Integer, Integer> doses)
	{
		if (unitPrice == null)
		{
			return null;
		}
		ItemTally one = new ItemTally();
		one.add(id, quantity);
		return ItemValuation.total(one, Collections.singletonMap(id, unitPrice), doses);
	}

	private static <V> Map<Integer, V> copy(Map<Integer, V> map)
	{
		Map<Integer, V> result = new TreeMap<>();
		if (map != null)
		{
			for (Map.Entry<Integer, V> e : map.entrySet())
			{
				if (e.getKey() != null && e.getValue() != null)
				{
					result.put(e.getKey(), e.getValue());
				}
			}
		}
		return Collections.unmodifiableMap(result);
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import javax.swing.border.*;
import net.runelite.client.ui.*;

/**
 * Supplies or loot as a grid of item icons, {@value #COLUMNS} to a row like RuneLite's Loot Tracker, in the
 * rows' order ({@link ItemDetails#BY_VALUE}). Each cell is a {@value #CELL_WIDTH} by {@value #CELL_HEIGHT} item
 * sprite with 1 px between cells, 184 px for a row (DESIGN_PRINCIPLES.md 3.6), which fits inside a card. Each icon
 * has its quantity drawn on it (a dose, bite or charge count for items counted that way; the tooltip says which), and
 * the row's tooltip ({@link ItemDetails.Row#tooltip()}: the full
 * name, exact quantity, value, unit prices and why the alch hint is shown). Loot whose high alch beats its GE price
 * (the alch hint, {@link ItemDetails#ALCH_MARKER}) gets a thin orange border. Every item is shown: five to a row keep
 * long lists short, so there is no "+N more". The title, "None" and opening and closing are
 * {@link TitledListView}'s. Loot grids leave out the items Ground Items hides, coins included
 * ({@link #setRows(List, HiddenLoot)}). EDT only.
 */
final class ItemGridView extends TitledListView<ItemDetails.Row>
{
	/** Icons per row, as in Loot Tracker. */
	static final int COLUMNS = 5;
	/** Width of a cell: an item sprite. */
	static final int CELL_WIDTH = 36;
	/** Height of a cell: an item sprite. The alch hint's 1 px border is drawn over the sprite's edge. */
	static final int CELL_HEIGHT = 32;
	/** The alch hint's border (DESIGN_PRINCIPLES.md 3.6 keeps RuneLite's brand orange for it). */
	static final Color ALCH_BORDER_COLOR = ColorScheme.BRAND_ORANGE;

	private final ItemIcons icons;
	/**
	 * Background of a cell, so the slots stand out from the list's: RuneLite's grey under the history and totals, the
	 * stone of a card for the live task's grids on the page ({@link #useSubHeader}), a darker parchment on the advisor's
	 * note ({@link #useParchment}).
	 */
	private Color cellBackground = ColorScheme.DARK_GRAY_COLOR;
	/** Each icon's tooltip (HTML): the row's own ({@link ItemDetails.Row#tooltip()}) unless set otherwise. */
	private Function<ItemDetails.Row, String> cellTooltip = ItemDetails.Row::tooltip;

	ItemGridView(String title, boolean collapsible, Color background, ItemIcons icons)
	{
		super(title, collapsible, background, "items");
		this.icons = icons;
		rebuild();
	}

	/**
	 * The advisor's Bring grid: on its parchment note ({@link TitledListView#useParchment}), with
	 * {@link LedgerTheme#PARCHMENT_CELL} slots and each icon's tooltip from {@code tooltip} (HTML; it starts with the
	 * item's name), since a thing to bring has an amount and no saved prices. Call it once, after the constructor.
	 */
	void useParchment(Function<ItemDetails.Row, String> tooltip)
	{
		cellBackground = LedgerTheme.PARCHMENT_CELL;
		cellTooltip = tooltip;
		useParchment();
	}

	/**
	 * Shows the rows {@code hidden} does not hide ({@code null}: all of them), and how many it hides in the title and
	 * the header's tooltip.
	 */
	void setRows(List<ItemDetails.Row> rows, HiddenLoot hidden)
	{
		List<ItemDetails.Row> shown = hidden == null ? rows : hidden.visibleRows(rows);
		setRows(shown, rows.size() - shown.size());
	}

	/** A flat sub-header's grid (the live task's): its cells in the card's stone. */
	@Override
	void useSubHeader()
	{
		cellBackground = LedgerTheme.CARD;
		super.useSubHeader();
	}

	@Override
	String hiddenNote(int hidden)
	{
		return (hidden == 1 ? "1 item is" : hidden + " items are") + " hidden by your Ground Items<br>hidden list;"
			+ " hidden items<br>are left out of loot value, except coins.";
	}

	@Override
	void fillBody(JPanel body, List<ItemDetails.Row> shown)
	{
		JPanel grid = new JPanel(new GridLayout(0, COLUMNS, 1, 1));
		// Names for tests, which find the cells from the list itself; no visible effect.
		grid.setName("itemGrid.grid");
		grid.setOpaque(false);
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (ItemDetails.Row row : shown)
		{
			grid.add(cell(row));
		}
		// Empty slots fill the last row, as in Loot Tracker.
		for (int i = shown.size(); i % COLUMNS != 0; i++)
		{
			grid.add(slot(new JLabel(), null));
		}
		// The cells keep their size: the grid never stretches to the list's width.
		grid.setMaximumSize(grid.getPreferredSize());
		body.add(grid);
	}

	private JLabel cell(ItemDetails.Row row)
	{
		JLabel cell = slot(new JLabel(),
			row.isAlchHint() ? BorderFactory.createLineBorder(ALCH_BORDER_COLOR, 1) : null);
		cell.setName("itemGrid.cell");
		cell.setToolTipText(cellTooltip.apply(row));
		icons.apply(cell, row.getItemId(), iconQuantity(row.getQuantity()));
		return cell;
	}

	/** A slot of the grid: one item sprite's size, so a row of five is 184 px wide and never widens the sidebar. */
	private JLabel slot(JLabel label, Border border)
	{
		label.setOpaque(true);
		label.setBackground(cellBackground);
		label.setHorizontalAlignment(SwingConstants.CENTER);
		label.setVerticalAlignment(SwingConstants.CENTER);
		label.setBorder(border);
		label.setPreferredSize(new Dimension(CELL_WIDTH, CELL_HEIGHT));
		return label;
	}

	/** The quantity to draw on an icon: the row's, capped to an {@code int} (the game shortens it, "10M"). */
	static int iconQuantity(long quantity)
	{
		return (int) Math.max(0, Math.min(Integer.MAX_VALUE, quantity));
	}
}

package com.shmayvan.slayerledger;

import javax.swing.*;

/**
 * Where the sidebar's item icons ({@link ItemGridView}) come from. The plugin backs it with RuneLite's
 * {@code ItemManager} ({@link SlayerLedgerPlugin#applyItemIcon}); tests pass a fake. Called on the EDT.
 */
@FunctionalInterface
interface ItemIcons
{
	/**
	 * Puts the icon of {@code itemId} (a noted id shows as a note) on {@code label}, with {@code quantity} drawn on it
	 * when it is above 1. The icon may be drawn later; the label is repainted when it is.
	 */
	void apply(JLabel label, int itemId, int quantity);
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.awt.event.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import net.runelite.client.ui.*;

/**
 * A text list of the sidebar ({@link TitledListView}): one line per {@link ItemListView.Line}, a small skill icon
 * ({@link SkillIcons}, as RuneLite's XP tracker shows), the name (cut short, with the full name in the tooltip) and the
 * amount on the right. Every line keeps an icon-sized slot before its name, empty for a line with no skill, so the
 * names stay aligned and the lines keep one height. A line can show a small item sprite in the slot instead
 * ({@link Line#getIconItemId}, {@link SmallItemIcon}, Overall totals' monsters assigned). At most
 * {@link ItemDetails#MAX_ROWS} lines show until "+N more" is clicked. The per-skill XP lists use it, with
 * {@link SkillXp.Row} lines; supplies and loot are item icons ({@link ItemGridView}). EDT only.
 */
class ItemListView extends TitledListView<ItemListView.Line>
{
	/** One line of a list: a name on the left, an amount on the right and a tooltip. */
	interface Line
	{
		/** Name to show (never {@code null}); cut short when too long. */
		String getName();

		/**
		 * Key of the skill whose small icon shows before the name (the name of RuneLite's {@code Skill} constant), or
		 * {@code null} for none.
		 */
		String getSkill();

		/**
		 * Item whose sprite shows small in the icon slot when the line has no skill, or {@code null} for none
		 * (the slot stays empty).
		 */
		default Integer getIconItemId()
		{
			return null;
		}

		/** Right-aligned amount text. */
		String amountText();

		/** HTML tooltip of the line. */
		String tooltip();
	}

	/**
	 * Width of the icon slot before a name: the small skill icons are 16 px wide (Ranged 18 px; checked against
	 * RuneLite 1.13.4's {@code skill_icons_small}).
	 */
	static final int ICON_WIDTH = 18;
	/** Height of the icon slot, as in the XP tracker's compact rows; Ranged's 18 px icon loses a pixel at each edge. */
	static final int ICON_HEIGHT = 16;

	/** What the lines are ("skills"), for the tooltips. */
	private final String noun;
	private final SkillIcons icons;
	/** Draws the item sprites of lines with {@link Line#getIconItemId}. */
	private final ItemIcons itemIcons;
	private final JLabel moreLabel = new JLabel();
	/** Whether every line is shown, past {@link ItemDetails#MAX_ROWS}. */
	private boolean showAll;
	/** Told when the player clicks "+N more" or "Show less", or {@code null}. */
	private Consumer<Boolean> showAllListener;
	/** The names' colour: white, or the label colour under a sub-header ({@link #useSubHeader}). */
	private Color nameColor = LedgerTheme.VALUE;
	/** The amounts' colour: RuneLite's light grey, or the value colour under a sub-header. */
	private Color amountColor = ColorScheme.LIGHT_GRAY_COLOR;

	/**
	 * @param noun what the lines are, for the tooltips ("skills")
	 * @param icons draws the small skill icons before the names
	 */
	ItemListView(String title, boolean collapsible, Color background, String noun, SkillIcons icons)
	{
		this(title, collapsible, background, noun, icons, (label, itemId, quantity) ->
		{
		});
	}

	/**
	 * @param noun what the lines are, for the tooltips ("monsters")
	 * @param icons draws the small skill icons before the names
	 * @param itemIcons draws the item sprites of lines with {@link Line#getIconItemId}, scaled to the slot
	 */
	ItemListView(String title, boolean collapsible, Color background, String noun, SkillIcons icons,
		ItemIcons itemIcons)
	{
		super(title, collapsible, background, noun);
		this.noun = noun;
		this.icons = icons;
		this.itemIcons = itemIcons;
		// Name for tests, which find it from the list itself; no visible effect.
		moreLabel.setName("itemList.more");
		moreLabel.setFont(FontManager.getRunescapeSmallFont());
		moreLabel.setForeground(ColorScheme.BRAND_ORANGE);
		moreLabel.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		moreLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		moreLabel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 1)
				{
					toggleShowAll();
				}
			}
		});
		rebuild();
	}

	/** A flat sub-header's list (the live XP): names in the label colour, amounts in the value colour. */
	@Override
	void useSubHeader()
	{
		nameColor = LedgerTheme.LABEL;
		amountColor = LedgerTheme.VALUE;
		moreLabel.setForeground(LedgerTheme.LABEL);
		super.useSubHeader();
	}

	/** Shows every line, or only the first {@link ItemDetails#MAX_ROWS} again, as a click on "+N more" does. */
	void toggleShowAll()
	{
		showAll = !showAll;
		rebuild();
		if (showAllListener != null)
		{
			showAllListener.accept(showAll);
		}
	}

	/**
	 * Starts with every line shown (or not), and tells {@code listener} when the player changes it, so a list that is
	 * built again (a history row's XP) keeps the choice.
	 */
	void setShowAll(boolean shown, Consumer<Boolean> listener)
	{
		showAllListener = listener;
		if (shown != showAll)
		{
			showAll = shown;
			rebuild();
		}
	}

	@Override
	void fillBody(JPanel body, List<Line> shown)
	{
		for (Line row : ItemDetails.visible(shown, showAll))
		{
			body.add(rowLine(row));
		}
		int hidden = ItemDetails.hiddenCount(shown.size());
		if (hidden > 0)
		{
			moreLabel.setText(showAll ? "Show less" : "+" + hidden + " more");
			moreLabel.setToolTipText(showAll ? "Show only the top " + ItemDetails.MAX_ROWS
				: "Click to show all " + shown.size() + " " + noun);
			body.add(moreLabel);
		}
	}

	/** The skill icon's slot, then the name filling the line (cut short if too long); the amount is right-aligned. */
	private JPanel rowLine(Line row)
	{
		JPanel line = new JPanel(new BorderLayout(4, 0));
		line.setOpaque(false);
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		line.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
		line.add(iconSlot(row), BorderLayout.WEST);
		JLabel name = label(row.getName(), nameColor);
		// The name asks for no width of its own, so a long one is cut short in the space left rather than widening
		// the sidebar (long monster names in "Monsters assigned").
		name.setPreferredSize(new Dimension(0, name.getPreferredSize().height));
		line.add(name, BorderLayout.CENTER);
		JPanel right = new JPanel(new BorderLayout(4, 0));
		right.setOpaque(false);
		right.add(label(row.amountText(), amountColor), BorderLayout.EAST);
		line.add(right, BorderLayout.EAST);
		// The tooltip has the full name and the exact amounts.
		line.setToolTipText(row.tooltip());
		return line;
	}

	/**
	 * A fixed-size slot with the skill's small icon, else the line's item sprite at the same size, or empty for a line
	 * with neither, so the names line up.
	 */
	private JLabel iconSlot(Line row)
	{
		String skill = row.getSkill();
		Integer itemId = row.getIconItemId();
		JLabel slot = new JLabel();
		// Name for tests, which read the icon from it; no visible effect.
		slot.setName("itemList.icon");
		Dimension size = new Dimension(ICON_WIDTH, ICON_HEIGHT);
		slot.setPreferredSize(size);
		slot.setMinimumSize(size);
		slot.setHorizontalAlignment(SwingConstants.CENTER);
		slot.setVerticalAlignment(SwingConstants.CENTER);
		if (skill != null)
		{
			icons.apply(slot, skill);
		}
		else if (itemId != null)
		{
			SmallItemIcon.apply(itemIcons, slot, itemId);
		}
		return slot;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Pure: the supplies or the loot of several saved tasks added up item by item, for the item grids of Overall totals
 *. Each task's rows come from {@link ItemDetails} exactly as its history details show them (at the prices it is
 * shown at), so a summed row is valued as the group's profit line counts it. No RuneLite dependencies.
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>One row per item id and {@link ItemDetails.Unit}, as tallied: a noted item stays its own row, and the doses,
 *     bites or charges of an item counted that way add up as doses, bites or charges.</li>
 *     <li>Quantities and values are the sums of the tasks' rows. A task whose item had no price adds its quantity but
 *     no value: the row's value is the sum of the priced tasks' values, marked approximate
 *     ({@link ItemDetails.Row#isApproximate()}); with no priced task it is unavailable ({@code null}).</li>
 *     <li>The unit prices and doses per item shown in the tooltip are those of the first task added that has them;
 *     Overall totals adds tasks newest first. At today's prices every task has the same GE price.</li>
 *     <li>The rows are not named and have no alch hint: names and the nature rune price are known on the EDT only, so
 *     the panel adds them with {@link ItemDetails#named}.</li>
 * </ul>
 *
 * <p>Not thread-safe: one is filled and read by one thread (the background thread working out the totals). The rows it
 * returns are immutable.</p>
 */
final class ItemSums
{
	/** The sums by item id and unit, in the order first added. */
	private final Map<List<Object>, Sum> sums = new LinkedHashMap<>();

	/** Adds one task's supply or loot rows ({@link ItemDetails#supplyRows} or {@link ItemDetails#lootRows}). */
	void add(List<ItemDetails.Row> rows)
	{
		for (ItemDetails.Row row : rows)
		{
			sums.computeIfAbsent(Arrays.asList(row.getItemId(), row.getUnit()), key -> new Sum(row)).add(row);
		}
	}

	/** The summed rows, unnamed ("Item &lt;id&gt;") and without the alch hint, unmodifiable. */
	List<ItemDetails.Row> rows()
	{
		List<ItemDetails.Row> rows = new ArrayList<>(sums.size());
		for (Sum sum : sums.values())
		{
			rows.add(sum.toRow());
		}
		return Collections.unmodifiableList(rows);
	}

	/** One item's running sum. */
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Sum
	{
		private final ItemDetails.Row first;
		private long quantity;
		private long value;
		private int priced;
		private int unpriced;
		private Long unitGe;
		private Long unitHa;
		private Integer dosesPerItem;

		private void add(ItemDetails.Row row)
		{
			quantity = saturatedAdd(quantity, row.getQuantity());
			if (row.getValue() == null)
			{
				unpriced++;
			}
			else
			{
				value = saturatedAdd(value, row.getValue());
				priced++;
			}
			unitGe = unitGe != null ? unitGe : row.getUnitGe();
			unitHa = unitHa != null ? unitHa : row.getUnitHa();
			dosesPerItem = dosesPerItem != null ? dosesPerItem : row.getDosesPerItem();
		}

		private ItemDetails.Row toRow()
		{
			return first.toBuilder()
				.quantity(quantity)
				.value(priced == 0 ? null : value)
				.unitGe(unitGe)
				.unitHa(unitHa)
				.dosesPerItem(dosesPerItem)
				.alchHint(false)
				.approximate(priced > 0 && unpriced > 0)
				.build();
		}
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Per-item quantities (item id to quantity), used for loot and supplies. Pure: no RuneLite dependencies.
 *
 * <p>Ids are stored exactly as received (a noted drop keeps its noted id); pricing resolves the unnoted id, see
 * {@link ItemValuation}. Quantities are {@code long} so large coin stacks over a long task cannot overflow. Only
 * positive quantities are kept. Not thread-safe; {@link SessionTracker} guards its instance with its own lock.</p>
 *
 * <p>The JSON form is a plain {@code Map<Integer, Long>} (an object such as {@code {"995": 1200}}), see
 * {@link #toMap()} and {@link #fromMap(Map)}.</p>
 */
@EqualsAndHashCode
@ToString
public final class ItemTally
{
	private final TreeMap<Integer, Long> quantities = new TreeMap<>();

	public ItemTally()
	{
	}

	/** A copy of another tally. */
	public ItemTally(ItemTally other)
	{
		if (other != null)
		{
			quantities.putAll(other.quantities);
		}
	}

	/**
	 * Builds a tally from its JSON form. {@code null} gives an empty tally; null keys and non-positive quantities
	 * are skipped.
	 */
	public static ItemTally fromMap(Map<Integer, Long> map)
	{
		ItemTally tally = new ItemTally();
		if (map != null)
		{
			for (Map.Entry<Integer, Long> e : map.entrySet())
			{
				if (e.getKey() != null && e.getValue() != null)
				{
					tally.add(e.getKey(), e.getValue());
				}
			}
		}
		return tally;
	}

	/**
	 * Adds a quantity of an item. Non-positive quantities are ignored. Saturates at {@link Long#MAX_VALUE}.
	 */
	public void add(int itemId, long quantity)
	{
		if (quantity <= 0)
		{
			return;
		}
		quantities.merge(itemId, quantity, ItemTally::saturatedAdd);
	}

	/**
	 * Removes up to a quantity of an item, never going below zero (an item reaching zero is removed). Non-positive
	 * quantities are ignored.
	 *
	 * @return the quantity actually removed
	 */
	public long subtract(int itemId, long quantity)
	{
		if (quantity <= 0)
		{
			return 0;
		}
		final long current = get(itemId);
		final long removed = Math.min(current, quantity);
		if (removed == current)
		{
			quantities.remove(itemId);
		}
		else
		{
			quantities.put(itemId, current - removed);
		}
		return removed;
	}

	/** Adds every item of another tally to this one. */
	public void merge(ItemTally other)
	{
		if (other == null)
		{
			return;
		}
		// Merging a tally into itself iterates over a copy.
		Map<Integer, Long> source = other == this ? new TreeMap<>(quantities) : other.quantities;
		for (Map.Entry<Integer, Long> e : source.entrySet())
		{
			add(e.getKey(), e.getValue());
		}
	}

	/** Quantity of an item, or 0. */
	public long get(int itemId)
	{
		Long q = quantities.get(itemId);
		return q == null ? 0 : q;
	}

	public boolean isEmpty()
	{
		return quantities.isEmpty();
	}

	/** Number of distinct items. */
	public int size()
	{
		return quantities.size();
	}

	/** Item ids in ascending order (read-only view). */
	public Set<Integer> itemIds()
	{
		return Collections.unmodifiableSet(quantities.keySet());
	}

	public void clear()
	{
		quantities.clear();
	}

	/**
	 * The JSON form: a new, sorted, mutable map, or {@code null} when the tally is empty (so records and snapshots
	 * without items omit the field).
	 */
	public Map<Integer, Long> toMap()
	{
		return quantities.isEmpty() ? null : new TreeMap<>(quantities);
	}

	private static long saturatedAdd(long a, long b)
	{
		long sum = a + b;
		return sum < 0 ? Long.MAX_VALUE : sum;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Pure item valuation: captures per-item unit prices through a {@link PriceLookup} and totals a tally against them.
 * No RuneLite dependencies; the plugin supplies a lookup backed by {@code ItemManager} on the client thread.
 *
 * <p>Rules (matching how core RuneLite values loot in 1.13.3):</p>
 * <ul>
 *     <li>Coins are valued at face value (1 gp each) for both GE and high alchemy, and platinum tokens at 1,000 gp.
 *     {@code ItemManager#getItemPrice} already does this for GE; it is applied here for high alchemy too, because the
 *     coin item's own high-alchemy value is not its face value.</li>
 *     <li>Prices are looked up by the canonical id ({@link PriceLookup#canonicalize}, which un-notes noted items), so
 *     a noted drop is valued like the unnoted item. Unit prices are keyed by the id as tallied.</li>
 *     <li>A GE price is <em>unavailable</em> when the lookup throws, or when a tradeable item's GE price is 0 or
 *     less. {@code ItemManager} (1.13.3) has no "prices loaded" flag: until its price list has been fetched, and for
 *     an item missing from it, {@code getItemPrice} simply returns 0, the same as for an untradeable item. So a
 *     tradeable item at 0 is treated as unavailable rather than worthless. An unavailable GE price is left out of
 *     {@link UnitPrices#getGe()} (and recorded in {@link UnitPrices#getGeMissing()}), so it can be told apart from a
 *     real 0. An untradeable item with no GE price is a known 0.</li>
 *     <li>A high-alchemy value of 0 or less is a known 0; it is unavailable only when the lookup throws.</li>
 *     <li>Totals sum the known prices; {@link #countUnpriced} tells how many items of a tally were left out.</li>
 * </ul>
 */
final class ItemValuation
{
	/** {@code net.runelite.api.gameval.ItemID.COINS} (1.13.3). */
	static final int COINS = 995;
	/** {@code net.runelite.api.gameval.ItemID.PLATINUM} (1.13.3). */
	static final int PLATINUM = 13204;
	static final long PLATINUM_VALUE = 1000L;

	/**
	 * Price source. Implementations may only be valid on a particular thread (the plugin's runs on the client thread).
	 */
	interface PriceLookup
	{
		/** The id to price: the unnoted id for a noted item, otherwise the id itself. */
		int canonicalize(int itemId);

		/** Grand Exchange unit price of a canonical id, or 0 / negative when unknown. */
		long gePrice(int canonicalId);

		/**
		 * Whether a canonical id can be traded on the Grand Exchange; a tradeable item without a GE price has an
		 * unavailable price rather than a value of 0.
		 */
		boolean isTradeable(int canonicalId);

		/** High-alchemy unit value of a canonical id, or 0 / negative when unknown. */
		long haPrice(int canonicalId);
	}

	/** Unit prices for a set of items, keyed by the id as tallied. */
	@Getter
	static final class UnitPrices
	{
		/** GE unit prices of the ids whose price was available. */
		private final Map<Integer, Long> ge = new TreeMap<>();
		/** High-alchemy unit values of the ids whose value was available. */
		private final Map<Integer, Long> ha = new TreeMap<>();
		/** Ids looked up whose GE price was unavailable (absent from {@link #getGe()}). */
		private final Set<Integer> geMissing = new TreeSet<>();
	}

	private ItemValuation()
	{
	}

	/**
	 * Adds the GE and high-alchemy unit price of every item in the tally to {@code into}. Items already present are
	 * looked up again; an item whose GE price is unavailable (see the class rules) is removed from the GE prices and
	 * added to {@link UnitPrices#getGeMissing()}, and likewise for a high-alchemy lookup that throws.
	 */
	static void capturePrices(ItemTally tally, PriceLookup lookup, UnitPrices into)
	{
		if (tally == null)
		{
			return;
		}
		for (int id : tally.itemIds())
		{
			capturePrice(id, lookup, into);
		}
	}

	/** Looks up one id's prices into {@code into}, as {@link #capturePrices(ItemTally, PriceLookup, UnitPrices)}. */
	static void capturePrice(int id, PriceLookup lookup, UnitPrices into)
	{
		Long ge = null;
		Long ha = null;
		try
		{
			int canonical = lookup.canonicalize(id);
			if (canonical == COINS)
			{
				ge = 1L;
				ha = 1L;
			}
			else if (canonical == PLATINUM)
			{
				ge = PLATINUM_VALUE;
				ha = PLATINUM_VALUE;
			}
			else
			{
				ge = gePrice(canonical, lookup);
				ha = haPrice(canonical, lookup);
			}
		}
		catch (RuntimeException e)
		{
			// Unknown item definition; both prices are unavailable.
		}
		if (ge != null)
		{
			into.getGe().put(id, ge);
			into.getGeMissing().remove(id);
		}
		else
		{
			into.getGe().remove(id);
			into.getGeMissing().add(id);
		}
		if (ha != null)
		{
			into.getHa().put(id, ha);
		}
		else
		{
			into.getHa().remove(id);
		}
	}

	/** The GE price, 0 for an untradeable item without one, or {@code null} when unavailable. */
	private static Long gePrice(int canonical, PriceLookup lookup)
	{
		try
		{
			long price = lookup.gePrice(canonical);
			if (price > 0)
			{
				return price;
			}
			return lookup.isTradeable(canonical) ? null : 0L;
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/** The high-alchemy value (at least 0), or {@code null} when the lookup fails. */
	private static Long haPrice(int canonical, PriceLookup lookup)
	{
		try
		{
			return Math.max(0, lookup.haPrice(canonical));
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * Number of distinct items in {@code tally} without an entry in {@code unitPrices} (their price was unavailable),
	 * or 0 when the tally is empty. Every item counts as unpriced when {@code unitPrices} is {@code null}.
	 */
	static int countUnpriced(ItemTally tally, Map<Integer, Long> unitPrices)
	{
		if (tally == null)
		{
			return 0;
		}
		int count = 0;
		for (int id : tally.itemIds())
		{
			if (unitPrices == null || !unitPrices.containsKey(id))
			{
				count++;
			}
		}
		return count;
	}

	/**
	 * Total value of a tally at the given unit prices. Items without a price are left out (count as 0); the total
	 * saturates at {@link Long#MAX_VALUE}.
	 */
	static long total(ItemTally tally, Map<Integer, Long> unitPrices)
	{
		return total(tally, unitPrices, null);
	}

	/**
	 * Total value of a tally whose quantities are in doses for some items: for an id with an entry {@code n} in
	 * {@code dosesPerItem}, the quantity counts doses and each is worth {@code unitPrice / n} (the id's price is for one
	 * {@code n}-dose item). The per-item product is rounded to the nearest gp. Other items are valued as in
	 * {@link #total(ItemTally, Map)}.
	 */
	static long total(ItemTally tally, Map<Integer, Long> unitPrices, Map<Integer, Integer> dosesPerItem)
	{
		if (tally == null || unitPrices == null)
		{
			return 0;
		}
		long total = 0;
		for (int id : tally.itemIds())
		{
			Long price = unitPrices.get(id);
			if (price == null || price <= 0)
			{
				continue;
			}
			Integer doses = dosesPerItem == null ? null : dosesPerItem.get(id);
			try
			{
				long value = Math.multiplyExact(price, tally.get(id));
				if (doses != null && doses > 1)
				{
					value = value / doses + (value % doses * 2 >= doses ? 1 : 0);
				}
				total = Math.addExact(total, value);
			}
			catch (ArithmeticException e)
			{
				return Long.MAX_VALUE;
			}
		}
		return total;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * The Slayer keys and clue scrolls among a task's loot: brimstone keys (Konar), Larran's keys (Krystilia's Wilderness
 * tasks) and clue scrolls by tier. Derived from the loot tally ({@link LedgerRecord#getLoot()}, or the session's
 * loot), so it follows the loot's rules (only loot received while the session was running, after the bonecrusher and
 * "Ignored loot" filters) and older records with loot get counts too. Nothing extra is stored. Immutable; pure (no
 * RuneLite types).
 *
 * <p>Ids are those of {@code net.runelite.api.gameval.ItemID} in RuneLite API 1.13.4 ({@code KeysAndCluesTest} checks
 * them against it). Besides each key's own id, the ids the game lists under the same name (its stack-size display
 * variants) are counted too, in case loot ever reports one. Clue scroll ids are in {@link ClueScrollIds}.</p>
 */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
final class KeysAndClues
{
	/** Clue scroll tiers, in display order. */
	@AllArgsConstructor
	enum ClueTier
	{
		BEGINNER("beginner", ClueScrollIds.BEGINNER),
		EASY("easy", ClueScrollIds.EASY),
		MEDIUM("medium", ClueScrollIds.MEDIUM),
		HARD("hard", ClueScrollIds.HARD),
		ELITE("elite", ClueScrollIds.ELITE),
		MASTER("master", ClueScrollIds.MASTER);

		private final String displayName;
		private final int[] itemIds;

		@Override
		public String toString()
		{
			return displayName;
		}
	}

	/**
	 * Brimstone key: {@code ItemID.KONAR_KEY} (23083) and its {@code KONAR_KEY_COUNTVIEW1}..{@code 6} variants
	 * (23085-23090).
	 */
	static final int[] BRIMSTONE_KEY_IDS = {23083, 23085, 23086, 23087, 23088, 23089, 23090};
	/**
	 * Larran's key: {@code ItemID.SLAYER_WILDERNESS_KEY} (23490) and its {@code SLAYER_WILDERNESS_KEY_2}, {@code _4}
	 * and {@code _5} variants (23492-23494).
	 */
	static final int[] LARRANS_KEY_IDS = {23490, 23492, 23493, 23494};

	static final KeysAndClues NONE = new KeysAndClues(0, 0, new long[ClueTier.values().length]);

	/** What each counted id is: a {@link ClueTier}, or {@link #BRIMSTONE} / {@link #LARRAN} for keys. */
	private static final Map<Integer, Object> KINDS = new HashMap<>();
	private static final Object BRIMSTONE = new Object();
	private static final Object LARRAN = new Object();

	static
	{
		for (int id : BRIMSTONE_KEY_IDS)
		{
			KINDS.put(id, BRIMSTONE);
		}
		for (int id : LARRANS_KEY_IDS)
		{
			KINDS.put(id, LARRAN);
		}
		for (ClueTier tier : ClueTier.values())
		{
			for (int id : tier.itemIds)
			{
				KINDS.put(id, tier);
			}
		}
	}

	private final long brimstoneKeys;
	private final long larransKeys;
	/** Clue scrolls by {@link ClueTier#ordinal()}. */
	private final long[] clues;

	/** The keys and clue scrolls in {@code loot} (item id to quantity); {@link #NONE} for {@code null}. */
	static KeysAndClues of(Map<Integer, Long> loot)
	{
		if (loot == null || loot.isEmpty())
		{
			return NONE;
		}
		long brimstone = 0;
		long larran = 0;
		long[] clues = new long[ClueTier.values().length];
		for (Map.Entry<Integer, Long> e : loot.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null || e.getValue() <= 0)
			{
				continue;
			}
			Object kind = KINDS.get(e.getKey());
			if (kind == BRIMSTONE)
			{
				brimstone = saturatedAdd(brimstone, e.getValue());
			}
			else if (kind == LARRAN)
			{
				larran = saturatedAdd(larran, e.getValue());
			}
			else if (kind instanceof ClueTier)
			{
				int i = ((ClueTier) kind).ordinal();
				clues[i] = saturatedAdd(clues[i], e.getValue());
			}
		}
		return new KeysAndClues(brimstone, larran, clues);
	}

	/** The keys and clue scrolls in {@code loot}; {@link #NONE} for {@code null}. */
	static KeysAndClues of(ItemTally loot)
	{
		return loot == null ? NONE : of(loot.toMap());
	}

	boolean hasKeys()
	{
		return brimstoneKeys > 0 || larransKeys > 0;
	}

	boolean hasClues()
	{
		return Arrays.stream(clues).anyMatch(n -> n > 0);
	}

	/** {@code Keys: 2 brimstone, 1 Larran's}, leaving out a kind with none; {@code null} when there are no keys. */
	String keysText()
	{
		List<String> parts = new ArrayList<>();
		if (brimstoneKeys > 0)
		{
			parts.add(brimstoneKeys + " brimstone");
		}
		if (larransKeys > 0)
		{
			parts.add(larransKeys + " Larran's");
		}
		return parts.isEmpty() ? null : "Keys: " + String.join(", ", parts);
	}

	/** {@code Clues: 1 hard, 2 elite}, lowest tier first, leaving out tiers with none; {@code null} when none. */
	String cluesText()
	{
		List<String> parts = new ArrayList<>();
		for (ClueTier tier : ClueTier.values())
		{
			long n = clues[tier.ordinal()];
			if (n > 0)
			{
				parts.add(n + " " + tier);
			}
		}
		return parts.isEmpty() ? null : "Clues: " + String.join(", ", parts);
	}

	private static long saturatedAdd(long a, long b)
	{
		long r = a + b;
		return ((a ^ r) & (b ^ r)) < 0 ? Long.MAX_VALUE : r;
	}
}

package com.shmayvan.slayerledger;

import java.util.regex.*;
import lombok.*;

/**
 * Recognises the game's kill count chat messages, such as {@code Your Vorkath kill count is: <col=ff0000>152</col>.}
 * Pure (no RuneLite types).
 *
 * <p>The pattern is core ChatCommandsPlugin's {@code KILLCOUNT_PATTERN} (RuneLite 1.13.4), matched the same way (on the
 * message with its colour tags, anywhere in it) for the same chat types (game, spam, trade and friends chat
 * notification messages). As in core, the count must be coloured ({@code <col=...>} or {@code @...@}, closed by
 * {@code </col>}), and a message with neither a prefix nor a count word ({@code Your X is: ...}) is not a kill count.
 * The boss name may be coloured too; its tags are removed.</p>
 *
 * <p>Core's pattern also matches counts that are not boss kills: raids and other completions ({@code completed},
 * {@code completion count for}, {@code completion count}), {@code subdued} (Wintertodt), {@code harvest} (Herbiboar),
 * {@code lap} (agility courses), {@code success} and {@code Total Ticket} counts. Those parse with
 * {@link Result#isBossKill()} {@code false}. Only {@code <boss> kill count is:} and the bare {@code <boss> count is:}
 * (for example {@code Your Barrows chest count is:}) are boss kills.</p>
 */
final class KillCountMessage
{
	/** Core ChatCommandsPlugin's KILLCOUNT_PATTERN (RuneLite 1.13.4), unchanged. */
	static final Pattern KILLCOUNT_PATTERN = Pattern.compile("Your (?<pre>completion count for |subdued |completed )?"
		+ "(?:<col=[0-9a-f]{6}>)?(?<boss>.+?)(?:</col>)? (?<post>(?:(?:kill|harvest|lap|completion|success|Total Ticket) )?"
		+ "(?:count )?)is: ?(?:<col=[0-9a-f]{6}>|@.+?@)(?<kc>[0-9,]+)</col>");

	private static final String KILL_COUNT = "kill count ";
	private static final String COUNT = "count ";

	private KillCountMessage()
	{
	}

	/** A recognised kill count message. */
	@Getter
	@EqualsAndHashCode
	@ToString
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	static final class Result
	{
		/** The name the message gives, without colour tags, for example {@code Vorkath} or {@code Barrows chest}. */
		private final String boss;
		/** The count the message gives (at least 0). */
		private final int kc;
		/** Whether it counts a boss kill ({@code kill count} or bare {@code count}), rather than a lap, raid and so on. */
		private final boolean bossKill;
	}

	/**
	 * What a chat message says about a kill count, or {@code null} when it is not a kill count message.
	 *
	 * @param kcMessageType whether the message type is one core checks: GAMEMESSAGE, SPAM, TRADE or
	 *                      FRIENDSCHATNOTIFICATION
	 * @param message       the message text, with its tags
	 */
	static Result parse(boolean kcMessageType, String message)
	{
		if (!kcMessageType || message == null)
		{
			return null;
		}
		final Matcher matcher = KILLCOUNT_PATTERN.matcher(message);
		if (!matcher.find())
		{
			return null;
		}
		final String pre = matcher.group("pre");
		final String post = matcher.group("post");
		final boolean hasPre = pre != null && !pre.isEmpty();
		final boolean hasPost = post != null && !post.isEmpty();
		if (!hasPre && !hasPost)
		{
			// Core ignores these too ("Your X is: n").
			return null;
		}
		final String boss = BossKillCounts.cleanName(matcher.group("boss"));
		final Integer kc = parseCount(matcher.group("kc"));
		if (boss.isEmpty() || kc == null)
		{
			return null;
		}
		final boolean bossKill = !hasPre && (KILL_COUNT.equals(post) || COUNT.equals(post));
		return new Result(boss, kc, bossKill);
	}

	/** A count such as {@code 1,130}, or {@code null} when it has no digits or is too large. */
	private static Integer parseCount(String text)
	{
		final String digits = text.replace(",", "");
		if (digits.isEmpty() || digits.length() > 10)
		{
			return null;
		}
		final long value = Long.parseLong(digits);
		return value > Integer.MAX_VALUE ? null : (int) value;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * What the plugin knows about a task kill (a drop of the Slayer count, or a bracelet of slaughter's activation) from
 * the NPCs the player damaged that died around it ({@link DamagedNpcs#pairing}, V2 plan 4.1): the earliest engagement
 * start among them, which is where a (re)start of the session is backdated to, and their names, which become the
 * session's known task NPCs. Also whether a kill may start a new session now, and when the kill's game tick began
 * ({@link #getTickStart()}): the plugin reads that tick's XP just before it sees the kill, so a (re)start counts it.
 * Pure and immutable.
 */
@Getter
@AllArgsConstructor(access = AccessLevel.PRIVATE)
final class KillPairing
{
	/** {@link #getEarliestStart()} when no damaged NPC died around the kill (for example a cannon-only kill). */
	static final long NO_START = Long.MAX_VALUE;

	/** Nothing paired; a kill may start a session; its tick's start unknown. */
	static final KillPairing NONE = new KillPairing(NO_START, Collections.emptySet(), true, NO_START);

	/** The earliest engagement start of the paired NPCs (clock millis), or {@link #NO_START}. */
	private final long earliestStart;
	/** The paired NPCs' names as the game gives them (unmodifiable, possibly empty). */
	private final Set<String> names;
	/** Whether a kill may start a new session now (see {@link #withStartBlocked()}). */
	private final boolean startAllowed;
	/** When the kill's game tick began (see {@link #withTickStart}), or {@link #NO_START} when not known. */
	private final long tickStart;

	/**
	 * A pairing of NPCs whose earliest engagement started at {@code earliestStart} ({@link #NO_START} for none), with
	 * the given NPC names ({@code null} entries are left out).
	 */
	static KillPairing of(long earliestStart, Collection<String> names)
	{
		final Set<String> kept = new LinkedHashSet<>();
		if (names != null)
		{
			for (String name : names)
			{
				if (name != null)
				{
					kept.add(name);
				}
			}
		}
		return new KillPairing(earliestStart, Collections.unmodifiableSet(kept), true, NO_START);
	}

	/**
	 * This pairing, except that a kill may not start a new session now: the plugin is still checking for a session to
	 * restore, which a new session would block. A session that exists still restarts.
	 */
	KillPairing withStartBlocked()
	{
		return startAllowed ? new KillPairing(earliestStart, names, false, tickStart) : this;
	}

	/**
	 * This pairing, for a kill seen on a game tick that began at {@code tickStart} (clock millis, read before that
	 * tick's supplies and XP): a (re)start at the kill counts what the buffer holds from that tick on, the kill's own XP
	 * included, even when nothing is paired (V2 plan 4.1).
	 */
	KillPairing withTickStart(long tickStart)
	{
		return new KillPairing(earliestStart, names, startAllowed, tickStart);
	}

	/** Whether any paired NPC's engagement start is known. */
	boolean hasStart()
	{
		return earliestStart != NO_START;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * Where the local player stood when the task count was read (V2 plan 4.5): the map region and the Slayer spot of
 * the player's tile ({@link SlayerSpots#spotAt}), instances as their template. Kills counted on that reading are
 * tallied there ({@link LocationTally}). Immutable and pure (no RuneLite types).
 */
@Getter
@EqualsAndHashCode
@ToString
@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
final class KillPlace
{
	/** No place known: no player or scene, or the player is on a Sailing boat. */
	static final KillPlace NONE = new KillPlace(LocationTally.NO_REGION, null);

	/** Map region id, or {@link LocationTally#NO_REGION}. */
	private final int region;
	/**
	 * The spot key of the tile ({@link SlayerSpots}: a table id or {@code region:N}), or {@code null} when it is
	 * decided from the region alone ({@link SlayerSpots#spotForRegion}), as for a tile in a shared region that no spot
	 * of it matches.
	 */
	private final String spot;

	/** A place known only by its region, whose spot is decided from the region ({@link SlayerSpots#spotForRegion}). */
	static KillPlace ofRegion(int region)
	{
		return LocationTally.isRegion(region) ? new KillPlace(region, null) : NONE;
	}

	/** The place of tile {@code (x, y)} on {@code plane}: its region and its spot in {@code spots}. */
	static KillPlace at(SlayerSpots spots, int x, int y, int plane)
	{
		final int region = SlayerSpots.regionOf(x, y);
		if (!LocationTally.isRegion(region))
		{
			return NONE;
		}
		return new KillPlace(region, spots == null ? null : spots.spotAt(x, y, plane));
	}

	/** Whether a region is known. */
	boolean isKnown()
	{
		return LocationTally.isRegion(region);
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import net.runelite.client.util.*;

/**
 * The number rules of docs/DESIGN_PRINCIPLES.md 5.5, for the redesigned sidebar and overlay: gp and XP,
 * signed profit, kills, the running clock, pace, rates and the time left. Pure. The live task card, the advisor card,
 * Overall totals and the overlay use them. The live card's time left stays {@link LedgerHistory#formatTimeLeft(long, int, int, Long)} ({@code ~38m},
 * {@code ~9h 59m}), which fits the card's columns; the overlay's is {@link #timeLeft} ({@code ~38 min}), the same
 * estimate in the 5.5 form.
 */
final class LedgerFormat
{
	/** Shown for a value that does not apply, such as the time left with no kills left. */
	static final String NONE = LedgerHistory.NO_VALUE;
	/** Shown for a value not known yet, such as the pace before enough kills: {@code ?}. */
	static final String UNKNOWN = "?";
	/** Marks an approximate value: some prices were not loaded. Comes before any sign. */
	static final String APPROXIMATE = LedgerHistory.APPROXIMATE;

	private LedgerFormat()
	{
	}

	/**
	 * gp or XP: in full with commas under 10,000, then at most 3 significant figures with K, M or B and no trailing
	 * zeros ({@code 950}, {@code 1,235}, {@code 12.4K}, {@code 477K}, {@code 1.24M}, {@code 2.1B}; {@code 10K} for
	 * 10,050, {@code 1M} for 1,005,000, {@code 1.5M} for 1,500,000), as RuneLite's
	 * {@link QuantityFormatter#quantityToStackSize} shows stacks but without the zeros it leaves after the point. A
	 * negative amount has a hyphen.
	 */
	static String amount(long value)
	{
		String text = QuantityFormatter.quantityToStackSize(value);
		int suffix = text.length() - 1;
		if (Character.isDigit(text.charAt(suffix)) || text.indexOf('.') < 0)
		{
			return text;
		}
		int end = suffix;
		while (text.charAt(end - 1) == '0')
		{
			end--;
		}
		if (text.charAt(end - 1) == '.')
		{
			end--;
		}
		return text.substring(0, end) + text.charAt(suffix);
	}

	/** {@link #amount}, with {@link #APPROXIMATE} first when {@code approximate}; {@link #NONE} for {@code null}. */
	static String amount(Long value, boolean approximate)
	{
		return value == null ? NONE : (approximate ? APPROXIMATE : "") + amount(value.longValue());
	}

	/**
	 * A profit or other change: always signed except zero ({@code +212K}, {@code -38K}, {@code 0}), with
	 * {@link #APPROXIMATE} before the sign when {@code approximate} ({@code ~+212K}); {@link #NONE} for {@code null}.
	 */
	static String signed(Long value, boolean approximate)
	{
		if (value == null)
		{
			return NONE;
		}
		long v = value;
		return (approximate ? APPROXIMATE : "") + (v > 0 ? "+" : "") + amount(v);
	}

	/** Kills: a whole number with commas ({@code 1,412}). */
	static String kills(long kills)
	{
		return QuantityFormatter.formatNumber(kills);
	}

	/** Kills done of the task's total, with spaces: {@code 73 / 201}. */
	static String progress(long done, long total)
	{
		return kills(done) + " / " + kills(total);
	}

	/** A running clock: m:ss under an hour, then h:mm:ss ({@code 21:54}, {@code 1:03:31}). A negative time is 0. */
	static String clock(long millis)
	{
		long seconds = Math.max(0, millis) / 1000;
		long hours = seconds / 3600;
		if (hours > 0)
		{
			return String.format(Locale.ROOT, "%d:%02d:%02d", hours, (seconds / 60) % 60, seconds % 60);
		}
		return String.format(Locale.ROOT, "%d:%02d", seconds / 60, seconds % 60);
	}

	/**
	 * A completed duration in text (5.5), such as a saved task's active time on its Task history row: whole minutes,
	 * rounded half up, {@code 52 min}, from an hour {@code 1 h 1 min}, on the hour {@code 2 h}; {@code <1 min} for less
	 * than half a minute and {@code 0 min} for none.
	 */
	static String duration(long millis)
	{
		if (millis <= 0)
		{
			return minutes(0);
		}
		long minutes = millis / 60_000 + (millis % 60_000 >= 30_000 ? 1 : 0);
		return minutes == 0 ? "<" + minutes(1) : minutes(minutes);
	}

	/** Whole minutes in text (5.5): {@code 54 min}, from an hour {@code 1 h 6 min}, on the hour {@code 2 h}. */
	static String minutes(long minutes)
	{
		if (minutes < 60)
		{
			return minutes + " min";
		}
		final long rest = minutes % 60;
		return minutes / 60 + " h" + (rest == 0 ? "" : " " + rest + " min");
	}

	/** Pace: the time per kill as m:ss per kill, rounded to whole seconds (half up): {@code 0:18/kill}. */
	static String pace(long millisPerKill)
	{
		long clamped = Math.max(0, millisPerKill);
		long seconds = clamped / 1000 + (clamped % 1000 >= 500 ? 1 : 0);
		return String.format(Locale.ROOT, "%d:%02d/kill", seconds / 60, seconds % 60);
	}

	/**
	 * The time left on a task (5.5's estimated time, {@link TaskPlanText#estimatedTime}): {@code ~38 min}, from an hour
	 * {@code ~1 h 5 min}. The estimate is {@link LedgerHistory#formatTimeLeft(long, int, int, Long)}'s: the session's
	 * pace once it has enough kills and time ({@link TaskTimeEstimate}), until then the history's time per kill when
	 * there is one. {@link #UNKNOWN} while neither gives one; {@link #NONE} with no kills left.
	 *
	 * @param historicalMillisPerKill the task's time per kill in its completed history, or {@code null} without one
	 */
	static String timeLeft(long activeMillis, int kills, int remaining, Long historicalMillisPerKill)
	{
		if (remaining <= 0)
		{
			return NONE;
		}
		final OptionalLong estimate = TaskTimeEstimate.remainingMillis(activeMillis, kills, remaining);
		if (estimate.isPresent())
		{
			return TaskPlanText.estimatedTime(estimate.getAsLong());
		}
		return historicalMillisPerKill == null ? UNKNOWN
			: TaskPlanText.estimatedTime(LedgerHistory.historicalTimeLeftMillis(historicalMillisPerKill, remaining));
	}

	/** A rate per hour without its unit, for a value under a {@code .../h} label: {@link #amount} of it, rounded. */
	static String perHour(double perHour)
	{
		return amount(Math.round(Math.max(0, perHour)));
	}
}

package com.shmayvan.slayerledger;

import java.time.*;
import java.time.format.*;
import java.util.*;
import net.runelite.client.util.*;

/**
 * Pure sorting, filtering and formatting for the task-history view and the live session values. No Swing, client
 * or file access (only RuneLite's static {@link QuantityFormatter}), so it can be unit-tested and called from any
 * thread.
 */
final class LedgerHistory
{
	/** Label of the filter entry that shows every monster. */
	static final String ALL = "All";
	static final String UNKNOWN_MONSTER = "Unknown task";
	/** Shown instead of a value that was never recorded (tasks saved before values were tracked). */
	static final String NO_VALUE = "-";
	/** The status word of a task saved before it was finished; the only status a Task history row names. */
	static final String PARTIAL = "Partial";
	/** The tooltip line that explains {@link #PARTIAL}. */
	static final String PARTIAL_NOTE = "Partial: saved before the task was finished";
	/** Prefix of a total that leaves out items whose GE price was unavailable. */
	static final String APPROXIMATE = "~";
	/** Time left until a session has enough kills and active time for an estimate ({@link #formatTimeLeft}). */
	static final String TIME_LEFT_ESTIMATING = "estimating...";
	/** Tooltip text for a task saved before loot and supply values were tracked. */
	static final String NOT_VALUED = "Not valued: this task was saved before loot and supply values were tracked.";
	/** Tooltip line of a history row valued at today's GE prices. */
	static final String CURRENT_PRICES = "Prices: today's GE prices (high alch values don't change)";
	/** Tooltip line of a history row saved without per-item prices, which keeps its saved totals. */
	static final String SAVED_TOTALS = "Prices: saved totals (no items kept), so GE values are marked ~";

	/** Newest first by end time; ties broken by start time (newest first), then id, for a stable order. */
	static final Comparator<LedgerRecord> NEWEST_FIRST = Comparator
		.comparingLong(LedgerRecord::getEndedAt).reversed()
		.thenComparing(Comparator.comparingLong(LedgerRecord::getStartedAt).reversed())
		.thenComparing(r -> r.getId() == null ? "" : r.getId());

	private LedgerHistory()
	{
	}

	/**
	 * Name shown for a record, and what the Monster filter matches: its {@link LedgerRecord#groupName} (the Catacombs
	 * variant for a task done on one); records without a name (very old or hand-edited files) show a fallback.
	 */
	static String monster(LedgerRecord record)
	{
		String monster = record.groupName();
		return monster == null || monster.isEmpty() ? UNKNOWN_MONSTER : monster;
	}

	/** Copy of {@code records} without nulls, newest first. */
	static List<LedgerRecord> sortNewestFirst(Collection<LedgerRecord> records)
	{
		List<LedgerRecord> sorted = new ArrayList<>(records.size());
		for (LedgerRecord r : records)
		{
			if (r != null)
			{
				sorted.add(r);
			}
		}
		sorted.sort(NEWEST_FIRST);
		return sorted;
	}

	/** Filter choices: {@link #ALL} followed by each distinct monster in the records, alphabetically (ignoring case). */
	static List<String> filterOptions(Collection<LedgerRecord> records)
	{
		TreeSet<String> names = new TreeSet<>(Comparator.comparing((String s) -> s.toLowerCase(Locale.ROOT)).thenComparing(s -> s));
		for (LedgerRecord r : records)
		{
			if (r != null)
			{
				names.add(monster(r));
			}
		}
		List<String> options = new ArrayList<>(names.size() + 1);
		options.add(ALL);
		options.addAll(names);
		return options;
	}

	/**
	 * The filter selection to keep after the options change: {@code selection} while it is still one of the monster
	 * options, otherwise {@code null} ("All").
	 */
	static String keepSelection(List<String> options, String selection)
	{
		return selection != null && !ALL.equals(selection) && options.contains(selection) ? selection : null;
	}

	/** "kills / originalAmount" when the assigned amount is known, otherwise just the kills. */
	static String formatKills(LedgerRecord record)
	{
		Integer original = record.getOriginalAmount();
		if (original != null && original > 0)
		{
			return record.getKills() + " / " + original;
		}
		return Integer.toString(record.getKills());
	}

	/** Active time as H:MM:SS. */
	static String formatDuration(long millis)
	{
		long totalSeconds = Math.max(0, millis) / 1000;
		return String.format("%d:%02d:%02d", totalSeconds / 3600, (totalSeconds / 60) % 60, totalSeconds % 60);
	}

	/**
	 * A time per kill in short form, rounded to whole seconds (half up): {@code 18s} under a minute,
	 * {@code 4m 05s} under an hour and {@code 1h 02m} from an hour on (minutes rounded half up). A negative time counts
	 * as none ({@code 0s}). Task lengths and elapsed time keep {@link #formatDuration}.
	 */
	static String formatKillTime(long millis)
	{
		long clamped = Math.max(0, millis);
		long seconds = clamped / 1000 + (clamped % 1000 >= 500 ? 1 : 0);
		if (seconds < 60)
		{
			return seconds + "s";
		}
		if (seconds < 3600)
		{
			return String.format("%dm %02ds", seconds / 60, seconds % 60);
		}
		// Minutes from the exact time, not the rounded seconds, so a time is rounded only once.
		long minutes = clamped / 60_000 + (clamped % 60_000 >= 30_000 ? 1 : 0);
		return String.format("%dh %02dm", minutes / 60, minutes % 60);
	}

	/**
	 * Estimated time left, rounded to the nearest whole minute (half up), without seconds: {@code ~44m} under an hour,
	 * {@code ~1h 05m} from an hour on, and {@code ~<1m} when it rounds to no minutes. A negative time counts as none;
	 * the saturated {@link Long#MAX_VALUE} of {@link #historicalTimeLeftMillis} formats without overflowing.
	 */
	static String formatTimeLeftMinutes(long millis)
	{
		long clamped = Math.max(0, millis);
		long minutes = clamped / 60_000 + (clamped % 60_000 >= 30_000 ? 1 : 0);
		if (minutes == 0)
		{
			return "~<1m";
		}
		if (minutes < 60)
		{
			return "~" + minutes + "m";
		}
		return String.format("~%dh %02dm", minutes / 60, minutes % 60);
	}

	/**
	 * Estimated time left on the task, in whole minutes ({@link #formatTimeLeftMinutes}): at the session's pace so far
	 * (see {@link TaskTimeEstimate}); until there are enough kills and active time for that, at the historical time per
	 * kill when there is one ({@link #historicalTimeLeftMillis}), else {@link #TIME_LEFT_ESTIMATING}; or
	 * {@link #NO_VALUE} when no kills are left on the task (no task, the task is done, or the kills left are unknown).
	 * The sidebar and the overlay both show it, so they can't disagree.
	 *
	 * @param historicalMillisPerKill the task's average active time per kill in its completed history
	 *                                ({@link TaskStatistics#getMillisPerKill}), or {@code null} when it has none
	 */
	static String formatTimeLeft(long activeMillis, int kills, int remaining, Long historicalMillisPerKill)
	{
		if (remaining <= 0)
		{
			return NO_VALUE;
		}
		OptionalLong estimate = TaskTimeEstimate.remainingMillis(activeMillis, kills, remaining);
		if (estimate.isPresent())
		{
			return formatTimeLeftMinutes(estimate.getAsLong());
		}
		return historicalMillisPerKill == null ? TIME_LEFT_ESTIMATING
			: formatTimeLeftMinutes(historicalTimeLeftMillis(historicalMillisPerKill, remaining));
	}

	/**
	 * Whether {@link #formatTimeLeft(long, int, int, Long)} shows the historical estimate for these values (rather than
	 * the live pace, {@link #TIME_LEFT_ESTIMATING} or {@link #NO_VALUE}).
	 */
	static boolean isHistoricalTimeLeft(long activeMillis, int kills, int remaining, Long historicalMillisPerKill)
	{
		return remaining > 0 && historicalMillisPerKill != null
			&& !TaskTimeEstimate.remainingMillis(activeMillis, kills, remaining).isPresent();
	}

	/** The historical time left: {@code millisPerKill * remaining}, saturated at {@link Long#MAX_VALUE}. */
	static long historicalTimeLeftMillis(long millisPerKill, int remaining)
	{
		try
		{
			return Math.multiplyExact(millisPerKill, (long) remaining);
		}
		catch (ArithmeticException e)
		{
			return millisPerKill >= 0 == remaining >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** Short, locale-style date/time formatter in the given zone (the system zone in the panel). */
	static DateTimeFormatter shortDateTime(ZoneId zone)
	{
		return DateTimeFormatter.ofLocalizedDateTime(FormatStyle.SHORT).withZone(zone);
	}

	/**
	 * Short, locale-style date formatter (no time) in the given zone: the date on a Task history row,
	 * whose tooltip has the time too ({@link #shortDateTime}).
	 */
	static DateTimeFormatter shortDate(ZoneId zone)
	{
		return DateTimeFormatter.ofLocalizedDate(FormatStyle.SHORT).withZone(zone);
	}

	/** End time formatted with {@code formatter}, or "-" when the record has no end time. */
	static String formatEndedAt(LedgerRecord record, DateTimeFormatter formatter)
	{
		long endedAt = record.getEndedAt();
		if (endedAt <= 0)
		{
			return "-";
		}
		return formatter.format(Instant.ofEpochMilli(endedAt));
	}

	/** Text of the delete confirmation dialog. */
	static String deleteConfirmation(LedgerRecord record)
	{
		return String.format("Delete this %s task (%d kills)? This can't be undone.", monster(record), record.getKills());
	}

	// ---- Values ----

	/** Compact gp amount as in core Loot Tracker ({@code QuantityFormatter}, e.g. "9,450 gp", "350K gp", "1.23M gp"). */
	static String formatGp(long value)
	{
		return LedgerFormat.amount(value) + " gp";
	}

	/**
	 * Compact gp amount, {@link #NO_VALUE} when {@code value} is {@code null} (never "0"), prefixed with
	 * {@link #APPROXIMATE} when {@code approximate}.
	 */
	static String formatGp(Long value, boolean approximate)
	{
		if (value == null)
		{
			return NO_VALUE;
		}
		return (approximate ? APPROXIMATE : "") + formatGp(value.longValue());
	}

	/**
	 * Like {@link #formatGp(Long, boolean)} without the " gp" suffix, for history rows: with the price label the loot
	 * and supplies don't fit one sidebar line otherwise.
	 */
	static String formatAmount(Long value, boolean approximate)
	{
		if (value == null)
		{
			return NO_VALUE;
		}
		return (approximate ? APPROXIMATE : "") + LedgerFormat.amount(value);
	}

	/** Full gp amount with thousands separators, for tooltips. */
	static String formatGpExact(long value)
	{
		return QuantityFormatter.formatNumber(value) + " gp";
	}

	/**
	 * Loot value minus supplies value, saturating at the {@code long} range; {@code null} when the loot was not valued.
	 * A {@code null} supplies value counts as 0 (no supplies recorded).
	 */
	static Long profit(Long loot, Long supplies)
	{
		if (loot == null)
		{
			return null;
		}
		if (supplies == null)
		{
			return loot;
		}
		try
		{
			return Math.subtractExact(loot, supplies);
		}
		catch (ArithmeticException e)
		{
			return supplies < 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** Whether a record was valued when saved; records saved before values were tracked were not. */
	static boolean isValued(LedgerRecord record)
	{
		return record.getLootGeValue() != null;
	}

	/**
	 * The record's stored loot GE value, or {@code null} when it was not valued. This is the raw saved total (an
	 * untradeable item at 0); what the history shows comes from {@link HistoryPricing}, which values a GE price of 0
	 * at high alch.
	 */
	static Long lootGe(LedgerRecord record)
	{
		return record.getLootGeValue();
	}

	/**
	 * The record's supplies GE value: the saved total, 0 for a valued record without supplies (none were used), or
	 * {@code null} when the record was not valued.
	 */
	static Long suppliesGe(LedgerRecord record)
	{
		if (record.getSuppliesGeValue() != null)
		{
			return record.getSuppliesGeValue();
		}
		return isValued(record) ? 0L : null;
	}

	/** Distinct loot items whose GE price was unavailable when the record was saved. */
	static int lootUnpriced(LedgerRecord record)
	{
		Integer n = record.getLootUnpricedItems();
		return n == null ? 0 : Math.max(0, n);
	}

	/** Distinct supply items whose GE price was unavailable when the record was saved. */
	static int suppliesUnpriced(LedgerRecord record)
	{
		Integer n = record.getSuppliesUnpricedItems();
		return n == null ? 0 : Math.max(0, n);
	}

	/** Short name of a loot price mode for the panel's value labels: "GE", or "HA" for high alchemy. */
	static String priceLabel(LootPriceMode mode)
	{
		return mode == LootPriceMode.HIGH_ALCH ? "HA" : "GE";
	}

	/** "Profit (GE): " or "Profit (HA): ", the label of a profit with the loot in {@code mode}. */
	static String profitLabel(LootPriceMode mode)
	{
		return profitName(mode) + ": ";
	}

	/** "Profit (GE)" or "Profit (HA)", the name of a profit with the loot in {@code mode} (the overlay's row label). */
	static String profitName(LootPriceMode mode)
	{
		return "Profit (" + priceLabel(mode) + ")";
	}

	/**
	 * The live session's profit amount ({@code 1.2M gp}): loot in its price mode minus supplies, approximate when
	 * either has an unavailable price. The sidebar's live profit line and the overlay both show it.
	 */
	static String formatLiveProfit(SessionValuation.Values values)
	{
		int unpriced = values.getLootValueUnpriced() + values.getSuppliesUnpriced();
		return formatGp(values.getProfit(), unpriced > 0);
	}

	/**
	 * HTML tooltip of a Task history row in look A. It starts with what the two-line row has no room
	 * for: the name in full (a long one is cut short on the row), {@link #PARTIAL_NOTE} for a partial task, when the task
	 * ended ({@code endedAt}, with the time), the exact active time ({@code Active: 1:01:05}, {@link #formatDuration}; the
	 * row shows it in whole minutes), the kills ({@link #formatKills}) and the XP with XP per hour of active time
	 * ({@link #formatXpLine}). Then the exact values ({@code values}, which also say which prices and price mode are
	 * shown), the variant, the location line ({@link TaskLocation#format}), the setup tags, the superior spawns, bank
	 * trips and deaths ({@link #NO_VALUE} when the task was saved before they were counted), the task context, the boss
	 * kill counts, keys, clue scrolls and notable drops (when there are any) and the note, if any.
	 *
	 * @param location the location to show ({@link TaskLocation#displayName}), or {@code null} for no location line
	 * @param endedAt  when the task ended, as {@link #formatEndedAt} gives it
	 */
	static String historyRowTooltip(LedgerRecord record, HistoryPricing.Values values, String location, String endedAt)
	{
		StringBuilder head = new StringBuilder(escapeHtml(monster(record)));
		if (!record.isCompleted())
		{
			head.append("<br>").append(PARTIAL_NOTE);
		}
		head.append("<br>").append(escapeHtml(endedAt))
			.append("<br>Active: ").append(formatDuration(record.getActiveMillis()))
			.append("<br>Kills: ").append(formatKills(record))
			.append("<br>").append(formatXpLine(record));
		return "<html>" + head + "<br>" + rowTooltipBody(record, values, location) + "</html>";
	}

	/**
	 * A saved task's XP with its XP per hour of active time, for a tooltip: {@code XP: 12,345 (40.1K/h)}; without the
	 * rate when the task had too little active time for one; {@code XP: -} for a task saved before XP was tracked
	 * ({@link SkillXp#totalText}).
	 */
	static String formatXpLine(LedgerRecord record)
	{
		return SkillXp.totalText(record.getXpGained(), record.getActiveMillis());
	}

	/**
	 * The values tooltip of a saved task's item lists (their sub-header values): the exact values and
	 * which prices are shown, as its row's tooltip gives them after its head, or {@link #NOT_VALUED}.
	 */
	static String valuesTooltip(HistoryPricing.Values values)
	{
		return "<html>" + (values.isValued() ? valuesTooltipBody(values) : NOT_VALUED) + "</html>";
	}

	/** {@link #historyRowTooltip}'s lines after its head, without {@code <html>} tags. */
	private static String rowTooltipBody(LedgerRecord record, HistoryPricing.Values values, String location)
	{
		String valuesText = values.isValued() ? valuesTooltipBody(values) : NOT_VALUED;
		String note = record.getNote() == null ? "" : "<br>" + formatNote(record.getNote());
		String locationText = location == null ? "" : "<br>" + escapeHtml(TaskLocation.format(location));
		String variantText = variantTooltip(record);
		return valuesText + variantText + locationText + setupTooltip(record) + "<br>"
			+ formatSuperiors(record.getSuperiorsSpawned()) + "<br>"
			+ formatBankTrips(record.getBankTrips()) + "<br>" + formatDeaths(record.getDeaths())
			+ taskContextTooltip(record) + bossKillCountTooltip(record.getBossKillCounts(), record.getMonster())
			+ taskLootTooltip(record, values.getMode()) + note;
	}

	/**
	 * The tooltip lines of a task's variant and boss flag ({@link TaskVariants}): {@code <br>Catacombs
	 * variant of Aberrant spectres} for a task done on its Catacombs variant, {@code <br>Slayer boss of Gargoyles} for
	 * one done on its Slayer boss, then, for a task with boss kills whose variant isn't the boss,
	 * {@code <br>Boss kills: Kraken}; "" for none.
	 */
	static String variantTooltip(LedgerRecord record)
	{
		String monster = record.getMonster();
		String variant = record.getVariant() == null ? null : record.getVariant().trim();
		if (monster == null)
		{
			return "";
		}
		String boss = TaskVariants.bossName(monster);
		boolean variantIsBoss = variant != null && boss != null && BossKillCounts.sameName(variant, boss);
		StringBuilder sb = new StringBuilder();
		if (variant != null && !variant.isEmpty())
		{
			sb.append("<br>").append(escapeHtml((variantIsBoss ? "Slayer boss of " : "Catacombs variant of ") + monster));
		}
		if (Boolean.TRUE.equals(record.getBossKills()) && boss != null && !variantIsBoss)
		{
			sb.append("<br>").append(escapeHtml("Boss kills: " + boss));
		}
		return sb.toString();
	}

	/**
	 * The setup tag lines of a history row's tooltip ({@link SetupTags#lines}), each starting with {@code <br>}:
	 * {@code Cannon: ~Yes}, {@code Style: ~Barrage}, {@code Gear: Unknown} and so on. "" for a record without stored
	 * tags (only one built without them; every record read from the ledger has them).
	 */
	static String setupTooltip(LedgerRecord record)
	{
		final SetupTags tags = SetupTags.of(record);
		if (!tags.isRecorded())
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		for (String line : tags.lines())
		{
			sb.append("<br>").append(escapeHtml(line));
		}
		return sb.toString();
	}

	/**
	 * The boss kill count lines ({@link BossKillCounts#lines}) of a tooltip, each starting with {@code <br>}; "" when
	 * there are none (for example a record saved before they were recorded).
	 *
	 * @param taskName the task's name, or {@code null}
	 */
	static String bossKillCountTooltip(List<BossKillCount> counts, String taskName)
	{
		StringBuilder sb = new StringBuilder();
		for (String line : BossKillCounts.lines(counts, taskName))
		{
			sb.append("<br>").append(escapeHtml(line));
		}
		return sb.toString();
	}

	/**
	 * The keys, clue scrolls and notable drops lines of a history row's tooltip, each starting with {@code <br>}. Keys
	 * and clues come from the record's loot ({@link KeysAndClues}); a kind with none, and a record without loot or
	 * notable drops (for example one saved before they were recorded), has no line at all.
	 *
	 * @param mode the price mode the notable drops' values are shown in ({@code null} is GE)
	 */
	static String taskLootTooltip(LedgerRecord record, LootPriceMode mode)
	{
		StringBuilder sb = new StringBuilder();
		KeysAndClues keysAndClues = KeysAndClues.of(record.getLoot());
		if (keysAndClues.hasKeys())
		{
			sb.append("<br>").append(escapeHtml(keysAndClues.keysText()));
		}
		if (keysAndClues.hasClues())
		{
			sb.append("<br>").append(escapeHtml(keysAndClues.cluesText()));
		}
		sb.append(notableDropsTooltip(record.getNotableDrops(), mode));
		return sb.toString();
	}

	/** Most notable drops listed in the live panel; the rest are in its tooltip. */
	static final int LIVE_NOTABLE_DROP_LINES = 3;

	/**
	 * The live panel's keys, clue scrolls and notable drops lines: {@code Keys: 2 brimstone} and
	 * {@code Clues: 1 hard, 2 elite} when there are any, then {@code Notable drops:} with the newest
	 * {@link #LIVE_NOTABLE_DROP_LINES} drops (short values in {@code mode}) and {@code +N more} for the rest. Empty when
	 * there is nothing to show.
	 */
	static List<String> liveTaskLootLines(KeysAndClues keysAndClues, List<NotableDrop> drops, LootPriceMode mode)
	{
		List<String> lines = new ArrayList<>();
		if (keysAndClues != null && keysAndClues.hasKeys())
		{
			lines.add(keysAndClues.keysText());
		}
		if (keysAndClues != null && keysAndClues.hasClues())
		{
			lines.add(keysAndClues.cluesText());
		}
		List<NotableDrop> sorted = NotableDrops.newestFirst(drops);
		if (!sorted.isEmpty())
		{
			lines.add("Notable drops:");
			for (int i = 0; i < Math.min(LIVE_NOTABLE_DROP_LINES, sorted.size()); i++)
			{
				lines.add("  " + formatNotableDrop(sorted.get(i), mode, false));
			}
			if (sorted.size() > LIVE_NOTABLE_DROP_LINES)
			{
				lines.add("  +" + (sorted.size() - LIVE_NOTABLE_DROP_LINES) + " more");
			}
		}
		return lines;
	}

	/**
	 * {@code <br>Notable drops:} followed by one indented line per drop, newest first, with exact values in
	 * {@code mode}; "" when there are none.
	 */
	static String notableDropsTooltip(List<NotableDrop> drops, LootPriceMode mode)
	{
		List<NotableDrop> sorted = NotableDrops.newestFirst(drops);
		if (sorted.isEmpty())
		{
			return "";
		}
		StringBuilder sb = new StringBuilder("<br>Notable drops:");
		for (NotableDrop drop : sorted)
		{
			sb.append("<br>&nbsp;&nbsp;").append(escapeHtml(formatNotableDrop(drop, mode, true)));
		}
		return sb.toString();
	}

	/**
	 * One notable drop: {@code Abyssal whip: 1.5M}, {@code Rune bar x 25: 300K}, {@code Pet} or
	 * {@code Pet (already owned)}. The value is in {@code mode} ({@code null} is GE) as it was when the drop arrived,
	 * {@link #NO_VALUE} when unknown; {@code exact} gives the full amount in gp, for tooltips.
	 */
	static String formatNotableDrop(NotableDrop drop, LootPriceMode mode, boolean exact)
	{
		if (drop.isPet())
		{
			return drop.getPet() == NotableDrop.Pet.DUPLICATE ? "Pet (already owned)" : "Pet";
		}
		String name = drop.getName() != null ? drop.getName()
			: drop.getItemId() != null ? "Item " + drop.getItemId() : "Unknown drop";
		String quantity = drop.getQuantity() > 1 ? " x " + QuantityFormatter.formatNumber(drop.getQuantity()) : "";
		Long value = drop.value(mode);
		String valueText = value == null ? NO_VALUE
			: exact ? formatGpExact(value) : LedgerFormat.amount(value);
		return name + quantity + ": " + valueText;
	}

	/**
	 * The task context lines of a history row's tooltip, each starting with {@code <br>}: the master, the type, the
	 * points earned and the streak. A part that is unknown (for example in a record saved before it was recorded) has
	 * no line at all.
	 */
	static String taskContextTooltip(LedgerRecord record)
	{
		StringBuilder sb = new StringBuilder();
		if (SlayerMaster.isKnown(record.getSlayerMaster()))
		{
			sb.append("<br>").append(escapeHtml(formatMaster(record.getSlayerMaster())));
		}
		TaskType type = TaskType.of(record.getSlayerMaster(), record.getCreatureId());
		if (type != null)
		{
			sb.append("<br>").append(escapeHtml(formatTaskType(type, record.getTaskLocation())));
		}
		if (record.getPointsEarned() != null)
		{
			sb.append("<br>").append(formatPointsEarned(record.getPointsEarned()));
		}
		if (record.getTaskStreak() != null)
		{
			sb.append("<br>").append(formatTaskStreak(record.getTaskStreak()));
		}
		return sb.toString();
	}

	/**
	 * {@code Master: Konar}; {@code Unknown master (n)} for a value not in {@link SlayerMaster}'s table; or
	 * {@code Master: -} when no master is known.
	 */
	static String formatMaster(Integer master)
	{
		if (!SlayerMaster.isKnown(master))
		{
			return "Master: " + NO_VALUE;
		}
		String name = SlayerMaster.displayName(master);
		return SlayerMaster.hasName(master) ? "Master: " + name : name;
	}

	/**
	 * {@code Type: Konar (Kraken Cove)}, {@code Type: Boss} and so on, or {@code Type: -} when the type is unknown.
	 *
	 * @param location the task's assigned area name (Konar's tasks), or {@code null}
	 */
	static String formatTaskType(TaskType type, String location)
	{
		if (type == null)
		{
			return "Type: " + NO_VALUE;
		}
		return "Type: " + type + (location == null ? "" : " (" + location + ")");
	}

	/** {@code Points earned: N}, or {@code Points earned: -} when unknown. */
	static String formatPointsEarned(Integer pointsEarned)
	{
		return "Points earned: " + formatCount(pointsEarned);
	}

	/** {@code Task streak: N}, or {@code Task streak: -} when unknown. */
	static String formatTaskStreak(Integer taskStreak)
	{
		return "Task streak: " + formatCount(taskStreak);
	}

	/** {@code Note: ...} for an HTML tooltip, with the note's HTML special characters escaped. */
	static String formatNote(String note)
	{
		return "Note: " + escapeHtml(note);
	}

	/** Escapes {@code &}, {@code <} and {@code >} for Swing HTML text; {@code null} becomes "". */
	static String escapeHtml(String s)
	{
		return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Text of the history "Edit note" dialog. */
	static String editNotePrompt(LedgerRecord record)
	{
		return String.format("Note for this %s task (up to %d characters; leave empty to remove it):", monster(record),
			TaskNote.MAX_LENGTH);
	}

	/** {@code Superiors: N}, or {@code Superiors: -} when not counted. */
	static String formatSuperiors(Integer superiorsSpawned)
	{
		return "Superiors: " + formatCount(superiorsSpawned);
	}

	/** {@code Bank trips: N}, or {@code Bank trips: -} when not counted. */
	static String formatBankTrips(Integer bankTrips)
	{
		return "Bank trips: " + formatCount(bankTrips);
	}

	/** {@code Deaths: N}, or {@code Deaths: -} when not counted. */
	static String formatDeaths(Integer deaths)
	{
		return "Deaths: " + formatCount(deaths);
	}

	/** A count, or {@link #NO_VALUE} when it is unknown ({@code null}). Never shows an unknown count as 0. */
	static String formatCount(Integer count)
	{
		return count == null ? NO_VALUE : Integer.toString(count);
	}

	/** Tooltip body of a valued history row: the values, the prices used and any approximations. */
	private static String valuesTooltipBody(HistoryPricing.Values v)
	{
		long lootGe = v.getLootGe() != null ? v.getLootGe() : 0;
		long lootHa = v.getLootHa() != null ? v.getLootHa() : 0;
		long suppliesGe = v.getSuppliesGe() != null ? v.getSuppliesGe() : 0;
		long suppliesHa = v.getSuppliesHa() != null ? v.getSuppliesHa() : 0;
		return valuesTooltipBody(v.getMode(), v.getLootValue(), lootGe, lootHa, suppliesGe, suppliesHa,
			v.getLootUnpriced(), v.getLootGeUnpriced(), v.getSuppliesUnpriced())
			+ (v.isCurrentPrices() ? "<br>" + CURRENT_PRICES : v.isSavedTotals() ? "<br>" + SAVED_TOTALS : "");
	}

	/** HTML tooltip of the live session values. */
	static String valuesTooltip(SessionValuation.Values v)
	{
		return "<html>" + valuesTooltipBody(v.getLootPriceMode(), v.getLootValue(), v.getLootGe(), v.getLootHa(),
			v.getSuppliesGe(), v.getSuppliesHa(), v.getLootValueUnpriced(), v.getLootUnpriced(), v.getSuppliesUnpriced())
			+ "</html>";
	}

	/**
	 * HTML tooltip for GE and high-alchemy loot and supply values with the loot at GE prices, noting the loot and
	 * supply items whose GE price was unavailable.
	 */
	static String valuesTooltip(long lootGe, long lootHa, long suppliesGe, long suppliesHa, int lootUnpriced,
		int suppliesUnpriced)
	{
		return "<html>" + valuesTooltipBody(LootPriceMode.GE, lootGe, lootGe, lootHa, suppliesGe, suppliesHa,
			lootUnpriced, lootUnpriced, suppliesUnpriced) + "</html>";
	}

	/**
	 * Exact GE and high-alchemy loot and supply values, a GE figure marked {@link #APPROXIMATE} when some of its GE
	 * prices were unavailable; the loot value in {@code mode} when that is not GE; the profit (loot in {@code mode}
	 * minus supplies at GE); and a note when some loot (priced in {@code mode}, and at GE when that is not the mode) or
	 * supply items had no price. So in High alch mode a missing GE price is still flagged.
	 *
	 * @param lootUnpriced   distinct loot items without a price in {@code mode}
	 * @param lootGeUnpriced distinct loot items without a GE price
	 */
	private static String valuesTooltipBody(LootPriceMode mode, long lootValue, long lootGe, long lootHa,
		long suppliesGe, long suppliesHa, int lootUnpriced, int lootGeUnpriced, int suppliesUnpriced)
	{
		boolean geMode = mode == null || mode == LootPriceMode.GE;
		StringBuilder sb = new StringBuilder();
		sb.append("Loot: ").append(formatGpExact(lootGe, lootGeUnpriced > 0)).append(" GE, ")
			.append(formatGpExact(lootHa)).append(" high alch");
		if (!geMode)
		{
			sb.append("<br>Loot value (").append(mode).append("): ").append(formatGpExact(lootValue));
		}
		sb.append("<br>Supplies: ").append(formatGpExact(suppliesGe, suppliesUnpriced > 0)).append(" GE, ")
			.append(formatGpExact(suppliesHa)).append(" high alch");
		sb.append("<br>Profit: ").append(formatGpExact(profit(lootValue, suppliesGe)));
		if (mode == null || mode == LootPriceMode.GE)
		{
			sb.append(" GE");
		}
		else
		{
			sb.append(" (loot at ").append(mode.toString().toLowerCase(Locale.ROOT)).append(", supplies at GE)");
		}
		if (!geMode && lootGeUnpriced > 0)
		{
			sb.append("<br>").append(unpricedNote(mode, lootUnpriced, lootGeUnpriced, suppliesUnpriced));
		}
		else if (lootUnpriced > 0 || suppliesUnpriced > 0)
		{
			sb.append("<br>").append(unpricedNote(lootUnpriced, suppliesUnpriced));
		}
		return sb.toString();
	}

	/** {@link #formatGpExact(long)}, prefixed with {@link #APPROXIMATE} when {@code approximate}. */
	private static String formatGpExact(long value, boolean approximate)
	{
		return (approximate ? APPROXIMATE : "") + formatGpExact(value);
	}

	/**
	 * Explains a {@link #APPROXIMATE} total. Loot and supplies are counted separately (not added up), because one item
	 * can be both loot and a supply and would otherwise be counted twice.
	 */
	static String unpricedNote(int lootUnpriced, int suppliesUnpriced)
	{
		return String.format("~ Some prices were unavailable (loot: %d, supplies: %d), so totals may be too low.",
			lootUnpriced, suppliesUnpriced);
	}

	/**
	 * {@link #unpricedNote(int, int)} in a loot price mode other than GE when some loot GE prices were unavailable:
	 * the loot is counted both in {@code mode} and at GE, for example
	 * {@code (loot at high alch: 0, loot at GE: 1, supplies: 0)}.
	 */
	static String unpricedNote(LootPriceMode mode, int lootUnpriced, int lootGeUnpriced, int suppliesUnpriced)
	{
		return String.format("~ Some prices were unavailable (loot at %s: %d, loot at GE: %d, supplies: %d), so the"
			+ " figures marked ~ may be too low.", mode.toString().toLowerCase(Locale.ROOT), lootUnpriced, lootGeUnpriced,
			suppliesUnpriced);
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import lombok.*;

/**
 * The shown account's saved history and everything worked out from it: its records and "Skipped /
 * blocked" entries and the overlay's historical time per kill. Now the rest is kept by three
 * collaborators it owns: how loot is valued ({@link HistoryValuation}: the "Loot price" mode, today's GE prices and the
 * wait for them), the player's region names and item names ({@link NameBook}) and the derived views ({@link LedgerViews}:
 * the per-task statistics, the advisor's plan, Overall totals and the "Skipped / blocked" rows). The model is still the
 * one entry point: callers read and write through it, and it decides what each change means and tells its listener
 * ({@link Change}). The plugin creates and owns it and writes to it; the panel observes it
 * ({@link #setListener}) and only renders the immutable results it returns.
 *
 * <p>Threading: EDT only. Every method, including the getters, must be called on the Swing event dispatch thread, as
 * the panel's were; the exceptions are the static {@link #liveInputs} and the instance method
 * {@link #isWaitingForCurrentPrices}, which reads one volatile field (in {@link HistoryValuation}). Nothing here is
 * synchronized. The advisor's plan and Overall totals are worked out on a background executor from an immutable
 * snapshot and handed back on the EDT ({@link LedgerViews}): they return {@code null} until ready (the plan
 * shown: the same task's previous one, if any), then the listener is told {@link Change#VIEWS}.
 * The tracker it reads is synchronized, so the EDT may read it. The plugin's callbacks it calls
 * ({@code requestLocationNames}, {@code requestCurrentPrices} and {@code requestItemNames}, which the plugin's
 * {@link ClientLookups} serves, and {@code publishHistoricalPace}) are the plugin's EDT entry points: they queue
 * client-thread work or write one volatile field. The panel's listener ({@link #setListener}) is told of every
 * change, on the EDT and after the change is complete, and redraws what it shows. The lists and views it returns are
 * unmodifiable and replaced, never changed, when what they come from changes.</p>
 *
 * <p>Derived views are worked out on demand and cached until what they come from changes: the records
 * ({@link #version}), how they are valued ({@link #valuationVersion}), item names where they are shown, and the view's
 * own inputs (a grouping, a task). Asking again with nothing changed returns the same object, so the panel's
 * refresh timer never works them out again. The per-task statistics stay on the EDT: the overlay's time per kill
 * decides from them at once.</p>
 *
 * <p>No Swing or AWT: what the overlay is told, when the advisor's plan is worked out and when a wait for today's
 * prices runs out are decided here, not by a refresh timer. The plugin re-checks them ({@link #refreshLive}) whenever
 * the live task or session changes ({@link #liveInputs}), and ends an expired wait for today's prices
 * ({@link #endExpiredCurrentPricesWait}) on the settled ticks while one runs; the panel's own refresh also ends an
 * expired wait. The plan is asked for whenever one of its inputs arrives ({@link #setRecords}, today's prices, the
 * "Loot price" mode, the hidden loot, {@link #addItemNames}).</p>
 */
final class LedgerHistoryModel
{
	/** See {@link HistoryValuation#CURRENT_PRICES_WAIT_MILLIS}. */
	static final long CURRENT_PRICES_WAIT_MILLIS = HistoryValuation.CURRENT_PRICES_WAIT_MILLIS;

	private final SessionTracker tracker;
	private final Consumer<OverlayRows.HistoricalPace> pacePublisher;
	/** How the history is valued. */
	private final HistoryValuation valuation;
	/** Region and item names. */
	private final NameBook names;
	/** The cached derived views. */
	private final LedgerViews views;
	/**
	 * Which of the records' loot ids Ground Items' hidden list hides, from the item names; the result is kept
	 * by {@link #valuation}.
	 */
	private final HiddenLootResolver hiddenLoot = new HiddenLootResolver();
	/** Told of every change (EDT); the panel's, none until set. */
	private Consumer<Change> listener = change -> { };
	/** Set by {@link #shutDown}: nothing is asked for, posted or published any more. */
	private boolean closed;

	// History
	/** Account whose records are held, or {@link SessionTracker#NO_ACCOUNT} when none are. */
	private long account = SessionTracker.NO_ACCOUNT;
	/** All records of {@link #account}, newest first; unmodifiable. */
	private List<LedgerRecord> records = Collections.emptyList();
	/** Whether {@link #records} are {@link #account}'s loaded records, not a message's empty list. */
	@Getter
	private boolean loaded;
	/** "Skipped / blocked" entries of {@link #account}, newest first; unmodifiable. */
	private List<AssignmentEntry> assignments = Collections.emptyList();
	/** Why the history is empty ({@link #clearRecords}), or {@code null} while records are held. */
	private String historyMessage;
	/** Bumped whenever {@link #records}, {@link #assignments} or {@link #account} change. */
	private long version;

	// Live
	/**
	 * The live inputs ({@link #liveInputs}) as {@link #refreshLive} last read them, or {@code null} before its first
	 * run: the listener is told {@link Change#LIVE} only when they differ.
	 */
	private List<Object> lastLiveInputs;

	/** What changed, as told to the listener ({@link #setListener}). */
	enum Change
	{
		/** New records; the views valued at today's prices are redrawn now. */
		RECORDS,
		/** New records, but the views valued at today's prices keep what they show until the prices arrive. */
		RECORDS_WAITING_FOR_PRICES,
		/** The records were dropped, with a message to show instead ({@link #historyMessage}). */
		HISTORY_CLEARED,
		/** New "Skipped / blocked" entries. */
		ASSIGNMENTS,
		/** Another "Loot price" mode. */
		LOOT_PRICE_MODE,
		/**
		 * Other loot items are hidden: Ground Items' hidden list or the setting changed, or names arrived that
		 * match it. Every view valued from the loot is redrawn.
		 */
		HIDDEN_LOOT,
		/** Today's prices arrived while nothing waited for them: the views valued at them are redrawn. */
		CURRENT_PRICES,
		/** A wait for today's prices ended: every view valued at them is redrawn. */
		PRICED_VIEWS,
		/** Region names arrived and one changed: records' and the current task's locations may differ. */
		LOCATION_NAMES,
		/** Region names arrived and none changed. */
		LOCATION_NAMES_UNCHANGED,
		/** Every region name was forgotten (another RuneScape profile). */
		LOCATION_NAMES_CLEARED,
		/** Item names (or the nature rune's price) arrived. */
		ITEM_NAMES,
		/**
		 * A view worked out in the background (the advisor's plan or Overall totals) is ready: what shows it is
		 * redrawn.
		 */
		VIEWS,
		/**
		 * The live inputs ({@link #liveInputs}: the task, its kills left, the session, ...) changed, as
		 * {@link #refreshLive} saw: what reads only the tracker for them (the advisor card's task and first kill) is
		 * checked again, with the panel hidden too. Told once per change, never for a check that finds nothing new.
		 */
		LIVE
	}

	/**
	 * @param locationNameRequests asks the plugin for the names of regions (EDT)
	 * @param currentPriceRequests asks the plugin for today's GE prices of item ids (EDT)
	 * @param itemNameRequests     asks the plugin for the names of item ids, and the nature rune's price (EDT)
	 * @param pacePublisher        publishes the overlay's historical time per kill, or {@code null} to clear it (EDT)
	 * @param viewExecutor         works out the plan and Overall totals off the EDT (the plugin's executor)
	 * @param edt                  runs their results on the EDT ({@code SwingUtilities::invokeLater})
	 */
	LedgerHistoryModel(SessionTracker tracker, LootPriceMode lootPriceMode,
		Consumer<Set<Integer>> locationNameRequests, Consumer<Set<Integer>> currentPriceRequests,
		Consumer<Set<Integer>> itemNameRequests, Consumer<OverlayRows.HistoricalPace> pacePublisher,
		Executor viewExecutor, Executor edt)
	{
		this.tracker = tracker;
		this.pacePublisher = pacePublisher;
		valuation = new HistoryValuation(lootPriceMode, currentPriceRequests);
		names = new NameBook(locationNameRequests, itemNameRequests);
		// The views get the records from setHistory, not from the model.
		views = new LedgerViews(tracker, valuation, names, viewExecutor, edt);
		views.setOnReady(() -> fire(Change.VIEWS));
	}

	/**
	 * Sets what is told of every change (the panel, which redraws); EDT. It is called on the EDT, after the change is
	 * complete, and may read the model.
	 */
	void setListener(Consumer<Change> listener)
	{
		this.listener = listener == null ? change -> { } : listener;
	}

	private void fire(Change change)
	{
		listener.accept(change);
	}

	/** The plugin stopped: nothing is asked for or published again. */
	void shutDown()
	{
		closed = true;
		names.close();
		views.close();
	}

	// ---- History ----

	/** Account whose history is held, or {@link SessionTracker#NO_ACCOUNT} when none is. */
	long account()
	{
		return account;
	}

	/** The account's records, newest first; unmodifiable, and empty while none are loaded. */
	List<LedgerRecord> records()
	{
		return records;
	}

	/** The account's "Skipped / blocked" entries, newest first; unmodifiable. */
	List<AssignmentEntry> assignments()
	{
		return assignments;
	}

	/** Bumped on every change of the account, its records or its entries; never goes back. */
	long version()
	{
		return version;
	}

	/**
	 * Holds an account's saved records (in any order; copied) and drops the statistics. Asks for today's prices of the
	 * items not priced yet; returns whether the views valued at today's prices should be redrawn now ({@code false}
	 * while they keep what they show until the prices arrive, which is never longer than
	 * {@link #CURRENT_PRICES_WAIT_MILLIS}; another account's records and an emptied history are always redrawn at
	 * once, and again when the prices arrive). The plugin clears the history before it loads another account's
	 * records ({@link #clearRecords}), so a first load waits too. The caller must have checked that {@code account} is
	 * still the account whose history should be shown. Tells the listener {@link Change#RECORDS} or
	 * {@link Change#RECORDS_WAITING_FOR_PRICES}.
	 */
	boolean setRecords(long account, List<LedgerRecord> records)
	{
		final boolean sameAccount = account == this.account;
		this.account = account;
		this.records = Collections.unmodifiableList(LedgerHistory.sortNewestFirst(records));
		loaded = true;
		historyMessage = null;
		version++;
		updateHiddenLoot();
		views.setHistory(this.account, version, this.records, assignments);
		clearTaskStatistics();
		requestCurrentPrices();
		final boolean redraw = !sameAccount || this.records.isEmpty() || !waitForCurrentPrices();
		if (redraw)
		{
			valuation.stopWaiting();
		}
		refreshHistoricalPace();
		refreshAdvisor();
		fire(redraw ? Change.RECORDS : Change.RECORDS_WAITING_FOR_PRICES);
		return redraw;
	}

	/**
	 * Drops the records and entries (logged out, loading, or a load failure), keeping {@code account} as the one shown;
	 * nothing waits for today's prices any more. {@code message} says why ({@link #historyMessage}). Tells the listener
	 * {@link Change#HISTORY_CLEARED}.
	 */
	void clearRecords(long account, String message)
	{
		valuation.stopWaiting();
		this.account = account;
		records = Collections.emptyList();
		loaded = false;
		assignments = Collections.emptyList();
		historyMessage = message;
		version++;
		updateHiddenLoot();
		views.setHistory(this.account, version, records, assignments);
		clearTaskStatistics();
		refreshHistoricalPace();
		fire(Change.HISTORY_CLEARED);
	}

	/** Why the history is empty (the message of the last {@link #clearRecords}), or {@code null}. */
	String historyMessage()
	{
		return historyMessage;
	}

	/**
	 * The record-fast task chat line for {@code record}, a completed task just saved ({@link FastestTaskMessage}), as a
	 * RuneLite chat message, or {@code null} when it is no record. Worked out from the records held, one pass over
	 * them, and only while they are {@code account}'s loaded records ({@code record} itself is left out, so it doesn't
	 * matter whether they hold it yet); otherwise {@code null}.
	 */
	String fastestTaskLine(long account, LedgerRecord record)
	{
		if (closed || !loaded || account != this.account)
		{
			return null;
		}
		return FastestTaskMessage.chatMessage(FastestTaskMessage.find(record, records));
	}

	/**
	 * Holds an account's "Skipped / blocked" entries (in any order; copied). Ignored, returning {@code false}, unless
	 * {@code account}'s history is the one held; otherwise tells the listener {@link Change#ASSIGNMENTS}.
	 */
	boolean setAssignments(long account, List<AssignmentEntry> entries)
	{
		if (account != this.account)
		{
			return false;
		}
		assignments = Collections.unmodifiableList(AssignmentLog.sortNewestFirst(entries));
		version++;
		views.setHistory(this.account, version, records, assignments);
		fire(Change.ASSIGNMENTS);
		return true;
	}

	// ---- Valuation (kept by HistoryValuation) ----

	LootPriceMode lootPriceMode()
	{
		return valuation.lootPriceMode();
	}

	/**
	 * Sets the "Loot price" mode ({@code null} is GE); returns whether it changed, which asks for the plan again and
	 * tells the listener {@link Change#LOOT_PRICE_MODE}. The per-task statistics value nothing, so they are kept.
	 */
	boolean setLootPriceMode(LootPriceMode mode)
	{
		if (!valuation.setLootPriceMode(mode))
		{
			return false;
		}
		refreshAdvisor();
		fire(Change.LOOT_PRICE_MODE);
		return true;
	}

	/** See {@link HistoryValuation#shownPrices}: today's GE prices the history is valued at; never {@code null}. */
	Map<Integer, Long> shownPrices()
	{
		return valuation.shownPrices();
	}

	/**
	 * Asks the plugin (once, in one batch) for today's GE price of every item in the records that has none yet and is
	 * not already asked for.
	 */
	void requestCurrentPrices()
	{
		if (!closed)
		{
			valuation.requestCurrentPrices(records);
		}
	}

	/**
	 * Adds today's GE prices the plugin looked up again after they were unavailable ({@code prices}, for those of
	 * {@code requested} that it found; {@code requested} was not pending); see
	 * {@link #addCurrentPrices(Set, Map, Set)}.
	 */
	void addCurrentPrices(Set<Integer> requested, Map<Integer, Long> prices)
	{
		addCurrentPrices(requested, prices, Collections.emptySet());
	}

	/**
	 * Adds today's GE prices the plugin looked up ({@code prices}, for those of {@code requested} that it found). The
	 * plugin also sends the prices it found when it looked up again the ones that were unavailable ({@code requested}
	 * is then not pending). While the views wait for prices ({@link #waitForCurrentPrices}), the wait ends once the
	 * last batch asked for has arrived and none of {@code retrying} is still being looked up again (for example while
	 * RuneLite's price list loads at client start), or once it runs out ({@link #endExpiredCurrentPricesWait});
	 * otherwise, when some price is new or changed, the plan is asked for again and the listener is told
	 * {@link Change#CURRENT_PRICES}. An answer that adds no new price redraws nothing.
	 *
	 * @param retrying ids of {@code requested} that came back without a price and that the plugin looks up again
	 *                 ({@link PriceRetry}); may be empty
	 */
	void addCurrentPrices(Set<Integer> requested, Map<Integer, Long> prices, Set<Integer> retrying)
	{
		final boolean changed = valuation.addCurrentPrices(requested, prices, retrying);
		if (valuation.isWaitingForCurrentPrices())
		{
			if (valuation.isWaitOver())
			{
				endCurrentPricesWait();
			}
			return;
		}
		if (!changed)
		{
			return;
		}
		refreshAdvisor();
		fire(Change.CURRENT_PRICES);
	}

	/** Whether some prices asked for have not arrived yet. */
	boolean isCurrentPricesPending()
	{
		return valuation.isCurrentPricesPending();
	}

	/** See {@link HistoryValuation#waitForCurrentPrices}. */
	boolean waitForCurrentPrices()
	{
		return valuation.waitForCurrentPrices();
	}

	/**
	 * Whether the views valued at today's prices keep what they show until the prices asked for arrive. Any
	 * thread (one volatile read): the plugin checks it on the client thread to ask for
	 * {@link #endExpiredCurrentPricesWait} on the EDT.
	 */
	boolean isWaitingForCurrentPrices()
	{
		return valuation.isWaitingForCurrentPrices();
	}

	/** See {@link HistoryValuation#currentPricesWaitExpired}; the caller ends the wait ({@link #endCurrentPricesWait}). */
	boolean currentPricesWaitExpired()
	{
		return valuation.currentPricesWaitExpired();
	}

	/** Test seam: lets a wait for today's prices run out at once, as if no answer came in time. */
	void expireCurrentPricesWait()
	{
		valuation.expireCurrentPricesWait();
	}

	/**
	 * Ends any wait for today's prices, asks for the advisor's plan at the prices there are and tells the listener
	 * {@link Change#PRICED_VIEWS}, so every view valued at them is redrawn.
	 */
	void endCurrentPricesWait()
	{
		valuation.stopWaiting();
		refreshAdvisor();
		fire(Change.PRICED_VIEWS);
	}

	/**
	 * Ends a wait for today's prices that has lasted {@link #CURRENT_PRICES_WAIT_MILLIS} (an answer never came;
	 * {@link #currentPricesWaitExpired}): the plan is asked for again ({@link #endCurrentPricesWait}) and the panel
	 * redraws its views valued at today's prices with the prices there are ({@link Change#PRICED_VIEWS}).
	 * Returns whether it did; does nothing while no wait has run out, so it may be called as often as wanted.
	 */
	boolean endExpiredCurrentPricesWait()
	{
		if (closed || !currentPricesWaitExpired())
		{
			return false;
		}
		endCurrentPricesWait();
		return true;
	}

	/** Bumped whenever how the history is valued changes: the mode, today's prices or the hidden loot. */
	long valuationVersion()
	{
		return valuation.valuationVersion();
	}

	// ---- Hidden loot ----

	/**
	 * Hides what {@code list} hides from now on (Ground Items' hidden list, or {@link GroundItemsHidden#NONE} while
	 * the setting or Ground Items is off; {@code null} is none). When that changes which loot is hidden, the plan is
	 * asked for again and the listener is told {@link Change#HIDDEN_LOOT}. Item names not known yet are asked for; the
	 * items are matched again when they arrive ({@link #addItemNames}).
	 */
	void setGroundItemsHidden(GroundItemsHidden list)
	{
		if (hiddenLoot.setList(list) && updateHiddenLoot())
		{
			hiddenLootChanged();
		}
	}

	/** The records' loot items left out of the loot value and the "Loot received" grids; never {@code null}. */
	HiddenLoot hiddenLoot()
	{
		return valuation.hiddenLoot();
	}

	/**
	 * Works out which of the records' loot ids are hidden, from the names known, and asks for the missing names while
	 * something can be hidden. Returns whether that changed (which bumps the valuation version); the caller tells the
	 * listener.
	 */
	private boolean updateHiddenLoot()
	{
		Set<Integer> ids = new HashSet<>();
		if (!hiddenLoot.list().isEmpty())
		{
			for (LedgerRecord record : records)
			{
				if (record.getLoot() != null)
				{
					ids.addAll(record.getLoot().keySet());
				}
			}
			ids.remove(null);
			names.requestItemNames(ids);
		}
		return valuation.setHiddenLoot(hiddenLoot.resolve(ids, names::itemBaseName));
	}

	/**
	 * Other loot is hidden: asks for the plan again and tells the listener (the per-task statistics value nothing, so
	 * they are kept).
	 */
	private void hiddenLootChanged()
	{
		refreshAdvisor();
		fire(Change.HIDDEN_LOOT);
	}

	// ---- Region names (kept by NameBook) ----

	/** The player's name for {@code region}, or {@code null} when it has none or it is not known yet. */
	String locationName(Integer region)
	{
		return names.locationName(region);
	}

	/**
	 * Sets the bundled Slayer spot table, which names the records' and the current task's locations;
	 * {@code null} is {@link SlayerSpots#NONE}. The plugin sets it once, when it starts.
	 */
	void setSpots(SlayerSpots spots)
	{
		names.setSpots(spots);
		clearTaskStatistics();
	}

	/** The bundled Slayer spot table; never {@code null}. */
	SlayerSpots spots()
	{
		return names.spots();
	}

	/**
	 * A saved record's location name as the history shows it ({@link TaskLocation#recordLocation}), or {@code null}
	 * when none is known.
	 */
	String recordLocation(LedgerRecord record)
	{
		return names.recordLocation(record);
	}

	/** Asks the plugin (once, in one batch) for the names of {@code regions} not known, asked for or missing yet. */
	void requestLocationNames(Set<Integer> regions)
	{
		names.requestLocationNames(regions);
	}

	/**
	 * Adds region names from the plugin ({@code names}, for the regions in {@code requested} that have one; also sent
	 * when the player names one). Requested regions without a name are not asked for again. Returns whether a name
	 * changed: the statistics are then dropped (a record's or the current task's location may have changed) and the
	 * overlay's time per kill is worked out again.
	 */
	boolean addLocationNames(Set<Integer> requested, Map<Integer, String> names)
	{
		boolean changed = this.names.addLocationNames(requested, names);
		if (changed)
		{
			clearTaskStatistics();
		}
		refreshHistoricalPace();
		fire(changed ? Change.LOCATION_NAMES : Change.LOCATION_NAMES_UNCHANGED);
		return changed;
	}

	/**
	 * Forgets every region name (another RuneScape profile is active): they are asked for again as needed. Tells the
	 * listener {@link Change#LOCATION_NAMES_CLEARED}.
	 */
	void clearLocationNames()
	{
		names.clearLocationNames();
		clearTaskStatistics();
		refreshHistoricalPace();
		fire(Change.LOCATION_NAMES_CLEARED);
	}

	/**
	 * The current task's location for the same-location statistics ({@link TaskLocation#current}): the active
	 * session's spot, else its assigned area, else the spot the player is in, with the name the live card's time left
	 * shows. Region names not known yet are asked of the plugin (once each), for the name;
	 * {@link TaskLocation.Here#UNKNOWN} while unknown.
	 */
	TaskLocation.Here currentLocation()
	{
		SessionTracker.State state = tracker.getState();
		boolean active = state.isActive();
		String area = active ? tracker.getSessionTaskLocation() : null;
		if (area == null)
		{
			area = tracker.getCurrentContext().getLocation();
		}
		TaskSpot sessionSpot = active ? tracker.getTaskSpot() : TaskSpot.UNKNOWN;
		int currentRegion = tracker.getCurrentRegion();
		String currentSpot = tracker.getCurrentSpot();
		// A region's name comes before its spot's; where the player stands matters only while the session has no spot
		// and the task no assigned area (as TaskLocation.current decides).
		Set<Integer> regions = new HashSet<>();
		boolean sessionHasSpot = sessionSpot.getSpotId() != null;
		if (sessionHasSpot && sessionSpot.getRegion() != null)
		{
			regions.add(sessionSpot.getRegion());
		}
		if (!sessionHasSpot && TaskLocation.normalizeName(area) == null)
		{
			regions.add(currentRegion);
		}
		names.requestLocationNames(regions);
		return TaskLocation.current(area, sessionSpot, currentRegion, currentSpot, names::locationName,
			names.spots());
	}

	// ---- Item names (kept by NameBook) ----

	/** The name of item {@code id} (as tallied), or {@code null} when it is not known (yet). */
	String itemName(Integer id)
	{
		return names.itemName(id);
	}

	/** The nature rune's GE price for the alch hint, or {@code null} while unknown. */
	Long natureRunePrice()
	{
		return names.natureRunePrice();
	}

	/** Whether the plugin could not name {@code id}. */
	boolean isItemNameFailed(Integer id)
	{
		return names.isItemNameFailed(id);
	}

	/** See {@link NameBook#requestItemNames}; the answer comes through {@link #addItemNames}. */
	void requestItemNames(Set<Integer> ids)
	{
		names.requestItemNames(ids);
	}

	/**
	 * Adds item names looked up by the plugin ({@code names}, for the ids in {@code requested} that have one) and the
	 * nature rune's GE price ({@code null} when unavailable); ids without a name are not asked for again. Tells the
	 * listener {@link Change#ITEM_NAMES}.
	 */
	void addItemNames(Set<Integer> requested, Map<Integer, String> names, Long natureRune)
	{
		this.names.addItemNames(requested, names, natureRune);
		fire(Change.ITEM_NAMES);
		// A name that arrived may be one Ground Items hides.
		if (!hiddenLoot.list().isEmpty() && updateHiddenLoot())
		{
			hiddenLootChanged();
		}
		// A potion's name may join it to its family in the plan.
		refreshAdvisor();
	}

	// ---- Live: the advisor's plan and the overlay's time per kill ----

	/**
	 * What {@link #refreshLive} depends on that the tracker holds: the session's state and id, the task, its master
	 * (the plan's task type) and its kills left, which version of it the session's kills say is done and whether its
	 * Cannon tag is Yes ({@link SessionTracker#getCurrentTaskSelection}), and every input of
	 * {@link #currentLocation}, the assigned area among them. Any thread (the tracker is synchronized); the plugin
	 * reads it on the client thread each settled tick and asks for {@link #refreshLive} on the EDT only when it
	 * changed, so a new kills left asks for a new plan at most once a tick.
	 */
	static List<Object> liveInputs(SessionTracker tracker)
	{
		SessionTracker.State state = tracker.getState();
		return Arrays.asList(state, tracker.getSessionId(), tracker.isTaskObserved(), tracker.getCurrentCreatureId(),
			tracker.getCurrentMonster(), tracker.getCurrentRemaining(), tracker.getCurrentContext().getMaster(),
			tracker.getSessionTaskLocation(), tracker.getCurrentContext().getLocation(), tracker.getTaskSpot(),
			tracker.getCurrentRegion(), tracker.getCurrentSpot(), tracker.getCurrentTaskSelection());
	}

	/**
	 * Ends a wait for today's prices that ran out ({@link #endExpiredCurrentPricesWait}), asks for the advisor's plan
	 * of the live task and publishes the overlay's time per kill again. When the live inputs differ from what the last
	 * call read, the listener is then told {@link Change#LIVE}, so what reads only the tracker (the advisor card's
	 * task) needn't wait for a panel refresh.
	 */
	void refreshLive()
	{
		List<Object> inputs = liveInputs(tracker);
		endExpiredCurrentPricesWait();
		refreshAdvisor();
		refreshHistoricalPace();
		if (!closed && !inputs.equals(lastLiveInputs))
		{
			lastLiveInputs = inputs;
			fire(Change.LIVE);
		}
	}

	/**
	 * Asks for the advisor's plan of the current inputs ({@link #plan}: worked out in the background, once per inputs).
	 * Called whenever one of the plan's inputs may have changed, so it doesn't wait for the panel.
	 */
	private void refreshAdvisor()
	{
		plan();
	}

	/**
	 * The advisor's plan to show for the current task ({@link LedgerViews#plan}): the plan for the current inputs
	 * or, while it is worked out in the background or the views wait for today's prices, the last plan for the
	 * same task, so a kill doesn't blank it. {@code null} while there is no task, the account's records are not loaded,
	 * or no such plan is kept. When the plan for the current inputs is ready the listener is told {@link Change#VIEWS}.
	 * Asking again with nothing changed works nothing out.
	 */
	TaskPlan plan()
	{
		return closed || !loaded ? null : views.plan();
	}

	/**
	 * How many times the plan was worked out ({@link LedgerViews#getPlanBuildCount}).
	 * Performance seam: tests assert this doesn't grow on the refresh timer.
	 */
	int getPlanBuildCount()
	{
		return views.getPlanBuildCount();
	}


	/**
	 * The historical time per kill the sidebar's "Time left" uses for the active session's task (at its
	 * location first, and of the version and cannon use its session shows), with the same tasks' supplies per
	 * kill for the overlay's supply runway, or {@code null} with no such session or no history for its task.
	 */
	OverlayRows.HistoricalPace historicalPace()
	{
		SessionTracker.State state = tracker.getState();
		if (!state.isActive())
		{
			return null;
		}
		TaskStatistics stats = taskStatistics(tracker.getCurrentCreatureId(), tracker.getCurrentMonster(),
			tracker.getCurrentTaskSelection(), currentLocation());
		Long perKill = stats.getSampleCount() == 0 ? null : stats.getMillisPerKill();
		String sessionId = tracker.getSessionId();
		// With the supplies per kill of the same tasks, for the overlay's supply runway.
		return perKill == null || sessionId == null ? null
			: new OverlayRows.HistoricalPace(sessionId, perKill, stats.getSuppliesPerKill());
	}

	/**
	 * Publishes {@link #historicalPace} to the plugin for the overlay: run when the records, a region name, the
	 * task, its location or the session change.
	 */
	void refreshHistoricalPace()
	{
		if (closed)
		{
			return;
		}
		pacePublisher.accept(historicalPace());
	}

	// ---- Derived views (kept by LedgerViews) ----

	/** Drops the cached statistics, after the history, the spot table or a region name changed. */
	private void clearTaskStatistics()
	{
		views.clearTaskStatistics();
	}

	/** See {@link LedgerViews#taskStatistics(int, String, TaskSelection, TaskLocation.Here)}. */
	TaskStatistics taskStatistics(int creatureId, String monster, TaskSelection selection, TaskLocation.Here location)
	{
		return views.taskStatistics(creatureId, monster, selection, location);
	}

	/**
	 * How many times a task's statistics were worked out ({@link LedgerViews#getTaskStatisticsBuildCount}).
	 * Performance seam: tests assert this doesn't grow on the refresh timer, or when only the valuation changes.
	 */
	int getTaskStatisticsBuildCount()
	{
		return views.getTaskStatisticsBuildCount();
	}

	/** See {@link LedgerViews#overallTotals}. */
	List<OverallTotals.Entry> overallTotals(OverallTotals.Grouping grouping)
	{
		return views.overallTotals(grouping);
	}

	/** See {@link LedgerViews#assignmentRows}. */
	List<AssignmentRow> assignmentRows()
	{
		return views.assignmentRows();
	}


	/**
	 * How many times the overall totals were worked out ({@link LedgerViews#getOverallTotalsBuildCount}).
	 * Performance seam: tests assert this doesn't grow on the refresh timer.
	 */
	int getOverallTotalsBuildCount()
	{
		return views.getOverallTotalsBuildCount();
	}

	/**
	 * How many times the "Skipped / blocked" rows were worked out ({@link LedgerViews#getAssignmentRowsBuildCount}).
	 * Performance seam: tests assert this doesn't grow on the refresh timer.
	 */
	int getAssignmentRowsBuildCount()
	{
		return views.getAssignmentRowsBuildCount();
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import net.runelite.client.ui.components.*;

/**
 * The live task card's progress bar (DESIGN_PRINCIPLES.md 2.4 and 3.4): RuneLite's {@link ProgressBar}, drawn in
 * {@link LedgerTheme}'s track and fill, with its centre label (the kills done of the task, {@code 73 / 201}) as wide as
 * the bar. RuneLite lays its left, centre and right labels out in a 1 by 3 grid, which gives the centre one a third of
 * the width: in the card's 199 px that cut {@code 2,000 / 3,985} (72 px in RuneScape Small) to {@code 1 / 3,...}. Here
 * every label spans the bar; the left and right ones are never set, so they draw nothing. Its preferred size stays
 * the 100 by 16 px RuneLite's constructor sets, so the labels never decide its width: 100 px is well inside the card,
 * whose bar row stretches it to the card's width, and 16 px is the bar's height. EDT only.
 */
final class LedgerProgressBar extends ProgressBar
{
	LedgerProgressBar()
	{
		setBackground(LedgerTheme.TRACK);
		setForeground(LedgerTheme.BAR_FILL);
		setLayout(new FullWidthLayout());
	}

	/** The labels overlap (each spans the bar), so Swing must not assume they tile it when it repaints one. */
	@Override
	public boolean isOptimizedDrawingEnabled()
	{
		return false;
	}

	/**
	 * Gives every label the whole bar. Its sizes ask for no width; only the minimum size comes from it, as RuneLite's
	 * constructor sets the bar's preferred size.
	 */
	private static final class FullWidthLayout implements LayoutManager
	{
		@Override
		public void addLayoutComponent(String name, Component component)
		{
		}

		@Override
		public void removeLayoutComponent(Component component)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets insets = parent.getInsets();
			int height = 0;
			for (Component label : parent.getComponents())
			{
				height = Math.max(height, label.getPreferredSize().height);
			}
			return new Dimension(insets.left + insets.right, insets.top + insets.bottom + height);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets insets = parent.getInsets();
			int width = Math.max(0, parent.getWidth() - insets.left - insets.right);
			int height = Math.max(0, parent.getHeight() - insets.top - insets.bottom);
			for (Component label : parent.getComponents())
			{
				label.setBounds(insets.left, insets.top, width, height);
			}
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * One saved Slayer task session. Serialized to JSON with Gson; optional fields can be added without breaking older
 * files because Gson ignores missing and unknown fields (and omits {@code null} fields when writing).
 *
 * <p>Schema history: version 1 had no item data. Version 2 adds the optional loot, supplies, unit-price and value
 * fields below; a version 1 record simply has them all {@code null}. The version was raised because an older build
 * would silently drop these fields when it rewrites the ledger file; see {@link LedgerStore#FILE_SCHEMA_VERSION}.
 * {@link #supplyDoses} was added to version 2 later, as an optional field, before any record with supplies existed;
 * version 2 records without supplies simply have it {@code null}. {@link #lootUnpricedItems} and
 * {@link #suppliesUnpricedItems} were added the same way; a record without them had every price available (or, if
 * saved by an earlier build, stored an unavailable GE price as 0). {@link #superiorsSpawned} and {@link #bankTrips} were
 * added the same way; records saved before they were counted have them {@code null}. {@link #note} was added the same way; older
 * records have none. {@link #deaths} was added the same way; records saved before deaths were counted have it
 * {@code null}. {@link #slayerMaster}, {@link #slayerArea}, {@link #taskLocation}, {@link #pointsEarned} and
 * {@link #taskStreak} were added the same way; older records have them {@code null} (unknown). {@link #notableDrops} was
 * added the same way; older records have it {@code null} and show no notable drops. Keys and clue scrolls are not
 * stored: they are derived from {@link #loot} ({@link KeysAndClues}). {@link #bossKillCounts} was added the same way;
 * older records have it {@code null} and show no boss kill count. {@link #xpGained} was added the same way; older
 * records have it {@code null} and show "-" for their XP. {@link #locationRegion} and {@link #location} were added the
 * same way; older records have them {@code null} and show "Unknown" for their location. {@link #variant} was added
 * the same way; older records have it {@code null}, so they count as the standard monster. Whether a task was
 * done with a cannon was not stored: 1.x derived it from {@link #supplies}; since version 3 it is the Cannon
 * tag ({@link #cannonTask}).</p>
 *
 * <p>Version 3 (2.0) adds the setup tags: the detected cannon, style and gear focus ({@link #detectedCannon},
 * {@link #detectedStyle}, {@link #detectedGear}), whether each is an estimate ({@link #cannonEstimated} and so on) and
 * the player's overrides ({@link #cannonOverride} and so on), read only through {@link SetupTags}. It also adds the
 * kills by NPC ({@link #npcKills}), the setup kill-context counts ({@link #cannonKills}, {@link #styleKills},
 * {@link #gearKills}, {@link #prayerBonusMin}, {@link #prayerBonusMax}; see {@link SetupKills}) and the spot
 * ({@link #spotId}). The version was raised because the setup tags change what a task's cannon means: a 1.x build
 * would ignore the player's overrides and classify the task by its own rule, so it must not write a 2.0 ledger. A
 * record below version 3 is migrated when it is read ({@link SetupMigration}): it gets estimated tags and version 3 in
 * memory, and keeps them once the file is next written.</p>
 *
 * <p>{@link #bossKills} was added to version 3 later, as an optional field, before any released build wrote
 * version 3. A 1.x record gets it when it is migrated ({@link SetupMigration}, {@link TaskVariants#migrate}), from its
 * {@link #npcKills} when it has any or else its {@link #bossKillCounts}, and keeps it once the file is next written.
 * Now {@link #variant} names any kind a task can be done on besides its own monsters ({@link TaskVariants}):
 * its Catacombs variant, as before, or its Slayer boss.</p>
 */
@Data
public class LedgerRecord
{
	public static final int CURRENT_SCHEMA_VERSION = 3;

	private int schemaVersion = CURRENT_SCHEMA_VERSION;
	private String id;
	private String monster;
	/**
	 * Slayer task creature key, or {@code null} when unknown: the SLAYER_TARGET varp value, or for boss tasks
	 * {@code -2 - bossId} (SLAYER_TARGET_BOSSID). See {@link SessionTracker#creatureKey(int, int)}.
	 */
	private Integer creatureId;
	/** Remaining task amount when the session started. */
	private int initialAmount;
	/** Assigned task size (SLAYER_COUNT_ORIGINAL plus any extension modifier), or {@code null} when unknown. */
	private Integer originalAmount;
	private int kills;
	private long activeMillis;
	private long startedAt;
	private long endedAt;
	private boolean completed;
	/** True when the player chose to keep an incomplete session. */
	private boolean partial;

	/** NPC loot received while the session was running: item id (as received, possibly noted) to quantity. */
	private Map<Integer, Long> loot;
	/**
	 * Supplies used while the session was running: item id to quantity, or {@code null} when none (and in older
	 * records). For a potion (an id in {@link #supplyDoses}) the quantity is in <em>doses</em>, keyed by the
	 * highest-dose variant of that potion seen since the plugin started. For a pizza, pie or cake (also an id in
	 * {@link #supplyDoses}) it is in <em>bites</em>, keyed by the whole item. For teleport jewellery or the fungicide
	 * spray (also an id in {@link #supplyDoses}) it is in <em>charges</em>, keyed by the highest-charge item; see
	 * {@link SupplyTracker}.
	 */
	private Map<Integer, Long> supplies;
	/**
	 * Doses (bites, charges) in one item, for every potion, multi-bite food and charged item id in {@link #supplies}:
	 * the supply quantity of that id counts doses, bites or charges, each valued at the id's unit price divided by this
	 * number. {@code null} when no potions, multi-bite food or charged items were used.
	 */
	private Map<Integer, Integer> supplyDoses;
	/**
	 * Grand Exchange unit price of every item in {@link #loot} and {@link #supplies}, captured when the record was
	 * saved. Noted items are priced as the unnoted item; coins at face value; untradeable items at 0. An item whose GE
	 * price was unavailable (not loaded yet, or a failed lookup) is left out; see {@link ItemValuation}.
	 * {@code null} when no prices were captured.
	 */
	private Map<Integer, Long> unitGePrices;
	/** High-alchemy unit value of every item in {@link #loot} and {@link #supplies}, captured with the GE prices. */
	private Map<Integer, Long> unitHaPrices;
	/**
	 * Total GE value of {@link #loot} at {@link #unitGePrices} as captured (an untradeable item at 0), or {@code null}
	 * when not valued (older records). The history shows a record with unit prices at {@link LootPricing}'s GE value
	 * instead, which counts a GE price of 0 at its high-alchemy value; see {@link HistoryPricing}.
	 */
	private Long lootGeValue;
	/** Total high-alchemy value of {@link #loot}, or {@code null} when not valued. */
	private Long lootHaValue;
	/**
	 * Total GE value of {@link #supplies} (potions per dose, see {@link #supplyDoses}), or {@code null} when not
	 * valued or no supplies were recorded.
	 */
	private Long suppliesGeValue;
	/** Total high-alchemy value of {@link #supplies}, or {@code null} when not valued or not recorded. */
	private Long suppliesHaValue;
	/**
	 * Number of distinct {@link #loot} items whose GE price was unavailable when valued (so {@link #lootGeValue} leaves
	 * them out), or {@code null} when there were none.
	 */
	private Integer lootUnpricedItems;
	/** Like {@link #lootUnpricedItems}, for {@link #supplies} and {@link #suppliesGeValue}. */
	private Integer suppliesUnpricedItems;
	/** Superior Slayer monster spawns seen while the session was running, or {@code null} when not counted. */
	private Integer superiorsSpawned;
	/** Bank trips made while the session was running (see {@link BankTripCounter}), or {@code null} when not counted. */
	private Integer bankTrips;
	/** Deaths of the local player while the session was running, or {@code null} when not counted. */
	private Integer deaths;
	/**
	 * The player's free-text note on the task (for example "Barrage"), {@link TaskNote#normalize normalized}, or
	 * {@code null} when none. Can be edited after saving.
	 */
	private String note;
	/**
	 * SLAYER_MASTER value of the master who assigned the task (see {@link SlayerMaster}), or {@code null} when unknown.
	 * The task's {@link TaskType} is derived from it and {@link #creatureId}; it is not stored.
	 */
	private Integer slayerMaster;
	/** SLAYER_AREA value (Konar's assigned area), or {@code null} when the task had none or it is unknown. */
	private Integer slayerArea;
	/** Name of {@link #slayerArea} from the game's SlayerArea table, or {@code null}. */
	private String taskLocation;
	/**
	 * Slayer points the completion gave (see {@link TaskRewards}), or {@code null} when the task wasn't completed, the
	 * change couldn't be trusted, or the record is older. Never negative.
	 */
	private Integer pointsEarned;
	/**
	 * The streak the completion raised (regular, Wilderness or Mortimer), as it stood afterwards, or {@code null} when
	 * unknown or not completed.
	 */
	private Integer taskStreak;
	/**
	 * Notable drops received while the session was running (see {@link NotableDrops}), in the order they arrived, with
	 * their values when they dropped; at most {@link NotableDrops#MAX_PER_TASK}. {@code null} when there were none (and
	 * in older records).
	 */
	private List<NotableDrop> notableDrops;
	/**
	 * Boss kill counts from the game's kill count messages while the session was running (see {@link BossKillCounts}),
	 * one per boss in the order first seen; at most {@link BossKillCounts#MAX_PER_TASK}. {@code null} when there were
	 * none (and in older records).
	 */
	private List<BossKillCount> bossKillCounts;
	/**
	 * XP gained per skill while the session was running (see {@link SessionTracker#observeXp}), keyed by the name of
	 * RuneLite's {@code Skill} constant (e.g. {@code "SLAYER"}). Empty when the session gained none; {@code null} in
	 * older records (shown as "-") and in a partial saved from a snapshot written before XP was tracked.
	 */
	private Map<String, Long> xpGained;
	/**
	 * The map region the task's location was decided from (see {@link LocationTally#decide}): the region with the
	 * most kills in the task's spot, or with no spot the region with the most kills of all (1.x saved the region with
	 * the most kills); {@code null} when no kill was tallied (and in older records).
	 */
	private Integer locationRegion;
	/**
	 * The task's own location name, which the history shows before any other ({@link TaskLocation#recordLocation}):
	 * since 2.0 only a name the player gave this task ("Edit location"); a 1.x record also kept the name its
	 * location had when it was saved (its assigned Konar or Wilderness area, else the player's name for
	 * {@link #locationRegion}). {@code null} when it has none. Can be edited after saving; never decides the spot.
	 */
	private String location;
	/**
	 * The task's Slayer spot (V2 plan 4.5): the bundled spot table's stable id ({@link SlayerSpots}), or
	 * {@code region:N} for a region the table doesn't list, decided from its kills when it was saved
	 * ({@link LocationTally#decide}); {@code null} when unknown, and in records saved before spots, whose spot is worked
	 * out from {@link #locationRegion} each time it is read ({@link SlayerSpots#recordSpot}).
	 */
	private String spotId;
	/**
	 * The kind the task was mostly done on besides its own monsters, by its name, decided from the session's kills per
	 * NPC name and its task kills when it was saved ({@link TaskVariants#decide}): its Catacombs of Kourend variant
	 * ({@link CatacombsVariants.Variant#getName}, for example "Deviant spectres") or,, its Slayer boss
	 * ({@link SlayerBosses.Boss#getName}, for example "Grotesque Guardians" on a gargoyle task); {@code null} for the
	 * standard monster (and in older records). The session's kills per NPC name are kept in {@link #npcKills} since
	 * version 3.
	 */
	private String variant;
	/**
	 * Whether the task's kills include its Slayer boss (V2 plan 4.4, {@link TaskVariants#bossKills}), for example
	 * a Grotesque Guardians kill on a gargoyle task, however few; {@code false} for a boss task (its own pool) or a task
	 * without a Slayer boss. {@code null} only in a record built without it (none is saved so, and a migrated 1.x
	 * record gets it), which reads as no boss kills.
	 */
	private Boolean bossKills;
	/**
	 * The session's kills per NPC name, in the order first seen ({@link NpcKillTally}, kept since version 3), or {@code null} when none (and in older records).
	 */
	private List<NpcKills> npcKills;
	/**
	 * Task kills made while the cannon was firing ({@link SetupKills}), or {@code null} when no kill context was
	 * counted (older records).
	 */
	private Integer cannonKills;
	/** Task kills per style ({@link SetupStyle} name), or {@code null} when none were counted. */
	private Map<String, Integer> styleKills;
	/** Task kills per gear focus ({@link GearFocus} name), or {@code null} when none were counted. */
	private Map<String, Integer> gearKills;
	/** The lowest worn prayer bonus seen at a task kill, or {@code null} when none was read. */
	private Integer prayerBonusMin;
	/** The highest worn prayer bonus seen at a task kill, or {@code null} when none was read. */
	private Integer prayerBonusMax;
	/**
	 * The detected cannon tag (V2 plan 4.3): whether the task was done with a cannon, as detected (or, for a migrated
	 * record, estimated from its cannonballs); {@code null} only in a record built without tags. Read the effective
	 * value through {@link SetupTags}, never this field.
	 */
	private Boolean detectedCannon;
	/** {@code true} when {@link #detectedCannon} is an estimate (a migrated record); {@code null} otherwise. */
	private Boolean cannonEstimated;
	/** The player's cannon override, or {@code null} for none (see {@link SetupOverrides}). Can be edited after saving. */
	private Boolean cannonOverride;
	/** The detected (or, migrated, estimated) style tag; {@code null} reads as {@link SetupStyle#UNKNOWN}. */
	private SetupStyle detectedStyle;
	/** {@code true} when {@link #detectedStyle} is an estimate (a migrated record); {@code null} otherwise. */
	private Boolean styleEstimated;
	/** The player's style override, or {@code null} for none. Can be edited after saving. */
	private SetupStyle styleOverride;
	/** The detected gear focus tag; {@code null} reads as {@link GearFocus#UNKNOWN}. */
	private GearFocus detectedGear;
	/** {@code true} when {@link #detectedGear} is an estimate; {@code null} otherwise (migrated records' gear is Unknown). */
	private Boolean gearEstimated;
	/** The player's gear focus override, or {@code null} for none. Can be edited after saving. */
	private GearFocus gearOverride;

	/**
	 * The name the record is shown and grouped under: its {@link #versionName}, with
	 * {@link CannonTasks#SUFFIX} for a {@link #cannonTask cannon task}, for example "Deviant spectres" or
	 * "Dust devils (cannon)". The history list and its Monster filter, the task-complete chat line and Overall totals By
	 * monster group by it (with {@link TaskStatistics#normalize}). The advisor's main advice and the Skipped / blocked
	 * rows pool every version
	 * and cannon use by task, the 2.0 advisor's plan ({@link TaskPlanner}) pools every version in options split by
	 * cannon, and {@link TaskStatistics} filters by creature plus a
	 * {@link TaskSelection}.
	 */
	String groupName()
	{
		return CannonTasks.name(versionName(), cannonTask());
	}

	/**
	 * Its {@link #variant} when it has one (its Catacombs variant or Slayer boss), else its
	 * {@link #monster}; without the cannon suffix.
	 */
	String versionName()
	{
		return variant != null && !variant.trim().isEmpty() ? variant.trim() : monster;
	}

	/**
	 * Whether the task counts as a cannon task: its effective Cannon tag ({@link SetupTags#of}: the
	 * player's override, else the detected value), so the name, the Monster filter and the Cannon filter agree. A
	 * record without a stored tag (none read through {@link LedgerStore}) falls back to its fired cannonballs
	 * ({@link CannonTasks#fired}), as 1.x classified it.
	 */
	boolean cannonTask()
	{
		return SetupTags.of(this).isCannon();
	}

	/**
	 * Name to show for a task, falling back to "Unknown task (id)" when the name lookup failed.
	 */
	static String displayName(String monster, int creatureId)
	{
		if (monster != null)
		{
			return monster;
		}
		if (creatureId == SessionTracker.NO_CREATURE)
		{
			return "Unknown task";
		}
		if (creatureId < SessionTracker.NO_CREATURE)
		{
			return "Unknown boss task (" + (-2 - creatureId) + ")";
		}
		return "Unknown task (" + creatureId + ")";
	}

	static LedgerRecord fromSummary(SessionTracker.Summary summary, boolean partial)
	{
		LedgerRecord record = new LedgerRecord();
		// The session id becomes the record id, so appending the same session twice is detectable.
		record.setId(summary.getSessionId() != null ? summary.getSessionId() : UUID.randomUUID().toString());
		record.setMonster(displayName(summary.getMonster(), summary.getCreatureId()));
		record.setCreatureId(summary.getCreatureId() == SessionTracker.NO_CREATURE ? null : summary.getCreatureId());
		record.setInitialAmount(summary.getInitialAmount());
		record.setOriginalAmount(summary.getOriginalAmount() == SessionTracker.UNKNOWN_AMOUNT ? null : summary.getOriginalAmount());
		record.setKills(summary.getKills());
		record.setActiveMillis(summary.getActiveMillis());
		record.setStartedAt(summary.getStartedAt());
		record.setEndedAt(summary.getEndedAt());
		record.setCompleted(summary.isCompleted());
		record.setPartial(partial);
		summary.getSessionLoot().copyTo(record);
		summary.getCounters().copyTo(record);
		record.setNote(summary.getNote());
		final TaskContext context = summary.getContext();
		record.setSlayerMaster(context.getMaster());
		record.setSlayerArea(context.getArea());
		record.setTaskLocation(context.getLocation());
		// Points and streak describe a completion; an incomplete session never has them.
		record.setPointsEarned(summary.isCompleted() ? context.getPointsEarned() : null);
		record.setTaskStreak(summary.isCompleted() ? context.getTaskStreak() : null);
		record.setXpGained(xpGainedFor(summary));
		// The spot its kills decided. No location name is saved: the history names it from the spot, the region's
		// name and the player's own name for this task.
		final TaskSpot spot = summary.getTaskSpot();
		record.setLocationRegion(spot.getRegion());
		record.setSpotId(spot.getSpotId());
		record.setVariant(TaskVariants.decide(summary.getMonster(), summary.getCreatureId(), summary.getNpcKills(),
			summary.getKills()).getVariant());
		record.setNpcKills(summary.getNpcKills().isEmpty() ? null : new ArrayList<>(summary.getNpcKills()));
		// From the kills per NPC name and the boss kill counts just copied.
		record.setBossKills(TaskVariants.bossKills(record));
		summary.getSetupKills().copyTo(record);
		summary.getSetupTags().copyTo(record);
		return record;
	}

	/** The summary's XP gained per skill as stored (possibly empty), or {@code null} when unknown. */
	static Map<String, Long> xpGainedFor(SessionTracker.Summary summary)
	{
		final Map<String, Long> xp = summary.getXpGained();
		return xp == null ? null : new TreeMap<>(xp);
	}

	/**
	 * Captures unit prices for the record's loot (and supplies, when present) and sets the value totals. Called once,
	 * when the record is saved, on whatever thread the lookup requires (the plugin's lookup uses the client thread).
	 * Loot totals are set even when no loot was received (0), so a valued record can be told apart from an older one.
	 * Unit prices are per item; potion supplies are valued per dose (unit price / {@link #supplyDoses}).
	 * Supply totals stay {@code null} when no supplies were recorded. Items whose GE price was unavailable are left out
	 * of {@link #unitGePrices} and the GE totals, and counted in {@link #lootUnpricedItems} /
	 * {@link #suppliesUnpricedItems}.
	 */
	void captureValues(ItemValuation.PriceLookup lookup)
	{
		ItemTally lootTally = ItemTally.fromMap(loot);
		ItemTally suppliesTally = supplies == null ? null : ItemTally.fromMap(supplies);
		ItemValuation.UnitPrices prices = new ItemValuation.UnitPrices();
		ItemValuation.capturePrices(lootTally, lookup, prices);
		ItemValuation.capturePrices(suppliesTally, lookup, prices);
		unitGePrices = prices.getGe().isEmpty() ? null : prices.getGe();
		unitHaPrices = prices.getHa().isEmpty() ? null : prices.getHa();
		lootGeValue = ItemValuation.total(lootTally, prices.getGe());
		lootHaValue = ItemValuation.total(lootTally, prices.getHa());
		if (suppliesTally != null)
		{
			suppliesGeValue = ItemValuation.total(suppliesTally, prices.getGe(), supplyDoses);
			suppliesHaValue = ItemValuation.total(suppliesTally, prices.getHa(), supplyDoses);
		}
		lootUnpricedItems = nullIfZero(ItemValuation.countUnpriced(lootTally, prices.getGe()));
		suppliesUnpricedItems = nullIfZero(ItemValuation.countUnpriced(suppliesTally, prices.getGe()));
	}

	/**
	 * Adds loot that came after the record was saved (Araxxor's harvest after the task-completing kill), as if it
	 * had come before the save. The items join {@link #loot} and its notable stacks join {@link #notableDrops}
	 * ({@link NotableDrops#add}: the most valuable are kept). A valued record ({@link LedgerHistory#isValued}) also takes
	 * the new items' unit prices, captured when the loot came ({@code prices}, by {@link #captureValues}' rules), where it
	 * has none of its own (an item it already priced keeps its saved price), and its loot totals and unpriced count are
	 * worked out again from them, as {@link #captureValues} works them out. Supplies are unchanged. A record saved
	 * without values gets the items and notable drops, no prices.
	 *
	 * @param items  the loot
	 * @param prices the loot's unit prices when it came, or {@code null} when it could not be priced
	 * @param drops  the loot's notable stacks, or {@code null} when none
	 * @return whether the record changed: {@code false} only for no loot
	 */
	boolean addLateLoot(ItemTally items, ItemValuation.UnitPrices prices, List<NotableDrop> drops)
	{
		if (items == null || items.isEmpty())
		{
			return false;
		}
		final ItemTally lootTally = ItemTally.fromMap(loot);
		lootTally.merge(items);
		loot = lootTally.toMap();
		final List<NotableDrop> notable = NotableDrops.add(notableDrops, drops);
		notableDrops = notable.isEmpty() ? null : notable;
		if (lootGeValue == null)
		{
			return true;
		}
		final Map<Integer, Long> ge = unitGePrices == null ? new TreeMap<>() : new TreeMap<>(unitGePrices);
		final Map<Integer, Long> ha = unitHaPrices == null ? new TreeMap<>() : new TreeMap<>(unitHaPrices);
		if (prices != null)
		{
			for (int id : items.itemIds())
			{
				final Long gePrice = prices.getGe().get(id);
				if (gePrice != null)
				{
					ge.putIfAbsent(id, gePrice);
				}
				final Long haPrice = prices.getHa().get(id);
				if (haPrice != null)
				{
					ha.putIfAbsent(id, haPrice);
				}
			}
		}
		unitGePrices = ge.isEmpty() ? null : ge;
		unitHaPrices = ha.isEmpty() ? null : ha;
		lootGeValue = ItemValuation.total(lootTally, unitGePrices);
		lootHaValue = ItemValuation.total(lootTally, unitHaPrices);
		lootUnpricedItems = nullIfZero(ItemValuation.countUnpriced(lootTally, unitGePrices));
		return true;
	}

	private static Integer nullIfZero(int n)
	{
		return n == 0 ? null : n;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.*;
import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.function.*;
import java.util.regex.*;
import java.util.stream.*;
import lombok.*;
import lombok.extern.slf4j.*;
import net.runelite.client.util.*;

/**
 * Reads and writes per-account ledger files ({@code <dir>/<accountHash>.json}) and active (in-progress) session
 * files ({@code <dir>/<accountHash>.active.json}). This class performs blocking file
 * IO and must not be called on the client thread or the Swing event dispatch thread.
 *
 * <p>A record that could not be appended can be kept in a side file ({@code <dir>/<accountHash>.unsaved-<id>.json},
 * {@link #writeUnsaved}) and appended on a later try ({@link #appendUnsaved}), which deletes the side file once the
 * record is in the ledger.</p>
 *
 * <p>The ledger file also holds the assignments that ended without a saved session ({@link AssignmentEntry}), in an
 * optional {@code assignments} list beside the records. Every rewrite keeps that list as read, and a file without it
 * stays without it until an entry is added. Loading the records never returns entries: they are not played tasks.</p>
 *
 * <p>The directory comes from a {@link DirectorySource} that is asked on the first file operation (so on the same
 * thread as all other IO) and again on later operations until it succeeds; once resolved it is kept. While it cannot
 * be resolved, every operation fails with an {@link IOException}.</p>
 *
 * <p><b>Schema policy</b> (stated here only; other docs refer to it). {@link #FILE_SCHEMA_VERSION} and
 * {@link SessionSnapshot#CURRENT_SCHEMA_VERSION} are raised only for a change an older build cannot read safely: a
 * field whose type or meaning changes, or a field that is removed. A new field is added without a raise and must be
 * nullable and additive (a file without it reads as {@code null}). A build that does not know a field still keeps it
 * in the ledger file: every rewrite (append, delete, note, location and setup edits, late loot, assignment changes)
 * starts from the file's JSON and writes back the members this build does not bind, both top-level members of the file
 * and members of each record and assignment entry that stays in the file. A member counts as unknown when it is missing after the
 * freshly bound object is serialized again, so it never replaces a known value or an edit. Members nested deeper
 * (inside a loot map, a notable drop and so on) are not kept, and the active session file is replaced as a whole by
 * each new snapshot. Do not add {@code @SerializedName} alternates to these classes without handling them here: a
 * member spelled with an alternate name would be kept as unknown and written back beside the bound one.</p>
 *
 * <p>Every read takes {@code schemaVersion} from the raw JSON before binding it. A ledger or active session file with
 * a higher version than this build supports is never written, moved aside or deleted: the write paths and
 * {@link #readActive} fail with {@link UnsupportedSchemaException}, and {@link #deleteActive} leaves it alone.
 * {@link #load} still reads a newer ledger file on a best-effort basis, and fails with
 * {@link UnsupportedSchemaException} if it does not bind. Only a file that is not valid JSON for this layout at a
 * supported version is moved aside (renamed with a {@code .corrupt-<time>} suffix) when it would be written.</p>
 *
 * <p><b>Migration on read.</b> A raise may come with a migration of older records, done where records are read (the
 * ledger file and kept side files) and in memory only, after the unknown members are taken: a migrated record's saved
 * form changes when the file is next written. Version 3 migrates 1.x records' setup tags and gives them the boss flag
 * ({@link SetupMigration}).</p>
 */
@Slf4j
public class LedgerStore
{
	/**
	 * Version of the ledger files this build writes; see the schema policy in the class comment. Version 2 (records
	 * with loot, supplies and values) replaced 1 because builds before it rewrote the file without the fields they did
	 * not know; those builds refuse to write a version 2 file. Fields added since are additive and kept by every
	 * rewrite, so they did not raise it. Version 1 files are read and upgraded on the next write.
	 *
	 * <p>Version 3 (2.0) adds the records' setup tags ({@link LedgerRecord}'s version 3), which change what a
	 * task's cannon means: the player's override wins over what the supplies show. A 1.x build would ignore the overrides
	 * and could append records the 2.0 rules never saw, so 1.x builds must refuse to write a 2.0 ledger, and they do
	 * (they still read it on a best-effort basis, with their own meaning). Every record below version 3 is migrated
	 * when it is read ({@link SetupMigration}), in memory: its saved form changes only when the file is next written,
	 * and a migrated record is written at version 3, so it is never migrated again. Version 1 and 2 files are read and
	 * upgraded on the next write.</p>
	 */
	static final int FILE_SCHEMA_VERSION = 3;

	/** The member holding a file's schema version, read before binding. */
	private static final String SCHEMA_VERSION = "schemaVersion";

	/** The ledger file is not valid JSON for the expected layout. */
	static class LedgerParseException extends IOException
	{
		LedgerParseException(String message, Throwable cause)
		{
			super(message, cause);
		}
	}

	/** The ledger file was written by a newer plugin version; it is never overwritten by this version. */
	static class UnsupportedSchemaException extends IOException
	{
		UnsupportedSchemaException(String message)
		{
			super(message);
		}
	}

	/**
	 * Kept records ({@link #writeUnsaved}) could not be appended by {@link #appendUnsaved}; their side files are kept
	 * for the next try. The cause is the append's failure.
	 */
	@Getter
	static class UnsavedRecordsException extends IOException
	{
		/** The updated record list after the kept records appended before the failure, or {@code null} if none was. */
		private final transient List<LedgerRecord> records;

		UnsavedRecordsException(String message, Exception cause, List<LedgerRecord> records)
		{
			super(message, cause);
			this.records = records;
		}
	}

	/** Suffix of the kept-record side files. */
	private static final String UNSAVED_SUFFIX = ".json";

	/** A record id usable as is in a side file name. */
	private static final Pattern SAFE_ID = Pattern.compile("[A-Za-z0-9_-]{1,64}");

	/**
	 * Supplies the ledger directory. It may do blocking IO (the plugin's source is {@code Plugin#getPluginDirectory},
	 * which can move a legacy directory), so it is only called from the store's own operations.
	 */
	@FunctionalInterface
	interface DirectorySource
	{
		Filepath get() throws IOException;
	}

	private final DirectorySource directorySource;
	private final Gson gson;
	/** The resolved directory, or {@code null} until {@link #directory()} first succeeds. Guarded by {@code this}. */
	private Filepath directory;

	public LedgerStore(Filepath directory, Gson gson)
	{
		this(() -> directory, gson);
	}

	LedgerStore(DirectorySource directorySource, Gson gson)
	{
		this.directorySource = Objects.requireNonNull(directorySource);
		this.gson = gson;
	}

	/**
	 * The ledger directory, resolved from the {@link DirectorySource} on the first call that succeeds. A failure is
	 * not remembered: the next call asks again.
	 *
	 * @throws IOException if the directory cannot be resolved (a runtime failure of the source is wrapped)
	 */
	synchronized Filepath directory() throws IOException
	{
		if (directory == null)
		{
			final Filepath resolved;
			try
			{
				resolved = directorySource.get();
			}
			catch (RuntimeException e)
			{
				throw new IOException("Unable to resolve the ledger directory", e);
			}
			if (resolved == null)
			{
				throw new IOException("No ledger directory");
			}
			directory = resolved;
		}
		return directory;
	}

	/**
	 * Loads all records for an account. A missing file yields an empty list. Files written by a newer schema are
	 * read on a best-effort basis (unknown fields are ignored); one that does not bind fails with
	 * {@link UnsupportedSchemaException}.
	 *
	 * @throws IOException if the file exists but cannot be read or parsed
	 */
	public synchronized List<LedgerRecord> load(long accountHash) throws IOException
	{
		return records(read(fileFor(accountHash), false));
	}

	/**
	 * Loads an account's records and its assignment entries with one read, like {@link #load}. A file without
	 * entries yields an empty entry list.
	 *
	 * @throws IOException if the file exists but cannot be read or parsed
	 */
	public synchronized Contents loadContents(long accountHash) throws IOException
	{
		final StoredFile file = read(fileFor(accountHash), false);
		return new Contents(records(file), assignments(file));
	}

	/**
	 * Appends a record to the account's file and returns the updated record list.
	 *
	 * <p>If the existing file is not valid JSON for this layout it is moved aside (renamed with a
	 * {@code .corrupt-<time>} suffix) rather than silently overwritten. Any other read failure, or a file with a newer
	 * schema version, fails the append without touching the file. A record whose id is already present is not
	 * appended again.</p>
	 */
	public synchronized List<LedgerRecord> append(long accountHash, LedgerRecord record) throws IOException
	{
		final StoredFile file = readForWrite(fileFor(accountHash));
		List<LedgerRecord> records = records(file);
		if (record.getId() != null && records.stream().anyMatch(r -> record.getId().equals(r.getId())))
		{
			// Already saved (e.g. a crash between appending and deleting the active-session file).
			log.debug("Ledger already contains record {}; not appending again", record.getId());
			return records;
		}
		records.add(record);
		write(accountHash, records, file);
		return records;
	}

	/**
	 * Deletes the record with the given id, if present, and returns the updated record list. Fails without
	 * changing anything if the file cannot be read or has a newer schema version.
	 *
	 * <p>When a record was removed and the account's active session file holds the same session id (left over by a
	 * crash between appending the record and deleting the active file), that file is deleted too, so the deleted
	 * task cannot come back as a restored session. An unreadable or newer-schema active file is never deleted. A kept
	 * side file for the same record ({@link #writeUnsaved}, left over when deleting it failed after its append) is
	 * deleted as well, so a later {@link #appendUnsaved} cannot bring the deleted task back.</p>
	 */
	public synchronized List<LedgerRecord> delete(long accountHash, String id) throws IOException
	{
		final StoredFile file = read(fileFor(accountHash), true);
		List<LedgerRecord> records = records(file);
		if (records.removeIf(r -> Objects.equals(r.getId(), id)))
		{
			write(accountHash, records, file);
			// Same lock (synchronized is reentrant); deleteActive leaves unreadable and newer-schema files alone.
			try
			{
				if (deleteActive(accountHash, id))
				{
					log.debug("Deleted leftover active session file for deleted record {}", id);
				}
			}
			catch (IOException e)
			{
				// The record is deleted; only a leftover active file (if any) may remain and be restored later.
				log.warn("Unable to check the active session file after deleting record {}", id, e);
			}
			if (id != null)
			{
				try
				{
					unsavedFileFor(accountHash, id).deleteIfExists();
				}
				catch (IOException e)
				{
					log.warn("Unable to delete the kept record file of deleted record {}", id, e);
				}
			}
		}
		return records;
	}

	/**
	 * Sets (or, with {@code null}, clears) the note of the record with the given id, if present, and returns the
	 * updated record list. The note is stored as given; callers normalize it ({@link TaskNote#normalize}). The file is
	 * only rewritten when the note changes. Fails without changing anything if the file cannot be read or has a newer
	 * schema version.
	 */
	public synchronized List<LedgerRecord> updateNote(long accountHash, String id, String note) throws IOException
	{
		return updateRecord(accountHash, id, r ->
		{
			if (Objects.equals(r.getNote(), note))
			{
				return false;
			}
			r.setNote(note);
			return true;
		});
	}

	/**
	 * Sets (or, with {@code null}, clears) the location name ({@link LedgerRecord#getLocation()}) of the record with the
	 * given id, if present, and returns the updated record list; its region and everything else are kept. The name is
	 * stored as given; callers normalize it ({@link TaskLocation#normalizeName}). Rewritten and failing like
	 * {@link #updateNote}.
	 */
	public synchronized List<LedgerRecord> updateLocation(long accountHash, String id, String location)
		throws IOException
	{
		return updateRecord(accountHash, id, r ->
		{
			if (Objects.equals(r.getLocation(), location))
			{
				return false;
			}
			r.setLocation(location);
			return true;
		});
	}

	/**
	 * Sets the player's setup overrides ({@link SetupOverrides}: cannon, style and gear, each {@code null} to clear it)
	 * of the record with the given id, if present, and returns the updated record list; its detected tags and everything
	 * else are kept. Rewritten and failing like {@link #updateNote}.
	 */
	public synchronized List<LedgerRecord> updateSetup(long accountHash, String id, SetupOverrides overrides)
		throws IOException
	{
		final SetupOverrides value = overrides == null ? SetupOverrides.NONE : overrides;
		return updateRecord(accountHash, id, r ->
		{
			if (SetupOverrides.from(r).equals(value))
			{
				return false;
			}
			value.copyTo(r);
			return true;
		});
	}

	/**
	 * Adds loot that came after the record with the given id was saved, if present, and returns the updated record list
	 * (Araxxor's harvest after its task-completing kill): its items, its unit prices where the record has none and
	 * its notable stacks, with the record's loot values worked out again ({@link LedgerRecord#addLateLoot}); everything
	 * else is kept. Rewritten and failing like {@link #updateNote}.
	 *
	 * @param prices the loot's unit prices when it came, or {@code null} when it could not be priced
	 * @param drops  the loot's notable stacks, or {@code null} when none
	 */
	public synchronized List<LedgerRecord> addLoot(long accountHash, String id, ItemTally loot,
		ItemValuation.UnitPrices prices, List<NotableDrop> drops) throws IOException
	{
		return updateRecord(accountHash, id, r -> r.addLateLoot(loot, prices, drops));
	}

	/**
	 * Applies {@code change} to the record with the given id, if present (it returns whether it changed the record),
	 * and rewrites the file only when it did. Fails without changing anything if the file cannot be read or has a newer
	 * schema version.
	 */
	private List<LedgerRecord> updateRecord(long accountHash, String id, Predicate<LedgerRecord> change)
		throws IOException
	{
		final StoredFile file = read(fileFor(accountHash), true);
		List<LedgerRecord> records = records(file);
		boolean changed = false;
		for (LedgerRecord r : records)
		{
			if (id != null && id.equals(r.getId()) && change.test(r))
			{
				changed = true;
			}
		}
		if (changed)
		{
			write(accountHash, records, file);
		}
		return records;
	}

	/**
	 * Adds an assignment entry to the account's file, keeping the newest {@link AssignmentLog#MAX_ENTRIES}, and returns
	 * the updated entries. With {@code checkRecords} the entry is left out when the saved records suggest its
	 * assignment was played in an earlier run ({@link AssignmentLog#playedBefore}). Fails like {@link #append} (an
	 * unparseable file is moved aside; a newer schema is never overwritten).
	 */
	public synchronized List<AssignmentEntry> appendAssignment(long accountHash, AssignmentEntry entry,
		boolean checkRecords) throws IOException
	{
		final StoredFile file = readForWrite(fileFor(accountHash));
		final List<LedgerRecord> records = records(file);
		final List<AssignmentEntry> assignments = assignments(file);
		if (checkRecords && AssignmentLog.playedBefore(records, entry))
		{
			log.debug("Assignment {} looks played in an earlier run; not adding it", entry.getMonster());
			return assignments;
		}
		final List<AssignmentEntry> updated = AssignmentLog.add(assignments, entry);
		writeFile(accountHash, records, updated, file);
		return updated;
	}

	/**
	 * Deletes the assignment entry with the given id, if present, and returns the updated entries. Fails without
	 * changing anything if the file cannot be read or has a newer schema version. Records are never touched.
	 */
	public synchronized List<AssignmentEntry> deleteAssignment(long accountHash, String id) throws IOException
	{
		final StoredFile file = read(fileFor(accountHash), true);
		final List<AssignmentEntry> assignments = assignments(file);
		if (id != null && assignments.removeIf(e -> id.equals(e.getId())))
		{
			writeFile(accountHash, records(file), assignments, file);
		}
		return assignments;
	}

	/**
	 * Atomically replaces the account's records with the given ones, keeping the file's assignment entries (with their
	 * unknown members) and its top-level members this build does not know. Unknown record members are kept only for
	 * record objects bound by the store's own read for that rewrite; the records given here never are (this call reads
	 * the file itself), so they are written with their known fields only. Fails like {@link #delete} if the file cannot
	 * be read or has a newer schema version.
	 */
	synchronized void write(long accountHash, List<LedgerRecord> records) throws IOException
	{
		write(accountHash, records, read(fileFor(accountHash), true));
	}

	/**
	 * Atomically replaces the account's file with the given records, keeping the assignment entries and unknown
	 * members of {@code read} (the file as read for writing before the change, or {@code null}).
	 */
	private void write(long accountHash, List<LedgerRecord> records, StoredFile read) throws IOException
	{
		writeFile(accountHash, records, assignments(read), read);
	}

	/**
	 * Atomically replaces the account's file (write to a temp file, then move). An empty entry list is not written, so
	 * a file without entries keeps the layout older builds wrote. The members of {@code read} (the file as read for
	 * writing, or {@code null}) that this build does not bind are written back after the known ones: top-level members
	 * of the file, and members of each record and entry that is still in the file.
	 */
	private void writeFile(long accountHash, List<LedgerRecord> records, List<AssignmentEntry> assignments,
		StoredFile read) throws IOException
	{
		LedgerFile file = new LedgerFile();
		file.records = new ArrayList<>(records);
		file.assignments = assignments == null || assignments.isEmpty() ? null : new ArrayList<>(assignments);
		final JsonObject tree = gson.toJsonTree(file).getAsJsonObject();
		if (read != null)
		{
			addUnknownItemMembers(tree.get("records"), file.records, read.unknownItemMembers);
			addUnknownItemMembers(tree.get("assignments"), file.assignments, read.unknownItemMembers);
			addMissingMembers(tree, read.unknownMembers);
		}
		writeAtomically(fileFor(accountHash), tree);
	}

	/** Adds each item's unknown members (if any) to its object in {@code tree}, the serialized {@code items}. */
	private static void addUnknownItemMembers(JsonElement tree, List<?> items, Map<Object, JsonObject> unknown)
	{
		if (unknown.isEmpty() || items == null || tree == null || !tree.isJsonArray())
		{
			return;
		}
		final JsonArray array = tree.getAsJsonArray();
		for (int i = 0; i < Math.min(array.size(), items.size()); i++)
		{
			final JsonObject members = unknown.get(items.get(i));
			if (members != null && array.get(i).isJsonObject())
			{
				addMissingMembers(array.get(i).getAsJsonObject(), members);
			}
		}
	}

	/** Adds the members of {@code members} that {@code target} does not have, after its own. */
	private static void addMissingMembers(JsonObject target, JsonObject members)
	{
		for (Map.Entry<String, JsonElement> member : members.entrySet())
		{
			if (!target.has(member.getKey()))
			{
				target.add(member.getKey(), member.getValue());
			}
		}
	}

	private void writeAtomically(Filepath target, Object content) throws IOException
	{
		final Filepath dir = directory();
		dir.createDirectories();
		final Filepath temp = dir.createTempFile(target.getFileName(), ".tmp");
		try
		{
			// A strict encoder, as Files.newBufferedWriter uses: unencodable text fails the write instead of
			// being replaced.
			try (Writer writer = new BufferedWriter(
				new OutputStreamWriter(temp.openOutputStream(), StandardCharsets.UTF_8.newEncoder())))
			{
				gson.toJson(content, writer);
			}
			try
			{
				temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		finally
		{
			temp.deleteIfExists();
		}
	}

	/**
	 * Atomically writes the account's active (in-progress) session file. An unparseable existing file is moved
	 * aside; a file with a newer schema version is never overwritten ({@link UnsupportedSchemaException}).
	 */
	public synchronized void writeActive(long accountHash, SessionSnapshot snapshot) throws IOException
	{
		Filepath path = activeFileFor(accountHash);
		try
		{
			readActiveFile(path);
		}
		catch (LedgerParseException e)
		{
			moveAside(path, e);
		}
		writeAtomically(path, snapshot);
	}

	/**
	 * Reads the account's active session file.
	 *
	 * <ul>
	 *     <li>Missing file: {@code null}.</li>
	 *     <li>Unparseable file: moved aside, {@code null}.</li>
	 *     <li>Newer schema version: {@link UnsupportedSchemaException}; the file is left untouched.</li>
	 *     <li>A session whose id is already in the ledger (crash between append and delete), or kept in a side file
	 *     by a failed save ({@link #writeUnsaved}): the file is deleted and {@code null} is returned, so a session can
	 *     never become two records and a stale snapshot never replaces the kept record.</li>
	 * </ul>
	 */
	public synchronized SessionSnapshot readActive(long accountHash) throws IOException
	{
		Filepath path = activeFileFor(accountHash);
		SessionSnapshot snapshot;
		try
		{
			snapshot = readActiveFile(path);
		}
		catch (LedgerParseException e)
		{
			moveAside(path, e);
			return null;
		}
		if (snapshot == null)
		{
			return null;
		}
		final String sessionId = snapshot.getSessionId();
		if (sessionId != null && isKept(accountHash, sessionId))
		{
			// Checked before the ledger, which may be the very file that cannot be read.
			log.debug("Active session {} is kept as an unsaved record; removing the active file", sessionId);
			path.deleteIfExists();
			return null;
		}
		if (sessionId != null)
		{
			List<LedgerRecord> records;
			try
			{
				records = load(accountHash);
			}
			catch (IOException e)
			{
				// Cannot check for duplicates; append's id guard still prevents a second record.
				log.warn("Unable to read ledger {} while checking active session", fileFor(accountHash), e);
				return snapshot;
			}
			if (records.stream().anyMatch(r -> sessionId.equals(r.getId())))
			{
				log.debug("Active session {} is already in the ledger; removing the active file", sessionId);
				path.deleteIfExists();
				return null;
			}
		}
		return snapshot;
	}

	/**
	 * Deletes the account's active session file if it holds the given session. A file for a different session, an
	 * unparseable file, or a newer-schema file is left untouched.
	 *
	 * @return whether the file was deleted
	 */
	public synchronized boolean deleteActive(long accountHash, String sessionId) throws IOException
	{
		Filepath path = activeFileFor(accountHash);
		SessionSnapshot snapshot;
		try
		{
			snapshot = readActiveFile(path);
		}
		catch (LedgerParseException | UnsupportedSchemaException e)
		{
			return false;
		}
		if (snapshot == null || sessionId == null || !sessionId.equals(snapshot.getSessionId()))
		{
			return false;
		}
		path.deleteIfExists();
		return true;
	}

	/**
	 * Deletes the account's active session file if it holds an Ended assignment's marker
	 * ({@link SessionSnapshot#isEndedMarker()}), for Track again. A session's file, an unparseable file, or a
	 * newer-schema file is left untouched.
	 *
	 * @return whether the file was deleted
	 */
	public synchronized boolean deleteEndedMarker(long accountHash) throws IOException
	{
		Filepath path = activeFileFor(accountHash);
		SessionSnapshot snapshot;
		try
		{
			snapshot = readActiveFile(path);
		}
		catch (LedgerParseException | UnsupportedSchemaException e)
		{
			return false;
		}
		if (snapshot == null || !snapshot.isEndedMarker())
		{
			return false;
		}
		path.deleteIfExists();
		return true;
	}

	/** The account's active session file, {@code <dir>/<accountHash>.active.json}. */
	Filepath activeFileFor(long accountHash) throws IOException
	{
		return directory().joinSegment(Long.toString(accountHash) + ".active.json");
	}

	/**
	 * Reads the active session file, or {@code null} if it does not exist.
	 *
	 * @throws UnsupportedSchemaException if its schema version is newer than supported (checked before binding)
	 * @throws LedgerParseException if it is not valid JSON for the snapshot layout
	 */
	private SessionSnapshot readActiveFile(Filepath path) throws IOException
	{
		final JsonObject raw = readJsonObject(path, "active session file");
		if (raw == null)
		{
			return null;
		}
		checkSupported(raw, SessionSnapshot.CURRENT_SCHEMA_VERSION, "Active session file " + path);
		try
		{
			return gson.fromJson(raw, SessionSnapshot.class);
		}
		catch (JsonParseException e)
		{
			throw new LedgerParseException("Unable to parse active session file " + path, e);
		}
	}

	private static void moveAside(Filepath path, Exception cause) throws IOException
	{
		Filepath backup = path.getParent().joinSegment(path.getFileName() + ".corrupt-" + System.currentTimeMillis());
		log.warn("File {} is not valid JSON for this layout; moving it to {}", path, backup, cause);
		path.moveTo(backup, StandardCopyOption.REPLACE_EXISTING);
	}

	/**
	 * Keeps a record whose {@link #append} failed in its own side file ({@link #unsavedFileFor}), written atomically
	 * like the ledger, so {@link #appendUnsaved} can save it later. Writing it again for the same record id replaces
	 * the earlier copy, except that a kept completed record is never replaced by a partial one (the partial would be a
	 * stale copy of the same session). A kept file that is not valid JSON for its layout is moved aside first.
	 *
	 * @return whether the record was written ({@code false} when a kept completed record was kept instead)
	 * @throws UnsupportedSchemaException if a kept file for the same id has a newer schema version; it is left alone
	 * @throws IOException if the file cannot be written (for example the directory is unavailable or the record holds
	 * text that cannot be encoded)
	 */
	public synchronized boolean writeUnsaved(long accountHash, LedgerRecord record) throws IOException
	{
		Objects.requireNonNull(record);
		final Filepath path = unsavedFileFor(accountHash, record.getId());
		if (record.getId() != null)
		{
			try
			{
				final LedgerRecord existing = readUnsavedFile(path);
				if (existing != null && existing.isCompleted() && !record.isCompleted()
					&& record.getId().equals(existing.getId()))
				{
					log.debug("Keeping the completed record {} instead of a partial copy", record.getId());
					return false;
				}
			}
			catch (LedgerParseException e)
			{
				moveAside(path, e);
			}
		}
		final UnsavedFile file = new UnsavedFile();
		file.record = record;
		writeAtomically(path, file);
		return true;
	}

	/**
	 * Whether a record with the given id is kept in a side file ({@link #writeUnsaved}). A side file written by a newer
	 * schema counts as kept; one that is not valid JSON for its layout does not.
	 */
	private boolean isKept(long accountHash, String id) throws IOException
	{
		final Filepath path = unsavedFileFor(accountHash, id);
		try
		{
			final LedgerRecord kept = readUnsavedFile(path);
			return kept != null && id.equals(kept.getId());
		}
		catch (UnsupportedSchemaException e)
		{
			return true;
		}
		catch (LedgerParseException e)
		{
			return false;
		}
	}

	/**
	 * Appends the account's kept records ({@link #writeUnsaved}) to its ledger, oldest file name first, and deletes
	 * each side file after its record is in the ledger. A record already in the ledger is not appended again
	 * ({@link #append}'s id guard), so a retry after a failed delete saves it only once; the account's active session
	 * file for the same session is removed as {@link #append}'s callers do. A side file that is not valid JSON for its
	 * layout is moved aside; one written by a newer schema is left alone and skipped.
	 *
	 * @return the updated record list, or {@code null} if no kept record was appended
	 * @throws UnsavedRecordsException if a kept record could not be appended; it and the ones after it stay kept, and
	 * the exception carries the updated list after the ones appended before it
	 * @throws IOException if the side files cannot be listed
	 */
	public synchronized List<LedgerRecord> appendUnsaved(long accountHash) throws IOException
	{
		List<LedgerRecord> updated = null;
		for (Filepath path : unsavedFiles(accountHash))
		{
			final LedgerRecord record;
			try
			{
				record = readUnsavedFile(path);
			}
			catch (UnsupportedSchemaException e)
			{
				log.warn("Skipping kept Slayer Ledger record {} written by a newer version", path, e);
				continue;
			}
			catch (LedgerParseException e)
			{
				moveAside(path, e);
				continue;
			}
			if (record == null)
			{
				continue;
			}
			try
			{
				updated = append(accountHash, record);
			}
			catch (IOException | RuntimeException e)
			{
				throw new UnsavedRecordsException("Unable to save kept record " + path, e, updated);
			}
			log.debug("Saved kept Slayer Ledger record {}", record.getId());
			try
			{
				path.deleteIfExists();
			}
			catch (IOException e)
			{
				// The record is saved; the next retry finds it in the ledger and only deletes the file.
				log.warn("Unable to delete kept record file {} after saving it", path, e);
			}
			try
			{
				deleteActive(accountHash, record.getId());
			}
			catch (IOException e)
			{
				// readActive removes an active file whose session is already in the ledger.
				log.warn("Unable to check the active session file after saving kept record {}", record.getId(), e);
			}
		}
		return updated;
	}

	/**
	 * The account's kept-record side files ({@code <accountHash>.unsaved-<key>.json}), sorted by name; empty if there
	 * are none or the directory does not exist yet.
	 */
	List<Filepath> unsavedFiles(long accountHash) throws IOException
	{
		final Filepath dir = directory();
		if (!dir.isDirectory())
		{
			return Collections.emptyList();
		}
		final String prefix = unsavedPrefix(accountHash);
		final List<Filepath> files = new ArrayList<>();
		try (Stream<Filepath> entries = dir.walk(1))
		{
			entries.filter(p -> !p.equals(dir))
				.filter(p ->
				{
					final String name = p.getFileName();
					// Temp files (".tmp") and corrupt backups (".corrupt-<time>") end differently.
					return name.startsWith(prefix) && name.endsWith(UNSAVED_SUFFIX) && p.isFile();
				})
				.forEach(files::add);
		}
		files.sort(Comparator.comparing(Filepath::getFileName));
		return files;
	}

	/**
	 * The side file keeping a record of the account that could not be saved:
	 * {@code <dir>/<accountHash>.unsaved-<key>.json}. The key is the record id when it is a plain id (letters, digits,
	 * {@code -} and {@code _}, as the plugin's UUIDs are), otherwise a UUID derived from it (random for a record
	 * without an id), so every name passes {@code Filepath}'s checks and one record id always maps to one file.
	 */
	Filepath unsavedFileFor(long accountHash, String id) throws IOException
	{
		final String key;
		if (id != null && SAFE_ID.matcher(id).matches())
		{
			key = id;
		}
		else if (id != null)
		{
			key = UUID.nameUUIDFromBytes(id.getBytes(StandardCharsets.UTF_8)).toString();
		}
		else
		{
			key = UUID.randomUUID().toString();
		}
		return directory().joinSegment(unsavedPrefix(accountHash) + key + UNSAVED_SUFFIX);
	}

	private static String unsavedPrefix(long accountHash)
	{
		return Long.toString(accountHash) + ".unsaved-";
	}

	/**
	 * Reads a kept-record side file, or {@code null} if it no longer exists.
	 *
	 * @throws UnsupportedSchemaException if its schema version is newer than supported (checked before binding)
	 * @throws LedgerParseException if it is not valid JSON for its layout or holds no record
	 */
	private LedgerRecord readUnsavedFile(Filepath path) throws IOException
	{
		final JsonObject raw = readJsonObject(path, "kept record file");
		if (raw == null)
		{
			if (path.exists())
			{
				throw new LedgerParseException("The kept record file " + path + " is empty", null);
			}
			return null;
		}
		checkSupported(raw, FILE_SCHEMA_VERSION, "Kept record file " + path);
		final UnsavedFile file;
		try
		{
			file = gson.fromJson(raw, UnsavedFile.class);
		}
		catch (JsonParseException e)
		{
			throw new LedgerParseException("Unable to parse kept record file " + path, e);
		}
		if (file == null || file.record == null)
		{
			throw new LedgerParseException("The kept record file " + path + " holds no record", null);
		}
		// A 1.x build's kept record is migrated like one in the ledger.
		SetupMigration.migrate(file.record);
		return file.record;
	}

	/** The account's ledger file, {@code <dir>/<accountHash>.json}. */
	Filepath fileFor(long accountHash) throws IOException
	{
		return directory().joinSegment(Long.toString(accountHash) + ".json");
	}

	/**
	 * Opens a file for reading as UTF-8 with a strict decoder, as {@code Files.newBufferedReader} does, so malformed
	 * input fails the read (and is reported as a parse error) instead of being replaced and later written back.
	 */
	private static Reader openReader(Filepath path) throws IOException
	{
		return new BufferedReader(new InputStreamReader(path.openInputStream(), StandardCharsets.UTF_8.newDecoder()));
	}

	/**
	 * Reads a file as a JSON object, without binding it.
	 *
	 * @return the object, or {@code null} if the file does not exist or holds no JSON value (or {@code null})
	 * @throws LedgerParseException if it is not valid UTF-8 JSON or not a JSON object
	 */
	private JsonObject readJsonObject(Filepath path, String what) throws IOException
	{
		if (!path.exists())
		{
			return null;
		}
		final JsonElement tree;
		try (Reader reader = openReader(path))
		{
			tree = gson.fromJson(reader, JsonElement.class);
		}
		catch (JsonParseException e)
		{
			// JsonSyntaxException is a subclass of JsonParseException; malformed UTF-8 arrives wrapped in one.
			throw new LedgerParseException("Unable to parse " + what + " " + path, e);
		}
		if (tree == null || tree.isJsonNull())
		{
			return null;
		}
		if (!tree.isJsonObject())
		{
			throw new LedgerParseException("The " + what + " " + path + " is not a JSON object", null);
		}
		return tree.getAsJsonObject();
	}

	/**
	 * Reads the ledger file for a write ({@link #read} with {@code forWrite}), moving it aside if it is not valid JSON
	 * for this layout; {@code null} is then returned, as for a missing file. A newer schema version fails with
	 * {@link UnsupportedSchemaException} and is never moved aside.
	 */
	private StoredFile readForWrite(Filepath path) throws IOException
	{
		try
		{
			return read(path, true);
		}
		catch (LedgerParseException e)
		{
			moveAside(path, e);
			return null;
		}
	}

	/**
	 * Reads and binds the ledger file. Its schema version is read before binding: for a write ({@code forWrite}) a
	 * newer version fails with {@link UnsupportedSchemaException}; otherwise a newer file is bound on a best-effort
	 * basis, and fails with {@link UnsupportedSchemaException} if it does not bind. For a write, the members this build
	 * does not bind are kept for {@link #writeFile}.
	 *
	 * @return the file, or {@code null} if it does not exist
	 * @throws LedgerParseException if a file at a supported version is not valid JSON for this layout
	 */
	private StoredFile read(Filepath path, boolean forWrite) throws IOException
	{
		final JsonObject raw = readJsonObject(path, "ledger file");
		if (raw == null)
		{
			return null;
		}
		final String description = "Ledger file " + path;
		if (forWrite)
		{
			checkSupported(raw, FILE_SCHEMA_VERSION, description);
		}
		final LedgerFile file;
		try
		{
			file = gson.fromJson(raw, LedgerFile.class);
		}
		catch (JsonParseException e)
		{
			if (isNewer(raw, FILE_SCHEMA_VERSION))
			{
				throw new UnsupportedSchemaException(description + " has schema version "
					+ raw.get(SCHEMA_VERSION).getAsString() + ", newer than supported version " + FILE_SCHEMA_VERSION
					+ ", and this version cannot read it");
			}
			throw new LedgerParseException("Unable to parse ledger file " + path, e);
		}
		if (file == null)
		{
			return null;
		}
		if (!forWrite)
		{
			return new StoredFile(file, new JsonObject());
		}
		// Computed now, before any caller edits the bound objects: a member is unknown when serializing the freshly
		// bound object does not produce it.
		final StoredFile stored = new StoredFile(file, unknownMembers(raw, file));
		collectUnknownItemMembers(raw.get("records"), file.records, stored.unknownItemMembers);
		collectUnknownItemMembers(raw.get("assignments"), file.assignments, stored.unknownItemMembers);
		return stored;
	}

	/** Whether the object's {@code schemaVersion} is a number above {@code supported}. */
	private static boolean isNewer(JsonObject raw, int supported)
	{
		final JsonElement version = raw.get(SCHEMA_VERSION);
		if (version == null || !version.isJsonPrimitive())
		{
			return false;
		}
		try
		{
			return version.getAsDouble() > supported;
		}
		catch (NumberFormatException e)
		{
			// Not a number: binding decides whether the file is usable.
			return false;
		}
	}

	/** Fails with {@link UnsupportedSchemaException} if the object's schema version is above {@code supported}. */
	private static void checkSupported(JsonObject raw, int supported, String description)
		throws UnsupportedSchemaException
	{
		if (isNewer(raw, supported))
		{
			throw new UnsupportedSchemaException(description + " has schema version "
				+ raw.get(SCHEMA_VERSION).getAsString() + ", newer than supported version " + supported
				+ "; refusing to change it");
		}
	}

	/**
	 * Keeps, for each item of {@code bound} (bound from the array {@code raw}, in the same order), the members of its
	 * JSON object that this build does not bind ({@link #unknownMembers}).
	 */
	private void collectUnknownItemMembers(JsonElement raw, List<?> bound, Map<Object, JsonObject> out)
	{
		if (raw == null || !raw.isJsonArray() || bound == null || raw.getAsJsonArray().size() != bound.size())
		{
			return;
		}
		final JsonArray array = raw.getAsJsonArray();
		for (int i = 0; i < array.size(); i++)
		{
			final Object item = bound.get(i);
			if (item != null && array.get(i).isJsonObject())
			{
				final JsonObject unknown = unknownMembers(array.get(i).getAsJsonObject(), item);
				if (unknown.size() > 0)
				{
					out.put(item, unknown);
				}
			}
		}
	}

	/**
	 * The members of {@code raw} that this build does not bind, in file order: those missing from {@code bound} (the
	 * object bound from {@code raw}, before any change) when it is serialized again. Members whose value is
	 * {@code null} are left out, so a known field written as an explicit {@code null} is not mistaken for an unknown
	 * one (Gson leaves {@code null} fields out); an unknown {@code null} reads the same as a missing member.
	 */
	private JsonObject unknownMembers(JsonObject raw, Object bound)
	{
		final JsonElement tree = gson.toJsonTree(bound);
		final Set<String> known = tree.isJsonObject() ? tree.getAsJsonObject().keySet() : Collections.emptySet();
		final JsonObject unknown = new JsonObject();
		for (Map.Entry<String, JsonElement> member : raw.entrySet())
		{
			if (!member.getValue().isJsonNull() && !known.contains(member.getKey()))
			{
				unknown.add(member.getKey(), member.getValue());
			}
		}
		return unknown;
	}

	/**
	 * The file's records without nulls, in file order, each migrated if it is older ({@link SetupMigration}; in place,
	 * so a later call for the same file finds it done). The unknown members were taken when the file was read, before
	 * this, so a migrated record keeps them.
	 */
	private static List<LedgerRecord> records(StoredFile stored)
	{
		List<LedgerRecord> records = new ArrayList<>();
		final LedgerFile file = stored == null ? null : stored.file;
		if (file != null && file.records != null)
		{
			for (LedgerRecord r : file.records)
			{
				if (r != null)
				{
					SetupMigration.migrate(r);
					records.add(r);
				}
			}
		}
		return records;
	}

	/** The file's assignment entries without nulls, in file order; empty when it has none. */
	private static List<AssignmentEntry> assignments(StoredFile stored)
	{
		List<AssignmentEntry> assignments = new ArrayList<>();
		final LedgerFile file = stored == null ? null : stored.file;
		if (file != null && file.assignments != null)
		{
			for (AssignmentEntry e : file.assignments)
			{
				if (e != null)
				{
					assignments.add(e);
				}
			}
		}
		return assignments;
	}

	/** An account's records and assignment entries, read together. */
	@Getter
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	static final class Contents
	{
		/** The played tasks. */
		private final List<LedgerRecord> records;
		/** The assignments that ended without a saved session; never played tasks (see {@link AssignmentEntry}). */
		private final List<AssignmentEntry> assignments;
	}

	/**
	 * A ledger file as read: the bound layout and, when read for a write, the JSON members this build does not bind,
	 * to be written back (see the schema policy in the class comment).
	 */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class StoredFile
	{
		final LedgerFile file;
		/** The file's top-level members this build does not bind. */
		final JsonObject unknownMembers;
		/** The members each bound record and entry has that this build does not bind, for those that have any. */
		final Map<Object, JsonObject> unknownItemMembers = new IdentityHashMap<>();
	}

	/**
	 * On-disk file layout. {@code assignments} was added to schema 2 as an optional list (see {@link AssignmentEntry}
	 * and the schema policy in the class comment); it is {@code null} (left out of the file) while there are none.
	 */
	static class LedgerFile
	{
		int schemaVersion = FILE_SCHEMA_VERSION;
		List<LedgerRecord> records = new ArrayList<>();
		List<AssignmentEntry> assignments;
	}

	/** On-disk layout of a kept-record side file ({@link #writeUnsaved}): one record, at the ledger's schema. */
	static class UnsavedFile
	{
		int schemaVersion = FILE_SCHEMA_VERSION;
		LedgerRecord record;
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import javax.swing.*;
import javax.swing.border.*;
import net.runelite.client.ui.*;

/**
 * The sidebar's colour tokens and fonts (docs/DESIGN_PRINCIPLES.md 4.1, 4.4), with the values of the visual direction
 * the owner chose, A: OSRS-native (2026-11-09). Every colour of the sidebar comes from here: a token means the
 * same thing wherever it is used, and no other sidebar class writes a colour literal. Where a value is one of
 * RuneLite's own colours, the token refers to the {@link ColorScheme} or {@link JagexColors} constant rather than
 * copying its hex.
 * The text tokens' contrast ratios against {@link #CARD} and {@link #PAGE} are in the doc's 4.2 table and
 * {@code scripts/contrast.py}.
 *
 * <p>The fonts are the three RuneScape fonts {@link FontManager} returns, at their native size: they are pixel fonts
 * and lose their crisp edges at any other.</p>
 */
final class LedgerTheme
{
	/** The panel's background, under every flat section. */
	static final Color PAGE = new Color(0x2A241C);
	/** The two raised cards' background (the live task and, from 9b, the advisor). */
	static final Color CARD = new Color(0x3E3529);
	/**
	 * A flat row's background under the mouse, which shows it can be clicked (DESIGN_PRINCIPLES.md 3.3, 3.7 Hover, 4.2's
	 * {@code hover}; the Task history's rows, 9c, and Skipped / blocked's, 9d): the card's stone, so every text token
	 * keeps its 4.5:1 there ({@link #HINT}, the lowest, 4.80:1). Not a card: no bevel goes with it.
	 */
	static final Color HOVER = CARD;
	/** A card's outer bevel line: the card colour times 0.8, as RuneLite's {@code BackgroundComponent} frames. */
	static final Color BEVEL_OUTER = new Color(0x322A21);
	/** A card's inner bevel line: the card colour times 1.2; also the flat sections' 1 px rules. */
	static final Color BEVEL_INNER = new Color(0x4A4031);
	/** The progress bar's empty part. */
	static final Color TRACK = PAGE;
	/** The progress bar's filled part: the game's interface orange (7.14:1 against the track). */
	static final Color BAR_FILL = JagexColors.DARK_ORANGE_INTERFACE_TEXT;
	/** Section headers and card names: the game's interface orange {@code #FF981F}. */
	static final Color HEADING = JagexColors.DARK_ORANGE_INTERFACE_TEXT;
	/** Labels: the left side of a row. */
	static final Color LABEL = new Color(0xD2BF94);
	/** Values: the right side of a row. */
	static final Color VALUE = Color.WHITE;
	/** The one key number of an area, in {@link #boldFont()}. */
	static final Color KEY = Color.WHITE;
	/** Quiet text: second lines, the running clock, small notes. */
	static final Color HINT = new Color(0xB3A27E);
	/** A gain, such as a profit; never the only cue (a sign or word goes with it). */
	static final Color GOOD = ColorScheme.GRAND_EXCHANGE_PRICE;
	/**
	 * Warnings, critical warnings and negative values: the game's yellow {@code #FFFF00}. Their level is told by words,
	 * signs and weight, never by another colour.
	 */
	static final Color ALERT = JagexColors.YELLOW_INTERFACE_TEXT;

	/** The parchment of the advisor note ({@link AdvisorCardSection}), the one surface that uses it. */
	static final Color PARCHMENT = new Color(0xD8C8A0);
	/** Text on {@link #PARCHMENT} (8.33:1). */
	static final Color INK = new Color(0x3A2A16);
	/** Quiet text on {@link #PARCHMENT} (5.03:1). */
	static final Color MUTED_INK = new Color(0x5E4B2E);
	/** Negative values and warnings on {@link #PARCHMENT} (5.63:1). */
	static final Color RED_INK = new Color(0x8A1C12);
	/**
	 * The advisor note's 1 px edge (the chosen mockup's) and the 1 px rule between its blocks: a darker
	 * {@link #PARCHMENT}. Not for text.
	 */
	static final Color PARCHMENT_EDGE = new Color(0xB8A678);
	/**
	 * The item cells of the advisor note's Bring grids: {@link #INK} at 14% over {@link #PARCHMENT}, so the slots stand
	 * out from the note as the live grids' stone cells do from the page. Not for text.
	 */
	static final Color PARCHMENT_CELL = new Color(0xC2B28D);

	/** Inside padding of a card, in pixels (as RuneLite's {@code LootTrackerBox} pads its title): 199 px inside. */
	static final int CARD_PADDING = 7;

	private LedgerTheme()
	{
	}

	/** Panel values that matter and history row names: RuneScape Plain 12. */
	static Font plainFont()
	{
		return FontManager.getRunescapeFont();
	}

	/** Card names, section headers and the one key number per area: RuneScape Bold 12. */
	static Font boldFont()
	{
		return FontManager.getRunescapeBoldFont();
	}

	/** Panel body text, second lines and hints: RuneScape Small. */
	static Font smallFont()
	{
		return FontManager.getRunescapeSmallFont();
	}

	/**
	 * A raised card's frame: the two-tone bevel (outer {@link #BEVEL_OUTER}, inner {@link #BEVEL_INNER}, 1 px each)
	 * around {@link #CARD_PADDING} of padding. Square corners, no shadow.
	 */
	static Border cardBorder()
	{
		return BorderFactory.createCompoundBorder(
			BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(BEVEL_OUTER, 1),
				BorderFactory.createLineBorder(BEVEL_INNER, 1)),
			BorderFactory.createEmptyBorder(CARD_PADDING - 2, CARD_PADDING - 2, CARD_PADDING - 2, CARD_PADDING - 2));
	}

	/** Makes {@code card} a raised card: {@link #CARD} with {@link #cardBorder()}. */
	static void styleCard(JComponent card)
	{
		card.setOpaque(true);
		card.setBackground(CARD);
		card.setBorder(cardBorder());
	}

	/** A label in {@code font} and {@code color}. */
	static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * Styles a section header (DESIGN_PRINCIPLES.md 3.3): the title in Bold in {@link #HEADING}, the right-hand
	 * {@code Show}/{@code Hide} (or a value) in Small in {@link #LABEL}, on the page with a 1 px rule under it.
	 */
	static void styleSectionHeader(JComponent header, JLabel title, JLabel right)
	{
		header.setOpaque(true);
		header.setBackground(PAGE);
		header.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, BEVEL_INNER),
			BorderFactory.createEmptyBorder(0, 0, 2, 0)));
		title.setFont(boldFont());
		title.setForeground(HEADING);
		if (right != null)
		{
			right.setFont(smallFont());
			right.setForeground(LABEL);
		}
	}

	/**
	 * Styles a sub-header nested in a block of a flat section (DESIGN_PRINCIPLES.md 3.8; Overall totals' Monsters
	 * assigned and item grids, and a history row's details, 9c): quieter than the block's title above
	 * it, so it is clear where one block ends. The title in Small in {@link #VALUE}, the right-hand
	 * {@code Show}/{@code Hide} or value (if any) in Small in {@link #LABEL}, on the page with no rule under it.
	 */
	static void styleNestedHeader(JComponent header, JLabel title, JLabel right)
	{
		header.setOpaque(true);
		header.setBackground(PAGE);
		header.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
		title.setFont(smallFont());
		title.setForeground(VALUE);
		if (right != null)
		{
			right.setFont(smallFont());
			right.setForeground(LABEL);
		}
	}
}

package com.shmayvan.slayerledger;

import java.time.*;
import java.time.format.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import lombok.*;

/**
 * The shown history's derived views (split from {@link LedgerHistoryModel}): the per-task statistics, the
 * advisor's plan, Overall totals and the "Skipped / blocked" rows.
 * Each is worked out on demand and cached until what it comes from changes: the records ({@link #setHistory}'s
 * version), how they are valued ({@link HistoryValuation#valuationVersion}), item names where they are shown
 * ({@link NameBook#itemNamesVersion}) and the view's own inputs (a grouping, a task). Asking again with
 * nothing changed returns the same object, so the panel's refresh timer never works them out again. The statistics are
 * kept until the model drops them ({@link #clearTaskStatistics}).
 *
 * <p>Off the EDT. The views that scan every record, the advisor's plan and Overall totals, are worked
 * out on a background executor (the plugin's), once per inputs, from an immutable snapshot taken on the EDT: the
 * records list (unmodifiable and replaced, never changed; the records in it are not changed once loaded), for Overall
 * totals' By master the "Skipped / blocked" entries list (the same), the task, its kills left and the potion families
 * for the plan, the "Loot price" mode and a copy of the prices shown ({@link Valued}). Asked for while it is being
 * worked out, such a view returns {@code null} (the plan shown: the same task's previous plan, else {@code null}), and
 * the panel keeps what it shows. The result goes back to the EDT, where it is kept only if it is still the latest one
 * asked for: a result for older inputs (an older records or valuation version, another grouping, other kills left) is
 * dropped. A kept result tells {@link #setOnReady}'s listener, which has the panel redraw. The background work
 * touches no Swing and no mutable state; everything it reads is captured before it is queued and everything it
 * returns is immutable, published to the EDT through the EDT executor's queue.</p>
 *
 * <p>Kept on the EDT, worked out when asked: the per-task statistics ({@link #taskStatistics}), because the live card's
 * time left and the overlay's time per kill decide synchronously from them and ask for region names while building
 * them; the "Skipped / blocked" rows, which are small. Names are asked for on the EDT only.</p>
 *
 * <p>Threading: EDT only, like the model that owns it (except the background work described above). The results are
 * unmodifiable.</p>
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class LedgerViews
{
	private final SessionTracker tracker;
	/** How the records are valued; only read. */
	private final HistoryValuation valuation;
	/** Region and item names; missing ones are asked for. */
	private final NameBook names;
	/** Works out the background views; the plugin's executor (tests: a queue or the calling thread). */
	private final Executor background;
	/** Runs a background view's result on the EDT ({@code SwingUtilities::invokeLater}; tests: the calling thread). */
	private final Executor edt;
	/** Told on the EDT when a background view's result is kept; none until set. */
	private Runnable onReady = () -> { };
	/** Set by {@link #close}: nothing more is worked out or kept. */
	private boolean closed;

	// The history the views come from, as the model last set it (setHistory).
	/** All records, newest first; unmodifiable, replaced and never changed. */
	private List<LedgerRecord> records = Collections.emptyList();
	/** "Skipped / blocked" entries, newest first; unmodifiable. */
	private List<AssignmentEntry> assignments = Collections.emptyList();
	/** The model's version of {@link #records} and {@link #assignments}. */
	private long version;
	/**
	 * Bumped only when {@link #records} change (a new list: they are replaced, never changed), not with the entries,
	 * so a "Skipped / blocked" entry doesn't work out the plan or its potion families again.
	 */
	private long recordsVersion;
	/** The account the records are of; another one drops the kept plan (see {@link #plan}). */
	private long account = SessionTracker.NO_ACCOUNT;
	/** How the records are valued, captured for the background views at {@link Valued#valuationVersion}. */
	private Valued valued;

	/** Per-task aggregates, dropped when the history, the spot table or a region name changes. */
	private final Map<String, TaskStatistics> taskStatisticsCache = new HashMap<>();
	/** How many times a task's statistics were worked out ({@link #getTaskStatisticsBuildCount}). */
	private int taskStatisticsBuilds;
	/** {@link #effectiveSelection} per task and live selection; dropped with the statistics or new history. */
	private final Map<String, TaskSelection> effectiveSelectionCache = new HashMap<>();
	private final Background<TaskPlan> plan = new Background<>();
	/** The records' potion families for the plan ({@link TaskPlanner#potionFamilies}), per records and item names. */
	private final Cached<Map<Integer, String>> potionFamilies = new Cached<>();
	private final Background<List<OverallTotals.Entry>> overallTotals = new Background<>();
	private final Cached<List<AssignmentRow>> assignmentRows = new Cached<>();

	/**
	 * Sets the history the views come from (the model's account, records and entries, newest first, unmodifiable, and
	 * its version); the views are worked out again when next asked for. Another account drops the kept plan and any
	 * still being worked out, so the previous account's is never shown for the same task while the new account's is
	 * worked out. A new records list bumps {@link #recordsVersion}; the same list (new entries only)
	 * doesn't.
	 */
	void setHistory(long account, long version, List<LedgerRecord> records, List<AssignmentEntry> assignments)
	{
		if (account != this.account)
		{
			this.account = account;
			plan.reset();
		}
		this.version = version;
		if (records != this.records)
		{
			recordsVersion++;
		}
		this.records = records;
		this.assignments = assignments;
		effectiveSelectionCache.clear();
	}

	/** Sets what is told, on the EDT, when a view worked out in the background is ready to be shown. */
	void setOnReady(Runnable listener)
	{
		onReady = listener == null ? () -> { } : listener;
	}

	/** The plugin stopped: nothing more is worked out, and results still on their way are dropped. */
	void close()
	{
		closed = true;
	}

	/** How the records are valued now, as an immutable copy made once per valuation version. */
	private Valued valued()
	{
		long current = valuation.valuationVersion();
		if (valued == null || valued.valuationVersion != current)
		{
			valued = new Valued(current, valuation.lootPriceMode(),
				Collections.unmodifiableMap(new HashMap<>(valuation.shownPrices())), valuation.hiddenLoot());
		}
		return valued;
	}

	// ---- Statistics ----

	/** Drops the cached statistics, after the history, the spot table or a region name changed. */
	void clearTaskStatistics()
	{
		taskStatisticsCache.clear();
		effectiveSelectionCache.clear();
	}

	/**
	 * Key of {@link #taskStatistics}: creature key, name as {@link TaskStatistics#normalize} matches it, the selection
	 * the statistics use (version and cannon use, {@link #effectiveSelection}, {@link TaskSelection#key})
	 * and the location (its spot key and the name shown), so a change of location or its name, version or cannon
	 * use, or a first cannon task in the history, gives other statistics. Nothing in the statistics is valued, so
	 * the "Loot price" mode, today's prices and the hidden loot are not part of it.
	 */
	private String taskStatisticsKey(int creatureId, String monster, TaskSelection selection,
		TaskLocation.Here location)
	{
		String name = TaskStatistics.normalize(monster);
		TaskLocation.Here here = location == null ? TaskLocation.Here.UNKNOWN : location;
		return creatureId + "\u0000" + (name == null ? "" : name) + "\u0000"
			+ effectiveSelection(creatureId, monster, selection).key() + "\u0000"
			+ (here.getSpot() == null ? "" : here.getSpot()) + "\u0000" + (here.getName() == null ? "" : here.getName());
	}

	/**
	 * The selection a task's statistics use for the live {@code selection} ({@link TaskStatistics#effectiveSelection}):
	 * cannon tasks only when the history has a completed cannon task of the task's selected version, else tasks
	 * with and without a cannon pooled. Cached with the statistics until {@link #clearTaskStatistics} or new history.
	 */
	private TaskSelection effectiveSelection(int creatureId, String monster, TaskSelection selection)
	{
		TaskSelection requested = selectionOrAny(selection);
		if (!Boolean.TRUE.equals(requested.getCannon()))
		{
			return requested;
		}
		String name = TaskStatistics.normalize(monster);
		String key = creatureId + "\u0000" + (name == null ? "" : name) + "\u0000" + requested.key();
		TaskSelection effective = effectiveSelectionCache.get(key);
		if (effective == null)
		{
			effective = TaskStatistics.effectiveSelection(records, creatureId, monster, requested);
			effectiveSelectionCache.put(key, effective);
		}
		return effective;
	}

	/**
	 * A task's statistics, of the records {@code selection} selects (version and cannon use; cannon tasks
	 * only just when the history has some, {@link #effectiveSelection}): from its history at {@code location}'s spot
	 * when it has some there (a record's spot is {@link SlayerSpots#recordSpot}), else from all of it (see
	 * {@link TaskStatistics#getLocation}). Cached until {@link #clearTaskStatistics}.
	 */
	TaskStatistics taskStatistics(int creatureId, String monster, TaskSelection selection,
		TaskLocation.Here location)
	{
		String key = taskStatisticsKey(creatureId, monster, selection, location);
		TaskStatistics stats = taskStatisticsCache.get(key);
		if (stats == null)
		{
			SlayerSpots spots = names.spots();
			stats = TaskStatistics.forTask(records, creatureId, monster,
				effectiveSelection(creatureId, monster, selection), location, spots::recordSpot);
			taskStatisticsCache.put(key, stats);
			taskStatisticsBuilds++;
		}
		return stats;
	}

	/**
	 * How many times a task's statistics were worked out. Performance seam: tests assert this doesn't grow on the
	 * refresh timer, or when only how the history is valued changes.
	 */
	int getTaskStatisticsBuildCount()
	{
		return taskStatisticsBuilds;
	}

	private static TaskSelection selectionOrAny(TaskSelection selection)
	{
		return selection == null ? TaskSelection.ANY : selection;
	}

	// ---- Advisor plan ----

	/**
	 * The advisor's plan to show for the current task ({@link TaskPlanner}): the plan for the current inputs, worked
	 * out in the background from the immutable snapshot: the task's creature key, name, type ({@link TaskType#of} its
	 * master) and assigned area (Konar's), its kills left, the records ({@link #recordsVersion}: not the "Skipped /
	 * blocked" entries), today's prices ({@link Valued}, at its valuation version), the spot table and the potion
	 * families ({@link #potionFamilies}). While that plan is worked out or the views wait for today's prices (it is
	 * worked out when the wait ends), the plan last kept for the same task (creature key, name, type and assigned
	 * area), so a kill doesn't blank it; only its kills left, records, prices, potion families or spot table may be
	 * older. {@code null} without a task (none observed, or no kills left) and while no such plan was kept. Only the
	 * plan of the inputs last asked for is kept (the stale-result rule), and when it is ready {@link #setOnReady}'s
	 * listener is told. Asked for again with the same inputs, nothing is worked out. The kept plan is always this
	 * account's ({@link #setHistory} drops it on another account).
	 */
	TaskPlan plan()
	{
		if (!tracker.isTaskObserved() || tracker.getCurrentRemaining() <= 0)
		{
			return null;
		}
		int creatureId = tracker.getCurrentCreatureId();
		String monster = tracker.getCurrentMonster();
		TaskContext context = tracker.getCurrentContext();
		TaskType type = TaskType.of(context.getMaster(), creatureId);
		String area = context.getLocation();
		// The task comes first in the key: a kept plan is shown only for the same.
		List<Object> task = Arrays.asList(creatureId, monster, type, area);
		if (!valuation.isWaitingForCurrentPrices())
		{
			int killsLeft = tracker.getCurrentRemaining();
			Valued now = valued();
			Map<Integer, String> families = potionFamilies();
			SlayerSpots spots = names.spots();
			List<LedgerRecord> from = records;
			List<Object> key = new ArrayList<>(task);
			key.addAll(Arrays.asList(recordsVersion, now.valuationVersion, killsLeft, families, spots));
			if (plan.request(key, () -> TaskPlanner.plan(TaskPlanner.Request.builder()
				.creatureId(creatureId)
				.task(monster)
				.taskType(type)
				.area(area)
				.killsLeft(killsLeft)
				.records(from)
				.prices(now.prices)
				.spots(spots)
				.potionFamilies(families)
				.build())))
			{
				return plan.value;
			}
		}
		List<Object> shown = plan.key;
		return shown != null && shown.subList(0, task.size()).equals(task) ? plan.value : null;
	}

	/**
	 * The records' potion families ({@link TaskPlanner#potionFamilies}) from the item names known, worked out again
	 * when the records change or names arrive; the names of the potions (the ids the records count in doses) are
	 * asked for. The map is unmodifiable and equal to the last one when no family changed, so the plan's inputs only
	 * change with a family.
	 */
	private Map<Integer, String> potionFamilies()
	{
		return potionFamilies.get(Arrays.asList(recordsVersion, names.itemNamesVersion()), () ->
		{
			Set<Integer> potions = new HashSet<>();
			for (LedgerRecord record : records)
			{
				if (record.getSupplyDoses() == null)
				{
					continue;
				}
				for (Integer id : record.getSupplyDoses().keySet())
				{
					if (id != null && ItemDetails.doseUnit(id) == ItemDetails.Unit.DOSES)
					{
						potions.add(id);
					}
				}
			}
			if (!potions.isEmpty())
			{
				names.requestItemNames(potions);
			}
			return Collections.unmodifiableMap(TaskPlanner.potionFamilies(records, names::itemName));
		});
	}

	/**
	 * How many times the plan was worked out (asked of the background).
	 * Performance seam: tests assert this doesn't grow on the refresh timer.
	 */
	int getPlanBuildCount()
	{
		return plan.builds;
	}

	// ---- Totals ----

	/**
	 * The completed-task totals in {@code grouping} ({@link OverallTotals}), once per records, entries and pricing,
	 * worked out in the background: {@code null} until it is ready. By master also counts the "Skipped / blocked"
	 * entries as assignments: the unmodifiable entries list is captured with the records (both are replaced,
	 * never changed, and {@link #version} covers both), and its entries are not changed once loaded.
	 */
	List<OverallTotals.Entry> overallTotals(OverallTotals.Grouping grouping)
	{
		ZoneId zone = ZoneId.systemDefault();
		Valued now = valued();
		List<LedgerRecord> from = records;
		List<AssignmentEntry> entries = assignments;
		return overallTotals.get(Arrays.asList(version, now.valuationVersion, grouping, zone),
			() -> Collections.unmodifiableList(OverallTotals.summarize(from, entries, grouping, now.mode, now.prices,
				now.hidden, zone)));
	}

	/**
	 * How many times the overall totals were worked out.
	 * Performance seam: tests assert this doesn't grow on the refresh timer.
	 */
	int getOverallTotalsBuildCount()
	{
		return overallTotals.builds;
	}

	// ---- Skipped / blocked ----

	/** The "Skipped / blocked" rows, newest first, worked out once per change of the entries. */
	List<AssignmentRow> assignmentRows()
	{
		ZoneId zone = ZoneId.systemDefault();
		return assignmentRows.get(Arrays.asList(version, zone), () ->
		{
			DateTimeFormatter dateTime = LedgerHistory.shortDateTime(zone);
			List<AssignmentRow> rows = new ArrayList<>();
			for (AssignmentEntry entry : assignments)
			{
				rows.add(new AssignmentRow(entry, AssignmentLog.monster(entry),
					AssignmentLog.tooltip(entry, dateTime)));
			}
			return Collections.unmodifiableList(rows);
		});
	}

	/**
	 * How many times the "Skipped / blocked" rows were worked out.
	 * Performance seam: tests assert this doesn't grow on the refresh timer.
	 */
	int getAssignmentRowsBuildCount()
	{
		return assignmentRows.builds;
	}

	/** How the records are valued, as one immutable snapshot for the background views. */
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Valued
	{
		private final long valuationVersion;
		private final LootPriceMode mode;
		/** An unmodifiable copy of today's prices the history is valued at; never {@code null}. */
		private final Map<Integer, Long> prices;
		/** Loot items left out of the loot value; immutable. */
		private final HiddenLoot hidden;
	}


	/**
	 * One derived view worked out in the background: its latest kept result and what it was worked out from, and the
	 * inputs being worked out now. Its fields are read and written on the EDT only; the background runs only the
	 * {@code compute} supplier, which reads nothing but what it captured.
	 */
	private final class Background<T>
	{
		/** What {@link #value} was worked out from; {@code null} before the first result. */
		private List<Object> key;
		private T value;
		/** The inputs being worked out now, or {@code null}; only a result for these is kept. */
		private List<Object> pendingKey;
		/** How many times it was asked of the background. */
		private int builds;
		/** True while {@link #request} queues the work, so a result delivered at once (tests) tells no one. */
		private boolean requesting;

		/** The result for {@code newKey}, or {@code null} while it is worked out in the background. */
		private T get(List<Object> newKey, Supplier<T> compute)
		{
			return request(newKey, compute) ? value : null;
		}

		/**
		 * Whether {@link #value} is the result for {@code newKey}; if not, has it worked out in the background (once
		 * per inputs: asked again while it is, nothing more is queued).
		 */
		private boolean request(List<Object> newKey, Supplier<T> compute)
		{
			if (newKey.equals(key))
			{
				// Back to the kept inputs: a result still on its way for others asked for since is dropped.
				pendingKey = null;
				return true;
			}
			if (closed || newKey.equals(pendingKey))
			{
				return false;
			}
			pendingKey = newKey;
			builds++;
			requesting = true;
			try
			{
				background.execute(() ->
				{
					// Background thread: only the captured snapshot is read. Should it throw, the executor reports it and
					// the view keeps what it shows until its inputs change.
					T result = compute.get();
					edt.execute(() -> deliver(newKey, result));
				});
			}
			catch (RejectedExecutionException e)
			{
				// The client is shutting down its executor: nothing is worked out any more.
				pendingKey = null;
			}
			finally
			{
				requesting = false;
			}
			return newKey.equals(key);
		}

		/** Drops the kept result and the inputs being worked out, so a result still on its way is dropped. */
		private void reset()
		{
			key = null;
			value = null;
			pendingKey = null;
		}

		/** EDT. Keeps a result only if it is for the latest inputs asked for; an older one is dropped. */
		private void deliver(List<Object> resultKey, T result)
		{
			if (closed || !resultKey.equals(pendingKey))
			{
				return;
			}
			pendingKey = null;
			key = resultKey;
			value = result;
			if (!requesting)
			{
				onReady.run();
			}
		}
	}

	/** One derived view's latest result and what it was worked out from. */
	private static final class Cached<T>
	{
		private List<Object> key;
		private T value;
		/** How many times it was worked out. */
		private int builds;

		private T get(List<Object> newKey, Supplier<T> compute)
		{
			if (!newKey.equals(key))
			{
				builds++;
				value = compute.get();
				key = newKey;
			}
			return value;
		}
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
