/**
 * The live task section of {@link SlayerLedgerPanel} (DESIGN_PRINCIPLES.md 3.4, V2 plan 8). First the live task
 * card, the one raised card of the live section: its header ({@link TaskBoxView}), then while a session is active the
 * setup tags as sprite toggles the player can set ({@link SetupToggles}), the progress bar
 * ({@code 73 / 201}, while the task's size is known, {@link LedgerProgressBar}) and the two-column stats grid, in the
 * overlay's order: Kills left and Time left, Pace and Kills/h, Elapsed and Superiors, Profit and XP (and Deaths and
 * Bank trips once either happened). Then, flat on the page: the
 * "Check your blowpipe" hint, the supplies and loot grids, each under a sub-header with its value, the XP per skill,
 * the session's boss kill counts, keys, clue scrolls and notable drops, and the session's note. Rows are added, shown
 * or rebuilt only when they change; a refresh with nothing new only sets the same texts again. EDT only.
 */
final class LiveSessionSection
{
	static final String DART_HINT_TEXT = "Check your blowpipe to count darts.";
	/** The supplies grid's sub-header. */
	static final String SUPPLIES_TITLE = "Supplies used";
	/** The loot grid's sub-header. */
	static final String LOOT_TITLE = "Loot";
	/** The time left before there are enough kills for an estimate and no history to fall back on: unknown. */
	static final String TIME_LEFT_UNKNOWN = LedgerFormat.UNKNOWN;
	/** Space between the parts of the card, and between the stats grid's two columns. */
	private static final int GAP = 6;
	/** Space between a stat's label and its value. */
	private static final int LABEL_GAP = 3;
	/**
	 * The widest forms of the clock and the time left under 10 hours (0 is the fonts' widest digit): their columns
	 * keep at least this width, so the columns don't shift as the values change ({@link StatsLayout}).
	 */
	private static final String CLOCK_PROTOTYPE = "0:00:00";
	private static final String TIME_LEFT_PROTOTYPE = "~0h 00m";

	/** Saves the active session's note: {@code (account, session id, note)}; {@code null} removes it. */
	@FunctionalInterface
	interface NoteSink
	{
		void save(long account, String sessionId, String note);
	}

	/** Saves the active session's setup overrides: {@code (account, session id, overrides)}. */
	@FunctionalInterface
	interface SetupSink
	{
		void save(long account, String sessionId, SetupOverrides overrides);
	}

	/**
	 * One cell of the stats grid: a label on the left, its value right-aligned, cut short with {@code …} when its
	 * column has no room for it ({@link FitLabel}); the tooltip always starts with the label and the whole value.
	 */
	private static final class Stat extends JPanel
	{
		/** The label's text, for the tooltip. */
		private final String title;
		private final JLabel label;
		private final FitLabel value = new FitLabel();
		/** The widest value the cell usually shows, which its column keeps room for ({@link StatsLayout}); or none. */
		private final String prototype;

		private Stat(String key, String text)
		{
			this(key, text, null);
		}

		private Stat(String key, String text, String prototype)
		{
			super(new BorderLayout(LABEL_GAP, 0));
			this.title = text;
			this.prototype = prototype;
			// Names for tests, which find the cells by them; no visible effect.
			setName("stats." + key);
			value.setName("stats." + key + ".value");
			setOpaque(false);
			label = LedgerTheme.label(text, LedgerTheme.smallFont(), LedgerTheme.LABEL);
			label.setVerticalAlignment(SwingConstants.BOTTOM);
			value.setFont(LedgerTheme.plainFont());
			value.setForeground(LedgerTheme.VALUE);
			value.setHorizontalAlignment(SwingConstants.RIGHT);
			value.setVerticalAlignment(SwingConstants.BOTTOM);
			add(label, BorderLayout.WEST);
			add(value, BorderLayout.CENTER);
		}

		/**
		 * Shows {@code text} in {@code color}, with the label and {@code text} in the whole cell's tooltip, then
		 * {@code more} (plain text or HTML), if any.
		 */
		private void show(String text, Color color, String more)
		{
			value.setText(text);
			value.setForeground(color);
			String tooltip = statTooltip(title, text, more);
			if (!tooltip.equals(getToolTipText()))
			{
				setToolTipText(tooltip);
				label.setToolTipText(tooltip);
				value.setToolTipText(tooltip);
			}
		}

		/**
		 * The width the cell needs for its label and its whole value, in their fonts; with {@code steady}, at least
		 * the width {@link #prototype} needs.
		 */
		private int need(boolean steady)
		{
			FontMetrics metrics = value.getFontMetrics(value.getFont());
			int valueWidth = metrics.stringWidth(value.getFullText());
			if (steady && prototype != null)
			{
				valueWidth = Math.max(valueWidth, metrics.stringWidth(prototype));
			}
			Insets insets = getInsets();
			return insets.left + label.getPreferredSize().width + LABEL_GAP + valueWidth + insets.right;
		}
	}

	/**
	 * The stats grid's layout: rows of two columns of unequal width, each as wide as its widest cell needs
	 * ({@link Stat#need}), so a long value such as {@code ~10h 05m} isn't cut short in one column while the other has
	 * room to spare (a grid of equal columns cut most times left of an hour or more); {@link #leftColumnWidth} splits
	 * the room. It asks for no width of its own, so it never widens the sidebar (DESIGN_PRINCIPLES.md 3.1). EDT only.
	 */
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class StatsLayout implements LayoutManager
	{
		private final int hgap;
		private final int vgap;

		@Override
		public void addLayoutComponent(String name, Component component)
		{
		}

		@Override
		public void removeLayoutComponent(Component component)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets insets = parent.getInsets();
			int rows = (parent.getComponentCount() + 1) / 2;
			return new Dimension(insets.left + insets.right,
				insets.top + insets.bottom + rows * rowHeight(parent) + Math.max(0, rows - 1) * vgap);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets insets = parent.getInsets();
			int available = parent.getWidth() - insets.left - insets.right - hgap;
			int[] steady = new int[2];
			int[] need = new int[2];
			for (int i = 0; i < parent.getComponentCount(); i++)
			{
				Stat stat = (Stat) parent.getComponent(i);
				steady[i % 2] = Math.max(steady[i % 2], stat.need(true));
				need[i % 2] = Math.max(need[i % 2], stat.need(false));
			}
			int left = leftColumnWidth(available, steady[0], steady[1], need[0], need[1]);
			int right = Math.max(0, available - left);
			int height = rowHeight(parent);
			for (int i = 0; i < parent.getComponentCount(); i++)
			{
				int y = insets.top + (i / 2) * (height + vgap);
				if (i % 2 == 0)
				{
					parent.getComponent(i).setBounds(insets.left, y, left, height);
				}
				else
				{
					parent.getComponent(i).setBounds(insets.left + left + hgap, y, right, height);
				}
			}
		}

		/** The tallest cell's height: every row has it. */
		private static int rowHeight(Container parent)
		{
			int height = 0;
			for (Component cell : parent.getComponents())
			{
				height = Math.max(height, cell.getPreferredSize().height);
			}
			return height;
		}
	}

	/**
	 * The stats grid's left column width, out of {@code available} for both columns. While the columns' steady needs
	 * (their values, and at least their prototypes) fit side by side, each column has its own and the room left over
	 * is shared, so the columns stay put as the values change. Else, while the values themselves fit, the left column
	 * keeps as much of its steady need as the right one leaves it. Only when they don't fit is each column cut to its
	 * share of the room; a value cut short has its whole text in the tooltip.
	 */
	static int leftColumnWidth(int available, int leftSteady, int rightSteady, int leftNeed, int rightNeed)
	{
		if (available <= 0)
		{
			return 0;
		}
		if (leftSteady + rightSteady <= available)
		{
			return leftSteady + (available - leftSteady - rightSteady) / 2;
		}
		if (leftNeed + rightNeed <= available)
		{
			return Math.max(leftNeed, Math.min(leftSteady, available - rightNeed));
		}
		return (int) ((long) available * leftNeed / Math.max(1, leftNeed + rightNeed));
	}

	/**
	 * A stat's tooltip: its label and whole value first ({@code Time left: ~1h 05m}), since the card may cut the value
	 * short (DESIGN_PRINCIPLES.md 3.1), then {@code more}, plain text or HTML, if any.
	 */
	static String statTooltip(String label, String value, String more)
	{
		String first = label + ": " + value;
		if (more == null)
		{
			return first;
		}
		String rest = more;
		if (rest.startsWith("<html>"))
		{
			rest = rest.substring("<html>".length());
			rest = rest.endsWith("</html>") ? rest.substring(0, rest.length() - "</html>".length()) : rest;
		}
		else
		{
			rest = LedgerHistory.escapeHtml(rest);
		}
		return "<html>" + LedgerHistory.escapeHtml(first) + "<br>" + rest + "</html>";
	}

	private final SessionTracker tracker;
	private final LedgerHistoryModel model;
	private final NoteSink saveNote;
	private final SetupSink saveSetup;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** The card's header: the task's icon, name, location, master and advice. */
	private final TaskBoxView header;

	/** The live task card: the header, then while a session is active the setup, the bar and the stats. */
	private final JPanel card = new JPanel();
	/**
	 * The task's progress, {@code 73 / 201}, its label as wide as the bar; shown while a session is active and the
	 * task's size is known.
	 */
	private final LedgerProgressBar bar = new LedgerProgressBar();
	/** {@link #bar} with the gap above it, shown and hidden as one. */
	private final JPanel barRow = new JPanel(new BorderLayout());
	/** The bar's label as last set, so it is set only when it changes. */
	private String barText;
	/** The stats grid: two columns, in the overlay's order. */
	private final JPanel stats = new JPanel(new StatsLayout(GAP, 2));
	private final Stat killsLeft = new Stat("killsLeft", "Kills left");
	private final Stat timeLeft = new Stat("timeLeft", "Time left", TIME_LEFT_PROTOTYPE);
	private final Stat pace = new Stat("pace", "Pace");
	private final Stat killsPerHour = new Stat("killsPerHour", "Kills/h");
	private final Stat elapsed = new Stat("elapsed", "Elapsed", CLOCK_PROTOTYPE);
	private final Stat superiors = new Stat("superiors", "Superiors");
	private final Stat profit = new Stat("profit", "Profit");
	private final Stat xp = new Stat("xp", "XP");
	/** Deaths and bank trips: a fifth row, in the grid only once either happened. */
	private final Stat deaths = new Stat("deaths", "Deaths");
	private final Stat bankTrips = new Stat("bankTrips", "Bank trips");
	/** The live session's supplies as item icons, under their sub-header; shown with the live values. */
	private final ItemGridView liveSupplies;
	/** The live session's loot as item icons, in the "Loot price" setting, with the alch hint. */
	private final ItemGridView liveLoot;
	/** The live session's XP, skill by skill with each skill's icon; shown while a session is active. */
	private final ItemListView liveXp;
	/**
	 * Boss kill counts ({@link BossKillCounts#lines}), keys, clue scrolls and notable drops
	 * ({@link LedgerHistory#liveTaskLootLines}) of the active session; shown only when there are any.
	 */
	private final JPanel taskLootSection = new JPanel();
	/** Lines {@link #taskLootSection} shows, so it is only rebuilt when they change. */
	private List<String> taskLootLines = Collections.emptyList();
	/** "Check your blowpipe" hint, shown while the dart type is unknown (see {@link #setDartHint}). */
	private final JLabel dartHintLabel = new JLabel(DART_HINT_TEXT);
	/** Whether the plugin asks for the dart hint; it is only shown while a session is running. */
	private boolean dartHintRequested;
	/** The session's note: an editable combo box whose list offers recent notes. */
	private final JComboBox<String> noteBox = new JComboBox<>();
	/** Row holding {@link #noteBox}; shown while a session is active. */
	private final JPanel noteSection;
	/** Recent notes in {@link #noteBox}'s list. */
	private List<String> recentNotes = Collections.emptyList();
	/** Session (and its account) the note box is editing, or {@code null} while no session is active. */
	private String noteSessionId;
	private long noteAccount = SessionTracker.NO_ACCOUNT;
	/** The note last sent to (or read from) the tracker for {@link #noteSessionId}. */
	private String committedNote;
	/** True while the note box is changed programmatically, so its events are not taken as the player's edits. */
	private boolean updatingNote;
	/**
	 * The live task's setup tags: Cannon, Style and Gear as sprite toggles, each opening a menu whose first
	 * choice shows the detected value and clears the player's override ({@link SetupChoices}), as the history's
	 * Setup... dialog; in the card, shown while a session is active.
	 */
	private final SetupToggles setup;
	/** Session (and its account) the setup toggles belong to, or {@code null} while no session is active. */
	private String setupSessionId;
	private long setupAccount = SessionTracker.NO_ACCOUNT;
	/**
	 * Live values last received, or {@code null} when none are known yet. Only shown while they belong to the
	 * tracker's current session. Set through {@link SlayerLedgerPanel#setSessionValues}; the next refresh shows them.
	 */
	@Setter
	private SessionValuation.Values sessionValues;

	/**
	 * @param header    the card's header, which the panel refreshes
	 * @param saveSetup saves the live task's setup overrides
	 * @param icons     draws the item grids' icons, the XP list's skill icons and the setup tags' images
	 */
	LiveSessionSection(SessionTracker tracker, LedgerHistoryModel model, TaskBoxView header, NoteSink saveNote,
		SetupSink saveSetup, Runnable relayout, SidebarIcons icons)
	{
		this.tracker = tracker;
		this.model = model;
		this.header = header;
		this.saveNote = saveNote;
		this.saveSetup = saveSetup;
		this.relayout = relayout;
		liveSupplies = new ItemGridView(SUPPLIES_TITLE, false, LedgerTheme.PAGE, icons.getItems());
		liveLoot = new ItemGridView(LOOT_TITLE, false, LedgerTheme.PAGE, icons.getItems());
		liveXp = new ItemListView(SkillXp.LIST_TITLE, false, LedgerTheme.PAGE, SkillXp.LIST_NOUN, icons.getSkills());
		for (TitledListView<?> list : new TitledListView<?>[]{liveSupplies, liveLoot, liveXp})
		{
			list.useSubHeader();
		}
		noteSection = buildNoteSection();
		// The toggles name their own parts (setup, setup.cannon, ...).
		setup = new SetupToggles(icons.getSetup());
		setup.setOnChoose(this::savePickedSetup);
		// Names for tests, which find the parts by them; no visible effect.
		card.setName("liveCard");
		barRow.setName("progress");
		bar.setName("progress.bar");
		stats.setName("stats");
		noteSection.setName("note");
		noteBox.setName("note.box");
		liveSupplies.setName("liveSupplies");
		liveLoot.setName("liveLoot");
		liveXp.setName("liveXp");
		taskLootSection.setName("taskLoot");
		dartHintLabel.setName("dartHint");
	}

	/** Adds the live task card, then the hint, the grids, the XP, the task loot and the note to {@code content}. */
	void addTo(JPanel content)
	{
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		LedgerTheme.styleCard(card);
		card.add(header.getComponent());

		// Each optional part carries the gap above it, so a hidden part leaves none.
		JComponent setupRow = setup.getComponent();
		setupRow.setBorder(BorderFactory.createEmptyBorder(GAP, 0, 0, 0));
		setupRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		setupRow.setVisible(false);
		card.add(setupRow);

		barRow.setOpaque(false);
		barRow.setBorder(BorderFactory.createEmptyBorder(GAP, 0, 0, 0));
		barRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		barRow.add(bar, BorderLayout.CENTER);
		barRow.setVisible(false);
		card.add(barRow);

		stats.setOpaque(false);
		stats.setBorder(BorderFactory.createEmptyBorder(GAP, 0, 0, 0));
		stats.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (Stat stat : new Stat[]{killsLeft, timeLeft, pace, killsPerHour, elapsed, superiors, profit, xp})
		{
			stats.add(stat);
		}
		killsLeft.value.setFont(LedgerTheme.boldFont());
		killsLeft.value.setForeground(LedgerTheme.KEY);
		stats.setVisible(false);
		card.add(stats);
		SlayerLedgerPanel.addRow(content, card);

		dartHintLabel.setForeground(LedgerTheme.ALERT);
		dartHintLabel.setFont(LedgerTheme.smallFont());
		dartHintLabel.setToolTipText("<html>Blowpipe darts are counted once the plugin knows the dart type.<br>"
			+ "Use Check on the blowpipe; until then only Zulrah's scales are counted.</html>");
		dartHintLabel.setVisible(false);
		// Each of these is hidden at times; each carries its own gap, so a hidden one leaves none.
		SlayerLedgerPanel.addHideableRow(content, dartHintLabel);
		for (TitledListView<?> list : new TitledListView<?>[]{liveSupplies, liveLoot, liveXp})
		{
			list.setVisible(false);
			SlayerLedgerPanel.addHideableRow(content, list);
		}
		taskLootSection.setOpaque(false);
		taskLootSection.setVisible(false);
		SlayerLedgerPanel.addHideableRow(content, taskLootSection);
		SlayerLedgerPanel.addHideableRow(content, noteSection);
	}

	/** Asks for (or withdraws) the "Check your blowpipe" hint; the next refresh shows or hides it. */
	void setDartHint(boolean requested)
	{
		dartHintRequested = requested;
	}

	/** Updates the card from the tracker for {@code state}, with {@code remaining} kills left on the task. */
	void refresh(SessionTracker.State state, int remaining)
	{
		final long activeMillis = tracker.getActiveMillis();
		final int kills = tracker.getKills();
		refreshBar(state, remaining);
		refreshStats(state, activeMillis, kills, remaining);
		refreshNote(state);
		refreshSetup(state);
	}

	/** Updates the values, the grids, the task loot and the dart hint for {@code state}. */
	void refreshValuesAndLoot(SessionTracker.State state)
	{
		refreshValues(state);
		refreshTaskLoot(state);
		boolean hint = dartHintRequested && state == SessionTracker.State.RUNNING;
		if (dartHintLabel.isVisible() != hint)
		{
			dartHintLabel.setVisible(hint);
			relayout.run();
		}
	}

	/** Redraws the task loot in the new "Loot price" mode; the values follow it through the plugin's values. */
	void lootPriceModeChanged()
	{
		refreshTaskLoot(tracker.getState());
	}

	/** Redraws the item lists once item names arrive. */
	void itemNamesChanged()
	{
		refreshItemLists(shownValues(sessionValues, tracker.getState(), tracker.getSessionId()));
	}

	// ---- Session note ----

	private JPanel buildNoteSection()
	{
		JPanel section = new JPanel(new BorderLayout(6, 0));
		section.setOpaque(false);
		section.add(LedgerTheme.label("Note", LedgerTheme.smallFont(), LedgerTheme.LABEL), BorderLayout.WEST);

		noteBox.setEditable(true);
		noteBox.setFont(LedgerTheme.smallFont());
		// Sized from a short label, not the longest note, so a long note never widens the sidebar.
		noteBox.setPrototypeDisplayValue("Strength gear");
		noteBox.setToolTipText("<html>How you're doing this task, e.g. Barrage. Saved with the task.<br>"
			+ "Type a note and press Enter, or pick a recent one.</html>");
		noteBox.addActionListener(e ->
		{
			Object picked = noteBox.getSelectedItem();
			if (!updatingNote && "comboBoxChanged".equals(e.getActionCommand()) && picked != null)
			{
				// A pick from the list: make sure the editor shows it before it is read.
				setNoteEditorText(picked.toString());
			}
			commitNote();
		});
		noteBox.getEditor().getEditorComponent().addFocusListener(new FocusAdapter()
		{
			@Override
			public void focusLost(FocusEvent e)
			{
				commitNote();
			}
		});
		setRecentNotes(TaskNote.DEFAULTS);
		section.add(noteBox, BorderLayout.CENTER);
		section.setVisible(false);
		return section;
	}

	/** Text in the note box's editor (what the player has typed so far). */
	private String noteEditorText()
	{
		Object item = noteBox.getEditor().getItem();
		return item == null ? "" : item.toString();
	}

	/** Puts {@code text} in the note box without it counting as the player's edit. */
	private void setNoteEditorText(String text)
	{
		String shown = text == null ? "" : text;
		updatingNote = true;
		try
		{
			noteBox.setSelectedItem(shown);
			noteBox.getEditor().setItem(shown);
		}
		finally
		{
			updatingNote = false;
		}
	}

	/**
	 * Sends the typed note to the session the note box belongs to (Enter, a pick from the list, leaving the box, or
	 * End task), and shows it as it was saved (trimmed and shortened).
	 */
	void commitNote()
	{
		if (updatingNote || noteSessionId == null)
		{
			return;
		}
		String note = TaskNote.normalize(noteEditorText());
		if (!Objects.equals(note, committedNote))
		{
			committedNote = note;
			saveNote.save(noteAccount, noteSessionId, note);
		}
		if (!noteEditorText().equals(note == null ? "" : note))
		{
			setNoteEditorText(note);
		}
	}

	/** Replaces the note box's list, keeping what is in its editor. */
	void setRecentNotes(List<String> notes)
	{
		if (notes.equals(recentNotes))
		{
			return;
		}
		recentNotes = notes;
		String text = noteEditorText();
		updatingNote = true;
		try
		{
			noteBox.setModel(new DefaultComboBoxModel<>(notes.toArray(new String[0])));
		}
		finally
		{
			updatingNote = false;
		}
		setNoteEditorText(text);
	}

	/**
	 * Shows the note box while a session is active, filled with that session's note. While the player is
	 * typing (the box has focus) or picking (its list is open) the text is left alone; when the session ends, text
	 * still being typed is sent first, to the session it was typed for.
	 */
	private void refreshNote(SessionTracker.State state)
	{
		boolean active = state.isActive();
		String sessionId = active ? tracker.getSessionId() : null;
		if (noteSessionId != null && !noteSessionId.equals(sessionId))
		{
			commitNote();
			noteSessionId = null;
			noteAccount = SessionTracker.NO_ACCOUNT;
			committedNote = null;
			setNoteEditorText(null);
		}
		if (sessionId != null)
		{
			String note = tracker.getNote();
			if (noteSessionId == null)
			{
				noteSessionId = sessionId;
				noteAccount = tracker.getSessionAccountHash();
				committedNote = note;
				setNoteEditorText(note);
			}
			else if (!isNoteBeingEdited() && !Objects.equals(note, committedNote))
			{
				committedNote = note;
				setNoteEditorText(note);
			}
		}
		if (noteSection.isVisible() != active)
		{
			noteSection.setVisible(active);
			relayout.run();
		}
	}

	/** Whether the player is typing in, or picking from, the note box. */
	private boolean isNoteBeingEdited()
	{
		return noteBox.getEditor().getEditorComponent().isFocusOwner() || noteBox.isPopupVisible();
	}

	// ---- Setup tags ----

	/**
	 * Sends the overrides the player picked on a toggle to the session the toggles belong to: the active one, or one
	 * that ended since the last refresh (the plugin then writes them to the completion held for late loot, or to the
	 * saved record, {@link SlayerLedgerPlugin#setSessionSetup}).
	 */
	private void savePickedSetup(SetupOverrides overrides)
	{
		if (setupSessionId != null)
		{
			saveSetup.save(setupAccount, setupSessionId, overrides);
		}
	}

	/**
	 * Shows the setup toggles while a session is active, with its detected tags and the player's overrides; redrawn
	 * only when they change, and not while the player has a toggle's menu open.
	 */
	private void refreshSetup(SessionTracker.State state)
	{
		boolean active = state.isActive();
		String sessionId = active ? tracker.getSessionId() : null;
		if (!Objects.equals(sessionId, setupSessionId))
		{
			setupSessionId = sessionId;
			setupAccount = active ? tracker.getSessionAccountHash() : SessionTracker.NO_ACCOUNT;
			setup.clear();
		}
		if (sessionId != null)
		{
			// Over the kills that may have a context, as the tags are (not a restored 1.x task's earlier kills).
			setup.show(tracker.getSetupTags(), tracker.getSetupKills(), tracker.getContextKills());
		}
		JComponent row = setup.getComponent();
		if (row.isVisible() != active)
		{
			row.setVisible(active);
			relayout.run();
		}
	}

	/**
	 * How many times the setup toggles were redrawn. Performance seam: tests assert this doesn't grow on the refresh
	 * timer.
	 */
	int getSetupBuildCount()
	{
		return setup.getBuildCount();
	}

	/**
	 * How many times the live grids and XP list were drawn. Performance seam: tests assert this doesn't grow on the
	 * refresh timer.
	 */
	int getListsBuildCount()
	{
		return liveSupplies.getBuildCount() + liveLoot.getBuildCount() + liveXp.getBuildCount();
	}

	// ---- Bar and stats ----

	/**
	 * Shows the task's progress while a session is active and the task's size is known: the kills done of the
	 * assignment, {@code 73 / 201} (DESIGN_PRINCIPLES.md 2.4: no bar for an unknown size). It keeps its fill while
	 * paused; the status strip says so.
	 */
	private void refreshBar(SessionTracker.State state, int remaining)
	{
		int total = tracker.getCurrentOriginalAmount();
		boolean show = state.isActive() && remaining > 0 && total > 0 && remaining <= total;
		if (show)
		{
			int done = total - remaining;
			String text = LedgerFormat.progress(done, total);
			if (!text.equals(barText))
			{
				barText = text;
				bar.setMaximumValue(total);
				bar.setValue(done);
				bar.setCenterLabel(text);
				bar.setToolTipText(LedgerFormat.kills(done) + " of " + LedgerFormat.kills(total) + " kills done");
			}
		}
		if (barRow.isVisible() != show)
		{
			barRow.setVisible(show);
			relayout.run();
		}
	}

	/**
	 * Shows the stats grid while a session is active (running, away, paused or logged out); hides it otherwise. The
	 * time left stands still while paused, as active time does.
	 */
	private void refreshStats(SessionTracker.State state, long activeMillis, int kills, int remaining)
	{
		boolean active = state.isActive();
		if (active)
		{
			killsLeft.show(remaining > 0 ? LedgerFormat.kills(remaining) : LedgerFormat.UNKNOWN, LedgerTheme.KEY, null);
			refreshTimeLeft(activeMillis, kills, remaining);
			OptionalLong perKill = TaskTimeEstimate.averageKillMillis(activeMillis, kills);
			OptionalDouble perHour = TaskTimeEstimate.killsPerHour(activeMillis, kills);
			String paceTip = String.format("Shown after %d kills and %d minute of active time.",
				TaskTimeEstimate.MIN_KILLS, TaskTimeEstimate.MIN_ACTIVE_MILLIS / 60_000);
			// Not known yet: ? (DESIGN_PRINCIPLES.md 5.5), as the time left.
			pace.show(perKill.isPresent() ? LedgerFormat.pace(perKill.getAsLong()) : LedgerFormat.UNKNOWN,
				LedgerTheme.VALUE, perKill.isPresent() ? "Average active time per kill" : paceTip);
			killsPerHour.show(perHour.isPresent() ? LedgerFormat.perHour(perHour.getAsDouble()) : LedgerFormat.UNKNOWN,
				LedgerTheme.VALUE, perHour.isPresent() ? "Kills per hour of active time" : paceTip);
			elapsed.show(LedgerFormat.clock(activeMillis), LedgerTheme.VALUE,
				"Active time: time not Away, Paused or logged out");
			superiors.show(LedgerFormat.kills(tracker.getSuperiorsSpawned()), LedgerTheme.VALUE, null);
			Map<String, Long> gained = tracker.getXpGained();
			xp.show(LedgerFormat.amount(SkillXp.total(gained)), LedgerTheme.VALUE,
				SkillXp.tooltip(gained, activeMillis));
			int deathCount = tracker.getDeaths();
			int tripCount = tracker.getBankTrips();
			deaths.show(LedgerFormat.kills(deathCount), LedgerTheme.VALUE, null);
			bankTrips.show(LedgerFormat.kills(tripCount), LedgerTheme.VALUE, null);
			showCountsRow(deathCount > 0 || tripCount > 0);
			// Without rates, so the rows (and an open tooltip) don't change every second; the header has the rate.
			liveXp.setRows(SkillXp.rows(gained, 0));
			Long xpRate = SkillXp.perHour(SkillXp.total(gained), activeMillis);
			liveXp.setHeaderValue(xpRate == null ? "" : LedgerFormat.amount(xpRate) + "/h", LedgerTheme.VALUE,
				xpRate == null ? null : "XP per hour of active time");
		}
		if (stats.isVisible() != active)
		{
			stats.setVisible(active);
			relayout.run();
		}
		if (liveXp.isVisible() != active)
		{
			liveXp.setVisible(active);
			relayout.run();
		}
	}

	/** Adds Deaths and Bank trips as the grid's fifth row, or takes them out. */
	private void showCountsRow(boolean show)
	{
		boolean shown = deaths.getParent() == stats;
		if (shown == show)
		{
			return;
		}
		if (show)
		{
			stats.add(deaths);
			stats.add(bankTrips);
		}
		else
		{
			stats.remove(deaths);
			stats.remove(bankTrips);
		}
		relayout.run();
	}

	/**
	 * The time left (the overlay's formatter, so the two never disagree): at the session's pace, else the history's
	 * time per kill, else {@link #TIME_LEFT_UNKNOWN}; the tooltip says which.
	 */
	private void refreshTimeLeft(long activeMillis, int kills, int remaining)
	{
		// The same statistics as the overlay's time per kill (LedgerHistoryModel#historicalPace), which the model
		// publishes itself when they or the session change.
		TaskStatistics taskStats = model.taskStatistics(tracker.getCurrentCreatureId(), tracker.getCurrentMonster(),
			tracker.getCurrentTaskSelection(), model.currentLocation());
		Long historicalPerKill = taskStats.getSampleCount() == 0 ? null : taskStats.getMillisPerKill();
		String tooltip;
		if (!LedgerHistory.isHistoricalTimeLeft(activeMillis, kills, remaining, historicalPerKill))
		{
			tooltip = timeLeftTooltip(activeMillis, kills);
		}
		else
		{
			tooltip = String.format("<html>Historical estimate from %d completed %s%s; assumes "
				+ "the same average time per kill.<br>The live pace takes over after %d kills and %d minute of "
				+ "active time.</html>", taskStats.getSampleCount(), taskStats.getSampleCount() == 1 ? "task" : "tasks",
				taskStats.getLocation() == null ? "" : " at " + LedgerHistory.escapeHtml(taskStats.getLocation()),
				TaskTimeEstimate.MIN_KILLS, TaskTimeEstimate.MIN_ACTIVE_MILLIS / 60_000);
		}
		timeLeft.show(timeLeftText(activeMillis, kills, remaining, historicalPerKill), LedgerTheme.VALUE, tooltip);
	}

	/**
	 * The time-left value: whole minutes ({@link LedgerHistory#formatTimeLeft(long, int, int, Long)}: {@code ~9h 59m},
	 * short for the card's columns; the overlay writes the same estimate {@code ~9 h 59 min},
	 * {@link LedgerFormat#timeLeft}) at the session's pace, or the history's until the live pace takes over;
	 * {@link #TIME_LEFT_UNKNOWN} until either gives an estimate, which the card has no room to spell out (its tooltip
	 * does); {@code -} when no kills are left.
	 */
	static String timeLeftText(long activeMillis, int kills, int remaining, Long historicalMillisPerKill)
	{
		String text = LedgerHistory.formatTimeLeft(activeMillis, kills, remaining, historicalMillisPerKill);
		return LedgerHistory.TIME_LEFT_ESTIMATING.equals(text) ? TIME_LEFT_UNKNOWN : text;
	}

	/** Tooltip of the time left: the pace behind the estimate, or when an estimate will appear. */
	static String timeLeftTooltip(long activeMillis, int kills)
	{
		OptionalDouble perHour = TaskTimeEstimate.killsPerHour(activeMillis, kills);
		OptionalLong perKill = TaskTimeEstimate.averageKillMillis(activeMillis, kills);
		if (!perHour.isPresent() || !perKill.isPresent())
		{
			return String.format("Estimated after %d kills and %d minute of active time.", TaskTimeEstimate.MIN_KILLS,
				TaskTimeEstimate.MIN_ACTIVE_MILLIS / 60_000);
		}
		return String.format("<html>Kills per hour: %d<br>Average kill: %s<br>Assumes the same pace as so far.</html>",
			Math.round(perHour.getAsDouble()), LedgerHistory.formatKillTime(perKill.getAsLong()));
	}

	// ---- Values, item lists and task loot ----

	/** Live session values to show: those of the tracker's current session while it is active. */
	static SessionValuation.Values shownValues(SessionValuation.Values values, SessionTracker.State state,
		String currentSessionId)
	{
		boolean active = state.isActive();
		if (!active || values == null || !Objects.equals(values.getSessionId(), currentSessionId))
		{
			return null;
		}
		return values;
	}

	/**
	 * Shows the live session's profit in the stats and the supplies' and loot's values over their grids while a session
	 * is active and its values are known; clears them otherwise.
	 */
	private void refreshValues(SessionTracker.State state)
	{
		boolean active = state.isActive();
		if (!active)
		{
			sessionValues = null;
		}
		SessionValuation.Values values = shownValues(sessionValues, state, tracker.getSessionId());
		if (values != null)
		{
			String tooltip = LedgerHistory.valuesTooltip(values);
			long amount = values.getProfit();
			profit.show(liveProfitText(values), amount > 0 ? LedgerTheme.GOOD : amount < 0 ? LedgerTheme.ALERT
				: LedgerTheme.VALUE, tooltip);
			liveSupplies.setHeaderValue(LedgerFormat.amount(values.getSuppliesGe(), values.getSuppliesUnpriced() > 0),
				LedgerTheme.VALUE, tooltip);
			liveLoot.setHeaderValue(liveLootText(values), LedgerTheme.VALUE, tooltip);
		}
		else if (active)
		{
			profit.show(LedgerFormat.UNKNOWN, LedgerTheme.VALUE, "Shown once the session's items are valued.");
		}
		refreshItemLists(values);
	}

	/**
	 * Shows the live session's supplies and loot as item icons, with their values (from the same values, so at the same
	 * prices and "Loot price" setting), and asks for the names not known yet. The icons are only rebuilt when the rows
	 * change.
	 */
	private void refreshItemLists(SessionValuation.Values values)
	{
		boolean show = values != null;
		if (show)
		{
			ItemDetails items = values.getItems();
			// One cell per potion, though the session may count one under two dose variants.
			liveSupplies.setRows(items.supplyGridRows(model::itemName));
			// Without the items Ground Items hides, as the loot value leaves them out.
			liveLoot.setRows(items.withNatureRunePrice(model.natureRunePrice())
				.lootRows(values.getLootPriceMode(), model::itemName), values.getHiddenLoot());
			// Asks the plugin, through the model, for the names not known, asked for or failed yet.
			model.requestItemNames(items.itemIds());
		}
		if (liveSupplies.isVisible() != show)
		{
			liveSupplies.setVisible(show);
			liveLoot.setVisible(show);
			relayout.run();
		}
	}

	/**
	 * Shows the session's boss kill counts, keys, clue scrolls and notable drops while a session is active
	 * and there are any; hides them otherwise. The notable drops' values follow the "Loot price" setting; the tooltip
	 * lists the boss kill counts and every drop.
	 */
	private void refreshTaskLoot(SessionTracker.State state)
	{
		boolean active = state.isActive();
		List<NotableDrop> drops = active ? tracker.getNotableDrops() : Collections.emptyList();
		List<BossKillCount> killCounts = active ? tracker.getBossKillCounts() : Collections.emptyList();
		String taskName = active ? tracker.getSessionMonster() : null;
		LootPriceMode mode = model.lootPriceMode();
		List<String> lines = new ArrayList<>(BossKillCounts.lines(killCounts, taskName));
		if (active)
		{
			lines.addAll(LedgerHistory.liveTaskLootLines(KeysAndClues.of(tracker.getLoot()), drops, mode));
		}
		if (!lines.equals(taskLootLines))
		{
			taskLootLines = lines;
			taskLootSection.removeAll();
			taskLootSection.setLayout(new GridLayout(Math.max(1, lines.size()), 1, 0, 2));
			for (String line : lines)
			{
				FitLabel label = new FitLabel(line);
				label.setForeground(LedgerTheme.LABEL);
				label.setFont(LedgerTheme.smallFont());
				taskLootSection.add(label);
			}
			relayout.run();
		}
		String tooltip = LedgerHistory.bossKillCountTooltip(killCounts, taskName)
			+ LedgerHistory.notableDropsTooltip(drops, mode);
		// The tooltip lists the kill counts and every notable drop with its exact value; the sidebar may cut a long
		// name short.
		taskLootSection.setToolTipText(tooltip.isEmpty() ? null : "<html>" + tooltip.substring("<br>".length())
			+ "</html>");
		boolean show = !lines.isEmpty();
		if (taskLootSection.isVisible() != show)
		{
			taskLootSection.setVisible(show);
			relayout.run();
		}
	}

	/** The loot's value over its grid: in its price mode ({@code 344K}), approximate when a price is missing. */
	static String liveLootText(SessionValuation.Values values)
	{
		return LedgerFormat.amount(values.getLootValue(), values.getLootValueUnpriced() > 0);
	}

	/**
	 * The live profit: loot in its price mode minus supplies, always signed ({@code +212K}, {@code -38K}), approximate
	 * when either has an unavailable price.
	 */
	static String liveProfitText(SessionValuation.Values values)
	{
		int unpriced = values.getLootValueUnpriced() + values.getSuppliesUnpriced();
		return LedgerFormat.signed(values.getProfit(), unpriced > 0);
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * Kills a session counted at one place: a map region and the Slayer spot of the tiles they were counted on.
 * Serialized with Gson in {@link SessionSnapshot}; effectively immutable (no setters). Pure (no RuneLite types). The
 * rules are in {@link LocationTally}.
 */
@Getter
@EqualsAndHashCode
@ToString
@AllArgsConstructor(access = AccessLevel.PACKAGE)
final class LocationKills
{
	/** Map region id of the local player's tile when the kills were counted (instances as their template region). */
	private int region;
	/**
	 * The Slayer spot key of those tiles ({@link KillPlace#getSpot}), or {@code null} when it is decided from
	 * {@link #region} alone: a tile no spot of a shared region matched, or a tally kept before spots.
	 */
	private String spot;
	/** Kills counted at this place; at least 1. */
	private int kills;

	/** For Gson. */
	private LocationKills()
	{
	}

	/** Kills in {@code region}, whose spot is decided from the region alone. */
	LocationKills(int region, int kills)
	{
		this(region, null, kills);
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Rules for a session's kills per place: each counted kill is added to the place (map region and Slayer
 * spot, {@link KillPlace}) the local player stood on when the task count went down. The tally is kept in the order the
 * places were last killed at, the most recent last. The task's spot is the spot with the most kills ({@link #decide}).
 * Pure (no RuneLite types); the lists passed in are never changed.
 */
final class LocationTally
{
	/** Value used for "no region known" (no local player or scene yet). Valid region ids are never negative. */
	static final int NO_REGION = -1;
	/** Most places tallied per session; kills at further places are still counted, only not tallied. */
	static final int MAX_REGIONS = 64;

	private LocationTally()
	{
	}

	/** Whether {@code region} is a region id (not {@link #NO_REGION} or another negative value). */
	static boolean isRegion(int region)
	{
		return region >= 0;
	}

	/** {@link #add(List, KillPlace, int)} for a place known only by its region. */
	static List<LocationKills> add(List<LocationKills> tally, int region, int kills)
	{
		return add(tally, KillPlace.ofRegion(region), kills);
	}

	/**
	 * A copy of {@code tally} with {@code kills} more kills at {@code place} (saturating), moved to the end: the place
	 * killed at most recently is last. Nothing is added for an unknown place, no kills, or a new place once
	 * {@link #MAX_REGIONS} are tallied.
	 *
	 * @param tally the tally so far, or {@code null} for none
	 */
	static List<LocationKills> add(List<LocationKills> tally, KillPlace place, int kills)
	{
		final List<LocationKills> result = sanitize(tally);
		if (place == null || !place.isKnown() || kills <= 0)
		{
			return result;
		}
		for (int i = 0; i < result.size(); i++)
		{
			final LocationKills entry = result.get(i);
			if (samePlace(entry, place.getRegion(), place.getSpot()))
			{
				result.remove(i);
				result.add(new LocationKills(entry.getRegion(), entry.getSpot(), saturatedAdd(entry.getKills(), kills)));
				return result;
			}
		}
		if (result.size() < MAX_REGIONS)
		{
			result.add(new LocationKills(place.getRegion(), place.getSpot(), kills));
		}
		return result;
	}

	/**
	 * A clean copy of a tally (for example one read from a file): entries without a region or kills are dropped, a
	 * repeated place is merged into its first entry, and at most {@link #MAX_REGIONS} places are kept. A blank spot
	 * reads as none. Never {@code null}.
	 */
	static List<LocationKills> sanitize(List<LocationKills> tally)
	{
		final List<LocationKills> result = new ArrayList<>();
		if (tally == null)
		{
			return result;
		}
		for (LocationKills entry : tally)
		{
			if (entry == null || !isRegion(entry.getRegion()) || entry.getKills() <= 0)
			{
				continue;
			}
			final String spot = entry.getSpot() == null || entry.getSpot().trim().isEmpty() ? null
				: entry.getSpot().trim();
			boolean merged = false;
			for (int i = 0; i < result.size(); i++)
			{
				if (samePlace(result.get(i), entry.getRegion(), spot))
				{
					result.set(i, new LocationKills(entry.getRegion(), spot,
						saturatedAdd(result.get(i).getKills(), entry.getKills())));
					merged = true;
					break;
				}
			}
			if (!merged && result.size() < MAX_REGIONS)
			{
				result.add(new LocationKills(entry.getRegion(), spot, entry.getKills()));
			}
		}
		return result;
	}

	/**
	 * The task's spot from its tally (V2 plan 4.5): each entry's spot is its own, or for one without, the spot of its
	 * region for {@code task} ({@link SlayerSpots#spotForRegion}); entries with no spot that way count for none. The
	 * spot with the most kills wins; on a tie, the spot whose task list includes {@code task}, then the spot killed at
	 * most recently. The region saved with it is the spot's region with the most kills (on a tie, the most recent);
	 * with no spot, the region with the most kills of all.
	 *
	 * @param tally the tally, in the order {@link #add} keeps (most recent last), or {@code null}
	 * @param spots the spot table ({@link SlayerSpots#NONE} when unavailable)
	 * @param task  the session's task name, or {@code null}
	 * @return the spot and region, {@link TaskSpot#UNKNOWN} when nothing is tallied
	 */
	static TaskSpot decide(List<LocationKills> tally, SlayerSpots spots, String task)
	{
		final List<LocationKills> entries = sanitize(tally);
		if (entries.isEmpty())
		{
			return TaskSpot.UNKNOWN;
		}
		final SlayerSpots table = spots == null ? SlayerSpots.NONE : spots;
		final Map<String, Group> groups = new LinkedHashMap<>();
		final Group all = new Group(null);
		for (int i = 0; i < entries.size(); i++)
		{
			final LocationKills entry = entries.get(i);
			all.add(entry, i);
			final String key = entry.getSpot() != null ? entry.getSpot()
				: table.spotForRegion(entry.getRegion(), task);
			if (key != null)
			{
				groups.computeIfAbsent(key, Group::new).add(entry, i);
			}
		}
		Group best = null;
		boolean bestListsTask = false;
		for (Group group : groups.values())
		{
			final boolean listsTask = table.listsTask(group.key, task);
			if (best == null || group.kills > best.kills
				|| (group.kills == best.kills && listsTask && !bestListsTask)
				|| (group.kills == best.kills && listsTask == bestListsTask && group.last > best.last))
			{
				best = group;
				bestListsTask = listsTask;
			}
		}
		return best == null ? new TaskSpot(null, all.topRegion()) : new TaskSpot(best.key, best.topRegion());
	}

	private static boolean samePlace(LocationKills entry, int region, String spot)
	{
		return entry.getRegion() == region && Objects.equals(entry.getSpot(), spot);
	}

	private static int saturatedAdd(int a, int b)
	{
		final long sum = (long) a + b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}

	/** One spot's entries while deciding: its kills, its latest entry and its kills per region. */
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Group
	{
		private final String key;
		private int kills;
		/** Index of its most recent entry. */
		private int last = -1;
		/** Kills per region, and each region's most recent entry index. */
		private final Map<Integer, int[]> regions = new LinkedHashMap<>();

		private void add(LocationKills entry, int index)
		{
			kills = saturatedAdd(kills, entry.getKills());
			last = Math.max(last, index);
			final int[] region = regions.computeIfAbsent(entry.getRegion(), r -> new int[]{0, -1});
			region[0] = saturatedAdd(region[0], entry.getKills());
			region[1] = Math.max(region[1], index);
		}

		/** The region with the most kills, the most recent among equals. */
		private Integer topRegion()
		{
			Integer best = null;
			int bestKills = -1;
			int bestLast = -1;
			for (Map.Entry<Integer, int[]> region : regions.entrySet())
			{
				final int[] counts = region.getValue();
				if (counts[0] > bestKills || (counts[0] == bestKills && counts[1] > bestLast))
				{
					best = region.getKey();
					bestKills = counts[0];
					bestLast = counts[1];
				}
			}
			return best;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;

/**
 * Decides which items of one kill-loot drop are counted, when the loot is captured: the items a bonecrusher or ash
 * sanctifier destroyed ({@link CrushedLootFilter}) and the player's ignored items ({@link IgnoredLoot}) are left out.
 * Saved records and loot already counted are never changed. Pure: item facts come from an {@link ItemNames} the plugin
 * backs with item compositions on the client thread.
 */
final class LootFilter
{
	/** Item facts for the ignored-items check. Implementations may only be valid on the client thread. */
	interface ItemNames
	{
		/** The unnoted item's id for a noted item, otherwise {@code itemId}. */
		int unnoted(int itemId);

		/** The item's name, or {@code null} when unknown. */
		String name(int itemId);
	}

	private final CrushedLootFilter crushed;
	private final IgnoredLoot ignored;

	LootFilter(CrushedLootFilter crushed, IgnoredLoot ignored)
	{
		this.crushed = Objects.requireNonNull(crushed);
		this.ignored = Objects.requireNonNull(ignored);
	}

	/**
	 * The loot that counts. Item facts are only looked up when items are ignored, at most once per distinct id; a
	 * failed lookup leaves that item to be matched by its id alone.
	 *
	 * @param loot  the drop, by item id as received
	 * @param names item facts; not used when nothing is ignored
	 */
	ItemTally apply(ItemTally loot, ItemNames names)
	{
		final ItemTally kept = new ItemTally();
		if (loot == null)
		{
			return kept;
		}
		final Map<Integer, Boolean> ignoredIds = new HashMap<>();
		for (int id : loot.itemIds())
		{
			if (crushed.keeps(id) && !ignoredIds.computeIfAbsent(id, k -> isIgnored(k, names)))
			{
				kept.add(id, loot.get(id));
			}
		}
		return kept;
	}

	private boolean isIgnored(int itemId, ItemNames names)
	{
		if (ignored.isEmpty())
		{
			return false;
		}
		int unnoted = itemId;
		String name = null;
		try
		{
			unnoted = names.unnoted(itemId);
			if (ignored.hasNames())
			{
				name = names.name(unnoted);
			}
		}
		catch (RuntimeException e)
		{
			// Item data unavailable: only an id entry can match.
		}
		return ignored.ignores(itemId, unnoted, name);
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * Which price values kill loot; see {@link LootPricing}. Supplies are always valued at GE prices, because they are
 * bought.
 *
 * <p>A "Higher of the two" option was removed (owner decision, 2026-10-25). A config value saved for it no longer
 * matches a constant; RuneLite's config proxy then returns the item's default, GE.</p>
 */
@AllArgsConstructor
public enum LootPriceMode
{
	/** The Grand Exchange price. */
	GE("GE"),
	/** The high-alchemy value. */
	HIGH_ALCH("High alch");

	private final String displayName;

	@Override
	public String toString()
	{
		return displayName;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;

/**
 * Pure loot valuation in a {@link LootPriceMode}, from per-item GE and high-alchemy unit prices (keyed by the id as
 * tallied, as in {@link ItemValuation.UnitPrices}). No RuneLite dependencies.
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>An item whose GE unit price is exactly 0 (untradeable, see {@link ItemValuation}) is valued at its
 *     high-alchemy unit value in every mode (owner decision, 2026-10-25). It has a known price, so it is not
 *     unpriced. An item <em>without</em> a GE price (unavailable) is not affected by this rule.</li>
 *     <li>{@link LootPriceMode#GE GE}: the GE unit price; an item without one is unpriced (left out, counted).</li>
 *     <li>{@link LootPriceMode#HIGH_ALCH High alch}: the high-alchemy unit value; an item without one is unpriced.</li>
 *     <li>Quantities in doses or bites are valued per dose ({@link ItemValuation#total(ItemTally, Map, Map)}).</li>
 * </ul>
 */
final class LootPricing
{
	private LootPricing()
	{
	}

	/**
	 * The unit price of every id in {@code ge} or {@code ha} in {@code mode}, leaving out ids without one. Either map
	 * may be {@code null} (no prices of that kind).
	 */
	static Map<Integer, Long> unitPrices(LootPriceMode mode, Map<Integer, Long> ge, Map<Integer, Long> ha)
	{
		Map<Integer, Long> result = new TreeMap<>();
		switch (mode == null ? LootPriceMode.GE : mode)
		{
			case HIGH_ALCH:
				putAll(result, ha);
				break;
			default:
				result.putAll(geUnitPrices(ge, ha));
				break;
		}
		return result;
	}

	/**
	 * The GE unit price of every id in {@code ge}, with a price of exactly 0 replaced by the id's high-alchemy value
	 * from {@code ha} when it has one (see the class rules). Ids without a GE price are left out. Either map may be
	 * {@code null}.
	 */
	static Map<Integer, Long> geUnitPrices(Map<Integer, Long> ge, Map<Integer, Long> ha)
	{
		Map<Integer, Long> result = new TreeMap<>();
		putAll(result, ge);
		if (ha != null)
		{
			for (Map.Entry<Integer, Long> e : result.entrySet())
			{
				Long alch = ha.get(e.getKey());
				if (e.getValue() == 0 && alch != null && alch > 0)
				{
					e.setValue(alch);
				}
			}
		}
		return result;
	}

	private static void putAll(Map<Integer, Long> into, Map<Integer, Long> from)
	{
		if (from == null)
		{
			return;
		}
		for (Map.Entry<Integer, Long> e : from.entrySet())
		{
			if (e.getKey() != null && e.getValue() != null)
			{
				into.put(e.getKey(), e.getValue());
			}
		}
	}

	/** Total value of {@code tally} in {@code mode}; see the class rules. Saturates at {@link Long#MAX_VALUE}. */
	static long total(ItemTally tally, LootPriceMode mode, Map<Integer, Long> ge, Map<Integer, Long> ha,
		Map<Integer, Integer> dosesPerItem)
	{
		return ItemValuation.total(tally, unitPrices(mode, ge, ha), dosesPerItem);
	}

	/**
	 * Distinct items of {@code tally} whose value in {@code mode} is unknown: without the mode's price. An item with a
	 * GE price of 0 has a known price in GE mode, so it is not counted.
	 */
	static int countUnpriced(ItemTally tally, LootPriceMode mode, Map<Integer, Long> ge, Map<Integer, Long> ha)
	{
		return ItemValuation.countUnpriced(tally, mode == LootPriceMode.HIGH_ALCH ? ha : ge);
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.awt.image.*;
import java.io.*;
import java.util.*;
import javax.imageio.*;
import javax.swing.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * The Slayer masters' face icons of Overall totals' By master headers: each master's chathead image from the
 * Old School RuneScape Wiki, bundled as a class resource under {@link #DIRECTORY} (Jagex's art, credited in the README).
 *
 * <p>Every image is optional: a missing or unreadable file gives {@link SmallItemIcon#EMPTY}, the same 18 by 16 slot,
 * and nothing throws, so deleting the {@code masters/} folder removes the faces with no code change (see
 * {@code docs/PUBLISHING.md}). Images are read with {@code getResourceAsStream}, as the bundled JSON is (no
 * {@code java.io} file APIs), the first time a master's icon is asked for, then kept (a missing one is remembered too).
 * A name two masters share ({@link SlayerMaster#displayName}, for example {@code Duradel/Kuradal}) shows the first
 * master's face; an unknown master shows the empty slot. EDT only.</p>
 *
 * <p>Images are scaled at load to twice the slot (keeping their aspect ratio, in halving steps so the downscale stays
 * smooth) and drawn into the slot at paint time with bicubic interpolation, centred, keeping the aspect ratio
 * ({@link MasterIcon}).</p>
 */
@Slf4j
final class MasterIcons
{
	/** Where the images are, relative to this class's package. */
	static final String DIRECTORY = "masters/";

	/**
	 * The image file of each master name {@link SlayerMaster#displayName} gives. A shared name uses the first master's
	 * face: Turael for Turael/Aya, Duradel for Duradel/Kuradal, Nieve for Nieve/Steve.
	 */
	private static final Map<String, String> FILES;

	static
	{
		Map<String, String> files = new HashMap<>();
		files.put("Turael/Aya", "turael_chathead.png");
		files.put("Mazchna", "mazchna_chathead.png");
		files.put("Vannaka", "vannaka_chathead.png");
		files.put("Chaeldar", "chaeldar_chathead.png");
		files.put("Duradel/Kuradal", "duradel_chathead.png");
		files.put("Nieve/Steve", "nieve_chathead.png");
		files.put("Krystilia", "krystilia_chathead.png");
		files.put("Konar", "konar_quo_maten_chathead.png");
		files.put("Spria", "spria_chathead.png");
		files.put("Mortimer", "mortimer_chathead.png");
		FILES = Collections.unmodifiableMap(files);
	}

	/** Where this loader reads the images from. */
	private final String directory;
	/** The icon of each file asked for; a file that could not be read maps to {@link SmallItemIcon#EMPTY}. */
	private final Map<String, Icon> icons = new HashMap<>();

	MasterIcons()
	{
		this(DIRECTORY);
	}

	/** Test seam: reads the images from {@code directory} (relative to this class's package) instead. */
	MasterIcons(String directory)
	{
		this.directory = directory;
	}

	/** The image file of the master named {@code master} ({@link SlayerMaster#displayName}), or {@code null}. */
	static String fileName(String master)
	{
		return master == null ? null : FILES.get(master);
	}

	/**
	 * The face of the master named {@code master} ({@link SlayerMaster#displayName}) at the small slot size, or
	 * {@link SmallItemIcon#EMPTY} for an unknown master or a missing or unreadable image. Read once, then kept.
	 */
	Icon icon(String master)
	{
		String file = fileName(master);
		if (file == null)
		{
			return SmallItemIcon.EMPTY;
		}
		return icons.computeIfAbsent(file, this::load);
	}

	private Icon load(String file)
	{
		String resource = directory + file;
		try (InputStream stream = MasterIcons.class.getResourceAsStream(resource))
		{
			if (stream == null)
			{
				log.debug("Slayer master image {} is missing", resource);
				return SmallItemIcon.EMPTY;
			}
			BufferedImage image;
			// As RuneLite's ImageUtil: ImageIO is not safe to use from several threads at once.
			synchronized (ImageIO.class)
			{
				image = ImageIO.read(stream);
			}
			if (image == null || image.getWidth() <= 0 || image.getHeight() <= 0)
			{
				log.debug("Slayer master image {} is unreadable", resource);
				return SmallItemIcon.EMPTY;
			}
			return new MasterIcon(file, scaled(image, 2 * ItemListView.ICON_WIDTH, 2 * ItemListView.ICON_HEIGHT));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Unable to load the Slayer master image {}", resource, e);
			return SmallItemIcon.EMPTY;
		}
	}

	/**
	 * {@code image} fitted into {@code maxWidth} by {@code maxHeight}, keeping its aspect ratio, halving the size in
	 * bilinear steps first so the result stays smooth; an image already that small is kept.
	 */
	static BufferedImage scaled(BufferedImage image, int maxWidth, int maxHeight)
	{
		double scale = Math.min(1, Math.min(maxWidth / (double) image.getWidth(), maxHeight / (double) image.getHeight()));
		int targetWidth = Math.max(1, (int) Math.round(image.getWidth() * scale));
		int targetHeight = Math.max(1, (int) Math.round(image.getHeight() * scale));
		BufferedImage current = image;
		while (current.getWidth() != targetWidth || current.getHeight() != targetHeight)
		{
			int width = Math.max(targetWidth, current.getWidth() / 2);
			int height = Math.max(targetHeight, current.getHeight() / 2);
			BufferedImage next = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = next.createGraphics();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
				g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
				g.drawImage(current, 0, 0, width, height, null);
			}
			finally
			{
				g.dispose();
			}
			current = next;
		}
		return current;
	}

	/**
	 * A master's face in the small slot ({@link ItemListView#ICON_WIDTH} by {@link ItemListView#ICON_HEIGHT}), scaled
	 * as it is painted with bicubic interpolation, keeping its aspect ratio, centred.
	 */
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	static final class MasterIcon implements Icon
	{
		/** The image's file name (under {@link #DIRECTORY}), for tests. */
		@Getter
		private final String file;
		private final BufferedImage image;

		@Override
		public void paintIcon(Component c, Graphics g, int x, int y)
		{
			double scale = Math.min(getIconWidth() / (double) image.getWidth(),
				getIconHeight() / (double) image.getHeight());
			int width = Math.max(1, (int) Math.round(image.getWidth() * scale));
			int height = Math.max(1, (int) Math.round(image.getHeight() * scale));
			Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
				g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
				g2.drawImage(image, x + (getIconWidth() - width) / 2, y + (getIconHeight() - height) / 2, width,
					height, null);
			}
			finally
			{
				g2.dispose();
			}
		}

		@Override
		public int getIconWidth()
		{
			return ItemListView.ICON_WIDTH;
		}

		@Override
		public int getIconHeight()
		{
			return ItemListView.ICON_HEIGHT;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;
import lombok.*;

/**
 * The names the shown history needs from the plugin (split from {@link LedgerHistoryModel}): the player's region
 * names and item names, which are asked for and which could not be found, and the nature rune's GE price for the alch
 * hint (it comes with the item names); with the bundled Slayer spot table, the locations they name.
 *
 * <p>Threading: EDT only, like the model that owns it. It only keeps the names and asks for missing ones, each once;
 * the model decides what an arrival means (dropping the statistics, asking for the advisor's plan again) and tells
 * its listener. Callers write through the model.</p>
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class NameBook
{
	/** Asks the plugin for the names of regions (EDT). */
	private final Consumer<Set<Integer>> locationNameRequests;
	/** Asks the plugin for the names of item ids, and the nature rune's price (EDT). */
	private final Consumer<Set<Integer>> itemNameRequests;
	/** Set by {@link #close}: nothing is asked for any more. */
	private boolean closed;

	// Region names
	/**
	 * The player's region names received from the plugin (the active RuneScape profile's), by region id; kept until the
	 * plugin says the profile changed ({@link #clearLocationNames}).
	 */
	private final Map<Integer, String> locationNames = new HashMap<>();
	/** Regions whose names were asked for and have not arrived yet, so they are not asked for twice. */
	private final Set<Integer> locationNamesPending = new HashSet<>();
	/** Regions without a name when last asked; asked again only after the profile changes or one is named. */
	private final Set<Integer> locationNamesMissing = new HashSet<>();
	/** The bundled Slayer spot table; {@link SlayerSpots#NONE} until set. */
	private SlayerSpots spots = SlayerSpots.NONE;

	// Item names
	/** Item names from the plugin, by item id as tallied. */
	private final Map<Integer, String> itemNames = new HashMap<>();
	/** Read-only view of {@link #itemNames}. */
	private final Map<Integer, String> itemNamesView = Collections.unmodifiableMap(itemNames);
	/** Ids asked for whose answer has not arrived yet, so they are not asked for twice. */
	private final Set<Integer> itemNamesPending = new HashSet<>();
	/** Ids the plugin could not name; never asked for again. */
	private final Set<Integer> itemNamesFailed = new HashSet<>();
	/** The nature rune's GE price for the alch hint, or {@code null} while unknown. */
	private Long natureRunePrice;
	/** Whether the nature rune's price was asked for (with the first batch of names). */
	private boolean natureRunePriceAsked;
	/** Bumped whenever item names arrive, so views that show them are worked out again. */
	private long itemNamesVersion;

	/** The plugin stopped: nothing is asked for again. */
	void close()
	{
		closed = true;
	}

	// ---- Region names ----

	/** The player's name for {@code region}, or {@code null} when it has none or it is not known yet. */
	String locationName(Integer region)
	{
		return locationNames.get(region);
	}

	/** Sets the bundled Slayer spot table; {@code null} is {@link SlayerSpots#NONE}. */
	void setSpots(SlayerSpots spots)
	{
		this.spots = spots == null ? SlayerSpots.NONE : spots;
	}

	/** The bundled Slayer spot table; never {@code null}. */
	SlayerSpots spots()
	{
		return spots;
	}

	/**
	 * A saved record's location name as the history shows it ({@link TaskLocation#recordLocation}), with the region
	 * names known so far, or {@code null} when none is known.
	 */
	String recordLocation(LedgerRecord record)
	{
		return TaskLocation.recordLocation(record, this::locationName, spots);
	}

	/** Asks the plugin (once, in one batch) for the names of {@code regions} not known, asked for or missing yet. */
	void requestLocationNames(Set<Integer> regions)
	{
		if (closed)
		{
			return;
		}
		Set<Integer> missing = new HashSet<>();
		for (Integer region : regions)
		{
			if (region != null && LocationTally.isRegion(region) && !locationNames.containsKey(region)
				&& !locationNamesPending.contains(region) && !locationNamesMissing.contains(region))
			{
				missing.add(region);
			}
		}
		if (!missing.isEmpty())
		{
			locationNamesPending.addAll(missing);
			locationNameRequests.accept(missing);
		}
	}

	/**
	 * Adds region names from the plugin ({@code names}, for the regions in {@code requested} that have one; also sent
	 * when the player names one). Requested regions without a name are not asked for again. Returns whether a name
	 * changed.
	 */
	boolean addLocationNames(Set<Integer> requested, Map<Integer, String> names)
	{
		locationNamesPending.removeAll(requested);
		boolean changed = false;
		for (Integer region : requested)
		{
			String name = names.get(region);
			if (name == null)
			{
				locationNamesMissing.add(region);
			}
			else
			{
				locationNamesMissing.remove(region);
				changed |= !name.equals(locationNames.put(region, name));
			}
		}
		return changed;
	}

	/** Forgets every region name (another RuneScape profile is active): they are asked for again as needed. */
	void clearLocationNames()
	{
		locationNames.clear();
		locationNamesPending.clear();
		locationNamesMissing.clear();
	}

	// ---- Item names ----

	/** The name of item {@code id} (as tallied), or {@code null} when it is not known (yet). */
	String itemName(Integer id)
	{
		return itemNames.get(id);
	}

	/**
	 * The item's own name, as Ground Items matches it: {@link #itemName} without the
	 * {@link ClientLookups#NOTED_SUFFIX} a note is shown with (a note's own name is its unnoted item's); {@code null}
	 * when not known (yet).
	 */
	String itemBaseName(Integer id)
	{
		String name = itemNames.get(id);
		return name != null && name.endsWith(ClientLookups.NOTED_SUFFIX)
			? name.substring(0, name.length() - ClientLookups.NOTED_SUFFIX.length()) : name;
	}

	/** Every known item name, by item id; a read-only view. */
	Map<Integer, String> itemNames()
	{
		return itemNamesView;
	}

	/** The nature rune's GE price for the alch hint, or {@code null} while unknown. */
	Long natureRunePrice()
	{
		return natureRunePrice;
	}

	/** Whether the plugin could not name {@code id}. */
	boolean isItemNameFailed(Integer id)
	{
		return itemNamesFailed.contains(id);
	}

	/**
	 * Asks the plugin (once, in one batch) for the names of {@code ids} not known, asked for or failed yet; it looks
	 * them up on the client thread and answers through {@link LedgerHistoryModel#addItemNames}. The nature rune price for the alch hint
	 * comes with the first batch, and is asked for again with later batches while it is unknown.
	 */
	void requestItemNames(Set<Integer> ids)
	{
		if (closed)
		{
			return;
		}
		Set<Integer> missing = new HashSet<>(ids);
		missing.removeAll(itemNames.keySet());
		missing.removeAll(itemNamesPending);
		missing.removeAll(itemNamesFailed);
		if (!missing.isEmpty() || !natureRunePriceAsked)
		{
			natureRunePriceAsked = true;
			itemNamesPending.addAll(missing);
			itemNameRequests.accept(missing);
		}
	}

	/**
	 * Adds item names looked up by the plugin ({@code names}, for the ids in {@code requested} that have one) and the
	 * nature rune's GE price ({@code null} when unavailable); ids without a name are not asked for again. Bumps
	 * {@link #itemNamesVersion}.
	 */
	void addItemNames(Set<Integer> requested, Map<Integer, String> names, Long natureRune)
	{
		if (natureRune != null)
		{
			natureRunePrice = natureRune;
		}
		itemNamesPending.removeAll(requested);
		itemNames.putAll(names);
		for (Integer id : requested)
		{
			if (!names.containsKey(id))
			{
				itemNamesFailed.add(id);
			}
		}
		itemNamesVersion++;
	}

	/** Bumped whenever item names arrive; never goes back. */
	long itemNamesVersion()
	{
		return itemNamesVersion;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * One notable drop of a task: a loot item stack worth at least the "Notable drop value" setting, or a pet. Its values
 * are kept as they were when it dropped, so the history doesn't depend on later prices. Serialized with Gson in
 * {@link LedgerRecord} and {@link SessionSnapshot}; effectively immutable (no setters). Pure (no RuneLite types). The
 * rules are in {@link NotableDrops}.
 */
@Getter
@EqualsAndHashCode
@ToString
@AllArgsConstructor(access = AccessLevel.PRIVATE)
final class NotableDrop
{
	/** What a pet message said. */
	enum Pet
	{
		/** A pet dropped (it follows you, or went to your inventory). */
		RECEIVED,
		/** A pet dropped that you already have, so you didn't receive it. */
		DUPLICATE
	}

	/** Item id as received (possibly noted), or {@code null} for a pet. */
	private Integer itemId;
	/** The item's name when it dropped, or {@code null} for a pet (or when the lookup failed). */
	private String name;
	/** Quantity of the stack; 1 for a pet. */
	private long quantity;
	/**
	 * Value of the stack at the GE price (an untradeable item at its high-alchemy value, as {@link LootPricing} does),
	 * or {@code null} when unknown (and for a pet).
	 */
	private Long geValue;
	/** Value of the stack at its high-alchemy value, or {@code null} when unknown (and for a pet). */
	private Long haValue;
	/** When it dropped (epoch milliseconds). */
	private long time;
	/** For a pet, what its message said; {@code null} for an item. */
	private Pet pet;

	/** For Gson. */
	private NotableDrop()
	{
	}

	/** An item stack worth {@code geValue} / {@code haValue} in all (each {@code null} when unknown). */
	static NotableDrop item(int itemId, String name, long quantity, Long geValue, Long haValue, long time)
	{
		return new NotableDrop(itemId, name, quantity, geValue, haValue, time, null);
	}

	/** A pet message seen at {@code time}. */
	static NotableDrop pet(Pet pet, long time)
	{
		return new NotableDrop(null, null, 1, null, null, time, pet == null ? Pet.RECEIVED : pet);
	}

	/** Whether this is a pet rather than an item stack. */
	boolean isPet()
	{
		return pet != null;
	}

	/** The stack's value in {@code mode} ({@code null} counts as GE), or {@code null} when unknown or a pet. */
	Long value(LootPriceMode mode)
	{
		return mode == LootPriceMode.HIGH_ALCH ? haValue : geValue;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import net.runelite.client.chat.*;
import net.runelite.client.util.*;

/**
 * The notable drop chat line ({@code DESIGN_PRINCIPLES.md} 5.2, 5.3): {@code Dragon chainbody (148K) from a dust
 * devil.} or {@code Abyssal whip (1.4M) at kill 140 of 201.} Pure (RuneLite's static {@link Text} and string-only
 * {@link ChatMessageBuilder} only).
 *
 * <p>Rules (decided by the project manager under the owner's standing OK, 2026-11-09):</p>
 * <ul>
 *     <li>A notable drop is a loot item stack from one kill worth at least the "Notable drop value" setting at the
 *     "Loot price" setting ({@link NotableDrops}). A kill with several gets one line, for the most valuable
 *     ({@link #pick}); a pet gets none (the game announces it).</li>
 *     <li>The line is the item, {@code x25} when the stack is more than one, and its value ({@link LedgerFormat#amount}),
 *     then one of two variants, chosen by the task's kill number so the choice is fixed: on an even kill number,
 *     {@code at kill 140 of 201} (the task's kills done of its assigned size, as the overlay's bar counts them); on an
 *     odd one, or with the kill number unknown, {@code from a dust devil} (the NPC that dropped it, lower case with
 *     {@code a} or {@code an}; a Slayer boss by its own name, {@code from Cerberus}). Without the NPC's name the kill
 *     variant is used when the kill number is known, else the item and value alone.</li>
 *     <li>It ends with {@link #PAID_FOR} only when the drop's value covers the session's supply cost so far
 *     ({@link #paysForTask}): a known, exact cost above 0. The plugin adds it once per task (session), on the first
 *     line it is true for.</li>
 *     <li>An item Ground Items' hidden list hides from the loot value (all but coins) gets no line; the plugin leaves it
 *     out before {@link #pick}, so the kill's next most valuable notable drop, if any, gets the line instead.</li>
 * </ul>
 */
final class NotableDropMessage
{
	/** The one flavour clause, used only when it is true ({@link #paysForTask}). */
	static final String PAID_FOR = "That's the task paid for.";

	private NotableDropMessage()
	{
	}

	/**
	 * The drop to announce from one kill's notable drops: the most valuable item at {@code mode} with a known name and
	 * value (the first of equals); {@code null} when there is none (no drops, or only pets).
	 */
	static NotableDrop pick(List<NotableDrop> drops, LootPriceMode mode)
	{
		NotableDrop best = null;
		if (drops == null)
		{
			return null;
		}
		for (NotableDrop drop : drops)
		{
			if (drop == null || drop.isPet() || drop.getName() == null || drop.getName().trim().isEmpty()
				|| drop.value(mode) == null)
			{
				continue;
			}
			if (best == null || drop.value(mode) > best.value(mode))
			{
				best = drop;
			}
		}
		return best;
	}

	/**
	 * Whether a drop worth {@code dropValue} pays for the task so far: the session's supply cost
	 * ({@code suppliesCost}, GE) is known exactly, above 0 and no more than the drop's value.
	 *
	 * @param suppliesCost the supply cost so far, or {@code null} when unknown or approximate (a price missing)
	 */
	static boolean paysForTask(long dropValue, Long suppliesCost)
	{
		return suppliesCost != null && suppliesCost > 0 && dropValue >= suppliesCost;
	}

	/**
	 * The line for {@code drop} (see the class rules), or {@code null} when it has no name or no value at
	 * {@code mode}.
	 *
	 * @param npcName    the name of the NPC it came from, or {@code null} when unknown
	 * @param killNumber the task's kills done when it dropped, or 0 when unknown
	 * @param taskSize   the task's assigned size, or 0 when unknown
	 * @param paidFor    whether to end with {@link #PAID_FOR} ({@link #paysForTask})
	 */
	static String line(NotableDrop drop, LootPriceMode mode, String npcName, int killNumber, int taskSize,
		boolean paidFor)
	{
		final String item = item(drop, mode);
		if (item == null)
		{
			return null;
		}
		final String source = source(npcName);
		final boolean killKnown = killNumber > 0 && taskSize >= killNumber;
		final String where;
		if (killKnown && (killNumber % 2 == 0 || source == null))
		{
			where = " at kill " + LedgerFormat.kills(killNumber) + " of " + LedgerFormat.kills(taskSize);
		}
		else
		{
			where = source == null ? "" : " from " + source;
		}
		return item + where + "." + (paidFor ? " " + PAID_FOR : "");
	}

	/**
	 * The line ({@link #line}) as a RuneLite chat message ({@code DESIGN_PRINCIPLES.md} 4.5): the item and its value in
	 * the player's chat highlight colour and the rest in the normal one, built with the escaping
	 * {@link ChatMessageBuilder#append(String)}, so a name can't add tags; {@code null} without a line.
	 */
	static String chatMessage(NotableDrop drop, LootPriceMode mode, String npcName, int killNumber, int taskSize,
		boolean paidFor)
	{
		final String line = line(drop, mode, npcName, killNumber, taskSize, paidFor);
		if (line == null)
		{
			return null;
		}
		final String item = item(drop, mode);
		return new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(item)
			.append(ChatColorType.NORMAL)
			.append(line.substring(item.length()))
			.build();
	}

	/** {@code Dragon chainbody (148K)} or {@code Rune bar x25 (125K)}; {@code null} without a name or value. */
	static String item(NotableDrop drop, LootPriceMode mode)
	{
		final Long value = drop == null ? null : drop.value(mode);
		final String name = drop == null || drop.getName() == null ? null : drop.getName().trim();
		if (value == null || name == null || name.isEmpty())
		{
			return null;
		}
		return name + (drop.getQuantity() > 1 ? " x" + LedgerFormat.kills(drop.getQuantity()) : "") + " ("
			+ LedgerFormat.amount(value) + ")";
	}

	/**
	 * Who dropped it, for {@code from ...}: a Slayer boss by its own name ({@code Cerberus}), any other NPC in lower
	 * case with its article ({@code a dust devil}, {@code an abyssal demon}); {@code null} without a name.
	 */
	static String source(String npcName)
	{
		final String name = npcName == null ? null : Text.removeTags(npcName).trim();
		if (name == null || name.isEmpty())
		{
			return null;
		}
		if (SlayerBosses.isBossNpcName(name))
		{
			return name;
		}
		final String lower = name.toLowerCase(Locale.ROOT);
		return ("aeiou".indexOf(lower.charAt(0)) >= 0 ? "an " : "a ") + lower;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;

/**
 * Rules for a task's notable drops ({@link NotableDrop}). Pure (no RuneLite types).
 *
 * <ul>
 *     <li>A loot item stack is notable when its value, in the "Loot price" setting's mode, is at least the "Notable
 *     drop value" setting ({@link #DEFAULT_THRESHOLD} by default). The value is the unit price times the quantity,
 *     with the same unit prices as the live loot value ({@link LootPricing}): in GE mode an untradeable item counts at
 *     its high-alchemy value. An item whose price in that mode is unavailable is never notable. One stack is one item
 *     id in one kill's loot (stacks of the same id in one kill are added up), after the bonecrusher and "Ignored loot"
 *     filters.</li>
 *     <li>A pet message ({@link PetMessage}) is always notable.</li>
 *     <li>A task keeps at most {@link #MAX_PER_TASK} notable drops, so the ledger file can't grow without limit. When
 *     another arrives, the lowest-ranked one is left out: items rank by value (the higher of the GE and high-alchemy
 *     values; unknown counts as 0), pets above every item, and among equals the oldest goes first.</li>
 * </ul>
 */
final class NotableDrops
{
	/** Default "Notable drop value" setting, in gp (owner decision, 2026-10-26). */
	static final int DEFAULT_THRESHOLD = 100_000;
	/** Most notable drops kept per task. */
	static final int MAX_PER_TASK = 20;

	/** Newest first by time; equal times keep the later-added one first when the list is reversed beforehand. */
	private static final Comparator<NotableDrop> NEWEST_FIRST =
		Comparator.comparingLong(NotableDrop::getTime).reversed();

	private NotableDrops()
	{
	}

	/** The threshold to use for a setting value: at least 1 gp. */
	static long threshold(long setting)
	{
		return Math.max(1, setting);
	}

	/**
	 * The notable stacks of one kill's loot.
	 *
	 * @param drop      the kill's loot (after filtering), by item id as received
	 * @param prices    unit prices of the loot's items ({@link ItemValuation#capturePrices})
	 * @param mode      the "Loot price" setting ({@code null} is GE)
	 * @param threshold the "Notable drop value" setting, in gp (see {@link #threshold(long)})
	 * @param names     the item name for an id, or {@code null}; only asked for notable items
	 * @param time      when the loot arrived (epoch milliseconds)
	 * @return the notable stacks, in item id order (empty when none)
	 */
	static List<NotableDrop> find(ItemTally drop, ItemValuation.UnitPrices prices, LootPriceMode mode,
		long threshold, IntFunction<String> names, long time)
	{
		if (drop == null || drop.isEmpty() || prices == null)
		{
			return Collections.emptyList();
		}
		final long minimum = threshold(threshold);
		final Map<Integer, Long> ge = LootPricing.geUnitPrices(prices.getGe(), prices.getHa());
		final Map<Integer, Long> ha = prices.getHa();
		List<NotableDrop> result = new ArrayList<>();
		for (int id : drop.itemIds())
		{
			final long quantity = drop.get(id);
			final Long geValue = stackValue(ge.get(id), quantity);
			final Long haValue = stackValue(ha.get(id), quantity);
			final Long value = mode == LootPriceMode.HIGH_ALCH ? haValue : geValue;
			if (value != null && value >= minimum)
			{
				result.add(NotableDrop.item(id, names == null ? null : names.apply(id), quantity, geValue, haValue,
					time));
			}
		}
		return result;
	}

	/** {@code unit * quantity}, saturating; {@code null} when the unit price is unknown or the quantity isn't positive. */
	static Long stackValue(Long unit, long quantity)
	{
		if (unit == null || quantity <= 0)
		{
			return null;
		}
		if (unit <= 0)
		{
			return 0L;
		}
		return unit > Long.MAX_VALUE / quantity ? Long.MAX_VALUE : unit * quantity;
	}

	/**
	 * {@code current} with {@code added} appended, keeping at most {@link #MAX_PER_TASK} (see the class rules).
	 * {@code null} entries are dropped. Neither list is changed; the result is in the order the drops were added.
	 */
	static List<NotableDrop> add(Collection<NotableDrop> current, Collection<NotableDrop> added)
	{
		List<NotableDrop> result = new ArrayList<>();
		addNonNull(result, current);
		addNonNull(result, added);
		while (result.size() > MAX_PER_TASK)
		{
			int lowest = 0;
			for (int i = 1; i < result.size(); i++)
			{
				// Strictly lower, so among equals the oldest (first) is removed.
				if (rank(result.get(i)) < rank(result.get(lowest)))
				{
					lowest = i;
				}
			}
			result.remove(lowest);
		}
		return result;
	}

	/** A stored list cleaned up for use: no {@code null} entries, at most {@link #MAX_PER_TASK}. */
	static List<NotableDrop> sanitize(Collection<NotableDrop> stored)
	{
		return add(stored, null);
	}

	/** {@code drops} newest first (by time; among equal times the later-added first). */
	static List<NotableDrop> newestFirst(Collection<NotableDrop> drops)
	{
		List<NotableDrop> result = sanitize(drops);
		Collections.reverse(result);
		result.sort(NEWEST_FIRST);
		return result;
	}

	/** Rank for {@link #add}: pets above every item, items by their higher known value. */
	static long rank(NotableDrop drop)
	{
		if (drop.isPet())
		{
			return Long.MAX_VALUE;
		}
		long ge = drop.getGeValue() == null ? 0 : drop.getGeValue();
		long ha = drop.getHaValue() == null ? 0 : drop.getHaValue();
		// Below every pet, even for an item at Long.MAX_VALUE.
		return Math.min(Long.MAX_VALUE - 1, Math.max(ge, ha));
	}

	private static void addNonNull(List<NotableDrop> into, Collection<NotableDrop> from)
	{
		if (from == null)
		{
			return;
		}
		for (NotableDrop d : from)
		{
			if (d != null)
			{
				into.add(d);
			}
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;

/**
 * Rules for a session's kills per NPC name: each death of an NPC the player damaged while the session ran is
 * added to its name, in the order names are first seen. Names are matched by {@link TaskStatistics#normalize}; the
 * first spelling seen is kept. Pure (no RuneLite types); the lists passed in are never changed.
 */
final class NpcKillTally
{
	/**
	 * Most names tallied per session; kills of further names are not tallied (the task count is unaffected), except a
	 * name the variant decision reads ({@link TaskVariants#isDecidingNpcName}: a Catacombs variant's, a Slayer boss's
	 * or a listed superior's), which is always tallied, so a session that met many other NPCs first still decides its
	 * variant and boss flag. At most {@code MAX_NAMES} plus those names.
	 */
	static final int MAX_NAMES = 32;

	private NpcKillTally()
	{
	}

	/**
	 * A copy of {@code tally} with one more kill of {@code name} (saturating). Nothing is added for a blank name, or a
	 * new name the variant decision doesn't read once {@link #MAX_NAMES} are tallied.
	 *
	 * @param tally the tally so far, or {@code null} for none
	 */
	static List<NpcKills> add(List<NpcKills> tally, String name)
	{
		final List<NpcKills> result = sanitize(tally);
		merge(result, name, 1);
		return result;
	}

	/**
	 * A clean copy of a tally (for example one read from a file): entries without a name or kills are dropped, a
	 * repeated name is merged into its first entry, and at most {@link #MAX_NAMES} names are kept, plus any names the
	 * variant decision reads. Never {@code null}.
	 */
	static List<NpcKills> sanitize(List<NpcKills> tally)
	{
		final List<NpcKills> result = new ArrayList<>();
		if (tally == null)
		{
			return result;
		}
		for (NpcKills entry : tally)
		{
			if (entry != null)
			{
				merge(result, entry.getName(), entry.getKills());
			}
		}
		return result;
	}

	/** The kills tallied for {@code name} (matched by {@link TaskStatistics#normalize}); 0 for none. */
	static int killsOf(List<NpcKills> tally, String name)
	{
		final String key = TaskStatistics.normalize(name);
		if (tally == null || key == null)
		{
			return 0;
		}
		int kills = 0;
		for (NpcKills entry : tally)
		{
			if (entry != null && entry.getKills() > 0 && key.equals(TaskStatistics.normalize(entry.getName())))
			{
				kills = saturatedAdd(kills, entry.getKills());
			}
		}
		return kills;
	}

	/** Every kill in the tally; 0 for none. */
	static int total(List<NpcKills> tally)
	{
		if (tally == null)
		{
			return 0;
		}
		int kills = 0;
		for (NpcKills entry : tally)
		{
			if (entry != null && TaskStatistics.normalize(entry.getName()) != null && entry.getKills() > 0)
			{
				kills = saturatedAdd(kills, entry.getKills());
			}
		}
		return kills;
	}

	private static void merge(List<NpcKills> result, String name, int kills)
	{
		final String key = TaskStatistics.normalize(name);
		if (key == null || kills <= 0)
		{
			return;
		}
		for (int i = 0; i < result.size(); i++)
		{
			final NpcKills entry = result.get(i);
			if (key.equals(TaskStatistics.normalize(entry.getName())))
			{
				result.set(i, new NpcKills(entry.getName(), saturatedAdd(entry.getKills(), kills)));
				return;
			}
		}
		if (result.size() < MAX_NAMES || TaskVariants.isDecidingNpcName(name))
		{
			result.add(new NpcKills(name.trim(), kills));
		}
	}

	private static int saturatedAdd(int a, int b)
	{
		final long sum = (long) a + b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * The player's kills of one NPC name in a session. Serialized with Gson in {@link SessionSnapshot}; effectively
 * immutable (no setters). Pure (no RuneLite types). The rules are in {@link NpcKillTally}.
 */
@Getter
@EqualsAndHashCode
@ToString
@AllArgsConstructor(access = AccessLevel.PACKAGE)
final class NpcKills
{
	/** The NPC's name as the game gives it, trimmed (for example "Deviant spectre"). */
	private String name;
	/** Deaths of NPCs with this name that the player had damaged; at least 1. */
	private int kills;

	/** For Gson. */
	private NpcKills()
	{
	}
}

package com.shmayvan.slayerledger;

import java.time.*;
import java.util.*;
import lombok.*;

/**
 * Overall and grouped totals from completed played-task records. XP is the total of every skill in a record's
 * {@code xpGained} ({@link SkillXp#total}; owner decision), not only Slayer XP. Each group also sums its tasks'
 * supplies and loot item by item ({@link ItemSums}), from the rows their history details show
 * ({@link ItemDetails}) at the same prices as the profit; a task saved without item data adds none.
 *
 * <p>Each group also has the figures the By monster and By master groupings show: kills, averages per
 * task, profit per kill and per hour, Slayer XP and Slayer points. The rates are pooled over the group's task
 * samples ({@link TaskStatistics#isTaskSample}) that recorded the figure, an hourly rate only from
 * {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of their active time, and Slayer XP only (the {@link SkillXp#SLAYER}
 * entry). A task that didn't record a figure is left out of it rather than counted as 0.
 * By master groups also count the master's assignments per monster ({@link Assignment}): its completed played tasks
 * plus the assignment log's entries ({@link AssignmentEntry}: skipped, blocked, reset, untracked and other ended
 * assignments).</p>
 */
final class OverallTotals
{
	@AllArgsConstructor
	enum Grouping
	{
		ALL("Overall"),
		MASTER("By master"),
		MONTH("By month"),
		/** One group per monster as the history names it ({@link LedgerRecord#groupName}). */
		MONSTER("By monster");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	static final String UNKNOWN_MASTER = "Unknown master";
	static final String UNKNOWN_DATE = "Unknown date";

	/** Sort rank of a group: named groups first, then masters with an unnamed id, then no master or date. */
	private static final int NAMED = 0;
	private static final int UNNAMED_ID = 1;
	private static final int UNKNOWN = 2;

	/** Most assigned first, then by name ignoring case, then by name. */
	private static final Comparator<Assignment> ASSIGNMENT_ORDER = Comparator
		.comparingInt(Assignment::getCount).reversed()
		.thenComparing(Assignment::getName, String.CASE_INSENSITIVE_ORDER)
		.thenComparing(Assignment::getName);

	private OverallTotals()
	{
	}

	/**
	 * Aggregates completed records, leaving profit and XP unknown unless the record captured them. Monthly groups use
	 * each task's local completion month; records without an end time are kept in an unknown-date group. Items are
	 * summed in the order of {@code records} (the history's: newest first), which picks the unit prices a summed row's
	 * tooltip shows ({@link ItemSums}). The loot items {@code hidden} hides are left out of the profit
	 * ({@link HistoryPricing}); the summed loot items still list them, and the panel leaves them out of its grid. By
	 * master groups also count their assignments per monster ({@link Entry#getAssignments}) from the completed records
	 * and {@code assignments}, the assignment log's entries. Only masters with a group (a completed played task) are
	 * counted.
	 *
	 * @param currentGe today's GE unit prices the records are valued at ({@link HistoryPricing}); never {@code null}
	 */
	static List<Entry> summarize(Collection<LedgerRecord> records, Collection<AssignmentEntry> assignments,
		Grouping grouping, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden, ZoneId zone)
	{
		Objects.requireNonNull(currentGe, "currentGe");
		if (records == null || records.isEmpty() || grouping == null)
		{
			return Collections.emptyList();
		}
		ZoneId localZone = zone == null ? ZoneId.systemDefault() : zone;
		Map<String, Aggregate> groups = new HashMap<>();
		for (LedgerRecord record : records)
		{
			if (!isCompletedTask(record))
			{
				continue;
			}
			String key = groupKey(record, grouping, localZone);
			int rank = groupRank(record, grouping);
			// By monster: keyed by the normalized name, labelled as the first (newest) record names it, and its icon is
			// that record's assigned task's, so a Catacombs variant or cannon task shows its task's icon.
			String label = grouping == Grouping.MONSTER ? monsterLabel(record) : key;
			String task = grouping == Grouping.MONSTER ? record.getMonster() : null;
			Aggregate aggregate = groups.computeIfAbsent(key, k -> new Aggregate(label, rank, task));
			aggregate.add(record, mode, currentGe, hidden);
		}
		if (grouping == Grouping.MASTER)
		{
			countAssignments(records, assignments, groups);
		}

		List<Entry> entries = new ArrayList<>();
		for (Map.Entry<String, Aggregate> group : groups.entrySet())
		{
			entries.add(group.getValue().toEntry());
		}
		entries.sort(comparator(grouping));
		return Collections.unmodifiableList(entries);
	}

	private static boolean isCompletedTask(LedgerRecord record)
	{
		return record != null && record.isCompleted() && !record.isPartial() && record.getKills() > 0;
	}

	private static String groupKey(LedgerRecord record, Grouping grouping, ZoneId zone)
	{
		switch (grouping)
		{
			case MASTER:
				return masterKey(record.getSlayerMaster());
			case MONTH:
				return record.getEndedAt() <= 0 ? UNKNOWN_DATE
					: YearMonth.from(Instant.ofEpochMilli(record.getEndedAt()).atZone(zone)).toString();
			case MONSTER:
				return TaskStatistics.normalize(monsterLabel(record));
			default:
				return "Overall";
		}
	}

	/**
	 * The By monster name of a record: the name the history shows and groups it under
	 * ({@link LedgerRecord#groupName}, with its Catacombs variant and cannon use), trimmed;
	 * {@link LedgerHistory#UNKNOWN_MONSTER} when blank.
	 */
	private static String monsterLabel(LedgerRecord record)
	{
		String name = LedgerHistory.monster(record).trim();
		return name.isEmpty() ? LedgerHistory.UNKNOWN_MONSTER : name;
	}

	/** The By master group of a SLAYER_MASTER value: its name, "Unknown master (N)" or {@link #UNKNOWN_MASTER}. */
	private static String masterKey(Integer master)
	{
		String masterName = SlayerMaster.displayName(master);
		return masterName == null ? UNKNOWN_MASTER : masterName;
	}

	private static int groupRank(LedgerRecord record, Grouping grouping)
	{
		switch (grouping)
		{
			case MASTER:
				if (SlayerMaster.hasName(record.getSlayerMaster()))
				{
					return NAMED;
				}
				return SlayerMaster.displayName(record.getSlayerMaster()) == null ? UNKNOWN : UNNAMED_ID;
			case MONTH:
				return record.getEndedAt() <= 0 ? UNKNOWN : NAMED;
			default:
				return NAMED;
		}
	}

	/**
	 * Months newest first and masters by name ignoring case; in both, unknown groups come last ("Unknown master (N)"
	 * groups, then "Unknown master"; "Unknown date"). Monsters by task count, most first, then by name ignoring case.
	 */
	private static Comparator<Entry> comparator(Grouping grouping)
	{
		Comparator<Entry> byRank = Comparator.comparingInt(entry -> entry.rank);
		if (grouping == Grouping.MONTH)
		{
			// "yyyy-MM" labels sort by date as text.
			return byRank.thenComparing(Entry::getLabel, Comparator.reverseOrder());
		}
		if (grouping == Grouping.MONSTER)
		{
			return Comparator.comparingInt(Entry::getTaskCount).reversed()
				.thenComparing(Entry::getLabel, String.CASE_INSENSITIVE_ORDER)
				.thenComparing(Entry::getLabel);
		}
		return byRank.thenComparing(Entry::getLabel, String.CASE_INSENSITIVE_ORDER)
			.thenComparing(Entry::getLabel);
	}

	/**
	 * Counts each By master group's assignments per monster: every completed task the groups count
	 * ({@link #isCompletedTask}, so a completed record without kills is not one) and every assignment log entry,
	 * under its master. A task is counted under its assigned name ({@link LedgerRecord#getMonster}), so a Catacombs
	 * variant or cannon task counts as its task. Entries and records of a master without a group are left out.
	 */
	private static void countAssignments(Collection<LedgerRecord> records, Collection<AssignmentEntry> assignments,
		Map<String, Aggregate> groups)
	{
		for (LedgerRecord record : records)
		{
			if (isCompletedTask(record))
			{
				Aggregate group = groups.get(masterKey(record.getSlayerMaster()));
				if (group != null)
				{
					group.assignments.add(record.getMonster(), null);
				}
			}
		}
		if (assignments == null)
		{
			return;
		}
		for (AssignmentEntry entry : assignments)
		{
			if (entry != null)
			{
				Aggregate group = groups.get(masterKey(entry.getSlayerMaster()));
				if (group != null)
				{
					group.assignments.add(entry.getMonster(), AssignmentOutcome.orUnknown(entry.getOutcome()));
				}
			}
		}
	}

	/**
	 * {@code 12 / 80 (15%)}: a monster's assignments out of the master's. The share is rounded to a whole percent
	 * (half up); a share that rounds to 0 shows as {@code <1%}.
	 */
	static String shareText(int count, int total)
	{
		return count + " / " + total + " (" + percentText(count, total) + ")";
	}

	private static String percentText(int count, int total)
	{
		if (total <= 0)
		{
			return LedgerHistory.NO_VALUE;
		}
		long percent = Math.round(count * 100d / total);
		return percent == 0 && count > 0 ? "<1%" : percent + "%";
	}

	/** {@code total / n} rounded, or {@code null} without samples. */
	private static Long average(long total, long n)
	{
		return n <= 0 ? null : Math.round(total / (double) n);
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** {@code total} per active hour, or {@code null} under {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of time. */
	static Long perHour(long total, long activeMillis)
	{
		if (activeMillis < TaskTimeEstimate.MIN_ACTIVE_MILLIS)
		{
			return null;
		}
		return Math.round(total * 3_600_000d / activeMillis);
	}

	/** {@code total} per kill, or {@code null} without kills; no minimum time. */
	static Long perKill(long total, long kills)
	{
		return kills <= 0 ? null : Math.round(total / (double) kills);
	}

	/**
	 * One monster in a By master group's assignments: how often the master assigned it, of how many, and how
	 * they ended. Immutable; equal when every field is.
	 */
	@Value
	static class Assignment
	{
		/** The task's name as the newest of them names it. */
		String name;
		int count;
		/** All the master's assignments counted. */
		int total;
		/** Assignments played to completion with a saved task the groups count (with kills). */
		int completed;
		/** Assignment log entries by outcome; unmodifiable, without zero counts. */
		Map<AssignmentOutcome, Integer> outcomes;

		/** {@code 12 / 80 (15%)} ({@link #shareText}). */
		String text()
		{
			return shareText(count, total);
		}

		/**
		 * HTML tooltip: the name, the count of the master's assignments with the exact share, then how they ended
		 * ({@code Completed: 8}, then each outcome of the log's entries, as their rows label them).
		 */
		String tooltip(String master)
		{
			StringBuilder sb = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(name))
				.append("<br>").append(count).append(" of ").append(total)
				.append(total == 1 ? " assignment" : " assignments").append(" from ")
				.append(LedgerHistory.escapeHtml(master));
			if (total > 0)
			{
				sb.append(String.format(Locale.ROOT, " (%.1f%%)", count * 100d / total));
			}
			if (completed > 0)
			{
				sb.append("<br>Completed: ").append(completed);
			}
			for (Map.Entry<AssignmentOutcome, Integer> outcome : outcomes.entrySet())
			{
				sb.append("<br>").append(outcome.getKey().getLabel()).append(": ").append(outcome.getValue());
			}
			return sb.append("</html>").toString();
		}
	}

	@Builder
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Entry
	{
		@Getter
		private final String label;
		/**
		 * By monster: the assigned task name ({@link LedgerRecord#getMonster}) of the group's newest task, without its
		 * Catacombs variant or cannon use, whose icon ({@link TaskIcons}) the group shows; {@code null} in other
		 * groupings or when the task had no name.
		 */
		@Getter
		private final String task;
		private final int rank;
		@Getter
		private final int taskCount;
		@Getter
		private final long activeMillis;
		@Getter
		private final Long profit;
		@Getter
		private final int profitSampleCount;
		@Getter
		private final boolean profitApproximate;
		/** XP of every skill ({@link SkillXp#total}) over the records with {@code xpGained}, or {@code null}. */
		@Getter
		private final Long xp;
		@Getter
		private final int xpSampleCount;
		/** Summed supplies, unnamed and unsorted ({@link ItemSums#rows()}); empty without item data. */
		private final List<ItemDetails.Row> supplies;
		/** Summed loot, unnamed, unsorted and without the alch hint ({@link ItemSums#rows()}). */
		private final List<ItemDetails.Row> loot;
		/** Task kills of all the group's tasks. */
		@Getter
		private final long kills;
		/** Active time per kill over the group's task samples, or {@code null} without any. */
		@Getter
		private final Long millisPerKill;
		/**
		 * Profit per kill, pooled ({@link OverallTotals#perKill}): the profit of the task samples that have one over
		 * their kills, or {@code null} without any.
		 */
		@Getter
		private final Long profitPerKill;
		/**
		 * Profit per hour, pooled ({@link OverallTotals#perHour}): the profit of the task samples that have one over
		 * their active time, or {@code null} under {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of it.
		 */
		@Getter
		private final Long profitPerHour;
		/** Whether {@link #getProfitPerKill} and {@link #getProfitPerHour} are approximate. */
		@Getter
		private final boolean profitRateApproximate;
		/** Slayer XP only, over the tasks with recorded XP, or {@code null} when none has any. */
		@Getter
		private final Long slayerXp;
		@Getter
		private final int slayerXpSampleCount;
		/**
		 * Slayer XP per hour, pooled (the task samples with XP over their active time), or
		 * {@code null} under {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS} of it.
		 */
		@Getter
		private final Long slayerXpPerHour;
		/** Slayer points of the tasks that recorded them (bonus tasks included), or {@code null} when none did. */
		@Getter
		private final Long points;
		@Getter
		private final int pointsSampleCount;
		/** Points of the tasks with recorded points that are not bonus (milestone) tasks, for the average. */
		private final long regularPoints;
		private final int regularPointsSampleCount;
		/** By master: the master's assignments per monster, most first; empty otherwise. */
		private final List<Assignment> assignments;
		/** By master: all the master's assignments counted; 0 in other groupings. */
		@Getter
		private final int assignmentTotal;

		/** Average active time per task. */
		long getAverageActiveMillis()
		{
			return taskCount <= 0 ? 0 : activeMillis / taskCount;
		}

		/** Average profit per task over the {@link #getProfitSampleCount} tasks that have one, or {@code null}. */
		Long getAverageProfit()
		{
			return profit == null ? null : average(profit, profitSampleCount);
		}

		/**
		 * The group's supplies summed item by item, valued at GE prices as the profit counts them; not named, so name
		 * them on the EDT ({@link ItemDetails#named}). Empty when none of its tasks used any or has item data.
		 */
		List<ItemDetails.Row> getSupplies()
		{
			return supplies == null ? Collections.emptyList() : supplies;
		}

		/**
		 * The group's loot summed item by item, in the Loot price mode as the profit counts it; not named and without
		 * the alch hint ({@link ItemDetails#named}). Empty when none of its tasks has any.
		 */
		List<ItemDetails.Row> getLoot()
		{
			return loot == null ? Collections.emptyList() : loot;
		}

		/** Average Slayer XP per task over {@link #getSlayerXpSampleCount} tasks, or {@code null}. */
		Long getAverageSlayerXp()
		{
			return slayerXp == null ? null : average(slayerXp, slayerXpSampleCount);
		}

		/**
		 * Average points per task over the {@link #getAveragePointsSampleCount} tasks with recorded points that are not
		 * bonus tasks ({@link StreakMilestone#isMilestone}, as Points/h leaves them out), or {@code null} without any.
		 * {@link #getPoints} still counts the bonus tasks.
		 */
		Long getAveragePoints()
		{
			return average(regularPoints, regularPointsSampleCount);
		}

		/** The tasks {@link #getAveragePoints} averages over. */
		int getAveragePointsSampleCount()
		{
			return regularPointsSampleCount;
		}

		/** By master: each monster's assignments, most first ({@link Assignment}); empty in other groupings. */
		List<Assignment> getAssignments()
		{
			return assignments == null ? Collections.emptyList() : assignments;
		}
	}

	/** A pooled rate's totals: its total, active time and kills. */
	private static final class Pool
	{
		private long total;
		private long activeMillis;
		private long kills;
		private boolean approximate;

		private void add(long value, LedgerRecord record, boolean isApproximate)
		{
			total = saturatedAdd(total, value);
			activeMillis = saturatedAdd(activeMillis, record.getActiveMillis());
			kills = saturatedAdd(kills, record.getKills());
			approximate |= isApproximate;
		}

		private Long perHour()
		{
			return activeMillis <= 0 ? null : OverallTotals.perHour(total, activeMillis);
		}
	}

	/** A By master group's assignments per monster, by normalized name. */
	private static final class AssignmentTally
	{
		private final Map<String, Counts> monsters = new LinkedHashMap<>();
		private int total;

		/** Counts one assignment of {@code monster}: a completed task ({@code outcome} {@code null}) or a log entry. */
		private void add(String monster, AssignmentOutcome outcome)
		{
			String name = monster == null || TaskStatistics.normalize(monster) == null
				? LedgerHistory.UNKNOWN_MONSTER : monster.trim();
			Counts counts = monsters.computeIfAbsent(TaskStatistics.normalize(name), k -> new Counts(name));
			counts.count++;
			if (outcome == null)
			{
				counts.completed++;
			}
			else
			{
				counts.outcomes.merge(outcome, 1, Integer::sum);
			}
			total++;
		}

		private List<Assignment> rows()
		{
			List<Assignment> rows = new ArrayList<>();
			for (Counts counts : monsters.values())
			{
				rows.add(new Assignment(counts.name, counts.count, total, counts.completed,
					Collections.unmodifiableMap(new EnumMap<>(counts.outcomes))));
			}
			rows.sort(ASSIGNMENT_ORDER);
			return Collections.unmodifiableList(rows);
		}

		@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
		private static final class Counts
		{
			private final String name;
			private int count;
			private int completed;
			private final Map<AssignmentOutcome, Integer> outcomes = new EnumMap<>(AssignmentOutcome.class);
		}
	}

	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Aggregate
	{
		private final String label;
		private final int rank;
		/** By monster: the newest task's assigned name ({@link Entry#getTask}); {@code null} otherwise. */
		private final String task;
		private int taskCount;
		private long activeMillis;
		private long profit;
		private int profitSampleCount;
		private boolean profitApproximate;
		private long xp;
		private int xpSampleCount;
		private final ItemSums supplies = new ItemSums();
		private final ItemSums loot = new ItemSums();
		private long kills;
		/** The task samples' time and kills, for the time per kill. */
		private final Pool time = new Pool();
		private final Pool profitRate = new Pool();
		private long slayerXp;
		private int slayerXpSampleCount;
		private final Pool slayerXpRate = new Pool();
		private long points;
		private int pointsSampleCount;
		private long regularPoints;
		private int regularPointsSampleCount;
		private final AssignmentTally assignments = new AssignmentTally();

		private void add(LedgerRecord record, LootPriceMode mode, Map<Integer, Long> currentGe, HiddenLoot hidden)
		{
			taskCount++;
			activeMillis = saturatedAdd(activeMillis, Math.max(0, record.getActiveMillis()));
			kills = saturatedAdd(kills, record.getKills());
			// The rates pool only the task samples (a task with no active time adds none).
			boolean sample = TaskStatistics.isTaskSample(record);
			if (sample)
			{
				time.add(0, record, false);
			}

			if (LedgerHistory.isValued(record))
			{
				HistoryPricing.Values values = HistoryPricing.value(record, mode, currentGe, hidden);
				if (values.getProfit() != null)
				{
					profit = saturatedAdd(profit, values.getProfit());
					profitSampleCount++;
					profitApproximate |= values.isProfitApproximate();
					if (sample)
					{
						profitRate.add(values.getProfit(), record, values.isProfitApproximate());
					}
				}
			}

			Map<String, Long> recordXp = record.getXpGained();
			if (recordXp != null)
			{
				xp = saturatedAdd(xp, SkillXp.total(recordXp));
				xpSampleCount++;
				// XP recorded without a Slayer entry means no Slayer XP was gained.
				Long slayer = recordXp.get(SkillXp.SLAYER);
				long slayerValue = slayer == null ? 0 : Math.max(0, slayer);
				slayerXp = saturatedAdd(slayerXp, slayerValue);
				slayerXpSampleCount++;
				if (sample)
				{
					slayerXpRate.add(slayerValue, record, false);
				}
			}

			Integer earned = record.getPointsEarned();
			if (earned != null && earned >= 0)
			{
				points = saturatedAdd(points, earned);
				pointsSampleCount++;
				// The average leaves out bonus tasks, whose points would swamp it.
				if (!StreakMilestone.isMilestone(record.getTaskStreak()))
				{
					regularPoints = saturatedAdd(regularPoints, earned);
					regularPointsSampleCount++;
				}
			}

			addItems(record, mode, currentGe);
		}

		/**
		 * Adds the record's supplies and loot as its history details show them (at the same prices: today's GE prices,
		 * as {@link HistoryPricing} values the profit); nothing without item data.
		 */
		private void addItems(LedgerRecord record, LootPriceMode mode, Map<Integer, Long> currentGe)
		{
			ItemDetails items = ItemDetails.of(record);
			if (items == null)
			{
				return;
			}
			items = items.withGePrices(currentGe);
			supplies.add(items.supplyRows(null));
			loot.add(items.lootRows(mode, null));
		}

		private Entry toEntry()
		{
			return Entry.builder()
				.label(label)
				.task(task)
				.rank(rank)
				.taskCount(taskCount)
				.activeMillis(activeMillis)
				.profit(profitSampleCount == 0 ? null : profit)
				.profitSampleCount(profitSampleCount)
				.profitApproximate(profitApproximate)
				.xp(xpSampleCount == 0 ? null : xp)
				.xpSampleCount(xpSampleCount)
				.supplies(supplies.rows())
				.loot(loot.rows())
				.kills(kills)
				.millisPerKill(perKill(time.activeMillis, time.kills))
				.profitPerKill(perKill(profitRate.total, profitRate.kills))
				.profitPerHour(profitRate.perHour())
				.profitRateApproximate(profitRate.approximate)
				.slayerXp(slayerXpSampleCount == 0 ? null : slayerXp)
				.slayerXpSampleCount(slayerXpSampleCount)
				.slayerXpPerHour(slayerXpRate.perHour())
				.points(pointsSampleCount == 0 ? null : points)
				.pointsSampleCount(pointsSampleCount)
				.regularPoints(regularPoints)
				.regularPointsSampleCount(regularPointsSampleCount)
				.assignments(assignments.rows())
				.assignmentTotal(assignments.total)
				.build();
		}
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import lombok.*;

/**
 * The collapsed "Overall totals" section of {@link SlayerLedgerPanel}: completed-task totals, overall or grouped
 * by Slayer master, month or monster ({@link OverallTotals}, worked out by the history model). The rows are built only
 * while the section is open and its "Overall totals" setting shows it, and never by the panel's refresh timer.
 * Overall and By month show the active time, profit and XP of all skills; By monster and By master show
 * averages and rates instead, and By master its monsters assigned ({@link OverallTotals.Assignment}) in a text list
 * with "+N more" ({@link ItemListView}).
 *
 * <p>Look A (DESIGN_PRINCIPLES.md 3.3, 3.8): flat on the page under its section header, no cards. Each
 * group is a block, and a grouping's blocks are small multiples: the same rows in the same order and units, so the eye
 * compares values, not layouts. A block's title is the group's name in Bold in {@link LedgerTheme#HEADING} with its
 * sample size on the right ({@code 3 tasks}). Each row is a label in Small in {@link LedgerTheme#LABEL}, with the unit
 * in it ({@code Profit (GE)/h}), and its value right-aligned in Plain, every amount through {@link LedgerFormat} (one
 * rule per row, so a row has the same precision in every block), profit signed and coloured. A total that only some
 * of the group's tasks recorded says how many beside its label, in {@link LedgerTheme#HINT} ({@code 2 tasks}).</p>
 *
 * <p>By monster's group names and By master's monsters assigned show the task's icon before the name
 * ({@link TaskIcons}), the item sprite at the XP lists' small icon size ({@link SmallItemIcon}), asked for on the EDT
 * only when the rows are built (open and shown, never by the refresh timer); a task without a known icon keeps an
 * empty slot of the same size.</p>
 *
 * <p>By master's group names show the master's face ({@link MasterIcons}), the bundled chathead image drawn in
 * the same slot, read the first time it is shown; a missing image or an unknown master keeps the empty slot.</p>
 *
 * <p>Each group has two item grids, "Supplies used" and "Loot received", under nested sub-headers, quieter
 * than the block's title ({@link TitledListView#useNestedSubHeader}), closed until clicked. Its items are summed off
 * the EDT with the totals ({@link OverallTotals.Entry#getSupplies()}); here they are only named
 * ({@link ItemDetails#named}, with the names the model's {@link NameBook} has, asked for here) and shown. A grid stays
 * open or closed while the section rebuilds the same group in the same grouping; closing the section or changing the
 * grouping closes them again. EDT only.</p>
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class OverallTotalsSection
{
	/** Shown instead of the blocks with no completed task (DESIGN_PRINCIPLES.md 3.9: plain, one line). */
	static final String EMPTY_TEXT = "No completed tasks yet.";
	/** XP is every skill's (owner decision), unlike the Slayer XP/h line, which counts Slayer XP only. */
	private static final String XP_LABEL = "XP (all skills)";
	private static final String SUPPLIES_TITLE = "Supplies used";
	private static final String LOOT_TITLE = "Loot received";
	private static final String ASSIGNMENTS_TITLE = "Monsters assigned";
	/** Space between two groups' blocks (DESIGN_PRINCIPLES.md 3.3: flat rows apart by 4 to 8 px). */
	private static final int BLOCK_GAP = 8;
	/** Space above each list under a block's rows: the monsters assigned and the two grids. */
	private static final int LIST_GAP = 4;
	/** The assignment lines have no skill icons; their task icons are item sprites ({@link #icons}). */
	private static final SkillIcons NO_ICONS = (label, skill) ->
	{
	};

	private final LedgerHistoryModel model;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Draws the item grids' icons and the task icons. */
	private final ItemIcons icons;
	/** The masters' faces before By master's group names. */
	private final MasterIcons masterIcons;

	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	private final JLabel title = new JLabel("Overall totals");
	private final JLabel toggle = new JLabel();
	private final JPanel body = new JPanel();
	private final JComboBox<OverallTotals.Grouping> grouping = new JComboBox<>(OverallTotals.Grouping.values());
	private final JPanel list = new JPanel();
	private boolean expanded;
	/** The "Overall totals" setting; while off, nothing is summed, open or not. The panel hides the components. */
	private boolean shown = true;
	/** How many times the rows were built. */
	private int builds;
	/** The model's totals the rows shown were built from; {@code null} when none are. */
	private List<OverallTotals.Entry> shownEntries;
	/**
	 * The item grids shown, by grouping, group and list, with the unnamed rows they show; kept while the same groups
	 * are rebuilt, so an open grid stays open.
	 */
	private Map<String, Grid> grids = new HashMap<>();
	/** The By master assignment lists shown, by grouping and group; kept like {@link #grids}, so "+N more" stays. */
	private Map<String, ItemListView> assignmentLists = new HashMap<>();

	/** Adds the header and the body to {@code content}, collapsed. */
	void addTo(JPanel content)
	{
		// Names for tests, which find the parts by them; no visible effect.
		header.setName("totals.header");
		title.setName("totals.title");
		toggle.setName("totals.toggle");
		body.setName("totals.body");
		grouping.setName("totals.grouping");
		list.setName("totals.list");
		// A section header (DESIGN_PRINCIPLES.md 3.3).
		LedgerTheme.styleSectionHeader(header, title, toggle);
		header.add(title, BorderLayout.WEST);
		header.add(toggle, BorderLayout.EAST);
		header.setToolTipText("Completed-task totals, overall or grouped by Slayer master, month or monster.");
		MouseAdapter toggleListener = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				toggle();
			}
		};
		header.addMouseListener(toggleListener);
		title.addMouseListener(toggleListener);
		toggle.addMouseListener(toggleListener);
		SlayerLedgerPanel.addRow(content, header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(LedgerTheme.PAGE);
		JPanel groupingRow = new JPanel(new BorderLayout(6, 0));
		groupingRow.setBackground(LedgerTheme.PAGE);
		JLabel groupingLabel = LedgerTheme.label("Group", LedgerTheme.smallFont(), LedgerTheme.LABEL);
		grouping.setFocusable(false);
		grouping.addActionListener(e ->
		{
			if (expanded && shown)
			{
				buildRows();
			}
		});
		groupingRow.add(groupingLabel, BorderLayout.WEST);
		groupingRow.add(grouping, BorderLayout.CENTER);
		SlayerLedgerPanel.addRow(body, groupingRow);

		list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
		list.setBackground(LedgerTheme.PAGE);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);
		SlayerLedgerPanel.addRow(body, list);
		body.setVisible(false);
		SlayerLedgerPanel.addRow(content, body);
		rebuild();
	}

	/** Opens or closes the section. */
	void toggle()
	{
		expanded = !expanded;
		rebuild();
	}

	/**
	 * Applies the "Overall totals" setting: hidden, the section drops its rows and sums nothing; shown again, it
	 * is rebuilt from the current records at once if it was open.
	 */
	void setShown(boolean value)
	{
		if (shown != value)
		{
			shown = value;
			rebuild();
		}
	}

	/** Shows the section as it now is: when open and shown, sums the current records; otherwise drops the rows. */
	void rebuild()
	{
		toggle.setText(expanded ? "Hide" : "Show");
		body.setVisible(expanded);
		if (expanded && shown)
		{
			buildRows();
		}
		else
		{
			// Nothing is summed while collapsed or hidden; opening or showing the section sums the current records.
			list.removeAll();
			shownEntries = null;
			grids = new HashMap<>();
			assignmentLists = new HashMap<>();
		}
		relayout.run();
	}

	/**
	 * Item names or the nature rune price (the alch hint) arrived: while open and shown, the grids are named again.
	 * Only grids whose rows changed are redrawn, and the totals are not rebuilt.
	 */
	void itemNamesChanged()
	{
		if (expanded && shown && shownEntries != null)
		{
			for (Grid grid : grids.values())
			{
				grid.show();
			}
			relayout.run();
		}
	}

	/**
	 * The totals worked out off the EDT are ready (the model's {@link LedgerHistoryModel.Change#VIEWS}): while open and
	 * shown, builds the rows again if the model now has totals it does not show.
	 */
	void viewsReady()
	{
		// While views wait for today's prices what is shown stays; the end of the wait rebuilds it.
		if (expanded && shown && !model.isWaitingForCurrentPrices())
		{
			List<OverallTotals.Entry> entries = model.overallTotals(
				(OverallTotals.Grouping) grouping.getSelectedItem());
			if (entries != null && entries != shownEntries)
			{
				buildRows();
			}
		}
	}

	private void buildRows()
	{
		OverallTotals.Grouping selected = (OverallTotals.Grouping) grouping.getSelectedItem();
		List<OverallTotals.Entry> entries = model.overallTotals(selected);
		if (entries == null)
		{
			// Worked out off the EDT: the rows shown stay until it is ready (viewsReady).
			return;
		}
		builds++;
		shownEntries = entries;
		list.removeAll();
		Map<String, Grid> kept = new HashMap<>();
		Map<String, ItemListView> keptLists = new HashMap<>();
		Set<Integer> ids = new TreeSet<>();
		if (entries.isEmpty())
		{
			JLabel empty = LedgerTheme.label(EMPTY_TEXT, LedgerTheme.smallFont(), LedgerTheme.LABEL);
			// A name for tests; no visible effect.
			empty.setName("totals.empty");
			empty.setBorder(BorderFactory.createEmptyBorder(4, 0, 4, 0));
			empty.setAlignmentX(Component.LEFT_ALIGNMENT);
			list.add(empty);
		}
		else
		{
			for (int i = 0; i < entries.size(); i++)
			{
				OverallTotals.Entry entry = entries.get(i);
				String key = selected + "|" + entry.getLabel();
				JPanel block = block(entry, selected);
				JPanel items = items(entry, key, kept, ids);
				if (selected == OverallTotals.Grouping.MASTER)
				{
					// The monsters assigned come first, above the item grids.
					items.add(assignmentList(entry, key, keptLists), 0);
				}
				block.add(items);
				list.add(block);
				if (i + 1 < entries.size())
				{
					list.add(Box.createVerticalStrut(BLOCK_GAP));
				}
			}
		}
		grids = kept;
		assignmentLists = keptLists;
		if (!ids.isEmpty())
		{
			model.requestItemNames(ids);
		}
		relayout.run();
	}

	/**
	 * A group's two item grids, below its rows: the grids already shown for {@code key} if any, so an open one stays
	 * open, else new closed ones. They go into {@code kept}, and their item ids into {@code ids}.
	 */
	private JPanel items(OverallTotals.Entry entry, String key, Map<String, Grid> kept, Set<Integer> ids)
	{
		JPanel items = new JPanel();
		// A name for tests, which read the rows above it apart from it; no visible effect.
		items.setName("totals.items");
		items.setLayout(new BoxLayout(items, BoxLayout.Y_AXIS));
		items.setOpaque(false);
		items.setAlignmentX(Component.LEFT_ALIGNMENT);
		items.setBorder(BorderFactory.createEmptyBorder(2, 0, 0, 0));
		items.add(grid(key + "|supplies", "totals.supplies", SUPPLIES_TITLE, entry.getSupplies(), false, kept));
		items.add(grid(key + "|loot", "totals.loot", LOOT_TITLE, entry.getLoot(), true, kept));
		for (ItemDetails.Row row : entry.getSupplies())
		{
			ids.add(row.getItemId());
		}
		for (ItemDetails.Row row : entry.getLoot())
		{
			ids.add(row.getItemId());
		}
		return items;
	}

	/**
	 * A By master group's monsters assigned: {@code Dust devils | 12 / 80 (15%)}, most first, the top
	 * {@link ItemDetails#MAX_ROWS} until "+N more" is clicked, under a nested sub-header like the grids'. The list
	 * shown for {@code key} is kept, so its "+N more" choice stays while the same group rebuilds; it goes into
	 * {@code kept}.
	 */
	private ItemListView assignmentList(OverallTotals.Entry entry, String key, Map<String, ItemListView> kept)
	{
		ItemListView view = assignmentLists.get(key);
		if (view == null)
		{
			view = new ItemListView(ASSIGNMENTS_TITLE, false, LedgerTheme.PAGE, "monsters", NO_ICONS, icons);
			// A name for tests, which find the list by it; no visible effect.
			view.setName("totals.assignments");
			// Its lines count assignments, so the title counts nothing (only hidden rows, which it never has); quieter
			// than the block's title above it.
			view.useNestedSubHeader();
			view.setBorder(BorderFactory.createEmptyBorder(LIST_GAP, 0, 0, 0));
			view.setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		List<AssignmentLine> lines = new ArrayList<>();
		for (OverallTotals.Assignment assignment : entry.getAssignments())
		{
			lines.add(new AssignmentLine(assignment, entry.getLabel()));
		}
		view.setRows(lines);
		kept.put(key, view);
		return view;
	}

	/**
	 * The grid for {@code key}, kept from the last build or new and closed, showing {@code rows}: a nested sub-header
	 * with Show / Hide, and the live grids' stone cells on the page.
	 */
	private ItemGridView grid(String key, String name, String title, List<ItemDetails.Row> rows, boolean loot,
		Map<String, Grid> kept)
	{
		Grid grid = grids.get(key);
		if (grid == null)
		{
			ItemGridView view = new ItemGridView(title, true, LedgerTheme.PAGE, icons);
			// A name for tests, which find the grids by it; no visible effect.
			view.setName(name);
			view.useNestedSubHeader();
			view.setBorder(BorderFactory.createEmptyBorder(LIST_GAP, 0, 0, 0));
			view.setAlignmentX(Component.LEFT_ALIGNMENT);
			grid = new Grid(view, loot);
		}
		grid.rows = rows;
		grid.show();
		kept.put(key, grid);
		return grid.view;
	}

	/**
	 * One group's block: its title line (the name and the sample size), then the grouping's rows
	 * ({@link #addTotalLines}, {@link #addMonsterLines}, {@link #addMasterLines}), every block of a grouping with the
	 * same rows; the item lists are added below them. Its tooltip has the exact figures.
	 */
	private JPanel block(OverallTotals.Entry entry, OverallTotals.Grouping grouping)
	{
		JPanel block = new JPanel();
		block.setLayout(new BoxLayout(block, BoxLayout.Y_AXIS));
		block.setOpaque(false);
		block.setAlignmentX(Component.LEFT_ALIGNMENT);
		block.add(titleLine(entry, grouping));
		if (grouping == OverallTotals.Grouping.MONSTER)
		{
			addMonsterLines(block, entry);
			block.setToolTipText(monsterTooltip(entry));
		}
		else if (grouping == OverallTotals.Grouping.MASTER)
		{
			addMasterLines(block, entry);
			block.setToolTipText(masterTooltip(entry));
		}
		else
		{
			addTotalLines(block, entry);
			block.setToolTipText(tooltip(entry));
		}
		for (Component line : block.getComponents())
		{
			((JComponent) line).setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		return block;
	}

	/**
	 * A block's title line: the group's name in Bold in the heading colour, cut short with {@code …} when it doesn't fit
	 * ({@link FitLabel}; the block's tooltip has it whole), with By monster's task icon or By master's face before it;
	 * on the right the sample size, {@code 3 tasks}, whose tooltip says they are completed tasks.
	 */
	private JPanel titleLine(OverallTotals.Entry entry, OverallTotals.Grouping grouping)
	{
		FitLabel name = new FitLabel(entry.getLabel());
		// A name for tests, which read the icon and the text as shown from it; no visible effect.
		name.setName("totals.name");
		name.setFont(LedgerTheme.boldFont());
		name.setForeground(LedgerTheme.HEADING);
		if (grouping == OverallTotals.Grouping.MONSTER)
		{
			// The icon of the group's task (OverallTotals.Entry#getTask), so a Catacombs variant or cannon group
			// shows its task's, or an empty slot of the same size.
			SmallItemIcon.applyTask(icons, name, entry.getTask());
		}
		else if (grouping == OverallTotals.Grouping.MASTER)
		{
			// The master's face, or an empty slot of the same size for an unknown master or a missing image.
			name.setIconTextGap(4);
			name.setIcon(masterIcons.icon(entry.getLabel()));
		}
		JLabel count = LedgerTheme.label(SlayerLedgerPanel.sampleTasks(entry.getTaskCount()), LedgerTheme.smallFont(),
			LedgerTheme.LABEL);
		count.setVerticalAlignment(SwingConstants.BOTTOM);
		// Completed tasks, not By master's assignments.
		count.setToolTipText(completedTasks(entry.getTaskCount()));
		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setOpaque(false);
		line.add(name, BorderLayout.CENTER);
		line.add(count, BorderLayout.EAST);
		return line;
	}

	/** Overall and By month: active time, profit and XP of all skills. */
	private void addTotalLines(JPanel block, OverallTotals.Entry entry)
	{
		int tasks = entry.getTaskCount();
		addLine(block, "Active time", LedgerHistory.formatDuration(entry.getActiveMillis()), LedgerTheme.VALUE, null);
		// "Profit (GE)" / "Profit (HA)" with the Loot price mode.
		addProfitLine(block, LedgerHistory.profitName(model.lootPriceMode()), entry.getProfit(),
			entry.isProfitApproximate(), sample(entry.getProfitSampleCount(), tasks));
		addLine(block, XP_LABEL, LedgerFormat.amount(entry.getXp(), false), LedgerTheme.VALUE,
			sample(entry.getXpSampleCount(), tasks));
	}

	/**
	 * By monster: kills, average task length, average task profit, profit per kill, pace, profit per hour, then
	 * Slayer XP and Slayer XP per hour. The tasks done are the title's sample size. The averages use the tasks that
	 * recorded the figure and the rates those of them with active time, so only the totals say how many.
	 */
	private void addMonsterLines(JPanel block, OverallTotals.Entry entry)
	{
		int tasks = entry.getTaskCount();
		String profit = LedgerHistory.profitName(model.lootPriceMode());
		addLine(block, "Kills", LedgerFormat.kills(entry.getKills()), LedgerTheme.VALUE, null);
		addLine(block, "Avg task", LedgerHistory.formatDuration(entry.getAverageActiveMillis()), LedgerTheme.VALUE,
			null);
		addProfitLine(block, "Avg " + lowerFirst(profit), entry.getAverageProfit(), entry.isProfitApproximate(),
			sample(entry.getProfitSampleCount(), tasks));
		addProfitLine(block, profit + "/kill", entry.getProfitPerKill(), entry.isProfitRateApproximate(), null);
		addLine(block, "Pace", pace(entry.getMillisPerKill()), LedgerTheme.VALUE, null);
		addProfitLine(block, profit + "/h", entry.getProfitPerHour(), entry.isProfitRateApproximate(), null);
		addLine(block, "Slayer XP", LedgerFormat.amount(entry.getSlayerXp(), false), LedgerTheme.VALUE,
			sample(entry.getSlayerXpSampleCount(), tasks));
		addLine(block, "Slayer XP/h", LedgerFormat.amount(entry.getSlayerXpPerHour(), false), LedgerTheme.VALUE, null);
	}

	/**
	 * By master: average task length, average task profit, total profit, profit per hour, Slayer points (total
	 * and per task, the average without bonus tasks) and Slayer XP (total and per task). The tasks are the title's
	 * sample size; the monsters assigned are a list below the rows ({@link #assignmentList}).
	 */
	private void addMasterLines(JPanel block, OverallTotals.Entry entry)
	{
		int tasks = entry.getTaskCount();
		String profit = LedgerHistory.profitName(model.lootPriceMode());
		addLine(block, "Avg task", LedgerHistory.formatDuration(entry.getAverageActiveMillis()), LedgerTheme.VALUE,
			null);
		addProfitLine(block, "Avg " + lowerFirst(profit), entry.getAverageProfit(), entry.isProfitApproximate(), null);
		addProfitLine(block, profit, entry.getProfit(), entry.isProfitApproximate(),
			sample(entry.getProfitSampleCount(), tasks));
		addProfitLine(block, profit + "/h", entry.getProfitPerHour(), entry.isProfitRateApproximate(), null);
		addLine(block, "Points", LedgerFormat.amount(entry.getPoints(), false), LedgerTheme.VALUE,
			sample(entry.getPointsSampleCount(), tasks));
		addLine(block, "Avg points", LedgerFormat.amount(entry.getAveragePoints(), false), LedgerTheme.VALUE, null);
		addLine(block, "Slayer XP", LedgerFormat.amount(entry.getSlayerXp(), false), LedgerTheme.VALUE,
			sample(entry.getSlayerXpSampleCount(), tasks));
		addLine(block, "Avg Slayer XP", LedgerFormat.amount(entry.getAverageSlayerXp(), false), LedgerTheme.VALUE,
			null);
	}

	/** "Profit (GE)" as "profit (GE)", after "Avg". */
	private static String lowerFirst(String text)
	{
		return text.isEmpty() ? text : Character.toLowerCase(text.charAt(0)) + text.substring(1);
	}

	/** The time per kill as the live card's pace, {@code 0:18/kill}, or {@link LedgerFormat#NONE} without one. */
	private static String pace(Long millisPerKill)
	{
		return millisPerKill == null ? LedgerFormat.NONE : LedgerFormat.pace(millisPerKill);
	}

	/**
	 * The sample size of a total that only some of the group's {@code tasks} recorded, {@code 2 tasks}; {@code null}
	 * when all did, since the block's title says how many those are.
	 */
	private static String sample(int samples, int tasks)
	{
		return samples < tasks ? SlayerLedgerPanel.sampleTasks(samples) : null;
	}

	/**
	 * Adds one row to {@code block}: {@code label} in Small in the label colour on the left, then {@code sample} (if
	 * any) in the hint colour, cut short when the row has no room for it, and {@code value} right-aligned in Plain in
	 * {@code color}. Labels and values are short, so a row never widens the sidebar.
	 */
	private static void addLine(JPanel block, String label, String value, Color color, String sample)
	{
		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setOpaque(false);
		line.setBorder(BorderFactory.createEmptyBorder(1, 0, 0, 0));
		JLabel left = LedgerTheme.label(label, LedgerTheme.smallFont(), LedgerTheme.LABEL);
		left.setVerticalAlignment(SwingConstants.BOTTOM);
		line.add(left, BorderLayout.WEST);
		if (sample != null)
		{
			FitLabel samples = new FitLabel(sample);
			samples.setFont(LedgerTheme.smallFont());
			samples.setForeground(LedgerTheme.HINT);
			samples.setVerticalAlignment(SwingConstants.BOTTOM);
			line.add(samples, BorderLayout.CENTER);
		}
		JLabel right = LedgerTheme.label(value, LedgerTheme.plainFont(), color);
		right.setVerticalAlignment(SwingConstants.BOTTOM);
		line.add(right, BorderLayout.EAST);
		block.add(line);
	}

	/**
	 * A profit row: signed ({@link LedgerFormat#signed}, {@code ~} first when approximate), in the good colour for a
	 * gain and the alert colour for a loss; the sign says it too (DESIGN_PRINCIPLES.md 4.3).
	 */
	private static void addProfitLine(JPanel block, String label, Long value, boolean approximate, String sample)
	{
		addLine(block, label, LedgerFormat.signed(value, approximate), profitColor(value), sample);
	}

	/** {@link LedgerTheme#GOOD} for a gain, {@link LedgerTheme#ALERT} for a loss, the value colour otherwise. */
	private static Color profitColor(Long profit)
	{
		if (profit == null || profit == 0)
		{
			return LedgerTheme.VALUE;
		}
		return profit > 0 ? LedgerTheme.GOOD : LedgerTheme.ALERT;
	}

	/** Exact totals, the price source and how many tasks each total comes from. */
	private String tooltip(OverallTotals.Entry entry)
	{
		LootPriceMode mode = model.lootPriceMode();
		StringBuilder sb = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(entry.getLabel()));
		sb.append("<br>").append(completedTasks(entry.getTaskCount())).append(", active ")
			.append(LedgerHistory.formatDuration(entry.getActiveMillis()));

		Long profit = entry.getProfit();
		sb.append("<br>").append(LedgerHistory.escapeHtml(LedgerHistory.profitLabel(mode)))
			.append(profit == null ? "unknown" : (entry.isProfitApproximate() ? LedgerHistory.APPROXIMATE : "")
				+ LedgerHistory.escapeHtml(LedgerHistory.formatGpExact(profit)));
		sb.append("<br>").append(LedgerHistory.escapeHtml(priceSource(mode)));
		sb.append("<br>Profit from ").append(SlayerLedgerPanel.sampleTasks(entry.getProfitSampleCount()))
			.append(" with loot and supply values");

		Long xp = entry.getXp();
		sb.append("<br>").append(XP_LABEL).append(": ")
			.append(xp == null ? "unknown" : String.format("%,d", xp));
		sb.append("<br>XP from ").append(SlayerLedgerPanel.sampleTasks(entry.getXpSampleCount()))
			.append(" with recorded XP");
		if (entry.isProfitApproximate())
		{
			sb.append("<br>~ means some item prices were unavailable, or an older task kept its saved totals.");
		}
		return sb.append("</html>").toString();
	}

	/** By monster's tooltip: the exact figures, the price source and how the rates are worked out. */
	private String monsterTooltip(OverallTotals.Entry entry)
	{
		LootPriceMode mode = model.lootPriceMode();
		String profit = LedgerHistory.profitName(mode);
		StringBuilder sb = groupTooltipStart(entry);
		sb.append("<br>Kills: ").append(String.format("%,d", entry.getKills()));
		sb.append("<br>Average task: ").append(LedgerHistory.formatDuration(entry.getAverageActiveMillis()));
		sb.append("<br>Average ").append(lowerFirst(profit)).append(": ")
			.append(exactGp(entry.getAverageProfit(), entry.isProfitApproximate()));
		sb.append("<br>").append(profit).append(" per kill: ")
			.append(exactGp(entry.getProfitPerKill(), entry.isProfitRateApproximate()));
		sb.append("<br>Pace: ").append(pace(entry.getMillisPerKill()));
		sb.append("<br>").append(profit).append(" per hour: ")
			.append(exactGp(entry.getProfitPerHour(), entry.isProfitRateApproximate()));
		sb.append("<br>Slayer XP: ").append(exact(entry.getSlayerXp()))
			.append(", per hour: ").append(exact(entry.getSlayerXpPerHour()));
		appendNotes(sb, entry, mode);
		return sb.append("</html>").toString();
	}

	/** By master's tooltip: the exact figures, the price source and how many tasks each total comes from. */
	private String masterTooltip(OverallTotals.Entry entry)
	{
		LootPriceMode mode = model.lootPriceMode();
		String profit = LedgerHistory.profitName(mode);
		StringBuilder sb = groupTooltipStart(entry);
		sb.append("<br>Average task: ").append(LedgerHistory.formatDuration(entry.getAverageActiveMillis()));
		sb.append("<br>Average ").append(lowerFirst(profit)).append(": ")
			.append(exactGp(entry.getAverageProfit(), entry.isProfitApproximate()));
		sb.append("<br>").append(profit).append(": ").append(exactGp(entry.getProfit(), entry.isProfitApproximate()));
		sb.append("<br>").append(profit).append(" per hour: ")
			.append(exactGp(entry.getProfitPerHour(), entry.isProfitRateApproximate()));
		sb.append("<br>Slayer points: ").append(exact(entry.getPoints())).append(", per task: ")
			.append(exact(entry.getAveragePoints()));
		sb.append("<br>Points from ").append(SlayerLedgerPanel.sampleTasks(entry.getPointsSampleCount()))
			.append(" with recorded points (bonus tasks included)");
		sb.append("<br>Per task leaves out bonus tasks (every 10th in a streak): ")
			.append(SlayerLedgerPanel.sampleTasks(entry.getAveragePointsSampleCount()));
		sb.append("<br>Slayer XP: ").append(exact(entry.getSlayerXp())).append(", per task: ")
			.append(exact(entry.getAverageSlayerXp()));
		appendNotes(sb, entry, mode);
		int assigned = entry.getAssignmentTotal();
		sb.append("<br>Monsters assigned: ").append(assigned).append(assigned == 1 ? " assignment" : " assignments")
			.append(" (completed tasks and Skipped / blocked entries)");
		return sb.append("</html>").toString();
	}

	/** The group's name and task count, with the active time. */
	private static StringBuilder groupTooltipStart(OverallTotals.Entry entry)
	{
		StringBuilder sb = new StringBuilder("<html>").append(LedgerHistory.escapeHtml(entry.getLabel()));
		return sb.append("<br>").append(completedTasks(entry.getTaskCount())).append(", active ")
			.append(LedgerHistory.formatDuration(entry.getActiveMillis()));
	}

	/** {@code 12 completed tasks}. */
	private static String completedTasks(int tasks)
	{
		return tasks + (tasks == 1 ? " completed task" : " completed tasks");
	}

	/** Where a profit's prices come from, in the Loot price {@code mode}. */
	private static String priceSource(LootPriceMode mode)
	{
		return "Loot at " + mode + " prices minus GE-valued supplies" + (mode == LootPriceMode.HIGH_ALCH
			? " (today's available GE prices for GE-priced items)"
			: " (today's available GE prices)");
	}

	/** The price source, how many tasks the totals come from, the rate rules and the {@code ~} note. */
	private static void appendNotes(StringBuilder sb, OverallTotals.Entry entry, LootPriceMode mode)
	{
		sb.append("<br>").append(LedgerHistory.escapeHtml(priceSource(mode)));
		sb.append("<br>Profit from ").append(SlayerLedgerPanel.sampleTasks(entry.getProfitSampleCount()))
			.append(" with loot and supply values, Slayer XP from ")
			.append(SlayerLedgerPanel.sampleTasks(entry.getSlayerXpSampleCount())).append(" with recorded XP");
		sb.append("<br>Averages use those tasks; rates pool those of them with active time,")
			.append(" and hourly rates need 1 minute of it.");
		if (entry.isProfitApproximate())
		{
			sb.append("<br>~ means some item prices were unavailable, or an older task kept its saved totals.");
		}
	}

	/** An exact gp amount for a tooltip, {@code ~} when approximate, or "-". */
	private static String exactGp(Long value, boolean approximate)
	{
		return value == null ? LedgerHistory.NO_VALUE : (approximate ? LedgerHistory.APPROXIMATE : "")
			+ LedgerHistory.escapeHtml(LedgerHistory.formatGpExact(value));
	}

	/** An exact count for a tooltip, or "-". */
	private static String exact(Long value)
	{
		return value == null ? LedgerHistory.NO_VALUE : String.format("%,d", value);
	}

	/** How many times the rows were built. Performance seam: tests assert this doesn't grow on the refresh timer. */
	int getBuildCount()
	{
		return builds;
	}

	/**
	 * One line of a By master group's monsters assigned ({@link OverallTotals.Assignment}); equal when its assignment
	 * and master are, so an unchanged list is not redrawn.
	 */
	@EqualsAndHashCode
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class AssignmentLine implements ItemListView.Line
	{
		private final OverallTotals.Assignment assignment;
		private final String master;

		@Override
		public String getName()
		{
			return assignment.getName();
		}

		@Override
		public String getSkill()
		{
			return null;
		}

		/** The task's icon, or {@code null} for a name that is no known task (an empty slot). */
		@Override
		public Integer getIconItemId()
		{
			return TaskIcons.itemId(assignment.getName());
		}

		@Override
		public String amountText()
		{
			return assignment.text();
		}

		@Override
		public String tooltip()
		{
			return assignment.tooltip(master);
		}
	}

	/** One item grid and the unnamed rows it shows. */
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	private final class Grid
	{
		private final ItemGridView view;
		/** Whether the rows are loot, which can have the alch hint. */
		private final boolean loot;
		/** Unnamed rows ({@link OverallTotals.Entry#getSupplies()} or {@link OverallTotals.Entry#getLoot()}). */
		private List<ItemDetails.Row> rows;

		/**
		 * Names the rows with what the model knows and shows them, loot without the items Ground Items hides;
		 * nothing is redrawn when they are unchanged.
		 */
		private void show()
		{
			view.setRows(ItemDetails.named(rows, model::itemName, model.natureRunePrice(), loot),
				loot ? model.hiddenLoot() : HiddenLoot.NONE);
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;

/**
 * Works out the overlay's {@link OverlayRows.Snapshot} once per settled tick, so that drawing a frame computes
 * nothing: the task's name with its variant and cannon, its icon, the spot's short name, the setup tag sprites, the
 * session's superiors and XP, the supply runway ({@link SupplyRunway}) and the superior moment line. It reads only the
 * pure {@link SessionTracker} and what the plugin hands it, so it is tested without a client. Client thread only: the
 * plugin calls {@link #update} at the end of each settled tick and publishes the result in a volatile field.
 *
 * <p>Kept between ticks: the superiors seen per session, so the moment line shows for {@link #MOMENT_TICKS} ticks
 * (about 10 seconds) after the count goes up (the plugin's superior detection, {@link SuperiorSpawnMessage}); the
 * supplies carried earlier in the session, so one that runs out keeps its runway at none
 * ({@link SupplyRunway#withRunOut}); what the supply counting left out since the last snapshot
 * ({@link #suppliesLeftOut}); and the history's supplies per kill by supply key, worked out again only when another
 * history figure is published for the session ({@link OverlayRows.HistoricalPace}). All of it is forgotten while the
 * overlay is off ({@link #reset}), so turning it back on shows no moment for superiors that came before.</p>
 *
 * <p>Only a fall to none that was counted as use runs a supply out. After a tick the supply counting left out as a
 * whole (the bank, a deposit box or another interface that moves items, a rune pouch dropped, a death) the supplies
 * carried earlier are exactly those carried after it, so a supply banked on purpose is forgotten, not run out. After
 * a tick that left only some items out (dropped, stored in the master scroll book, loaded into or emptied from a
 * charged weapon) only their supplies are, so dropping the vial of the last prayer dose leaves prayer run out.</p>
 */
final class OverlayFeed
{
	/** How long the superior moment line shows: 17 ticks, about 10 seconds. */
	static final int MOMENT_TICKS = 17;
	private static final int NO_TICK = Integer.MIN_VALUE;

	/** The session whose superiors {@link #superiorsSeen} counts, or {@code null}. */
	private String momentSession;
	private int superiorsSeen;
	/** The tick the latest moment started on, or {@link #NO_TICK}. */
	private int momentFrom = NO_TICK;
	/** Which of its session's superiors the latest moment is about. */
	private int momentNumber;

	/** The session whose supplies {@link #carriedEarlier} holds, or {@code null}. */
	private String runwaySession;
	/** Each supply carried earlier in {@link #runwaySession}, as last carried, by supply key. */
	private final Map<String, SupplyRunway.Supply> carriedEarlier = new TreeMap<>();
	/** The supply keys carried at the last update: only these can leave on the next tick. */
	private final Set<String> carriedLast = new HashSet<>();
	/** Whether the supply counting left a whole tick out since the last {@link #update}. */
	private boolean tickLeftOut;
	/** Items whose changes the supply counting left out since the last {@link #update}. */
	private final Set<Integer> itemsLeftOut = new HashSet<>();

	/** The history figures {@link #historyByKey} was worked out from, or {@code null}. */
	private OverlayRows.HistoricalPace keyedPace;
	private Map<String, Double> historyByKey = Collections.emptyMap();

	/**
	 * Forgets the moment, the supplies carried earlier and the cached history figures: at the plugin's start, and on
	 * each tick while the overlay is off.
	 */
	void reset()
	{
		momentSession = null;
		superiorsSeen = 0;
		momentFrom = NO_TICK;
		momentNumber = 0;
		runwaySession = null;
		carriedEarlier.clear();
		carriedLast.clear();
		tickLeftOut = false;
		itemsLeftOut.clear();
		keyedPace = null;
		historyByKey = Collections.emptyMap();
	}

	/**
	 * What the supply counting left out on a tick, from the plugin's supplies diff on every tick (also those that make
	 * no snapshot, the login's settle ticks, say), kept until the next {@link #update}: a fall to none then is no
	 * run-out.
	 *
	 * @param wholeTick whether nothing was counted on the tick ({@link SupplyExclusions#isTickExcluded}: an
	 *                  interface that moves items, such as the bank or a deposit box, a rune pouch dropped, a death)
	 * @param itemIds   items whose changes were left out on their own ({@link SupplyExclusions#droppedItems},
	 *                  {@link ChargeExclusions#excludedItems}); {@code null} for none
	 */
	void suppliesLeftOut(boolean wholeTick, Collection<Integer> itemIds)
	{
		tickLeftOut |= wholeTick;
		if (itemIds != null)
		{
			itemsLeftOut.addAll(itemIds);
		}
	}

	/**
	 * The snapshot for this tick: a session's, or an assignment's waiting for its first kill or Ended (identity, size
	 * and kills left only); {@code null} with neither. First forgets the supplies whose fall the supply counting left
	 * out since the last update ({@link #suppliesLeftOut}), with or without a session.
	 *
	 * @param spots       the bundled spot table
	 * @param regionNames the player's names for map regions, for an unlisted region's spot ({@code null} for none)
	 * @param carried     what is carried now ({@link SupplyRunway#carrying}, with the blowpipe's contents), or
	 *                    {@link SupplyRunway.Carrying#UNSEEN}
	 * @param keyOf       an item's supply key ({@link SupplyTracker#supplyKey})
	 * @param pace        the history figures last published, or {@code null}
	 * @param tick        this tick's count
	 */
	OverlayRows.Snapshot update(SessionTracker tracker, SlayerSpots spots, IntFunction<String> regionNames,
		SupplyRunway.Carrying carried, IntFunction<String> keyOf, OverlayRows.HistoricalPace pace, int tick)
	{
		forgetLeftOut(keyOf);
		final SessionTracker.LiveTask live = tracker.liveTask();
		if (live == null)
		{
			final SessionTracker.Status status = tracker.getStatus();
			if (status != SessionTracker.Status.WAITING_FOR_FIRST_KILL && status != SessionTracker.Status.ENDED)
			{
				return null;
			}
			final String monster = tracker.getCurrentMonster();
			return OverlayRows.Snapshot.builder()
				.taskName(monster == null ? null : LedgerRecord.displayName(monster, tracker.getCurrentCreatureId()))
				.iconItemId(TaskIcons.itemId(monster))
				.spotName(areaSpot(spots, tracker.getCurrentContext().getLocation()))
				.assigned(tracker.getCurrentOriginalAmount())
				.remaining(tracker.getCurrentRemaining())
				.caveTask(TaskCaves.isCaveTask(monster))
				.build();
		}

		final String monster = live.getMonster();
		final TaskSelection selection = tracker.getCurrentTaskSelection().forTask(monster);
		final TaskVariants.Decision variant = tracker.getCurrentVariant().forTask(monster);
		final TaskSpot spot = tracker.getTaskSpot();
		final String spotName = spot.getSpotId() != null
			? TaskPlanText.shortSpotName(spot.getSpotId(), spots, regionNames)
			: areaSpot(spots, tracker.getSessionTaskLocation());
		final int superiors = tracker.getSuperiorsSpawned();
		final int remaining = live.getRemaining();
		return OverlayRows.Snapshot.builder()
			.sessionId(live.getSessionId())
			.taskName(monster == null ? null : OverlayRows.taskName(monster, live.getCreatureId(), selection, variant))
			.iconItemId(TaskIcons.itemId(monster))
			.spotName(spotName)
			.tags(SetupTagIcons.of(tracker.getSetupTags()))
			// The kills left are known only while the session is on the observed task, whose size this is.
			.assigned(remaining > 0 ? tracker.getCurrentOriginalAmount() : OverlayRows.UNKNOWN)
			.superiors(superiors)
			.xp(SkillXp.total(tracker.getXpGained()))
			.runway(runway(tracker, live, carried, keyOf, pace))
			.moment(moment(live.getSessionId(), superiors, tick))
			.caveTask(TaskCaves.isCaveTask(monster))
			.build();
	}

	/** The short name of the spot an assigned area (Konar's) names, or {@code null}. */
	private static String areaSpot(SlayerSpots spots, String area)
	{
		final String key = spots == null || area == null ? null : spots.spotNamed(area);
		return key == null ? null : spots.shortName(key);
	}

	/**
	 * Forgets the supplies carried earlier whose fall the supply counting left out since the last update
	 * ({@link #suppliesLeftOut}): all of them after a tick left out as a whole, else those of the items left out
	 * ({@code keyOf}: an item's supply key) that were carried at the last update. An item left out that wasn't carried
	 * then didn't leave (a charge window lists every material it could touch), so a supply that ran out earlier stays
	 * run out. The runway then remembers what is carried now, so after a tick left out as
	 * a whole the supplies carried earlier are exactly those carried after it.
	 */
	private void forgetLeftOut(IntFunction<String> keyOf)
	{
		if (tickLeftOut)
		{
			carriedEarlier.clear();
		}
		else if (keyOf != null)
		{
			for (Integer itemId : itemsLeftOut)
			{
				final String key = itemId == null ? null : keyOf.apply(itemId);
				if (key != null && carriedLast.contains(key))
				{
					carriedEarlier.remove(key);
				}
			}
		}
		tickLeftOut = false;
		itemsLeftOut.clear();
	}

	/**
	 * The runway for the session ({@link SupplyRunway#scarcest}), or {@code null}: what is carried now, with the
	 * supplies carried earlier in the session that ran out ({@link SupplyRunway#withRunOut}).
	 */
	private SupplyRunway.Warning runway(SessionTracker tracker, SessionTracker.LiveTask live,
		SupplyRunway.Carrying carried, IntFunction<String> keyOf, OverlayRows.HistoricalPace pace)
	{
		final SupplyRunway.Carrying now = carried == null ? SupplyRunway.Carrying.UNSEEN : carried;
		if (!Objects.equals(live.getSessionId(), runwaySession))
		{
			runwaySession = live.getSessionId();
			carriedEarlier.clear();
		}
		final List<SupplyRunway.Supply> supplies = SupplyRunway.withRunOut(now, carriedEarlier.values());
		carriedLast.clear();
		for (SupplyRunway.Supply supply : now.getSupplies())
		{
			if (supply.getAmount() > 0)
			{
				carriedEarlier.put(supply.getKey(), supply);
				carriedLast.add(supply.getKey());
			}
		}
		final int remaining = live.getRemaining();
		if (remaining <= 0 || supplies.isEmpty() || keyOf == null)
		{
			return null;
		}
		final int kills = live.getKills();
		// Only the rate the rule uses is worked out.
		if (kills >= SupplyRunway.MIN_TASK_KILLS)
		{
			final Map<String, Long> used = SupplyRunway.byKey(tracker.getSupplies().toMap(), keyOf);
			return SupplyRunway.scarcest(supplies, used, kills, Collections.emptyMap(), remaining);
		}
		return SupplyRunway.scarcest(supplies, Collections.emptyMap(), kills, history(live, pace, keyOf), remaining);
	}

	/** The history's supplies per kill by supply key, for {@code live}'s session; cached per published figures. */
	private Map<String, Double> history(SessionTracker.LiveTask live, OverlayRows.HistoricalPace pace,
		IntFunction<String> keyOf)
	{
		if (pace == null || !pace.belongsTo(live))
		{
			return Collections.emptyMap();
		}
		// The model publishes new figures after each kill; equal ones are not keyed again.
		if (!pace.equals(keyedPace))
		{
			keyedPace = pace;
			historyByKey = SupplyRunway.perKillByKey(pace.getSuppliesPerKill(), keyOf);
		}
		return historyByKey;
	}

	/**
	 * The moment line while it shows: {@link #MOMENT_TICKS} ticks from the tick the session's superior count went up.
	 * A session first seen with superiors already counted (restored, say) shows none for them.
	 */
	private String moment(String sessionId, int superiors, int tick)
	{
		if (sessionId == null || !sessionId.equals(momentSession))
		{
			momentSession = sessionId;
			superiorsSeen = superiors;
			momentFrom = NO_TICK;
		}
		else if (superiors > superiorsSeen)
		{
			superiorsSeen = superiors;
			momentNumber = superiors;
			momentFrom = tick;
		}
		else
		{
			superiorsSeen = superiors;
		}
		return momentFrom != NO_TICK && tick >= momentFrom && tick - momentFrom < MOMENT_TICKS
			? OverlayRows.momentText(momentNumber) : null;
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.util.*;
import java.util.List;
import lombok.*;
import net.runelite.client.ui.overlay.components.*;
import net.runelite.client.ui.overlay.components.TextComponent;

/**
 * One overlay line of text with small images beside it, which no RuneLite component draws (DESIGN_PRINCIPLES.md 2: own
 * drawing only where no component can do the job): the runway's supply icon before its text, and the identity's
 * second line, the spot's short name with the setup tag sprites after it. The text goes through RuneLite's
 * {@link TextComponent}, so it has the same 1 px black shadow as every other overlay line, at the same baseline as a
 * {@code LineComponent} of the same font. Each image is scaled into its box, keeping its shape, and centred on the
 * line. The caller cuts the text to fit ({@link OverlayRows#fitted}).
 */
final class OverlayIconLine implements LayoutableRenderableEntity
{
	private final String text;
	private final Color color;
	/** The text's font, or {@code null} for the overlay's. */
	private final Font font;
	private final Image leading;
	private final int leadingWidth;
	private final int leadingHeight;
	private final List<Image> trailing;
	private final int trailingSize;

	@Getter
	private final Rectangle bounds = new Rectangle();
	@Setter
	private Point preferredLocation = new Point();
	@Setter
	private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 0);

	private OverlayIconLine(String text, Color color, Font font, Image leading, int leadingWidth, int leadingHeight,
		List<Image> trailing, int trailingSize)
	{
		this.text = text == null ? "" : text;
		this.color = color;
		this.font = font;
		this.leading = leading;
		this.leadingWidth = leadingWidth;
		this.leadingHeight = leadingHeight;
		this.trailing = trailing;
		this.trailingSize = trailingSize;
	}

	/** An icon in a {@code width} by {@code height} box, then the text (the runway). */
	static OverlayIconLine leading(Image icon, int width, int height, String text, Color color, Font font)
	{
		return new OverlayIconLine(text, color, font, icon, width, height, Collections.emptyList(), 0);
	}

	/** The text, then the images, each in a {@code size} square box (the identity's spot and tags). */
	static OverlayIconLine trailing(String text, Color color, List<Image> images, int size)
	{
		return new OverlayIconLine(text, color, null, null, 0, 0, new ArrayList<>(images), size);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final Font textFont = font != null ? font : graphics.getFont();
		final FontMetrics metrics = graphics.getFontMetrics(textFont);
		final int textHeight = metrics.getHeight();
		final int imageHeight = Math.max(leading != null ? leadingHeight : 0, trailing.isEmpty() ? 0 : trailingSize);
		final int height = Math.max(textHeight, imageHeight);
		int x = preferredLocation.x;
		final int y = preferredLocation.y;

		final Object interpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		try
		{
			if (leading != null)
			{
				drawFitted(graphics, leading, x, y + (height - leadingHeight) / 2, leadingWidth, leadingHeight);
				x += leadingWidth + OverlayRows.TEXT_ICON_GAP;
			}
			if (!text.isEmpty())
			{
				final TextComponent component = new TextComponent();
				// As LineComponent draws it: the baseline a font height below the line's top.
				component.setPosition(x, y + (height - textHeight) / 2 + textHeight);
				component.setText(text);
				component.setColor(color);
				component.setFont(textFont);
				component.render(graphics);
				x += metrics.stringWidth(text) + OverlayRows.TEXT_ICON_GAP;
			}
			for (Image image : trailing)
			{
				drawFitted(graphics, image, x, y + (height - trailingSize) / 2, trailingSize, trailingSize);
				x += trailingSize + OverlayRows.TAG_GAP;
			}
		}
		finally
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
				interpolation != null ? interpolation : RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		}

		final Dimension dimension = new Dimension(preferredSize.width, height);
		bounds.setLocation(preferredLocation);
		bounds.setSize(dimension);
		return dimension;
	}

	/** Draws {@code image} scaled into the {@code width} by {@code height} box, keeping its shape, centred in it. */
	private static void drawFitted(Graphics2D graphics, Image image, int x, int y, int width, int height)
	{
		final int imageWidth = image.getWidth(null);
		final int imageHeight = image.getHeight(null);
		if (imageWidth <= 0 || imageHeight <= 0)
		{
			return;
		}
		final double scale = Math.min(width / (double) imageWidth, height / (double) imageHeight);
		final int drawWidth = Math.max(1, (int) Math.round(imageWidth * scale));
		final int drawHeight = Math.max(1, (int) Math.round(imageHeight * scale));
		graphics.drawImage(image, x + (width - drawWidth) / 2, y + (height - drawHeight) / 2, drawWidth, drawHeight,
			null);
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.util.*;
import java.util.List;
import lombok.*;

/**
 * The task overlay's rows (DESIGN_PRINCIPLES.md section 2, V2 plan 7), in their fixed order:
 * <ol>
 * <li>the state line, whenever time isn't running (no setting turns it off): {@code Away} / {@code Back on your next
 * kill}, {@code Paused} / {@code Resume in sidebar}, {@code Ended} / {@code See sidebar}; on a Jad or Zuk task
 * ({@link #stateRow}) {@code Away} / {@code Back when you go in} after leaving the Fight Caves or the Inferno, and
 * {@code Waiting} / {@code Go in to start} or {@code Go in to resume};</li>
 * <li>the identity: the task's icon beside its name and a line with the spot's short name and the setup tag sprites
 * (Progress and identity);</li>
 * <li>the bar, labelled {@code 73 / 201} (Progress and identity; only with the task's size known);</li>
 * <li>{@code 128 left} / {@code ~38 min}, or with the kills left unknown {@code 73 killed} / {@code ? left} (Progress
 * and identity);</li>
 * <li>{@code 0:18/kill} / {@code 200/h} (Pace; once the pace is known);</li>
 * <li>{@code 21:54 elapsed} (Pace) / {@code 1 superior} (Haul);</li>
 * <li>{@code +212K} / {@code 58.6K XP} (Haul; once the live values are loaded);</li>
 * <li>the supply runway, {@code Prayer: ~40 kills} or critical {@code Prayer: 6 left} (Supply runway), or else the
 * superior moment line for about 10 s (Haul): at most one of the two, the runway first.</li>
 * </ol>
 * A line that pairs two groups shows only the enabled one's value, in its place. Rows 4 to 8 need a session; without
 * one an assigned task shows only its state, identity and bar.
 *
 * <p>Pure: no client, so every row is unit-tested. The plugin builds a {@link Snapshot} once per tick (the identity, the
 * superiors, XP, the runway and the moment) and the overlay joins it with the live task every frame ({@link Data}); the
 * rows are text, worked out with {@link LedgerFormat}'s number rules, the same as the sidebar's. {@link #fitted} cuts
 * the text to the overlay's width with the live {@link FontMetrics}, so nothing wraps.</p>
 */
final class OverlayRows
{
	/** Shown instead of the kills left while they are not known (see {@link SessionTracker#liveTask()}). */
	static final String UNKNOWN_REMAINING = LedgerFormat.UNKNOWN;
	/** The state line's hint on a Jad or Zuk task while Away, until the player goes in again. */
	static final String CAVE_HINT = "Back when you go in";
	/**
	 * The state line's label on a Jad or Zuk task while it waits for its first or next kill: short, so that the hint
	 * beside it fits 152 px (DESIGN_PRINCIPLES.md 2.2).
	 */
	static final String CAVE_WAITING = "Waiting";
	/** The hint beside {@link #CAVE_WAITING} while a Jad or Zuk task waits for its first kill: going in starts it. */
	static final String CAVE_START_HINT = "Go in to start";
	/** The hint beside {@link #CAVE_WAITING} while a Jad or Zuk task waits for its next kill: going in restarts it. */
	static final String CAVE_RESUME_HINT = "Go in to resume";
	/** Marks text cut short to fit: names, the spot, the state hint, the runway and the moment, never a value. */
	static final String ELLIPSIS = "…";
	/** The words the runway drops first when its line doesn't fit. */
	static final String KILLS_WORD = " kills";
	/** The unit word the elapsed value drops when its line doesn't fit ({@link #unitWord}). */
	static final String ELAPSED_WORD = " elapsed";
	/** The unit word the kills left drop when their line doesn't fit. */
	static final String LEFT_WORD = " left";
	/** The unit word the kills done (with the kills left unknown) drop when their line doesn't fit. */
	static final String KILLED_WORD = " killed";
	/** The unit word the time left drops when its line doesn't fit: {@code ~5 h 12}. */
	static final String MIN_WORD = " min";
	/** The unit word the pace drops when its line doesn't fit: {@code 0:18}. */
	static final String PER_KILL_WORD = "/kill";
	/** A kills count, value or size not known. */
	static final int UNKNOWN = -1;

	/** The task icon: an item sprite, 36 by 32. */
	static final int ICON_WIDTH = 36;
	static final int ICON_HEIGHT = 32;
	/** Between the task icon and its two lines. */
	static final int ICON_GAP = 4;
	/** The runway's supply icon: the item sprite at half size. */
	static final int SMALL_ICON_WIDTH = 18;
	static final int SMALL_ICON_HEIGHT = 16;
	/** A setup tag sprite's box on the identity's second line. */
	static final int TAG_SIZE = 16;
	/** Between two tag sprites. */
	static final int TAG_GAP = 2;
	/** Between text and the icons beside it. */
	static final int TEXT_ICON_GAP = 3;

	private OverlayRows()
	{
	}

	/** Which row a {@link Row} is, top to bottom. */
	enum Kind
	{
		STATE,
		IDENTITY,
		BAR,
		PROGRESS,
		PACE,
		ELAPSED,
		HAUL,
		RUNWAY,
		MOMENT
	}

	/** What colour a text is drawn in: the overlay maps each to a {@link LedgerTheme} token. */
	enum Tone
	{
		/** White ({@link LedgerTheme#VALUE}). */
		VALUE,
		/** The game's yellow ({@link LedgerTheme#ALERT}): states, the runway and a loss. */
		ALERT,
		/** The game's orange ({@link LedgerTheme#HEADING}): the task's name. */
		NAME,
		/** The light green ({@link LedgerTheme#GOOD}): a profit. */
		GOOD
	}

	/** The overlay's four row groups (V2 plan 2.1, 7), each with its own setting. Immutable. */
	@Value
	static class Groups
	{
		/** Every group on: the default. */
		static final Groups ALL = new Groups(true, true, true, true);
		/** Every group off: only the state line is left. */
		static final Groups NONE = new Groups(false, false, false, false);

		/** The identity, the bar, and the kills left and time left. */
		boolean progress;
		/** The pace and kills per hour, and the elapsed time. */
		boolean pace;
		/** The superiors, profit, XP and the superior moment line. */
		boolean haul;
		/** The supply runway. */
		boolean runway;
	}

	/**
	 * What the plugin works out for the overlay once per settled tick ({@link OverlayFeed}), so that drawing a frame
	 * computes nothing: the identity, the session's superiors and XP, the supply runway and the superior moment. For an
	 * assignment with no session ({@link #getSessionId} {@code null}) only the identity, its size and kills left.
	 * Immutable.
	 */
	@Value
	@Builder
	static class Snapshot
	{
		/** The session it belongs to, or {@code null} for the assignment without a session. */
		String sessionId;
		/** The task's name as the sidebar shows it ({@link #taskName}), or {@code null} while unknown. */
		String taskName;
		/** The task icon's item ({@link TaskIcons}), or {@code null} for none. */
		Integer iconItemId;
		/** The spot's short name ({@link SlayerSpots#shortName}), or {@code null} while unknown. */
		String spotName;
		/** The setup tag sprites ({@link SetupTagIcons}). */
		@Builder.Default
		List<SetupTagIcons.Icon> tags = Collections.emptyList();
		/** The task's assigned size, or {@link #UNKNOWN}. */
		@Builder.Default
		int assigned = UNKNOWN;
		/** The kills left, for the assignment without a session (a session's are read live), or {@link #UNKNOWN}. */
		@Builder.Default
		int remaining = UNKNOWN;
		/** The session's superiors so far. */
		int superiors;
		/** The session's XP so far, all skills. */
		long xp;
		/** The supply runway to show, or {@code null}. */
		SupplyRunway.Warning runway;
		/** The superior moment line while it shows, or {@code null}. */
		String moment;
		/** Whether the task is a Jad or Zuk task ({@link TaskCaves#isCaveTask}). */
		boolean caveTask;
	}

	/**
	 * What one frame shows: the live task (status, kills, active time and kills left, read every frame so the clock and
	 * a Pause are current), with the tick's {@link Snapshot}, the live values and the historical time per kill, each
	 * only when it belongs to the same session (the plugin checks); or, with no session, the state of an assignment
	 * waiting for its first kill or Ended ({@link #stateOnly}).
	 */
	@Getter
	static final class Data
	{
		/** What tracking is doing ({@link SessionTracker#getStatus()}); never {@code null}. */
		private final SessionTracker.Status status;
		/** The active session's task, or {@code null} for {@link #stateOnly}. */
		private final SessionTracker.LiveTask task;
		/** The tick's snapshot, or {@code null}. */
		private final Snapshot snapshot;
		/** The session's live values, or {@code null}. */
		private final SessionValuation.Values values;
		/** The historical time per kill for the time left, or {@code null} when there is none. */
		private final Long historicalMillisPerKill;

		/**
		 * @param task                    the active session's task (not {@code null})
		 * @param snapshot                the same session's tick snapshot, or {@code null} before its first
		 * @param values                  the same session's live values, or {@code null} when none are known yet
		 * @param historicalMillisPerKill the same session's task's historical time per kill, as the sidebar uses it
		 *                                ({@link HistoricalPace}), or {@code null} when it has no history
		 */
		Data(SessionTracker.LiveTask task, Snapshot snapshot, SessionValuation.Values values,
			Long historicalMillisPerKill)
		{
			this.status = task.getStatus();
			this.task = task;
			this.snapshot = snapshot;
			this.values = values;
			this.historicalMillisPerKill = historicalMillisPerKill;
		}

		private Data(SessionTracker.Status status, Snapshot snapshot)
		{
			this.status = status;
			this.task = null;
			this.snapshot = snapshot;
			this.values = null;
			this.historicalMillisPerKill = null;
		}

		/**
		 * The state line, with the assignment's identity and bar from {@code snapshot} (or {@code null} before the first
		 * tick's), for an assignment with no session: waiting for its first kill, or Ended
		 * ({@link SessionTracker#getStatus()}).
		 */
		static Data stateOnly(SessionTracker.Status status, Snapshot snapshot)
		{
			return new Data(status, snapshot);
		}

		/**
		 * The task's name: the snapshot's (with its variant and cannon, {@link #taskName}), else the session's task
		 * name alone; {@code null} when neither is known.
		 */
		String getTaskName()
		{
			if (snapshot != null && snapshot.getTaskName() != null)
			{
				return snapshot.getTaskName();
			}
			return task == null || task.getMonster() == null ? null
				: LedgerRecord.displayName(task.getMonster(), task.getCreatureId());
		}

		/** The task icon's item: the snapshot's, else the session task's ({@link TaskIcons}); {@code null} for none. */
		Integer getIconItemId()
		{
			if (snapshot != null)
			{
				return snapshot.getIconItemId();
			}
			return task == null ? null : TaskIcons.itemId(task.getMonster());
		}

		/** The kills left: the live task's, else the assignment's from the snapshot; {@link #UNKNOWN} when not known. */
		int getRemaining()
		{
			if (task != null)
			{
				return task.getRemaining() > 0 ? task.getRemaining() : UNKNOWN;
			}
			return snapshot == null || snapshot.getRemaining() <= 0 ? UNKNOWN : snapshot.getRemaining();
		}
	}

	/**
	 * The history's figures the overlay uses for a session's task (and location) until the session's own take over: the
	 * time per kill ({@link LedgerFormat#timeLeft}) and the supplies per kill ({@link SupplyRunway}).
	 * {@link LedgerHistoryModel} works them out from the history on the EDT and publishes them; the plugin reads them on
	 * the client thread and uses them only for the same session. Immutable.
	 */
	@Getter
	@EqualsAndHashCode
	static final class HistoricalPace
	{
		private final String sessionId;
		private final long millisPerKill;
		/** Each supply's use per kill in the history, by item id; empty for none. */
		private final Map<Integer, Double> suppliesPerKill;

		/**
		 * @param suppliesPerKill each supply's use per kill (item id to doses, bites or items:
		 *                        {@link TaskStatistics#getSuppliesPerKill}), or {@code null} for none
		 */
		HistoricalPace(String sessionId, long millisPerKill, Map<Integer, Double> suppliesPerKill)
		{
			this.sessionId = sessionId;
			this.millisPerKill = millisPerKill;
			this.suppliesPerKill = suppliesPerKill == null || suppliesPerKill.isEmpty() ? Collections.emptyMap()
				: Collections.unmodifiableMap(new TreeMap<>(suppliesPerKill));
		}

		/** Whether this belongs to {@code task}'s session. */
		boolean belongsTo(SessionTracker.LiveTask task)
		{
			return task != null && sessionId != null && sessionId.equals(task.getSessionId());
		}

		/** The time per kill when this pace belongs to {@code task}'s session, else {@code null}. */
		Long millisPerKillFor(SessionTracker.LiveTask task)
		{
			return belongsTo(task) ? millisPerKill : null;
		}
	}

	/**
	 * One overlay row: text on the left and right, their tones, and per kind the task icon, the identity's second line
	 * and tags, the bar's numbers or the runway. Immutable.
	 */
	static final class Row
	{
		@Getter
		private final Kind kind;
		/** The left text: the state, the task name, the bar label, a value or the runway's and moment's line. */
		@Getter
		private final String left;
		/** The right text (empty for none): the state's hint or a value. */
		@Getter
		private final String right;
		@Getter
		private final Tone leftTone;
		@Getter
		private final Tone rightTone;
		/**
		 * Whether the left text is the key number ({@code 128 left}), Bold while the overlay font is the default
		 * Plain.
		 */
		@Getter
		private final boolean key;
		/** The identity's task icon or the runway's supply icon, or {@code null}. */
		@Getter
		private final Integer iconItemId;
		private final String second;
		/** The identity's setup tag sprites. */
		@Getter
		private final List<SetupTagIcons.Icon> tags;
		/** The bar's kills done. */
		@Getter
		private final int done;
		/** The bar's task size. */
		@Getter
		private final int total;
		/** The runway this row shows, or {@code null}. */
		@Getter
		private final SupplyRunway.Warning runway;

		private Row(Kind kind, String left, String right, Tone leftTone, Tone rightTone, boolean key,
			Details details)
		{
			this.kind = kind;
			this.left = left == null ? "" : left;
			this.right = right == null ? "" : right;
			this.leftTone = leftTone;
			this.rightTone = rightTone;
			this.key = key;
			this.iconItemId = details.iconItemId;
			this.second = details.second;
			this.tags = details.tags;
			this.done = details.done;
			this.total = details.total;
			this.runway = details.runway;
		}

		/** A row's kind-specific parts, so the constructor stays short. */
		private static final class Details
		{
			static final Details NONE = new Details(null, null, Collections.emptyList(), 0, 0, null);

			final Integer iconItemId;
			final String second;
			final List<SetupTagIcons.Icon> tags;
			final int done;
			final int total;
			final SupplyRunway.Warning runway;

			Details(Integer iconItemId, String second, List<SetupTagIcons.Icon> tags, int done, int total,
				SupplyRunway.Warning runway)
			{
				this.iconItemId = iconItemId;
				this.second = second;
				this.tags = tags == null ? Collections.emptyList() : tags;
				this.done = done;
				this.total = total;
				this.runway = runway;
			}
		}

		static Row line(Kind kind, String left, String right)
		{
			return new Row(kind, left, right, Tone.VALUE, Tone.VALUE, false, Details.NONE);
		}

		/** The text, cut to fit by {@link #fitted}. */
		private Row withText(String newLeft, String newRight, String newSecond)
		{
			return new Row(kind, newLeft, newRight, leftTone, rightTone, key,
				new Details(iconItemId, newSecond, tags, done, total, runway));
		}

		private Row withTones(Tone newLeft, Tone newRight)
		{
			return new Row(kind, left, right, newLeft, newRight, key,
				new Details(iconItemId, second, tags, done, total, runway));
		}

		/** Whether the row is drawn in Bold while the overlay font is Plain: the key number, a critical runway. */
		boolean isBold()
		{
			return key || (runway != null && runway.isCritical());
		}

		/** The identity's second line: the spot's short name (may be empty). */
		String getSecond()
		{
			return second == null ? "" : second;
		}

		@Override
		public String toString()
		{
			return kind + ": " + left + (right.isEmpty() ? "" : " / " + right)
				+ (getSecond().isEmpty() ? "" : " | " + getSecond());
		}
	}

	/**
	 * The state line for {@code status}: its label and hint, in the alert colour; {@code null} while time is running (or
	 * there is no task). On a Jad or Zuk task ({@code caveTask}) the session starts or restarts when the player goes in
	 * (V2 plan 4.1), so Away says {@link #CAVE_HINT}, and the waiting states read {@link #CAVE_WAITING} with
	 * {@link #CAVE_START_HINT} (the first kill) or {@link #CAVE_RESUME_HINT} (the next).
	 */
	static Row stateRow(SessionTracker.Status status, boolean caveTask)
	{
		if (status == null || !status.hasStateLine())
		{
			return null;
		}
		String label = status.getLabel();
		String hint = status.getHint();
		if (caveTask)
		{
			switch (status)
			{
				case AWAY:
					hint = CAVE_HINT;
					break;
				case WAITING_FOR_FIRST_KILL:
					label = CAVE_WAITING;
					hint = CAVE_START_HINT;
					break;
				case WAITING_FOR_NEXT_KILL:
					label = CAVE_WAITING;
					hint = CAVE_RESUME_HINT;
					break;
				default:
					break;
			}
		}
		return Row.line(Kind.STATE, label, hint).withTones(Tone.ALERT, Tone.ALERT);
	}

	/** The identity: the task icon (or none) beside the name, then the spot's short name and the setup tag sprites. */
	static Row identityRow(String name, Integer iconItemId, String spotName, List<SetupTagIcons.Icon> tags)
	{
		return new Row(Kind.IDENTITY, name, null, Tone.NAME, Tone.VALUE, false,
			new Row.Details(iconItemId, spotName, tags, 0, 0, null));
	}

	/** The bar: {@code done} of {@code total} kills, labelled {@code 73 / 201}. */
	static Row barRow(int done, int total)
	{
		return new Row(Kind.BAR, LedgerFormat.progress(done, total), null, Tone.VALUE, Tone.VALUE, false,
			new Row.Details(null, null, null, done, total, null));
	}

	/**
	 * The key line: {@code 128 left} (the key number) / the time left ({@link LedgerFormat#timeLeft}); with the kills
	 * left unknown, the session's kills and {@code ? left}.
	 */
	static Row progressRow(SessionTracker.LiveTask task, Long historicalMillisPerKill)
	{
		final int remaining = task.getRemaining();
		if (remaining <= 0)
		{
			return Row.line(Kind.PROGRESS, LedgerFormat.kills(task.getKills()) + " killed", UNKNOWN_REMAINING + " left");
		}
		return new Row(Kind.PROGRESS, LedgerFormat.kills(remaining) + " left",
			LedgerFormat.timeLeft(task.getActiveMillis(), task.getKills(), remaining, historicalMillisPerKill),
			Tone.VALUE, Tone.VALUE, true, Row.Details.NONE);
	}

	/** The pace line, {@code 0:18/kill} / {@code 200/h}, or {@code null} until the pace is known. */
	static Row paceRow(SessionTracker.LiveTask task)
	{
		final OptionalLong perKill = TaskTimeEstimate.averageKillMillis(task.getActiveMillis(), task.getKills());
		final OptionalDouble perHour = TaskTimeEstimate.killsPerHour(task.getActiveMillis(), task.getKills());
		if (!perKill.isPresent() || !perHour.isPresent())
		{
			return null;
		}
		return Row.line(Kind.PACE, LedgerFormat.pace(perKill.getAsLong()),
			LedgerFormat.perHour(perHour.getAsDouble()) + "/h");
	}

	/** {@code 1 superior}, {@code 0 superiors}, {@code 12 superiors}. */
	static String superiorsText(int superiors)
	{
		return superiors == 1 ? "1 superior" : LedgerFormat.kills(Math.max(0, superiors)) + " superiors";
	}

	/**
	 * The live profit, as the live card shows it: loot in its price mode minus supplies, always signed ({@code +212K},
	 * {@code -38K}), with {@code ~} before the sign when a price is missing.
	 */
	static String profitText(SessionValuation.Values values)
	{
		final int unpriced = values.getLootValueUnpriced() + values.getSuppliesUnpriced();
		return LedgerFormat.signed(values.getProfit(), unpriced > 0);
	}

	/** {@code 58.6K XP}. */
	static String xpText(long xp)
	{
		return LedgerFormat.amount(Math.max(0, xp)) + " XP";
	}

	/**
	 * The runway's text: {@code Prayer: ~40 kills}, or without {@code withKillsWord} {@code Prayer: ~40}; critical
	 * {@code Prayer: 6 left}.
	 */
	static String runwayText(SupplyRunway.Warning runway, boolean withKillsWord)
	{
		final String name = runway.getKind().getShortName() + ": ";
		if (runway.isCritical())
		{
			return name + LedgerFormat.kills(runway.getKills()) + " left";
		}
		return name + LedgerFormat.APPROXIMATE + LedgerFormat.kills(runway.getKills())
			+ (withKillsWord ? KILLS_WORD : "");
	}

	/** The runway row: the supply's icon and {@link #runwayText}, in the alert colour; Bold when critical. */
	static Row runwayRow(SupplyRunway.Warning runway)
	{
		return new Row(Kind.RUNWAY, runwayText(runway, true), null, Tone.ALERT, Tone.ALERT, false,
			new Row.Details(runway.getItemId(), null, null, 0, 0, runway));
	}

	/**
	 * The superior moment line (DESIGN_PRINCIPLES.md 5.2, 5.3): {@code Superior spawned.} for the session's first, then
	 * by turns {@code Another superior (2nd).} and {@code Superior spawned (3rd).}; three variants at most.
	 *
	 * @param number which of the session's superiors it is, from 1
	 */
	static String momentText(int number)
	{
		if (number <= 1)
		{
			return "Superior spawned.";
		}
		final String nth = ordinal(number);
		return number % 2 == 0 ? "Another superior (" + nth + ")." : "Superior spawned (" + nth + ").";
	}

	/** {@code 1st}, {@code 2nd}, {@code 3rd}, {@code 4th}, {@code 11th}, {@code 12th}, {@code 21st}, {@code 112th}. */
	static String ordinal(int n)
	{
		final int lastTwo = Math.abs(n) % 100;
		final String suffix;
		if (lastTwo >= 11 && lastTwo <= 13)
		{
			suffix = "th";
		}
		else
		{
			switch (Math.abs(n) % 10)
			{
				case 1:
					suffix = "st";
					break;
				case 2:
					suffix = "nd";
					break;
				case 3:
					suffix = "rd";
					break;
				default:
					suffix = "th";
					break;
			}
		}
		return LedgerFormat.kills(n) + suffix;
	}

	/**
	 * The task's name as the sidebar's task box shows it: its display name ({@link LedgerRecord#displayName}), or its
	 * variant's (its Catacombs variant or Slayer boss) once the session's kills say so, with {@code (cannon)}
	 * while its Cannon tag is Yes and {@code + boss} for boss kills its name doesn't show
	 * ({@link TaskVariants.Decision#displayName}; without a variant, {@link TaskSelection#displayName}).
	 *
	 * @param selection the session's version and cannon use ({@link SessionTracker#getCurrentTaskSelection}), or
	 *                  {@code null} for the task itself
	 * @param variant   the session's variant and boss flag ({@link SessionTracker#getCurrentVariant}), or {@code null}
	 *                  for the selection's version alone
	 */
	static String taskName(String monster, int creatureId, TaskSelection selection, TaskVariants.Decision variant)
	{
		final String name = LedgerRecord.displayName(monster, creatureId);
		if (variant == null)
		{
			return selection == null ? name : selection.displayName(name);
		}
		return variant.displayName(name, selection != null && Boolean.TRUE.equals(selection.getCannon()));
	}

	/**
	 * The rows to show, in order, for the enabled groups; empty when {@code data} is {@code null}. The state line comes
	 * first whatever the groups, so a stopped clock is never silent. See the class comment for the rows.
	 */
	static List<Row> rows(Data data, Groups groups)
	{
		if (data == null)
		{
			return Collections.emptyList();
		}
		final Groups shown = groups == null ? Groups.ALL : groups;
		final Snapshot snapshot = data.getSnapshot();
		final SessionTracker.LiveTask task = data.getTask();
		final List<Row> rows = new ArrayList<>(10);
		final Row state = stateRow(data.getStatus(), snapshot != null && snapshot.isCaveTask());
		if (state != null)
		{
			rows.add(state);
		}
		if (shown.isProgress())
		{
			final String name = data.getTaskName();
			if (name != null)
			{
				rows.add(identityRow(name, data.getIconItemId(), snapshot == null ? null : snapshot.getSpotName(),
					snapshot == null ? null : snapshot.getTags()));
			}
			final int remaining = data.getRemaining();
			final int total = snapshot == null ? UNKNOWN : snapshot.getAssigned();
			if (total > 0 && remaining > 0 && remaining <= total)
			{
				rows.add(barRow(total - remaining, total));
			}
			if (task != null)
			{
				rows.add(progressRow(task, data.getHistoricalMillisPerKill()));
			}
		}
		if (task == null)
		{
			return rows;
		}
		if (shown.isPace())
		{
			final Row pace = paceRow(task);
			if (pace != null)
			{
				rows.add(pace);
			}
		}
		final String elapsed = shown.isPace() ? LedgerFormat.clock(task.getActiveMillis()) + ELAPSED_WORD : null;
		final String superiors = shown.isHaul() && snapshot != null ? superiorsText(snapshot.getSuperiors()) : null;
		if (elapsed != null || superiors != null)
		{
			rows.add(Row.line(Kind.ELAPSED, elapsed, superiors));
		}
		final SessionValuation.Values values = data.getValues();
		if (shown.isHaul() && values != null)
		{
			final long profit = values.getProfit();
			rows.add(Row.line(Kind.HAUL, profitText(values), snapshot == null ? null : xpText(snapshot.getXp()))
				.withTones(profit > 0 ? Tone.GOOD : profit < 0 ? Tone.ALERT : Tone.VALUE, Tone.VALUE));
		}
		// At most one of the two; a moment never hides a warning (DESIGN_PRINCIPLES.md 2.1).
		if (shown.isRunway() && snapshot != null && snapshot.getRunway() != null)
		{
			rows.add(runwayRow(snapshot.getRunway()));
		}
		else if (shown.isHaul() && snapshot != null && snapshot.getMoment() != null)
		{
			rows.add(Row.line(Kind.MOMENT, snapshot.getMoment(), null));
		}
		return rows;
	}

	// ---- Fitting to the width ----

	/**
	 * {@code row} with its text cut to fit {@code width} pixels of content (the overlay's width less its borders) in the
	 * live fonts, so that nothing wraps (DESIGN_PRINCIPLES.md 2.2):
	 * <ul>
	 * <li>the value lines (progress, pace, elapsed, haul) never cut a value ({@link #fitValues}): they drop unit words,
	 * then whole values ({@code 1,128 left} / {@code ~5 h 12}, {@code 1:03:31} / {@code 2 superiors});</li>
	 * <li>the state line keeps its label whole and cuts the hint, and cuts the label only when it doesn't fit alone
	 * (dropping the hint); the moment line is cut;</li>
	 * <li>the identity's name and spot fit beside the task icon, the spot also beside its tag sprites;</li>
	 * <li>the runway fits beside its icon, dropping {@link #KILLS_WORD} first;</li>
	 * <li>the bar's label is left as it is.</li>
	 * </ul>
	 * Text is cut with {@link #ELLIPSIS}.
	 *
	 * @param plain the metrics of the overlay's font
	 * @param bold  the metrics of the Bold font for {@link Row#isBold} text, or {@code null} when it is drawn in
	 *              {@code plain} (a non-default overlay font)
	 */
	static Row fitted(Row row, int width, FontMetrics plain, FontMetrics bold)
	{
		final FontMetrics leftMetrics = row.isBold() && bold != null ? bold : plain;
		switch (row.getKind())
		{
			case BAR:
				return row;
			case IDENTITY:
			{
				final int textWidth = width - (row.getIconItemId() != null ? ICON_WIDTH + ICON_GAP : 0);
				final int tagsWidth = tagsWidth(row.getTags().size());
				final String name = truncate(row.getLeft(), textWidth, plain);
				final String spot = truncate(row.getSecond(),
					textWidth - (tagsWidth > 0 ? tagsWidth + TEXT_ICON_GAP : 0), plain);
				return row.withText(name, "", spot);
			}
			case RUNWAY:
			{
				final int textWidth = width - SMALL_ICON_WIDTH - TEXT_ICON_GAP;
				String text = row.getLeft();
				if (leftMetrics.stringWidth(text) > textWidth && row.getRunway() != null)
				{
					text = runwayText(row.getRunway(), false);
				}
				return row.withText(truncate(text, textWidth, leftMetrics), "", null);
			}
			case PROGRESS:
			case PACE:
			case ELAPSED:
			case HAUL:
			{
				final String[] fit = fitValues(row.getKind(), row.getLeft(), row.getRight(), width, leftMetrics, plain);
				return row.withText(fit[0], fit[1], row.getSecond());
			}
			default:
			{
				final String[] fit = fit(row.getLeft(), row.getRight(), width, leftMetrics, plain);
				return row.withText(fit[0], fit[1], row.getSecond());
			}
		}
	}

	/**
	 * A value line's two values fitted to {@code width} pixels without cutting one, so no number loses a digit: the first
	 * of these that fits, with a space between:
	 * <ol>
	 * <li>both whole;</li>
	 * <li>the right value without its unit word ({@link #unitWord}: {@code 1,128 left} / {@code ~5 h 12});</li>
	 * <li>both without their unit words ({@code 1:03:31} / {@code 2 superiors});</li>
	 * <li>the left value alone, whole, then without its unit word;</li>
	 * <li>nothing.</li>
	 * </ol>
	 */
	static String[] fitValues(Kind kind, String left, String right, int width, FontMetrics leftMetrics,
		FontMetrics rightMetrics)
	{
		final String l = left == null ? "" : left;
		final String r = right == null ? "" : right;
		final String shortLeft = l.substring(0, l.length() - unitWord(kind, true, l).length());
		final String shortRight = r.substring(0, r.length() - unitWord(kind, false, r).length());
		final String[][] candidates = {{l, r}, {l, shortRight}, {shortLeft, shortRight}, {l, ""}, {shortLeft, ""}};
		for (String[] candidate : candidates)
		{
			if (fits(candidate[0], candidate[1], width, leftMetrics, rightMetrics))
			{
				return candidate;
			}
		}
		return new String[]{"", ""};
	}

	/**
	 * The unit word a value of a {@code kind} line ends with, which {@link #fitValues} drops before the whole value, or
	 * {@code ""} for none: on the left {@link #LEFT_WORD} or {@link #KILLED_WORD} (progress), {@link #PER_KILL_WORD}
	 * (pace) and {@link #ELAPSED_WORD} (elapsed); on the right {@link #MIN_WORD} (the time left). The other values (the
	 * kills per hour, superiors, profit and XP) have none: without it a bare number would say nothing.
	 */
	static String unitWord(Kind kind, boolean leftSide, String value)
	{
		final List<String> words;
		switch (kind)
		{
			case PROGRESS:
				words = leftSide ? Arrays.asList(LEFT_WORD, KILLED_WORD) : Collections.singletonList(MIN_WORD);
				break;
			case PACE:
				words = leftSide ? Collections.singletonList(PER_KILL_WORD) : Collections.emptyList();
				break;
			case ELAPSED:
				words = leftSide ? Collections.singletonList(ELAPSED_WORD) : Collections.emptyList();
				break;
			default:
				words = Collections.emptyList();
				break;
		}
		for (String word : words)
		{
			if (value != null && value.length() > word.length() && value.endsWith(word))
			{
				return word;
			}
		}
		return "";
	}

	/** Whether {@code left} and {@code right} fit {@code width} pixels whole, with a space between. */
	private static boolean fits(String left, String right, int width, FontMetrics leftMetrics,
		FontMetrics rightMetrics)
	{
		final int gap = left.isEmpty() || right.isEmpty() ? 0 : rightMetrics.stringWidth(" ");
		return leftMetrics.stringWidth(left) + gap + rightMetrics.stringWidth(right) <= width;
	}

	/** The width the identity's tag sprites take: {@link #TAG_SIZE} each, {@link #TAG_GAP} between. */
	static int tagsWidth(int tags)
	{
		return tags <= 0 ? 0 : tags * TAG_SIZE + (tags - 1) * TAG_GAP;
	}

	/**
	 * {@code left} and {@code right} cut to share {@code width} pixels with a space between: the left whole and the
	 * right cut to what is left, or, when the left doesn't fit alone, the left cut and no right.
	 */
	static String[] fit(String left, String right, int width, FontMetrics leftMetrics, FontMetrics rightMetrics)
	{
		final String l = left == null ? "" : left;
		final String r = right == null ? "" : right;
		final int leftWidth = leftMetrics.stringWidth(l);
		if (r.isEmpty())
		{
			return new String[]{truncate(l, width, leftMetrics), ""};
		}
		final int gap = l.isEmpty() ? 0 : rightMetrics.stringWidth(" ");
		if (leftWidth + gap + rightMetrics.stringWidth(r) <= width)
		{
			return new String[]{l, r};
		}
		final int room = width - leftWidth - gap;
		final String cut = room > 0 ? truncate(r, room, rightMetrics) : "";
		if (cut.isEmpty() || cut.equals(ELLIPSIS))
		{
			// No useful room for the right side: the left alone, cut if it must be.
			return new String[]{truncate(l, width, leftMetrics), ""};
		}
		return new String[]{l, cut};
	}

	/**
	 * {@code text} as it is when it fits {@code maxWidth} pixels, else its longest start that fits with {@link #ELLIPSIS}
	 * after it (trailing spaces dropped); just the ellipsis, or nothing, when even that is too wide.
	 */
	static String truncate(String text, int maxWidth, FontMetrics metrics)
	{
		if (text == null || text.isEmpty())
		{
			return "";
		}
		if (metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		final int ellipsis = metrics.stringWidth(ELLIPSIS);
		if (ellipsis > maxWidth)
		{
			return "";
		}
		// The longest start that fits with the ellipsis (widths grow with length, so a binary search).
		int low = 0;
		int high = text.length() - 1;
		while (low < high)
		{
			final int mid = (low + high + 1) / 2;
			if (metrics.stringWidth(text.substring(0, mid)) + ellipsis <= maxWidth)
			{
				low = mid;
			}
			else
			{
				high = mid - 1;
			}
		}
		final String start = text.substring(0, low).replaceAll("\\s+$", "");
		return start + ELLIPSIS;
	}
}

package com.shmayvan.slayerledger;

/**
 * Recognises the game messages sent when a pet drops. Pure; tags and markup are stripped by
 * {@link GameMessageText}.
 *
 * <p>The texts are the three core ScreenshotPlugin (RuneLite 1.13.4, {@code PET_MESSAGES}) takes a pet screenshot on,
 * for the same chat types (game, spam, trade and friends chat notification messages). Core uses {@code contains};
 * this strips the colour tags and checks the start of the message instead, so a message only quoting the text is not
 * counted. Each text starts with "You", so another player's pet broadcast never matches.</p>
 */
final class PetMessage
{
	/** The pet follows you. */
	static final String FOLLOWED = "You have a funny feeling like you're being followed";
	/** The pet went to your inventory, because another follower was out. */
	static final String BACKPACK = "You feel something weird sneaking into your backpack";
	/** You already have this pet, so it was not given to you. */
	static final String DUPLICATE = "You have a funny feeling like you would have been followed";

	private PetMessage()
	{
	}

	/**
	 * What a chat message says about a pet drop, or {@code null} when it is not a pet message.
	 *
	 * @param petMessageType whether the message type is one core checks: GAMEMESSAGE, SPAM, TRADE or
	 *                       FRIENDSCHATNOTIFICATION
	 * @param message        the message text, possibly with tags
	 */
	static NotableDrop.Pet parse(boolean petMessageType, String message)
	{
		if (!petMessageType || message == null)
		{
			return null;
		}
		final String text = GameMessageText.plain(message);
		if (text.startsWith(FOLLOWED) || text.startsWith(BACKPACK))
		{
			return NotableDrop.Pet.RECEIVED;
		}
		if (text.startsWith(DUPLICATE))
		{
			return NotableDrop.Pet.DUPLICATE;
		}
		return null;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * The player's attacks of the last few game ticks, each with its style ({@link AttackStyles}), its target NPC and the
 * clock time its tick began, so each of the player's own hitsplats can be put down to the attack that landed it (V2
 * plan 4.3). Pure; client thread only, not synchronized. Bounded to the attacks of the last
 * {@link #RANGED_LATEST} + 1 ticks.
 *
 * <p><b>When an attack's hits land.</b> An attack is noted on the GameTick it starts on, tick A. Every hit on an NPC
 * lands one tick later than the attack's own hit delay, because the game processes NPCs before players (OSRS Wiki,
 * "Hit delay": processing order delay; RuneLite 1.13.4's {@code SpecialWeapon.getHitDelay}: "one server cycle of
 * additional delay"). Melee has no hit delay of its own, so:</p>
 * <ul>
 * <li>melee lands on A + 1 ({@link #MELEE}); a multi-hit special attack's last hits (the dragon claws') on A + 2
 * ({@link #MELEE_LATE});</li>
 * <li>bows, crossbows, thrown weapons, chinchompas and ballistae land on A + 2 to A + 4, spells and powered staves on
 * A + 2 to A + 5, and Tumeken's shadow at range and a Barrage on a large NPC up to A + 6: ranged and magic attacks land
 * on A + {@link #RANGED_EARLIEST} to A + {@link #RANGED_LATEST}.</li>
 * </ul>
 *
 * <p><b>Which attack a hitsplat on an NPC is</b> ({@link #forHit}). Only an attack on that NPC (its target) can be it.
 * For a hitsplat on tick H, in this order:</p>
 * <ol>
 * <li>a melee attack on it on H - 1;</li>
 * <li>else a melee attack on it on H - 2 (a multi-hit special's last hits);</li>
 * <li>else the latest ranged or magic attack on it from H - 6 to H - 2;</li>
 * <li>else none: a hitsplat of the player's with no attack of theirs on that NPC around it, such as the cannon's.</li>
 * </ol>
 * <p>Melee is tried first. By then a ranged or magic attack's hits have landed: the player's next attack waits out the
 * weapon's attack speed (2 ticks for a blowpipe, 3 for a shortbow, 4 for a trident, 5 for a Barrage), and only a hit
 * from its longest range lands as late as one tick after that, the tick a melee attack's hit would; from that far away
 * the player can't reach melee range in time. So a dart's hit on A + 2, after a swap to a whip that attacks on A + 2,
 * is the dart's, and a whip's hit on A + 5 after a trident's cast on A is the whip's.</p>
 *
 * <p><b>Splash</b> ({@link #forSplashHit}). A Burst or Barrage, and a chinchompa, also hits the NPCs around its target.
 * A hitsplat that no attack on its own NPC landed is such a splash when, on its tick, the same attack's hit on its
 * target landed too (all of one cast's hits land together; a chinchompa's other targets are hit only when its target is,
 * OSRS Wiki, "Black chinchompa"). So the cannon's hits on other NPCs while the player barrages give no style, apart
 * from one that lands on the very tick of a Barrage's hits.</p>
 *
 * <p>The style is the attack's, decided when it started, so a ranged attack's hitsplat that lands after the player
 * switched to a melee weapon is still Ranged.</p>
 */
final class PlayerAttacks
{
	/** Ticks after a melee attack its hits land. */
	static final int MELEE = 1;
	/** Ticks after a multi-hit melee special attack its last hits land. */
	static final int MELEE_LATE = 2;
	/** The fewest ticks after a ranged or magic attack its hits land. */
	static final int RANGED_EARLIEST = 2;
	/** The most ticks after a ranged or magic attack its hits land. */
	static final int RANGED_LATEST = 6;

	/** No XP reading ({@link #xpRose}). */
	static final long NO_XP = -1;

	/** One attack: the tick it started on, its style and target, and when that tick began (clock millis). */
	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	static final class Attack
	{
		@Getter
		private final int tick;
		@Getter
		private final SetupStyle style;
		/** When the attack's tick began (clock millis): before that tick's XP is read. */
		@Getter
		private final long at;
		private final long target;
		private final boolean splash;
		/** For a splash attack: bit {@code d} is set once its hit on its target landed {@code d} ticks after it. */
		private int landed;

		private boolean isMelee()
		{
			return style == SetupStyle.MELEE;
		}
	}

	/** Recent attacks, oldest first; at most one per tick. */
	private final Deque<Attack> attacks = new ArrayDeque<>();
	/** The XP reading of the previous tick ({@link #xpRose}), or {@link #NO_XP}. */
	private long lastXp = NO_XP;

	/**
	 * The player's attack on the NPC {@code target} ({@link DamagedNpcs#key}) started on {@code tick}, whose start is
	 * {@code at} (clock millis), with {@code style}; {@code splash} when it also hits the NPCs around its target (a Burst
	 * or Barrage, a chinchompa). Ignored without a style, or for a tick not after the latest attack's.
	 */
	void add(int tick, SetupStyle style, long at, long target, boolean splash)
	{
		if (style == null || (!attacks.isEmpty() && tick <= attacks.peekLast().tick))
		{
			return;
		}
		attacks.addLast(new Attack(tick, style, at, target, splash));
		while (attacks.peekFirst().tick < tick - RANGED_LATEST - 1)
		{
			attacks.removeFirst();
		}
	}

	/**
	 * The attack on the NPC {@code npc} that a hitsplat of the player's on it on {@code hitTick} is put down to (see the
	 * class comment), or {@code null}. A splash attack it finds notes that its hits land on {@code hitTick}, for
	 * {@link #forSplashHit}: so call this for all of a tick's hitsplats first.
	 */
	Attack forHit(int hitTick, long npc)
	{
		Attack melee = null;
		Attack meleeLate = null;
		Attack ranged = null;
		final Iterator<Attack> it = attacks.descendingIterator();
		while (it.hasNext())
		{
			final Attack attack = it.next();
			final int delay = hitTick - attack.tick;
			if (delay > RANGED_LATEST)
			{
				break;
			}
			if (attack.target != npc || delay < MELEE)
			{
				continue;
			}
			if (attack.isMelee())
			{
				if (delay == MELEE)
				{
					melee = attack;
				}
				else if (delay == MELEE_LATE)
				{
					meleeLate = attack;
				}
			}
			else if (ranged == null && delay >= RANGED_EARLIEST)
			{
				ranged = attack;
			}
		}
		final Attack found = melee != null ? melee : meleeLate != null ? meleeLate : ranged;
		if (found != null && found.splash)
		{
			found.landed |= 1 << (hitTick - found.tick);
		}
		return found;
	}

	/**
	 * The splash attack (a Burst or Barrage, a chinchompa) that a hitsplat of the player's on {@code hitTick} is put
	 * down to when no attack on its own NPC is ({@link #forHit}): the latest one from {@link #RANGED_EARLIEST} to
	 * {@link #RANGED_LATEST} ticks before whose hit on its target landed on {@code hitTick} too, or {@code null}.
	 */
	Attack forSplashHit(int hitTick)
	{
		final Iterator<Attack> it = attacks.descendingIterator();
		while (it.hasNext())
		{
			final Attack attack = it.next();
			final int delay = hitTick - attack.tick;
			if (delay > RANGED_LATEST)
			{
				break;
			}
			if (attack.splash && delay >= RANGED_EARLIEST && (attack.landed & (1 << delay)) != 0)
			{
				return attack;
			}
		}
		return null;
	}

	/**
	 * This tick's total XP in the skills that confirm an attack ({@link AttackStyles#ATTACK_XP_SKILLS}), or
	 * {@link #NO_XP} when it can't be read: whether it rose since the previous tick's reading. An animation is an
	 * attack only if it did: every attack that hits gains XP on its own tick, before its hitsplat, and a block
	 * gains none. Called once a tick, so the next tick compares with this reading.
	 */
	boolean xpRose(long xp)
	{
		final boolean rose = lastXp != NO_XP && xp != NO_XP && xp > lastXp;
		lastXp = xp;
		return rose;
	}

	/** Forgets the XP reading, keeping the attacks (no attack can start while the XP isn't read). */
	void forgetXp()
	{
		lastXp = NO_XP;
	}

	/** Forgets every attack and the XP reading (a login, hop or plugin start, or while no task is assigned). */
	void clear()
	{
		attacks.clear();
		lastXp = NO_XP;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;

/**
 * Decides when to look up again the items whose GE price was unavailable when the history asked for today's prices
 *. Pure: the plugin tells it which ids came back without a price and which were found, and asks it on every
 * game tick which ids to look up again. Not thread-safe (the plugin uses it on the client thread only).
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>RuneLite's {@code ItemManager} has no "prices loaded" flag, so an item asked for before its price list was
 *     fetched comes back unavailable (see {@link ItemValuation}). Each such id is tried again every
 *     {@link #INTERVAL_TICKS} game ticks, at most {@link #MAX_ATTEMPTS} times, then dropped: it is only asked for
 *     again when the history next asks for it (the records change).</li>
 *     <li>An id that comes back unavailable from a new request (not a retry) gets {@link #MAX_ATTEMPTS} tries again,
 *     so a later request can never be cut short by an earlier one, while retries alone can never loop.</li>
 *     <li>An id whose price is found is never tried again.</li>
 * </ul>
 */
final class PriceRetry
{
	/** Game ticks (3 seconds) between tries of the unavailable prices. */
	static final int INTERVAL_TICKS = 5;
	/** Tries per unavailable price after the request that missed it (30 seconds in all). */
	static final int MAX_ATTEMPTS = 10;

	/** Tries left per id still unavailable. */
	private final Map<Integer, Integer> attemptsLeft = new TreeMap<>();
	/** Game ticks until the next try, while there are ids to try. */
	private int ticksLeft;

	/**
	 * Ids a request (not a retry) found unavailable: each is tried again {@link #MAX_ATTEMPTS} times, the first time
	 * {@link #INTERVAL_TICKS} ticks from now (or with the next try already counting down).
	 */
	void missed(Collection<Integer> ids)
	{
		for (Integer id : ids)
		{
			if (id != null)
			{
				attemptsLeft.put(id, MAX_ATTEMPTS);
			}
		}
		if (!attemptsLeft.isEmpty() && ticksLeft <= 0)
		{
			ticksLeft = INTERVAL_TICKS;
		}
	}

	/** Ids whose price is now known: they are not tried again. */
	void found(Collection<Integer> ids)
	{
		attemptsLeft.keySet().removeAll(ids);
		if (attemptsLeft.isEmpty())
		{
			ticksLeft = 0;
		}
	}

	/**
	 * One game tick: the ids to look up again now, or an empty set. Each id returned has used up one try; an id
	 * without tries left is dropped. The caller reports the ones it found through {@link #found}.
	 */
	Set<Integer> tick()
	{
		if (attemptsLeft.isEmpty() || --ticksLeft > 0)
		{
			return Collections.emptySet();
		}
		final Set<Integer> due = new TreeSet<>(attemptsLeft.keySet());
		attemptsLeft.replaceAll((id, left) -> left - 1);
		attemptsLeft.values().removeIf(left -> left <= 0);
		ticksLeft = attemptsLeft.isEmpty() ? 0 : INTERVAL_TICKS;
		return due;
	}

	/** Whether any id is waiting for another try. */
	boolean isEmpty()
	{
		return attemptsLeft.isEmpty();
	}

	/** Forgets every id (a new run of the plugin). */
	void clear()
	{
		attemptsLeft.clear();
		ticksLeft = 0;
	}
}

package com.shmayvan.slayerledger;

/**
 * Pure decision of what to do with a session when it ends or must leave memory.
 */
final class SaveDecision
{
	/** Why the session is ending (or being taken out of memory). */
	enum EndReason
	{
		/** The player pressed End task. */
		PLAYER_STOP,
		/** The plugin ended it while logged in (task completed, changed, or cleared). */
		SYSTEM,
		/** The player logged out. The in-memory session is kept; a copy is persisted. */
		LOGOUT,
		/** The plugin was turned off or the client is closing. */
		SHUTDOWN,
		/** Another account logged in while this account's session was active. */
		ACCOUNT_SWITCH,
		/** A persisted active session could not be restored because the task no longer matches. */
		RESTORE_MISMATCH,
		/** A Keep/Discard dialog was still open when the client or plugin shut down. */
		PROMPT_UNRESOLVED
	}

	enum Action
	{
		/** Save as a completed record. */
		SAVE_COMPLETED,
		/** Ask the player whether to keep (as partial) or discard. */
		PROMPT,
		/** Save as partial silently. */
		SAVE_PARTIAL,
		/** Save as partial and show a non-modal notice offering Discard. */
		SAVE_PARTIAL_WITH_NOTICE,
		/** Do not create a record; persist the session as the account's active session to restore later. */
		PERSIST_ACTIVE,
		/** Do not save. */
		DISCARD
	}

	private SaveDecision()
	{
	}

	static Action decide(SessionTracker.Summary summary, EndReason reason, boolean confirmIncomplete)
	{
		return decide(summary.hasTask(), summary.getAccountHash(), summary.isCompleted(), reason, confirmIncomplete);
	}

	static Action decide(boolean hasTask, long accountHash, boolean completed, EndReason reason,
		boolean confirmIncomplete)
	{
		if (!hasTask || accountHash == SessionTracker.NO_ACCOUNT)
		{
			return Action.DISCARD;
		}
		if (completed)
		{
			return Action.SAVE_COMPLETED;
		}
		switch (reason)
		{
			case LOGOUT:
			case SHUTDOWN:
			case ACCOUNT_SWITCH:
				return Action.PERSIST_ACTIVE;
			case SYSTEM:
			case RESTORE_MISMATCH:
				return Action.SAVE_PARTIAL_WITH_NOTICE;
			case PROMPT_UNRESOLVED:
				return Action.SAVE_PARTIAL;
			case PLAYER_STOP:
			default:
				return confirmIncomplete ? Action.PROMPT : Action.SAVE_PARTIAL;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * What a session's restore needs besides its tallies (V2 plan 4.1), carried by {@link SessionTracker.Summary} into
 * {@link SessionSnapshot}: the state it was in, the clamps of its next resume point (the close of its last segment,
 * when its assignment was first seen, and the end of the session before it) and its known task NPCs. Times are clock
 * millis, {@code null} when unknown. Pure and immutable.
 */
@Getter
final class SegmentInfo
{
	/** Nothing known (a summary built from a 1.x snapshot, or in tests). */
	static final SegmentInfo NONE = new SegmentInfo(null, SessionTracker.NO_TIME, SessionTracker.NO_TIME,
		SessionTracker.NO_TIME, null);

	/** The state the session was in when this was taken, or {@code null} when unknown. */
	private final SessionTracker.State state;
	/** The close of the session's last segment, or {@code null} while unknown (or a segment is open). */
	private final Long segmentClosedAt;
	/** When the session's assignment was first seen, or {@code null}. */
	private final Long assignedAt;
	/** The end of the session before this one, or {@code null}. */
	private final Long previousSessionEnd;
	/** The session's known task NPCs, normalized (unmodifiable, possibly empty). */
	private final List<String> taskNpcs;

	/**
	 * @param state              the state the session was in, or {@code null} when unknown
	 * @param segmentClosedAt    the close of its last segment, or {@link SessionTracker#NO_TIME}
	 * @param assignedAt         when its assignment was first seen, or {@link SessionTracker#NO_TIME}
	 * @param previousSessionEnd the end of the session before it, or {@link SessionTracker#NO_TIME}
	 * @param taskNpcs           its known task NPCs (normalized names), or {@code null} for none
	 */
	SegmentInfo(SessionTracker.State state, long segmentClosedAt, long assignedAt, long previousSessionEnd,
		List<String> taskNpcs)
	{
		this.state = state;
		this.segmentClosedAt = time(segmentClosedAt);
		this.assignedAt = time(assignedAt);
		this.previousSessionEnd = time(previousSessionEnd);
		this.taskNpcs = taskNpcs == null || taskNpcs.isEmpty() ? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(taskNpcs));
	}

	private static Long time(long millis)
	{
		return millis == SessionTracker.NO_TIME ? null : millis;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * The plain counters of one session (superior spawns, bank trips, deaths), shared by {@link SessionTracker} (which
 * counts them), {@link SessionTracker.Summary}, {@link SessionSnapshot} and {@link LedgerRecord}. Immutable; build one
 * with {@link #builder()} or {@link #toBuilder()}. No RuneLite dependencies.
 *
 * <p>Each counter is {@code null} when unknown: a snapshot or record from before it was counted. A builder starts every
 * counter at 0. The persisted classes keep these as flat fields of their own (their JSON must not change), so this
 * class copies them in and out ({@link #copyTo(SessionSnapshot)}, {@link #copyTo(LedgerRecord)},
 * {@link #from(SessionSnapshot)}).</p>
 *
 * <p>Adding a counter: add the field here (and to {@link #copyTo(SessionSnapshot)}, {@link #copyTo(LedgerRecord)},
 * {@link #from(SessionSnapshot)} and {@link #withUnknownAsZero()}), the same-named field to {@link SessionSnapshot} and
 * {@link LedgerRecord}, and count it in {@link SessionTracker} with {@code toBuilder()}.</p>
 */
@Value
@Builder(toBuilder = true)
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class SessionCounters
{
	/** Every counter at 0: a new session. */
	static final SessionCounters ZERO = builder().build();

	/** Superior Slayer monster spawns seen while RUNNING, or {@code null} when unknown. */
	@Builder.Default
	Integer superiorsSpawned = 0;
	/** Bank trips made while RUNNING (see {@link BankTripCounter}), or {@code null} when unknown. */
	@Builder.Default
	Integer bankTrips = 0;
	/** Deaths of the local player while RUNNING, or {@code null} when unknown. */
	@Builder.Default
	Integer deaths = 0;

	/** The counters with every unknown or negative count as 0, as a restored session counts on from them. */
	SessionCounters withUnknownAsZero()
	{
		return builder()
			.superiorsSpawned(nonNegative(superiorsSpawned))
			.bankTrips(nonNegative(bankTrips))
			.deaths(nonNegative(deaths))
			.build();
	}

	/** The snapshot's counters as stored ({@code null} where the file has none). */
	static SessionCounters from(SessionSnapshot snapshot)
	{
		return builder()
			.superiorsSpawned(snapshot.getSuperiorsSpawned())
			.bankTrips(snapshot.getBankTrips())
			.deaths(snapshot.getDeaths())
			.build();
	}

	/** Sets the snapshot's counter fields. */
	void copyTo(SessionSnapshot snapshot)
	{
		snapshot.setSuperiorsSpawned(superiorsSpawned);
		snapshot.setBankTrips(bankTrips);
		snapshot.setDeaths(deaths);
	}

	/** Sets the record's counter fields. */
	void copyTo(LedgerRecord record)
	{
		record.setSuperiorsSpawned(superiorsSpawned);
		record.setBankTrips(bankTrips);
		record.setDeaths(deaths);
	}

	private static int nonNegative(Integer n)
	{
		return n == null ? 0 : Math.max(0, n);
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * What a session received and used: its loot, supplies (with their doses), notable drops and boss kill counts. Shared by
 * {@link SessionTracker.Summary}, {@link SessionSnapshot} and {@link LedgerRecord}: the persisted classes keep these as
 * flat fields of their own (their JSON must not change), and this class converts to and from them in one place.
 * Immutable; build one with {@link #builder()} or {@link #toBuilder()}. No RuneLite dependencies.
 */
public final class SessionLoot
{
	/** Nothing received or used. */
	static final SessionLoot EMPTY = builder().build();

	private final ItemTally loot;
	private final ItemTally supplies;
	private final Map<Integer, Integer> supplyDoses;
	/** Notable drops in the order they arrived (never {@code null}; unmodifiable). */
	@Getter
	private final List<NotableDrop> notableDrops;
	/** Boss kill counts in the order first seen (never {@code null}; unmodifiable). */
	@Getter
	private final List<BossKillCount> bossKillCounts;

	/**
	 * Copies everything it is given, so later changes to the arguments don't reach it.
	 *
	 * @param loot           NPC loot, or {@code null} for none
	 * @param supplies       supplies used, potions in doses, or {@code null} for none
	 * @param supplyDoses    doses per item for potion ids in {@code supplies} (only positive entries are kept), or
	 *                       {@code null} for none
	 * @param notableDrops   notable drops in the order they arrived, or {@code null} for none
	 * @param bossKillCounts boss kill counts in the order first seen, or {@code null} for none
	 */
	@Builder(toBuilder = true)
	private SessionLoot(ItemTally loot, ItemTally supplies, Map<Integer, Integer> supplyDoses,
		List<NotableDrop> notableDrops, List<BossKillCount> bossKillCounts)
	{
		this.loot = loot == null ? new ItemTally() : new ItemTally(loot);
		this.supplies = supplies == null ? new ItemTally() : new ItemTally(supplies);
		final Map<Integer, Integer> doses = new TreeMap<>();
		SessionTracker.putDoses(doses, supplyDoses);
		this.supplyDoses = Collections.unmodifiableMap(doses);
		this.notableDrops = Collections.unmodifiableList(NotableDrops.sanitize(notableDrops));
		this.bossKillCounts = Collections.unmodifiableList(BossKillCounts.sanitize(bossKillCounts));
	}

	/** A copy of the loot (never {@code null}). */
	public ItemTally getLoot()
	{
		return new ItemTally(loot);
	}

	/** A copy of the supplies used, potions in doses (never {@code null}). */
	public ItemTally getSupplies()
	{
		return new ItemTally(supplies);
	}

	/** A copy of the doses per item for potion ids in {@link #getSupplies()} (never {@code null}). */
	public Map<Integer, Integer> getSupplyDoses()
	{
		return new TreeMap<>(supplyDoses);
	}

	/** A copy with extra loot (may be {@code null}) merged in and extra notable drops (likewise) added. */
	SessionLoot withAddedLoot(ItemTally extra, List<NotableDrop> extraNotableDrops)
	{
		final ItemTally merged = new ItemTally(loot);
		if (extra != null)
		{
			merged.merge(extra);
		}
		return toBuilder().loot(merged).notableDrops(NotableDrops.add(notableDrops, extraNotableDrops)).build();
	}

	/** A copy with one more boss kill count message counted ({@link BossKillCounts#add}). */
	SessionLoot withBossKillCount(String boss, int kc)
	{
		return toBuilder().bossKillCounts(BossKillCounts.add(bossKillCounts, boss, kc)).build();
	}

	/** The snapshot's loot as stored. */
	static SessionLoot from(SessionSnapshot snapshot)
	{
		return builder()
			.loot(ItemTally.fromMap(snapshot.getLoot()))
			.supplies(ItemTally.fromMap(snapshot.getSupplies()))
			.supplyDoses(snapshot.getSupplyDoses())
			.notableDrops(snapshot.getNotableDrops())
			.bossKillCounts(snapshot.getBossKillCounts())
			.build();
	}

	/** Sets the snapshot's loot, supplies, doses, notable drop and boss kill count fields. */
	void copyTo(SessionSnapshot snapshot)
	{
		snapshot.setLoot(loot.toMap());
		snapshot.setSupplies(supplies.toMap());
		snapshot.setSupplyDoses(dosesFor(snapshot.getSupplies(), supplyDoses));
		snapshot.setNotableDrops(notableDropsOrNull());
		snapshot.setBossKillCounts(bossKillCountsOrNull());
	}

	/** Sets the record's loot, supplies, doses, notable drop and boss kill count fields. */
	void copyTo(LedgerRecord record)
	{
		record.setLoot(loot.toMap());
		record.setSupplies(supplies.toMap());
		record.setSupplyDoses(dosesFor(record.getSupplies(), supplyDoses));
		record.setNotableDrops(notableDropsOrNull());
		record.setBossKillCounts(bossKillCountsOrNull());
	}

	/** The notable drops as stored, or {@code null} when there are none. */
	private List<NotableDrop> notableDropsOrNull()
	{
		return notableDrops.isEmpty() ? null : new ArrayList<>(notableDrops);
	}

	/** The boss kill counts as stored, or {@code null} when there are none. */
	private List<BossKillCount> bossKillCountsOrNull()
	{
		return bossKillCounts.isEmpty() ? null : new ArrayList<>(bossKillCounts);
	}

	/** The dose entries for ids present in {@code supplies}, or {@code null} when there are none. */
	static Map<Integer, Integer> dosesFor(Map<Integer, Long> supplies, Map<Integer, Integer> doses)
	{
		if (supplies == null || doses == null)
		{
			return null;
		}
		Map<Integer, Integer> result = new TreeMap<>();
		for (Map.Entry<Integer, Integer> e : doses.entrySet())
		{
			if (e.getKey() != null && e.getValue() != null && e.getValue() > 0 && supplies.containsKey(e.getKey()))
			{
				result.put(e.getKey(), e.getValue());
			}
		}
		return result.isEmpty() ? null : result;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * A persisted in-progress session (the account's "active session" file). Written on logout, client exit, plugin
 * shutdown and account switch, and restored as Logged out on the next login if the task still matches (the next task
 * kill restarts it). The same file may instead hold an Ended assignment's marker ({@link #isEndedMarker()}): no
 * session, only the assignment, so it stays Ended after a client restart. Serialized with Gson; no RuneLite
 * dependencies.
 */
@Data
public class SessionSnapshot
{
	/** {@link #trackingState} of an Ended assignment's marker. */
	static final String ENDED_STATE = "ENDED";
	/** Start of a marker's {@link #sessionId}: never a session's or a record's id. */
	static final String ENDED_ID_PREFIX = "ended-";

	/**
	 * Version 2 adds {@link #loot}. Raised from 1 so an older build, which would drop the loot when it rewrites the
	 * file, refuses to overwrite or restore it instead. {@link #supplies} and {@link #supplyDoses} were added to
	 * version 2 later as optional fields, before any build wrote supplies. {@link #superiorsSpawned} and
	 * {@link #bankTrips} were added the same way; a file without them restores with both counts at 0. {@link #note} was
	 * added the same way; a file without it has no note. {@link #deaths} was added the same way; a file without it
	 * restores with 0 deaths. {@link #slayerMaster}, {@link #slayerArea} and {@link #taskLocation} were added the same
	 * way; a file without them restores with the assignment read from the game, since the task must match. Points and
	 * streak are not kept: a snapshot is never of a completed task. {@link #notableDrops} was added the same way; a file
	 * without it restores with none. {@link #bossKillCounts} was added the same way; a file without it restores with
	 * none. {@link #xpGained} was added the same way; a file without it restores with no XP, and XP counts from the
	 * restore. {@link #locationKills} was added the same way; a file without it restores with none, and kills are
	 * tallied per region from the restore. {@link #npcKills} was added the same way; a file without it restores
	 * with none, and kills are tallied per NPC name from the restore.
	 *
	 * <p>Version 3 (2.0) adds the Ended assignment's marker ({@link #isEndedMarker()}), a file that holds no
	 * session. An older build would restore it as an empty session, so it may not read version 3 files; it leaves them
	 * untouched. Version 3 also adds the segment fields {@link #trackingState}, {@link #segmentClosedAt},
	 * {@link #assignedAt}, {@link #previousSessionEnd} and {@link #taskNpcs}, all optional: a version 2 (1.x) file has
	 * none and restores with its last segment closed when it was saved, and its known task NPCs learned again from the
	 * next kill.</p>
	 *
	 * <p>The setup fields (2.0) were added to version 3 later, as optional fields, before any released build
	 * wrote version 3: the player's overrides ({@link #cannonOverride}, {@link #styleOverride}, {@link #gearOverride}) and the
	 * kill-context counts ({@link #cannonKills}, {@link #styleKills}, {@link #gearKills}, {@link #prayerBonusMin},
	 * {@link #prayerBonusMax}; see {@link SetupKills}). A file without them restores with no overrides and no counts.
	 * The detected tags are not kept: they are worked out from the session again ({@link SetupTags#forSession}), and
	 * the spot is decided when the record is saved. Nor are the variant and the boss flag: they are worked out
	 * from {@link #npcKills} ({@link TaskVariants}).</p>
	 *
	 * <p>{@link #killsBeforeContexts} was added to version 3 the same way: a file without it counts none, unless it
	 * is a version 2 (1.x) file, whose kills all recorded no context ({@link #killsWithoutContexts()}).</p>
	 */
	public static final int CURRENT_SCHEMA_VERSION = 3;
	/**
	 * The first version a 2.0 build wrote, and the first whose sessions record kill contexts: an older
	 * (1.x) file's kills recorded none.
	 */
	static final int FIRST_2_0_SCHEMA_VERSION = 3;

	private int schemaVersion = CURRENT_SCHEMA_VERSION;
	/** Session id; becomes the ledger record id so a session can never become two records. */
	private String sessionId;
	private long accountHash;
	private String monster;
	/** Creature key, see {@link SessionTracker#creatureKey(int, int)}. */
	private int creatureId = SessionTracker.NO_CREATURE;
	private int initialAmount;
	/** Assigned task size, or {@code null} when unknown. */
	private Integer originalAmount;
	private int kills;
	private long activeMillis;
	private long startedAt;
	/** When the snapshot was taken; used as the end time if it later becomes a partial record. */
	private long savedAt;
	/** Remaining task count when the snapshot was taken. */
	private int remaining;
	/** Task-completion counters when the snapshot was taken, or {@code null} if unknown. */
	private int[] completionCounters;
	/** Loot tally so far (item id to quantity), or {@code null} when none (and in version 1 files). */
	private Map<Integer, Long> loot;
	/** Supplies used so far (item id to quantity, potions in doses), or {@code null} when none. */
	private Map<Integer, Long> supplies;
	/** Doses per item for potion ids in {@link #supplies}, or {@code null} when none. */
	private Map<Integer, Integer> supplyDoses;
	/** Superior spawns counted so far, or {@code null} in files from before they were counted. */
	private Integer superiorsSpawned;
	/** Bank trips counted so far, or {@code null} in files from before they were counted. */
	private Integer bankTrips;
	/** Deaths of the local player counted so far, or {@code null} in files from before they were counted. */
	private Integer deaths;
	/** The player's note on the session, or {@code null} when none (and in files from before notes existed). */
	private String note;
	/** SLAYER_MASTER value of the session task, or {@code null} when unknown (and in older files). */
	private Integer slayerMaster;
	/** SLAYER_AREA value of the session task, or {@code null} when none or unknown. */
	private Integer slayerArea;
	/** Name of {@link #slayerArea}, or {@code null}. */
	private String taskLocation;
	/** Notable drops so far, in the order they arrived, or {@code null} when none (and in older files). */
	private List<NotableDrop> notableDrops;
	/** Boss kill counts so far, in the order first seen, or {@code null} when none (and in older files). */
	private List<BossKillCount> bossKillCounts;
	/**
	 * XP gained so far per skill (keyed as {@link SkillXp} keys them, e.g. {@code "SLAYER"}), or {@code null} in files
	 * from before XP was tracked. Empty when the session has gained none yet.
	 */
	private Map<String, Long> xpGained;
	/**
	 * Counted kills per place so far ({@link LocationTally}), or {@code null} when none (and in older files). Each entry
	 * keeps its Slayer spot ({@link LocationKills#getSpot}, an optional member); a 1.x file's entries have
	 * regions only, and their spots are decided from the regions. The order is the order the tally keeps (1.x: first
	 * seen; since the place killed at most recently last).
	 */
	private List<LocationKills> locationKills;
	/**
	 * Kills per NPC name so far, in the order first seen ({@link NpcKillTally}), or {@code null} when none (and in
	 * older files).
	 */
	private List<NpcKills> npcKills;
	/**
	 * The session's state when it was persisted ({@link SessionTracker.State} name: RUNNING, AWAY, PAUSED or
	 * LOGGED_OUT), or {@link #ENDED_STATE} for an Ended assignment's marker; {@code null} in older files. A session is
	 * always restored as Logged out, whatever it was.
	 */
	private String trackingState;
	/**
	 * When the session's last segment closed (a logout, a pause, Away at the last activity), or {@code null} in older
	 * files, which restore with {@link #savedAt} instead. The next resume point is never earlier.
	 */
	private Long segmentClosedAt;
	/** When the session's assignment was first seen (a clamp of every resume point), or {@code null} when unknown. */
	private Long assignedAt;
	/**
	 * The end of the session before this one (a clamp of every resume point), or {@code null} when unknown. In a
	 * marker, the Ended session's end, so a kill after Track again is never backdated before it.
	 */
	private Long previousSessionEnd;
	/** The session's known task NPCs (normalized names paired with its kills), or {@code null} when none. */
	private List<String> taskNpcs;
	/** Task kills made while the cannon was firing ({@link SetupKills}), or {@code null} when none were counted. */
	private Integer cannonKills;
	/** Task kills per style ({@link SetupStyle} name), or {@code null} when none were counted. */
	private Map<String, Integer> styleKills;
	/** Task kills per gear focus ({@link GearFocus} name), or {@code null} when none were counted. */
	private Map<String, Integer> gearKills;
	/** The lowest worn prayer bonus seen at a task kill, or {@code null}. */
	private Integer prayerBonusMin;
	/** The highest worn prayer bonus seen at a task kill, or {@code null}. */
	private Integer prayerBonusMax;
	/** The player's cannon override on the live task, or {@code null} for none ({@link SetupOverrides}). */
	private Boolean cannonOverride;
	/** The player's style override on the live task, or {@code null} for none. */
	private SetupStyle styleOverride;
	/** The player's gear focus override on the live task, or {@code null} for none. */
	private GearFocus gearOverride;
	/**
	 * Task kills the session counted before it recorded kill contexts: those of a session a 1.x version started,
	 * which a 2.0 build restored and persisted again. Left out of the cannon share
	 * ({@link SessionTracker#contextKills}). {@code null} for none; read through {@link #killsWithoutContexts()}.
	 */
	private Integer killsBeforeContexts;

	/** Whether this is an Ended assignment's marker (no session; see the class comment). */
	boolean isEndedMarker()
	{
		return ENDED_STATE.equals(trackingState);
	}

	/**
	 * The session's task kills that recorded no kill context, between 0 and its kills: the stored
	 * {@link #killsBeforeContexts}, or every kill of a 1.x file (below {@link #FIRST_2_0_SCHEMA_VERSION}), which recorded
	 * none. 0 for a 2.0 session that has none stored, whatever its contexts.
	 */
	int killsWithoutContexts()
	{
		final int before = killsBeforeContexts != null ? killsBeforeContexts
			: schemaVersion < FIRST_2_0_SCHEMA_VERSION ? kills : 0;
		return Math.max(0, Math.min(kills, before));
	}

	static SessionSnapshot fromSummary(SessionTracker.Summary summary, int[] completionCounters, long savedAt)
	{
		SessionSnapshot s = new SessionSnapshot();
		s.setSessionId(summary.getSessionId());
		s.setAccountHash(summary.getAccountHash());
		s.setMonster(summary.getMonster());
		s.setCreatureId(summary.getCreatureId());
		s.setInitialAmount(summary.getInitialAmount());
		s.setOriginalAmount(summary.getOriginalAmount() == SessionTracker.UNKNOWN_AMOUNT ? null : summary.getOriginalAmount());
		s.setKills(summary.getKills());
		s.setActiveMillis(summary.getActiveMillis());
		s.setStartedAt(summary.getStartedAt());
		s.setSavedAt(savedAt);
		s.setRemaining(summary.getResumeRemaining());
		s.setCompletionCounters(completionCounters == null ? null : Arrays.copyOf(completionCounters, completionCounters.length));
		summary.getSessionLoot().copyTo(s);
		summary.getCounters().copyTo(s);
		s.setNote(summary.getNote());
		final TaskContext context = summary.getContext();
		s.setSlayerMaster(context.getMaster());
		s.setSlayerArea(context.getArea());
		s.setTaskLocation(context.getLocation());
		s.setXpGained(LedgerRecord.xpGainedFor(summary));
		s.setLocationKills(summary.getLocationKills().isEmpty() ? null : new ArrayList<>(summary.getLocationKills()));
		s.setNpcKills(summary.getNpcKills().isEmpty() ? null : new ArrayList<>(summary.getNpcKills()));
		final SegmentInfo segments = summary.getSegments();
		s.setTrackingState(segments.getState() == null ? null : segments.getState().name());
		// A segment still open (a snapshot of a running session) closes when it is saved.
		s.setSegmentClosedAt(segments.getSegmentClosedAt() != null ? segments.getSegmentClosedAt() : savedAt);
		s.setAssignedAt(segments.getAssignedAt());
		s.setPreviousSessionEnd(segments.getPreviousSessionEnd());
		s.setTaskNpcs(segments.getTaskNpcs().isEmpty() ? null : new ArrayList<>(segments.getTaskNpcs()));
		summary.getSetupKills().copyTo(s);
		s.setKillsBeforeContexts(summary.getKillsBeforeContexts() > 0 ? summary.getKillsBeforeContexts() : null);
		summary.getSetupOverrides().copyTo(s);
		return s;
	}

	/**
	 * The snapshot as an ended, incomplete session summary (used when it cannot be restored). Its spot and the region
	 * saved with it are decided from {@link #locationKills} with {@code spots} ({@link LocationTally#decide}), exactly as
	 * for a live session: kills tallied by region alone (a 1.x file) take their region's spot, and a tie goes to the spot
	 * that lists the task.
	 *
	 * @param spots the plugin's spot table ({@link SlayerSpots#NONE} or {@code null} when unavailable)
	 */
	SessionTracker.Summary toSummary(SlayerSpots spots)
	{
		return SessionTracker.Summary.builder()
			.sessionId(sessionId)
			.accountHash(accountHash)
			.monster(monster)
			.creatureId(creatureId)
			.hasTask(true)
			.initialAmount(initialAmount)
			.originalAmount(originalAmount == null ? SessionTracker.UNKNOWN_AMOUNT : originalAmount)
			.kills(kills)
			.activeMillis(activeMillis)
			.startedAt(startedAt)
			.endedAt(savedAt)
			.completed(false)
			.resumeRemaining(remaining)
			.sessionLoot(SessionLoot.from(this))
			.counters(SessionCounters.from(this))
			.note(TaskNote.normalize(note))
			.context(TaskContext.of(slayerMaster, slayerArea, taskLocation, null, null))
			.xpGained(xpGained)
			.locationKills(locationKills)
			.taskSpot(LocationTally.decide(locationKills, spots, monster))
			.npcKills(npcKills)
			.setupKills(SetupKills.from(this))
			.killsBeforeContexts(killsWithoutContexts())
			.setupOverrides(SetupOverrides.from(this))
			.build();
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;
import lombok.*;

/**
 * Tracks a single Slayer task session. This class has no RuneLite dependencies so it can be unit tested with a
 * controllable clock. All public methods are synchronized because the plugin calls it from both the client thread
 * (task observations, kills, Away, logouts, account changes) and the Swing event dispatch thread (Pause / Resume /
 * End task / Track again).
 *
 * <p><b>Automatic lifecycle</b> (V2 plan 4.1). No session exists ({@code IDLE}) until a task kill: a drop of the
 * Slayer count ({@link #observe}) or a bracelet of slaughter keeping it ({@link #braceletKill}). The kill starts the
 * session. A session's time is the sum of its segments: a segment opens at a (re)start and closes at a stop, and time
 * outside segments is never task time. A task kill while the session is not {@code RUNNING} ({@code AWAY},
 * {@code PAUSED} or {@code LOGGED_OUT}) opens a segment at the kill's resume point: the earliest engagement start of
 * the NPCs paired with it ({@link KillPairing}), or the kill itself, never earlier than the assignment, the previous
 * session's end or the close of the previous segment. {@link #resume} (manual, from {@code PAUSED}) opens one at once.
 * The stops are {@link #pause}, {@link #loggedOut} (logout or connection loss; a hop is not a stop), Away
 * ({@link #checkAway}), {@link #endTask} and the end of the task (completion or a new task).</p>
 *
 * <p>States: {@code IDLE -> RUNNING} (a task kill, or {@link #startNow} in tests), {@code RUNNING -> AWAY | PAUSED |
 * LOGGED_OUT}, {@code AWAY | PAUSED | LOGGED_OUT -> RUNNING} (a task kill; {@code PAUSED} also by {@link #resume}),
 * {@code AWAY | PAUSED -> LOGGED_OUT}, any of them {@code -> STOPPED}, and {@link #restore} takes {@code IDLE} to
 * {@code LOGGED_OUT}. Invalid transitions are no-ops and return {@code false}. The plugin ends sessions through
 * {@link #stopAndReset} and {@link #endTask}, so it never leaves the tracker {@code STOPPED}; see
 * {@code docs/ARCHITECTURE.md}. {@link #reset()} returns a stopped tracker to {@code IDLE} so a new session can begin.
 * What the player is shown is {@link #getStatus()}.</p>
 *
 * <p><b>Ended.</b> {@link #endTask} stops the session and marks its assignment Ended: no kill on it starts a session
 * until {@link #trackAgain}, and nothing from before End task counts after it. A new assignment is tracked
 * normally.</p>
 *
 * <p>A running session that completes can be held back from saving for {@link #COMPLETION_LOOT_GRACE_TICKS} game
 * ticks (see {@link #holdCompletion()}) so the final kill's loot, which may arrive after the task count update, is
 * still recorded. The held session is already stopped (its kills and active time are final) and the tracker is back to
 * {@code IDLE}; it is outside the state machine, so it is never reported as active. When its final kill was Araxxor's,
 * whose loot comes only when the player harvests its corpse, a harvest after the save is added to its saved record
 * ({@link #takeHarvestRecord}).</p>
 *
 * <p><b>Supplies, XP and loot</b> (V2 plan 4.1). Inside a segment they count at once. Outside one, while a task is
 * assigned and not Ended ({@link #isCollecting()}), they are held per arrival time in a buffer of at most 60 minutes
 * ({@link TimedUsage}). Every (re)start counts the buffered XP and loot from the segment start (for a kill restart, the
 * backdated resume point, and the kill's own tick) and the buffered supplies from {@link #WARM_UP_MILLIS} before it,
 * no earlier than the resume point's clamps; the rest of the buffer is dropped once the restart's pairing is final
 * ({@link #pairKill}). When Away starts, the supplies, XP and loot since the last activity are taken back into the
 * buffer, apart from loot of a known task NPC (a paired task kill's) arriving within {@link #TASK_NPC_LOOT_MILLIS} of
 * the last task kill ({@link #ARAXXOR_LOOT_MILLIS} for Araxxor's), which always counts, even when it arrives after the
 * session stopped. The counters (superiors, bank trips, deaths) still count only while {@code RUNNING}; Away takes the
 * bank trips since the last activity back out, but not the deaths.</p>
 *
 * <p><b>Jad and Zuk tasks.</b> Inside the Fight Caves or the Inferno with that task assigned is Running
 * ({@link #setInTaskCave}): entering opens a segment, leaving closes it, and Away never starts inside.</p>
 */
public class SessionTracker
{
	public enum State
	{
		/** No session: waiting for the first kill of an assignment, Ended, or no task. */
		IDLE,
		/** A segment is open: time, supplies, XP and loot count. */
		RUNNING,
		/**
		 * No task kill or hit on a known task NPC for {@code awayMinutes}, or the player left the Fight Caves or the
		 * Inferno on that task; the next task kill (or entering again) restarts.
		 */
		AWAY,
		/** Paused by the player; Resume or the next task kill restarts. */
		PAUSED,
		/** Logged out (or the connection was lost), or restored after a client restart; the next task kill restarts. */
		LOGGED_OUT,
		/** Only seen inside {@link #stopAndReset}. */
		STOPPED;

		/** Whether a session exists and has not ended: running or waiting to restart. */
		public boolean isActive()
		{
			return this == RUNNING || this == AWAY || this == PAUSED || this == LOGGED_OUT;
		}

		/** Whether a session exists but its clock is stopped (Away, Paused or Logged out). */
		public boolean isClockStopped()
		{
			return this == AWAY || this == PAUSED || this == LOGGED_OUT;
		}
	}

	/**
	 * What the overlay and panel show about tracking ({@link #getStatus()}): the session's state, or without a session
	 * whether the assignment waits for its first kill or was Ended. Each has a label and, for the overlay's state line,
	 * a hint (empty when there is nothing to add).
	 */
	@Getter
	@RequiredArgsConstructor
	public enum Status
	{
		NO_TASK("No task", ""),
		WAITING_FOR_FIRST_KILL("Waiting for first kill", ""),
		RUNNING("Running", ""),
		AWAY("Away", "Back on your next kill"),
		/** Paused by the player: Resume in the sidebar (or the next task kill) restarts it. */
		PAUSED("Paused", "Resume in sidebar"),
		/** Logged out, before the next login has read the task. */
		LOGGED_OUT("Logged out", ""),
		/** Logged out earlier, or restored, and logged in again: the next task kill restarts. */
		WAITING_FOR_NEXT_KILL("Waiting for next kill", ""),
		/** After End task: the sidebar's Track again tracks the assignment again. */
		ENDED("Ended", "See sidebar");

		/** The status as shown, for example "Away". */
		private final String label;
		/**
		 * What happens next or what to do, for the overlay's state line (DESIGN_PRINCIPLES.md 2.1), for example "Back on
		 * your next kill" or "Resume in sidebar"; may be empty. On a Jad or Zuk task the overlay words Away and the
		 * waiting states for the caves instead ({@link OverlayRows#stateRow}).
		 */
		private final String hint;

		/** Whether time is not running while a task is assigned, so the overlay shows a state line. */
		public boolean hasStateLine()
		{
			return this != NO_TASK && this != RUNNING;
		}
	}

	/**
	 * Outcome of {@link #restore} and {@link #restoreEnded}.
	 */
	public enum RestoreResult
	{
		/** The snapshot was restored (a session as LOGGED_OUT, or the assignment's Ended flag). */
		RESTORED,
		/** The current task does not match the snapshot; it should be saved as partial instead. */
		MISMATCH,
		/** Restore is not possible right now (a session is active or no task has been observed yet). */
		REFUSED
	}

	/**
	 * Outcome of {@link #observe}, telling the caller whether the session needs attention.
	 */
	public enum ObserveResult
	{
		/** Nothing the caller needs to act on. */
		NONE,
		/** The session's task was completed (the session should be stopped and saved). */
		COMPLETED,
		/** The remaining count dropped to zero without a completion signal (for example, a cancelled task). */
		TASK_CLEARED,
		/** A different task was observed while a session was active (the session should be stopped). */
		TASK_CHANGED
	}

	/** Value used for "no creature id known". */
	public static final int NO_CREATURE = -1;
	/** Value used for "no amount known". */
	public static final int UNKNOWN_AMOUNT = -1;
	/**
	 * A drop to zero followed by the same task within this many zero observations (ticks) is treated as a transient
	 * glitch and the session resumes. Longer gaps are treated as a cancelled-and-reassigned task, unless the assigned
	 * size is unchanged and the remaining count did not go up.
	 */
	public static final int MAX_TRANSIENT_ZERO_OBSERVATIONS = 3;

	/** Maximum ticks a post-login restore check waits for a non-zero task count before running anyway. */
	public static final int RESTORE_SYNC_MAX_TICKS = 10;

	/** SLAYER_TARGET value for boss tasks, from [proc,helper_slayer_current_assignment] (as used by core SlayerPlugin). */
	public static final int BOSS_TASK_TARGET = 98;

	/**
	 * Creature key identifying a task: the SLAYER_TARGET value, or for boss tasks {@code -2 - bossId} so that each
	 * boss is a distinct task even when name lookups fail. Boss keys are always negative and never equal
	 * {@link #NO_CREATURE}.
	 */
	public static int creatureKey(int slayerTarget, int bossId)
	{
		return slayerTarget == BOSS_TASK_TARGET ? -2 - Math.max(0, bossId) : slayerTarget;
	}

	/** Value used for "no account". Matches {@code Client#getAccountHash()} when logged out. */
	public static final long NO_ACCOUNT = -1L;

	/**
	 * Game ticks a completed running session waits for late loot before it is saved (see {@link #holdCompletion()}).
	 * The final kill's loot can arrive on the completion tick after the task count update, or a tick or two later; the
	 * plugin counts the window from the tick after completion, so loot through completion tick + 2 is kept.
	 */
	public static final int COMPLETION_LOOT_GRACE_TICKS = 2;

	/** Default of the "Away after" setting, in minutes (V2 plan 4.1). */
	public static final int DEFAULT_AWAY_MINUTES = 10;
	/** Smallest "Away after" setting, in minutes. */
	public static final int MIN_AWAY_MINUTES = 1;
	/** Largest "Away after" setting, in minutes. */
	public static final int MAX_AWAY_MINUTES = 60;
	/** A time that is not known (no clamp, no kill yet). */
	static final long NO_TIME = Long.MIN_VALUE;
	/**
	 * The supplies warm-up (V2 plan 4.1): a (re)start also counts the supplies buffered this long before the segment
	 * start (a pre-pot, a teleport to the task, potions drunk at the bank), no earlier than the resume point's clamps.
	 */
	static final long WARM_UP_MILLIS = 3 * 60_000L;
	/**
	 * How long after the session's last task kill a known task NPC's loot still counts as that kill's: it is never
	 * taken back by Away, and counts when it arrives while the session is stopped (a Pause or logout just after the
	 * kill). 10 game ticks: a kill's loot arrives within a tick or two of the count's drop. Later loot of the same names
	 * (a Konar or Wilderness task monster killed outside the assigned area, say) is like any other loot.
	 */
	static final long TASK_NPC_LOOT_MILLIS = 10 * 600L;
	/**
	 * {@link #TASK_NPC_LOOT_MILLIS} for Araxxor's loot: 5 minutes. Its drop is rolled only when the player
	 * chooses to Harvest its corpse, which can be well after the kill (OSRS Wiki, "Araxxor": "Choosing the Harvest
	 * option rolls the drop table"; RuneLite 1.13.4's boss timer notes that harvestable Araxxor is not marked dead).
	 */
	static final long ARAXXOR_LOOT_MILLIS = 5 * 60_000L;
	/** Araxxor's name, as {@link TaskStatistics#normalize} keys it: its loot gets {@link #ARAXXOR_LOOT_MILLIS}. */
	private static final String ARAXXOR = TaskStatistics.normalize("Araxxor");
	/** Most bank trips kept as since the last activity ({@link #bankTripsSinceActivity}); plenty. */
	private static final int MAX_COUNTERS_SINCE_ACTIVITY = 256;

	/** The time source, in clock millis. */
	private final LongSupplier clock;

	private State state = State.IDLE;
	/** How long without activity a running session goes Away ({@link #setAwayMinutes}). */
	private long awayMillis = DEFAULT_AWAY_MINUTES * 60_000L;
	/** The logged-in account ({@link #setAccount}), or {@link #NO_ACCOUNT}; a kill starts a session only for one. */
	private long account = NO_ACCOUNT;

	// The current assignment, kept across logins (unlike the observed task) so a login onto the same assignment keeps
	// its clamp and its Ended flag. Only an observation with a task changes it; see noteAssignment.
	private boolean hasAssignment;
	private long assignmentAccount = NO_ACCOUNT;
	private String assignmentMonster;
	private int assignmentCreatureId = NO_CREATURE;
	private int assignmentOriginalAmount = UNKNOWN_AMOUNT;
	/** The lowest count read on the assignment; a higher one is a new assignment. */
	private int assignmentRemaining;
	/** When the current assignment was first seen (a clamp of every resume point), or {@link #NO_TIME}. */
	private long assignmentAt = NO_TIME;
	/** Whether the current assignment was Ended ({@link #endTask}) and not tracked again. */
	private boolean ended;
	/**
	 * When the last session ended, or End task was pressed with no session ({@link #endTask}): a clamp of every resume
	 * point, or {@link #NO_TIME}. Outlives sessions.
	 */
	private long previousSessionEnd = NO_TIME;
	/** Clock time of the latest kill a session counted or (re)started on ({@link #getLastKillAt()}); outlives sessions. */
	private long lastKillAt = NO_TIME;
	/** A drop to zero seen while no session ran, waiting for its completion to start one; or {@code null}. */
	private PendingFirstKill pendingFirstKill;
	/** Readings with a zero count since {@link #pendingFirstKill}. */
	private int pendingFirstKillZeros;
	/** Most known task NPC names a session keeps ({@link #taskNpcNames}). */
	static final int MAX_TASK_NPCS = 32;

	// Latest observed task, kept regardless of session state.
	private boolean taskObserved;
	private String currentMonster;
	private int currentCreatureId = NO_CREATURE;
	private int currentRemaining;
	private int currentOriginalAmount = UNKNOWN_AMOUNT;
	/** Who assigned the latest observed task (master and area), or {@link TaskContext#NONE}. */
	private TaskContext currentContext = TaskContext.NONE;

	// Session task.
	private String sessionId;
	private boolean restoredPending;
	private long sessionAccountHash = NO_ACCOUNT;
	private String sessionMonster;
	private int sessionCreatureId = NO_CREATURE;
	private boolean hasSessionTask;
	private int initialAmount;
	private int originalAmount = UNKNOWN_AMOUNT;
	private int baseline;
	private int kills;
	// Kills from a final drop to zero that is awaiting a completion signal.
	private int pendingFinalKills;
	/**
	 * Whether that drop restarts a stopped session once the completion confirms it, from {@link #pendingFinalPairing}
	 * at {@link #pendingFinalAt}: a drop to zero without a completion may be a cancelled task, so it restarts nothing yet.
	 */
	private boolean pendingFinalRestart;
	private KillPairing pendingFinalPairing = KillPairing.NONE;
	private long pendingFinalAt = NO_TIME;
	private boolean awaitingCompletion;
	// Remaining count just before the drop to zero, and how many zero observations have been seen since.
	private int preZeroBaseline;
	private int zeroObservations;
	private boolean completed;
	/**
	 * NPC loot counted: received while RUNNING, a known task NPC's while stopped, or buffered and counted at a
	 * (re)start.
	 */
	private final ItemTally loot = new ItemTally();
	/** Supplies used while RUNNING, and buffered ones a (re)start counted; potions in doses (see {@link #supplyDoses}). */
	private final ItemTally supplies = new ItemTally();
	/** Doses per item for potion ids in {@link #supplies}. */
	private final Map<Integer, Integer> supplyDoses = new TreeMap<>();
	/** Superior spawns, bank trips and deaths counted while RUNNING; never {@code null} and never unknown here. */
	private SessionCounters counters = SessionCounters.ZERO;
	/** Notable drops of the loot counted, and pets, in the order they arrived; bounded by {@link NotableDrops#add}. */
	private List<NotableDrop> notableDrops = new ArrayList<>();
	/** Boss kill counts while RUNNING, in the order first seen; bounded by {@link BossKillCounts#add}. */
	private List<BossKillCount> bossKillCounts = new ArrayList<>();
	/**
	 * Counted kills per place (map region and Slayer spot), the place killed at most recently last (see
	 * {@link LocationTally}); counted like {@link #kills}. They decide the task's spot ({@link #getTaskSpot}).
	 */
	private List<LocationKills> locationKills = new ArrayList<>();
	/**
	 * Deaths of NPCs the player damaged while RUNNING (and, added once it runs, those paired with the kill that
	 * (re)started it), per NPC name in the order first seen ({@link NpcKillTally}); they decide the task's variant
	 * (its Catacombs variant or Slayer boss) and boss flag ({@link TaskVariants}).
	 */
	private List<NpcKills> npcKills = new ArrayList<>();
	/** Where the player was when {@link #pendingFinalKills} dropped, so they are tallied there when confirmed. */
	private KillPlace pendingFinalPlace = KillPlace.NONE;
	/**
	 * Where the player was at the latest {@link #observe}, or {@link KillPlace#NONE} when unknown or the task was
	 * cleared. Not session data: the panel uses it for the current task's location.
	 */
	private KillPlace currentPlace = KillPlace.NONE;
	/**
	 * The bundled Slayer spot table, which decides the spot of kills tallied by region alone and breaks ties
	 * between spots ({@link LocationTally#decide}); {@link SlayerSpots#NONE} until {@link #setSpots}.
	 */
	private SlayerSpots spots = SlayerSpots.NONE;
	/** The player's note on the session ({@link TaskNote#normalize normalized}), or {@code null}. */
	private String note;
	/** The player's setup overrides on the session ({@link #setSetupOverrides}); never {@code null}. */
	private SetupOverrides setupOverrides = SetupOverrides.NONE;
	/**
	 * The session's setup kill contexts ({@link SetupKills}); never {@code null}. Kept across a restore; one is counted
	 * per task kill ({@link #addKillContext}).
	 */
	private SetupKills setupKills = SetupKills.NONE;
	/**
	 * Task kills the session counted before it recorded kill contexts: every kill of a session restored from a 1.x
	 * active-session file, which recorded none ({@link SessionSnapshot#killsWithoutContexts}). They are left out of the
	 * cannon share ({@link #contextKills}), so a cannon task a 1.x version started stays one after its next kill. 0 for a
	 * 2.0 session; kept across a restore.
	 */
	private int killsBeforeContexts;
	/**
	 * XP gained per skill while RUNNING, and buffered XP a (re)start counted ({@link #observeXp}), keyed as
	 * {@link SkillXp} keys them.
	 */
	private final Map<String, Long> xpGained = new TreeMap<>();
	/**
	 * The latest XP reading of every skill ({@link #observeXp}), or {@code null} after {@link #resetXpBaseline()} or an
	 * unsynced reading. Kept whatever the state, so it is always the baseline for the next reading: XP gained outside a
	 * segment is buffered ({@link #buffer}) while a task is assigned and not Ended, and otherwise (no task, Ended, a
	 * held completion's grace window) is never counted.
	 */
	private Map<String, Integer> xpReading;
	/**
	 * The session task's assignment, and once the task is completed the points earned and streak (see
	 * {@link #setCompletionRewards}), or {@link TaskContext#NONE}.
	 */
	private TaskContext sessionContext = TaskContext.NONE;

	/** Time of the closed segments. */
	private long accumulatedMillis;
	/** Start of the open segment (while RUNNING). */
	private long segmentStart;
	/** Close of the session's previous segment (a clamp of the next resume point), or {@link #NO_TIME}. */
	private long lastSegmentClose = NO_TIME;
	/** The open segment's latest task kill or hit on a known task NPC; Away counts from it (or the segment start). */
	private long lastActivity = NO_TIME;
	/** Clock time of the kill that opened the current segment, or {@link #NO_TIME}; {@link #pairKill} may backdate it. */
	private long restartKillAt = NO_TIME;
	/** The clamp the current segment's resume point was held to; a later backdating keeps to it too. */
	private long restartFloor = NO_TIME;
	/** The state {@link #stop()} stopped the session from, for its snapshot ({@link SegmentInfo#getState()}). */
	private State stoppedFrom = State.IDLE;
	/** The end of the session before this one when this one started (a clamp, persisted), or {@link #NO_TIME}. */
	private long priorSessionEnd = NO_TIME;
	/** Normalized names of the NPCs paired with the session's kills: its known task NPCs (V2 plan 4.1). */
	private final Set<String> taskNpcNames = new LinkedHashSet<>();
	/**
	 * Supplies, XP and loot outside segments while a task is assigned and not Ended ({@link #isBuffering()}), and what
	 * Away took back; a (re)start counts part of it ({@link #countBuffered}). Not session data: it belongs to the
	 * assignment, so a session's start can count it, and it is forgotten at a logout or account change
	 * ({@link #clearCurrentTask}) and at End task ({@link #endTask}). The resume point's clamps keep anything from before
	 * them out.
	 */
	private final TimedUsage buffer = new TimedUsage();
	/**
	 * The open segment's supplies, XP and loot since its last activity, as they were added to the totals: what Away
	 * takes back ({@link #takeBackSince}). Pets and loot of known task NPCs are never in it.
	 */
	private final TimedUsage sinceActivity = new TimedUsage();
	/**
	 * Clock times of the bank trips counted in the open segment since its last activity, oldest first: Away takes them
	 * back like the supplies (project-manager decision: they belong to whatever the player went off to
	 * do). Unlike supplies they are dropped, never buffered: a bank trip counts only while the clock runs. Deaths are
	 * never taken back (project-manager decision): a death usually lands a few ticks after the last
	 * hit, and a long recovery after it shouldn't erase a real task death.
	 */
	private final ArrayDeque<Long> bankTripsSinceActivity = new ArrayDeque<>();
	/** Whether the player is inside the Fight Caves or the Inferno on that task ({@link #setInTaskCave}). */
	private boolean inTaskCave;
	private long startedAt;
	private long endedAt;

	/** Completed session held back from saving for late loot, or {@code null}. Independent of {@link #state}. */
	private Summary pendingCompletion;
	/** Game ticks left before {@link #pendingCompletion} is released by {@link #tickCompletion()}. */
	private int pendingCompletionTicks;
	/**
	 * When the held completion's last segment was opened by its final kill ({@link #restartKillAt}), that kill's time,
	 * the segment's start and its clamp, so {@link #pairKill} can still backdate it; else {@link #NO_TIME}.
	 */
	private long pendingRestartKillAt = NO_TIME;
	private long pendingSegmentStart;
	private long pendingRestartFloor = NO_TIME;
	/** The held completion's final kill ({@link #lastKillAt} when it was held), for {@link #addHeldNpcKill}. */
	private long pendingKillAt = NO_TIME;
	/** Whether the latest task kill ({@link #lastKillAt}) was paired with Araxxor's death. */
	private boolean lastKillAraxxor;
	/**
	 * Whether the held completion's final kill was paired with Araxxor's death, on its tick or the tick after
	 * ({@link #pairKill}): its record then waits for the harvest ({@link #takeHarvestRecord}).
	 */
	private boolean pendingKillAraxxor;
	/**
	 * Clock time of the latest Araxxor loot ({@link #addLoot(ItemTally, List, String)}), whatever its items (none kept
	 * after the bonecrusher and Ignored loot, too) and wherever it went, or {@link #NO_TIME}; outlives sessions. Loot at
	 * or after a held completion's final kill was that kill's harvest, so no harvest window opens for it.
	 */
	private long lastAraxxorLootAt = NO_TIME;
	/**
	 * The Araxxor harvest window: the id of the record of a task whose final kill was Araxxor, from when its held
	 * completion was released for saving ({@link #tickCompletion}) until its harvest ({@link #takeHarvestRecord}), or
	 * {@code null}. Araxxor drops its loot only when the player harvests its corpse, which can come after the save.
	 */
	private String harvestRecordId;
	/** The account of {@link #harvestRecordId}'s task. */
	private long harvestAccount = NO_ACCOUNT;
	/** The final kill of {@link #harvestRecordId}'s task; the window lasts {@link #ARAXXOR_LOOT_MILLIS} from it. */
	private long harvestKillAt = NO_TIME;
	/**
	 * Creature keys of tasks a session took (adopted or restored) since the last {@link #takeSessionTaskKeys()}, so a
	 * session started and ended between two calls is still reported.
	 */
	private final Set<Integer> takenTaskKeys = new HashSet<>();

	public SessionTracker(LongSupplier clock)
	{
		this.clock = Objects.requireNonNull(clock);
	}

	/** The tracker's clock now (clock millis); the plugin stamps the player's hits and NPC deaths with it. */
	public synchronized long now()
	{
		return clock.getAsLong();
	}

	/**
	 * The "Away after" setting: a running session with no task kill and no hit on a known task NPC for this many
	 * minutes goes Away ({@link #checkAway}). Clamped to {@link #MIN_AWAY_MINUTES} to {@link #MAX_AWAY_MINUTES}.
	 */
	public synchronized void setAwayMinutes(int minutes)
	{
		awayMillis = Math.max(MIN_AWAY_MINUTES, Math.min(MAX_AWAY_MINUTES, minutes)) * 60_000L;
	}

	/** The Away limit in millis; also the longest gap within one engagement ({@link DamagedNpcs}). */
	public synchronized long getAwayMillis()
	{
		return awayMillis;
	}

	/**
	 * The logged-in account, or {@link #NO_ACCOUNT}. A kill starts a session only for a known account, and the
	 * assignment it belongs to is remembered per account.
	 */
	public synchronized void setAccount(long accountHash)
	{
		account = accountHash;
	}

	/**
	 * Test seam: starts a session at once for the given account, as the old Play did: from {@code IDLE} it adopts the
	 * observed task (or the first one observed later) and opens a segment now; from {@code AWAY}, {@code PAUSED} or
	 * {@code LOGGED_OUT} it opens one now, as a kill restart with nothing paired would. Lets tests whose subject is not
	 * how a session starts begin one without a kill. Like Play, it counts nothing from before it: the buffer outside
	 * segments is dropped, with no warm-up. Refused until the task has been observed for the current login, for an
	 * Ended assignment, and for another account's session.
	 */
	synchronized boolean startNow(long accountHash)
	{
		if (accountHash == NO_ACCOUNT || !taskObserved)
		{
			return false;
		}
		final long now = clock.getAsLong();
		if (state == State.IDLE)
		{
			if (ended)
			{
				return false;
			}
			sessionId = UUID.randomUUID().toString();
			sessionAccountHash = accountHash;
			priorSessionEnd = previousSessionEnd;
			startedAt = now;
			openSegmentNow(now);
			buffer.clear();
			if (currentRemaining > 0)
			{
				adoptCurrentTask();
			}
			return true;
		}
		if (state.isClockStopped() && accountHash == sessionAccountHash)
		{
			openSegmentNow(now);
			buffer.clear();
			return true;
		}
		return false;
	}

	/** Whether {@link #resume} would succeed for the given account: the session is Paused and the account's. */
	public synchronized boolean canResume(long accountHash)
	{
		return state == State.PAUSED && accountHash != NO_ACCOUNT && accountHash == sessionAccountHash && taskObserved;
	}

	/**
	 * Resume (the player's, while Paused): opens a segment at once, a restart, so the supplies buffered in the warm-up
	 * before it count ({@link #restartNow}).
	 */
	public synchronized boolean resume(long accountHash)
	{
		if (!canResume(accountHash))
		{
			return false;
		}
		restartNow(clock.getAsLong());
		return true;
	}

	/**
	 * Pauses a running session: its segment closes now.
	 */
	public synchronized boolean pause()
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		closeSegment(clock.getAsLong());
		state = State.PAUSED;
		return true;
	}

	/**
	 * A logout or lost connection stops the session: a running segment closes now, and the next task kill after a
	 * login restarts it (a login is not a restart). An Away or Paused session becomes Logged out too.
	 *
	 * @return whether the state changed
	 */
	public synchronized boolean loggedOut()
	{
		if (!state.isActive() || state == State.LOGGED_OUT)
		{
			return false;
		}
		if (state == State.RUNNING)
		{
			closeSegment(clock.getAsLong());
		}
		state = State.LOGGED_OUT;
		return true;
	}

	/**
	 * Away (V2 plan 4.1): once {@code awayMinutes} have passed since the running session's last activity (its latest
	 * task kill or own hit on a known task NPC, or the segment's start), the segment closes at that last activity, so
	 * the clock steps back once, and the session waits for the next task kill. The supplies, XP and loot added since
	 * the last activity are taken back out of the totals into the buffer ({@link #takeBackSince}), and so are the bank
	 * trips since then, which are dropped; the last kill's own XP (on its tick), loot of its known task NPCs
	 * ({@link #TASK_NPC_LOOT_MILLIS}), deaths and superiors stay. Never inside the Fight Caves or the Inferno on that task
	 * ({@link #setInTaskCave}). Called every settled tick.
	 *
	 * @return whether the session went Away
	 */
	public synchronized boolean checkAway()
	{
		if (state != State.RUNNING || inTaskCave)
		{
			return false;
		}
		final long last = Math.max(segmentStart, lastActivity);
		if (clock.getAsLong() - last < awayMillis)
		{
			return false;
		}
		takeBackSince(last);
		takeBackBankTripsSince(last);
		closeSegment(last);
		state = State.AWAY;
		return true;
	}

	/**
	 * Jad and Zuk tasks (V2 plan 4.1): whether the player is inside the Fight Caves or the Inferno with that task
	 * assigned ({@link TaskCaves#isInside}), read every settled tick. Inside is Running:
	 * <ul>
	 * <li>entering, or being inside with a session waiting to restart (after a login inside, or a client restart's
	 * restore), opens a segment at once: a restart ({@link #restartNow}, with the warm-up), or the start of a session on
	 * an assignment waiting for its first kill. A session the player paused inside stays Paused until they Resume or
	 * enter again;</li>
	 * <li>leaving, also after a death, closes the segment now and keeps what came before; the session waits Away for
	 * the next entry (or task kill). A logout inside closes it as any logout does ({@link #loggedOut});</li>
	 * <li>Away never starts inside ({@link #checkAway}).</li>
	 * </ul>
	 *
	 * @param inside       whether the player is inside the assigned task's cave now
	 * @param startAllowed whether a new session may start now (not while a restore check is pending, as for a kill)
	 * @return whether a segment opened or closed
	 */
	public synchronized boolean setInTaskCave(boolean inside, boolean startAllowed)
	{
		final boolean entered = inside && !inTaskCave;
		final boolean left = !inside && inTaskCave;
		inTaskCave = inside;
		final long now = clock.getAsLong();
		if (left)
		{
			if (state != State.RUNNING)
			{
				return false;
			}
			closeSegment(now);
			state = State.AWAY;
			return true;
		}
		if (!inside || state == State.RUNNING || (state == State.PAUSED && !entered))
		{
			return false;
		}
		if (state.isClockStopped())
		{
			if (!isSessionOnCurrentTask())
			{
				return false;
			}
			restartNow(now);
			return true;
		}
		if (state != State.IDLE || !taskObserved || currentRemaining <= 0 || account == NO_ACCOUNT || ended
			|| !startAllowed)
		{
			return false;
		}
		clearSession();
		sessionId = UUID.randomUUID().toString();
		sessionAccountHash = account;
		priorSessionEnd = previousSessionEnd;
		adoptCurrentTask();
		restartNow(now);
		startedAt = segmentStart;
		return true;
	}

	/**
	 * The player hit an NPC named {@code name}: activity for Away when it is one of the session's known task NPCs (the
	 * names paired with its kills) and the session is running.
	 *
	 * @return whether it counted as activity
	 */
	public synchronized boolean taskNpcHit(String name)
	{
		final String key = TaskStatistics.normalize(name);
		if (state != State.RUNNING || key == null || !taskNpcNames.contains(key))
		{
			return false;
		}
		lastActivity = Math.max(lastActivity, clock.getAsLong());
		return true;
	}

	/**
	 * A bracelet of slaughter's activation: a task kill that left the count unchanged (V2 plan 4.1). It is activity:
	 * it resets the Away clock of a running session, restarts a stopped one at its resume point, and starts a session
	 * on an assignment waiting for its first kill. It counts no kill: the kills follow the task count.
	 *
	 * @param pairing the NPCs that died around the activation
	 * @return whether it counted (for a session, or started one)
	 */
	public synchronized boolean braceletKill(KillPairing pairing)
	{
		final KillPairing kill = pairing == null ? KillPairing.NONE : pairing;
		final long now = clock.getAsLong();
		if (state == State.RUNNING)
		{
			noteKill(now, kill);
			return true;
		}
		if (state.isClockStopped() && isSessionOnCurrentTask())
		{
			openSegmentAtKill(kill, now);
			noteKill(now, kill);
			return true;
		}
		if (state == State.IDLE && taskObserved && currentRemaining > 0 && canStart(kill))
		{
			startSession(currentMonster, currentCreatureId, currentOriginalAmount, currentContext, currentRemaining,
				kill, now);
			return true;
		}
		return false;
	}

	/**
	 * The NPCs that died around a task kill, once all of them are known (deaths on the tick after the kill included):
	 * their names become known task NPCs, and when that kill (re)started the session, its segment is backdated to their
	 * earliest engagement start if that is earlier, still clamped as the restart was, and the buffered XP and loot from
	 * the new start and supplies from the warm-up before it are counted too. A completed session held for late loot is
	 * backdated the same way when its final kill restarted it. This is the restart's final pairing, so the rest of the
	 * buffer is dropped (V2 plan 4.1). A held completion's final kill paired with Araxxor's death waits for its harvest
	 * once it is saved ({@link #takeHarvestRecord}).
	 *
	 * @param killAt  the kill's clock time ({@link #getLastKillAt()} just after it)
	 * @param pairing the NPCs that died from 2 ticks before the kill to 1 tick after
	 */
	public synchronized void pairKill(long killAt, KillPairing pairing)
	{
		if (pairing == null || killAt == NO_TIME)
		{
			return;
		}
		if (state.isActive() && lastKillAt == killAt)
		{
			learnTaskNpcs(pairing);
		}
		if (pendingCompletion != null && pendingKillAt == killAt && pairsAraxxor(pairing))
		{
			pendingKillAraxxor = true;
		}
		if (state == State.RUNNING && restartKillAt == killAt)
		{
			final long backdated = pairing.hasStart()
				? Math.max(restartFloor, Math.min(segmentStart, pairing.getEarliestStart())) : segmentStart;
			if (backdated < segmentStart)
			{
				if (startedAt == segmentStart)
				{
					startedAt = backdated;
				}
				segmentStart = backdated;
				countBuffered(restartFloor, backdated);
			}
			buffer.clear();
		}
		else if (pendingCompletion != null && pendingRestartKillAt == killAt)
		{
			final long backdated = pairing.hasStart() ? Math.max(pendingRestartFloor,
				Math.min(pendingSegmentStart, pairing.getEarliestStart())) : pendingSegmentStart;
			if (backdated < pendingSegmentStart)
			{
				pendingCompletion = pendingCompletion.backdated(pendingSegmentStart - backdated, pendingSegmentStart)
					.withCounted(buffer.take(warmUpFrom(pendingRestartFloor, backdated), backdated));
				pendingSegmentStart = backdated;
			}
			buffer.clear();
		}
	}

	/** Clock time of the latest task kill a session counted or (re)started on, or {@link #NO_TIME}. */
	public synchronized long getLastKillAt()
	{
		return lastKillAt;
	}

	/**
	 * Whether End task would do something: a session exists, or the observed assignment waits for its first kill.
	 */
	public synchronized boolean canEndTask()
	{
		return state.isActive() || (state == State.IDLE && !ended && taskObserved && currentRemaining > 0);
	}

	/**
	 * End task (V2 plan 4.1): stops the session, if any, and marks its assignment Ended, so no kill on it starts a
	 * session again until {@link #trackAgain}. Without a session, an assignment waiting for its first kill is marked
	 * Ended. Decided in one call, so a kill can't restart the session in between. Either way nothing from before it
	 * counts after Track again: the buffer outside segments is dropped, and End task is the next resume point's clamp
	 * ({@link #previousSessionEnd}), as a session's end is.
	 *
	 * @return the stopped session's summary (to save through Keep / Discard), or {@code null} when none was active
	 */
	public synchronized Summary endTask()
	{
		if (!canEndTask())
		{
			return null;
		}
		final long now = clock.getAsLong();
		if (!hasAssignment && hasSessionTask)
		{
			// A session started without a task observed for this login (a test seam's): its own task is the assignment.
			setAssignment(sessionAccountHash, sessionMonster, sessionCreatureId, originalAmount, baseline, now);
		}
		ended = true;
		buffer.clear();
		if (!state.isActive())
		{
			// No session to stop (whose end would be the clamp): the wait for the first kill ends here.
			previousSessionEnd = now;
			return null;
		}
		return stopAndReset();
	}

	/** Track again: an Ended assignment waits for its first kill again. */
	public synchronized boolean trackAgain()
	{
		if (!ended)
		{
			return false;
		}
		ended = false;
		return true;
	}

	/**
	 * The account of the Ended assignment, whose marker ({@link #endedMarker}) a logout or shutdown may have persisted,
	 * or {@link #NO_ACCOUNT} when the assignment isn't Ended.
	 */
	public synchronized long getEndedAccount()
	{
		return ended && hasAssignment ? assignmentAccount : NO_ACCOUNT;
	}

	/**
	 * What the overlay and panel show: the session's state, or without one whether the observed assignment waits for its
	 * first kill or was Ended. A Logged out session reads {@link Status#WAITING_FOR_NEXT_KILL} once the task has been
	 * read after the next login.
	 */
	public synchronized Status getStatus()
	{
		switch (state)
		{
			case RUNNING:
				return Status.RUNNING;
			case AWAY:
				return Status.AWAY;
			case PAUSED:
				return Status.PAUSED;
			case LOGGED_OUT:
				return taskObserved ? Status.WAITING_FOR_NEXT_KILL : Status.LOGGED_OUT;
			default:
				break;
		}
		if (ended && (!taskObserved || currentRemaining > 0))
		{
			return Status.ENDED;
		}
		return taskObserved && currentRemaining > 0 ? Status.WAITING_FOR_FIRST_KILL : Status.NO_TASK;
	}

	/**
	 * The Ended assignment as a marker snapshot ({@link SessionSnapshot#isEndedMarker()}) for the active-session file,
	 * so a client restart keeps it Ended; {@code null} when the assignment isn't Ended.
	 */
	public synchronized SessionSnapshot endedMarker(int[] completionCounters, long savedAt)
	{
		if (!ended || !hasAssignment || assignmentAccount == NO_ACCOUNT)
		{
			return null;
		}
		final SessionSnapshot marker = new SessionSnapshot();
		marker.setSessionId(SessionSnapshot.ENDED_ID_PREFIX + UUID.randomUUID());
		marker.setAccountHash(assignmentAccount);
		marker.setMonster(assignmentMonster);
		marker.setCreatureId(assignmentCreatureId);
		marker.setOriginalAmount(assignmentOriginalAmount == UNKNOWN_AMOUNT ? null : assignmentOriginalAmount);
		marker.setInitialAmount(assignmentRemaining);
		marker.setRemaining(assignmentRemaining);
		marker.setCompletionCounters(completionCounters == null ? null
			: Arrays.copyOf(completionCounters, completionCounters.length));
		marker.setStartedAt(savedAt);
		marker.setSavedAt(savedAt);
		marker.setTrackingState(SessionSnapshot.ENDED_STATE);
		marker.setAssignedAt(assignmentAt == NO_TIME ? null : assignmentAt);
		marker.setPreviousSessionEnd(previousSessionEnd == NO_TIME ? null : previousSessionEnd);
		return marker;
	}

	/**
	 * Restores an Ended assignment from its marker ({@link #endedMarker}) when it matches the observed task, as
	 * {@link #restore} checks a session. Nothing else is restored.
	 */
	public synchronized RestoreResult restoreEnded(SessionSnapshot marker, int[] currentCompletionCounters)
	{
		if (state != State.IDLE || !taskObserved)
		{
			return RestoreResult.REFUSED;
		}
		if (!matchesCurrentTask(marker, currentCompletionCounters))
		{
			return RestoreResult.MISMATCH;
		}
		ended = true;
		if (marker.getAssignedAt() != null)
		{
			assignmentAt = marker.getAssignedAt();
		}
		if (marker.getPreviousSessionEnd() != null)
		{
			previousSessionEnd = Math.max(previousSessionEnd, marker.getPreviousSessionEnd());
		}
		return RestoreResult.RESTORED;
	}

	/**
	 * Forgets the latest observed task (for example on logout or account change) so stale data is not shown or
	 * adopted, and the next {@link #observe} only sets the baselines (it is never a kill). The buffer outside segments
	 * goes with it, as the player's hits do, so nothing from before a logout or from another account is counted, and so
	 * does whether the player was inside a task's cave. The active session, if any, and the current assignment (with
	 * its Ended flag) are unaffected.
	 */
	public synchronized void clearCurrentTask()
	{
		buffer.clear();
		inTaskCave = false;
		taskObserved = false;
		currentMonster = null;
		currentCreatureId = NO_CREATURE;
		currentRemaining = 0;
		currentOriginalAmount = UNKNOWN_AMOUNT;
		currentContext = TaskContext.NONE;
		currentPlace = KillPlace.NONE;
	}

	/**
	 * Stops an active session (its running segment closes now). Use {@link #summary()} to read the result, then
	 * {@link #reset()}. Its end is the next session's clamp ({@link #previousSessionEnd}).
	 */
	public synchronized boolean stop()
	{
		if (!state.isActive())
		{
			return false;
		}
		long now = clock.getAsLong();
		stoppedFrom = state;
		if (state == State.RUNNING)
		{
			closeSegment(now);
		}
		endedAt = now;
		previousSessionEnd = now;
		state = State.STOPPED;
		return true;
	}

	/**
	 * Returns a stopped tracker to IDLE. The latest observed task is kept so it can be shown and adopted by the
	 * next session.
	 */
	public synchronized boolean reset()
	{
		if (state != State.STOPPED)
		{
			return false;
		}
		state = State.IDLE;
		clearSession();
		return true;
	}

	/**
	 * Atomically stops an active session, captures its summary and returns to IDLE.
	 *
	 * @return the stopped session's summary, or {@code null} if no session was active
	 */
	public synchronized Summary stopAndReset()
	{
		if (!stop())
		{
			return null;
		}
		Summary summary = summary();
		reset();
		return summary;
	}

	/**
	 * Atomically stops and resets the active session only if it belongs to an account other than the given one.
	 *
	 * @return the stopped session's summary, or {@code null} if nothing was stopped
	 */
	public synchronized Summary stopAndResetIfOtherAccount(long accountHash)
	{
		if (!state.isActive() || sessionAccountHash == accountHash)
		{
			return null;
		}
		return stopAndReset();
	}

	/**
	 * Whether a snapshot matches the latest observed task closely enough to be restored: same creature key, a task
	 * is active, the remaining count has not gone up, the assigned size has not changed (when both are known), and
	 * no task-completion counter has changed since the snapshot (when both are known). See
	 * {@link #counterChanged(int, int)}.
	 */
	public synchronized boolean matchesCurrentTask(SessionSnapshot snapshot, int[] currentCompletionCounters)
	{
		if (!taskObserved || currentRemaining <= 0 || currentCreatureId != snapshot.getCreatureId()
			|| currentRemaining > snapshot.getRemaining())
		{
			return false;
		}
		Integer savedOriginal = snapshot.getOriginalAmount();
		if (savedOriginal != null && currentOriginalAmount != UNKNOWN_AMOUNT && savedOriginal != currentOriginalAmount)
		{
			return false;
		}
		int[] saved = snapshot.getCompletionCounters();
		if (saved != null && currentCompletionCounters != null && saved.length == currentCompletionCounters.length)
		{
			for (int i = 0; i < saved.length; i++)
			{
				if (counterChanged(saved[i], currentCompletionCounters[i]))
				{
					return false;
				}
			}
		}
		return true;
	}

	/**
	 * For a session kept in memory across a logout: whether it still matches the task observed after the next login,
	 * using the same checks as {@link #restore}. Returns {@code true} (nothing to do) if no session is active or the
	 * active session is not the one in the snapshot.
	 */
	public synchronized boolean activeSessionStillMatches(SessionSnapshot logoutSnapshot, int[] currentCompletionCounters)
	{
		if (!state.isActive() || logoutSnapshot == null
			|| !Objects.equals(sessionId, logoutSnapshot.getSessionId()))
		{
			return true;
		}
		return matchesCurrentTask(logoutSnapshot, currentCompletionCounters);
	}

	/**
	 * Whether one task-completion counter shows a change since a snapshot. An increase means a task was completed;
	 * a decrease to a non-zero value means the streak changed (for example a Turael reset or cancellation). A counter
	 * that reads zero now but was non-zero in the snapshot is treated as not yet synced (unknown), not a decrease.
	 */
	static boolean counterChanged(int saved, int current)
	{
		if (current == 0 && saved != 0)
		{
			return false;
		}
		return current != saved;
	}

	/**
	 * Whether a post-login restore / re-login check should wait another tick: the task count may not be synced yet
	 * while it reads zero, so the check is deferred until it is positive, for at most
	 * {@link #RESTORE_SYNC_MAX_TICKS} ticks (after which it runs anyway and a zero count is a mismatch).
	 *
	 * @param remaining    the task count read this tick
	 * @param ticksWaited  how many ticks the check has already been deferred
	 */
	public static boolean shouldDeferRestoreCheck(int remaining, int ticksWaited)
	{
		return remaining <= 0 && ticksWaited < RESTORE_SYNC_MAX_TICKS;
	}

	/**
	 * Restores a persisted session as LOGGED_OUT (V2 plan 4.1: as after a logout, so the next task kill restarts it) if
	 * it matches the latest observed task. Kills, active time and the clamps are kept; the kill baseline is the current
	 * remaining count, so kills made while untracked are not counted. A 1.x file (no segment fields) closes its last
	 * segment when it was saved, and its kills, which recorded no kill context, are left out of the cannon share
	 * ({@link #killsBeforeContexts}).
	 */
	public synchronized RestoreResult restore(SessionSnapshot snapshot, int[] currentCompletionCounters)
	{
		if (state != State.IDLE || !taskObserved)
		{
			return RestoreResult.REFUSED;
		}
		if (snapshot.getAccountHash() == NO_ACCOUNT || !matchesCurrentTask(snapshot, currentCompletionCounters))
		{
			return RestoreResult.MISMATCH;
		}
		clearSession();
		state = State.LOGGED_OUT;
		restoredPending = true;
		lastSegmentClose = snapshot.getSegmentClosedAt() != null ? snapshot.getSegmentClosedAt() : snapshot.getSavedAt();
		if (snapshot.getAssignedAt() != null)
		{
			assignmentAt = snapshot.getAssignedAt();
		}
		if (snapshot.getPreviousSessionEnd() != null)
		{
			previousSessionEnd = Math.max(previousSessionEnd, snapshot.getPreviousSessionEnd());
		}
		priorSessionEnd = previousSessionEnd;
		if (snapshot.getTaskNpcs() != null)
		{
			for (String name : snapshot.getTaskNpcs())
			{
				learnTaskNpc(name);
			}
		}
		sessionId = snapshot.getSessionId() != null ? snapshot.getSessionId() : UUID.randomUUID().toString();
		sessionAccountHash = snapshot.getAccountHash();
		sessionMonster = snapshot.getMonster() != null ? snapshot.getMonster() : currentMonster;
		sessionCreatureId = snapshot.getCreatureId();
		hasSessionTask = true;
		takenTaskKeys.add(sessionCreatureId);
		initialAmount = snapshot.getInitialAmount();
		originalAmount = snapshot.getOriginalAmount() != null ? snapshot.getOriginalAmount() : currentOriginalAmount;
		baseline = currentRemaining;
		kills = Math.max(0, snapshot.getKills());
		loot.merge(ItemTally.fromMap(snapshot.getLoot()));
		supplies.merge(ItemTally.fromMap(snapshot.getSupplies()));
		putDoses(supplyDoses, snapshot.getSupplyDoses());
		// A snapshot from before these were counted has none; counting starts from the restore.
		counters = SessionCounters.from(snapshot).withUnknownAsZero();
		// A snapshot from before notable drops were kept has none.
		notableDrops = NotableDrops.sanitize(snapshot.getNotableDrops());
		// Likewise for boss kill counts.
		bossKillCounts = BossKillCounts.sanitize(snapshot.getBossKillCounts());
		// Likewise for the kills per place; a snapshot without them tallies from the restore. A tally kept before spots
		// has regions only: their spots are decided from the regions.
		locationKills = LocationTally.sanitize(snapshot.getLocationKills());
		// Likewise for the kills per NPC name; a snapshot without them tallies from the restore.
		npcKills = NpcKillTally.sanitize(snapshot.getNpcKills());
		note = TaskNote.normalize(snapshot.getNote());
		// A snapshot from before setup tags has no overrides and no kill contexts.
		setupOverrides = SetupOverrides.from(snapshot);
		setupKills = SetupKills.from(snapshot);
		// A 1.x file's kills recorded no context: they are left out of the cannon share.
		killsBeforeContexts = Math.min(kills, snapshot.killsWithoutContexts());
		// A snapshot from before XP was tracked has none; counting starts from the restore.
		SkillXp.add(xpGained, snapshot.getXpGained());
		// The snapshot matched the current task, so the current reading fills what an older snapshot lacks.
		sessionContext = TaskContext.of(snapshot.getSlayerMaster(), snapshot.getSlayerArea(),
			snapshot.getTaskLocation(), null, null).fillAssignment(currentContext);
		accumulatedMillis = Math.max(0, snapshot.getActiveMillis());
		startedAt = snapshot.getStartedAt();
		return RestoreResult.RESTORED;
	}

	/**
	 * Stops a RUNNING session whose task was just completed and holds it back from saving for
	 * {@link #COMPLETION_LOOT_GRACE_TICKS} game ticks, so late loot from the final kill is still recorded. The kills,
	 * active time and end time are frozen now and the tracker returns to {@code IDLE} at once.
	 *
	 * <p>Refused (returns {@code false}, nothing changes) unless the session is RUNNING and completed, or if another
	 * completed session is already held. A final kill restarts a stopped session before it completes it, so a completion
	 * is normally RUNNING; one that isn't (it completed without a kill being seen) is saved immediately as before.</p>
	 *
	 * @return whether the session is now held; if {@code false} the caller should end and save it as usual
	 */
	public synchronized boolean holdCompletion()
	{
		if (state != State.RUNNING || !completed || pendingCompletion != null)
		{
			return false;
		}
		// The final kill may have opened the last segment; its pairing may still backdate it (pairKill).
		final long restartAt = restartKillAt;
		final long floor = restartFloor;
		final long start = segmentStart;
		pendingCompletion = stopAndReset();
		pendingCompletionTicks = COMPLETION_LOOT_GRACE_TICKS;
		pendingRestartKillAt = restartAt;
		pendingRestartFloor = floor;
		pendingSegmentStart = start;
		pendingKillAt = lastKillAt;
		pendingKillAraxxor = lastKillAraxxor;
		return true;
	}

	/**
	 * Counts down the held completed session by one game tick. Call once per game tick. When the grace window ends and
	 * the final kill was paired with Araxxor's death, and no Araxxor loot came since that kill (before the completion
	 * was held or while it was, and whatever its items: {@link #lastAraxxorLootAt}), Araxxor's harvest window opens for
	 * the session's record ({@link #takeHarvestRecord}): Araxxor drops its loot only when the player harvests its
	 * corpse.
	 *
	 * @return the held session's final summary once its grace window has ended (it is no longer held), otherwise
	 *         {@code null}
	 */
	public synchronized Summary tickCompletion()
	{
		if (pendingCompletion == null)
		{
			return null;
		}
		pendingCompletionTicks--;
		if (pendingCompletionTicks > 0)
		{
			return null;
		}
		final long killAt = pendingKillAt;
		final boolean harvested = lastAraxxorLootAt != NO_TIME && lastAraxxorLootAt >= killAt;
		final boolean awaitsHarvest = pendingKillAraxxor && !harvested && pendingCompletion.isCompleted()
			&& pendingCompletion.getSessionId() != null;
		final Summary summary = releasePendingCompletion();
		if (awaitsHarvest)
		{
			harvestRecordId = summary.getSessionId();
			harvestAccount = summary.getAccountHash();
			harvestKillAt = killAt;
		}
		return summary;
	}

	/**
	 * Releases the held completed session at once (for example on logout, hop, account change, End task or shutdown).
	 * Each held session is returned exactly once, by this method or {@link #tickCompletion()}. Every one of those paths
	 * also ends Araxxor's harvest window, released early or not: a logout, a lost connection or a hop leaves the
	 * corpse behind, and the others end the task's tracking.
	 *
	 * @return the held session's summary (including loot received so far), or {@code null} if none is held
	 */
	public synchronized Summary takePendingCompletion()
	{
		endHarvestWindow();
		return releasePendingCompletion();
	}

	/** Hands out the held completed session, if any, and forgets it. */
	private Summary releasePendingCompletion()
	{
		final Summary summary = pendingCompletion;
		pendingCompletion = null;
		pendingCompletionTicks = 0;
		pendingRestartKillAt = NO_TIME;
		pendingRestartFloor = NO_TIME;
		pendingKillAt = NO_TIME;
		pendingKillAraxxor = false;
		return summary;
	}

	/**
	 * Araxxor's harvest after its task was saved: whether loot of {@code npcName} arriving now for
	 * {@code accountHash} is the harvest of the Araxxor kill that completed the task saved last, and if so the id of that
	 * task's record, which the loot is added to instead of {@link #addLoot(ItemTally, List, String)}. That is Araxxor's
	 * loot within {@link #ARAXXOR_LOOT_MILLIS} of that final kill, for the same account, with no task kill since. Any
	 * Araxxor loot ends the window, so a harvest is added once; so does every early release of a held completion
	 * ({@link #takePendingCompletion}: a logout, hop or account change).
	 *
	 * @param accountHash the logged-in account
	 * @param npcName     the name of the NPC the loot came from, or {@code null} when not known
	 * @return the record's id, or {@code null} when the loot is not that harvest (it is then loot like any other)
	 */
	public synchronized String takeHarvestRecord(long accountHash, String npcName)
	{
		if (harvestRecordId == null || !isAraxxor(npcName))
		{
			return null;
		}
		final String id = harvestRecordId;
		final long since = clock.getAsLong() - harvestKillAt;
		final boolean harvest = accountHash != NO_ACCOUNT && accountHash == harvestAccount
			&& lastKillAt == harvestKillAt && pendingCompletion == null && since >= 0 && since <= ARAXXOR_LOOT_MILLIS;
		endHarvestWindow();
		return harvest ? id : null;
	}

	/** Ends Araxxor's harvest window, if one is open. */
	private void endHarvestWindow()
	{
		harvestRecordId = null;
		harvestAccount = NO_ACCOUNT;
		harvestKillAt = NO_TIME;
	}

	/** Whether a completed session is being held for late loot. */
	public synchronized boolean hasPendingCompletion()
	{
		return pendingCompletion != null;
	}

	/**
	 * Creature keys of the tasks a session held since the previous call: the active (or just stopped) session's task,
	 * a completed session held for late loot, and any task a session took since then, even if that session has ended
	 * already. {@link AssignmentWatch} uses them, once per settled tick, to tell played assignments from ones that
	 * ended without a session. Decided in one call, so a Resume click can't fall between two reads.
	 */
	public synchronized Set<Integer> takeSessionTaskKeys()
	{
		final Set<Integer> keys = new HashSet<>(takenTaskKeys);
		takenTaskKeys.clear();
		if (state != State.IDLE && hasSessionTask)
		{
			keys.add(sessionCreatureId);
		}
		if (pendingCompletion != null && pendingCompletion.hasTask())
		{
			keys.add(pendingCompletion.getCreatureId());
		}
		return keys;
	}

	/**
	 * Adds NPC loot to the session ({@link #addLoot(ItemTally, List, String)} with no NPC name).
	 *
	 * @return whether the loot was added to a session
	 */
	public synchronized boolean addLoot(ItemTally items)
	{
		return addLoot(items, null, null);
	}

	/**
	 * Adds NPC loot and its notable stacks ({@link #addLoot(ItemTally, List, String)} with no NPC name).
	 *
	 * @return whether the loot was added to a session
	 */
	public synchronized boolean addLoot(ItemTally items, List<NotableDrop> notableDrops)
	{
		return addLoot(items, notableDrops, null);
	}

	/**
	 * Adds NPC loot and its notable stacks (see {@link NotableDrops}); both go to the same place, or neither is kept:
	 * <ul>
	 * <li>while a completed session is held for late loot ({@link #holdCompletion()}), to that session, even if a new
	 * session has been started meanwhile;</li>
	 * <li>while RUNNING, to the session. Unless it is a paired task kill's loot (below), it is also noted as use since the
	 * last activity, which Away takes back;</li>
	 * <li>a paired task kill's loot while the session is Away, Paused or Logged out: to the session, because loot from a
	 * paired task kill always counts, even when it arrives after the session stopped (V2 plan 4.1). That is loot of one
	 * of the session's known task NPCs arriving within {@link #TASK_NPC_LOOT_MILLIS} ({@link #ARAXXOR_LOOT_MILLIS} for
	 * Araxxor) after its last task kill;
	 * later loot of those names is like any other;</li>
	 * <li>otherwise, while a task is assigned and not Ended, to the buffer outside segments, which a (re)start counts
	 * from the segment start;</li>
	 * <li>otherwise nowhere.</li>
	 * </ul>
	 *
	 * <p>Loot is deliberately not filtered by the task monster: any NPC loot received while the session runs counts,
	 * because drop sources do not map reliably to Slayer task categories (superiors, variants, bosses and wildcards
	 * share or rename NPCs) and the session runs only between task kills, Pause and Away.</p>
	 *
	 * <p>Araxxor's loot is noted first, even with no items (all crushed or ignored): after the final kill it is that
	 * kill's harvest, so no harvest window opens for the task's record ({@link #lastAraxxorLootAt},
	 * {@link #takeHarvestRecord}).</p>
	 *
	 * @param items        the loot, as kept; may be empty
	 * @param notableDrops the loot's notable stacks, or {@code null} when none
	 * @param npcName      the name of the NPC it came from, or {@code null} when not known
	 * @return whether the loot was added to a session (not when only buffered)
	 */
	public synchronized boolean addLoot(ItemTally items, List<NotableDrop> notableDrops, String npcName)
	{
		if (isAraxxor(npcName))
		{
			lastAraxxorLootAt = clock.getAsLong();
		}
		if (items == null || items.isEmpty())
		{
			return false;
		}
		if (pendingCompletion != null)
		{
			pendingCompletion = pendingCompletion.withAddedLoot(items, notableDrops);
			return true;
		}
		final boolean taskNpcLoot = isTaskKillLoot(npcName);
		if (state == State.RUNNING || (state.isActive() && taskNpcLoot))
		{
			loot.merge(items);
			this.notableDrops = NotableDrops.add(this.notableDrops, notableDrops);
			if (state == State.RUNNING && !taskNpcLoot)
			{
				noteSinceActivity().addLoot(clock.getAsLong(), items, notableDrops);
			}
			return true;
		}
		if (isBuffering())
		{
			buffer.addLoot(clock.getAsLong(), items, notableDrops);
		}
		return false;
	}

	/**
	 * Whether loot may be kept now ({@link #addLoot(ItemTally, List, String)}): a session is active, a completed one is
	 * held for late loot, or a task is assigned and not Ended (buffered). Lets the caller skip pricing loot that would
	 * not be kept.
	 */
	public synchronized boolean isRecordingLoot()
	{
		return pendingCompletion != null || state.isActive() || isBuffering();
	}

	/**
	 * Adds a pet drop ({@link PetMessage}) to the session's notable drops: to a completed session held for late loot,
	 * since the pet may come from the final kill; while RUNNING, to the session, and it is never taken back by Away;
	 * otherwise, while a task is assigned and not Ended, to the buffer, as loot.
	 *
	 * @return whether it was added to a session (not when only buffered)
	 */
	public synchronized boolean addPet(NotableDrop pet)
	{
		if (pet == null)
		{
			return false;
		}
		final List<NotableDrop> added = Collections.singletonList(pet);
		if (pendingCompletion != null)
		{
			pendingCompletion = pendingCompletion.withAddedLoot(null, added);
			return true;
		}
		if (state == State.RUNNING)
		{
			notableDrops = NotableDrops.add(notableDrops, added);
			return true;
		}
		if (isBuffering())
		{
			buffer.addLoot(clock.getAsLong(), null, added);
		}
		return false;
	}

	/** Whether {@code npcName} is one of the session's known task NPCs (paired with its kills). */
	private boolean isKnownTaskNpc(String npcName)
	{
		final String key = TaskStatistics.normalize(npcName);
		return key != null && taskNpcNames.contains(key);
	}

	/**
	 * Whether loot from {@code npcName} arriving now is a paired task kill's: one of the session's known task NPCs,
	 * within {@link #TASK_NPC_LOOT_MILLIS} after the session's last task kill, or {@link #ARAXXOR_LOOT_MILLIS} for
	 * Araxxor, whose loot comes when the player harvests its corpse.
	 */
	private boolean isTaskKillLoot(String npcName)
	{
		if (lastKillAt == NO_TIME || !isKnownTaskNpc(npcName))
		{
			return false;
		}
		final long since = clock.getAsLong() - lastKillAt;
		final long window = isAraxxor(npcName) ? ARAXXOR_LOOT_MILLIS : TASK_NPC_LOOT_MILLIS;
		return since >= 0 && since <= window;
	}

	/** Whether {@code npcName} is Araxxor's, as {@link TaskStatistics#normalize} keys names. */
	private static boolean isAraxxor(String npcName)
	{
		return ARAXXOR.equals(TaskStatistics.normalize(npcName));
	}

	/** Whether Araxxor's death is among the NPCs paired with a task kill. */
	private static boolean pairsAraxxor(KillPairing pairing)
	{
		if (pairing != null)
		{
			for (String name : pairing.getNames())
			{
				if (isAraxxor(name))
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Counts a boss kill count message ({@link KillCountMessage}) for the session, by the same rules as loot
	 * ({@link #addLoot(ItemTally)}): while RUNNING, or for a completed session held for late loot, since the message
	 * may come with the final kill. Whether the boss belongs to the task, and the counts, follow
	 * {@link BossKillCounts}; all of it is decided here in one step.
	 *
	 * @param boss the boss name the message gives
	 * @param kc   the count the message gives
	 * @return whether it was counted for a session (its count may still have been a repeat)
	 */
	public synchronized boolean addBossKillCount(String boss, int kc)
	{
		if (pendingCompletion != null)
		{
			if (!BossKillCounts.appliesTo(pendingCompletion.getMonster(), pendingCompletion.getCreatureId(), boss))
			{
				return false;
			}
			pendingCompletion = pendingCompletion.withBossKillCount(boss, kc);
			return true;
		}
		if (state != State.RUNNING || !BossKillCounts.appliesTo(sessionMonster, sessionCreatureId, boss))
		{
			return false;
		}
		bossKillCounts = BossKillCounts.add(bossKillCounts, boss, kc);
		return true;
	}

	/**
	 * Adds supplies used: while RUNNING to the session (and noted as use since the last activity, which Away takes
	 * back); otherwise, while a task is assigned and not Ended, to the buffer outside segments, which a (re)start counts
	 * from {@link #WARM_UP_MILLIS} before the segment start. Unlike loot, supplies are never added to a completed session
	 * held for late loot (see {@link #holdCompletion()}): it stopped running when the task completed.
	 *
	 * @param used     items used; potions in doses
	 * @param returned ammo or cannonballs that came back (picked up, or unloaded from the cannon); each reduces that
	 *                 item's used quantity, never below zero
	 * @param doses    doses per item for the potion ids in {@code used}, or {@code null}
	 * @return whether the session changed (not when only buffered)
	 */
	public synchronized boolean addSupplies(ItemTally used, ItemTally returned, Map<Integer, Integer> doses)
	{
		final boolean hasUsed = used != null && !used.isEmpty();
		if (!hasUsed && (returned == null || returned.isEmpty()))
		{
			return false;
		}
		if (state != State.RUNNING)
		{
			if (isBuffering())
			{
				buffer.addSupplies(clock.getAsLong(), used, returned, doses);
			}
			return false;
		}
		boolean changed = false;
		if (hasUsed)
		{
			supplies.merge(used);
			putDoses(supplyDoses, doses);
			changed = true;
		}
		// What a return actually took off, so taking it back (Away) puts exactly that back.
		final ItemTally takenOff = new ItemTally();
		if (returned != null)
		{
			for (int id : returned.itemIds())
			{
				takenOff.add(id, supplies.subtract(id, returned.get(id)));
			}
		}
		changed |= !takenOff.isEmpty();
		noteSinceActivity().addSupplies(clock.getAsLong(), hasUsed ? used : null, takenOff, doses);
		return changed;
	}

	/**
	 * Counts a superior Slayer monster spawn, only while the session is RUNNING. Unlike loot, a spawn is never added to
	 * a completed session held for late loot (see {@link #holdCompletion()}): it stopped running when the task
	 * completed, and a superior that appears after that belongs to no task. One that appears just before the kill that
	 * (re)starts the session is held by the plugin and added once it runs.
	 *
	 * @return whether it was counted
	 */
	public synchronized boolean addSuperiorSpawn()
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		counters = counters.toBuilder().superiorsSpawned(saturatedIncrement(counters.getSuperiorsSpawned())).build();
		return true;
	}

	/**
	 * Counts a bank trip, only while the session is RUNNING (never for a held completed session). Which bank openings
	 * are trips is decided by {@link BankTripCounter}. One after the last activity is taken back if the session goes
	 * Away ({@link #checkAway}).
	 *
	 * @return whether it was counted
	 */
	public synchronized boolean addBankTrip()
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		counters = counters.toBuilder().bankTrips(saturatedIncrement(counters.getBankTrips())).build();
		noteSinceActivity(bankTripsSinceActivity);
		return true;
	}

	/**
	 * Counts a death of the local player, only while the session is RUNNING (never for a held completed session, like
	 * {@link #addSuperiorSpawn()}). Deaths are only counted; what a death costs is not tracked. Never taken back by Away
	 * ({@link #bankTripsSinceActivity}), like superiors.
	 *
	 * @return whether it was counted
	 */
	public synchronized boolean addDeath()
	{
		if (state != State.RUNNING)
		{
			return false;
		}
		counters = counters.toBuilder().deaths(saturatedIncrement(counters.getDeaths())).build();
		return true;
	}

	/**
	 * Counts the death of an NPC the player damaged under its name ({@link CatacombsVariants#tallyName}), only while
	 * the session is RUNNING (never for a held completed session, like {@link #addDeath()}). The deaths paired with the
	 * kill that (re)starts the session die before it does, so the plugin adds them once it runs. The kill count itself
	 * still comes from the task count; this tally only decides the task's variant and boss flag.
	 *
	 * @param name the name to tally, or {@code null} for none
	 * @return whether it was tallied
	 */
	public synchronized boolean addNpcKill(String name)
	{
		if (state != State.RUNNING || TaskStatistics.normalize(name) == null)
		{
			return false;
		}
		final List<NpcKills> updated = NpcKillTally.add(npcKills, name);
		final boolean tallied = NpcKillTally.total(updated) != NpcKillTally.total(npcKills);
		npcKills = updated;
		return tallied;
	}

	/**
	 * Tallies the death of an NPC the player damaged into the completed session held for late loot, when the death was
	 * paired with that session's final kill at {@code killAt}: the session stopped on its completion tick, so a
	 * paired death on the tick after was refused by {@link #addNpcKill}. Matters for a short task's variant or boss.
	 *
	 * @param killAt the final kill's clock time ({@link #getLastKillAt()} just after it)
	 * @param name   the name to tally, or {@code null} for none
	 * @return whether it was tallied
	 */
	public synchronized boolean addHeldNpcKill(long killAt, String name)
	{
		if (pendingCompletion == null || killAt == NO_TIME || killAt != pendingKillAt
			|| TaskStatistics.normalize(name) == null)
		{
			return false;
		}
		pendingCompletion = pendingCompletion.withNpcKill(name);
		return true;
	}

	/** A copy of the session's kills per NPC name so far, in the order first seen. */
	public synchronized List<NpcKills> getNpcKills()
	{
		return new ArrayList<>(npcKills);
	}

	/**
	 * Which records the observed task's statistics use, while the active session is on the observed task (else
	 * {@link TaskSelection#ANY}):
	 * <ul>
	 * <li>the version the session's kills decide ({@link CatacombsVariants#selection} of its kills per NPC name
	 * and its task kills, the same numbers the saved record's variant is decided from);</li>
	 * <li>cannon tasks only while the session's Cannon tag is Yes ({@link #getSetupTags}, the player's
	 * override, else at least half of its kills cannon kills, or with no kill context its fired cannonballs), as its
	 * saved record will be classified ({@link LedgerRecord#cannonTask}); else tasks with and without a cannon pooled.
	 * It never narrows to tasks without a cannon (owner decision): a cannon can still be set up later in the task.</li>
	 * </ul>
	 */
	public synchronized TaskSelection getCurrentTaskSelection()
	{
		if (!isSessionOnCurrentTask())
		{
			return TaskSelection.ANY;
		}
		return CatacombsVariants.selection(sessionMonster, npcKills, kills)
			.withCannon(getSetupTags().isCannon() ? Boolean.TRUE : null);
	}

	/**
	 * The variant and boss flag the active session's kills give its task ({@link TaskVariants#decide} of its kills per
	 * NPC name and its task kills, the numbers the saved record's are decided from), while the session is on the
	 * observed task (as {@link #getCurrentTaskSelection}); else {@link TaskVariants.Decision#NONE}. For display only: the
	 * statistics follow {@link #getCurrentTaskSelection}.
	 */
	public synchronized TaskVariants.Decision getCurrentVariant()
	{
		if (!isSessionOnCurrentTask())
		{
			return TaskVariants.Decision.NONE;
		}
		return TaskVariants.decide(sessionMonster, sessionCreatureId, npcKills, kills);
	}

	private boolean isSessionOnCurrentTask()
	{
		return state.isActive() && hasSessionTask && taskObserved
			&& currentCreatureId == sessionCreatureId
			&& (currentMonster == null || sessionMonster == null || currentMonster.equals(sessionMonster));
	}

	/**
	 * Records this tick's XP reading of every skill and adds the XP gained since the previous reading: while the session
	 * is RUNNING to it (and noted as use since the last activity, which Away takes back); otherwise, while a task is
	 * assigned and not Ended, to the buffer outside segments, which a (re)start counts from the segment start (so the
	 * fight that restarts the session, and the restart kill's own XP, count). Decided in one synchronized call, so a
	 * Pause or Resume click can't fall between the reading and the decision. The previous reading is the baseline
	 * whatever the state. Nothing is added when:
	 * <ul>
	 *     <li>the session is not RUNNING and no task is assigned, or it is Ended, or a completion is held for late loot
	 *     (it stopped on its completion tick, so XP after that tick never reaches it);</li>
	 *     <li>there is no previous reading: the first reading after {@link #resetXpBaseline()} (login, world hop, lost
	 *     connection, account switch) or after an unsynced one only sets the baseline, so the stats a login sends are
	 *     never counted;</li>
	 *     <li>{@code reading} is {@code null} (the caller's sign that the stats are not synced); the baseline is
	 *     dropped;</li>
	 *     <li>any skill went down since the previous reading ({@link SkillXp#gains}): the readings can't be compared,
	 *     and this one becomes the baseline.</li>
	 * </ul>
	 *
	 * @param reading every skill's XP, keyed as {@link SkillXp} keys them, or {@code null} when not synced
	 * @return whether XP was added to the session (not when only buffered)
	 */
	public synchronized boolean observeXp(Map<String, Integer> reading)
	{
		final Map<String, Integer> previous = xpReading;
		xpReading = reading == null ? null : new TreeMap<>(reading);
		final boolean running = state == State.RUNNING;
		if (reading == null || previous == null || (!running && !isBuffering()))
		{
			return false;
		}
		final Map<String, Long> gains = SkillXp.gains(previous, reading);
		if (gains == null || gains.isEmpty())
		{
			return false;
		}
		if (!running)
		{
			buffer.addXp(clock.getAsLong(), gains);
			return false;
		}
		SkillXp.add(xpGained, gains);
		noteSinceActivity().addXp(clock.getAsLong(), gains);
		return true;
	}

	/**
	 * Forgets the XP baseline (on login, world hop, lost connection or account switch), so the next reading of
	 * {@link #observeXp} only sets it. The session's XP so far is kept.
	 */
	public synchronized void resetXpBaseline()
	{
		xpReading = null;
	}

	/** A copy of the XP gained per skill in the started (running, paused or just stopped) session. */
	public synchronized Map<String, Long> getXpGained()
	{
		return new TreeMap<>(xpGained);
	}

	/**
	 * Sets (or, with an empty or {@code null} note, clears) the note of the given session: the active
	 * session, or a completed session still held for late loot (see {@link #holdCompletion()}), so a note committed
	 * just as the task completes still reaches the saved record. The note is {@link TaskNote#normalize normalized}.
	 *
	 * @param sessionId the session the note was typed for; another session's note is never changed
	 * @return whether a session took the note; {@code false} when it is no longer active or held
	 */
	public synchronized boolean setNote(String sessionId, String note)
	{
		if (sessionId == null)
		{
			return false;
		}
		final String normalized = TaskNote.normalize(note);
		if (state.isActive() && sessionId.equals(this.sessionId))
		{
			this.note = normalized;
			return true;
		}
		if (pendingCompletion != null && sessionId.equals(pendingCompletion.getSessionId()))
		{
			pendingCompletion = pendingCompletion.withNote(normalized);
			return true;
		}
		return false;
	}

	/**
	 * Sets the Slayer points earned and the streak of a completed session: the active session once
	 * {@link #observe} reported it {@link ObserveResult#COMPLETED}, or the completed session held for late loot (see
	 * {@link #holdCompletion()}), so the points can still be corrected while it is held. Recorded whether the session
	 * was running or stopped when the task completed: they belong to the task, not to the time tracked.
	 *
	 * @param sessionId    the completed session; another session is never changed
	 * @param pointsEarned points the completion gave, or {@code null} when not trusted
	 * @param taskStreak   streak after the completion, or {@code null} when unknown
	 * @return whether a completed session took them; {@code false} when it is no longer active or held
	 */
	public synchronized boolean setCompletionRewards(String sessionId, Integer pointsEarned, Integer taskStreak)
	{
		if (sessionId == null)
		{
			return false;
		}
		if (state.isActive() && completed && sessionId.equals(this.sessionId))
		{
			sessionContext = sessionContext.withRewards(pointsEarned, taskStreak);
			return true;
		}
		if (pendingCompletion != null && sessionId.equals(pendingCompletion.getSessionId()))
		{
			pendingCompletion = pendingCompletion.withContext(
				pendingCompletion.getContext().withRewards(pointsEarned, taskStreak));
			return true;
		}
		return false;
	}

	/** Assignment of the latest observed task (master and area), or {@link TaskContext#NONE}. */
	public synchronized TaskContext getCurrentContext()
	{
		return currentContext;
	}

	/** Note of the started (running, paused or just stopped) session, or {@code null}. */
	public synchronized String getNote()
	{
		return note;
	}

	/**
	 * Sets the player's setup overrides (V2 plan 4.3) of the given session, replacing the earlier ones (each
	 * {@code null} in {@code overrides} clears that tag's override): the active session, or a completed session still
	 * held for late loot (see {@link #holdCompletion()}), so they reach the saved record like a note. They are saved
	 * with the session's snapshot and record.
	 *
	 * @param sessionId the session they were set for; another session's are never changed
	 * @param overrides the overrides, or {@code null} for none
	 * @return whether a session took them; {@code false} when it is no longer active or held
	 */
	public synchronized boolean setSetupOverrides(String sessionId, SetupOverrides overrides)
	{
		if (sessionId == null)
		{
			return false;
		}
		final SetupOverrides value = overrides == null ? SetupOverrides.NONE : overrides;
		if (state.isActive() && sessionId.equals(this.sessionId))
		{
			setupOverrides = value;
			return true;
		}
		if (pendingCompletion != null && sessionId.equals(pendingCompletion.getSessionId()))
		{
			pendingCompletion = pendingCompletion.withSetupOverrides(value);
			return true;
		}
		return false;
	}

