			/** Superior spawns, bank trips and deaths; {@code null} is {@link SessionCounters#ZERO}. */
			Builder counters(SessionCounters counters)
			{
				this.counters = counters;
				return this;
			}

			/** The player's note, or {@code null}. */
			Builder note(String note)
			{
				this.note = note;
				return this;
			}

			/** The task's assignment and completion rewards; {@code null} is {@link TaskContext#NONE}. */
			Builder context(TaskContext context)
			{
				this.context = context;
				return this;
			}

			/**
			 * XP gained per skill ({@link SkillXp}), or {@code null} when unknown (a snapshot from before XP was
			 * tracked).
			 */
			Builder xpGained(Map<String, Long> xpGained)
			{
				this.xpGained = xpGained;
				return this;
			}

			/** Counted kills per place, the most recent last ({@link LocationTally}), or {@code null}. */
			Builder locationKills(List<LocationKills> locationKills)
			{
				this.locationKills = locationKills;
				return this;
			}

			/**
			 * The task's spot and region as the tracker (or {@link SessionSnapshot#toSummary(SlayerSpots)}) decided them
			 * with its spot table ({@link LocationTally#decide}); {@code null} decides them from {@link #locationKills}
			 * without the table.
			 */
			Builder taskSpot(TaskSpot taskSpot)
			{
				this.taskSpot = taskSpot;
				return this;
			}

			/** Kills per NPC name in the order first seen ({@link NpcKillTally}), or {@code null}. */
			Builder npcKills(List<NpcKills> npcKills)
			{
				this.npcKills = npcKills;
				return this;
			}

			/** The setup kill contexts ({@link SetupKills}); {@code null} is {@link SetupKills#NONE}. */
			Builder setupKills(SetupKills setupKills)
			{
				this.setupKills = setupKills;
				return this;
			}

			/**
			 * Task kills counted before kill contexts were recorded, left out of the cannon share; kept between 0
			 * and the kills.
			 */
			Builder killsBeforeContexts(int killsBeforeContexts)
			{
				this.killsBeforeContexts = killsBeforeContexts;
				return this;
			}

			/** The player's setup overrides; {@code null} is {@link SetupOverrides#NONE}. */
			Builder setupOverrides(SetupOverrides setupOverrides)
			{
				this.setupOverrides = setupOverrides;
				return this;
			}

			/** The segment clamps, state and known task NPCs; {@code null} is {@link SegmentInfo#NONE}. */
			Builder segments(SegmentInfo segments)
			{
				this.segments = segments;
				return this;
			}

			Summary build()
			{
				return new Summary(this);
			}
		}

		/** A copy of this summary with extra loot (may be {@code null}) and notable drops (likewise) added. */
		Summary withAddedLoot(ItemTally extra, List<NotableDrop> extraNotableDrops)
		{
			return toBuilder().sessionLoot(sessionLoot.withAddedLoot(extra, extraNotableDrops)).build();
		}

		/** A copy of this summary with one more boss kill count message counted ({@link BossKillCounts#add}). */
		Summary withBossKillCount(String boss, int kc)
		{
			return toBuilder().sessionLoot(sessionLoot.withBossKillCount(boss, kc)).build();
		}

		/** A copy of this summary with the given note. */
		Summary withNote(String newNote)
		{
			return toBuilder().note(newNote).build();
		}

		/** A copy of this summary with the given setup overrides. */
		Summary withSetupOverrides(SetupOverrides newOverrides)
		{
			return toBuilder().setupOverrides(newOverrides).build();
		}

		/** A copy of this summary with the given setup kill contexts. */
		Summary withSetupKills(SetupKills newKills)
		{
			return toBuilder().setupKills(newKills).build();
		}

		/** A copy of this summary with the given task context. */
		Summary withContext(TaskContext newContext)
		{
			return toBuilder().context(newContext).build();
		}

		/** A copy of this summary with one more kill of {@code name} in its kills per NPC name ({@link NpcKillTally}). */
		Summary withNpcKill(String name)
		{
			return toBuilder().npcKills(NpcKillTally.add(npcKills, name)).build();
		}

		/**
		 * A copy of this summary with buffered supplies, XP and loot added ({@link #pairKill} backdating a held
		 * completion), in the order given, as {@link SessionTracker} counts them.
		 */
		Summary withCounted(List<TimedUsage.Entry> entries)
		{
			if (entries == null || entries.isEmpty())
			{
				return this;
			}
			final ItemTally addedLoot = new ItemTally(sessionLoot.getLoot());
			final ItemTally addedSupplies = new ItemTally(sessionLoot.getSupplies());
			final Map<Integer, Integer> doses = new TreeMap<>(sessionLoot.getSupplyDoses());
			List<NotableDrop> drops = sessionLoot.getNotableDrops();
			final Map<String, Long> xp = new TreeMap<>();
			SkillXp.add(xp, xpGained);
			for (TimedUsage.Entry entry : entries)
			{
				if (entry.getUsed() != null)
				{
					addedSupplies.merge(entry.getUsed());
					putDoses(doses, entry.getDoses());
				}
				if (entry.getReturned() != null)
				{
					for (int id : entry.getReturned().itemIds())
					{
						addedSupplies.subtract(id, entry.getReturned().get(id));
					}
				}
				SkillXp.add(xp, entry.getXp());
				if (entry.getLoot() != null)
				{
					addedLoot.merge(entry.getLoot());
				}
				drops = NotableDrops.add(drops, entry.getDrops());
			}
			return toBuilder()
				.sessionLoot(sessionLoot.toBuilder().loot(addedLoot).supplies(addedSupplies).supplyDoses(doses)
					.notableDrops(drops).build())
				.xpGained(xp)
				.build();
		}

		/**
		 * A copy of this summary whose last segment, which started at {@code segmentStart}, starts {@code millis}
		 * earlier ({@link #pairKill}): the active time grows by {@code millis}, and the session's start moves with it when
		 * that segment was its first.
		 */
		Summary backdated(long millis, long segmentStart)
		{
			return toBuilder()
				.activeMillis(activeMillis + millis)
				.startedAt(startedAt == segmentStart ? startedAt - millis : startedAt)
				.build();
		}

		public boolean hasTask()
		{
			return hasTask;
		}

		/** A copy of the session's loot (never {@code null}). */
		public ItemTally getLoot()
		{
			return sessionLoot.getLoot();
		}

		/** A copy of the session's supplies used, potions in doses (never {@code null}). */
		public ItemTally getSupplies()
		{
			return sessionLoot.getSupplies();
		}

		/** A copy of the doses per item for potion ids in {@link #getSupplies()} (never {@code null}). */
		public Map<Integer, Integer> getSupplyDoses()
		{
			return sessionLoot.getSupplyDoses();
		}

		/** Superior spawns counted while running, or {@code null} when unknown. */
		public Integer getSuperiorsSpawned()
		{
			return counters.getSuperiorsSpawned();
		}

		/** Bank trips counted while running, or {@code null} when unknown. */
		public Integer getBankTrips()
		{
			return counters.getBankTrips();
		}

		/** Deaths counted while running, or {@code null} when unknown. */
		public Integer getDeaths()
		{
			return counters.getDeaths();
		}

		/** The session's notable drops in the order they arrived (never {@code null}; unmodifiable). */
		public List<NotableDrop> getNotableDrops()
		{
			return sessionLoot.getNotableDrops();
		}

		/** The session's boss kill counts in the order first seen (never {@code null}; unmodifiable). */
		public List<BossKillCount> getBossKillCounts()
		{
			return sessionLoot.getBossKillCounts();
		}

		/**
		 * The session's setup tags, detected from its kill contexts and the kills that may have one (or, with no kill
		 * context, its supplies; {@link SetupTags#forSession}) with the player's overrides: what its record stores.
		 */
		public SetupTags getSetupTags()
		{
			return SetupTags.forSession(sessionLoot.getSupplies(), setupKills, contextKills(kills, killsBeforeContexts),
				setupOverrides);
		}
	}

	/** Immutable snapshot of the active session's task progress ({@link #liveTask()}). */
	@Getter
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class LiveTask
	{
		/** {@link #getRemaining()} when the kills left on the session's task are not known right now. */
		public static final int UNKNOWN_REMAINING = -1;

		private final Status status;
		private final String sessionId;
		/** The session's task name, or {@code null} when unknown. */
		private final String monster;
		private final int creatureId;
		private final int kills;
		private final long activeMillis;
		/** Kills left on the session's task, or {@link #UNKNOWN_REMAINING}. */
		private final int remaining;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Values the live session's loot and supplies for the panel. Pure: prices come from a {@link ItemValuation.PriceLookup}
 * (the plugin's runs on the client thread). Not thread-safe; the plugin only calls it on the client thread.
 *
 * <p>Unit prices are cached for the session, so a recompute only looks up items not seen before (and retries items
 * whose GE price was unavailable, at most once every {@link #RETRY_TICKS} ticks). Totals use the
 * same rules as saved records ({@link ItemValuation}): potions per dose, coins at face value, unavailable GE prices
 * left out and counted. Loot is also valued in the chosen {@link LootPriceMode} ({@link LootPricing}), and its GE value
 * follows {@link LootPricing} too (an item with a GE price of 0 counts at its high-alchemy value); supplies are
 * always valued at GE prices as captured. Loot items Ground Items hides ({@link HiddenLoot}), except coins,
 * are left out of every loot value and unpriced count; the tally is not changed. The cache is dropped when the
 * session changes or {@link #reset()} is called.</p>
 *
 * <p>Not final only so plugin tests can stand in a valuation that fails.</p>
 */
class SessionValuation
{
	/** Ticks between retries of unavailable GE prices while the tallies do not change. */
	static final int RETRY_TICKS = 10;

	/** Loot and supplies values of a session at one moment. Immutable. */
	@Value
	static final class Values
	{
		/** Id of the session these values belong to. */
		private final String sessionId;
		/** The price mode {@link #getLootValue()} uses. */
		private final LootPriceMode lootPriceMode;
		/** Loot value in {@link #getLootPriceMode()}. */
		private final long lootValue;
		/**
		 * Distinct loot items whose price in {@link #getLootPriceMode()} was unavailable, so {@link #getLootValue()} is
		 * approximate; see {@link LootPricing#countUnpriced}.
		 */
		private final int lootValueUnpriced;
		/** Loot value in {@link LootPriceMode#GE}: GE prices, with a GE price of 0 at high alch ({@link LootPricing}). */
		private final long lootGe;
		private final long lootHa;
		private final long suppliesGe;
		private final long suppliesHa;
		/** Distinct loot items whose GE price was unavailable (left out of {@link #getLootGe()}). */
		private final int lootUnpriced;
		/** Distinct supply items whose GE price was unavailable (left out of {@link #getSuppliesGe()}). */
		private final int suppliesUnpriced;
		/**
		 * The session's loot and supplies item by item, with the unit prices these values use, for the panel's item
		 * lists.
		 */
		private final ItemDetails items;
		/**
		 * The loot items left out of these values, which the "Loot received" grid leaves out too; never
		 * {@code null}. {@link #getItems()} still lists them.
		 */
		private final HiddenLoot hiddenLoot;

		private Values(Builder b)
		{
			this.sessionId = b.sessionId;
			this.lootPriceMode = b.lootPriceMode == null ? LootPriceMode.GE : b.lootPriceMode;
			this.lootValue = b.lootValue;
			this.lootValueUnpriced = b.lootValueUnpriced;
			this.lootGe = b.lootGe;
			this.lootHa = b.lootHa;
			this.suppliesGe = b.suppliesGe;
			this.suppliesHa = b.suppliesHa;
			this.lootUnpriced = b.lootUnpriced;
			this.suppliesUnpriced = b.suppliesUnpriced;
			this.items = b.items == null ? ItemDetails.EMPTY : b.items;
			this.hiddenLoot = b.hiddenLoot == null ? HiddenLoot.NONE : b.hiddenLoot;
		}

		/** A builder starting from no values: GE mode, everything 0, no item details. */
		static Builder builder()
		{
			return new Builder();
		}

		/** Builds {@link Values}; a {@code null} price mode is GE and {@code null} items are none. */
		static final class Builder
		{
			private String sessionId;
			private LootPriceMode lootPriceMode = LootPriceMode.GE;
			private long lootValue;
			private int lootValueUnpriced;
			private long lootGe;
			private long lootHa;
			private long suppliesGe;
			private long suppliesHa;
			private int lootUnpriced;
			private int suppliesUnpriced;
			private ItemDetails items = ItemDetails.EMPTY;
			private HiddenLoot hiddenLoot = HiddenLoot.NONE;

			private Builder()
			{
			}

			Builder sessionId(String sessionId)
			{
				this.sessionId = sessionId;
				return this;
			}

			Builder lootPriceMode(LootPriceMode lootPriceMode)
			{
				this.lootPriceMode = lootPriceMode;
				return this;
			}

			Builder lootValue(long lootValue)
			{
				this.lootValue = lootValue;
				return this;
			}

			Builder lootValueUnpriced(int lootValueUnpriced)
			{
				this.lootValueUnpriced = lootValueUnpriced;
				return this;
			}

			Builder lootGe(long lootGe)
			{
				this.lootGe = lootGe;
				return this;
			}

			Builder lootHa(long lootHa)
			{
				this.lootHa = lootHa;
				return this;
			}

			Builder suppliesGe(long suppliesGe)
			{
				this.suppliesGe = suppliesGe;
				return this;
			}

			Builder suppliesHa(long suppliesHa)
			{
				this.suppliesHa = suppliesHa;
				return this;
			}

			Builder lootUnpriced(int lootUnpriced)
			{
				this.lootUnpriced = lootUnpriced;
				return this;
			}

			Builder suppliesUnpriced(int suppliesUnpriced)
			{
				this.suppliesUnpriced = suppliesUnpriced;
				return this;
			}

			Builder items(ItemDetails items)
			{
				this.items = items;
				return this;
			}

			Builder hiddenLoot(HiddenLoot hiddenLoot)
			{
				this.hiddenLoot = hiddenLoot;
				return this;
			}

			Values build()
			{
				return new Values(this);
			}
		}

		/** Loot value in {@link #getLootPriceMode()} minus supplies GE value. */
		long getProfit()
		{
			return LedgerHistory.profit(lootValue, suppliesGe);
		}
	}

	private String sessionId;
	private ItemValuation.UnitPrices prices = new ItemValuation.UnitPrices();
	private ItemTally lastLoot;
	private ItemTally lastSupplies;
	private Map<Integer, Integer> lastDoses;
	private LootPriceMode lastMode;
	private HiddenLoot lastHidden;
	private Values last;
	private int lastRetryTick;

	/**
	 * The session's values with the loot valued at GE prices; see
	 * {@link #update(String, ItemTally, ItemTally, Map, LootPriceMode, ItemValuation.PriceLookup, int)}.
	 */
	Values update(String sessionId, ItemTally loot, ItemTally supplies, Map<Integer, Integer> doses,
		ItemValuation.PriceLookup lookup, int tick)
	{
		return update(sessionId, loot, supplies, doses, LootPriceMode.GE, lookup, tick);
	}

	/**
	 * The session's values. Recomputed only when the session, its loot, its supplies, its doses or the price mode
	 * changed since the
	 * last call, or when some GE price was unavailable and {@link #RETRY_TICKS} ticks have passed since it was last
	 * tried; otherwise the
	 * previous values are returned without any lookup.
	 *
	 * @param sessionId id of the session; a different id drops the cached prices
	 * @param loot      the session's loot
	 * @param supplies  the session's supplies (potions in doses)
	 * @param doses     doses per item for the potion ids in {@code supplies}, or {@code null}
	 * @param mode      how the loot is valued ({@code null} means GE); supplies are always valued at GE prices
	 * @param lookup    price source, valid on the calling thread
	 * @param tick      current game tick, for the retry cadence
	 */
	Values update(String sessionId, ItemTally loot, ItemTally supplies, Map<Integer, Integer> doses,
		LootPriceMode mode, ItemValuation.PriceLookup lookup, int tick)
	{
		return update(sessionId, loot, supplies, doses, mode, HiddenLoot.NONE, lookup, tick);
	}

	/**
	 * The session's values, with the loot items {@code hidden} hides, except coins, left out of the loot values
	 *; see {@link #update(String, ItemTally, ItemTally, Map, LootPriceMode, ItemValuation.PriceLookup, int)}.
	 * Other hidden items also recompute the values.
	 *
	 * @param hidden loot items left out ({@code null} is none); they are still priced and listed in the item details
	 */
	Values update(String sessionId, ItemTally loot, ItemTally supplies, Map<Integer, Integer> doses,
		LootPriceMode mode, HiddenLoot hidden, ItemValuation.PriceLookup lookup, int tick)
	{
		final HiddenLoot hiddenLoot = hidden == null ? HiddenLoot.NONE : hidden;
		final LootPriceMode lootMode = mode == null ? LootPriceMode.GE : mode;
		if (!Objects.equals(sessionId, this.sessionId))
		{
			reset();
			this.sessionId = sessionId;
		}
		final ItemTally lootTally = loot == null ? new ItemTally() : loot;
		final ItemTally suppliesTally = supplies == null ? new ItemTally() : supplies;
		final Map<Integer, Integer> doseMap = doses == null ? new TreeMap<>() : doses;
		final boolean changed = last == null || !lootTally.equals(lastLoot) || !suppliesTally.equals(lastSupplies)
			|| !doseMap.equals(lastDoses) || lootMode != lastMode || !hiddenLoot.equals(lastHidden);
		// The tick count restarts after a login or hop; a retry is then due at once.
		final boolean retry = !prices.getGeMissing().isEmpty()
			&& (tick - lastRetryTick >= RETRY_TICKS || tick < lastRetryTick);
		if (!changed && !retry)
		{
			return last;
		}

		final boolean noneMissing = prices.getGeMissing().isEmpty();
		priceNew(lootTally, lookup);
		priceNew(suppliesTally, lookup);
		if (retry)
		{
			// Items whose GE price was unavailable are looked up again (new items were priced above); items no
			// longer in the tallies are forgotten, and priced afresh if they come back.
			for (int id : prices.getGeMissing().toArray(new Integer[0]))
			{
				if (lootTally.get(id) > 0 || suppliesTally.get(id) > 0)
				{
					ItemValuation.capturePrice(id, lookup, prices);
				}
				else
				{
					prices.getGeMissing().remove(id);
				}
			}
			lastRetryTick = tick;
		}
		else if (noneMissing && !prices.getGeMissing().isEmpty())
		{
			// The first unavailable price: retry it RETRY_TICKS from now, even while the tallies keep changing.
			lastRetryTick = tick;
		}

		lastLoot = new ItemTally(lootTally);
		lastSupplies = new ItemTally(suppliesTally);
		lastDoses = new TreeMap<>(doseMap);
		lastMode = lootMode;
		lastHidden = hiddenLoot;
		final ItemTally valued = hiddenLoot.valued(lootTally);
		last = Values.builder()
			.sessionId(sessionId)
			.lootPriceMode(lootMode)
			.lootValue(LootPricing.total(valued, lootMode, prices.getGe(), prices.getHa(), null))
			.lootValueUnpriced(LootPricing.countUnpriced(valued, lootMode, prices.getGe(), prices.getHa()))
			.lootGe(LootPricing.total(valued, LootPriceMode.GE, prices.getGe(), prices.getHa(), null))
			.lootHa(ItemValuation.total(valued, prices.getHa()))
			.suppliesGe(ItemValuation.total(suppliesTally, prices.getGe(), doseMap))
			.suppliesHa(ItemValuation.total(suppliesTally, prices.getHa(), doseMap))
			.lootUnpriced(ItemValuation.countUnpriced(valued, prices.getGe()))
			.suppliesUnpriced(ItemValuation.countUnpriced(suppliesTally, prices.getGe()))
			.items(ItemDetails.of(lootTally, suppliesTally, doseMap, prices.getGe(), prices.getHa()))
			.hiddenLoot(hiddenLoot)
			.build();
		return last;
	}

	/** Looks up items not priced (or tried) yet this session. */
	private void priceNew(ItemTally tally, ItemValuation.PriceLookup lookup)
	{
		for (int id : tally.itemIds())
		{
			if (!prices.getGe().containsKey(id) && !prices.getGeMissing().contains(id))
			{
				ItemValuation.capturePrice(id, lookup, prices);
			}
		}
	}

	/** Drops the cached prices and values (session ended or changed). */
	void reset()
	{
		sessionId = null;
		prices = new ItemValuation.UnitPrices();
		lastLoot = null;
		lastSupplies = null;
		lastDoses = null;
		lastMode = null;
		lastHidden = null;
		last = null;
		lastRetryTick = 0;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * The choices of a saved task's "Setup..." dialog (the history row's right-click menu) and of the menus of the
 * live task's setup toggles ({@link SetupToggles}): for each setup tag, a first choice that clears the
 * override and shows the detected value (for example {@code Detected: ~Barrage}), then every value the player can set.
 * Unknown can't be set: it is no override. Pure (no Swing); the dialog and the menus show the choices' labels.
 */
final class SetupChoices
{
	/** One choice: its label and the override it sets ({@code null}: none, the detected value counts). */
	@Getter
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Choice<T>
	{
		private final String label;
		/** The override this choice sets, or {@code null} to clear it. */
		private final T value;

		/** The label: what a combo box shows. */
		@Override
		public String toString()
		{
			return label;
		}
	}

	private SetupChoices()
	{
	}

	/** The cannon choices: detected, Yes, No. */
	static List<Choice<Boolean>> cannon(SetupTags tags)
	{
		final List<Choice<Boolean>> choices = new ArrayList<>();
		choices.add(detected(SetupTags.shown(SetupTags.cannonLabel(tags.isDetectedCannon()),
			tags.isDetectedCannonEstimated())));
		choices.add(new Choice<>(SetupTags.cannonLabel(true), Boolean.TRUE));
		choices.add(new Choice<>(SetupTags.cannonLabel(false), Boolean.FALSE));
		return Collections.unmodifiableList(choices);
	}

	/** The style choices: detected, then every style but Unknown. */
	static List<Choice<SetupStyle>> style(SetupTags tags)
	{
		final List<Choice<SetupStyle>> choices = new ArrayList<>();
		choices.add(detected(SetupTags.shown(tags.getDetectedStyle().getLabel(), tags.isDetectedStyleEstimated())));
		for (SetupStyle style : SetupStyle.values())
		{
			if (style != SetupStyle.UNKNOWN)
			{
				choices.add(new Choice<>(style.getLabel(), style));
			}
		}
		return Collections.unmodifiableList(choices);
	}

	/** The gear focus choices: detected, then every focus but Unknown. */
	static List<Choice<GearFocus>> gear(SetupTags tags)
	{
		final List<Choice<GearFocus>> choices = new ArrayList<>();
		choices.add(detected(SetupTags.shown(tags.getDetectedGear().getLabel(), tags.isDetectedGearEstimated())));
		for (GearFocus gear : GearFocus.values())
		{
			if (gear != GearFocus.UNKNOWN)
			{
				choices.add(new Choice<>(gear.getLabel(), gear));
			}
		}
		return Collections.unmodifiableList(choices);
	}

	/** The index of the choice that sets {@code override}; 0 (detected) when there is none or it isn't listed. */
	static <T> int indexOf(List<Choice<T>> choices, T override)
	{
		if (override == null)
		{
			return 0;
		}
		for (int i = 0; i < choices.size(); i++)
		{
			if (Objects.equals(choices.get(i).getValue(), override))
			{
				return i;
			}
		}
		return 0;
	}

	/** The dialog's first line: {@code Setup of this <task> task:}. */
	static String prompt(LedgerRecord record)
	{
		return "Setup of this " + LedgerHistory.monster(record) + " task:";
	}

	private static <T> Choice<T> detected(String shownValue)
	{
		return new Choice<>("Detected: " + shownValue, null);
	}
}

package com.shmayvan.slayerledger;

import java.util.*;

/**
 * The rules that turn what was seen at a task's kills into its detected setup tags (V2 plan 4.3): each kill's
 * gear focus from the worn prayer bonus, each killed NPC's style from its hitsplats' attacks, and the task's cannon,
 * style and gear focus from its kill contexts ({@link SetupKills}). {@link SetupTags#forSession} uses them for the live
 * session and the record it is saved as. Pure (no RuneLite types).
 *
 * <p><b>Gear focus cut-offs.</b> The total prayer bonus of the worn items: {@value #PRAYER_FOCUS_MIN} or more is
 * Prayer, {@value #STRENGTH_FOCUS_MAX} or less is Strength, anything between is Mixed. Checked against the OSRS Wiki's
 * bonuses of real setups on 2026-11-09 ({@code docs/COUNTING_RULES.md}, "Setup tags"): damage-focused sets total +4 to
 * +14 (Torva or Bandos with a torture and infernal cape +7 to +9, with Rada's blessing 4 up to +11; Masori or Armadyl
 * +6; crystal armour with a bow of faerdhinen +10; Ancestral with an Elidinis' ward +8; Virtus with a ward and Rada's
 * blessing +14), and prayer sets +29 to +37 (Justiciar or Proselyte with holy wraps, a holy book, a ring of the gods,
 * holy sandals and a blessing). The plan's first guess, Strength at +10 or less, would have called the common Bandos
 * set with Rada's blessing 4 Mixed, so the Strength cut-off was raised to +14.</p>
 */
final class SetupDetection
{
	/** The lowest worn prayer bonus that is Prayer gear. */
	static final int PRAYER_FOCUS_MIN = 25;
	/** The highest worn prayer bonus that is Strength (damage) gear. */
	static final int STRENGTH_FOCUS_MAX = 14;

	private SetupDetection()
	{
	}

	/** The gear focus of a worn prayer bonus (see the class comment). */
	static GearFocus gearFocus(int prayerBonus)
	{
		if (prayerBonus >= PRAYER_FOCUS_MIN)
		{
			return GearFocus.PRAYER;
		}
		return prayerBonus <= STRENGTH_FOCUS_MAX ? GearFocus.STRENGTH : GearFocus.MIXED;
	}

	/**
	 * A killed NPC's style: the style most of the player's hitsplats on it were put down to ({@link PlayerAttacks}), Mixed
	 * when two styles tie for most, or {@code null} when none was (only cannon hits, say).
	 *
	 * @param hitsPerStyle hitsplats per style, indexed by {@link SetupStyle#ordinal()}
	 */
	static SetupStyle npcStyle(int[] hitsPerStyle)
	{
		SetupStyle best = null;
		int bestHits = 0;
		boolean tie = false;
		for (SetupStyle style : SetupStyle.values())
		{
			final int hits = style.ordinal() < hitsPerStyle.length ? hitsPerStyle[style.ordinal()] : 0;
			if (hits > bestHits)
			{
				best = style;
				bestHits = hits;
				tie = false;
			}
			else if (hits > 0 && hits == bestHits)
			{
				tie = true;
			}
		}
		return tie ? SetupStyle.MIXED : best;
	}

	/**
	 * Whether a task was done with a cannon: at least half of its {@code kills} were cannon kills. A task with no kills,
	 * or none counted as cannon kills, was not.
	 */
	static boolean cannon(Integer cannonKills, int kills)
	{
		return cannonKills != null && cannonKills > 0 && kills > 0 && 2L * cannonKills >= kills;
	}

	/**
	 * A task's style from its kills per style ({@link SetupKills#getStyleKills()}): the style covering at least half of
	 * the kills that have a style. Mixed when two styles tie for that, when no style reaches half, or when the covering
	 * style is itself Mixed (kills whose NPC was hit equally in two styles); Unknown with no styled kill at all (a
	 * cannon-only task). Keys this build doesn't know (a later build's styles) are left out.
	 */
	static SetupStyle taskStyle(Map<String, Integer> styleKills)
	{
		long total = 0;
		SetupStyle best = null;
		int bestKills = 0;
		boolean tie = false;
		for (SetupStyle style : SetupStyle.values())
		{
			if (style == SetupStyle.UNKNOWN)
			{
				continue;
			}
			final int kills = styleKills == null ? 0 : styleKills.getOrDefault(style.name(), 0);
			if (kills <= 0)
			{
				continue;
			}
			total += kills;
			if (kills > bestKills)
			{
				best = style;
				bestKills = kills;
				tie = false;
			}
			else if (kills == bestKills)
			{
				tie = true;
			}
		}
		if (best == null)
		{
			return SetupStyle.UNKNOWN;
		}
		return !tie && 2L * bestKills >= total ? best : SetupStyle.MIXED;
	}

	/**
	 * A task's gear focus from its kills per focus ({@link SetupKills#getGearKills()}): the focus of the most kills,
	 * Mixed when two tie for most, Unknown with none. Keys this build doesn't know are left out.
	 */
	static GearFocus taskGear(Map<String, Integer> gearKills)
	{
		GearFocus best = null;
		int bestKills = 0;
		boolean tie = false;
		for (GearFocus gear : GearFocus.values())
		{
			if (gear == GearFocus.UNKNOWN)
			{
				continue;
			}
			final int kills = gearKills == null ? 0 : gearKills.getOrDefault(gear.name(), 0);
			if (kills > bestKills)
			{
				best = gear;
				bestKills = kills;
				tie = false;
			}
			else if (kills > 0 && kills == bestKills)
			{
				tie = true;
			}
		}
		if (best == null)
		{
			return GearFocus.UNKNOWN;
		}
		return tie ? GearFocus.MIXED : best;
	}

	/*
	 * What each tag was detected from, for the live card's setup toggles' tooltips (SetupToggles; plain text, no
	 * player text). Each is empty before a kill's context is counted.
	 */

	/**
	 * What the cannon tag was detected from: the cannon kills of the task's kills that may have a kill context
	 * ({@code taskKills}, {@link SessionTracker#contextKills}), {@code Cannon kills: 2 of 3}.
	 */
	static List<String> cannonDetails(SetupKills kills, int taskKills)
	{
		final List<String> lines = new ArrayList<>();
		if (kills.getCannonKills() != null)
		{
			lines.add("Cannon kills: " + kills.getCannonKills() + " of " + taskKills);
		}
		return lines;
	}

	/** What the style tag was detected from: the kills per style, {@code Kills by style: Melee 2, Barrage 1}. */
	static List<String> styleDetails(SetupKills kills)
	{
		final List<String> lines = new ArrayList<>();
		addCounts(lines, "Kills by style: ", kills.getStyleKills(), styleLabels());
		return lines;
	}

	/**
	 * What the gear focus tag was detected from: the kills per gear focus and the worn prayer bonus seen at the kills,
	 * {@code Kills by gear: Prayer 2, Strength 1} and {@code Prayer bonus: -2 to +33}.
	 */
	static List<String> gearDetails(SetupKills kills)
	{
		final List<String> lines = new ArrayList<>();
		addCounts(lines, "Kills by gear: ", kills.getGearKills(), gearLabels());
		final Integer min = kills.getPrayerBonusMin();
		final Integer max = kills.getPrayerBonusMax();
		if (min != null && max != null)
		{
			lines.add("Prayer bonus: " + signed(min) + (min.equals(max) ? "" : " to " + signed(max)));
		}
		return lines;
	}

	private static void addCounts(List<String> lines, String title, Map<String, Integer> counts,
		Map<String, String> labels)
	{
		final StringBuilder line = new StringBuilder();
		for (Map.Entry<String, String> label : labels.entrySet())
		{
			final int n = counts.getOrDefault(label.getKey(), 0);
			if (n > 0)
			{
				line.append(line.length() == 0 ? "" : ", ").append(label.getValue()).append(' ').append(n);
			}
		}
		if (line.length() > 0)
		{
			lines.add(title + line);
		}
	}

	private static Map<String, String> styleLabels()
	{
		final Map<String, String> labels = new LinkedHashMap<>();
		for (SetupStyle style : SetupStyle.values())
		{
			labels.put(style.name(), style.getLabel());
		}
		return labels;
	}

	private static Map<String, String> gearLabels()
	{
		final Map<String, String> labels = new LinkedHashMap<>();
		for (GearFocus gear : GearFocus.values())
		{
			labels.put(gear.name(), gear.getLabel());
		}
		return labels;
	}

	/** {@code +6}, {@code 0} or {@code -2}. */
	static String signed(int n)
	{
		return n > 0 ? "+" + n : Integer.toString(n);
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.util.function.*;

/**
 * Where the sidebar's setup tag images come from: the game images {@link SetupTagIcons} names, asked for once
 * each through {@link SetupImages} for the live card's toggles and the Task history rows. The plugin backs it with
 * RuneLite's {@code ItemManager} (the cannon barrels item) and {@code SpriteManager} (the spell and skill sprites),
 * {@link SlayerLedgerPlugin#loadSetupIcon}; tests pass a fake. Called on the EDT.
 */
@FunctionalInterface
interface SetupIcons
{
	/**
	 * Asks for {@code icon}'s image and hands it to {@code show} on the EDT, at once or later (a sprite waits for the
	 * game's cache). An item icon may be handed over blank and drawn afterwards: {@code repaint} is then run, on any
	 * thread, once it is drawn.
	 */
	void load(SetupTagIcons.Icon icon, Consumer<Image> show, Runnable repaint);
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.concurrent.*;
import java.util.function.*;
import lombok.*;

/**
 * The sidebar's setup tag images: the game images {@link SetupTagIcons} names, the same ones the overlay draws,
 * for the live card's setup toggles ({@link SetupToggles}) and the Task history rows' tag icons
 * ({@link HistoryListSection}). The panel makes one and hands it to both through {@link SidebarIcons}, so each image is
 * asked for once from {@link SetupIcons} (the plugin's {@code loadSetupIcon}: the cannon barrels from
 * {@code ItemManager}, the spell and skill sprites from {@code SpriteManager}), the first time either needs it, and kept
 * while the panel lasts.
 *
 * <p>An image handed over at once (an item icon, which may still be blank) is returned by {@link #get}; one handed over
 * later (a sprite, which waits for the game's cache) is kept and announced to every listener ({@link #addListener}), on
 * the EDT. When a blank item icon has been drawn, every listener's repaint runs, on any thread. EDT only, but for those
 * repaints.</p>
 */
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class SetupImages
{
	/** Where the images come from (the plugin's {@code loadSetupIcon}; a fake in tests). */
	private final SetupIcons source;
	/** The images that have arrived. */
	private final Map<SetupTagIcons.Icon, Image> images = new EnumMap<>(SetupTagIcons.Icon.class);
	/** The images asked for: each only once. */
	private final Set<SetupTagIcons.Icon> requested = EnumSet.noneOf(SetupTagIcons.Icon.class);
	/** Told on the EDT which image arrived after it was asked for. */
	private final List<Consumer<SetupTagIcons.Icon>> listeners = new ArrayList<>();
	/** Run, on any thread, when an item icon handed over blank has been drawn. */
	private final List<Runnable> repaints = new CopyOnWriteArrayList<>();
	/** True while an image is asked for, so one handed over at once is returned rather than announced. */
	private boolean asking;

	/**
	 * Adds a user of the images: {@code arrived} is told on the EDT which image arrived after it was asked for, and
	 * {@code repaint} runs, on any thread, when an item icon handed over blank has been drawn. Both are kept while the
	 * panel lasts.
	 */
	void addListener(Consumer<SetupTagIcons.Icon> arrived, Runnable repaint)
	{
		listeners.add(arrived);
		repaints.add(repaint);
	}

	/**
	 * {@code icon}'s image as it has arrived, asking for it the first time; {@code null} for {@code null} or an image
	 * not arrived yet (its listeners are told when it does).
	 */
	Image get(SetupTagIcons.Icon icon)
	{
		if (icon == null)
		{
			return null;
		}
		if (requested.add(icon))
		{
			asking = true;
			try
			{
				source.load(icon, image -> arrived(icon, image), this::repaintAll);
			}
			finally
			{
				asking = false;
			}
		}
		return images.get(icon);
	}

	/** {@code icon}'s image was handed over (EDT): kept and, unless it came at once, announced. */
	private void arrived(SetupTagIcons.Icon icon, Image image)
	{
		if (image == null)
		{
			return;
		}
		images.put(icon, image);
		if (asking)
		{
			return;
		}
		for (Consumer<SetupTagIcons.Icon> listener : new ArrayList<>(listeners))
		{
			listener.accept(icon);
		}
	}

	private void repaintAll()
	{
		for (Runnable repaint : repaints)
		{
			repaint.run();
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * A session's setup kill contexts, as counts (V2 plan 4.3): how many task kills were cannon kills, how many were
 * made with each style and in each gear focus, and the range of the prayer bonus seen at those kills. The plugin
 * counts them per task kill ({@link SessionTracker#addKillContext}); a session starts with none ({@link #NONE}).
 * Shared by {@link SessionTracker.Summary},
 * {@link SessionSnapshot} and {@link LedgerRecord}, which keep them as flat fields of their own ({@code cannonKills},
 * {@code styleKills}, {@code gearKills}, {@code prayerBonusMin}, {@code prayerBonusMax}). Immutable. No RuneLite
 * dependencies.
 *
 * <p>The style and gear counts are keyed by the {@link SetupStyle} and {@link GearFocus} names, as strings, so a key a
 * later build adds survives a restore and a save by this one. Only positive counts are kept. Everything is
 * {@code null} (unknown) until a first kill context is counted: a migrated record, or one saved before setup detection,
 * has no counts, which is not the same as counts of 0.</p>
 */
@Value
final class SetupKills
{
	/** No kill context counted. */
	static final SetupKills NONE = new SetupKills(null, null, null, null, null);

	/** Cannon kills, or {@code null} when no kill context was counted. */
	private final Integer cannonKills;
	/** Kills per style name ({@link SetupStyle#name()}); never {@code null}, unmodifiable. */
	private final Map<String, Integer> styleKills;
	/** Kills per gear focus name ({@link GearFocus#name()}); never {@code null}, unmodifiable. */
	private final Map<String, Integer> gearKills;
	/** The lowest prayer bonus seen at a kill, or {@code null}. */
	private final Integer prayerBonusMin;
	/** The highest prayer bonus seen at a kill, or {@code null}. */
	private final Integer prayerBonusMax;

	private SetupKills(Integer cannonKills, Map<String, Integer> styleKills, Map<String, Integer> gearKills,
		Integer prayerBonusMin, Integer prayerBonusMax)
	{
		this.cannonKills = cannonKills == null ? null : Math.max(0, cannonKills);
		this.styleKills = Collections.unmodifiableMap(positive(styleKills));
		this.gearKills = Collections.unmodifiableMap(positive(gearKills));
		this.prayerBonusMin = prayerBonusMin;
		this.prayerBonusMax = prayerBonusMax;
	}

	/**
	 * The given counts, cleaned: negative cannon kills become 0, entries without a key or with a count below 1 are left
	 * out, and a prayer bonus range is kept only when both ends are known and in order.
	 */
	static SetupKills of(Integer cannonKills, Map<String, Integer> styleKills, Map<String, Integer> gearKills,
		Integer prayerBonusMin, Integer prayerBonusMax)
	{
		final boolean range = prayerBonusMin != null && prayerBonusMax != null && prayerBonusMin <= prayerBonusMax;
		final SetupKills kills = new SetupKills(cannonKills, styleKills, gearKills, range ? prayerBonusMin : null,
			range ? prayerBonusMax : null);
		return kills.isEmpty() ? NONE : kills;
	}

	/**
	 * A copy with one more task kill's context counted (the tracker calls this per kill, {@link
	 * SessionTracker#addKillContext}).
	 *
	 * @param cannon      whether it was a cannon kill
	 * @param style       its style, or {@code null} for none (a cannon-only kill)
	 * @param gear        its gear focus, or {@code null} for none
	 * @param prayerBonus the worn prayer bonus at the kill, or {@code null} when not read
	 */
	SetupKills withKill(boolean cannon, SetupStyle style, GearFocus gear, Integer prayerBonus)
	{
		final int cannonCount = saturatedAdd(cannonKills == null ? 0 : cannonKills, cannon ? 1 : 0);
		final Map<String, Integer> styles = new TreeMap<>(styleKills);
		if (style != null)
		{
			styles.merge(style.name(), 1, SetupKills::saturatedAdd);
		}
		final Map<String, Integer> gears = new TreeMap<>(gearKills);
		if (gear != null)
		{
			gears.merge(gear.name(), 1, SetupKills::saturatedAdd);
		}
		Integer min = prayerBonusMin;
		Integer max = prayerBonusMax;
		if (prayerBonus != null)
		{
			min = min == null ? prayerBonus : Math.min(min, prayerBonus);
			max = max == null ? prayerBonus : Math.max(max, prayerBonus);
		}
		return new SetupKills(cannonCount, styles, gears, min, max);
	}

	/** Whether no kill context was counted. */
	boolean isEmpty()
	{
		return cannonKills == null && styleKills.isEmpty() && gearKills.isEmpty() && prayerBonusMin == null;
	}

	/** Kills made with {@code style}; 0 for none. */
	int styleKills(SetupStyle style)
	{
		return style == null ? 0 : styleKills.getOrDefault(style.name(), 0);
	}

	/** Kills made in {@code gear}; 0 for none. */
	int gearKills(GearFocus gear)
	{
		return gear == null ? 0 : gearKills.getOrDefault(gear.name(), 0);
	}

	/** The record's counts as stored. */
	static SetupKills from(LedgerRecord record)
	{
		return of(record.getCannonKills(), record.getStyleKills(), record.getGearKills(), record.getPrayerBonusMin(),
			record.getPrayerBonusMax());
	}

	/** The snapshot's counts as stored. */
	static SetupKills from(SessionSnapshot snapshot)
	{
		return of(snapshot.getCannonKills(), snapshot.getStyleKills(), snapshot.getGearKills(),
			snapshot.getPrayerBonusMin(), snapshot.getPrayerBonusMax());
	}

	/** Sets the record's count fields ({@code null} for what was not counted, and for empty maps). */
	void copyTo(LedgerRecord record)
	{
		record.setCannonKills(cannonKills);
		record.setStyleKills(mapOrNull(styleKills));
		record.setGearKills(mapOrNull(gearKills));
		record.setPrayerBonusMin(prayerBonusMin);
		record.setPrayerBonusMax(prayerBonusMax);
	}

	/** Sets the snapshot's count fields, as {@link #copyTo(LedgerRecord)}. */
	void copyTo(SessionSnapshot snapshot)
	{
		snapshot.setCannonKills(cannonKills);
		snapshot.setStyleKills(mapOrNull(styleKills));
		snapshot.setGearKills(mapOrNull(gearKills));
		snapshot.setPrayerBonusMin(prayerBonusMin);
		snapshot.setPrayerBonusMax(prayerBonusMax);
	}

	private static Map<String, Integer> mapOrNull(Map<String, Integer> counts)
	{
		return counts.isEmpty() ? null : new TreeMap<>(counts);
	}

	private static Map<String, Integer> positive(Map<String, Integer> counts)
	{
		final Map<String, Integer> result = new TreeMap<>();
		if (counts != null)
		{
			for (Map.Entry<String, Integer> e : counts.entrySet())
			{
				if (e.getKey() != null && !e.getKey().trim().isEmpty() && e.getValue() != null && e.getValue() > 0)
				{
					result.put(e.getKey(), e.getValue());
				}
			}
		}
		return result;
	}

	private static int saturatedAdd(int a, int b)
	{
		final long sum = (long) a + b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import net.runelite.api.gameval.*;

/**
 * Migrates a 1.x ledger record to the 2.0 record (V2 plan 4.3) when it is read: a record whose
 * {@link LedgerRecord#getSchemaVersion() schemaVersion} is below {@link #MIGRATED_VERSION} gets estimated setup tags and
 * the current schema version, in memory. {@link LedgerStore} calls it for every record it reads, so a record's saved
 * form changes only when the file is next written, and a record is never migrated twice. Pure (no RuneLite types; the
 * rune ids are gameval {@code ItemID} constants, plain ints).
 *
 * <p>The rules (a 1.x record has no kill contexts, so they work from what it kept):</p>
 * <ul>
 * <li><b>Cannon</b>: from the cannonballs used ({@link CannonTasks#fired}), as 1.x classified it: yes when any were
 * fired, no otherwise (also for a record saved before supplies were tracked). Estimated, because 2.0 tags a cannon task
 * only when most of its kills were cannon kills.</li>
 * <li><b>Style</b>: estimated from the XP shares of the combat skills ({@link #estimateStyle}). Melee XP is Attack and
 * Strength, plus Defence when there is any of them; Defence alone (longrange, defensive casting, or a melee Defence
 * stance) can't be told apart, so it is left out. Ranged XP is left out on a cannon task, since the cannon gives Ranged
 * XP. Magic XP is Barrage when the supplies include Ancient Magicks runes or are empty ({@link #barrageRunes}),
 * otherwise Magic. The style with at least half of that XP is the task's style; a tie between two styles, or none
 * reaching half, is Mixed. With no such XP left (no XP kept, or a cannon task done with ranged), the style is Unknown,
 * which is not an estimate.</li>
 * <li><b>Gear</b>: Unknown (1.x kept no equipment).</li>
 * </ul>
 * <p>It also gets the boss flag ({@link TaskVariants#migrate}): from its kills by NPC when it has any (a 1.x
 * record has none), else from its boss kill counts. Its variant is kept as saved: a 1.x record's is a Catacombs
 * variant's name or none, named as this version names it. Kills by NPC, the kill-context counts, overrides and the spot
 * are left as they are (none).</p>
 */
final class SetupMigration
{
	/** The record schema version that introduced the setup tags; a record below it is migrated when read. */
	static final int MIGRATED_VERSION = 3;

	private static final String ATTACK = "ATTACK";
	private static final String STRENGTH = "STRENGTH";
	private static final String DEFENCE = "DEFENCE";
	private static final String RANGED = "RANGED";
	private static final String MAGIC = "MAGIC";

	private SetupMigration()
	{
	}

	/**
	 * Migrates {@code record} in place when its schema version is below {@link #MIGRATED_VERSION}: sets its estimated
	 * tags, its boss flag and {@link LedgerRecord#CURRENT_SCHEMA_VERSION}. Leaves a 2.0 (or newer) record alone.
	 *
	 * @return whether it was migrated
	 */
	static boolean migrate(LedgerRecord record)
	{
		if (record == null || record.getSchemaVersion() >= MIGRATED_VERSION)
		{
			return false;
		}
		final boolean cannon = CannonTasks.fired(record.getSupplies());
		final SetupStyle style = estimateStyle(record.getXpGained(), record.getSupplies(), cannon);
		final SetupOverrides kept = SetupOverrides.from(record);
		SetupTags.estimated(cannon, style).withOverrides(kept).copyTo(record);
		TaskVariants.migrate(record);
		// This step's own version, so a later step added after it still runs on a record it migrated.
		record.setSchemaVersion(MIGRATED_VERSION);
		return true;
	}

	/**
	 * A 1.x task's estimated style from its XP gained per skill (see the class comment).
	 *
	 * @param xp       XP gained per skill, keyed by RuneLite's {@code Skill} names, or {@code null} when not kept
	 * @param supplies supplies used (item id to quantity), or {@code null} when not kept
	 * @param cannon   whether it was a cannon task, so its Ranged XP is left out
	 * @return the style, {@link SetupStyle#UNKNOWN} when no XP is left to estimate from
	 */
	static SetupStyle estimateStyle(Map<String, Long> xp, Map<Integer, Long> supplies, boolean cannon)
	{
		if (xp == null)
		{
			return SetupStyle.UNKNOWN;
		}
		final long attackStrength = add(xp(xp, ATTACK), xp(xp, STRENGTH));
		final long defence = xp(xp, DEFENCE);
		final long magic = xp(xp, MAGIC);
		final long melee;
		if (attackStrength > 0)
		{
			melee = add(attackStrength, defence);
		}
		else if (defence > add(xp(xp, RANGED), magic))
		{
			// A melee Defence stance (4 Defence XP per damage): longrange gives as much Ranged XP as Defence XP, and
			// defensive casting less Defence XP than Magic XP, so neither gets here.
			melee = defence;
		}
		else
		{
			melee = 0;
		}
		final long ranged = cannon ? 0 : xp(xp, RANGED);
		final long total = add(add(melee, ranged), magic);
		if (total <= 0)
		{
			return SetupStyle.UNKNOWN;
		}
		final SetupStyle magicStyle = barrageRunes(supplies) ? SetupStyle.BARRAGE : SetupStyle.MAGIC;
		final long[] shares = {melee, ranged, magic};
		final SetupStyle[] styles = {SetupStyle.MELEE, SetupStyle.RANGED, magicStyle};
		long most = 0;
		int mostIndex = -1;
		boolean tie = false;
		for (int i = 0; i < shares.length; i++)
		{
			if (shares[i] > most)
			{
				most = shares[i];
				mostIndex = i;
				tie = false;
			}
			else if (shares[i] == most && most > 0)
			{
				tie = true;
			}
		}
		// At least half (most >= total - most, without overflow), and no other style with as much.
		if (mostIndex < 0 || tie || most < total - most)
		{
			return SetupStyle.MIXED;
		}
		return styles[mostIndex];
	}

	/**
	 * Whether a task's Magic XP counts as Barrage: its supplies are empty (none kept, as on a task whose supplies were
	 * not counted) or include Ancient Magicks runes in their own proportions. Every Barrage or Blitz uses between half
	 * and twice as many blood runes as death runes; every Burst uses about twice as many chaos runes as death runes
	 * (a Rush, like a trident cast, uses as many). A trident's charges are counted as one death and one chaos rune per
	 * cast ({@link ChargedWeaponUsage}), so they don't count. A Sanguinesti staff's blood runes, or Tumeken's shadow's
	 * chaos runes, with a few death runes from thralls fall far outside both proportions, so they don't either.
	 */
	static boolean barrageRunes(Map<Integer, Long> supplies)
	{
		if (isEmpty(supplies))
		{
			return true;
		}
		final long death = quantity(supplies, ItemID.DEATHRUNE);
		final long blood = quantity(supplies, ItemID.BLOODRUNE);
		final long chaos = quantity(supplies, ItemID.CHAOSRUNE);
		if (death <= 0)
		{
			return false;
		}
		// Blood between half and twice the death runes (Barrage, Blitz); chaos between 1.5 and 2.5 times (Burst).
		final boolean bloodRatio = blood > 0 && 2 * blood >= death && blood <= 2 * death;
		final boolean chaosRatio = 2 * chaos >= 3 * death && 2 * chaos <= 5 * death;
		return bloodRatio || chaosRatio;
	}

	private static boolean isEmpty(Map<Integer, Long> supplies)
	{
		if (supplies == null)
		{
			return true;
		}
		for (Long quantity : supplies.values())
		{
			if (quantity != null && quantity > 0)
			{
				return false;
			}
		}
		return true;
	}

	private static long quantity(Map<Integer, Long> supplies, int itemId)
	{
		final Long quantity = supplies.get(itemId);
		return quantity == null ? 0 : Math.max(0, quantity);
	}

	private static long xp(Map<String, Long> xp, String skill)
	{
		final Long gained = xp.get(skill);
		return gained == null ? 0 : Math.max(0, gained);
	}

	private static long add(long a, long b)
	{
		final long sum = a + b;
		return sum < 0 ? Long.MAX_VALUE : sum;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * The player's overrides of a task's setup tags (V2 plan 4.3): cannon, style and gear focus, each {@code null}
 * when not overridden (the detected value counts, see {@link SetupTags}). Shared by {@link SessionTracker} (the live
 * task), {@link SessionTracker.Summary}, {@link SessionSnapshot} and {@link LedgerRecord}, which keep them as flat
 * fields of their own ({@code cannonOverride}, {@code styleOverride}, {@code gearOverride}). Immutable; an
 * {@link SetupStyle#UNKNOWN} or {@link GearFocus#UNKNOWN} override is no override. No RuneLite dependencies.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class SetupOverrides
{
	/** Nothing overridden. */
	static final SetupOverrides NONE = new SetupOverrides(null, null, null);

	/** {@code true} for "done with a cannon", {@code false} for "without", {@code null} for no override. */
	Boolean cannon;
	/** The style the player set, or {@code null}; never {@link SetupStyle#UNKNOWN}. */
	SetupStyle style;
	/** The gear focus the player set, or {@code null}; never {@link GearFocus#UNKNOWN}. */
	GearFocus gear;

	/** The given overrides, each {@code null} (or Unknown) for none. */
	static SetupOverrides of(Boolean cannon, SetupStyle style, GearFocus gear)
	{
		final SetupStyle s = style == SetupStyle.UNKNOWN ? null : style;
		final GearFocus g = gear == GearFocus.UNKNOWN ? null : gear;
		return cannon == null && s == null && g == null ? NONE : new SetupOverrides(cannon, s, g);
	}

	/** Whether nothing is overridden. */
	boolean isEmpty()
	{
		return cannon == null && style == null && gear == null;
	}

	/** A copy with the cannon override set ({@code null} clears it). */
	SetupOverrides withCannon(Boolean newCannon)
	{
		return of(newCannon, style, gear);
	}

	/** A copy with the style override set ({@code null} or Unknown clears it). */
	SetupOverrides withStyle(SetupStyle newStyle)
	{
		return of(cannon, newStyle, gear);
	}

	/** A copy with the gear override set ({@code null} or Unknown clears it). */
	SetupOverrides withGear(GearFocus newGear)
	{
		return of(cannon, style, newGear);
	}

	/** The record's overrides as stored. */
	static SetupOverrides from(LedgerRecord record)
	{
		return of(record.getCannonOverride(), record.getStyleOverride(), record.getGearOverride());
	}

	/** The snapshot's overrides as stored. */
	static SetupOverrides from(SessionSnapshot snapshot)
	{
		return of(snapshot.getCannonOverride(), snapshot.getStyleOverride(), snapshot.getGearOverride());
	}

	/** Sets the record's override fields ({@code null} where there is none). */
	void copyTo(LedgerRecord record)
	{
		record.setCannonOverride(cannon);
		record.setStyleOverride(style);
		record.setGearOverride(gear);
	}

	/** Sets the snapshot's override fields ({@code null} where there is none). */
	void copyTo(SessionSnapshot snapshot)
	{
		snapshot.setCannonOverride(cannon);
		snapshot.setStyleOverride(style);
		snapshot.setGearOverride(gear);
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * A task's attack style setup tag (V2 plan 4.3): how most of its kills were made. Saved by name in
 * {@link LedgerRecord} and {@link SessionSnapshot}; a name this build doesn't know reads as {@code null}, which counts
 * as {@link #UNKNOWN}. Pure (no RuneLite types).
 */
@Getter
@RequiredArgsConstructor
enum SetupStyle
{
	MELEE("Melee"),
	RANGED("Ranged"),
	/** Ancient Magicks' multi-target spells: Burst and Barrage share their cast animations. */
	BARRAGE("Barrage"),
	/** Any other spell, including Rush and Blitz. */
	MAGIC("Magic"),
	/** No style did most of the work: a tie, or none reached half. */
	MIXED("Mixed"),
	/** Nothing to tell it from: no styled kill, or (on a migrated task) no combat XP left to estimate from. */
	UNKNOWN("Unknown");

	/** The style as shown, for example "Barrage". */
	private final String label;
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;
import net.runelite.api.gameval.*;

/**
 * The small sprites that stand for a task's setup tags (V2 plan 4.3, DESIGN_PRINCIPLES.md 2.1 and 3.4): the overlay's
 * identity line shows them after the spot's name, and the sidebar can show the same ones. Pure: it says which
 * game image stands for which tag; the caller loads it (an item icon through {@code ItemManager}, a sprite through
 * {@code SpriteManager}) at the size it needs.
 *
 * <p>The images are the game's own: the cannon barrels item for a cannon task; Ice Barrage's spell icon for Barrage;
 * the Ranged, Magic and Attack skill icons for the Ranged, Magic and Melee styles; the Prayer and Strength skill icons
 * for the gear focus. Mixed and Unknown have no sprite: a tag that says nothing gets no image (the tooltips still name
 * it, and the live card's setup toggles show a short word in its place).</p>
 *
 * <p>The sidebar (the live card's setup toggles and the Task history rows) shows the same images, each asked for
 * once on the EDT through {@link SetupImages} (the plugin's {@code loadSetupIcon}: {@code ItemManager} for the cannon
 * barrels, {@code SpriteManager.getSpriteAsync} for the sprites). Each history row's icon comes with how its tag was
 * decided ({@link #tags}): an estimate on a migrated 1.x task, or set by the player.</p>
 */
final class SetupTagIcons
{
	/** Added to a tag's tooltip when its value is an estimate (a migrated 1.x task, {@link SetupTags}). */
	static final String ESTIMATED = " (estimated)";
	/** Added to a tag's tooltip when the player set its value (an override, {@link SetupOverrides}). */
	static final String SET_BY_YOU = " (set by you)";

	/** One tag's image: an item icon or a game sprite (sprite archive, frame 0). */
	@Getter
	@AllArgsConstructor
	enum Icon
	{
		/** A cannon task: the cannon barrels item ({@code ItemID.TWPART3}, "Cannon barrels"). */
		CANNON("Cannon", ItemID.TWPART3, true),
		/** Barrage style: Ice Barrage's spell icon ({@code SpriteID.Magicon2.ICE_BARRAGE}). */
		BARRAGE("Barrage", SpriteID.Magicon2.ICE_BARRAGE, false),
		/** Ranged style: the Ranged skill icon. */
		RANGED("Ranged", SpriteID.Staticons.RANGED, false),
		/** Magic style (other spells): the Magic skill icon. */
		MAGIC("Magic", SpriteID.Staticons.MAGIC, false),
		/** Melee style: the Attack skill icon. */
		MELEE("Melee", SpriteID.Staticons.ATTACK, false),
		/** Prayer gear focus: the Prayer skill icon. */
		PRAYER("Prayer gear", SpriteID.Staticons.PRAYER, false),
		/** Strength gear focus: the Strength skill icon. */
		STRENGTH("Strength gear", SpriteID.Staticons.STRENGTH, false);

		/** What the image stands for, for a tooltip: {@code Cannon}, {@code Barrage}, {@code Prayer gear}. */
		private final String name;
		/** The item id ({@link #isItem}) or the sprite archive id. */
		private final int id;
		/** Whether {@link #getId} is an item id (else a sprite archive, drawn from frame 0). */
		private final boolean item;
	}

	/**
	 * One effective tag's image with how its value was decided, for the sidebar: an estimate (a migrated 1.x task) or
	 * set by the player (never both: an overridden tag is never estimated, {@link SetupTags}). Immutable.
	 */
	@Getter
	@EqualsAndHashCode
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	static final class Tag
	{
		private final Icon icon;
		/** Whether the value is an estimate: detected on a migrated 1.x task and not set by the player. */
		private final boolean estimated;
		/** Whether the player set the value (an override). */
		private final boolean setByYou;

		/**
		 * The icon's tooltip, plain text: what it stands for ({@link Icon#getName}), then {@link #ESTIMATED} or
		 * {@link #SET_BY_YOU}: {@code Cannon}, {@code Barrage (estimated)}, {@code Prayer gear (set by you)}.
		 */
		String getTooltip()
		{
			return icon.getName() + (estimated ? ESTIMATED : "") + (setByYou ? SET_BY_YOU : "");
		}

		@Override
		public String toString()
		{
			return getTooltip();
		}
	}

	private SetupTagIcons()
	{
	}

	/**
	 * The images for {@code tags}' effective values, in a fixed order (cannon, style, gear focus); empty for
	 * {@code null}. Mixed and Unknown add none.
	 */
	static List<Icon> of(SetupTags tags)
	{
		final List<Tag> shown = tags(tags);
		final List<Icon> icons = new ArrayList<>(shown.size());
		for (Tag tag : shown)
		{
			icons.add(tag.getIcon());
		}
		return Collections.unmodifiableList(icons);
	}

	/**
	 * {@link #of}'s images, each with how its tag was decided (estimated or set by the player), in the same order;
	 * empty for {@code null}.
	 */
	static List<Tag> tags(SetupTags tags)
	{
		if (tags == null)
		{
			return Collections.emptyList();
		}
		final SetupOverrides overrides = tags.getOverrides();
		final List<Tag> shown = new ArrayList<>(3);
		if (tags.isCannon())
		{
			shown.add(new Tag(Icon.CANNON, tags.isCannonEstimated(), overrides.getCannon() != null));
		}
		final Icon style = style(tags.getStyle());
		if (style != null)
		{
			shown.add(new Tag(style, tags.isStyleEstimated(), overrides.getStyle() != null));
		}
		final Icon gear = gear(tags.getGear());
		if (gear != null)
		{
			shown.add(new Tag(gear, tags.isGearEstimated(), overrides.getGear() != null));
		}
		return Collections.unmodifiableList(shown);
	}

	/** The image for an attack style, or {@code null} for Mixed, Unknown and {@code null}. */
	static Icon style(SetupStyle style)
	{
		if (style == null)
		{
			return null;
		}
		switch (style)
		{
			case MELEE:
				return Icon.MELEE;
			case RANGED:
				return Icon.RANGED;
			case BARRAGE:
				return Icon.BARRAGE;
			case MAGIC:
				return Icon.MAGIC;
			default:
				return null;
		}
	}

	/** The image for a gear focus, or {@code null} for Mixed, Unknown and {@code null}. */
	static Icon gear(GearFocus gear)
	{
		if (gear == null)
		{
			return null;
		}
		switch (gear)
		{
			case PRAYER:
				return Icon.PRAYER;
			case STRENGTH:
				return Icon.STRENGTH;
			default:
				return null;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * A task's setup tags (V2 plan 4.3): cannon, style and gear focus, each with its detected value, whether that
 * value is an estimate (a migrated 1.x task, {@link SetupMigration}) and the player's override ({@link SetupOverrides}).
 * This is the one place that decides a tag's <b>effective</b> value: the override when there is one, else the detected
 * value. An overridden tag is never estimated. The history tooltip shows the effective values, and the grouping,
 * filters and advisor read only them ({@link #isCannon()}, {@link #getStyle()}, {@link #getGear()} and their
 * {@code is...Estimated}), the cannon task name too ({@link LedgerRecord#cannonTask}). Immutable; pure (no RuneLite
 * types).
 *
 * <p>Cannon is never Unknown: a record without a stored detected cannon falls back to its supplies
 * ({@link CannonTasks#fired}), as 1.x classified it. Style and gear may be {@link SetupStyle#UNKNOWN} and
 * {@link GearFocus#UNKNOWN}, which are never estimated.</p>
 */
@EqualsAndHashCode(doNotUseGetters = true)
@ToString(doNotUseGetters = true)
final class SetupTags
{
	/** The last tooltip line when a detected value is an estimate. */
	static final String ESTIMATE_NOTE = "~ estimated: saved before setup was recorded";

	/** The detected cannon (the fallback for a record that stored none), whatever the override. */
	@Getter
	private final boolean detectedCannon;
	/** The detected style (never {@code null}), whatever the override. */
	@Getter
	private final SetupStyle detectedStyle;
	/** The detected gear focus (never {@code null}), whatever the override. */
	@Getter
	private final GearFocus detectedGear;
	private final boolean cannonEstimated;
	private final boolean styleEstimated;
	private final boolean gearEstimated;
	/** The player's overrides (never {@code null}). */
	@Getter
	private final SetupOverrides overrides;
	/**
	 * Whether a detected value or an override was stored (a record saved or migrated by 2.0, or a live session).
	 * {@code false} only for a record built without them (never one read through {@link LedgerStore}), whose tags are
	 * then all fallbacks.
	 */
	@Getter
	private final boolean recorded;

	private SetupTags(boolean detectedCannon, boolean cannonEstimated, SetupStyle detectedStyle,
		boolean styleEstimated, GearFocus detectedGear, boolean gearEstimated, SetupOverrides overrides,
		boolean recorded)
	{
		this.detectedCannon = detectedCannon;
		this.detectedStyle = detectedStyle == null ? SetupStyle.UNKNOWN : detectedStyle;
		this.detectedGear = detectedGear == null ? GearFocus.UNKNOWN : detectedGear;
		this.cannonEstimated = cannonEstimated;
		// Unknown is never an estimate (V2 plan 4.3: the two are treated differently).
		this.styleEstimated = styleEstimated && this.detectedStyle != SetupStyle.UNKNOWN;
		this.gearEstimated = gearEstimated && this.detectedGear != GearFocus.UNKNOWN;
		this.overrides = overrides == null ? SetupOverrides.NONE : overrides;
		this.recorded = recorded;
	}

	/**
	 * Detected tags (none estimated) with the given overrides, as a live session or a new record has them.
	 *
	 * @param style {@code null} is {@link SetupStyle#UNKNOWN}
	 * @param gear  {@code null} is {@link GearFocus#UNKNOWN}
	 */
	static SetupTags detected(boolean cannon, SetupStyle style, GearFocus gear, SetupOverrides overrides)
	{
		return new SetupTags(cannon, false, style, false, gear, false, overrides, true);
	}

	/**
	 * The tags of a migrated task: the estimated cannon and style (a style of Unknown is not an estimate) and an Unknown
	 * gear focus, with no overrides.
	 */
	static SetupTags estimated(boolean cannon, SetupStyle style)
	{
		return new SetupTags(cannon, true, style, true, GearFocus.UNKNOWN, false, SetupOverrides.NONE, true);
	}

	/**
	 * A session's detected tags, as the live task shows them and its record keeps them, from its kill contexts
	 * ({@link SetupDetection}): Cannon when at least half of its {@code taskKills} were cannon kills, the style covering
	 * at least half of its styled kills, and the gear focus of most kills. A session with no kill context counted (one
	 * restored from a 1.x version's file, or before its first kill's context is known) falls back to its fired
	 * cannonballs for the cannon ({@link CannonTasks#fired}), as a record without tags does, with an Unknown style and
	 * gear focus.
	 *
	 * @param supplies  the session's supplies used, or {@code null}
	 * @param kills     the session's kill contexts
	 * @param taskKills the session's task kills that may have a kill context ({@link SessionTracker#contextKills}): its
	 *                  kill count, less the kills a 1.x version counted before a restore
	 */
	static SetupTags forSession(ItemTally supplies, SetupKills kills, int taskKills, SetupOverrides overrides)
	{
		final SetupKills counted = kills == null ? SetupKills.NONE : kills;
		final boolean cannon = counted.getCannonKills() == null ? CannonTasks.fired(supplies)
			: SetupDetection.cannon(counted.getCannonKills(), taskKills);
		return detected(cannon, SetupDetection.taskStyle(counted.getStyleKills()),
			SetupDetection.taskGear(counted.getGearKills()), overrides);
	}

	/**
	 * The record's tags as stored. A tag without a stored detected value is Unknown, except the cannon, which falls back
	 * to the record's supplies. Records read through {@link LedgerStore} were saved or migrated by 2.0 and always store
	 * every detected value.
	 */
	static SetupTags of(LedgerRecord record)
	{
		final Boolean cannon = record.getDetectedCannon();
		final SetupOverrides overrides = SetupOverrides.from(record);
		final boolean recorded = cannon != null || record.getDetectedStyle() != null
			|| record.getDetectedGear() != null || !overrides.isEmpty();
		return new SetupTags(cannon != null ? cannon : CannonTasks.fired(record.getSupplies()),
			Boolean.TRUE.equals(record.getCannonEstimated()), record.getDetectedStyle(),
			Boolean.TRUE.equals(record.getStyleEstimated()), record.getDetectedGear(),
			Boolean.TRUE.equals(record.getGearEstimated()), overrides, recorded);
	}

	/** Sets the record's detected values, estimated flags ({@code null} when not estimated) and overrides. */
	void copyTo(LedgerRecord record)
	{
		record.setDetectedCannon(detectedCannon);
		record.setCannonEstimated(cannonEstimated ? Boolean.TRUE : null);
		record.setDetectedStyle(detectedStyle);
		record.setStyleEstimated(styleEstimated ? Boolean.TRUE : null);
		record.setDetectedGear(detectedGear);
		record.setGearEstimated(gearEstimated ? Boolean.TRUE : null);
		overrides.copyTo(record);
	}

	/** A copy with other overrides ({@code null} for none). */
	SetupTags withOverrides(SetupOverrides newOverrides)
	{
		return new SetupTags(detectedCannon, cannonEstimated, detectedStyle, styleEstimated, detectedGear,
			gearEstimated, newOverrides, true);
	}

	/** The effective cannon: the override, else the detected value. */
	boolean isCannon()
	{
		return overrides.getCannon() != null ? overrides.getCannon() : detectedCannon;
	}

	/** Whether {@link #isCannon()} is an estimate: detected on a migrated task and not overridden. */
	boolean isCannonEstimated()
	{
		return overrides.getCannon() == null && cannonEstimated;
	}

	/** The effective style: the override, else the detected value (never {@code null}). */
	SetupStyle getStyle()
	{
		return overrides.getStyle() != null ? overrides.getStyle() : detectedStyle;
	}

	/** Whether {@link #getStyle()} is an estimate: detected on a migrated task and not overridden. */
	boolean isStyleEstimated()
	{
		return overrides.getStyle() == null && styleEstimated;
	}

	/** The effective gear focus: the override, else the detected value (never {@code null}). */
	GearFocus getGear()
	{
		return overrides.getGear() != null ? overrides.getGear() : detectedGear;
	}

	/** Whether {@link #getGear()} is an estimate: detected on a migrated task and not overridden. */
	boolean isGearEstimated()
	{
		return overrides.getGear() == null && gearEstimated;
	}

	/** Whether the detected cannon is an estimate (a migrated task), whatever the override. */
	boolean isDetectedCannonEstimated()
	{
		return cannonEstimated;
	}

	/** Whether the detected style is an estimate, whatever the override. */
	boolean isDetectedStyleEstimated()
	{
		return styleEstimated;
	}

	/** Whether the detected gear focus is an estimate, whatever the override. */
	boolean isDetectedGearEstimated()
	{
		return gearEstimated;
	}

	/** Whether any detected value is an estimate, overridden or not. */
	boolean hasEstimates()
	{
		return cannonEstimated || styleEstimated || gearEstimated;
	}

	/** "Yes" or "No", as a cannon tag is shown. */
	static String cannonLabel(boolean cannon)
	{
		return cannon ? "Yes" : "No";
	}

	/** A shown value: {@code ~} before an estimate. */
	static String shown(String label, boolean estimated)
	{
		return estimated ? "~" + label : label;
	}

	/**
	 * The tooltip lines of the tags, as plain text: {@code Cannon: ~Yes}, {@code Style: ~Barrage} and
	 * {@code Gear: Unknown}, an override followed by {@code (set by you; detected ~Yes)}, and a last line explaining
	 * {@code ~} when a detected value is an estimate.
	 */
	List<String> lines()
	{
		final List<String> lines = new ArrayList<>();
		lines.add("Cannon: " + shown(cannonLabel(isCannon()), isCannonEstimated())
			+ overridden(overrides.getCannon() != null, shown(cannonLabel(detectedCannon), cannonEstimated)));
		lines.add("Style: " + shown(getStyle().getLabel(), isStyleEstimated())
			+ overridden(overrides.getStyle() != null, shown(detectedStyle.getLabel(), styleEstimated)));
		lines.add("Gear: " + shown(getGear().getLabel(), isGearEstimated())
			+ overridden(overrides.getGear() != null, shown(detectedGear.getLabel(), gearEstimated)));
		if (hasEstimates())
		{
			lines.add(ESTIMATE_NOTE);
		}
		return lines;
	}

	private static String overridden(boolean overridden, String detected)
	{
		return overridden ? " (set by you; detected " + detected + ")" : "";
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;
import javax.swing.event.*;
import lombok.*;

/**
 * The live task card's setup tags (DESIGN_PRINCIPLES.md 3.4, V2 plan 4.3, sprite toggles): Cannon,
 * Style and Gear as three small toggles in one row. Each is its tag's name in Small and, after it, the game image
 * {@link SetupTagIcons} has for the tag's effective value, fitted into the sidebar's 18 by 16 icon slot. A value with no
 * image has a short word in its place, drawn in {@link LedgerTheme}'s colours: {@code ?} (in the hint colour) for
 * Unknown, {@code Mix} for Mixed and {@code No} for no cannon. A value the player set has a small corner mark in the
 * heading colour, and its tooltip says {@code Set by you}: the mark is never the only cue. Each tooltip gives the tag,
 * its value, whether it was detected or set by you, whether the detected value is an estimate and what it was detected
 * from.
 *
 * <p>A toggle is a button, so Tab reaches it and Space presses it, as the status strip's buttons. A press, or a right
 * click, opens a menu of the tag's {@link SetupChoices}: the detected value first, which clears the player's override,
 * then every value they can set, with the current choice selected; a click on the toggle while its menu is open closes
 * it. A pick goes to {@link #setOnChoose}'s listener and shows at once. The row asks only for the width its three
 * toggles need (188 to 192 px in the RuneScape fonts), inside the card's 199 px. The images come from the sidebar's
 * {@link SetupImages}, which asks for each once, shared with the Task history rows; the toggles are redrawn only when
 * the tags change ({@link #show}), never while a menu is open. EDT only.</p>
 */
final class SetupToggles
{
	/** A toggle's tooltip's last line. */
	static final String HINT = "Click to set it yourself; Detected: uses the detected value.";
	/** The word drawn for Unknown, in the hint colour. */
	static final String UNKNOWN_WORD = "?";
	/** The image slot: the sidebar's small icon slot, as the XP lists' ({@link ItemListView}). */
	static final int SLOT_WIDTH = ItemListView.ICON_WIDTH;
	static final int SLOT_HEIGHT = ItemListView.ICON_HEIGHT;
	/** The override mark: a right triangle in the slot's top right corner, this many pixels a side. */
	static final int MARK_SIZE = 6;
	/** Space between a toggle's name and its image. */
	private static final int ICON_GAP = 3;
	/** The least space between two toggles; the room left over is shared between the gaps. */
	private static final int TOGGLE_GAP = 4;

	/** A setup tag: its name, and how its value, override, image, choices and details are read. */
	@Getter
	@RequiredArgsConstructor
	enum Tag
	{
		CANNON("Cannon"),
		STYLE("Style"),
		GEAR("Gear");

		/** The tag as shown: {@code Cannon}, {@code Style}, {@code Gear}. */
		private final String label;

		/** The name of its toggle's parts ({@code setup.cannon}, ...), for tests; no visible effect. */
		String key()
		{
			return "setup." + name().toLowerCase(Locale.ROOT);
		}

		/** The effective value as shown, {@code ~} before an estimate: {@code Yes}, {@code ~Barrage}, {@code Unknown}. */
		String shown(SetupTags tags)
		{
			switch (this)
			{
				case CANNON:
					return SetupTags.shown(SetupTags.cannonLabel(tags.isCannon()), tags.isCannonEstimated());
				case STYLE:
					return SetupTags.shown(tags.getStyle().getLabel(), tags.isStyleEstimated());
				default:
					return SetupTags.shown(tags.getGear().getLabel(), tags.isGearEstimated());
			}
		}

		/** The detected value as shown, whatever the override. */
		String detectedShown(SetupTags tags)
		{
			switch (this)
			{
				case CANNON:
					return SetupTags.shown(SetupTags.cannonLabel(tags.isDetectedCannon()),
						tags.isDetectedCannonEstimated());
				case STYLE:
					return SetupTags.shown(tags.getDetectedStyle().getLabel(), tags.isDetectedStyleEstimated());
				default:
					return SetupTags.shown(tags.getDetectedGear().getLabel(), tags.isDetectedGearEstimated());
			}
		}

		/** Whether the detected value is an estimate (a migrated task), whatever the override. */
		boolean isDetectedEstimated(SetupTags tags)
		{
			switch (this)
			{
				case CANNON:
					return tags.isDetectedCannonEstimated();
				case STYLE:
					return tags.isDetectedStyleEstimated();
				default:
					return tags.isDetectedGearEstimated();
			}
		}

		/** Whether the player set the tag. */
		boolean isOverridden(SetupTags tags)
		{
			final SetupOverrides overrides = tags.getOverrides();
			switch (this)
			{
				case CANNON:
					return overrides.getCannon() != null;
				case STYLE:
					return overrides.getStyle() != null;
				default:
					return overrides.getGear() != null;
			}
		}

		/** The image of the effective value, or {@code null} for one without (no cannon, Mixed, Unknown). */
		SetupTagIcons.Icon icon(SetupTags tags)
		{
			switch (this)
			{
				case CANNON:
					return tags.isCannon() ? SetupTagIcons.Icon.CANNON : null;
				case STYLE:
					return SetupTagIcons.style(tags.getStyle());
				default:
					return SetupTagIcons.gear(tags.getGear());
			}
		}

		/** The menu's choices ({@link SetupChoices}): the detected value first, then every value that can be set. */
		List<? extends SetupChoices.Choice<?>> choices(SetupTags tags)
		{
			switch (this)
			{
				case CANNON:
					return SetupChoices.cannon(tags);
				case STYLE:
					return SetupChoices.style(tags);
				default:
					return SetupChoices.gear(tags);
			}
		}

		/** The index of the current choice in {@link #choices}: the override's, or 0 (detected) without one. */
		int selected(SetupTags tags)
		{
			final SetupOverrides overrides = tags.getOverrides();
			switch (this)
			{
				case CANNON:
					return SetupChoices.indexOf(SetupChoices.cannon(tags), overrides.getCannon());
				case STYLE:
					return SetupChoices.indexOf(SetupChoices.style(tags), overrides.getStyle());
				default:
					return SetupChoices.indexOf(SetupChoices.gear(tags), overrides.getGear());
			}
		}

		/** {@code overrides} with this tag's override set to a choice's value ({@code null} clears it). */
		SetupOverrides with(SetupOverrides overrides, Object value)
		{
			switch (this)
			{
				case CANNON:
					return overrides.withCannon((Boolean) value);
				case STYLE:
					return overrides.withStyle((SetupStyle) value);
				default:
					return overrides.withGear((GearFocus) value);
			}
		}

		/** What the tag was detected from ({@link SetupDetection}), plain text. */
		List<String> details(SetupKills kills, int taskKills)
		{
			switch (this)
			{
				case CANNON:
					return SetupDetection.cannonDetails(kills, taskKills);
				case STYLE:
					return SetupDetection.styleDetails(kills);
				default:
					return SetupDetection.gearDetails(kills);
			}
		}
	}

	/** The tag images, asked for once each and kept (shared with the Task history rows). */
	private final SetupImages images;
	/** The row of the three toggles; shown by the live section while a session is active. */
	private final JPanel row = new JPanel();
	private final Map<Tag, JButton> toggles = new EnumMap<>(Tag.class);
	private final Map<Tag, JPopupMenu> menus = new EnumMap<>(Tag.class);
	/**
	 * The toggle whose open menu the mouse press now going on closed, else {@code null}, with that press's time
	 * ({@link #menuClosing}): the click that press starts must not open the menu again.
	 */
	private Tag closedByPress;
	private long closingPressTime;
	/** Told the overrides the player picked. */
	private Consumer<SetupOverrides> onChoose = overrides -> { };
	/** The tags shown, or {@code null} before a session's are; the menus and a pick read them. */
	private SetupTags shown;
	/** What the tooltips' details come from, as last shown. */
	private SetupKills kills = SetupKills.NONE;
	private int taskKills;
	/** How many times the toggles were redrawn for new tags ({@link #getBuildCount}). */
	private int builds;

	/** @param images the sidebar's setup tag images */
	SetupToggles(SetupImages images)
	{
		this.images = images;
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setOpaque(false);
		// Names for tests, which find the parts by them; no visible effect.
		row.setName("setup");
		for (Tag tag : Tag.values())
		{
			if (tag != Tag.CANNON)
			{
				row.add(Box.createHorizontalStrut(TOGGLE_GAP));
				row.add(Box.createHorizontalGlue());
			}
			row.add(toggle(tag));
		}
		images.addListener(this::arrived, row::repaint);
	}

	private JButton toggle(Tag tag)
	{
		final JButton toggle = new JButton(tag.getLabel());
		toggle.setName(tag.key());
		toggle.setFont(LedgerTheme.smallFont());
		toggle.setForeground(LedgerTheme.LABEL);
		toggle.setBackground(LedgerTheme.CARD);
		toggle.setFocusPainted(false);
		toggle.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(LedgerTheme.BEVEL_INNER, 1),
			BorderFactory.createEmptyBorder(2, 4, 2, 4)));
		// The name, then the image.
		toggle.setHorizontalTextPosition(SwingConstants.LEADING);
		toggle.setIconTextGap(ICON_GAP);
		toggle.setIcon(new Slot(null, null, null, false, null, SLOT_WIDTH));

		final JPopupMenu menu = new JPopupMenu();
		menu.setName(tag.key() + ".menu");
		// Filled from the tags shown each time it opens: a right click, or Shift+F10, opens it as a click does.
		menu.addPopupMenuListener(new PopupMenuListener()
		{
			@Override
			public void popupMenuWillBecomeVisible(PopupMenuEvent e)
			{
				fillMenu(tag);
			}

			@Override
			public void popupMenuWillBecomeInvisible(PopupMenuEvent e)
			{
				menuClosing(tag, EventQueue.getCurrentEvent());
			}

			@Override
			public void popupMenuCanceled(PopupMenuEvent e)
			{
			}
		});
		toggle.setComponentPopupMenu(menu);
		toggle.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed(e);
			}
		});
		toggle.addActionListener(e -> clicked(tag, EventQueue.getCurrentEvent()));
		toggles.put(tag, toggle);
		menus.put(tag, menu);
		return toggle;
	}

	/** The row of toggles, for the card. */
	JComponent getComponent()
	{
		return row;
	}

	/** Sets who is told the overrides the player picked (the live section, which saves them to its session). */
	void setOnChoose(Consumer<SetupOverrides> listener)
	{
		onChoose = listener == null ? overrides -> { } : listener;
	}

	/** Forgets the tags shown (another session or none): the next {@link #show} draws its own. */
	void clear()
	{
		shown = null;
	}

	/**
	 * Shows {@code tags}, detected from {@code setupKills} over {@code killCount} task kills (those that may have a kill
	 * context, {@link SessionTracker#getContextKills}, which the Cannon tooltip's "of" counts): the toggles are redrawn
	 * only when the tags differ from those shown and no menu is open (a pick shows at once, so the tags it led to draw
	 * nothing new); the tooltips change only when their text does.
	 */
	void show(SetupTags tags, SetupKills setupKills, int killCount)
	{
		kills = setupKills == null ? SetupKills.NONE : setupKills;
		taskKills = killCount;
		if (!Objects.equals(tags, shown) && !isMenuOpen())
		{
			shown = tags;
			builds++;
			for (Tag tag : Tag.values())
			{
				draw(tag);
			}
		}
		updateTooltips();
	}

	/** Whether the player has a toggle's menu open. */
	boolean isMenuOpen()
	{
		for (JPopupMenu menu : menus.values())
		{
			if (menu.isVisible())
			{
				return true;
			}
		}
		return false;
	}

	/** How many times the toggles were redrawn for new tags or a pick (the live section's performance seam). */
	int getBuildCount()
	{
		return builds;
	}

	/** Draws {@code tag}'s toggle for the tags shown: its image (or word) and the override mark. */
	private void draw(Tag tag)
	{
		final JButton toggle = toggles.get(tag);
		if (shown == null)
		{
			toggle.setIcon(new Slot(null, null, null, false, null, SLOT_WIDTH));
			return;
		}
		final String word = placeholder(tag, shown);
		final Image image = images.get(tag.icon(shown));
		final FontMetrics metrics = toggle.getFontMetrics(LedgerTheme.smallFont());
		final int width = word == null ? SLOT_WIDTH : Math.max(SLOT_WIDTH, metrics.stringWidth(word) + 2);
		final Color color = word != null && word.equals(UNKNOWN_WORD) ? LedgerTheme.HINT : LedgerTheme.VALUE;
		toggle.setIcon(new Slot(image, word, color, tag.isOverridden(shown), description(tag, shown), width));
	}

	/** {@code icon}'s image arrived after it was asked for (EDT): drawn on the toggle that shows it. */
	private void arrived(SetupTagIcons.Icon icon)
	{
		if (shown == null)
		{
			return;
		}
		for (Tag tag : Tag.values())
		{
			if (tag.icon(shown) == icon)
			{
				draw(tag);
			}
		}
	}

	private void updateTooltips()
	{
		for (Tag tag : Tag.values())
		{
			final JButton toggle = toggles.get(tag);
			final String tooltip = shown == null ? null : tooltip(tag, shown, kills, taskKills);
			if (!Objects.equals(tooltip, toggle.getToolTipText()))
			{
				toggle.setToolTipText(tooltip);
			}
		}
	}

	/**
	 * {@code tag}'s menu is closing while {@code event} is dispatched. Swing closes an open menu on a mouse press outside
	 * it before the component under the mouse gets the press ({@code BasicPopupMenuUI}'s mouse grabber), and the toggle
	 * acts on the release: so a press on the menu's own toggle is noted, and the click it starts only closes the menu
	 * ({@link #clicked}). Any other close (a pick, Escape, a press elsewhere) notes nothing.
	 */
	private void menuClosing(Tag tag, AWTEvent event)
	{
		if (event instanceof MouseEvent && event.getID() == MouseEvent.MOUSE_PRESSED
			&& ((MouseEvent) event).getComponent() == toggles.get(tag))
		{
			closedByPress = tag;
			closingPressTime = ((MouseEvent) event).getWhen();
		}
	}

	/** A mouse press on a toggle, after any menu it closed: a press that closed none forgets an older one's note. */
	private void pressed(MouseEvent press)
	{
		if (press.getWhen() != closingPressTime)
		{
			closedByPress = null;
		}
	}

	/**
	 * {@code tag}'s toggle fired (a mouse click, or Space, while {@code event} is dispatched): opens its menu, unless the
	 * click's press just closed that menu ({@link #menuClosing}), so a second click on an open menu's toggle closes it.
	 */
	private void clicked(Tag tag, AWTEvent event)
	{
		final boolean closedThisMenu = closedByPress == tag && event instanceof MouseEvent;
		closedByPress = null;
		if (!closedThisMenu)
		{
			openMenu(tag);
		}
	}

	/** Fills {@code tag}'s menu and opens it under the toggle. */
	private void openMenu(Tag tag)
	{
		fillMenu(tag);
		final JButton toggle = toggles.get(tag);
		// Only a toggle on screen has a place to open it (never in the headless tests).
		if (toggle.isShowing() && shown != null)
		{
			menus.get(tag).show(toggle, 0, toggle.getHeight());
		}
	}

	/** Fills {@code tag}'s menu with its choices for the tags shown, the current one selected. */
	private void fillMenu(Tag tag)
	{
		final JPopupMenu menu = menus.get(tag);
		menu.removeAll();
		if (shown == null)
		{
			return;
		}
		final List<? extends SetupChoices.Choice<?>> choices = tag.choices(shown);
		final int selected = tag.selected(shown);
		final ButtonGroup group = new ButtonGroup();
		for (int i = 0; i < choices.size(); i++)
		{
			final SetupChoices.Choice<?> choice = choices.get(i);
			final JRadioButtonMenuItem item = new JRadioButtonMenuItem(choice.getLabel(), i == selected);
			item.setFont(LedgerTheme.smallFont());
			final Object value = choice.getValue();
			item.addActionListener(e -> choose(tag, value));
			group.add(item);
			menu.add(item);
		}
	}

	/** The player picked {@code value} for {@code tag} ({@code null}: the detected value): shown, then passed on. */
	private void choose(Tag tag, Object value)
	{
		if (shown == null)
		{
			return;
		}
		final SetupOverrides chosen = tag.with(shown.getOverrides(), value);
		if (chosen.equals(shown.getOverrides()))
		{
			return;
		}
		shown = shown.withOverrides(chosen);
		builds++;
		draw(tag);
		updateTooltips();
		onChoose.accept(chosen);
	}

	/**
	 * The word drawn in place of an image for a value without one, or {@code null} for a value with an image:
	 * {@code ?} for Unknown, {@code Mix} for Mixed, {@code No} for no cannon. The fonts have no glyph that could stand
	 * for these, and emoji are not allowed (DESIGN_PRINCIPLES.md 4.4, 6).
	 */
	static String placeholder(Tag tag, SetupTags tags)
	{
		if (tag.icon(tags) != null)
		{
			return null;
		}
		switch (tag)
		{
			case CANNON:
				return SetupTags.cannonLabel(false);
			case STYLE:
				return tags.getStyle() == SetupStyle.UNKNOWN ? UNKNOWN_WORD : "Mix";
			default:
				return tags.getGear() == GearFocus.UNKNOWN ? UNKNOWN_WORD : "Mix";
		}
	}

	/**
	 * The toggle image's accessible description: the value as shown, with {@code , set by you} when the player set it
	 * ({@code Barrage, set by you}).
	 */
	static String description(Tag tag, SetupTags tags)
	{
		return tag.shown(tags) + (tag.isOverridden(tags) ? ", set by you" : "");
	}

	/**
	 * A toggle's tooltip, as HTML with no player text in it: the tag and its value ({@code Style: Barrage}),
	 * {@code Detected} or {@code Set by you; detected Melee}, the estimate note when the detected value is an estimate
	 * ({@link SetupTags#ESTIMATE_NOTE}), what it was detected from, and {@link #HINT}.
	 */
	static String tooltip(Tag tag, SetupTags tags, SetupKills kills, int taskKills)
	{
		final List<String> lines = new ArrayList<>();
		lines.add(tag.getLabel() + ": " + tag.shown(tags));
		lines.add(tag.isOverridden(tags) ? "Set by you; detected " + tag.detectedShown(tags) : "Detected");
		if (tag.isDetectedEstimated(tags))
		{
			lines.add(SetupTags.ESTIMATE_NOTE);
		}
		lines.addAll(tag.details(kills == null ? SetupKills.NONE : kills, taskKills));
		lines.add(HINT);
		return "<html>" + String.join("<br>", lines) + "</html>";
	}

	/**
	 * A toggle's image slot: the tag's image fitted into it (scaled down, never up, keeping its shape, centred), or a
	 * word centred in it, with the override mark in its top right corner. {@link #getImage()} is the image as it
	 * arrived, {@link #getDescription()} the value it shows.
	 */
	static final class Slot extends ImageIcon
	{
		private final String word;
		private final Color wordColor;
		private final boolean marked;
		private final int width;

		private Slot(Image image, String word, Color wordColor, boolean marked, String description, int width)
		{
			if (image != null)
			{
				setImage(image);
			}
			setDescription(description);
			this.word = word;
			this.wordColor = wordColor;
			this.marked = marked;
			this.width = width;
		}

		@Override
		public int getIconWidth()
		{
			return width;
		}

		@Override
		public int getIconHeight()
		{
			return SLOT_HEIGHT;
		}

		@Override
		public synchronized void paintIcon(Component c, Graphics g, int x, int y)
		{
			final Graphics2D g2 = (Graphics2D) g.create();
			try
			{
				final Image image = getImage();
				if (image != null)
				{
					drawFitted(g2, image, x, y, c);
				}
				else if (word != null)
				{
					g2.setFont(LedgerTheme.smallFont());
					g2.setColor(wordColor);
					final FontMetrics metrics = g2.getFontMetrics();
					g2.drawString(word, x + (width - metrics.stringWidth(word)) / 2,
						y + (SLOT_HEIGHT + metrics.getAscent() - metrics.getDescent()) / 2);
				}
				if (marked)
				{
					g2.setColor(LedgerTheme.HEADING);
					g2.fillPolygon(new int[]{x + width - MARK_SIZE, x + width, x + width},
						new int[]{y, y, y + MARK_SIZE}, 3);
				}
			}
			finally
			{
				g2.dispose();
			}
		}

		private void drawFitted(Graphics2D g2, Image image, int x, int y, Component c)
		{
			final int imageWidth = image.getWidth(null);
			final int imageHeight = image.getHeight(null);
			if (imageWidth <= 0 || imageHeight <= 0)
			{
				return;
			}
			final double scale = Math.min(1, Math.min(width / (double) imageWidth, SLOT_HEIGHT / (double) imageHeight));
			final int drawWidth = Math.max(1, (int) Math.round(imageWidth * scale));
			final int drawHeight = Math.max(1, (int) Math.round(imageHeight * scale));
			g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g2.drawImage(image, x + (width - drawWidth) / 2, y + (SLOT_HEIGHT - drawHeight) / 2, drawWidth, drawHeight,
				c);
		}
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * The sidebar's icon sources, passed as one so a section's constructor stays within 7 parameters: item icons
 * for the supply and loot grids, small skill icons for the XP lists, and the setup tag images of the live card's
 * toggles and the Task history rows. The panel builds it from the plugin; tests use fakes. Used on the EDT.
 */
@Value
class SidebarIcons
{
	/** Icons of the item grids ({@link ItemGridView}). */
	ItemIcons items;
	/** Small icons before the skill names of the XP lists ({@link ItemListView}). */
	SkillIcons skills;
	/**
	 * The setup tags' game images, each asked for once and shared by the live card's toggles ({@link SetupToggles}) and
	 * the Task history rows.
	 */
	SetupImages setup;
}

package com.shmayvan.slayerledger;

import javax.swing.*;

/**
 * Where the small skill icons before the names of the XP lists ({@link ItemListView}) come from. The plugin backs
 * it with RuneLite's {@code SkillIconManager} ({@link SlayerLedgerPlugin#applySkillIcon}); tests pass a fake. Called
 * on the EDT.
 */
@FunctionalInterface
interface SkillIcons
{
	/**
	 * Puts the small icon of {@code skill} (the name of RuneLite's {@code Skill} constant, as {@link SkillXp} keys
	 * skills) on {@code label}; leaves the label without an icon for a key that is no skill.
	 */
	void apply(JLabel label, String skill);
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * XP gained per skill during a task. Skills are keyed by the name of RuneLite's {@code Skill} constant (for
 * example {@code "SLAYER"}), so this class has no RuneLite types and the saved files stay readable. Pure and
 * stateless; {@link SessionTracker} keeps the readings and the totals.
 *
 * <p>XP is counted as the difference between two readings of every skill's experience. A reading in which any skill
 * went <em>down</em> is never counted ({@link #gains} returns {@code null}): XP never decreases in the game, so the
 * two readings are of different accounts or one of them was not synced yet.</p>
 *
 * <p>Readings iterate {@code Skill.values()}. There is no overall skill to read: in the RuneLite API (checked against
 * 1.13.4) {@code Skill.OVERALL} is a deprecated constant that is {@code null} and not one of the values, so an "all
 * skills" figure is the sum of the per-skill gains.</p>
 */
final class SkillXp
{
	/** Title of the per-skill XP lists (the live one and a saved task's). */
	static final String LIST_TITLE = "XP gained";
	/** Noun of the per-skill XP lists' "+N more" tooltip. */
	static final String LIST_NOUN = "skills";
	/** Key of the Slayer skill: the name of RuneLite's {@code Skill.SLAYER} constant. */
	static final String SLAYER = "SLAYER";

	/** Highest XP first, then by skill name. */
	private static final Comparator<Row> ORDER = Comparator.comparingLong(Row::getXp).reversed()
		.thenComparing(Row::getName);

	private SkillXp()
	{
	}

	/**
	 * XP gained per skill from {@code before} to {@code after}: each skill whose XP went up, by how much. A skill
	 * missing from either reading is left out.
	 *
	 * @return the gains (empty when nothing went up), or {@code null} when either reading is missing or any skill went
	 *         down, so the readings can't be compared
	 */
	static Map<String, Long> gains(Map<String, Integer> before, Map<String, Integer> after)
	{
		if (before == null || after == null)
		{
			return null;
		}
		Map<String, Long> gains = new TreeMap<>();
		for (Map.Entry<String, Integer> e : after.entrySet())
		{
			Integer was = before.get(e.getKey());
			Integer now = e.getValue();
			if (e.getKey() == null || was == null || now == null)
			{
				continue;
			}
			if (now < was)
			{
				return null;
			}
			if (now > was)
			{
				gains.put(e.getKey(), (long) now - was);
			}
		}
		return gains;
	}

	/** Adds {@code gains} (may be {@code null}) into {@code into}, saturating at {@link Long#MAX_VALUE}. */
	static void add(Map<String, Long> into, Map<String, Long> gains)
	{
		if (gains == null)
		{
			return;
		}
		for (Map.Entry<String, Long> e : gains.entrySet())
		{
			if (e.getKey() == null || e.getValue() == null || e.getValue() <= 0)
			{
				continue;
			}
			into.merge(e.getKey(), e.getValue(), SkillXp::saturatedAdd);
		}
	}

	/**
	 * Takes {@code gains} (may be {@code null}) back out of {@code from}: each skill goes down by its gain, never below
	 * zero, and a skill left at zero is removed. Undoes {@link #add} of the same gains.
	 */
	static void subtract(Map<String, Long> from, Map<String, Long> gains)
	{
		if (gains == null)
		{
			return;
		}
		for (Map.Entry<String, Long> e : gains.entrySet())
		{
			final Long had = e.getKey() == null ? null : from.get(e.getKey());
			if (had == null || e.getValue() == null || e.getValue() <= 0)
			{
				continue;
			}
			final long left = had - e.getValue();
			if (left > 0)
			{
				from.put(e.getKey(), left);
			}
			else
			{
				from.remove(e.getKey());
			}
		}
	}

	/** A sorted copy of {@code xp} with only positive entries; empty for {@code null}. */
	static Map<String, Long> sanitize(Map<String, Long> xp)
	{
		Map<String, Long> result = new TreeMap<>();
		add(result, xp);
		return result;
	}

	/** Total XP of every skill; 0 for {@code null}. */
	static long total(Map<String, Long> xp)
	{
		long total = 0;
		if (xp != null)
		{
			for (Long value : xp.values())
			{
				if (value != null && value > 0)
				{
					total = saturatedAdd(total, value);
				}
			}
		}
		return total;
	}

	/**
	 * XP per hour of active time, or {@code null} until there is at least {@link TaskTimeEstimate#MIN_ACTIVE_MILLIS}
	 * of it (a rate from a few seconds means little).
	 */
	static Long perHour(long xp, long activeMillis)
	{
		if (activeMillis < TaskTimeEstimate.MIN_ACTIVE_MILLIS || xp < 0)
		{
			return null;
		}
		return Math.round(xp * 3_600_000d / activeMillis);
	}

	/** Display name of a skill key: {@code "HITPOINTS"} is "Hitpoints". */
	static String skillName(String key)
	{
		if (key == null || key.isEmpty())
		{
			return "Unknown skill";
		}
		return key.substring(0, 1).toUpperCase(Locale.ROOT) + key.substring(1).toLowerCase(Locale.ROOT).replace('_', ' ');
	}

	/**
	 * The total line: {@code XP: 12,345 (40,100/h)}, without the rate until {@link #perHour} gives one, or
	 * {@code XP: -} when the XP was not recorded ({@code null}, a task saved before XP was tracked).
	 */
	static String totalText(Map<String, Long> xp, long activeMillis)
	{
		if (xp == null)
		{
			return "XP: " + LedgerHistory.NO_VALUE;
		}
		long total = total(xp);
		String rate = rateText(total, activeMillis);
		return "XP: " + LedgerHistory.formatAmount(total, false) + (rate == null ? "" : " (" + rate + ")");
	}

	/** {@code 40,100/h}, or {@code null} until {@link #perHour} gives a rate. */
	static String rateText(long xp, long activeMillis)
	{
		Long rate = perHour(xp, activeMillis);
		return rate == null ? null : LedgerHistory.formatAmount(rate, false) + "/h";
	}

	/**
	 * Tooltip of a total line: the exact total and rate, then every skill; a plain note when the XP was not recorded.
	 */
	static String tooltip(Map<String, Long> xp, long activeMillis)
	{
		if (xp == null)
		{
			return "Not recorded: this task was saved before XP was tracked.";
		}
		long total = total(xp);
		StringBuilder sb = new StringBuilder("<html>XP gained: ").append(String.format("%,d", total));
		Long rate = perHour(total, activeMillis);
		if (rate != null)
		{
			sb.append("<br>XP per hour: ").append(String.format("%,d", rate));
		}
		for (Row row : rows(xp, activeMillis))
		{
			sb.append("<br>").append(row.getName()).append(": ").append(String.format("%,d", row.getXp()));
		}
		return sb.append("<br>Counted only while the session runs.</html>").toString();
	}

	/** One line per skill with XP, highest first; empty for {@code null}. */
	static List<Row> rows(Map<String, Long> xp, long activeMillis)
	{
		if (xp == null)
		{
			return Collections.emptyList();
		}
		List<Row> rows = new ArrayList<>();
		for (Map.Entry<String, Long> e : sanitize(xp).entrySet())
		{
			rows.add(new Row(e.getKey(), skillName(e.getKey()), e.getValue(), perHour(e.getValue(), activeMillis)));
		}
		rows.sort(ORDER);
		return rows;
	}

	private static long saturatedAdd(long a, long b)
	{
		long sum = a + b;
		return ((a ^ sum) & (b ^ sum)) < 0 ? Long.MAX_VALUE : sum;
	}

	/** One skill's line of a per-skill XP list, with the skill's small icon before its name. */
	@Value
	static class Row implements ItemListView.Line
	{
		/** Skill key ({@code "SLAYER"}), for the icon. */
		String skill;
		/** Skill name to show. */
		String name;
		long xp;
		/** XP per hour of active time, or {@code null} while too little time has passed. */
		Long perHour;

		@Override
		public String amountText()
		{
			return LedgerHistory.formatAmount(xp, false);
		}

		@Override
		public String tooltip()
		{
			return "<html>" + name + ": " + String.format("%,d", xp) + " XP"
				+ (perHour == null ? "" : "<br>" + String.format("%,d", perHour) + " XP per hour") + "</html>";
		}
	}
}

package com.shmayvan.slayerledger;

/**
 * Notices a long stretch of game ticks on which a running session's supplies were not counted, so the plugin can leave
 * a log line saying why (on 2026-11-08 supply counting stopped silently for hours). Pure; the plugin calls it
 * once per tick on the client thread. Not thread-safe.
 *
 * <p>The first line is due after {@link #FIRST_REPORT_TICKS} skipped ticks in a row, then one every
 * {@link #REPEAT_REPORT_TICKS} more while the stretch lasts: a bank visit of a minute or more leaves one line, an
 * exclusion that never ends one line every ten minutes.</p>
 */
final class SkippedSupplyTicks
{
	/** Skipped ticks in a row (one minute) before the first report. */
	static final int FIRST_REPORT_TICKS = 100;
	/** Further skipped ticks (ten minutes) between reports while the stretch lasts. */
	static final int REPEAT_REPORT_TICKS = 1_000;

	/** Ticks skipped in a row so far. */
	private int length;

	/**
	 * A running session's tick whose supplies were not counted.
	 *
	 * @return whether the stretch is due to be reported now ({@link #length()} long)
	 */
	boolean skipped()
	{
		if (length < Integer.MAX_VALUE)
		{
			length++;
		}
		return length == FIRST_REPORT_TICKS
			|| (length > FIRST_REPORT_TICKS && (length - FIRST_REPORT_TICKS) % REPEAT_REPORT_TICKS == 0);
	}

	/** Ticks skipped in a row so far. */
	int length()
	{
		return length;
	}

	/** Supplies were counted on this tick, or no session is running: the stretch ends. */
	void reset()
	{
		length = 0;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.*;
import java.util.*;
import lombok.*;

/**
 * The bundled boss table (V2 plan 4.4): each Slayer task that has a Slayer boss, the boss, and the NPC names the
 * game gives the boss when it dies, so a task's kills per NPC name ({@link NpcKillTally}) can tell a task done on its
 * boss from one done on the task's own monsters ({@link TaskVariants}). Also the superior Slayer monsters of the tasks
 * with a boss or a Catacombs variant ({@link CatacombsVariants}), which the variant decision leaves out. Pure (no
 * RuneLite types).
 *
 * <p><b>Data and licence.</b> The rows are the bundled {@code slayer-bosses.json} ({@link BundledData}; no rows when it
 * can't be read), adapted from the Old School RuneScape Wiki by Old School RuneScape Wiki contributors, under CC
 * BY-NC-SA 3.0 (the file's {@code attribution}; the README credits it as it credits the other Wiki snapshots). The
 * list of Slayer bosses is the "Slayer bosses" section of the Wiki's Boss article (the file's {@code listSource}): the
 * bosses that each "requires a task for either the boss itself or the equivalent monster", that is the Slayer bosses
 * fought on a regular task. The "Bosses" section of the Slayer article and its main article, Boss Slayer (the boss task
 * list), were checked against it (the file's {@code checkedAgainst}). Each row cites the boss's own article, which
 * names the task (Araxxor's names two: araxytes and spiders). The superiors are from the file's
 * {@code superiorsSource}. Bosses that are only assigned as boss tasks (Vorkath, Zulrah, the Maggot King and the rest
 * of Boss Slayer's list) and bosses that count for a task without needing one (for example the King Black Dragon for
 * black dragons) are not on that list, so they are not rows.</p>
 *
 * <p><b>NPC names.</b> Each boss lists the name of every NPC that dies in one of its kills, as the game's NPC
 * definitions give it (the gameval {@code NpcID} javadoc names; the file keeps one id and constant per name to show
 * where it came from, and {@code TaskVariantsTest} checks them). The name is the same in every form: the Abyssal Sire's
 * phases, the Alchemical Hydra's forms and Cerberus' are all named after the boss. The Grotesque Guardians are two
 * NPCs, Dusk and Dawn, killed together. The Kraken lies as a "Whirlpool" until it is disturbed and dies as the
 * "Kraken"; the whirlpool's name is left out, since cave kraken lie as whirlpools too.</p>
 */
final class SlayerBosses
{
	/** One Slayer task's Slayer boss. Immutable. */
	@Getter
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Boss
	{
		/** The Slayer task's name, as the game's task table gives it (for example "Gargoyles"). */
		private final String task;
		/**
		 * The boss's name, as its kill count message gives it (for example "Grotesque Guardians"): the name a task done
		 * on it is shown and grouped under ({@link LedgerRecord#getVariant}).
		 */
		private final String name;
		/** The name of every NPC that dies in one of its kills ("Dusk", "Dawn"), in the file's order. Unmodifiable. */
		private final List<String> npcNames;
	}

	private static final List<Boss> BOSSES = BundledData.load("slayer-bosses.json",
		root -> BundledData.rows(root.getAsJsonArray("bosses"), row -> new Boss(row.get("task").getAsString(),
			row.get("name").getAsString(), names(row.getAsJsonArray("npcs")))), Collections.emptyList());

	/**
	 * The names of the superior Slayer monsters of the tasks with a Slayer boss or a Catacombs variant; hellhounds, cave
	 * kraken, spiders and the dragons have none. On any other task the variant is always the standard monster, so its
	 * superiors need no row. A superior only appears on its own task.
	 */
	private static final List<String> SUPERIORS = BundledData.load("slayer-bosses.json",
		root -> names(root.getAsJsonArray("superiors")), Collections.emptyList());

	/** The bosses' NPC names, {@link TaskStatistics#normalize}d (the tally asks for every NPC that dies). */
	private static final Set<String> BOSS_NPC_KEYS = bossNpcKeys();
	/** The superiors' names, {@link TaskStatistics#normalize}d (the overlay's variant asks every frame). */
	private static final Set<String> SUPERIOR_KEYS = keys(SUPERIORS);

	private SlayerBosses()
	{
	}

	/** Every row, in a fixed order. */
	static List<Boss> all()
	{
		return BOSSES;
	}

	/** The task's Slayer boss ({@code taskName} matched by {@link TaskStatistics#normalize}), or {@code null}. */
	static Boss forTask(String taskName)
	{
		final String key = TaskStatistics.normalize(taskName);
		if (key == null)
		{
			return null;
		}
		for (Boss boss : BOSSES)
		{
			if (key.equals(TaskStatistics.normalize(boss.task)))
			{
				return boss;
			}
		}
		return null;
	}

	/** Whether {@code npcName} (matched by {@link TaskStatistics#normalize}) is one of a listed boss's NPCs. */
	static boolean isBossNpcName(String npcName)
	{
		final String key = TaskStatistics.normalize(npcName);
		return key != null && BOSS_NPC_KEYS.contains(key);
	}

	/** Whether {@code npcName} (matched by {@link TaskStatistics#normalize}) is a listed superior's name. */
	static boolean isSuperiorName(String npcName)
	{
		final String key = TaskStatistics.normalize(npcName);
		return key != null && SUPERIOR_KEYS.contains(key);
	}

	private static Set<String> bossNpcKeys()
	{
		final Set<String> keys = new HashSet<>();
		for (Boss boss : BOSSES)
		{
			keys.addAll(keys(boss.npcNames));
		}
		return Collections.unmodifiableSet(keys);
	}

	private static Set<String> keys(List<String> names)
	{
		final Set<String> keys = new HashSet<>();
		for (String name : names)
		{
			keys.add(TaskStatistics.normalize(name));
		}
		return Collections.unmodifiableSet(keys);
	}

	/** The {@code name}s of the NPC objects of {@code npcs}, in order. Unmodifiable. */
	private static List<String> names(JsonArray npcs)
	{
		return BundledData.rows(npcs, npc -> npc.get("name").getAsString());
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.regex.*;
import net.runelite.api.gameval.*;

/**
 * Charges used by the bracelet of slaughter and the expeditious bracelet. Each time a worn bracelet's effect
 * activates, the game uses one of its {@value #CHARGES_PER_BRACELET} charges (OSRS Wiki, "Bracelet of slaughter" and
 * "Expeditious bracelet") and prints a game message saying so, which core ItemChargePlugin also counts them by
 * (RuneLite 1.13.4). The bracelet's item id doesn't change with its charges and the charges aren't in a container, so
 * the supplies diff can't see them; one message is one charge, recorded under the bracelet with
 * {@value #CHARGES_PER_BRACELET} charges per item and valued like a teleport jewellery charge. The last charge counts
 * too, whether the bracelet then crumbles or regenerates (a Combat Achievements reward); breaking a bracelet early is
 * not counted. Pure; tags and markup are stripped by {@link GameMessageText}.
 */
final class SlayerBracelets
{
	/** No bracelet charge used. */
	static final int NONE = -1;
	/**
	 * The bracelet of slaughter: its activation means a task kill left the Slayer count unchanged, which the session
	 * still counts as activity (V2 plan 4.1, {@link SessionTracker#braceletKill}).
	 */
	static final int SLAUGHTER_BRACELET = ItemID.BRACELET_OF_SLAUGHTER;
	/** Charges in one bracelet of either kind (core ItemChargePlugin's MAX_SLAYER_BRACELET_CHARGES). */
	static final int CHARGES_PER_BRACELET = 30;
	/** The two bracelets, as recorded in the supplies: counted (and shown) in charges. */
	static final Set<Integer> BRACELETS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ItemID.BRACELET_OF_SLAUGHTER, ItemID.EXPEDITIOUS_BRACELET)));

	/** A bracelet of slaughter activating, as core ItemChargePlugin matches it (1.13.4). */
	private static final Pattern SLAUGHTER = Pattern.compile("Your bracelet of slaughter prevents your slayer count "
		+ "from decreasing\\. (?:It has \\d{1,2} charges? left\\.|It then crumbles to dust\\.|It then regenerates itself "
		+ "to full charge!)");
	/** An expeditious bracelet activating, as core ItemChargePlugin matches it (1.13.4). */
	private static final Pattern EXPEDITIOUS = Pattern.compile("Your expeditious bracelet helps you progress your "
		+ "slayer (?:task )?faster\\. (?:It has \\d{1,2} charges? left\\.|It then crumbles to dust\\.|It then "
		+ "regenerates itself to full charge!)");

	private SlayerBracelets()
	{
	}

	/**
	 * The bracelet a game message says used a charge ({@code ItemID.BRACELET_OF_SLAUGHTER} or
	 * {@code ItemID.EXPEDITIOUS_BRACELET}), or {@link #NONE}. The message may carry colour tags. A check message ("Your
	 * bracelet of slaughter has 12 charges left.") is not a use.
	 */
	static int chargeUsed(String message)
	{
		if (message == null)
		{
			return NONE;
		}
		final String plain = GameMessageText.plain(message);
		if (SLAUGHTER.matcher(plain).find())
		{
			return ItemID.BRACELET_OF_SLAUGHTER;
		}
		if (EXPEDITIOUS.matcher(plain).find())
		{
			return ItemID.EXPEDITIOUS_BRACELET;
		}
		return NONE;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import javax.inject.*;
import lombok.extern.slf4j.*;
import net.runelite.api.*;
import net.runelite.api.gameval.*;

/**
 * The plugin's Slayer DB-table lookups: the task name and Konar's area name, read the way core SlayerPlugin
 * reads them. Client thread only. The last successful lookup of each is cached for the plugin instance's lifetime
 * (never cleared, as before the move); failed lookups are not cached, so they are retried on the next tick.
 *
 * <p>Injected by Guice into the plugin, as RuneLite plugins inject their overlays and helpers.
 */
@Slf4j
class SlayerDbLookups
{
	private final Client client;
	private int cachedTaskKey = Integer.MIN_VALUE;
	private String cachedTaskName;
	private int cachedAreaId = Integer.MIN_VALUE;
	private String cachedAreaName;

	@Inject
	SlayerDbLookups(Client client)
	{
		this.client = client;
	}

	/**
	 * Client thread. Name of a Slayer area from the SlayerArea DB table (COL_AREA_NAME_IN_HELPER, as core
	 * SlayerPlugin's task location), or {@code null} when the lookup fails; failures are retried on the next tick.
	 */
	String lookupAreaName(int areaId)
	{
		if (areaId == cachedAreaId && cachedAreaName != null)
		{
			return cachedAreaName;
		}
		String name = null;
		try
		{
			final List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID,
				DBTableID.SlayerArea.COL_AREA_ID, 0, areaId);
			if (!rows.isEmpty())
			{
				name = (String) client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0)[0];
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to look up slayer area {}", areaId, e);
		}
		if (name == null || name.isEmpty())
		{
			return null;
		}
		cachedAreaId = areaId;
		cachedAreaName = name;
		return name;
	}

	/**
	 * Client thread. Resolves the task name the same way core SlayerPlugin does (1.13.3): the SlayerTask DB table
	 * keyed by the SLAYER_TARGET varp, or the SlayerTaskSublist table for boss tasks. Successful lookups are cached;
	 * failed lookups return {@code null} and are retried on the next tick.
	 */
	String lookupTaskName(int taskId, int bossId, int key)
	{
		if (key == cachedTaskKey && cachedTaskName != null)
		{
			return cachedTaskName;
		}

		String name = null;
		try
		{
			Integer taskRow = null;
			if (taskId == SessionTracker.BOSS_TASK_TARGET)
			{
				List<Integer> bossRows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
					DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, bossId);
				if (!bossRows.isEmpty())
				{
					taskRow = (Integer) client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0)[0];
				}
			}
			else
			{
				List<Integer> taskRows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
				if (!taskRows.isEmpty())
				{
					taskRow = taskRows.get(0);
				}
			}
			if (taskRow != null)
			{
				name = (String) client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0)[0];
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to look up slayer task {}", taskId, e);
		}

		if (name == null || name.isEmpty())
		{
			// Not cached, so the lookup is retried next tick. The panel and record show a fallback name.
			return null;
		}
		name = name.substring(0, 1).toUpperCase(Locale.ROOT) + name.substring(1);
		cachedTaskKey = key;
		cachedTaskName = name;
		return name;
	}
}

package com.shmayvan.slayerledger;

import net.runelite.client.config.*;

@ConfigGroup(SlayerLedgerConfig.GROUP)
public interface SlayerLedgerConfig extends Config
{
	String GROUP = "slayerledger";

	// Sections in the order the config panel shows them: the core tracking and value settings first, the
	// niche charged-weapon setting last. Their keys and the items' keys are unchanged, so saved settings are kept.

	@ConfigSection(
		name = "Tracking",
		description = "What a session counts and how incomplete tasks are saved.",
		position = 0
	)
	String trackingSection = "tracking";

	@ConfigSection(
		name = "Values",
		description = "How loot is valued and which drops are listed as notable.",
		position = 1
	)
	String valuesSection = "values";

	@ConfigSection(
		name = "Chat",
		description = "The chat lines and notification the plugin posts.",
		position = 2
	)
	String chatSection = "chat";

	@ConfigSection(
		name = "Task overlay",
		description = "The in-game overlay showing the assigned task's progress, and its four groups of rows.",
		position = 3
	)
	String taskOverlaySection = "taskOverlay";

	@ConfigSection(
		name = "Panel sections",
		description = "Choose which optional sections the Slayer Ledger sidebar shows.",
		position = 4
	)
	String panelSectionsSection = "panelSections";

	@ConfigSection(
		name = "Charged weapons",
		description = "How charged weapons' supplies are estimated.",
		position = 5
	)
	String chargedWeaponsSection = "chargedWeapons";

	@ConfigItem(
		keyName = "confirmIncomplete",
		name = "Confirm before saving incomplete tasks",
		position = 0,
		section = trackingSection,
		description = "When you press End task before the task is complete, ask whether to keep the session (saved as"
			+ " partial) or discard it. When off, incomplete sessions are kept as partial automatically."
	)
	default boolean confirmIncomplete()
	{
		return true;
	}

	String AWAY_MINUTES = "awayMinutes";

	@ConfigItem(
		keyName = AWAY_MINUTES,
		name = "Away after",
		position = 4,
		section = trackingSection,
		description = "After this many minutes without a task kill or a hit on a task monster, the session goes Away:"
			+ " its time stops at your last kill or hit, and your next task kill starts it again."
	)
	@Range(min = SessionTracker.MIN_AWAY_MINUTES, max = SessionTracker.MAX_AWAY_MINUTES)
	@Units(Units.MINUTES)
	default int awayMinutes()
