	/**
	 * Binds the plugin's own helpers here, so Guice keeps them in the plugin's injector. Left to just-in-time
	 * binding they would land in RuneLite's main injector and keep this plugin's classes loaded after a Plugin Hub
	 * update or uninstall.
	 */
	@Override
	public void configure(Binder binder)
	{
		binder.bind(ClientLookups.class);
		binder.bind(SupplyReader.class);
		binder.bind(SlayerDbLookups.class);
	}

	@Provides
	SlayerLedgerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SlayerLedgerConfig.class);
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		Future<?> pending = savePendingPrompt();
		if (pending != null)
		{
			event.waitFor(pending);
		}
		Future<?> completion = flushPendingCompletion();
		if (completion != null)
		{
			event.waitFor(completion);
		}
		Future<?> marker = persistEndedMarker();
		if (marker != null)
		{
			event.waitFor(marker);
		}
		Future<?> save = endSession(SaveDecision.EndReason.SHUTDOWN);
		if (save != null)
		{
			event.waitFor(save);
		}
	}

	/**
	 * Any thread. Re-parses the "Ignored loot" setting when it changes (loot already counted is not changed), reads a
	 * new "Notable drop value" (notable drops already listed are kept), and applies a new "Loot price" setting: the
	 * live values follow on the next game tick and the history is redrawn on the EDT. A change of "Hide Ground Items'
	 * hidden items", of Ground Items' hidden or highlighted list, or Ground Items turned on or off, is applied the same
	 * way. A "Panel sections" setting shows or hides its sidebar section on the EDT.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (isGroundItemsHiddenKey(event.getGroup(), event.getKey()))
		{
			applyGroundItemsHidden();
			return;
		}
		if (!SlayerLedgerConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (SlayerLedgerConfig.HIDE_GROUND_ITEMS_HIDDEN.equals(event.getKey()))
		{
			applyGroundItemsHidden();
		}
		else if (SlayerLedgerConfig.IGNORED_LOOT.equals(event.getKey()))
		{
			ignoredLoot = IgnoredLoot.parse(config.ignoredLoot());
		}
		else if (SlayerLedgerConfig.NOTABLE_DROP_THRESHOLD.equals(event.getKey()))
		{
			notableDropThreshold = NotableDrops.threshold(config.notableDropThreshold());
		}
		else if (SlayerLedgerConfig.LOOT_PRICE_MODE.equals(event.getKey()))
		{
			final LootPriceMode mode = readLootPriceMode();
			lootPriceMode = mode;
			final LedgerHistoryModel m = historyModel;
			if (m != null)
			{
				SwingUtilities.invokeLater(() -> m.setLootPriceMode(mode));
			}
		}
		else if (SlayerLedgerConfig.AWAY_MINUTES.equals(event.getKey()))
		{
			// The tracker is synchronized; the next settled tick checks Away against the new limit.
			final SessionTracker t = tracker;
			if (t != null)
			{
				t.setAwayMinutes(config.awayMinutes());
			}
		}
		else
		{
			final SlayerLedgerPanel.OptionalSection section = optionalSection(event.getKey());
			final SlayerLedgerPanel p = panel;
			if (section != null && p != null)
			{
				final boolean shown = isSectionShown(section);
				SwingUtilities.invokeLater(() -> p.setSectionShown(section, shown));
			}
		}
	}

	/** The optional sidebar section a "Panel sections" setting's key shows, or {@code null} for any other key. */
	private static SlayerLedgerPanel.OptionalSection optionalSection(String key)
	{
		if (key == null)
		{
			return null;
		}
		switch (key)
		{
			case SlayerLedgerConfig.SHOW_OVERALL_TOTALS:
				return SlayerLedgerPanel.OptionalSection.OVERALL_TOTALS;
			case SlayerLedgerConfig.SHOW_SKIPPED_BLOCKED:
				return SlayerLedgerPanel.OptionalSection.SKIPPED_BLOCKED;
			default:
				return null;
		}
	}

	/** Whether the "Panel sections" settings show {@code section} in the sidebar. */
	private boolean isSectionShown(SlayerLedgerPanel.OptionalSection section)
	{
		switch (section)
		{
			case OVERALL_TOTALS:
				return config.showOverallTotals();
			default:
				return config.showSkippedBlocked();
		}
	}

	/**
	 * The "Loot price" setting, GE when unset. A saved value that is no longer a {@link LootPriceMode} (the removed
	 * "Higher of the two") also reads as GE: RuneLite's config proxy returns the item's default when it cannot parse
	 * the value.
	 */
	private LootPriceMode readLootPriceMode()
	{
		final LootPriceMode mode = config.lootPriceMode();
		return mode == null ? LootPriceMode.GE : mode;
	}

	/** Whether a config change of {@code group} and {@code key} can change what {@link #groundItemsHidden} hides. */
	private static boolean isGroundItemsHiddenKey(String group, String key)
	{
		if (GroundItemsHidden.GROUP.equals(group))
		{
			return GroundItemsHidden.HIDDEN_ITEMS_KEY.equals(key) || GroundItemsHidden.HIGHLIGHTED_ITEMS_KEY.equals(key);
		}
		return GroundItemsHidden.PLUGIN_ENABLED_GROUP.equals(group) && GroundItemsHidden.PLUGIN_ENABLED_KEY.equals(key);
	}

	/**
	 * Any thread. What Ground Items' lists hide from the loot now, read from the config (Ground Items' own
	 * settings are only read, never written; ConfigManager reads are safe on any thread).
	 */
	private GroundItemsHidden readGroundItemsHidden()
	{
		return GroundItemsHidden.effective(config.hideGroundItemsHidden(),
			configManager.getConfiguration(GroundItemsHidden.PLUGIN_ENABLED_GROUP, GroundItemsHidden.PLUGIN_ENABLED_KEY),
			configManager.getConfiguration(GroundItemsHidden.GROUP, GroundItemsHidden.HIDDEN_ITEMS_KEY),
			configManager.getConfiguration(GroundItemsHidden.GROUP, GroundItemsHidden.HIGHLIGHTED_ITEMS_KEY));
	}

	/**
	 * Any thread. Reads {@link #groundItemsHidden} again; when it changed, the live values follow on the next game tick
	 * and the history model works out the hidden loot again on the EDT. Synchronized so that concurrent
	 * {@code ConfigChanged} events read, store and hand over their lists one at a time, in order: the last list read
	 * is the one kept and the last one the model gets.
	 */
	private synchronized void applyGroundItemsHidden()
	{
		final GroundItemsHidden list = readGroundItemsHidden();
		if (list.equals(groundItemsHidden))
		{
			return;
		}
		groundItemsHidden = list;
		final LedgerHistoryModel m = historyModel;
		if (m != null)
		{
			SwingUtilities.invokeLater(() -> m.setGroundItemsHidden(list));
		}
	}

	/**
	 * Client thread. Which of {@code itemIds} {@link #groundItemsHidden} hides, from their item compositions' names (a
	 * note's is its unnoted item's, as Ground Items matches it).
	 */
	private HiddenLoot hiddenLoot(Collection<Integer> itemIds)
	{
		hiddenLoot.setList(groundItemsHidden);
		return hiddenLoot.resolve(itemIds, lookups.lootItemNames()::name);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (!clientStateReady)
		{
			return;
		}
		switch (event.getGameState())
		{
			case LOGIN_SCREEN:
				// A completed session held for late loot is saved now; it is never persisted as the active session.
				flushPendingCompletion();
				// A logout stops the session: its segment closes now, and the next kill after a login restarts it.
				tracker.loggedOut();
				waitingLineDue = true;
				cancelPendingRestore();
				// Keep the session in memory (the next kill after a re-login restarts it) but persist it in case the
				// client is closed; or an Ended assignment's marker.
				persistOnLogout();
				restoreCheckNeeded = true;
				// The next login may be a different account; never show or adopt the old task.
				tracker.clearCurrentTask();
				// The history is cleared below, so the next login's first settled tick must tell the model the task
				// again, even when nothing changed (the same account, task and place): it asks for the advisor's plan.
				lastLiveInputs = null;
				streakCounter = StreakMilestone.NO_COUNTER;
				loggedIn = false;
				resetClientState();
				blowpipeDartId = ChargedWeaponUsage.NO_ITEM;
				// The next login may be a different account, with another blowpipe and assignment.
				blowpipeContents.forget();
				overlaySnapshot = null;
				// Nothing on the overlay after the next login until its first settled tick has read that account's task.
				overlaySettled = false;
				// Hide the history while logged out; it is reloaded on the next login (any account).
				setHistoryAccount(SessionTracker.NO_ACCOUNT);
				break;
			case CONNECTION_LOST:
				// A lost connection stops the session like a logout (V2 plan 4.1); it is persisted if the login
				// screen follows.
				tracker.loggedOut();
				waitingLineDue = true;
				// fall through
			case HOPPING:
				// A hop is not a stop: time keeps running.
			case LOGGING_IN:
				// No game ticks count the grace window down while not logged in; save a held completion now.
				flushPendingCompletion();
				loggedIn = false;
				resetClientState();
				break;
			case LOGGED_IN:
				loggedIn = true;
				checkAccount();
				loadBlowpipeDartId();
				break;
			default:
				break;
		}
	}

	/**
	 * Client thread, on the first settled tick after a login (or the plugin's start), once any restore check has run.
	 * Posts one chat line ({@link #WAITING_LINE}) when a session of this account waits for the next kill: kept across
	 * the logout, or restored from the last run. Nothing is posted when there is none, when it already restarted, or
	 * when it belongs to another account.
	 */
	private void announceWaiting()
	{
		waitingLineDue = false;
		if (tracker.getStatus() == SessionTracker.Status.WAITING_FOR_NEXT_KILL
			&& tracker.getSessionAccountHash() == client.getAccountHash())
		{
			postChatLine(WAITING_LINE);
		}
	}

	/**
	 * Any thread (ConfigManager posts it from wherever the profile changed). Another RuneScape profile is active, for
	 * example a different account or world type: its blowpipe dart type is read.
	 */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		loadBlowpipeDartId();
		// Logging out leaves no profile; the names are kept until another profile is active.
		if (event.getNewProfile() != null)
		{
			clientThread.invoke(this::forgetLocationNames);
		}
	}

	/**
	 * Client thread. Another account or RuneScape profile is active: its region names are read afresh, and the history
	 * model forgets the names it has.
	 */
	private void forgetLocationNames()
	{
		lookups.forgetLocationNames();
		final LedgerHistoryModel m = historyModel;
		if (m != null)
		{
			SwingUtilities.invokeLater(m::clearLocationNames);
		}
	}

	/**
	 * EDT. Renames map region {@code region}, a region the spot table doesn't list (its spot is {@code region:N}),
	 * for every task there (the history's "Rename place"): the name is kept in the RSProfile config, as 1.x
	 * kept the names its prompt asked for, so it names the running session, every later task there and the saved tasks
	 * there without a name of their own. Saved files are not rewritten.
	 *
	 * @return whether the name was taken; {@code false} when nothing is left after {@link TaskLocation#normalizeName}
	 */
	boolean saveLocationName(int region, String name)
	{
		final String normalized = TaskLocation.normalizeName(name);
		if (normalized == null || !LocationTally.isRegion(region))
		{
			return false;
		}
		clientThread.invoke(() ->
		{
			lookups.saveLocationName(region, normalized);
			final LedgerHistoryModel m = historyModel;
			if (m != null)
			{
				SwingUtilities.invokeLater(() -> m.addLocationNames(Collections.singleton(region),
					Collections.singletonMap(region, normalized)));
			}
		});
		return true;
	}

	/**
	 * Client thread. Where the local player stands ({@link KillPlace#at}): the map region and the Slayer spot of the
	 * player's tile ({@link WorldPoint#fromLocalInstance}, so an instance is its template's tile and plane), or
	 * {@link KillPlace#NONE} while there is no player or scene, or while the player is on a Sailing boat (the tile is in
	 * the boat's own world view, whose template is not where the boat is). Never throws, so the task is always observed.
	 */
	private KillPlace readPlace()
	{
		try
		{
			final Player player = client.getLocalPlayer();
			final LocalPoint local = player == null ? null : player.getLocalLocation();
			final WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
			if (view == null || !view.isTopLevel())
			{
				return KillPlace.NONE;
			}
			final WorldPoint point = WorldPoint.fromLocalInstance(client, local);
			return KillPlace.at(spots, point.getX(), point.getY(), point.getPlane());
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to read the local player's location", e);
			return KillPlace.NONE;
		}
	}

	/** Any thread. Reads the active RuneScape profile's blowpipe dart type from the RSProfile config. */
	private void loadBlowpipeDartId()
	{
		final String saved = configManager.getRSProfileConfiguration(SlayerLedgerConfig.GROUP, BLOWPIPE_DART_KEY);
		int dartId = ChargedWeaponUsage.NO_ITEM;
		if (saved != null)
		{
			try
			{
				dartId = Integer.parseInt(saved.trim());
			}
			catch (NumberFormatException e)
			{
				log.debug("Ignoring a saved blowpipe dart type that is not an item id: {}", saved);
			}
		}
		blowpipeDartId = dartId;
	}

	/**
	 * Client thread. Remembers the blowpipe's dart type for this RuneScape profile (or forgets it, with
	 * {@link ChargedWeaponUsage#NO_ITEM}).
	 */
	private void setBlowpipeDartId(int dartId)
	{
		if (dartId == blowpipeDartId)
		{
			return;
		}
		blowpipeDartId = dartId;
		if (dartId == ChargedWeaponUsage.NO_ITEM)
		{
			configManager.unsetRSProfileConfiguration(SlayerLedgerConfig.GROUP, BLOWPIPE_DART_KEY);
		}
		else
		{
			configManager.setRSProfileConfiguration(SlayerLedgerConfig.GROUP, BLOWPIPE_DART_KEY, dartId);
		}
	}

	/**
	 * Counts down the grace window of a completed session held for late loot, and saves it when the window ends. A
	 * separate subscriber because the event bus requires handlers to be named after their event and a class can have
	 * only one {@code onGameTick(GameTick)}. Registered at a lower priority than the default-priority tick handlers, so
	 * LootManager has already posted this tick's ServerNpcLoot; the completion tick itself is not counted. Loot from the
	 * completion tick through {@link SessionTracker#COMPLETION_LOOT_GRACE_TICKS} ticks later is therefore included.
	 */
	private final class CompletionGraceTicker
	{
		/** Client thread. */
		@Subscribe(priority = -1)
		public void onGameTick(GameTick tick)
		{
			if (!clientStateReady || client.getGameState() != GameState.LOGGED_IN || client.getTickCount() == completionHeldTick)
			{
				return;
			}
			handleEndedSession(tracker.tickCompletion(), SaveDecision.EndReason.SYSTEM);
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (!clientStateReady)
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		checkAccount();
		lookups.retryCurrentPrices();
		// Read before this tick's supplies and XP, so a kill seen on this tick that restarts the session counts them
		// (KillPairing.withTickStart): its own XP is read just before the kill is seen. This tick's attack is timed by it
		// too, so a fight backdated to the attack counts its XP.
		final long tickStart = tracker.now();
		// Before observing the task, so supplies used on the tick the task completes still count.
		trackSupplies();
		// The menu clicks and messages that open a charging window arrive before this tick's GameTick, so trackSupplies
		// has already left the charged materials out of this tick's diff. Weapon use comes from the attack itself, not
		// the diff, so it is counted next and valued with the rest of this tick's supplies. This tick's attack and
		// cannon shot are noted with it.
		trackChargedWeapons(tickStart);
		trackCannon();
		updateSessionValues();

		if (settleTicks > 0)
		{
			settleTicks--;
			applyHits();
			return;
		}

		// Before observing the task, so XP gained on the tick the task completes still counts, and XP of a kill that
		// restarts the session is buffered for it; a completion held for late loot is no longer running, so it gets no XP
		// after its completion tick.
		observeSkillXp();
		// After this tick's supplies, XP and attack, before the deaths are paired.
		applyHits();

		final int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		final int[] counters = {
			client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED),
			client.getVarbitValue(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED),
			client.getVarpValue(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED)
		};
		lastCompletionCounters = counters;
		final boolean completionSignaled = completionSignal.update(counters);
		final int points = client.getVarbitValue(VarbitID.SLAYER_POINTS);
		taskRewards.update(points);
		// A completed session held for late loot takes points that arrive after its completion tick.
		if (taskRewards.isFollowing() && !tracker.setCompletionRewards(taskRewards.getSessionId(), taskRewards.earned(),
			taskRewards.streak()))
		{
			// Saved (or no longer held): nothing left to update.
			taskRewards.stopFollowing();
		}

		String name = null;
		int creatureId = SessionTracker.NO_CREATURE;
		int originalAmount = SessionTracker.UNKNOWN_AMOUNT;
		TaskContext assignment = TaskContext.NONE;
		if (remaining > 0)
		{
			final int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
			final int bossId = taskId == SessionTracker.BOSS_TASK_TARGET
				? client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID) : 0;
			creatureId = SessionTracker.creatureKey(taskId, bossId);
			name = dbLookups.lookupTaskName(taskId, bossId, creatureId);
			originalAmount = readOriginalAmount();
			assignment = readAssignment();
		}

		// Decided before observing, so no kill starts a new session from the first settled observation until the
		// restore ran (a new session would block the restore).
		if (restoreCheckNeeded)
		{
			restoreCheckNeeded = false;
			pendingFileRestore = accountHash != SessionTracker.NO_ACCOUNT
				&& tracker.getState() == SessionTracker.State.IDLE;
			// A session kept in memory across logout must pass the same checks as one restored from disk.
			pendingReloginSnapshot = pendingFileRestore ? null : logoutSnapshot;
			logoutSnapshot = null;
			restoreWaitTicks = 0;
			if (pendingFileRestore || pendingReloginSnapshot != null)
			{
				restorePending = true;
			}
		}

		// Read with the task, so the kills this observation counts are tallied where the player is.
		final KillPlace place = readPlace();
		final int tickCount = client.getTickCount();
		// The previous tick's kill is paired again with the deaths of that tick too (T - 2 to T + 1), and its kills'
		// setup contexts are counted with their styles.
		pairPreviousKill(tickCount);
		countKillContexts(tickCount);
		// This tick's kill, if the count dropped, is paired with the deaths from 2 ticks ago (V2 plan 4.1); they
		// backdate a (re)start and name the known task NPCs. A (re)start also counts this tick's supplies and XP.
		KillPairing pairing = damagedNpcs.pairing(tickCount - PAIR_TICKS_BEFORE, tickCount).withTickStart(tickStart);
		final boolean restoreChecking = restorePending || pendingFileRestore || pendingReloginSnapshot != null;
		if (restoreChecking)
		{
			// A new session would block the restore of the last one; an existing session still restarts.
			pairing = pairing.withStartBlocked();
		}
		final long killAtBefore = tracker.getLastKillAt();
		final SessionTracker.State stateBefore = tracker.getState();
		// No session has kills while IDLE, so this also covers a kill that starts one.
		final int killsBefore = tracker.getKills();
		final SessionTracker.ObserveResult result = tracker.observe(name, creatureId, remaining, originalAmount,
			assignment, place, completionSignaled, pairing);
		if (slaughterKillPending)
		{
			// A bracelet of slaughter kept the count: still a task kill, so activity (or a restart), with no kill counted.
			slaughterKillPending = false;
			tracker.braceletKill(pairing);
		}
		// Before a completion is held (which resets the tracker's kills), the kills this tick counted.
		final int killsCounted = Math.max(0, tracker.getKills() - killsBefore);
		// A drop to zero is the final kill only once a completion confirms it, possibly on a later tick.
		if (remaining > 0)
		{
			zeroDropTick = NO_TICK;
		}
		else if (lastRemainingRead > 0)
		{
			zeroDropTick = tickCount;
		}
		lastRemainingRead = remaining;
		noteKillTick(tickCount, killAtBefore, stateBefore);
		noteKillContexts(tickCount, killsCounted);
		switch (result)
		{
			case COMPLETED:
				log.debug("Slayer task completed");
				// The completion was signalled on this tick, so the incremented counter is this completion's streak.
				taskRewards.startCompletion(tracker.getSessionId(), counters, completionSignal.incrementedCounter());
				tracker.setCompletionRewards(taskRewards.getSessionId(), taskRewards.earned(), taskRewards.streak());
				// A running session waits COMPLETION_LOOT_GRACE_TICKS ticks for the final kill's loot before it is
				// saved (see CompletionGraceTicker). The final kill restarted a stopped session first, so it is running;
				// one that completed without a kill being seen is saved now.
				if (tracker.holdCompletion())
				{
					completionHeldTick = client.getTickCount();
				}
				else
				{
					taskRewards.stopFollowing();
					endSession(SaveDecision.EndReason.SYSTEM);
				}
				break;
			case TASK_CHANGED:
				log.debug("Slayer task changed during a session");
				// The tracker already holds the new task as "current", ready for the next session.
				endSession(SaveDecision.EndReason.SYSTEM);
				break;
			default:
				break;
		}
		// After the session's decision, so the master the tracker filled in for this task is used.
		updateTaskStreak(remaining, counters);
		// After the session's decision, so a session that took this task on this tick marks it as played.
		watchAssignments(AssignmentWatch.Reading.builder()
			.monster(name)
			.creatureId(creatureId)
			.remaining(remaining)
			.originalAmount(originalAmount)
			.context(assignment)
			.points(points)
			.counters(counters)
			.blockedValues(readBlockedTaskValues())
			.completionSignaled(completionSignaled)
			.build());
		// Jad and Zuk tasks (V2 plan 4.1): inside the Fight Caves or the Inferno with that task assigned is Running. While
		// a drop to zero waits for its completion the task has no name, so the session's is used.
		final String caveTask = name != null ? name : tracker.getSessionMonster();
		tracker.setInTaskCave(TaskCaves.isInside(caveTask, place.getRegion()), !restoreChecking);
		// After this tick's kills, which are activity, and the cave, inside which Away never starts.
		tracker.checkAway();

		if (pendingFileRestore || pendingReloginSnapshot != null)
		{
			runPendingRestoreCheck(remaining, counters);
		}
		// After the restore check (a file restore is applied when its load comes back) and this tick's task decision,
		// so a session that one of them restored is told about and one they ended or restarted gets no line.
		if (waitingLineDue && !restorePending && !pendingFileRestore && pendingReloginSnapshot == null)
		{
			announceWaiting();
		}
		// Last, so a session this tick started, restored or ended is seen.
		refreshHistoryModelIfLiveChanged();
		publishOverlaySnapshot(tickCount);
	}

	/**
	 * Client thread, at the end of each settled tick. Works out the overlay's snapshot ({@link OverlayFeed}): the
	 * identity, superiors, XP, the supply runway and the superior moment, so the overlay computes nothing while it draws
	 *. The runway reads the supplies the diff saw this tick ({@link SupplyTracker#carried}; none seen without its
	 * baseline) with what a worn blowpipe holds, the session's use, and the history's use per kill published with its
	 * time per kill. Nothing while the overlay is off, and the feed forgets what it kept between ticks, so turning the
	 * overlay back on shows no moment for a superior that came while it was off. Either way the overlay may show again
	 * ({@link #overlaySettled}): this tick has read the logged-in account's task.
	 */
	private void publishOverlaySnapshot(int tick)
	{
		if (!config.showTaskOverlay() || supplyTracker == null)
		{
			overlaySnapshot = null;
			overlayFeed.reset();
			overlaySettled = true;
			return;
		}
		final SupplyRunway.Carrying carried = SupplyRunway.carrying(SupplyRunway.carried(supplyTracker.carried()),
			supplyTracker.hasBaseline(), blowpipeWorn, blowpipeContents, looseScales);
		overlaySnapshot = overlayFeed.update(tracker, spots, lookups::locationName, carried, supplyTracker::supplyKey,
			historicalPace, tick);
		overlaySettled = true;
	}

	/**
	 * Client thread, each settled tick before the task is observed. A task kill seen on an earlier tick is paired again
	 * with the deaths from 2 ticks before it to 1 tick after ({@link SessionTracker#pairKill}): an NPC can die on the
	 * tick after the count dropped, and it may still backdate the restart the kill caused. When that kill completed the
	 * task, its session is held for late loot and no longer runs, so a death paired with it on the tick after was
	 * refused as it died: it is tallied into the held session now ({@link SessionTracker#addHeldNpcKill}).
	 */
	private void pairPreviousKill(int tick)
	{
		if (pairKillAt == SessionTracker.NO_TIME || tick <= pairTick)
		{
			return;
		}
		final long killAt = pairKillAt;
		pairKillAt = SessionTracker.NO_TIME;
		tracker.pairKill(killAt, damagedNpcs.pairing(pairFromTick, pairTick + 1));
		damagedNpcs.tallyUntallied(pairFromTick, pairTick + 1, name -> tracker.addHeldNpcKill(killAt, name));
	}

	/**
	 * Client thread, after this tick's task decision. Remembers this tick's task kill, if there was one, for
	 * {@link #pairPreviousKill} on the next tick: its deaths are paired from 2 ticks before it, or before the drop to
	 * zero a completion on this tick confirms ({@link #zeroDropTick}). When the kill started or restarted the
	 * session:
	 * <ul>
	 * <li>tallies the deaths paired with it so far (from that tick to this one), which died before the session ran and
	 * so were refused then ({@link DamagedNpcs#tallyUntallied}; a death on T + 1 is tallied as it dies, and none
	 * twice);</li>
	 * <li>counts the superior spawns held since the tick before ({@link #heldSuperiorSpawns}).</li>
	 * </ul>
	 * Held superior spawns are dropped after the tick after their message. The supplies diff runs while the task is
	 * assigned, so a (re)start needs no new baseline: the tracker counts its warm-up from the buffer.
	 */
	private void noteKillTick(int tick, long killAtBefore, SessionTracker.State stateBefore)
	{
		final long killAt = tracker.getLastKillAt();
		final int from = (zeroDropTick != NO_TICK ? Math.min(tick, zeroDropTick) : tick) - PAIR_TICKS_BEFORE;
		if (killAt != killAtBefore)
		{
			pairKillAt = killAt;
			pairTick = tick;
			pairFromTick = from;
		}
		if (stateBefore != SessionTracker.State.RUNNING && tracker.getState() == SessionTracker.State.RUNNING)
		{
			damagedNpcs.tallyUntallied(from, tick, tracker::addNpcKill);
			while (heldSuperiorSpawns > 0)
			{
				tracker.addSuperiorSpawn();
				heldSuperiorSpawns--;
			}
		}
		if (heldSuperiorTick < tick)
		{
			// Held since an earlier tick, so this tick was its last chance: no kill of the session spawned it.
			heldSuperiorSpawns = 0;
		}
	}

	/**
	 * The task kills one settled tick counted, waiting for the next one, when the deaths paired with them are all
	 * known, to be counted as setup contexts ({@link SlayerLedgerPlugin#countKillContexts}). What is read on the kill's
	 * own tick (the cannon and the worn gear) is kept with them.
	 */
	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class KillContextsDue
	{
		/** The kills' clock time ({@link SessionTracker#getLastKillAt()} just after them). */
		final long killAt;
		/** The tick they were counted on. */
		final int tick;
		/** The first tick their deaths are paired from (as {@link SlayerLedgerPlugin#pairFromTick}). */
		final int fromTick;
		final int kills;
		final boolean cannon;
		final Integer prayerBonus;
	}

	/**
	 * Client thread, after this tick's task decision. When the tick counted task kills, keeps them for
	 * {@link #countKillContexts} on the next settled tick, with what only this tick can tell: whether the cannon
	 * fired in the last {@link CannonFire#FIRE_WINDOW_TICKS} ticks, and the worn prayer bonus ({@link #readPrayerBonus}).
	 * Their deaths are paired from 2 ticks before the kill, or before the drop to zero a completion on this tick
	 * confirms, as {@link #noteKillTick} pairs them.
	 */
	private void noteKillContexts(int tick, int kills)
	{
		if (kills <= 0)
		{
			return;
		}
		final int from = (zeroDropTick != NO_TICK ? Math.min(tick, zeroDropTick) : tick) - PAIR_TICKS_BEFORE;
		killContextsDue = new KillContextsDue(tracker.getLastKillAt(), tick, from, kills, cannonFire.firedWithin(tick),
			readPrayerBonus());
	}

	/**
	 * Client thread, each settled tick before the task is observed. Counts the setup contexts of the kills the previous
	 * settled tick counted ({@link SessionTracker#addKillContext}): each with the cannon and gear focus of its
	 * tick, and the style of one of the deaths paired with them, from 2 ticks before to 1 tick after
	 * ({@link DamagedNpcs#takeStyles}); kills with no such death (a cannon's, say) have no style. A completion held for
	 * late loot takes its final kill's contexts too.
	 */
	private void countKillContexts(int tick)
	{
		final KillContextsDue due = killContextsDue;
		if (due == null || tick <= due.tick)
		{
			return;
		}
		killContextsDue = null;
		final List<SetupStyle> styles = damagedNpcs.takeStyles(due.fromTick, due.tick + 1, due.kills);
		final GearFocus gear = due.prayerBonus == null ? null : SetupDetection.gearFocus(due.prayerBonus);
		for (int i = 0; i < due.kills; i++)
		{
			tracker.addKillContext(due.killAt, due.cannon, i < styles.size() ? styles.get(i) : null, gear,
				due.prayerBonus);
		}
	}

	/**
	 * Client thread. The total prayer bonus of the worn items, from their equipment stats
	 * ({@code ItemManager.getItemStats}, RuneLite's copy of the OSRS Wiki's bonuses), for a kill's gear focus;
	 * {@code null} when nothing worn has stats (none worn, or the stats not loaded yet). A worn item without stats adds
	 * nothing.
	 */
	private Integer readPrayerBonus()
	{
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return null;
		}
		int total = 0;
		boolean known = false;
		for (Item item : worn.getItems())
		{
			if (item == null || item.getId() < 0)
			{
				continue;
			}
			final ItemStats stats = itemManager.getItemStats(item.getId());
			if (stats != null && stats.getEquipment() != null)
			{
				total += stats.getEquipment().getPrayer();
				known = true;
			}
		}
		return known ? total : null;
	}

	/**
	 * Client thread, each tick after its supplies and XP are read: puts this tick's hits (and any left from the
	 * settling ticks) down to the player's attacks ({@link DamagedNpcs#applyHits}), and makes the hits on the
	 * session's known task NPCs activity for Away ({@link SessionTracker#taskNpcHit}) now, so this tick's supplies and
	 * XP are not after the last activity.
	 */
	private void applyHits()
	{
		damagedNpcs.applyHits(playerAttacks);
		for (String name : hitNpcNames)
		{
			tracker.taskNpcHit(name);
		}
		hitNpcNames.clear();
	}

	/**
	 * Client thread, every settled tick and after a loaded active session is applied ({@link #applyActiveSession},
	 * which runs between ticks). When the task, its master, its kills left, its location or the session changed
	 * ({@link LedgerHistoryModel#liveInputs}), asks the history model on the EDT to ask for the advisor's plan and
	 * publish the overlay's historical time per kill; otherwise, while the model waits for today's prices, asks it to
	 * end that wait once it has run out. So neither waits for the panel's refresh timer, and a new kills left asks for
	 * a new plan at most once a tick.
	 */
	private void refreshHistoryModelIfLiveChanged()
	{
		final List<Object> inputs = LedgerHistoryModel.liveInputs(tracker);
		final LedgerHistoryModel m = historyModel;
		if (!inputs.equals(lastLiveInputs))
		{
			lastLiveInputs = inputs;
			if (m != null)
			{
				SwingUtilities.invokeLater(m::refreshLive);
			}
		}
		else if (m != null && m.isWaitingForCurrentPrices())
		{
			SwingUtilities.invokeLater(m::endExpiredCurrentPricesWait);
		}
	}

	/** Test seam: the history model, or {@code null} while the plugin is stopped. Use it on the EDT. */
	LedgerHistoryModel historyModel()
	{
		return historyModel;
	}

	/**
	 * Test seam: replaces (or, with {@code null}, unsets) the history model, so a test can lose the answers the client
	 * thread would send it.
	 */
	void setHistoryModel(LedgerHistoryModel model)
	{
		historyModel = model;
	}

	/** Test seam: the session tracker, or {@code null} before the plugin first starts. */
	SessionTracker tracker()
	{
		return tracker;
	}

	/** Test seam: stands {@code valuation} in for the live session valuation. Call on the client thread. */
	void setSessionValuation(SessionValuation valuation)
	{
		sessionValuation = valuation;
	}

	/** EDT, after a panel action changed the session: the history model's live checks run at once. */
	private void refreshHistoryModel()
	{
		final LedgerHistoryModel m = historyModel;
		if (m != null)
		{
			m.refreshLive();
		}
	}

	/**
	 * Client thread, every settled tick, whether or not a session is running (only varps and varbits are read). Saves
	 * each assignment that ended without a session; see {@link AssignmentWatch}.
	 */
	private void watchAssignments(AssignmentWatch.Reading reading)
	{
		final List<AssignmentWatch.Ended> ended = assignmentWatch.update(reading, tracker.takeSessionTaskKeys(),
			System.currentTimeMillis());
		final long account = accountHash;
		if (account == SessionTracker.NO_ACCOUNT)
		{
			return;
		}
		for (AssignmentWatch.Ended e : ended)
		{
			log.debug("Slayer assignment ended without a session: {}", e.getEntry().getOutcome());
			executor.execute(() ->
			{
				try
				{
					publishAssignments(account, store.appendAssignment(account, e.getEntry(), e.isCheckRecords()));
				}
				catch (IOException | RuntimeException ex)
				{
					log.warn("Unable to save a Slayer Ledger assignment entry", ex);
				}
			});
		}
	}

	/**
	 * Client thread, every settled tick. Publishes the streak for the panel's "Next bonus" line: the counter of
	 * the current task's master while there is a task; right after a completion the counter it raised, so the line
	 * shows the new streak until the next task. Unknown (hidden) while the master is unknown or not in the table.
	 */
	private void updateTaskStreak(int remaining, int[] counters)
	{
		if (remaining > 0)
		{
			streakCounter = StreakMilestone.counterFor(tracker.getCurrentContext().getMaster());
		}
		else if (completionSignal.incrementedCounter() != CompletionSignal.NO_COUNTER)
		{
			streakCounter = completionSignal.incrementedCounter();
		}
		currentTaskStreak = streakCounter >= 0 && streakCounter < counters.length ? counters[streakCounter] : null;
	}

	/**
	 * The current task streak for the panel's "Next bonus" line, or {@code null} when unknown (not logged in, no
	 * settled reading yet, no task or completion seen since logging in, or the master is unknown). Any thread.
	 */
	Integer currentTaskStreak()
	{
		return currentTaskStreak;
	}

	/** Client thread. The blocked-task varps then varbits, in a fixed order. */
	private int[] readBlockedTaskValues()
	{
		final int[] values = new int[BLOCKED_TASK_VARPS.length + BLOCKED_TASK_VARBITS.length];
		int i = 0;
		for (int varp : BLOCKED_TASK_VARPS)
		{
			values[i++] = client.getVarpValue(varp);
		}
		for (int varbit : BLOCKED_TASK_VARBITS)
		{
			values[i++] = client.getVarbitValue(varbit);
		}
		return values;
	}

	/**
	 * Client thread. NPC kill loot from the game's own loot tracker, the event core LootTrackerPlugin (1.13.3) uses for
	 * NPC loot. Where it goes, with the name of the NPC it came from, is decided by
	 * {@link SessionTracker#addLoot(ItemTally, List, String)}: the running session (or a just-completed one during its
	 * late-loot grace window), a stopped session when it is a known task NPC's (a paired task kill's late loot), or the
	 * buffer outside segments while a task is assigned. Loot from any NPC counts, not only the task monster. Bones and
	 * demonic ashes a bonecrusher or ash sanctifier destroyed are left out ({@link CrushedLootFilter}), judged by what is
	 * carried at the time of this drop, and so are the player's ignored items ({@link IgnoredLoot}); see
	 * {@link LootFilter}. The kept loot's notable stacks ({@link NotableDrops}) go with it; they are only priced while
	 * loot may be kept ({@link SessionTracker#isRecordingLoot}), so no price lookups run while no task is assigned.
	 * Araxxor's harvest after the task its kill completed was saved goes to that task's record instead
	 * ({@link SessionTracker#takeHarvestRecord}, {@link #addHarvestToRecord}). Notable stacks a session takes get
	 * the notable drop line ({@link #announceNotableDrop}).
	 */
	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		if (!clientStateReady)
		{
			return;
		}
		if (pickpocketTick == client.getTickCount())
		{
			// The server sends NPC loot for pickpockets too; like core LootTracker, ignore it.
			return;
		}
		final ItemTally items = new ItemTally();
		for (ItemStack stack : event.getItems())
		{
			items.add(stack.getId(), stack.getQuantity());
		}
		final ItemTally kept = new LootFilter(crushedLootFilter(), ignoredLoot).apply(items, lookups.lootItemNames());
		final NPCComposition npc = event.getComposition();
		final String npcName = npc == null ? null : npc.getName();
		final long account = accountHash;
		final String harvestRecord = tracker.takeHarvestRecord(account, npcName);
		if (harvestRecord != null)
		{
			addHarvestToRecord(account, harvestRecord, kept);
			return;
		}
		// Priced only while recording. A Resume click between the check and addLoot records this kill's loot without its
		// notable stacks (at most one drop's entries); addLoot still decides loot and drops in one step. Passed on even
		// with nothing kept: Araxxor's loot is its harvest whatever it kept, so no harvest window opens after it.
		final boolean priced = !kept.isEmpty() && tracker.isRecordingLoot();
		final List<NotableDrop> drops = priced ? findNotableDrops(kept) : null;
		final boolean added = tracker.addLoot(kept, drops, npcName);
		if (added && tracker.getState().isClockStopped())
		{
			// A stopped session took a paired task kill's late loot: valued again (see updateSessionValues).
			pausedValuesSession = null;
		}
		if (added)
		{
			announceNotableDrop(drops, npcName);
		}
	}

	/**
	 * Client thread. Adds Araxxor's harvest that came after the task its kill completed was saved to that task's record
	 *, as if it had come before the save: its items are priced now, as a save prices a record
	 * ({@link LedgerRecord#captureValues}), and its notable stacks found at the "Loot price" setting, as for any loot;
	 * {@link LedgerStore#addLoot} adds them on the executor, after the record's own save, which the client thread queued
	 * there first. The ledger is then reloaded, like the note and setup edits ({@link #editRecordNote}). The task-complete
	 * chat line went out with the save, and this loot gets no notable drop line: the task it is added to has ended.
	 */
	private void addHarvestToRecord(long account, String id, ItemTally loot)
	{
		if (loot.isEmpty())
		{
			return;
		}
		final ItemValuation.UnitPrices prices = new ItemValuation.UnitPrices();
		try
		{
			ItemValuation.capturePrices(loot, lookups.priceLookup(), prices);
		}
		catch (RuntimeException e)
		{
			log.warn("Unable to price Araxxor's loot for Slayer Ledger record {}", id, e);
		}
		final List<NotableDrop> drops = findNotableDrops(loot, prices);
		executor.execute(() ->
		{
			boolean failed = false;
			try
			{
				store.addLoot(account, id, loot, prices, drops);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to add Araxxor's loot to Slayer Ledger record {}", id, e);
				failed = true;
			}
			// Reload either way so the panel reflects what is actually on disk.
			reloadLedger(account);
			if (failed)
			{
				// Posted after the reload's update, so the refresh does not immediately clear it.
				publishHistoryError(account, SlayerLedgerPanel.HARVEST_FAILED_MESSAGE);
			}
		});
	}

	/**
	 * Client thread. The notable stacks of one kill's kept loot, valued now at the "Loot price" setting through
	 * {@code ItemManager} (see {@link NotableDrops}); none when the lookup fails.
	 */
	private List<NotableDrop> findNotableDrops(ItemTally loot)
	{
		if (loot == null || loot.isEmpty())
		{
			return null;
		}
		try
		{
			final ItemValuation.UnitPrices prices = new ItemValuation.UnitPrices();
			ItemValuation.capturePrices(loot, lookups.priceLookup(), prices);
			return findNotableDrops(loot, prices);
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to value loot for notable drops", e);
			return null;
		}
	}

	/**
	 * Client thread. The notable stacks of one kill's kept loot at its unit prices, at the "Loot price" setting (see
	 * {@link NotableDrops}); none when that fails.
	 */
	private List<NotableDrop> findNotableDrops(ItemTally loot, ItemValuation.UnitPrices prices)
	{
		try
		{
			return NotableDrops.find(loot, prices, lootPriceMode, notableDropThreshold, this::lootItemName,
				System.currentTimeMillis());
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to value loot for notable drops", e);
			return null;
		}
	}

	/**
	 * Client thread. Posts the notable drop line ({@link NotableDropMessage}) for one kill's notable stacks that a
	 * session took (not buffered loot), unless the "Notable drop line" setting is off: the most valuable item that
	 * Ground Items' hidden list doesn't hide ({@link #withoutHiddenDrops}; hidden coins still count), with the task's
	 * kill number while its kills left are known (the overlay bar's kills done of the assigned size). It says the task
	 * is paid for only when the session's supply cost so far, as last valued ({@link #publishedValues}, at most
	 * {@link #SESSION_VALUE_TICKS} ticks old), is known exactly and the drop's value covers it, and only once per task
	 * ({@link #paidForSessionId}).
	 */
	private void announceNotableDrop(List<NotableDrop> drops, String npcName)
	{
		if (drops == null || drops.isEmpty() || !config.notableDropLine())
		{
			return;
		}
		final LootPriceMode mode = lootPriceMode;
		final NotableDrop drop = NotableDropMessage.pick(withoutHiddenDrops(drops), mode);
		if (drop == null)
		{
			return;
		}
		int killNumber = 0;
		int taskSize = 0;
		final SessionTracker.LiveTask live = tracker.liveTask();
		final int assigned = tracker.getCurrentOriginalAmount();
		if (live != null && live.getRemaining() > 0 && assigned >= live.getRemaining())
		{
			killNumber = assigned - live.getRemaining();
			taskSize = assigned;
		}
		final SessionValuation.Values values = publishedValues;
		final Long suppliesCost = values != null && values.getSuppliesUnpriced() == 0 && live != null
			&& Objects.equals(values.getSessionId(), live.getSessionId()) ? values.getSuppliesGe() : null;
		final Long value = drop.value(mode);
		final String sessionId = live == null ? null : live.getSessionId();
		final boolean paidFor = value != null && sessionId != null && !sessionId.equals(paidForSessionId)
			&& NotableDropMessage.paysForTask(value, suppliesCost);
		final String message = NotableDropMessage.chatMessage(drop, mode, npcName, killNumber, taskSize, paidFor);
		if (message != null)
		{
			postChatMessage(message);
			if (paidFor)
			{
				paidForSessionId = sessionId;
			}
		}
	}

	/**
	 * Client thread. {@code drops} without the item stacks Ground Items' hidden list hides from the loot value
	 * ({@link #hiddenLoot}, {@link HiddenLoot#leavesOutAny}): every hidden item but coins, which always count. Pets are
	 * kept. {@code drops} itself when none is left out.
	 */
	private List<NotableDrop> withoutHiddenDrops(List<NotableDrop> drops)
	{
		final List<Integer> ids = new ArrayList<>();
		for (NotableDrop drop : drops)
		{
			if (drop != null && drop.getItemId() != null)
			{
				ids.add(drop.getItemId());
			}
		}
		final HiddenLoot hidden = hiddenLoot(ids);
		if (!hidden.leavesOutAny(ids))
		{
			return drops;
		}
		final List<NotableDrop> shown = new ArrayList<>(drops.size());
		for (NotableDrop drop : drops)
		{
			if (drop == null || drop.getItemId() == null
				|| !hidden.leavesOutAny(Collections.singletonList(drop.getItemId())))
			{
				shown.add(drop);
			}
		}
		return shown;
	}

	/** Client thread. An item's name for a notable drop, or {@code null} when the lookup fails. */
	private String lootItemName(int itemId)
	{
		try
		{
			return lookups.lootItemNames().name(itemId);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	/**
	 * Client thread. The bonecrusher filter for a loot drop now: in Auto mode, from the items in the inventory and worn
	 * right now (the player may switch the crusher on and off mid-task).
	 */
	private CrushedLootFilter crushedLootFilter()
	{
		final BonecrusherMode mode = config.bonecrusherHandling();
		if (!CrushedLootFilter.needsCarriedItems(mode))
		{
			return CrushedLootFilter.forDrop(mode, null);
		}
		final List<Integer> carried = new ArrayList<>();
		for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			final ItemContainer container = client.getItemContainer(containerId);
			if (container != null)
			{
				for (Item item : container.getItems())
				{
					carried.add(item.getId());
				}
			}
		}
		return CrushedLootFilter.forDrop(mode, carried);
	}

	/**
	 * Client thread. Remembers the tick of a pickpocket so its server NPC loot is not counted as kill loot, counts
	 * superior spawns ({@link SuperiorSpawnMessage}; RUNNING only, see {@link SessionTracker#addSuperiorSpawn}, or held
	 * for a kill that (re)starts the session on this tick or the next, see {@link #heldSuperiorSpawns}), counts
	 * a Slayer bracelet charge as a supply ({@link SlayerBracelets}; as any supply, see
	 * {@link SessionTracker#addSupplies}), learns the blowpipe's dart type
	 * from its check message ({@link BlowpipeMessage}), lets a charging message close a
	 * {@link ChargeExclusions} window, adds a pet drop ({@link PetMessage}) to the notable drops (by the loot rules,
	 * see {@link SessionTracker#addPet}), and counts a boss kill count message ({@link KillCountMessage}; by the loot
	 * rules and {@link BossKillCounts}, see {@link SessionTracker#addBossKillCount}).
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!clientStateReady)
		{
			return;
		}
		final ChatMessageType type = event.getType();
		// The chat types core ScreenshotPlugin (pets) and ChatCommandsPlugin (kill counts) check.
		final boolean notificationType = type == ChatMessageType.GAMEMESSAGE || type == ChatMessageType.SPAM
			|| type == ChatMessageType.TRADE || type == ChatMessageType.FRIENDSCHATNOTIFICATION;
		final NotableDrop.Pet pet = PetMessage.parse(notificationType, event.getMessage());
		if (pet != null)
		{
			tracker.addPet(NotableDrop.pet(pet, System.currentTimeMillis()));
		}
		final KillCountMessage.Result killCount = KillCountMessage.parse(notificationType, event.getMessage());
		if (killCount != null && killCount.isBossKill())
		{
			tracker.addBossKillCount(killCount.getBoss(), killCount.getKc());
		}
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM && type != ChatMessageType.MESBOX)
		{
			return;
		}
		if (PICKPOCKET_REGEX.matcher(GameMessageText.plain(event.getMessage())).matches())
		{
			pickpocketTick = client.getTickCount();
		}
		if (SuperiorSpawnMessage.matches(type != ChatMessageType.MESBOX, event.getMessage())
			&& !tracker.addSuperiorSpawn() && tracker.getCurrentRemaining() > 0)
		{
			// The kill that spawned it may (re)start the session on this tick's GameTick or the next (noteKillTick).
			heldSuperiorSpawns++;
			heldSuperiorTick = client.getTickCount();
		}
		final int bracelet = type != ChatMessageType.MESBOX ? SlayerBracelets.chargeUsed(event.getMessage())
			: SlayerBracelets.NONE;
		if (bracelet != SlayerBracelets.NONE)
		{
			// One charge of the worn bracelet: counted while RUNNING, else buffered while a task is assigned
			// (SessionTracker.addSupplies).
			final ItemTally used = new ItemTally();
			used.add(bracelet, 1);
			tracker.addSupplies(used, null, Collections.singletonMap(bracelet, SlayerBracelets.CHARGES_PER_BRACELET));
			// A bracelet of slaughter kept the count after a task kill: handled on the next settled tick, with the NPC
			// deaths around it. An expeditious bracelet's double drop needs nothing: the kills follow the count.
			if (bracelet == SlayerBracelets.SLAUGHTER_BRACELET)
			{
				slaughterKillPending = true;
			}
		}
		final BlowpipeMessage.Darts darts = BlowpipeMessage.parse(event.getMessage());
		if (darts != null)
		{
			// A check message naming a dart type this plugin doesn't know also forgets the type: darts aren't counted.
			setBlowpipeDartId(darts.isLoaded() ? darts.getDartId() : ChargedWeaponUsage.NO_ITEM);
			// The overlay's runway counts what it holds.
			blowpipeContents.messageSeen(darts);
		}
		else if (BlowpipeMessage.isOutOfScales(event.getMessage()))
		{
			blowpipeContents.outOfScales();
		}
		chargeExclusions.messageSeen(event.getMessage(), client.getTickCount());
	}

	/**
	 * Client thread. Remembers "Drop" clicks so the dropped item's decrease is not counted as a supply, teleport scrolls
	 * stored in the master scroll book ({@link SupplyExclusions#useClicked}), and loading, charging, unloading or
	 * uncharging the blowpipe, a trident or a powered staff ({@link ChargeExclusions}). Only reads the click; the menu
	 * is never changed.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!clientStateReady)
		{
			return;
		}
		final String option = event.getMenuOption();
		if (option == null)
		{
			return;
		}
		final String plain = Text.removeTags(option).trim();
		final int itemId = event.getItemId();
		final int tick = client.getTickCount();
		if ("Drop".equalsIgnoreCase(plain))
		{
			if (itemId >= 0)
			{
				// Dropping a rune pouch counts nothing on these ticks: the runes inside leave with the pouch.
				supplyExclusions.dropClicked(itemId, SupplyReader.isRunePouch(itemId), tick);
			}
			return;
		}
		if ("Use".equalsIgnoreCase(plain))
		{
			// Only the click that uses the selected item on another one; selecting an item is also "Use".
			if (event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_WIDGET)
			{
				final int[] used = useItemIds(event);
				chargeExclusions.menuOptionClicked(option, used, tick);
				supplyExclusions.useClicked(used, tick);
				for (int id : used)
				{
					if (ChargedWeaponUsage.BLOWPIPES.contains(id))
					{
						// Darts or scales loaded: what it holds is known again only from a check message.
						blowpipeContents.forget();
						break;
					}
				}
			}
			return;
		}
		if ("Charge".equalsIgnoreCase(plain))
		{
			// The powered staves' charge prompt takes the runes from the inventory.
			chargeExclusions.menuOptionClicked(option, new int[]{itemId}, tick);
			return;
		}
		if ("Unload".equalsIgnoreCase(plain) || "Uncharge".equalsIgnoreCase(plain))
		{
			chargeExclusions.menuOptionClicked(option, new int[]{itemId}, tick);
			if (ChargedWeaponUsage.BLOWPIPES.contains(itemId))
			{
				// The darts come out; the type is learned again from the next check message.
				setBlowpipeDartId(ChargedWeaponUsage.NO_ITEM);
				blowpipeContents.forget();
			}
		}
	}

	/**
	 * Client thread. The items of an item-on-item "Use": the target (the clicked entry's item and its widget's item)
	 * and the selected item ({@code client.getSelectedWidget()}, as core CompostTracker reads it, 1.13.4).
	 */
	private int[] useItemIds(MenuOptionClicked event)
	{
		final Widget target = event.getWidget();
		final Widget selected = client.getSelectedWidget();
		return new int[]{
			event.getItemId(),
			target != null ? target.getItemId() : -1,
			selected != null ? selected.getItemId() : -1
		};
	}

	/**
	 * Client thread. An excluded interface opening; also covers one opened and closed between two ticks. A bank opening
	 * may be a bank trip ({@link BankTripCounter}; RUNNING only).
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (!clientStateReady)
		{
			return;
		}
		final int tick = client.getTickCount();
		supplyExclusions.interfaceChanged(event.getGroupId(), tick);
		if (event.getGroupId() == InterfaceID.OBJECTBOX)
		{
			// The trident's "You add N charges to the weapon." is an item dialog. Its text may be set after the
			// interface loads, so it is read later on the client thread, as core ItemChargePlugin reads the dialog's
			// item (1.13.4).
			clientThread.invokeLater(this::readObjectboxText);
		}
		if (BankTripCounter.isBankInterface(event.getGroupId()))
		{
			final SessionTracker.State state = tracker.getState();
			final boolean active = state.isActive();
			if (bankTripCounter.bankOpened(tick, state == SessionTracker.State.RUNNING,
				active ? tracker.getSessionId() : null))
			{
				tracker.addBankTrip();
			}
		}
	}

	/** Client thread. Lets the item dialog's text close a {@link ChargeExclusions} window. */
	private void readObjectboxText()
	{
		final Widget text = client.getWidget(InterfaceID.Objectbox.TEXT);
		if (text != null)
		{
			chargeExclusions.messageSeen(text.getText(), client.getTickCount());
		}
	}

	/**
	 * Client thread. An excluded interface closing; items it moved may only arrive on the next tick. A bank closing
	 * starts the same-trip window.
	 */
	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (!clientStateReady)
		{
			return;
		}
		final int tick = client.getTickCount();
		supplyExclusions.interfaceChanged(event.getGroupId(), tick);
		if (BankTripCounter.isBankInterface(event.getGroupId()))
		{
			bankTripCounter.bankClosed(tick);
		}
	}

	/**
	 * Client thread. A death of the local player: counted while RUNNING ({@link SessionTracker#addDeath}), and the
	 * items that leave the inventory after it are not supplies used. A death of an NPC the player damaged
	 * ({@link #onHitsplatApplied}) is kept for pairing with a task kill around it ({@link DamagedNpcs#pairing}, V2 plan
	 * 4.1) and tallied under its name ({@link SessionTracker#addNpcKill}): now while RUNNING, else by the kill it
	 * is paired with if that kill (re)starts the session ({@link #noteKillTick}).
	 */
	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!clientStateReady)
		{
			return;
		}
		if (event.getActor() != null && event.getActor() == client.getLocalPlayer())
		{
			supplyExclusions.playerDied(client.getTickCount());
			tracker.addDeath();
		}
		else if (event.getActor() instanceof NPC)
		{
			final NPC npc = (NPC) event.getActor();
			final int worldViewId = worldViewId(npc);
			if (!damagedNpcs.isDamaged(worldViewId, npc.getIndex()))
			{
				return;
			}
			final String name = npc.getName();
			// An NPC outside the Catacombs with a variant's name is not tallied at all (CatacombsVariants#tallyName).
			final String tallyName = CatacombsVariants.tallyName(npc.getId(), name);
			// Tallied now only while RUNNING (the tracker decides). A death before the kill that (re)starts the session
			// is tallied by that kill (noteKillTick), once.
			final boolean tallied = tracker.addNpcKill(tallyName);
			damagedNpcs.died(worldViewId, npc.getIndex(), name, tallyName, tallied, client.getTickCount(),
				tracker.now(), tracker.getAwayMillis());
		}
	}

	/**
	 * Client thread. Remembers an NPC the player hit, with when their run of hits on it began (V2 plan 4.1), while a
	 * task is assigned, a session exists or a completion is held for late loot (its final kill's last hits may land the
	 * tick after the task count's drop): its death is the player's kill in the session's kills per NPC name
	 * ({@link SessionTracker#addNpcKill}), and a task kill paired with it is backdated to that start. It is
	 * remembered now, so a death later in this tick finds it. The rest waits for this tick's GameTick, after its
	 * supplies, XP and attack are read ({@link #applyHits}): the hit is put down to the player's attack, for its
	 * style and to start its run no later than the attack's tick, and a hit on one of the session's known task
	 * NPCs is activity for Away ({@link SessionTracker#taskNpcHit}). Only the player's own hitsplats count
	 * ({@code Hitsplat.isMine()}); {@link DamagedNpcs} keeps a bounded number of NPCs.
	 */
	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!clientStateReady || !(event.getActor() instanceof NPC) || event.getHitsplat() == null
			|| !event.getHitsplat().isMine())
		{
			return;
		}
		if (!tracker.getState().isActive() && tracker.getCurrentRemaining() <= 0 && !tracker.hasPendingCompletion())
		{
			return;
		}
		final NPC npc = (NPC) event.getActor();
		damagedNpcs.damaged(worldViewId(npc), npc.getIndex(), tracker.now(), tracker.getAwayMillis(),
			client.getTickCount());
		final String name = npc.getName();
		if (name != null && hitNpcNames.size() < MAX_HIT_NPC_NAMES)
		{
			hitNpcNames.add(name);
		}
	}

	/** Client thread. Forgets a despawned NPC the player damaged: its index can be reused. */
	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (!clientStateReady || event.getNpc() == null)
		{
			return;
		}
		damagedNpcs.forget(worldViewId(event.getNpc()), event.getNpc().getIndex());
	}

	/**
	 * Client thread. The id of the world view {@code npc} is in: NPC indexes are unique only within one world
	 * view (the top-level one, or a boat's), so {@link DamagedNpcs} keeps both. An NPC without a world view is taken
	 * as top-level ({@link WorldView#TOPLEVEL}), the same way on its hit, death and despawn.
	 */
	private static int worldViewId(NPC npc)
	{
		final WorldView worldView = npc.getWorldView();
		return worldView == null ? WorldView.TOPLEVEL : worldView.getId();
	}

	/**
	 * Client thread. Reads this tick's tracked containers and adds what was used ({@link SessionTracker#addSupplies};
	 * the diff and its rules are in {@link SupplyTracker}): to the session while it runs, otherwise to the buffer
	 * outside segments, which a (re)start counts from its warm-up (V2 plan 4.1). The baseline always moves to this
	 * tick, so changes made inside an excluded interface are never counted later.
	 *
	 * <p>The diff runs while the tracker collects ({@link SessionTracker#isCollecting}): a session is running, or a task
	 * is assigned and not Ended (Waiting for the first kill, Away, Paused, after a login). While no task is assigned
	 * (none, or a completion held for late loot) or it is Ended, the containers are not read and the baseline is
	 * dropped; only the inventory is read, once after it changes, to note its potions
	 * ({@link #notePotionVariants}), and the excluded interfaces are still checked every tick, so one closed just before
	 * the diff resumes still shields its first ticks.</p>
	 *
	 * <p>A running session's ticks left out in a long stretch leave a log line with the reason
	 * ({@link #noteSkippedSupplyTick}), so a silent stop leaves a trace.</p>
	 *
	 * <p>Every tick, diffed or not, tells the overlay's feed what the counting leaves out (the whole tick, or dropped
	 * and charged items; {@link OverlayFeed#suppliesLeftOut}), so a supply that leaves the inventory then, banked or
	 * dropped, is forgotten by the runway rather than shown as run out.</p>
	 */
	private void trackSupplies()
	{
		final int tick = client.getTickCount();
		final int openGroup = openSupplyExcludedInterface();
		supplyExclusions.beginTick(tick, openGroup != NO_INTERFACE);
		final boolean excluded = supplyExclusions.isTickExcluded(tick);
		final Set<Integer> dropped = supplyExclusions.droppedItems();
		final Set<Integer> charged = chargeExclusions.excludedItems(tick);
		// Every tick, counted or not: a supply that leaves on such a tick (banked, dropped) never runs out.
		overlayFeed.suppliesLeftOut(excluded, dropped);
		overlayFeed.suppliesLeftOut(false, charged);

		final boolean running = tracker.getState() == SessionTracker.State.RUNNING;
		looseScales = 0;
		if (!tracker.isCollecting())
		{
			skippedSupplyTicks.reset();
			supplyTracker.reset();
			notePotionVariants();
			return;
		}
		final SupplyTracker.Observation observation = supplyReader.readSupplyObservation();
		if (observation == null)
		{
			supplyTracker.reset();
			noteSkippedSupplyTick(running, tick, openGroup, false);
			return;
		}
		looseScales = observation.getItems().getOrDefault(SupplyRunway.ZULRAH_SCALES, 0L);
		// Charged materials are skipped both ways: loading darts is not a use, and unloading them is not a return.
		final SupplyTracker.Usage usage = supplyTracker.update(observation, true, excluded, dropped, charged);
		if (!usage.isEmpty())
		{
			tracker.addSupplies(usage.getUsed(), usage.getReturned(), usage.getDoses());
		}
		if (excluded)
		{
			noteSkippedSupplyTick(running, tick, openGroup, true);
		}
		else
		{
			skippedSupplyTicks.reset();
		}
	}

	/**
	 * Client thread. The first of {@link #SUPPLY_EXCLUDED_INTERFACES} open now, or {@link #NO_INTERFACE}. An interface
	 * is open while its root widget is loaded and shown ({@code !isHidden()}, as core ItemStatPlugin checks the GE offers
	 * interface, 1.13.4). A loaded root widget alone is not enough: the game's own widget lookup also loads a
	 * group whenever a script or server packet refers to one of its components, without opening it or posting
	 * WidgetLoaded, so a group can stay loaded after its interface was closed. Its root widget then has no parent, so
	 * it reads hidden; taking it for open would leave every later tick out of supply counting.
	 */
	private int openSupplyExcludedInterface()
	{
		for (int group : SUPPLY_EXCLUDED_INTERFACES)
		{
			final Widget root = client.getWidget(group, 0);
			if (root != null && !root.isHidden())
			{
				return group;
			}
		}
		return NO_INTERFACE;
	}

	/**
	 * Client thread. A tick whose supplies were not counted. While a session runs, an unusually long stretch of such
	 * ticks leaves a rate-limited log line with the reason ({@link SkippedSupplyTicks}): the first at debug level, the
	 * repeats (ten minutes or more, rare for a real visit) at info, so a silent stop of supply counting leaves a trace
	 * in the default client log. Cheap: the reason is only worked out when a line is due.
	 *
	 * @param openGroup       the excluded interface open on this tick, or {@link #NO_INTERFACE}
	 * @param inventoryLoaded whether the inventory could be read
	 */
	private void noteSkippedSupplyTick(boolean running, int tick, int openGroup, boolean inventoryLoaded)
	{
		if (!running)
		{
			skippedSupplyTicks.reset();
			return;
		}
		if (!skippedSupplyTicks.skipped())
		{
			return;
		}
		final String reason;
		if (!inventoryLoaded)
		{
			reason = "the inventory is not loaded";
		}
		else if (openGroup != NO_INTERFACE)
		{
			reason = "excluded interface " + openGroup + " is open";
		}
		else
		{
			reason = supplyExclusions.exclusionReason(tick);
		}
		final int length = skippedSupplyTicks.length();
		if (length > SkippedSupplyTicks.FIRST_REPORT_TICKS)
		{
			// Ten minutes or more is rare for a real visit, so it reaches the default (INFO) client log.
			log.info("Supplies not counted for {} game ticks in a row while the session runs: {}", length, reason);
		}
		else
		{
			log.debug("Supplies not counted for {} game ticks in a row while the session runs: {}", length, reason);
		}
	}

	/**
	 * Client thread, while no supplies diff runs (no task assigned, or it is Ended). The diff used to see the inventory
	 * every tick, and each potion's use is recorded under the highest-dose variant the tracker has seen
	 * ({@link SupplyTracker}); so, after the inventory changed, its items alone are read once and their potions noted
	 *. A potion drunk from 4 to 3 doses before a task is assigned is still recorded as the 4-dose item.
	 *
	 * <p>Each read notes every item whose data is loaded. An item whose data is not loaded yet is retried on the next
	 * idle ticks, at most {@link #INVENTORY_NOTE_TRIES} reads per change: apart from a lookup that threw, only a
	 * wieldable item waiting for its item stats, which is never a potion, or a members item seen on a free world
	 * ({@link SupplyReader#classifyItem}) can be in that state. A login or hop to a members world reads the inventory
	 * again, so stopping loses no potion. Counting is unchanged: the diff classifies every item it sees while it
	 * runs.</p>
	 */
	private void notePotionVariants()
	{
		if (inventoryNoteTries <= 0)
		{
			return;
		}
		final SupplyTracker.Observation inventory = supplyReader.readInventoryObservation();
		if (inventory == null || supplyTracker.noteVariants(inventory))
		{
			// Not loaded: the client posts ItemContainerChanged when it is. Noted: nothing left to read.
			inventoryNoteTries = 0;
		}
		else
		{
			// Item data not loaded yet: noted again next tick, a few times at most.
			inventoryNoteTries--;
		}
	}

	/** Client thread. The inventory changed: its potions are noted on the next tick no diff runs. */
	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (clientStateReady && event.getContainerId() == InventoryID.INV)
		{
			inventoryNoteTries = INVENTORY_NOTE_TRIES;
		}
	}

	/**
	 * Client thread. Counts this tick's blowpipe shot or trident or powered staff cast ({@link ChargedWeaponUsage}) from
	 * the worn weapon and cape, the local player's animation and frame, and the weapon's cast graphics
	 * ({@link ChargedWeaponUsage#castGraphics}, {@code Actor#hasSpotAnim}, 1.13.4), and adds what it used
	 * ({@link SessionTracker#addSupplies}: to the session while it runs, otherwise to the buffer outside segments).
	 * Only while the supplies diff runs ({@link SessionTracker#isCollecting}): otherwise the carry-overs, the dart
	 * hint and the recent attacks are reset, apart from the attacks while a completion is held for late loot, whose
	 * final kill's last hits may land on the next tick. Also shows or hides the panel's "Check your blowpipe"
	 * hint, while the session runs, and notes this tick's attack for the styles of the hits it lands
	 * ({@link #noteAttack}).
	 *
	 * @param tickStart when this tick began (clock millis), before its supplies and XP were read
	 */
	private void trackChargedWeapons(long tickStart)
	{
		final Player player = tracker.isCollecting() ? client.getLocalPlayer() : null;
		if (player == null)
		{
			chargedWeaponUsage.reset();
			// What the blowpipe holds is kept, between tasks and after End task too, though shots now are not taken out
			// of it: only loading, Unload, Uncharge, logout and another account forget it.
			blowpipeWorn = false;
			if (tracker.hasPendingCompletion())
			{
				playerAttacks.forgetXp();
			}
			else
			{
				playerAttacks.clear();
			}
			publishDartHint(false);
			return;
		}
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		final int weaponId = SupplyReader.wornItemId(worn, EquipmentInventorySlot.WEAPON);
		final int animationId = player.getAnimation();
		final int animationFrame = player.getAnimationFrame();
		noteAttack(player, weaponId, animationId, animationFrame, tickStart);
		boolean castGraphic = false;
		for (int graphic : ChargedWeaponUsage.castGraphics(weaponId, animationId))
		{
			castGraphic |= player.hasSpotAnim(graphic);
		}
		final Map<Integer, Integer> used = chargedWeaponUsage.update(ChargedWeaponUsage.Tick.builder()
			.tick(client.getTickCount())
			.weaponId(weaponId)
			.animationId(animationId)
			.animationFrame(animationFrame)
			.capeId(SupplyReader.wornItemId(worn, EquipmentInventorySlot.CAPE))
			// Dizana's quiver setting (varbit 9803) is not verified in game yet: assume it saves 80%.
			.quiverAmmoSave(null)
			.castGraphic(castGraphic)
			.vorkathsHeadUpgrade(config.vorkathsHeadUpgrade())
			.dartId(blowpipeDartId)
			.build());
		blowpipeWorn = ChargedWeaponUsage.BLOWPIPES.contains(weaponId);
		if (!used.isEmpty())
		{
			final ItemTally items = new ItemTally();
			used.forEach(items::add);
			tracker.addSupplies(items, null, null);
			if (blowpipeWorn)
			{
				blowpipeContents.used(used);
			}
		}
		publishDartHint(tracker.getState() == SessionTracker.State.RUNNING && chargedWeaponUsage.isDartCheckNeeded()
			&& ChargedWeaponUsage.BLOWPIPES.contains(weaponId));
	}

	/**
	 * Client thread. Notes the player's attack starting this tick on the NPC they are interacting with
	 * ({@link PlayerAttacks}): an animation at its first frame (as {@link ChargedWeaponUsage} counts attacks), not
	 * eating or drinking, while the player is interacting with an NPC, so loading a cannon or picking something up is
	 * not one, and with XP gained this tick in {@link AttackStyles#ATTACK_XP_SKILLS}, so a block is not one either. The
	 * XP is read every tick for that. Its style comes from the animation and the worn weapon
	 * ({@link AttackStyles#attackStyle}); an attack whose style isn't known (the weapon's stats not loaded yet) is not
	 * noted.
	 */
	private void noteAttack(Player player, int weaponId, int animationId, int animationFrame, long tickStart)
	{
		final boolean xpRose = playerAttacks.xpRose(readAttackXp());
		final Actor target = player.getInteracting();
		if (animationFrame != 0 || !AttackStyles.mayBeAttack(animationId) || !(target instanceof NPC) || !xpRose)
		{
			return;
		}
		final NPC npc = (NPC) target;
		final SetupStyle weapon = AttackStyles.isSpell(animationId) ? null : weaponStyle(weaponId);
		playerAttacks.add(client.getTickCount(), AttackStyles.attackStyle(animationId, weapon), tickStart,
			DamagedNpcs.key(worldViewId(npc), npc.getIndex()), AttackStyles.splashes(animationId, weaponId));
	}

	/**
	 * Client thread. The total XP of {@link AttackStyles#ATTACK_XP_SKILLS} now, or {@link PlayerAttacks#NO_XP} before
	 * the stats are loaded (Hitpoints XP reads 0, as {@link #observeSkillXp} checks).
	 */
	private long readAttackXp()
	{
		if (client.getSkillExperience(Skill.HITPOINTS) <= 0)
		{
			return PlayerAttacks.NO_XP;
		}
		long total = 0;
		for (Skill skill : AttackStyles.ATTACK_XP_SKILLS)
		{
			total += client.getSkillExperience(skill);
		}
		return total;
	}

	/**
	 * Client thread. The worn weapon's style from its equipment stats ({@link AttackStyles#weaponStyle}): Melee when
	 * nothing is wielded (unarmed), {@code null} when its stats are not loaded.
	 */
	private SetupStyle weaponStyle(int weaponId)
	{
		if (weaponId == ChargedWeaponUsage.NO_ITEM)
		{
			return SetupStyle.MELEE;
		}
		final ItemStats stats = itemManager.getItemStats(weaponId);
		final ItemEquipmentStats e = stats == null ? null : stats.getEquipment();
		if (e == null)
		{
			return null;
		}
		return AttackStyles.weaponStyle(e.getAstab(), e.getAslash(), e.getAcrush(), e.getAmagic(), e.getArange(),
			e.getRstr());
	}

	/**
	 * Client thread. Reads whether the player's cannon is placed ({@code DROPCANNON} 4) and decayed
	 * ({@code MCANNON_DECAYED} 1), as core CannonPlugin reads them (1.13.4), and its loaded cannonballs
	 * ({@code ROCKTHROWER}) for {@link CannonFire}. Only while the supplies diff runs
	 * ({@link SessionTracker#isCollecting}), so nothing is read while no task is assigned; otherwise its shots are
	 * forgotten.
	 */
	private void trackCannon()
	{
		if (!tracker.isCollecting())
		{
			cannonFire.reset();
			return;
		}
		cannonFire.update(client.getTickCount(), client.getVarpValue(VarPlayerID.DROPCANNON) == CannonFire.PLACED,
			client.getVarbitValue(VarbitID.MCANNON_DECAYED) == 1, client.getVarpValue(VarPlayerID.ROCKTHROWER));
	}

	/** Client thread. Shows or hides the panel's "Check your blowpipe" hint (on the EDT) when it changes. */
	private void publishDartHint(boolean shown)
	{
		if (shown == dartHintShown)
		{
			return;
		}
		dartHintShown = shown;
		final SlayerLedgerPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.setDartHint(shown));
		}
	}

	/**
	 * Client thread. Values the active session's loot and supplies for the panel, at most once every
	 * {@link #SESSION_VALUE_TICKS} ticks. ItemManager is only called here, on the client thread; {@link SessionValuation}
	 * caches unit prices for the session and skips the lookups when nothing changed. Results reach the panel on the
	 * EDT, and only when they differ from what it shows. When no session is active the values are cleared.
	 *
	 * <p>A stopped (Away, Paused or Logged out) session's supplies can't change (they are buffered), nor its loot apart
	 * from a paired task kill's late loot, so once it has been valued while stopped with every GE price known, it is not
	 * valued again (no copy of its tallies is taken) until such loot arrives, it restarts or the "Loot price" setting
	 * changes. While a price is unavailable it keeps being valued, so the retry can still fill it in.</p>
	 */
	private void updateSessionValues()
	{
		final SessionTracker.State state = tracker.getState();
		if (!state.isActive())
		{
			if (publishedValues != null)
			{
				sessionValuation.reset();
				publishSessionValues(null);
			}
			// The next session is valued on its first tick.
			sessionValueTick = SupplyExclusions.NEVER_TICK;
			pausedValuesSession = null;
			return;
		}
		final LootPriceMode mode = lootPriceMode;
		final GroundItemsHidden hiddenList = groundItemsHidden;
		// A new "Loot price" setting or hidden list is valued at once (once: a failing valuation is still throttled).
		final boolean modeChanged = mode != sessionValueMode || !hiddenList.equals(sessionValueHidden);
		final boolean stopped = state.isClockStopped();
		if (!stopped)
		{
			pausedValuesSession = null;
		}
		else if (!modeChanged && pausedValuesSession != null && pausedValuesSession.equals(tracker.getSessionId()))
		{
			// Valued while stopped (Away, Paused or Logged out) already, in this mode and with every price known:
			// nothing can have changed.
			return;
		}
		final int tick = client.getTickCount();
		// Throttled whether or not the last valuation succeeded, so a failing price lookup is not retried every tick.
		if (!modeChanged && tick >= sessionValueTick && tick - sessionValueTick < SESSION_VALUE_TICKS)
		{
			return;
		}
		sessionValueTick = tick;
		sessionValueMode = mode;
		sessionValueHidden = hiddenList;
		final SessionTracker.Summary active = tracker.activeSummary();
		if (active == null)
		{
			return;
		}
		final SessionValuation.Values values;
		try
		{
			final HiddenLoot hidden = hiddenLoot(active.getLoot() == null ? null : active.getLoot().itemIds());
			values = sessionValuation.update(active.getSessionId(), active.getLoot(), active.getSupplies(),
				active.getSupplyDoses(), mode, hidden, lookups.priceLookup(), tick);
		}
		catch (RuntimeException e)
		{
			log.debug("Unable to value the Slayer Ledger session", e);
			return;
		}
		// The state read above: a session resumed meanwhile is RUNNING on the next tick, which clears this again.
		pausedValuesSession = stopped && values.getLootUnpriced() == 0
			&& values.getSuppliesUnpriced() == 0 ? active.getSessionId() : null;
		if (!values.equals(publishedValues))
		{
			publishSessionValues(values);
		}
	}

	/** Client thread. Sends the live session values (or {@code null} to clear them) to the panel on the EDT. */
	private void publishSessionValues(SessionValuation.Values values)
	{
		publishedValues = values;
		final SlayerLedgerPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.setSessionValues(values));
		}
	}

	/**
	 * Client thread. Takes a fresh supplies baseline now, so nothing from before it is counted: only for the
	 * {@link #startSessionNow} test seam, which counts nothing from before it as the removed Play did. A real (re)start
	 * needs none: the diff runs while a task is assigned, and the tracker counts the warm-up from its buffer.
	 */
	private void takeSupplyBaseline()
	{
		if (supplyTracker == null)
		{
			return;
		}
		supplyTracker.reset();
		// Fractional darts and scales from before are not carried into the started or resumed session.
		chargedWeaponUsage.reset();
		final SupplyTracker.Observation observation = supplyReader.readSupplyObservation();
		if (observation != null)
		{
			supplyTracker.update(observation, false, true, Collections.emptySet());
		}
	}

	/**
	 * Client thread. Runs the pending file-restore or re-login check, deferring while the task count still reads
	 * zero (possibly not yet synced) for up to {@link SessionTracker#RESTORE_SYNC_MAX_TICKS} ticks.
	 */
	private void runPendingRestoreCheck(int remaining, int[] counters)
	{
		if (SessionTracker.shouldDeferRestoreCheck(remaining, restoreWaitTicks))
		{
			restoreWaitTicks++;
			return;
		}
		final boolean fileRestore = pendingFileRestore;
		final SessionSnapshot reloginSnapshot = pendingReloginSnapshot;
		pendingFileRestore = false;
		pendingReloginSnapshot = null;

		if (fileRestore)
		{
			// restorePending is cleared when the load is applied.
			loadActiveSession(accountHash);
		}
		if (reloginSnapshot != null)
		{
			try
			{
				if (!tracker.activeSessionStillMatches(reloginSnapshot, counters))
				{
					log.debug("Session {} no longer matches the task after re-login", reloginSnapshot.getSessionId());
					endSession(SaveDecision.EndReason.RESTORE_MISMATCH);
				}
			}
			finally
			{
				restorePending = false;
			}
		}
	}

	/** Client thread. Drops any pending restore check and invalidates in-flight loads (logout, account change). */
	private void cancelPendingRestore()
	{
		pendingFileRestore = false;
		pendingReloginSnapshot = null;
		restoreWaitTicks = 0;
		loadGeneration++;
		restorePending = false;
	}


	// ---- Panel actions (EDT) ----

	/**
	 * Test seam: starts a session at once ({@link SessionTracker#startNow}), as the removed Play did, for tests whose
	 * subject is not how a session starts; the player starts sessions with a task kill.
	 */
	boolean startSessionNow()
	{
		if (!loggedIn || restorePending || !tracker.startNow(accountHash))
		{
			return false;
		}
		// Supplies count from now: anything used before is never counted.
		clientThread.invoke(this::takeSupplyBaseline);
		refreshHistoryModel();
		return true;
	}

	/** Pause: the running session's segment closes now. */
	void pause()
	{
		tracker.pause();
		refreshHistoryModel();
	}

	/**
	 * Resume, while Paused: opens a segment at once, a restart, so the supplies used in the warm-up before it count
	 * (V2 plan 4.1); the supplies diff kept running while paused, so it needs no new baseline.
	 */
	boolean resume()
	{
		if (!canResume() || !tracker.resume(accountHash))
		{
			return false;
		}
		refreshHistoryModel();
		return true;
	}

	/** Whether Resume would succeed: logged in, no restore check pending, and the session is this account's and Paused. */
	boolean canResume()
	{
		return loggedIn && !restorePending && tracker.canResume(accountHash);
	}

	/**
	 * End task: the session, if any, is saved through the Keep / Discard decision (as Stop was), and its assignment is
	 * Ended: no kill on it starts a session until Track again (V2 plan 4.1).
	 */
	void endTask()
	{
		// Any completed session still held for late loot is saved first, as completed.
		flushPendingCompletion();
		handleEndedSession(tracker.endTask(), SaveDecision.EndReason.PLAYER_STOP);
		refreshHistoryModel();
	}

	/**
	 * Track again: the Ended assignment waits for its first kill again. Its marker, if a logout wrote one (Track again
	 * can be pressed at the login screen), is deleted, so the next login or client start can't make it Ended again.
	 */
	void trackAgain()
	{
		final long account = tracker.getEndedAccount();
		if (tracker.trackAgain())
		{
			deleteEndedMarker(account);
		}
		refreshHistoryModel();
	}

	/**
	 * What the task overlay shows, or {@code null} when there is nothing to show: no active session with a task (idle, a
	 * no-task session, or a completed one held for late loot) and no assigned task waiting for its first kill or Ended.
	 * The task comes from one {@link SessionTracker#liveTask()} call, which carries its status for the state line, its
	 * kills, active time and kills left, so the clock and a Pause show at once. The rest is what was last published,
	 * used only when it belongs to the same session: the tick's snapshot ({@link #publishOverlaySnapshot}: the name with
	 * its variant and cannon, the spot, the tags, superiors, XP, the runway and the moment), the live values and the
	 * historical time per kill ({@link #publishHistoricalPace}). Without a session, the state line with the assignment's
	 * snapshot (V2 plan 4.1: the state shows whenever time isn't running). Nothing after the plugin's start or a logout
	 * until the first settled tick has read the logged-in account's task ({@link #overlaySettled}), so another account
	 * never sees the last one's state. Called by the overlay on the client thread every frame, so it only reads.
	 */
	OverlayRows.Data overlayData()
	{
		if (tracker == null || !clientStateReady || !overlaySettled)
		{
			return null;
		}
		final OverlayRows.Snapshot snapshot = overlaySnapshot;
		SessionTracker.LiveTask task = tracker.liveTask();
		if (task == null)
		{
			final SessionTracker.Status status = tracker.getStatus();
			return loggedIn && (status == SessionTracker.Status.WAITING_FOR_FIRST_KILL
				|| status == SessionTracker.Status.ENDED) ? OverlayRows.Data.stateOnly(status,
				snapshot != null && snapshot.getSessionId() == null ? snapshot : null) : null;
		}

		SessionValuation.Values values = publishedValues;
		if (values != null && !Objects.equals(task.getSessionId(), values.getSessionId()))
		{
			values = null;
		}
		final OverlayRows.HistoricalPace pace = historicalPace;
		return new OverlayRows.Data(task,
			snapshot != null && Objects.equals(task.getSessionId(), snapshot.getSessionId()) ? snapshot : null,
			values, pace == null ? null : pace.millisPerKillFor(task));
	}

	/**
	 * EDT, from the history model ({@link LedgerHistoryModel#refreshHistoricalPace}) whenever the records, a region
	 * name, the task, its location or the session change; never from a timer. Publishes the historical time per kill
	 * the sidebar's "Time left" uses for the active session, or {@code null} to clear it (no session, or no history for
	 * its task), so the overlay shows the same estimate. Only a volatile write: no other work.
	 */
	void publishHistoricalPace(OverlayRows.HistoricalPace pace)
	{
		historicalPace = pace;
	}

	/**
	 * Puts an item's icon on a sidebar label ({@link ItemIcons}), with the quantity drawn when it is above 1, as
	 * Loot Tracker does. Called on the EDT, as Loot Tracker calls it: unlike the rest of {@code ItemManager},
	 * {@code getImage} may be called from any thread. It returns a cached image at once (blank until drawn) and queues
	 * the sprite drawing to the client thread; {@code addTo} repaints the label once the sprite is drawn.
	 */
	void applyItemIcon(JLabel label, int itemId, int quantity)
	{
		AsyncBufferedImage image = itemManager.getImage(itemId, quantity, quantity > 1);
		if (image != null)
		{
			image.addTo(label);
		}
	}

	/**
	 * Puts a skill's small icon on a sidebar label ({@link SkillIcons}), as the XP tracker shows before a skill's
	 * name; a key that is no {@link Skill} constant (a skill this client does not know) leaves the label without an
	 * icon.
	 *
	 * <p>Checked against RuneLite 1.13.4: {@code SkillIconManager.getSkillImage(Skill skill, boolean small)} returns a
	 * {@code BufferedImage} loaded from the client's {@code skill_icons_small} resources (16 by 16 px, Ranged 18) and
	 * caches it per skill. It reads nothing from the client, so it needs no client thread, but its cache is an
	 * unsynchronized array: it is called only on the EDT, as the XP tracker and Skill Calculator panels call it.</p>
	 */
	void applySkillIcon(JLabel label, String skill)
	{
		if (skill == null)
		{
			return;
		}
		Skill constant;
		try
		{
			constant = Skill.valueOf(skill);
		}
		catch (IllegalArgumentException e)
		{
			return;
		}
		BufferedImage image = skillIconManager.getSkillImage(constant, true);
		if (image != null)
		{
			label.setIcon(new ImageIcon(image));
		}
	}

	/**
	 * Loads a setup tag's game image for the sidebar ({@link SetupIcons}, the live card's toggles and the Task
	 * history rows, which ask for each image once through {@link SetupImages}), on the EDT. The cannon barrels come
	 * from {@code ItemManager.getImage}, as {@link #applyItemIcon}: a cached image at once, drawn later on the client
	 * thread, which then runs {@code repaint}. A spell or skill sprite comes from
	 * {@code SpriteManager.getSpriteAsync}, which reads only its own cache and otherwise queues the read on the client
	 * thread (until the game's cache is loaded); it calls back there, or at once when cached, so the image is handed to
	 * {@code show} with {@code invokeLater} (DESIGN_PRINCIPLES.md 4.5).
	 */
	void loadSetupIcon(SetupTagIcons.Icon icon, Consumer<Image> show, Runnable repaint)
	{
		if (icon.isItem())
		{
			AsyncBufferedImage image = itemManager.getImage(icon.getId(), 1, false);
			if (image != null)
			{
				image.onLoaded(repaint);
				show.accept(image);
			}
			return;
		}
		spriteManager.getSpriteAsync(icon.getId(), 0,
			(BufferedImage sprite) -> SwingUtilities.invokeLater(() -> show.accept(sprite)));
	}

	/**
	 * Deletes a saved ledger record (history Delete or the partial notice's Discard) on the executor, then reloads
	 * the account's ledger and refreshes the panel. Never touches the active (in-progress) session or its file.
	 */
	void deleteRecord(long account, String id)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		executor.execute(() ->
		{
			boolean failed = false;
			try
			{
				store.delete(account, id);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to delete Slayer Ledger record", e);
				failed = true;
			}
			// Reload either way so the panel reflects what is actually on disk.
			reloadLedger(account);
			if (failed)
			{
				// Posted after the reload's update, so the refresh does not immediately clear it.
				publishHistoryError(account, SlayerLedgerPanel.DELETE_FAILED_MESSAGE);
			}
		});
	}

	/**
	 * Deletes an assignment entry (the "Skipped / blocked" section's Delete) on the executor, then shows the account's
	 * entries again. Never touches the records or the active session.
	 */
	void deleteAssignment(long account, String id)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		executor.execute(() ->
		{
			try
			{
				publishAssignments(account, store.deleteAssignment(account, id));
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to delete Slayer Ledger assignment entry", e);
				// Reload so the panel reflects what is actually on disk, then post the error after that update.
				reloadLedger(account);
				publishHistoryError(account, SlayerLedgerPanel.DELETE_ENTRY_FAILED_MESSAGE);
			}
		});
	}


	/**
	 * Sets the note of the session the panel's note box belongs to (see {@link SessionTracker#setNote}). If that
	 * session has ended and was handed off for saving meanwhile (for example the task completed while the player was
	 * typing), the note is written to its saved record instead: via the client thread, so the record's save, which is
	 * queued on the executor from the client thread, is queued first and the note lands after it.
	 */
	void setSessionNote(long account, String sessionId, String note)
	{
		if (sessionId == null || tracker.setNote(sessionId, note))
		{
			return;
		}
		clientThread.invokeLater(() -> editRecordNote(account, sessionId, note));
	}

	/**
	 * Sets the setup overrides (cannon, style, gear; each {@code null} to clear it) of the session the panel's setup
	 * toggles belong to ({@link SessionTracker#setSetupOverrides}). If that session has ended and was handed off for saving
	 * meanwhile, they are written to its saved record instead, through the client thread as {@link #setSessionNote}
	 * does, so the record's save is queued first.
	 */
	void setSessionSetup(long account, String sessionId, SetupOverrides overrides)
	{
		if (sessionId == null || tracker.setSetupOverrides(sessionId, overrides))
		{
			return;
		}
		clientThread.invokeLater(() -> editRecordSetup(account, sessionId, overrides));
	}

	/**
	 * Sets (or, with an empty note, clears) the note of a saved ledger record on the executor, then reloads the
	 * account's ledger and refreshes the panel, like {@link #deleteRecord}. A record that no longer exists is left
	 * alone. Never touches the active (in-progress) session or its file.
	 */
	void editRecordNote(long account, String id, String note)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		final String normalized = TaskNote.normalize(note);
		executor.execute(() ->
		{
			boolean failed = false;
			try
			{
				store.updateNote(account, id, normalized);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to update the note of Slayer Ledger record", e);
				failed = true;
			}
			// Reload either way so the panel reflects what is actually on disk.
			reloadLedger(account);
			if (failed)
			{
				// Posted after the reload's update, so the refresh does not immediately clear it.
				publishHistoryError(account, SlayerLedgerPanel.EDIT_NOTE_FAILED_MESSAGE);
			}
		});
	}

	/**
	 * Sets (or, with an empty name, clears) the location name of a saved ledger record on the executor, then reloads
	 * the account's ledger and refreshes the panel, like {@link #editRecordNote}. Only that record's name changes: its
	 * spot, its region, the region's name and other records are kept, so it still groups with its spot's other
	 * tasks. Never touches the active session.
	 */
	void editRecordLocation(long account, String id, String location)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		final String normalized = TaskLocation.normalizeName(location);
		executor.execute(() ->
		{
			boolean failed = false;
			try
			{
				store.updateLocation(account, id, normalized);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to update the location of Slayer Ledger record", e);
				failed = true;
			}
			// Reload either way so the panel reflects what is actually on disk.
			reloadLedger(account);
			if (failed)
			{
				// Posted after the reload's update, so the refresh does not immediately clear it.
				publishHistoryError(account, SlayerLedgerPanel.EDIT_LOCATION_FAILED_MESSAGE);
			}
		});
	}

	/**
	 * Sets the player's setup overrides (cannon, style, gear; each {@code null} to clear it) of a saved ledger record on
	 * the executor, then reloads the account's ledger and refreshes the panel, like {@link #editRecordNote}. Only that
	 * record's overrides change: its detected tags and other records are kept. Never touches the active session (whose
	 * overrides are set through {@link #setSessionSetup}).
	 */
	void editRecordSetup(long account, String id, SetupOverrides overrides)
	{
		if (account == SessionTracker.NO_ACCOUNT || id == null)
		{
			return;
		}
		final SetupOverrides value = overrides == null ? SetupOverrides.NONE : overrides;
		executor.execute(() ->
		{
			boolean failed = false;
			try
			{
				store.updateSetup(account, id, value);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to update the setup of Slayer Ledger record", e);
				failed = true;
			}
			// Reload either way so the panel reflects what is actually on disk.
			reloadLedger(account);
			if (failed)
			{
				// Posted after the reload's update, so the refresh does not immediately clear it.
				publishHistoryError(account, SlayerLedgerPanel.EDIT_SETUP_FAILED_MESSAGE);
			}
		});
	}

	/** Any thread. Shows a non-modal error above the history list, guarded like {@link #publishRecords}. */
	private void publishHistoryError(long account, String message)
	{
		final SlayerLedgerPanel p = panel;
		if (p == null)
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (account == historyAccount)
			{
				p.showHistoryError(account, message);
			}
		});
	}

	// ---- Internals ----

	/**
	 * Stops the active session (if any) and handles it according to {@link SaveDecision}. May be called from the
	 * client thread or the EDT; the prompt and notice are always shown on the EDT and file IO runs on the executor.
	 *
	 * @return the pending file write, or {@code null} if nothing is being written yet
	 */
	private Future<?> endSession(SaveDecision.EndReason reason)
	{
		// Any completed session still held for late loot is saved first, as completed. Its write is not returned;
		// ClientShutdown waits for it separately via flushPendingCompletion.
		flushPendingCompletion();
		return handleEndedSession(tracker.stopAndReset(), reason);
	}

	/**
	 * Saves, as completed, a completed session still held for late loot (see {@link SessionTracker#holdCompletion()}),
	 * without waiting for the rest of its grace window. The tracker hands each held session out exactly once.
	 *
	 * @return the pending save, or {@code null} if no session was held
	 */
	private Future<?> flushPendingCompletion()
	{
		return handleEndedSession(tracker.takePendingCompletion(), SaveDecision.EndReason.SYSTEM);
	}

	private Future<?> handleEndedSession(SessionTracker.Summary summary, SaveDecision.EndReason reason)
	{
		if (summary == null)
		{
			return null;
		}
		final long account = summary.getAccountHash();
		final String sessionId = summary.getSessionId();
		switch (SaveDecision.decide(summary, reason, config.confirmIncomplete()))
		{
			case SAVE_COMPLETED:
			{
				final LedgerRecord record = LedgerRecord.fromSummary(summary, false);
				final LootPriceMode mode = lootPriceMode;
				return saveRecord(account, record, () -> announceCompletedTask(account, record, mode));
			}
			case SAVE_PARTIAL:
				return saveRecord(account, LedgerRecord.fromSummary(summary, true), null);
			case SAVE_PARTIAL_WITH_NOTICE:
			{
				final LedgerRecord record = LedgerRecord.fromSummary(summary, true);
				final SlayerLedgerPanel noticePanel = panel;
				// The notice is posted only after the append succeeds, so a failed save never claims "saved"; and only
				// while that account is still the one logged in (an account switch clears it, see checkAccount).
				return saveRecord(account, record, noticePanel == null ? null
					: () -> SwingUtilities.invokeLater(() ->
					{
						if (account == accountHash)
						{
							noticePanel.showPartialNotice(account, record);
						}
					}));
			}
			case PERSIST_ACTIVE:
				return persistActive(summary);
			case PROMPT:
			{
				final SlayerLedgerPanel promptPanel = panel;
				final BiPredicate<SlayerLedgerPanel, SessionTracker.Summary> dialog = keepIncompleteDialog;
				pendingPrompt.set(summary);
				SwingUtilities.invokeLater(() ->
				{
					boolean keep = promptPanel == null || dialog.test(promptPanel, summary);
					// If shutdown already saved the pending session, compareAndSet fails and nothing is saved twice.
					if (pendingPrompt.compareAndSet(summary, null))
					{
						if (keep)
						{
							saveRecord(account, LedgerRecord.fromSummary(summary, true), null);
						}
						else
						{
							deleteActive(account, sessionId);
						}
					}
				});
				return null;
			}
			case DISCARD:
			default:
				log.debug("Discarding session without a task or account");
				return deleteActive(account, sessionId);
		}
	}

	/**
	 * Any thread. Queues a completed task's chat lines after its ledger record has been appended successfully. First,
	 * on the EDT, the history model works out whether the task is a record-fast one
	 * ({@link LedgerHistoryModel#fastestTaskLine}, from the account's records, which the append's
	 * {@link #publishRecords} gave it before this runs); none without a model (the plugin is stopping) or once another
	 * account's history is shown. Then {@link #postCompletedTask} posts the lines.
	 */
	private void announceCompletedTask(long account, LedgerRecord record, LootPriceMode mode)
	{
		final LedgerHistoryModel m = historyModel;
		if (m == null)
		{
			postCompletedTask(record, mode, null);
			return;
		}
		SwingUtilities.invokeLater(() -> postCompletedTask(record, mode,
			account == historyAccount ? m.fastestTaskLine(account, record) : null));
	}

	/**
	 * Any thread. On the client thread, where the loot Ground Items hides is known: the task-complete line
	 * ({@link TaskCompleteMessage}, its "Task-complete line" setting) and its notification ("Task-complete
	 * notification", the same text, whether or not the line is on), then the record-fast task line
	 * ({@link FastestTaskMessage}) unless its "Record task line" setting is off. When the record line follows, the
	 * task-complete line leaves out its {@code Gz.}, so only one of them carries personality.
	 *
	 * @param fastestLine the record-fast task line as a chat message, or {@code null} when the task is no record
	 */
	private void postCompletedTask(LedgerRecord record, LootPriceMode mode, String fastestLine)
	{
		clientThread.invoke(() ->
		{
			final boolean fastest = fastestLine != null && config.recordTaskLine();
			final String line = TaskCompleteMessage.format(record, mode,
				hiddenLoot(record.getLoot() == null ? null : record.getLoot().keySet()), !fastest);
			if (line == null)
			{
				return;
			}
			if (config.taskCompleteLine())
			{
				postChatMessage(TaskCompleteMessage.chatMessage(record, line));
			}
			if (config.taskCompleteNotification())
			{
				notifier.notify(line);
			}
			if (fastest)
			{
				postChatMessage(fastestLine);
			}
		});
	}


	/**
	 * Client thread. Posts the plugin's plain-text chat line (waiting for the next kill) as a console message named
	 * "Slayer Ledger". The plain text is always escaped with {@link Text#escapeJagex}, so it can't add tags. The line is
	 * plain text with no markup of its own, so nothing is escaped twice. The other lines are built with
	 * {@link net.runelite.client.chat.ChatMessageBuilder} and posted with {@link #postChatMessage}.
	 */
	private void postChatLine(String text)
	{
		postChatMessage(Text.escapeJagex(text));
	}

	/**
	 * Client thread. Posts a chat message already in RuneLite's format (escaped plain text and
	 * {@link net.runelite.client.chat.ChatColorType} tags, as {@link net.runelite.client.chat.ChatMessageBuilder}
	 * builds it) as a console message named "Slayer Ledger".
	 */
	private void postChatMessage(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.name("Slayer Ledger")
			.runeLiteFormattedMessage(message)
			.build());
	}

	/**
	 * Saves, as partial, a session whose Keep/Discard dialog is still open (client exit or plugin shutdown).
	 *
	 * @return the pending save, or {@code null} if no dialog was pending
	 */
	private Future<?> savePendingPrompt()
	{
		return handleEndedSession(pendingPrompt.getAndSet(null), SaveDecision.EndReason.PROMPT_UNRESOLVED);
	}

	/**
	 * Writes the session as the account's active session file (on the executor). The session is not turned into a
	 * ledger record.
	 */
	private Future<?> persistActive(SessionTracker.Summary summary)
	{
		return persistActive(SessionSnapshot.fromSummary(summary, lastCompletionCounters, System.currentTimeMillis()));
	}

	private Future<?> persistActive(SessionSnapshot snapshot)
	{
		final long account = snapshot.getAccountHash();
		return executor.submit(() ->
		{
			try
			{
				store.writeActive(account, snapshot);
				log.debug("Persisted active Slayer Ledger session {}", snapshot.getSessionId());
			}
			catch (IOException e)
			{
				log.warn("Unable to persist the active Slayer Ledger session", e);
			}
		});
	}

	/**
	 * Client thread. On logout the in-memory session is kept (and Logged out) but a copy is persisted in case the
	 * client is closed before the next login. Without a session, an Ended assignment's marker is persisted instead.
	 */
	private void persistOnLogout()
	{
		final SessionTracker.Summary summary = tracker.activeSummary();
		if (summary != null
			&& SaveDecision.decide(summary, SaveDecision.EndReason.LOGOUT, config.confirmIncomplete())
			== SaveDecision.Action.PERSIST_ACTIVE)
		{
			logoutSnapshot = SessionSnapshot.fromSummary(summary, lastCompletionCounters, System.currentTimeMillis());
			persistActive(logoutSnapshot);
		}
		else
		{
			logoutSnapshot = null;
			if (summary == null)
			{
				persistEndedMarker();
			}
		}
	}

	/**
	 * Any thread. Persists the Ended assignment's marker ({@link SessionTracker#endedMarker}) as the account's active
	 * session file, so the assignment stays Ended after a client restart; it never becomes a record. Only while no
	 * session is active (End task ended it), so it never replaces a session's file.
	 *
	 * @return the pending write, or {@code null} when nothing is Ended
	 */
	private Future<?> persistEndedMarker()
	{
		if (tracker.getState().isActive())
		{
			return null;
		}
		final SessionSnapshot marker = tracker.endedMarker(lastCompletionCounters, System.currentTimeMillis());
		return marker == null ? null : persistActive(marker);
	}

	/**
	 * Captures the record's item prices on the client thread (prices are recorded as of the save), then appends it on
	 * the executor and removes the account's active session file if it holds the same session. Its spot was decided
	 * with the record ({@link LedgerRecord#fromSummary}); no location name is saved. {@code onSaved}, if given,
	 * runs on the executor after a successful append. If pricing fails the record is saved without values.
	 *
	 * @return completes when the write has finished (or failed)
	 */
	private Future<?> saveRecord(long account, LedgerRecord record, Runnable onSaved)
	{
		final CompletableFuture<Void> done = new CompletableFuture<>();
		// Runs immediately when already on the client thread. The client thread keeps running while ClientShutdown
		// consumers are awaited, so this also completes on client exit.
		clientThread.invoke(() ->
		{
			try
			{
				record.captureValues(lookups.priceLookup());
			}
			catch (RuntimeException e)
			{
				log.warn("Unable to price Slayer Ledger record {}", record.getId(), e);
			}
			finally
			{
				try
				{
					executor.execute(() ->
					{
						try
						{
							writeRecord(account, record, onSaved);
						}
						finally
						{
							done.complete(null);
						}
					});
				}
				catch (RejectedExecutionException e)
				{
					log.warn("Unable to save Slayer Ledger record {}", record.getId(), e);
					done.completeExceptionally(e);
				}
			}
		});
		return done;
	}

	/**
	 * Executor. Appends the record and removes the matching active session file, then saves any records kept by
	 * earlier failed saves. If the append fails, the record is kept in a side file for the next save or ledger load
	 * ({@link LedgerStore#writeUnsaved}) and the panel shows {@link SlayerLedgerPanel#SAVE_FAILED_MESSAGE}.
	 */
	private void writeRecord(long account, LedgerRecord record, Runnable onSaved)
	{
		List<LedgerRecord> updatedRecords;
		try
		{
			updatedRecords = store.append(account, record);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to save Slayer Ledger record {}; keeping it to save later", record.getId(), e);
			boolean keptRecord = false;
			try
			{
				store.writeUnsaved(account, record);
				keptRecord = true;
			}
			catch (IOException | RuntimeException keepFailure)
			{
				log.warn("Unable to keep unsaved Slayer Ledger record {}", record.getId(), keepFailure);
			}
			if (keptRecord)
			{
				// A stale active file of this session (from a logout mid-task) must not become a second, partial
				// record of it; readActive also ignores a session that is kept.
				try
				{
					store.deleteActive(account, record.getId());
				}
				catch (IOException | RuntimeException deleteFailure)
				{
					log.warn("Unable to remove the active session of kept Slayer Ledger record {}",
						record.getId(), deleteFailure);
				}
			}
			publishHistoryError(account, SlayerLedgerPanel.SAVE_FAILED_MESSAGE);
			return;
		}

		final KeptRecords kept = saveKeptRecords(account);
		if (kept.records != null)
		{
			updatedRecords = kept.records;
		}

		try
		{
			publishRecords(account, updatedRecords);
		}
		catch (RuntimeException e)
		{
			log.warn("Unable to publish saved Slayer Ledger records for account {}", account, e);
		}
		if (kept.failed)
		{
			// Posted after the records' update, so the refresh does not immediately clear it.
			publishHistoryError(account, SlayerLedgerPanel.SAVE_FAILED_MESSAGE);
		}
		// After the append: a crash in between leaves an active file whose id is already in the ledger,
		// which readActive detects and removes instead of restoring it.
		try
		{
			store.deleteActive(account, record.getId());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to remove saved Slayer Ledger active session {}", record.getId(), e);
		}
		// A partial notice for an earlier session stays until a later session is saved: this one.
		final SlayerLedgerPanel savedPanel = panel;
		if (savedPanel != null)
		{
			SwingUtilities.invokeLater(() -> savedPanel.sessionSaved(record.getId()));
		}
		if (onSaved != null)
		{
			try
			{
				onSaved.run();
			}
			catch (RuntimeException e)
			{
				log.warn("Unable to run post-save action for Slayer Ledger record {}", record.getId(), e);
			}
		}
	}

	/**
	 * Executor. Appends the records kept by earlier failed saves ({@link LedgerStore#appendUnsaved}). Their post-save
	 * actions (the task-complete chat line) are not run: the task ended earlier.
	 */
	private KeptRecords saveKeptRecords(long account)
	{
		try
		{
			return new KeptRecords(store.appendUnsaved(account), false);
		}
		catch (LedgerStore.UnsavedRecordsException e)
		{
			log.warn("Unable to save kept Slayer Ledger records; keeping them for the next try", e);
			// Any kept records saved before the failure are in the ledger; show them.
			return new KeptRecords(e.getRecords(), true);
		}
		catch (IOException | RuntimeException e)
		{
			// The side files could not be listed (for example no ledger directory), so none are known to be waiting.
			log.warn("Unable to check for kept Slayer Ledger records", e);
			return new KeptRecords(null, false);
		}
	}

	/** The result of {@link #saveKeptRecords}. */
	@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class KeptRecords
	{
		/** The updated record list, or {@code null} if no kept record was saved. */
		final List<LedgerRecord> records;
		/** Whether a kept record could not be saved and is still waiting. */
		final boolean failed;
	}

	private Future<?> deleteActive(long account, String sessionId)
	{
		if (account == SessionTracker.NO_ACCOUNT || sessionId == null)
		{
			return null;
		}
		return executor.submit(() ->
		{
			try
			{
				store.deleteActive(account, sessionId);
			}
			catch (IOException e)
			{
				log.warn("Unable to delete the active Slayer Ledger session", e);
			}
		});
	}

	/** Any thread. Deletes the account's Ended marker, if its active session file holds one, on the executor. */
	private Future<?> deleteEndedMarker(long account)
	{
		if (account == SessionTracker.NO_ACCOUNT)
		{
			return null;
		}
		return executor.submit(() ->
		{
			try
			{
				store.deleteEndedMarker(account);
			}
			catch (IOException e)
			{
				log.warn("Unable to delete the Ended Slayer Ledger assignment's marker", e);
			}
		});
	}

	/**
	 * Client thread. Loads the account's active session file on the executor, then applies it on the client thread.
	 */
	private void loadActiveSession(long account)
	{
		final int generation = ++loadGeneration;
		executor.execute(() ->
		{
			SessionSnapshot snapshot = null;
			try
			{
				snapshot = store.readActive(account);
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("Unable to read the active Slayer Ledger session", e);
			}
			finally
			{
				// Always hand back to the client thread so restorePending is cleared.
				final SessionSnapshot loaded = snapshot;
				clientThread.invokeLater(() -> applyActiveSession(account, loaded, generation));
			}
		});
	}

	/**
	 * Client thread. Restores a loaded active session as Logged out (the next task kill restarts it) if the task still
	 * matches, otherwise saves it as a partial record with the Discard notice. An Ended assignment's marker restores
	 * only the Ended flag, and is deleted either way once read: it never becomes a record.
	 */
	private void applyActiveSession(long account, SessionSnapshot snapshot, int generation)
	{
		if (generation != loadGeneration)
		{
			// Superseded by a newer load (or cancelled by logout); that one owns restorePending.
			return;
		}
		try
		{
			if (snapshot == null || account != accountHash)
			{
				// Nothing to restore, or another account logged in meanwhile (the file stays for later).
				return;
			}
			if (!tracker.isTaskObserved())
			{
				// Logged out (or switched) before this ran; try again after the next settled observation.
				restoreCheckNeeded = true;
				return;
			}
			final SessionTracker.Summary active = tracker.activeSummary();
			if (active != null && snapshot.getSessionId() != null && snapshot.getSessionId().equals(active.getSessionId()))
			{
				// Already in memory (e.g. a stale load after a quick plugin restart); never turn it into a record too.
				return;
			}
			// The file is per account; it is authoritative for which account the session belongs to.
			snapshot.setAccountHash(account);
			if (snapshot.isEndedMarker())
			{
				applyEndedMarker(account, snapshot);
				return;
			}
			switch (tracker.restore(snapshot, lastCompletionCounters))
			{
				case RESTORED:
					log.debug("Restored Slayer Ledger session {}", snapshot.getSessionId());
					break;
				case REFUSED:
					// A session is active in memory; keep the file and check again after the next login.
					restoreCheckNeeded = true;
					return;
				case MISMATCH:
				default:
					log.debug("Active Slayer Ledger session {} does not match the current task", snapshot.getSessionId());
					// Its spot is decided with the table, as for a live session.
					handleEndedSession(snapshot.toSummary(spots), SaveDecision.EndReason.RESTORE_MISMATCH);
					break;
			}
		}
		finally
		{
			restorePending = false;
			// Applied after the tick's own live check: a session it restored (or ended) is told to the history model
			// now, not on the next tick, so its live checks see it whatever the EDT ran first.
			refreshHistoryModelIfLiveChanged();
		}
	}

	/**
	 * Client thread. An Ended assignment's marker: the assignment stays Ended when it is still the current one
	 * ({@link SessionTracker#restoreEnded}); the marker is deleted either way (the next logout writes a new one while it
	 * is Ended), unless the check must wait for a session in memory.
	 */
	private void applyEndedMarker(long account, SessionSnapshot marker)
	{
		final SessionTracker.RestoreResult result = tracker.restoreEnded(marker, lastCompletionCounters);
		if (result == SessionTracker.RestoreResult.REFUSED)
		{
			// A session is active in memory; keep the file and check again after the next login.
			restoreCheckNeeded = true;
			return;
		}
		log.debug("Ended Slayer Ledger assignment {}: {}", marker.getSessionId(), result);
		deleteActive(account, marker.getSessionId());
	}

	/** Loads the account's ledger on the executor and shows it in the panel. */
	private void loadLedger(long account)
	{
		executor.execute(() -> reloadLedger(account));
	}

	/**
	 * Executor. Saves the records kept by earlier failed saves, then reads the account's ledger and shows it in the
	 * panel, or a load-failure message; while a kept record still cannot be saved, the save-failed message too.
	 */
	private void reloadLedger(long account)
	{
		final boolean keptRecordsFailed = saveKeptRecords(account).failed;
		try
		{
			final LedgerStore.Contents contents = store.loadContents(account);
			publishRecords(account, contents.getRecords());
			publishAssignments(account, contents.getAssignments());
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Unable to load Slayer Ledger records", e);
			publishHistoryMessage(account, SlayerLedgerPanel.LOAD_FAILED_MESSAGE);
		}
		if (keptRecordsFailed)
		{
			// Posted after the history's update, so the refresh does not immediately clear it.
			publishHistoryError(account, SlayerLedgerPanel.SAVE_FAILED_MESSAGE);
		}
	}

	/**
	 * Any thread. Gives the history model (which the panel shows) an account's records on the EDT, but only if that
	 * account's history is still the one to show when the update runs; results for a previous account or a
	 * logged-out client are dropped.
	 */
	private void publishRecords(long account, List<LedgerRecord> records)
	{
		final LedgerHistoryModel m = historyModel;
		if (m == null)
		{
			return;
		}
		final List<LedgerRecord> copy = new ArrayList<>(records);
		SwingUtilities.invokeLater(() ->
		{
			if (account == historyAccount)
			{
				m.setRecords(account, copy);
			}
		});
	}

	/**
	 * Any thread. Gives the history model an account's entries for the panel's "Skipped / blocked" section, guarded
	 * like {@link #publishRecords}. Entries never go to the played-task history.
	 */
	private void publishAssignments(long account, List<AssignmentEntry> entries)
	{
		final LedgerHistoryModel m = historyModel;
		if (m == null)
		{
			return;
		}
		final List<AssignmentEntry> copy = new ArrayList<>(entries);
		SwingUtilities.invokeLater(() ->
		{
			if (account == historyAccount)
			{
				m.setAssignments(account, copy);
			}
		});
	}

	/** Any thread. Like {@link #publishRecords} but replaces the history with a message. */
	private void publishHistoryMessage(long account, String message)
	{
		final LedgerHistoryModel m = historyModel;
		if (m == null)
		{
			return;
		}
		SwingUtilities.invokeLater(() ->
		{
			if (account == historyAccount)
			{
				m.clearRecords(account, message);
			}
		});
	}

	/**
	 * Client thread. Changes whose history the panel shows, clearing it at once (so another account's rows are never
	 * left on screen), and loads the new account's ledger.
	 */
	private void setHistoryAccount(long account)
	{
		if (account == historyAccount)
		{
			return;
		}
		historyAccount = account;
		if (account == SessionTracker.NO_ACCOUNT)
		{
			publishHistoryMessage(account, SlayerLedgerPanel.LOGGED_OUT_MESSAGE);
		}
		else
		{
			publishHistoryMessage(account, SlayerLedgerPanel.LOADING_MESSAGE);
			loadLedger(account);
		}
	}

	/**
	 * Client thread. Detects account changes, persists sessions that belong to another account and loads the
	 * ledger.
	 */
	private void checkAccount()
	{
		final long hash = client.getAccountHash();
		// Also covers re-login to the same account, whose history was hidden at the login screen.
		setHistoryAccount(hash);
		if (hash == accountHash)
		{
			return;
		}
		accountHash = hash;
		tracker.setAccount(hash);
		tracker.clearCurrentTask();
		// A partial notice of the previous account's session is not this account's to Discard.
		final SlayerLedgerPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.accountChanged(hash));
		}
		// The XP read so far was the previous account's.
		resetXpBaseline();
		// So was the blowpipe.
		blowpipeContents.forget();
		// The watched assignment belonged to the previous account.
		assignmentWatch.forget();
		cancelPendingRestore();
		restoreCheckNeeded = true;
		// A completed session held for late loot is saved under its own account, as completed.
		flushPendingCompletion();
		// Another account's session is persisted as that account's active session, not saved as partial.
		handleEndedSession(tracker.stopAndResetIfOtherAccount(hash), SaveDecision.EndReason.ACCOUNT_SWITCH);
		// The region names were the previous account's: an account with no RuneScape profile yet posts no profile
		// change. Forgotten after the saves above (named on this thread, as they ran), so those still get their names.
		forgetLocationNames();
	}

	/**
	 * Client thread, every settled tick. Reads every skill's XP ({@code Client#getSkillExperience}, as core
	 * XpTrackerPlugin reads it) into a reused array and gives it to the tracker ({@link SessionTracker#observeXp}),
	 * keyed by the {@link Skill} constant's name for {@link SkillXp}; {@code null} while the stats are not synced
	 * (Hitpoints XP reads 0, which no synced account has: Hitpoints starts at level 10). A reading equal to the last one
	 * the tracker got is not passed again: the tracker would find no gain and keep an equal baseline, so only
	 * ticks with an XP change build a map. {@link #resetXpBaseline} keeps this in step with the tracker's baseline.
	 */
	private void observeSkillXp()
	{
		if (client.getSkillExperience(Skill.HITPOINTS) <= 0)
		{
			xpSent = false;
			tracker.observeXp(null);
			return;
		}
		for (int i = 0; i < SKILLS.length; i++)
		{
			xpReading[i] = client.getSkillExperience(SKILLS[i]);
		}
		if (xpSent && Arrays.equals(xpReading, xpLastSent))
		{
			return;
		}
		final Map<String, Integer> xp = new HashMap<>();
		for (int i = 0; i < SKILLS.length; i++)
		{
			xp.put(SKILLS[i].name(), xpReading[i]);
		}
		tracker.observeXp(xp);
		System.arraycopy(xpReading, 0, xpLastSent, 0, SKILLS.length);
		xpSent = true;
	}

	/**
	 * Client thread. Drops the tracker's XP baseline ({@link SessionTracker#resetXpBaseline}), so the next settled
	 * reading is only a baseline, and makes {@link #observeSkillXp} pass that reading even if it equals the last one.
	 */
	private void resetXpBaseline()
	{
		tracker.resetXpBaseline();
		xpSent = false;
	}

	private void resetClientState()
	{
		completionSignal.reset();
		// Shown again from the next settled reading; the counter it is for is kept across a hop.
		currentTaskStreak = null;
		// The stats are re-sent after (re)login or a hop: the next settled reading is only a baseline.
		resetXpBaseline();
		taskRewards.reset();
		// Drops an undecided end; the next reading is a baseline. The current assignment is kept (not ended by logout).
		assignmentWatch.reset();
		settleTicks = LOGIN_SETTLE_TICKS;
		// Containers are re-sent after (re)login or a hop; start supplies from a fresh baseline.
		if (supplyTracker != null)
		{
			supplyTracker.reset();
		}
		// Includes the plugin starting while logged in, when no ItemContainerChanged comes for the current inventory.
		inventoryNoteTries = INVENTORY_NOTE_TRIES;
		supplyExclusions.reset();
		skippedSupplyTicks.reset();
		chargedWeaponUsage.reset();
		chargeExclusions.reset();
		// NPC indexes are re-sent after (re)login or a hop; the deaths kept for pairing go with them, and so do the
		// attacks, cannon shots, hits and kills their styles and contexts would come from.
		damagedNpcs.clear();
		playerAttacks.clear();
		cannonFire.reset();
		hitNpcNames.clear();
		killContextsDue = null;
		pairKillAt = SessionTracker.NO_TIME;
		// The first settled reading after it is a baseline, never a drop.
		zeroDropTick = NO_TICK;
		lastRemainingRead = -1;
		slaughterKillPending = false;
		heldSuperiorSpawns = 0;
		// Hidden after a login or hop, and in step with a new panel (startUp), which starts with it hidden.
		publishDartHint(false);
		sessionValueTick = SupplyExclusions.NEVER_TICK;
		// A paused session is valued once more after a login or hop, as on its first tick.
		pausedValuesSession = null;
	}

	/**
	 * Client thread. Assigned task size as computed by core SlayerPlugin (1.13.3): SLAYER_COUNT_ORIGINAL adjusted by
	 * an amount modifier when SLAYER_MODIFIER_ID is 2.
	 */
	private int readOriginalAmount()
	{
		int amount = client.getVarpValue(VarPlayerID.SLAYER_COUNT_ORIGINAL);
		if (client.getVarbitValue(VarbitID.SLAYER_MODIFIER_ID) == AMOUNT_MODIFIER_ID)
		{
			boolean negative = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_NEGATIVE) == 1;
			int value = client.getVarbitValue(VarbitID.SLAYER_MODIFIER_VALUE);
			amount += negative ? -value : value;
		}
		return amount > 0 ? amount : SessionTracker.UNKNOWN_AMOUNT;
	}

	/**
	 * Client thread. Who assigned the current task: the SLAYER_MASTER varbit and the SLAYER_AREA varp (Konar's
	 * location), with the area named from the SlayerArea DB table as core SlayerPlugin does (1.13.4).
	 */
	private TaskContext readAssignment()
	{
		final int master = client.getVarbitValue(VarbitID.SLAYER_MASTER);
		final int area = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		return TaskContext.assignment(master, area, area > 0 ? dbLookups.lookupAreaName(area) : null);
	}
}

package com.shmayvan.slayerledger;

/**
 * Names of the Slayer masters by the game's SLAYER_MASTER varbit value (4067), which says which master assigned the
 * current task. Pure; no RuneLite types.
 *
 * <p>The values come from the OSRS wiki's page for varbit 4067 ("RuneScape:Varbit/4067", read 2026-10-26). Core
 * RuneLite SlayerPlugin (1.13.4) uses the same values for Krystilia (7) and Mortimer (10) to pick the task streak.
 * Some values are shared by two masters that assign the same tasks (Turael and Aya, for example), so the name shows
 * both. A value not in the table shows as "Unknown master (n)", never as a guessed name.</p>
 */
final class SlayerMaster
{
	/** SLAYER_MASTER value when no task has been assigned (and the value before it has synced). */
	static final int NONE = 0;
	static final int KRYSTILIA = 7;
	static final int KONAR = 8;
	static final int MORTIMER = 10;

	/** Names by SLAYER_MASTER value; index 0 (no task) has none. */
	private static final String[] NAMES = {
		null,
		"Turael/Aya",
		"Mazchna",
		"Vannaka",
		"Chaeldar",
		"Duradel/Kuradal",
		"Nieve/Steve",
		"Krystilia",
		"Konar",
		"Spria",
		"Mortimer",
	};

	private SlayerMaster()
	{
	}

	/** Whether {@code master} names a master: a known (non-{@code null}) value other than {@link #NONE}. */
	static boolean isKnown(Integer master)
	{
		return master != null && master != NONE;
	}

	/**
	 * The master's name, "Unknown master (n)" for a value not in the table, or {@code null} when no master is known
	 * ({@code null} or {@link #NONE}).
	 */
	static String displayName(Integer master)
	{
		if (!isKnown(master))
		{
			return null;
		}
		if (master > 0 && master < NAMES.length)
		{
			return NAMES[master];
		}
		return "Unknown master (" + master + ")";
	}

	/** Whether the value is in the name table (so {@link #displayName} is a real name). */
	static boolean hasName(Integer master)
	{
		return isKnown(master) && master > 0 && master < NAMES.length;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.*;
import com.google.gson.annotations.*;
import java.io.*;
import java.nio.charset.*;
import java.util.*;
import lombok.*;
import lombok.extern.slf4j.*;

/**
 * The bundled Slayer spot table (V2 plan 4.5): each named Slayer spot's stable id, its full and short names, the
 * map regions it covers (with the plane or bounds that decide a region it shares with other spots) and the tasks done
 * there. It names a task's location from where its kills happened. An instance holds one validated snapshot
 * ({@link #load}); the lookups are pure (no RuneLite types) and the instance is immutable, so any thread may use it.
 *
 * <p><b>Spot keys.</b> A spot is keyed by its table id ({@code catacombs-of-kourend}) or, for a map region the table
 * doesn't list, by {@link #regionKey} ({@code region:7238}): an unlisted region is a spot of its own. {@code null} is
 * the Unknown spot. While the table is unavailable ({@link #NONE}: missing or invalid), listed and unlisted regions
 * can't be told apart, so no key is given at all.</p>
 *
 * <p><b>Matching</b> (the table's {@code matching} rule): a point's region is
 * {@code ((x >> 6) << 8) | (y >> 6)}, as {@code WorldPoint.getRegionID()} gives it. A region listed by one spot
 * belongs to that spot on every plane. In a region listed by several spots, a spot matches only if its {@code plane} is
 * {@code null} or the point's plane, and its {@code bounds} are {@code null} or one inclusive {@code [x1, y1, x2, y2]}
 * box contains the point; plane and bounds are used only in such shared regions.</p>
 *
 * <p><b>Data and licence.</b> Adapted from the Old School RuneScape Wiki by Old School RuneScape Wiki contributors,
 * under CC BY-NC-SA 3.0 (the file's {@code attribution}; each spot lists the Wiki revisions it was read from).
 * {@code mejrs/data_osrs} was used to verify the coordinates and translate relocated Wiki map pins, and a few region ids
 * were derived from it (the file's {@code verifiedWith}; the spots that rest on it cite it); none of its records are
 * copied. The README credits both.</p>
 */
@Slf4j
final class SlayerSpots
{
	/** The bundled snapshot, relative to this class. */
	static final String SNAPSHOT_RESOURCE = "slayer-spots.json";
	/** The only snapshot schema version this build reads. */
	static final int SNAPSHOT_VERSION = 1;
	/** The longest short name ({@link Spot#getShortName}), in characters. */
	static final int MAX_SHORT_NAME_LENGTH = 15;
	/** Prefix of an unlisted region's spot key ({@link #regionKey}). */
	static final String REGION_PREFIX = "region:";
	/** The table when the bundled one could not be read: no spots, and no key is ever given. */
	static final SlayerSpots NONE = new SlayerSpots();

	private final Snapshot snapshot;
	/** Spots by id. */
	private final Map<String, Spot> byId;
	/** The spots listing each region, in table order. */
	private final Map<Integer, List<Spot>> byRegion;
	/** The ids of the spots with each full or short name, by {@link TaskLocation#matchKey}. */
	private final Map<String, Set<String>> byName;
	/** Unmodifiable, in table order. */
	private final List<Spot> spots;

	private SlayerSpots()
	{
		snapshot = null;
		byId = Collections.emptyMap();
		byRegion = Collections.emptyMap();
		byName = Collections.emptyMap();
		spots = Collections.emptyList();
	}

	private SlayerSpots(Snapshot snapshot)
	{
		this.snapshot = snapshot;
		Map<String, Spot> ids = new HashMap<>();
		Map<Integer, List<Spot>> regions = new HashMap<>();
		Map<String, Set<String>> names = new HashMap<>();
		for (Spot spot : snapshot.spots)
		{
			spot.taskKeys = new HashSet<>();
			for (String task : spot.tasks)
			{
				spot.taskKeys.add(TaskStatistics.normalize(task));
			}
			ids.put(spot.id, spot);
			for (int region : spot.regions)
			{
				regions.computeIfAbsent(region, r -> new ArrayList<>()).add(spot);
			}
			for (String name : new String[]{spot.name, spot.shortName})
			{
				names.computeIfAbsent(TaskLocation.matchKey(name), n -> new HashSet<>()).add(spot.id);
			}
		}
		byId = ids;
		byRegion = regions;
		byName = names;
		spots = Collections.unmodifiableList(new ArrayList<>(snapshot.spots));
	}

	/**
	 * Reads and validates the snapshot {@code resource} (relative to this class) with {@code gson}, the client's
	 * injected instance. Returns {@link #NONE}, logged at debug level, when the resource is missing, unreadable,
	 * malformed or invalid, so bad data never breaks the plugin.
	 */
	static SlayerSpots load(Gson gson, String resource)
	{
		if (gson == null)
		{
			return NONE;
		}
		try (InputStream stream = SlayerSpots.class.getResourceAsStream(resource))
		{
			if (stream == null)
			{
				log.debug("Slayer spots {} are missing", resource);
				return NONE;
			}
			return parse(gson, new InputStreamReader(stream, StandardCharsets.UTF_8));
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Unable to load the Slayer spots {}", resource, e);
			return NONE;
		}
	}

	/** Parses and validates a snapshot. Throws a {@link RuntimeException} when it is malformed or invalid. */
	static SlayerSpots parse(Gson gson, Reader reader)
	{
		Snapshot snapshot = gson.fromJson(reader, Snapshot.class);
		validate(snapshot);
		return new SlayerSpots(snapshot);
	}

	/** Whether the table was read; {@code false} for {@link #NONE}. */
	boolean isAvailable()
	{
		return snapshot != null;
	}

	/** Every spot, in table order. Unmodifiable. */
	List<Spot> spots()
	{
		return spots;
	}

	/** The spot with table id {@code id}, or {@code null} (an unlisted region's key, an unknown id, {@code null}). */
	Spot spot(String id)
	{
		return id == null ? null : byId.get(id);
	}

	/** The spots listing {@code region}, in table order. Unmodifiable; empty when it is unlisted. */
	List<Spot> spotsInRegion(int region)
	{
		List<Spot> listed = byRegion.get(region);
		return listed == null ? Collections.emptyList() : Collections.unmodifiableList(listed);
	}

	/** The map region of tile {@code (x, y)}, as {@code WorldPoint.getRegionID()} gives it. */
	static int regionOf(int x, int y)
	{
		return ((x >> 6) << 8) | (y >> 6);
	}

	/** The spot key of unlisted region {@code region}: {@code region:N}. */
	static String regionKey(int region)
	{
		return REGION_PREFIX + region;
	}

	/** The region of an unlisted region's spot key ({@link #regionKey}), or {@code null} for any other key. */
	static Integer keyRegion(String spotKey)
	{
		if (spotKey == null || !spotKey.startsWith(REGION_PREFIX))
		{
			return null;
		}
		try
		{
			int region = Integer.parseInt(spotKey.substring(REGION_PREFIX.length()));
			return LocationTally.isRegion(region) ? region : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * The spot of a kill at tile {@code (x, y)} on {@code plane} (instances as their template tile), by the table's
	 * matching rule: the spot listing its region, or in a shared region the one whose plane and bounds match; an
	 * unlisted region's key ({@link #regionKey}) when no spot lists it.
	 *
	 * @return the spot key, or {@code null} when no spot of a shared region matches or the table is unavailable
	 */
	String spotAt(int x, int y, int plane)
	{
		if (!isAvailable())
		{
			return null;
		}
		final int region = regionOf(x, y);
		final List<Spot> listed = byRegion.get(region);
		if (listed == null)
		{
			return regionKey(region);
		}
		if (listed.size() == 1)
		{
			return listed.get(0).id;
		}
		for (Spot spot : listed)
		{
			if (spot.matches(x, y, plane))
			{
				return spot.id;
			}
		}
		return null;
	}

	/**
	 * The spot of map region {@code region} when only the region is known (a record saved before spots, or a kill
	 * tallied by region alone), for a task of {@code task}: the spot listing it; in a region shared by several spots the
	 * one shared spot whose tasks include {@code task}; an unlisted region's key ({@link #regionKey}) when no spot lists
	 * it.
	 *
	 * @param region the map region, or {@code null}
	 * @param task   the task's name (matched by {@link TaskStatistics#normalize}), or {@code null}
	 * @return the spot key, or {@code null} (Unknown) for no region, a shared region that none or several of its spots'
	 * tasks decide, or an unavailable table
	 */
	String spotForRegion(Integer region, String task)
	{
		if (region == null || !LocationTally.isRegion(region) || !isAvailable())
		{
			return null;
		}
		final List<Spot> listed = byRegion.get(region);
		if (listed == null)
		{
			return regionKey(region);
		}
		if (listed.size() == 1)
		{
			return listed.get(0).id;
		}
		Spot found = null;
		for (Spot spot : listed)
		{
			if (spot.hasTask(task))
			{
				if (found != null)
				{
					return null;
				}
				found = spot;
			}
		}
		return found == null ? null : found.id;
	}

	/**
	 * A saved record's spot: its stored {@link LedgerRecord#getSpotId() spotId}, or for a record without one (saved
	 * before spots, V2 plan 4.5) the spot of its {@link LedgerRecord#getLocationRegion() locationRegion}
	 * ({@link #spotForRegion}, with its task). A stored id this table doesn't know ({@link #knows}: one a later table
	 * dropped or renamed) is treated as no id, so the record takes its region's spot. Worked out each time it is read;
	 * the file is not changed. While the table is unavailable ({@link #NONE}), a stored id is kept as it is.
	 *
	 * @return the spot key, or {@code null} (Unknown)
	 */
	String recordSpot(LedgerRecord record)
	{
		if (record == null)
		{
			return null;
		}
		final String stored = record.getSpotId() == null ? null : record.getSpotId().trim();
		if (stored != null && !stored.isEmpty() && (!isAvailable() || knows(stored)))
		{
			return stored;
		}
		return spotForRegion(record.getLocationRegion(), record.getMonster());
	}

	/**
	 * Whether {@code spotKey} is a spot of this table: one of its ids, or the key of a region it doesn't list. A
	 * {@code region:N} key of a region a later table lists is not known, so its task moves to that region's spot.
	 */
	boolean knows(String spotKey)
	{
		if (spot(spotKey) != null)
		{
			return true;
		}
		final Integer region = keyRegion(spotKey);
		return region != null && spotsInRegion(region).isEmpty();
	}

	/**
	 * The table's name of spot {@code spotKey} ("Catacombs of Kourend"), or {@code "Region N"} for an unlisted
	 * region's key.
	 *
	 * @return the name, or {@code null} for the Unknown spot or an id the table doesn't have
	 */
	String name(String spotKey)
	{
		final Integer region = keyRegion(spotKey);
		if (region != null)
		{
			return regionName(region);
		}
		final Spot spot = spot(spotKey);
		return spot == null ? null : spot.name;
	}

	/**
	 * The short name of spot {@code spotKey} for narrow places such as the overlay ("Catacombs"), at most
	 * {@link #MAX_SHORT_NAME_LENGTH} characters; {@code "Region N"} for an unlisted region's key.
	 *
	 * @return the short name, or {@code null} for the Unknown spot or an id the table doesn't have
	 */
	String shortName(String spotKey)
	{
		final Integer region = keyRegion(spotKey);
		if (region != null)
		{
			return regionName(region);
		}
		final Spot spot = spot(spotKey);
		return spot == null ? null : spot.shortName;
	}

	/**
	 * The spot the table calls {@code name} (its full or short name, compared as {@link TaskLocation#matchKey}
	 * compares names, so case and spacing don't matter), for a place known only by name, such as Konar's assigned area.
	 *
	 * @return the spot's id, or {@code null} when no spot, or more than one, has that name
	 */
	String spotNamed(String name)
	{
		final Set<String> ids = byName.get(TaskLocation.matchKey(name));
		return ids == null || ids.size() != 1 ? null : ids.iterator().next();
	}

	/** How an unlisted region is named until the player names it: {@code Region 7238}. */
	static String regionName(int region)
	{
		return "Region " + region;
	}

	/** Whether spot {@code spotKey}'s task list includes {@code task}; never for an unlisted region or no spot. */
	boolean listsTask(String spotKey, String task)
	{
		final Spot spot = spot(spotKey);
		return spot != null && spot.hasTask(task);
	}

	/** Snapshot metadata, for attribution. {@code null} for {@link #NONE}. */
	String getRetrieved()
	{
		return snapshot == null ? null : snapshot.retrieved;
	}

	String getSource()
	{
		return snapshot == null ? null : snapshot.source;
	}

	String getLicense()
	{
		return snapshot == null ? null : snapshot.license;
	}

	String getAttribution()
	{
		return snapshot == null ? null : snapshot.attribution;
	}

	String getVerifiedWith()
	{
		return snapshot == null ? null : snapshot.verifiedWith;
	}

	private static void validate(Snapshot snapshot)
	{
		if (snapshot == null || snapshot.version != SNAPSHOT_VERSION || snapshot.spots == null
			|| snapshot.spots.isEmpty() || isBlank(snapshot.source) || isBlank(snapshot.license)
			|| isBlank(snapshot.licenseUrl) || isBlank(snapshot.contributors) || isBlank(snapshot.retrieved)
			|| isBlank(snapshot.attribution) || isBlank(snapshot.matching))
		{
			throw new IllegalStateException("Slayer spots metadata is missing or unsupported.");
		}
		Set<String> ids = new HashSet<>();
		for (Spot spot : snapshot.spots)
		{
			// No colon, so an id is never an unlisted region's key or another kind of key (HistoryFilter.NAME_PREFIX).
			if (spot == null || isBlank(spot.id) || !spot.id.equals(spot.id.trim()) || spot.id.indexOf(':') >= 0
				|| !ids.add(spot.id) || isBlank(spot.name) || isBlank(spot.shortName)
				|| spot.shortName.length() > MAX_SHORT_NAME_LENGTH)
			{
				throw new IllegalStateException("Slayer spots have an invalid or duplicate spot.");
			}
			if (spot.regions == null || spot.regions.isEmpty() || spot.tasks == null || spot.sources == null
				|| spot.sources.isEmpty() || (spot.plane != null && (spot.plane < 0 || spot.plane > 3)))
			{
				throw new IllegalStateException("Slayer spot " + spot.id + " has no regions, tasks or sources.");
			}
			for (Integer region : spot.regions)
			{
				if (region == null || !LocationTally.isRegion(region))
				{
					throw new IllegalStateException("Slayer spot " + spot.id + " has an invalid region.");
				}
			}
			for (String task : spot.tasks)
			{
				if (isBlank(task))
				{
					throw new IllegalStateException("Slayer spot " + spot.id + " has a blank task.");
				}
			}
			if (spot.bounds != null)
			{
				for (int[] box : spot.bounds)
				{
					if (box == null || box.length != 4 || box[0] > box[2] || box[1] > box[3])
					{
						throw new IllegalStateException("Slayer spot " + spot.id + " has an invalid bounds box.");
					}
				}
			}
		}
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	private static final class Snapshot
	{
		private int version;
		private String source;
		private String license;
		private String licenseUrl;
		private String contributors;
		private String retrieved;
		private String attribution;
		private String verifiedWith;
		private String matching;
		private List<Spot> spots;
	}

	/** One Slayer spot of the table. Read by Gson; never changed once loaded. */
	static final class Spot
	{
		/** The stable id, for example {@code catacombs-of-kourend}. */
		@Getter
		private String id;
		/** The full name, for example "Catacombs of Kourend". */
		@Getter
		private String name;
		/** The short name, at most {@link #MAX_SHORT_NAME_LENGTH} characters, for example "Catacombs". */
		@SerializedName("short")
		@Getter
		private String shortName;
		private List<Integer> regions;
		/** The plane that decides a shared region, or {@code null}. */
		@Getter
		private Integer plane;
		/** Inclusive {@code [x1, y1, x2, y2]} boxes that decide shared regions, or {@code null}. */
		private List<int[]> bounds;
		private List<String> tasks;
		private List<String> sources;
		/** {@code high}, {@code medium} or {@code low}. */
		@Getter
		private String confidence;
		/** {@link #tasks}, {@link TaskStatistics#normalize}d; set once when the table is built. */
		private transient Set<String> taskKeys;

		/** The regions, in table order. Unmodifiable. */
		List<Integer> getRegions()
		{
			return Collections.unmodifiableList(regions);
		}

		/** Copies of the bounds boxes, or an empty list when the spot has none. */
		List<int[]> getBounds()
		{
			List<int[]> copy = new ArrayList<>();
			if (bounds != null)
			{
				for (int[] box : bounds)
				{
					copy.add(box.clone());
				}
			}
			return copy;
		}

		/** The task names, as the table spells them. Unmodifiable. */
		List<String> getTasks()
		{
			return Collections.unmodifiableList(tasks);
		}

		/** The source URLs. Unmodifiable. */
		List<String> getSources()
		{
			return Collections.unmodifiableList(sources);
		}

		/** Whether the task list includes {@code task} (matched by {@link TaskStatistics#normalize}). */
		boolean hasTask(String task)
		{
			final String key = TaskStatistics.normalize(task);
			return key != null && taskKeys.contains(key);
		}

		/** Whether a point in a shared region is this spot's: its plane, if set, and one of its boxes, if any. */
		boolean matches(int x, int y, int pointPlane)
		{
			if (plane != null && plane != pointPlane)
			{
				return false;
			}
			if (bounds == null)
			{
				return true;
			}
			for (int[] box : bounds)
			{
				if (x >= box[0] && x <= box[2] && y >= box[1] && y <= box[3])
				{
					return true;
				}
			}
			return false;
		}
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import javax.swing.*;

/**
 * An item sprite drawn at the size of the sidebar's small icon slot ({@link ItemListView#ICON_WIDTH} by
 * {@link ItemListView#ICON_HEIGHT}, half the 36 by 32 item sprite), for the task icons of Overall totals, so a
 * line with one is no taller or wider than an XP list's skill line. The sprite comes through the item grids' path
 * ({@link ItemIcons}, RuneLite's {@code ItemManager.getImage}, on the EDT) and is scaled as it is painted, so a sprite
 * that arrives later is drawn when the label repaints, as {@link ItemIcons#apply} promises. {@link #getImage()} is the
 * full sprite. Now the task icons also show in Task history and Skipped / blocked ({@link #applyTask}), and
 * the setup tags' game images on the Task history rows ({@link #applyTag}), each in a
 * {@link #TAG_SIZE} square as the overlay draws them. The image keeps its shape, centred in its box. EDT only.
 */
final class SmallItemIcon extends ImageIcon
{
	/** The side of a setup tag's square icon box: the overlay's ({@link OverlayRows#TAG_SIZE}). */
	static final int TAG_SIZE = OverlayRows.TAG_SIZE;

	/** An empty slot of the same size, for a task without a known icon, so the names stay aligned. */
	static final Icon EMPTY = empty(ItemListView.ICON_WIDTH, ItemListView.ICON_HEIGHT);

	/** An empty tag box, for a tag whose icon could not be had, so the boxes stay the same size. */
	static final Icon EMPTY_TAG = empty(TAG_SIZE, TAG_SIZE);

	private final int width;
	private final int height;

	private SmallItemIcon(Image image, int width, int height)
	{
		super(image);
		this.width = width;
		this.height = height;
	}

	/** An icon that draws nothing, {@code width} by {@code height}. */
	private static Icon empty(int width, int height)
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics g, int x, int y)
			{
			}

			@Override
			public int getIconWidth()
			{
				return width;
			}

			@Override
			public int getIconHeight()
			{
				return height;
			}
		};
	}

	/**
	 * Puts {@code itemId}'s sprite on {@code label} at the small slot size, through {@code icons}; {@link #EMPTY} when
	 * {@code icons} puts no image on it.
	 */
	static void apply(ItemIcons icons, JLabel label, int itemId)
	{
		label.setIcon(null);
		icons.apply(label, itemId, 1);
		Icon full = label.getIcon();
		label.setIcon(full instanceof ImageIcon
			? new SmallItemIcon(((ImageIcon) full).getImage(), ItemListView.ICON_WIDTH, ItemListView.ICON_HEIGHT)
			: EMPTY);
	}

	/**
	 * Puts the icon of the Slayer task {@code task} ({@link TaskIcons}; pass the assigned name, so a Catacombs variant
	 * or cannon task shows its task's) before {@code label}'s text at the small slot size, or {@link #EMPTY} for a name
	 * that is no known task, so the names line up. The label then asks for no width of its own, so the
	 * icon can't widen the sidebar: a long name is cut short in the space its line gives it.
	 */
	static void applyTask(ItemIcons icons, JLabel label, String task)
	{
		label.setIconTextGap(4);
		Integer itemId = TaskIcons.itemId(task);
		if (itemId == null)
		{
			label.setIcon(EMPTY);
		}
		else
		{
			apply(icons, label, itemId);
		}
		label.setPreferredSize(new Dimension(0, label.getPreferredSize().height));
	}

	/**
	 * Puts a setup tag's game image ({@link SetupTagIcons.Icon}: the cannon barrels, Ice Barrage's spell icon, the skill
	 * icons, as the overlay and the live card's toggles show them) on {@code label} in a {@link #TAG_SIZE} square,
	 * from the sidebar's {@link SetupImages}, which asks for it the first time; {@link #EMPTY_TAG} until it has arrived.
	 * Returns whether the image is on the label. EDT only.
	 */
	static boolean applyTag(SetupImages images, JLabel label, SetupTagIcons.Icon tag)
	{
		Image image = images.get(tag);
		label.setIcon(image == null ? EMPTY_TAG : new SmallItemIcon(image, TAG_SIZE, TAG_SIZE));
		return image != null;
	}

	@Override
	public int getIconWidth()
	{
		return width;
	}

	@Override
	public int getIconHeight()
	{
		return height;
	}

	@Override
	public synchronized void paintIcon(Component c, Graphics g, int x, int y)
	{
		Image image = getImage();
		int imageWidth = image.getWidth(c);
		int imageHeight = image.getHeight(c);
		int drawWidth = width;
		int drawHeight = height;
		if (imageWidth > 0 && imageHeight > 0)
		{
			// Keeps the image's shape: the 36 by 32 item sprites fill the 18 by 16 slot, a cannon a tag box's width.
			double scale = Math.min((double) width / imageWidth, (double) height / imageHeight);
			drawWidth = Math.max(1, (int) Math.round(imageWidth * scale));
			drawHeight = Math.max(1, (int) Math.round(imageHeight * scale));
		}
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g2.drawImage(image, x + (width - drawWidth) / 2, y + (height - drawHeight) / 2, drawWidth, drawHeight, c);
		}
		finally
		{
			g2.dispose();
		}
	}
}

package com.shmayvan.slayerledger;

/**
 * The next bonus-points task of a Slayer task streak. Pure; no RuneLite types.
 *
 * <p>Per the OSRS Wiki "Slayer reward point" (revision 15372070, 2026-10-13,
 * https://oldschool.runescape.wiki/w/Slayer_reward_point?oldid=15372070), bonus points are awarded after every 10th,
 * 50th, 100th, 250th and 1,000th completed task in a row, and Krystilia (Wilderness) has a streak of her own. Every one
 * of those is a multiple of 10, so the next bonus task is always the next multiple of 10 (the larger tiers only change
 * how many points it gives, which this does not show). Turael, Aya and Spria give no points, even on a bonus task.</p>
 *
 * <p>The streak counters are those {@link CompletionSignal} reads, in its order: regular ({@link #REGULAR}),
 * Wilderness ({@link #WILDERNESS}) and Mortimer ({@link #MORTIMER}).</p>
 */
final class StreakMilestone
{
	/** No streak counter applies: the master is unknown. */
	static final int NO_COUNTER = CompletionSignal.NO_COUNTER;
	static final int REGULAR = 0;
	static final int WILDERNESS = 1;
	static final int MORTIMER = 2;

	/** Bonus points come every this many tasks in a row. */
	static final int INTERVAL = 10;

	private StreakMilestone()
	{
	}

	/**
	 * The streak counter for a task from {@code master} (a SLAYER_MASTER value): Wilderness for Krystilia, Mortimer's
	 * for Mortimer, regular for the other masters in {@link SlayerMaster}'s table, and {@link #NO_COUNTER} for no
	 * master or one not in the table.
	 */
	static int counterFor(Integer master)
	{
		if (!SlayerMaster.hasName(master))
		{
			return NO_COUNTER;
		}
		switch (master)
		{
			case SlayerMaster.KRYSTILIA:
				return WILDERNESS;
			case SlayerMaster.MORTIMER:
				return MORTIMER;
			default:
				return REGULAR;
		}
	}

	/**
	 * The next bonus task after {@code streak} completed tasks in a row: the smallest multiple of {@link #INTERVAL}
	 * above it, or {@code null} when the streak is unknown ({@code null}, negative) or the next one would overflow.
	 */
	static Integer nextMilestone(Integer streak)
	{
		if (streak == null || streak < 0 || streak > Integer.MAX_VALUE - INTERVAL)
		{
			return null;
		}
		return (streak / INTERVAL + 1) * INTERVAL;
	}

	/**
	 * Whether {@code streak}, a record's streak after its completion ({@link LedgerRecord#getTaskStreak()}), makes that
	 * task a bonus-points task: a positive multiple of {@link #INTERVAL}. {@code false} when the streak is unknown
	 * ({@code null}), 0 or negative. Points/h leaves these tasks out (owner decision): which monster lands on a
	 * bonus task is streak luck, not the monster.
	 */
	static boolean isMilestone(Integer streak)
	{
		return streak != null && streak > 0 && streak % INTERVAL == 0;
	}

	/**
	 * {@code Next bonus: task 50 (in 3)}: the next bonus task and how many tasks are left to it (the current task, when
	 * one is assigned, is the first of them), or {@code null} when the streak is unknown.
	 */
	static String format(Integer streak)
	{
		final Integer next = nextMilestone(streak);
		if (next == null)
		{
			return null;
		}
		return "Next bonus: task " + next + " (in " + (next - streak) + ")";
	}

	/**
	 * {@code bonus in 3}: the short form of {@link #format} for the task box's second line, or {@code null} when the
	 * streak is unknown.
	 */
	static String formatShort(Integer streak)
	{
		final Integer next = nextMilestone(streak);
		if (next == null)
		{
			return null;
		}
		return "bonus in " + (next - streak);
	}
}

package com.shmayvan.slayerledger;

/**
 * Recognises the game message sent when a superior Slayer monster spawns. Pure; tags and markup are stripped by
 * {@link GameMessageText}.
 *
 * <p>The text is the one core SlayerPlugin (RuneLite 1.13.4, {@code CHAT_SUPERIOR_MESSAGE}) notifies on, received as a
 * game or spam message. The game colours it (seen in November 2026 as {@code @mes_hl_red@...</col>}), so tags and
 * markup are stripped before an exact comparison; core uses {@code contains}, which this deliberately tightens so
 * that, for example, a player's own message quoting the text in another chat type or with extra words is never
 * counted.</p>
 */
final class SuperiorSpawnMessage
{
	static final String TEXT = "A superior foe has appeared...";

	private SuperiorSpawnMessage()
	{
	}

	/**
	 * Whether a chat message announces a superior spawn.
	 *
	 * @param gameOrSpamMessage whether the message type is GAMEMESSAGE or SPAM (as core SlayerPlugin checks)
	 * @param message           the message text, possibly with tags
	 */
	static boolean matches(boolean gameOrSpamMessage, String message)
	{
		return gameOrSpamMessage && message != null && TEXT.equals(GameMessageText.plain(message));
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import net.runelite.api.gameval.*;

/**
 * Decides which game ticks, and which items, are left out of supply counting. Pure: the plugin passes in the tick
 * numbers and events it sees (on the client thread) and asks before each supplies diff. Not thread-safe.
 *
 * <p>Rules:</p>
 * <ul>
 *     <li>While an excluded interface (see {@link #isExcludedInterface}) is open, and for {@link #INTERFACE_TICKS}
 *     ticks after it was last seen open, opened or closed, the whole tick is excluded. The plugin decides "open" from
 *     the interface's root widget being loaded and shown: the game can keep a closed interface's group loaded,
 *     which must not exclude anything.</li>
 *     <li>Dropping a rune pouch excludes the whole tick the same way, because the runes inside leave with it.</li>
 *     <li>For {@link #DEATH_TICKS} ticks after the local player dies the whole tick is excluded (items move to the
 *     gravestone on respawn).</li>
 *     <li>An item on which "Drop" was clicked {@link #DROP_WINDOW_TICKS} ticks ago or less is not a supply, and nor is a
 *     teleport scroll used on the master scroll book that recently (it is stored in the book, see
 *     {@link #useClicked}).</li>
 *     <li>Each window covers only ticks from the one it was recorded on: a tick before it (the tick count restarted)
 *     is outside it, so no window can last longer than its length. RuneLite 1.13.4's tick count keeps counting
 *     across logins and hops ({@code Hooks.tick()} is the only thing that changes it), but this does not rely on
 *     that.</li>
 * </ul>
 */
final class SupplyExclusions
{
	/** Ticks after an excluded interface was last seen open (or opened or closed) during which nothing is counted. */
	static final int INTERFACE_TICKS = 2;
	/** A decrease of an item is not a supply if "Drop" was clicked on that item this many ticks ago or less. */
	static final int DROP_WINDOW_TICKS = 2;
	/** Ticks after the local player dies during which nothing is counted. */
	static final int DEATH_TICKS = 10;
	/** Far enough in the past that no tick window above includes it, without overflowing tick arithmetic. */
	static final int NEVER_TICK = Integer.MIN_VALUE / 2;

	/** The bank, deposit box and group storage; also counted as bank trips (see {@link BankTripCounter}). */
	private static final int[] BANK_INTERFACES = {
		InterfaceID.BANKMAIN, InterfaceID.BANK_DEPOSITBOX, InterfaceID.SHARED_BANK
	};

	/**
	 * Interfaces that move items without using them (bank, deposit box, group storage, seed vault, Grand Exchange,
	 * shops, trade, Death's office and coffer).
	 */
	private static final int[] EXCLUDED_INTERFACES = {
		InterfaceID.BANKMAIN, InterfaceID.BANK_DEPOSITBOX, InterfaceID.SHARED_BANK, InterfaceID.SEED_VAULT,
		InterfaceID.GE_OFFERS, InterfaceID.GE_COLLECT, InterfaceID.SHOPMAIN, InterfaceID.TRADEMAIN,
		InterfaceID.TRADECONFIRM, InterfaceID.DEATH_OFFICE, InterfaceID.DEATH_COFFER
	};

	/**
	 * The master scroll book, empty and filled (RuneLite 1.13.4 {@code net.runelite.api.gameval.ItemID}
	 * {@code BOOKOFSCROLLS_EMPTY} and {@code BOOKOFSCROLLS_CHARGED}).
	 */
	static final Set<Integer> SCROLL_BOOKS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ItemID.BOOKOFSCROLLS_EMPTY, ItemID.BOOKOFSCROLLS_CHARGED)));

	/** Tick on which "Drop" was last clicked (or a scroll stored), per item id; pruned by {@link #beginTick}. */
	private final Map<Integer, Integer> dropTicks = new HashMap<>();
	/** Last tick an excluded interface was open, opened or closed (or a rune pouch was dropped). */
	private int exclusionTick = NEVER_TICK;
	/** Tick the local player last died. */
	private int deathTick = NEVER_TICK;

	/** A copy of the bank interface group ids (the bank, deposit box and group storage), all of them excluded. */
	static int[] bankInterfaces()
	{
		return BANK_INTERFACES.clone();
	}

	/** A copy of the excluded interface group ids. */
	static int[] excludedInterfaces()
	{
		return EXCLUDED_INTERFACES.clone();
	}

	static boolean isExcludedInterface(int groupId)
	{
		for (int group : EXCLUDED_INTERFACES)
		{
			if (group == groupId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * An interface opened (WidgetLoaded) or closed (WidgetClosed) on {@code tick}; excludes the tick if it is an
	 * excluded interface. Covers an interface opened and closed between two ticks, and items it moved that only
	 * arrive on the next tick.
	 */
	void interfaceChanged(int groupId, int tick)
	{
		if (isExcludedInterface(groupId))
		{
			exclusionTick = tick;
		}
	}

	/** "Drop" was clicked on {@code itemId} on {@code tick}; dropping a rune pouch excludes the whole tick. */
	void dropClicked(int itemId, boolean runePouch, int tick)
	{
		dropTicks.put(itemId, tick);
		if (runePouch)
		{
			exclusionTick = tick;
		}
	}

	/**
	 * An item was used on another on {@code tick} ({@code itemIds}: both items, in any order; other ids are ignored). A
	 * teleport scroll ({@link SupplyTracker#TELEPORT_SCROLLS}) used on the master scroll book, or the book on a scroll,
	 * is stored in the book (OSRS Wiki "Master scroll book": scrolls are stored by using them on it), so its decrease
	 * is not counted, as for a drop. The book's stored scrolls are not tracked.
	 */
	void useClicked(int[] itemIds, int tick)
	{
		if (itemIds == null)
		{
			return;
		}
		boolean book = false;
		for (int itemId : itemIds)
		{
			book |= SCROLL_BOOKS.contains(itemId);
		}
		if (!book)
		{
			return;
		}
		for (int itemId : itemIds)
		{
			if (SupplyTracker.TELEPORT_SCROLLS.contains(itemId))
			{
				dropTicks.put(itemId, tick);
			}
		}
	}

	/** The local player died on {@code tick}. */
	void playerDied(int tick)
	{
		deathTick = tick;
	}

	/**
	 * Start of a supplies diff on {@code tick}: records whether an excluded interface is open now and forgets drop
	 * clicks outside the {@link #DROP_WINDOW_TICKS} window (or from a later tick).
	 */
	void beginTick(int tick, boolean excludedInterfaceOpen)
	{
		if (excludedInterfaceOpen)
		{
			exclusionTick = tick;
		}
		dropTicks.values().removeIf(t -> t > tick || tick - t > DROP_WINDOW_TICKS);
	}

	/** Whether nothing may be counted on {@code tick} (an excluded interface or a rune pouch drop, or a death). */
	boolean isTickExcluded(int tick)
	{
		return within(tick, exclusionTick, INTERFACE_TICKS) || within(tick, deathTick, DEATH_TICKS);
	}

	/**
	 * Why {@code tick} is excluded, for the plugin's debug line about a long stretch of uncounted ticks; {@code null}
	 * when it is not.
	 */
	String exclusionReason(int tick)
	{
		if (within(tick, exclusionTick, INTERFACE_TICKS))
		{
			return "an excluded interface was open, opened or closed (or a rune pouch dropped) on tick "
				+ exclusionTick;
		}
		if (within(tick, deathTick, DEATH_TICKS))
		{
			return "the local player died on tick " + deathTick;
		}
		return null;
	}

	/**
	 * Whether {@code tick} is {@code from} or at most {@code length} ticks after it. A tick before {@code from} (the
	 * tick count restarted) is not.
	 */
	private static boolean within(int tick, int from, int length)
	{
		return tick >= from && (long) tick - from <= length;
	}

	/** A copy of the item ids dropped within the window, as of the last {@link #beginTick}. */
	Set<Integer> droppedItems()
	{
		return new HashSet<>(dropTicks.keySet());
	}

	/** Forgets everything (login, hop, lost connection, plugin start): nothing from before them is excluded after. */
	void reset()
	{
		dropTicks.clear();
		exclusionTick = NEVER_TICK;
		deathTick = NEVER_TICK;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import javax.inject.*;
import net.runelite.api.*;
import net.runelite.api.gameval.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.*;

/**
 * Reads what the player carries for supply counting: the {@link SupplyTracker.Observation} of the tracked
 * containers, and each item's supplies category ({@link #classifyItem}) from its definition. The diff and the counting
 * rules stay in {@link SupplyTracker}; this class only reads the client. Client thread only; the rune pouch's rune ids
 * are cached until {@link #reset()}, which the plugin calls in its startUp client-thread block.
 *
 * <p>Injected by Guice into the plugin, as RuneLite plugins inject their overlays and helpers.
 */
class SupplyReader
{
	/** Rune pouch slots as read by core RunepouchOverlay (1.13.3); the divine rune pouch uses the same varbits. */
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
	};
	private static final int[] RUNE_POUCH_QUANTITY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
	};
	/** Worn slots read for supplies: ammo and thrown weapons, and teleport jewellery used from the equipment tab. */
	private static final EquipmentInventorySlot[] SUPPLY_WORN_SLOTS = {
		EquipmentInventorySlot.AMMO, EquipmentInventorySlot.WEAPON, EquipmentInventorySlot.AMULET,
		EquipmentInventorySlot.RING, EquipmentInventorySlot.GLOVES
	};
	/** What the game appends to a members item's name on a free world (see {@link #classifyItem}). */
	static final String MEMBERS_SUFFIX = " (Members)";

	private final Client client;
	private final ItemManager itemManager;
	/** Item ids the rune pouch can hold (EnumID.RUNEPOUCH_RUNE values), loaded on first use. */
	private Set<Integer> runePouchRuneIds;

	@Inject
	SupplyReader(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/** Client thread, in the plugin's startUp block: the rune pouch's rune ids are loaded afresh. */
	void reset()
	{
		runePouchRuneIds = null;
	}

	/**
	 * Client thread. The tracked containers: the inventory; the worn ammo and weapon slots (classification keeps only
	 * ammo and stackable thrown weapons) and amulet, ring and gloves slots (classification keeps only charged teleport
	 * jewellery, see {@link SupplyTracker#CHARGED_ITEMS}); Dizana's quiver (the DIZANAS_QUIVER_TEMP_AMMO / _AMOUNT varps,
	 * as core AmmoPlugin reads them); the rune pouch while one is in the inventory (varbits RUNE_POUCH_TYPE_1-6 and
	 * RUNE_POUCH_QUANTITY_1-6 mapped through EnumID.RUNEPOUCH_RUNE, as core RunepouchOverlay does); and the cannon's
	 * loaded ammo (the ROCKTHROWER varp core CannonPlugin reads).
	 *
	 * @return the observation, or {@code null} while the inventory is not loaded
	 */
	SupplyTracker.Observation readSupplyObservation()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return null;
		}
		final SupplyTracker.Observation observation = new SupplyTracker.Observation();
		boolean hasRunePouch = false;
		for (Item item : inventory.getItems())
		{
			observation.add(item.getId(), item.getQuantity());
			hasRunePouch |= isRunePouch(item.getId());
		}

		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			for (EquipmentInventorySlot slot : SUPPLY_WORN_SLOTS)
			{
				final Item item = worn.getItem(slot.getSlotIdx());
				if (item != null)
				{
					observation.add(item.getId(), item.getQuantity());
				}
			}
		}

		final int quiverAmmo = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		final int quiverAmount = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		if (quiverAmmo >= 0 && quiverAmount > 0)
		{
			observation.add(quiverAmmo, quiverAmount);
		}

		if (hasRunePouch)
		{
			final EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			for (int i = 0; runeEnum != null && i < RUNE_POUCH_TYPE_VARBITS.length; i++)
			{
				final int type = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
				final int amount = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[i]);
				if (type != 0 && amount > 0)
				{
					observation.add(runeEnum.getIntValue(type), amount);
				}
			}
		}

		observation.setCannonBalls(client.getVarpValue(VarPlayerID.ROCKTHROWER));
		return observation;
	}

	/**
	 * Client thread. The inventory's items alone (the only place potions are kept), for
	 * {@link SupplyTracker#noteVariants} while no session is running; {@code null} while the inventory is not loaded.
	 */
	SupplyTracker.Observation readInventoryObservation()
	{
		final ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return null;
		}
		final SupplyTracker.Observation observation = new SupplyTracker.Observation();
		for (Item item : inventory.getItems())
		{
			observation.add(item.getId(), item.getQuantity());
		}
		return observation;
	}

	/**
	 * Client thread. Supplies category from the item definition: cannonballs by id, runes by the rune pouch enum (or a
	 * name ending in " rune"), ammo by equipment slot (ammo, or a stackable weapon such as darts, knives or
	 * chinchompas), multi-bite food (pies, pizzas and cakes), charged teleport jewellery, the fungicide spray, Slayer
	 * consumables and teleport scrolls by id, and teleport tablets, potions and food by name and inventory actions (see
	 * {@link SupplyTracker#classify}). Noted items and placeholders are never supplies.
	 *
	 * <p>A members item seen on a free world is not classified: there the game appends {@value #MEMBERS_SUFFIX}
	 * to its name ({@code ItemComposition.getName}; the client's {@code getMembersName} removes exactly that suffix,
	 * 1.13.4), so "Prayer potion(4) (Members)" would not read as a potion. {@link SupplyTracker} caches what this
	 * returns for the plugin's life, so it would stay wrong after a hop to a members world; {@code null} makes it ask
	 * again once the item's real definition shows. The item can't be used on a free world anyway.</p>
	 *
	 * @return the category, or {@code null} while a wieldable item's stats are not loaded yet or a members item is seen
	 * on a free world (retried later)
	 */
	SupplyTracker.ItemInfo classifyItem(int itemId)
	{
		final ItemComposition comp = itemManager.getItemComposition(itemId);
		if (comp.getNote() != -1 || comp.getPlaceholderTemplateId() != -1)
		{
			return SupplyTracker.ItemInfo.OTHER;
		}
		final String name = comp.getName();
		if (SupplyTracker.classifiesById(itemId))
		{
			// Decided by id alone: no need to wait for the item stats of wearable jewellery, and the free-world name of a
			// members item doesn't matter.
			return SupplyTracker.classify(itemId, name, comp.getInventoryActions(), false, false, false);
		}
		if (name != null && name.endsWith(MEMBERS_SUFFIX))
		{
			return null;
		}
		final boolean cannonball = itemId == SupplyTracker.CANNONBALL || itemId == SupplyTracker.GRANITE_CANNONBALL;
		final boolean rune = runePouchRuneIds().contains(itemId) || (name != null && name.endsWith(" rune"));
		final ItemStats stats = itemManager.getItemStats(itemId);
		if (stats == null && !cannonball && !rune && isEquipable(comp.getInventoryActions()))
		{
			// Item stats are loaded asynchronously and may not be available yet; don't let an unloaded wieldable item
			// (possibly ammo) be cached as untracked. SupplyTracker retries a null classification later.
			return null;
		}
		final int slot = stats != null && stats.getEquipment() != null ? stats.getEquipment().getSlot() : -1;
		final boolean ammo = slot == EquipmentInventorySlot.AMMO.getSlotIdx()
			|| (slot == EquipmentInventorySlot.WEAPON.getSlotIdx() && comp.isStackable());
		return SupplyTracker.classify(itemId, name, comp.getInventoryActions(), rune, ammo, cannonball);
	}

	/** Whether inventory actions {@code actions} include "Wield" or "Wear". Pure. */
	static boolean isEquipable(String[] actions)
	{
		if (actions != null)
		{
			for (String action : actions)
			{
				if ("Wield".equals(action) || "Wear".equals(action))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Client thread. Item ids the rune pouch can hold; empty (and retried later) while the enum is unavailable. */
	private Set<Integer> runePouchRuneIds()
	{
		if (runePouchRuneIds != null)
		{
			return runePouchRuneIds;
		}
		final Set<Integer> ids = new HashSet<>();
		final EnumComposition runeEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runeEnum != null)
		{
			for (int id : runeEnum.getIntVals())
			{
				if (id > 0)
				{
					ids.add(id);
				}
			}
		}
		if (!ids.isEmpty())
		{
			runePouchRuneIds = ids;
		}
		return ids;
	}

	/** Whether {@code itemId} is a rune pouch (regular or divine, either version) whose runes are read. Pure. */
	static boolean isRunePouch(int itemId)
	{
		return itemId == ItemID.BH_RUNE_POUCH || itemId == ItemID.BH_RUNE_POUCH_TROUVER
			|| itemId == ItemID.DIVINE_RUNE_POUCH || itemId == ItemID.DIVINE_RUNE_POUCH_TROUVER;
	}

	/** The item worn in {@code slot} of {@code worn}, or {@link ChargedWeaponUsage#NO_ITEM}. Pure. */
	static int wornItemId(ItemContainer worn, EquipmentInventorySlot slot)
	{
		final Item item = worn != null ? worn.getItem(slot.getSlotIdx()) : null;
		return item != null ? item.getId() : ChargedWeaponUsage.NO_ITEM;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;
import lombok.*;
import net.runelite.api.gameval.*;

/**
 * The overlay's supply runway (DESIGN_PRINCIPLES.md 2.5): how many kills each carried supply lasts at the
 * current rate, and the scarcest one when it runs out before the task ends. Pure; the plugin hands it what is carried
 * and what was used, on the client thread once per tick, never while the overlay draws. The rule is written out in
 * docs/COUNTING_RULES.md ("Supply runway").
 *
 * <ul>
 * <li><b>What counts.</b> Only supplies with a short name ({@link Kind}): prayer potions, restores (super restores,
 * blighted super restores, sanfew serums), food, cannonballs, runes, ammo, darts and Zulrah's scales. Other potions,
 * teleports, jewellery charges and Slayer consumables don't.</li>
 * <li><b>Units.</b> Potions count in doses, food eaten in parts in bites, everything else in items; the carried amount
 * and the use are in the same unit and summed per supply ({@link SupplyTracker#supplyKey}), so every dose of every
 * potion size of a family counts as one supply.</li>
 * <li><b>Per-kill use.</b> This task's once its session has {@link #MIN_TASK_KILLS} kills: what it used divided by its
 * kills (a supply it hasn't used lasts). Before that the history's, the same completed tasks the time left uses
 * ({@link TaskStatistics#getSuppliesPerKill}); none without history.</li>
 * <li><b>Kills it lasts.</b> The carried amount divided by the per-kill use, rounded down, but at least 1 while any of
 * it is carried: 0 means none is.</li>
 * <li><b>Run out.</b> A supply carried earlier in the session and gone now counts at none ({@link #withRunOut}), so its
 * warning stays at {@code Prayer: 0 left} until it or another of its kind (but not another rune) is carried again,
 * the session ends or the rate in use no longer uses it. Only a fall to none counted as use runs a supply out: a tick
 * the supply counting leaves out (the bank, a drop) forgets what left with it ({@link OverlayFeed}). Not while the
 * containers weren't read, nor darts and scales while a blowpipe may hold some that aren't counted
 * ({@link #blowpipeUnseen}).</li>
 * <li><b>Shown.</b> Only the scarcest supply (fewest kills; a tie goes to the first {@link Kind}, then the lower item
 * id), and only when it lasts fewer kills than are left on the task. Critical within {@link #CRITICAL_KILLS}
 * kills.</li>
 * </ul>
 */
final class SupplyRunway
{
	/** A supply that lasts this many kills or fewer is critical: {@code Prayer: 6 left}, in Bold. */
	static final int CRITICAL_KILLS = 9;
	/** From this many kills in the session, its own use per kill replaces the history's. */
	static final int MIN_TASK_KILLS = 10;
	/** Zulrah's scales: the blowpipe's ammunition ({@code ItemID.SNAKEBOSS_SCALE}). */
	static final int ZULRAH_SCALES = ItemID.SNAKEBOSS_SCALE;

	/** The potion families counted as {@link Kind#PRAYER}, lower case. */
	private static final List<String> PRAYER_FAMILIES = Collections.singletonList("prayer potion");
	/** The potion families counted as {@link Kind#RESTORES}, lower case. */
	private static final List<String> RESTORE_FAMILIES = Collections.unmodifiableList(Arrays.asList(
		"super restore", "blighted super restore", "sanfew serum"));

	/** What a counted supply is, with its short name (DESIGN_PRINCIPLES.md 2.5), in tie-break order. */
	@Getter
	@AllArgsConstructor
	enum Kind
	{
		PRAYER("Prayer"),
		RESTORES("Restores"),
		FOOD("Food"),
		CANNONBALLS("Cannonballs"),
		RUNES("Runes"),
		AMMO("Ammo"),
		DARTS("Darts"),
		SCALES("Scales");

		/** The runway's name for it: {@code Prayer}, {@code Cannonballs}. */
		private final String shortName;
	}

	/** A supply the player carries now. Immutable. */
	@Getter
	static final class Supply
	{
		private final String key;
		private final int itemId;
		private final Kind kind;
		private final long amount;

		/**
		 * @param key    the supply's key ({@link SupplyTracker#supplyKey})
		 * @param itemId the item whose icon the runway shows (a potion's largest size seen)
		 * @param amount how much is carried, in the unit its use is counted in (doses, bites or items)
		 */
		Supply(String key, int itemId, Kind kind, long amount)
		{
			this.key = Objects.requireNonNull(key);
			this.itemId = itemId;
			this.kind = Objects.requireNonNull(kind);
			this.amount = amount;
		}
	}

	/**
	 * What the player carries on a tick, for the runway: the counted supplies, whether the containers were read at all,
	 * and whether a toxic blowpipe may hold darts and scales that can't be counted ({@link #blowpipeUnseen}). Immutable.
	 */
	static final class Carrying
	{
		/** Nothing known carried: the containers were not read on the tick, and no blowpipe's contents are known. */
		static final Carrying UNSEEN = new Carrying(Collections.emptyList(), false, false);

		/** The counted supplies carried; empty when {@link #UNSEEN}. */
		@Getter
		private final List<Supply> supplies;
		/** Whether the containers were read on the tick. */
		@Getter
		private final boolean seen;
		private final boolean blowpipeUnseen;

		/**
		 * @param supplies       the counted supplies carried ({@link #carried}, {@link #withBlowpipe})
		 * @param seen           whether the containers were read on the tick (no task assigned, or the inventory not
		 *                       loaded): without them only a worn blowpipe's known contents are carried, and nothing
		 *                       counts as run out
		 * @param blowpipeUnseen whether a blowpipe may hold darts and scales that can't be counted
		 */
		Carrying(List<Supply> supplies, boolean seen, boolean blowpipeUnseen)
		{
			this.supplies = supplies == null ? Collections.emptyList()
				: Collections.unmodifiableList(new ArrayList<>(supplies));
			this.seen = seen;
			this.blowpipeUnseen = blowpipeUnseen;
		}

		/**
		 * Whether the amount of {@code kind} carried is known, so that none of it means it ran out: not while the
		 * containers weren't read, nor darts and scales while a blowpipe may hold some that can't be counted.
		 */
		boolean isSeen(Kind kind)
		{
			return seen && !(blowpipeUnseen && (kind == Kind.DARTS || kind == Kind.SCALES));
		}
	}

	/** The runway to show: a supply and the kills it lasts. Immutable. */
	@Value
	static final class Warning
	{
		private final Kind kind;
		/** The item whose icon is shown. */
		private final int itemId;
		/** The kills the carried amount lasts (rounded down, at least 1 while any is carried); 0 once it ran out. */
		private final long kills;

		Warning(Kind kind, int itemId, long kills)
		{
			this.kind = Objects.requireNonNull(kind);
			this.itemId = itemId;
			this.kills = kills;
		}

		/** Whether it runs out within {@link #CRITICAL_KILLS} kills. */
		boolean isCritical()
		{
			return kills <= CRITICAL_KILLS;
		}
	}

	private SupplyRunway()
	{
	}

	/**
	 * What a tracked supply counts as for the runway, or {@code null} when it doesn't count.
	 *
	 * @param category its supplies category ({@link SupplyTracker.ItemInfo#getCategory})
	 * @param family   a potion's family (its name without the dose), or {@code null}
	 * @param itemId   the item (a dart the blowpipe takes is {@link Kind#DARTS}, other ammo {@link Kind#AMMO})
	 */
	static Kind kind(SupplyTracker.Category category, String family, int itemId)
	{
		if (category == null)
		{
			return null;
		}
		switch (category)
		{
			case POTION:
			{
				final String name = family == null ? "" : family.trim().toLowerCase(Locale.ROOT);
				if (PRAYER_FAMILIES.contains(name))
				{
					return Kind.PRAYER;
				}
				return RESTORE_FAMILIES.contains(name) ? Kind.RESTORES : null;
			}
			case FOOD:
				return Kind.FOOD;
			case CANNONBALL:
				return Kind.CANNONBALLS;
			case RUNE:
				return Kind.RUNES;
			case AMMO:
				return BlowpipeMessage.isDart(itemId) ? Kind.DARTS : Kind.AMMO;
			default:
				return null;
		}
	}

	/** The carried supplies that count ({@link #kind}), from what the supplies diff last saw. */
	static List<Supply> carried(Collection<SupplyTracker.Carried> carried)
	{
		if (carried == null || carried.isEmpty())
		{
			return Collections.emptyList();
		}
		final List<Supply> supplies = new ArrayList<>(carried.size());
		for (SupplyTracker.Carried item : carried)
		{
			final Kind kind = kind(item.getCategory(), item.getFamily(), item.getItemId());
			if (kind != null && item.getAmount() > 0)
			{
				supplies.add(new Supply(item.getKey(), item.getItemId(), kind, item.getAmount()));
			}
		}
		return supplies;
	}

	/**
	 * {@code carried} with what a worn toxic blowpipe holds: its darts added to the darts of their type, and its Zulrah's
	 * scales with the loose ones carried. While its contents are not known ({@link BlowpipeContents}) no darts or scales
	 * count, since what it holds could be anything; without a blowpipe worn {@code carried} is returned as it is.
	 *
	 * @param looseScales Zulrah's scales carried outside the blowpipe
	 */
	static List<Supply> withBlowpipe(List<Supply> carried, boolean blowpipeWorn, BlowpipeContents contents,
		long looseScales)
	{
		if (!blowpipeWorn)
		{
			return carried;
		}
		final boolean known = contents != null && contents.isKnown();
		final List<Supply> supplies = new ArrayList<>(carried.size() + 2);
		final String dartKey = known && contents.getDartId() != ChargedWeaponUsage.NO_ITEM
			? SupplyTracker.itemKey(contents.getDartId()) : null;
		boolean dartsAdded = false;
		for (Supply supply : carried)
		{
			if (supply.getKind() == Kind.DARTS || supply.getKind() == Kind.SCALES)
			{
				if (!known)
				{
					continue;
				}
				if (supply.getKey().equals(dartKey))
				{
					supplies.add(new Supply(supply.getKey(), supply.getItemId(), Kind.DARTS,
						saturatedAdd(supply.getAmount(), contents.getDarts())));
					dartsAdded = true;
					continue;
				}
			}
			supplies.add(supply);
		}
		if (known)
		{
			if (dartKey != null && !dartsAdded && contents.getDarts() > 0)
			{
				supplies.add(new Supply(dartKey, contents.getDartId(), Kind.DARTS, contents.getDarts()));
			}
			final long scales = saturatedAdd(contents.getScales(), Math.max(0, looseScales));
			if (scales > 0)
			{
				supplies.add(new Supply(SupplyTracker.itemKey(ZULRAH_SCALES), ZULRAH_SCALES, Kind.SCALES, scales));
			}
		}
		return supplies;
	}

	/**
	 * Whether a toxic blowpipe may hold darts and scales the runway can't count, so that none of them carried says
	 * nothing about running out: whenever its contents are not known, worn or not (worn, {@link #withBlowpipe} then
	 * counts no darts or scales at all; not worn, the player may still have one, unequipped since a login or a load
	 * made its contents unknown, say), or not worn while it is known to hold some (they count only while it is worn).
	 * So without a blowpipe checked since the login, thrown darts don't run out either.
	 */
	static boolean blowpipeUnseen(boolean blowpipeWorn, BlowpipeContents contents)
	{
		if (contents == null || !contents.isKnown())
		{
			return true;
		}
		return !blowpipeWorn && (contents.getDarts() > 0 || contents.getScales() > 0);
	}

	/**
	 * What is carried on a tick, for the runway: {@code carried} with a worn blowpipe's contents
	 * ({@link #withBlowpipe}), and whether the blowpipe may hold darts and scales that can't be counted
	 * ({@link #blowpipeUnseen}).
	 *
	 * @param carried the counted supplies the containers hold ({@link #carried}); empty when they weren't read
	 * @param seen    whether the containers were read on the tick ({@link Carrying#isSeen})
	 */
	static Carrying carrying(List<Supply> carried, boolean seen, boolean blowpipeWorn, BlowpipeContents contents,
		long looseScales)
	{
		return new Carrying(withBlowpipe(carried, blowpipeWorn, contents, looseScales), seen,
			blowpipeUnseen(blowpipeWorn, contents));
	}

	/**
	 * {@code carrying}'s supplies, with each supply carried earlier in the session ({@code earlier}) that is not carried
	 * now added at none, so that its runway shows it ran out: only when its amount is seen ({@link Carrying#isSeen}),
	 * and not while another supply of its kind is carried (karambwans after the sharks ran out, another dart type),
	 * except runes, each of which a spell needs.
	 *
	 * @param earlier the supplies carried earlier in the session, each as last carried (its key, icon and kind)
	 */
	static List<Supply> withRunOut(Carrying carrying, Collection<Supply> earlier)
	{
		final List<Supply> supplies = new ArrayList<>(carrying.getSupplies());
		if (earlier == null || earlier.isEmpty() || !carrying.isSeen())
		{
			return supplies;
		}
		final Set<String> carried = new HashSet<>();
		final Set<Kind> kinds = EnumSet.noneOf(Kind.class);
		for (Supply supply : supplies)
		{
			carried.add(supply.getKey());
			if (supply.getAmount() > 0)
			{
				kinds.add(supply.getKind());
			}
		}
		for (Supply supply : earlier)
		{
			final boolean replaced = supply.getKind() != Kind.RUNES && kinds.contains(supply.getKind());
			if (!carried.contains(supply.getKey()) && !replaced && carrying.isSeen(supply.getKind()))
			{
				supplies.add(new Supply(supply.getKey(), supply.getItemId(), supply.getKind(), 0));
				carried.add(supply.getKey());
			}
		}
		return supplies;
	}

	/** {@code items} (item id to amount) summed per supply key ({@code keyOf}); ids without a key are left out. */
	static Map<String, Long> byKey(Map<Integer, Long> items, IntFunction<String> keyOf)
	{
		final Map<String, Long> byKey = new TreeMap<>();
		if (items != null)
		{
			items.forEach((id, amount) ->
			{
				final String key = id == null || amount == null || amount <= 0 ? null : keyOf.apply(id);
				if (key != null)
				{
					byKey.merge(key, amount, SupplyRunway::saturatedAdd);
				}
			});
		}
		return byKey;
	}

	/** {@code perKill} (item id to use per kill) summed per supply key ({@code keyOf}); ids without a key are left out. */
	static Map<String, Double> perKillByKey(Map<Integer, Double> perKill, IntFunction<String> keyOf)
	{
		final Map<String, Double> byKey = new TreeMap<>();
		if (perKill != null)
		{
			perKill.forEach((id, amount) ->
			{
				final String key = id == null || amount == null || !(amount > 0) ? null : keyOf.apply(id);
				if (key != null)
				{
					byKey.merge(key, amount, Double::sum);
				}
			});
		}
		return byKey;
	}

	/**
	 * The runway to show, or {@code null}: the carried supply that lasts the fewest kills, when that is fewer than
	 * {@code killsLeft} (see the class comment for the rule).
	 *
	 * @param carried        the supplies carried now
	 * @param taskUse        this session's use so far, per supply key, in the same units
	 * @param taskKills      this session's kills
	 * @param historyPerKill the history's use per kill, per supply key; empty without history
	 * @param killsLeft      the kills left on the task; nothing is shown when it is not known ({@code <= 0})
	 */
	static Warning scarcest(Collection<Supply> carried, Map<String, Long> taskUse, int taskKills,
		Map<String, Double> historyPerKill, int killsLeft)
	{
		if (carried == null || killsLeft <= 0)
		{
			return null;
		}
		final boolean ownRate = taskKills >= MIN_TASK_KILLS;
		Supply best = null;
		long bestKills = Long.MAX_VALUE;
		for (Supply supply : carried)
		{
			final long kills = ownRate ? lastsAtTaskRate(supply, taskUse, taskKills)
				: lastsAtHistoryRate(supply, historyPerKill);
			if (kills < 0 || kills >= killsLeft)
			{
				continue;
			}
			if (best == null || kills < bestKills || (kills == bestKills && before(supply, best)))
			{
				best = supply;
				bestKills = kills;
			}
		}
		return best == null ? null : new Warning(best.getKind(), best.getItemId(), bestKills);
	}

	/** Kills {@code supply} lasts at the session's own rate ({@link #atLeastOne}), or -1 when the session used none. */
	private static long lastsAtTaskRate(Supply supply, Map<String, Long> taskUse, int taskKills)
	{
		final Long used = taskUse == null ? null : taskUse.get(supply.getKey());
		if (used == null || used <= 0 || taskKills <= 0)
		{
			return -1;
		}
		// carried / (used / kills), rounded down, exactly.
		try
		{
			return atLeastOne(supply, Math.multiplyExact(Math.max(0, supply.getAmount()), (long) taskKills) / used);
		}
		catch (ArithmeticException e)
		{
			return Long.MAX_VALUE;
		}
	}

	/** Kills {@code supply} lasts at the history's rate ({@link #atLeastOne}), or -1 when the history has no use of it. */
	private static long lastsAtHistoryRate(Supply supply, Map<String, Double> historyPerKill)
	{
		final Double perKill = historyPerKill == null ? null : historyPerKill.get(supply.getKey());
		if (perKill == null || !(perKill > 0))
		{
			return -1;
		}
		// A small allowance, so 20 doses at 0.5 a kill are 40 kills, not 39.999...
		final double kills = Math.floor(Math.max(0, supply.getAmount()) / perKill + 1e-9);
		return atLeastOne(supply, kills >= Long.MAX_VALUE ? Long.MAX_VALUE : (long) kills);
	}

	/** {@code kills}, but at least 1 while any of {@code supply} is carried: 0 kills means none is. */
	private static long atLeastOne(Supply supply, long kills)
	{
		return supply.getAmount() > 0 ? Math.max(1, kills) : kills;
	}

	/** The tie-break: the earlier kind, then the lower item id. */
	private static boolean before(Supply a, Supply b)
	{
		final int byKind = a.getKind().compareTo(b.getKind());
		return byKind != 0 ? byKind < 0 : a.getItemId() < b.getItemId();
	}

	private static long saturatedAdd(long a, long b)
	{
		final long sum = a + b;
		return ((a ^ sum) & (b ^ sum)) < 0 ? Long.MAX_VALUE : sum;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.*;
import java.util.*;
import java.util.regex.*;
import lombok.*;
import net.runelite.api.gameval.*;

/**
 * Pure per-tick supplies diff. The plugin reads the player's item containers once per game tick into an
 * {@link Observation} (inventory, worn ammo, weapon, amulet, ring and gloves slots, Dizana's quiver, rune pouch, and the
 * cannon's loaded ammo); this class compares it with the previous tick and reports what was used. No RuneLite dependencies; item
 * facts come from a {@link Classifier} the plugin backs with {@code ItemComposition} on the client thread.
 *
 * <p>All tracked containers are summed into one virtual container before diffing, so moving items between them nets
 * to zero: filling or emptying the rune pouch, equipping ammo from the inventory, loading the quiver, and loading or
 * picking up the cannon. Only these categories are tracked; every other item is ignored:</p>
 * <ul>
 *     <li>{@link Category#FOOD}: items with an "Eat" or "Drink" inventory action that are not potions. Food eaten in
 *     parts (pies, pizzas and cakes, see {@link #MULTI_BITE_FOOD}) is tracked in bites per food, like potion doses:
 *     eating a whole pizza (2 to 1 bite, then 1 to 0) uses two bites, which are worth one pizza.</li>
 *     <li>{@link Category#POTION}: items named {@code Name(n)} with a "Drink" action. Tracked in doses per family
 *     ({@code Name}), so a drink (4 to 3) uses one dose and decanting, which keeps the family's total doses, nets to
 *     zero.</li>
 *     <li>{@link Category#RUNE}, {@link Category#AMMO} and {@link Category#CANNONBALL}, as decided by the plugin.</li>
 *     <li>{@link Category#SLAYER_CONSUMABLE}: bags of salt and ice coolers ({@link #SLAYER_CONSUMABLES}), one per item
 *     used.</li>
 *     <li>{@link Category#TELEPORT_TABLET}: items with a "Break" inventory action whose name contains "teleport" (for
 *     example "Varrock teleport", "Teleport to house" or "Salve graveyard teleport"), one per tablet broken.</li>
 *     <li>{@link Category#TELEPORT_SCROLL}: teleport scrolls ({@link #TELEPORT_SCROLLS}, by id), one per scroll read.</li>
 *     <li>{@link Category#CHARGES}: teleport jewellery and the fungicide spray ({@link #CHARGED_ITEMS}), tracked in
 *     charges per item type like potion doses and recorded under the item's highest-charge variant. Using a charge (8
 *     to 7) uses one charge, and so does the last one, whether the item then crumbles (ring of dueling, games
 *     necklace) or becomes an uncharged variant, which is not a supply (amulet of glory, "Fungicide spray 0").
 *     Recharging (the Fountain of Heroes, refilling the spray) is an increase, so it is ignored. The refill item
 *     ("Fungicide") is not a supply, so a spray's cost is counted once, per charge sprayed.</li>
 * </ul>
 *
 * <p>A net decrease is a use, except for items dropped on this tick (see {@link #update}). A net increase is ignored
 * (it is loot or a withdrawal), except that an increase of ammo or cannonballs is reported as
 * {@link Usage#getReturned() returned}: picked-up ammo, or cannonballs back from the cannon, offset what was counted as
 * used before (the session never lets that go below zero).</p>
 *
 * <p>The cannon's loaded ammo is counted as the cannonball type that left the inventory when it was loaded. When
 * tracking starts with the cannon already loaded, the type is unknown and regular cannonballs are assumed until a load
 * or pickup shows it. If the cannon's pickup or unload (or a further load) shows the other type, the assumption is
 * corrected: its load moves to that type, so picking up a cannon that has not fired counts nothing, and cannonballs
 * fired since the last {@link #reset()} under the assumed type move to that type too. A pickup or unload shows
 * the type only when more than half of the cannon's last seen load comes back as it, so shots fired on the pickup tick
 * are allowed for, while fewer cannonballs looted as the cannon empties are not taken for its type.</p>
 *
 * <p>Not thread-safe; the plugin uses it on the client thread only.</p>
 */
final class SupplyTracker
{
	/** {@code net.runelite.api.gameval.ItemID.MCANNONBALL} (1.13.3), the default for the cannon's loaded ammo. */
	static final int CANNONBALL = 2;
	/** {@code net.runelite.api.gameval.ItemID.GRANITE_CANNONBALL} (1.13.3). */
	static final int GRANITE_CANNONBALL = 21728;

	/** Potion names end in the dose count, for example "Prayer potion(4)". */
	private static final Pattern DOSE_NAME = Pattern.compile("^(.+)\\((\\d)\\)$");

	/**
	 * Food eaten in parts, by the id of each stage: {full item id, bites left in this stage, bites in a full item}. The
	 * families are the bundled {@code supply-items.json}'s {@code multiBiteFood} ({@link BundledData}; none when it
	 * can't be read), by gameval {@code ItemID} (unnoted; noted items are never supplies). What is left after the last
	 * bite of a pie (the pie dish) has no "Eat" action, so it is not a supply.
	 */
	static final Map<Integer, int[]> MULTI_BITE_FOOD = stages("multiBiteFood");

	/**
	 * Items used per charge, by the id of each charged variant: {highest-charge item id, charges left, charges in the
	 * highest-charge item}. One family per item type; the trimmed glory and the imbued ring of wealth are families of
	 * their own. Uncharged variants ("Amulet of glory", "Skills necklace", "Fungicide spray 0" and so on) are not
	 * listed, so they are not supplies, and neither are items that never run out (amulet of eternal glory, slayer ring
	 * (eternal)). The families are the bundled {@code supply-items.json}'s {@code chargedItems}, by gameval
	 * {@code ItemID}, with the charges core {@code ItemWithCharge} gives them (its TELEPORT and FUNGICIDE_SPRAY types).
	 */
	static final Map<Integer, int[]> CHARGED_ITEMS = stages("chargedItems");

	/**
	 * Slayer items used up one per use: the bag of salt ({@code SLAYER_BAG_OF_SALT}) and the ice cooler
	 * ({@code SLAYER_ICY_WATER}), RuneLite 1.13.4 {@code net.runelite.api.gameval.ItemID} constants. Tools that are not
	 * used up, such as the rock hammer, are not supplies.
	 */
	static final Set<Integer> SLAYER_CONSUMABLES = Collections.unmodifiableSet(
		new HashSet<>(Arrays.asList(ItemID.SLAYER_BAG_OF_SALT, ItemID.SLAYER_ICY_WATER)));

	/**
	 * Teleport scrolls, used up one per teleport: the scrolls core ItemIdentification lists as
	 * {@code Type.SCROLL}, the bundled {@code supply-items.json}'s {@code teleportScrolls}. They are stackable
	 * and read with a "Teleport" inventory action (OSRS Wiki item infoboxes, for example Zul-andra teleport and Revenant
	 * cave teleport), which other items that are not used up share, so they are classified by id. The scrolls stored in
	 * a master scroll book are not read; storing them is not a use ({@link SupplyExclusions#useClicked}).
	 */
	static final Set<Integer> TELEPORT_SCROLLS = BundledData.idSet("supply-items.json", "teleportScrolls");

	/**
	 * The {@code list} families of {@code supply-items.json}, each item's stages from the full item down to the last
	 * bite (or charge), by the id of each stage. Unmodifiable; empty when the file can't be read.
	 */
	private static Map<Integer, int[]> stages(String list)
	{
		return BundledData.load("supply-items.json", root ->
		{
			final Map<Integer, int[]> items = new HashMap<>();
			for (JsonElement family : root.getAsJsonArray(list))
			{
				final int[] stages = BundledData.ids(family.getAsJsonObject().getAsJsonArray("stages"));
				for (int i = 0; i < stages.length; i++)
				{
					items.put(stages[i], new int[]{stages[0], stages.length - i, stages.length});
				}
			}
			return Collections.unmodifiableMap(items);
		}, Collections.emptyMap());
	}

	/** How an item is tracked. */
	enum Category
	{
		FOOD,
		POTION,
		RUNE,
		AMMO,
		CANNONBALL,
		/** Bags of salt and ice coolers; see {@link #SLAYER_CONSUMABLES}. */
		SLAYER_CONSUMABLE,
		/** Teleport tablets: a "Break" action and "teleport" in the name. */
		TELEPORT_TABLET,
		/** Teleport scrolls; see {@link #TELEPORT_SCROLLS}. */
		TELEPORT_SCROLL,
		/** Teleport jewellery and the fungicide spray, in charges; see {@link #CHARGED_ITEMS}. */
		CHARGES,
		/** Not a supply; ignored. */
		OTHER
	}

	/** What the tracker needs to know about one item id. */
	@Getter
	static final class ItemInfo
	{
		static final ItemInfo OTHER = new ItemInfo(Category.OTHER, null, 0);

		private final Category category;
		/**
		 * Family tracked in doses (or bites), or {@code null}: a potion's name without the dose suffix, or one key per
		 * full item for food eaten in parts.
		 */
		private final String family;
		/** Doses in one potion item, or bites left in one stage of a multi-bite food; 0 otherwise. */
		private final int doses;
		/**
		 * Item a multi-bite food's bites (or a charged item's charges) are recorded under, or -1 (potions use their
		 * highest-dose variant seen).
		 */
		private final int fullItemId;
		/** Bites (or charges) in one {@link #fullItemId} item, or 0. */
		private final int dosesPerItem;

		ItemInfo(Category category, String family, int doses)
		{
			this(category, family, doses, -1, 0);
		}

		private ItemInfo(Category category, String family, int doses, int fullItemId, int dosesPerItem)
		{
			this.category = Objects.requireNonNull(category);
			this.family = family;
			this.doses = doses;
			this.fullItemId = fullItemId;
			this.dosesPerItem = dosesPerItem;
		}

		static ItemInfo of(Category category)
		{
			return new ItemInfo(category, null, 0);
		}

		static ItemInfo potion(String family, int doses)
		{
			return new ItemInfo(Category.POTION, family, doses);
		}

		/**
		 * One stage of a food eaten in parts: food tracked in bites, in one family per full item, and recorded under the
		 * full item with {@code bitesPerItem} bites per item.
		 */
		static ItemInfo multiBiteFood(int fullItemId, int bitesLeft, int bitesPerItem)
		{
			return new ItemInfo(Category.FOOD, "bites:" + fullItemId, bitesLeft, fullItemId, bitesPerItem);
		}

		/**
		 * One variant of a charged item: tracked in charges, in one family per item type, and recorded under the
		 * highest-charge item {@code fullItemId} with {@code chargesPerItem} charges per item.
		 */
		static ItemInfo charged(int fullItemId, int chargesLeft, int chargesPerItem)
		{
			return new ItemInfo(Category.CHARGES, "charges:" + fullItemId, chargesLeft, fullItemId, chargesPerItem);
		}
	}

	/** Item facts source. Implementations may only be valid on a particular thread (the plugin's: the client thread). */
	interface Classifier
	{
		ItemInfo classify(int itemId);
	}

	/**
	 * Classifies an item from its definition. Rune, ammo and cannonball are decided by the caller (they need lookups
	 * this class cannot do) and take precedence. A teleport tablet has a "Break" action and "teleport" in its name; a
	 * potion is a {@code Name(n)} item with a "Drink" action; food is any other item with an "Eat" or "Drink" action.
	 * Noted items have no inventory actions, so they are never supplies.
	 *
	 * @param name             item name, or {@code null}
	 * @param inventoryActions inventory actions, entries may be {@code null}
	 */
	static ItemInfo classify(String name, String[] inventoryActions, boolean rune, boolean ammo, boolean cannonball)
	{
		return classify(-1, name, inventoryActions, rune, ammo, cannonball);
	}

	/**
	 * Like {@link #classify(String, String[], boolean, boolean, boolean)}, except that some items are classified by
	 * their id first (see {@link #classifiesById}): a stage of a food eaten in parts ({@link #MULTI_BITE_FOOD}) as
	 * {@link ItemInfo#multiBiteFood multi-bite food}, a charged item ({@link #CHARGED_ITEMS}) as
	 * {@link ItemInfo#charged charges}, a {@link #SLAYER_CONSUMABLES Slayer consumable}, and a
	 * {@link #TELEPORT_SCROLLS teleport scroll}.
	 */
	static ItemInfo classify(int itemId, String name, String[] inventoryActions, boolean rune, boolean ammo,
		boolean cannonball)
	{
		final int[] stage = MULTI_BITE_FOOD.get(itemId);
		if (stage != null)
		{
			return ItemInfo.multiBiteFood(stage[0], stage[1], stage[2]);
		}
		final int[] charges = CHARGED_ITEMS.get(itemId);
		if (charges != null)
		{
			return ItemInfo.charged(charges[0], charges[1], charges[2]);
		}
		if (SLAYER_CONSUMABLES.contains(itemId))
		{
			return ItemInfo.of(Category.SLAYER_CONSUMABLE);
		}
		if (TELEPORT_SCROLLS.contains(itemId))
		{
			return ItemInfo.of(Category.TELEPORT_SCROLL);
		}
		if (cannonball)
		{
			return ItemInfo.of(Category.CANNONBALL);
		}
		if (rune)
		{
			return ItemInfo.of(Category.RUNE);
		}
		if (ammo)
		{
			return ItemInfo.of(Category.AMMO);
		}
		if (hasAction(inventoryActions, "Break") && name != null && name.toLowerCase(Locale.ROOT).contains("teleport"))
		{
			return ItemInfo.of(Category.TELEPORT_TABLET);
		}
		final boolean eat = hasAction(inventoryActions, "Eat");
		final boolean drink = hasAction(inventoryActions, "Drink");
		if (drink && name != null)
		{
			final Matcher m = DOSE_NAME.matcher(name.trim());
			if (m.matches())
			{
				final int doses = Integer.parseInt(m.group(2));
				if (doses > 0)
				{
					return ItemInfo.potion(m.group(1).trim(), doses);
				}
			}
		}
		return eat || drink ? ItemInfo.of(Category.FOOD) : ItemInfo.OTHER;
	}

	/**
	 * Whether {@link #classify(int, String, String[], boolean, boolean, boolean)} decides this id from its tables alone
	 * (multi-bite food, charged items, Slayer consumables and teleport scrolls), so the caller needs no other lookups for
	 * it.
	 */
	static boolean classifiesById(int itemId)
	{
		return MULTI_BITE_FOOD.containsKey(itemId) || CHARGED_ITEMS.containsKey(itemId)
			|| SLAYER_CONSUMABLES.contains(itemId) || TELEPORT_SCROLLS.contains(itemId);
	}

	private static boolean hasAction(String[] actions, String action)
	{
		if (actions == null)
		{
			return false;
		}
		for (String a : actions)
		{
			if (a != null && a.equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	/** One tick's view of the tracked containers. Quantities of the same id are summed. */
	static final class Observation
	{
		private final Map<Integer, Long> items = new TreeMap<>();
		@Getter
		private int cannonBalls;

		/** Adds an item stack. Negative ids (empty slots) and non-positive quantities are ignored. */
		Observation add(int itemId, long quantity)
		{
			if (itemId >= 0 && quantity > 0)
			{
				items.merge(itemId, quantity, Long::sum);
			}
			return this;
		}

		/** Cannonballs loaded in the player's cannon (the ROCKTHROWER varp); 0 when none or no cannon. */
		Observation setCannonBalls(int cannonBalls)
		{
			this.cannonBalls = Math.max(0, cannonBalls);
			return this;
		}

		Map<Integer, Long> getItems()
		{
			return Collections.unmodifiableMap(items);
		}
	}

	/** Supplies used on one tick. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	static final class Usage
	{
		static final Usage NONE = new Usage(new ItemTally(), new ItemTally(), Collections.emptyMap());

		private final ItemTally used;
		private final ItemTally returned;
		private final Map<Integer, Integer> doses;

		/**
		 * Items used, by item id. Potions are in doses, keyed by the highest-dose variant seen of their family,
		 * multi-bite food is in bites, keyed by the full item, and charged items are in charges, keyed by the
		 * highest-charge item; see {@link #getDoses()}.
		 */
		ItemTally getUsed()
		{
			return new ItemTally(used);
		}

		/** Ammo and cannonballs that came back (picked up or unloaded), by item id. */
		ItemTally getReturned()
		{
			return new ItemTally(returned);
		}

		/** Doses (bites, charges) per item for every potion, multi-bite food and charged item id in {@link #getUsed()}. */
		Map<Integer, Integer> getDoses()
		{
			return new TreeMap<>(doses);
		}

		boolean isEmpty()
		{
			return used.isEmpty() && returned.isEmpty();
		}
	}

	/** Identifies one tracked quantity: an item id, or a potion or multi-bite food family (in doses or bites). */
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Key
	{
		private final int itemId;
		private final String family;

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Key))
			{
				return false;
			}
			Key k = (Key) o;
			return family != null ? family.equals(k.family) : k.family == null && itemId == k.itemId;
		}

		@Override
		public int hashCode()
		{
			return family != null ? family.hashCode() : Integer.hashCode(itemId);
		}
	}

	private final Classifier classifier;
	/**
	 * Classifications by item id, kept for the tracker's life. Only answers are kept: the classifier returns
	 * {@code null} (asked again on a later update) while an item's definition may still change, that is while a
	 * wieldable item's stats are not loaded or while a members item is seen on a free world, where the game shows a
	 * changed name (see {@link SupplyReader#classifyItem}). A definition read on a members world does not change
	 * while the client runs.
	 */
	private final Map<Integer, ItemInfo> infoCache = new HashMap<>();
	/**
	 * Category of every key seen as a supply. A key not (yet) classified as one has none, so its category is the one it
	 * gets once its data is loaded, even if it was dropped or excluded before.
	 */
	private final Map<Key, Category> keyCategories = new HashMap<>();
	/**
	 * Item each family's use is recorded under, with its doses per item: {doses, item id}. For a potion, the
	 * highest-dose variant seen; for multi-bite food and charged items, the full (highest-charge) item.
	 */
	private final Map<String, int[]> potionVariants = new HashMap<>();

	/** Tracked quantities at the previous update, or {@code null} when a fresh baseline is needed. */
	private Map<Key, Long> baseline;
	private int baselineCannonBalls;
	/** The cannon's ammo at the update before the baseline's, so a pickup split over two ticks can resolve a guess. */
	private int priorCannonBalls;
	/** Cannonball type the cannon's loaded ammo is attributed to; inferred from what the player loads or picks up. */
	@Getter
	private int cannonBallId = CANNONBALL;
	/**
	 * Whether {@link #cannonBallId} comes from a load or pickup this tracker saw. Until then it is only a guess (regular
	 * cannonballs), for example when tracking starts with a cannon already loaded.
	 */
	private boolean cannonBallIdKnown;
	/** Cannonballs counted as used under the guessed type since the last reset; moved to the real type once it shows. */
	private long guessedFired;

	SupplyTracker(Classifier classifier)
	{
		this.classifier = Objects.requireNonNull(classifier);
	}

	/** Forgets the baseline; the next {@link #update} takes a fresh one and counts nothing. */
	void reset()
	{
		baseline = null;
		baselineCannonBalls = 0;
		priorCannonBalls = 0;
		// A correction after a reset could move cannonballs into a session that never counted them.
		guessedFired = 0;
	}

	/** Whether a baseline is held. */
	boolean hasBaseline()
	{
		return baseline != null;
	}

	/**
	 * Compares this tick's containers with the previous tick's and returns what was used. The observation always
	 * becomes the new baseline. Nothing is counted when there was no baseline (first tick, or after {@link #reset()}),
	 * when {@code counting} is false (the session is not running), or when {@code excluded} is true (a bank, shop,
	 * trade or similar interface was open, or the player died).
	 *
	 * @param dropped item ids the player chose "Drop" on recently; decreases of these (and, for a potion, of its whole
	 *                family) are not counted this tick
	 */
	Usage update(Observation observation, boolean counting, boolean excluded, Set<Integer> dropped)
	{
		return update(observation, counting, excluded, dropped, Collections.emptySet());
	}

	/**
	 * Like {@link #update(Observation, boolean, boolean, Set)}, and changes of the {@code ignored} item ids count
	 * neither way this tick: no decrease is used and no increase is returned. Used for the materials of a blowpipe or
	 * trident being loaded, charged or emptied ({@link ChargeExclusions}), which leave or enter the inventory without
	 * being used up.
	 */
	Usage update(Observation observation, boolean counting, boolean excluded, Set<Integer> dropped,
		Set<Integer> ignored)
	{
		final Map<Key, Long> after = new HashMap<>();
		for (Map.Entry<Integer, Long> e : observation.getItems().entrySet())
		{
			final int id = e.getKey();
			final ItemInfo info = info(id);
			if (info.getCategory() == Category.OTHER)
			{
				continue;
			}
			final Key key = key(id, info);
			long quantity = e.getValue();
			if (info.getFamily() != null)
			{
				quantity = saturatedMultiply(quantity, info.getDoses());
			}
			after.merge(key, quantity, SupplyTracker::saturatedAdd);
		}

		final int cannon = observation.getCannonBalls();
		final int previousCannon = baselineCannonBalls;
		// Cannonballs counted under a wrong guess of the loaded type, moved to the type that showed.
		int guessedId = -1;
		long correction = 0;
		if (baseline != null)
		{
			// The cannon's previous load is the type that showed only when this load adds to it or this is its pickup.
			boolean sameLoad = baselineCannonBalls > 0;
			int shown = -1;
			if (cannon > baselineCannonBalls)
			{
				// Loading: attribute the cannon's ammo to the cannonball type that left the inventory.
				shown = largestInventoryChange(after, false);
			}
			else if (!cannonBallIdKnown && cannon == 0 && (baselineCannonBalls > 0 || priorCannonBalls > 0))
			{
				// Picked up or unloaded with the type a guess (on this tick, or the varp a tick before the
				// inventory): the type that came back is the one the cannon held.
				final int returnedId = largestInventoryChange(after, true);
				// Only when more than half of the cannon's last load came back: the cannon may fire between the
				// last load seen and the pickup, so fewer than it held can come back, but a few cannonballs looted
				// on the tick the cannon emptied by firing must not pass for its type.
				final int lastLoad = baselineCannonBalls > 0 ? baselineCannonBalls : priorCannonBalls;
				if (returnedId >= 0 && inventoryChange(after, new Key(returnedId, null)) * 2 > lastLoad)
				{
					shown = returnedId;
					sameLoad = true;
				}
			}
			if (shown >= 0)
			{
				if (!cannonBallIdKnown && shown != cannonBallId && sameLoad)
				{
					// The guess was wrong: the baseline's load, and what it fired, were the shown type all along.
					moveCannonLoad(shown);
					guessedId = cannonBallId;
					correction = guessedFired;
				}
				cannonBallId = shown;
				cannonBallIdKnown = true;
				guessedFired = 0;
			}
			else if (!cannonBallIdKnown && cannon == 0 && baselineCannonBalls == 0 && priorCannonBalls == 0)
			{
				// Empty for three updates without its type showing: what it fired stays under the guess.
				guessedFired = 0;
			}
		}
		if (cannon > 0)
		{
			final Key cannonKey = new Key(cannonBallId, null);
			keyCategories.put(cannonKey, Category.CANNONBALL);
			after.merge(cannonKey, (long) cannon, SupplyTracker::saturatedAdd);
		}

		final Map<Key, Long> before = baseline;
		baseline = after;
		priorCannonBalls = previousCannon;
		baselineCannonBalls = cannon;
		if (before == null || !counting || excluded)
		{
			return Usage.NONE;
		}

		final Set<Key> droppedKeys = new HashSet<>();
		if (dropped != null)
		{
			for (Integer id : dropped)
			{
				if (id != null && id >= 0)
				{
					droppedKeys.add(key(id, info(id)));
				}
			}
		}
		final Set<Key> ignoredKeys = new HashSet<>();
		if (ignored != null)
		{
			for (Integer id : ignored)
			{
				if (id != null && id >= 0)
				{
					ignoredKeys.add(key(id, info(id)));
				}
			}
		}

		final ItemTally used = new ItemTally();
		final ItemTally returned = new ItemTally();
		final Map<Integer, Integer> doses = new TreeMap<>();
		final Set<Key> keys = new HashSet<>(before.keySet());
		keys.addAll(after.keySet());
		keys.removeAll(ignoredKeys);
		for (Key key : keys)
		{
			final long delta = after.getOrDefault(key, 0L) - before.getOrDefault(key, 0L);
			final Category category = keyCategories.getOrDefault(key, Category.OTHER);
			if (delta < 0)
			{
				if (droppedKeys.contains(key))
				{
					continue;
				}
				if (key.family != null)
				{
					final int[] variant = potionVariants.get(key.family);
					used.add(variant[1], -delta);
					doses.put(variant[1], variant[0]);
				}
				else
				{
					used.add(key.itemId, -delta);
					if (!cannonBallIdKnown && key.itemId == cannonBallId)
					{
						// Fired from a cannon whose type is a guess: corrected if its pickup shows another type.
						guessedFired = saturatedAdd(guessedFired, Math.min(-delta, Math.max(0, previousCannon - cannon)));
					}
				}
			}
			else if (delta > 0 && (category == Category.AMMO || category == Category.CANNONBALL))
			{
				returned.add(key.itemId, delta);
			}
		}
		if (correction > 0)
		{
			used.add(cannonBallId, correction);
			returned.add(guessedId, correction);
		}
		return used.isEmpty() && returned.isEmpty() ? Usage.NONE : new Usage(used, returned, doses);
	}

	/** One supply the last {@link #update} saw carried ({@link #carried}). Immutable. */
	@Getter
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	static final class Carried
	{
		/** Its key ({@link #supplyKey}): one per item, or one per potion, multi-bite food or charged item family. */
		private final String key;
		/** The item its use is recorded under: the item, or a family's largest size seen (its full item). */
		private final int itemId;
		private final Category category;
		/** A potion's family (its name without the dose), or {@code null}; internal keys for food and charges. */
		private final String family;
		/** How much is carried: doses, bites or charges for a family, else items. */
		private final long amount;
	}

	/** The key of an item tracked on its own ({@link #supplyKey}). */
	static String itemKey(int itemId)
	{
		return "item:" + itemId;
	}

	/** The key of a potion, multi-bite food or charged item family ({@link #supplyKey}). */
	static String familyKey(String family)
	{
		return "family:" + family;
	}

	/**
	 * The key {@code itemId}'s use and carried amount are summed under: its family's for a potion (every dose size),
	 * food eaten in parts or charged item, else the item's own ({@link #itemKey}), also for an item that is no supply
	 * (the blowpipe's Zulrah's scales). Classifies the item when it hasn't been yet, through the plugin's
	 * {@link Classifier} (so on the client thread).
	 */
	String supplyKey(int itemId)
	{
		final ItemInfo info = info(itemId);
		return info.getFamily() != null ? familyKey(info.getFamily()) : itemKey(itemId);
	}

	/**
	 * What the last {@link #update} saw carried in the tracked containers (the inventory, the worn ammo, weapon and
	 * jewellery slots, Dizana's quiver, the rune pouch and the cannon's loaded cannonballs), per supply: potions in
	 * doses, food eaten in parts in bites and charged items in charges, under their family's recorded item. Empty while
	 * there is no baseline (no task assigned, or the inventory not loaded). For the overlay's supply runway
	 * ({@link SupplyRunway}).
	 */
	List<Carried> carried()
	{
		if (baseline == null || baseline.isEmpty())
		{
			return Collections.emptyList();
		}
		final List<Carried> carried = new ArrayList<>(baseline.size());
		for (Map.Entry<Key, Long> e : baseline.entrySet())
		{
			final Key key = e.getKey();
			final Category category = keyCategories.get(key);
			if (category == null || category == Category.OTHER || e.getValue() <= 0)
			{
				continue;
			}
			if (key.family != null)
			{
				final int[] variant = potionVariants.get(key.family);
				if (variant != null)
				{
					carried.add(new Carried(familyKey(key.family), variant[1], category, key.family, e.getValue()));
				}
			}
			else
			{
				carried.add(new Carried(itemKey(key.itemId), key.itemId, category, null, e.getValue()));
			}
		}
		return carried;
	}

	/**
	 * Classifies the observation's items and notes each potion family's highest-dose variant seen, as {@link #update}
	 * does for every item it sees, without touching the baseline or counting anything. Lets the plugin keep noting the
	 * potions the player holds while no diff runs (no session running), so a potion's use is recorded under the same
	 * item as when every tick was diffed.
	 *
	 * @return {@code false} when an item's data was not loaded yet, so it should be noted again later
	 */
	boolean noteVariants(Observation observation)
	{
		boolean complete = true;
		for (Integer id : observation.getItems().keySet())
		{
			final ItemInfo info = info(id);
			if (info.getCategory() == Category.OTHER)
			{
				// Not cached: the classifier had no answer yet (see info), and asks again next time.
				complete &= infoCache.containsKey(id);
				continue;
			}
			key(id, info);
		}
		return complete;
	}

	/**
	 * The cannonball type whose amount outside the cannon changed most since the baseline, or -1 when none did: the
	 * largest decrease (what was loaded) or, with {@code increase}, the largest increase (what came back from a pickup
	 * or unload).
	 */
	private int largestInventoryChange(Map<Key, Long> after, boolean increase)
	{
		long largest = 0;
		int itemId = -1;
		// Only a key in the baseline can decrease, and only one in after can increase.
		for (Key key : (increase ? after : baseline).keySet())
		{
			if (key.family != null || keyCategories.get(key) != Category.CANNONBALL)
			{
				continue;
			}
			final long change = inventoryChange(after, key);
			final long size = increase ? change : -change;
			if (size > largest)
			{
				largest = size;
				itemId = key.itemId;
			}
		}
		return itemId;
	}

	/**
	 * How much the amount of {@code key} outside the cannon changed since the baseline: positive when it went up. The
	 * baseline's cannon load, held under the current {@link #cannonBallId}, is left out.
	 */
	private long inventoryChange(Map<Key, Long> after, Key key)
	{
		long beforeInventory = baseline.getOrDefault(key, 0L);
		if (key.itemId == cannonBallId)
		{
			// The baseline includes the cannon's previous load under the current type.
			beforeInventory -= baselineCannonBalls;
		}
		return after.getOrDefault(key, 0L) - beforeInventory;
	}

	/** Moves the baseline's cannon load from the guessed {@link #cannonBallId} to {@code itemId}. */
	private void moveCannonLoad(int itemId)
	{
		if (baselineCannonBalls <= 0)
		{
			return;
		}
		baseline.merge(new Key(cannonBallId, null), (long) -baselineCannonBalls, Long::sum);
		baseline.merge(new Key(itemId, null), (long) baselineCannonBalls, Long::sum);
	}

	private ItemInfo info(int itemId)
	{
		ItemInfo info = infoCache.get(itemId);
		if (info == null)
		{
			try
			{
				info = classifier.classify(itemId);
			}
			catch (RuntimeException e)
			{
				info = null;
			}
			if (info == null)
			{
				// Item data not available yet (or the lookup failed): treat as untracked now, classify again later.
				return ItemInfo.OTHER;
			}
			if ((info.getCategory() == Category.POTION || info.getFamily() != null)
				&& (info.getFamily() == null || info.getDoses() <= 0))
			{
				info = ItemInfo.OTHER;
			}
			infoCache.put(itemId, info);
		}
		return info;
	}

	private Key key(int itemId, ItemInfo info)
	{
		final Key key;
		if (info.getFamily() != null)
		{
			key = new Key(-1, info.getFamily());
			if (info.getFullItemId() >= 0)
			{
				potionVariants.putIfAbsent(info.getFamily(), new int[]{info.getDosesPerItem(), info.getFullItemId()});
			}
			else
			{
				final int[] best = potionVariants.get(info.getFamily());
				if (best == null || info.getDoses() > best[0])
				{
					potionVariants.put(info.getFamily(), new int[]{info.getDoses(), itemId});
				}
			}
		}
		else
		{
			key = new Key(itemId, null);
		}
		if (info.getCategory() != Category.OTHER)
		{
			// An item still waiting for its data reads OTHER (not cached, see info), for example when dropped or
			// excluded first: recording that would keep picked-up ammo from ever offsetting it.
			keyCategories.putIfAbsent(key, info.getCategory());
		}
		return key;
	}

	private static long saturatedAdd(long a, long b)
	{
		long sum = a + b;
		return sum < 0 ? Long.MAX_VALUE : sum;
	}

	private static long saturatedMultiply(long a, long b)
	{
		try
		{
			return Math.multiplyExact(a, b);
		}
		catch (ArithmeticException e)
		{
			return Long.MAX_VALUE;
		}
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.util.*;
import java.util.List;
import java.util.function.*;
import javax.swing.*;

/**
 * The header of the live task card (DESIGN_PRINCIPLES.md 3.4): the task's icon (36 by 32) beside its lines.
 * <ol>
 * <li>The task's name in Bold, in the heading colour: {@code Abyssal demons}; a task done on its Catacombs variant or
 * Slayer boss, once the session's kills say so, shows the variant instead: {@code Deviant spectres},
 * {@code Grotesque Guardians}; while the session's Cannon tag is Yes the name ends with {@code (cannon)};
 * boss kills the name doesn't show add {@code + boss}: {@code Cave kraken + boss}. Without a task:
 * {@code No Slayer task.}</li>
 * <li>(while known) the location, in Small: the active session's Slayer spot, else a Konar or Wilderness task's
 * assigned area;</li>
 * <li>(while any part is known) the master, the type when it isn't Regular or Konar (the master already says Konar),
 * the kills left while no session is active (the stats grid shows them while one is: before the first kill, after
 * End task) and the next bonus, in Small: {@code Konar · 201 left · bonus in 3}; its tooltip has each part,
 * the location too, in full.</li>
 * </ol>
 * The lines are cut short with {@code …} when they don't fit the card ({@link FitLabel}); the optional ones are added
 * or removed only when they appear or go, and the icon is asked for only when the task changes. EDT only.
 */
final class TaskBoxView
{
	/** Between the parts of the master line. */
	static final String SEPARATOR = " · ";
	/** The name line without a task (DESIGN_PRINCIPLES.md 3.9). */
	static final String NO_TASK = "No Slayer task.";
	/** The name line before the game has told the plugin the task. */
	static final String WAITING_FOR_GAME = "Waiting for game data";
	/** The task icon's size: an item sprite. */
	static final int ICON_WIDTH = 36;
	static final int ICON_HEIGHT = 32;

	private final LedgerHistoryModel model;
	private final SessionTracker tracker;
	/** The plugin's current task streak, or {@code null} while unknown. */
	private final Supplier<Integer> taskStreak;
	/** Revalidates and repaints the panel after a change. */
	private final Runnable relayout;
	/** Draws the task's icon. */
	private final ItemIcons icons;

	/** The task's icon, 36 by 32; shown while the task has one. */
	private final JLabel iconLabel = new JLabel();
	/** "Abyssal demons", "No Slayer task." or "Waiting for game data". */
	private final FitLabel taskLabel = new FitLabel();
	/** "Catacombs of Kourend"; in {@link #lines} only while known. */
	private final FitLabel locationLabel = new FitLabel();
	/** "Konar · bonus in 3"; in {@link #lines}, after the location, only while some part is known. */
	private final FitLabel detailsLabel = new FitLabel();
	/** The header: the icon, then {@link #lines}. */
	private final JPanel box = new JPanel(new BorderLayout(6, 0));
	/** The name, then (while known) the location and the details. */
	private final JPanel lines = new JPanel();
	/** The details of the current task, as of the last {@link #refreshTask}: whether there is a task, its master etc. */
	private boolean hasTask;
	/** The kills left on the task. */
	private int remaining;
	/** Whether a session is active, so the stats grid shows the kills left and the master line doesn't. */
	private boolean sessionActive;
	private Integer master;
	private TaskType type;
	/** The task's assigned area (Konar, Wilderness), or {@code null}. */
	private String area;
	/** The active session's location name, as of the last {@link #refreshLocation}, or {@code null}. */
	private String liveLocation;
	/** The task whose icon is shown ({@code null}: none), so it is asked for only when the task changes. */
	private String iconTask;
	/** How many times the icon was asked for ({@link #getBuildCount}). */
	private int builds;

	TaskBoxView(LedgerHistoryModel model, SessionTracker tracker, Supplier<Integer> taskStreak, Runnable relayout,
		ItemIcons icons)
	{
		this.model = model;
		this.tracker = tracker;
		this.taskStreak = taskStreak;
		this.relayout = relayout;
		this.icons = icons;
		// Names for tests, which find the rows by them; no visible effect.
		box.setName("taskBox");
		iconLabel.setName("taskBox.icon");
		lines.setName("taskBox.lines");
		taskLabel.setName("taskBox.task");
		locationLabel.setName("taskBox.location");
		detailsLabel.setName("taskBox.details");

		box.setOpaque(false);
		box.setAlignmentX(Component.LEFT_ALIGNMENT);
		Dimension iconSize = new Dimension(ICON_WIDTH, ICON_HEIGHT);
		iconLabel.setPreferredSize(iconSize);
		iconLabel.setMinimumSize(iconSize);
		iconLabel.setMaximumSize(iconSize);
		iconLabel.setHorizontalAlignment(SwingConstants.CENTER);
		iconLabel.setVerticalAlignment(SwingConstants.CENTER);
		iconLabel.setVisible(false);
		box.add(iconLabel, BorderLayout.WEST);

		lines.setOpaque(false);
		lines.setLayout(new BoxLayout(lines, BoxLayout.Y_AXIS));
		taskLabel.setFont(LedgerTheme.boldFont());
		taskLabel.setForeground(LedgerTheme.HEADING);
		locationLabel.setFont(LedgerTheme.smallFont());
		locationLabel.setForeground(LedgerTheme.LABEL);
		detailsLabel.setFont(LedgerTheme.smallFont());
		detailsLabel.setForeground(LedgerTheme.HINT);
		for (FitLabel label : new FitLabel[]{taskLabel, locationLabel, detailsLabel})
		{
			label.setAlignmentX(Component.LEFT_ALIGNMENT);
		}
		lines.add(taskLabel);
		// The lines are centred on the icon's height, and take the width beside it.
		JPanel centred = new JPanel(new GridBagLayout());
		centred.setOpaque(false);
		GridBagConstraints c = new GridBagConstraints();
		c.weightx = 1;
		c.fill = GridBagConstraints.HORIZONTAL;
		centred.add(lines, c);
		box.add(centred, BorderLayout.CENTER);
	}

	/** The header, for the live task card to add first. */
	JPanel getComponent()
	{
		return box;
	}

	/** Shows the task's name, icon and tooltip, then who assigned it, its type and the next bonus. */
	void refreshTask(int remaining, String monster)
	{
		hasTask = remaining > 0;
		this.remaining = remaining;
		sessionActive = tracker.getState().isActive();
		String icon = null;
		if (!tracker.isTaskObserved())
		{
			taskLabel.setText(WAITING_FOR_GAME);
			taskLabel.setToolTipText(null);
		}
		else if (hasTask)
		{
			// The variant the active session's kills say is being done (its Catacombs variant, or Slayer
			// boss), and whether its Cannon tag is Yes: the name its task is saved under; then
			// whether it has boss kills its name doesn't show.
			TaskSelection selection = tracker.getCurrentTaskSelection();
			TaskVariants.Decision decision = tracker.getCurrentVariant();
			String variant = decision.getVariant();
			boolean cannon = Boolean.TRUE.equals(selection.getCannon());
			String boss = decision.isBossKills() && !decision.isVariantBoss()
				? TaskVariants.bossName(decision.getTask()) : null;
			taskLabel.setText(decision.displayName(monster, cannon));
			// A long monster name may not fit the card; the tooltip has it in full.
			taskLabel.setToolTipText("<html>Task: " + LedgerHistory.escapeHtml(monster)
				+ (variant == null ? "" : "<br>Doing: " + LedgerHistory.escapeHtml(variant) + " (from your kills)")
				+ (boss == null ? "" : "<br>Boss kills: " + LedgerHistory.escapeHtml(boss))
				+ (cannon ? "<br>Cannon: Yes, a cannon task" : "")
				+ "<br>Kills left: " + LedgerFormat.kills(remaining) + "</html>");
			// The assigned task's icon, also for a variant or cannon task, as the history rows show it.
			icon = tracker.getCurrentMonster();
		}
		else
		{
			taskLabel.setText(NO_TASK);
			taskLabel.setToolTipText(null);
		}
		refreshIcon(icon);
		TaskContext context = hasTask ? tracker.getCurrentContext() : TaskContext.NONE;
		master = context.getMaster();
		type = hasTask ? context.type(tracker.getCurrentCreatureId()) : null;
		area = type == null ? null : TaskLocation.normalizeName(context.getLocation());
		refreshDetails();
	}

	/** Shows {@code task}'s icon ({@link TaskIcons}), or none; asks for it only when the task changed. */
	private void refreshIcon(String task)
	{
		if (Objects.equals(task, iconTask))
		{
			return;
		}
		iconTask = task;
		Integer itemId = task == null ? null : TaskIcons.itemId(task);
		boolean show = itemId != null;
		iconLabel.setIcon(null);
		if (show)
		{
			builds++;
			icons.apply(iconLabel, itemId, 0);
		}
		if (iconLabel.isVisible() != show)
		{
			iconLabel.setVisible(show);
			relayout.run();
		}
	}

	/**
	 * Takes the active session's location while it is known: the name of the Slayer spot its kills so far decide
	 * ({@link TaskLocation#liveName}: the player's name for its region, asked of the plugin when not known yet,
	 * else the spot table's name). Until then the line shows a Konar or Wilderness task's assigned area.
	 */
	void refreshLocation(SessionTracker.State state)
	{
		String name = null;
		if (state.isActive())
		{
			TaskSpot spot = tracker.getTaskSpot();
			if (spot.getRegion() != null)
			{
				model.requestLocationNames(Collections.singleton(spot.getRegion()));
			}
			name = TaskLocation.liveName(spot, model::locationName, model.spots());
		}
		liveLocation = name;
		refreshDetails();
	}

	/**
	 * Shows the location line and the details line: the known parts of master, type (unless Regular or Konar), the
	 * kills left while no session is active and the next bonus, with each part and the location in full in the
	 * tooltip; each line is in the header only while it has something to say.
	 */
	private void refreshDetails()
	{
		List<String> parts = new ArrayList<>();
		List<String> tooltip = new ArrayList<>();
		if (hasTask)
		{
			String masterName = SlayerMaster.displayName(master);
			if (masterName != null)
			{
				parts.add(masterName);
			}
			if (type != null && type != TaskType.REGULAR && type != TaskType.KONAR)
			{
				parts.add(type.toString());
			}
			tooltip.add("Master: " + LedgerHistory.escapeHtml(masterName == null ? LedgerHistory.NO_VALUE : masterName));
			tooltip.add(LedgerHistory.escapeHtml(LedgerHistory.formatTaskType(type, area)));
			if (!sessionActive)
			{
				// The task's size before the first kill and after End task; while a session is active the stats grid
				// shows it.
				parts.add(LedgerFormat.kills(remaining) + " left");
				tooltip.add("Kills left: " + LedgerFormat.kills(remaining));
			}
		}
		String location = liveLocation != null ? liveLocation : area;
		if (liveLocation != null)
		{
			tooltip.add(LedgerHistory.escapeHtml(TaskLocation.format(liveLocation)));
		}
		Integer streak = taskStreak.get();
		String bonus = StreakMilestone.formatShort(streak);
		if (bonus != null)
		{
			parts.add(bonus);
			tooltip.add(StreakMilestone.format(streak));
		}

		String tip = tooltip.isEmpty() ? null : "<html>" + String.join("<br>", tooltip) + "</html>";
		boolean changed = false;
		if (location != null)
		{
			// A player-typed location must not turn the line into HTML.
			locationLabel.setText(location.regionMatches(true, 0, "<html", 0, 5) ? " " + location : location);
			// A long location may not fit the card; the tooltip has every part in full.
			locationLabel.setToolTipText(tip);
		}
		changed |= showLine(locationLabel, location != null, 1);
		if (!parts.isEmpty())
		{
			detailsLabel.setText(String.join(SEPARATOR, parts));
			detailsLabel.setToolTipText(tip);
		}
		changed |= showLine(detailsLabel, !parts.isEmpty(), lineIndex(locationLabel) + 1);
		if (changed)
		{
			relayout.run();
		}
	}

	/** Where the line after {@code previous} goes: after it while it is shown, else after the name. */
	private int lineIndex(JLabel previous)
	{
		return previous.getParent() == lines ? lines.getComponentZOrder(previous) : 0;
	}

	/** Adds {@code line} at {@code index} or removes it, as {@code show} says; whether it changed. */
	private boolean showLine(JLabel line, boolean show, int index)
	{
		boolean shown = line.getParent() == lines;
		if (shown == show)
		{
			return false;
		}
		if (show)
		{
			lines.add(line, Math.min(index, lines.getComponentCount()));
		}
		else
		{
			lines.remove(line);
		}
		return true;
	}

	/**
	 * How many times the task icon was asked for. Performance seam: tests assert this doesn't grow on the refresh
	 * timer.
	 */
	int getBuildCount()
	{
		return builds;
	}
}

package com.shmayvan.slayerledger;

/**
 * Jad and Zuk tasks (V2 plan 4.1): their only task kill comes at the end of a long run, so being inside the Fight
 * Caves or the Inferno with that task assigned is Running. This tells whether the player is inside the cave of the
 * assigned task. Pure (no RuneLite types).
 *
 * <p>The tasks are recognised by their name, the one the Slayer task DB table gives (as core SlayerPlugin names them
 * in its {@code Task} enum, RuneLite 1.13.4): "TzTok-Jad" and "TzKal-Zuk". These are their own task types, apart from
 * the "Tzhaar" task. The regions are the ones core TimersAndBuffsPlugin checks (RuneLite 1.13.4,
 * {@code FIGHT_CAVES_REGION_ID} and {@code INFERNO_REGION_ID}); both caves are instances, so the region is the one
 * the instance copies, as the plugin reads it for kill locations.</p>
 */
final class TaskCaves
{
	/** The Fight Caves' map region (core TimersAndBuffsPlugin's {@code FIGHT_CAVES_REGION_ID}, RuneLite 1.13.4). */
	static final int FIGHT_CAVES_REGION = 9551;
	/** The Inferno's map region (core TimersAndBuffsPlugin's {@code INFERNO_REGION_ID}, RuneLite 1.13.4). */
	static final int INFERNO_REGION = 9043;
	/** The Jad task's name (core SlayerPlugin's {@code Task.JAD}). */
	static final String JAD_TASK = "TzTok-Jad";
	/** The Zuk task's name (core SlayerPlugin's {@code Task.ZUK}). */
	static final String ZUK_TASK = "TzKal-Zuk";

	private TaskCaves()
	{
	}

	/**
	 * Whether {@code task} is a Jad or Zuk task, whose session restarts when the player goes into its cave (the overlay's
	 * state line says so). Names are compared as {@link #isInside} compares them.
	 */
	static boolean isCaveTask(String task)
	{
		final String name = TaskStatistics.normalize(task);
		return name != null && (name.equals(TaskStatistics.normalize(JAD_TASK))
			|| name.equals(TaskStatistics.normalize(ZUK_TASK)));
	}

	/**
	 * Whether the player, in map region {@code region}, is inside the cave of the task named {@code task}: the Fight
	 * Caves on a Jad task, the Inferno on a Zuk task. Names are compared ignoring capitals and outer spaces.
	 *
	 * @param task   the assigned task's name, or {@code null} when there is none or it is not known yet
	 * @param region the player's map region (an instance's template region), or {@link LocationTally#NO_REGION}
	 */
	static boolean isInside(String task, int region)
	{
		final String name = TaskStatistics.normalize(task);
		if (name == null || !LocationTally.isRegion(region))
		{
			return false;
		}
		if (name.equals(TaskStatistics.normalize(JAD_TASK)))
		{
			return region == FIGHT_CAVES_REGION;
		}
		return name.equals(TaskStatistics.normalize(ZUK_TASK)) && region == INFERNO_REGION;
	}
}

package com.shmayvan.slayerledger;

import net.runelite.client.chat.*;

/**
 * The task-complete chat line ({@code DESIGN_PRINCIPLES.md} 5.2, 5.3), posted for a successfully saved completed task:
 * {@code Dust devils done: 201 kills in 1 h 1 min, +412K. Gz.} Facts first: the task as the history names it
 * ({@link LedgerHistory#monster}: its Catacombs variant or Slayer boss, {@code (cannon)} for a cannon task), its kills,
 * its active time ({@link LedgerFormat#duration}), its profit at the "Loot price" mode ({@link LedgerFormat#signed},
 * {@code ~} before the sign when approximate) and its superiors when any spawned, then {@code Gz.} unless a
 * fastest-task line follows it ({@link FastestTaskMessage}), so only one line carries personality. Plain text, apart
 * from {@link #chatMessage}. Pure (RuneLite's string-only {@link ChatMessageBuilder} only).
 */
final class TaskCompleteMessage
{
	/** The line's one word of personality, after the facts. */
	static final String GZ = "Gz.";

	private TaskCompleteMessage()
	{
	}

	/** {@link #format(LedgerRecord, LootPriceMode, HiddenLoot, boolean)} with nothing hidden and {@link #GZ}. */
	static String format(LedgerRecord record, LootPriceMode mode)
	{
		return format(record, mode, HiddenLoot.NONE, true);
	}

	/**
	 * The line for a completed record in the selected loot price mode, with the loot items {@code hidden} hides left
	 * out of the profit; {@code null} for a partial or missing record. A profit not recorded is left out, as is a
	 * superior count of 0 or not recorded: {@code Wyrms done: 172 kills in 1 h 40 min, ~+2.1M, 3 superiors. Gz.}
	 *
	 * @param gz whether to end with {@link #GZ}
	 */
	static String format(LedgerRecord record, LootPriceMode mode, HiddenLoot hidden, boolean gz)
	{
		if (record == null || !record.isCompleted())
		{
			return null;
		}

		final StringBuilder line = new StringBuilder(head(record)).append(' ')
			.append(LedgerFormat.kills(record.getKills())).append(record.getKills() == 1 ? " kill" : " kills")
			.append(" in ").append(LedgerFormat.duration(record.getActiveMillis()));

		// The record was just saved, so the prices saved with it are today's.
		final HistoryPricing.Values values = HistoryPricing.value(record, mode, null, hidden);
		final Long profit = values.getProfit();
		if (profit != null)
		{
			line.append(", ").append(LedgerFormat.signed(profit, values.isProfitApproximate()));
		}

		final Integer superiors = record.getSuperiorsSpawned();
		// Most tasks have none; "0 superiors" would only make the line longer.
		if (superiors != null && superiors > 0)
		{
			line.append(", ").append(LedgerFormat.kills(superiors)).append(superiors == 1 ? " superior" : " superiors");
		}
		line.append('.');
		if (gz)
		{
			line.append(' ').append(GZ);
		}
		return line.toString();
	}

	/** The line's head, the task as the history names it: {@code Dust devils done:}. */
	static String head(LedgerRecord record)
	{
		return LedgerHistory.monster(record) + " done:";
	}

	/**
	 * A line from {@link #format} as a RuneLite chat message ({@code DESIGN_PRINCIPLES.md} 4.5): its {@link #head} in
	 * the player's chat highlight colour and the rest in the normal one, as the plugin's other chat lines.
	 * {@link ChatMessageBuilder#append(String)} escapes the plain text, so nothing is escaped before and no text goes
	 * through its unescaped {@code append(Color, String)}.
	 */
	static String chatMessage(LedgerRecord record, String line)
	{
		final String head = head(record);
		final ChatMessageBuilder message = new ChatMessageBuilder();
		if (line.startsWith(head))
		{
			message.append(ChatColorType.HIGHLIGHT).append(head).append(ChatColorType.NORMAL)
				.append(line.substring(head.length()));
		}
		else
		{
			message.append(ChatColorType.NORMAL).append(line);
		}
		return message.build();
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * Who assigned a task and what completing it gave: the raw SLAYER_MASTER and SLAYER_AREA values, the area's name, and
 * (for a completed task) the Slayer points earned and the streak afterwards. Every part is {@code null} when unknown.
 * Immutable; pure (no RuneLite types). The task's {@link TaskType} is derived from it, see {@link #type(Integer)}.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
final class TaskContext
{
	static final TaskContext NONE = new TaskContext(null, null, null, null, null);

	/** SLAYER_MASTER value, or {@code null} when unknown. */
	private final Integer master;
	/** SLAYER_AREA value, or {@code null} when the task has no area (or it is unknown). */
	private final Integer area;
	/** The area's name, or {@code null}. */
	private final String location;
	/** Slayer points the completion gave, or {@code null} when unknown or not trusted. */
	private final Integer pointsEarned;
	/** The streak the completion raised, as it stood afterwards, or {@code null} when unknown. */
	private final Integer taskStreak;

	/**
	 * The assignment as read from the game.
	 *
	 * @param master   SLAYER_MASTER value; {@link SlayerMaster#NONE} or less is unknown
	 * @param area     SLAYER_AREA value (Konar's location); 0 or less is none
	 * @param location the area's name, or {@code null} when there is none or the lookup failed
	 */
	static TaskContext assignment(int master, int area, String location)
	{
		final boolean hasArea = area > 0;
		return of(master > SlayerMaster.NONE ? master : null, hasArea ? area : null,
			hasArea && location != null && !location.isEmpty() ? location : null, null, null);
	}

	/** A context from stored values ({@code null} for each unknown part); {@link #NONE} when all are unknown. */
	static TaskContext of(Integer master, Integer area, String location, Integer pointsEarned, Integer taskStreak)
	{
		if (master == null && area == null && location == null && pointsEarned == null && taskStreak == null)
		{
			return NONE;
		}
		return new TaskContext(master, area, location, pointsEarned, taskStreak);
	}

	/** This context with the completion's points earned and streak (each {@code null} when not trusted). */
	TaskContext withRewards(Integer newPointsEarned, Integer newTaskStreak)
	{
		return of(master, area, location, newPointsEarned, newTaskStreak);
	}

	/**
	 * This context with the assignment parts it doesn't know yet taken from {@code later}, a later reading of the same
	 * task's assignment: the master once its varbit has synced, the area, or the area's name once its lookup worked.
	 * Known parts are kept.
	 */
	TaskContext fillAssignment(TaskContext later)
	{
		if (later == null)
		{
			return this;
		}
		final Integer newMaster = master != null ? master : later.master;
		Integer newArea = area;
		String newLocation = location;
		if (area == null && later.area != null)
		{
			newArea = later.area;
			newLocation = later.location;
		}
		else if (area != null && location == null && area.equals(later.area))
		{
			newLocation = later.location;
		}
		return of(newMaster, newArea, newLocation, pointsEarned, taskStreak);
	}

	/** The task's type for the given creature key; see {@link TaskType#of}. */
	TaskType type(Integer creatureId)
	{
		return TaskType.of(master, creatureId);
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.*;
import java.util.*;

/**
 * The icon of each Slayer task: the item whose sprite RuneLite's core Slayer plugin shows for the task in its
 * infobox (mostly the Slayer-guide pictures, {@code ItemID.SLAYERGUIDE_*}; boss tasks show their pet). Overall totals
 * draws it before a monster's name ({@link OverallTotalsSection}).
 *
 * <p>The table is the bundled {@code task-icons.json} ({@link BundledData}), a copy of the core plugin's
 * {@code net.runelite.client.plugins.slayer.Task} enum (task name and {@code itemSpriteId}) in RuneLite 1.13.4, BSD
 * 2-Clause (the notice is in the file and in {@code LICENSE}). That enum and its {@code getTask} are package-private,
 * so a Plugin Hub plugin can't call them without reflection, which the hub forbids; {@code TaskIconsTest} checks the
 * copy against the enum (by reflection, test code only), so a RuneLite update that changes it fails the build.</p>
 *
 * <p>Names are matched by {@link TaskStatistics#normalize}. Pass the task's assigned name
 * ({@link LedgerRecord#getMonster}): a Catacombs variant or cannon group's name is no task name and has no icon here.
 * Pure (the ids are gameval {@code ItemID} values, plain ints).</p>
 */
final class TaskIcons
{
	/** Item id of each task's icon, by normalized task name. */
	private static final Map<String, Integer> ICONS = BundledData.load("task-icons.json", TaskIcons::read,
		Collections.emptyMap());

	private TaskIcons()
	{
	}

	/**
	 * The item id whose sprite is {@code taskName}'s icon, or {@code null} for a name that is no known task (blank,
	 * {@code null}, a Catacombs variant or cannon group name, or a task newer than the table).
	 */
	static Integer itemId(String taskName)
	{
		String key = TaskStatistics.normalize(taskName);
		return key == null ? null : ICONS.get(key);
	}

	private static Map<String, Integer> read(JsonObject root)
	{
		final Map<String, Integer> map = new HashMap<>();
		for (JsonElement row : root.getAsJsonArray("tasks"))
		{
			final JsonObject task = row.getAsJsonObject();
			map.put(TaskStatistics.normalize(task.get("task").getAsString()), task.get("id").getAsInt());
		}
		return Collections.unmodifiableMap(map);
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;
import lombok.*;

/**
 * Rules for a task's location name: how a typed name is cleaned up and which name the panel shows. A task's
 * location is its Slayer spot ({@link SlayerSpots}, decided from its kills); the name shown is, in order, the player's
 * own name for the task ({@link LedgerRecord#getLocation}, "Edit location"), the player's name for its map region (kept
 * per RuneScape profile: named in 1.x, or an unlisted region renamed since; not for a region several spots share,
 * {@link #spotName}), the spot table's name ("Region N" for an unlisted region), and a Konar or Wilderness task's
 * assigned area when its spot is Unknown. Names never decide the spot: tasks group by spot id. Pure (no RuneLite
 * types).
 */
final class TaskLocation
{
	/** Longest location name kept, in characters; longer names are cut. */
	static final int MAX_NAME_LENGTH = 40;
	/** Shown for a record without a location (older records without a region). */
	static final String UNKNOWN = "Unknown";

	private TaskLocation()
	{
	}

	/**
	 * A location name as stored: cleaned up like a note ({@link TaskNote#normalize(String, int)}: whitespace runs become
	 * one space, the ends are trimmed) and cut to {@link #MAX_NAME_LENGTH} characters.
	 *
	 * @return the name, or {@code null} when nothing is left (an empty name is never stored)
	 */
	static String normalizeName(String raw)
	{
		return TaskNote.normalize(raw, MAX_NAME_LENGTH);
	}

	/**
	 * The location a history row shows ({@link #recordLocation}), or {@link #UNKNOWN}.
	 *
	 * @param regionNames region id to the player's name for it, {@code null} when unnamed or not known yet
	 */
	static String displayName(LedgerRecord record, IntFunction<String> regionNames, SlayerSpots spots)
	{
		final String name = recordLocation(record, regionNames, spots);
		return name != null ? name : UNKNOWN;
	}

	/**
	 * A saved record's location name: its own name (the player's for this task; a 1.x record's name as saved), else
	 * its spot's name ({@link #spotName}: its region's name, else the table's), else its assigned area (an older Konar
	 * or Wilderness record with no spot). The spot is {@link SlayerSpots#recordSpot}: the stored one, or for a record
	 * saved before spots, its region's.
	 *
	 * @return the name, or {@code null} when none is known (never {@link #UNKNOWN})
	 */
	static String recordLocation(LedgerRecord record, IntFunction<String> regionNames, SlayerSpots spots)
	{
		final String own = normalizeName(record.getLocation());
		if (own != null)
		{
			return own;
		}
		final SlayerSpots table = spots == null ? SlayerSpots.NONE : spots;
		final String spot = spotName(table.recordSpot(record), record.getLocationRegion(), regionNames, table);
		return spot != null ? spot : normalizeName(record.getTaskLocation());
	}

	/**
	 * The location a Task history row shows on its second line: {@link #recordLocation}'s name, with
	 * the spot table's short name ({@link SlayerSpots#shortName}, "Catacombs") in place of its full name ("Catacombs
	 * of Kourend") when that is the name shown. A name the player gave (the task's own, or its region's) is shown as
	 * given; the row cuts a long one short and its tooltip has the full location.
	 *
	 * @return the name, or {@code null} when none is known
	 */
	static String shortName(LedgerRecord record, IntFunction<String> regionNames, SlayerSpots spots)
	{
		final String name = recordLocation(record, regionNames, spots);
		if (name == null || spots == null)
		{
			return name;
		}
		final String spot = spots.recordSpot(record);
		if (spot == null || !name.equals(normalizeName(spots.name(spot))))
		{
			return name;
		}
		final String shortName = spots.shortName(spot);
		return shortName != null ? shortName : name;
	}

	/**
	 * A spot's name without a task's own name: the player's name for {@code region} (one they gave it in 1.x, or the
	 * name of an unlisted region they renamed), else the table's name of {@code spotKey} ({@link SlayerSpots#name}:
	 * "Region N" for an unlisted region). The region's name is used only for a region with at most one spot in the
	 * table (V2 plan 4.5), or for the Unknown spot, which has no table name: a 1.x name for a region several spots share
	 * (Kraken Cove and its boss room, Karuulm and the Hydra's lair) can't tell which of them it meant, so each of them
	 * shows its table name.
	 *
	 * @param spotKey the spot key, or {@code null} for the Unknown spot
	 * @param region  the region the task was saved with or is decided from, or {@code null}
	 * @return the name, or {@code null} when neither is known
	 */
	static String spotName(String spotKey, Integer region, IntFunction<String> regionNames, SlayerSpots spots)
	{
		final SlayerSpots table = spots == null ? SlayerSpots.NONE : spots;
		if (region != null && LocationTally.isRegion(region) && regionNames != null
			&& (spotKey == null || table.spotsInRegion(region).size() <= 1))
		{
			final String named = normalizeName(regionNames.apply(region));
			if (named != null)
			{
				return named;
			}
		}
		return spots == null ? null : normalizeName(spots.name(spotKey));
	}

	/**
	 * The live session's location: the name of its spot ({@link #spotName} of its {@link TaskSpot}).
	 *
	 * @param spot the session's spot so far ({@link TaskSpot#UNKNOWN} with no kill tallied)
	 * @return the name, or {@code null} while unknown
	 */
	static String liveName(TaskSpot spot, IntFunction<String> regionNames, SlayerSpots spots)
	{
		return spot == null ? null : spotName(spot.getSpotId(), spot.getRegion(), regionNames, spots);
	}

	/**
	 * The current task's location, for same-location estimates (by spot): the active session's
	 * spot, named as {@link #liveName} names it; else its assigned area (Konar, Wilderness), with the spot the table
	 * gives that name ({@link SlayerSpots#spotNamed}, none when it has no such spot); else the spot the player is in
	 * now, named as {@link #spotName} names it. A session whose spot is Unknown (a shared region its kills don't decide)
	 * is passed over like no session.
	 *
	 * @param sessionSpot   the active session's spot, or {@link TaskSpot#UNKNOWN}
	 * @param currentRegion the region the player is in now, or {@link LocationTally#NO_REGION}
	 * @param currentSpot   the spot the player is in now, or {@code null}
	 * @return the location; {@link Here#UNKNOWN} while neither is known
	 */
	static Here current(String taskLocation, TaskSpot sessionSpot, int currentRegion, String currentSpot,
		IntFunction<String> regionNames, SlayerSpots spots)
	{
		final SlayerSpots table = spots == null ? SlayerSpots.NONE : spots;
		if (sessionSpot != null && sessionSpot.getSpotId() != null)
		{
			return new Here(sessionSpot.getSpotId(), liveName(sessionSpot, regionNames, table));
		}
		final String area = normalizeName(taskLocation);
		if (area != null)
		{
			return new Here(table.spotNamed(area), area);
		}
		return new Here(currentSpot, spotName(currentSpot, LocationTally.isRegion(currentRegion) ? currentRegion : null,
			regionNames, table));
	}

	/**
	 * Where the current task is, for the same-location statistics (the live card's time left and the overlay's pace):
	 * its spot key ({@link SlayerSpots}), which the saved tasks are matched by ({@link SlayerSpots#recordSpot}), and
	 * its name, which the time left's tooltip shows. Immutable; compares by value, so it can be part of a cache key.
	 */
	@Value
	static class Here
	{
		/** No location known: every task counts. */
		static final Here UNKNOWN = new Here(null, null);

		/** The spot key, or {@code null} when no spot is known (then no task is matched by location). */
		String spot;
		/**
		 * The name the time left's tooltip shows ("from 1 completed task at Smoke Dungeon"), or {@code null} when none
		 * is known.
		 */
		String name;

		/** Whether tasks can be matched by location: the spot and its name are known. */
		boolean isKnown()
		{
			return spot != null && name != null;
		}
	}

	/**
	 * A location name as names are compared: {@link #normalizeName}d and lower case, so names that differ only in
	 * case or spacing are the same place.
	 *
	 * @return the key, or {@code null} for no name
	 */
	static String matchKey(String name)
	{
		final String normalized = normalizeName(name);
		return normalized == null ? null : normalized.toLowerCase(Locale.ROOT);
	}

	/** The location line of the live task box and the history tooltip: {@code Location: Smoke Dungeon}. */
	static String format(String name)
	{
		return "Location: " + (name == null ? UNKNOWN : name);
	}

	/** The question of the history's "Edit location" dialog. */
	static String editPrompt(LedgerRecord record)
	{
		final int creatureId = record.getCreatureId() == null ? SessionTracker.NO_CREATURE : record.getCreatureId();
		return "Location of this " + LedgerRecord.displayName(record.getMonster(), creatureId)
			+ " task only (empty to remove its own name):";
	}

	/** The question of the history's "Rename place" dialog, for an unlisted region ({@link SlayerSpots#regionKey}). */
	static String renamePrompt(int region)
	{
		return "Name of " + SlayerSpots.regionName(region) + ", for every task there:";
	}
}

package com.shmayvan.slayerledger;

import java.util.*;

/**
 * Rules for the free-text note on a task (for example "Barrage" or "Prayer gear"): how a typed note is cleaned up and
 * which notes the panel offers for reuse. Pure; no RuneLite, Swing or file access.
 */
final class TaskNote
{
	/** Longest note kept, in characters; longer notes are cut. */
	static final int MAX_LENGTH = 60;
	/** Most notes offered in the recent-notes list. */
	static final int MAX_RECENT = 8;
	/** Notes offered before (and after) the player's own, so common labels are spelled the same way every time. */
	static final List<String> DEFAULTS = Collections.unmodifiableList(Arrays.asList(
		"Prayer gear", "Strength gear", "Barrage", "Range pray", "Cannon"));

	private TaskNote()
	{
	}

	/**
	 * The note as stored: control characters become spaces, runs of whitespace become one space, the ends are trimmed
	 * and it is cut to {@link #MAX_LENGTH} characters (never in the middle of a surrogate pair).
	 *
	 * @return the note, or {@code null} when nothing is left (or {@code raw} is {@code null})
	 */
	static String normalize(String raw)
	{
		return normalize(raw, MAX_LENGTH);
	}

	/**
	 * {@link #normalize(String)} with another length limit, for other short player-typed labels (for example
	 * {@link TaskLocation#normalizeName location names}).
	 *
	 * @param maxLength longest result kept, in characters
	 */
	static String normalize(String raw, int maxLength)
	{
		if (raw == null)
		{
			return null;
		}
		StringBuilder sb = new StringBuilder(Math.min(raw.length(), maxLength + 1));
		boolean pendingSpace = false;
		for (int i = 0; i < raw.length(); )
		{
			int cp = raw.codePointAt(i);
			i += Character.charCount(cp);
			if (Character.isISOControl(cp) || Character.isWhitespace(cp) || Character.isSpaceChar(cp)
				|| Character.getType(cp) == Character.FORMAT)
			{
				// Separators become one space between words; format characters (e.g. zero-width) are dropped too.
				pendingSpace |= Character.getType(cp) != Character.FORMAT;
				continue;
			}
			int extra = (pendingSpace && sb.length() > 0 ? 1 : 0) + Character.charCount(cp);
			if (sb.length() + extra > maxLength)
			{
				break;
			}
			if (pendingSpace && sb.length() > 0)
			{
				sb.append(' ');
			}
			pendingSpace = false;
			sb.appendCodePoint(cp);
		}
		return sb.length() == 0 ? null : sb.toString();
	}

	/**
	 * Notes to offer for reuse: the distinct notes of the given records, newest first, then the {@link #DEFAULTS}, at
	 * most {@link #MAX_RECENT}. Notes differing only in case count once, with the newest record's spelling.
	 */
	static List<String> recentNotes(Collection<LedgerRecord> records)
	{
		List<String> notes = new ArrayList<>();
		for (LedgerRecord r : LedgerHistory.sortNewestFirst(records))
		{
			notes.add(r.getNote());
		}
		return recentNotes(notes);
	}

	/**
	 * Like {@link #recentNotes(Collection)}, from notes already ordered newest first. Each is normalized; empty and
	 * {@code null} ones are skipped.
	 */
	static List<String> recentNotes(List<String> newestFirst)
	{
		List<String> result = new ArrayList<>(MAX_RECENT);
		Set<String> seen = new HashSet<>();
		addDistinct(newestFirst, result, seen);
		addDistinct(DEFAULTS, result, seen);
		return result;
	}

	private static void addDistinct(List<String> notes, List<String> result, Set<String> seen)
	{
		for (String raw : notes)
		{
			if (result.size() >= MAX_RECENT)
			{
				return;
			}
			String note = normalize(raw);
			if (note != null && seen.add(note.toLowerCase(Locale.ROOT)))
			{
				result.add(note);
			}
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * The advisor's plan for the current task (V2 plan 6), as {@link TaskPlanner} works it out from the player's
 * completed tasks: the options (the task's setups, grouped by spot, boss variant, cannon and style), the recommendation
 * and the creature-level "All setups" summary. Item names and spot names are not part of it: the plan is worked out off
 * the EDT and the names are asked for where it is shown. Immutable; pure (no RuneLite types).
 */
@Value
@Builder(access = AccessLevel.PRIVATE)
@AllArgsConstructor(access = AccessLevel.PRIVATE)
class TaskPlan
{
	/** The task's name as given ({@link LedgerRecord#displayName}), or {@code null} when unknown. */
	String task;
	/**
	 * The task's creature key as asked for ({@link TaskPlanner.Request#getCreatureId}); with {@link #getTask},
	 * {@link #getTaskType} and {@link #getArea} the assignment the plan is for ({@link #isFor}).
	 */
	int creatureId;
	/** The task's type as asked for ({@link TaskPlanner.Request#getTaskType}), or {@code null} when unknown. */
	TaskType taskType;
	/** The name of the task's assigned area as asked for (Konar's, {@link TaskPlanner.Request#getArea}), or null. */
	String area;
	/**
	 * The kills the plan is for: the kills left; 0 or less when they are unknown ({@link #hasKillsLeft}), and the plan
	 * is then per kill.
	 */
	int killsLeft;
	/** Every completed task of the creature, the ones left out of the options included. */
	Summary allSetups;
	/**
	 * The options, fastest first ({@link TaskPlanner#ORDER}): every option, or on a task with an assigned area
	 * that names a spot ({@link #getAreaSpot}) the options at that spot, unless none is there
	 * ({@link #isAreaFallback}). Unmodifiable.
	 */
	List<Option> options;
	/** The creature's completed tasks in no option because their spot or style is Unknown. */
	int excludedTasks;
	/**
	 * The spot the task's assigned area names ({@link SlayerSpots#spotNamed}: Konar's area, where the kills must be
	 * made), which the options are limited to; {@code null} without an area or a spot of its name.
	 */
	String areaSpot;
	/**
	 * Whether no option is at {@link #getAreaSpot}, so the options are every option instead; noted, since the history
	 * then has no task done where the kills count.
	 */
	boolean areaFallback;
	/** The fastest option (see {@link TaskPlanner}), or {@code null} without options. */
	Option recommendation;
	/**
	 * Whether this is a Wilderness task's plan with no completed Wilderness task of the creature, though it has other
	 * completed tasks (which a Wilderness task doesn't use, {@link TaskPlanner}): the card says "no completed
	 * Wilderness tasks yet" ({@link TaskPlanText#noHistoryLine}). Only ever true for a plan without history ({@link #hasHistory}).
	 */
	boolean wildernessHistoryMissing;

	/**
	 * A plan for {@code request}'s assignment with no completed task of the creature: no options and an "All setups"
	 * of 0 tasks; {@code wildernessHistoryMissing} says whether it is a Wilderness task's whose creature has completed
	 * tasks, just none in the Wilderness ({@link #isWildernessHistoryMissing}).
	 */
	static TaskPlan empty(TaskPlanner.Request request, int killsLeft, boolean wildernessHistoryMissing)
	{
		return builder()
			.task(request.getTask())
			.creatureId(request.getCreatureId())
			.taskType(request.getTaskType())
			.area(request.getArea())
			.killsLeft(killsLeft)
			.allSetups(Summary.NONE)
			.options(Collections.emptyList())
			.recommendation(null)
			.wildernessHistoryMissing(wildernessHistoryMissing)
			.build();
	}

	/** A plan for {@code request}'s assignment; {@link TaskPlanner} makes the options list unmodifiable. */
	static TaskPlan of(TaskPlanner.Request request, int killsLeft, Summary allSetups, List<Option> options,
		int excludedTasks, String areaSpot, boolean areaFallback, Option recommendation)
	{
		return builder()
			.task(request.getTask())
			.creatureId(request.getCreatureId())
			.taskType(request.getTaskType())
			.area(request.getArea())
			.killsLeft(killsLeft)
			.allSetups(allSetups == null ? Summary.NONE : allSetups)
			.options(options)
			.excludedTasks(excludedTasks)
			.areaSpot(areaSpot)
			.areaFallback(areaFallback)
			.recommendation(recommendation)
			.build();
	}

	/**
	 * Whether the plan has any completed task of the creature to work from; {@code false} for the plan that says "no
	 * completed tasks yet". The kills left don't matter: unknown, the plan is per kill ({@link #hasKillsLeft}).
	 */
	boolean hasHistory()
	{
		return allSetups.getTasks() > 0;
	}

	/**
	 * Whether this is a plan of the assignment given: the same creature key, name, type and assigned area. Its kills
	 * left, records and prices may differ (the kept plan {@link LedgerViews#plan} shows while the current one is
	 * worked out).
	 */
	boolean isFor(int creatureId, String task, TaskType taskType, String area)
	{
		return this.creatureId == creatureId && Objects.equals(this.task, task) && this.taskType == taskType
			&& Objects.equals(this.area, area);
	}

	/**
	 * Whether the kills left are known (more than 0). Without them nothing is scaled to them: each {@link Time} is for
	 * one kill (the median per kill), and nothing is to bring.
	 */
	boolean hasKillsLeft()
	{
		return killsLeft > 0;
	}

	/**
	 * Whether the recommendation is based on fewer than {@link TaskPlanner#MIN_TASKS} tasks: no option had that many,
	 * so it is the option with the most ({@link TaskPlanText#basedOn}).
	 */
	boolean isRecommendationThin()
	{
		return recommendation != null && recommendation.getTasks() < TaskPlanner.MIN_TASKS;
	}

	/**
	 * The time for the kills left: the median time per kill of the tasks ({@link TaskPlanner#percentile}) times the
	 * kills left; for one kill when the kills left are unknown ({@link #hasKillsLeft}). Immutable.
	 */
	@Value
	static class Time
	{
		/** The median time per kill, rounded to the millisecond. */
		long perKillMillis;
		/** The median time per kill times the kills left. */
		long millis;
	}

	/** The creature-level "All setups" line: its completed tasks and their time. Immutable. */
	@Value
	static class Summary
	{
		/** No completed task. */
		static final Summary NONE = new Summary(0, null);

		/** The completed tasks: the sample size n. */
		int tasks;
		/** Their time for the kills left, or {@code null} without tasks. */
		Time time;
	}

	/**
	 * One thing to bring: a supply in whole items for the kills left (potions, multi-bite food and charged items in
	 * whole items, not doses, bites or charges), keyed by the item id as tallied; a potion kept under several ids (its
	 * family, {@link TaskPlanner.Request#getPotionFamilies}) by the one with the most doses. Immutable.
	 */
	@Value
	static class BringItem
	{
		int itemId;
		/** Whole items. */
		long quantity;
		/** The quantity at today's GE unit price, or {@code null} without one; for the order. */
		Long value;
	}

	/**
	 * One option: the completed tasks of the creature with the same spot, boss variant, effective cannon and effective
	 * style ({@link SetupTags}), and what they say about doing the kills left that way. Immutable; built by
	 * {@link TaskPlanner}.
	 */
	@Value
	@Builder
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static class Option
	{
		/** The spot key ({@link SlayerSpots}: a table id or {@code region:N}); never the Unknown spot. */
		String spot;
		/**
		 * Whether the tasks' variant is the task's Slayer boss (most kills were the boss), for example the Grotesque
		 * Guardians on a gargoyle task.
		 */
		boolean boss;
		/** The effective cannon of the tasks. */
		boolean cannon;
		/** The effective style of the tasks; never {@link SetupStyle#UNKNOWN}. */
		SetupStyle style;
		/** Whether some task's cannon is an estimate (a migrated task). */
		boolean cannonEstimated;
		/** Whether some task's style is an estimate (a migrated task). */
		boolean styleEstimated;
		/** How many of the tasks had a kill of the task's Slayer boss ({@link TaskVariants#hasBossKills}); shown. */
		int bossKillTasks;
		/** The completed tasks: the sample size n. */
		int tasks;
		/** The time for the kills left. */
		Time time;
		/**
		 * What to bring, most valuable first: at most {@link TaskPlanner#MAX_BRING_ITEMS}; none when the kills left are
		 * unknown. Unmodifiable.
		 */
		List<BringItem> bring;
		/**
		 * The bring items past the first {@link TaskPlanner#MAX_BRING_ITEMS}, in the same order: "+N more", listed in
		 * its tooltip. Unmodifiable; empty unless there are more.
		 */
		@Builder.Default
		List<BringItem> bringRest = Collections.emptyList();

		/** How many bring items are past the first {@link TaskPlanner#MAX_BRING_ITEMS}: the N of "+N more". */
		int getBringMore()
		{
			return bringRest.size();
		}

		/** Whether the option carries the "estimated" mark: some task's cannon or style is an estimate. */
		boolean isEstimated()
		{
			return cannonEstimated || styleEstimated;
		}
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;
import net.runelite.client.util.*;

/**
 * The advisor plan's words (V2 plan 6, {@code DESIGN_PRINCIPLES.md} section 5): the estimated times and paces,
 * the thin-data and no-history phrases, and the advisor card's text (its title, option names and rows,
 * and the Konar and Wilderness notes), so {@link AdvisorCardSection} has no wording of its own. Plain text; the card
 * escapes what it puts in HTML. Straight quotes, no em dashes, {@code ~} before every estimate. Pure (RuneLite's
 * static {@link QuantityFormatter} only).
 */
final class TaskPlanText
{
	/** The card's note when the plan has tasks but no option: every task's spot or style is Unknown. */
	static final String SETUP_UNKNOWN = "Setup unknown for these tasks.";

	private TaskPlanText()
	{
	}

	/**
	 * An estimated time, rounded to the minute (at least 1): {@code ~24 min}, from 60 minutes {@code ~1 h 5 min}, and
	 * {@code ~2 h} on the hour.
	 */
	static String estimatedTime(long millis)
	{
		final long minutes = Math.max(1, (Math.max(0, millis) + 30_000) / 60_000);
		if (minutes < 60)
		{
			return LedgerHistory.APPROXIMATE + minutes + " min";
		}
		final long rest = minutes % 60;
		return LedgerHistory.APPROXIMATE + minutes / 60 + " h" + (rest == 0 ? "" : " " + rest + " min");
	}

	/**
	 * An estimated pace ({@code DESIGN_PRINCIPLES.md} 5.5), rounded to the second (at least 1): {@code ~0:12/kill},
	 * from an hour {@code ~1:02:05/kill}.
	 */
	static String estimatedPace(long millis)
	{
		final long seconds = Math.max(1, (Math.max(0, millis) + 500) / 1_000);
		final long hours = seconds / 3_600;
		final long minutes = seconds / 60 % 60;
		final String clock = hours > 0 ? String.format(Locale.ROOT, "%d:%02d:%02d", hours, minutes, seconds % 60)
			: String.format(Locale.ROOT, "%d:%02d", minutes, seconds % 60);
		return LedgerHistory.APPROXIMATE + clock + "/kill";
	}

	/** {@code based on 1 task} or {@code based on 2 tasks}: what a thin recommendation is labelled with. */
	static String basedOn(int tasks)
	{
		return "based on " + tasks(tasks);
	}

	/** {@code No completed Dust devils tasks yet, so no estimate.}: the advisor with no history. */
	static String noHistory(String task)
	{
		return "No completed " + (task == null ? "" : task + " ") + "tasks yet, so no estimate.";
	}

	/**
	 * An option's time ({@code ~60 min}): for the kills left ({@link #estimatedTime}), or its pace ({@code ~0:12/kill},
	 * {@link #estimatedPace}) with them unknown ({@code perKill}).
	 */
	static String time(TaskPlan.Time time, boolean perKill)
	{
		return perKill ? estimatedPace(time.getPerKillMillis()) : estimatedTime(time.getMillis());
	}

	/** {@code 1 task} or {@code 3 tasks}. */
	static String tasks(int tasks)
	{
		return tasks + (tasks == 1 ? " task" : " tasks");
	}

	// ---- The advisor card (DESIGN_PRINCIPLES.md 3.5) ----

	/**
	 * The card's title, what the plan is based on: {@code Based on 6 Dust devils tasks}, {@code Based on 1 Dust devils
	 * task}, or without a name {@code Based on 6 tasks}.
	 *
	 * @param task  the task's name as shown, or {@code null}
	 * @param tasks the plan's sample size (its All setups tasks)
	 */
	static String cardTitle(String task, int tasks)
	{
		return "Based on " + tasks + (task == null ? "" : " " + task) + (tasks == 1 ? " task" : " tasks");
	}

	/**
	 * The card's one line without history ({@link TaskPlan#hasHistory} false): {@link #noHistory}, or for a Wilderness
	 * task whose creature has completed tasks, none of them in the Wilderness
	 * ({@link TaskPlan#isWildernessHistoryMissing}), {@code No completed Wilderness Abyssal demons tasks yet, so no
	 * estimate.}
	 */
	static String noHistoryLine(String task, TaskPlan plan)
	{
		return plan.isWildernessHistoryMissing() ? noHistory(task == null ? "Wilderness" : "Wilderness " + task)
			: noHistory(task);
	}

	/**
	 * A Konar task's note when no option is at its assigned area's spot, so every option is shown
	 * ({@link TaskPlan#isAreaFallback}): {@code No completed tasks in Catacombs yet, so all areas are used.}
	 *
	 * @param area the area's spot as shown ({@link #shortSpotName}), or {@code null}
	 */
	static String areaFallback(String area)
	{
		return "No completed tasks in " + (area == null ? "the assigned area" : area) + " yet, so all areas are used.";
	}

	/**
	 * An option's name on the card, its setup and spot: {@code Barrage, Catacombs}, {@code Cannon, melee, Smoke
	 * Dungeon}, and for an option done on the task's Slayer boss its name first, {@code Grotesque Guardians, melee,
	 * Slayer Tower}. No {@code ~}: the card says {@code estimated} beside the sample size ({@link #optionTasks}).
	 *
	 * @param task        the task's name, for its Slayer boss ({@link TaskVariants#bossName})
	 * @param regionNames the player's names for map regions, {@code null} when unknown
	 */
	static String optionName(TaskPlan.Option option, String task, SlayerSpots spots, IntFunction<String> regionNames)
	{
		final String style = option.getStyle().getLabel();
		String setup = option.isCannon() ? "Cannon, " + style.toLowerCase(Locale.ROOT) : style;
		if (option.isBoss())
		{
			final String boss = task == null ? null : TaskVariants.bossName(task);
			setup = (boss == null ? "Boss" : boss) + ", " + setup.substring(0, 1).toLowerCase(Locale.ROOT)
				+ setup.substring(1);
		}
		return setup + ", " + shortSpotName(option.getSpot(), spots, regionNames);
	}

	/**
	 * An option's sample size on the card: {@code 3 tasks}, {@code 1 task}, and {@code 3 tasks, estimated} when some
	 * task's cannon or style is an estimate ({@link TaskPlan.Option#isEstimated}, a migrated 1.x task); for a thin
	 * recommendation ({@link TaskPlan#isRecommendationThin}: {@code thin}) {@code based on 1 task} ({@link #basedOn}),
	 * {@code based on 1 task, estimated} (V2 plan 6, DESIGN_PRINCIPLES.md 3.5).
	 */
	static String optionTasks(TaskPlan.Option option, boolean thin)
	{
		return (thin ? basedOn(option.getTasks()) : tasks(option.getTasks()))
			+ (option.isEstimated() ? ", estimated" : "");
	}

	/** The bring items past the grid's 8: {@code +3 more}. */
	static String bringMore(int more)
	{
		return "+" + more + " more";
	}

	/**
	 * A bring item's tooltip lines, plain text: its full name, the amount for the kills left and, when priced, its
	 * value at today's GE price: {@code Prayer potion(4)}, {@code Bring: 6}, {@code GE value: 54,000 gp}.
	 */
	static List<String> bringTooltip(String name, long quantity, Long value)
	{
		final List<String> lines = new ArrayList<>();
		lines.add(name);
		lines.add("Bring: " + QuantityFormatter.formatNumber(quantity));
		if (value != null)
		{
			lines.add("GE value: " + LedgerHistory.formatGpExact(value));
		}
		return lines;
	}

	/**
	 * One line of the {@code +N more} label's tooltip, plain text: a bring item past the grid's 8, its icon tooltip's
	 * lines ({@link #bringTooltip}) on one line: {@code Soul rune, Bring: 20, GE value: 3,000 gp}.
	 */
	static String bringMoreLine(String name, long quantity, Long value)
	{
		return String.join(", ", bringTooltip(name, quantity, value));
	}

	/** The All setups line's label: {@code All setups (6 tasks)}. */
	static String allSetups(TaskPlan.Summary summary)
	{
		return "All setups (" + tasks(summary.getTasks()) + ")";
	}

	/**
	 * {@code text} broken into lines at spaces, each as many words as fit {@code width} as {@code measure} measures
	 * them (the card's sentences, in its font): {@code No completed Abyssal demons tasks yet,} / {@code so no
	 * estimate.} A word wider than {@code width} has a line of its own, which the card cuts short.
	 */
	static List<String> wrap(String text, int width, ToIntFunction<String> measure)
	{
		return wrap(text, width, width, Integer.MAX_VALUE, measure);
	}

	/**
	 * {@code text} broken into at most {@code maxLines} lines at spaces: the first as many words as fit
	 * {@code firstWidth}, each later one as many as fit {@code width}, as {@code measure} measures them (the card's
	 * title and option names, which have two lines: an option's name wraps beside its sample size first,
	 * {@code Cannon, melee, Smoke} / {@code Dungeon}). The last line allowed holds the rest of the text, which the card
	 * cuts short with {@code …} when it doesn't fit, its tooltip holding the whole. A word wider than its line has a
	 * line of its own.
	 */
	static List<String> wrap(String text, int firstWidth, int width, int maxLines, ToIntFunction<String> measure)
	{
		final List<String> lines = new ArrayList<>();
		String line = "";
		for (String word : text.trim().split(" +"))
		{
			final String longer = line.isEmpty() ? word : line + " " + word;
			final boolean last = lines.size() >= maxLines - 1;
			if (line.isEmpty() || last || measure.applyAsInt(longer) <= (lines.isEmpty() ? firstWidth : width))
			{
				line = longer;
			}
			else
			{
				lines.add(line);
				line = word;
			}
		}
		if (!line.isEmpty())
		{
			lines.add(line);
		}
		return lines;
	}

	/**
	 * A spot's short name for narrow places: the table's short name ({@link SlayerSpots#shortName}), or for an unlisted
	 * region's spot the player's name for the region (cut to {@link SlayerSpots#MAX_SHORT_NAME_LENGTH} characters),
	 * else {@code Region N}. A key the table doesn't know is shown as it is.
	 */
	static String shortSpotName(String spotKey, SlayerSpots spots, IntFunction<String> regionNames)
	{
		final Integer region = SlayerSpots.keyRegion(spotKey);
		if (region != null && regionNames != null)
		{
			final String named = TaskLocation.normalizeName(regionNames.apply(region));
			if (named != null)
			{
				return named.length() > SlayerSpots.MAX_SHORT_NAME_LENGTH
					? named.substring(0, SlayerSpots.MAX_SHORT_NAME_LENGTH).trim() : named;
			}
		}
		final String name = (spots == null ? SlayerSpots.NONE : spots).shortName(spotKey);
		if (name != null)
		{
			return name;
		}
		return region != null ? SlayerSpots.regionName(region) : spotKey;
	}
}

package com.shmayvan.slayerledger;

import java.math.*;
import java.util.*;
import lombok.*;

/**
 * The advisor's planner (V2 plan 5 and 6): from the player's completed tasks of the current task's creature, how
 * to do the kills left, how long it takes and what to bring. Pure: no client, Swing or file access, so the plugin can
 * work it out off the EDT from an immutable snapshot ({@link Request}).
 *
 * <p><b>Pool.</b> The samples are the records that are completed, not partial, with kills and active time
 * ({@link TaskStatistics#isTaskSample}) and of the current task's creature ({@link TaskStatistics#isSample}: by
 * creature key, or by name for a record or task without one), every version pooled. Boss tasks are their own pool: a
 * boss task's plan uses only boss-task records, any other task's only the others. A Wilderness task's (Krystilia's)
 * plan uses only Wilderness tasks ({@link TaskType#of} the record's master and creature key), since its kills count
 * only in the Wilderness.</p>
 *
 * <p><b>Options.</b> The samples are grouped by spot ({@link SlayerSpots#recordSpot}), whether their variant is the
 * task's Slayer boss (most kills were the boss: {@link LedgerRecord#getVariant} names the boss of
 * {@link TaskVariants#bossName}), the effective cannon and the effective style ({@link SetupTags#of}). An estimated
 * value groups under its own value, and the option carries the estimated mark. A sample with an Unknown spot or style
 * is in no option; it counts only in the "All setups" summary. The boss flag ({@link TaskVariants#hasBossKills}) is
 * reported per option and doesn't split them. A task with an assigned area (Konar's, whose kills
 * count only there) keeps only the options at the spot the area names ({@link SlayerSpots#spotNamed}); with none
 * there it keeps them all and the plan notes it ({@link TaskPlan#isAreaFallback}), and an area naming no spot keeps
 * them all.</p>
 *
 * <p><b>Each option</b> has its sample size n; the time for the kills left (the median time per kill of its tasks
 * times the kills left: {@link #percentile}); and what to bring: per item, the {@value #BRING_PERCENTILE}th percentile
 * of its use per kill over the tasks with supply data ({@link #hasSupplyData}; a task that didn't use it counts 0),
 * times the kills left, rounded up to whole items, potions from doses, multi-bite food from bites and charged items
 * from charges ({@link LedgerRecord#getSupplyDoses}), a potion's ids of one family as one item
 * ({@link Request#getPotionFamilies}).
 * The items are sorted most valuable first (at today's GE price; unpriced last, then by amount and id) and cut to
 * {@value #MAX_BRING_ITEMS}, with the rest kept apart ({@link TaskPlan.Option#getBringRest}). With the kills left
 * unknown (0 or less) nothing is scaled to them: the times are for one kill and nothing is to bring
 * ({@link TaskPlan#hasKillsLeft}).</p>
 *
 * <p><b>Recommendation.</b> The fastest option ({@link #ORDER}: least time for the kills left) among those with at
 * least {@value #MIN_TASKS} tasks; with none, the option with the most tasks, ties broken by time, which the plan marks
 * thin ({@link TaskPlan#isRecommendationThin}). With no samples the plan is {@link TaskPlan#empty}, which for a
 * Wilderness task notes when the creature has other completed tasks ({@link TaskPlan#isWildernessHistoryMissing}).</p>
 */
final class TaskPlanner
{
	/** Tasks an option needs to be chosen on its time alone. */
	static final int MIN_TASKS = 3;
	/** Bring items a plan shows before "+N more". */
	static final int MAX_BRING_ITEMS = 8;
	/** The percentile of the use per kill each bring amount is from: a safe amount, not an average one. */
	static final int BRING_PERCENTILE = 80;

	private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);
	/**
	 * Below any fraction of an item the records can give, above the rounding of {@link MathContext#DECIMAL128}: a whole
	 * amount worked out as 71.000...01 is 71, not 72.
	 */
	private static final BigDecimal ROUNDING_SLACK = new BigDecimal("1e-20");
	private static final BigDecimal LONG_MAX = BigDecimal.valueOf(Long.MAX_VALUE);

	/** The options' last tie-break, so the order never depends on the records' order: spot, boss, cannon, style. */
	private static final Comparator<TaskPlan.Option> KEY_ORDER = Comparator
		.comparing(TaskPlan.Option::getSpot)
		.thenComparing(TaskPlan.Option::isBoss)
		.thenComparing(TaskPlan.Option::isCannon)
		.thenComparing(TaskPlan.Option::getStyle);

	/**
	 * The options' order: least time for the kills left first (Fastest finish); ties by more tasks, then the option's
	 * key.
	 */
	static final Comparator<TaskPlan.Option> ORDER = Comparator
		.<TaskPlan.Option>comparingLong(option -> option.getTime().getMillis())
		.thenComparing(Comparator.comparingInt(TaskPlan.Option::getTasks).reversed())
		.thenComparing(KEY_ORDER);

	private TaskPlanner()
	{
	}

	/**
	 * What the planner works from, captured where the plan is asked for: the current task, the kills left, the records
	 * (not changed by the planner) and today's prices, as {@link LedgerViews}' background views capture them.
	 * Immutable once built (the records collection and the prices map must not change while the plan is worked out).
	 * Set the creature key: the builder's default, 0, is a creature.
	 */
	@Value
	@Builder
	static class Request
	{
		/**
		 * The task's creature key ({@link SessionTracker#creatureKey}; boss tasks below
		 * {@link SessionTracker#NO_CREATURE}), or {@link SessionTracker#NO_CREATURE} to match by name.
		 */
		int creatureId;
		/** The task's name. */
		String task;
		/**
		 * The task's type, or {@code null} when unknown; {@link TaskType#BOSS} picks the boss pool and
		 * {@link TaskType#WILDERNESS} only Wilderness tasks.
		 */
		TaskType taskType;
		/**
		 * The kills left; 0 or less when unknown ({@link SessionTracker#UNKNOWN_AMOUNT}), and the plan is then per kill
		 * ({@link TaskPlan#hasKillsLeft}).
		 */
		int killsLeft;
		/**
		 * The name of the task's assigned area (Konar's, {@link TaskContext#getLocation}), whose spot the options are
		 * limited to; {@code null} for none.
		 */
		String area;
		Collection<LedgerRecord> records;
		/** Today's GE unit prices ({@link HistoryPricing}), which value the bring items; {@code null} is none. */
		Map<Integer, Long> prices;
		/** The spot table; {@code null} is {@link SlayerSpots#NONE}. */
		SlayerSpots spots;
		/**
		 * Each potion id's family, its name without the dose suffix ({@link #potionFamilies}), so a potion a record
		 * keeps under two ids (its key moved to a higher-dose variant mid-session, {@link SupplyTracker}) is one bring
		 * item; {@code null} is none, every id on its own.
		 */
		Map<Integer, String> potionFamilies;
	}

	/** The plan for {@code request} (see the class rules); {@link TaskPlan#empty} with no samples. */
	static TaskPlan plan(Request request)
	{
		final int kills = request.getKillsLeft();
		final boolean wilderness = request.getTaskType() == TaskType.WILDERNESS;
		final List<LedgerRecord> samples = samples(request, wilderness);
		if (samples.isEmpty())
		{
			// A Wilderness task whose creature has only other tasks: said so, not "no completed tasks".
			return TaskPlan.empty(request, kills, wilderness && !samples(request, false).isEmpty());
		}
		// With the kills left unknown, the times are for one kill.
		final int scaleKills = kills > 0 ? kills : 1;
		final SlayerSpots spots = request.getSpots() == null ? SlayerSpots.NONE : request.getSpots();
		final Map<Integer, Long> prices = request.getPrices() == null ? Collections.emptyMap() : request.getPrices();

		final Map<OptionKey, List<LedgerRecord>> groups = new LinkedHashMap<>();
		int excluded = 0;
		for (LedgerRecord record : samples)
		{
			final String spot = spots.recordSpot(record);
			final SetupTags tags = SetupTags.of(record);
			if (spot == null || tags.getStyle() == SetupStyle.UNKNOWN)
			{
				// Counted in All setups only (V2 plan 5).
				excluded++;
				continue;
			}
			groups.computeIfAbsent(new OptionKey(spot, isBossVariant(record), tags.isCannon(), tags.getStyle()),
				key -> new ArrayList<>()).add(record);
		}

		List<TaskPlan.Option> options = new ArrayList<>();
		for (Map.Entry<OptionKey, List<LedgerRecord>> group : groups.entrySet())
		{
			options.add(option(group.getKey(), group.getValue(), kills, request, prices));
		}
		options.sort(ORDER);

		// An assigned area (Konar's): its kills count only there, so only the options at its spot, when there are any.
		final String areaSpot = areaSpot(request.getArea(), spots);
		boolean areaFallback = false;
		if (areaSpot != null)
		{
			final List<TaskPlan.Option> there = new ArrayList<>();
			for (TaskPlan.Option option : options)
			{
				if (areaSpot.equals(option.getSpot()))
				{
					there.add(option);
				}
			}
			if (there.isEmpty())
			{
				areaFallback = !options.isEmpty();
			}
			else
			{
				options = there;
			}
		}

		return TaskPlan.of(request, kills, new TaskPlan.Summary(samples.size(), time(samples, scaleKills)),
			Collections.unmodifiableList(options), excluded, areaSpot, areaFallback, pick(options));
	}

	/**
	 * The spot assigned area {@code area} names ({@link SlayerSpots#spotNamed}), or {@code null} for no area or no spot
	 * of its name.
	 */
	private static String areaSpot(String area, SlayerSpots spots)
	{
		return area == null || area.trim().isEmpty() ? null : spots.spotNamed(area);
	}

	/**
	 * Whether {@code record} says what supplies it used: it recorded some, or it was saved by 2.0, which stores
	 * none when nothing was used. A 1.x record without supplies is unknown, since 1.x also saved none when its supply
	 * counting had stopped, and that empty list is what made such a task's Magic XP Barrage when it was migrated
	 * ({@link SetupMigration#barrageRunes}). A migrated record's schema version reads 3 in memory and once the file is
	 * next written, so it is told by its estimated cannon tag, which only {@link SetupMigration} sets.
	 */
	static boolean hasSupplyData(LedgerRecord record)
	{
		if (record.getSupplies() != null)
		{
			return true;
		}
		return record.getSchemaVersion() >= SetupMigration.MIGRATED_VERSION
			&& !Boolean.TRUE.equals(record.getCannonEstimated());
	}

	/**
	 * The best of {@code options} in {@link #ORDER} among those with at least {@link #MIN_TASKS} tasks; with none, the
	 * one with the most tasks, ties in {@link #ORDER}. {@code null} for no options.
	 */
	private static TaskPlan.Option pick(List<TaskPlan.Option> options)
	{
		TaskPlan.Option best = null;
		for (TaskPlan.Option option : options)
		{
			if (option.getTasks() >= MIN_TASKS && (best == null || ORDER.compare(option, best) < 0))
			{
				best = option;
			}
		}
		if (best != null)
		{
			return best;
		}
		final Comparator<TaskPlan.Option> mostTasks = Comparator.comparingInt(TaskPlan.Option::getTasks).reversed()
			.thenComparing(ORDER);
		for (TaskPlan.Option option : options)
		{
			if (best == null || mostTasks.compare(option, best) < 0)
			{
				best = option;
			}
		}
		return best;
	}

	/**
	 * The request's samples (see the class rules), in the records' order; Wilderness tasks only when
	 * {@code wilderness}.
	 */
	private static List<LedgerRecord> samples(Request request, boolean wilderness)
	{
		final List<LedgerRecord> samples = new ArrayList<>();
		if (request.getRecords() == null)
		{
			return samples;
		}
		final boolean boss = request.getTaskType() == TaskType.BOSS
			|| request.getCreatureId() < SessionTracker.NO_CREATURE;
		for (LedgerRecord record : request.getRecords())
		{
			if (TaskStatistics.isTaskSample(record)
				&& TaskStatistics.isSample(record, request.getCreatureId(), request.getTask())
				&& isBossTask(record) == boss
				&& (!wilderness || isWildernessTask(record)))
			{
				samples.add(record);
			}
		}
		return samples;
	}

	/** Whether the record is a Wilderness task: Krystilia's ({@link TaskType#of} its master and creature key). */
	private static boolean isWildernessTask(LedgerRecord record)
	{
		return TaskType.of(record.getSlayerMaster(), record.getCreatureId()) == TaskType.WILDERNESS;
	}

	private static boolean isBossTask(LedgerRecord record)
	{
		return record.getCreatureId() != null && record.getCreatureId() < SessionTracker.NO_CREATURE;
	}

	/**
	 * Whether the record's variant is its task's Slayer boss: most of its kills were the boss ({@link TaskVariants}),
	 * for example a gargoyle task done on the Grotesque Guardians.
	 */
	static boolean isBossVariant(LedgerRecord record)
	{
		final String boss = TaskStatistics.normalize(TaskVariants.bossName(record.getMonster()));
		return boss != null && boss.equals(TaskStatistics.normalize(record.getVariant()));
	}

	private static TaskPlan.Option option(OptionKey key, List<LedgerRecord> tasks, int kills, Request request,
		Map<Integer, Long> prices)
	{
		boolean cannonEstimated = false;
		boolean styleEstimated = false;
		int bossKillTasks = 0;
		for (LedgerRecord record : tasks)
		{
			final SetupTags tags = SetupTags.of(record);
			cannonEstimated |= tags.isCannonEstimated();
			styleEstimated |= tags.isStyleEstimated();
			if (TaskVariants.hasBossKills(record))
			{
				bossKillTasks++;
			}
		}
		// Unknown kills left: nothing to bring, and the time of one kill.
		final List<TaskPlan.BringItem> bring = kills > 0 ? bring(tasks, kills, prices, request.getPotionFamilies())
			: Collections.emptyList();
		// The grid's items; the rest are "+N more".
		final int shown = Math.min(MAX_BRING_ITEMS, bring.size());
		final int scaleKills = kills > 0 ? kills : 1;
		return TaskPlan.Option.builder()
			.spot(key.spot)
			.boss(key.boss)
			.cannon(key.cannon)
			.style(key.style)
			.cannonEstimated(cannonEstimated)
			.styleEstimated(styleEstimated)
			.bossKillTasks(bossKillTasks)
			.tasks(tasks.size())
			.time(time(tasks, scaleKills))
			.bring(Collections.unmodifiableList(new ArrayList<>(bring.subList(0, shown))))
			.bringRest(Collections.unmodifiableList(new ArrayList<>(bring.subList(shown, bring.size()))))
			.build();
	}

	/** The time for {@code kills} kills from {@code tasks}' times per kill (see {@link TaskPlan.Time}). */
	static TaskPlan.Time time(List<LedgerRecord> tasks, int kills)
	{
		final List<BigDecimal> perKill = new ArrayList<>(tasks.size());
		for (LedgerRecord record : tasks)
		{
			perKill.add(BigDecimal.valueOf(Math.max(0, record.getActiveMillis()))
				.divide(BigDecimal.valueOf(record.getKills()), MathContext.DECIMAL128));
		}
		Collections.sort(perKill);
		final BigDecimal median = percentile(perKill, 50);
		return new TaskPlan.Time(round(median), round(median.multiply(BigDecimal.valueOf(kills))));
	}

	/**
	 * What to bring for {@code kills} kills from {@code tasks} (see the class rules), every item, sorted most valuable
	 * first. Only tasks with supply data count ({@link #hasSupplyData}). The ids of one potion family
	 * ({@code families}: id to family, {@code null} for none) are one item: a task's doses of them all, in potions of
	 * the family's id with the most doses (the lower id on a tie), which the item is keyed and priced by.
	 */
	static List<TaskPlan.BringItem> bring(List<LedgerRecord> tasks, int kills, Map<Integer, Long> prices,
		Map<Integer, String> families)
	{
		final List<LedgerRecord> withSupplies = new ArrayList<>();
		final Map<Object, Line> lines = new LinkedHashMap<>();
		for (LedgerRecord record : tasks)
		{
			if (!hasSupplyData(record))
			{
				continue;
			}
			withSupplies.add(record);
			if (record.getSupplies() == null)
			{
				continue;
			}
			for (Map.Entry<Integer, Long> item : record.getSupplies().entrySet())
			{
				if (item.getKey() != null && item.getValue() != null && item.getValue() > 0)
				{
					final int id = item.getKey();
					final int perItem = perItem(record, id);
					final Object key = lineKey(id, families);
					final Line line = lines.get(key);
					if (line == null)
					{
						lines.put(key, new Line(id, perItem));
					}
					else
					{
						line.offer(id, perItem);
					}
				}
			}
		}
		final List<TaskPlan.BringItem> items = new ArrayList<>();
		final BigDecimal killsLeft = BigDecimal.valueOf(kills);
		for (Map.Entry<Object, Line> line : lines.entrySet())
		{
			final List<BigDecimal> perKill = new ArrayList<>(withSupplies.size());
			for (LedgerRecord record : withSupplies)
			{
				perKill.add(itemsPerKill(record, line.getKey(), line.getValue(), families));
			}
			Collections.sort(perKill);
			final long quantity = toLong(percentile(perKill, BRING_PERCENTILE).multiply(killsLeft)
				.subtract(ROUNDING_SLACK).setScale(0, RoundingMode.CEILING));
			if (quantity <= 0)
			{
				continue;
			}
			final int id = line.getValue().itemId;
			final Long price = prices.get(id);
			items.add(new TaskPlan.BringItem(id, quantity, price == null || price <= 0 ? null
				: toLong(BigDecimal.valueOf(price).multiply(BigDecimal.valueOf(quantity)))));
		}
		items.sort(Comparator
			.comparing(TaskPlan.BringItem::getValue, Comparator.nullsLast(Comparator.reverseOrder()))
			.thenComparing(Comparator.comparingLong(TaskPlan.BringItem::getQuantity).reversed())
			.thenComparingInt(TaskPlan.BringItem::getItemId));
		return items;
	}

	/**
	 * The bring line of supply {@code id}: its potion family's name when {@code families} has one, else the id itself.
	 * A name and an id are never equal, and an id is either always in a family or never, so no two lines share an item.
	 */
	private static Object lineKey(int id, Map<Integer, String> families)
	{
		final String family = families == null ? null : families.get(id);
		return family == null ? (Object) id : family;
	}

	/** Doses (bites, charges) in one item of {@code id} as the record counts it, or 1 for one counted in items. */
	private static int perItem(LedgerRecord record, int id)
	{
		final Integer perItem = record.getSupplyDoses() == null ? null : record.getSupplyDoses().get(id);
		return perItem != null && perItem > 1 ? perItem : 1;
	}

	/**
	 * Whole items of line {@code key} the record used per kill: for one id, its doses, bites or charges divided by the
	 * count in one item ({@link LedgerRecord#getSupplyDoses}), else its items; for a potion family, the doses of all
	 * its ids divided by the doses in one potion of the line's item. 0 when it used none.
	 */
	private static BigDecimal itemsPerKill(LedgerRecord record, Object key, Line line, Map<Integer, String> families)
	{
		final Map<Integer, Long> supplies = record.getSupplies();
		if (supplies == null || record.getKills() <= 0)
		{
			return BigDecimal.ZERO;
		}
		long used = 0;
		int perItem = line.perItem;
		if (key instanceof Integer)
		{
			final Long quantity = supplies.get(key);
			used = quantity == null ? 0 : quantity;
			perItem = perItem(record, (Integer) key);
		}
		else
		{
			for (Map.Entry<Integer, Long> item : supplies.entrySet())
			{
				if (item.getKey() != null && item.getValue() != null && item.getValue() > 0
					&& key.equals(lineKey(item.getKey(), families)))
				{
					used = saturatedAdd(used, item.getValue());
				}
			}
		}
		if (used <= 0)
		{
			return BigDecimal.ZERO;
		}
		final long divisor = (long) record.getKills() * perItem;
		return BigDecimal.valueOf(used).divide(BigDecimal.valueOf(divisor), MathContext.DECIMAL128);
	}

	/**
	 * The potion families of the potions {@code records} used, for {@link Request#getPotionFamilies}: each id a record
	 * counts in doses ({@link LedgerRecord#getSupplyDoses}; not the bites or charges of {@link ItemDetails#doseUnit})
	 * whose name {@code names} knows, to that name without its dose suffix ({@link ItemDetails#displayName}), lower
	 * case, as {@link SupplyTracker} names a potion's family: "Prayer potion(4)" and "Prayer potion(3)" are both
	 * "prayer potion" ({@link ItemDetails#potionFamily}, which the supplies grids merge by too). Worked out where
	 * item names are known; an id whose name is unknown stays on its own.
	 */
	static Map<Integer, String> potionFamilies(Collection<LedgerRecord> records, ItemDetails.ItemNames names)
	{
		final Map<Integer, String> families = new HashMap<>();
		if (records == null || names == null)
		{
			return families;
		}
		for (LedgerRecord record : records)
		{
			if (record == null || record.getSupplyDoses() == null)
			{
				continue;
			}
			for (Integer id : record.getSupplyDoses().keySet())
			{
				if (id == null || families.containsKey(id))
				{
					continue;
				}
				final String family = ItemDetails.potionFamily(id, names);
				if (family != null)
				{
					families.put(id, family);
				}
			}
		}
		return families;
	}

	/**
	 * The {@code percent}th percentile of {@code sorted} (ascending), by linear interpolation between the closest
	 * ranks: the rank is {@code (n - 1) * percent / 100}, so with one value every percentile is it, the 50th of an even
	 * count
	 * is the mean of the middle two, and the 20th of 5 values lies 80% of the way from the lowest to the second.
	 *
	 * @return the percentile, or {@code null} for no values
	 */
	static BigDecimal percentile(List<BigDecimal> sorted, int percent)
	{
		final int n = sorted.size();
		if (n == 0)
		{
			return null;
		}
		final BigDecimal rank = BigDecimal.valueOf((long) (n - 1) * percent).divide(HUNDRED);
		final int lower = rank.intValue();
		final BigDecimal fraction = rank.subtract(BigDecimal.valueOf(lower));
		final BigDecimal low = sorted.get(lower);
		if (fraction.signum() == 0 || lower + 1 >= n)
		{
			return low;
		}
		return low.add(sorted.get(lower + 1).subtract(low).multiply(fraction));
	}

	private static long round(BigDecimal value)
	{
		return toLong(value.setScale(0, RoundingMode.HALF_UP));
	}

	/** A whole {@code value} as a long, saturating at the {@code long} range. */
	private static long toLong(BigDecimal value)
	{
		if (value.compareTo(LONG_MAX) > 0)
		{
			return Long.MAX_VALUE;
		}
		return value.signum() < 0 && value.compareTo(BigDecimal.valueOf(Long.MIN_VALUE)) < 0 ? Long.MIN_VALUE
			: value.longValue();
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** One bring line's item: an id, or a potion family's id with the most doses in a potion (on a tie the lower). */
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class Line
	{
		private int itemId;
		/** Doses (bites, charges) in one item of {@link #itemId}, 1 for an item counted whole. */
		private int perItem;

		/** Takes {@code id} as the item when it holds more doses in one item, or as many with a lower id. */
		private void offer(int id, int dosesPerItem)
		{
			if (dosesPerItem > perItem || dosesPerItem == perItem && id < itemId)
			{
				itemId = id;
				perItem = dosesPerItem;
			}
		}
	}

	/** What splits the options: spot, boss variant, effective cannon and effective style. */
	@EqualsAndHashCode
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	private static final class OptionKey
	{
		private final String spot;
		private final boolean boss;
		private final boolean cannon;
		private final SetupStyle style;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * Works out what a task completion gave: the Slayer points earned (the SLAYER_POINTS varbit, 4068) and the streak the
 * completion raised. Read on the same settled ticks as {@link CompletionSignal}. Pure (no RuneLite types) and not
 * thread-safe; the plugin uses it on the client thread only.
 *
 * <p>Points earned are the change from the reading just before the completion tick to the latest reading. Points
 * spent earlier in the task don't matter, since the baseline is the last reading before the completion. The change
 * is followed after the completion tick ({@link #startCompletion}, {@link #earned}) while the completed session is
 * held for late loot, in case the points arrive a tick after the streak counter. It is {@code null}, never negative,
 * when it can't be trusted:</p>
 * <ul>
 *     <li>there is no reading before the completion: the first reading after {@link #reset()} (after login, a world
 *     hop or a lost connection) only sets the baseline, as it does for {@link CompletionSignal}, so a login resync is
 *     never counted;</li>
 *     <li>the points went down (spent on the completion tick or just after).</li>
 * </ul>
 */
final class TaskRewards
{
	/** Reading before the latest, or {@code null}. */
	private Integer previous;
	/** Latest reading, or {@code null} after {@link #reset()}. */
	private Integer latest;
	/** Session whose completion is being followed, or {@code null} when none is. */
	@Getter
	private String sessionId;
	/** Points before the followed completion, or {@code null} when unknown. */
	private Integer completionBaseline;
	/** Streak after the followed completion, or {@code null} when unknown. */
	private Integer completionStreak;

	/** Forgets every reading and stops following. */
	void reset()
	{
		previous = null;
		latest = null;
		stopFollowing();
	}

	/** Records this settled tick's SLAYER_POINTS reading. Call once per settled tick, before {@link #startCompletion}. */
	void update(int points)
	{
		previous = latest;
		latest = points;
	}

	/**
	 * Starts following a completion signalled on this tick.
	 *
	 * @param completedSessionId the completed session
	 * @param counters           this tick's completion counters (as passed to {@link CompletionSignal#update})
	 * @param incrementedCounter {@link CompletionSignal#incrementedCounter()} for this tick
	 */
	void startCompletion(String completedSessionId, int[] counters, int incrementedCounter)
	{
		sessionId = completedSessionId;
		completionBaseline = previous;
		completionStreak = streakAfter(counters, incrementedCounter);
	}

	/** Whether a completion is being followed. */
	boolean isFollowing()
	{
		return sessionId != null;
	}

	/** Points earned by the followed completion as of the latest reading, or {@code null}; see the class comment. */
	Integer earned()
	{
		return isFollowing() ? pointsEarned(completionBaseline, latest) : null;
	}

	/** Streak after the followed completion, or {@code null}. */
	Integer streak()
	{
		return isFollowing() ? completionStreak : null;
	}

	/** Stops following the completion (it has been saved, or can no longer be updated). */
	void stopFollowing()
	{
		sessionId = null;
		completionBaseline = null;
		completionStreak = null;
	}

	/** {@code after - before}, or {@code null} when either is unknown or the points went down. */
	static Integer pointsEarned(Integer before, Integer after)
	{
		if (before == null || after == null || after < before)
		{
			return null;
		}
		return after - before;
	}

	/**
	 * The streak a completion raised: the counter that went up, as it stands now, or {@code null} when it is not
	 * known which counter that was.
	 */
	static Integer streakAfter(int[] counters, int incrementedCounter)
	{
		if (counters == null || incrementedCounter < 0 || incrementedCounter >= counters.length)
		{
			return null;
		}
		return counters[incrementedCounter];
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Which of a task's records the current task's statistics use, on two independent dimensions:
 * <ul>
 * <li>the version: any (the standard monster and its Catacombs variant pooled, as before variants were told
 * apart), only the standard monster's, or only one variant's;</li>
 * <li>the cannon: any (tasks with and without a cannon pooled), only cannon tasks, or only tasks without one
 * ({@link CannonTasks}).</li>
 * </ul>
 * Immutable; compares by value so it can be part of a cache key. Pure (no RuneLite types).
 */
@Getter
@AllArgsConstructor(access = AccessLevel.PRIVATE)
final class TaskSelection
{
	/** Every record of the task, whichever version and with or without a cannon. */
	static final TaskSelection ANY = new TaskSelection(true, null, null);
	/** Only records of the standard monster (no {@link LedgerRecord#getVariant variant}), with or without a cannon. */
	static final TaskSelection STANDARD = new TaskSelection(false, null, null);

	/** Whether the version is pooled (standard and variant alike). */
	private final boolean anyVariant;
	/** The variant's name ({@link CatacombsVariants.Variant#getName}), or {@code null} for any and standard. */
	private final String variant;
	/** {@code true} for cannon tasks only, {@code false} for tasks without a cannon only, {@code null} for both. */
	private final Boolean cannon;

	/** Only the records of the variant {@code name} (with or without a cannon); {@link #STANDARD} for a blank name. */
	static TaskSelection of(String name)
	{
		return TaskStatistics.normalize(name) == null ? STANDARD : new TaskSelection(false, name.trim(), null);
	}

	/**
	 * This selection, limited to cannon tasks ({@code true}), tasks without a cannon ({@code false}) or both
	 * ({@code null}). Without a cannon limit, {@link #ANY} and {@link #STANDARD} stay the same instances.
	 */
	TaskSelection withCannon(Boolean cannon)
	{
		if (Objects.equals(cannon, this.cannon))
		{
			return this;
		}
		if (cannon == null && variant == null)
		{
			return anyVariant ? ANY : STANDARD;
		}
		return new TaskSelection(anyVariant, variant, cannon);
	}

	/** This selection with the version pooled ({@link #ANY}'s), keeping its cannon limit. */
	TaskSelection withAnyVariant()
	{
		return anyVariant ? this : ANY.withCannon(cannon);
	}

	/**
	 * This selection for the task {@code taskName}: kept when its variant is that task's Catacombs variant (or it has
	 * none), else with the version pooled ({@link #withAnyVariant}). Guards a selection read in a separate call from the
	 * task it is shown with, which could see another session (the overlay's Task row).
	 */
	TaskSelection forTask(String taskName)
	{
		if (variant == null)
		{
			return this;
		}
		final CatacombsVariants.Variant taskVariant = CatacombsVariants.forTask(taskName);
		return taskVariant != null && variant.equals(taskVariant.getName()) ? this : withAnyVariant();
	}

	/** Whether {@code record}'s version and cannon use are ones this selects (its task is matched elsewhere). */
	boolean matches(LedgerRecord record)
	{
		if (cannon != null && cannon != record.cannonTask())
		{
			return false;
		}
		if (anyVariant)
		{
			return true;
		}
		return Objects.equals(TaskStatistics.normalize(variant), TaskStatistics.normalize(record.getVariant()));
	}

	/**
	 * The name the live task is shown under with this selection, the same way {@link LedgerRecord#groupName} names a
	 * saved one: the variant's name when there is one, else {@code task}, with {@link CannonTasks#SUFFIX} for cannon
	 * tasks only. A pooled cannon dimension adds nothing.
	 */
	String displayName(String task)
	{
		return CannonTasks.name(variant != null ? variant : task, Boolean.TRUE.equals(cannon));
	}

	/**
	 * A short key for caches: the version ({@code *} for any, empty for standard, else the normalized name), then
	 * {@code /} and the cannon ({@code *} for both, {@code c} with, {@code n} without).
	 */
	String key()
	{
		String version;
		if (anyVariant)
		{
			version = "*";
		}
		else
		{
			String normalized = TaskStatistics.normalize(variant);
			version = normalized == null ? "" : normalized;
		}
		return version + "/" + (cannon == null ? "*" : cannon ? "c" : "n");
	}

	@Override
	public boolean equals(Object other)
	{
		return other instanceof TaskSelection && key().equals(((TaskSelection) other).key());
	}

	@Override
	public int hashCode()
	{
		return key().hashCode();
	}

	@Override
	public String toString()
	{
		String version = anyVariant ? "ANY" : variant == null ? "STANDARD" : variant;
		return cannon == null ? version : version + (cannon ? " (cannon)" : " (no cannon)");
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * A task's location as its kills decide it (V2 plan 4.5, {@link LocationTally#decide}): its Slayer spot and the
 * map region it is saved with. Immutable and pure (no RuneLite types).
 */
@Getter
@EqualsAndHashCode
@ToString
@RequiredArgsConstructor(access = AccessLevel.PACKAGE)
final class TaskSpot
{
	/** No kill was tallied: no spot and no region. */
	static final TaskSpot UNKNOWN = new TaskSpot(null, null);

	/**
	 * The spot key ({@link SlayerSpots}: a table id or {@code region:N}), or {@code null} for the Unknown spot (no kill
	 * tallied, or none at a place the table decides).
	 */
	private final String spotId;
	/**
	 * The region saved with it ({@link LedgerRecord#getLocationRegion}): the spot's region with the most kills, or with
	 * an Unknown spot the region with the most kills of all; {@code null} when no kill was tallied.
	 */
	private final Integer region;
}

package com.shmayvan.slayerledger;

import java.util.*;
import java.util.function.*;
import lombok.*;

/**
 * Per-task historical averages, calculated from saved completed records only: what the live task card's time left and
 * the overlay's time left and supply runway read (the 2.0 rebuild trimmed it to them). That is the sample count, the time per
 * kill, the location the samples were limited to and the supplies per kill. Nothing here is valued, so neither today's
 * prices, the "Loot price" mode nor Ground Items' hidden items change it. Immutable; pure (no RuneLite types).
 */
final class TaskStatistics
{
	@Getter
	private final int sampleCount;
	private final long totalKills;
	private final long activeMillis;
	/** Kills of the samples that count for the supplies per kill ({@link TaskPlanner#hasSupplyData}). */
	private final long supplyKills;
	/** Supplies used by those samples, by item id (doses, bites or charges for the items saved so). */
	private final Map<Integer, Long> supplies;
	/**
	 * The name of the location the samples were limited to (the current task's
	 * {@link TaskLocation.Here#getName}), or {@code null} for every location.
	 */
	@Getter
	private final String location;

	private TaskStatistics(Totals t)
	{
		this.location = t.location;
		this.sampleCount = t.sampleCount;
		this.totalKills = t.totalKills;
		this.activeMillis = t.activeMillis;
		this.supplyKills = t.supplyKills;
		this.supplies = Collections.unmodifiableMap(new TreeMap<>(t.supplies));
	}

	/** The running totals {@link #aggregate} adds the samples into; a new one is the empty statistics. */
	private static final class Totals
	{
		private int sampleCount;
		private long totalKills;
		private long activeMillis;
		private long supplyKills;
		private final Map<Integer, Long> supplies = new TreeMap<>();
		private String location;
	}

	/**
	 * The statistics of the records of the task {@code selection} selects: its version and whether a cannon was
	 * used; {@link TaskSelection#ANY} (or {@code null}) pools the standard monster and its Catacombs variant,
	 * with and without a cannon. Per-kill values are pooled across their kills. Outliers are not removed.
	 *
	 * <p>Same location first (by spot): when {@code here} is
	 * {@link TaskLocation.Here#isKnown known} and at least one sample ({@link #isSample}) is at its spot
	 * ({@code recordSpot}'s spot key for the record equals {@code here}'s), only those samples count and
	 * {@link #getLocation} is {@code here}'s name; otherwise every sample counts. A record's own location name (Edit
	 * location) never moves it: tasks match by spot, as they group.</p>
	 *
	 * <p>Supplies count only from samples that say what they used, by the advisor's rule
	 * ({@link TaskPlanner#hasSupplyData}): a 1.x record saved without supplies may have had its supply counting
	 * stop, so it is left out of the supplies per kill, not counted as using nothing. It still counts for the
	 * kills and the time.</p>
	 *
	 * @param here       the current task's location ({@link TaskLocation#current}), or {@code null} while unknown
	 * @param recordSpot a saved record's spot key ({@link SlayerSpots#recordSpot}), {@code null} when Unknown; or
	 *                   {@code null} to pool every location
	 */
	static TaskStatistics forTask(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskSelection selection, TaskLocation.Here here, Function<LedgerRecord, String> recordSpot)
	{
		if (here != null && here.isKnown() && records != null && recordSpot != null)
		{
			List<LedgerRecord> atLocation = new ArrayList<>();
			for (LedgerRecord record : records)
			{
				if (isSample(record, creatureId, monster, selection) && here.getSpot().equals(recordSpot.apply(record)))
				{
					atLocation.add(record);
				}
			}
			if (!atLocation.isEmpty())
			{
				return aggregate(atLocation, creatureId, monster, selection, here.getName());
			}
		}
		return aggregate(records, creatureId, monster, selection, null);
	}

	/**
	 * Whether {@code record} is a sample of the task: completed, not partial, with kills, and the same creature (either
	 * version, standard or Catacombs variant, with or without a cannon).
	 */
	static boolean isSample(LedgerRecord record, int creatureId, String monster)
	{
		return isSample(record, creatureId, monster, TaskSelection.ANY);
	}

	/**
	 * As {@link #isSample(LedgerRecord, int, String)}, and of the version and cannon use {@code selection} selects
	 *.
	 */
	static boolean isSample(LedgerRecord record, int creatureId, String monster, TaskSelection selection)
	{
		return record != null && record.isCompleted() && !record.isPartial() && record.getKills() > 0
			&& matches(record, creatureId, monster) && (selection == null || selection.matches(record));
	}

	/**
	 * A completed, not partial record with kills and active time, of any task: the samples Overall totals' rates and
	 * the advisor's plan pool.
	 */
	static boolean isTaskSample(LedgerRecord record)
	{
		return record != null && record.isCompleted() && !record.isPartial() && record.getKills() > 0
			&& record.getActiveMillis() > 0;
	}

	/**
	 * The selection the live task's statistics use for {@code selection} (owner decision 2026-10-28): when it
	 * asks for cannon tasks only but {@code records} hold no {@link #isSample sample} of the task that is a cannon task
	 * of its version (at any location), tasks with and without a cannon pooled ({@code selection} without its cannon
	 * limit), as before the cannonball; otherwise {@code selection} itself. A {@code null} selection is
	 * {@link TaskSelection#ANY}.
	 */
	static TaskSelection effectiveSelection(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskSelection selection)
	{
		TaskSelection requested = selection == null ? TaskSelection.ANY : selection;
		if (!Boolean.TRUE.equals(requested.getCannon()))
		{
			return requested;
		}
		if (records != null)
		{
			for (LedgerRecord record : records)
			{
				if (isSample(record, creatureId, monster, requested))
				{
					return requested;
				}
			}
		}
		return requested.withCannon(null);
	}

	private static TaskStatistics aggregate(Collection<LedgerRecord> records, int creatureId, String monster,
		TaskSelection selection, String location)
	{
		final Totals t = new Totals();
		t.location = location;
		if (records == null)
		{
			return new TaskStatistics(t);
		}

		for (LedgerRecord record : records)
		{
			if (!isSample(record, creatureId, monster, selection))
			{
				continue;
			}

			long recordKills = record.getKills();
			t.sampleCount++;
			t.totalKills = saturatedAdd(t.totalKills, recordKills);
			t.activeMillis = saturatedAdd(t.activeMillis, Math.max(0, record.getActiveMillis()));

			// A 1.x task saved without supplies: what it used is unknown, not nothing. A valued task saved
			// without supplies used none.
			Map<Integer, Long> recordSupplies = record.getSupplies();
			if (TaskPlanner.hasSupplyData(record) && (recordSupplies != null || LedgerHistory.isValued(record)))
			{
				t.supplyKills = saturatedAdd(t.supplyKills, recordKills);
				if (recordSupplies != null)
				{
					for (Map.Entry<Integer, Long> item : recordSupplies.entrySet())
					{
						if (item.getKey() != null && item.getValue() != null && item.getValue() > 0)
						{
							t.supplies.merge(item.getKey(), item.getValue(), TaskStatistics::saturatedAdd);
						}
					}
				}
			}
		}
		return new TaskStatistics(t);
	}

	private static boolean matches(LedgerRecord record, int creatureId, String monster)
	{
		Integer recordCreatureId = record.getCreatureId();
		if (creatureId != SessionTracker.NO_CREATURE && recordCreatureId != null)
		{
			return recordCreatureId == creatureId;
		}
		String recordMonster = normalize(record.getMonster());
		return recordMonster != null && recordMonster.equals(normalize(monster));
	}

	/**
	 * The one monster-name key every feature groups and matches by (task statistics, the advisor's ranking, Overall
	 * totals, the Slayer spot table's task lists): trimmed and lower case in {@link Locale#ROOT}, so the key never
	 * depends on the client's default locale. {@code null} for a {@code null} or blank name, which matches nothing.
	 */
	static String normalize(String value)
	{
		if (value == null)
		{
			return null;
		}
		String name = value.trim();
		return name.isEmpty() ? null : name.toLowerCase(Locale.ROOT);
	}

	private static long saturatedAdd(long left, long right)
	{
		try
		{
			return Math.addExact(left, right);
		}
		catch (ArithmeticException e)
		{
			return right >= 0 ? Long.MAX_VALUE : Long.MIN_VALUE;
		}
	}

	/** The samples' active time over their kills, or {@code null} without a sample. */
	Long getMillisPerKill()
	{
		return totalKills == 0 ? null : Math.round(activeMillis / (double) totalKills);
	}

	/**
	 * Each supply's use per kill, by item id, over the kills of the samples that say what they used (doses, bites or
	 * charges for the items saved so); empty without one. The overlay's supply runway reads it.
	 */
	Map<Integer, Double> getSuppliesPerKill()
	{
		Map<Integer, Double> result = new TreeMap<>();
		if (supplyKills > 0)
		{
			supplies.forEach((id, quantity) -> result.put(id, quantity / (double) supplyKills));
		}
		return Collections.unmodifiableMap(result);
	}
}

package com.shmayvan.slayerledger;

import java.util.*;

/**
 * Estimates how long the rest of a Slayer task will take from the session's pace so far: the average active time per
 * kill times the kills left. Pure; no RuneLite types.
 *
 * <p>No estimate is given until the session has at least {@link #MIN_KILLS} kills and {@link #MIN_ACTIVE_MILLIS} of
 * active time, so the first kills (or a quick first kill) do not produce a wild figure.</p>
 */
final class TaskTimeEstimate
{
	/** Kills needed before an estimate is given. */
	static final int MIN_KILLS = 3;
	/** Active time needed before an estimate is given. */
	static final long MIN_ACTIVE_MILLIS = 60_000;

	private static final double MILLIS_PER_HOUR = 3_600_000d;

	private TaskTimeEstimate()
	{
	}

	/**
	 * Estimated active time left on the task.
	 *
	 * @param activeMillis the session's active (running) time so far
	 * @param kills        kills in the session so far
	 * @param remaining    kills left on the task
	 * @return {@code round(activeMillis / kills * remaining)}, saturated at {@link Long#MAX_VALUE}; empty when there
	 * is too little data ({@link #isEstimable}) or nothing is left ({@code remaining <= 0})
	 */
	static OptionalLong remainingMillis(long activeMillis, int kills, int remaining)
	{
		if (!isEstimable(activeMillis, kills) || remaining <= 0)
		{
			return OptionalLong.empty();
		}
		// Math.round saturates at Long.MAX_VALUE, and the double cannot overflow for int and long inputs.
		return OptionalLong.of(Math.round(activeMillis / (double) kills * remaining));
	}

	/** Kills per hour of active time, or empty when there is too little data ({@link #isEstimable}). */
	static OptionalDouble killsPerHour(long activeMillis, int kills)
	{
		if (!isEstimable(activeMillis, kills))
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of(kills * MILLIS_PER_HOUR / activeMillis);
	}

	/** Average active time per kill, or empty when there is too little data ({@link #isEstimable}). */
	static OptionalLong averageKillMillis(long activeMillis, int kills)
	{
		if (!isEstimable(activeMillis, kills))
		{
			return OptionalLong.empty();
		}
		return OptionalLong.of(Math.round(activeMillis / (double) kills));
	}

	/** Whether the session has enough kills and active time for an estimate. */
	static boolean isEstimable(long activeMillis, int kills)
	{
		return kills >= MIN_KILLS && activeMillis >= MIN_ACTIVE_MILLIS;
	}
}

package com.shmayvan.slayerledger;

import lombok.*;

/**
 * Kind of Slayer task, derived from the assigning master and the task (never stored, so it can't disagree with the
 * raw values it comes from). Pure; no RuneLite types.
 *
 * <p>A boss task (SLAYER_TARGET {@value SessionTracker#BOSS_TASK_TARGET}) is {@link #BOSS} whoever assigned it.
 * Otherwise Krystilia's tasks are {@link #WILDERNESS}, Konar's are {@link #KONAR} and every other known master's are
 * {@link #REGULAR}. Without a known master (or with one missing from {@link SlayerMaster}'s table) a non-boss task
 * has no type. Whether a task was extended is not part of the
 * type: the plugin has no reliable way to tell (see docs/COUNTING_RULES.md).</p>
 */
@RequiredArgsConstructor
enum TaskType
{
	REGULAR("Regular"),
	WILDERNESS("Wilderness"),
	KONAR("Konar"),
	BOSS("Boss");

	private final String label;

	/**
	 * @param master     SLAYER_MASTER value, or {@code null} when unknown
	 * @param creatureId creature key ({@link SessionTracker#creatureKey}), or {@code null} or
	 *                   {@link SessionTracker#NO_CREATURE} when unknown
	 * @return the task's type, or {@code null} when it can't be told
	 */
	static TaskType of(Integer master, Integer creatureId)
	{
		if (creatureId != null && creatureId < SessionTracker.NO_CREATURE)
		{
			// Boss keys are -2 - bossId, always below NO_CREATURE.
			return BOSS;
		}
		if (!SlayerMaster.isKnown(master))
		{
			return null;
		}
		switch (master)
		{
			case SlayerMaster.KRYSTILIA:
				return WILDERNESS;
			case SlayerMaster.KONAR:
				return KONAR;
			default:
				// A master missing from the name table could be any kind (a new Wilderness master, say).
				return SlayerMaster.hasName(master) ? REGULAR : null;
		}
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * A task's variant and boss flag (V2 plan 4.4), decided from its kills per NPC name ({@link NpcKillTally}). Pure
 * (no RuneLite types).
 *
 * <p><b>Kinds.</b> A task's kinds are the NPC kinds it can be done on besides its own monsters: its Catacombs variant
 * ({@link CatacombsVariants}, named as the 1.x records name it, for example "Deviant spectres") and its Slayer boss
 * ({@link SlayerBosses}, for example "Grotesque Guardians" on a gargoyle task). A kind's kills are the tallied kills of
 * its most-killed NPC name: every NPC of a kind dies in each of its kills (Dusk and Dawn), so a Grotesque Guardians kill
 * counts once.</p>
 *
 * <p><b>Variant.</b> The kind with the most task kills in the tally, leaving out superiors
 * ({@link SlayerBosses#isSuperiorName}): a kind's kills against the task's own monsters' kills, which are the tally's other
 * kills, but never more than the task kills (the game's task counter) the kinds and superiors leave over. That bound
 * keeps other monsters out (an Ankou on the way, death spawns, a boss's minions, anything else caught in a barrage),
 * and the tally keeps a boss whose kill takes off two task kills (the Grotesque Guardians with the Double Trouble reward)
 * from counting its second one as a gargoyle. Task kills the tally missed (a death not seen, or one before the tally
 * existed) count for neither; in older versions a Catacombs variant needed more than half of the task kills, so they counted
 * as the standard monster. A tie, no task kills, or a task without a kind is the standard monster ({@code null}).</p>
 *
 * <p><b>Boss flag.</b> Kills of the task's Slayer boss, any number, set it: in the tally, or for a record without a
 * tally (one saved by 1.x), in its boss kill counts ({@link BossKillCounts}). Boss tasks (task type Boss) are their own
 * pool, so they have neither a variant nor the flag.</p>
 */
final class TaskVariants
{
	/** What a live task's name ends with when it has boss kills but its name doesn't say so: {@code " + boss"}. */
	static final String BOSS_SUFFIX = " + boss";

	/** The variant and boss flag decided for one task. Immutable. */
	@EqualsAndHashCode
	@ToString
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Decision
	{
		/** No variant and no boss kills, for no task. */
		static final Decision NONE = new Decision(null, null, false, false);

		/** The task the decision is for, or {@code null} for {@link #NONE}. */
		@Getter
		private final String task;
		/** The variant's name (a kind's), or {@code null} for the standard monster. */
		@Getter
		private final String variant;
		private final boolean variantIsBoss;
		/** Whether the kills include the task's Slayer boss. */
		@Getter
		private final boolean bossKills;

		/** Whether the variant is the task's Slayer boss. */
		boolean isVariantBoss()
		{
			return variantIsBoss;
		}

		/**
		 * This decision when it is for {@code taskName} (matched by {@link TaskStatistics#normalize}), else
		 * {@link #NONE}. Guards a decision read in a separate call from the task it is shown with, which could see another
		 * session (the overlay's Task row).
		 */
		Decision forTask(String taskName)
		{
			final String key = TaskStatistics.normalize(task);
			return key != null && key.equals(TaskStatistics.normalize(taskName)) ? this : NONE;
		}

		/**
		 * The name a live task is shown under, as the saved one is ({@link LedgerRecord#groupName}): the variant's name
		 * when there is one, else {@code taskName}, with {@link CannonTasks#SUFFIX} when {@code cannon}, then
		 * {@link #BOSS_SUFFIX} when there are boss kills and the name isn't the boss's own. For example
		 * "Grotesque Guardians", "Deviant spectres (cannon)" or "Cave kraken + boss".
		 */
		String displayName(String taskName, boolean cannon)
		{
			final String name = CannonTasks.name(variant != null ? variant : taskName, cannon);
			return name != null && bossKills && !variantIsBoss ? name + BOSS_SUFFIX : name;
		}
	}

	/** One kind of a task: its name, its NPC names' {@link TaskStatistics#normalize} keys, whether it is a boss. */
	private static final class Kind
	{
		private final String name;
		private final List<String> npcKeys;
		private final boolean boss;

		private Kind(String name, List<String> npcNames, boolean boss)
		{
			this.name = name;
			final List<String> keys = new ArrayList<>(npcNames.size());
			for (String npcName : npcNames)
			{
				keys.add(TaskStatistics.normalize(npcName));
			}
			this.npcKeys = Collections.unmodifiableList(keys);
			this.boss = boss;
		}
	}

	/**
	 * Each task's kinds by its {@link TaskStatistics#normalize}d name, worked out once (the overlay asks every frame):
	 * its Catacombs variant, then its Slayer boss.
	 */
	private static final Map<String, List<Kind>> KINDS = kindsByTask();

	private TaskVariants()
	{
	}

	/**
	 * The variant and boss flag of a task from its kills (see the class rules).
	 *
	 * @param taskName   the task's name, or {@code null} when unknown (no kinds)
	 * @param creatureId the task's creature key ({@link SessionTracker#creatureKey}); boss tasks are below
	 *                   {@link SessionTracker#NO_CREATURE}
	 * @param tally      the kills per NPC name ({@link NpcKillTally}), or {@code null} for none
	 * @param taskKills  the task kills, as the game's task counter counted them
	 */
	static Decision decide(String taskName, int creatureId, List<NpcKills> tally, int taskKills)
	{
		final List<Kind> kinds = kinds(taskName, creatureId);
		if (kinds.isEmpty())
		{
			return Decision.NONE;
		}
		// Each kind's kills per NPC name, added up over a name's entries (a file's tally may repeat one), without
		// copying the tally: the overlay asks every frame.
		final long[][] npcKills = new long[kinds.size()][];
		for (int i = 0; i < kinds.size(); i++)
		{
			npcKills[i] = new long[kinds.get(i).npcKeys.size()];
		}
		long superiors = 0;
		long others = 0;
		for (NpcKills entry : tally == null ? Collections.<NpcKills>emptyList() : tally)
		{
			final String key = entry == null || entry.getKills() <= 0 ? null : TaskStatistics.normalize(entry.getName());
			if (key == null)
			{
				continue;
			}
			if (addToKind(kinds, npcKills, key, entry.getKills()))
			{
				continue;
			}
			if (SlayerBosses.isSuperiorName(key))
			{
				superiors += entry.getKills();
			}
			else
			{
				others += entry.getKills();
			}
		}
		// A kind's kills are its most-killed NPC's: all of its NPCs die in each of its kills.
		final long[] kindKills = new long[kinds.size()];
		boolean bossKills = false;
		long kindTotal = 0;
		int best = -1;
		boolean tie = false;
		for (int i = 0; i < kinds.size(); i++)
		{
			for (long kills : npcKills[i])
			{
				kindKills[i] = Math.max(kindKills[i], kills);
			}
			bossKills |= kinds.get(i).boss && kindKills[i] > 0;
			kindTotal += kindKills[i];
			if (best < 0 || kindKills[i] > kindKills[best])
			{
				best = i;
				tie = false;
			}
			else if (kindKills[i] == kindKills[best])
			{
				tie = true;
			}
		}
		// The task's own monsters: the tally's other kills, at most what the task kills leave over.
		final long standard = Math.min(others, Math.max(0, taskKills - kindTotal - superiors));
		final boolean variant = taskKills > 0 && !tie && kindKills[best] > standard;
		final Kind kind = kinds.get(best);
		return new Decision(taskName.trim(), variant ? kind.name : null, variant && kind.boss, bossKills);
	}

	/**
	 * A saved record's boss flag (see the class rules): from its kills per NPC name when it has any, else from its boss
	 * kill counts; {@code false} for a boss task or a task without a Slayer boss.
	 */
	static boolean bossKills(LedgerRecord record)
	{
		final SlayerBosses.Boss boss = record == null || isBossTask(record.getCreatureId()) ? null
			: SlayerBosses.forTask(record.getMonster());
		if (boss == null)
		{
			return false;
		}
		final List<NpcKills> tally = NpcKillTally.sanitize(record.getNpcKills());
		if (!tally.isEmpty())
		{
			for (String npcName : boss.getNpcNames())
			{
				if (NpcKillTally.killsOf(tally, npcName) > 0)
				{
					return true;
				}
			}
			return false;
		}
		for (BossKillCount count : BossKillCounts.sanitize(record.getBossKillCounts()))
		{
			if (BossKillCounts.sameName(count.getBoss(), boss.getName()))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Gives a record without a boss flag its flag ({@link #bossKills(LedgerRecord)}), in place; a record that has one
	 * keeps it. {@link SetupMigration} calls it for a 1.x record when it is read. A version 3 record written before the flag existed
	 * keeps a null flag on file; read it through {@link #hasBossKills}. Its variant is left as saved: a 1.x
	 * record's is a Catacombs variant's name or none, which this version names the same way.
	 *
	 * @return whether the record was given its flag
	 */
	static boolean migrate(LedgerRecord record)
	{
		if (record == null || record.getBossKills() != null)
		{
			return false;
		}
		record.setBossKills(bossKills(record));
		return true;
	}

	/**
	 * Whether {@code record}'s task included a kill of its Slayer boss: its saved flag, or, for a record saved without
	 * one (a version 3 record written before the flag existed), the flag worked out from its kills by name and boss kill
	 * counts, without changing the record. Grouping and the advisor read the flag only through this.
	 */
	static boolean hasBossKills(LedgerRecord record)
	{
		if (record == null)
		{
			return false;
		}
		final Boolean saved = record.getBossKills();
		return saved != null ? saved : bossKills(record);
	}

	/** The name of the Slayer boss of {@code taskName} ({@link SlayerBosses#forTask}), or {@code null} for none. */
	static String bossName(String taskName)
	{
		final SlayerBosses.Boss boss = SlayerBosses.forTask(taskName);
		return boss == null ? null : boss.getName();
	}

	/**
	 * Whether {@code npcName} is an NPC name a variant decision reads: a Catacombs variant's, a Slayer boss's or a
	 * listed superior's. The tally always takes these ({@link NpcKillTally#MAX_NAMES}).
	 */
	static boolean isDecidingNpcName(String npcName)
	{
		return CatacombsVariants.isVariantNpcName(npcName) || SlayerBosses.isBossNpcName(npcName)
			|| SlayerBosses.isSuperiorName(npcName);
	}

	/** The task's kinds, in a fixed order; none for a boss task or an unknown one. */
	private static List<Kind> kinds(String taskName, int creatureId)
	{
		final String key = isBossTask(creatureId) ? null : TaskStatistics.normalize(taskName);
		final List<Kind> kinds = key == null ? null : KINDS.get(key);
		return kinds == null ? Collections.emptyList() : kinds;
	}

	private static Map<String, List<Kind>> kindsByTask()
	{
		final Map<String, List<Kind>> byTask = new HashMap<>();
		for (CatacombsVariants.Variant variant : CatacombsVariants.all())
		{
			byTask.computeIfAbsent(TaskStatistics.normalize(variant.getTask()), task -> new ArrayList<>(2))
				.add(new Kind(variant.getName(), Collections.singletonList(variant.getNpcName()), false));
		}
		for (SlayerBosses.Boss boss : SlayerBosses.all())
		{
			byTask.computeIfAbsent(TaskStatistics.normalize(boss.getTask()), task -> new ArrayList<>(2))
				.add(new Kind(boss.getName(), boss.getNpcNames(), true));
		}
		final Map<String, List<Kind>> kinds = new HashMap<>();
		for (Map.Entry<String, List<Kind>> entry : byTask.entrySet())
		{
			kinds.put(entry.getKey(), Collections.unmodifiableList(entry.getValue()));
		}
		return Collections.unmodifiableMap(kinds);
	}

	/** Adds {@code kills} of the NPC name {@code key} to its kind's, if it is one of {@code kinds}' NPCs. */
	private static boolean addToKind(List<Kind> kinds, long[][] npcKills, String key, int kills)
	{
		for (int i = 0; i < kinds.size(); i++)
		{
			final int npc = kinds.get(i).npcKeys.indexOf(key);
			if (npc >= 0)
			{
				npcKills[i][npc] += kills;
				return true;
			}
		}
		return false;
	}

	private static boolean isBossTask(Integer creatureId)
	{
		return creatureId != null && creatureId < SessionTracker.NO_CREATURE;
	}
}

package com.shmayvan.slayerledger;

import java.util.*;
import lombok.*;

/**
 * Supplies, XP and loot, each stamped with the clock time it arrived (V2 plan 4.1), for the use a session may still
 * count or give back. {@link SessionTracker} keeps two: the buffer outside segments, from which a (re)start counts the
 * XP and loot from the segment start and the supplies from 3 minutes before it; and the open segment's use since its
 * last activity, which is taken back into the buffer if Away starts.
 *
 * <p>Additions at the same clock time share one entry. Bounded: each addition drops the entries more than
 * {@link #MAX_AGE_MILLIS} older than it, and the oldest beyond {@link #MAX_ENTRIES}. Pure (no RuneLite types); not
 * synchronized (the tracker's lock guards it).</p>
 */
final class TimedUsage
{
	/** How long an entry is kept: the buffer holds at most 60 minutes (V2 plan 4.1). */
	static final long MAX_AGE_MILLIS = 60 * 60_000L;
	/**
	 * Most entries kept. The plugin adds supplies, XP and loot a few times per game tick at most, and only on ticks when
	 * something was used or gained; this bounds even an hour of fighting with every part on every tick.
	 */
	static final int MAX_ENTRIES = 12_000;

	/**
	 * What arrived at one clock time. Each part is {@code null} when nothing of it arrived. Changed only by its
	 * {@link TimedUsage}.
	 */
	@Getter
	@RequiredArgsConstructor(access = AccessLevel.PRIVATE)
	static final class Entry
	{
		/** When it arrived (clock millis). */
		private final long at;
		/** Supplies used, potions in doses (as {@link SessionTracker#addSupplies}). */
		private ItemTally used;
		/** Ammo or cannonballs that came back; each takes that much off the item's use, never below zero. */
		private ItemTally returned;
		/** Doses (bites, charges) per item for the potion ids in {@link #used}. */
		private Map<Integer, Integer> doses;
		/** XP gained per skill ({@link SkillXp}). */
		private Map<String, Long> xp;
		private ItemTally loot;
		/** Notable stacks of {@link #loot}, and pets. */
		private List<NotableDrop> drops;

		private boolean hasSupplies()
		{
			return used != null || returned != null;
		}

		private boolean hasCounted()
		{
			return xp != null || loot != null || drops != null;
		}

		private boolean isEmpty()
		{
			return !hasSupplies() && !hasCounted();
		}

		/** Moves this entry's supplies to a new entry at the same time, which is returned. */
		private Entry takeSupplies()
		{
			final Entry taken = new Entry(at);
			taken.used = used;
			taken.returned = returned;
			taken.doses = doses;
			used = null;
			returned = null;
			doses = null;
			return taken;
		}

		/** Moves this entry's XP and loot into {@code into}. */
		private void moveCountedTo(Entry into)
		{
			into.xp = xp;
			into.loot = loot;
			into.drops = drops;
			xp = null;
			loot = null;
			drops = null;
		}
	}

	/**
	 * Oldest first. The tracker adds each one at its clock's time now, which only moves on, and Away gives the buffer
	 * back what it took at times after anything the buffer still holds (the buffer fills only while no segment is
	 * open, and a restart leaves only what came before the segment), so {@link #dropBefore}, {@link #dropUpTo} and
	 * {@link #prune} drop from the front and stop at the first newer entry, at little cost per addition. A clock that
	 * went back can leave an entry out of order: the drops then stop at it and leave older ones behind for a later drop,
	 * {@link #prune} or {@link #clear}, while {@link #take} and {@link #takeAfter} still go by each entry's own time.
	 */
	private final Deque<Entry> entries = new ArrayDeque<>();

	/** Adds supplies used and returned at {@code at}; empty or {@code null} parts are left out. */
	void addSupplies(long at, ItemTally used, ItemTally returned, Map<Integer, Integer> doses)
	{
		final boolean hasUsed = used != null && !used.isEmpty();
		final boolean hasReturned = returned != null && !returned.isEmpty();
		if (!hasUsed && !hasReturned)
		{
			return;
		}
		final Entry entry = entryAt(at);
		if (hasUsed)
		{
			if (entry.used == null)
			{
				entry.used = new ItemTally();
			}
			entry.used.merge(used);
			if (doses != null && !doses.isEmpty())
			{
				if (entry.doses == null)
				{
					entry.doses = new TreeMap<>();
				}
				SessionTracker.putDoses(entry.doses, doses);
			}
		}
		if (hasReturned)
		{
			if (entry.returned == null)
			{
				entry.returned = new ItemTally();
			}
			entry.returned.merge(returned);
		}
		prune(at);
	}

	/** Adds XP gained at {@code at} ({@link SkillXp#gains}); {@code null} or empty adds nothing. */
	void addXp(long at, Map<String, Long> gains)
	{
		if (gains == null || gains.isEmpty())
		{
			return;
		}
		final Entry entry = entryAt(at);
		if (entry.xp == null)
		{
			entry.xp = new TreeMap<>();
		}
		SkillXp.add(entry.xp, gains);
		prune(at);
	}

	/** Adds loot and its notable drops (either may be {@code null} or empty, for example a pet's drop alone). */
	void addLoot(long at, ItemTally items, List<NotableDrop> notableDrops)
	{
		final boolean hasItems = items != null && !items.isEmpty();
		final boolean hasDrops = notableDrops != null && !notableDrops.isEmpty();
		if (!hasItems && !hasDrops)
		{
			return;
		}
		final Entry entry = entryAt(at);
		if (hasItems)
		{
			if (entry.loot == null)
			{
				entry.loot = new ItemTally();
			}
			entry.loot.merge(items);
		}
		if (hasDrops)
		{
			if (entry.drops == null)
			{
				entry.drops = new ArrayList<>();
			}
			for (NotableDrop drop : notableDrops)
			{
				if (drop != null)
				{
					entry.drops.add(drop);
				}
			}
		}
		prune(at);
	}

	/** Adds everything in {@code entry} at its own time, as if it had arrived here. */
	void add(Entry entry)
	{
		if (entry == null)
		{
			return;
		}
		addSupplies(entry.at, entry.used, entry.returned, entry.doses);
		addXp(entry.at, entry.xp);
		addLoot(entry.at, entry.loot, entry.drops);
	}

	/**
	 * Removes and returns, oldest first, the supplies of the entries at or after {@code suppliesFrom} and the XP and
	 * loot of the entries at or after {@code countFrom}. What is left of each entry stays.
	 */
	List<Entry> take(long suppliesFrom, long countFrom)
	{
		final List<Entry> taken = new ArrayList<>();
		final Iterator<Entry> it = entries.iterator();
		while (it.hasNext())
		{
			final Entry entry = it.next();
			Entry part = null;
			if (entry.at >= suppliesFrom && entry.hasSupplies())
			{
				part = entry.takeSupplies();
			}
			if (entry.at >= countFrom && entry.hasCounted())
			{
				if (part == null)
				{
					part = new Entry(entry.at);
				}
				entry.moveCountedTo(part);
			}
			if (part != null)
			{
				taken.add(part);
			}
			if (entry.isEmpty())
			{
				it.remove();
			}
		}
		taken.sort((a, b) -> Long.compare(a.at, b.at));
		return taken;
	}

	/** Removes and returns the entries after {@code after}, newest first, so they can be undone in reverse order. */
	List<Entry> takeAfter(long after)
	{
		final List<Entry> taken = new ArrayList<>();
		final Iterator<Entry> it = entries.iterator();
		while (it.hasNext())
		{
			final Entry entry = it.next();
			if (entry.at > after)
			{
				taken.add(entry);
				it.remove();
			}
		}
		taken.sort((a, b) -> Long.compare(b.at, a.at));
		return taken;
	}

	/** Drops the entries before {@code at}, from the front (see {@link #entries}). */
	void dropBefore(long at)
	{
		while (!entries.isEmpty() && entries.peekFirst().at < at)
		{
			entries.removeFirst();
		}
	}

	/**
	 * Drops the entries at or before {@code at}, from the front (see {@link #entries}): called on every addition to the
	 * open segment's use since its last activity, so it must not scan what it keeps.
	 */
	void dropUpTo(long at)
	{
		while (!entries.isEmpty() && entries.peekFirst().at <= at)
		{
			entries.removeFirst();
		}
	}

	void clear()
	{
		entries.clear();
	}

	boolean isEmpty()
	{
		return entries.isEmpty();
	}

	/** How many entries are kept. */
	int size()
	{
		return entries.size();
	}

	/** The entry for {@code at}: the newest one when it has that time, otherwise a new one. */
	private Entry entryAt(long at)
	{
		final Entry newest = entries.peekLast();
		if (newest != null && newest.at == at)
		{
			return newest;
		}
		final Entry entry = new Entry(at);
		entries.addLast(entry);
		return entry;
	}

	/**
	 * Drops the oldest entries while they are more than {@link #MAX_AGE_MILLIS} before {@code now}, then the oldest
	 * beyond {@link #MAX_ENTRIES}. Only from the front, so each addition costs little; an entry left behind by a clock
	 * that went back goes with the others once it reaches the front.
	 */
	private void prune(long now)
	{
		if (now > Long.MIN_VALUE + MAX_AGE_MILLIS)
		{
			final long oldest = now - MAX_AGE_MILLIS;
			while (!entries.isEmpty() && entries.peekFirst().at < oldest)
			{
				entries.removeFirst();
			}
		}
		while (entries.size() > MAX_ENTRIES)
		{
			entries.removeFirst();
		}
	}
}

package com.shmayvan.slayerledger;

import java.awt.*;
import java.awt.event.*;
import java.util.*;
import java.util.List;
import javax.swing.*;
import lombok.*;
import net.runelite.client.ui.*;

/**
 * A titled list of the sidebar, the part {@link ItemListView} (text lines) and {@link ItemGridView} (item icons)
 * share: a title with its row count, then "None" while the list is empty, or the body a subclass fills from the rows.
 * A collapsible list (Overall totals' grids) opens and closes from its title ("Show" or "Hide") and starts closed.
 * Rows the caller left out (the loot Ground Items hides) are counted in the title, "Loot received (12,
 * 3 hidden)", explained in the header's tooltip ({@link #hiddenNote}), and an empty list then says they are all
 * hidden instead of "None". Subclasses call {@link #rebuild} at the end of their constructor.
 *
 * <p>The live task's lists are flat sections of the page under a sub-header ({@link #useSubHeader}): the title
 * in Bold in the heading colour over a 1 px rule, a value on the right ({@link #setHeaderValue}), always open, and
 * only the rows left out counted in the title, {@code Loot (3 hidden)} (DESIGN_PRINCIPLES.md 3.6). A list inside a
 * block of a flat section (Overall totals', a history row's details) has a quieter nested sub-header
 * ({@link #useNestedSubHeader}): Small, no rule. The advisor card's Bring grids sit on its parchment note
 * ({@link #useParchment}). EDT only.</p>
 *
 * @param <T> what one row is
 */
abstract class TitledListView<T> extends JPanel
{
	private final String title;
	private final boolean collapsible;
	private final JLabel titleLabel = new JLabel();
	private final JLabel toggleLabel = new JLabel();
	/** The sub-header's value on the right ({@link #setHeaderValue}); in the header only for a sub-header. */
	private final JLabel valueLabel = new JLabel();
	private final JPanel header = new JPanel(new BorderLayout(6, 0));
	/** What the header's tooltip says without hidden rows ({@code null}: no tooltip). */
	private final String headerTip;
	private final JPanel body = new JPanel();
	/** Rows shown; empty before the first {@link #setRows}. */
	private List<T> rows;
	/** Whether a collapsible list is open; always true otherwise. */
	@Getter
	private boolean expanded;
	/** Rows the caller left out of {@link #rows}, counted in the title; 0 for none. */
	private int hiddenCount;
	/** Whether the title shows the row count ({@link #hideCount}). */
	private boolean countShown = true;
	/** Whether the list is a flat section's sub-header ({@link #useSubHeader}). */
	private boolean subHeader;
	/** The colour of "None" and "All hidden": the hint colour, muted ink on parchment ({@link #useParchment}). */
	private Color noneColor = LedgerTheme.HINT;
	/** How many times the title and body were drawn ({@link #getBuildCount}). */
	private int builds;

	/** @param noun what the rows are, for the tooltips ("items", "skills") */
	TitledListView(String title, boolean collapsible, Color background, String noun)
	{
		this.title = title;
		this.collapsible = collapsible;
		this.expanded = !collapsible;
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(background);

		// Names for tests, which find the parts by them (searching from the list itself); no visible effect.
		header.setName("itemList.header");
		titleLabel.setName("itemList.title");
		toggleLabel.setName("itemList.toggle");
		valueLabel.setName("itemList.value");
		body.setName("itemList.body");
		header.setOpaque(false);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		titleLabel.setFont(FontManager.getRunescapeSmallFont());
		titleLabel.setForeground(collapsible ? LedgerTheme.VALUE : ColorScheme.LIGHT_GRAY_COLOR);
		header.add(titleLabel, BorderLayout.CENTER);
		if (collapsible)
		{
			toggleLabel.setFont(FontManager.getRunescapeSmallFont());
			toggleLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			header.add(toggleLabel, BorderLayout.EAST);
			header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			headerTip = "Click to show or hide the " + noun;
			header.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 1)
					{
						toggle();
					}
				}
			});
		}
		else
		{
			headerTip = null;
		}
		header.setToolTipText(headerTip);
		add(header);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setOpaque(false);
		body.setAlignmentX(Component.LEFT_ALIGNMENT);
		add(body);
		rows = Collections.emptyList();
	}

	/** Shows {@code newRows} (already sorted); nothing is rebuilt when they are the rows already shown. */
	void setRows(List<? extends T> newRows)
	{
		setRows(newRows, 0);
	}

	/**
	 * Shows {@code newRows} (already sorted), with {@code hidden} more left out by the caller; nothing is
	 * rebuilt when both are what is shown already.
	 */
	void setRows(List<? extends T> newRows, int hidden)
	{
		int newHidden = Math.max(0, hidden);
		if (newRows.equals(rows) && newHidden == hiddenCount)
		{
			return;
		}
		rows = new ArrayList<>(newRows);
		hiddenCount = newHidden;
		rebuild();
	}

	/**
	 * The header tooltip's lines on {@code hidden} rows left out (HTML, lines joined by {@code <br>}, no player or game
	 * text), or {@code null} to say nothing.
	 */
	String hiddenNote(int hidden)
	{
		return null;
	}

	/** Opens or closes a collapsible list, as a click on its title does. */
	void toggle()
	{
		if (collapsible)
		{
			expanded = !expanded;
			rebuild();
		}
	}

	/**
	 * The title as shown, with " | Show" or " | Hide" for a collapsible list, and " | " and the value for a sub-header
	 * with one.
	 */
	String getHeaderText()
	{
		if (collapsible)
		{
			return titleLabel.getText() + " | " + toggleLabel.getText();
		}
		String value = valueLabel.getText();
		return subHeader && value != null && !value.isEmpty() ? titleLabel.getText() + " | " + value
			: titleLabel.getText();
	}

	/**
	 * Makes the list a flat section of the page with a sub-header (DESIGN_PRINCIPLES.md 3.3, 3.6): the title in Bold in
	 * {@link LedgerTheme#HEADING} over a 1 px rule, a value on the right ({@link #setHeaderValue}), the page's
	 * background, and only the rows left out counted in the title. A collapsible list has no value: its
	 * {@code Show}/{@code Hide} stays on the right, in Small in {@link LedgerTheme#LABEL}, as a section header's. Call
	 * it once, after the constructor; a list nested in a block calls {@link #useNestedSubHeader} instead.
	 */
	void useSubHeader()
	{
		subHeader = true;
		countShown = false;
		setBackground(LedgerTheme.PAGE);
		LedgerTheme.styleSectionHeader(header, titleLabel, valueLabel);
		valueLabel.setForeground(LedgerTheme.VALUE);
		if (collapsible)
		{
			toggleLabel.setFont(LedgerTheme.smallFont());
			toggleLabel.setForeground(LedgerTheme.LABEL);
		}
		else
		{
			header.add(valueLabel, BorderLayout.EAST);
		}
		body.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		rebuild();
	}

	/**
	 * Makes the list a sub-header nested in a block of a flat section (phase 9d, Overall totals' Monsters
	 * assigned and item grids; phase 9c, a history row's item grids and XP list; DESIGN_PRINCIPLES.md 3.8): as
	 * {@link #useSubHeader}, but quieter than the block's title above it, so it is clear where one block ends and the
	 * next begins: the title in Small in {@link LedgerTheme#VALUE} with no rule under it
	 * ({@link LedgerTheme#styleNestedHeader}), a collapsible list's {@code Show}/{@code Hide} or another list's value
	 * still on the right in Small in {@link LedgerTheme#LABEL} (pass that colour to {@link #setHeaderValue}). Call it
	 * once, after the constructor, instead of {@link #useSubHeader}.
	 */
	final void useNestedSubHeader()
	{
		// The subclass's sub-header look first (the grid's stone cells, the list's colours), then the quieter title.
		useSubHeader();
		LedgerTheme.styleNestedHeader(header, titleLabel, collapsible ? toggleLabel : valueLabel);
		header.revalidate();
		header.repaint();
	}

	/**
	 * Makes the list part of the advisor's parchment note (DESIGN_PRINCIPLES.md 4.2): a plain title in
	 * Small in {@link LedgerTheme#INK} with no count, rule or tooltip, "None" in {@link LedgerTheme#MUTED_INK}, and no
	 * background of its own, so the note's {@link LedgerTheme#PARCHMENT} shows through. Meant for a list that isn't
	 * collapsible. Call it once, after the constructor.
	 */
	void useParchment()
	{
		countShown = false;
		noneColor = LedgerTheme.MUTED_INK;
		setOpaque(false);
		setBackground(LedgerTheme.PARCHMENT);
		titleLabel.setFont(LedgerTheme.smallFont());
		titleLabel.setForeground(LedgerTheme.INK);
		body.setBorder(BorderFactory.createEmptyBorder(2, 0, 0, 0));
		rebuild();
	}

	/**
	 * Shows {@code text} on the right of a sub-header ({@link #useSubHeader}) in {@code color}, with {@code tooltip}
	 * (HTML or {@code null}); the empty text for none. Only the label changes: nothing is rebuilt.
	 */
	void setHeaderValue(String text, Color color, String tooltip)
	{
		valueLabel.setText(text == null ? "" : text);
		valueLabel.setForeground(color);
		valueLabel.setToolTipText(tooltip);
	}

	/** Draws the title and, while the list is open, "None" or the rows ({@link #fillBody}). */
	final void rebuild()
	{
		builds++;
		titleLabel.setText(titleText());
		toggleLabel.setText(expanded ? "Hide" : "Show");
		String note = hiddenCount > 0 ? hiddenNote(hiddenCount) : null;
		header.setToolTipText(note == null ? headerTip
			: "<html>" + (headerTip == null ? "" : headerTip + ".<br>") + note + "</html>");
		body.removeAll();
		body.setVisible(expanded);
		if (expanded)
		{
			if (rows.isEmpty())
			{
				JPanel none = new JPanel(new BorderLayout());
				none.setOpaque(false);
				none.setAlignmentX(Component.LEFT_ALIGNMENT);
				none.setBorder(BorderFactory.createEmptyBorder(1, 0, 1, 0));
				none.add(label(hiddenCount > 0 ? "All hidden" : "None", noneColor),
					BorderLayout.CENTER);
				body.add(none);
			}
			else
			{
				fillBody(body, rows);
			}
		}
		revalidate();
		repaint();
	}

	/**
	 * "Title (12)", the rows shown, or "Title (12, 3 hidden)" when rows are left out; the same for collapsible and
	 * fixed lists.
	 */
	private String titleText()
	{
		if (!countShown)
		{
			return hiddenCount > 0 ? title + " (" + hiddenCount + " hidden)" : title;
		}
		return title + " (" + rows.size() + (hiddenCount > 0 ? ", " + hiddenCount + " hidden" : "") + ")";
	}

	/**
	 * Shows the plain title without the row count, for a list whose lines count something else (Monsters assigned:
	 * its lines are assignment shares, so a count of monsters in the title would read like a count of assignments).
	 */
	void hideCount()
	{
		countShown = false;
		titleLabel.setText(titleText());
	}

	/**
	 * Adds the components that show {@code shown} (never empty) to {@code body}, a vertical box; their alignment must
	 * be {@link Component#LEFT_ALIGNMENT}.
	 */
	abstract void fillBody(JPanel body, List<T> shown);

	/**
	 * How many times the title and body were drawn. Performance seam: tests assert this doesn't grow on the refresh
	 * timer.
	 */
	int getBuildCount()
	{
		return builds;
	}

	/** A label in the sidebar's small font. */
	static JLabel label(String text, Color color)
	{
		JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(FontManager.getRunescapeSmallFont());
		return label;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.client.util.Filepath;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Araxxor's harvest after its task-completing kill. Araxxor drops its loot only when the player harvests its
 * corpse, which can come after the task was saved. The harvest window ({@link SessionTracker#takeHarvestRecord}) opens
 * when a completion whose final kill was paired with Araxxor's death is released at the end of its grace window, and
 * takes one Araxxor loot of the same account within {@link SessionTracker#ARAXXOR_LOOT_MILLIS} of that kill, for the
 * task's record; the record takes it with {@link LedgerRecord#addLateLoot}, through {@link LedgerStore#addLoot}.
 * {@link HarnessAraxxorHarvestTest} covers the plugin's wiring.
 */
public class AraxxorHarvestTest
{
	private static final long ACCOUNT = 555L;
	private static final long OTHER_ACCOUNT = 556L;
	private static final int ARAXYTES = 105;
	private static final long MINUTE = 60_000L;
	private static final int WHIP = 4151;
	private static final int BONES = 526;
	private static final int UNPRICED = 9999;

	/** Whip 1.5M GE / 72K HA, bones 100 GE / 0 HA, coins at face value; {@link #UNPRICED} has no GE price yet. */
	private static final ItemValuation.PriceLookup PRICES = lookup(100);
	/** As {@link #PRICES}, but bones cost 150 now. */
	private static final ItemValuation.PriceLookup LATER_PRICES = lookup(150);

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		tracker.setAccount(ACCOUNT);
		observe(3, false);
	}

	private static ItemValuation.PriceLookup lookup(long bonesPrice)
	{
		return new ItemValuation.PriceLookup()
		{
			@Override
			public int canonicalize(int itemId)
			{
				return itemId;
			}

			@Override
			public long gePrice(int canonicalId)
			{
				return canonicalId == WHIP ? 1_500_000 : canonicalId == BONES ? bonesPrice : 0;
			}

			@Override
			public boolean isTradeable(int canonicalId)
			{
				return true;
			}

			@Override
			public long haPrice(int canonicalId)
			{
				return canonicalId == WHIP ? 72_000 : 0;
			}
		};
	}

	private static ItemTally tally(int... idQuantity)
	{
		final ItemTally tally = new ItemTally();
		for (int i = 0; i < idQuantity.length; i += 2)
		{
			tally.add(idQuantity[i], idQuantity[i + 1]);
		}
		return tally;
	}

	/** The task count reads {@code remaining}, with the NPCs named {@code paired} dying around it. */
	private SessionTracker.ObserveResult observe(int remaining, boolean completion, String... paired)
	{
		return tracker.observe("Araxytes", ARAXYTES, remaining, 3, TaskContext.NONE, LocationTally.NO_REGION, completion,
			paired.length == 0 ? KillPairing.NONE : KillPairing.of(now, Arrays.asList(paired)));
	}

	/**
	 * A 3-kill task: an araxyte, then a final kill with {@code finalPaired} dying around it, held for late loot.
	 *
	 * @return the held session's id
	 */
	private String completeAndHold(String... finalPaired)
	{
		now += MINUTE;
		observe(2, false, "Araxyte");
		assertEquals(SessionTracker.State.RUNNING, tracker.getState());
		now += MINUTE;
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, true, finalPaired));
		final String id = tracker.getSessionId();
		assertTrue(tracker.holdCompletion());
		return id;
	}

	/** Lets the grace window pass: the completion is released for saving. */
	private SessionTracker.Summary release()
	{
		SessionTracker.Summary summary = null;
		for (int i = 0; i < SessionTracker.COMPLETION_LOOT_GRACE_TICKS; i++)
		{
			summary = tracker.tickCompletion();
		}
		assertNotNull(summary);
		return summary;
	}

	// ---- The harvest window ----

	@Test
	public void theHarvestOfAnAraxxorFinalKillIsForItsRecordOnce()
	{
		final String id = completeAndHold("Araxxor");
		assertNull("not while held: the held task takes it", tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
		assertEquals(id, release().getSessionId());

		now += MINUTE;
		assertNull("another NPC's loot is not the harvest", tracker.takeHarvestRecord(ACCOUNT, "Araxyte"));
		assertNull("loot of an unknown NPC neither", tracker.takeHarvestRecord(ACCOUNT, null));
		assertEquals("Araxxor's, a minute after the kill", id, tracker.takeHarvestRecord(ACCOUNT, "araxxor"));
		assertNull("once per harvest", tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void theWindowLastsFiveMinutesFromTheKill()
	{
		final String id = completeAndHold("Araxxor");
		release();
		now += SessionTracker.ARAXXOR_LOOT_MILLIS;
		assertEquals("at 5 minutes", id, tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));

		setUp();
		completeAndHold("Araxxor");
		release();
		now += SessionTracker.ARAXXOR_LOOT_MILLIS + 1;
		assertNull("after 5 minutes", tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void onlyTheSameAccountsHarvestWithNoTaskKillSince()
	{
		completeAndHold("Araxxor");
		release();
		now += MINUTE;
		assertNull("another account", tracker.takeHarvestRecord(OTHER_ACCOUNT, "Araxxor"));
		assertNull("which ended the window", tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));

		setUp();
		completeAndHold("Araxxor");
		release();
		// A new task, and a kill on it: the corpse is long gone.
		now += MINUTE;
		tracker.observe("Kurask", 47, 20, 20, false);
		now += MINUTE;
		tracker.observe("Kurask", 47, 19, 20, TaskContext.NONE, LocationTally.NO_REGION, false, KillPairing.NONE);
		assertEquals(SessionTracker.State.RUNNING, tracker.getState());
		assertNull(tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void noWindowWhenTheFinalKillWasNotAraxxors()
	{
		// Araxxor died around an earlier kill; the final kill was an araxyte's.
		now += MINUTE;
		observe(2, false, "Araxxor");
		now += MINUTE;
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, true, "Araxyte"));
		assertTrue(tracker.holdCompletion());
		release();
		now += MINUTE;
		assertNull(tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));

		// Nothing paired at all (a kill nobody saw die).
		setUp();
		completeAndHold();
		release();
		now += MINUTE;
		assertNull(tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void araxxorsDeathOnTheTickAfterTheFinalKillCountsToo()
	{
		final String id = completeAndHold();
		final long killAt = tracker.getLastKillAt();
		tracker.pairKill(killAt, KillPairing.of(now, Collections.singletonList("Araxxor")));
		release();
		now += MINUTE;
		assertEquals(id, tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void aHarvestInTheGraceWindowGoesToTheHeldTaskAndOpensNoWindow()
	{
		completeAndHold("Araxxor");
		assertTrue(tracker.addLoot(tally(WHIP, 1), null, "Araxxor"));
		final SessionTracker.Summary summary = release();
		assertEquals(1, summary.getLoot().get(WHIP));
		now += MINUTE;
		assertNull(tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void aHarvestBeforeTheCompletionIsHeldOpensNoWindow()
	{
		// The count reads 0 before the completion confirms it; the harvest comes in between.
		now += MINUTE;
		observe(2, false, "Araxyte");
		now += MINUTE;
		assertEquals(SessionTracker.ObserveResult.TASK_CLEARED, observe(0, false, "Araxxor"));
		now += 600;
		assertTrue("the running session takes it", tracker.addLoot(tally(WHIP, 1), null, "Araxxor"));
		now += 600;
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, true));
		assertTrue(tracker.holdCompletion());
		assertEquals(1, release().getLoot().get(WHIP));
		now += MINUTE;
		assertNull("its record already has it", tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void aHarvestWithNoItemsKeptOpensNoWindow()
	{
		// All of it crushed or ignored: the plugin passes it on empty.
		completeAndHold("Araxxor");
		assertFalse(tracker.addLoot(new ItemTally(), null, "Araxxor"));
		release();
		now += MINUTE;
		assertNull(tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));

		// The same before the completion is held.
		setUp();
		now += MINUTE;
		observe(2, false, "Araxyte");
		now += MINUTE;
		observe(0, false, "Araxxor");
		assertFalse(tracker.addLoot(new ItemTally(), null, "Araxxor"));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, true));
		assertTrue(tracker.holdCompletion());
		release();
		now += MINUTE;
		assertNull(tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void anEarlierAraxxorsHarvestLeavesTheWindowOpen()
	{
		// Araxxor's loot before the final kill was another Araxxor's.
		assertFalse(tracker.addLoot(tally(WHIP, 1), null, "Araxxor"));
		final String id = completeAndHold("Araxxor");
		assertFalse("another NPC's loot is no harvest", tracker.addLoot(new ItemTally(), null, "Araxyte"));
		release();
		now += MINUTE;
		assertEquals(id, tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	@Test
	public void anEarlyReleaseEndsTheWindow()
	{
		// Released early (a logout, hop or account change during the grace window): no window.
		completeAndHold("Araxxor");
		assertNotNull(tracker.takePendingCompletion());
		now += MINUTE;
		assertNull(tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));

		// The same paths end an open window, also with nothing held.
		setUp();
		completeAndHold("Araxxor");
		release();
		assertNull(tracker.takePendingCompletion());
		now += MINUTE;
		assertNull(tracker.takeHarvestRecord(ACCOUNT, "Araxxor"));
	}

	// ---- The record ----

	/** A completed record with 2 bones, valued at {@link #PRICES}. */
	private static LedgerRecord valuedRecord()
	{
		final LedgerRecord record = new LedgerRecord();
		record.setId("r1");
		record.setMonster("Araxytes");
		record.setCompleted(true);
		record.setLoot(tally(BONES, 2).toMap());
		record.captureValues(PRICES);
		return record;
	}

	/** The harvest: a whip (notable), 3 bones, 5,000 coins and an item without a GE price yet. */
	private static ItemTally harvest()
	{
		return tally(WHIP, 1, BONES, 3, ItemValuation.COINS, 5_000, UNPRICED, 1);
	}

	@Test
	public void lateLootJoinsTheRecordAsIfItCameBeforeTheSave()
	{
		final LedgerRecord record = valuedRecord();
		assertEquals(Long.valueOf(200), record.getLootGeValue());
		final ItemValuation.UnitPrices prices = ItemValuationTest.capturePrices(harvest(), LATER_PRICES);
		final List<NotableDrop> drops = NotableDrops.find(harvest(), prices, LootPriceMode.GE, 100_000,
			itemId -> itemId == WHIP ? "Abyssal whip" : null, now);
		assertEquals(1, drops.size());

		assertTrue(record.addLateLoot(harvest(), prices, drops));
		final Map<Integer, Long> loot = new TreeMap<>();
		loot.put(BONES, 5L);
		loot.put(ItemValuation.COINS, 5_000L);
		loot.put(WHIP, 1L);
		loot.put(UNPRICED, 1L);
		assertEquals(loot, record.getLoot());
		assertEquals("the saved price is kept", Long.valueOf(100), record.getUnitGePrices().get(BONES));
		assertEquals(Long.valueOf(1_500_000), record.getUnitGePrices().get(WHIP));
		assertFalse(record.getUnitGePrices().containsKey(UNPRICED));
		assertEquals(Long.valueOf(72_000), record.getUnitHaPrices().get(WHIP));
		assertEquals(Long.valueOf(5 * 100 + 5_000 + 1_500_000), record.getLootGeValue());
		assertEquals(Long.valueOf(5_000 + 72_000), record.getLootHaValue());
		assertEquals(Integer.valueOf(1), record.getLootUnpricedItems());
		assertEquals(drops, record.getNotableDrops());
		assertNull("no supplies were recorded", record.getSuppliesGeValue());

		assertFalse("nothing to add", record.addLateLoot(new ItemTally(), prices, null));
	}

	@Test
	public void aRecordSavedWithoutValuesGetsTheItemsAndNotableDropsNoPrices()
	{
		final LedgerRecord record = new LedgerRecord();
		record.setId("r1");
		record.setLoot(tally(BONES, 2).toMap());
		final ItemValuation.UnitPrices prices = ItemValuationTest.capturePrices(tally(WHIP, 1), PRICES);
		final List<NotableDrop> drops = NotableDrops.find(tally(WHIP, 1), prices, LootPriceMode.GE, 100_000,
			itemId -> itemId == WHIP ? "Abyssal whip" : null, now);
		assertEquals(1, drops.size());
		assertTrue(record.addLateLoot(tally(WHIP, 1), prices, drops));
		assertEquals(Long.valueOf(1), record.getLoot().get(WHIP));
		assertEquals(Long.valueOf(2), record.getLoot().get(BONES));
		assertEquals("the notable drop is kept", drops, record.getNotableDrops());
		assertNull(record.getLootGeValue());
		assertNull(record.getLootHaValue());
		assertNull(record.getUnitGePrices());
		assertNull(record.getUnitHaPrices());
	}

	@Test
	public void theStoreAddsLateLootToThatRecordOnly() throws IOException
	{
		final Gson gson = new Gson();
		final File dir = new File(temp.getRoot(), "slayer-ledger");
		final LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(dir.toPath()), gson);
		final LedgerRecord other = valuedRecord();
		other.setId("other");
		store.append(ACCOUNT, other);
		store.append(ACCOUNT, valuedRecord());
		final File ledger = new File(dir, ACCOUNT + ".json");

		final ItemValuation.UnitPrices prices = ItemValuationTest.capturePrices(tally(WHIP, 1), PRICES);
		final List<LedgerRecord> records = store.addLoot(ACCOUNT, "r1", tally(WHIP, 1), prices, null);
		assertEquals(records, store.load(ACCOUNT));
		assertEquals(other, records.get(0));
		assertEquals(Long.valueOf(1), records.get(1).getLoot().get(WHIP));
		assertEquals(Long.valueOf(200 + 1_500_000), records.get(1).getLootGeValue());

		final String before = new String(Files.readAllBytes(ledger.toPath()), StandardCharsets.UTF_8);
		assertEquals(2, store.addLoot(ACCOUNT, "missing", tally(WHIP, 1), prices, null).size());
		assertEquals("a missing record changes nothing", before,
			new String(Files.readAllBytes(ledger.toPath()), StandardCharsets.UTF_8));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import org.junit.Test;

/**
 * {@link AssignmentLog}: the bound, the check against saved records, the order, and the row's monster name, tooltip
 * and delete confirmation.
 */
public class AssignmentLogTest
{
	private static final DateTimeFormatter DATE_TIME = DateTimeFormatter.ofPattern("M/d/yy, h:mm a", Locale.US)
		.withZone(ZoneOffset.UTC);
	/** 2026-10-26 12:00 UTC. */
	private static final long OCT_26 = 1_793_016_000_000L;

	static AssignmentEntry entry(String id, long endedAt)
	{
		AssignmentEntry e = new AssignmentEntry();
		e.setId(id);
		e.setMonster("Abyssal demons");
		e.setCreatureId(42);
		e.setOriginalAmount(120);
		e.setEndedAt(endedAt);
		e.setOutcome(AssignmentOutcome.SKIPPED);
		e.setPointsChange(-30);
		return e;
	}

	private static LedgerRecord record(int creatureId, Integer amount, boolean completed, long endedAt)
	{
		LedgerRecord r = new LedgerRecord();
		r.setId("r" + endedAt);
		r.setCreatureId(creatureId);
		r.setOriginalAmount(amount);
		r.setCompleted(completed);
		r.setPartial(!completed);
		r.setEndedAt(endedAt);
		return r;
	}

	@Test
	public void addKeepsTheNewestEntriesOldestFirst()
	{
		List<AssignmentEntry> entries = new ArrayList<>();
		for (int i = 0; i < AssignmentLog.MAX_ENTRIES; i++)
		{
			entries = AssignmentLog.add(entries, entry("e" + i, 1_000L + i));
		}
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		entries = AssignmentLog.add(entries, entry("newest", 5_000L));
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		assertEquals("the oldest went", "e1", entries.get(0).getId());
		assertEquals("newest", entries.get(entries.size() - 1).getId());
	}

	@Test
	public void anOlderEntryBeyondTheBoundIsNotKept()
	{
		List<AssignmentEntry> entries = new ArrayList<>();
		for (int i = 0; i < AssignmentLog.MAX_ENTRIES; i++)
		{
			entries.add(entry("e" + i, 1_000L + i));
		}
		entries = AssignmentLog.add(entries, entry("ancient", 1L));
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		assertTrue(entries.stream().noneMatch(e -> "ancient".equals(e.getId())));
	}

	@Test
	public void addIgnoresAnIdAlreadyThereAndNulls()
	{
		List<AssignmentEntry> entries = AssignmentLog.add(Arrays.asList(entry("a", 1L), null), entry("a", 2L));
		assertEquals(1, entries.size());
		assertEquals(1L, entries.get(0).getEndedAt());
		assertEquals(1, AssignmentLog.add(entries, null).size());
	}

	@Test
	public void sortNewestFirst()
	{
		List<AssignmentEntry> sorted = AssignmentLog.sortNewestFirst(Arrays.asList(entry("a", 1L), entry("b", 3L),
			null, entry("c", 2L)));
		assertEquals(Arrays.asList("b", "c", "a"), Arrays.asList(sorted.get(0).getId(), sorted.get(1).getId(),
			sorted.get(2).getId()));
		assertTrue(AssignmentLog.sortNewestFirst(null).isEmpty());
	}

	@Test
	public void playedBeforeWhenTheNewestRecordIsAPartialOfTheSameTask()
	{
		AssignmentEntry e = entry("a", 9_000L);
		assertTrue(AssignmentLog.playedBefore(Arrays.asList(record(46, 150, true, 1_000L), record(42, 120, false, 2_000L)),
			e));
		assertTrue("size unknown in the record", AssignmentLog.playedBefore(
			Collections.singletonList(record(42, null, false, 2_000L)), e));
	}

	@Test
	public void notPlayedBeforeOtherwise()
	{
		AssignmentEntry e = entry("a", 9_000L);
		assertFalse("no records", AssignmentLog.playedBefore(Collections.emptyList(), e));
		assertFalse("completed: that assignment ended", AssignmentLog.playedBefore(
			Collections.singletonList(record(42, 120, true, 2_000L)), e));
		assertFalse("another task", AssignmentLog.playedBefore(
			Collections.singletonList(record(46, 120, false, 2_000L)), e));
		assertFalse("another size", AssignmentLog.playedBefore(
			Collections.singletonList(record(42, 200, false, 2_000L)), e));
		assertFalse("only the newest counts", AssignmentLog.playedBefore(
			Arrays.asList(record(42, 120, false, 1_000L), record(46, 150, true, 2_000L)), e));
		e.setCreatureId(null);
		assertFalse("unknown task", AssignmentLog.playedBefore(
			Collections.singletonList(record(42, 120, false, 2_000L)), e));
	}

	@Test
	public void monsterFallsBackToUnknownTask()
	{
		assertEquals("Abyssal demons", AssignmentLog.monster(entry("a", OCT_26)));
		AssignmentEntry e = entry("a", OCT_26);
		e.setMonster(null);
		assertEquals("Unknown task", AssignmentLog.monster(e));
		e.setMonster("");
		assertEquals("Unknown task", AssignmentLog.monster(e));
	}

	@Test
	public void tooltipShowsKnownPartsOnly()
	{
		AssignmentEntry e = entry("a", OCT_26);
		e.setSlayerMaster(5);
		assertEquals("<html>Abyssal demons<br>Skipped (cancelled for points)<br>Ended: 10/26/26, 12:00 PM"
			+ "<br>Master: Duradel/Kuradal<br>Type: Regular<br>Assigned: 120<br>Points: -30</html>",
			AssignmentLog.tooltip(e, DATE_TIME));

		AssignmentEntry bare = new AssignmentEntry();
		bare.setOutcome(AssignmentOutcome.COMPLETED);
		bare.setMonster("<b>x</b>");
		assertEquals("<html>&lt;b&gt;x&lt;/b&gt;<br>Completed without a tracked session</html>",
			AssignmentLog.tooltip(bare, DATE_TIME));

		AssignmentEntry konar = entry("k", OCT_26);
		konar.setSlayerMaster(SlayerMaster.KONAR);
		konar.setTaskLocation("Kraken Cove");
		konar.setSlayerArea(12);
		konar.setPointsChange(18);
		konar.setOutcome(AssignmentOutcome.COMPLETED);
		String tip = AssignmentLog.tooltip(konar, DATE_TIME);
		assertTrue(tip, tip.contains("<br>Type: Konar (Kraken Cove)<br>"));
		assertTrue(tip, tip.endsWith("<br>Points: +18</html>"));
	}

	@Test
	public void deleteConfirmation()
	{
		assertEquals("Delete this Abyssal demons entry (skipped)? This can't be undone.",
			AssignmentLog.deleteConfirmation(entry("a", 1L)));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/** {@link AssignmentOutcome#classify}: every outcome, and the ambiguous cases that must stay unknown. */
public class AssignmentOutcomeTest
{
	private static AssignmentOutcome classify(boolean completed, Integer points, boolean blocked, boolean streakDropped)
	{
		return AssignmentOutcome.classify(completed, points, blocked, streakDropped);
	}

	@Test
	public void pointsSpentWithoutABlockIsASkip()
	{
		assertEquals(AssignmentOutcome.SKIPPED, classify(false, -30, false, false));
		// Costs vary by master; any amount counts.
		assertEquals(AssignmentOutcome.SKIPPED, classify(false, -100, false, false));
		assertEquals(AssignmentOutcome.SKIPPED, classify(false, -1, false, false));
	}

	@Test
	public void pointsSpentWithABlockChangeIsABlock()
	{
		assertEquals(AssignmentOutcome.BLOCKED, classify(false, -100, true, false));
		assertEquals(AssignmentOutcome.BLOCKED, classify(false, -40, true, false));
	}

	@Test
	public void aStreakDropWithNoPointsSpentIsAReset()
	{
		assertEquals(AssignmentOutcome.RESET, classify(false, 0, false, true));
	}

	@Test
	public void aCompletionIsCompleted()
	{
		assertEquals(AssignmentOutcome.COMPLETED, classify(true, 15, false, false));
		assertEquals("no points (an early task)", AssignmentOutcome.COMPLETED, classify(true, 0, false, false));
		assertEquals("points not read", AssignmentOutcome.COMPLETED, classify(true, null, false, false));
	}

	@Test
	public void nothingChangedIsUnknown()
	{
		assertEquals(AssignmentOutcome.UNKNOWN, classify(false, 0, false, false));
	}

	@Test
	public void ambiguousSignalsAreUnknown()
	{
		assertEquals("completion and streak reset", AssignmentOutcome.UNKNOWN, classify(true, 15, false, true));
		assertEquals("completion and block", AssignmentOutcome.UNKNOWN, classify(true, -85, true, false));
		assertEquals("points spent and streak reset", AssignmentOutcome.UNKNOWN, classify(false, -30, false, true));
		assertEquals("points spent, block and streak reset", AssignmentOutcome.UNKNOWN,
			classify(false, -100, true, true));
		assertEquals("points up without a completion", AssignmentOutcome.UNKNOWN, classify(false, 20, false, false));
		assertEquals("a block without points spent", AssignmentOutcome.UNKNOWN, classify(false, 0, true, false));
		assertEquals("reset with a block change", AssignmentOutcome.UNKNOWN, classify(false, 0, true, true));
		assertEquals("points unknown", AssignmentOutcome.UNKNOWN, classify(false, null, false, false));
		assertEquals("points unknown with a block", AssignmentOutcome.UNKNOWN, classify(false, null, true, false));
		assertEquals("points unknown with a streak drop", AssignmentOutcome.UNKNOWN, classify(false, null, false, true));
	}

	@Test
	public void aMissingOutcomeReadsAsUnknown()
	{
		assertEquals(AssignmentOutcome.UNKNOWN, AssignmentOutcome.orUnknown(null));
		assertEquals(AssignmentOutcome.BLOCKED, AssignmentOutcome.orUnknown(AssignmentOutcome.BLOCKED));
		assertEquals("Ended (reason unknown)", AssignmentOutcome.UNKNOWN.getDescription());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link AssignmentWatch}: which assignment ends produce an entry, with which outcome, and the guards (played tasks,
 * transient zeros, logins). The readings come from a small fake of the game's values, with a real
 * {@link CompletionSignal} as in the plugin.
 */
public class AssignmentWatchTest
{
	private static final int DEMONS = 42;
	private static final int GARGOYLES = 46;

	private final AssignmentWatch watch = new AssignmentWatch();
	private final CompletionSignal completionSignal = new CompletionSignal();
	private final List<AssignmentWatch.Ended> ended = new ArrayList<>();
	private long now = 1_000_000L;

	// The fake game's values.
	private String monster;
	private int creatureId = SessionTracker.NO_CREATURE;
	private int remaining;
	private int amount;
	private int master = SlayerMaster.NONE;
	private int points = 500;
	private int[] counters = {10, 0, 0};
	private int[] blocked = {0, 0, 0};
	/** Keys a session held this tick. */
	private Set<Integer> sessionKeys = Collections.emptySet();

	@Before
	public void setUp()
	{
		// The first readings after a start only sync; with no task, the sync ends after SYNC_MAX_TICKS.
		clearTask();
		ticks(AssignmentWatch.SYNC_MAX_TICKS);
		// Then the task is assigned while watched.
		assign("Abyssal demons", DEMONS, 120, 5);
		tick();
		assertTrue(watch.hasCurrent());
		assertTrue(ended.isEmpty());
	}

	private void assign(String name, int key, int count, int byMaster)
	{
		monster = name;
		creatureId = key;
		remaining = count;
		amount = count;
		master = byMaster;
	}

	private void clearTask()
	{
		monster = null;
		creatureId = SessionTracker.NO_CREATURE;
		remaining = 0;
		amount = 0;
		master = SlayerMaster.NONE;
	}

	private void tick()
	{
		final boolean completion = completionSignal.update(counters);
		final TaskContext context = remaining > 0 ? TaskContext.assignment(master, 0, null) : TaskContext.NONE;
		ended.addAll(watch.update(AssignmentWatch.Reading.builder().monster(monster).creatureId(creatureId)
			.remaining(remaining).originalAmount(amount).context(context).points(points).counters(counters.clone())
			.blockedValues(blocked.clone()).completionSignaled(completion).build(), sessionKeys, now));
		now += 600;
	}

	private void ticks(int n)
	{
		for (int i = 0; i < n; i++)
		{
			tick();
		}
	}

	/** Ticks out the decision window. */
	private void settle()
	{
		ticks(AssignmentWatch.END_WINDOW_TICKS + 1);
	}

	private void login()
	{
		watch.reset();
		completionSignal.reset();
	}

	private AssignmentEntry only()
	{
		assertEquals(ended.toString(), 1, ended.size());
		return ended.get(0).getEntry();
	}

	@Test
	public void aSkipIsRecordedWithThePointsSpent()
	{
		remaining = 80;
		tick();
		final long endTime = now;
		clearTask();
		points -= 30;
		settle();

		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.SKIPPED, e.getOutcome());
		assertEquals(Integer.valueOf(-30), e.getPointsChange());
		assertEquals("Abyssal demons", e.getMonster());
		assertEquals(Integer.valueOf(DEMONS), e.getCreatureId());
		assertEquals(Integer.valueOf(120), e.getOriginalAmount());
		assertEquals(Integer.valueOf(5), e.getSlayerMaster());
		assertEquals("the first tick it was gone", endTime, e.getEndedAt());
		assertNotNull(e.getId());
		assertFalse("watched from its start", ended.get(0).isCheckRecords());
	}

	@Test
	public void theOutcomeIsDecidedAfterTheWindow()
	{
		clearTask();
		points -= 30;
		ticks(AssignmentWatch.END_WINDOW_TICKS);
		assertTrue("not yet", ended.isEmpty());
		tick();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
	}

	@Test
	public void pointsArrivingLateInTheWindowStillCount()
	{
		clearTask();
		tick();
		points -= 30;
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
		assertEquals(Integer.valueOf(-30), only().getPointsChange());
	}

	@Test
	public void aSkipFollowedQuicklyByANewTaskIsStillASkip()
	{
		clearTask();
		points -= 30;
		tick();
		assign("Gargoyles", GARGOYLES, 150, 5);
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
		assertEquals("Abyssal demons", only().getMonster());
		assertTrue("the new task is watched", watch.hasCurrent());
	}

	@Test
	public void aBlockIsRecorded()
	{
		clearTask();
		points -= 100;
		blocked[1] = DEMONS;
		settle();
		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.BLOCKED, e.getOutcome());
		assertEquals(Integer.valueOf(-100), e.getPointsChange());
	}

	@Test
	public void aTuraelResetIsRecorded()
	{
		// Turael gives a new task straight away and the streak drops to 0; no points are spent.
		assign("Cows", 6, 20, 1);
		counters[0] = 0;
		settle();
		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.RESET, e.getOutcome());
		assertEquals("Abyssal demons", e.getMonster());
		assertEquals(Integer.valueOf(0), e.getPointsChange());
	}

	@Test
	public void aCompletionWithoutASessionIsRecorded()
	{
		remaining = 1;
		tick();
		clearTask();
		counters[0]++;
		points += 15;
		settle();
		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.COMPLETED, e.getOutcome());
		assertEquals(Integer.valueOf(15), e.getPointsChange());
	}

	@Test
	public void aStreakArrivingAfterTheCountStillCountsAsACompletion()
	{
		clearTask();
		tick();
		counters[0]++;
		points += 15;
		settle();
		assertEquals(AssignmentOutcome.COMPLETED, only().getOutcome());
	}

	@Test
	public void anEndThatFitsNothingIsUnknownOnceTheNextTaskAppears()
	{
		// Count to 0 with nothing else changing (for example the task was stored).
		clearTask();
		settle();
		assertTrue("an unknown end by a 0 count waits", ended.isEmpty());
		ticks(20);
		assertTrue(ended.isEmpty());
		assign("Gargoyles", GARGOYLES, 150, 5);
		tick();
		AssignmentEntry e = only();
		assertEquals(AssignmentOutcome.UNKNOWN, e.getOutcome());
		assertEquals(Integer.valueOf(0), e.getPointsChange());
	}

	@Test
	public void aDirectChangeThatFitsNothingIsUnknown()
	{
		assign("Gargoyles", GARGOYLES, 150, 5);
		settle();
		assertEquals(AssignmentOutcome.UNKNOWN, only().getOutcome());
	}

	@Test
	public void theUnknownOutcomeUsesTheWindowsReadings()
	{
		clearTask();
		settle();
		// Points spent long after the end (a reward bought) don't turn it into a skip.
		points -= 30;
		ticks(5);
		assign("Gargoyles", GARGOYLES, 150, 5);
		tick();
		assertEquals(AssignmentOutcome.UNKNOWN, only().getOutcome());
		assertEquals(Integer.valueOf(0), only().getPointsChange());
	}

	@Test
	public void aTransientZeroIsNotAnEnd()
	{
		remaining = 80;
		tick();
		clearTask();
		ticks(2);
		assign("Abyssal demons", DEMONS, 120, 5);
		remaining = 80;
		settle();
		assertTrue(ended.isEmpty());
		assertFalse(watch.hasPending());
	}

	@Test
	public void theSameTaskAfterALongZeroIsNotAnEnd()
	{
		remaining = 80;
		tick();
		clearTask();
		ticks(20);
		assign("Abyssal demons", DEMONS, 120, 5);
		remaining = 79;
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void theSameCreatureWithMoreLeftAfterALongZeroIsANewAssignment()
	{
		remaining = 80;
		tick();
		clearTask();
		ticks(20);
		assign("Abyssal demons", DEMONS, 120, 5);
		tick();
		assertEquals(AssignmentOutcome.UNKNOWN, only().getOutcome());
	}

	@Test
	public void killsOnTheTaskAreNotAnEnd()
	{
		for (int i = 0; i < 10; i++)
		{
			remaining--;
			tick();
		}
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void aPlayedTaskIsNeverRecorded()
	{
		sessionKeys = Collections.singleton(DEMONS);
		tick();
		sessionKeys = Collections.emptySet();
		clearTask();
		points -= 30;
		settle();
		assertTrue("skipped after a session", ended.isEmpty());
	}

	@Test
	public void aCompletedPlayedTaskIsNeverRecorded()
	{
		sessionKeys = Collections.singleton(DEMONS);
		clearTask();
		counters[0]++;
		tick();
		sessionKeys = Collections.emptySet();
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void aSessionTakingTheTaskOnTheEndTickStillCounts()
	{
		clearTask();
		points -= 30;
		// Reported on the tick the count dropped (for example Play pressed and Stopped within one tick).
		sessionKeys = Collections.singleton(DEMONS);
		tick();
		sessionKeys = Collections.emptySet();
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void aSessionOnAnotherTaskDoesNotMarkThisOne()
	{
		sessionKeys = new HashSet<>(Collections.singletonList(GARGOYLES));
		tick();
		sessionKeys = Collections.emptySet();
		clearTask();
		points -= 30;
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
	}

	@Test
	public void theFirstReadingAfterALoginProducesNothing()
	{
		login();
		// The task was skipped while logged out (on another client): the login resync shows a new task.
		points -= 30;
		assign("Gargoyles", GARGOYLES, 150, 5);
		tick();
		settle();
		assertTrue(ended.isEmpty());
		assertTrue(watch.hasCurrent());
	}

	@Test
	public void aZeroCountWhileTheLoginSyncsProducesNothing()
	{
		login();
		clearTask();
		points = 0;
		ticks(3);
		assign("Abyssal demons", DEMONS, 120, 5);
		points = 500;
		settle();
		assertTrue(ended.isEmpty());
	}

	@Test
	public void anAssignmentActiveAtLogoutKeepsItsPlayedFlag()
	{
		sessionKeys = Collections.singleton(DEMONS);
		tick();
		sessionKeys = Collections.emptySet();
		login();
		tick();
		clearTask();
		points -= 30;
		settle();
		assertTrue("played before the logout", ended.isEmpty());
	}

	@Test
	public void anUndecidedEndIsDroppedByALogin()
	{
		clearTask();
		points -= 30;
		tick();
		login();
		settle();
		assertTrue(ended.isEmpty());
		assertFalse(watch.hasPending());
	}

	@Test
	public void anAssignmentFirstSeenAtAStartIsCheckedAgainstTheRecords()
	{
		watch.forget();
		completionSignal.reset();
		tick();
		clearTask();
		points -= 30;
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, only().getOutcome());
		assertTrue(ended.get(0).isCheckRecords());
	}

	@Test
	public void forgettingDropsThePlayedFlag()
	{
		sessionKeys = Collections.singleton(DEMONS);
		tick();
		sessionKeys = Collections.emptySet();
		// Another account logged in.
		watch.forget();
		tick();
		clearTask();
		points -= 30;
		settle();
		assertEquals(1, ended.size());
	}

	@Test
	public void aSecondEndInsideTheWindowDecidesTheFirstAtOnce()
	{
		// Turael reset to cows, then the cows task is skipped straight away.
		assign("Cows", 6, 20, 1);
		counters[0] = 0;
		tick();
		clearTask();
		points -= 30;
		tick();
		assertEquals(1, ended.size());
		assertEquals("Abyssal demons", ended.get(0).getEntry().getMonster());
		assertEquals("judged before the skip", AssignmentOutcome.RESET, ended.get(0).getEntry().getOutcome());
		settle();
		assertEquals(2, ended.size());
		assertEquals("Cows", ended.get(1).getEntry().getMonster());
		assertEquals(AssignmentOutcome.SKIPPED, ended.get(1).getEntry().getOutcome());
	}

	@Test
	public void noTaskAtAllProducesNothing()
	{
		clearTask();
		login();
		ticks(AssignmentWatch.SYNC_MAX_TICKS + 5);
		assertTrue(ended.isEmpty());
		assertFalse(watch.hasCurrent());
	}

	@Test
	public void unknownPartsAreStoredAsNull()
	{
		watch.forget();
		completionSignal.reset();
		monster = null;
		amount = 0;
		master = SlayerMaster.NONE;
		tick();
		clearTask();
		points -= 30;
		settle();
		AssignmentEntry e = only();
		assertNull(e.getMonster());
		assertNull(e.getOriginalAmount());
		assertNull(e.getSlayerMaster());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import net.runelite.api.Skill;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * The style of one of the player's attacks ({@link AttackStyles}): the cast animations, and each weapon's style
 * from its equipment stats. The stats are the OSRS Wiki's Infobox Bonuses (stab, slash, crush, magic and ranged attack,
 * ranged strength), read on 2026-11-09, which RuneLite's item stats copy.
 */
public class AttackStylesTest
{
	private static SetupStyle weapon(int stab, int slash, int crush, int magic, int range, int rangedStrength)
	{
		return AttackStyles.weaponStyle(stab, slash, crush, magic, range, rangedStrength);
	}

	@Test
	public void theCastAnimationsAreTheGameValuesThePlanNames()
	{
		assertEquals(1979, AnimationID.ZAROS_VERTICAL_CASTING);
		assertEquals(10092, AnimationID.ZAROS_VERTICAL_CASTING_WALKMERGE);
		assertEquals(7753, AnimationID.ZAROS_VERTICAL_CASTING_PRIORITY);
		assertEquals(1978, AnimationID.ZAROS_CASTING);
		assertEquals(10091, AnimationID.ZAROS_CASTING_WALKMERGE);
	}

	@Test
	public void burstAndBarrageCastsAreBarrageWhateverIsWielded()
	{
		for (int animation : new int[]{1979, 10092, 7753})
		{
			assertEquals(SetupStyle.BARRAGE, AttackStyles.attackStyle(animation, SetupStyle.MAGIC));
			assertEquals("a staff with melee bonuses", SetupStyle.BARRAGE,
				AttackStyles.attackStyle(animation, SetupStyle.MELEE));
			assertEquals("the weapon's stats not loaded", SetupStyle.BARRAGE, AttackStyles.attackStyle(animation, null));
			assertTrue(AttackStyles.isSpell(animation));
		}
	}

	@Test
	public void rushBlitzAndOtherSpellsAreMagic()
	{
		// Rush and Blitz, standing and walking.
		for (int animation : new int[]{1978, 10091})
		{
			assertEquals(SetupStyle.MAGIC, AttackStyles.attackStyle(animation, SetupStyle.MELEE));
		}
		// A wave (also a trident's cast), a surge, Iban Blast, Magic Dart, a god spell and an Arceuus demonbane.
		for (int animation : new int[]{AnimationID.HUMAN_CASTWAVE_STAFF, AnimationID.HUMAN_CAST_SURGE,
			AnimationID.HUMAN_CAST_SURGE_WALKMERGE, AnimationID.HUMAN_CASTIBANBLAST, AnimationID.SLAYER_MAGICDART_CAST,
			AnimationID.HUMAN_CASTING, AnimationID.HUMAN_SPELLCAST_DEMONBANE})
		{
			assertEquals(SetupStyle.MAGIC, AttackStyles.attackStyle(animation, SetupStyle.MELEE));
		}
	}

	@Test
	public void anyOtherAnimationIsTheWeaponsStyle()
	{
		final int whipAttack = 1658;
		assertEquals(SetupStyle.MELEE, AttackStyles.attackStyle(whipAttack, SetupStyle.MELEE));
		assertEquals(SetupStyle.RANGED, AttackStyles.attackStyle(whipAttack, SetupStyle.RANGED));
		assertNull("no style without the weapon's", AttackStyles.attackStyle(whipAttack, null));
		assertFalse(AttackStyles.isSpell(whipAttack));
	}

	@Test
	public void noAnimationAndEatingAreNeverAttacks()
	{
		assertFalse(AttackStyles.mayBeAttack(-1));
		assertFalse(AttackStyles.mayBeAttack(AnimationID.HUMAN_EAT));
		assertTrue(AttackStyles.mayBeAttack(1658));
		assertTrue(AttackStyles.mayBeAttack(1979));
	}

	@Test
	public void meleeWeaponsAreMelee()
	{
		// stab, slash, crush, magic, range, ranged strength
		assertEquals("Abyssal whip", SetupStyle.MELEE, weapon(0, 82, 0, 0, 0, 0));
		assertEquals("Abyssal tentacle", SetupStyle.MELEE, weapon(0, 90, 0, 0, 0, 0));
		assertEquals("Scythe of vitur", SetupStyle.MELEE, weapon(70, 125, 30, -6, 0, 0));
		assertEquals("Ghrazi rapier", SetupStyle.MELEE, weapon(100, 55, 0, 0, 0, 0));
		assertEquals("Osmumten's fang", SetupStyle.MELEE, weapon(105, 75, 0, 0, 0, 0));
		assertEquals("Blade of saeldor", SetupStyle.MELEE, weapon(55, 100, 0, 0, 0, 0));
		assertEquals("Dragon hunter lance", SetupStyle.MELEE, weapon(85, 65, 65, 0, 0, 0));
		assertEquals("Abyssal bludgeon", SetupStyle.MELEE, weapon(0, 0, 102, 0, 0, 0));
		assertEquals("Armadyl godsword", SetupStyle.MELEE, weapon(0, 132, 80, 0, 0, 0));
		assertEquals("Dragon scimitar", SetupStyle.MELEE, weapon(8, 67, -2, 0, 0, 0));
		assertEquals("Arclight", SetupStyle.MELEE, weapon(10, 38, 0, 0, 0, 0));
		assertEquals("Emberlight", SetupStyle.MELEE, weapon(63, 70, 0, 0, 0, 0));
		assertEquals("Keris partisan", SetupStyle.MELEE, weapon(58, -2, 57, 2, 0, 0));
		assertEquals("Voidwaker", SetupStyle.MELEE, weapon(70, 80, -2, 5, 0, 0));
		assertEquals("Inquisitor's mace", SetupStyle.MELEE, weapon(52, -4, 102, 0, 0, 0));
		assertEquals("Soulreaper axe", SetupStyle.MELEE, weapon(28, 134, 66, 0, 0, 0));
		assertEquals("Noxious halberd", SetupStyle.MELEE, weapon(80, 132, 0, 0, 0, 0));
		assertEquals("Elder maul", SetupStyle.MELEE, weapon(0, 0, 135, 0, 0, 0));
		assertEquals("Dragon claws", SetupStyle.MELEE, weapon(41, 57, -4, 0, 0, 0));
		assertEquals("Dragon warhammer", SetupStyle.MELEE, weapon(-4, -4, 95, -4, 0, 0));
		assertEquals("Zamorakian hasta", SetupStyle.MELEE, weapon(85, 65, 65, 0, 0, 0));
		assertEquals("Dual macuahuitl", SetupStyle.MELEE, weapon(115, -4, 121, -4, 0, 0));
	}

	@Test
	public void staffsWithMeleeBonusesAreMeleeAndTheirCastsMagic()
	{
		assertEquals("Staff of the dead", SetupStyle.MELEE, weapon(55, 70, 0, 17, 0, 0));
		assertEquals("Toxic staff of the dead", SetupStyle.MELEE, weapon(55, 70, 0, 25, 0, 0));
		assertEquals("Staff of light", SetupStyle.MELEE, weapon(55, 70, 0, 17, 0, 0));
		assertEquals("Ahrim's staff", SetupStyle.MELEE, weapon(12, -1, 65, 15, 0, 0));
		assertEquals("Ancient staff", SetupStyle.MELEE, weapon(10, -1, 40, 15, 0, 0));
		assertEquals("Iban's staff", SetupStyle.MELEE, weapon(10, -1, 40, 10, 0, 0));
		assertEquals("Slayer's staff", SetupStyle.MELEE, weapon(7, -1, 25, 12, 0, 0));
		// The OSRS Wiki's bonuses, read on 2026-11-09: so its block, if it read as an attack, would be Melee.
		assertEquals("Ancient sceptre", SetupStyle.MELEE, weapon(20, -1, 50, 20, 0, 0));
		// Their autocast spells are told by the cast animation: a surge from Ahrim's staff, Iban Blast, Magic Dart.
		assertEquals(SetupStyle.MAGIC, AttackStyles.attackStyle(AnimationID.HUMAN_CAST_SURGE, SetupStyle.MELEE));
		assertEquals(SetupStyle.MAGIC, AttackStyles.attackStyle(AnimationID.HUMAN_CASTIBANBLAST, SetupStyle.MELEE));
		assertEquals(SetupStyle.MAGIC, AttackStyles.attackStyle(AnimationID.SLAYER_MAGICDART_CAST, SetupStyle.MELEE));
	}

	@Test
	public void rangedWeaponsAreRanged()
	{
		assertEquals("Toxic blowpipe (charged)", SetupStyle.RANGED, weapon(0, 0, 0, 0, 30, 20));
		assertEquals("Toxic blowpipe (empty)", SetupStyle.RANGED, weapon(0, 0, 0, 0, 30, 0));
		assertEquals("Twisted bow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 70, 20));
		assertEquals("Bow of faerdhinen", SetupStyle.RANGED, weapon(0, 0, 0, 0, 128, 106));
		assertEquals("Magic shortbow (i)", SetupStyle.RANGED, weapon(0, 0, 0, 0, 75, 0));
		assertEquals("Crystal bow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 100, 78));
		assertEquals("Dark bow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 95, 0));
		assertEquals("Venator bow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 90, 25));
		assertEquals("Webweaver bow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 85, 65));
		assertEquals("Rune crossbow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 90, 0));
		assertEquals("Armadyl crossbow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 100, 0));
		assertEquals("Dragon hunter crossbow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 95, 0));
		assertEquals("Zaryte crossbow", SetupStyle.RANGED, weapon(0, 0, 0, 0, 110, 0));
		assertEquals("Heavy ballista", SetupStyle.RANGED, weapon(0, 0, 0, 0, 125, 15));
		assertEquals("Dragon dart: no ranged attack bonus, only ranged strength", SetupStyle.RANGED,
			weapon(0, 0, 0, 0, 0, 35));
		assertEquals("Dragon knife", SetupStyle.RANGED, weapon(0, 0, 0, 0, 28, 30));
		assertEquals("Red chinchompa", SetupStyle.RANGED, weapon(0, 0, 0, 0, 70, 15));
		assertEquals("Black chinchompa", SetupStyle.RANGED, weapon(0, 0, 0, 0, 80, 30));
		assertEquals("Eclipse atlatl: ranged with melee strength", SetupStyle.RANGED, weapon(0, 0, 0, 0, 87, 0));
