	@Test
	public void selectionsCompareByValueAndKeyTheCannon()
	{
		assertSame(TaskSelection.ANY, TaskSelection.ANY.withCannon(null));
		assertSame(TaskSelection.ANY, TaskSelection.ANY.withCannon(true).withCannon(null));
		assertSame(TaskSelection.STANDARD, TaskSelection.STANDARD.withCannon(false).withCannon(null));
		assertNotEquals(TaskSelection.ANY, TaskSelection.ANY.withCannon(true));
		assertNotEquals(TaskSelection.ANY.withCannon(true), TaskSelection.ANY.withCannon(false));
		assertNotEquals(TaskSelection.ANY.withCannon(true).key(), TaskSelection.STANDARD.withCannon(true).key());
		assertEquals(TaskSelection.of("Deviant spectres").withCannon(true),
			TaskSelection.of("deviant SPECTRES").withCannon(true));
		assertEquals(TaskSelection.ANY.withCannon(true), TaskSelection.of(DEVIANT).withCannon(true).withAnyVariant());
		assertTrue(TaskSelection.ANY.withCannon(true).isAnyVariant());
		assertNull(TaskSelection.ANY.withCannon(true).getVariant());

		assertEquals(DEVILS, TaskSelection.ANY.displayName(DEVILS));
		assertEquals("without a cannon limit nothing is added", DEVILS,
			TaskSelection.ANY.withCannon(false).displayName(DEVILS));
		assertEquals(DEVIANT, TaskSelection.of(DEVIANT).displayName(SPECTRE_TASK));
	}

	// ---- Per-task statistics and overlay text ----

	@Test
	public void afterACannonballTheStatisticsUseCannonTasksOnlyWhenThereAreSome()
	{
		TaskSelection cannon = TaskSelection.ANY.withCannon(true);
		List<LedgerRecord> plain = Arrays.asList(record(DUST_DEVILS, DEVILS, null, false, 10, HOUR),
			record(DUST_DEVILS, DEVILS, null, false, 20, HOUR));
		assertSame("no cannon tasks: pooled, as before the cannonball", TaskSelection.ANY,
			TaskStatistics.effectiveSelection(plain, DUST_DEVILS, DEVILS, cannon));
		assertEquals(2, devilStats(plain, TaskStatistics.effectiveSelection(plain, DUST_DEVILS, DEVILS, cannon))
			.getSampleCount());

		List<LedgerRecord> mixed = new ArrayList<>(plain);
		mixed.add(record(DUST_DEVILS, DEVILS, null, true, 10, HOUR));
		assertEquals("one cannon task: cannon tasks only", cannon,
			TaskStatistics.effectiveSelection(mixed, DUST_DEVILS, DEVILS, cannon));
		assertEquals(1, devilStats(mixed, TaskStatistics.effectiveSelection(mixed, DUST_DEVILS, DEVILS, cannon))
			.getSampleCount());

		// Another task's cannon tasks, or an unfinished one, don't count.
		List<LedgerRecord> others = new ArrayList<>(plain);
		others.add(record(SPECTRES, SPECTRE_TASK, null, true, 10, HOUR));
		LedgerRecord partial = record(DUST_DEVILS, DEVILS, null, true, 10, HOUR);
		partial.setCompleted(false);
		others.add(partial);
		assertSame(TaskSelection.ANY, TaskStatistics.effectiveSelection(others, DUST_DEVILS, DEVILS, cannon));

		// Without a cannonball the selection stays, whatever the history.
		assertSame(TaskSelection.ANY, TaskStatistics.effectiveSelection(mixed, DUST_DEVILS, DEVILS, TaskSelection.ANY));
		assertSame(TaskSelection.ANY, TaskStatistics.effectiveSelection(mixed, DUST_DEVILS, DEVILS, null));

		// The version stays: a Deviant spectres cannon task needs a Deviant spectres one in the history.
		TaskSelection deviantCannon = TaskSelection.of(DEVIANT).withCannon(true);
		List<LedgerRecord> spectres = Arrays.asList(record(SPECTRES, SPECTRE_TASK, null, true, 10, HOUR),
			record(SPECTRES, SPECTRE_TASK, DEVIANT, false, 10, HOUR));
		assertEquals(TaskSelection.of(DEVIANT),
			TaskStatistics.effectiveSelection(spectres, SPECTRES, SPECTRE_TASK, deviantCannon));
		assertEquals(TaskSelection.ANY.withCannon(true), TaskStatistics.effectiveSelection(spectres, SPECTRES,
			SPECTRE_TASK, TaskSelection.ANY.withCannon(true)));
	}

	@Test
	public void theOverlayNamesTheTaskAsTheTaskBoxDoes()
	{
		SessionTracker.LiveTask task = new SessionTracker.LiveTask(SessionTracker.Status.RUNNING, "session", DEVILS,
			DUST_DEVILS, 3, 60_000L, 20);
		assertEquals(DEVILS, new OverlayRows.Data(task, null, null, null).getTaskName());
		assertEquals(DEVILS, OverlayRows.taskName(DEVILS, DUST_DEVILS, TaskSelection.ANY, null));
		assertEquals(DEVILS + " (cannon)",
			OverlayRows.taskName(DEVILS, DUST_DEVILS, TaskSelection.ANY.withCannon(true), null));
		assertEquals(DEVIANT + " (cannon)", OverlayRows.taskName(SPECTRE_TASK, SPECTRES,
			TaskSelection.of(DEVIANT).withCannon(true), null));
	}

	// ---- Helpers ----

	/** A running task of 50 just started, without task kills. */
	private SessionTracker playing(String monster, int creatureId)
	{
		SessionTracker tracker = new SessionTracker(() -> now);
		tracker.observe(monster, creatureId, 50, 50, false);
		assertTrue(tracker.startNow(ACCOUNT));
		return tracker;
	}

	private static ItemTally tally(int id, long quantity)
	{
		ItemTally tally = new ItemTally();
		tally.add(id, quantity);
		return tally;
	}

	private static Map<Integer, Long> supplies(int id, long quantity)
	{
		Map<Integer, Long> supplies = new HashMap<>();
		supplies.put(id, quantity);
		return supplies;
	}

	private static TaskStatistics devilStats(List<LedgerRecord> records, TaskSelection selection)
	{
		return TaskStatistics.forTask(records, DUST_DEVILS, DEVILS, selection, null, null);
	}

	private static TaskStatistics spectreStats(List<LedgerRecord> records, TaskSelection selection)
	{
		return TaskStatistics.forTask(records, SPECTRES, SPECTRE_TASK, selection, null, null);
	}

	/** A completed task; a cannon task fired 50 cannonballs. */
	private static LedgerRecord record(int creatureId, String monster, String variant, boolean cannon, int kills,
		long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(java.util.UUID.randomUUID().toString());
		record.setCreatureId(creatureId);
		record.setMonster(monster);
		record.setVariant(variant);
		record.setSupplies(cannon ? supplies(SupplyTracker.CANNONBALL, 50L) : null);
		record.setKills(kills);
		record.setInitialAmount(kills);
		record.setOriginalAmount(kills);
		record.setActiveMillis(activeMillis);
		record.setEndedAt(500_000L);
		record.setCompleted(true);
		return record;
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Catacombs variant tasks in the session, the saved record and every per-monster grouping: the per-task
 * statistics and the history list and its Monster filter.
 * Records saved in older versions have no variant and stay standard.
 */
public class CatacombsVariantGroupingTest
{
	private static final long ACCOUNT = 555L;
	private static final int SPECTRES = 7;
	private static final String TASK = "Aberrant spectres";
	private static final String DEVIANT = "Deviant spectres";
	private static final long HOUR = 60 * 60_000L;
	private static final long MINUTE = 60_000L;

	private long now = 1_000_000L;

	// ---- Session and saved record ----

	@Test
	public void killsWhileRunningDecideTheSavedRecordsVariant()
	{
		// 10 task kills: 6 Deviant spectres, 4 Aberrant spectres, and Ankous on the way that don't count.
		SessionTracker tracker = runningSpectreTask();
		for (int i = 0; i < 6; i++)
		{
			assertTrue(tracker.addNpcKill("Deviant spectre"));
		}
		for (int i = 0; i < 4; i++)
		{
			assertTrue(tracker.addNpcKill("Aberrant spectre"));
		}
		for (int i = 0; i < 8; i++)
		{
			assertTrue(tracker.addNpcKill("Ankou"));
		}
		assertFalse(tracker.addNpcKill(null));
		assertEquals(DEVIANT, tracker.getCurrentTaskSelection().getVariant());
		assertEquals(TaskSelection.of(DEVIANT), tracker.getCurrentTaskSelection());

		// Paused: not tallied, but the decision stands.
		assertTrue(tracker.pause());
		assertFalse(tracker.addNpcKill("Aberrant spectre"));
		assertFalse(tracker.addNpcKill("Aberrant spectre"));
		assertEquals(DEVIANT, tracker.getCurrentTaskSelection().getVariant());

		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(DEVIANT, record.getVariant());
		assertEquals(TASK, record.getMonster());
		assertEquals(DEVIANT, record.groupName());
		assertEquals(DEVIANT, LedgerHistory.monster(record));
		assertNull("no session any more", tracker.getCurrentTaskSelection().getVariant());
		assertSame(TaskSelection.ANY, tracker.getCurrentTaskSelection());
	}

	@Test
	public void theLiveSelectionWaitsForTheFirstTaskKillAndATieIsStandard()
	{
		SessionTracker tracker = playingSpectreTask();
		assertNull(tracker.getCurrentTaskSelection().getVariant());
		assertSame("no task kills yet: both versions pooled", TaskSelection.ANY, tracker.getCurrentTaskSelection());
		assertNull(LedgerRecord.fromSummary(tracker.activeSummary(), true).getVariant());

		// An unrelated kill first (for example an Ankou on the way) changes nothing.
		tracker.addNpcKill("Ankou");
		assertSame(TaskSelection.ANY, tracker.getCurrentTaskSelection());
		// A variant kill counts once the task counter has counted it.
		tracker.addNpcKill("Deviant spectre");
		assertSame(TaskSelection.ANY, tracker.getCurrentTaskSelection());
		killTask(tracker);
		assertEquals(DEVIANT, tracker.getCurrentTaskSelection().getVariant());
		assertEquals(TaskSelection.of(DEVIANT), tracker.getCurrentTaskSelection());
		assertEquals(DEVIANT, LedgerRecord.fromSummary(tracker.activeSummary(), true).getVariant());

		tracker.addNpcKill("Aberrant spectre");
		killTask(tracker);
		assertNull("a tie is standard", tracker.getCurrentTaskSelection().getVariant());
		assertSame(TaskSelection.STANDARD, tracker.getCurrentTaskSelection());
		assertNull(LedgerRecord.fromSummary(tracker.stopAndReset(), true).getVariant());
	}

	@Test
	public void deathSpawnsAndOtherBarragedNpcsDontMakeItStandard()
	{
		// A Greater nechryael task: each Greater Nechryael kill also kills its death spawns, which count for nothing.
		SessionTracker tracker = new SessionTracker(() -> now);
		tracker.observe("Nechryael", 52, 20, 20, false);
		assertTrue(tracker.startNow(ACCOUNT));
		for (int i = 1; i <= 5; i++)
		{
			tracker.addNpcKill("Greater Nechryael");
			tracker.addNpcKill("Death spawn");
			tracker.addNpcKill("Death spawn");
			tracker.addNpcKill("Death spawn");
			now += MINUTE;
			tracker.observe("Nechryael", 52, 20 - i, 20, false);
			assertEquals("Greater nechryael", tracker.getCurrentTaskSelection().getVariant());
		}
		assertEquals("Greater nechryael", LedgerRecord.fromSummary(tracker.stopAndReset(), true).getVariant());
	}

	@Test
	public void theTallySurvivesTheActiveSessionFile()
	{
		Gson gson = new Gson();
		SessionTracker tracker = runningSpectreTask();
		for (int i = 0; i < 6; i++)
		{
			tracker.addNpcKill("Deviant spectre");
		}
		tracker.loggedOut();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), null, now);
		String json = gson.toJson(snapshot);
		String tally = ",\"npcKills\":[{\"name\":\"Deviant spectre\",\"kills\":6}]";
		assertTrue(json, json.contains(tally));

		// Restored, the same 6 variant kills of 10 task kills decide it, live and on save.
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe(TASK, SPECTRES, 40, 50, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED,
			restored.restore(gson.fromJson(json, SessionSnapshot.class), null));
		assertEquals(10, restored.getKills());
		assertEquals(DEVIANT, restored.getCurrentTaskSelection().getVariant());
		assertEquals(TaskSelection.of(DEVIANT), restored.getCurrentTaskSelection());
		assertEquals(DEVIANT, LedgerRecord.fromSummary(restored.activeSummary(), true).getVariant());
		// A snapshot that can't be restored becomes a partial record with its variant.
		SessionSnapshot unrestorable = gson.fromJson(json, SessionSnapshot.class);
		assertEquals(DEVIANT, LedgerRecord.fromSummary(unrestorable.toSummary(SlayerSpots.NONE), true).getVariant());

		// Fewer variant kills than standard ones in the restored tally: standard, live and on save. (Task kills the tally
		// missed count for neither, so 5 variant kills alone would still be the variant.)
		SessionTracker half = new SessionTracker(() -> now);
		half.observe(TASK, SPECTRES, 40, 50, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, half.restore(gson.fromJson(json.replace("\"kills\":6}",
			"\"kills\":4},{\"name\":\"Aberrant spectre\",\"kills\":6}"), SessionSnapshot.class), null));
		assertNull(half.getCurrentTaskSelection().getVariant());
		assertSame(TaskSelection.STANDARD, half.getCurrentTaskSelection());
		assertNull(LedgerRecord.fromSummary(half.activeSummary(), true).getVariant());

		// A file from an older version has no tally and restores without one.
		SessionSnapshot old = gson.fromJson(json.replace(tally, ""), SessionSnapshot.class);
		assertNull(old.getNpcKills());
		SessionTracker fromOld = new SessionTracker(() -> now);
		fromOld.observe(TASK, SPECTRES, 40, 50, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, fromOld.restore(old, null));
		assertTrue(fromOld.getNpcKills().isEmpty());
		assertNull(fromOld.getCurrentTaskSelection().getVariant());
	}

	@Test
	public void recordsWithoutTheFieldLoadAsStandard()
	{
		Gson gson = new Gson();
		LedgerRecord old = gson.fromJson("{\"schemaVersion\":2,\"id\":\"a\",\"monster\":\"Aberrant spectres\","
			+ "\"creatureId\":7,\"kills\":10,\"activeMillis\":60000,\"completed\":true}", LedgerRecord.class);
		assertNull(old.getVariant());
		assertEquals(TASK, old.groupName());
		assertTrue(TaskSelection.STANDARD.matches(old));
		// Written back without the field, and a variant record with it.
		assertFalse(gson.toJson(old).contains("variant"));
		old.setVariant(DEVIANT);
		assertTrue(gson.toJson(old).contains("\"variant\":\"Deviant spectres\""));
	}

	// ---- Grouping ----

	@Test
	public void statisticsCountTheSelectedVersion()
	{
		List<LedgerRecord> records = Arrays.asList(record(null, 10, 10 * MINUTE), record(null, 10, 10 * MINUTE),
			record(DEVIANT, 10, 20 * MINUTE));
		assertEquals(3, stats(records, TaskSelection.ANY).getSampleCount());
		assertEquals(2, stats(records, TaskSelection.STANDARD).getSampleCount());
		TaskStatistics deviant = stats(records, TaskSelection.of(DEVIANT));
		assertEquals(1, deviant.getSampleCount());
		assertEquals(Long.valueOf(2 * MINUTE), deviant.getMillisPerKill());
		assertEquals("no selection pools them", 3, stats(records, null).getSampleCount());
	}

	@Test
	public void theHistoryFilterListsTheVariantSeparately()
	{
		List<LedgerRecord> records = Arrays.asList(record(null, 10, HOUR), record(DEVIANT, 10, HOUR));
		assertEquals(Arrays.asList(LedgerHistory.ALL, TASK, DEVIANT), LedgerHistory.filterOptions(records));
		assertEquals(1, new HistoryFilter(DEVIANT, null, null).apply(records, SlayerSpots.NONE, r -> null).size());
		assertEquals(1, new HistoryFilter(TASK, null, null).apply(records, SlayerSpots.NONE, r -> null).size());
		assertTrue(LedgerHistory.historyRowTooltip(records.get(1), HistoryPricing.value(records.get(1),
			LootPriceMode.GE, Collections.emptyMap()), null, LedgerHistory.NO_VALUE)
			.contains("Catacombs variant of Aberrant spectres"));
		assertFalse(LedgerHistory.historyRowTooltip(records.get(0), HistoryPricing.value(records.get(0),
			LootPriceMode.GE, Collections.emptyMap()), null, LedgerHistory.NO_VALUE).contains("Catacombs variant"));
	}

	// ---- Helpers ----

	/** A running spectres task of 50 with 10 task kills so far. */
	private SessionTracker runningSpectreTask()
	{
		SessionTracker tracker = playingSpectreTask();
		now += 60_000;
		tracker.observe(TASK, SPECTRES, 40, 50, false);
		return tracker;
	}

	/** A spectres task of 50 just started, without task kills. */
	private SessionTracker playingSpectreTask()
	{
		SessionTracker tracker = new SessionTracker(() -> now);
		tracker.observe(TASK, SPECTRES, 50, 50, false);
		assertTrue(tracker.startNow(ACCOUNT));
		return tracker;
	}

	/** The task counter counts one more kill of the running spectres task. */
	private void killTask(SessionTracker tracker)
	{
		now += MINUTE;
		tracker.observe(TASK, SPECTRES, tracker.getCurrentRemaining() - 1, 50, false);
	}

	private static TaskStatistics stats(List<LedgerRecord> records, TaskSelection variant)
	{
		return TaskStatistics.forTask(records, SPECTRES, TASK, variant, null, null);
	}

	private static LedgerRecord record(String variant, int kills, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(java.util.UUID.randomUUID().toString());
		record.setCreatureId(SPECTRES);
		record.setMonster(TASK);
		record.setVariant(variant);
		record.setKills(kills);
		record.setInitialAmount(kills);
		record.setOriginalAmount(kills);
		record.setActiveMillis(activeMillis);
		record.setEndedAt(1_700_000_000_000L + activeMillis);
		record.setCompleted(true);
		return record;
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.NpcID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The Catacombs variant table, the kills per NPC name and the most-kills rule: {@link CatacombsVariants},
 * {@link NpcKillTally}, {@link DamagedNpcs} and {@link TaskSelection}.
 */
public class CatacombsVariantsTest
{
	@Test
	public void theTableHasTheCatacombsNpcIdsAndNames()
	{
		// The ids and names of the RuneLite 1.13.4 gameval NpcID constants (their javadoc gives the NPC's name).
		assertVariant("Aberrant spectres", NpcID.KOUREND_SPECTRE, 7279, "Deviant spectre", "Deviant spectres");
		assertVariant("Nechryael", NpcID.KOUREND_NECHRYAEL, 7278, "Greater Nechryael", "Greater nechryael");
		assertVariant("Bloodveld", NpcID.KOUREND_BLOODVELD, 7276, "Mutated Bloodveld", "Mutated bloodveld");
		assertVariant("Jellies", NpcID.KOUREND_JELLY, 7277, "Warped Jelly", "Warped jellies");
		assertVariant("Banshees", NpcID.KOUREND_BANSHEE, 7272, "Twisted Banshee", "Twisted banshees");
		assertVariant("Black dragons", NpcID.KOUREND_BLACK_DRAGON, 7275, "Brutal black dragon", "Brutal black dragons");
		assertVariant("Blue dragons", NpcID.KOUREND_BLUE_DRAGON, 7273, "Brutal blue dragon", "Brutal blue dragons");
		assertVariant("Red dragons", NpcID.KOUREND_RED_DRAGON, 7274, "Brutal red dragon", "Brutal red dragons");
		assertEquals(8, CatacombsVariants.all().size());
	}

	@Test
	public void tasksMatchByTheOneNameKeyAndOthersHaveNoVariant()
	{
		assertEquals("Deviant spectres", CatacombsVariants.forTask("  ABERRANT spectres ").getName());
		assertNull(CatacombsVariants.forTask("Abyssal demons"));
		assertNull(CatacombsVariants.forTask("Green dragons"));
		assertNull(CatacombsVariants.forTask(null));
		assertNull(CatacombsVariants.forTask(" "));
	}

	@Test
	public void onlyTheCatacombsNpcCountsAsTheVariant()
	{
		assertEquals("Deviant spectre", CatacombsVariants.tallyName(NpcID.KOUREND_SPECTRE, " Deviant spectre "));
		assertEquals("Aberrant spectre", CatacombsVariants.tallyName(NpcID.SLAYER_ABBERANT_SPECTRE_1, "Aberrant spectre"));
		// The same names outside the Catacombs are not the variant, so they are not tallied.
		assertNull(CatacombsVariants.tallyName(NpcID.WILD_CAVE_NECHRYAEL, "Greater Nechryael"));
		assertNull(CatacombsVariants.tallyName(NpcID.MYQ5_BLOODVELD, "Mutated Bloodveld"));
		assertNull(CatacombsVariants.tallyName(NpcID.DS2_BRUT_BLACK_DRAGON, "Brutal black dragon"));
		assertNull(CatacombsVariants.tallyName(NpcID.BRUTAL_BLUE_DRAGON_TAPOYAUIK, "Brutal blue dragon"));
		assertNull(CatacombsVariants.tallyName(1, null));
		assertNull(CatacombsVariants.tallyName(1, "  "));
	}

	@Test
	public void theVariantMustHaveMoreTaskKillsThanTheStandardMonster()
	{
		// All standard.
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Aberrant spectre", 50), 50));
		// All variant.
		assertEquals("Deviant spectres", CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 50),
			50));
		// Mixed: more than half of the task kills variant, or not.
		assertEquals("Deviant spectres", CatacombsVariants.decide("Aberrant spectres",
			tally("Deviant spectre", 31, "Aberrant spectre", 30), 61));
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 30, "Aberrant spectre", 31),
			61));
		// A tie is the standard monster.
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 20, "Aberrant spectre", 20),
			40));
		// No tallied kills, or no task kills.
		assertNull(CatacombsVariants.decide("Aberrant spectres", Collections.emptyList(), 10));
		assertNull(CatacombsVariants.decide("Aberrant spectres", null, 10));
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 5), 0));
		// Names match ignoring case and spaces; a task without a variant never has one.
		assertEquals("Greater nechryael", CatacombsVariants.decide("nechryael", tally(" greater NECHRYAEL", 3), 3));
		assertNull(CatacombsVariants.decide("Abyssal demons", tally("Deviant spectre", 50), 50));
		assertNull(CatacombsVariants.decide(null, tally("Deviant spectre", 50), 50));
	}

	@Test
	public void unrelatedKillsDontCount()
	{
		// An Ankou on the way and other barraged NPCs are left out: 10 of 14 task kills were the variant.
		assertEquals("Deviant spectres", CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 10,
			"Ankou", 6, "Aberrant spectre", 4, "Ghost", 12), 14));
		// Greater Nechryael death spawns (and other names) don't count against the variant.
		assertEquals("Greater nechryael", CatacombsVariants.decide("Nechryael", tally("Greater Nechryael", 20,
			"Death spawn", 45), 20));
		// Nor for it: the variant against the task kills only.
		assertNull(CatacombsVariants.decide("Aberrant spectres", tally("Deviant spectre", 3, "Ankou", 40), 6));
		assertSame(TaskSelection.STANDARD,
			CatacombsVariants.selection("Aberrant spectres", tally("Deviant spectre", 3, "Ankou", 40), 6));
	}

	@Test
	public void theLiveSelectionPoolsUntilTheFirstTaskKill()
	{
		assertSame(TaskSelection.ANY, CatacombsVariants.selection("Aberrant spectres", Collections.emptyList(), 0));
		assertSame(TaskSelection.ANY, CatacombsVariants.selection("Abyssal demons", tally("Abyssal demon", 5), 5));
		// An unrelated kill before the first task kill changes nothing.
		assertSame(TaskSelection.ANY, CatacombsVariants.selection("Aberrant spectres", tally("Ankou", 1), 0));
		// A variant kill tallied before the task counter moved: still pooled.
		assertSame(TaskSelection.ANY, CatacombsVariants.selection("Aberrant spectres", tally("Deviant spectre", 1), 0));
		assertSame(TaskSelection.STANDARD, CatacombsVariants.selection("Aberrant spectres", tally("Aberrant spectre", 1),
			1));
		// One unrelated kill doesn't make it standard.
		assertEquals(TaskSelection.of("Deviant spectres"),
			CatacombsVariants.selection("Aberrant spectres", tally("Ankou", 1, "Deviant spectre", 1), 1));
		// A tie is standard.
		assertSame(TaskSelection.STANDARD,
			CatacombsVariants.selection("Aberrant spectres", tally("Deviant spectre", 1, "Aberrant spectre", 1), 2));
	}

	@Test
	public void taskVariantsSelectRecordsByTheirVersion()
	{
		LedgerRecord standard = new LedgerRecord();
		standard.setMonster("Aberrant spectres");
		LedgerRecord deviant = new LedgerRecord();
		deviant.setMonster("Aberrant spectres");
		deviant.setVariant("Deviant spectres");

		assertTrue(TaskSelection.ANY.matches(standard));
		assertTrue(TaskSelection.ANY.matches(deviant));
		assertTrue(TaskSelection.STANDARD.matches(standard));
		assertFalse(TaskSelection.STANDARD.matches(deviant));
		assertFalse(TaskSelection.of("deviant SPECTRES ").matches(standard));
		assertTrue(TaskSelection.of("deviant SPECTRES ").matches(deviant));
		assertSame(TaskSelection.STANDARD, TaskSelection.of(" "));
		assertNotEquals(TaskSelection.ANY, TaskSelection.STANDARD);
		assertEquals(TaskSelection.of("Deviant spectres").hashCode(), TaskSelection.of("deviant spectres").hashCode());

		// The group name is the variant's for a variant record, else the monster.
		assertEquals("Aberrant spectres", standard.groupName());
		assertEquals("Deviant spectres", deviant.groupName());
		deviant.setVariant(" ");
		assertEquals("Aberrant spectres", deviant.groupName());
	}

	@Test
	public void theTallyMergesNamesAndIsBounded()
	{
		List<NpcKills> tally = NpcKillTally.add(null, "Deviant spectre");
		tally = NpcKillTally.add(tally, " deviant SPECTRE ");
		tally = NpcKillTally.add(tally, "Ankou");
		tally = NpcKillTally.add(tally, null);
		tally = NpcKillTally.add(tally, " ");
		assertEquals(Arrays.asList(new NpcKills("Deviant spectre", 2), new NpcKills("Ankou", 1)), tally);
		assertEquals(2, NpcKillTally.killsOf(tally, "DEVIANT spectre"));
		assertEquals(0, NpcKillTally.killsOf(tally, "Aberrant spectre"));
		assertEquals(3, NpcKillTally.total(tally));

		List<NpcKills> many = new ArrayList<>();
		for (int i = 0; i < NpcKillTally.MAX_NAMES + 5; i++)
		{
			many = NpcKillTally.add(many, "Npc " + i);
		}
		assertEquals(NpcKillTally.MAX_NAMES, many.size());
		// A name already tallied still counts once the tally is full.
		many = NpcKillTally.add(many, "Npc 0");
		assertEquals(2, NpcKillTally.killsOf(many, "Npc 0"));
		// A Catacombs variant's name is always tallied, so the full tally can still decide the variant.
		many = NpcKillTally.add(many, "Deviant spectre");
		many = NpcKillTally.add(many, "deviant spectre");
		assertEquals(NpcKillTally.MAX_NAMES + 1, many.size());
		assertEquals(2, NpcKillTally.killsOf(many, "Deviant spectre"));
		assertEquals("Deviant spectres", CatacombsVariants.decide("Aberrant spectres", many, 3));
		// Other new names still aren't, and a file's full tally keeps the variant's name.
		many = NpcKillTally.add(many, "Npc 99");
		assertEquals(0, NpcKillTally.killsOf(many, "Npc 99"));
		assertEquals(2, NpcKillTally.killsOf(NpcKillTally.sanitize(many), "Deviant spectre"));
		assertTrue(CatacombsVariants.isVariantNpcName(" GREATER nechryael"));
		assertFalse(CatacombsVariants.isVariantNpcName("Aberrant spectre"));
		assertFalse(CatacombsVariants.isVariantNpcName(null));

		// A file's tally is cleaned: no names, no kills and repeats.
		List<NpcKills> read = Arrays.asList(null, new NpcKills(null, 3), new NpcKills("Ankou", 0),
			new NpcKills("Ankou", 2), new NpcKills("ankou", 1));
		assertEquals(Collections.singletonList(new NpcKills("Ankou", 3)), NpcKillTally.sanitize(read));
		assertTrue(NpcKillTally.sanitize(null).isEmpty());
	}

	@Test
	public void damagedNpcsAreTakenOnceAndBounded()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 5, 0L, AWAY, NO_TICK);
		assertTrue(died(npcs, 0, 5));
		assertFalse("taken once", died(npcs, 0, 5));
		assertFalse("never damaged", died(npcs, 0, 6));

		npcs.damaged(0, 7, 0L, AWAY, NO_TICK);
		npcs.forget(0, 7);
		assertFalse("despawned", died(npcs, 0, 7));

		for (int i = 0; i < DamagedNpcs.MAX_NPCS + 10; i++)
		{
			npcs.damaged(0, i, 0L, AWAY, NO_TICK);
		}
		assertEquals(DamagedNpcs.MAX_NPCS, npcs.size());
		// The ones damaged longest ago went first.
		assertFalse(died(npcs, 0, 0));
		assertTrue(died(npcs, 0, DamagedNpcs.MAX_NPCS + 9));
		npcs.clear();
		assertEquals(0, npcs.size());
	}

	@Test
	public void damagedNpcsAreKeptPerWorldView()
	{
		// The same index in another world view (a boat's) is another NPC.
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 5, 0L, AWAY, NO_TICK);
		assertFalse(died(npcs, 3, 5));
		npcs.forget(3, 5);
		assertTrue(died(npcs, 0, 5));

		npcs.damaged(-1, 5, 0L, AWAY, NO_TICK);
		npcs.damaged(3, 5, 0L, AWAY, NO_TICK);
		assertEquals(2, npcs.size());
		assertTrue(died(npcs, 3, 5));
		assertFalse(died(npcs, 0, 5));
		assertTrue(died(npcs, -1, 5));
		// Indexes and ids with the high bit set don't collide.
		npcs.damaged(0, -1, 0L, AWAY, NO_TICK);
		assertFalse(died(npcs, -1, -1));
		assertTrue(died(npcs, 0, -1));
	}

	/** The Away limit the engagements in these tests use. */
	private static final long AWAY = 10 * 60_000L;
	/** The game tick of a hit: never read, since these tests never put hits down to attacks. */
	private static final int NO_TICK = 0;

	/** The NPC died, with no name, on tick 0 (pairing is {@link DamagedNpcsTest}'s subject). */
	private static boolean died(DamagedNpcs npcs, int worldViewId, int index)
	{
		return npcs.died(worldViewId, index, null, null, false, 0, 0L, AWAY);
	}

	private static void assertVariant(String task, int constant, int id, String npcName, String name)
	{
		assertEquals(id, constant);
		CatacombsVariants.Variant variant = CatacombsVariants.forTask(task);
		assertEquals(task, variant.getTask());
		assertEquals(id, variant.getNpcId());
		assertEquals(npcName, variant.getNpcName());
		assertEquals(name, variant.getName());
	}

	/** A tally of name and kills pairs, in order. */
	static List<NpcKills> tally(Object... nameAndKills)
	{
		List<NpcKills> tally = new ArrayList<>();
		for (int i = 0; i < nameAndKills.length; i += 2)
		{
			tally.add(new NpcKills((String) nameAndKills[i], (Integer) nameAndKills[i + 1]));
		}
		return tally;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Charging, loading, unloading and uncharging the blowpipe, a trident or a powered staff is left out of the supplies
 * diff.
 */
public class ChargeExclusionsTest
{
	private static final int SHARK = 385;
	private static final int BLOWPIPE = ItemID.TOXIC_BLOWPIPE_LOADED;
	private static final int TRIDENT = ItemID.TOXIC_TOTS_CHARGED;

	private final ChargeExclusions exclusions = new ChargeExclusions();

	@Test
	public void nothingIsExcludedByDefault()
	{
		assertFalse(exclusions.excludedItems(0).contains(ItemID.RUNE_DART));
		assertTrue(exclusions.excludedItems(0).isEmpty());
	}

	@Test
	public void usingDartsOnTheBlowpipeExcludesMaterialsOnly()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 100);
		assertTrue(exclusions.excludedItems(100).contains(ItemID.RUNE_DART));
		assertTrue(exclusions.excludedItems(100).contains(ItemID.SNAKEBOSS_SCALE));
		assertTrue(exclusions.excludedItems(101).contains(ItemID.DEATHRUNE));
		assertTrue(exclusions.excludedItems(101).contains(ItemID.CHAOSRUNE));
		assertTrue(exclusions.excludedItems(101).contains(ItemID.FIRERUNE));
		assertTrue(exclusions.excludedItems(101).contains(ItemID.COINS));
		assertFalse(exclusions.excludedItems(100).contains(SHARK));
		assertFalse(exclusions.excludedItems(100).contains(BLOWPIPE));
		assertFalse(exclusions.excludedItems(100).contains(ItemID.NATURERUNE));
		assertEquals(ChargeExclusions.MATERIALS, exclusions.excludedItems(100));
	}

	@Test
	public void eitherOrderOfUseCounts()
	{
		exclusions.menuOptionClicked("Use", new int[]{TRIDENT, ItemID.FIRERUNE}, 10);
		assertTrue(exclusions.excludedItems(10).contains(ItemID.FIRERUNE));
	}

	@Test
	public void unloadAndUnchargeOpenTheWindow()
	{
		exclusions.menuOptionClicked("Unload", new int[]{BLOWPIPE}, 10);
		assertTrue(exclusions.excludedItems(11).contains(ItemID.RUNE_DART));
		exclusions.reset();
		exclusions.menuOptionClicked("<col=ff9040>Uncharge</col>", new int[]{ItemID.TOTS_CHARGED_ORN}, 20);
		assertTrue(exclusions.excludedItems(21).contains(ItemID.COINS));
		exclusions.reset();
		exclusions.menuOptionClicked("UNCHARGE", new int[]{ItemID.TOXIC_BLOWPIPE_ORNAMENT}, 30);
		assertTrue(exclusions.excludedItems(30).contains(ItemID.SNAKEBOSS_SCALE));
	}

	@Test
	public void otherOptionsAndItemsDontOpenIt()
	{
		exclusions.menuOptionClicked("Check", new int[]{BLOWPIPE}, 10);
		exclusions.menuOptionClicked("Wield", new int[]{TRIDENT}, 10);
		exclusions.menuOptionClicked("Drop", new int[]{BLOWPIPE}, 10);
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, SHARK}, 10);
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART}, 10);
		exclusions.menuOptionClicked(null, new int[]{BLOWPIPE}, 10);
		exclusions.menuOptionClicked("Use", null, 10);
		assertFalse(exclusions.excludedItems(10).contains(ItemID.RUNE_DART));
		assertFalse(exclusions.excludedItems(11).contains(ItemID.RUNE_DART));
	}

	@Test
	public void timesOut()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.CHAOSRUNE, TRIDENT}, 100);
		assertFalse("before", exclusions.excludedItems(99).contains(ItemID.CHAOSRUNE));
		assertTrue(exclusions.excludedItems(100 + ChargeExclusions.TIMEOUT_TICKS).contains(ItemID.CHAOSRUNE));
		assertFalse(exclusions.excludedItems(101 + ChargeExclusions.TIMEOUT_TICKS).contains(ItemID.CHAOSRUNE));
	}

	@Test
	public void confirmationClosesAfterTheGrace()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.DEATHRUNE, TRIDENT}, 100);
		exclusions.messageSeen("You add 123 charges to the weapon.<br>New total: 246", 110);
		assertTrue(exclusions.excludedItems(110).contains(ItemID.DEATHRUNE));
		assertTrue(exclusions.excludedItems(112).contains(ItemID.DEATHRUNE));
		assertFalse(exclusions.excludedItems(113).contains(ItemID.DEATHRUNE));
		assertTrue(exclusions.excludedItems(113).isEmpty());
	}

	@Test
	public void otherMessagesDontClose()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 100);
		exclusions.messageSeen("You eat the shark.", 101);
		exclusions.messageSeen(null, 101);
		assertTrue(exclusions.excludedItems(120).contains(ItemID.RUNE_DART));
	}

	@Test
	public void confirmationWithoutAWindowDoesNothing()
	{
		exclusions.messageSeen("You uncharge your weapon.", 5);
		assertFalse(exclusions.excludedItems(5).contains(ItemID.COINS));
		exclusions.menuOptionClicked("Uncharge", new int[]{TRIDENT}, 10);
		// The earlier confirmation didn't shorten the new window.
		assertTrue(exclusions.excludedItems(20).contains(ItemID.COINS));
	}

	@Test
	public void aNewClickReopensTheWindow()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 100);
		exclusions.messageSeen("Darts: Rune dart x 50. Scales: 0 (0.0%).", 100);
		exclusions.menuOptionClicked("Use", new int[]{ItemID.SNAKEBOSS_SCALE, BLOWPIPE}, 140);
		assertTrue(exclusions.excludedItems(140 + ChargeExclusions.TIMEOUT_TICKS).contains(ItemID.SNAKEBOSS_SCALE));
	}

	@Test
	public void confirmations()
	{
		assertTrue(ChargeExclusions.isConfirmation(
			"Darts: <col=007f00>Rune dart x 1,000</col>. Scales: <col=007f00>16,383 (100.0%)</col>."));
		assertTrue(ChargeExclusions.isConfirmation("Darts: None. Scales: 99 (0.6%)."));
		assertTrue(ChargeExclusions.isConfirmation("The blowpipe can't hold any more darts."));
		assertTrue(ChargeExclusions.isConfirmation("The blowpipe can't hold any more scales."));
		assertTrue(ChargeExclusions.isConfirmation("The blowpipe has no darts in it."));
		assertTrue(ChargeExclusions.isConfirmation("@mes_hl_red@The blowpipe has no darts in it.</col>"));
		assertTrue(ChargeExclusions.isConfirmation("You add a charge to the weapon.<br>New total: 2016"));
		assertTrue(ChargeExclusions.isConfirmation("You add 1,200 charges to the weapon.<br>New total: 2,500"));
		assertTrue(ChargeExclusions.isConfirmation("Your weapon is already fully charged."));
		assertTrue(ChargeExclusions.isConfirmation("Your Sanguinesti staff is already fully charged."));
		assertTrue(ChargeExclusions.isConfirmation("Your Holy sanguinesti staff is already fully charged."));
		assertTrue(ChargeExclusions.isConfirmation("You uncharge your weapon."));
		// The powered staves' dialogs, as geheur/weapon-charges recorded them.
		assertTrue(ChargeExclusions.isConfirmation("You apply 201 charges to your Tumeken's shadow."));
		assertTrue(ChargeExclusions.isConfirmation(
			"You apply an additional 301 charges to your<br>Tumeken's shadow. It now has 498 charges in total."));
		assertTrue(ChargeExclusions.isConfirmation("You apply 1 charges to your Holy sanguinesti staff."));
		assertTrue(ChargeExclusions.isConfirmation(
			"You uncharge your Sanguinesti staff, regaining 3 blood<br>runes in the process."));
		assertTrue(ChargeExclusions.isConfirmation(
			"You uncharge your Tumeken's shadow, regaining 198<br>soul runes and 495 chaos runes in the process."));
		assertFalse(ChargeExclusions.isConfirmation("Your blowpipe has run out of darts."));
		assertFalse(ChargeExclusions.isConfirmation("Tumeken's shadow has 200 charges remaining."));
		assertFalse(ChargeExclusions.isConfirmation(null));
	}

	@Test
	public void chargingAndUnchargingAPoweredStaffExcludesItsRunes()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.BLOODRUNE, ItemID.SANGUINESTI_STAFF_UNCHARGED}, 100);
		assertTrue(exclusions.excludedItems(100).contains(ItemID.BLOODRUNE));
		assertFalse(exclusions.excludedItems(100).contains(SHARK));
		exclusions.messageSeen("You apply 500 charges to your Sanguinesti staff.", 103);
		assertTrue(exclusions.excludedItems(105).contains(ItemID.BLOODRUNE));
		assertFalse(exclusions.excludedItems(106).contains(ItemID.BLOODRUNE));

		// The staves' own "Charge" option opens the charge prompt.
		exclusions.menuOptionClicked("Charge", new int[]{ItemID.TUMEKENS_SHADOW}, 200);
		assertTrue(exclusions.excludedItems(200).contains(ItemID.SOULRUNE));
		assertTrue(exclusions.excludedItems(201).contains(ItemID.AETHERRUNE));
		assertTrue(exclusions.excludedItems(201).contains(ItemID.CHAOSRUNE));
		exclusions.reset();
		exclusions.menuOptionClicked("Uncharge", new int[]{ItemID.SANGUINESTI_STAFF_OR}, 300);
		assertTrue(exclusions.excludedItems(301).contains(ItemID.BLOODRUNE));
		exclusions.reset();
		// "Charge" on anything else opens nothing.
		exclusions.menuOptionClicked("Charge", new int[]{ItemID.BLOODRUNE}, 400);
		assertFalse(exclusions.excludedItems(400).contains(ItemID.BLOODRUNE));
	}

	@Test
	public void resetForgetsTheWindow()
	{
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 100);
		exclusions.reset();
		assertFalse(exclusions.excludedItems(100).contains(ItemID.RUNE_DART));
	}

	@Test
	public void aWindowFromALaterTickExcludesNothing()
	{
		// a window opened before the tick count restarted must not cover the ticks after the restart.
		exclusions.menuOptionClicked("Use", new int[]{ItemID.RUNE_DART, BLOWPIPE}, 5_000);
		assertFalse(exclusions.excludedItems(10).contains(ItemID.RUNE_DART));
		assertTrue(exclusions.excludedItems(10).isEmpty());
		exclusions.messageSeen("The blowpipe has no darts in it.", 10);
		assertTrue("the window itself is unchanged", exclusions.excludedItems(5_000).contains(ItemID.RUNE_DART));
	}

	@Test
	public void everyWeaponVariantIsAWeapon()
	{
		for (int id : ChargedWeaponUsage.BLOWPIPES)
		{
			assertTrue(ChargeExclusions.WEAPONS.contains(id));
		}
		for (int id : ChargedWeaponUsage.SEAS_TRIDENTS)
		{
			assertTrue(ChargeExclusions.WEAPONS.contains(id));
		}
		for (int id : ChargedWeaponUsage.SWAMP_TRIDENTS)
		{
			assertTrue(ChargeExclusions.WEAPONS.contains(id));
		}
		for (int id : ChargedWeaponUsage.SANGUINESTI_STAVES)
		{
			assertTrue(ChargeExclusions.WEAPONS.contains(id));
		}
		for (int id : ChargedWeaponUsage.TUMEKENS_SHADOWS)
		{
			assertTrue(ChargeExclusions.WEAPONS.contains(id));
		}
		assertEquals(28, ChargeExclusions.WEAPONS.size());
		assertEquals(17, ChargeExclusions.MATERIALS.size());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Blowpipe darts and scales, and trident and powered staff casts, counted from attack animations.
 */
public class ChargedWeaponUsageTest
{
	private static final int BLOWPIPE = ItemID.TOXIC_BLOWPIPE_LOADED;
	private static final int SHOT = AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK;
	private static final int CAST = AnimationID.HUMAN_CASTWAVE_STAFF;
	private static final int SHADOW_CAST = AnimationID.TOA_SOT_CAST_B;
	private static final int DART = ItemID.ADAMANT_DART;
	private static final int SCALE = ItemID.SNAKEBOSS_SCALE;

	private final ChargedWeaponUsage usage = new ChargedWeaponUsage();
	private int tick;

	private static ChargedWeaponUsage.Tick.TickBuilder blowpipeShot()
	{
		return ChargedWeaponUsage.Tick.builder().weaponId(BLOWPIPE).animationId(SHOT).dartId(DART);
	}

	private static ChargedWeaponUsage.Tick.TickBuilder tridentCast(int weaponId)
	{
		return ChargedWeaponUsage.Tick.builder().weaponId(weaponId).animationId(CAST).castGraphic(true);
	}

	/** A Sanguinesti staff cast uses the trident's wave-staff animation; a shadow cast has its own. */
	private static ChargedWeaponUsage.Tick.TickBuilder shadowCast()
	{
		return ChargedWeaponUsage.Tick.builder().weaponId(ItemID.TUMEKENS_SHADOW).animationId(SHADOW_CAST)
			.castGraphic(true);
	}

	/** Feeds {@code shots} ticks built by {@code tick} and sums what was used. */
	private Map<Integer, Integer> run(ChargedWeaponUsage.Tick.TickBuilder builder, int shots)
	{
		final Map<Integer, Integer> total = new HashMap<>();
		for (int i = 0; i < shots; i++)
		{
			usage.update(builder.tick(++tick).build()).forEach((id, qty) -> total.merge(id, qty, Integer::sum));
		}
		return total;
	}

	private static int qty(Map<Integer, Integer> used, int itemId)
	{
		return used.getOrDefault(itemId, 0);
	}

	@Test
	public void noDeviceUsesOneDartPerShot()
	{
		final Map<Integer, Integer> used = run(blowpipeShot(), 3);
		assertEquals(3, qty(used, DART));
		assertEquals(2, qty(used, SCALE));
	}

	@Test
	public void scalesCarryOverInThirds()
	{
		assertEquals(0, qty(run(blowpipeShot(), 1), SCALE));
		assertEquals(1, qty(run(blowpipeShot(), 1), SCALE));
		assertEquals(1, qty(run(blowpipeShot(), 1), SCALE));
		assertEquals(0, qty(run(blowpipeShot(), 1), SCALE));
	}

	@Test
	public void hundredShotsWithEachDevice()
	{
		assertDarts(ItemID.ANMA_30_REWARD, false, 40);
		assertDarts(ItemID.ANMA_50_REWARD, false, 28);
		assertDarts(ItemID.SKILLCAPE_MAX_ANMA, false, 28);
		assertDarts(ItemID.AVAS_ASSEMBLER, false, 20);
		assertDarts(ItemID.AVAS_ASSEMBLER_MASORI, false, 20);
		assertDarts(ItemID.SKILLCAPE_MAX_ASSEMBLER_MASORI_TROUVER, false, 20);
		assertDarts(ItemID.SKILLCAPE_RANGING, false, 28);
		assertDarts(ItemID.SKILLCAPE_RANGING, true, 20);
		assertDarts(ItemID.SKILLCAPE_RANGING_TRIMMED, true, 20);
		assertDarts(ItemID.SKILLCAPE_MAX, false, 28);
		assertDarts(ItemID.SKILLCAPE_MAX, true, 20);
		assertDarts(ItemID.DIZANAS_QUIVER_CHARGED, false, 20);
		assertDarts(ItemID.SKILLCAPE_MAX_DIZANAS, false, 20);
		// The upgrade setting only affects ranging and max capes.
		assertDarts(ItemID.ANMA_50_REWARD, true, 28);
		assertDarts(ChargedWeaponUsage.NO_ITEM, true, 100);
		// A broken assembler saves nothing.
		assertDarts(ItemID.AVAS_ASSEMBLER_BROKEN, false, 100);
	}

	private void assertDarts(int capeId, boolean upgrade, int expectedDarts)
	{
		usage.reset();
		final Map<Integer, Integer> used = run(blowpipeShot().capeId(capeId).vorkathsHeadUpgrade(upgrade), 100);
		assertEquals("darts with " + capeId, expectedDarts, qty(used, DART));
		assertEquals("scales with " + capeId, 66, qty(used, SCALE));
	}

	@Test
	public void assemblerCarriesDartsOverInHundredths()
	{
		final ChargedWeaponUsage.Tick.TickBuilder shot = blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER);
		assertEquals(0, qty(run(shot, 4), DART));
		assertEquals(1, qty(run(shot, 1), DART));
		assertEquals(0, qty(run(shot, 4), DART));
		assertEquals(1, qty(run(shot, 1), DART));
	}

	@Test
	public void quiverSettingWhenPassed()
	{
		assertEquals(20, ChargedWeaponUsage.quiverLossHundredths(null));
		assertEquals(20, ChargedWeaponUsage.quiverLossHundredths(0));
		assertEquals(28, ChargedWeaponUsage.quiverLossHundredths(1));
		assertEquals(40, ChargedWeaponUsage.quiverLossHundredths(2));
		assertEquals(20, ChargedWeaponUsage.quiverLossHundredths(7));
		assertEquals(40, ChargedWeaponUsage.dartLossHundredths(ItemID.DIZANAS_QUIVER_INFINITE, 2, false));
		// The quiver setting doesn't apply to other capes.
		assertEquals(20, ChargedWeaponUsage.dartLossHundredths(ItemID.AVAS_ASSEMBLER, 2, false));
	}

	@Test
	public void unknownDartTypeCountsScalesOnlyAndAsksForACheck()
	{
		assertFalse(usage.isDartCheckNeeded());
		final Map<Integer, Integer> used = run(blowpipeShot().dartId(ChargedWeaponUsage.NO_ITEM), 3);
		assertEquals(1, used.size());
		assertEquals(2, qty(used, SCALE));
		assertTrue(usage.isDartCheckNeeded());

		// No dart fraction was carried while unknown: the first known shot uses one dart from scratch.
		final Map<Integer, Integer> known = run(blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER), 4);
		assertFalse(usage.isDartCheckNeeded());
		assertEquals(0, qty(known, DART));
	}

	@Test
	public void knownDartTypeOnAnyTickClearsTheHint()
	{
		run(blowpipeShot().dartId(ChargedWeaponUsage.NO_ITEM), 1);
		assertTrue(usage.isDartCheckNeeded());
		run(ChargedWeaponUsage.Tick.builder().dartId(DART), 1);
		assertFalse(usage.isDartCheckNeeded());
	}

	@Test
	public void changingDartTypeDropsTheCarryOver()
	{
		final ChargedWeaponUsage.Tick.TickBuilder shot = blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER);
		run(shot, 4);
		final Map<Integer, Integer> used = run(shot.dartId(ItemID.RUNE_DART), 1);
		assertEquals(0, qty(used, ItemID.RUNE_DART));
		assertEquals(0, qty(used, DART));
		assertEquals(1, qty(run(shot, 4), ItemID.RUNE_DART));
	}

	@Test
	public void ornamentBlowpipeAndAnimationCount()
	{
		final Map<Integer, Integer> used = run(blowpipeShot().weaponId(ItemID.TOXIC_BLOWPIPE_LOADED_ORNAMENT)
			.animationId(AnimationID.SNAKEBOSS_BLOWPIPE_ATTACK_ORNAMENT), 1);
		assertEquals(1, qty(used, DART));
	}

	@Test
	public void nothingWithoutTheBlowpipeWorn()
	{
		assertTrue(run(blowpipeShot().weaponId(ChargedWeaponUsage.NO_ITEM), 10).isEmpty());
		assertTrue(run(blowpipeShot().weaponId(ItemID.TOXIC_BLOWPIPE), 10).isEmpty());
	}

	@Test
	public void nothingForOtherAnimations()
	{
		assertTrue(run(blowpipeShot().animationId(-1), 10).isEmpty());
		assertTrue(run(blowpipeShot().animationId(CAST), 10).isEmpty());
	}

	@Test
	public void nothingAfterFrameZero()
	{
		assertTrue(run(blowpipeShot().animationFrame(1), 10).isEmpty());
		assertTrue(run(tridentCast(ItemID.TOTS_CHARGED).animationFrame(3), 10).isEmpty());
	}

	@Test
	public void atMostOneAttackPerTick()
	{
		final ChargedWeaponUsage.Tick shot = blowpipeShot().tick(5).build();
		assertEquals(1, qty(usage.update(shot), DART));
		assertTrue(usage.update(shot).isEmpty());
		assertTrue(usage.update(blowpipeShot().tick(4).build()).isEmpty());
		assertEquals(1, qty(usage.update(blowpipeShot().tick(6).build()), DART));
	}

	@Test
	public void tridentOfTheSeasCast()
	{
		for (int trident : new int[]{ItemID.TOTS, ItemID.TOTS_CHARGED, ItemID.TOTS_I_CHARGED, ItemID.TOTS_ORN,
			ItemID.TOTS_CHARGED_ORN, ItemID.TOTS_I_CHARGED_ORN})
		{
			final Map<Integer, Integer> used = run(tridentCast(trident), 1);
			assertEquals("" + trident, 4, used.size());
			assertEquals(1, qty(used, ItemID.DEATHRUNE));
			assertEquals(1, qty(used, ItemID.CHAOSRUNE));
			assertEquals(5, qty(used, ItemID.FIRERUNE));
			assertEquals(10, qty(used, ItemID.COINS));
		}
	}

	@Test
	public void tridentOfTheSwampCast()
	{
		for (int trident : new int[]{ItemID.TOXIC_TOTS_CHARGED, ItemID.TOXIC_TOTS_I_CHARGED,
			ItemID.TOXIC_TOTS_CHARGED_ORN, ItemID.TOXIC_TOTS_I_CHARGED_ORN})
		{
			final Map<Integer, Integer> used = run(tridentCast(trident)
				.animationId(AnimationID.HUMAN_CASTWAVE_STAFF_WALKMERGE), 1);
			assertEquals("" + trident, 4, used.size());
			assertEquals(1, qty(used, ItemID.DEATHRUNE));
			assertEquals(1, qty(used, ItemID.CHAOSRUNE));
			assertEquals(5, qty(used, ItemID.FIRERUNE));
			assertEquals(1, qty(used, SCALE));
		}
	}

	@Test
	public void tridentCastsAddUp()
	{
		final Map<Integer, Integer> used = run(tridentCast(ItemID.TOXIC_TOTS_CHARGED), 10);
		assertEquals(10, qty(used, ItemID.DEATHRUNE));
		assertEquals(50, qty(used, ItemID.FIRERUNE));
		assertEquals(10, qty(used, SCALE));
	}

	@Test
	public void unchargedTridentsCastNothing()
	{
		for (int trident : new int[]{ItemID.TOTS_UNCHARGED, ItemID.TOTS_I_UNCHARGED, ItemID.TOTS_UNCHARGED_ORN,
			ItemID.TOTS_I_UNCHARGED_ORN, ItemID.TOXIC_TOTS_UNCHARGED, ItemID.TOXIC_TOTS_I_UNCHARGED,
			ItemID.TOXIC_TOTS_UNCHARGED_ORN, ItemID.TOXIC_TOTS_I_UNCHARGED_ORN})
		{
			assertTrue("" + trident, run(tridentCast(trident), 1).isEmpty());
		}
	}

	@Test
	public void tridentNeedsTheCastGraphic()
	{
		assertTrue(run(tridentCast(ItemID.TOTS_CHARGED).castGraphic(false), 5).isEmpty());
		// A wave spell from another staff shows no trident graphic, and the graphic alone isn't a cast.
		assertTrue(run(tridentCast(ItemID.TOTS_CHARGED).animationId(-1), 5).isEmpty());
	}

	@Test
	public void sanguinestiStaffCastsCostTwoBloodRunesEach()
	{
		for (int staff : new int[]{ItemID.SANGUINESTI_STAFF, ItemID.SANGUINESTI_STAFF_OR})
		{
			final Map<Integer, Integer> used = run(tridentCast(staff), 1);
			assertEquals("" + staff, 1, used.size());
			assertEquals(2, qty(used, ItemID.BLOODRUNE));
		}
		// The walk-merged cast too, and casts add up: whole runes, so nothing carries over.
		final Map<Integer, Integer> used = run(tridentCast(ItemID.SANGUINESTI_STAFF)
			.animationId(AnimationID.HUMAN_CASTWAVE_STAFF_WALKMERGE), 10);
		assertEquals(20, qty(used, ItemID.BLOODRUNE));
	}

	@Test
	public void tumekensShadowCastsCostTwoSoulAndFiveChaosRunesEach()
	{
		final Map<Integer, Integer> used = run(shadowCast(), 3);
		assertEquals(2, used.size());
		assertEquals(6, qty(used, ItemID.SOULRUNE));
		assertEquals(15, qty(used, ItemID.CHAOSRUNE));
	}

	@Test
	public void staffCastsNeedTheirOwnAnimationGraphicAndChargedStaff()
	{
		assertTrue("no graphic", run(tridentCast(ItemID.SANGUINESTI_STAFF).castGraphic(false), 5).isEmpty());
		assertTrue("no graphic", run(shadowCast().castGraphic(false), 5).isEmpty());
		assertTrue("the shadow's animation is not a Sanguinesti cast",
			run(tridentCast(ItemID.SANGUINESTI_STAFF).animationId(SHADOW_CAST), 5).isEmpty());
		assertTrue("the wave-staff animation is not a shadow cast", run(shadowCast().animationId(CAST), 5).isEmpty());
		assertTrue(run(shadowCast().animationFrame(2), 5).isEmpty());
		for (int uncharged : new int[]{ItemID.SANGUINESTI_STAFF_UNCHARGED, ItemID.SANGUINESTI_STAFF_UNCHARGED_OR})
		{
			assertTrue("" + uncharged, run(tridentCast(uncharged), 1).isEmpty());
		}
		assertTrue(run(shadowCast().weaponId(ItemID.TUMEKENS_SHADOW_UNCHARGED), 1).isEmpty());
	}

	@Test
	public void castGraphicsDependOnTheWornWeaponAndAnimation()
	{
		assertEquals(ChargedWeaponUsage.TRIDENT_GRAPHICS, ChargedWeaponUsage.castGraphics(ItemID.TOTS_CHARGED, CAST));
		assertEquals(ChargedWeaponUsage.TRIDENT_GRAPHICS, ChargedWeaponUsage.castGraphics(ItemID.TOXIC_TOTS_CHARGED,
			AnimationID.HUMAN_CASTWAVE_STAFF_WALKMERGE));
		assertEquals(ChargedWeaponUsage.SANGUINESTI_GRAPHICS,
			ChargedWeaponUsage.castGraphics(ItemID.SANGUINESTI_STAFF_OR, CAST));
		assertEquals(ChargedWeaponUsage.SHADOW_GRAPHICS,
			ChargedWeaponUsage.castGraphics(ItemID.TUMEKENS_SHADOW, SHADOW_CAST));
		assertTrue(ChargedWeaponUsage.castGraphics(ItemID.TUMEKENS_SHADOW, CAST).isEmpty());
		assertTrue(ChargedWeaponUsage.castGraphics(ItemID.SANGUINESTI_STAFF, SHADOW_CAST).isEmpty());
		assertTrue(ChargedWeaponUsage.castGraphics(ItemID.SANGUINESTI_STAFF_UNCHARGED, CAST).isEmpty());
		assertTrue(ChargedWeaponUsage.castGraphics(BLOWPIPE, SHOT).isEmpty());
		assertTrue(ChargedWeaponUsage.castGraphics(ChargedWeaponUsage.NO_ITEM, CAST).isEmpty());
	}

	@Test
	public void resetForgetsCarryOversAndTheLastTick()
	{
		run(blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER), 4);
		run(blowpipeShot().dartId(ChargedWeaponUsage.NO_ITEM), 2);
		assertTrue(usage.isDartCheckNeeded());
		usage.reset();
		assertFalse(usage.isDartCheckNeeded());
		tick = 0;
		final Map<Integer, Integer> used = run(blowpipeShot().capeId(ItemID.AVAS_ASSEMBLER), 1);
		assertEquals(0, qty(used, DART));
		assertEquals(0, qty(used, SCALE));
	}

	@Test
	public void trackedIdSetsDontOverlap()
	{
		final List<Set<Integer>> weapons = Arrays.asList(ChargedWeaponUsage.BLOWPIPES,
			ChargedWeaponUsage.SEAS_TRIDENTS, ChargedWeaponUsage.SWAMP_TRIDENTS, ChargedWeaponUsage.SANGUINESTI_STAVES,
			ChargedWeaponUsage.TUMEKENS_SHADOWS);
		for (int i = 0; i < weapons.size(); i++)
		{
			for (int j = i + 1; j < weapons.size(); j++)
			{
				for (int id : weapons.get(i))
				{
					assertFalse(id + " is in two weapon sets", weapons.get(j).contains(id));
				}
			}
		}
		for (int id : ChargedWeaponUsage.SHADOW_ANIMATIONS)
		{
			assertFalse(ChargedWeaponUsage.TRIDENT_ANIMATIONS.contains(id)
				|| ChargedWeaponUsage.BLOWPIPE_ANIMATIONS.contains(id));
		}
		for (int id : ChargedWeaponUsage.ASSEMBLERS)
		{
			assertFalse(ChargedWeaponUsage.ACCUMULATORS.contains(id) || ChargedWeaponUsage.RANGING_CAPES.contains(id)
				|| ChargedWeaponUsage.QUIVERS.contains(id) || ChargedWeaponUsage.ATTRACTORS.contains(id));
		}
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import javax.swing.JComboBox;
import javax.swing.JScrollPane;
import javax.swing.event.PopupMenuListener;
import org.junit.Test;

/**
 * A drop-down's open list widening to fit its longest choice. Headless, the list is never shown, so these check
 * the size it is given; the move to keep its right edge in place needs a screen (checked in game).
 */
public class ComboPopupWidenerTest
{
	private static final String LONG = "Catacombs of Kourend, the far north end";

	private static JComboBox<String> box(String... items)
	{
		JComboBox<String> box = new JComboBox<>(items);
		box.setPrototypeDisplayValue("Abyssal demons");
		box.setSize(box.getPreferredSize());
		return box;
	}

	private static ComboPopupWidener widener(JComboBox<String> box)
	{
		for (PopupMenuListener listener : box.getPopupMenuListeners())
		{
			if (listener instanceof ComboPopupWidener)
			{
				return (ComboPopupWidener) listener;
			}
		}
		throw new AssertionError("no widener");
	}

	@Test
	public void theWidthIsTheContentsAtLeastTheBoxAndAtMostTheMaximum()
	{
		assertEquals(250, ComboPopupWidener.width(120, 250, 320));
		assertEquals("never narrower than the box", 120, ComboPopupWidener.width(120, 80, 320));
		assertEquals("capped", 320, ComboPopupWidener.width(120, 500, 320));
		assertEquals("a box wider than the cap stays as it is", 400, ComboPopupWidener.width(400, 500, 320));
	}

	@Test
	public void theListWidensToItsLongestChoiceAndTheBoxKeepsItsWidth()
	{
		JComboBox<String> box = box("All", LONG);
		int closed = box.getPreferredSize().width;
		ComboPopupWidener.install(box, 1_000);
		widener(box).widen(box);
		JScrollPane scroller = ComboPopupWidener.listScroller(box);
		assertNotNull(scroller);
		int list = scroller.getPreferredSize().width;
		assertTrue("wider than the box: " + list + " > " + closed, list > closed);
		assertEquals("the closed box keeps its width", closed, box.getPreferredSize().width);
	}

	@Test
	public void aLongChoiceIsCappedAndShortOnesKeepTheBoxWidth()
	{
		JComboBox<String> capped = box("All", LONG);
		int cap = capped.getWidth() + 20;
		ComboPopupWidener.install(capped, cap);
		widener(capped).widen(capped);
		assertEquals(cap, ComboPopupWidener.listScroller(capped).getPreferredSize().width);

		JComboBox<String> narrow = box("All", "Abyss");
		ComboPopupWidener.install(narrow, 1_000);
		widener(narrow).widen(narrow);
		int list = ComboPopupWidener.listScroller(narrow).getPreferredSize().width;
		assertTrue("the box's width, less the list's border: " + list + " of " + narrow.getWidth(),
			list <= narrow.getWidth() && list >= narrow.getWidth() - 10);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/**
 * The late-loot grace window for a running session whose task completes ({@link SessionTracker#holdCompletion()}).
 * The plugin calls {@code tickCompletion()} once per game tick before observing, holds on a running completion, and
 * releases any held session with {@code takePendingCompletion()} on every other end path.
 */
public class CompletionGraceTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final int BONES = 526;
	private static final int ASHES = 592;

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	private static ItemTally tally(int id, int qty)
	{
		ItemTally t = new ItemTally();
		t.add(id, qty);
		return t;
	}

	/** Starts a 3-kill demon task, kills all three over 60 seconds and completes it on the last observation. */
	private void runAndCompleteTask()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 3, 3, false);
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.addLoot(tally(BONES, 1));
		now += 30_000;
		tracker.observe("Abyssal demons", DEMON_ID, 1, 3, false);
		now += 30_000;
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
	}

	/** Mirrors the plugin's endSession: a held completion is released first, then the active session is stopped. */
	private SessionTracker.Summary[] endSession()
	{
		return new SessionTracker.Summary[]{tracker.takePendingCompletion(), tracker.stopAndReset()};
	}

	@Test
	public void lootDuringGraceWindowIsIncluded()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.hasPendingCompletion());
		// Same tick as the completion, after the task count update.
		assertTrue(tracker.addLoot(tally(BONES, 1)));

		assertNull("tick 1 of 2", tracker.tickCompletion());
		assertTrue(tracker.addLoot(tally(ASHES, 2)));

		SessionTracker.Summary summary = tracker.tickCompletion();
		assertNotNull("released after " + SessionTracker.COMPLETION_LOOT_GRACE_TICKS + " ticks", summary);
		assertFalse(tracker.hasPendingCompletion());
		assertTrue(summary.isCompleted());
		assertEquals(2, summary.getLoot().get(BONES));
		assertEquals(2, summary.getLoot().get(ASHES));
		assertEquals(SaveDecision.Action.SAVE_COMPLETED,
			SaveDecision.decide(summary, SaveDecision.EndReason.SYSTEM, true));
		assertNull("released once", tracker.tickCompletion());
		assertNull(tracker.takePendingCompletion());
	}

	@Test
	public void lootAfterGraceWindowIsNotIncluded()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		tracker.tickCompletion();
		SessionTracker.Summary summary = tracker.tickCompletion();
		assertNotNull(summary);
		assertFalse("idle, no session", tracker.addLoot(tally(ASHES, 1)));
		assertEquals(1, summary.getLoot().get(BONES));
		assertEquals(0, summary.getLoot().get(ASHES));
	}

	@Test
	public void durationAndKillsAreFrozenAtCompletion()
	{
		runAndCompleteTask();
		final long completedAt = now;
		assertTrue(tracker.holdCompletion());
		assertEquals("the panel shows the session as ended", SessionTracker.State.IDLE, tracker.getState());
		assertNull(tracker.activeSummary());

		now += 600;
		tracker.tickCompletion();
		// A stray count change during the window does not touch the held session.
		tracker.observe("Abyssal demons", DEMON_ID, 5, 5, false);
		now += 600;
		SessionTracker.Summary summary = tracker.tickCompletion();
		assertNotNull(summary);
		assertEquals(3, summary.getKills());
		assertEquals(60_000, summary.getActiveMillis());
		assertEquals(completedAt, summary.getEndedAt());
	}

	@Test
	public void holdIsRefusedUnlessRunningAndCompleted()
	{
		assertFalse("idle", tracker.holdCompletion());
		tracker.observe("Abyssal demons", DEMON_ID, 3, 3, false);
		assertTrue(tracker.startNow(ACCOUNT));
		assertFalse("running, not completed", tracker.holdCompletion());
		assertEquals(SessionTracker.State.RUNNING, tracker.getState());
		assertNull(tracker.tickCompletion());
	}

	@Test
	public void finalKillWhilePausedRestartsTheSessionAndIsHeld()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 3, 3, false);
		assertTrue(tracker.startNow(ACCOUNT));
		now += 10_000;
		tracker.observe("Abyssal demons", DEMON_ID, 2, 3, false);
		tracker.pause();
		now += 10_000;
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));

		// The final kill restarted the session first (at the kill, nothing paired), then completed it.
		assertEquals(SessionTracker.State.RUNNING, tracker.getState());
		assertTrue(tracker.holdCompletion());
		assertTrue("its loot still counts", tracker.addLoot(tally(BONES, 1)));

		SessionTracker.Summary[] ended = endSession();
		assertNotNull(ended[0]);
		assertNull(ended[1]);
		assertTrue(ended[0].isCompleted());
		assertEquals(3, ended[0].getKills());
		assertEquals(10_000, ended[0].getActiveMillis());
		assertEquals(Long.valueOf(1), ended[0].getLoot().toMap().get(BONES));
		assertEquals(SaveDecision.Action.SAVE_COMPLETED,
			SaveDecision.decide(ended[0], SaveDecision.EndReason.SYSTEM, true));
	}

	@Test
	public void completionAfterAwaitedZeroIsHeldToo()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 2, 2, false);
		assertTrue(tracker.startNow(ACCOUNT));
		assertEquals(SessionTracker.ObserveResult.TASK_CLEARED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, false));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.holdCompletion());
		tracker.addLoot(tally(BONES, 1));
		tracker.tickCompletion();
		SessionTracker.Summary summary = tracker.tickCompletion();
		assertEquals(2, summary.getKills());
		assertEquals(1, summary.getLoot().get(BONES));
	}

	@Test
	public void endPathsDuringWindowSaveOnceAsCompleted()
	{
		for (SaveDecision.EndReason reason : new SaveDecision.EndReason[]{SaveDecision.EndReason.LOGOUT,
			SaveDecision.EndReason.PLAYER_STOP, SaveDecision.EndReason.SHUTDOWN, SaveDecision.EndReason.ACCOUNT_SWITCH,
			SaveDecision.EndReason.SYSTEM})
		{
			setUp();
			runAndCompleteTask();
			assertTrue(tracker.holdCompletion());
			tracker.addLoot(tally(ASHES, 1));
			tracker.loggedOut();
			// Logout persists only an active session; a held completion is never one.
			assertNull(reason.name(), tracker.activeSummary());

			SessionTracker.Summary[] ended = endSession();
			assertNotNull(reason.name(), ended[0]);
			assertNull(reason.name() + ": no active session", ended[1]);
			assertTrue(ended[0].isCompleted());
			assertEquals(1, ended[0].getLoot().get(ASHES));
			// The plugin saves a released completion with SYSTEM, but any reason saves a completed summary.
			assertEquals(reason.name(), SaveDecision.Action.SAVE_COMPLETED,
				SaveDecision.decide(ended[0], reason, true));

			// Nothing left to save twice: not by a later tick, end path or shutdown.
			assertNull(tracker.tickCompletion());
			assertNull(tracker.tickCompletion());
			SessionTracker.Summary[] again = endSession();
			assertNull(again[0]);
			assertNull(again[1]);
		}
	}

	@Test
	public void newSessionDuringWindowDoesNotStealLoot()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		tracker.observe("Black dragons", DRAGON_ID, 10, 10, false);
		assertTrue("Play is allowed during the window", tracker.startNow(ACCOUNT));
		assertTrue(tracker.addLoot(tally(ASHES, 1)));
		assertTrue("the new session gets none of it", tracker.getLoot().isEmpty());

		SessionTracker.Summary[] ended = endSession();
		assertEquals(1, ended[0].getLoot().get(ASHES));
		assertEquals(DEMON_ID, ended[0].getCreatureId());
		assertEquals(DRAGON_ID, ended[1].getCreatureId());
		assertTrue(ended[1].getLoot().isEmpty());
	}

	@Test
	public void newSessionGetsLootAfterWindow()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		tracker.observe("Black dragons", DRAGON_ID, 10, 10, false);
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.tickCompletion();
		assertNotNull(tracker.tickCompletion());
		assertTrue(tracker.addLoot(tally(ASHES, 1)));
		assertEquals(1, tracker.getLoot().get(ASHES));
	}

	@Test
	public void secondCompletionIsNotHeldWhileOneIsPending()
	{
		runAndCompleteTask();
		assertTrue(tracker.holdCompletion());
		tracker.observe("Black dragons", DRAGON_ID, 1, 1, false);
		assertTrue(tracker.startNow(ACCOUNT));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertFalse(tracker.holdCompletion());
		// The plugin then ends the session normally, which releases the held one first.
		SessionTracker.Summary[] ended = endSession();
		assertEquals(DEMON_ID, ended[0].getCreatureId());
		assertEquals(DRAGON_ID, ended[1].getCreatureId());
		assertTrue(ended[0].isCompleted());
		assertTrue(ended[1].isCompleted());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class CompletionSignalTest
{
	@Test
	public void firstReadingIsBaselineOnly()
	{
		CompletionSignal signal = new CompletionSignal();
		assertFalse(signal.update(10, 0, 0));
		assertTrue(signal.update(11, 0, 0));
		assertFalse(signal.update(11, 0, 0));
	}

	@Test
	public void resetRestoresBaselineBehaviour()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(10, 0, 0);
		signal.reset();
		assertFalse(signal.update(11, 0, 0));
	}

	@Test
	public void lateLoginSyncIsNotACompletion()
	{
		CompletionSignal signal = new CompletionSignal();
		// counters read as zero before the server resynced them
		assertFalse(signal.update(0, 0, 0));
		assertFalse(signal.update(57, 0, 0));
		assertFalse(signal.update(57, 3, 0));
		assertTrue(signal.update(58, 3, 0));
	}

	@Test
	public void resyncAlongsideAnotherCounterIsNotACompletion()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(0, 0, 0);
		assertFalse(signal.update(1, 40, 0));
	}

	@Test
	public void decreasesAreNotCompletions()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(25, 0, 0);
		assertFalse(signal.update(0, 0, 0)); // streak reset
		assertTrue(signal.update(0, 0, 1)); // another counter increments by one
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Which kill loot a bonecrusher or ash sanctifier leaves out, for each "Bonecrusher handling" mode.
 */
public class CrushedLootFilterTest
{
	private static final List<Integer> NOTHING = Collections.emptyList();
	private static final List<Integer> CRUSHER = Arrays.asList(ItemID.SHARK, ItemID.BONECRUSHER);
	private static final List<Integer> NECKLACE = Collections.singletonList(ItemID.BONECRUSHER_NECKLACE);
	private static final List<Integer> SANCTIFIER = Collections.singletonList(ItemID.ASH_SANCTIFIER);
	private static final List<Integer> BOTH = Arrays.asList(ItemID.BONECRUSHER_NECKLACE, ItemID.ASH_SANCTIFIER);

	/** Wyrm loot as in the owner's task: wyrm bones, demonic ashes, plain ashes, noted bones, coins. */
	private static ItemTally wyrmLoot()
	{
		ItemTally loot = new ItemTally();
		loot.add(ItemID.WYRM_BONES, 1);
		loot.add(ItemID.ABYSSAL_ASHES, 1);
		loot.add(ItemID.ASHES, 1);
		loot.add(ItemID.Cert.DRAGON_BONES, 5);
		loot.add(ItemID.COINS, 300);
		return loot;
	}

	@Test
	public void itemIdsMatchTheGameValues()
	{
		// Checked against net.runelite.api.gameval.ItemID in RuneLite 1.13.4, and the owner's wyrm data (22780).
		assertEquals(13116, ItemID.BONECRUSHER);
		assertEquals(22986, ItemID.BONECRUSHER_NECKLACE);
		assertEquals(25781, ItemID.ASH_SANCTIFIER);
		assertEquals(22780, ItemID.WYRM_BONES);
		assertTrue(CrushedLootFilter.BONES.contains(22780));
		assertTrue(CrushedLootFilter.DEMONIC_ASHES.containsAll(Arrays.asList(25766, 25769, 25772, 25775, 25778)));
		assertEquals(5, CrushedLootFilter.DEMONIC_ASHES.size());
	}

	@Test
	public void boneAndAshSetsDoNotOverlapAndHoldNoNotedOrPlainItems()
	{
		for (int id : CrushedLootFilter.BONES)
		{
			assertFalse(CrushedLootFilter.DEMONIC_ASHES.contains(id));
		}
		assertFalse(CrushedLootFilter.BONES.contains(ItemID.Cert.BONES));
		assertFalse(CrushedLootFilter.BONES.contains(ItemID.Cert.WYRM_BONES));
		assertFalse(CrushedLootFilter.DEMONIC_ASHES.contains(ItemID.ASHES));
		assertFalse(CrushedLootFilter.DEMONIC_ASHES.contains(ItemID.Cert.ABYSSAL_ASHES));
		assertTrue(CrushedLootFilter.BONES.containsAll(Arrays.asList(ItemID.BONES, ItemID.BIG_BONES,
			ItemID.DRAGON_BONES, ItemID.DAGANNOTH_KING_BONES, ItemID.DRAKE_BONES, ItemID.HYDRA_BONES)));
	}

	@Test
	public void autoWithoutACrusherKeepsEverything()
	{
		CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.AUTO, NOTHING);
		assertSame(CrushedLootFilter.KEEP_ALL, filter);
		assertEquals(wyrmLoot(), filter.apply(wyrmLoot()));
		assertSame(CrushedLootFilter.KEEP_ALL, CrushedLootFilter.forDrop(BonecrusherMode.AUTO, null));
		assertSame(CrushedLootFilter.KEEP_ALL, CrushedLootFilter.forDrop(BonecrusherMode.AUTO,
			Arrays.asList(null, ItemID.SHARK)));
	}

	@Test
	public void autoWithABonecrusherDropsBonesOnly()
	{
		for (List<Integer> carried : Arrays.asList(CRUSHER, NECKLACE))
		{
			CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.AUTO, carried);
			assertFalse(filter.keeps(ItemID.WYRM_BONES));
			assertTrue(filter.keeps(ItemID.ABYSSAL_ASHES));
			ItemTally kept = filter.apply(wyrmLoot());
			assertEquals(0, kept.get(ItemID.WYRM_BONES));
			assertEquals(1, kept.get(ItemID.ABYSSAL_ASHES));
			assertEquals(1, kept.get(ItemID.ASHES));
			assertEquals("noted bones are not crushed", 5, kept.get(ItemID.Cert.DRAGON_BONES));
			assertEquals(300, kept.get(ItemID.COINS));
			assertEquals(4, kept.size());
		}
	}

	@Test
	public void autoWithAnAshSanctifierDropsDemonicAshesOnly()
	{
		CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.AUTO, SANCTIFIER);
		assertTrue(filter.keeps(ItemID.WYRM_BONES));
		assertFalse(filter.keeps(ItemID.ABYSSAL_ASHES));
		ItemTally kept = filter.apply(wyrmLoot());
		assertEquals(1, kept.get(ItemID.WYRM_BONES));
		assertEquals(0, kept.get(ItemID.ABYSSAL_ASHES));
		assertEquals("plain ashes are not demonic", 1, kept.get(ItemID.ASHES));
	}

	@Test
	public void autoWithBothDropsBonesAndAshes()
	{
		ItemTally kept = CrushedLootFilter.forDrop(BonecrusherMode.AUTO, BOTH).apply(wyrmLoot());
		assertEquals(0, kept.get(ItemID.WYRM_BONES));
		assertEquals(0, kept.get(ItemID.ABYSSAL_ASHES));
		assertEquals(3, kept.size());
	}

	@Test
	public void alwaysExcludeIgnoresWhatIsCarried()
	{
		for (List<Integer> carried : Arrays.asList(NOTHING, CRUSHER, null))
		{
			CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.ALWAYS_EXCLUDE, carried);
			assertFalse(filter.keeps(ItemID.WYRM_BONES));
			assertFalse(filter.keeps(ItemID.ABYSSAL_ASHES));
			assertFalse(filter.keeps(ItemID.INFERNAL_ASHES));
			assertTrue(filter.keeps(ItemID.COINS));
		}
		assertFalse(CrushedLootFilter.needsCarriedItems(BonecrusherMode.ALWAYS_EXCLUDE));
	}

	@Test
	public void neverExcludeKeepsEverythingEvenWithACrusher()
	{
		CrushedLootFilter filter = CrushedLootFilter.forDrop(BonecrusherMode.NEVER_EXCLUDE, BOTH);
		assertSame(CrushedLootFilter.KEEP_ALL, filter);
		assertEquals(wyrmLoot(), filter.apply(wyrmLoot()));
		assertFalse(CrushedLootFilter.needsCarriedItems(BonecrusherMode.NEVER_EXCLUDE));
	}

	@Test
	public void nullModeIsAuto()
	{
		assertTrue(CrushedLootFilter.needsCarriedItems(BonecrusherMode.AUTO));
		assertTrue(CrushedLootFilter.needsCarriedItems(null));
		assertFalse(CrushedLootFilter.forDrop(null, CRUSHER).keeps(ItemID.WYRM_BONES));
	}

	@Test
	public void applyLeavesTheInputAloneAndHandlesNull()
	{
		ItemTally loot = wyrmLoot();
		CrushedLootFilter.forDrop(BonecrusherMode.ALWAYS_EXCLUDE, null).apply(loot);
		assertEquals(wyrmLoot(), loot);
		assertTrue(CrushedLootFilter.KEEP_ALL.apply(null).isEmpty());
	}

	@Test
	public void modesShowReadableNames()
	{
		assertEquals("Auto", BonecrusherMode.AUTO.toString());
		assertEquals("Always exclude", BonecrusherMode.ALWAYS_EXCLUDE.toString());
		assertEquals("Never exclude", BonecrusherMode.NEVER_EXCLUDE.toString());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import org.junit.Test;

/**
 * Engagements and kill pairing (V2 plan 4.1): each damaged NPC's run of the player's hits, the deaths paired with a
 * task kill, and tallying the deaths before a restart once. {@link CatacombsVariantsTest} covers keeping, forgetting
 * and bounding the NPCs themselves.
 */
public class DamagedNpcsTest
{
	private static final long MINUTE = 60_000L;
	private static final long AWAY = 10 * MINUTE;
	/**
	 * The game tick of a hit in the tests of engagements and deaths: those never put hits down to attacks
	 * ({@link DamagedNpcs#applyHits}), so it is never read.
	 */
	private static final int NO_TICK = 0;

	@Test
	public void engagementStartsAtTheFirstHitOfTheCurrentRun()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 1, 1_000, AWAY, NO_TICK);
		npcs.damaged(0, 1, 5 * MINUTE, AWAY, NO_TICK);
		npcs.damaged(0, 1, 14 * MINUTE, AWAY, NO_TICK);
		assertTrue(npcs.died(0, 1, "Abyssal demon", "Abyssal demon", false, 100, 15 * MINUTE, AWAY));

		KillPairing pairing = npcs.pairing(98, 100);
		assertEquals("no gap over the limit: one engagement", 1_000, pairing.getEarliestStart());
		assertEquals(Collections.singleton("Abyssal demon"), pairing.getNames());
	}

	@Test
	public void aGapOverTheLimitStartsANewEngagement()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 1, 0, AWAY, NO_TICK);
		// Walked off for half an hour, then came back for it.
		npcs.damaged(0, 1, 30 * MINUTE, AWAY, NO_TICK);
		npcs.damaged(0, 1, 31 * MINUTE, AWAY, NO_TICK);
		npcs.died(0, 1, "Abyssal demon", "Abyssal demon", false, 10, 31 * MINUTE, AWAY);

		assertEquals(30 * MINUTE, npcs.pairing(8, 10).getEarliestStart());
	}

	@Test
	public void anNpcHitLongBeforeItDiesDoesNotStretchTheStart()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 1, 0, AWAY, NO_TICK);
		// Killed 20 minutes later by someone else, or a cannon: its own run is the death itself.
		npcs.died(0, 1, "Abyssal demon", "Abyssal demon", false, 10, 20 * MINUTE, AWAY);

		KillPairing pairing = npcs.pairing(8, 10);
		assertEquals(20 * MINUTE, pairing.getEarliestStart());
		assertEquals("still a task NPC", Collections.singleton("Abyssal demon"), pairing.getNames());
	}

	@Test
	public void aBarrageMultiKillPairsEveryDeathInTheWindow()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 1, 2_000, AWAY, NO_TICK);
		npcs.damaged(0, 2, 1_000, AWAY, NO_TICK);
		npcs.damaged(0, 3, 3_000, AWAY, NO_TICK);
		npcs.damaged(0, 4, 500, AWAY, NO_TICK);
		npcs.died(0, 1, "Dust devil", "Dust devil", false, 99, 60_000, AWAY);
		npcs.died(0, 2, "Dust devil", "Dust devil", false, 100, 60_000, AWAY);
		npcs.died(0, 3, "Choke devil", "Choke devil", false, 101, 60_000, AWAY);
		// Outside T - 2 to T + 1 for a kill on tick 100.
		npcs.died(0, 4, "Abyssal demon", "Abyssal demon", false, 97, 60_000, AWAY);

		KillPairing atKill = npcs.pairing(98, 100);
		assertEquals(1_000, atKill.getEarliestStart());
		assertEquals(Collections.singleton("Dust devil"), atKill.getNames());
		KillPairing nextTick = npcs.pairing(98, 101);
		assertEquals(new LinkedHashSet<>(Arrays.asList("Dust devil", "Choke devil")), nextTick.getNames());
		assertEquals(1_000, nextTick.getEarliestStart());
	}

	@Test
	public void nothingPairedIsNoStart()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		KillPairing pairing = npcs.pairing(98, 100);
		assertFalse(pairing.hasStart());
		assertEquals(KillPairing.NO_START, pairing.getEarliestStart());
		assertTrue(pairing.getNames().isEmpty());
		assertTrue(pairing.isStartAllowed());
		assertFalse(pairing.withStartBlocked().isStartAllowed());

		// An NPC the player never hit is no kill of theirs.
		assertFalse(npcs.died(0, 9, "Abyssal demon", "Abyssal demon", false, 100, 1_000, AWAY));
		assertFalse(npcs.pairing(98, 100).hasStart());
	}

	@Test
	public void theDeathsBeforeARestartAreTalliedOnceByTheKillThatRestartsIt()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		for (int index = 1; index <= 5; index++)
		{
			npcs.damaged(0, index, 1_000, AWAY, NO_TICK);
		}
		// Died while the session was stopped, so refused then; a kill on tick 100 restarts it.
		npcs.died(0, 1, "Deviant spectre", "Deviant spectre", false, 98, 2_000, AWAY);
		npcs.died(0, 2, "Deviant spectre", "Deviant spectre", false, 100, 2_000, AWAY);
		// Tallied as it died (the session ran then).
		npcs.died(0, 3, "Deviant spectre", "Deviant spectre", true, 100, 2_000, AWAY);
		// Before the kill's window (T - 2 to T).
		npcs.died(0, 4, "Abyssal demon", "Abyssal demon", false, 97, 2_000, AWAY);

		List<String> tallied = new ArrayList<>();
		assertEquals(2, npcs.tallyUntallied(98, 100, tallied::add));
		assertEquals(Arrays.asList("Deviant spectre", "Deviant spectre"), tallied);
		assertEquals("a restart on the next tick: its window overlaps, nothing is tallied twice", 0,
			npcs.tallyUntallied(99, 101, tallied::add));

		// One the tally refuses stays untallied, for a later kill to try again.
		npcs.died(0, 5, "Deviant spectre", "Deviant spectre", false, 101, 2_000, AWAY);
		assertEquals("refused", 0, npcs.tallyUntallied(99, 101, name -> false));
		assertEquals(1, npcs.tallyUntallied(99, 101, tallied::add));
		assertEquals(3, tallied.size());
	}

	@Test
	public void deathsAreKeptOnlyAFewTicks()
	{
		DamagedNpcs npcs = new DamagedNpcs();
		npcs.damaged(0, 1, 1_000, AWAY, NO_TICK);
		npcs.died(0, 1, "Abyssal demon", "Abyssal demon", false, 100, 2_000, AWAY);

		assertTrue("paired again on the tick after a kill on tick 102",
			npcs.pairing(100, 103).hasStart());
		assertFalse("dropped after DEATH_KEEP_TICKS", npcs.pairing(90, 100 + DamagedNpcs.DEATH_KEEP_TICKS + 1).hasStart());

		npcs.damaged(0, 2, 1_000, AWAY, NO_TICK);
		npcs.died(0, 2, "Abyssal demon", "Abyssal demon", false, 200, 2_000, AWAY);
		npcs.clear();
		assertFalse("a login or hop forgets the deaths", npcs.pairing(198, 200).hasStart());
	}

	// ---- Styles ----

	/** The key of the NPC at {@code index} in world view 0, as the plugin keys an attack's target. */
	private static long npc(int index)
	{
		return DamagedNpcs.key(0, index);
	}

	@Test
	public void eachHitCountsForItsAttacksStyleAndADeathGivesItsMajority()
	{
		final DamagedNpcs npcs = new DamagedNpcs();
		final PlayerAttacks attacks = new PlayerAttacks();
		attacks.add(100, SetupStyle.MELEE, 60_000, npc(1), false);
		npcs.applyHits(attacks);
		// A melee hit lands the tick after its attack.
		npcs.damaged(0, 1, 60_600, AWAY, 101);
		npcs.applyHits(attacks);
		attacks.add(104, SetupStyle.MELEE, 62_400, npc(1), false);
		npcs.applyHits(attacks);
		npcs.damaged(0, 1, 63_000, AWAY, 105);
		// A cannon's hit: no attack of the player's around it.
		npcs.damaged(0, 1, 63_600, AWAY, 110);
		npcs.applyHits(attacks);
		npcs.died(0, 1, "Abyssal demon", "Abyssal demon", false, 110, 63_600, AWAY);

		assertEquals(Collections.singletonList(SetupStyle.MELEE), npcs.takeStyles(108, 111, 1));
		assertTrue("each death's style goes to one kill", npcs.takeStyles(108, 111, 1).isEmpty());
	}

	@Test
	public void theKillingHitPutDownAfterTheDeathStillCounts()
	{
		final DamagedNpcs npcs = new DamagedNpcs();
		final PlayerAttacks attacks = new PlayerAttacks();
		attacks.add(100, SetupStyle.MELEE, 60_000, npc(1), false);
		// The hit and the death arrive before the next tick's GameTick, which puts the hit down to the attack.
		npcs.damaged(0, 1, 60_600, AWAY, 101);
		npcs.died(0, 1, "Abyssal demon", "Abyssal demon", false, 101, 60_600, AWAY);
		npcs.applyHits(attacks);
		assertEquals(Collections.singletonList(SetupStyle.MELEE), npcs.takeStyles(99, 102, 1));
	}

	@Test
	public void onlyHitsOnTheAttacksTargetOrItsSplashCount()
	{
		final DamagedNpcs npcs = new DamagedNpcs();
		final PlayerAttacks attacks = new PlayerAttacks();
		// A dart at NPC 1; the cannon hits NPC 2 as the dart lands.
		attacks.add(100, SetupStyle.RANGED, 60_000, npc(1), false);
		npcs.damaged(0, 2, 61_200, AWAY, 102);
		npcs.damaged(0, 1, 61_200, AWAY, 102);
		npcs.applyHits(attacks);
		// A barrage at NPC 1 when the blowpipe allows; the cannon hits NPC 3 on the next tick, then the barrage lands on
		// NPC 3 (its splash, arriving before the hit on its target) and NPC 1 together.
		attacks.add(102, SetupStyle.BARRAGE, 61_200, npc(1), true);
		npcs.damaged(0, 3, 61_800, AWAY, 103);
		npcs.applyHits(attacks);
		npcs.damaged(0, 3, 62_400, AWAY, 104);
		npcs.damaged(0, 1, 62_400, AWAY, 104);
		npcs.applyHits(attacks);
		for (int index = 1; index <= 3; index++)
		{
			npcs.died(0, index, "Dust devil", "Dust devil", false, 104, 62_400, AWAY);
		}

		final List<SetupStyle> styles = npcs.takeStyles(102, 105, 3);
		assertEquals("NPC 1: the dart and the barrage (a tie); NPC 2: only the cannon's hit; NPC 3: the splash",
			Arrays.asList(SetupStyle.MIXED, null, SetupStyle.BARRAGE), styles);
	}

	@Test
	public void aRangedHitStartsItsRunAtTheAttacksTick()
	{
		final DamagedNpcs npcs = new DamagedNpcs();
		final PlayerAttacks attacks = new PlayerAttacks();
		attacks.add(100, SetupStyle.RANGED, 60_000, npc(1), false);
		npcs.applyHits(attacks);
		// The arrow lands two ticks later.
		npcs.damaged(0, 1, 61_100, AWAY, 102);
		npcs.applyHits(attacks);
		npcs.died(0, 1, "Abyssal demon", "Abyssal demon", false, 102, 61_100, AWAY);
		assertEquals("backdated to the attack's tick, before its XP", 60_000, npcs.pairing(100, 102).getEarliestStart());

		// A cannon's hit moves nothing.
		npcs.damaged(0, 2, 70_000, AWAY, 120);
		npcs.applyHits(attacks);
		npcs.died(0, 2, "Abyssal demon", "Abyssal demon", false, 120, 70_000, AWAY);
		assertEquals(70_000, npcs.pairing(118, 120).getEarliestStart());
		assertEquals(Collections.singletonList(null), npcs.takeStyles(118, 120, 1));
	}

	@Test
	public void aCountDropTakesTheStylesOfItsDeathsOldestFirstUpToItsKills()
	{
		final DamagedNpcs npcs = new DamagedNpcs();
		final PlayerAttacks attacks = new PlayerAttacks();
		attacks.add(100, SetupStyle.BARRAGE, 60_000, npc(1), true);
		for (int index = 1; index <= 3; index++)
		{
			// The barrage on its target, NPC 1, and its splash on two more.
			npcs.damaged(0, index, 61_000, AWAY, 102);
		}
		npcs.applyHits(attacks);
		for (int index = 1; index <= 3; index++)
		{
			npcs.died(0, index, "Dust devil", "Dust devil", false, 102, 61_000, AWAY);
		}
		assertEquals(Arrays.asList(SetupStyle.BARRAGE, SetupStyle.BARRAGE), npcs.takeStyles(100, 103, 2));
		assertEquals("the third death is left for the next kill", Collections.singletonList(SetupStyle.BARRAGE),
			npcs.takeStyles(100, 104, 5));
		npcs.damaged(0, 9, 61_000, AWAY, 102);
		npcs.clear();
		npcs.applyHits(attacks);
		assertTrue("a login or hop forgets the hits waiting too", npcs.takeStyles(100, 104, 5).isEmpty());
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.AbstractExecutorService;
import java.util.concurrent.Callable;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

/**
 * Test stand-in for RuneLite's shared {@link ScheduledExecutorService}. Tasks are queued and run only when the test
 * (or {@link PluginHarness}) calls {@link #runPending}, in submission order, on the calling thread. This keeps file
 * IO deterministic while still being asynchronous from the plugin's point of view: work handed to the executor has
 * not happened until it is drained, as in the real client.
 *
 * <p>{@link #submit} returns a {@link java.util.concurrent.FutureTask}, which completes when the task runs, so
 * {@code ClientShutdown.waitFor} sees real completion. Delayed scheduling is not used by the plugin and throws
 * {@link UnsupportedOperationException} so a future use is noticed. After {@link #shutdown()} new tasks are rejected
 * with {@link RejectedExecutionException}, as a stopped executor would.</p>
 */
final class DeterministicExecutor extends AbstractExecutorService implements ScheduledExecutorService
{
	private final Queue<Runnable> tasks = new ArrayDeque<>();
	private boolean shutdown;
	private boolean running;

	@Override
	public synchronized void execute(Runnable command)
	{
		if (shutdown)
		{
			throw new RejectedExecutionException("executor is shut down");
		}
		tasks.add(command);
	}

	/** Number of queued tasks not yet run. */
	synchronized int pendingCount()
	{
		return tasks.size();
	}

	/** Whether a task is running right now (on the draining thread). */
	synchronized boolean isRunningTask()
	{
		return running;
	}

	/**
	 * Runs queued tasks, including ones they queue, until none are left. A task that throws is reported to
	 * {@code onError} and the rest still run.
	 *
	 * @return the number of tasks run
	 */
	int runPending(Consumer<Throwable> onError)
	{
		int ran = 0;
		for (;;)
		{
			final Runnable task;
			synchronized (this)
			{
				task = tasks.poll();
				if (task == null)
				{
					return ran;
				}
				running = true;
			}
			try
			{
				task.run();
			}
			catch (RuntimeException | Error e)
			{
				onError.accept(e);
			}
			finally
			{
				synchronized (this)
				{
					running = false;
				}
			}
			ran++;
		}
	}

	@Override
	public synchronized void shutdown()
	{
		shutdown = true;
	}

	@Override
	public synchronized List<Runnable> shutdownNow()
	{
		shutdown = true;
		final List<Runnable> remaining = new ArrayList<>(tasks);
		tasks.clear();
		return remaining;
	}

	@Override
	public synchronized boolean isShutdown()
	{
		return shutdown;
	}

	@Override
	public synchronized boolean isTerminated()
	{
		return shutdown && tasks.isEmpty() && !running;
	}

	@Override
	public boolean awaitTermination(long timeout, TimeUnit unit)
	{
		return isTerminated();
	}

	@Override
	public ScheduledFuture<?> schedule(Runnable command, long delay, TimeUnit unit)
	{
		throw new UnsupportedOperationException("delayed tasks are not supported by the test executor");
	}

	@Override
	public <V> ScheduledFuture<V> schedule(Callable<V> callable, long delay, TimeUnit unit)
	{
		throw new UnsupportedOperationException("delayed tasks are not supported by the test executor");
	}

	@Override
	public ScheduledFuture<?> scheduleAtFixedRate(Runnable command, long initialDelay, long period, TimeUnit unit)
	{
		throw new UnsupportedOperationException("periodic tasks are not supported by the test executor");
	}

	@Override
	public ScheduledFuture<?> scheduleWithFixedDelay(Runnable command, long initialDelay, long delay, TimeUnit unit)
	{
		throw new UnsupportedOperationException("periodic tasks are not supported by the test executor");
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertTrue;
import net.runelite.client.eventbus.EventBus;
import org.junit.Rule;
import org.junit.Test;

/**
 * The event bus rejects subscriber methods not named after their event, which stops the plugin from starting. Unit
 * tests that call the plugin directly cannot see that, so register its subscribers the way the client does.
 */
public class EventSubscriberTest
{
	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void pluginSubscribersRegisterWithTheEventBus()
	{
		EventBus eventBus = new EventBus();
		SlayerLedgerPlugin plugin = new SlayerLedgerPlugin();
		eventBus.register(plugin);

		// startUp registers the plugin's other subscriber, the completion grace ticker, with the injected (real) bus;
		// a rejected one would make it throw.
		harness.startUp();
		assertTrue(harness.isRunning());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;

/**
 * The record-fast task line ({@link FastestTaskMessage}): what counts as a record (3 earlier completed tasks of the same
 * name, strictly faster per kill; not a tie, a partial task, another cannon use or Catacombs version), the margin at
 * this task's kills, and the line's words.
 */
public class FastestTaskMessageTest
{
	private static final long MINUTE = 60_000L;
	private static final AtomicInteger IDS = new AtomicInteger();

	@Test
	public void theDesignShape()
	{
		// Three earlier 200-kill tasks, the best 56 min; this one 52 min.
		LedgerRecord task = devils(200, 52 * MINUTE);
		List<LedgerRecord> history = Arrays.asList(devils(200, 56 * MINUTE), devils(200, 60 * MINUTE),
			devils(200, 70 * MINUTE), task);

		FastestTaskMessage.Record record = FastestTaskMessage.find(task, history);

		assertNotNull(record);
		assertEquals("Fastest Dust devils task yet: 52 min, 4 min under your old best.",
			FastestTaskMessage.line(record));
		assertEquals("<colHIGHLIGHT>Fastest Dust devils task yet:<colNORMAL> 52 min, 4 min under your old best.",
			FastestTaskMessage.chatMessage(record));
	}

	@Test
	public void needsThreeEarlierCompletedTasks()
	{
		LedgerRecord task = devils(200, 30 * MINUTE);

		assertNull(FastestTaskMessage.find(task, Collections.singletonList(task)));
		assertNull(FastestTaskMessage.find(task, Arrays.asList(devils(200, 60 * MINUTE), devils(200, 60 * MINUTE))));
		// A partial task is not one to beat.
		assertNull(FastestTaskMessage.find(task, Arrays.asList(devils(200, 60 * MINUTE), devils(200, 60 * MINUTE),
			partial(devils(200, 60 * MINUTE)))));
		assertNotNull(FastestTaskMessage.find(task, Arrays.asList(devils(200, 60 * MINUTE), devils(200, 60 * MINUTE),
			devils(200, 60 * MINUTE))));
	}

	@Test
	public void aTieOrSlowerIsNoRecord()
	{
		List<LedgerRecord> history = Arrays.asList(devils(200, 50 * MINUTE), devils(200, 60 * MINUTE),
			devils(200, 70 * MINUTE));

		assertNull("a tie", FastestTaskMessage.find(devils(200, 50 * MINUTE), history));
		// The same time per kill on a task of another size is a tie too.
		assertNull("a tie per kill", FastestTaskMessage.find(devils(100, 25 * MINUTE), history));
		assertNull("slower", FastestTaskMessage.find(devils(200, 51 * MINUTE), history));
		assertNotNull("a second faster", FastestTaskMessage.find(devils(200, 50 * MINUTE - 1_000), history));
	}

	@Test
	public void aPartialTaskIsNoRecord()
	{
		List<LedgerRecord> history = Arrays.asList(devils(200, 50 * MINUTE), devils(200, 60 * MINUTE),
			devils(200, 70 * MINUTE));

		assertNull(FastestTaskMessage.find(partial(devils(200, 10 * MINUTE)), history));
		LedgerRecord notCompleted = devils(200, 10 * MINUTE);
		notCompleted.setCompleted(false);
		assertNull(FastestTaskMessage.find(notCompleted, history));
		assertNull(FastestTaskMessage.find(null, history));
		assertNull(FastestTaskMessage.find(devils(200, 10 * MINUTE), null));
	}

	@Test
	public void onlyTheSameCannonUseAndVersionCount()
	{
		LedgerRecord task = devils(200, 30 * MINUTE);
		List<LedgerRecord> cannon = Arrays.asList(cannon(devils(200, 60 * MINUTE)), cannon(devils(200, 60 * MINUTE)),
			cannon(devils(200, 60 * MINUTE)));

		assertNull("cannon tasks are another group", FastestTaskMessage.find(task, cannon));
		assertNotNull(FastestTaskMessage.find(cannon(devils(200, 30 * MINUTE)), cannon));
		assertEquals("Fastest Dust devils (cannon) task yet: 30 min, 30 min under your old best.",
			FastestTaskMessage.line(FastestTaskMessage.find(cannon(devils(200, 30 * MINUTE)), cannon)));

		List<LedgerRecord> spectres = Arrays.asList(spectres(null, 60), spectres(null, 60), spectres(null, 60));
		assertNull("the Catacombs variant is another group",
			FastestTaskMessage.find(spectres("Deviant spectres", 30), spectres));
		assertNotNull(FastestTaskMessage.find(spectres(null, 30), spectres));
		// Matched as the history groups names: case and spaces don't matter.
		LedgerRecord upper = spectres(null, 30);
		upper.setMonster(" ABERRANT SPECTRES ");
		assertNotNull(FastestTaskMessage.find(upper, spectres));
	}

	@Test
	public void theMarginIsAtThisTasksKills()
	{
		// The best earlier task did 100 kills in 30 min (18 s a kill): 200 kills at that pace take 60 min.
		List<LedgerRecord> history = Arrays.asList(devils(100, 30 * MINUTE), devils(150, 60 * MINUTE),
			devils(300, 120 * MINUTE));

		FastestTaskMessage.Record record = FastestTaskMessage.find(devils(200, 52 * MINUTE), history);

		assertEquals(52 * MINUTE, record.getActiveMillis());
		assertEquals(8 * MINUTE, record.getMarginMillis());
		assertEquals("Fastest Dust devils task yet: 52 min, 8 min under your old best.", FastestTaskMessage.line(record));
	}

	@Test
	public void shortAndLongTimes()
	{
		List<LedgerRecord> history = Arrays.asList(devils(200, 90 * MINUTE + 20_000), devils(200, 100 * MINUTE),
			devils(200, 120 * MINUTE));

		assertEquals("Fastest Dust devils task yet: 1 h 30 min, <1 min under your old best.",
			FastestTaskMessage.line(FastestTaskMessage.find(devils(200, 90 * MINUTE), history)));
		assertEquals("Fastest Dust devils task yet: 20 min, 1 h 10 min under your old best.",
			FastestTaskMessage.line(FastestTaskMessage.find(devils(200, 20 * MINUTE + 20_000), history)));
	}

	@Test
	public void theTaskItselfIsLeftOutOfTheHistory()
	{
		LedgerRecord task = devils(200, 30 * MINUTE);
		LedgerRecord copy = devils(200, 30 * MINUTE);
		copy.setId(task.getId());
		List<LedgerRecord> history = new ArrayList<>(Arrays.asList(devils(200, 60 * MINUTE), devils(200, 60 * MINUTE),
			task, copy));

		assertNull("two others only", FastestTaskMessage.find(task, history));
		history.add(devils(200, 60 * MINUTE));
		assertNotNull(FastestTaskMessage.find(task, history));
	}

	@Test
	public void aLongName()
	{
		List<LedgerRecord> history = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			history.add(thermy(60));
		}
		assertEquals("Fastest Thermonuclear smoke devil task yet: 30 min, 30 min under your old best.",
			FastestTaskMessage.line(FastestTaskMessage.find(thermy(30), history)));
	}

	/** A completed Dust devils task without a cannon. */
	private static LedgerRecord devils(int kills, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId("task-" + IDS.incrementAndGet());
		record.setCreatureId(49);
		record.setMonster("Dust devils");
		record.setKills(kills);
		record.setActiveMillis(activeMillis);
		record.setCompleted(true);
		SetupTags.detected(false, SetupStyle.BARRAGE, GearFocus.UNKNOWN, SetupOverrides.NONE).copyTo(record);
		return record;
	}

	private static LedgerRecord cannon(LedgerRecord record)
	{
		SetupTags.detected(true, SetupStyle.MELEE, GearFocus.UNKNOWN, SetupOverrides.NONE).copyTo(record);
		return record;
	}

	private static LedgerRecord partial(LedgerRecord record)
	{
		record.setPartial(true);
		return record;
	}

	/** A completed 100-kill Aberrant spectres task, on {@code variant} when given. */
	private static LedgerRecord spectres(String variant, int minutes)
	{
		LedgerRecord record = devils(100, minutes * MINUTE);
		record.setCreatureId(7);
		record.setMonster("Aberrant spectres");
		record.setVariant(variant);
		return record;
	}

	/** A completed 50-kill Smoke devils task done on the Thermonuclear smoke devil. */
	private static LedgerRecord thermy(int minutes)
	{
		LedgerRecord record = devils(50, minutes * MINUTE);
		record.setMonster("Smoke devils");
		record.setVariant("Thermonuclear smoke devil");
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.FontMetrics;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Supplier;
import javax.swing.SwingUtilities;
import javax.swing.plaf.basic.BasicHTML;
import net.runelite.client.ui.FontManager;
import org.junit.Test;

/**
 * {@link FitLabel}: no width of its own, a text that doesn't fit is cut short with the fonts' own ellipsis, and its
 * text is never rendered as HTML.
 */
public class FitLabelTest
{
	private static <T> T onEdt(Supplier<T> read) throws Exception
	{
		List<T> result = new ArrayList<>(1);
		SwingUtilities.invokeAndWait(() -> result.add(read.get()));
		return result.get(0);
	}

	@Test
	public void aLongTextIsCutShortWithAnEllipsisAndKeptInFull() throws Exception
	{
		String name = "Thermonuclear smoke devil (cannon)";
		String[] shown = onEdt(() ->
		{
			FitLabel label = new FitLabel(name);
			label.setFont(FontManager.getRunescapeBoldFont());
			String before = label.getText();
			label.setBounds(0, 0, 120, 16);
			FontMetrics metrics = label.getFontMetrics(label.getFont());
			return new String[]{before, label.getText(), label.getFullText(),
				Integer.toString(metrics.stringWidth(label.getText())),
				Integer.toString(label.getPreferredSize().width)};
		});
		assertEquals("before it is laid out, the whole text", name, shown[0]);
		assertTrue(shown[1], shown[1].endsWith(FitLabel.ELLIPSIS));
		assertTrue(shown[1], name.startsWith(shown[1].substring(0, shown[1].length() - 1)));
		assertTrue("fits: " + shown[3], Integer.parseInt(shown[3]) <= 120);
		assertEquals(name, shown[2]);
		assertEquals("asks for no width", "0", shown[4]);
	}

	@Test
	public void aTextThatFitsIsShownWholeAndFollowsTheWidth() throws Exception
	{
		String[] shown = onEdt(() ->
		{
			FitLabel label = new FitLabel("Dust devils");
			label.setFont(FontManager.getRunescapeBoldFont());
			label.setBounds(0, 0, 157, 16);
			String wide = label.getText();
			label.setBounds(0, 0, 30, 16);
			String narrow = label.getText();
			label.setBounds(0, 0, 157, 16);
			label.setText("Abyssal demons");
			return new String[]{wide, narrow, label.getText()};
		});
		assertEquals("Dust devils", shown[0]);
		assertTrue(shown[1], shown[1].endsWith(FitLabel.ELLIPSIS) && shown[1].length() < "Dust devils".length());
		assertEquals("a new text fits the width it has", "Abyssal demons", shown[2]);
	}

	@Test
	public void aSpaceBeforeTheEllipsisIsDroppedButALeadingOneStays() throws Exception
	{
		String[] shown = onEdt(() ->
		{
			FitLabel label = new FitLabel("Dust devils");
			label.setFont(FontManager.getRunescapeBoldFont());
			FontMetrics metrics = label.getFontMetrics(label.getFont());
			// Room for "Dust " and the ellipsis, not for "Dust d".
			label.setBounds(0, 0, metrics.stringWidth("Dust ") + metrics.stringWidth(FitLabel.ELLIPSIS), 16);
			String cut = label.getText();
			label.setText(" Dust devils");
			label.setBounds(0, 0, metrics.stringWidth(" Dust") + metrics.stringWidth(FitLabel.ELLIPSIS), 16);
			return new String[]{cut, label.getText()};
		});
		assertEquals("Dust" + FitLabel.ELLIPSIS, shown[0]);
		assertEquals(" Dust" + FitLabel.ELLIPSIS, shown[1]);
	}

	@Test
	public void playerTypedHtmlStaysPlainTextWholeOrCutShort() throws Exception
	{
		String typed = "<html><b>My spot</b> with a very long name that will not fit the card";
		Object[] shown = onEdt(() ->
		{
			// As TaskBoxView sets a typed location that starts with "<html": after a space.
			FitLabel guarded = new FitLabel();
			guarded.setFont(FontManager.getRunescapeSmallFont());
			guarded.setText(" " + typed);
			guarded.setBounds(0, 0, 157, 12);
			// And without the space: whole before it is laid out, then cut short.
			FitLabel bare = new FitLabel(typed);
			bare.setFont(FontManager.getRunescapeSmallFont());
			boolean wholeIsHtml = bare.getClientProperty(BasicHTML.propertyKey) != null;
			bare.setBounds(0, 0, 157, 12);
			return new Object[]{guarded.getText(), guarded.getClientProperty(BasicHTML.propertyKey), wholeIsHtml,
				bare.getText(), bare.getClientProperty(BasicHTML.propertyKey)};
		});
		String guarded = (String) shown[0];
		assertTrue(guarded, guarded.startsWith(" <html><b>My spot") && guarded.endsWith(FitLabel.ELLIPSIS));
		assertNull("cut short, the guarded text is not rendered as HTML", shown[1]);
		assertFalse("whole, a typed <html> is not rendered as HTML", (Boolean) shown[2]);
		String bare = (String) shown[3];
		assertTrue(bare, bare.startsWith("<html><b>My spot") && bare.endsWith(FitLabel.ELLIPSIS));
		assertNull("nor cut short", shown[4]);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/**
 * Stripping tags and Jagex's {@code @name@} colour markup from game messages.
 */
public class GameMessageTextTest
{
	@Test
	public void stripsTagsAndAtMarkup()
	{
		assertEquals("A superior foe has appeared...",
			GameMessageText.plain("@mes_hl_red@A superior foe has appeared...</col>"));
		assertEquals("Your divine magic potion is about to expire.",
			GameMessageText.plain("@mes_hl_red@Your divine magic potion is about to expire.</col>"));
		assertEquals("Darts: Adamant dart x 1,234.", GameMessageText.plain("Darts: <col=007f00>Adamant dart x 1,234</col>."));
		assertEquals("red then blue", GameMessageText.plain(" @red@red then @blu@blue "));
	}

	@Test
	public void leavesOtherAtSignsAlone()
	{
		assertEquals("Mail me @ home", GameMessageText.plain("Mail me @ home"));
		assertEquals("@ABC@ stays", GameMessageText.plain("@ABC@ stays"));
		assertEquals("a@b", GameMessageText.plain("a@b"));
	}

	@Test
	public void plainTextAndNull()
	{
		assertEquals("You have completed your task!", GameMessageText.plain("You have completed your task!"));
		assertEquals("", GameMessageText.plain(""));
		assertNull(GameMessageText.plain(null));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Ground Items' hidden list as Slayer Ledger reads it: {@link GroundItemsHidden} matches names as
 * {@code GroundItemsPlugin} (RuneLite 1.13.4) does, and {@link HiddenLootResolver} turns names into hidden item ids
 * once per list.
 */
public class GroundItemsHiddenTest
{
	private static GroundItemsHidden hidden(String list)
	{
		return GroundItemsHidden.parse(list, "");
	}

	@Test
	public void exactNamesIgnoreCase()
	{
		GroundItemsHidden list = hidden("Bones, Rune platebody");
		assertTrue(list.hides("Bones"));
		assertTrue(list.hides("bones"));
		assertTrue(list.hides("RUNE PLATEBODY"));
		assertFalse("exact means the whole name", list.hides("Big bones"));
		assertFalse(list.hides("Bone"));
		assertFalse("an unknown name is never hidden", list.hides(null));
	}

	@Test
	public void wildcardsUseRuneLitesMatcher()
	{
		GroundItemsHidden list = hidden("*seed, Clue scroll*, *rune*");
		assertTrue(list.hides("Ranarr seed"));
		assertTrue(list.hides("RANARR SEED"));
		assertTrue(list.hides("Clue scroll (hard)"));
		assertTrue(list.hides("Nature rune"));
		assertTrue(list.hides("Rune platebody"));
		assertFalse(list.hides("Seed pod"));
		assertFalse(list.hides("Bones"));
		// Other regex characters are taken literally.
		assertTrue(hidden("Clue scroll (*)").hides("Clue scroll (elite)"));
		assertFalse(hidden("Coins.*").hides("Coinsxx"));
		assertTrue(hidden("Coins.*").hides("Coins.xx"));
	}

	@Test
	public void entriesAreSplitOnCommasAndTrimmed()
	{
		GroundItemsHidden list = hidden("  Vial ,Ashes,, ,  Jug  ,");
		assertTrue(list.hides("Vial"));
		assertTrue(list.hides("Ashes"));
		assertTrue(list.hides("Jug"));
		assertFalse("blank entries match nothing", list.hides(""));
		assertFalse(list.hides(" "));
		assertEquals("the same list however it is spaced", hidden("Vial, Ashes, Jug"), list);
	}

	@Test
	public void anEmptyListHidesNothing()
	{
		assertSame(GroundItemsHidden.NONE, hidden(""));
		assertSame(GroundItemsHidden.NONE, hidden(" , ,"));
		assertTrue(hidden("").isEmpty());
		assertFalse(hidden("").hides("Bones"));
	}

	@Test
	public void aListNeverEditedIsGroundItemsDefault()
	{
		GroundItemsHidden list = GroundItemsHidden.parse(null, null);
		assertEquals(hidden(GroundItemsHidden.DEFAULT_HIDDEN_ITEMS), list);
		for (String name : Arrays.asList("Vial", "Ashes", "Coins", "Bones", "Bucket", "Jug", "Seaweed"))
		{
			assertTrue(name, list.hides(name));
		}
		assertFalse(list.hides("Big bones"));
	}

	@Test
	public void entriesWithAQuantityConditionAreIgnored()
	{
		GroundItemsHidden list = hidden("Coins < 1000, Bones > 5, Ashes > 0, Vial > 1 2");
		assertFalse("only a stack on the ground can be checked against it", list.hides("Coins"));
		assertFalse(list.hides("Bones"));
		assertTrue("> 0 holds for every stack", list.hides("Ashes"));
		// Ground Items reads an unparsable quantity as "> 0".
		assertTrue(list.hides("Vial"));
		// Text after the < or > that is not a number: no condition, it is all name.
		assertTrue(hidden("Vial>abc").hides("vial>ABC"));
		// A trailing number without < or > is part of the name.
		assertTrue(hidden("Rune 2h sword").hides("Rune 2h sword"));
		assertTrue(hidden("Coins <").hides("Coins <"));
		assertSame(GroundItemsHidden.NONE, hidden("Coins < 1000"));
	}

	@Test
	public void theHighlightedListWinsAsInGroundItems()
	{
		// An exact highlight beats any hide.
		assertFalse(GroundItemsHidden.parse("*", "Dragon bones").hides("Dragon bones"));
		assertTrue(GroundItemsHidden.parse("*", "Dragon bones").hides("Bones"));
		assertFalse(GroundItemsHidden.parse("Bones", "bones").hides("Bones"));
		// A wildcard highlight beats a wildcard hide, but not an exact one.
		assertFalse(GroundItemsHidden.parse("*bones", "Dragon*").hides("Dragon bones"));
		assertTrue(GroundItemsHidden.parse("Dragon bones", "Dragon*").hides("Dragon bones"));
		// A highlight with a quantity condition is ignored too.
		assertTrue(GroundItemsHidden.parse("Coins", "Coins > 10000").hides("Coins"));
	}

	@Test
	public void theSettingAndGroundItemsMustBothBeOn()
	{
		assertSame("setting off", GroundItemsHidden.NONE, GroundItemsHidden.effective(false, null, "Bones", ""));
		assertSame("Ground Items off", GroundItemsHidden.NONE,
			GroundItemsHidden.effective(true, "false", "Bones", ""));
		assertTrue("Ground Items on", GroundItemsHidden.effective(true, "true", "Bones", "").hides("Bones"));
		assertTrue("never turned off: on by default", GroundItemsHidden.effective(true, null, "Bones", "")
			.hides("Bones"));
		assertTrue("never edited: the default list", GroundItemsHidden.effective(true, null, null, null)
			.hides("Coins"));
	}

	@Test
	public void equalListsAreEqual()
	{
		assertEquals(hidden("Bones, *seed"), GroundItemsHidden.parse("Bones,*seed", null));
		assertEquals(hidden("Bones, *seed").hashCode(), hidden("Bones,*seed").hashCode());
		assertNotEquals(hidden("Bones"), hidden("Bones, Ashes"));
		assertNotEquals(GroundItemsHidden.parse("Bones", "Ashes"), hidden("Bones"));
	}

	// ---- HiddenLootResolver and HiddenLoot ----

	@Test
	public void theResolverMatchesEachIdOncePerList()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(526, "Bones");
		names.put(1127, "Rune platebody");
		// A noted item's own name is its unnoted item's.
		names.put(527, "Bones");
		List<Integer> asked = new ArrayList<>();
		HiddenLootResolver resolver = new HiddenLootResolver();
		assertSame("nothing to hide: no names asked", HiddenLoot.NONE,
			resolver.resolve(Arrays.asList(526, 1127), id ->
			{
				asked.add(id);
				return names.get(id);
			}));
		assertTrue(asked.isEmpty());

		assertTrue(resolver.setList(hidden("Bones")));
		assertFalse("the same list again", resolver.setList(hidden("Bones")));
		HiddenLoot result = resolver.resolve(Arrays.asList(526, 527, 1127), id ->
		{
			asked.add(id);
			return names.get(id);
		});
		assertEquals("the note too, not the platebody", HiddenLoot.of(Arrays.asList(526, 527)), result);
		assertEquals(Arrays.asList(526, 527, 1127), asked);

		// Matched once: asked again, no name is looked up.
		resolver.resolve(Arrays.asList(526, 527, 1127), id ->
		{
			asked.add(id);
			return names.get(id);
		});
		assertEquals(3, asked.size());

		// Another list matches afresh.
		assertTrue(resolver.setList(hidden("Rune*")));
		assertEquals(HiddenLoot.of(Collections.singleton(1127)), resolver.resolve(Arrays.asList(526, 1127),
			names::get));
	}

	@Test
	public void anUnknownNameIsNotHiddenUntilItIsKnown()
	{
		Map<Integer, String> names = new HashMap<>();
		HiddenLootResolver resolver = new HiddenLootResolver();
		resolver.setList(hidden("Bones"));
		assertSame(HiddenLoot.NONE, resolver.resolve(Collections.singleton(526), names::get));
		assertSame("a failed lookup is unknown", HiddenLoot.NONE, resolver.resolve(Collections.singleton(526), id ->
		{
			throw new IllegalStateException("no item data");
		}));
		names.put(526, "Bones");
		assertEquals(HiddenLoot.of(Collections.singleton(526)), resolver.resolve(Collections.singleton(526),
			names::get));
	}

	@Test
	public void hiddenLootLeavesItemsOutWithoutChangingTheTally()
	{
		ItemTally loot = new ItemTally();
		loot.add(526, 3);
		loot.add(1127, 1);
		HiddenLoot hidden = HiddenLoot.of(Arrays.asList(526, null));
		ItemTally valued = hidden.valued(loot);
		assertEquals(0, valued.get(526));
		assertEquals(1, valued.get(1127));
		assertEquals("the tally itself is unchanged", 3, loot.get(526));
		assertSame("nothing hidden: the same tally", loot, HiddenLoot.of(Collections.singleton(4151)).valued(loot));
		assertSame(HiddenLoot.NONE, HiddenLoot.of(Collections.emptyList()));
		assertTrue(hidden.leavesOutAny(Arrays.asList(1, 526)));
		assertFalse(hidden.leavesOutAny(Collections.singleton(1)));
	}

	@Test
	public void hiddenCoinsLeaveTheGridButKeepTheirValue()
	{
		ItemTally loot = new ItemTally();
		loot.add(ItemValuation.COINS, 5_000);
		loot.add(526, 3);
		loot.add(1127, 1);
		HiddenLoot coinsAndBones = HiddenLoot.of(Arrays.asList(ItemValuation.COINS, 526));

		ItemTally valued = coinsAndBones.valued(loot);
		assertEquals("coins always count in the value", 5_000, valued.get(ItemValuation.COINS));
		assertEquals("bones are left out", 0, valued.get(526));
		assertEquals(1, valued.get(1127));
		assertFalse(coinsAndBones.isEmpty());

		HiddenLoot coinsOnly = HiddenLoot.of(Collections.singleton(ItemValuation.COINS));
		assertFalse(coinsOnly.isEmpty());
		assertFalse(coinsOnly.leavesOutAny(loot.itemIds()));
		assertSame("hidden coins alone leave nothing out of the value", loot, coinsOnly.valued(loot));

		List<ItemDetails.Row> rows = Arrays.asList(
			ItemDetails.Row.builder().itemId(1127).name("Rune platebody").quantity(1).build(),
			ItemDetails.Row.builder().itemId(526).name("Bones").quantity(3).build(),
			ItemDetails.Row.builder().itemId(ItemValuation.COINS).name("Coins").quantity(5_000).build());
		List<ItemDetails.Row> shown = coinsAndBones.visibleRows(rows);
		assertEquals("coins are hidden from the grid like any item", 1, shown.size());
		assertEquals(1127, shown.get(0).getItemId());
		assertEquals(2, coinsOnly.visibleRows(rows).size());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.events.ConfigChanged;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Ignored loot, multi-bite food and deaths as wired in the plugin ({@link PluginHarness}): the ignored-items setting is
 * read at startUp and on ConfigChanged and applied when loot arrives, with item names read on the client thread;
 * pizzas are counted in bites from the inventory each tick; and local-player deaths count while RUNNING and survive
 * logout and a restart. {@link IgnoredLootTest}, {@link LootFilterTest}, {@link MultiBiteFoodTest} and
 * {@link SessionTrackerCountersTest} cover the rules.
 */
public class HarnessAccuracyTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String EAT = "Eat";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1, "Bury");
		harness.defineItem(ItemID.COINS, "Coins", 1, 1);
		harness.defineItem(ItemID.RANARR_SEED, "Ranarr seed", 40_000, 20);
		harness.defineItem(ItemID.DRAGON_BONES, "Dragon bones", 2_000, 1, "Bury");
		harness.defineNotedItem(ItemID.Cert.DRAGON_BONES, ItemID.DRAGON_BONES);
		harness.defineItem(ItemID.PLAIN_PIZZA, "Plain pizza", 300, 10, EAT);
		harness.defineItem(ItemID.HALF_PLAIN_PIZZA, "1/2 plain pizza", 200, 5, EAT);
		harness.defineItem(ItemID.MEAT_PIE, "Meat pie", 100, 6, EAT);
		harness.defineItem(ItemID.HALF_A_MEAT_PIE, "Half a meat pie", 60, 3, EAT);
		harness.defineItem(ItemID.PIEDISH, "Pie dish", 10, 1);
	}

	private void startRunning(String ignoredLoot)
	{
		harness.config.ignoredLoot = ignoredLoot;
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
	}

	private void killDrops()
	{
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.lootOnNextTick(ItemID.COINS, 100);
		harness.lootOnNextTick(ItemID.RANARR_SEED, 1);
		harness.lootOnNextTick(ItemID.Cert.DRAGON_BONES, 3);
		harness.tick();
	}

	private ItemTally loot()
	{
		return harness.tracker().getLoot();
	}

	// ---- Ignored loot ----

	@Test
	public void theSettingAtStartUpIsApplied()
	{
		startRunning("bones, *SEED");
		killDrops();
		assertEquals(0, loot().get(ItemID.BONES));
		assertEquals(0, loot().get(ItemID.RANARR_SEED));
		assertEquals(100, loot().get(ItemID.COINS));
		assertEquals("Dragon bones is not matched by 'bones'", 3, loot().get(ItemID.Cert.DRAGON_BONES));
	}

	@Test
	public void aChangedSettingAppliesToNewLootOnly()
	{
		startRunning("");
		killDrops();
		assertEquals(1, loot().get(ItemID.BONES));

		harness.setIgnoredLoot("Bones, Dragon bones, " + ItemID.COINS);
		assertEquals("loot already counted is kept", 1, loot().get(ItemID.BONES));
		killDrops();
		assertEquals(1, loot().get(ItemID.BONES));
		assertEquals(100, loot().get(ItemID.COINS));
		assertEquals("a noted drop matches its unnoted name", 3, loot().get(ItemID.Cert.DRAGON_BONES));
		assertEquals(2, loot().get(ItemID.RANARR_SEED));

		harness.setIgnoredLoot("");
		killDrops();
		assertEquals(2, loot().get(ItemID.BONES));

		harness.endTask();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(2), record.getLoot().get(ItemID.BONES));
		assertEquals(Long.valueOf(6), record.getLoot().get(ItemID.Cert.DRAGON_BONES));
	}

	@Test
	public void otherSettingsChangesDoNotReparse()
	{
		startRunning("coins");
		// The value changes without a ConfigChanged for its key: the cached list is still used.
		harness.config.ignoredLoot = "";
		harness.post(configChanged(SlayerLedgerConfig.GROUP, "bonecrusherHandling"));
		harness.post(configChanged("lootTracker", SlayerLedgerConfig.IGNORED_LOOT));
		killDrops();
		assertEquals(0, loot().get(ItemID.COINS));
	}

	@Test
	public void ignoredLootByIdMatchesTheNotedDrop()
	{
		startRunning(Integer.toString(ItemID.DRAGON_BONES));
		killDrops();
		assertEquals(0, loot().get(ItemID.Cert.DRAGON_BONES));
		assertEquals(1, loot().get(ItemID.BONES));
	}

	private static ConfigChanged configChanged(String group, String key)
	{
		ConfigChanged event = new ConfigChanged();
		event.setGroup(group);
		event.setKey(key);
		return event;
	}

	// ---- Multi-bite food ----

	@Test
	public void eatingAWholePizzaCostsOnePizza()
	{
		startRunning("");
		harness.setInventory(PluginHarness.item(ItemID.PLAIN_PIZZA, 1));
		harness.tick();
		harness.setInventory(PluginHarness.item(ItemID.HALF_PLAIN_PIZZA, 1));
		harness.tick();
		harness.setInventory();
		harness.tick();

		ItemTally used = harness.tracker().getSupplies();
		assertEquals(2, used.get(ItemID.PLAIN_PIZZA));
		assertEquals(0, used.get(ItemID.HALF_PLAIN_PIZZA));
		harness.endTask();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(2), record.getSupplies().get(ItemID.PLAIN_PIZZA));
		assertEquals(Integer.valueOf(2), record.getSupplyDoses().get(ItemID.PLAIN_PIZZA));
		assertEquals("exactly one pizza", Long.valueOf(300), record.getSuppliesGeValue());
	}

	@Test
	public void aHalfPieInTheInventoryAtPlayCostsHalf()
	{
		harness.config.ignoredLoot = "";
		harness.startUp();
		harness.setInventory(PluginHarness.item(ItemID.HALF_A_MEAT_PIE, 1));
		harness.setTask(TASK, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.setInventory(PluginHarness.item(ItemID.PIEDISH, 1));
		harness.tick();

		harness.endTask();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(1), record.getSupplies().get(ItemID.MEAT_PIE));
		assertNull("the dish is not a supply", record.getSupplies().get(ItemID.PIEDISH));
		assertEquals("half of the 100 gp pie", Long.valueOf(50), record.getSuppliesGeValue());
	}

	// ---- Deaths ----

	@Test
	public void localPlayerDeathsCountOnlyWhileRunning()
	{
		startRunning("");
		harness.localPlayerDies();
		harness.otherActorDies();
		assertEquals(1, harness.tracker().getDeaths());
		harness.pause();
		harness.localPlayerDies();
		assertEquals("not while paused", 1, harness.tracker().getDeaths());
		assertTrue(harness.startNow());
		harness.localPlayerDies();
		assertEquals("Superiors: 0 | Deaths: 2 | Bank trips: 0", countsText());
		harness.endTask();
		assertEquals(Integer.valueOf(2), harness.onlyRecord(ACCOUNT).getDeaths());
	}

	@Test
	public void deathsSurviveLogoutAndARestart()
	{
		startRunning("");
		harness.localPlayerDies();
		harness.logout();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertNotNull(snapshot);
		assertEquals(Integer.valueOf(1), snapshot.getDeaths());
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertEquals(1, harness.tracker().getDeaths());
		assertTrue(harness.startNow());
		harness.localPlayerDies();
		harness.endTask();
		assertEquals(Integer.valueOf(2), harness.onlyRecord(ACCOUNT).getDeaths());
	}

	@Test
	public void deathDuringTheCompletionGraceWindowIsNotAdded()
	{
		startRunning("");
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.localPlayerDies();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(Integer.valueOf(0), harness.onlyRecord(ACCOUNT).getDeaths());
	}

	private String countsText()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getCountsText();
		});
		return text[0];
	}
}

package com.shmayvan.slayerledger;

