			records.add(task(TASK, "region:" + unlisted, true, SetupStyle.MELEE, GearFocus.UNKNOWN, 20, 1_000L, 10_000L,
				CANNON_SUPPLIES));
		}
		start(records);
		String title = card(PanelProbe.AdvisorCardProbe::getTitle);
		assertTrue(title, title.contains("Abyssal demons"));
		int builds = card(PanelProbe.AdvisorCardProbe::getBuildCount);

		// The count reads 0 for a tick, and meanwhile that region gets its name: the card is rebuilt from its kept plan,
		// with the plan's task name, not the tracker's "no task".
		harness.setRemaining(0);
		harness.tick();
		assertFalse(refreshed(PanelProbe.AdvisorCardProbe::isShown));
		harness.onEdt(() -> harness.historyModel().addLocationNames(Collections.singleton(unlisted),
			Collections.singletonMap(unlisted, "My spot")));
		assertTrue("rebuilt for the new spot name", card(PanelProbe.AdvisorCardProbe::getBuildCount) > builds);

		// The task is read again: the card the gap built shows, naming the task and the region's new name.
		harness.setRemaining(20);
		harness.tick();
		assertTrue(refreshed(PanelProbe.AdvisorCardProbe::isShown));
		assertEquals("still the task's name", title, card(PanelProbe.AdvisorCardProbe::getTitle));
		assertTrue(card(probe -> probe.getBlock("recommendation")).get(0).contains("My spot"));
	}

	@Test
	public void aReloginToTheSameTaskShowsTheCardAgain()
	{
		start(history());
		assertTrue(card(PanelProbe.AdvisorCardProbe::isShown));
		List<String> recommendation = card(probe -> probe.getBlock("recommendation"));

		// Logging out clears the history; logging back in to the same account, task and place (no kill in between)
		// loads it again, and the first settled tick tells the model the task, which asks for the plan.
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		assertTrue("shown again after the relog", card(PanelProbe.AdvisorCardProbe::isShown));
		assertEquals("the same plan", recommendation, card(probe -> probe.getBlock("recommendation")));
	}

	@Test
	public void anotherKonarAreasPlanIsNeverShown()
	{
		harness.setAssignment(SlayerMaster.KONAR, KONAR_AREA + 1, "Catacombs of Kourend");
		start(history());
		assertEquals("Barrage, Catacombs | 3 tasks", card(probe -> probe.getBlock("recommendation")).get(0));

		// The same creature in another area, same kills left: the tick is read and the new plan asked for, but not
		// worked out yet (the executor hasn't run). The Catacombs plan is not this assignment's.
		harness.setAssignment(SlayerMaster.KONAR, KONAR_AREA, "Slayer Tower");
		harness.tickWithoutDrain();
		harness.flushEdt();
		assertFalse("hidden until this area's plan is ready", refreshed(PanelProbe.AdvisorCardProbe::isShown));

		harness.drain();
		assertTrue(card(PanelProbe.AdvisorCardProbe::isShown));
		assertEquals("No completed tasks in " + TaskPlanText.shortSpotName(TestSpots.TOWER_ID, TestSpots.TABLE, null)
			+ " yet, so all areas are used.", card(PanelProbe.AdvisorCardProbe::getAreaNote));
		assertEquals("Cannon, melee, Smoke Dungeon | 3 tasks", card(probe -> probe.getBlock("recommendation")).get(0));
	}

	/** A panel refresh after the model's changes built the card finds nothing to change: nothing is rebuilt. */
	private void assertRefreshBuildsNothing()
	{
		int builds = card(PanelProbe.AdvisorCardProbe::getBuildCount);
		boolean shown = card(PanelProbe.AdvisorCardProbe::isShown);
		assertEquals(shown, refreshed(PanelProbe.AdvisorCardProbe::isShown));
		assertEquals(builds, (int) card(PanelProbe.AdvisorCardProbe::getBuildCount));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Rule;
import org.junit.Test;

/**
 * The advisor's plan as wired in the plugin ({@link PluginHarness}): worked out off the EDT for the current task
 * when the task, its kills left or the records change, kept only for the latest inputs (the plan shown stays through a
 * kill until the new one is back), never worked out on the panel's refresh timer, and for Konar's and Krystilia's
 * tasks from the history where their kills count. {@link TaskPlannerTest} covers the plan itself.
 */
public class HarnessAdvisorPlanTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final long MINUTE = 60_000L;
	private static final int DEMONS = 42;
	/** Nieve's SLAYER_MASTER value: a regular master. */
	private static final int NIEVE = 6;
	/** A SLAYER_AREA value for Konar's assigned area, which the harness names. */
	private static final int KONAR_AREA = 7;
	/** Numbers the records' ids: the store skips a duplicate id, so they must never repeat. */
	private static final AtomicInteger IDS = new AtomicInteger();

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/**
	 * A completed Abyssal demons task of 10 kills at {@code spotId} with melee: with a cannon, 30 minutes for 30K of
	 * coins and 30K Slayer XP; without, 60 minutes for 300K and 1K Slayer XP.
	 */
	private static LedgerRecord demons(String spotId, boolean cannon)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId("demons-" + IDS.incrementAndGet());
		record.setCreatureId(DEMONS);
		record.setMonster("Abyssal demons");
		record.setKills(10);
		record.setInitialAmount(10);
		record.setOriginalAmount(10);
		record.setActiveMillis((cannon ? 30 : 60) * MINUTE);
		record.setCompleted(true);
		record.setLootGeValue(cannon ? 30_000L : 300_000L);
		record.setLootHaValue(0L);
		record.setSuppliesGeValue(0L);
		record.setXpGained(Collections.singletonMap(SkillXp.SLAYER, cannon ? 30_000L : 1_000L));
		record.setSpotId(spotId);
		SetupTags.detected(cannon, SetupStyle.MELEE, GearFocus.UNKNOWN, SetupOverrides.NONE).copyTo(record);
		return SavedItems.withItems(record);
	}

	/** Three tasks of each {@link #demons} setup at the Smoke Dungeon. */
	private static List<LedgerRecord> smokeDungeon()
	{
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			records.add(demons(TestSpots.SMOKE_ID, false));
			records.add(demons(TestSpots.SMOKE_ID, true));
		}
		return records;
	}


	/** Starts the plugin on a 20-kill Abyssal demons task and shows {@code records}. */
	private void start(List<LedgerRecord> records)
	{
		harness.startUp();
		harness.setInventory();
		harness.setTask(DEMONS, "Abyssal demons", 20, 20);
		harness.loginAndSettle(ACCOUNT);
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, records));
		harness.drain();
	}

	/** The model's plan to show now, without draining anything first. */
	private TaskPlan plan()
	{
		AtomicReference<TaskPlan> plan = new AtomicReference<>();
		harness.onEdt(() -> plan.set(harness.historyModel().plan()));
		return plan.get();
	}


	private int planBuilds()
	{
		AtomicInteger builds = new AtomicInteger();
		harness.onEdt(() -> builds.set(harness.historyModel().getPlanBuildCount()));
		return builds.get();
	}


	@Test
	public void thePlanShownStaysThroughAKillAndAnOlderOneIsDropped()
	{
		start(smokeDungeon());
		TaskPlan first = plan();
		assertNotNull(first);
		assertEquals(20, first.getKillsLeft());
		int builds = planBuilds();

		// A kill: the settled tick asks for the plan for 19 kills left, which waits for the executor. Meanwhile the
		// plan for 20 is still shown, so the card doesn't blank once a kill.
		harness.setRemaining(19);
		harness.tickWithoutDrain();
		harness.runClientThread();
		harness.flushEdt();
		assertSame("the kept plan is shown", first, plan());
		assertEquals(builds + 1, planBuilds());

		// Another kill before it is back: its plan is dropped when it arrives, and the plan for 18 is kept.
		harness.setRemaining(18);
		harness.tickWithoutDrain();
		harness.runClientThread();
		harness.flushEdt();
		assertEquals(builds + 2, planBuilds());
		assertSame(first, plan());
		harness.runExecutor();
		harness.flushEdt();
		TaskPlan latest = plan();
		assertEquals(18, latest.getKillsLeft());
		harness.drain();
		assertEquals("nothing more worked out", builds + 2, planBuilds());
		assertEquals(18, plan().getKillsLeft());
	}

	@Test
	public void theFastestSetupIsRecommended()
	{
		start(smokeDungeon());

		// The cannon tasks, at 3 minutes a kill against 6: always the least time for the kills left.
		TaskPlan plan = plan();
		assertTrue(plan.getRecommendation().isCannon());
		assertEquals("both setups are options", 2, plan.getOptions().size());
		assertFalse(plan.getOptions().get(1).isCannon());
	}

	@Test
	public void nothingIsWorkedOutOnThePanelRefreshTimer()
	{
		start(smokeDungeon());
		assertNotNull(plan());
		int builds = planBuilds();

		// The refresh timer and ticks with nothing changed work nothing out.
		for (int i = 0; i < 5; i++)
		{
			harness.onEdt(() -> harness.panel().refresh());
		}
		harness.ticks(5);
		assertEquals(builds, planBuilds());
		assertNotNull(plan());

		// With the panel shut (as with the sidebar closed for good), a kill still brings the new plan.
		harness.onEdt(() -> harness.panel().shutDown());
		harness.setRemaining(19);
		harness.tick();
		assertEquals(19, plan().getKillsLeft());
		assertEquals(builds + 1, planBuilds());
	}

	@Test
	public void aKonarTaskUsesTheOptionsAtItsAssignedArea()
	{
		List<LedgerRecord> records = smokeDungeon();
		// One slower barrage task in the Catacombs, where Konar sends the player.
		LedgerRecord catacombs = demons(TestSpots.CATACOMBS_ID, false);
		catacombs.setActiveMillis(90 * MINUTE);
		catacombs.setDetectedStyle(SetupStyle.BARRAGE);
		records.add(catacombs);
		harness.setAssignment(SlayerMaster.KONAR, KONAR_AREA, "Catacombs of Kourend");
		start(records);

		TaskPlan plan = plan();
		assertEquals(TestSpots.CATACOMBS_ID, plan.getAreaSpot());
		assertFalse(plan.isAreaFallback());
		assertEquals("only the option there", 1, plan.getOptions().size());
		assertEquals(TestSpots.CATACOMBS_ID, plan.getRecommendation().getSpot());
		assertEquals(SetupStyle.BARRAGE, plan.getRecommendation().getStyle());
		assertTrue("one task", plan.isRecommendationThin());
		assertEquals("All setups keeps every task", 7, plan.getAllSetups().getTasks());

		// Another master's task of the same creature: every option.
		harness.setAssignment(NIEVE, 0, null);
		harness.tick();
		assertNull(plan().getAreaSpot());
		assertEquals(TestSpots.SMOKE_ID, plan().getRecommendation().getSpot());
	}

	@Test
	public void aWildernessTaskUsesOnlyWildernessHistory()
	{
		List<LedgerRecord> records = smokeDungeon();
		for (LedgerRecord record : records)
		{
			record.setSlayerMaster(NIEVE);
		}
		// Two of Krystilia's tasks, in the Slayer Tower for the test's sake.
		for (int i = 0; i < 2; i++)
		{
			LedgerRecord wilderness = demons(TestSpots.TOWER_ID, false);
			wilderness.setSlayerMaster(SlayerMaster.KRYSTILIA);
			records.add(wilderness);
		}
		harness.setAssignment(SlayerMaster.KRYSTILIA, 0, null);
		start(records);

		TaskPlan plan = plan();
		assertEquals("only the Wilderness tasks", 2, plan.getAllSetups().getTasks());
		assertEquals(TestSpots.TOWER_ID, plan.getRecommendation().getSpot());

		// The master's varbit says Nieve now: every task of the creature.
		harness.setAssignment(NIEVE, 0, null);
		harness.tick();
		assertEquals(8, plan().getAllSetups().getTasks());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;
import static org.mockito.Mockito.withSettings;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.game.ItemStack;
import net.runelite.client.events.ServerNpcLoot;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Araxxor's harvest after its task-completing kill as wired in the plugin ({@link PluginHarness}). Araxxor drops
 * its loot only when the player harvests its corpse, which can come after the task was saved (2 ticks after the count
 * reached 0). A harvest within 5 minutes of that final kill is added to the saved record, once: its loot, its values
 * and its notable drop, which the History row and its item details then show, with Ground Items' hidden items left out
 * of the value as for any loot; if that can't be written, the History says so. A harvest the game reports on the save's
 * tick goes with the save. Araxxor loot is not added after 5 minutes, after a logout, a hop or an account switch,
 * after a final kill that wasn't Araxxor's, or once the harvest came before the save (also before the completion was
 * held, or with every item ignored). {@link AraxxorHarvestTest} covers the rules.
 */
public class HarnessAraxxorHarvestTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int ARAXYTES = 105;
	private static final long MINUTE = 60_000L;
	private static final int COINS = ItemID.COINS;
	/** Ticks between two kills: more than a kill's pairing window, so each kill pairs only its own NPC's death. */
	private static final int FIGHT_TICKS = 5;
	/** {@link #historyShown} for the saved task before its harvest: the araxyte's 1,000 coins. */
	private static final List<String> BEFORE_HARVEST = Arrays.asList("+1,000",
		"Loot: 1,000 gp GE, 1,000 gp high alch", "Loot received | 1,000 [Coins | " + COINS + " x1000]");

	@Rule
	public final PluginHarness harness = new PluginHarness();

	private final AtomicLong now = new AtomicLong(1_000_000_000L);
	private int nextIndex = 1;

	@Before
	public void setUp()
	{
		harness.defineItem(COINS, "Coins", 1, 1);
		harness.defineItem(ItemID.RUNE_PLATEBODY, "Rune platebody", 38_000, 39_000);
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.setGroundItemsHidden("Bones");
		harness.startUp();
		harness.setTrackerClock(now::get);
		harness.setNotableDropThreshold(30_000);
		harness.setTask(ARAXYTES, "Araxytes", 2, 2);
		harness.loginAndSettle(ACCOUNT);
	}

	private <T> T onEdt(Supplier<T> read)
	{
		final AtomicReference<T> value = new AtomicReference<>();
		harness.onEdt(() -> value.set(read.get()));
		return value.get();
	}

	/** The player hits {@code name} and it dies; nothing else happens until the next tick. */
	private void hitAndKill(int id, String name)
	{
		final NPC npc = harness.npc(nextIndex++, id, name);
		harness.hitsplat(npc, true);
		harness.npcDies(npc);
	}

	/**
	 * The task: an araxyte kill that drops 1,000 coins, then the final kill of {@code finalId} named {@code finalName},
	 * which completes it; the task is saved 2 ticks later.
	 */
	private void completeTask(int finalId, String finalName)
	{
		playToTheFinalKill(finalId, finalName);
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 1);
		harness.drain();
		final LedgerRecord saved = harness.onlyRecord(ACCOUNT);
		assertTrue(saved.isCompleted());
		assertEquals(Collections.singletonMap(COINS, 1_000L), saved.getLoot());
	}

	/**
	 * The task up to its final kill: an araxyte kill that drops 1,000 coins, a fight later the death of {@code finalId}
	 * named {@code finalName}, and a minute; the task count is not read yet.
	 */
	private void playToTheFinalKill(int finalId, String finalName)
	{
		hitAndKill(NpcID.ARAXYTE_NORMAL, "Araxyte");
		now.addAndGet(MINUTE);
		harness.setRemaining(1);
		harness.tick();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		harness.postLoot("Araxyte", COINS, 1_000);
		// A fight later, so the araxyte's death is not paired with the final kill.
		harness.ticks(FIGHT_TICKS);

		hitAndKill(finalId, finalName);
		now.addAndGet(MINUTE);
	}

	/** Araxxor's harvest arrives, as the game's loot tracker reports it: one loot event from Araxxor. */
	private void harvest(ItemStack... stacks)
	{
		final NPCComposition araxxor = mock(NPCComposition.class, withSettings().stubOnly());
		when(araxxor.getName()).thenReturn("Araxxor");
		harness.post(new ServerNpcLoot(araxxor, Arrays.asList(stacks)));
		harness.drain();
	}

	private void harvest()
	{
		harvest(new ItemStack(ItemID.RUNE_PLATEBODY, 1), new ItemStack(ItemID.BONES, 3), new ItemStack(COINS, 5_000));
	}

	/**
	 * As the player sees the History row: its profit, the loot line of its tooltip, and its item details' loot
	 * grid (opened), whose sub-header shows the loot value.
	 */
	private List<String> historyShown()
	{
		harness.drain();
		return onEdt(() ->
		{
			final PanelProbe.HistoryListProbe history = harness.ui().getHistory();
			if (history.getDetailsText(0) == null)
			{
				history.clickRow(0);
			}
			final PanelProbe.ItemGridProbe grid = history.getDetailsGrid(0, "Loot received");
			return Arrays.asList(history.getValuesText().get(0).split(" \\| ")[0],
				lootLine(history.getTooltips().get(0)), grid.getHeaderText() + " " + grid.getCellTexts());
		});
	}

	/** The {@code Loot: ...} line of a row tooltip, or the whole tooltip when it has none. */
	private static String lootLine(String tooltip)
	{
		for (String line : tooltip.split("<br>"))
		{
			if (line.startsWith("Loot: "))
			{
				return line;
			}
		}
		return tooltip;
	}

	@Test
	public void aHarvestAMinuteAfterTheFinalKillLandsInTheSavedRecordOnce()
	{
		completeTask(NpcID.ARAXXOR, "Araxxor");
		assertEquals(BEFORE_HARVEST, historyShown());

		now.addAndGet(MINUTE);
		harvest();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		final Map<Integer, Long> loot = new TreeMap<>();
		loot.put(COINS, 6_000L);
		loot.put(ItemID.RUNE_PLATEBODY, 1L);
		loot.put(ItemID.BONES, 3L);
		assertEquals(loot, record.getLoot());
		assertEquals(Long.valueOf(6_000 + 38_000 + 300), record.getLootGeValue());
		assertEquals(Long.valueOf(6_000 + 39_000 + 3), record.getLootHaValue());
		assertEquals(Long.valueOf(38_000), record.getUnitGePrices().get(ItemID.RUNE_PLATEBODY));
		assertEquals(Long.valueOf(39_000), record.getUnitHaPrices().get(ItemID.RUNE_PLATEBODY));
		assertNull(record.getLootUnpricedItems());
		assertEquals(1, record.getNotableDrops().size());
		assertEquals("Rune platebody", record.getNotableDrops().get(0).getName());
		assertEquals(Long.valueOf(38_000), record.getNotableDrops().get(0).getGeValue());
		assertTrue("still completed", record.isCompleted());

		// The History row and its details follow, at today's prices, with the hidden bones left out of the value.
		assertEquals(Arrays.asList("+44K", "Loot: 44,000 gp GE, 45,000 gp high alch", "Loot received (1 hidden) | 44K "
			+ "[Rune platebody | " + ItemID.RUNE_PLATEBODY + ", Coins | " + COINS + " x6000]"), historyShown());
		final String tooltip = onEdt(() -> harness.ui().getHistory().getTooltips().get(0));
		assertTrue(tooltip, tooltip.contains("Rune platebody"));

		// Once per harvest: more Araxxor loot is not this task's.
		now.addAndGet(MINUTE);
		harvest(new ItemStack(ItemID.RUNE_PLATEBODY, 1));
		assertEquals(loot, harness.onlyRecord(ACCOUNT).getLoot());
	}

	@Test
	public void aHarvestAfterFiveMinutesIsNotAdded()
	{
		completeTask(NpcID.ARAXXOR, "Araxxor");
		// The final kill's time is the completion tick's: 5 minutes and a moment after it.
		now.addAndGet(SessionTracker.ARAXXOR_LOOT_MILLIS + 1);
		harvest();
		assertEquals(Collections.singletonMap(COINS, 1_000L), harness.onlyRecord(ACCOUNT).getLoot());
		assertEquals(BEFORE_HARVEST, historyShown());
	}

	@Test
	public void aHarvestWithNoAraxxorFinalKillIsNotAdded()
	{
		// Araxxor died earlier in the task, not at its final kill.
		hitAndKill(NpcID.ARAXXOR, "Araxxor");
		now.addAndGet(MINUTE);
		harness.setRemaining(1);
		harness.tick();
		harness.ticks(FIGHT_TICKS);
		hitAndKill(NpcID.ARAXYTE_NORMAL, "Araxyte");
		now.addAndGet(MINUTE);
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 1);
		harness.drain();
		final LedgerRecord saved = harness.onlyRecord(ACCOUNT);
		assertNull(saved.getLoot());

		now.addAndGet(MINUTE);
		harvest();
		assertNull(harness.onlyRecord(ACCOUNT).getLoot());
	}

	@Test
	public void aLogoutEndsTheWindow()
	{
		completeTask(NpcID.ARAXXOR, "Araxxor");
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		now.addAndGet(MINUTE);
		harvest();
		assertEquals(Collections.singletonMap(COINS, 1_000L), harness.onlyRecord(ACCOUNT).getLoot());
	}

	@Test
	public void aHopEndsTheWindow()
	{
		completeTask(NpcID.ARAXXOR, "Araxxor");
		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		now.addAndGet(MINUTE);
		harvest();
		assertEquals(Collections.singletonMap(COINS, 1_000L), harness.onlyRecord(ACCOUNT).getLoot());
	}

	@Test
	public void anAccountSwitchEndsTheWindow()
	{
		completeTask(NpcID.ARAXXOR, "Araxxor");
		// Another account seen on a tick, then this one again: the harvest comes for the task's own account.
		harness.setAccountHash(PluginHarness.OTHER_ACCOUNT);
		harness.tick();
		harness.setAccountHash(ACCOUNT);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		now.addAndGet(MINUTE);
		harvest();
		assertEquals(Collections.singletonMap(COINS, 1_000L), harness.onlyRecord(ACCOUNT).getLoot());
	}

	@Test
	public void aFailedWriteShowsTheMessage() throws IOException
	{
		completeTask(NpcID.ARAXXOR, "Araxxor");
		// A newer version rewrote the ledger meanwhile: it is never overwritten, so the harvest can't be added.
		final String id = harness.onlyRecord(ACCOUNT).getId();
		final File ledger = new File(harness.ledgerDirectory(), ACCOUNT + ".json");
		final String newer = "{\"schemaVersion\":" + (LedgerStore.FILE_SCHEMA_VERSION + 1) + ",\"records\":[{\"id\":\""
			+ id + "\",\"monster\":\"Araxytes\",\"kills\":2,\"completed\":true}]}";
		Files.write(ledger.toPath(), newer.getBytes(StandardCharsets.UTF_8));

		now.addAndGet(MINUTE);
		harvest();
		assertEquals("<html>" + SlayerLedgerPanel.HARVEST_FAILED_MESSAGE + "</html>",
			onEdt(() -> harness.ui().getHistory().getErrorText()));
		assertEquals(newer, new String(Files.readAllBytes(ledger.toPath()), StandardCharsets.UTF_8));
	}

	/**
	 * Araxxor's harvest reported by the game on the tick the held task is released for saving: the loot tracker's
	 * {@code ServerNpcLoot} comes before the release (the plugin's grace ticker runs after LootManager), so the held
	 * task takes it and is saved with it, once.
	 */
	@Test
	public void aHarvestOnTheReleaseTickIsSavedWithTheTaskOnce()
	{
		playToTheFinalKill(NpcID.ARAXXOR, "Araxxor");
		harness.completeTask();
		harness.tick();
		assertTrue("held", harness.tracker().hasPendingCompletion());
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS - 1);
		assertTrue("still held", harness.tracker().hasPendingCompletion());
		assertTrue(harness.records(ACCOUNT).isEmpty());

		harness.lootOnNextTick(NpcID.ARAXXOR, "Araxxor", ItemID.RUNE_PLATEBODY, 1);
		harness.tick();
		assertFalse("released", harness.tracker().hasPendingCompletion());
		final Map<Integer, Long> loot = new TreeMap<>();
		loot.put(COINS, 1_000L);
		loot.put(ItemID.RUNE_PLATEBODY, 1L);
		assertEquals(loot, harness.onlyRecord(ACCOUNT).getLoot());
		assertEquals(Long.valueOf(1_000 + 38_000), harness.onlyRecord(ACCOUNT).getLootGeValue());

		// Its harvest is in: more Araxxor loot is not this task's.
		now.addAndGet(MINUTE);
		harvest();
		assertEquals(loot, harness.onlyRecord(ACCOUNT).getLoot());
	}

	/** Araxxor's harvest reported by the game on the tick after the save: it is added to the saved task. */
	@Test
	public void aHarvestOnTheTickAfterTheSaveIsAddedThroughTheGamesLootPath()
	{
		completeTask(NpcID.ARAXXOR, "Araxxor");
		now.addAndGet(MINUTE);
		harness.lootOnNextTick(NpcID.ARAXXOR, "Araxxor", ItemID.RUNE_PLATEBODY, 1);
		harness.tick();
		harness.drain();
		final Map<Integer, Long> loot = new TreeMap<>();
		loot.put(COINS, 1_000L);
		loot.put(ItemID.RUNE_PLATEBODY, 1L);
		assertEquals(loot, harness.onlyRecord(ACCOUNT).getLoot());
	}

	/**
	 * The count reads 0 a tick before the completion confirms it, and the harvest comes in between, while the
	 * session still runs. The task is saved with it, so no harvest window opens after the save.
	 */
	@Test
	public void aHarvestBeforeTheCompletionIsHeldOpensNoWindow()
	{
		playToTheFinalKill(NpcID.ARAXXOR, "Araxxor");
		harness.setRemaining(0);
		harness.tick();
		assertFalse("not completed yet", harness.tracker().hasPendingCompletion());
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		harvest(new ItemStack(ItemID.RUNE_PLATEBODY, 1));
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 1);
		final Map<Integer, Long> loot = new TreeMap<>();
		loot.put(COINS, 1_000L);
		loot.put(ItemID.RUNE_PLATEBODY, 1L);
		assertEquals(loot, harness.onlyRecord(ACCOUNT).getLoot());

		now.addAndGet(MINUTE);
		harvest();
		assertEquals("another Araxxor's loot is not this task's", loot, harness.onlyRecord(ACCOUNT).getLoot());
	}

	/** A harvest whose items are all ignored (or crushed) is still the harvest, so no harvest window opens. */
	@Test
	public void aHarvestWithEveryItemIgnoredOpensNoWindow()
	{
		playToTheFinalKill(NpcID.ARAXXOR, "Araxxor");
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.setIgnoredLoot("Bones");
		harvest(new ItemStack(ItemID.BONES, 3));
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 1);
		assertEquals(Collections.singletonMap(COINS, 1_000L), harness.onlyRecord(ACCOUNT).getLoot());

		harness.setIgnoredLoot("");
		now.addAndGet(MINUTE);
		harvest();
		assertEquals("another Araxxor's loot is not this task's", Collections.singletonMap(COINS, 1_000L),
			harness.onlyRecord(ACCOUNT).getLoot());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The skip and block log as wired in the plugin ({@link PluginHarness}): assignments that end without a session are
 * saved beside the records with their outcome, never for a played task, never from a login resync or a hop, bounded,
 * deletable, shown only in the collapsed "Skipped / blocked" section and never counted as played tasks.
 * {@link AssignmentWatchTest}, {@link AssignmentOutcomeTest} and {@link AssignmentLogTest} cover the rules.
 */
public class HarnessAssignmentLogTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int DEMONS = 42;
	private static final int CAVE_HORRORS = 80;
	private static final int DURADEL = 5;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(DEMONS, "Abyssal demons", 120, 120);
		harness.setAssignment(DURADEL, 0, null);
		harness.setSlayerPoints(500);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Ticks out the decision window after an end. */
	private void settle()
	{
		harness.ticks(AssignmentWatch.END_WINDOW_TICKS + 1);
	}

	private void skip(int cost)
	{
		harness.setRemaining(0);
		harness.setSlayerPoints(500 - cost);
	}

	private AssignmentEntry onlyEntry()
	{
		final List<AssignmentEntry> entries = harness.assignments(ACCOUNT);
		assertEquals(entries.toString(), 1, entries.size());
		return entries.get(0);
	}

	private <T> T onEdt(java.util.function.Supplier<T> read)
	{
		final List<T> result = new ArrayList<>(1);
		harness.onEdt(() -> result.add(read.get()));
		return result.get(0);
	}

	private List<String> assignmentRows()
	{
		return onEdt(() -> harness.ui().getAssignments().getRows());
	}

	@Test
	public void aSkipIsSavedAndShownCollapsed()
	{
		skip(30);
		settle();
		AssignmentEntry e = onlyEntry();
		assertEquals(AssignmentOutcome.SKIPPED, e.getOutcome());
		assertEquals(Integer.valueOf(-30), e.getPointsChange());
		assertEquals("Abyssal demons", e.getMonster());
		assertEquals(Integer.valueOf(DEMONS), e.getCreatureId());
		assertEquals(Integer.valueOf(120), e.getOriginalAmount());
		assertEquals(Integer.valueOf(DURADEL), e.getSlayerMaster());
		assertTrue(e.getEndedAt() > 0);
		assertTrue("not a played task", harness.records(ACCOUNT).isEmpty());

		assertEquals("collapsed by default", "Skipped / blocked (1) | Show",
			onEdt(() -> harness.ui().getAssignments().getHeaderText()));
		assertFalse(onEdt(() -> harness.ui().getAssignments().isExpanded()));
		assertTrue(assignmentRows().isEmpty());

		harness.onEdt(() -> harness.ui().getAssignments().toggle());
		assertTrue(onEdt(() -> harness.ui().getAssignments().isExpanded()));
		List<String> rows = assignmentRows();
		assertEquals(1, rows.size());
		// The monster and the outcome word, then the date and the master (9d).
		assertTrue(rows.get(0), rows.get(0).startsWith("Abyssal demons | Skipped | "));
		assertTrue(rows.get(0), rows.get(0).contains(" \u00b7 Duradel/Kuradal | <html>"));
		assertTrue(rows.get(0), rows.get(0).contains("<br>Master: Duradel/Kuradal<br>Type: Regular<br>Assigned: 120"
			+ "<br>Points: -30</html>"));
		assertEquals("Saved tasks: 0", onEdt(() -> harness.ui().getSavedTasksText()));
		assertEquals(Arrays.asList(LedgerHistory.ALL), onEdt(() -> harness.ui().getHistory().getFilterOptions()));
		assertTrue(onEdt(() -> harness.ui().getHistory().getValuesText()).isEmpty());
	}

	@Test
	public void aBlockIsSaved()
	{
		skip(100);
		harness.setVarbit(VarbitID.SLAYER_BLOCKED_DURADEL_1, DEMONS);
		settle();
		assertEquals(AssignmentOutcome.BLOCKED, onlyEntry().getOutcome());
		assertEquals(Integer.valueOf(-100), onlyEntry().getPointsChange());
	}

	@Test
	public void aBlockSeenInAnOldBlockedVarpIsSaved()
	{
		skip(100);
		harness.setVarp(VarPlayerID.SLAYER_REWARDS_BLOCKED_2, DEMONS);
		settle();
		assertEquals(AssignmentOutcome.BLOCKED, onlyEntry().getOutcome());
	}

	@Test
	public void aTuraelResetIsSaved()
	{
		harness.setTask(6, "Cows", 20, 20);
		harness.setAssignment(1, 0, null);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 0);
		settle();
		AssignmentEntry e = onlyEntry();
		assertEquals(AssignmentOutcome.RESET, e.getOutcome());
		assertEquals("Abyssal demons", e.getMonster());
		assertEquals("the old task's master", Integer.valueOf(DURADEL), e.getSlayerMaster());
		assertEquals(Integer.valueOf(0), e.getPointsChange());
	}

	@Test
	public void aCompletionSeenWhileWaitingForTheFirstKillIsATrackedTask()
	{
		// Tracking is automatic (V2 plan 4.1): the final kill is the assignment's first kill, so it starts a session
		// and completes it. The assignment was played, so it is no "Completed (untracked)" entry
		// (AssignmentWatchTest covers that outcome).
		harness.completeTask(15);
		settle();
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Integer.valueOf(15), record.getPointsEarned());
	}

	@Test
	public void anUnexplainedEndIsSavedAsUnknownWhenTheNextTaskAppears()
	{
		harness.setRemaining(0);
		settle();
		harness.ticks(10);
		assertTrue("waits for the next task", harness.assignments(ACCOUNT).isEmpty());
		harness.setTask(CAVE_HORRORS, "Cave horrors", 150, 150);
		harness.tick();
		assertEquals(AssignmentOutcome.UNKNOWN, onlyEntry().getOutcome());
	}

	@Test
	public void aCompletedPlayedTaskGetsNoEntry()
	{
		assertTrue(harness.startNow());
		harness.setRemaining(119);
		harness.tick();
		harness.completeTask(15);
		settle();
		assertTrue(harness.onlyRecord(ACCOUNT).isCompleted());
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aPartialPlayedTaskGetsNoEntryWhenSkippedLater()
	{
		assertTrue(harness.startNow());
		harness.setRemaining(100);
		harness.tick();
		harness.endTask();
		assertTrue(harness.onlyRecord(ACCOUNT).isPartial());
		harness.ticks(5);
		skip(30);
		settle();
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aRunningSessionsTaskSkippedGetsNoEntry()
	{
		assertTrue(harness.startNow());
		harness.tick();
		skip(30);
		settle();
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aTaskChangedDuringASessionGetsNoEntry()
	{
		assertTrue(harness.startNow());
		harness.tick();
		harness.setTask(6, "Cows", 20, 20);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 0);
		settle();
		assertTrue("the session was saved as partial", harness.onlyRecord(ACCOUNT).isPartial());
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aTaskPlayedInAnEarlierRunGetsNoEntry()
	{
		assertTrue(harness.startNow());
		harness.setRemaining(100);
		harness.tick();
		harness.endTask();
		// The client is restarted: the plugin forgets what it watched.
		harness.shutDown();
		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		skip(30);
		settle();
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void anUnplayedTaskFirstSeenAtAStartIsStillSaved()
	{
		harness.shutDown();
		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		skip(30);
		settle();
		assertEquals(AssignmentOutcome.SKIPPED, onlyEntry().getOutcome());
	}

	@Test
	public void aLoginResyncMakesNoEntry()
	{
		harness.logout();
		// Skipped and reassigned on another client while logged out here.
		harness.setTask(CAVE_HORRORS, "Cave horrors", 150, 150);
		harness.setSlayerPoints(470);
		harness.loginAndSettle(ACCOUNT);
		settle();
		harness.ticks(10);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void varpsSyncingAfterALoginMakeNoEntry()
	{
		harness.logout();
		harness.setRemaining(0);
		harness.setSlayerPoints(0);
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(3);
		harness.setRemaining(120);
		harness.setSlayerPoints(500);
		settle();
		harness.ticks(10);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aHopMakesNoEntry()
	{
		harness.hop();
		harness.setRemaining(0);
		harness.setSlayerPoints(0);
		harness.ticks(PluginHarness.SETTLE_TICKS + 2);
		harness.setRemaining(120);
		harness.setSlayerPoints(500);
		settle();
		harness.ticks(10);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void aSkipJustBeforeALogoutIsDropped()
	{
		skip(30);
		harness.tick();
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		settle();
		harness.ticks(10);
		assertTrue("an undecided end is dropped, not guessed", harness.assignments(ACCOUNT).isEmpty());
	}

	@Test
	public void theNewestEntriesAreKept() throws IOException
	{
		harness.logout();
		final StringBuilder json = new StringBuilder("{\"schemaVersion\":2,\"records\":[],\"assignments\":[");
		for (int i = 0; i < AssignmentLog.MAX_ENTRIES; i++)
		{
			json.append(i == 0 ? "" : ",").append("{\"id\":\"old").append(i).append("\",\"monster\":\"Cows\","
				+ "\"endedAt\":").append(1_000 + i).append(",\"outcome\":\"SKIPPED\"}");
		}
		json.append("]}");
		writeLedger(json.toString());
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Skipped / blocked (500) | Show", onEdt(() -> harness.ui().getAssignments().getHeaderText()));

		skip(30);
		settle();
		final List<AssignmentEntry> entries = harness.assignments(ACCOUNT);
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		assertEquals("the oldest went", "old1", entries.get(0).getId());
		assertEquals("Abyssal demons", entries.get(entries.size() - 1).getMonster());
		assertEquals("Skipped / blocked (500) | Show", onEdt(() -> harness.ui().getAssignments().getHeaderText()));
	}

	@Test
	public void anEntryCanBeDeleted()
	{
		skip(30);
		settle();
		final String id = onlyEntry().getId();
		harness.deleteAssignment(ACCOUNT, id);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
		assertEquals("Skipped / blocked (0) | Show", onEdt(() -> harness.ui().getAssignments().getHeaderText()));
		harness.onEdt(() -> harness.ui().getAssignments().toggle());
		assertTrue(assignmentRows().isEmpty());
	}

	@Test
	public void deletingAnEntryKeepsTheRecords()
	{
		assertTrue(harness.startNow());
		harness.setRemaining(100);
		harness.tick();
		harness.endTask();
		harness.setTask(CAVE_HORRORS, "Cave horrors", 150, 150);
		harness.ticks(2);
		skip(30);
		settle();
		harness.deleteAssignment(ACCOUNT, onlyEntry().getId());
		assertEquals(1, harness.records(ACCOUNT).size());
		assertEquals("Saved tasks: 1", onEdt(() -> harness.ui().getSavedTasksText()));
	}

	@Test
	public void anOldLedgerFileLoadsUnchanged() throws IOException
	{
		harness.logout();
		final String old = "{\"schemaVersion\":2,\"records\":[{\"id\":\"r1\",\"monster\":\"Kraken\",\"creatureId\":"
			+ DEMONS + ",\"initialAmount\":3,\"kills\":3,\"activeMillis\":60000,\"startedAt\":1000,\"endedAt\":61000,"
			+ "\"completed\":true,\"partial\":false}]}";
		writeLedger(old);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Saved tasks: 1", onEdt(() -> harness.ui().getSavedTasksText()));
		assertEquals("Skipped / blocked (0) | Show", onEdt(() -> harness.ui().getAssignments().getHeaderText()));
		assertEquals("loading never rewrites the file", old, readLedger());

		skip(30);
		settle();
		assertEquals(1, harness.records(ACCOUNT).size());
		assertEquals("Kraken", harness.onlyRecord(ACCOUNT).getMonster());
		assertEquals(1, harness.assignments(ACCOUNT).size());
	}

	@Test
	public void anotherAccountsTaskIsNotCarriedOver()
	{
		harness.logout();
		harness.setSlayerPoints(470);
		harness.setRemaining(0);
		harness.loginAndSettle(PluginHarness.OTHER_ACCOUNT);
		settle();
		harness.ticks(10);
		assertTrue(harness.assignments(ACCOUNT).isEmpty());
		assertTrue(harness.assignments(PluginHarness.OTHER_ACCOUNT).isEmpty());
	}

	private Path ledgerPath()
	{
		return harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json");
	}

	private void writeLedger(String json) throws IOException
	{
		Files.write(ledgerPath(), json.getBytes(StandardCharsets.UTF_8));
	}

	private String readLedger() throws IOException
	{
		return new String(Files.readAllBytes(ledgerPath()), StandardCharsets.UTF_8);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.atLeast;
import static org.mockito.Mockito.verify;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.stream.Collectors;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.chat.QueuedMessage;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * The automatic session lifecycle through the plugin's events (V2 plan 4.1): a task kill starts the session,
 * backdated to the player's first hit on the NPCs paired with it, with their kills per NPC and the superior they
 * spawned; hops keep it running; logouts stop it until the next kill; Away; Pause and Resume; End task and Track again;
 * the sidebar's buttons and partial notice; and what is saved or persisted on each path.
 * {@link SessionSegmentsTest} covers the same rules on the tracker alone.
 */
public class HarnessAutomaticTrackingTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";
	private static final int DEMON = 415;
	private static final long MINUTE = 60_000L;
	private static final String SLAUGHTER = "Your bracelet of slaughter prevents your slayer count from decreasing. It has"
		+ " 29 charges left.";
	private static final String EXPEDITIOUS = "Your expeditious bracelet helps you progress your slayer task faster. It"
		+ " has 29 charges left.";
	private static final String SUPERIOR = "<col=ef1020>A superior foe has appeared...</col>";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The tracker's clock: hits, deaths and segments are timed by it. */
	private final AtomicLong now = new AtomicLong(1_000_000_000L);
	private int nextIndex = 1;

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTrackerClock(now::get);
		harness.setTask(TASK, TASK_NAME, 50, 50);
		harness.loginAndSettle(ACCOUNT);
	}

	private NPC demon()
	{
		return harness.npc(nextIndex++, DEMON, "Abyssal demon");
	}

	/** The count drops by {@code n} on the next tick. */
	private void countDrops(int n)
	{
		harness.setRemaining(harness.tracker().getCurrentRemaining() - n);
		harness.tick();
	}

	/** A kill with no NPC of the player's dying (a cannon-only kill): the count drops on the next tick. */
	private void cannonKill()
	{
		countDrops(1);
	}

	/** A fight: the player's first hit now, more hits for {@code millis}, then the NPC dies and the count drops. */
	private void fight(long millis)
	{
		final NPC npc = demon();
		harness.hitsplat(npc, true);
		now.addAndGet(millis);
		harness.hitsplat(npc, true);
		harness.npcDies(npc);
		countDrops(1);
	}

	private long active()
	{
		return harness.tracker().getActiveMillis();
	}

	/** The chat lines posted so far. */
	private List<String> chatLines()
	{
		ArgumentCaptor<QueuedMessage> messages = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, atLeast(0)).queue(messages.capture());
		return messages.getAllValues().stream().map(QueuedMessage::getRuneLiteFormattedMessage)
			.collect(Collectors.toList());
	}

	/** The overlay's first row, as its two sides, or {@code null} when it shows nothing. */
	private String overlayFirstRow()
	{
		List<OverlayRows.Row> rows = OverlayRows.rows(harness.overlayData(), OverlayRows.Groups.ALL);
		return rows.isEmpty() ? null : rows.get(0).getLeft() + " / " + rows.get(0).getRight();
	}

	/**
	 * The sidebar's status strip after a refresh: the state word, then only the buttons shown (Pause or Resume, End
	 * task or Track again), {@code " (off)"} on one that can't be pressed.
	 */
	private String panel()
	{
		final String[] shown = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			shown[0] = harness.ui().getStatusStrip();
		});
		return shown[0];
	}

	/** The status strip's clock after a refresh: the elapsed time beside "Running", or "" without one. */
	private String clock()
	{
		final String[] shown = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			shown[0] = harness.ui().getStatusClock();
		});
		return shown[0];
	}

	/** The sidebar's partial-save notice after a refresh, or {@code null} while it is hidden. */
	private String partialNotice()
	{
