/**
 * The personality pass's chat lines as wired in the plugin ({@link PluginHarness}, 2.0 phase 11): the task-complete
 * line and the record-fast task line post once per task, the record line only with 3 earlier completed tasks to beat
 * and then the task-complete line without its {@code Gz.}; the notable drop line for a session's notable stack, with
 * the kill number on even kills, never for an item Ground Items' hidden list hides (coins aside), and
 * {@code That's the task paid for.} only when the drop covers the supplies so far, once per task; and each line's
 * setting stops it. {@link TaskCompleteMessageTest}, {@link FastestTaskMessageTest} and
 * {@link NotableDropMessageTest} cover the words.
 */
public class HarnessChatLinesTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final long MINUTE = 60_000L;
	private static final int DEMONS = 42;
	private static final String[] EAT = {"Eat", null, null, null, "Drop"};
	private static final String COMPLETE = "<colHIGHLIGHT>Abyssal demons done:<colNORMAL> 3 kills in 15 min, +100.";
	private static final String RECORD = "<colHIGHLIGHT>Fastest Abyssal demons task yet:<colNORMAL> 15 min, 15 min"
		+ " under your old best.";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The tracker's clock, so a task's active time is under the test's control. */
	private final AtomicLong now = new AtomicLong(1_000_000_000L);
	private int ids;

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.defineItem(ItemID.ABYSSAL_WHIP, "Abyssal whip", 1_500_000, 72_000);
		harness.defineItem(ItemID.SHARK, "Shark", 800, 50, EAT);
		harness.defineItem(ItemID.RUNE_PLATEBODY, "Rune platebody", 200_000, 39_000);
		harness.defineItem(ItemID.COINS, "Coins", 1, 1);
		harness.startUp();
		harness.setTrackerClock(now::get);
	}

	// ---- Task complete and record ----

	@Test
	public void theTaskCompleteAndRecordLinesPostOncePerTask() throws IOException
	{
		saveSlowTasks(3);

		playTask();
		harness.ticks(5);
		harness.logout();

		assertEquals(15 * MINUTE, played().getActiveMillis());
		// The record line follows, so the task-complete line has no Gz.
		assertEquals(Arrays.asList(COMPLETE, RECORD), lines());
	}

	@Test
	public void withoutThreeEarlierTasksThereIsNoRecord() throws IOException
	{
		saveSlowTasks(2);

		playTask();

		assertEquals(Collections.singletonList(COMPLETE.replace("+100.", "+100. Gz.")), lines());
	}

	@Test
	public void theRecordTaskLineSettingStopsItsLine() throws IOException
	{
		saveSlowTasks(3);
		harness.config.recordTaskLine = false;

		playTask();

		assertEquals("the Gz. is back", Collections.singletonList(COMPLETE.replace("+100.", "+100. Gz.")), lines());
	}

	@Test
	public void theTaskCompleteLineSettingStopsItsLineButNotTheNotification() throws IOException
	{
		saveSlowTasks(3);
		harness.config.taskCompleteLine = false;
		harness.config.taskCompleteNotification = true;

		playTask();

		assertEquals(Collections.singletonList(RECORD), lines());
		ArgumentCaptor<String> notification = ArgumentCaptor.forClass(String.class);
		verify(harness.notifier, times(1)).notify(notification.capture());
		assertEquals("Abyssal demons done: 3 kills in 15 min, +100.", notification.getValue());
	}

	@Test
	public void aPartialTaskHasNeitherLine() throws IOException
	{
		saveSlowTasks(3);
		harness.setTask(DEMONS, "Abyssal demons", 3, 3);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		now.addAndGet(MINUTE);
		harness.setRemaining(2);
		harness.tick();
		harness.endTask();

		assertTrue(played().isPartial());
		assertEquals(Collections.emptyList(), lines());
	}

	@Test
	public void aLogoutBeforeTheRecordCheckLeavesTheGzAndNoRecordLine() throws IOException
	{
		saveSlowTasks(3);

		playTaskThenLeaveBeforeTheRecordCheck(this::logoutWithoutDrain);

		assertEquals(15 * MINUTE, played().getActiveMillis());
		assertEquals(Collections.singletonList(COMPLETE.replace("+100.", "+100. Gz.")), lines());
	}

	@Test
	public void anAccountSwitchBeforeTheRecordCheckLeavesTheGzAndNoRecordLine() throws IOException
	{
		saveSlowTasks(3);

		playTaskThenLeaveBeforeTheRecordCheck(() ->
		{
			logoutWithoutDrain();
			harness.setAccountHash(PluginHarness.OTHER_ACCOUNT);
			gameStateWithoutDrain(GameState.LOGGING_IN);
			gameStateWithoutDrain(GameState.LOADING);
			gameStateWithoutDrain(GameState.LOGGED_IN);
		});

		assertEquals(15 * MINUTE, played().getActiveMillis());
		assertEquals(Collections.singletonList(COMPLETE.replace("+100.", "+100. Gz.")), lines());
	}

	// ---- Notable drops ----

	@Test
	public void theNotableDropLineNamesTheMonsterOrTheKill()
	{
		startTask(10);
		kill(9);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);
		kill(8);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);
		// Below the Notable drop value: no line.
		harness.postLoot("Abyssal demon", ItemID.BONES, 1);

		assertEquals(Arrays.asList("<colHIGHLIGHT>Abyssal whip (1.5M)<colNORMAL> from an abyssal demon.",
			"<colHIGHLIGHT>Abyssal whip (1.5M)<colNORMAL> at kill 2 of 10."), lines());
	}

	@Test
	public void theTaskIsPaidForOnlyWhenTheDropCoversTheSuppliesSoFar()
	{
		harness.setInventory(item(ItemID.SHARK, 10));
		startTask(10);
		// Two sharks eaten: 1,600 gp of supplies, valued within two ticks.
		harness.setInventory(item(ItemID.SHARK, 8));
		kill(9);
		harness.ticks(2);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);
		// Bones worth 100 gp each, notable at a 50 gp threshold, don't cover 1,600 gp.
		harness.setNotableDropThreshold(50);
		harness.postLoot("Abyssal demon", ItemID.BONES, 1);

		assertEquals(Arrays.asList(
			"<colHIGHLIGHT>Abyssal whip (1.5M)<colNORMAL> from an abyssal demon. That's the task paid for.",
			"<colHIGHLIGHT>Bones (100)<colNORMAL> from an abyssal demon."), lines());
	}

	@Test
	public void theTaskIsPaidForOnlyOncePerTask()
	{
		harness.setInventory(item(ItemID.SHARK, 10));
		startTask(10);
		harness.setInventory(item(ItemID.SHARK, 8));
		kill(9);
		harness.ticks(2);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);
		kill(7);
		harness.ticks(2);
		// It covers the supplies again, but the task was paid for already.
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);

		assertEquals(Arrays.asList(
			"<colHIGHLIGHT>Abyssal whip (1.5M)<colNORMAL> from an abyssal demon. That's the task paid for.",
			"<colHIGHLIGHT>Abyssal whip (1.5M)<colNORMAL> from an abyssal demon."), lines());
	}

	@Test
	public void theNextTaskCanBePaidForAgain()
	{
		harness.setInventory(item(ItemID.SHARK, 10));
		startTask(10);
		harness.setInventory(item(ItemID.SHARK, 8));
		kill(9);
		harness.ticks(2);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);
		harness.completeTask();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 1);

		// A new task, a new session: its first drop that covers its supplies says it again.
		harness.setTask(DEMONS, "Abyssal demons", 10, 10);
		harness.tick();
		assertTrue(harness.startNow());
		harness.setInventory(item(ItemID.SHARK, 6));
		kill(9);
		harness.ticks(2);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);

		String paid = "<colHIGHLIGHT>Abyssal whip (1.5M)<colNORMAL> from an abyssal demon. That's the task paid for.";
		assertEquals(Arrays.asList(paid, paid), lines().stream().filter(l -> l.contains("Abyssal whip"))
			.collect(Collectors.toList()));
	}

	@Test
	public void aHiddenItemGetsNoLineNorPaysForTheTask()
	{
		harness.setGroundItemsHidden("Abyssal whip");
		harness.setInventory(item(ItemID.SHARK, 10));
		startTask(10);
		harness.setInventory(item(ItemID.SHARK, 8));
		kill(9);
		harness.ticks(2);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);

		assertEquals(Collections.emptyList(), lines());
		assertEquals("still a notable drop of the task", 1, harness.tracker().getNotableDrops().size());
	}

	@Test
	public void aHiddenItemGivesWayToTheKillsNextNotableDrop()
	{
		harness.setGroundItemsHidden("Abyssal whip");
		startTask(10);
		kill(9);
		harness.postLoot("Abyssal demon", new ItemStack(ItemID.ABYSSAL_WHIP, 1),
			new ItemStack(ItemID.RUNE_PLATEBODY, 1));

		assertEquals(Collections.singletonList("<colHIGHLIGHT>Rune platebody (200K)<colNORMAL> from an abyssal demon."),
			lines());
	}

	@Test
	public void hiddenCoinsStillGetTheirLine()
	{
		harness.setGroundItemsHidden("Coins");
		startTask(10);
		kill(9);
		harness.postLoot("Abyssal demon", ItemID.COINS, 200_000);

		assertEquals(Collections.singletonList("<colHIGHLIGHT>Coins x200,000 (200K)<colNORMAL> from an abyssal demon."),
			lines());
	}

	@Test
	public void withNoSuppliesUsedTheTaskIsNotPaidFor()
	{
		startTask(10);
		kill(9);
		harness.ticks(2);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);

		assertEquals(Collections.singletonList("<colHIGHLIGHT>Abyssal whip (1.5M)<colNORMAL> from an abyssal demon."),
			lines());
	}

	@Test
	public void theNotableDropLineSettingStopsItsLine()
	{
		harness.config.notableDropLine = false;
		startTask(10);
		kill(9);
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);

		assertEquals(Collections.emptyList(), lines());
		assertEquals("still a notable drop of the task", 1, harness.tracker().getNotableDrops().size());
	}

	@Test
	public void lootTheSessionDoesNotTakeHasNoLine()
	{
		harness.setTask(DEMONS, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		// A task, but no session yet: the loot is only buffered.
		harness.postLoot("Abyssal demon", ItemID.ABYSSAL_WHIP, 1);

		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
	}

	// ---- Helpers ----

	/** A 3-kill Abyssal demons task done in 15 minutes, its last kill's loot one bone, then its grace window. */
	private void playTask()
	{
		harness.setTask(DEMONS, "Abyssal demons", 3, 3);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		now.addAndGet(5 * MINUTE);
		harness.setRemaining(2);
		harness.tick();
		now.addAndGet(5 * MINUTE);
		harness.setRemaining(1);
		harness.tick();
		now.addAndGet(5 * MINUTE);
		harness.completeTask();
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
	}

	/**
	 * As {@link #playTask}, but the EDT is held while the grace window ends and the task is saved, so the record check
	 * waits there; {@code leave} then runs (without draining) before the EDT is let go and everything drains.
	 */
	private void playTaskThenLeaveBeforeTheRecordCheck(Runnable leave)
	{
		harness.setTask(DEMONS, "Abyssal demons", 3, 3);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		now.addAndGet(5 * MINUTE);
		harness.setRemaining(2);
		harness.tick();
		now.addAndGet(5 * MINUTE);
		harness.setRemaining(1);
		harness.tick();
		now.addAndGet(5 * MINUTE);
		harness.completeTask();
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS - 1);
		assertEquals("not saved yet", Collections.emptyList(), lines());

		CountDownLatch held = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		SwingUtilities.invokeLater(() ->
		{
			held.countDown();
			try
			{
				release.await(10, TimeUnit.SECONDS);
			}
			catch (InterruptedException e)
			{
				Thread.currentThread().interrupt();
			}
		});
		try
		{
			assertTrue(held.await(10, TimeUnit.SECONDS));
			// The grace window ends: the save is queued, then runs, and the record check waits for the EDT.
			harness.tickWithoutDrain();
			harness.runClientThread();
			assertTrue("the save ran", harness.runExecutor() > 0);
			leave.run();
		}
		catch (InterruptedException e)
		{
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
		finally
		{
			release.countDown();
		}
		harness.drain();
	}

	/** The client goes to the login screen without draining: the account hash reads -1 there. */
	private void logoutWithoutDrain()
	{
		harness.setAccountHash(SessionTracker.NO_ACCOUNT);
		gameStateWithoutDrain(GameState.LOGIN_SCREEN);
	}

	/** Sets the game state and posts {@link GameStateChanged} without draining any queued work. */
	private void gameStateWithoutDrain(GameState state)
	{
		harness.setGameStateSilently(state);
		GameStateChanged event = new GameStateChanged();
		event.setGameState(state);
		harness.postWithoutDrain(event);
	}

	/** Logs in on an Abyssal demons task of {@code size} and starts its session. */
	private void startTask(int size)
	{
		harness.setTask(DEMONS, "Abyssal demons", size, size);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
	}

	/** A task kill: the kills left drop to {@code remaining}, seen on the next tick. */
	private void kill(int remaining)
	{
		harness.setRemaining(remaining);
		harness.tick();
	}

	/** Saves {@code count} completed 3-kill Abyssal demons tasks of 30 minutes each, read when the account logs in. */
	private void saveSlowTasks(int count) throws IOException
	{
		LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(harness.ledgerDirectory().toPath()),
			harness.gson);
		for (int i = 0; i < count; i++)
		{
			LedgerRecord record = new LedgerRecord();
			record.setId("slow-" + ids++);
			record.setCreatureId(DEMONS);
			record.setMonster("Abyssal demons");
			record.setKills(3);
			record.setActiveMillis(30 * MINUTE);
			record.setCompleted(true);
			record.setLootGeValue(0L);
			record.setLootHaValue(0L);
			record.setSuppliesGeValue(0L);
			store.append(ACCOUNT, record);
		}
	}

	/** The one saved task that isn't one of {@link #saveSlowTasks}. */
	private LedgerRecord played()
	{
		List<LedgerRecord> played = harness.records(ACCOUNT).stream().filter(r -> !r.getId().startsWith("slow-"))
			.collect(Collectors.toList());
		assertEquals(played.toString(), 1, played.size());
		return played.get(0);
	}

	/** The chat lines posted so far, each a "Slayer Ledger" console message. */
	private List<String> lines()
	{
		ArgumentCaptor<QueuedMessage> messages = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, atLeast(0)).queue(messages.capture());
		for (QueuedMessage message : messages.getAllValues())
		{
			assertEquals(ChatMessageType.CONSOLE, message.getType());
			assertEquals("Slayer Ledger", message.getName());
		}
		return messages.getAllValues().stream().map(QueuedMessage::getRuneLiteFormattedMessage)
			.collect(Collectors.toList());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.Future;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.chat.QueuedMessage;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * The late-loot grace window as wired in the plugin ({@link PluginHarness}): the priority -1 grace ticker runs after
 * the default-priority handlers and LootManager's loot, a completed session is saved exactly once as completed when
 * the window ends, and every other way out (logout, hop, plugin stop, client exit) saves it at once.
 * {@link CompletionGraceTest} covers the tracker's side of the window.
 */
public class HarnessCompletionGraceTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.defineItem(ItemID.ABYSSAL_WHIP, "Abyssal whip", 1_500_000, 72_000);
		harness.defineItem(ItemID.COINS, "Coins", 1, 1);
		// The whip is a notable drop; its chat line has its own tests (HarnessChatLinesTest).
		harness.config.notableDropLine = false;
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 3, 3);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.setRemaining(1);
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
	}

	/** Kills the last monster: the completion is read on this tick and the session is held for late loot. */
	private void completeOnNextTick()
	{
		harness.completeTask();
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		assertTrue("not saved during the grace window", harness.records(ACCOUNT).isEmpty());
	}

	@Test
	public void lootPostedOnTheCompletionTickIsCounted()
	{
		harness.completeTask();
		// LootManager posts this during the completion tick. It counts whichever side of the hold it lands on, so this
		// does not test ordering; lootWithinTheGraceWindowCountsAndLaterLootDoesNot does.
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertFalse(record.isPartial());
		assertEquals(3, record.getKills());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.ABYSSAL_WHIP));
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.BONES));
		// Priced on the client thread when saved (the harness fails the test on an off-thread ItemManager call).
		assertEquals(Long.valueOf(1_500_100), record.getLootGeValue());
	}

	@Test
	public void successfulCompletionPostsOneChatSummaryAndNoNotificationByDefault()
	{
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		completeOnNextTick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		ArgumentCaptor<QueuedMessage> message = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, times(1)).queue(message.capture());
		assertEquals(ChatMessageType.CONSOLE, message.getValue().getType());
		assertEquals("Slayer Ledger", message.getValue().getName());
		assertTrue(message.getValue().getRuneLiteFormattedMessage()
			.startsWith("<colHIGHLIGHT>Abyssal demons done:<colNORMAL> 3 kills in "));
		assertTrue(message.getValue().getRuneLiteFormattedMessage().endsWith(", +1.5M. Gz."));
		verifyNoInteractions(harness.notifier);
	}

	@Test
	public void notificationCanBeEnabledForSuccessfulCompletion()
	{
		harness.config.taskCompleteNotification = true;
		completeOnNextTick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		ArgumentCaptor<String> message = ArgumentCaptor.forClass(String.class);
		verify(harness.notifier, times(1)).notify(message.capture());
		assertTrue(message.getValue().startsWith("Abyssal demons done: 3 kills in "));
	}

	@Test
	public void completionSummaryIsPostedOnlyOnce()
	{
		completeOnNextTick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		harness.ticks(5);
		harness.logout();

		verify(harness.chatMessageManager, times(1)).queue(any(QueuedMessage.class));
	}

	@Test
	public void failedSaveDoesNotPostCompletionSummary() throws IOException
	{
		harness.config.taskCompleteNotification = true;
		// A ledger from a newer plugin version is never overwritten, so the completed record's append fails.
		String json = "{\"schemaVersion\":" + (LedgerStore.FILE_SCHEMA_VERSION + 1) + ",\"records\":[]}";
		Path ledger = harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json");
		Files.write(ledger, json.getBytes(StandardCharsets.UTF_8));

		completeOnNextTick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		assertFalse("the save was attempted", harness.tracker().hasPendingCompletion());
		assertEquals("the newer ledger is left alone", json, new String(Files.readAllBytes(ledger), StandardCharsets.UTF_8));
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
		verifyNoInteractions(harness.notifier);
	}

	@Test
	public void partialSaveDoesNotPostCompletionSummary()
	{
		harness.config.taskCompleteNotification = true;
		harness.endTask();

		assertTrue(harness.onlyRecord(ACCOUNT).isPartial());
		verify(harness.chatMessageManager, never()).queue(any(QueuedMessage.class));
		verifyNoInteractions(harness.notifier);
	}

	@Test
	public void lootWithinTheGraceWindowCountsAndLaterLootDoesNot()
	{
		completeOnNextTick();
		harness.lootOnNextTick(ItemID.BONES, 2);
		harness.tick();
		assertTrue("one grace tick left", harness.tracker().hasPendingCompletion());
		assertTrue(harness.records(ACCOUNT).isEmpty());

		// The last grace tick: LootManager's loot arrives before the ticker releases the session.
		harness.lootOnNextTick(ItemID.COINS, 500);
		harness.tick();
		assertFalse(harness.tracker().hasPendingCompletion());
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Long.valueOf(3), record.getLoot().get(ItemID.BONES));
		assertEquals(Long.valueOf(500), record.getLoot().get(ItemID.COINS));

		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.ticks(3);
		record = harness.onlyRecord(ACCOUNT);
		assertNull("loot after the window is not added", record.getLoot().get(ItemID.ABYSSAL_WHIP));
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void lootPostedBetweenTicksDuringTheWindowCounts()
	{
		completeOnNextTick();
		harness.postLoot(ItemID.ABYSSAL_WHIP, 1);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(Long.valueOf(1), harness.onlyRecord(ACCOUNT).getLoot().get(ItemID.ABYSSAL_WHIP));
	}

	@Test
	public void logoutDuringTheWindowSavesTheCompletedSessionOnce()
	{
		completeOnNextTick();
		harness.logout();
		assertFalse(harness.tracker().hasPendingCompletion());
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertNull("a completed session is never persisted as active", harness.activeSession(ACCOUNT));

		harness.setTask(TASK + 1, "Greater demons", 20, 20);
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(5);
		harness.shutDown();
		assertEquals(1, harness.records(ACCOUNT).size());
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void worldHopDuringTheWindowSavesTheCompletedSession()
	{
		completeOnNextTick();
		harness.hop();
		assertFalse(harness.tracker().hasPendingCompletion());
		assertTrue(harness.onlyRecord(ACCOUNT).isCompleted());
		harness.ticks(PluginHarness.SETTLE_TICKS + SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(1, harness.records(ACCOUNT).size());
	}

	@Test
	public void pluginStopDuringTheWindowSavesTheCompletedSession()
	{
		completeOnNextTick();
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();
		harness.shutDown();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertFalse(record.isPartial());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.ABYSSAL_WHIP));
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void clientExitDuringTheWindowSavesTheCompletedSessionAndWaitsForIt()
	{
		completeOnNextTick();
		List<Future<?>> waitedFor = harness.clientShutdown();

		assertEquals("the held completion's save", 1, waitedFor.size());
		for (Future<?> future : waitedFor)
		{
			assertTrue(future.isDone());
			assertFalse(future.isCancelled());
		}
		assertTrue(harness.onlyRecord(ACCOUNT).isCompleted());
		assertFalse(harness.tracker().hasPendingCompletion());
	}

	@Test
	public void stopDuringTheWindowKeepsTheCompletedRecordAndNewSessionApart()
	{
		completeOnNextTick();
		// A new task, and a new session, while the old one is still held.
		harness.setTask(TASK + 1, "Greater demons", 20, 20);
		harness.tick();
		assertTrue(harness.startNow());
		harness.endTask();

		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(2, records.size());
		LedgerRecord completed = records.stream().filter(LedgerRecord::isCompleted).findFirst().orElse(null);
		LedgerRecord partial = records.stream().filter(LedgerRecord::isPartial).findFirst().orElse(null);
		assertEquals("Abyssal demons", completed.getMonster());
		assertEquals("Greater demons", partial.getMonster());
		assertFalse(harness.tracker().hasPendingCompletion());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.chat.QueuedMessage;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * Ground Items' hidden list as wired in the plugin: the items it hides are left out of every loot grid (live,
 * a saved task's details, Overall totals) and out of the loot value and profit everywhere (live values, history rows,
 * Overall totals, the task-complete line), read only from Ground Items' config. A change of the
 * list, of Ground Items' on/off state or of the "Hide Ground Items' hidden items" setting applies at once, and the
 * records are never changed, so the values come back. {@link GroundItemsHiddenTest} covers the matching and
 * {@link HiddenLootValuationTest} the values.
 */
public class HarnessGroundItemsHiddenTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.RUNE_PLATEBODY, "Rune platebody", 38_000, 39_000);
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.defineNotedItem(ItemID.Cert.BONES, ItemID.BONES);
		harness.defineItem(ItemID.NATURERUNE, "Nature rune", 90, 108);
	}

	private <T> T onEdt(Supplier<T> read)
	{
		AtomicReference<T> value = new AtomicReference<>();
		harness.onEdt(() -> value.set(read.get()));
		return value.get();
	}

	private String liveLootLine()
	{
		return onEdt(() ->
		{
			harness.panel().refresh();
			return harness.ui().getValuesText();
		}).split(" \\| ")[0];
	}

	/** The live loot's value as {@link PanelProbe#getValuesText} reads it from the loot grid's sub-header. */
	private static String lootLine(long value)
	{
		return "Loot: " + LedgerFormat.amount(value);
	}

	/** Starts a session with a platebody, 3 bones and 2 noted bones looted; the live loot grid is always open. */
	private void startLooting()
	{
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.postLoot(ItemID.RUNE_PLATEBODY, 1);
		harness.postLoot(ItemID.BONES, 3);
		harness.postLoot(ItemID.Cert.BONES, 2);
		harness.ticks(2);
	}

	@Test
	public void liveLootLeavesHiddenItemsOutOfTheGridAndTheValue()
	{
		harness.setGroundItemsHidden("bones");
		startLooting();

		assertEquals("noted bones match as bones", lootLine(38_000), liveLootLine());
		assertEquals("Loot (2 hidden) | 38K", onEdt(() -> harness.ui().getLiveLoot().getHeaderText()));
		assertEquals(Collections.singletonList("Rune platebody | " + ItemID.RUNE_PLATEBODY + " | (alch)"),
			onEdt(() -> harness.ui().getLiveLoot().getCellTexts()));
		String tip = onEdt(() -> harness.ui().getLiveLoot().getHeaderTooltip());
		assertTrue(tip, tip.contains("2 items are hidden by your Ground Items<br>hidden list"));
		assertTrue(tip, tip.contains("hidden items<br>are left out of loot value, except coins."));

		// The setting turned off: everything counts again, at once (on the next tick).
		harness.setHideGroundItemsHidden(false);
		harness.tick();
		assertEquals(lootLine(38_500), liveLootLine());
		assertEquals("Loot | 38.5K", onEdt(() -> harness.ui().getLiveLoot().getHeaderText()));

		// On again, and the list edited in Ground Items: applied without a restart.
		harness.setHideGroundItemsHidden(true);
		harness.setGroundItemsHidden("Rune*");
		harness.tick();
		assertEquals(lootLine(500), liveLootLine());
		assertEquals("Loot (1 hidden) | 500", onEdt(() -> harness.ui().getLiveLoot().getHeaderText()));

		// Ground Items turned off: its list no longer applies.
		harness.setGroundItemsConfig(GroundItemsHidden.PLUGIN_ENABLED_GROUP, GroundItemsHidden.PLUGIN_ENABLED_KEY,
			"false");
		harness.tick();
		assertEquals(lootLine(38_500), liveLootLine());
		harness.setGroundItemsConfig(GroundItemsHidden.PLUGIN_ENABLED_GROUP, GroundItemsHidden.PLUGIN_ENABLED_KEY,
			"true");
		harness.tick();
		assertEquals(lootLine(500), liveLootLine());

		// Never edited: Ground Items' built-in list, which hides Bones.
		harness.setGroundItemsHidden(null);
		harness.tick();
		assertEquals(lootLine(38_000), liveLootLine());
	}

	@Test
	public void onlyGroundItemsOwnSettingsAreRead()
	{
		startLooting();
		// Another Ground Items setting, or another plugin's, changes nothing.
		harness.setGroundItemsConfig(GroundItemsHidden.GROUP, "showHighlightedOnly", "true");
		harness.setGroundItemsConfig("lootTracker", GroundItemsHidden.HIDDEN_ITEMS_KEY, "Bones");
		harness.tick();
		assertEquals(lootLine(38_500), liveLootLine());
	}

	@Test
	public void theTaskCompleteLineLeavesHiddenLootOut()
	{
		harness.setGroundItemsHidden("Bones");
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 3, 3);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.setRemaining(1);
		harness.lootOnNextTick(ItemID.RUNE_PLATEBODY, 1);
		harness.tick();
		harness.lootOnNextTick(ItemID.BONES, 10);
		harness.tick();
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		ArgumentCaptor<QueuedMessage> message = ArgumentCaptor.forClass(QueuedMessage.class);
		verify(harness.chatMessageManager, times(1)).queue(message.capture());
		String line = message.getValue().getRuneLiteFormattedMessage();
		assertTrue(line, line.endsWith(", " + LedgerFormat.signed(38_000L, false) + ". Gz."));
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals("the saved loot keeps the bones", Long.valueOf(10), record.getLoot().get(ItemID.BONES));
		assertEquals("and its saved value", Long.valueOf(39_000), record.getLootGeValue());
	}

	private static String profitLine(long profit)
	{
		return "Profit (GE) | " + LedgerFormat.signed(profit, false);
	}

	/** A completed hour-long task: a platebody (30,000 saved) and 10 bones (50 saved), 600 gp of supplies. */
	private static LedgerRecord record()
	{
		LedgerRecord r = new LedgerRecord();
		r.setId("a");
		r.setMonster("Abyssal demons");
		r.setCreatureId(TASK);
		r.setInitialAmount(10);
		r.setKills(10);
		r.setActiveMillis(3_600_000L);
		r.setStartedAt(1_000L);
		r.setEndedAt(3_601_000L);
		r.setCompleted(true);
		r.setPartial(false);
		Map<Integer, Long> loot = new HashMap<>();
		loot.put(ItemID.RUNE_PLATEBODY, 1L);
		loot.put(ItemID.BONES, 10L);
		r.setLoot(loot);
		Map<Integer, Long> ge = new HashMap<>();
		ge.put(ItemID.RUNE_PLATEBODY, 30_000L);
		ge.put(ItemID.BONES, 50L);
		r.setUnitGePrices(ge);
		Map<Integer, Long> ha = new HashMap<>();
		ha.put(ItemID.RUNE_PLATEBODY, 39_000L);
		ha.put(ItemID.BONES, 1L);
		r.setUnitHaPrices(ha);
		r.setLootGeValue(30_500L);
		r.setLootHaValue(39_010L);
		r.setSuppliesGeValue(600L);
		r.setSuppliesHaValue(0L);
		return r;
	}

	/**
	 * The history row's profit, the details' loot grid (its sub-header with the loot value, and its icons), the totals'
	 * profit line and loot grid.
	 */
	private List<String> shown()
	{
		harness.drain();
		harness.onEdt(() -> harness.ui().getOverallTotals().getRows());
		harness.drain();
		return onEdt(() ->
		{
			PanelProbe ui = harness.ui();
			String row = ui.getHistory().getValuesText().get(0).split(" \\| ")[0];
			PanelProbe.ItemGridProbe details = ui.getHistory().getDetailsGrid(0, "Loot received");
			String profit = ui.getOverallTotals().getRows().get(0).split("\n")[2];
			return Arrays.asList(row, details.getHeaderText() + " " + details.getCellTexts(), profit,
				ui.getOverallTotals().getLoot(0).getHeaderText());
		});
	}

	@Test
	public void historyAndTotalsLeaveHiddenLootOutAndFollowTheList()
	{
		harness.setGroundItemsHidden("Bones");
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		LedgerRecord record = record();
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(ACCOUNT, Collections.singletonList(record));
			harness.ui().getOverallTotals().clickTitle();
		});
		harness.drain();
		harness.onEdt(() -> harness.ui().getHistory().clickRow(0));

		// Valued at today's prices: the platebody at 38,000 gp, the bones at 100 gp.
		Map<Integer, Long> today = new HashMap<>();
		today.put(ItemID.RUNE_PLATEBODY, 38_000L);
		today.put(ItemID.BONES, 100L);
		HistoryPricing.Values hiddenValues = HistoryPricing.value(record, LootPriceMode.GE, today,
			HiddenLoot.of(Collections.singleton(ItemID.BONES)));
		HistoryPricing.Values allValues = HistoryPricing.value(record, LootPriceMode.GE, today);
		// The loot value, as the details' Loot received sub-header shows it.
		assertEquals("38K", LedgerFormat.amount(hiddenValues.getLootValue(), hiddenValues.isLootApproximate()));
		assertEquals("39K", LedgerFormat.amount(allValues.getLootValue(), allValues.isLootApproximate()));
		// The row shows the profit: here the loot, as no supply item was kept to value today.
		String hiddenLoot = LedgerFormat.signed(hiddenValues.getProfit(), false);
		String allLoot = LedgerFormat.signed(allValues.getProfit(), false);
		assertEquals("+38K", hiddenLoot);
		assertEquals("+39K", allLoot);
		// Names arrive from the client thread; the bones are then matched and left out everywhere.
		assertEquals(Arrays.asList(hiddenLoot,
			"Loot received (1 hidden) | 38K [Rune platebody | " + ItemID.RUNE_PLATEBODY + " | (alch)]",
			profitLine(38_000), "Loot received (1 hidden) | Show"), shown());
		String tip = onEdt(() -> harness.ui().getHistory().getDetailsGrid(0, "Loot received").getHeaderTooltip());
		assertTrue(tip, tip.startsWith("<html>1 item is hidden by your Ground Items"));

		int[] builds = new int[2];
		harness.onEdt(() -> builds[0] = harness.ui().getOverallTotals().getBuildCount());
		long valuation = onEdt(() -> harness.historyModel().valuationVersion());

		// The list edited in Ground Items: every view is valued again, nothing cached is served.
		harness.setGroundItemsHidden("");
		assertEquals(Arrays.asList(allLoot,
			"Loot received | 39K [Rune platebody | " + ItemID.RUNE_PLATEBODY + " | (alch), Bones | " + ItemID.BONES + " x10]",
			profitLine(39_000), "Loot received | Show"), shown());
		harness.onEdt(() -> builds[1] = harness.ui().getOverallTotals().getBuildCount());
		assertTrue("the totals were worked out again", builds[1] > builds[0]);
		assertTrue(onEdt(() -> harness.historyModel().valuationVersion()) > valuation);

		// Hidden again, then the setting turned off: the values come back, the record unchanged.
		harness.setGroundItemsHidden("*bones*");
		assertEquals(hiddenLoot, shown().get(0));
		harness.setHideGroundItemsHidden(false);
		assertEquals(allLoot, shown().get(0));
		assertEquals(profitLine(39_000), shown().get(2));
		assertEquals(Long.valueOf(10), record.getLoot().get(ItemID.BONES));

		// The refresh timer works nothing out again.
		harness.onEdt(() ->
		{
			builds[0] = harness.ui().getOverallTotals().getBuildCount();
			harness.panel().refresh();
			harness.panel().refresh();
		});
		harness.drain();
		harness.onEdt(() -> builds[1] = harness.ui().getOverallTotals().getBuildCount());
		assertEquals(builds[0], builds[1]);
		assertNotNull(record.getLoot());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Supplier;
import net.runelite.client.ui.PluginPanel;
import org.junit.Rule;
import org.junit.Test;

/**
 * The Task history's Monster, Location and Master filters as wired in the plugin ({@link PluginHarness}): their
 * choices, how they combine, paging and the empty text on the filtered list, values that disappear, another account,
 * region names that arrive later and an edited location. The Location filter's choices are spots, shown by their
 * tasks' location names. {@link HistoryFilterTest} covers the rules.
 */
public class HarnessHistoryFiltersTest
{
	@Rule
	public final PluginHarness harness = new PluginHarness();

	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int DURADEL = 5;
	private static final int NIEVE = 6;
	private static final String DURADEL_NAME = "Duradel/Kuradal";
	private static final String NIEVE_NAME = "Nieve/Steve";
	private static final String LONG_LOCATION = "Catacombs of Kourend, the far north end";

	private <T> T onEdt(Supplier<T> read)
	{
		List<T> result = new ArrayList<>(1);
		harness.onEdt(() -> result.add(read.get()));
		return result.get(0);
	}

	private PanelProbe.HistoryListProbe history()
	{
		return harness.ui().getHistory();
	}

	private static LedgerRecord record(int i, String monster, String location, Integer master)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId("r" + i);
		record.setMonster(monster);
		record.setLocation(location);
		record.setSlayerMaster(master);
		record.setKills(10);
		record.setInitialAmount(10);
		record.setActiveMillis(60_000L);
		record.setEndedAt(1_700_000_000_000L - i * 60_000L);
		record.setStartedAt(record.getEndedAt() - 60_000L);
		record.setCompleted(true);
		return record;
	}

	/**
	 * 60 tasks, newest first: Abyssal demons in the Catacombs from Duradel (every 3rd, from 0), Dust devils in the Smoke
	 * Dungeon from Nieve (every 3rd, from 1), and Abyssal demons with no location and no master (every 3rd, from 2).
	 */
	private static List<LedgerRecord> tasks()
	{
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < 60; i++)
		{
			switch (i % 3)
			{
				case 0:
					records.add(record(i, "Abyssal demons", "Catacombs", DURADEL));
					break;
				case 1:
					records.add(record(i, "Dust devils", "Smoke Dungeon", NIEVE));
					break;
				default:
					records.add(record(i, "Abyssal demons", null, null));
					break;
			}
		}
		return records;
	}

	private void show(long account, List<LedgerRecord> records)
	{
		harness.onEdt(() -> harness.historyModel().setRecords(account, records));
		harness.drain();
	}

	private List<String> titles()
	{
		return onEdt(() -> history().getTitleTexts());
	}

	@Test
	public void eachFilterListsOnlyTheValuesInTheHistoryAlphabeticallyWithTheUnknownLast()
	{
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("no history yet", Arrays.asList(LedgerHistory.ALL),
			onEdt(() -> history().getLocationFilterOptions()));
		assertEquals(Arrays.asList(LedgerHistory.ALL), onEdt(() -> history().getMasterFilterOptions()));

		show(ACCOUNT, tasks());
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Abyssal demons", "Dust devils"),
			onEdt(() -> history().getFilterOptions()));
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Catacombs", "Smoke Dungeon", HistoryFilter.NO_LOCATION_LABEL),
			onEdt(() -> history().getLocationFilterOptions()));
		assertEquals(Arrays.asList(LedgerHistory.ALL, DURADEL_NAME, NIEVE_NAME, HistoryFilter.UNKNOWN_MASTER),
			onEdt(() -> history().getMasterFilterOptions()));
		assertEquals("All | All | All", onEdt(() -> history().getFilterSelections()));
	}

	@Test
	public void eachFilterAloneAndTogetherPagesTheFilteredList()
	{
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		show(ACCOUNT, tasks());
		assertEquals("Showing 25 of 60 tasks", onEdt(() -> history().getShowMoreTooltip()));

		// Location alone: 20 Smoke Dungeon tasks, one page.
		harness.onEdt(() -> history().selectLocationFilter("Smoke Dungeon"));
		assertEquals(20, (int) onEdt(() -> history().getRowCount()));
		assertNull(onEdt(() -> history().getShowMoreText()));
		assertTrue(titles().stream().allMatch(t -> t.startsWith("Dust devils")));
		harness.onEdt(() -> history().selectLocationFilter(LedgerHistory.ALL));

		// Master alone: 20 tasks without a known master.
		harness.onEdt(() -> history().selectMasterFilter(HistoryFilter.UNKNOWN_MASTER));
		assertEquals(20, (int) onEdt(() -> history().getRowCount()));

		// Monster alone: 40 Abyssal demons tasks, paged by 25.
		harness.onEdt(() ->
		{
			history().selectMasterFilter(LedgerHistory.ALL);
			history().selectFilter("Abyssal demons");
		});
		assertEquals(25, (int) onEdt(() -> history().getRowCount()));
		assertEquals("Show 15 more", onEdt(() -> history().getShowMoreText()));
		assertEquals("Showing 25 of 40 tasks", onEdt(() -> history().getShowMoreTooltip()));
		harness.onEdt(() -> history().clickShowMore());
		assertEquals(40, (int) onEdt(() -> history().getRowCount()));
		assertNull(onEdt(() -> history().getShowMoreText()));

		// Another value in a second filter: back to the first page of what both match.
		harness.onEdt(() -> history().selectLocationFilter(HistoryFilter.NO_LOCATION));
		assertEquals(20, (int) onEdt(() -> history().getRowCount()));
		assertEquals("Abyssal demons | No location | All", onEdt(() -> history().getFilterSelections()));
		assertNull(onEdt(() -> history().getEmptyText()));

		// Together they can match nothing: the list says so, and the filters stay to change.
		harness.onEdt(() -> history().selectMasterFilter(DURADEL_NAME));
		assertEquals(0, (int) onEdt(() -> history().getRowCount()));
		assertEquals("<html>" + HistoryListSection.NO_MATCHES + "</html>", onEdt(() -> history().getEmptyText()));
		assertNull(onEdt(() -> history().getShowMoreText()));
		harness.onEdt(() -> history().selectLocationFilter("Catacombs"));
		assertEquals(20, (int) onEdt(() -> history().getRowCount()));
		assertNull(onEdt(() -> history().getEmptyText()));
	}

	@Test
	public void aValueThatDisappearsGoesBackToAllFromTheFirstPage()
	{
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		List<LedgerRecord> records = tasks();
		show(ACCOUNT, records);
		harness.onEdt(() ->
		{
			history().selectFilter("Abyssal demons");
			history().selectMasterFilter(HistoryFilter.UNKNOWN_MASTER);
		});
		assertEquals(20, (int) onEdt(() -> history().getRowCount()));

		// The tasks without a master are gone (deleted): Master goes back to "All", Monster stays.
		List<LedgerRecord> withMasters = new ArrayList<>();
		for (LedgerRecord record : records)
		{
			if (record.getSlayerMaster() != null)
			{
				withMasters.add(record);
			}
		}
		show(ACCOUNT, withMasters);
		assertEquals("Abyssal demons | All | All", onEdt(() -> history().getFilterSelections()));
		assertEquals(Arrays.asList(LedgerHistory.ALL, DURADEL_NAME, NIEVE_NAME),
			onEdt(() -> history().getMasterFilterOptions()));
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Catacombs", "Smoke Dungeon"),
			onEdt(() -> history().getLocationFilterOptions()));
		assertEquals(20, (int) onEdt(() -> history().getRowCount()));
		assertNull(onEdt(() -> history().getShowMoreText()));
	}

	@Test
	public void anotherAccountStartsWithEveryFilterOnAll()
