			assertTrue(name, onEdt(() -> history().widenFilterList(name)));
		}
		int list = onEdt(() -> history().getFilterListPreferredWidth("history.locationFilter"));
		assertTrue("the open list fits the long name: " + list + " > " + box, list > box);
