package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.concurrent.Future;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The Keep/Discard dialog that Stop shows for an unfinished task while "Confirm before saving incomplete tasks" is on
 * (the default), through the plugin's wiring ({@link PluginHarness}, with the dialog's answer scripted): Keep saves one
 * partial record, Discard saves none, and a dialog still open when the plugin is turned off or the client exits is
 * saved as partial exactly once, with the late answer saving nothing more (checked by the work it queues, as the ledger
 * also skips a record id it already holds). Each test also checks the account's
 * active-session file, which the logout before Stop has written. {@link SaveDecisionTest} covers the decision itself.
 */
public class HarnessKeepDiscardPromptTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The id of the session Stop ends; its active-session file was written at the logout. */
	private String sessionId;

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);

		// Two kills, then a logout and login, so the session has an active-session file when Stop is pressed.
		assertTrue(harness.startNow());
		harness.setRemaining(8);
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.tick();

		final SessionSnapshot active = harness.activeSession(ACCOUNT);
		assertNotNull(active);
		sessionId = active.getSessionId();
		assertTrue(harness.records(ACCOUNT).isEmpty());
	}

	/** The account's one record: the partial session Stop ended. */
	private void assertOnePartialRecord()
	{
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isPartial());
		assertFalse(record.isCompleted());
		assertEquals(sessionId, record.getId());
		assertEquals(TASK_NAME, record.getMonster());
		assertEquals(2, record.getKills());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.BONES));
	}

	@Test
	public void keepSavesOnePartialRecord()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.KEEP);
		harness.endTask();

		assertEquals(1, harness.promptsShown());
		assertOnePartialRecord();
		assertNull("the active file goes once the record is saved", harness.activeSession(ACCOUNT));
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());

		harness.clientShutdown();
		harness.shutDown();
		assertOnePartialRecord();
		assertNull(harness.persistedSession(ACCOUNT));
	}

	@Test
	public void discardSavesNothingAndRemovesTheActiveFile()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.DISCARD);
		harness.endTask();

		assertEquals(1, harness.promptsShown());
		assertTrue(harness.records(ACCOUNT).isEmpty());
		assertNull("a discarded session is not restored later", harness.activeSession(ACCOUNT));
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());

		harness.clientShutdown();
		harness.shutDown();
		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("nothing restored", SessionTracker.State.IDLE, harness.sessionState());
		assertTrue(harness.records(ACCOUNT).isEmpty());
		assertNull(harness.persistedSession(ACCOUNT));
	}

	@Test
	public void keepAnsweredAfterTheDialogWasOpenSavesOnce()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.LEAVE_OPEN);
		harness.endTask();
		assertTrue(harness.isPromptOpen());
		assertTrue("nothing saved while the dialog is open", harness.records(ACCOUNT).isEmpty());
		assertNotNull(harness.activeSession(ACCOUNT));

		assertTrue("Keep queues the save", harness.answerOpenPrompt(true) > 0);
		assertFalse(harness.isPromptOpen());
		assertOnePartialRecord();
		assertNull(harness.persistedSession(ACCOUNT));

		harness.clientShutdown();
		harness.shutDown();
		assertOnePartialRecord();
		assertEquals(1, harness.promptsShown());
	}

	@Test
	public void pluginShutDownWhileTheDialogIsOpenSavesThePartialOnce()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.LEAVE_OPEN);
		harness.endTask();
		assertTrue(harness.isPromptOpen());

		harness.shutDown();
		assertOnePartialRecord();
		assertNull(harness.persistedSession(ACCOUNT));

		// The dialog outlives the plugin; its late answer saves nothing more.
		assertTrue(harness.isPromptOpen());
		assertEquals("the late Keep queues no second save", 0, harness.answerOpenPrompt(true));
		assertOnePartialRecord();
		assertNull(harness.persistedSession(ACCOUNT));
		assertEquals(1, harness.promptsShown());
	}

	@Test
	public void pluginShutDownWhileTheDialogIsOpenKeepsThePartialWhenDiscardIsAnsweredLate()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.LEAVE_OPEN);
		harness.endTask();

		harness.shutDown();
		assertEquals("the late Discard queues no delete", 0, harness.answerOpenPrompt(false));
		assertOnePartialRecord();
		assertNull(harness.persistedSession(ACCOUNT));
	}

	@Test
	public void clientExitWhileTheDialogIsOpenSavesThePartialOnceAndWaitsForIt()
	{
		harness.scriptKeepDiscardPrompt(PluginHarness.PromptAnswer.LEAVE_OPEN);
		harness.endTask();
		assertTrue(harness.isPromptOpen());

		final List<Future<?>> waitedFor = harness.clientShutdown();
		assertEquals("the client waits for the partial's save and the Ended assignment's marker", 2,
			waitedFor.size());
		for (Future<?> write : waitedFor)
		{
			assertTrue(write.isDone());
		}
		assertOnePartialRecord();
		assertNull(harness.persistedSession(ACCOUNT));
		assertTrue("End task keeps the assignment Ended", harness.activeSession(ACCOUNT).isEndedMarker());

		// The plugin is stopped as the client closes, then the dialog's late answer comes; neither saves again.
		harness.shutDown();
		assertEquals("the late Keep queues no second save", 0, harness.answerOpenPrompt(true));
		assertOnePartialRecord();
		assertNull(harness.persistedSession(ACCOUNT));
		assertEquals(1, harness.promptsShown());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.SwingUtilities;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Where the ledger files live and when that is decided: the descriptor names the plugin directory and the legacy
 * directory RuneLite migrates, the directory is resolved once on the executor (never the client thread or the EDT),
 * and a directory that cannot be resolved leaves the plugin running without saving, through startUp, saves and
 * shutDown. The migration itself is RuneLite's ({@code Plugin#getPluginDirectory}) and is not exercised here: tests
 * never call it, so they never touch {@code ~/.runelite}.
 */
public class HarnessLedgerDirectoryTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** Thread descriptions of every directory resolution: "executor", "client thread", "EDT" or "other". */
	private final List<String> resolvedOn = new CopyOnWriteArrayList<>();
	private final AtomicInteger failuresLeft = new AtomicInteger();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		final Filepath directory = Filepath.Unchecked.getRooted(harness.ledgerDirectory().toPath());
		harness.plugin.setLedgerDirectorySource(() ->
		{
			resolvedOn.add(currentThread());
			if (failuresLeft.getAndUpdate(n -> Math.max(0, n - 1)) > 0)
			{
				throw new IOException("plugin directory unavailable");
			}
			return directory;
		});
	}

	private String currentThread()
	{
		if (harness.executor.isRunningTask())
		{
			return "executor";
		}
		if (SwingUtilities.isEventDispatchThread())
		{
			return "EDT";
		}
		return harness.isClientThread() ? "client thread" : "other";
	}

	/** Logs in on the task, plays and kills two of the ten. */
	private void loginPlayAndKillTwo()
	{
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.setRemaining(8);
		harness.lootOnNextTick(ItemID.BONES, 1);
		harness.tick();
	}

	private String[] savedFiles()
	{
		return harness.ledgerDirectory().list();
	}

	@Test
	public void descriptorNamesThePluginDirectoryAndTheLegacyDirectory()
	{
		final PluginDescriptor descriptor = SlayerLedgerPlugin.class.getAnnotation(PluginDescriptor.class);
		assertNotNull(descriptor);
		assertEquals("slayer-ledger", descriptor.internalName());
		assertEquals("slayer-ledger", descriptor.legacyDataDirectory());

		// getPluginDirectory joins these as single segments (the legacy one must not be a RuneLite directory); both
		// throw for an unusable name. Only paths are built here, nothing is read or written.
		final Path fakeRuneLiteDir = harness.ledgerDirectory().toPath();
		assertEquals("slayer-ledger", Filepath.Unchecked.getRooted(fakeRuneLiteDir.resolve("plugin-data"))
			.joinSegment(descriptor.internalName()).getFileName());
		assertEquals("slayer-ledger", Filepath.Unchecked.getLegacyPluginDirectory(fakeRuneLiteDir,
			descriptor.legacyDataDirectory()).getFileName());
	}

	@Test
	public void directoryIsResolvedOnceOnTheExecutorAtStartUp()
	{
		harness.startUp();
		assertEquals("resolved by startUp's executor task", 1, resolvedOn.size());
		assertEquals("executor", resolvedOn.get(0));

		loginPlayAndKillTwo();
		harness.endTask();
		harness.onlyRecord(ACCOUNT);
		harness.shutDown();
		assertEquals("kept for the plugin's lifetime", 1, resolvedOn.size());
	}

	@Test
	public void failedResolutionKeepsThePluginRunningWithoutSaving()
	{
		failuresLeft.set(Integer.MAX_VALUE);
		harness.startUp();
		loginPlayAndKillTwo();
		assertEquals("tracking still works", 2, harness.tracker().getKills());

		harness.endTask();
		assertEquals(SessionTracker.State.IDLE, harness.sessionState());
		harness.trackAgain();
		assertTrue(harness.startNow());
		harness.setRemaining(7);
		harness.tick();
		// Shutdown with a running session tries to persist it and fails quietly (logged), like any IO failure.
		harness.shutDown();

		assertEquals("nothing written", 0, savedFiles().length);
		assertTrue("each operation tried again", resolvedOn.size() > 2);
		assertTrue(resolvedOn.stream().allMatch("executor"::equals));
	}

	@Test
	public void resolutionThatFailedAtStartUpIsRetriedByTheNextOperation()
	{
		failuresLeft.set(1);
		harness.startUp();
		assertEquals(1, resolvedOn.size());
		loginPlayAndKillTwo();
		harness.endTask();

		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(2, record.getKills());
		assertNull(harness.activeSession(ACCOUNT));
		assertEquals("resolved by the history load after login, then kept", 2, resolvedOn.size());
		assertFalse(resolvedOn.contains("client thread"));
		assertFalse(resolvedOn.contains("EDT"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.NavigationButton;
import org.junit.Rule;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

/**
 * Plugin start and stop through the client's wiring ({@link PluginHarness}): registration with a real event bus, the
 * sidebar button, the completion grace ticker's registration, and recovery from a failed start.
 */
public class HarnessLifecycleTest
{
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void startedPluginReceivesEventsFromTheEventBus()
	{
		harness.startUp();
		assertFalse("logged out", harness.tracker().isTaskObserved());

		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.login(PluginHarness.ACCOUNT);
		harness.ticks(PluginHarness.SETTLE_TICKS - 1);
		assertFalse("task not read while the login settles", harness.tracker().isTaskObserved());
		harness.tick();

		// Only true if onGameStateChanged and onGameTick both ran.
		assertTrue(harness.tracker().isTaskObserved());
		assertEquals(TASK_NAME, harness.tracker().getCurrentMonster());
		assertEquals(10, harness.tracker().getCurrentRemaining());
	}

	@Test
	public void navigationButtonIsAddedOnStartAndRemovedOnStop()
	{
		harness.startUp();
		ArgumentCaptor<NavigationButton> added = ArgumentCaptor.forClass(NavigationButton.class);
		verify(harness.clientToolbar).addNavigation(added.capture());
		assertEquals("Slayer Ledger", added.getValue().getTooltip());
		assertNotNull(added.getValue().getPanel());
		verify(harness.clientToolbar, never()).removeNavigation(any());

		harness.shutDown();
		verify(harness.clientToolbar).removeNavigation(added.getValue());
	}

	@Test
	public void stoppedPluginIgnoresEvents()
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		harness.shutDown();

		// Neither the plugin nor its grace ticker is left subscribed, so no handler of the plugin reads the client.
		final int callsWhenStopped = harness.pluginCallCount();
		assertTrue("the running plugin read the client, so the count works", callsWhenStopped > 0);
		harness.setRemaining(9);
		harness.ticks(3);
		harness.lootOnNextTick(526, 1);
		harness.tick();
		harness.postLoot(526, 1);
		harness.chat(ChatMessageType.GAMEMESSAGE, "You pick the man's pocket.");
		harness.clickMenu("Drop", 526);
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.localPlayerDies();
		harness.hop();
		harness.logout();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertEquals("client calls by a stopped plugin", callsWhenStopped, harness.pluginCallCount());

		assertEquals("no kill started a session", SessionTracker.State.IDLE, harness.sessionState());
		assertTrue(harness.records(PluginHarness.ACCOUNT).isEmpty());
		assertNull(harness.activeSession(PluginHarness.ACCOUNT));
	}

	/**
	 * startUp (EDT) only queues the reset of the client-thread state, and the handlers are registered right after it, so
	 * a client frame may post events before that block runs. Until it has, the handlers do nothing: no client reads, and
	 * nothing from the previous run (here a settled login, which would read the task at once).
	 */
	@Test
	public void handlersWaitForTheStartUpResetOfClientThreadState()
	{
		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		harness.shutDown();

		harness.startUpWithoutDrain();
		final int callsBeforeReset = harness.pluginCallCount();
		harness.postWithoutDrain(new GameTick());
		final GameStateChanged loggedIn = new GameStateChanged();
		loggedIn.setGameState(GameState.LOGGED_IN);
		harness.postWithoutDrain(loggedIn);
		harness.postWithoutDrain(new ChatMessage(null, ChatMessageType.GAMEMESSAGE, "", "You pick the man's pocket.",
			null, 0));
		assertEquals("no handler read the client before the reset", callsBeforeReset, harness.pluginCallCount());
		assertFalse("the task was not read with the previous run's state", harness.tracker().isTaskObserved());
		assertFalse(harness.tracker().isTaskObserved());

		// The block reads the game state and account itself, so the skipped GameStateChanged loses nothing; the login
		// settles afresh before the task is read.
		harness.drain();
		harness.ticks(PluginHarness.SETTLE_TICKS - 1);
		assertFalse("task not read while the login settles", harness.tracker().isTaskObserved());
		harness.tick();
		assertTrue(harness.tracker().isTaskObserved());
		assertEquals(10, harness.tracker().getCurrentRemaining());
	}

	@Test
	public void startingWhileLoggedInPicksUpTheAccountAndTask()
	{
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.setAccountHash(PluginHarness.ACCOUNT);
		harness.setGameStateSilently(GameState.LOGGED_IN);

		harness.startUp();
		harness.ticks(PluginHarness.SETTLE_TICKS);

		assertTrue(harness.tracker().isTaskObserved());
		assertTrue(harness.startNow());
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals(PluginHarness.ACCOUNT, harness.tracker().getSessionAccountHash());
	}

	@Test
	public void failedStartUpIsCleanedUpByShutDown()
	{
		doThrow(new IllegalStateException("toolbar unavailable")).when(harness.clientToolbar).addNavigation(any());
		try
		{
			harness.startUp();
			fail("startUp should have failed");
		}
		catch (IllegalStateException e)
		{
			assertEquals("toolbar unavailable", e.getMessage());
			assertEquals("shutDown after the failed startUp threw", 0, e.getSuppressed().length);
		}
		assertFalse(harness.isRunning());
		ArgumentCaptor<NavigationButton> button = ArgumentCaptor.forClass(NavigationButton.class);
		verify(harness.clientToolbar).addNavigation(button.capture());
		verify(harness.clientToolbar).removeNavigation(button.getValue());

		// Nothing is left subscribed: game events after the failed start reach nothing and throw nothing.
		harness.setTask(TASK, TASK_NAME, 10, 10);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertFalse(harness.tracker().isTaskObserved());
	}

	@Test
	public void pluginStartsNormallyAfterAFailedStart()
	{
		doThrow(new IllegalStateException("toolbar unavailable")).doNothing()
			.when(harness.clientToolbar).addNavigation(any());
		try
		{
			harness.startUp();
			fail("startUp should have failed");
		}
		catch (IllegalStateException expected)
		{
			// Retried below.
		}

		harness.startUp();
		harness.setTask(TASK, TASK_NAME, 3, 3);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertTrue(harness.startNow());
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.tick();
		assertTrue("the ticker counts each tick once", harness.tracker().hasPendingCompletion());
		harness.tick();
		assertTrue(harness.onlyRecord(PluginHarness.ACCOUNT).isCompleted());
	}

	@Test
	public void shutDownWithoutStartUpDoesNotThrow()
	{
		harness.onEdt(harness.plugin::shutDown);
		verify(harness.clientToolbar, never()).removeNavigation(any());
	}

	@Test
	public void restartDoesNotRegisterTheGraceTickerTwice()
	{
		harness.startUp();
		harness.shutDown();
		harness.startUp();
		verify(harness.clientToolbar, times(2)).addNavigation(any());

		harness.setTask(TASK, TASK_NAME, 3, 3);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		assertTrue(harness.startNow());
		harness.setRemaining(1);
		harness.tick();
		harness.completeTask();
		harness.tick();

		// Held on the completion tick, then two more ticks. A second ticker registration would halve the window.
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		assertTrue(harness.records(PluginHarness.ACCOUNT).isEmpty());
		harness.tick();
		assertFalse(harness.tracker().hasPendingCompletion());
		LedgerRecord record = harness.onlyRecord(PluginHarness.ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(3, record.getKills());
	}

	@Test
	public void restartKeepsTheSameNavigationLifecycle()
	{
		harness.startUp();
		harness.shutDown();
		harness.startUp();
		harness.shutDown();
		ArgumentCaptor<NavigationButton> added = ArgumentCaptor.forClass(NavigationButton.class);
		verify(harness.clientToolbar, times(2)).addNavigation(added.capture());
		ArgumentCaptor<NavigationButton> removed = ArgumentCaptor.forClass(NavigationButton.class);
		verify(harness.clientToolbar, times(2)).removeNavigation(removed.capture());
		assertSame(added.getAllValues().get(0), removed.getAllValues().get(0));
		assertSame(added.getAllValues().get(1), removed.getAllValues().get(1));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Function;
import java.util.function.Supplier;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.ui.PluginPanel;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The sidebar's shell in direction A as wired in the plugin, read through {@link PanelProbe}: the
 * status strip's words and buttons per state, the live task card's header, bar and stats in the overlay's order, the
 * supplies and loot grids and the XP under their sub-headers inside the live section, the width budget (long values
 * shown whole, a long name cut short), Trends and the Luck meter gone, and a refresh with nothing new rebuilding
 * nothing. Every refresh here is called by the test; nothing waits for the panel's refresh timer.
 */
public class HarnessLiveCardTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final long MINUTE = 60_000;
	private static final int TASK = 42;
	private static final String DEMONS = "Abyssal demons";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The tracker's clock, so active time, pace and the time left are under the test's control. */
	private final AtomicLong now = new AtomicLong(1_000_000_000L);

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		// The client's stats have arrived (Hitpoints above 0), so the XP the tests gain counts from this baseline.
		harness.setSkillXp(Skill.SLAYER, 1_000_000);
		harness.setSkillXp(Skill.HITPOINTS, 2_000_000);
		harness.startUp();
		harness.setTrackerClock(now::get);
		harness.setTask(TASK, DEMONS, 201, 201);
		harness.loginAndSettle(ACCOUNT);
	}

	private <T> T onEdt(Supplier<T> read)
	{
		List<T> result = new ArrayList<>(1);
		harness.onEdt(() -> result.add(read.get()));
		return result.get(0);
	}

	/** Refreshes the panel, as its timer would, then reads it. */
	private <T> T refreshed(Function<PanelProbe, T> read)
	{
		return onEdt(() ->
		{
			harness.panel().refresh();
			return read.apply(harness.ui());
		});
	}

	/** Starts a session and kills 3 in a minute: 198 of 201 left. */
	private void threeKillsInAMinute()
	{
		assertTrue(harness.startNow());
		now.addAndGet(MINUTE);
		harness.setRemaining(198);
		harness.tick();
	}

	@Test
	public void theStatusStripSaysTheStateInWordsAndShowsOnlyTheValidButtons()
	{
		assertEquals("no Pause before the first kill", "Waiting for first kill | End task",
			refreshed(PanelProbe::getStatusStrip));
		assertEquals("", refreshed(PanelProbe::getStatusClock));

		assertTrue(harness.startNow());
		now.addAndGet(21 * MINUTE + 54_000);
		assertEquals("Running | Pause | End task", refreshed(PanelProbe::getStatusStrip));
		assertEquals("the elapsed clock, m:ss under an hour", "21:54", refreshed(PanelProbe::getStatusClock));
		now.addAndGet(41 * MINUTE + 37_000);
		assertEquals("then h:mm:ss", "1:03:31", refreshed(PanelProbe::getStatusClock));

		harness.pause();
		assertEquals("Paused | Resume | End task", refreshed(PanelProbe::getStatusStrip));
		assertEquals("no clock while paused", "", refreshed(PanelProbe::getStatusClock));
		assertTrue(harness.resume());
		assertEquals("Running | Pause | End task", refreshed(PanelProbe::getStatusStrip));

		harness.endTask();
		assertEquals("Ended | Track again", refreshed(PanelProbe::getStatusStrip));
		harness.trackAgain();
		assertEquals("Waiting for first kill | End task", refreshed(PanelProbe::getStatusStrip));

		harness.setTask(TASK, DEMONS, 0, 201);
		harness.ticks(3);
		assertEquals("no buttons without a task", "No task", refreshed(PanelProbe::getStatusStrip));
		assertFalse(refreshed(PanelProbe::isPauseButtonShown));
		assertFalse(refreshed(PanelProbe::isEndButtonShown));
	}

	@Test
	public void theCardShowsTheHeaderTheBarAndTheStatsInTheOverlaysOrder()
	{
		// Before the first kill: the header only, its master line with the task's size.
		assertEquals(Arrays.asList(DEMONS, "201 left"), refreshed(ui -> ui.getTaskBox().getRows()));
		assertTrue(refreshed(ui -> ui.getTaskBox().getDetailsTooltip()).contains("Kills left: 201"));
		assertTrue(refreshed(ui -> ui.getTaskBox().getTaskTooltip()).contains("Kills left: 201"));
		assertEquals("the task's item sprite, 36 by 32", TaskIcons.itemId(DEMONS) + " 36x32",
			refreshed(PanelProbe::getTaskIcon));
		assertFalse("no stats before the first kill", refreshed(PanelProbe::isStatsShown));
		assertNull("no bar before the first kill", refreshed(PanelProbe::getBarText));

		// A session with no kills yet: the stats have the kills left, so the master line doesn't; what isn't known
		// yet is ?.
		assertTrue(harness.startNow());
		assertEquals(Collections.singletonList(DEMONS), refreshed(ui -> ui.getTaskBox().getRows()));
		assertEquals(Arrays.asList(
			"Kills left | 201", "Time left | ?",
			"Pace | ?", "Kills/h | ?",
			"Elapsed | 0:00", "Superiors | 0",
			"Profit | ?", "XP | 0"), refreshed(PanelProbe::getStatsRows));

		// 3 kills in a minute.
		now.addAndGet(MINUTE);
		harness.setRemaining(198);
		harness.tick();
		harness.postLoot(ItemID.BONES, 3);
		harness.gainXp(Skill.SLAYER, 1_500);
		harness.ticks(2);

		assertEquals("3 / 201", refreshed(PanelProbe::getBarText));
		assertEquals(1, (int) refreshed(PanelProbe::getBarPercentage));
		assertEquals(Arrays.asList(
			"Kills left | 198", "Time left | ~1h 06m",
			"Pace | 0:20/kill", "Kills/h | 180",
			"Elapsed | 1:00", "Superiors | 0",
			"Profit | +300", "XP | 1,500"), refreshed(PanelProbe::getStatsRows));
		// The one key number is Kills left, in Bold; a gain is green and signed, never the colour alone.
		assertEquals(LedgerTheme.KEY, refreshed(ui -> ui.statColor("killsLeft")));
		assertEquals(LedgerTheme.GOOD, refreshed(ui -> ui.statColor("profit")));
		assertTrue(refreshed(ui -> ui.statTooltip("xp")).contains("Slayer"));

		// Deaths and bank trips: a fifth row once either happened.
		harness.localPlayerDies();
		harness.tick();
		List<String> rows = refreshed(PanelProbe::getStatsRows);
		assertEquals(Arrays.asList("Deaths | 1", "Bank trips | 0"), rows.subList(8, 10));

		harness.endTask();
		assertFalse("no stats once the session ended", refreshed(PanelProbe::isStatsShown));
		assertNull(refreshed(PanelProbe::getBarText));
		assertEquals("the master line has the task's size again", Arrays.asList(DEMONS, "198 left"),
			refreshed(ui -> ui.getTaskBox().getRows()));
	}

	@Test
	public void theGridsAndTheXpAreInTheLiveSectionUnderSubHeaders()
	{
		threeKillsInAMinute();
		harness.postLoot(ItemID.BONES, 3);
		harness.gainXp(Skill.SLAYER, 1_500);
		harness.ticks(2);

		List<String> order = refreshed(PanelProbe::getContentOrder);
		int card = order.indexOf("liveCard");
		assertTrue(order.toString(), order.indexOf("session") < card);
		assertTrue(order.toString(), card < order.indexOf("liveSupplies"));
		assertTrue(order.toString(), order.indexOf("liveSupplies") < order.indexOf("liveLoot"));
		assertTrue(order.toString(), order.indexOf("liveLoot") < order.indexOf("liveXp"));
		assertTrue("the advisor's place comes after the live section: " + order,
			order.indexOf("liveXp") < order.indexOf("advisor"));

		assertEquals("Supplies used | 0", refreshed(ui -> ui.getLiveSupplies().getHeaderText()));
		assertEquals(Collections.singletonList("None"), refreshed(ui -> ui.getLiveSupplies().getCellTexts()));
		assertEquals("Loot | 300", refreshed(ui -> ui.getLiveLoot().getHeaderText()));
		assertEquals(Collections.singletonList("Bones | " + ItemID.BONES + " x3"),
			refreshed(ui -> ui.getLiveLoot().getCellTexts()));
		assertEquals("five slots to a row", 5, (int) refreshed(ui -> ui.getLiveLoot().getSlotCount()));
		assertEquals("XP gained | 90K/h", refreshed(ui -> ui.getLiveXp().getHeaderText()));
		assertEquals(Collections.singletonList("Slayer | 1,500"), refreshed(ui -> ui.getLiveXp().getLineTexts()));

		// Flat sub-headers (DESIGN_PRINCIPLES.md 3.4): Bold in the heading colour over a 1 px rule, the value on the
		// right. (The lists nested in Overall totals' blocks are quieter: HarnessOverallTotalsTest.)
		assertEquals("Bold heading | Small value | rule", refreshed(ui -> ui.getLiveLoot().getHeaderLook()));
		assertEquals("Bold heading | Small value | rule", refreshed(ui -> ui.getLiveSupplies().getHeaderLook()));
		assertEquals("Bold heading | Small value | rule", refreshed(ui -> ui.getLiveXp().getHeaderLook()));
	}

	/**
	 * Lays the panel out at the sidebar's width with the scroll bar showing, then reads it. RuneLite's PluginPanel is
	 * 225 px wide beside its 17 px scroll bar: 213 px of content (DESIGN_PRINCIPLES.md 3.1), the live card as wide,
	 * 199 px inside it.
	 */
	private <T> T laidOut(Function<PanelProbe, T> read)
	{
		Object[] result = refreshed(ui -> new Object[]{ui.layOutLiveCard(), read.apply(ui)});
		Object[] widths = (Object[]) result[0];
		assertEquals("the panel", PluginPanel.PANEL_WIDTH, widths[0]);
		assertEquals("the content and the card", PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET, widths[1]);
		@SuppressWarnings("unchecked")
		T value = (T) result[1];
		return value;
	}

	@Test
	public void longValuesShowWholeAtTheSidebarsWidthWithTheirFullTextInTheTooltip()
	{
		// A long task: 2,000 kills in 10:03:31 of active time (0:18 a kill), 1,985 left (~9h 59m at that pace), and
		// a 1.24M drop.
		harness.defineItem(ItemID.DRAGON_BONES, "Dragon bones", 1_240_000, 1);
		harness.setTask(TASK + 1, "Dust devils", 3_985, 3_985);
		harness.tick();
		assertTrue(harness.startNow());
		now.addAndGet((10 * 3600 + 3 * 60 + 31) * 1000L);
		harness.setRemaining(1_985);
		harness.tick();
		harness.postLoot(ItemID.DRAGON_BONES, 1);
		harness.ticks(2);

		List<String> rows = Arrays.asList(
			"Kills left | 1,985", "Time left | ~9h 59m",
			"Pace | 0:18/kill", "Kills/h | 199",
			"Elapsed | 10:03:31", "Superiors | 0",
			"Profit | +1.24M", "XP | 0");
		assertEquals(rows, refreshed(PanelProbe::getStatsRows));
		// Shown whole: a grid of two equal columns cut "~9h 59m" short.
		assertEquals(rows, laidOut(PanelProbe::getStatsRowsShown));
		// The bar's label has the bar's whole width: RuneLite's bar gave it a third and cut it to "1 / 3,...".
		assertEquals("2,000 / 3,985", refreshed(PanelProbe::getBarText));
		assertEquals("2,000 / 3,985", laidOut(PanelProbe::getBarTextShown));
		List<String> tooltips = refreshed(PanelProbe::getStatsTooltips);
		for (int i = 0; i < rows.size(); i++)
		{
			String full = rows.get(i).replace(" | ", ": ");
			assertTrue("the whole value in the tooltip: " + tooltips.get(i), tooltips.get(i).startsWith(full)
				|| tooltips.get(i).startsWith("<html>" + full + "<br>"));
		}
	}

	@Test
	public void tenHoursLeftShowWholeBesideAShortClock()
	{
		// 3 kills in a minute, 1,815 left: ~10h 05m at that pace, the widest time left a task usually has.
		harness.setTask(TASK + 1, "Dust devils", 1_818, 1_818);
		harness.tick();
		assertTrue(harness.startNow());
		now.addAndGet(MINUTE);
		harness.setRemaining(1_815);
		harness.tick();

		assertEquals(Arrays.asList("Kills left | 1,815", "Time left | ~10h 05m", "Pace | 0:20/kill", "Kills/h | 180",
			"Elapsed | 1:00"), laidOut(ui -> ui.getStatsRowsShown().subList(0, 5)));
	}

	@Test
	public void aLongNameIsCutShortWithItsFullTextInTheTooltipAndNothingWidensThePanel()
	{
		String name = "Lava strykewyrms in the Wilderness Slayer Cave";
		harness.setTask(TASK + 1, name, 201, 201);
		harness.tick();
		threeKillsInAMinute();

		// No icon for a name that is no known task, so the name has the card's whole width.
		assertEquals("none", refreshed(PanelProbe::getTaskIcon));
		// The name's line as shown (PanelProbe#layOutLiveCard).
		String shown = laidOut(ui -> (String) ui.layOutLiveCard()[4]);
		assertTrue(shown, shown.endsWith(FitLabel.ELLIPSIS));
		assertTrue(shown, name.startsWith(shown.substring(0, shown.length() - 1)));
		assertTrue(refreshed(ui -> ui.getTaskBox().getTaskTooltip()).contains(name));
		assertEquals("the full name is kept", Collections.singletonList(name),
			refreshed(ui -> ui.getTaskBox().getRows()));
		assertTrue("the setup toggles fit the card", refreshed(PanelProbe::getLiveSetupPreferredWidth) <= 199);
		int widest = refreshed(PanelProbe::getLiveSectionPreferredWidth);
		assertTrue("nothing in the live section asks for more than the content's 213 px: " + widest,
			widest <= PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET);
	}

	@Test
	public void trendsAndTheLuckMeterAreGone()
	{
		assertEquals(Arrays.asList(SlayerLedgerPanel.OptionalSection.OVERALL_TOTALS,
			SlayerLedgerPanel.OptionalSection.SKIPPED_BLOCKED),
			Arrays.asList(SlayerLedgerPanel.OptionalSection.values()));
		for (String part : new String[]{"trendsBlock", "trends.header", "luckBlock", "luck.header"})
		{
			assertFalse(part, onEdt(() -> harness.ui().isInPanel(part)));
		}
		assertNull("the drop snapshot is no longer bundled",
			SlayerLedgerPlugin.class.getResource("slayer-drop-snapshot.json"));
	}

	@Test
	public void aRefreshWithNothingNewRebuildsNothing()
	{
		threeKillsInAMinute();
		harness.postLoot(ItemID.BONES, 3);
		harness.gainXp(Skill.SLAYER, 1_500);
		harness.ticks(2);
		Function<PanelProbe, List<Integer>> builds = ui -> Arrays.asList(ui.getLiveCardBuildCount(),
			ui.getLiveListsBuildCount(), ui.getLiveSetupBuildCount());
		List<Integer> before = refreshed(builds);
		for (int i = 0; i < 5; i++)
		{
			assertEquals(before, refreshed(builds));
		}

		// New loot redraws the grids, not the card's icon or the setup toggles.
		harness.postLoot(ItemID.BONES, 1);
		harness.ticks(2);
		List<Integer> after = refreshed(builds);
		assertEquals(before.get(0), after.get(0));
		assertTrue(after.toString(), after.get(1) > before.get(1));
		assertEquals(before.get(2), after.get(2));
		assertEquals("and then nothing again", after, refreshed(builds));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The panel's live session lines as wired in the plugin ({@link PluginHarness}): the time-left line, live values
 * that belong to another session, and the valuation throttle when pricing fails. {@link TaskTimeEstimateTest} and
 * {@link SessionValuationTest} cover the calculations.
 */
public class HarnessLiveValuesTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** A valuation that throws (an unexpected failure) until {@link #fail} is cleared, counting its calls. */
	private static final class FailingValuation extends SessionValuation
	{
		volatile boolean fail = true;
		int attempts;

		@Override
		Values update(String sessionId, ItemTally loot, ItemTally supplies, Map<Integer, Integer> doses,
			LootPriceMode mode, HiddenLoot hidden, ItemValuation.PriceLookup lookup, int tick)
		{
			attempts++;
			if (fail)
			{
				throw new IllegalStateException("valuation failure (set by the test)");
			}
			return super.update(sessionId, loot, supplies, doses, mode, hidden, lookup, tick);
		}
	}

	/** Stands {@code valuation} in for the plugin's live session valuation. */
	private void replaceSessionValuation(SessionValuation valuation)
	{
		harness.plugin.setSessionValuation(valuation);
	}

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Refreshes the panel from the tracker (as its timer does) and returns whether the time-left line is shown. */
	private boolean timeLeftShown()
	{
		final boolean[] shown = new boolean[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			shown[0] = harness.ui().isTimeLeftShown();
		});
		return shown[0];
	}

	private String timeLeftText()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getTimeLeftText();
		});
		return text[0];
	}

	private boolean valuesShown()
	{
		final boolean[] shown = new boolean[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			shown[0] = harness.ui().isValuesShown();
		});
		return shown[0];
	}

	@Test
	public void timeLeftIsShownOnlyWhileRunningOrPaused()
	{
		assertFalse("idle", timeLeftShown());

		assertTrue(harness.startNow());
		assertTrue("running", timeLeftShown());
		assertEquals("no kills yet", "Time left: " + LiveSessionSection.TIME_LEFT_UNKNOWN, timeLeftText());

		harness.pause();
		assertTrue("paused", timeLeftShown());

		harness.endTask();
		assertFalse("stopped", timeLeftShown());
	}

	@Test
	public void valuesOfAnotherSessionAreIgnored()
	{
		assertTrue(harness.startNow());
		harness.ticks(2);
		assertTrue("the plugin's own values are shown", valuesShown());

		final String current = harness.tracker().getSessionId();
		assertNotNull(current);
		harness.onEdt(() -> harness.panel().setSessionValues(
			SessionValuation.Values.builder().sessionId("an-ended-session").lootValue(1_000).lootGe(1_000).build()));
		assertFalse("values of another session are not shown", valuesShown());

		harness.onEdt(() -> harness.panel().setSessionValues(
			SessionValuation.Values.builder().sessionId(current).lootValue(1_000).lootGe(1_000).build()));
		assertTrue(valuesShown());
	}

	@Test
	public void newSessionWithEqualAmountsIsStillShown()
	{
		assertTrue(harness.startNow());
		harness.ticks(2);
		assertTrue(valuesShown());
		final String first = harness.tracker().getSessionId();

		// Stop and start again between ticks: the new session's values have the same (zero) amounts as the old one's.
		harness.endTask();
		harness.trackAgain();
		assertTrue(harness.startNow());
		assertNotEquals(first, harness.tracker().getSessionId());
		harness.ticks(2);
		assertTrue("the new session's values are published although the amounts are equal", valuesShown());
	}

	@Test
	public void shownValuesFilter()
	{
		SessionValuation.Values values = SessionValuation.Values.builder().sessionId("s1").build();
		assertSame(values, LiveSessionSection.shownValues(values, SessionTracker.State.RUNNING, "s1"));
		assertSame(values, LiveSessionSection.shownValues(values, SessionTracker.State.PAUSED, "s1"));
		assertNull(LiveSessionSection.shownValues(values, SessionTracker.State.RUNNING, "s2"));
		assertNull(LiveSessionSection.shownValues(values, SessionTracker.State.RUNNING, null));
		assertNull(LiveSessionSection.shownValues(values, SessionTracker.State.STOPPED, "s1"));
		assertNull(LiveSessionSection.shownValues(null, SessionTracker.State.RUNNING, "s1"));
	}

	@Test
	public void aLootPriceChangeIsValuedAtOnceButAFailingValuationStaysThrottled()
	{
		final FailingValuation valuation = new FailingValuation();
		replaceSessionValuation(valuation);
		assertTrue(harness.startNow());
		harness.ticks(1);
		assertEquals(1, valuation.attempts);

		// The next tick would be throttled; a new setting is valued on it anyway, but only once.
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.ticks(1);
		assertEquals(2, valuation.attempts);
		harness.ticks(1);
		assertEquals(2, valuation.attempts);
		harness.ticks(1);
		assertEquals(3, valuation.attempts);
	}

	@Test
	public void failingValuationIsStillThrottled()
	{
		final FailingValuation valuation = new FailingValuation();
		replaceSessionValuation(valuation);
		assertTrue(harness.startNow());
		harness.postLoot(ItemID.BONES, 1);

		// A new session is valued on its first tick.
		harness.ticks(1);
		assertEquals(1, valuation.attempts);

		// The first valuation fails, so no values have ever been shown.
		harness.ticks(9);
		// One attempt every 2 ticks, not one every tick.
		assertEquals(5, valuation.attempts);
		assertFalse(valuesShown());

		// Once valuing works again the values come back.
		valuation.fail = false;
		harness.ticks(2);
		assertTrue(valuesShown());
		harness.endTask();
		assertEquals(Long.valueOf(100), harness.onlyRecord(ACCOUNT).getLootGeValue());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.ui.PluginPanel;
import org.junit.Rule;
import org.junit.Test;

/**
 * The task icons as wired in the plugin: Task history rows and Skipped / blocked rows, through the
 * {@code ItemManager.getImage} fake on the EDT, and the masters' faces in Overall totals' By master. (The live task
 * card's icon is {@link HarnessLiveCardTest}'s.) Variants and cannon tasks show their task's icon, unknown tasks an
 * empty slot of the same size; nothing widens the sidebar; nothing is asked for while a section is closed or by the
 * refresh timer.
 */
public class HarnessMoreIconsTest
{
	/** A name that is no task, long enough to test the sidebar's width. */
	private static final String UNKNOWN = "Lava strykewyrms in the Wilderness Slayer Cave";
	private static final String SLOT = " " + ItemListView.ICON_WIDTH + "x" + ItemListView.ICON_HEIGHT;
	private static final String DUST_DEVIL = ItemID.SLAYERGUIDE_DUSTDEVIL + SLOT;
	private static final String SPECTRE = ItemID.SLAYERGUIDE_ABERRANTSPECTER + SLOT;
	private static final String EMPTY = "-" + SLOT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void historyRowsShowTheirTasksIcon()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT, versions(1)));
		harness.drain();

		assertEquals(Arrays.asList("Dust devils", "Deviant spectres",
			"Dust devils (cannon)", UNKNOWN),
			onEdt(() -> harness.ui().getHistory().getTitleTexts()));
		// A Catacombs variant and a cannon task show their task's icon; an unknown task an empty slot of the same size.
		assertEquals(Arrays.asList(DUST_DEVIL, SPECTRE, DUST_DEVIL, EMPTY),
			onEdt(() -> harness.ui().getHistory().getNameIcons()));
		int width = onEdt(() -> harness.ui().getHistory().getListPreferredWidth());
		assertTrue("wants " + width, width <= PluginPanel.PANEL_WIDTH);

		// The refresh timer asks for none.
		int before = harness.itemImageRequests();
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			harness.panel().refresh();
		});
		harness.drain();
		assertEquals(before, harness.itemImageRequests());
	}

	@Test
	public void skippedAndBlockedRowsShowTheirTasksIcon()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		List<AssignmentEntry> entries = Arrays.asList(entry("Dust devils", 3), entry("Aberrant spectres", 2),
			entry(UNKNOWN, 1));
		int before = harness.itemImageRequests();
		harness.onEdt(() ->
		{
			harness.historyModel().setAssignments(PluginHarness.ACCOUNT, entries);
			harness.panel().refresh();
		});
		harness.drain();
		assertEquals("closed: no icons", before, harness.itemImageRequests());

		harness.onEdt(() -> harness.ui().getAssignments().toggle());
		harness.drain();
		List<String> rows = onEdt(() -> harness.ui().getAssignments().getRows());
		assertTrue(rows.toString(), rows.get(0).startsWith("Dust devils | "));
		assertTrue(rows.toString(), rows.get(2).startsWith(UNKNOWN + " | "));
		assertEquals(Arrays.asList(DUST_DEVIL, SPECTRE, EMPTY),
			onEdt(() -> harness.ui().getAssignments().getNameIcons()));
		assertEquals(before + 2, harness.itemImageRequests());
		int width = onEdt(() -> harness.ui().getAssignments().getListPreferredWidth());
		assertTrue("wants " + width, width <= PluginPanel.PANEL_WIDTH);

		harness.onEdt(() -> harness.panel().refresh());
		harness.drain();
		assertEquals("the refresh timer asks for none", before + 2, harness.itemImageRequests());
	}

	@Test
	public void byMasterNamesShowTheMastersFace()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		List<LedgerRecord> records = new ArrayList<>();
		// Every master (a shared name uses one face), and a value not in the table.
		for (int master = 1; master <= SlayerMaster.MORTIMER; master++)
		{
			LedgerRecord record = monster("Dust devils");
			record.setSlayerMaster(master);
			// Newest first by master, so the groups show in table order.
			record.setEndedAt(100 - master);
			records.add(record);
		}
		LedgerRecord unknown = monster("Dust devils");
		unknown.setSlayerMaster(42);
		records.add(unknown);
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, records);
			harness.ui().getOverallTotals().clickTitle();
			harness.ui().getOverallTotals().setGrouping(OverallTotals.Grouping.MASTER);
		});
		harness.drain();

		List<String> rows = onEdt(() -> harness.ui().getOverallTotals().getRows());
		List<String> icons = onEdt(() -> harness.ui().getOverallTotals().getNameIcons());
		assertEquals(rows.size(), icons.size());
		List<String> seen = new ArrayList<>();
		for (int i = 0; i < rows.size(); i++)
		{
			String name = rows.get(i).substring(0, rows.get(i).indexOf(" | "));
			String file = MasterIcons.fileName(name);
			// A missing image (the masters/ folder deleted for the hub) is an empty slot of the same size.
			String expected = file != null && MasterIcons.class.getResource(MasterIcons.DIRECTORY + file) != null
				? "master:" + file + SLOT : EMPTY;
			assertEquals(name, expected, icons.get(i));
			seen.add(name);
		}
		assertTrue(seen.toString(), seen.contains("Duradel/Kuradal"));
		assertTrue(seen.toString(), seen.contains("Unknown master (42)"));
		assertEquals(seen.toString(), 11, seen.size());
		int width = onEdt(() -> harness.ui().getOverallTotals().getListPreferredWidth());
		assertTrue("wants " + width, width <= PluginPanel.PANEL_WIDTH);
	}

	/**
	 * {@code count} completed Konar tasks each of Dust devils, Deviant spectres (an Aberrant spectres task), Dust
	 * devils with a cannon and {@link #UNKNOWN}, newest first in that order, with Slayer XP.
	 */
	private static List<LedgerRecord> versions(int count)
	{
		List<LedgerRecord> records = new ArrayList<>();
		long ended = 1_000_000;
		for (int i = 0; i < count; i++)
		{
			records.add(at(monster("Dust devils"), ended--));
			LedgerRecord deviant = monster("Aberrant spectres");
			deviant.setVariant("Deviant spectres");
			records.add(at(deviant, ended--));
			LedgerRecord cannon = monster("Dust devils");
			cannon.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 200L));
			records.add(at(cannon, ended--));
			records.add(at(monster(UNKNOWN), ended--));
		}
		records.sort((a, b) -> Long.compare(b.getEndedAt(), a.getEndedAt()));
		return records;
	}

	private static LedgerRecord at(LedgerRecord record, long endedAt)
	{
		record.setEndedAt(endedAt);
		return record;
	}

	/** A completed Konar task of {@code name}, with Slayer XP and no values. */
	private static LedgerRecord monster(String name)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(UUID.randomUUID().toString());
		record.setMonster(name);
		record.setSlayerMaster(SlayerMaster.KONAR);
		record.setEndedAt(1);
		record.setKills(10);
		record.setActiveMillis(30 * 60_000L);
		record.setXpGained(Collections.singletonMap(SkillXp.SLAYER, 1_000L));
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}

	/** A Konar "Skipped / blocked" entry, ended at {@code endedAt}. */
	private static AssignmentEntry entry(String name, long endedAt)
	{
		AssignmentEntry entry = new AssignmentEntry();
		entry.setId(UUID.randomUUID().toString());
		entry.setMonster(name);
		entry.setSlayerMaster(SlayerMaster.KONAR);
		entry.setOutcome(AssignmentOutcome.SKIPPED);
		entry.setEndedAt(endedAt);
		return entry;
	}

	/** Reads {@code read} on the EDT. */
	private <T> T onEdt(Supplier<T> read)
	{
		AtomicReference<T> value = new AtomicReference<>();
		harness.onEdt(() -> value.set(read.get()));
		return value.get();
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
