	private static List<OverlayRows.Kind> kinds(List<OverlayRows.Row> rows)
	{
		List<OverlayRows.Kind> kinds = new ArrayList<>();
		for (OverlayRows.Row row : rows)
		{
			kinds.add(row.getKind());
		}
		return kinds;
	}

