import org.junit.Test;

/**
 * The "Skipped / blocked" section in look A (DESIGN_PRINCIPLES.md 3.8, 3.9), read through
 * {@link PanelProbe}: each entry's date, task icon and monster, outcome word and master, in quiet colours that keep
 * 4.5:1; the row's right-click menu on both of its lines; one plain line without entries; long names cut short at the
 * sidebar's width; and no rebuild by the refresh timer or the hover. {@link HarnessAssignmentLogTest} covers how
 * entries are made.
 */
public class HarnessSkippedBlockedTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final String SLOT = " " + ItemListView.ICON_WIDTH + "x" + ItemListView.ICON_HEIGHT;
	private static final String DUST_DEVIL = ItemID.SLAYERGUIDE_DUSTDEVIL + SLOT;
	private static final String EMPTY_SLOT = "-" + SLOT;
	private static final long DAY = 24L * 3_600_000L;
	private static final long ENDED = 1_760_000_000_000L;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
	}

	@Test
	public void eachEntryGivesItsDateIconMonsterOutcomeAndMaster()
	{
		AssignmentEntry skipped = entry("Dust devils", AssignmentOutcome.SKIPPED, 5, ENDED);
		AssignmentEntry blocked = entry("Gargoyles", AssignmentOutcome.BLOCKED, SlayerMaster.KONAR, ENDED - DAY);
		AssignmentEntry untracked = entry("Hellhounds", AssignmentOutcome.COMPLETED, null, ENDED - 2 * DAY);
		// Neither a date nor a master: only the first line.
		AssignmentEntry unknown = entry("Not a Slayer task", null, null, 0);
		setEntries(skipped, blocked, untracked, unknown);
		harness.onEdt(() -> harness.ui().getAssignments().toggle());

		DateTimeFormatter date = AssignmentLog.shortDate(ZoneId.systemDefault());
		List<String> rows = rows();
		assertEquals(4, rows.size());
		assertTrue(rows.get(0), rows.get(0).startsWith("Dust devils | Skipped | " + day(date, ENDED)
			+ " · Duradel/Kuradal | <html>Dust devils<br>"));
		assertTrue(rows.get(1), rows.get(1).startsWith("Gargoyles | Blocked | " + day(date, ENDED - DAY)
			+ " · Konar | <html>"));
		assertTrue(rows.get(2), rows.get(2).startsWith("Hellhounds | Completed (untracked) | "
			+ day(date, ENDED - 2 * DAY) + " | <html>"));
		assertTrue(rows.get(3), rows.get(3).startsWith("Not a Slayer task | Ended | <html>"));
		// The task's icon, or an empty slot of the same size, so the names line up.
		assertEquals(DUST_DEVIL, onEdt(() -> harness.ui().getAssignments().getNameIcons()).get(0));
		assertEquals(EMPTY_SLOT, onEdt(() -> harness.ui().getAssignments().getNameIcons()).get(3));

		// Quieter than the rest (Small, the label and hint colours), never below 4.5:1 on the page or under the mouse:
		// the hover is the card's stone, and LedgerThemeTest checks every text token on the page and the card.
		assertEquals(Arrays.asList(LedgerTheme.LABEL, LedgerTheme.LABEL, LedgerTheme.HINT),
			onEdt(() -> harness.ui().getAssignments().getRowColors(0)));
		assertEquals(Arrays.asList(LedgerTheme.LABEL, LedgerTheme.LABEL),
			onEdt(() -> harness.ui().getAssignments().getRowColors(3)));
		assertEquals(LedgerTheme.CARD, LedgerTheme.HOVER);
	}

	@Test
	public void rightClickingEitherLineOfAnEntryOpensItsMenuWithDeleteOnlyForAnEntryWithAnId()
	{
		AssignmentEntry withId = entry("Dust devils", AssignmentOutcome.SKIPPED, 5, ENDED);
		// LedgerStore.deleteAssignment matches by id, so an entry without one can't be deleted safely.
		AssignmentEntry withoutId = entry("Gargoyles", AssignmentOutcome.BLOCKED, SlayerMaster.KONAR, ENDED - DAY);
		withoutId.setId(null);
		setEntries(withId, withoutId);
		harness.onEdt(() -> harness.ui().getAssignments().toggle());
		assertEquals(2, rows().size());

		assertEquals(Collections.singletonList("Delete entry"),
			onEdt(() -> harness.ui().getAssignments().getMenuItems(0)));
		assertEquals(Collections.singletonList("-Delete entry"),
			onEdt(() -> harness.ui().getAssignments().getMenuItems(1)));
		// Each label of both lines, the monster, the outcome and the date and master under them, opens the row's menu.
		DateTimeFormatter date = AssignmentLog.shortDate(ZoneId.systemDefault());
		assertEquals(Arrays.asList("Dust devils: row menu", "Skipped: row menu",
			day(date, ENDED) + " · Duradel/Kuradal: row menu"),
			onEdt(() -> harness.ui().getAssignments().getLabelMenus(0)));
		assertEquals(Arrays.asList("Gargoyles: row menu", "Blocked: row menu",
			day(date, ENDED - DAY) + " · Konar: row menu"),
			onEdt(() -> harness.ui().getAssignments().getLabelMenus(1)));
	}

	@Test
	public void noEntriesIsOnePlainLine()
	{
		harness.onEdt(() -> harness.ui().getAssignments().toggle());
		assertEquals("Skipped / blocked (0) | Hide", onEdt(() -> harness.ui().getAssignments().getHeaderText()));
		assertEquals("No skipped or blocked tasks yet.", onEdt(() -> harness.ui().getAssignments().getEmptyText()));
		assertTrue(rows().isEmpty());
		assertFalse("no hint about deleting rows that aren't there",
			onEdt(() -> harness.ui().getAssignments().isHintShown()));

		setEntries(entry("Dust devils", AssignmentOutcome.SKIPPED, 5, ENDED));
		assertNull(onEdt(() -> harness.ui().getAssignments().getEmptyText()));
		assertEquals(1, rows().size());
		assertTrue(onEdt(() -> harness.ui().getAssignments().isHintShown()));

		// Deleting the last one shows the one line again.
		setEntries();
		assertEquals(AssignmentsSection.EMPTY_TEXT, onEdt(() -> harness.ui().getAssignments().getEmptyText()));
		assertFalse(onEdt(() -> harness.ui().getAssignments().isHintShown()));
	}

	@Test
	public void longNamesAreCutShortAtTheSidebarsWidth()
	{
		String longName = "Lava strykewyrms in the Wilderness Slayer Cave";
		setEntries(entry(longName, AssignmentOutcome.COMPLETED, 12, ENDED),
			entry("Dust devils", AssignmentOutcome.SKIPPED, 5, ENDED - DAY));
		harness.onEdt(() -> harness.ui().getAssignments().toggle());

		int width = onEdt(() -> harness.ui().getAssignments().layOut());
		assertTrue("list " + width, width > 0 && width <= PluginPanel.PANEL_WIDTH);
		assertTrue(onEdt(() -> harness.ui().getAssignments().getListPreferredWidth()) <= PluginPanel.PANEL_WIDTH);
		List<String> lines = onEdt(() -> harness.ui().getAssignments().getFirstLinesShown());
		// The long name is cut short with "…" and the outcome still fits beside it; the tooltip has the name whole.
		String first = lines.get(0);
		assertTrue(first, first.endsWith(" | Completed (untracked) (fits)"));
		String shownName = first.substring(0, first.indexOf(" | "));
		assertTrue(shownName, shownName.endsWith(FitLabel.ELLIPSIS)
			&& longName.startsWith(shownName.substring(0, shownName.length() - 1)));
		assertTrue(rows().get(0), rows().get(0).contains("| <html>" + longName + "<br>"));
		assertEquals("Dust devils | Skipped (fits)", lines.get(1));
	}

	@Test
	public void theRefreshTimerAndTheHoverRebuildNothing()
	{
		setEntries(entry("Dust devils", AssignmentOutcome.SKIPPED, 5, ENDED),
			entry("Gargoyles", AssignmentOutcome.BLOCKED, 5, ENDED - DAY));
		harness.onEdt(() -> harness.ui().getAssignments().toggle());
		int builds = onEdt(() -> harness.ui().getAssignments().getBuildCount());
		int requests = harness.itemImageRequests();

		harness.onEdt(() ->
		{
			harness.panel().refresh();
			harness.panel().refresh();
		});
		harness.drain();
		assertEquals(builds, (int) onEdt(() -> harness.ui().getAssignments().getBuildCount()));
		assertEquals("no icon asked for again", requests, harness.itemImageRequests());

		// The hover shows the row can be right-clicked, and draws only its background.
		assertEquals(LedgerTheme.PAGE, onEdt(() -> harness.ui().getAssignments().getRowBackground(1)));
		harness.onEdt(() -> harness.ui().getAssignments().hoverRow(1, true));
		assertEquals(LedgerTheme.HOVER, onEdt(() -> harness.ui().getAssignments().getRowBackground(1)));
		harness.onEdt(() -> harness.ui().getAssignments().hoverRow(1, false));
		assertEquals(LedgerTheme.PAGE, onEdt(() -> harness.ui().getAssignments().getRowBackground(1)));
		assertEquals(builds, (int) onEdt(() -> harness.ui().getAssignments().getBuildCount()));
	}

	/** Sets the account's entries, as a load of its ledger does. */
	private void setEntries(AssignmentEntry... entries)
	{
		harness.onEdt(() -> harness.historyModel().setAssignments(ACCOUNT, Arrays.asList(entries)));
		harness.drain();
	}

	private List<String> rows()
	{
		harness.drain();
		return onEdt(() -> harness.ui().getAssignments().getRows());
	}

	/** Reads {@code read} on the EDT. */
	private <T> T onEdt(Supplier<T> read)
	{
		AtomicReference<T> value = new AtomicReference<>();
		harness.onEdt(() -> value.set(read.get()));
		return value.get();
	}

	private static String day(DateTimeFormatter date, long millis)
	{
		return date.format(Instant.ofEpochMilli(millis));
	}

	private static AssignmentEntry entry(String name, AssignmentOutcome outcome, Integer master, long endedAt)
	{
		AssignmentEntry entry = new AssignmentEntry();
		entry.setId(name + endedAt);
		entry.setMonster(name);
		entry.setOutcome(outcome);
		entry.setSlayerMaster(master);
		entry.setEndedAt(endedAt);
		return entry;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The task box's next bonus, short on its second line and in full in that line's tooltip, as wired in the
 * plugin ({@link PluginHarness}): the streak of the current task's master, read on settled ticks, the new streak right
 * after a completion, and hidden while it is unknown.
 * {@link StreakMilestoneTest} covers the rules.
 */
public class HarnessStreakHintTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(42, "Kraken", 3, 3);
		harness.setAssignment(SlayerMaster.KONAR, 0, null);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 47);
		harness.setVarbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 9);
		harness.setVarp(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED, 120);
	}

	private String hint()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getTaskBox().getStreakHintText();
		});
		return text[0];
	}

	private List<String> taskBoxRows()
	{
		final List<?>[] rows = new List<?>[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			rows[0] = harness.ui().getTaskBox().getRows();
		});
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) rows[0];
		return result;
	}

	@Test
	public void hiddenUntilLoggedInAndSettled()
	{
		assertNull("not logged in", hint());
		harness.login(ACCOUNT);
		assertNull("no settled reading yet", hint());
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("Next bonus: task 50 (in 3)", hint());
	}

	@Test
	public void shownShortOnTheSecondLineAndInFullInItsTooltip()
	{
		harness.loginAndSettle(ACCOUNT);
		assertEquals(Arrays.asList("Kraken", "Konar · 3 left · bonus in 3"), taskBoxRows());
		assertEquals("Next bonus: task 50 (in 3)", hint());
	}

	@Test
	public void hiddenWhileTheMasterIsUnknown()
	{
		harness.setAssignment(SlayerMaster.NONE, 0, null);
		harness.loginAndSettle(ACCOUNT);
		assertNull(hint());
		// The master's varbit syncs later.
		harness.setAssignment(6, 0, null);
		harness.tick();
		assertEquals("Next bonus: task 50 (in 3)", hint());
	}

	@Test
	public void hiddenForAMasterNotInTheTable()
	{
		harness.setAssignment(14, 0, null);
		harness.loginAndSettle(ACCOUNT);
		assertNull(hint());
	}

	@Test
	public void hiddenWithNoTaskAndNoCompletionSeen()
	{
		harness.setRemaining(0);
		harness.loginAndSettle(ACCOUNT);
		assertNull(hint());
	}

	@Test
	public void justCompletedTaskShowsTheNewStreak()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.completeTask(18);
		harness.tick();
		assertEquals("streak 48, no task yet", "Next bonus: task 50 (in 2)", hint());
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals("kept until the next task", "Next bonus: task 50 (in 2)", hint());

		// The next task, from the same master type.
		harness.setTask(43, "Hydras", 100, 100);
		harness.tick();
		assertEquals("Next bonus: task 50 (in 2)", hint());
	}

	@Test
	public void completingTheTenthTaskMovesToTheNext()
	{
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 49);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Next bonus: task 50 (in 1)", hint());
		// Completed without a session: the hint still follows the counter.
		harness.completeTask();
		harness.tick();
		assertEquals("Next bonus: task 60 (in 10)", hint());
	}

	@Test
	public void wildernessAndMortimerUseTheirOwnStreaks()
	{
		harness.setAssignment(SlayerMaster.KRYSTILIA, 0, null);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Wilderness streak 9", "Next bonus: task 10 (in 1)", hint());
		harness.setRemaining(0);
		harness.setVarbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 10);
		harness.tick();
		assertEquals("the Wilderness streak went up", "Next bonus: task 20 (in 10)", hint());

		harness.setTask(43, "Hydras", 100, 100);
		harness.setAssignment(SlayerMaster.MORTIMER, 0, null);
		harness.tick();
		assertEquals("Mortimer streak 120", "Next bonus: task 130 (in 10)", hint());

		harness.setAssignment(SlayerMaster.KONAR, 0, null);
		harness.tick();
		assertEquals("regular streak 47", "Next bonus: task 50 (in 3)", hint());
	}

	@Test
	public void aStreakRisingATickAfterTheTaskEndsKeepsItsMaster()
	{
		harness.setAssignment(SlayerMaster.KRYSTILIA, 0, null);
		harness.loginAndSettle(ACCOUNT);
		harness.setRemaining(0);
		harness.tick();
		assertEquals("still the Wilderness streak", "Next bonus: task 10 (in 1)", hint());
		harness.setVarbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 10);
		harness.tick();
		assertEquals("the Wilderness streak went up", "Next bonus: task 20 (in 10)", hint());
	}

	@Test
	public void logoutHidesItAndAHopKeepsIt()
	{
		harness.loginAndSettle(ACCOUNT);
		harness.completeTask();
		harness.tick();
		assertEquals("Next bonus: task 50 (in 2)", hint());

		harness.hop();
		assertNull("no settled reading after the hop yet", hint());
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("the completed task's streak is kept across a hop", "Next bonus: task 50 (in 2)", hint());

		harness.logout();
		assertNull(hint());
		harness.loginAndSettle(ACCOUNT);
		assertNull("no task and no completion seen since the login screen", hint());
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.PluginHarness.item;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.slf4j.LoggerFactory;

/**
 * Supply counting must not stop for good during a long client run. On 2026-11-08 every task after a bank visit
 * was saved with no supplies at all while its session ran normally: the bank's interface group can stay loaded after
 * the bank closed ({@link PluginHarness#loadInterfaceWithoutOpening}), and the plugin took a loaded root widget for an
 * open interface, so it left every later tick out of the supplies diff. An excluded interface now counts as open only
 * while its root widget is loaded and shown. Counting also carries on after a bank trip, a logout and login, a world
 * hop and a lost connection in the same client run. {@link HarnessSupplyExclusionsTest} covers the exclusions
 * themselves.
 */
public class HarnessSupplyCountingStopTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final String[] EAT = {"Eat", null, null, null, "Drop"};
	private static final String[] DRINK = {"Drink", null, null, "Empty", "Drop"};
	private static final String[] NO_USE = {null, null, null, null, "Drop"};
	/** Prayer potion item ids by dose (index 1 to 4). */
	private static final int[] PRAYER = {-1, ItemID._1DOSEPRAYERRESTORE, ItemID._2DOSEPRAYERRESTORE,
		ItemID._3DOSEPRAYERRESTORE, ItemID._4DOSEPRAYERRESTORE};

	@Rule
	public final PluginHarness harness = new PluginHarness();

	private int sharks = 10;
	/** Prayer potions held, by dose (index 1 to 4). */
	private final int[] potions = {0, 0, 0, 0, 4};
	private int deathRunes;
	private int bloodRunes;
	private int waterRunes;

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.SHARK, "Shark", 800, 0, EAT);
		for (int dose = 1; dose <= 4; dose++)
		{
			harness.defineItem(PRAYER[dose], "Prayer potion(" + dose + ")", 2_000L * dose, 0, DRINK);
		}
		harness.defineItem(ItemID.DEATHRUNE, "Death rune", 200, 0, NO_USE);
		harness.defineItem(ItemID.BLOODRUNE, "Blood rune", 300, 0, NO_USE);
		harness.defineItem(ItemID.WATERRUNE, "Water rune", 5, 0, NO_USE);
		updateInventory();
		harness.startUp();
		harness.setTask(42, "Dust devils", 200, 200);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Sets the inventory to the sharks, potions and runes held now. */
	private void updateInventory()
	{
		final List<Item> items = new ArrayList<>();
		addStack(items, ItemID.SHARK, sharks);
		for (int dose = 1; dose <= 4; dose++)
		{
			for (int i = 0; i < potions[dose]; i++)
			{
				items.add(item(PRAYER[dose], 1));
			}
		}
		addStack(items, ItemID.DEATHRUNE, deathRunes);
		addStack(items, ItemID.BLOODRUNE, bloodRunes);
		addStack(items, ItemID.WATERRUNE, waterRunes);
		harness.setInventory(items.toArray(new Item[0]));
	}

	private static void addStack(List<Item> items, int itemId, int quantity)
	{
		if (quantity > 0)
		{
			items.add(item(itemId, quantity));
		}
	}

	/** Eats one shark and drinks one dose (from the potion with the fewest doses), each on its own tick. */
	private void eatAndDrink()
	{
		sharks--;
		updateInventory();
		harness.tick();
		for (int dose = 1; dose <= 4; dose++)
		{
			if (potions[dose] > 0)
			{
				// The drunk dose leaves a potion with one dose fewer (a 1-dose potion leaves a vial, not tracked).
				potions[dose]--;
				if (dose > 1)
				{
					potions[dose - 1]++;
				}
				break;
			}
		}
		updateInventory();
		harness.tick();
	}

	/**
	 * A bank trip: the bank opens, sharks are deposited, then sharks, potions and runes are withdrawn, and the bank
	 * closes, after which nothing is counted for a couple of ticks. With {@code groupLeftLoaded}, the game then loads
	 * the bank's group again without opening it, as suspected on 2026-11-08.
	 */
	private void bankTrip(boolean groupLeftLoaded)
	{
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.tick();
		sharks = 5;
		updateInventory();
		harness.tick();
		sharks = 20;
		potions[4] += 2;
		deathRunes = 1_000;
		bloodRunes = 500;
		waterRunes = 1_500;
		updateInventory();
		harness.tick();
		harness.closeInterface(InterfaceID.BANKMAIN);
		if (groupLeftLoaded)
		{
			harness.loadInterfaceWithoutOpening(InterfaceID.BANKMAIN);
		}
		harness.ticks(SupplyExclusions.INTERFACE_TICKS + 1);
	}

	/** Stops the session and returns the saved record's supplies. */
	private Map<Integer, Long> stopAndGetSupplies()
	{
		harness.endTask();
		final Map<Integer, Long> supplies = harness.onlyRecord(ACCOUNT).getSupplies();
		return supplies == null ? Collections.emptyMap() : supplies;
	}

	private static long used(Map<Integer, Long> supplies, int itemId)
	{
		return supplies.getOrDefault(itemId, 0L);
	}

	@Test
	public void theBanksGroupLeftLoadedAfterItClosedDoesNotStopCounting()
	{
		assertTrue(harness.startNow());
		eatAndDrink();
		bankTrip(true);
		for (int i = 0; i < 5; i++)
		{
			eatAndDrink();
		}

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals("sharks eaten before and after the bank trip", 6L, used(supplies, ItemID.SHARK));
		assertEquals("prayer potion doses", 6L, used(supplies, ItemID._4DOSEPRAYERRESTORE));
	}

	@Test
	public void noExcludedInterfaceThatIsOnlyLoadedStopsCounting()
	{
		for (int group : SupplyExclusions.excludedInterfaces())
		{
			harness.loadInterfaceWithoutOpening(group);
		}
		assertTrue(harness.startNow());
		harness.tick();
		eatAndDrink();
		eatAndDrink();

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(2L, used(supplies, ItemID.SHARK));
		assertEquals(2L, used(supplies, ItemID._4DOSEPRAYERRESTORE));
	}

	@Test
	public void barrageRunesLooseInTheInventoryAreCountedAfterABankTrip()
	{
		assertTrue(harness.startNow());
		bankTrip(true);
		// Ten Ice Barrage casts: 4 death, 2 blood and 6 water runes each, from the inventory.
		for (int cast = 0; cast < 10; cast++)
		{
			deathRunes -= 4;
			bloodRunes -= 2;
			waterRunes -= 6;
			updateInventory();
			harness.tick();
		}

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(40L, used(supplies, ItemID.DEATHRUNE));
		assertEquals(20L, used(supplies, ItemID.BLOODRUNE));
		assertEquals(60L, used(supplies, ItemID.WATERRUNE));
	}

	/** One Ice Barrage cast on its own tick: 4 death, 2 blood and 6 water runes from the inventory. */
	private void barrage()
	{
		deathRunes -= 4;
		bloodRunes -= 2;
		waterRunes -= 6;
		updateInventory();
		harness.tick();
	}

	@Test
	public void theOwnersBarrageTaskCountsRunesPotionsAndFoodAroundABankTrip()
	{
		// The owner's task of 2026-11-08, the fixed regression case: Ice Barrage with death, blood and water
		// runes loose in the inventory, potions and food used in the same task, and a bank trip after which the bank's
		// group stayed loaded.
		deathRunes = 400;
		bloodRunes = 200;
		waterRunes = 600;
		updateInventory();
		harness.tick();
		assertTrue(harness.startNow());
		for (int i = 0; i < 5; i++)
		{
			barrage();
			eatAndDrink();
		}
		bankTrip(true);
		for (int i = 0; i < 5; i++)
		{
			barrage();
			eatAndDrink();
		}

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(40L, used(supplies, ItemID.DEATHRUNE));
		assertEquals(20L, used(supplies, ItemID.BLOODRUNE));
		assertEquals(60L, used(supplies, ItemID.WATERRUNE));
		assertEquals(10L, used(supplies, ItemID.SHARK));
		assertEquals("prayer potion doses", 10L, used(supplies, ItemID._4DOSEPRAYERRESTORE));
		assertEquals(5, supplies.size());
	}

	@Test
	public void potionsAndFoodKeepCountingAfterABankTripALogoutAHopAndALostConnection()
	{
		keepsCountingThroughALongClientRun(false);
	}

	@Test
	public void potionsAndFoodKeepCountingThroughALongClientRunWithTheBanksGroupLeftLoaded()
	{
		keepsCountingThroughALongClientRun(true);
	}

	@Test
	public void sharksDepositedInTheMiddleOfABankVisitAreNotCounted()
	{
		assertTrue(harness.startNow());
		eatAndDrink();
		harness.openInterface(InterfaceID.BANKMAIN);
		// Well past the ticks around opening: only the open check keeps this deposit out.
		harness.ticks(SupplyExclusions.INTERFACE_TICKS + 3);
		sharks -= 3;
		updateInventory();
		harness.tick();
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.ticks(SupplyExclusions.INTERFACE_TICKS + 1);
		eatAndDrink();

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals("only the two sharks eaten", 2L, used(supplies, ItemID.SHARK));
	}

	@Test
	public void aLongStretchOfUncountedTicksLeavesRateLimitedLogLines()
	{
		final Logger logger = (Logger) LoggerFactory.getLogger(SlayerLedgerPlugin.class);
		final Level previousLevel = logger.getLevel();
		final ListAppender<ILoggingEvent> appender = new ListAppender<>();
		appender.start();
		logger.addAppender(appender);
		logger.setLevel(Level.DEBUG);
		try
		{
			final String line = "Supplies not counted for %d game ticks in a row while the session runs: %s";
			final String bankOpen = "excluded interface " + InterfaceID.BANKMAIN + " is open";
			final int first = SkippedSupplyTicks.FIRST_REPORT_TICKS;
			final int repeat = SkippedSupplyTicks.REPEAT_REPORT_TICKS;

			// No session running: nothing would be counted anyway, so nothing is logged.
			harness.openInterface(InterfaceID.BANKMAIN);
			harness.ticks(first + 1);
			assertEquals(Collections.emptyList(), supplyLines(appender));

			assertTrue(harness.startNow());
			harness.ticks(first - 1);
			assertEquals("a short bank visit leaves no line", Collections.emptyList(), supplyLines(appender));
			harness.tick();
			assertEquals(Collections.singletonList(String.format(line, first, bankOpen)), supplyLines(appender));
			assertEquals("the first line is debug", Level.DEBUG, supplyEvents(appender).get(0).getLevel());
			harness.ticks(repeat - 1);
			assertEquals("rate-limited", 1, supplyLines(appender).size());
			harness.tick();
			assertEquals(String.format(line, first + repeat, bankOpen), supplyLines(appender).get(1));
			assertEquals("a repeat reaches the default client log", Level.INFO,
				supplyEvents(appender).get(1).getLevel());

			// Closed, with its group left loaded: counting goes on, so no further line.
			harness.closeInterface(InterfaceID.BANKMAIN);
			harness.loadInterfaceWithoutOpening(InterfaceID.BANKMAIN);
			harness.ticks(repeat + first);
			assertEquals(2, supplyLines(appender).size());
		}
		finally
		{
			logger.detachAppender(appender);
			logger.setLevel(previousLevel);
		}
	}

	/** The plugin's "Supplies not counted" log lines so far. */
	private static List<String> supplyLines(ListAppender<ILoggingEvent> appender)
	{
		final List<String> lines = new ArrayList<>();
		for (ILoggingEvent event : supplyEvents(appender))
		{
			lines.add(event.getFormattedMessage());
		}
		return lines;
	}

	/** The plugin's "Supplies not counted" log events so far, at any level. */
	private static List<ILoggingEvent> supplyEvents(ListAppender<ILoggingEvent> appender)
	{
		final List<ILoggingEvent> events = new ArrayList<>();
		for (ILoggingEvent event : new ArrayList<>(appender.list))
		{
			if (event.getFormattedMessage().startsWith("Supplies not counted"))
			{
				events.add(event);
			}
		}
		return events;
	}

	/**
	 * One running session through a long client run: supplies used after a bank trip, after a logout and login
	 * (restarted), after a world hop (still running: a hop is not a stop) and after a lost connection (restarted) all
	 * count.
	 */
	private void keepsCountingThroughALongClientRun(boolean groupLeftLoaded)
	{
		assertTrue(harness.startNow());
		eatAndDrink();

		bankTrip(groupLeftLoaded);
		eatAndDrink();

		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertTrue("restarted after the login", harness.startNow());
		eatAndDrink();

		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("a hop is not a stop", SessionTracker.State.RUNNING, harness.sessionState());
		eatAndDrink();

		harness.setGameState(GameState.CONNECTION_LOST);
		harness.setGameState(GameState.LOGGED_IN);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("a lost connection stops it like a logout", SessionTracker.State.LOGGED_OUT,
			harness.sessionState());
		assertTrue("restarted after the reconnect", harness.startNow());
		eatAndDrink();

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals("one shark in each stretch", 5L, used(supplies, ItemID.SHARK));
		assertEquals("one dose in each stretch", 5L, used(supplies, ItemID._4DOSEPRAYERRESTORE));
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.PluginHarness.item;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.Map;
import net.runelite.api.ChatMessageType;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Supply coverage audit: each consumable family a Slayer task uses is counted through the plugin's wiring
 * ({@link PluginHarness}), so a regression in any family fails the build. This class covers the families no other
 * harness test does; the rest are proven elsewhere:
 * <ul>
 *     <li>runes loose in the inventory (an Ice Barrage task), potions by dose and food:
 *     {@link HarnessSupplyCountingStopTest}; decanting nets zero: {@link SupplyTrackerTest}; food eaten in bites:
 *     {@link MultiBiteFoodTest};</li>
 *     <li>blowpipe darts and scales, trident and powered staff charges, and loading or charging them:
 *     {@link HarnessChargedWeaponsTest};</li>
 *     <li>regular and granite cannonballs: {@link HarnessCannonTaskTest};</li>
 *     <li>bags of salt, teleport tablets and teleport jewellery: {@link HarnessChargedSuppliesTest}; ice coolers and the
 *     fungicide spray: {@link SupplyChargesTest}.</li>
 * </ul>
 */
public class HarnessSupplyCoverageTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final String[] NO_USE = {null, null, null, null, "Drop"};
	private static final String[] DRINK = {"Drink", null, null, "Empty", "Drop"};
	private static final String[] WEAR = {null, "Wear", null, null, "Drop"};
	private static final String[] TELEPORT = {"Teleport", null, null, null, "Drop"};
	/** Rune types of the rune pouch enum ({@link PluginHarness#setRunePouchRunes}), from type 1. */
	private static final int[] POUCH_RUNES = {ItemID.DEATHRUNE, ItemID.BLOODRUNE, ItemID.WATERRUNE, ItemID.COSMICRUNE};
	private static final int[] POUCH_TYPES = {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_TYPE_4};
	private static final int[] POUCH_QUANTITIES = {VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4};

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.DEATHRUNE, "Death rune", 200, 0, NO_USE);
		harness.defineItem(ItemID.BLOODRUNE, "Blood rune", 300, 0, NO_USE);
		harness.defineItem(ItemID.WATERRUNE, "Water rune", 5, 0, NO_USE);
		harness.defineItem(ItemID.COSMICRUNE, "Cosmic rune", 100, 0, NO_USE);
		harness.defineItem(ItemID.FIRERUNE, "Fire rune", 5, 0, NO_USE);
		harness.setRunePouchRunes(POUCH_RUNES);
		harness.defineAmmo(ItemID.RUNE_ARROW, "Rune arrow", 100);
		harness.defineAmmo(ItemID.ADAMANT_ARROW, "Adamant arrow", 40);
		harness.defineStackableWeapon(ItemID.RUNE_KNIFE, "Rune knife", 150);
		harness.defineStackableWeapon(ItemID.RUNE_DART, "Rune dart", 120);
		harness.defineItem(ItemID.TELEPORTSCROLL_ZULANDRA, "Zul-andra teleport", 1_000, 0, TELEPORT);
		harness.defineItem(ItemID.TELEPORTSCROLL_CERBERUS, "Key master teleport", 2_000, 0, TELEPORT);
		harness.defineItem(ItemID.BRACELET_OF_SLAUGHTER, "Bracelet of slaughter", 3_000, 0, WEAR);
		harness.defineItem(ItemID.EXPEDITIOUS_BRACELET, "Expeditious bracelet", 6_000, 0, WEAR);
		harness.setInventory();
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 100, 100);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Stops the session and returns the saved record's supplies. */
	private Map<Integer, Long> stopAndGetSupplies()
	{
		harness.endTask();
		final Map<Integer, Long> supplies = harness.onlyRecord(ACCOUNT).getSupplies();
		return supplies == null ? Collections.emptyMap() : supplies;
	}

	private static long used(Map<Integer, Long> supplies, int itemId)
	{
		return supplies.getOrDefault(itemId, 0L);
	}

	/** Puts {@code quantities} in rune pouch slots 1 to 4, holding the {@link #POUCH_RUNES} types in that order. */
	private void runePouch(int... quantities)
	{
		for (int slot = 0; slot < POUCH_TYPES.length; slot++)
		{
			harness.setVarbit(POUCH_TYPES[slot], slot + 1);
			harness.setVarbit(POUCH_QUANTITIES[slot], quantities[slot]);
		}
	}

	@Test
	public void runesFromTheInventoryAndEveryDivineRunePouchSlotAreCounted()
	{
		runePouch(1_000, 500, 1_500, 100);
		harness.setInventory(item(ItemID.DIVINE_RUNE_POUCH, 1), item(ItemID.FIRERUNE, 500),
			item(ItemID.DEATHRUNE, 100));
		harness.tick();
		assertTrue(harness.startNow());

		// Filling the pouch with the inventory's death runes is not a use.
		runePouch(1_100, 500, 1_500, 100);
		harness.setInventory(item(ItemID.DIVINE_RUNE_POUCH, 1), item(ItemID.FIRERUNE, 500));
		harness.tick();
		// One cast from each of the four slots, and fire runes loose in the inventory.
		runePouch(1_096, 498, 1_494, 99);
		harness.setInventory(item(ItemID.DIVINE_RUNE_POUCH, 1), item(ItemID.FIRERUNE, 490));
		harness.tick();

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(4L, used(supplies, ItemID.DEATHRUNE));
		assertEquals(2L, used(supplies, ItemID.BLOODRUNE));
		assertEquals(6L, used(supplies, ItemID.WATERRUNE));
		assertEquals(1L, used(supplies, ItemID.COSMICRUNE));
		assertEquals(10L, used(supplies, ItemID.FIRERUNE));
		assertEquals(5, supplies.size());
	}

	@Test
	public void runesCastForAThrallFromTheInventoryAndPouchAreCounted()
	{
		// Resurrect Greater Ghost (OSRS Wiki): 10 fire, 5 blood and 1 cosmic rune, with the Book of the Dead carried.
		runePouch(0, 200, 0, 50);
		harness.setInventory(item(ItemID.BH_RUNE_POUCH, 1), item(ItemID.FIRERUNE, 300),
			item(ItemID.BOOK_OF_THE_DEAD, 1));
		harness.tick();
		assertTrue(harness.startNow());
		for (int cast = 1; cast <= 3; cast++)
		{
			runePouch(0, 200 - 5 * cast, 0, 50 - cast);
			harness.setInventory(item(ItemID.BH_RUNE_POUCH, 1), item(ItemID.FIRERUNE, 300 - 10 * cast),
				item(ItemID.BOOK_OF_THE_DEAD, 1));
			harness.tick();
		}

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(30L, used(supplies, ItemID.FIRERUNE));
		assertEquals(15L, used(supplies, ItemID.BLOODRUNE));
		assertEquals(3L, used(supplies, ItemID.COSMICRUNE));
		assertEquals("the book is not used up", 3, supplies.size());
	}

	@Test
	public void arrowsFromTheAmmoSlotAndQuiverCountAndPickedUpOnesOffsetThem()
	{
		harness.setWorn(EquipmentInventorySlot.AMMO, ItemID.RUNE_ARROW, 500);
		harness.setVarp(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO, ItemID.ADAMANT_ARROW);
		harness.setVarp(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT, 200);
		harness.tick();
		assertTrue(harness.startNow());

		// Fired from the ammo slot, then from the quiver's second ammo.
		harness.setWorn(EquipmentInventorySlot.AMMO, ItemID.RUNE_ARROW, 495);
		harness.tick();
		harness.setVarp(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT, 197);
		harness.tick();
		// Two rune arrows picked up from the floor.
		harness.setInventory(item(ItemID.RUNE_ARROW, 2));
		harness.tick();
		// Equipping them into the ammo slot moves them between tracked containers.
		harness.setInventory();
		harness.setWorn(EquipmentInventorySlot.AMMO, ItemID.RUNE_ARROW, 497);
		harness.tick();

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals("5 fired, 2 picked up", 3L, used(supplies, ItemID.RUNE_ARROW));
		assertEquals(3L, used(supplies, ItemID.ADAMANT_ARROW));
		assertEquals(2, supplies.size());
	}

	@Test
	public void thrownKnivesAndDartsFromTheWeaponSlotCountAndPickedUpOnesOffsetThem()
	{
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.RUNE_KNIFE, 100);
		harness.setInventory(item(ItemID.RUNE_DART, 50));
		harness.tick();
		assertTrue(harness.startNow());

		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.RUNE_KNIFE, 96);
		harness.tick();
		harness.setInventory(item(ItemID.RUNE_DART, 50), item(ItemID.RUNE_KNIFE, 2));
		harness.tick();
		// Swapping to the darts: both stacks move between the inventory and the weapon slot.
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.RUNE_DART, 50);
		harness.setInventory(item(ItemID.RUNE_KNIFE, 98));
		harness.tick();
		harness.setWorn(EquipmentInventorySlot.WEAPON, ItemID.RUNE_DART, 47);
		harness.tick();

		final Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals("4 thrown, 2 picked up", 2L, used(supplies, ItemID.RUNE_KNIFE));
		assertEquals(3L, used(supplies, ItemID.RUNE_DART));
		assertEquals(2, supplies.size());
	}

	@Test
	public void teleportScrollsCountOnePerScrollAndStoringThemInTheBookIsNotAUse()
	{
		harness.setInventory(item(ItemID.TELEPORTSCROLL_ZULANDRA, 10), item(ItemID.TELEPORTSCROLL_CERBERUS, 5),
			item(ItemID.BOOKOFSCROLLS_CHARGED, 1));
		harness.tick();
		assertTrue(harness.startNow());

		harness.setInventory(item(ItemID.TELEPORTSCROLL_ZULANDRA, 9), item(ItemID.TELEPORTSCROLL_CERBERUS, 5),
			item(ItemID.BOOKOFSCROLLS_CHARGED, 1));
		harness.tick();
		// The Key master teleports are stored in the master scroll book.
		harness.clickUseOn(ItemID.TELEPORTSCROLL_CERBERUS, ItemID.BOOKOFSCROLLS_CHARGED);
		harness.setInventory(item(ItemID.TELEPORTSCROLL_ZULANDRA, 9), item(ItemID.BOOKOFSCROLLS_CHARGED, 1));
		harness.tick();
		// Well after the store: the last Zul-andra scroll read is counted as usual.
		harness.ticks(SupplyExclusions.DROP_WINDOW_TICKS + 1);
		harness.setInventory(item(ItemID.TELEPORTSCROLL_ZULANDRA, 8), item(ItemID.BOOKOFSCROLLS_CHARGED, 1));
		harness.tick();

		harness.endTask();
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(2L, used(record.getSupplies(), ItemID.TELEPORTSCROLL_ZULANDRA));
		assertEquals(0L, used(record.getSupplies(), ItemID.TELEPORTSCROLL_CERBERUS));
		assertEquals(1, record.getSupplies().size());
		assertEquals(Long.valueOf(2 * 1_000), record.getSuppliesGeValue());
	}

	@Test
	public void slayerBraceletChargesCountFromTheirMessages()
	{
		harness.setWorn(EquipmentInventorySlot.GLOVES, ItemID.BRACELET_OF_SLAUGHTER, 1);
		harness.tick();
		final String slaughter = "Your bracelet of slaughter prevents your slayer count from decreasing. It has %d "
			+ "charges left.";
		harness.chat(ChatMessageType.GAMEMESSAGE, String.format(slaughter, 29));
		assertTrue(harness.startNow());
		harness.chat(ChatMessageType.GAMEMESSAGE, String.format(slaughter, 28));
		harness.tick();
		harness.chat(ChatMessageType.GAMEMESSAGE, String.format(slaughter, 27));
		// Checking it uses nothing.
		harness.chat(ChatMessageType.GAMEMESSAGE, "Your bracelet of slaughter has 27 charges left.");
		harness.tick();
		// An expeditious bracelet's last charge: it crumbles and leaves the gloves slot, which is not counted again.
		harness.setWorn(EquipmentInventorySlot.GLOVES, ItemID.EXPEDITIOUS_BRACELET, 1);
		harness.tick();
		harness.chat(ChatMessageType.GAMEMESSAGE,
			"Your expeditious bracelet helps you progress your slayer task faster. It then crumbles to dust.");
		harness.setWorn(EquipmentInventorySlot.GLOVES, -1, 0);
		harness.tick();
		harness.pause();
		// A slaughter activation is a task kill: it restarts the paused session, and its charge, used just
		// before, counts in the restart's supplies warm-up (V2 plan 4.1).
		harness.chat(ChatMessageType.GAMEMESSAGE, String.format(slaughter, 26));
		harness.tick();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());

		harness.endTask();
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		final Map<Integer, Long> supplies = record.getSupplies();
		assertEquals("28, 27 and 26; not 29, before the test seam's start", 3L,
			used(supplies, ItemID.BRACELET_OF_SLAUGHTER));
		assertEquals(1L, used(supplies, ItemID.EXPEDITIOUS_BRACELET));
		assertEquals(2, supplies.size());
		assertEquals(Integer.valueOf(30), record.getSupplyDoses().get(ItemID.BRACELET_OF_SLAUGHTER));
		assertEquals(Integer.valueOf(30), record.getSupplyDoses().get(ItemID.EXPEDITIOUS_BRACELET));
		// 3 * 3,000 / 30 + 6,000 / 30.
		assertEquals(Long.valueOf(300 + 200), record.getSuppliesGeValue());
	}

	@Test
	public void aMembersPotionSeenOnAFreeWorldIsCountedInDosesAfterAHopToAMembersWorld()
	{
		// on a free world the game names members items "... (Members)". If that definition were classified and
		// cached, a prayer potion would count as food for the rest of the client run.
		final int[] prayer = {-1, ItemID._1DOSEPRAYERRESTORE, ItemID._2DOSEPRAYERRESTORE, ItemID._3DOSEPRAYERRESTORE,
			ItemID._4DOSEPRAYERRESTORE};
		for (int dose = 1; dose <= 4; dose++)
		{
			harness.defineItem(prayer[dose], "Prayer potion(" + dose + ")" + SupplyReader.MEMBERS_SUFFIX, 2_000L * dose,
				0, DRINK);
		}
		harness.setInventory(item(ItemID._4DOSEPRAYERRESTORE, 1), item(ItemID._4DOSEPRAYERRESTORE, 1));
		harness.ticks(PluginHarness.SETTLE_TICKS + SlayerLedgerPlugin.INVENTORY_NOTE_TRIES);

		// A hop to a members world: the same items now show their real definitions.
		for (int dose = 1; dose <= 4; dose++)
		{
			harness.defineItem(prayer[dose], "Prayer potion(" + dose + ")", 2_000L * dose, 0, DRINK);
		}
		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertTrue(harness.startNow());
		harness.setInventory(item(ItemID._4DOSEPRAYERRESTORE, 1), item(ItemID._3DOSEPRAYERRESTORE, 1));
		harness.tick();
		harness.setInventory(item(ItemID._4DOSEPRAYERRESTORE, 1), item(ItemID._2DOSEPRAYERRESTORE, 1));
		harness.tick();

		harness.endTask();
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals("two doses, under the 4-dose potion", Collections.singletonMap(ItemID._4DOSEPRAYERRESTORE, 2L),
			record.getSupplies());
		assertEquals(Integer.valueOf(4), record.getSupplyDoses().get(ItemID._4DOSEPRAYERRESTORE));
		assertNull(record.getSupplyDoses().get(ItemID._3DOSEPRAYERRESTORE));
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.PluginHarness.item;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.Map;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Supplies counting as wired in the plugin ({@link PluginHarness}): only while RUNNING, and not while a bank-like
 * interface is open (tracked through WidgetLoaded / WidgetClosed and the root widget), after a "Drop" click on the
 * item, or around the local player's death. {@link SupplyExclusionsTest}, {@link SupplyTrackerTest} and
 * {@link SuppliesSessionTest} cover the rules themselves.
 */
public class HarnessSupplyExclusionsTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.SHARK, "Shark", 800, 0, "Eat", null, null, null, "Drop");
		harness.defineItem(ItemID.LOBSTER, "Lobster", 150, 0, "Eat", null, null, null, "Drop");
		harness.setInventory(item(ItemID.SHARK, 10), item(ItemID.LOBSTER, 5));
		harness.startUp();
		harness.setTask(42, "Abyssal demons", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	private void inventory(int sharks, int lobsters)
	{
		harness.setInventory(item(ItemID.SHARK, sharks), item(ItemID.LOBSTER, lobsters));
	}

	/** Stops the session and returns the saved record's supplies. */
	private Map<Integer, Long> stopAndGetSupplies()
	{
		harness.endTask();
		Map<Integer, Long> supplies = harness.onlyRecord(ACCOUNT).getSupplies();
		return supplies == null ? Collections.emptyMap() : supplies;
	}

	private static long used(Map<Integer, Long> supplies, int itemId)
	{
		return supplies.getOrDefault(itemId, 0L);
	}

	@Test
	public void foodEatenWhileRunningIsCountedAndPriced()
	{
		assertTrue(harness.startNow());
		inventory(8, 5);
		harness.tick();
		inventory(8, 4);
		harness.tick();

		harness.endTask();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(2L, used(record.getSupplies(), ItemID.SHARK));
		assertEquals(1L, used(record.getSupplies(), ItemID.LOBSTER));
		assertEquals(Long.valueOf(2 * 800 + 150), record.getSuppliesGeValue());
	}

	@Test
	public void suppliesCountOnlyWhileRunning()
	{
		inventory(9, 5);
		harness.tick();
		assertTrue(harness.startNow());
		inventory(8, 5);
		harness.tick();
		harness.pause();
		inventory(7, 5);
		harness.tick();
		// Eaten between the last tick and Play: Play takes a fresh baseline, so this is not counted either.
		inventory(6, 5);
		assertTrue(harness.startNow());
		inventory(5, 5);
		harness.tick();

		assertEquals(2L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void nothingIsCountedWhileTheBankIsOpenOrJustAfter()
	{
		assertTrue(harness.startNow());
		harness.openInterface(InterfaceID.BANKMAIN);
		inventory(3, 0);
		harness.tick();
		inventory(20, 0);
		harness.tick();
		harness.closeInterface(InterfaceID.BANKMAIN);
		// Items the bank moved can still arrive for a couple of ticks after it closes.
		inventory(18, 0);
		harness.ticks(SupplyExclusions.INTERFACE_TICKS + 1);

		inventory(17, 0);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void bankOpenedAndClosedBetweenTicksStillExcludesTheTick()
	{
		assertTrue(harness.startNow());
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		inventory(4, 5);
		harness.tick();

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(0L, used(supplies, ItemID.SHARK));
	}

	@Test
	public void otherInterfacesDoNotExclude()
	{
		assertTrue(harness.startNow());
		harness.openInterface(InterfaceID.INVENTORY);
		inventory(9, 5);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void droppedItemIsNotASupplyButOthersOnTheSameTickAre()
	{
		assertTrue(harness.startNow());
		harness.clickMenu("Drop", ItemID.SHARK);
		inventory(9, 4);
		harness.tick();
		harness.ticks(SupplyExclusions.DROP_WINDOW_TICKS);
		// Outside the drop window, eating a shark counts again.
		inventory(8, 4);
		harness.tick();

		Map<Integer, Long> supplies = stopAndGetSupplies();
		assertEquals(1L, used(supplies, ItemID.SHARK));
		assertEquals(1L, used(supplies, ItemID.LOBSTER));
	}

	@Test
	public void otherMenuOptionsDoNotExclude()
	{
		assertTrue(harness.startNow());
		harness.clickMenu("Eat", ItemID.SHARK);
		inventory(9, 5);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void nothingIsCountedAroundTheLocalPlayersDeath()
	{
		assertTrue(harness.startNow());
		harness.localPlayerDies();
		inventory(0, 0);
		harness.ticks(SupplyExclusions.DEATH_TICKS + 1);
		assertEquals(0L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void suppliesCountAgainAfterTheDeathWindow()
	{
		assertTrue(harness.startNow());
		harness.localPlayerDies();
		inventory(0, 0);
		harness.ticks(SupplyExclusions.DEATH_TICKS + 1);
		inventory(5, 5);
		harness.tick();
		inventory(4, 5);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}

	@Test
	public void anotherActorsDeathDoesNotExclude()
	{
		assertTrue(harness.startNow());
		harness.otherActorDies();
		inventory(9, 5);
		harness.tick();
		assertEquals(1L, used(stopAndGetSupplies(), ItemID.SHARK));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Item;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Jad and Zuk tasks through the plugin's events (V2 plan 4.1): inside the Fight Caves or the Inferno with that
 * task assigned is Running. Entering opens a segment, leaving (also after a death) closes it and keeps what came
 * before, a logout inside closes it and a login inside opens one, and Away never starts inside. Supplies count inside
 * (with the warm-up before an entry), not outside.
 */
public class HarnessTaskCaveTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int JAD_TASK = 93;
	private static final int ZUK_TASK = 94;
	/** The TzHaar city, outside the Fight Caves. */
	private static final int TZHAAR_CITY = 9808;
	private static final long MINUTE = 60_000L;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	private final AtomicLong now = new AtomicLong(1_000_000_000L);
	private int sharks = 20;

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.SHARK, "Shark", 1_000, 300, "Eat");
		harness.startUp();
		harness.setTrackerClock(now::get);
		harness.setInventory(sharkStacks());
		harness.setPlayerRegion(TZHAAR_CITY);
		harness.setTask(JAD_TASK, TaskCaves.JAD_TASK, 1, 1);
		harness.loginAndSettle(ACCOUNT);
		// The task is read; the supplies diff takes its first baseline.
		harness.tick();
	}

	private Item[] sharkStacks()
	{
		final Item[] items = new Item[sharks];
		for (int i = 0; i < sharks; i++)
		{
			items[i] = PluginHarness.item(ItemID.SHARK, 1);
		}
		return items;
	}

	/** Eats a shark now: the supplies diff sees it on the next tick. */
	private void eat()
	{
		sharks--;
		harness.setInventory(sharkStacks());
		harness.tick();
	}

	private long sharksUsed()
	{
		return harness.tracker().getSupplies().get(ItemID.SHARK);
	}

	/** The player moves to {@code region}; the plugin sees it on the next tick. */
	private void moveTo(int region)
	{
		harness.setPlayerRegion(region);
		harness.tick();
	}

	private long active()
	{
		return harness.tracker().getActiveMillis();
	}

	@Test
	public void insideTheFightCavesOnAJadTaskIsRunning()
	{
		assertEquals(SessionTracker.Status.WAITING_FOR_FIRST_KILL, harness.status());
		// Ten minutes before entering: not counted. Two minutes before: a pre-pot, in the warm-up.
		eat();
		now.addAndGet(8 * MINUTE);
		eat();
		now.addAndGet(2 * MINUTE);

		moveTo(TaskCaves.FIGHT_CAVES_REGION);
		assertEquals("entering starts the session", SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals(1, sharksUsed());
		now.addAndGet(MINUTE);
		eat();
		assertEquals(2, sharksUsed());

		// A long wave with no task kill: Away never starts inside.
		now.addAndGet(15 * MINUTE);
		harness.tick();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals(16 * MINUTE, active());

		// Dying and leaving closes the segment and keeps what came before.
		harness.localPlayerDies();
		moveTo(TZHAAR_CITY);
		assertEquals(SessionTracker.State.AWAY, harness.sessionState());
		assertEquals(16 * MINUTE, active());
		assertEquals("the death inside counts", 1, harness.tracker().getDeaths());
		// Past the ticks after a death, when the items moving to the gravestone are not supplies.
		harness.ticks(SupplyExclusions.DEATH_TICKS);
		// Outside, more than 3 minutes before entering again: not counted.
		now.addAndGet(MINUTE);
		eat();
		now.addAndGet(9 * MINUTE);
		harness.tick();
		assertEquals(16 * MINUTE, active());

		// Entering again restarts it.
		moveTo(TaskCaves.FIGHT_CAVES_REGION);
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals(2, sharksUsed());
		now.addAndGet(2 * MINUTE);
		eat();
		assertEquals(3, sharksUsed());

		// Logging out inside closes it; logging in inside opens one at once.
		harness.logout();
		assertEquals(SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertEquals(18 * MINUTE, active());
		now.addAndGet(30 * MINUTE);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("a login inside is a restart", SessionTracker.State.RUNNING, harness.sessionState());
		assertFalse("so there is no waiting line", harness.status() == SessionTracker.Status.WAITING_FOR_NEXT_KILL);
		harness.tick();
		now.addAndGet(MINUTE);
		eat();
		assertEquals(19 * MINUTE, active());
		assertEquals(4, sharksUsed());

		// Leaving closes it again; outside, nothing counts.
		moveTo(TZHAAR_CITY);
		assertEquals(SessionTracker.State.AWAY, harness.sessionState());
		now.addAndGet(10 * MINUTE);
		eat();
		assertEquals(19 * MINUTE, active());
		assertEquals(4, sharksUsed());

		// Jad, killed inside, completes the task.
		now.addAndGet(10 * MINUTE);
		moveTo(TaskCaves.FIGHT_CAVES_REGION);
		now.addAndGet(5 * MINUTE);
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(1, record.getKills());
		assertEquals(24 * MINUTE, record.getActiveMillis());
		assertEquals(Long.valueOf(4), record.getSupplies().get(ItemID.SHARK));
		assertEquals(Integer.valueOf(1), record.getDeaths());
	}

	@Test
	public void aSessionPausedInsideStaysPausedUntilResumedOrEnteredAgain()
	{
		moveTo(TaskCaves.FIGHT_CAVES_REGION);
		now.addAndGet(MINUTE);
		harness.pause();
		now.addAndGet(5 * MINUTE);
		harness.ticks(3);
		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		assertTrue(harness.resume());
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());

		harness.pause();
		moveTo(TZHAAR_CITY);
		assertEquals(SessionTracker.State.PAUSED, harness.sessionState());
		moveTo(TaskCaves.FIGHT_CAVES_REGION);
		assertEquals("entering again restarts it", SessionTracker.State.RUNNING, harness.sessionState());
	}

	@Test
	public void anEndedJadTaskIsNotTrackedInside()
	{
		harness.endTask();
		moveTo(TaskCaves.FIGHT_CAVES_REGION);
		assertEquals(SessionTracker.Status.ENDED, harness.status());
		harness.trackAgain();
		harness.tick();
		assertEquals("Track again inside starts it", SessionTracker.State.RUNNING, harness.sessionState());
	}

	@Test
	public void onlyTheTasksOwnCaveIsRunning()
	{
		// A Jad task in the Inferno: not its cave.
		moveTo(TaskCaves.INFERNO_REGION);
		assertEquals(SessionTracker.Status.WAITING_FOR_FIRST_KILL, harness.status());

		// A Zuk task in the Inferno.
		harness.setTask(ZUK_TASK, TaskCaves.ZUK_TASK, 1, 1);
		harness.tick();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals(TaskCaves.ZUK_TASK, harness.tracker().getSessionMonster());
		moveTo(TaskCaves.FIGHT_CAVES_REGION);
		assertEquals(SessionTracker.State.AWAY, harness.sessionState());

		// Another task in the Fight Caves: a new assignment ends the Zuk session, and the cave means nothing to it.
		harness.setTask(42, "Abyssal demons", 50, 50);
		harness.tick();
		assertEquals(SessionTracker.Status.WAITING_FOR_FIRST_KILL, harness.status());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Master, task type, Slayer points earned and task streak as wired in the plugin ({@link PluginHarness}): read on the
 * client thread with the task, saved with the record, shown in the live panel and the history, and never taken from a
 * login resync or a spend. {@link TaskContextTest}, {@link TaskRewardsTest} and {@link SlayerMasterTest} cover the
 * rules.
 */
public class HarnessTaskContextTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final int AREA = 12;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(TASK, "Kraken", 3, 3);
		harness.setAssignment(SlayerMaster.KONAR, AREA, "Kraken Cove");
		harness.setSlayerPoints(500);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 42);
	}

	/** Completes the task with {@code points} and waits out the late-loot grace window. */
	private LedgerRecord completeAndSave(int points)
	{
		harness.completeTask(points);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		return harness.onlyRecord(ACCOUNT);
	}

	private String assignmentText()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getTaskBox().getAssignmentText();
		});
		return text[0];
	}

	/** The task box's rows as shown. */
	private List<String> taskBoxRows()
	{
		final List<?>[] rows = new List<?>[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			rows[0] = harness.ui().getTaskBox().getRows();
		});
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) rows[0];
		return result;
	}

	private List<String> historyText()
	{
		final List<?>[] rows = new List<?>[1];
		harness.onEdt(() -> rows[0] = harness.ui().getHistory().getValuesText());
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) rows[0];
		return result;
	}

	@Test
	public void completedTaskRecordsMasterTypePointsAndStreak()
	{
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Master: Konar | Type: Konar (Kraken Cove)", assignmentText());
		// Konar's type is her name, so the second line shows it once; the assigned area is the location. Before the
		// first kill the master line has the task's size.
		assertEquals(Arrays.asList("Kraken", "Kraken Cove", "Konar · 3 left · bonus in 8"), taskBoxRows());
		assertTrue(harness.startNow());
		harness.setRemaining(1);
		harness.tick();
		assertEquals("while a session is active the stats have the kills left",
			Arrays.asList("Kraken", "Kraken Cove", "Konar · bonus in 8"), taskBoxRows());

		LedgerRecord record = completeAndSave(18);
		assertTrue(record.isCompleted());
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), record.getSlayerMaster());
		assertEquals(Integer.valueOf(AREA), record.getSlayerArea());
		assertEquals("Kraken Cove", record.getTaskLocation());
		assertEquals(Integer.valueOf(18), record.getPointsEarned());
		assertEquals(Integer.valueOf(43), record.getTaskStreak());
		assertNull("no task now", assignmentText());
		assertEquals("the next bonus stays", Arrays.asList(TaskBoxView.NO_TASK, "bonus in 7"), taskBoxRows());

		String row = historyText().get(0);
		assertTrue(row, row.contains("<br>Master: Konar<br>Type: Konar (Kraken Cove)<br>Points earned: 18"
			+ "<br>Task streak: 43"));
	}

	@Test
	public void pointsArrivingDuringTheGraceWindowCount()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		// The points varbit lands a tick after the streak counter.
		harness.setSlayerPoints(518);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Integer.valueOf(18), record.getPointsEarned());
		assertEquals(Integer.valueOf(43), record.getTaskStreak());
	}

	@Test
	public void streakArrivingAfterTheLastKillStillRecordsTheRewards()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		// SLAYER_COUNT reaches 0 a tick before the streak counter and points go up.
		harness.setRemaining(0);
		harness.tick();
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 43);
		harness.setSlayerPoints(518);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Integer.valueOf(18), record.getPointsEarned());
		assertEquals(Integer.valueOf(43), record.getTaskStreak());
	}

	@Test
	public void pointsSpentMidTaskDontChangeTheTaskPoints()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.setRemaining(2);
		harness.tick();
		// Spent 400 points at a master during the task.
		harness.setSlayerPoints(100);
		harness.tick();
		LedgerRecord record = completeAndSave(18);
		assertEquals(Integer.valueOf(18), record.getPointsEarned());
	}

	@Test
	public void pointsThatWentDownAtTheCompletionAreNotRecorded()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		LedgerRecord record = completeAndSave(-50);
		assertNull("never negative", record.getPointsEarned());
		assertEquals(Integer.valueOf(43), record.getTaskStreak());
	}

	@Test
	public void loginResyncIsNotAReward()
	{
		// The game reads 0 points and no streak until the server resyncs them after login.
		harness.setSlayerPoints(0);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 0);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.setSlayerPoints(500);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 42);
		harness.tick();
		assertTrue("a resync is no completion", harness.records(ACCOUNT).isEmpty());

		// Logging out and back in resets the baselines; the first reading after it never counts.
		harness.logout();
		harness.login(ACCOUNT);
		harness.setSlayerPoints(900);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertTrue(harness.startNow());
		LedgerRecord record = completeAndSave(18);
		assertEquals("from the reading after login, not the one before logout", Integer.valueOf(18),
			record.getPointsEarned());
	}

	@Test
	public void wildernessCompletionRecordsTheWildernessStreak()
	{
		harness.setAssignment(SlayerMaster.KRYSTILIA, 0, null);
		harness.setVarbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 9);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Master: Krystilia | Type: Wilderness", assignmentText());
		assertEquals(Arrays.asList("Kraken", "Krystilia · Wilderness · 3 left · bonus in 1"), taskBoxRows());
		assertTrue(harness.startNow());
		harness.setRemaining(0);
		harness.setVarbit(VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED, 10);
		harness.setSlayerPoints(525);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Integer.valueOf(10), record.getTaskStreak());
		assertEquals(Integer.valueOf(25), record.getPointsEarned());
		assertEquals(Integer.valueOf(SlayerMaster.KRYSTILIA), record.getSlayerMaster());
		assertNull(record.getSlayerArea());
	}

	@Test
	public void mortimerCompletionRecordsMortimersStreak()
	{
		harness.setAssignment(SlayerMaster.MORTIMER, 0, null);
		harness.setVarp(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED, 4);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Master: Mortimer | Type: Regular", assignmentText());
		assertEquals("Regular is not shown", Arrays.asList("Kraken", "Mortimer · 3 left · bonus in 6"),
			taskBoxRows());
		assertTrue(harness.startNow());
		harness.setRemaining(0);
		harness.setVarp(VarPlayerID.SLAYER_MORTIMER_TASKS_COMPLETED, 5);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(Integer.valueOf(5), harness.onlyRecord(ACCOUNT).getTaskStreak());
	}

	@Test
	public void bossTaskAndUnmappedMaster()
	{
		harness.setTask(SessionTracker.BOSS_TASK_TARGET, "Boss", 3, 3);
		harness.setAssignment(14, 0, null);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("Master: Unknown master (14) | Type: Boss", assignmentText());
		// The boss is not known yet (no boss id), as the task line shows it.
		assertEquals(Arrays.asList("Unknown boss task (0)", "Unknown master (14) · Boss · 3 left"),
			taskBoxRows());
	}

	@Test
	public void masterSyncedAfterTheStartIsFilledIn()
	{
		harness.setAssignment(SlayerMaster.NONE, 0, null);
		harness.loginAndSettle(ACCOUNT);
		assertEquals("nothing known but the task's size", "Master: - | Type: -", assignmentText());
		assertEquals(Arrays.asList("Kraken", "3 left"), taskBoxRows());
		assertTrue(harness.startNow());
		assertEquals("the stats have the kills left: no second line", Arrays.asList("Kraken"), taskBoxRows());
		harness.setAssignment(6, 0, null);
		harness.tick();
		harness.endTask();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isPartial());
		assertEquals(Integer.valueOf(6), record.getSlayerMaster());
		assertNull("not completed: no points", record.getPointsEarned());
		assertNull(record.getTaskStreak());
	}

	@Test
	public void aCompletionWhilePausedRestartsAndRecordsItsRewards()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.pause();
		harness.completeTask(18);
		harness.tick();
		// The final kill restarted the session, so the completion waits for its loot like any other.
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Integer.valueOf(18), record.getPointsEarned());
		assertEquals(Integer.valueOf(43), record.getTaskStreak());
	}

	@Test
	public void restoredSessionKeepsItsAssignment()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.logout();
		harness.shutDown();
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), harness.activeSession(ACCOUNT).getSlayerMaster());

		// After the restart the game hasn't sent the master and area yet; the snapshot's are kept.
		harness.setAssignment(SlayerMaster.NONE, 0, null);
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertTrue(harness.startNow());
		LedgerRecord record = completeAndSave(18);
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), record.getSlayerMaster());
		assertEquals(Integer.valueOf(AREA), record.getSlayerArea());
		assertEquals("Kraken Cove", record.getTaskLocation());
		assertEquals(Integer.valueOf(18), record.getPointsEarned());
	}

	@Test
	public void olderRecordWithoutTheFieldsStillLoads() throws IOException
	{
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		String json = "{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"old\",\"monster\":\"Kraken\","
			+ "\"creatureId\":42,\"initialAmount\":3,\"kills\":3,\"activeMillis\":60000,\"startedAt\":1000,"
			+ "\"endedAt\":61000,\"completed\":true,\"partial\":false}]}";
		Files.write(harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json"), json.getBytes(StandardCharsets.UTF_8));

		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.completeTask(18);
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(2, records.size());
		LedgerRecord old = records.stream().filter(r -> "old".equals(r.getId())).findFirst().orElseThrow(AssertionError::new);
		assertNull(old.getSlayerMaster());
		assertNull(old.getPointsEarned());
		assertNull(old.getTaskStreak());
		List<String> rows = historyText();
		assertEquals(2, rows.size());
		String oldRow = rows.get(1);
		assertTrue(oldRow, oldRow.endsWith("<br>Deaths: -</html>"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import net.runelite.api.ChatMessageType;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Bonecrusher handling, superior spawns and bank trips as wired in the plugin ({@link PluginHarness}): the crusher is
 * read from the inventory and worn items at each loot drop on the client thread, the spawn message and bank interfaces
 * count only while RUNNING, and the counts survive logout and a restart. {@link CrushedLootFilterTest},
 * {@link SuperiorSpawnMessageTest}, {@link BankTripCounterTest} and {@link SessionTrackerCountersTest} cover the rules.
 */
public class HarnessTaskDetailsTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String SUPERIOR = "<col=ef1020>A superior foe has appeared...</col>";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.WYRM_BONES, "Wyrm bones", 600, 1, "Bury");
		harness.defineItem(ItemID.ABYSSAL_ASHES, "Abyssal ashes", 300, 1, "Scatter");
		harness.defineItem(ItemID.COINS, "Coins", 1, 1);
		harness.defineItem(ItemID.BONECRUSHER, "Bonecrusher", 0, 1);
		harness.defineItem(ItemID.BONECRUSHER_NECKLACE, "Bonecrusher necklace", 0, 1, "Wear");
		harness.defineItem(ItemID.ASH_SANCTIFIER, "Ash sanctifier", 0, 1);
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Wyrms", 10, 10);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
	}

	/** Loot from one kill, arriving through LootManager on the next tick. */
	private void killDrops()
	{
		harness.lootOnNextTick(ItemID.WYRM_BONES, 1);
		harness.lootOnNextTick(ItemID.ABYSSAL_ASHES, 1);
		harness.lootOnNextTick(ItemID.COINS, 100);
		harness.tick();
	}

	private ItemTally loot()
	{
		return harness.tracker().getLoot();
	}

	// ---- Bonecrusher ----

	@Test
	public void lootWithoutACrusherKeepsBonesAndAshes()
	{
		killDrops();
		assertEquals(1, loot().get(ItemID.WYRM_BONES));
		assertEquals(1, loot().get(ItemID.ABYSSAL_ASHES));
		assertEquals(100, loot().get(ItemID.COINS));
	}

	@Test
	public void crusherIsCheckedAtEachLootDrop()
	{
		harness.setInventory(PluginHarness.item(ItemID.BONECRUSHER, 1));
		killDrops();
		assertEquals("crushed", 0, loot().get(ItemID.WYRM_BONES));
		assertEquals(1, loot().get(ItemID.ABYSSAL_ASHES));
		assertEquals(100, loot().get(ItemID.COINS));

		// Banked mid-task: the next kill's bones count again.
		harness.setInventory();
		killDrops();
		assertEquals(1, loot().get(ItemID.WYRM_BONES));

		// A worn bonecrusher necklace and an ash sanctifier.
		harness.setWorn(EquipmentInventorySlot.AMULET, ItemID.BONECRUSHER_NECKLACE, 1);
		harness.setInventory(PluginHarness.item(ItemID.ASH_SANCTIFIER, 1));
		killDrops();
		assertEquals(1, loot().get(ItemID.WYRM_BONES));
		assertEquals(2, loot().get(ItemID.ABYSSAL_ASHES));
		assertEquals(300, loot().get(ItemID.COINS));

		harness.endTask();
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.WYRM_BONES));
		assertEquals(Long.valueOf(2), record.getLoot().get(ItemID.ABYSSAL_ASHES));
	}

	@Test
	public void lootPostedBetweenTicksIsFilteredToo()
	{
		harness.setInventory(PluginHarness.item(ItemID.BONECRUSHER, 1));
		harness.postLoot(ItemID.WYRM_BONES, 1);
		assertEquals(0, loot().get(ItemID.WYRM_BONES));
	}

	@Test
	public void overridesIgnoreWhatIsCarried()
	{
		harness.config.bonecrusherHandling = BonecrusherMode.ALWAYS_EXCLUDE;
		killDrops();
		assertEquals(0, loot().get(ItemID.WYRM_BONES));
		assertEquals(0, loot().get(ItemID.ABYSSAL_ASHES));
		assertEquals(100, loot().get(ItemID.COINS));

		harness.config.bonecrusherHandling = BonecrusherMode.NEVER_EXCLUDE;
		harness.setInventory(PluginHarness.item(ItemID.BONECRUSHER, 1), PluginHarness.item(ItemID.ASH_SANCTIFIER, 1));
		killDrops();
		assertEquals(1, loot().get(ItemID.WYRM_BONES));
		assertEquals(1, loot().get(ItemID.ABYSSAL_ASHES));
	}

	@Test
	public void lootOfOnlyCrushedBonesAddsNothing()
	{
		harness.setInventory(PluginHarness.item(ItemID.BONECRUSHER, 1));
		harness.lootOnNextTick(ItemID.WYRM_BONES, 1);
		harness.tick();
		assertTrue(loot().isEmpty());
	}

	// ---- Superior spawns ----

	@Test
	public void superiorSpawnCountsOnlyWhileRunning()
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.chat(ChatMessageType.SPAM, SUPERIOR);
		harness.chat(ChatMessageType.PUBLICCHAT, SUPERIOR);
		harness.chat(ChatMessageType.GAMEMESSAGE, "A superior foe has appeared");
		assertEquals(2, harness.tracker().getSuperiorsSpawned());

		harness.pause();
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		assertEquals("not while paused", 2, harness.tracker().getSuperiorsSpawned());

		assertTrue(harness.startNow());
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.endTask();
		assertEquals(Integer.valueOf(3), harness.onlyRecord(ACCOUNT).getSuperiorsSpawned());
	}

	@Test
	public void superiorSpawnWithJagexColourMarkupCounts()
	{
		// The exact message from the client log of the 2026-11-09 playtest.
		harness.chat(ChatMessageType.GAMEMESSAGE, "@mes_hl_red@A superior foe has appeared...</col>");
		assertEquals(1, harness.tracker().getSuperiorsSpawned());
		harness.endTask();
		assertEquals(Integer.valueOf(1), harness.onlyRecord(ACCOUNT).getSuperiorsSpawned());
	}

	@Test
	public void superiorSpawnDuringTheCompletionGraceWindowIsNotAdded()
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.completeTask();
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertFalse(harness.tracker().hasPendingCompletion());

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(Integer.valueOf(1), record.getSuperiorsSpawned());
	}

	// ---- Bank trips ----

	@Test
	public void bankOpensAndReopensCountAsTrips()
	{
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.ticks(5);
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.ticks(10);
		// A forgotten item: the same trip.
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		assertEquals(1, harness.tracker().getBankTrips());

		harness.ticks(BankTripCounter.SAME_TRIP_TICKS + 1);
		harness.openInterface(InterfaceID.BANK_DEPOSITBOX);
		harness.closeInterface(InterfaceID.BANK_DEPOSITBOX);
		assertEquals(2, harness.tracker().getBankTrips());

		// Other interfaces are not banks.
		harness.ticks(BankTripCounter.SAME_TRIP_TICKS + 1);
		harness.openInterface(InterfaceID.SEED_VAULT);
		harness.closeInterface(InterfaceID.SEED_VAULT);
		assertEquals(2, harness.tracker().getBankTrips());

		harness.openInterface(InterfaceID.SHARED_BANK);
		assertEquals(3, harness.tracker().getBankTrips());
		harness.closeInterface(InterfaceID.SHARED_BANK);

		harness.endTask();
		assertEquals(Integer.valueOf(3), harness.onlyRecord(ACCOUNT).getBankTrips());
	}

	@Test
	public void bankingWhilePausedIsNotATripAndANewSessionStartsAtZero()
	{
		harness.pause();
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		assertEquals(0, harness.tracker().getBankTrips());
		harness.ticks(BankTripCounter.SAME_TRIP_TICKS + 1);
		assertTrue(harness.startNow());
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		assertEquals(1, harness.tracker().getBankTrips());
		harness.endTask();
		assertEquals(Integer.valueOf(1), harness.onlyRecord(ACCOUNT).getBankTrips());

		// The next session's first bank visit counts even within the window, and its count starts at 0.
		harness.trackAgain();
		assertTrue(harness.startNow());
		assertEquals(0, harness.tracker().getBankTrips());
		harness.openInterface(InterfaceID.BANKMAIN);
		assertEquals(1, harness.tracker().getBankTrips());
	}

	// ---- Persistence and panel ----

	@Test
	public void countsSurviveLogoutAndARestart()
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.logout();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertNotNull(snapshot);
		assertEquals(Integer.valueOf(1), snapshot.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), snapshot.getBankTrips());
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("restored as logged out", SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertEquals(1, harness.tracker().getSuperiorsSpawned());
		assertEquals(1, harness.tracker().getBankTrips());
		assertTrue(harness.startNow());
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.endTask();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Integer.valueOf(2), record.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(2), record.getBankTrips());
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void panelShowsTheCountsOnlyWhileASessionIsActive()
	{
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		harness.openInterface(InterfaceID.BANKMAIN);
		assertEquals("Superiors: 1 | Deaths: 0 | Bank trips: 1", countsText());
		harness.pause();
		assertEquals("Superiors: 1 | Deaths: 0 | Bank trips: 1", countsText());
		harness.endTask();
		assertNull("hidden once the session ended", countsText());
	}

	private String countsText()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().getCountsText();
		});
		return text[0];
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.ui.PluginPanel;
import org.junit.Rule;
import org.junit.Test;

/**
 * The task icons of Overall totals as wired in the plugin: By monster's group names and By master's monsters
 * assigned show the task's item sprite at the small slot size, through the {@code ItemManager.getImage} fake, on the
 * EDT; an unknown task keeps an empty slot of the same size; nothing is asked for while the section is closed or by
 * the refresh timer.
 */
public class HarnessTaskIconsTest
{
	/** A name that is no task, long enough to test the sidebar's width. */
	private static final String UNKNOWN = "Lava strykewyrms in the Wilderness Slayer Cave";
	private static final String SLOT = " " + ItemListView.ICON_WIDTH + "x" + ItemListView.ICON_HEIGHT;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Test
	public void byMonsterNamesShowTheirTasksIcon()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			records.add(monster("Dust devils"));
		}
		for (int i = 0; i < 2; i++)
		{
			LedgerRecord deviant = monster("Aberrant spectres");
			deviant.setVariant("Deviant spectres");
			records.add(deviant);
		}
		LedgerRecord cannon = monster("Dust devils");
		cannon.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 200L));
		records.add(cannon);
		records.add(monster(UNKNOWN));
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, records);
			harness.ui().getOverallTotals().clickTitle();
			harness.ui().getOverallTotals().setGrouping(OverallTotals.Grouping.MONSTER);
		});

		List<String> rows = rows();
		assertEquals(4, rows.size());
		// The names read as before: the icon is on the name's label, not in its text.
		assertTrue(rows.get(0), rows.get(0).startsWith("Dust devils | 3 tasks\n"));
		assertTrue(rows.get(1), rows.get(1).startsWith("Deviant spectres | 2 tasks\n"));
		assertTrue(rows.get(2), rows.get(2).startsWith("Dust devils (cannon) | 1 task\n"));
		assertTrue(rows.get(3), rows.get(3).startsWith(UNKNOWN + " | 1 task\n"));
		// A Catacombs variant and a cannon task show their task's icon; an unknown task an empty slot of the same size.
		assertEquals(Arrays.asList(ItemID.SLAYERGUIDE_DUSTDEVIL + SLOT, ItemID.SLAYERGUIDE_ABERRANTSPECTER + SLOT,
			ItemID.SLAYERGUIDE_DUSTDEVIL + SLOT, "-" + SLOT),
			onEdt(() -> harness.ui().getOverallTotals().getNameIcons()));

		int width = onEdt(() -> harness.ui().getOverallTotals().getListPreferredWidth());
		assertTrue("wants " + width, width <= PluginPanel.PANEL_WIDTH);

		// Overall and By month have no icons; By master shows the master's face (HarnessMoreIconsTest).
		for (OverallTotals.Grouping grouping : Arrays.asList(OverallTotals.Grouping.ALL,
			OverallTotals.Grouping.MONTH))
		{
			harness.onEdt(() -> harness.ui().getOverallTotals().setGrouping(grouping));
			harness.drain();
			assertEquals(grouping.toString(), Collections.singletonList("none"),
				onEdt(() -> harness.ui().getOverallTotals().getNameIcons()));
		}
	}

	@Test
	public void monstersAssignedLinesShowTheirTasksIcon()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		LedgerRecord deviant = monster("Aberrant spectres");
		deviant.setVariant("Deviant spectres");
		LedgerRecord cannon = monster("Dust devils");
		cannon.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 200L));
		List<LedgerRecord> records = Arrays.asList(monster("Dust devils"), monster("Dust devils"), cannon, deviant);
		List<AssignmentEntry> entries = Arrays.asList(entry("Abyssal demons"), entry(UNKNOWN));
		harness.onEdt(() ->
		{
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, records);
			harness.historyModel().setAssignments(PluginHarness.ACCOUNT, entries);
			harness.ui().getOverallTotals().clickTitle();
			harness.ui().getOverallTotals().setGrouping(OverallTotals.Grouping.MASTER);
		});
		rows();

		// Variants and cannon tasks count as their task, with its icon; the unknown name keeps an empty slot.
		assertEquals(Arrays.asList("Dust devils | 3 / 6 (50%)", "Aberrant spectres | 1 / 6 (17%)",
			"Abyssal demons | 1 / 6 (17%)", UNKNOWN + " | 1 / 6 (17%)"),
			onEdt(() -> harness.ui().getOverallTotals().getAssignments(0).getLineTexts()));
		assertEquals(Arrays.asList(ItemID.SLAYERGUIDE_DUSTDEVIL + SLOT, ItemID.SLAYERGUIDE_ABERRANTSPECTER + SLOT,
			ItemID.SLAYERGUIDE_ABYSSALDEMON + SLOT, "-" + SLOT),
			onEdt(() -> harness.ui().getOverallTotals().getAssignments(0).getLineIcons()));
		// The master's name shows the master's face, or an empty slot when the image is not bundled.
		String konar = MasterIcons.fileName("Konar");
		assertEquals(Collections.singletonList(MasterIcons.class.getResource(MasterIcons.DIRECTORY + konar) != null
			? "master:" + konar + SLOT : "-" + SLOT), onEdt(() -> harness.ui().getOverallTotals().getNameIcons()));

		int width = onEdt(() -> harness.ui().getOverallTotals().getListPreferredWidth());
		assertTrue("wants " + width, width <= PluginPanel.PANEL_WIDTH);

		// Equal lines are not drawn again: the same entries again rebuild the totals but ask for no icon.
		int before = harness.itemImageRequests();
		int builds = onEdt(() -> harness.ui().getOverallTotals().getBuildCount());
		harness.onEdt(() -> harness.historyModel().setAssignments(PluginHarness.ACCOUNT, new ArrayList<>(entries)));
		harness.drain();
		assertTrue("the totals were built again",
			onEdt(() -> harness.ui().getOverallTotals().getBuildCount()) > builds);
		assertEquals(before, harness.itemImageRequests());
	}

	@Test
	public void noIconIsAskedForWhileClosedOrByTheRefreshTimer()
	{
		harness.startUp();
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		List<LedgerRecord> records = Arrays.asList(monster("Dust devils"), monster("Kurask"));
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT, records));
		harness.drain();
		// The Task history rows have asked for theirs; the closed totals ask for none.
		int before = harness.itemImageRequests();
		harness.onEdt(() ->
		{
			harness.ui().getOverallTotals().setGrouping(OverallTotals.Grouping.MONSTER);
			harness.panel().refresh();
		});
		harness.drain();
		assertEquals("closed: no icons", before, harness.itemImageRequests());

		// Opening asks for the two icons once, on the EDT (the fake fails a call from any other thread).
		harness.onEdt(() -> harness.ui().getOverallTotals().clickTitle());
		rows();
		assertEquals(before + 2, harness.itemImageRequests());
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			harness.panel().refresh();
		});
		harness.drain();
		assertEquals("the refresh timer asks for none", before + 2, harness.itemImageRequests());

		// Closed again, new records ask for none in the totals: only the one Task history row asks for its icon.
		harness.onEdt(() ->
		{
			harness.ui().getOverallTotals().clickTitle();
			harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(monster("Nechryael")));
		});
		harness.drain();
		assertEquals(before + 3, harness.itemImageRequests());
	}

	/** A completed Konar task of {@code name}, without values. */
	private static LedgerRecord monster(String name)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(UUID.randomUUID().toString());
		record.setMonster(name);
		record.setSlayerMaster(SlayerMaster.KONAR);
		record.setEndedAt(1);
		record.setKills(10);
		record.setActiveMillis(30 * 60_000L);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}

	/** A Konar "Skipped / blocked" entry. */
	private static AssignmentEntry entry(String name)
	{
		AssignmentEntry entry = new AssignmentEntry();
		entry.setId(UUID.randomUUID().toString());
		entry.setMonster(name);
		entry.setSlayerMaster(SlayerMaster.KONAR);
		entry.setOutcome(AssignmentOutcome.SKIPPED);
		entry.setEndedAt(1);
		return entry;
	}

	/** Reads {@code read} on the EDT. */
	private <T> T onEdt(Supplier<T> read)
	{
		AtomicReference<T> value = new AtomicReference<>();
		harness.onEdt(() -> value.set(read.get()));
		return value.get();
	}

	/** The Overall totals rows, after the totals worked out off the EDT arrive. */
	private List<String> rows()
	{
		harness.drain();
		return onEdt(() -> harness.ui().getOverallTotals().getRows());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Task locations as wired in the plugin ({@link PluginHarness}): the current task's
 * statistics, which the live card's time left and the overlay's pace use, come only from the history at the task's
 * spot when there is some (the session's spot, else the assigned area's, else the spot where the player is), matched
 * by spot id, and name the location; otherwise from all of it. The History estimate that showed them went with the
 * advisor card. {@link TaskStatisticsTest} and {@link TaskLocationTest} cover the rules.
 */
public class HarnessTaskLocationEstimateTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final long MINUTE = 60_000L;
	private static final int TASK = 42;
	private static final int SMOKE = 12_946;
	private static final int CATACOMBS = 6_557;
	/** A region the spot table doesn't list, with no history: named "Region 12342" until the player renames it. */
	private static final int UNLISTED = TestSpots.UNLISTED;
	private static final int KONAR_AREA = 7;
	private static final String SMOKE_ID = TestSpots.SMOKE_ID;
	private static final String CATACOMBS_ID = TestSpots.CATACOMBS_ID;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Dust devils", 20, 20);
		harness.setPlayerRegion(SMOKE);
	}

	/**
	 * A completed Dust devils task of 10 kills in {@code minutes} minutes, 1,000 gp loot a minute (in coins), at the
	 * spot {@code spotId} ({@code null}: Unknown).
	 */
	private static LedgerRecord task(int minutes, String spotId)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId("task-" + minutes);
		record.setCreatureId(TASK);
		record.setMonster("Dust devils");
		record.setKills(10);
		record.setActiveMillis(minutes * MINUTE);
		record.setCompleted(true);
		record.setLootGeValue(minutes * 1_000L);
		record.setLootHaValue(minutes * 1_000L);
		record.setSuppliesGeValue(0L);
		record.setSupplies(Collections.singletonMap(100, (long) minutes));
		record.setBankTrips(0);
		record.setSpotId(spotId);
		return SavedItems.withItems(record);
	}

	private void name(int region, String name)
	{
		harness.setRsProfileConfig(SlayerLedgerConfig.GROUP, SlayerLedgerPlugin.LOCATION_NAME_KEY_PREFIX + region, name);
	}

	private void showRecords(LedgerRecord... records)
	{
		harness.onEdt(() -> harness.historyModel().setRecords(ACCOUNT, Arrays.asList(records)));
		harness.drain();
	}

	/**
	 * The current task's statistics as the live card's time left reads them, after a refresh, once the location names
	 * asked of the plugin have arrived.
	 */
	private TaskStatistics stats()
	{
		harness.onEdt(() -> harness.panel().refresh());
		harness.drain();
		final AtomicReference<TaskStatistics> stats = new AtomicReference<>();
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			stats.set(harness.historyModel().taskStatistics(TASK, "Dust devils",
				harness.tracker().getCurrentTaskSelection(), harness.historyModel().currentLocation()));
		});
		return stats.get();
	}

	/** {@link #stats} in short: "Smoke Dungeon (1 task) | 60s a kill", or "All locations (...)" for all of them. */
	private String statistics()
	{
		TaskStatistics stats = stats();
		return (stats.getLocation() == null ? "All locations" : stats.getLocation()) + " ("
			+ SlayerLedgerPanel.sampleTasks(stats.getSampleCount()) + ") | " + stats.getMillisPerKill() / 1_000
			+ "s a kill";
	}

	/** Kills {@code n} more of the task in {@code region} (the count drops on the next tick). */
	private void kill(int n, int region)
	{
		harness.setPlayerRegion(region);
		harness.setRemaining(harness.tracker().getCurrentRemaining() - n);
		harness.tick();
	}

	@Test
	public void theStatisticsUseOnlyTheHistoryWhereThePlayerIs()
	{
		name(SMOKE, "Smoke Dungeon");
		name(CATACOMBS, "Catacombs of Kourend");
		harness.loginAndSettle(ACCOUNT);
		showRecords(task(10, SMOKE_ID), task(30, CATACOMBS_ID), task(50, CATACOMBS_ID));

		assertEquals("Smoke Dungeon (1 task) | 60s a kill", statistics());

		// Walking to the Catacombs while the task is idle: its two tasks there.
		harness.setPlayerRegion(CATACOMBS);
		harness.tick();
