package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.List;
import net.runelite.api.ChatMessageType;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Keys, clue scrolls and notable drops as wired in the plugin ({@link PluginHarness}): counted from loot received while
 * the session runs, notable stacks valued at the "Notable drop value" and "Loot price" settings, pet messages, the live
 * panel, the saved record and its history tooltip, and the active session file. {@link KeysAndCluesTest},
 * {@link NotableDropsTest} and {@link PetMessageTest} cover the rules.
 */
public class HarnessTaskLootTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final int HARD_CLUE = ClueScrollIds.HARD[0];
	private static final int ELITE_CLUE = ClueScrollIds.ELITE[0];
	private static final String PET_TEXT = "<col=ef1020>You have a funny feeling like you're being followed.</col>";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 50, 50);
		harness.setVarbit(VarbitID.SLAYER_TASKS_COMPLETED, 10);
		harness.defineItem(ItemID.ABYSSAL_WHIP, "Abyssal whip", 1_500_000, 72_000);
		harness.defineItem(ItemID.RUNE_PLATEBODY, "Rune platebody", 100_000, 39_000);
		harness.defineItem(ItemID.RUNE_FULL_HELM, "Rune full helm", 99_999, 21_120);
		harness.defineItem(ItemID.KONAR_KEY, "Brimstone key", 0, 0);
	}

	private void loot(int... idQuantityPairs)
	{
		for (int i = 0; i < idQuantityPairs.length; i += 2)
		{
			harness.lootOnNextTick(idQuantityPairs[i], idQuantityPairs[i + 1]);
		}
		harness.tick();
	}

	private List<String> liveLines()
	{
		final List<?>[] lines = new List<?>[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			lines[0] = harness.ui().getTaskLootLines();
		});
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) lines[0];
		return result;
	}

	private String liveTooltip()
	{
		final String[] text = new String[1];
		harness.onEdt(() -> text[0] = harness.ui().getTaskLootTooltip());
		return text[0];
	}

	/**
	 * The history rows. The brimstone key has no GE price, so the history waits for it until the wait runs out
	 *; the wait is run out first.
	 */
	private List<String> historyText()
	{
		final List<?>[] rows = new List<?>[1];
		harness.onEdt(() ->
		{
			harness.historyModel().expireCurrentPricesWait();
			harness.historyModel().endExpiredCurrentPricesWait();
			rows[0] = harness.ui().getHistory().getValuesText();
		});
		@SuppressWarnings("unchecked")
		final List<String> result = (List<String>) rows[0];
		return result;
	}

	private List<NotableDrop> sessionDrops()
	{
		return harness.tracker().getNotableDrops();
	}

	@Test
	public void lootWhileRunningCountsAndLootWhilePausedDoesNot()
	{
		harness.loginAndSettle(ACCOUNT);
		assertNull("nothing to show yet", liveLines());
		assertTrue(harness.startNow());
		assertNull(liveLines());

		loot(ItemID.ABYSSAL_WHIP, 1, ItemID.KONAR_KEY, 2, HARD_CLUE, 1);
		assertEquals(Arrays.asList("Keys: 2 brimstone", "Clues: 1 hard", "Notable drops:", "  Abyssal whip: 1.5M"),
			liveLines());
		assertEquals("<html>Notable drops:<br>&nbsp;&nbsp;Abyssal whip: 1,500,000 gp</html>", liveTooltip());

		harness.pause();
		loot(ItemID.ABYSSAL_WHIP, 1, ItemID.KONAR_KEY, 1, ELITE_CLUE, 1);
		assertEquals("paused: nothing counted", Arrays.asList("Keys: 2 brimstone", "Clues: 1 hard",
			"Notable drops:", "  Abyssal whip: 1.5M"), liveLines());
		assertEquals(1, sessionDrops().size());

		harness.endTask();
		assertNull("hidden once the session ends", liveLines());
		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(2), record.getLoot().get(ItemID.KONAR_KEY));
		assertEquals(1, record.getNotableDrops().size());
		NotableDrop whip = record.getNotableDrops().get(0);
		assertEquals(Integer.valueOf(ItemID.ABYSSAL_WHIP), whip.getItemId());
		assertEquals("Abyssal whip", whip.getName());
		assertEquals(1, whip.getQuantity());
		assertEquals(Long.valueOf(1_500_000), whip.getGeValue());
		assertEquals(Long.valueOf(72_000), whip.getHaValue());
		assertFalse(whip.isPet());

		String row = historyText().get(0);
		assertTrue(row, row.contains("<br>Keys: 2 brimstone<br>Clues: 1 hard<br>Notable drops:"
			+ "<br>&nbsp;&nbsp;Abyssal whip: 1,500,000 gp"));
	}

	/**
	 * Notable drops are priced through ItemManager only while loot may be kept: never for loot while no task is
	 * assigned, but while one waits for its first kill (buffered, V2 plan 4.1), while running and for the final kill's
	 * loot in the held-completion grace window.
	 */
	@Test
	public void notableDropsArePricedOnlyWhileLootIsRecorded()
	{
		harness.setRemaining(0);
		harness.loginAndSettle(ACCOUNT);
		final int idleLookups = harness.itemPriceLookups(ItemID.ABYSSAL_WHIP);
		loot(ItemID.ABYSSAL_WHIP, 1);
		assertEquals("no price lookup for loot while no task is assigned", idleLookups,
			harness.itemPriceLookups(ItemID.ABYSSAL_WHIP));

		harness.setTask(TASK, "Abyssal demons", 2, 50);
		harness.tick();
		loot(ItemID.ABYSSAL_WHIP, 1);
		final int waitingLookups = harness.itemPriceLookups(ItemID.ABYSSAL_WHIP);
		assertTrue("priced while the task waits for its first kill: the loot is buffered",
			waitingLookups > idleLookups);

		assertTrue(harness.startNow());
		assertEquals("Play drops the buffer", 0, sessionDrops().size());
		loot(ItemID.ABYSSAL_WHIP, 1);
		assertTrue("priced while running", harness.itemPriceLookups(ItemID.ABYSSAL_WHIP) > waitingLookups);
		assertEquals(1, sessionDrops().size());

		harness.setRemaining(1);
		harness.tick();
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		final int heldLookups = harness.itemPriceLookups(ItemID.ABYSSAL_WHIP);
		loot(ItemID.ABYSSAL_WHIP, 1);
		assertTrue("priced in the grace window", harness.itemPriceLookups(ItemID.ABYSSAL_WHIP) > heldLookups);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals("the running kill's and the final kill's whips", 2, record.getNotableDrops().size());
	}

	@Test
	public void thresholdBoundaryAndChangingTheSetting()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());

		loot(ItemID.RUNE_PLATEBODY, 1, ItemID.RUNE_FULL_HELM, 1);
		assertEquals("exactly the threshold is notable; 1 gp below is not", 1, sessionDrops().size());
		assertEquals(Integer.valueOf(ItemID.RUNE_PLATEBODY), sessionDrops().get(0).getItemId());

		harness.setNotableDropThreshold(200_000);
		loot(ItemID.RUNE_PLATEBODY, 1);
		assertEquals("below the new threshold", 1, sessionDrops().size());
		loot(ItemID.RUNE_PLATEBODY, 2);
		assertEquals("one stack of two is worth the threshold", 2, sessionDrops().size());
		assertEquals(Long.valueOf(200_000), sessionDrops().get(1).getGeValue());
		assertEquals("  Rune platebody x 2: 200K", liveLines().get(1));

		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.setNotableDropThreshold(100_000);
		loot(ItemID.ABYSSAL_WHIP, 1);
		assertEquals("the whip alchs for 72K: not notable in high alch mode", 2, sessionDrops().size());
		loot(ItemID.RUNE_PLATEBODY, 3);
		assertEquals(3, sessionDrops().size());
		assertEquals("values follow the setting", Arrays.asList("Notable drops:", "  Rune platebody x 3: 117K",
			"  Rune platebody x 2: 78K", "  Rune platebody: 39K"), liveLines());
	}

	@Test
	public void petMessageWhileRunningIsANotableDrop()
	{
		harness.loginAndSettle(ACCOUNT);
		harness.chat(ChatMessageType.GAMEMESSAGE, PET_TEXT);
		assertTrue(harness.startNow());
		harness.pause();
		harness.chat(ChatMessageType.GAMEMESSAGE, PET_TEXT);
		assertTrue("not counted while paused or idle", sessionDrops().isEmpty());

		assertTrue(harness.startNow());
		harness.chat(ChatMessageType.PUBLICCHAT, PET_TEXT);
		assertTrue("not a game message", sessionDrops().isEmpty());
		harness.chat(ChatMessageType.GAMEMESSAGE, PET_TEXT);
		harness.chat(ChatMessageType.GAMEMESSAGE,
			"You have a funny feeling like you would have been followed...");
		assertEquals(Arrays.asList("Notable drops:", "  Pet (already owned)", "  Pet"), liveLines());

		harness.endTask();
		List<NotableDrop> drops = harness.onlyRecord(ACCOUNT).getNotableDrops();
		assertEquals(2, drops.size());
		assertEquals(NotableDrop.Pet.RECEIVED, drops.get(0).getPet());
		assertEquals(NotableDrop.Pet.DUPLICATE, drops.get(1).getPet());
	}

	@Test
	public void finalKillDropsDuringTheGraceWindowGoToTheCompletedTask()
	{
		harness.setTask(TASK, "Abyssal demons", 1, 50);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.chat(ChatMessageType.GAMEMESSAGE, PET_TEXT);
		loot(ItemID.ABYSSAL_WHIP, 1, ItemID.KONAR_KEY, 1);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(2, record.getNotableDrops().size());
		assertTrue(record.getNotableDrops().get(0).isPet());
		assertEquals(Integer.valueOf(ItemID.ABYSSAL_WHIP), record.getNotableDrops().get(1).getItemId());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.KONAR_KEY));
	}

	@Test
	public void activeSessionKeepsItsNotableDropsAcrossARestart()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		loot(ItemID.ABYSSAL_WHIP, 1, HARD_CLUE, 1);
		harness.logout();
		harness.shutDown();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertEquals(1, snapshot.getNotableDrops().size());
		assertEquals(Long.valueOf(1_500_000), snapshot.getNotableDrops().get(0).getGeValue());

		// Today's price has dropped; the drop keeps the value it had.
		harness.setGePrice(ItemID.ABYSSAL_WHIP, 1_000_000);
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertEquals(Arrays.asList("Clues: 1 hard", "Notable drops:", "  Abyssal whip: 1.5M"), liveLines());

		assertTrue(harness.startNow());
		loot(ItemID.ABYSSAL_WHIP, 1);
		harness.endTask();
		List<NotableDrop> drops = harness.onlyRecord(ACCOUNT).getNotableDrops();
		assertEquals(2, drops.size());
		assertEquals(Long.valueOf(1_500_000), drops.get(0).getGeValue());
		assertEquals(Long.valueOf(1_000_000), drops.get(1).getGeValue());
	}

	@Test
	public void olderRecordsStillLoadAndRecordsWithLootGainKeyCounts() throws IOException
	{
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		String json = "{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"old\",\"monster\":\"Kraken\","
			+ "\"creatureId\":42,\"initialAmount\":3,\"kills\":3,\"activeMillis\":60000,\"startedAt\":1000,"
			+ "\"endedAt\":61000,\"completed\":true,\"partial\":false},"
			+ "{\"schemaVersion\":2,\"id\":\"withLoot\",\"monster\":\"Kraken\",\"creatureId\":42,\"initialAmount\":3,"
			+ "\"kills\":3,\"activeMillis\":60000,\"startedAt\":2000,\"endedAt\":62000,\"completed\":true,"
			+ "\"partial\":false,\"loot\":{\"" + ItemID.KONAR_KEY + "\":1,\"995\":500}}]}";
		Files.write(harness.ledgerDirectory().toPath().resolve(ACCOUNT + ".json"), json.getBytes(StandardCharsets.UTF_8));

		harness.loginAndSettle(ACCOUNT);
		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(2, records.size());
		for (LedgerRecord r : records)
		{
			assertNull(r.getNotableDrops());
		}
		List<String> rows = historyText();
		assertEquals(2, rows.size());
		assertTrue("derived from the saved loot", rows.get(0).endsWith("<br>Deaths: -<br>Keys: 1 brimstone</html>"));
		assertTrue("unchanged", rows.get(1).endsWith("<br>Deaths: -</html>"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Task notes as wired in the plugin ({@link PluginHarness}): the panel's note box sets the live session's note on
 * the EDT, the note is saved on the record, kept across logout and a restart, and a saved record's note is rewritten
 * on the executor. {@link TaskNoteTest} and {@link SessionTrackerNoteTest} cover the rules.
 */
public class HarnessTaskNoteTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Wyrms", 10, 10);
		harness.loginAndSettle(ACCOUNT);
	}

	/** Types a note in the panel's note box and commits it (Enter), on the EDT. */
	private void typeNote(String text)
	{
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			harness.ui().typeNote(text);
		});
		harness.drain();
	}

	/** The note box's text after a refresh, or {@code null} while it is hidden. */
	private String noteBox()
	{
		final String[] text = new String[1];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			text[0] = harness.ui().isNoteShown() ? harness.ui().getNoteText() : null;
		});
		return text[0];
	}

	/** The panel's list of recent notes. */
	private List<String> recentNotes()
	{
		final AtomicReference<List<String>> recent = new AtomicReference<>();
		harness.onEdt(() -> recent.set(harness.ui().getRecentNotes()));
		return recent.get();
	}

	@Test
	public void noteSetWhileRunningIsSavedOnTheRecord()
	{
		assertNull("hidden without a session", noteBox());
		assertTrue(harness.startNow());
		assertEquals("", noteBox());
		typeNote("  Barrage   and  burst ");
		assertEquals("Barrage and burst", harness.tracker().getNote());
		assertEquals("shown as saved", "Barrage and burst", noteBox());

		harness.pause();
		typeNote("Prayer gear");
		assertEquals("Prayer gear", noteBox());
		harness.endTask();
		assertNull("hidden once the session ended", noteBox());

		assertEquals("Prayer gear", harness.onlyRecord(ACCOUNT).getNote());
		assertEquals("offered first next time", "Prayer gear", recentNotes().get(0));

		harness.trackAgain();
		assertTrue(harness.startNow());
		assertEquals("a new session starts without a note", "", noteBox());
	}

	@Test
	public void clearingTheNoteSavesNone()
	{
		assertTrue(harness.startNow());
		typeNote("Cannon");
		typeNote("   ");
		assertNull(harness.tracker().getNote());
		harness.endTask();
		assertNull(harness.onlyRecord(ACCOUNT).getNote());
	}

	@Test
	public void noteSurvivesLogoutAndARestart()
	{
		assertTrue(harness.startNow());
		typeNote("Range pray");
		harness.logout();
		SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertNotNull(snapshot);
		assertEquals("Range pray", snapshot.getNote());
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("restored as logged out", SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertEquals("Range pray", harness.tracker().getNote());
		assertEquals("Range pray", noteBox());
		assertTrue(harness.startNow());
		harness.endTask();
		assertEquals("Range pray", harness.onlyRecord(ACCOUNT).getNote());
	}

	@Test
	public void noteKeptInMemoryAcrossARelogin()
	{
		assertTrue(harness.startNow());
		typeNote("Strength gear");
		harness.logout();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertEquals("Strength gear", noteBox());
	}

	@Test
	public void noteSetDuringTheCompletionGraceWindowIsSaved()
	{
		assertTrue(harness.startNow());
		final String sessionId = harness.tracker().getSessionId();
		harness.completeTask();
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		harness.onEdt(() -> harness.plugin.setSessionNote(ACCOUNT, sessionId, "Barrage"));
		harness.drain();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertFalse(harness.tracker().hasPendingCompletion());

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals("Barrage", record.getNote());
	}

	@Test
	public void noteSentAfterTheSessionWasSavedGoesToItsRecord()
	{
		assertTrue(harness.startNow());
		final String sessionId = harness.tracker().getSessionId();
		harness.completeTask();
		harness.ticks(1 + SessionTracker.COMPLETION_LOOT_GRACE_TICKS);
		assertEquals(sessionId, harness.onlyRecord(ACCOUNT).getId());

		harness.onEdt(() -> harness.plugin.setSessionNote(ACCOUNT, sessionId, " Cannon "));
		harness.drain();
		assertEquals("Cannon", harness.onlyRecord(ACCOUNT).getNote());
	}

	@Test
	public void noteSentJustAsEndTaskIsPressedReachesTheRecord()
	{
		assertTrue(harness.startNow());
		final String sessionId = harness.tracker().getSessionId();
		// End task queues the record's save on the client thread; a note sent before that runs must still land on it.
		harness.onEdt(() ->
		{
			harness.plugin.endTask();
			harness.plugin.setSessionNote(ACCOUNT, sessionId, "Barrage");
		});
		harness.drain();
		assertEquals("Barrage", harness.onlyRecord(ACCOUNT).getNote());
	}

	@Test
	public void editingASavedRecordsNoteRewritesItAndClearingRemovesIt()
	{
		assertTrue(harness.startNow());
		typeNote("Cannon");
		harness.endTask();
		final LedgerRecord saved = harness.onlyRecord(ACCOUNT);
		assertEquals("Cannon", saved.getNote());

		harness.onEdt(() -> harness.plugin.editRecordNote(ACCOUNT, saved.getId(), "  Burst\n"));
		harness.drain();
		LedgerRecord edited = harness.onlyRecord(ACCOUNT);
		assertEquals("Burst", edited.getNote());
		saved.setNote("Burst");
		assertEquals("only the note changes", saved, edited);
		assertEquals("the panel was refreshed", "Burst", recentNotes().get(0));

		harness.onEdt(() -> harness.plugin.editRecordNote(ACCOUNT, saved.getId(), ""));
		harness.drain();
		assertNull(harness.onlyRecord(ACCOUNT).getNote());
		assertEquals(TaskNote.DEFAULTS, recentNotes());
	}

	@Test
	public void editingANoteNeverTouchesTheActiveSession()
	{
		assertTrue(harness.startNow());
		typeNote("Cannon");
		harness.endTask();
		final String savedId = harness.onlyRecord(ACCOUNT).getId();
		harness.trackAgain();
		assertTrue(harness.startNow());
		typeNote("Barrage");

		harness.onEdt(() -> harness.plugin.editRecordNote(ACCOUNT, savedId, "Burst"));
		harness.drain();
		assertEquals("Burst", harness.onlyRecord(ACCOUNT).getNote());
		assertEquals("Barrage", harness.tracker().getNote());
		assertEquals("Barrage", noteBox());
	}
}

package com.shmayvan.slayerledger;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Setup tags as wired in the plugin ({@link PluginHarness}): a saved task's "Setup..." menu item, its overrides
 * saved on the executor through {@link SlayerLedgerPlugin#editRecordSetup} and shown in the row's tooltip, the live
 * task's overrides carried through a logout and a client restart to its record, and a 1.x ledger shown with its
 * estimated tags without being rewritten. Nothing here waits for the panel's refresh timer: the rows are rebuilt when
 * the records change, and every read follows a drain.
 */
public class HarnessTaskSetupTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setInventory();
		harness.setTask(TASK, "Dust devils", 10, 10);
	}

	private <T> T onEdt(Supplier<T> read)
	{
		final AtomicReference<T> result = new AtomicReference<>();
		harness.onEdt(() -> result.set(read.get()));
		return result.get();
	}

	/** The first history row's tooltip, after everything queued has run. */
	private String tooltip()
	{
		harness.drain();
		return onEdt(() -> harness.ui().getHistory().getTooltips().get(0));
	}

	private void editSetup(String id, SetupOverrides overrides)
	{
		harness.onEdt(() -> harness.plugin.editRecordSetup(ACCOUNT, id, overrides));
		harness.drain();
	}

	private File ledgerFile()
	{
		return new File(harness.ledgerDirectory(), ACCOUNT + ".json");
	}

	private String readLedger() throws IOException
	{
		return new String(Files.readAllBytes(ledgerFile().toPath()), StandardCharsets.UTF_8);
	}

	private void writeLedger(String json) throws IOException
	{
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		Files.write(ledgerFile().toPath(), json.getBytes(StandardCharsets.UTF_8));
	}

	/** Plays a task briefly and ends it, so it is saved as a partial record. */
	private LedgerRecord savedTask()
	{
		assertTrue(harness.startNow());
		harness.endTask();
		return harness.onlyRecord(ACCOUNT);
	}

	@Test
	public void aSavedTasksSetupIsSetFromItsMenuShownInItsTooltipAndCleared()
	{
		harness.loginAndSettle(ACCOUNT);
		final LedgerRecord saved = savedTask();
		assertEquals(Boolean.FALSE, saved.getDetectedCannon());
		assertEquals(SetupStyle.UNKNOWN, saved.getDetectedStyle());
		final List<String> menu = onEdt(() -> harness.ui().getHistory().getMenuItems(0));
		assertEquals(Arrays.asList("Edit note", "Edit location", "Setup…", "Delete task"), menu);
		String tooltip = tooltip();
		assertTrue(tooltip, tooltip.contains("<br>Cannon: No<br>Style: Unknown<br>Gear: Unknown<br>"));
		assertFalse("nothing estimated", tooltip.contains(SetupTags.ESTIMATE_NOTE));

		editSetup(saved.getId(), SetupOverrides.of(true, SetupStyle.BARRAGE, GearFocus.PRAYER));
		final LedgerRecord edited = harness.onlyRecord(ACCOUNT);
		assertEquals(SetupOverrides.of(true, SetupStyle.BARRAGE, GearFocus.PRAYER), SetupOverrides.from(edited));
		SetupOverrides.of(true, SetupStyle.BARRAGE, GearFocus.PRAYER).copyTo(saved);
		assertEquals("only the overrides change", saved, edited);
		tooltip = tooltip();
		assertTrue(tooltip, tooltip.contains("<br>Cannon: Yes (set by you; detected No)<br>Style: Barrage (set by you;"
			+ " detected Unknown)<br>Gear: Prayer (set by you; detected Unknown)<br>"));

		editSetup(saved.getId(), SetupOverrides.of(null, SetupStyle.BARRAGE, null));
		assertEquals(SetupOverrides.of(null, SetupStyle.BARRAGE, null), SetupOverrides.from(harness.onlyRecord(ACCOUNT)));
		editSetup(saved.getId(), SetupOverrides.NONE);
		assertEquals(SetupOverrides.NONE, SetupOverrides.from(harness.onlyRecord(ACCOUNT)));
		tooltip = tooltip();
		assertTrue(tooltip, tooltip.contains("<br>Cannon: No<br>Style: Unknown<br>Gear: Unknown<br>"));
		assertNull(onEdt(() -> harness.ui().getHistory().getErrorText()));
	}

	@Test
	public void aSavedTasksOverridesSurviveAClientRestart()
	{
		harness.loginAndSettle(ACCOUNT);
		final String id = savedTask().getId();
		editSetup(id, SetupOverrides.of(false, SetupStyle.MELEE, null));

		harness.logout();
		harness.shutDown();
		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals(SetupOverrides.of(false, SetupStyle.MELEE, null), SetupOverrides.from(harness.onlyRecord(ACCOUNT)));
		final String tooltip = tooltip();
		assertTrue(tooltip, tooltip.contains("<br>Style: Melee (set by you; detected Unknown)<br>"));
	}

	@Test
	public void theLiveTasksOverridesSurviveALogoutAndARestartAndReachItsRecord()
	{
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		final String id = harness.tracker().getSessionId();
		final SetupOverrides mine = SetupOverrides.of(true, SetupStyle.RANGED, GearFocus.STRENGTH);
		assertTrue(onEdt(() -> harness.tracker().setSetupOverrides(id, mine)));

		harness.logout();
		final SessionSnapshot snapshot = harness.activeSession(ACCOUNT);
		assertEquals(mine, SetupOverrides.from(snapshot));
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("restored as logged out", SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertEquals(mine, harness.tracker().getSetupOverrides());
		assertTrue(harness.startNow());
		harness.endTask();

		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(id, record.getId());
		assertEquals(mine, SetupOverrides.from(record));
		final SetupTags tags = SetupTags.of(record);
		assertTrue("the override wins", tags.isCannon());
		assertFalse("over the detected value", tags.isDetectedCannon());
		assertEquals(SetupStyle.RANGED, tags.getStyle());
		assertEquals(GearFocus.STRENGTH, tags.getGear());
	}

	@Test
	public void aOneXLedgerShowsItsEstimatedTagsAndIsOnlyRewrittenByAnEdit() throws IOException
	{
		// Synthetic, shaped like a 1.x ledger: a barrage task whose supplies were not counted.
		final String oneX = "{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"old\","
			+ "\"monster\":\"Dust devils\",\"creatureId\":42,\"initialAmount\":180,\"kills\":180,"
			+ "\"activeMillis\":1800000,\"startedAt\":1762500000000,\"endedAt\":1762501800000,\"completed\":true,"
			+ "\"partial\":false,\"xpGained\":{\"ATTACK\":12000,\"HITPOINTS\":30000,\"MAGIC\":54000,"
			+ "\"SLAYER\":24000,\"STRENGTH\":24000}}]}";
		writeLedger(oneX);
		harness.loginAndSettle(ACCOUNT);
		String tooltip = tooltip();
		assertTrue(tooltip, tooltip.contains("<br>Cannon: ~No<br>Style: ~Barrage<br>Gear: Unknown<br>"
			+ SetupTags.ESTIMATE_NOTE + "<br>"));
		assertEquals("reading never rewrites the ledger", oneX, readLedger());

		editSetup("old", SetupOverrides.NONE.withStyle(SetupStyle.MAGIC));
		final LedgerRecord edited = harness.onlyRecord(ACCOUNT);
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, edited.getSchemaVersion());
		assertEquals(Boolean.TRUE, edited.getStyleEstimated());
		assertEquals(SetupStyle.BARRAGE, edited.getDetectedStyle());
		tooltip = tooltip();
		assertTrue(tooltip, tooltip.contains("<br>Cannon: ~No<br>Style: Magic (set by you; detected ~Barrage)<br>"));
		assertTrue(readLedger(), readLedger().startsWith("{\"schemaVersion\":" + LedgerStore.FILE_SCHEMA_VERSION));
	}

	@Test
	public void aFailedEditShowsTheMessageAndLeavesANewerLedgerAlone() throws IOException
	{
		final String newer = "{\"schemaVersion\":" + (LedgerStore.FILE_SCHEMA_VERSION + 1) + ",\"records\":[{\"id\":"
			+ "\"future\",\"monster\":\"Hydras\",\"kills\":9,\"completed\":true}]}";
		writeLedger(newer);
		harness.loginAndSettle(ACCOUNT);
		editSetup("future", SetupOverrides.of(true, null, null));
		assertEquals("<html>" + SlayerLedgerPanel.EDIT_SETUP_FAILED_MESSAGE + "</html>",
			onEdt(() -> harness.ui().getHistory().getErrorText()));
		assertEquals(newer, readLedger());
	}

	/** With no kill context counted (no kill yet), the live cannon falls back to the cannonballs fired. */
	@Test
	public void theLiveCannonIsDetectedFromTheCannonballsFiredUntilAKillsContextIsCounted()
	{
		harness.defineItem(SupplyTracker.CANNONBALL, "Cannonball", 200, 5);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		final ItemTally fired = new ItemTally();
		fired.add(SupplyTracker.CANNONBALL, 20);
		// As the plugin adds them, on the client thread (the test thread).
		assertTrue(harness.tracker().addSupplies(fired, null, null));
		assertTrue(harness.tracker().getSetupTags().isCannon());
		harness.endTask();
		assertEquals(Boolean.TRUE, harness.onlyRecord(ACCOUNT).getDetectedCannon());
		final String tooltip = tooltip();
		assertTrue(tooltip, tooltip.contains("<br>Cannon: Yes<br>"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.gameval.ItemID;
import org.junit.Rule;
import org.junit.Test;

/**
 * The current task's per-task statistics as wired in the plugin ({@link PluginHarness}): the live card's
 * time-left fallback until the live pace is reliable, and, since they value nothing, kept when today's prices
 * or the "Loot price" mode change. The History estimate that showed their values went with the advisor card. {@link TaskStatisticsTest} covers the averages.
 */
public class HarnessTaskStatisticsTest
{
	private static final long MINUTE = 60_000L;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The tracker's clock, so active time (and the live time-left estimate) is under the test's control. */
	private final AtomicLong now = new AtomicLong(1_000_000_000L);

	/**
	 * A completed task: 10 kills in 10 minutes, loot 100K GE / 200K high alch, supplies 10K; with its items
	 * ({@link SavedItems}).
	 */
	private static LedgerRecord prior()
	{
		LedgerRecord prior = new LedgerRecord();
		prior.setCreatureId(42);
		prior.setMonster("Abyssal demons");
		prior.setKills(10);
		prior.setActiveMillis(10 * MINUTE);
		prior.setCompleted(true);
		prior.setLootGeValue(100_000L);
		prior.setLootHaValue(200_000L);
		prior.setSuppliesGeValue(10_000L);
		return SavedItems.withItems(prior);
	}

	/** Starts the plugin on a task with {@code remaining} of {@code assigned} kills left and shows {@code prior}. */
	private void start(int remaining, int assigned, LedgerRecord prior)
	{
		SavedItems.define(harness);
		harness.startUp();
		useTestClock();
		harness.setTask(42, "Abyssal demons", remaining, assigned);
		harness.loginAndSettle(PluginHarness.ACCOUNT);
		harness.onEdt(() -> harness.historyModel().setRecords(PluginHarness.ACCOUNT, Collections.singletonList(prior)));
		// Today's prices of its items are looked up on the client thread and answered on the EDT.
		harness.drain();
	}

	/** Points the plugin's session tracker at {@link #now} (it reads the system clock otherwise). */
	private void useTestClock()
	{
		harness.setTrackerClock(now::get);
	}

	/**
	 * The current task's statistics as the live card's time left and the overlay's pace read them: of the session's
	 * version and cannon use, at its location ({@link LedgerHistoryModel#currentLocation}).
	 */
	private TaskStatistics stats()
	{
		TaskStatistics[] stats = new TaskStatistics[1];
		harness.onEdt(() -> stats[0] = harness.historyModel().taskStatistics(42, "Abyssal demons",
			harness.tracker().getCurrentTaskSelection(), harness.historyModel().currentLocation()));
		return stats[0];
	}

	private String[] timeLeft()
	{
		String[] time = new String[2];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			time[0] = harness.ui().getTimeLeftText();
			time[1] = harness.ui().getTimeLeftTooltip();
		});
		return time;
	}

	@Test
	public void theStatisticsFeedTheLiveTimeLeftUntilTheLivePaceIsReliable()
	{
		start(10, 10, prior());

		TaskStatistics stats = stats();
		assertEquals(1, stats.getSampleCount());
		assertEquals(Long.valueOf(MINUTE), stats.getMillisPerKill());
		assertEquals("10K of manta rays (200) over 10 kills", 20d, stats.getSuppliesPerKill().get(SavedItems.SUPPLY),
			1e-9);

		assertTrue(harness.startNow());
		String[] time = timeLeft();
		assertEquals("Time left: ~10m", time[0]);
		assertTrue(time[1], time[1].contains("Historical estimate"));
		assertTrue(time[1], time[1].contains("after 3 kills and 1 minute"));
	}

	@Test
	public void aPriceOrLootPriceModeChangeKeepsTheStatistics()
	{
		harness.defineItem(ItemID.DRAGON_BONES, "Dragon bones", 3_000, 5_000);
		start(10, 10, prior());
		assertTrue(harness.startNow());
		timeLeft();
		TaskStatistics stats = stats();
		long[] before = new long[2];
		harness.onEdt(() ->
		{
			before[0] = harness.historyModel().getTaskStatisticsBuildCount();
			before[1] = harness.historyModel().valuationVersion();
		});

		// Another Loot price mode, then a price arriving: the history is valued again, the statistics not.
		harness.setLootPriceMode(LootPriceMode.HIGH_ALCH);
		harness.drain();
		harness.onEdt(() -> harness.historyModel().addCurrentPrices(Collections.singleton(ItemID.DRAGON_BONES),
			Collections.singletonMap(ItemID.DRAGON_BONES, 3_500L)));
		harness.drain();
		assertEquals("Time left: ~10m", timeLeft()[0]);
		assertSame(stats, stats());
		long[] after = new long[2];
		harness.onEdt(() ->
		{
			after[0] = harness.historyModel().getTaskStatisticsBuildCount();
			after[1] = harness.historyModel().valuationVersion();
		});
		assertTrue("the valuation changed", after[1] > before[1]);
		assertEquals("not worked out again", before[0], after[0]);
	}

	@Test
	public void livePaceTakesOverAfterThreeKillsAndOneMinute()
	{
		start(10, 10, prior());
		assertTrue(harness.startNow());
		assertEquals("Time left: ~10m", timeLeft()[0]);

		// 3 kills in 30 seconds: not yet a minute of active time, so still the history (1 minute a kill, 7 left).
		now.addAndGet(MINUTE / 2);
		harness.setRemaining(7);
		harness.tick();
		String[] time = timeLeft();
		assertEquals("Time left: ~7m", time[0]);
		assertTrue(time[1], time[1].contains("Historical estimate"));

		// 3 kills in 90 seconds: 30 seconds a kill, 7 left.
		now.addAndGet(MINUTE);
		harness.tick();
		time = timeLeft();
		assertEquals("3m 30s rounds half up", "Time left: ~4m", time[0]);
		assertTrue(time[1], time[1].contains("Kills per hour"));
	}
}

package com.shmayvan.slayerledger;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.api.NPC;
import net.runelite.api.gameval.NpcID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Variants and Slayer bosses as wired in the plugin ({@link PluginHarness}): the player's kills of a task's
 * Slayer boss are tallied by NPC name, the task box and the overlay's Task row show the boss once the kills say so (or
 * {@code + boss} for a few boss kills), and the saved record keeps the variant and the boss flag, which the History
 * list shows. A 1.x ledger's records get the flag when read. Nothing here waits for the panel's refresh timer.
 * {@link TaskVariantsTest} covers the rules.
 */
public class HarnessTaskVariantsTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int GARGOYLES = 46;
	private static final int CAVE_KRAKEN = 84;
	private static final String GG = "Grotesque Guardians";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	private final AtomicLong now = new AtomicLong(1_000_000L);
	/** The next NPC scene index, so every NPC is a new one. */
	private int nextIndex = 1;

	@Before
	public void setUp()
	{
		harness.startUp();
		harness.setInventory();
		harness.setTrackerClock(now::get);
	}

	private <T> T onEdt(Supplier<T> read)
	{
		final AtomicReference<T> result = new AtomicReference<>();
		harness.onEdt(() -> result.set(read.get()));
		return result.get();
	}

	/**
	 * The player hits the NPCs and they die; the task count goes down by {@code taskKills} on the next tick (2 minutes
	 * later).
	 */
	private void kill(int taskKills, NPC... npcs)
	{
		for (NPC npc : npcs)
		{
			harness.hitsplat(npc, true);
		}
		for (NPC npc : npcs)
		{
			harness.npcDies(npc);
		}
		now.addAndGet(2 * 60_000L);
		harness.setRemaining(harness.tracker().getCurrentRemaining() - taskKills);
		harness.tick();
	}

	private NPC npc(int id, String name)
	{
		return harness.npc(nextIndex++, id, name);
	}

	/** One Grotesque Guardians kill: Dusk and Dawn die together, taking {@code taskKills} off the task. */
	private void killGuardians(int taskKills)
	{
		kill(taskKills, npc(NpcID.GARGBOSS_DAWN_DEATH, "Dawn"), npc(NpcID.GARGBOSS_DUSK_DEATH, "Dusk"));
	}

	/** Completes the task and lets its grace window pass, so it is saved. */
	private void complete()
	{
		now.addAndGet(60_000L);
		harness.completeTask();
		harness.tick();
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS + 1);
	}

	private String taskBoxRow()
	{
		return onEdt(() ->
		{
			harness.panel().refresh();
			return harness.ui().getTaskBox().getRows().get(0);
		});
	}

	private String taskBoxTooltip()
	{
		return onEdt(() -> harness.ui().getTaskBox().getTaskTooltip());
	}

	/** The overlay's task name, or {@code null} when it shows none. */
	private String overlayTask()
	{
		for (OverlayRows.Row row : OverlayRows.rows(harness.overlayData(), OverlayRows.Groups.ALL))
		{
			if (row.getKind() == OverlayRows.Kind.IDENTITY)
			{
				return row.getLeft();
			}
		}
		return null;
	}

	@Test
	public void grotesqueGuardiansKillsOnAGargoyleTaskSetTheVariantAndTheBossFlag()
	{
		harness.setTask(GARGOYLES, "Gargoyles", 6, 6);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		assertEquals("Gargoyles", overlayTask());

		killGuardians(1);
		assertEquals(Arrays.asList(new NpcKills("Dawn", 1), new NpcKills("Dusk", 1)), harness.tracker().getNpcKills());
		assertEquals(GG, overlayTask());
		assertEquals(GG, taskBoxRow());
		assertTrue(taskBoxTooltip(), taskBoxTooltip().contains("Task: Gargoyles<br>Doing: " + GG + " (from your kills)"));

		// A gargoyle: a tie is the standard monster, with the boss kill still shown.
		kill(1, npc(NpcID.SLAYER_GARGOYLE_1, "Gargoyle"));
		assertEquals("Gargoyles + boss", overlayTask());
		assertEquals("Gargoyles + boss", taskBoxRow());
		assertTrue(taskBoxTooltip(), taskBoxTooltip().contains("<br>Boss kills: " + GG));

		// With Double Trouble a Guardians kill takes two off the task; it still counts as one kill of the boss.
		killGuardians(2);
		assertEquals(GG, overlayTask());
		killGuardians(1);
		complete();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals("Gargoyles", record.getMonster());
		assertEquals(GG, record.getVariant());
		assertEquals(Boolean.TRUE, record.getBossKills());
		harness.drain();
		assertEquals(Arrays.asList(GG), onEdt(() -> harness.ui().getHistory().getTitleTexts()));
		String tooltip = onEdt(() -> harness.ui().getHistory().getTooltips().get(0));
		assertTrue(tooltip, tooltip.contains("<br>Slayer boss of Gargoyles"));
	}

	@Test
	public void aFewKrakenKillsOnACaveKrakenTaskShowAsBossKills()
	{
		harness.setTask(CAVE_KRAKEN, "Cave kraken", 4, 4);
		harness.loginAndSettle(ACCOUNT);
		assertTrue(harness.startNow());
		kill(1, npc(NpcID.SLAYER_KRAKEN, "Cave kraken"));
		kill(1, npc(NpcID.SLAYER_KRAKEN, "Cave kraken"));
		assertEquals("Cave kraken", overlayTask());
		kill(1, npc(NpcID.SLAYER_KRAKEN_BOSS, "Kraken"));
		assertEquals("Cave kraken + boss", overlayTask());
		assertEquals("Cave kraken + boss", taskBoxRow());
		kill(1, npc(NpcID.SLAYER_KRAKEN, "Cave kraken"));
		complete();

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertNull("the cave kraken did most of the task", record.getVariant());
		assertEquals(Boolean.TRUE, record.getBossKills());
		harness.drain();
		assertEquals(Arrays.asList("Cave kraken"), onEdt(() -> harness.ui().getHistory().getTitleTexts()));
		String tooltip = onEdt(() -> harness.ui().getHistory().getTooltips().get(0));
		assertTrue(tooltip, tooltip.contains("<br>Boss kills: Kraken"));
	}

	@Test
	public void aOneXLedgerGetsTheBossFlagWhenRead() throws IOException
	{
		// Synthetic 1.x records: a gargoyle task with Grotesque Guardians kill counts, and one without.
		File ledger = new File(harness.ledgerDirectory(), ACCOUNT + ".json");
		assertTrue(harness.ledgerDirectory().isDirectory() || harness.ledgerDirectory().mkdirs());
		String oneX = "{\"schemaVersion\":2,\"records\":["
			+ "{\"schemaVersion\":2,\"id\":\"gg\",\"monster\":\"Gargoyles\",\"creatureId\":46,\"kills\":10,"
			+ "\"activeMillis\":600000,\"startedAt\":1000,\"endedAt\":601000,\"completed\":true,\"partial\":false,"
			+ "\"bossKillCounts\":[{\"boss\":\"Grotesque Guardians\",\"firstKc\":100,\"lastKc\":102,\"kills\":3}]},"
			+ "{\"schemaVersion\":2,\"id\":\"plain\",\"monster\":\"Gargoyles\",\"creatureId\":46,\"kills\":10,"
			+ "\"activeMillis\":600000,\"startedAt\":1000,\"endedAt\":501000,\"completed\":true,\"partial\":false}]}";
		Files.write(ledger.toPath(), oneX.getBytes(StandardCharsets.UTF_8));
		harness.loginAndSettle(ACCOUNT);
		harness.drain();

		List<LedgerRecord> records = harness.records(ACCOUNT);
		assertEquals(Boolean.TRUE, records.stream().filter(r -> "gg".equals(r.getId())).findFirst().get().getBossKills());
		assertEquals(Boolean.FALSE,
			records.stream().filter(r -> "plain".equals(r.getId())).findFirst().get().getBossKills());
		List<String> tooltips = onEdt(() -> harness.ui().getHistory().getTooltips());
		assertEquals(2, tooltips.size());
		assertTrue(tooltips.get(0), tooltips.get(0).contains("<br>Boss kills: " + GG));
		assertFalse(tooltips.get(1), tooltips.get(1).contains("Boss kills"));
		// Reading changed nothing on disk.
		assertEquals(oneX, new String(Files.readAllBytes(ledger.toPath()), StandardCharsets.UTF_8));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.ChatMessageType;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemEquipmentStats;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * The follow-ups of the automatic-tracking review, through the plugin's events: a hit's activity and engagement
 * are timed with its tick's supplies, XP and attack (not before them); a known task NPC's loot counts while the
 * session is stopped only just after a task kill; and Away takes back the bank trips since the last activity, but not
 * the deaths (project-manager decision) or the superiors.
 */
public class HarnessTrackingFollowUpsTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final int DEMON = 415;
	private static final long TICK = 600L;
	private static final long MINUTE = 60_000L;
	private static final int BOW = 40_003;
	private static final String SUPERIOR = "<col=ef1020>A superior foe has appeared...</col>";

	@Rule
	public final PluginHarness harness = new PluginHarness();

	private final AtomicLong now = new AtomicLong(1_000_000_000L);
	private int nextIndex = 1;
	private int sharks = 20;

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.SHARK, "Shark", 1_000, 300, "Eat");
		harness.defineItem(ItemID.ABYSSAL_WHIP, "Abyssal whip", 1_500_000, 72_000);
		harness.defineEquipment(BOW, "Magic shortbow (i)", ItemEquipmentStats.builder()
			.slot(EquipmentInventorySlot.WEAPON.getSlotIdx()).arange(75).build());
		harness.setSkillXp(Skill.HITPOINTS, 1_000_000);
		harness.setSkillXp(Skill.ATTACK, 2_000_000);
		harness.setSkillXp(Skill.RANGED, 3_000_000);
		harness.startUp();
		harness.setTrackerClock(now::get);
		harness.setInventory(inventory());
		harness.setTask(TASK, "Abyssal demons", 50, 50);
		harness.loginAndSettle(ACCOUNT);
		tick();
	}

	private Item[] inventory()
	{
		final List<Item> items = new ArrayList<>();
		for (int i = 0; i < sharks; i++)
		{
			items.add(PluginHarness.item(ItemID.SHARK, 1));
		}
		return items.toArray(new Item[0]);
	}

	private void tick()
	{
		now.addAndGet(TICK);
		harness.tick();
	}

	/** An Abyssal demon, the name {@link PluginHarness#lootOnNextTick} reports loot for. */
	private NPC demon()
	{
		return harness.npc(nextIndex++, DEMON, PluginHarness.LOOT_NPC_NAME);
	}

	/** A one-hit task kill: the hit and death now, the count's drop on the next tick, and one more tick. */
	private void kill()
	{
		final NPC npc = demon();
		harness.hitsplat(npc, true);
		harness.npcDies(npc);
		harness.setRemaining(harness.tracker().getCurrentRemaining() - 1);
		tick();
		tick();
	}

	private long xp(Skill skill)
	{
		return harness.tracker().getXpGained().getOrDefault(skill.name(), 0L);
	}

	// ---- Hit timing within a tick ----

	@Test
	public void aMeleeHitsOwnTickXpAndSuppliesAreNotTakenBackByAway()
	{
		kill();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		// A hit on a task monster arrives early in its tick; the tick's XP and the shark eaten are read on its GameTick,
		// a moment later.
		final NPC demon = demon();
		harness.hitsplat(demon, true);
		now.addAndGet(300);
		harness.gainXp(Skill.ATTACK, 40);
		sharks--;
		harness.setInventory(inventory());
		harness.tick();
		assertEquals(40, xp(Skill.ATTACK));
		assertEquals(1, harness.tracker().getSupplies().get(ItemID.SHARK));

		// Nothing more: Away, closing at that hit.
		now.addAndGet(10 * MINUTE);
		harness.tick();
		assertEquals(SessionTracker.State.AWAY, harness.sessionState());
		assertEquals("the hit's own tick's XP stays", 40, xp(Skill.ATTACK));
		assertEquals("and so does its shark", 1, harness.tracker().getSupplies().get(ItemID.SHARK));
	}

	@Test
	public void aRangedAttacksOwnTickXpCountsWhenItsKillStartsTheSession()
	{
		harness.setWorn(EquipmentInventorySlot.WEAPON, BOW, 1);
		final NPC demon = demon();
		// The attack starts, with its Ranged and Hitpoints XP on the same tick; no session yet, so it is held back.
		harness.setInteracting(demon);
		harness.setAnimation(AnimationID.HUMAN_BOW, 0);
		harness.gainXp(Skill.RANGED, 80);
		harness.gainXp(Skill.HITPOINTS, 26);
		tick();
		final long attackTick = now.get();
		harness.setAnimation(AnimationID.HUMAN_BOW, 1);
		tick();
		// The arrow lands two ticks later and kills it: the first task kill.
		now.addAndGet(TICK);
		harness.hitsplat(demon, true);
		harness.npcDies(demon);
		harness.setRemaining(49);
		harness.tick();

		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("backdated to the attack's tick", now.get() - attackTick, harness.tracker().getActiveMillis());
		assertEquals("its XP counts", 80, xp(Skill.RANGED));
	}

	// ---- Loot of a task kill ----

	@Test
	public void aTaskKillsLootCountsWhileStoppedOnlyJustAfterTheKill()
	{
		kill();
		harness.pause();
		// The kill's loot arrives a tick later.
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		tick();
		assertEquals(1, harness.tracker().getLoot().get(ItemID.ABYSSAL_WHIP));

		// The same monster's loot a minute later, still paused (killed outside a Konar area, say): held back.
		now.addAndGet(MINUTE);
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		tick();
		assertEquals(1, harness.tracker().getLoot().get(ItemID.ABYSSAL_WHIP));

		harness.endTask();
		assertEquals(Long.valueOf(1), harness.onlyRecord(ACCOUNT).getLoot().get(ItemID.ABYSSAL_WHIP));
	}

	// ---- Counters on Away ----

	@Test
	public void bankTripsAfterTheLastActivityAreTakenBackOnAwayButDeathsAndSuperiorsStay()
	{
		kill();
		// A death before the next kill: the player was still on the task.
		now.addAndGet(MINUTE);
		harness.localPlayerDies();
		now.addAndGet(MINUTE);
		kill();

		// After the last kill: a bank trip, a death and a superior.
		now.addAndGet(MINUTE);
		harness.openInterface(InterfaceID.BANKMAIN);
		harness.closeInterface(InterfaceID.BANKMAIN);
		harness.localPlayerDies();
		harness.chat(ChatMessageType.GAMEMESSAGE, SUPERIOR);
		assertEquals(1, harness.tracker().getBankTrips());
		assertEquals(2, harness.tracker().getDeaths());
		assertEquals(1, harness.tracker().getSuperiorsSpawned());

		now.addAndGet(10 * MINUTE);
		tick();
		assertEquals(SessionTracker.State.AWAY, harness.sessionState());
		assertEquals("the bank trip after the last kill is taken back", 0, harness.tracker().getBankTrips());
		assertEquals("a death a while after the last hit is still a task death", 2, harness.tracker().getDeaths());
		assertEquals("only task kills spawn superiors", 1, harness.tracker().getSuperiorsSpawned());

		harness.endTask();
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Integer.valueOf(0), record.getBankTrips());
		assertEquals(Integer.valueOf(2), record.getDeaths());
		assertEquals(Integer.valueOf(1), record.getSuperiorsSpawned());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.api.Item;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * Supplies, XP and loot outside segments, through the plugin's events (V2 plan 4.1): the buffer while a task is
 * assigned and no segment is open; the 3-minute supplies warm-up and XP and loot from the segment start at every
 * (re)start, with the resume point's clamps (End task among them), kept across a hop; what Away takes back, and how it
 * counts at the next restart; the restart kill's own XP; and the final kill's NPC tallies. {@link SessionBufferTest}
 * covers the same rules on the tracker alone, {@link HarnessTaskCaveTest} the Jad and Zuk tasks.
 */
public class HarnessUsageBufferTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;
	private static final String TASK_NAME = "Abyssal demons";
	private static final int DEMON = 415;
	private static final int SPECTRES = 7;
	private static final long MINUTE = 60_000L;
	private static final long SECOND = 1_000L;
	private static final String[] DRINK = {"Drink", null, null, "Empty", "Drop"};

	@Rule
	public final PluginHarness harness = new PluginHarness();

	/** The tracker's clock: supplies, XP, loot, hits, deaths and segments are timed by it. */
	private final AtomicLong now = new AtomicLong(1_000_000_000L);
	private int nextIndex = 1;
	/** Sharks in the inventory. */
	private int sharks = 30;
	/** Potions in the inventory besides the sharks, one item id each (none unless a test adds them). */
	private final List<Integer> potions = new ArrayList<>();

	@Before
	public void setUp()
	{
		harness.defineItem(ItemID.SHARK, "Shark", 1_000, 300, "Eat");
		harness.defineItem(ItemID.ABYSSAL_WHIP, "Abyssal whip", 1_500_000, 72_000);
		harness.defineItem(ItemID.BONES, "Bones", 100, 1);
		harness.setSkillXp(Skill.HITPOINTS, 1_000_000);
		harness.setSkillXp(Skill.SLAYER, 2_000_000);
		harness.setSkillXp(Skill.ATTACK, 3_000_000);
		harness.startUp();
		harness.setTrackerClock(now::get);
		harness.setInventory(inventory());
		harness.setTask(TASK, TASK_NAME, 50, 50);
		harness.loginAndSettle(ACCOUNT);
		// The task is read; the supplies diff takes its first baseline.
		harness.tick();
	}

	private Item[] inventory()
	{
		final List<Item> items = new ArrayList<>();
		for (int i = 0; i < sharks; i++)
		{
			items.add(PluginHarness.item(ItemID.SHARK, 1));
		}
		for (int id : potions)
		{
			items.add(PluginHarness.item(id, 1));
		}
		return items.toArray(new Item[0]);
	}

	/** Eats a shark now: the supplies diff sees it on the next tick. */
	private void eat()
	{
		sharks--;
		harness.setInventory(inventory());
		harness.tick();
	}

	/**
	 * Defines a potion family's 4- and 3-dose items, as the supplies diff reads potions, and puts {@code count} 4-dose
	 * potions in the inventory; the next tick sees them (a gain, never a use).
	 */
	private void holdPotions(String name, int fourDose, int threeDose, int count)
	{
		harness.defineItem(fourDose, name + "(4)", 10_000, 0, DRINK);
		harness.defineItem(threeDose, name + "(3)", 7_500, 0, DRINK);
		for (int i = 0; i < count; i++)
		{
			potions.add(fourDose);
		}
		harness.setInventory(inventory());
		harness.tick();
	}

	/** Drinks one dose of a 4-dose potion now, leaving a 3-dose one: the supplies diff sees it on the next tick. */
	private void drink(int fourDose, int threeDose)
	{
		potions.set(potions.indexOf(fourDose), threeDose);
		harness.setInventory(inventory());
		harness.tick();
	}

	/** Doses used of the potion family whose 4-dose item is {@code fourDose} (supplies key a family by it). */
	private long dosesUsed(int fourDose)
	{
		return harness.tracker().getSupplies().get(fourDose);
	}

	private long sharksUsed()
	{
		return harness.tracker().getSupplies().get(ItemID.SHARK);
	}

	private long xp(Skill skill)
	{
		return harness.tracker().getXpGained().getOrDefault(skill.name(), 0L);
	}

	private long loot(int itemId)
	{
		return harness.tracker().getLoot().get(itemId);
	}

	private NPC demon()
	{
		return harness.npc(nextIndex++, DEMON, "Abyssal demon");
	}

	/** The count drops by {@code n} on the next tick. */
	private void countDrops(int n)
	{
		harness.setRemaining(harness.tracker().getCurrentRemaining() - n);
		harness.tick();
	}

	/** A kill with no NPC of the player's dying (a cannon-only kill): the count drops on the next tick. */
	private void cannonKill()
	{
		countDrops(1);
	}

	/** A fight: the player's first hit now, more hits for {@code millis}, then the NPC dies and the count drops. */
	private void fight(long millis)
	{
		final NPC npc = demon();
		harness.hitsplat(npc, true);
		now.addAndGet(millis);
		harness.hitsplat(npc, true);
		harness.npcDies(npc);
		countDrops(1);
	}

	private long active()
	{
		return harness.tracker().getActiveMillis();
	}

	// ---- The first kill: warm-up, and a long fight counting in full ----

	@Test
	public void aBossFightLongerThanTheWarmUpCountsInFullFromTheFirstHit()
	{
		// Five minutes before the first hit: before the warm-up.
		eat();
		// Two and a half minutes before it: a pre-pot, in the warm-up.
		now.addAndGet(2 * MINUTE + 30 * SECOND);
		eat();
		// XP before the first hit (another fight) is not the task's.
		now.addAndGet(30 * SECOND);
		harness.gainXp(Skill.ATTACK, 50);
		harness.tick();
		assertEquals("buffered, not counted yet", SessionTracker.State.IDLE, harness.sessionState());

		now.addAndGet(2 * MINUTE);
		final NPC boss = demon();
		harness.hitsplat(boss, true);
		for (int minute = 1; minute <= 6; minute++)
		{
			now.addAndGet(MINUTE);
			harness.hitsplat(boss, true);
			harness.gainXp(Skill.ATTACK, 100);
			eat();
		}
		now.addAndGet(30 * SECOND);
		harness.npcDies(boss);
		harness.gainXp(Skill.SLAYER, 500);
		countDrops(1);
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();

		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("from the first hit", 6 * MINUTE + 30 * SECOND, active());
		assertEquals("the pre-pot and every shark of the fight, not the one five minutes before", 7, sharksUsed());
		assertEquals("the whole fight's XP, not what came before the first hit", 600, xp(Skill.ATTACK));
		assertEquals("the kill's own XP", 500, xp(Skill.SLAYER));
		assertEquals(1, loot(ItemID.ABYSSAL_WHIP));

		harness.endTask();
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertEquals(Long.valueOf(7), record.getSupplies().get(ItemID.SHARK));
		assertEquals(Long.valueOf(600), record.getXpGained().get(Skill.ATTACK.name()));
	}

	// ---- The warm-up's clamps ----

	@Test
	public void aTuraelSkipKeepsThePreviousTasksSuppliesOutOfTheNewOnesWarmUp()
	{
		// Used while the first task waits for its first kill.
		eat();
		now.addAndGet(30 * SECOND);
		// Turael skips it for another task.
		harness.setTask(43, "Black demons", 30, 30);
		harness.tick();
		now.addAndGet(30 * SECOND);
		eat();
		// The new task's first kill, a minute and a half after the first shark: both lie in its 3 minutes.
		now.addAndGet(30 * SECOND);
		cannonKill();

		assertEquals("Black demons", harness.tracker().getSessionMonster());
		assertEquals("only the shark eaten on the new task", 1, sharksUsed());
	}

	@Test
	public void theWarmUpNeverReachesBackBeforeThePreviousSessionsEnd()
	{
		fight(10 * SECOND);
		harness.tick();
		harness.pause();
		now.addAndGet(10 * SECOND);
		// Used while paused, then the session is ended: neither counts it.
		eat();
		now.addAndGet(10 * SECOND);
		harness.endTask();
		assertNull("no supplies", harness.onlyRecord(ACCOUNT).getSupplies());

		now.addAndGet(10 * SECOND);
		harness.trackAgain();
		// The diff runs again from the next tick.
		harness.tick();
		now.addAndGet(10 * SECOND);
		eat();
		now.addAndGet(10 * SECOND);
		cannonKill();

		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("only the shark eaten after the previous session ended", 1, sharksUsed());
	}

	@Test
	public void endTaskWhileWaitingForTheFirstKillDropsWhatWasHeldBack()
	{
		eat();
		now.addAndGet(10 * SECOND);
		harness.endTask();
		assertEquals(SessionTracker.Status.ENDED, harness.status());

		now.addAndGet(10 * SECOND);
		harness.trackAgain();
		// The diff runs again from the next tick.
		harness.tick();
		now.addAndGet(10 * SECOND);
		// Half a minute after the shark: well within the warm-up, were it not for End task.
		cannonKill();

		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("the shark eaten before End task", 0, sharksUsed());
	}

	@Test
	public void aHopKeepsWhatWasHeldBack()
	{
		// A pre-pot while waiting for the first kill, then a hop.
		eat();
		now.addAndGet(30 * SECOND);
		harness.hop();
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("a hop is not a stop", SessionTracker.Status.WAITING_FOR_FIRST_KILL, harness.status());
		assertEquals("the shark is still held back", 1, harness.tracker().bufferSize());

		now.addAndGet(30 * SECOND);
		cannonKill();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("the shark eaten before the hop is in the warm-up", 1, sharksUsed());
	}

	@Test
	public void theWarmUpAfterAPauseCountsWhatWasUsedSinceThePauseOnce()
	{
		fight(10 * SECOND);
		now.addAndGet(10 * SECOND);
		eat();
		assertEquals("counted while running", 1, sharksUsed());
		now.addAndGet(MINUTE);
		harness.pause();
		now.addAndGet(30 * SECOND);
		eat();
		assertEquals("buffered while paused", 1, sharksUsed());

		// A kill restart a minute after the pause: its warm-up starts at the pause (the close of the previous segment),
		// so the shark eaten before the pause, already counted, is not counted again.
		now.addAndGet(30 * SECOND);
		fight(10 * SECOND);
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals(2, sharksUsed());
	}

	@Test
	public void resumeCountsTheWarmUpBeforeIt()
	{
		cannonKill();
		harness.pause();
		now.addAndGet(5 * MINUTE);
		eat();
		now.addAndGet(MINUTE);
		harness.gainXp(Skill.ATTACK, 70);
		eat();
		now.addAndGet(MINUTE);
		assertTrue(harness.resume());
		assertEquals("the sharks of the last 3 minutes", 2, sharksUsed());
		assertEquals("XP counts from the restart only", 0, xp(Skill.ATTACK));
	}

	// ---- Pause and Away ----

	@Test
	public void aPauseHoldingAFortyMinuteRaidCountsOnlyItsLastThreeMinutesOfSupplies()
	{
		fight(10 * SECOND);
		harness.tick();
		harness.pause();
		final long paused = now.get();
		for (int minute = 5; minute <= 35; minute += 5)
		{
			now.set(paused + minute * MINUTE);
			harness.gainXp(Skill.ATTACK, 1_000);
			harness.postLoot("Great Olm", ItemID.BONES, 10);
			eat();
		}
		now.set(paused + 38 * MINUTE + 30 * SECOND);
		eat();

		// The kill that restarts the session, with its own Slayer XP.
		now.set(paused + 40 * MINUTE);
		harness.gainXp(Skill.SLAYER, 100);
		cannonKill();

		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("only the shark of the last 3 minutes before the restart", 1, sharksUsed());
		assertEquals("the raid's XP never counts", 0, xp(Skill.ATTACK));
		assertEquals("nor its loot", 0, loot(ItemID.BONES));
		assertEquals("the restart kill's XP does", 100, xp(Skill.SLAYER));
	}

	@Test
	public void aKillThenAwayKeepsItsXpAndLateLootAndTakesBackLaterUse()
	{
		fight(10 * SECOND);
		now.addAndGet(30 * SECOND);
		// The second kill, with its Slayer XP on its tick.
		final NPC npc = demon();
		harness.hitsplat(npc, true);
		harness.npcDies(npc);
		harness.gainXp(Skill.SLAYER, 300);
		countDrops(1);
		// Its loot arrives two ticks and a second later.
		now.addAndGet(SECOND);
		harness.tick();
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();

		// Then the player stops doing the task: a shark, other XP, other loot.
		now.addAndGet(MINUTE);
		eat();
		now.addAndGet(MINUTE);
		harness.gainXp(Skill.ATTACK, 200);
		harness.tick();
		now.addAndGet(MINUTE);
		harness.postLoot("Goblin", ItemID.BONES, 5);
		assertEquals(1, sharksUsed());
		assertEquals(200, xp(Skill.ATTACK));
		assertEquals(5, loot(ItemID.BONES));

		now.addAndGet(7 * MINUTE - SECOND);
		harness.tick();
		assertEquals(SessionTracker.State.AWAY, harness.sessionState());
		assertEquals("the clock steps back to the last kill", 40 * SECOND, active());
		assertEquals("the kill's own XP stays", 300, xp(Skill.SLAYER));
		assertEquals("its loot stays", 1, loot(ItemID.ABYSSAL_WHIP));
		assertEquals("the later shark is taken back", 0, sharksUsed());
		assertEquals("so is the later XP", 0, xp(Skill.ATTACK));
		assertEquals("and the other NPC's loot", 0, loot(ItemID.BONES));

		// The task monster's loot this long after the last task kill is no paired kill's: it doesn't count.
		harness.lootOnNextTick(ItemID.ABYSSAL_WHIP, 1);
		harness.tick();
		assertEquals(1, loot(ItemID.ABYSSAL_WHIP));
		// Nor does other loot.
		harness.postLoot("Goblin", ItemID.BONES, 5);
		assertEquals(0, loot(ItemID.BONES));

		harness.endTask();
		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertNull("no supplies saved", record.getSupplies());
		assertEquals(Long.valueOf(1), record.getLoot().get(ItemID.ABYSSAL_WHIP));
	}

	@Test
	public void whatAwayTookBackCountsInTheNextWarmUpAtItsOwnTimeOnce()
	{
		holdPotions("Prayer potion", ItemID._4DOSEPRAYERRESTORE, ItemID._3DOSEPRAYERRESTORE, 2);
		holdPotions("Super restore", ItemID._4DOSE2RESTORE, ItemID._3DOSE2RESTORE, 1);
		holdPotions("Super combat potion", ItemID._4DOSE2COMBAT, ItemID._3DOSE2COMBAT, 1);
		fight(10 * SECOND);
		harness.tick();
		final long lastKill = now.get();

		// Sips after the last kill, counted while the clock runs.
		now.set(lastKill + MINUTE);
		drink(ItemID._4DOSEPRAYERRESTORE, ItemID._3DOSEPRAYERRESTORE);
		now.set(lastKill + 8 * MINUTE + 30 * SECOND);
		drink(ItemID._4DOSE2RESTORE, ItemID._3DOSE2RESTORE);
		assertEquals(1, dosesUsed(ItemID._4DOSEPRAYERRESTORE));
		assertEquals(1, dosesUsed(ItemID._4DOSE2RESTORE));

		// Away, 10 minutes after the last kill, takes both back into the buffer.
		now.set(lastKill + 10 * MINUTE);
		harness.tick();
		assertEquals(SessionTracker.State.AWAY, harness.sessionState());
		assertEquals(0, dosesUsed(ItemID._4DOSEPRAYERRESTORE));
		assertEquals(0, dosesUsed(ItemID._4DOSE2RESTORE));

		// More sips at the bank.
		now.set(lastKill + 10 * MINUTE + 30 * SECOND);
		drink(ItemID._4DOSE2COMBAT, ItemID._3DOSE2COMBAT);
		now.set(lastKill + 10 * MINUTE + 45 * SECOND);
		drink(ItemID._4DOSEPRAYERRESTORE, ItemID._3DOSEPRAYERRESTORE);

		// The restart, 11 minutes after the last kill: its warm-up starts 8 minutes after it, after the first prayer sip
		// and before the super restore (both taken back at their own times, not when Away started).
		now.set(lastKill + 11 * MINUTE);
		cannonKill();
		harness.tick();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("the bank sip, not the one taken back from before the warm-up", 1,
			dosesUsed(ItemID._4DOSEPRAYERRESTORE));
		assertEquals("taken back, then counted again in the warm-up: once", 1, dosesUsed(ItemID._4DOSE2RESTORE));
		assertEquals(1, dosesUsed(ItemID._4DOSE2COMBAT));
		assertEquals("the rest is dropped", 0, harness.tracker().bufferSize());
	}

	@Test
	public void fightingOtherNpcsPastTheAwayLimitAddsNoSuppliesXpOrLoot()
	{
		fight(10 * SECOND);
		harness.tick();
		final NPC boss = harness.npc(nextIndex++, 7540, "Tekton");
		for (int minute = 1; minute <= 15; minute++)
		{
			now.addAndGet(MINUTE);
			harness.hitsplat(boss, true);
			harness.gainXp(Skill.ATTACK, 100);
			eat();
			harness.postLoot("Tekton", ItemID.BONES, 1);
		}
		assertEquals(SessionTracker.State.AWAY, harness.sessionState());
		assertEquals(10 * SECOND, active());
		assertEquals(0, sharksUsed());
		assertEquals(0, xp(Skill.ATTACK));
		assertEquals(0, loot(ItemID.BONES));

		// A task kill five quiet minutes later: none of it is in its warm-up.
		now.addAndGet(5 * MINUTE);
		cannonKill();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals(0, sharksUsed());
		assertEquals(0, xp(Skill.ATTACK));
		assertEquals(0, loot(ItemID.BONES));
	}

	// ---- The restart kill and the final kill ----

	@Test
	public void theXpOfTheKillThatStartsOrRestartsTheSessionCounts()
	{
		// Every read moves the clock on a millisecond, as real time moves between the XP read and the kill.
		harness.setTrackerClock(now::getAndIncrement);
		harness.gainXp(Skill.SLAYER, 100);
		cannonKill();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("the first kill's own XP", 100, xp(Skill.SLAYER));

		harness.pause();
		now.addAndGet(MINUTE);
		harness.gainXp(Skill.SLAYER, 50);
		cannonKill();
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());
		assertEquals("the restart kill's own XP", 150, xp(Skill.SLAYER));
	}

	@Test
	public void aDeathPairedWithTheFinalKillIsTalliedDuringTheGraceWindow()
	{
		harness.setTask(SPECTRES, "Aberrant spectres", 2, 2);
		harness.tick();
		final NPC first = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(first, true);
		harness.npcDies(first);
		now.addAndGet(10 * SECOND);
		countDrops(1);
		assertEquals(SessionTracker.State.RUNNING, harness.sessionState());

		// The final kill completes the task; its NPC dies on the tick after.
		final NPC last = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(last, true);
		now.addAndGet(10 * SECOND);
		harness.completeTask();
		harness.tick();
		assertTrue(harness.tracker().hasPendingCompletion());
		harness.npcDies(last);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals("both kills were the variant's", "Deviant spectres", record.getVariant());
	}

	@Test
	public void aCompletionTicksAfterTheDropToZeroTalliesTheFinalKillFromTheDropTick()
	{
		harness.setTask(SPECTRES, "Aberrant spectres", 2, 2);
		harness.tick();
		final NPC first = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(first, true);
		harness.npcDies(first);
		now.addAndGet(10 * SECOND);
		countDrops(1);
		harness.logout();
		now.addAndGet(30 * MINUTE);
		harness.loginAndSettle(ACCOUNT);
		harness.ticks(2);
		assertEquals(SessionTracker.Status.WAITING_FOR_NEXT_KILL, harness.status());

		// The final kill: its NPC dies, the count drops to zero on the next tick (D), and the completion comes three
		// ticks after that (C). Its death, on D - 1, is paired from D - 2, not C - 2, and is still kept on C.
		final NPC last = harness.npc(nextIndex++, NpcID.KOUREND_SPECTRE, "Deviant spectre");
		harness.hitsplat(last, true);
		now.addAndGet(20 * SECOND);
		harness.npcDies(last);
		harness.tick();
		countDrops(1);
		harness.ticks(2);
		harness.completeTask();
		harness.tick();
		assertTrue("restarted first, so held for its loot", harness.tracker().hasPendingCompletion());
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		final LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(2, record.getKills());
		assertEquals("the final kill's death is tallied", "Deviant spectres", record.getVariant());
		assertEquals("its fight counts", 10 * SECOND + 20 * SECOND, record.getActiveMillis());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;

/**
 * XP gained per task as wired in the plugin ({@link PluginHarness}): read once per settled tick before the task
 * is observed, counted only while RUNNING, never from a login's stats, and kept through logout and a restart.
 * {@link SessionTrackerXpTest} covers the tracker's rules.
 */
public class HarnessXpTest
{
	private static final long ACCOUNT = PluginHarness.ACCOUNT;
	private static final int TASK = 42;

	@Rule
	public final PluginHarness harness = new PluginHarness();

	@Before
	public void setUp()
	{
		harness.setSkillXp(Skill.SLAYER, 1_000_000);
		harness.setSkillXp(Skill.HITPOINTS, 2_000_000);
		harness.setSkillXp(Skill.MAGIC, 3_000_000);
		harness.startUp();
		harness.setTask(TASK, "Abyssal demons", 100, 100);
		harness.loginAndSettle(ACCOUNT);
	}

	private static Map<String, Long> xp(Object... skillAndXp)
	{
		Map<String, Long> map = new TreeMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			map.put((String) skillAndXp[i], ((Number) skillAndXp[i + 1]).longValue());
		}
		return map;
	}

	@Test
	public void xpIsCountedOnlyWhileRunning()
	{
		harness.gainXp(Skill.SLAYER, 500);
		harness.tick();
		assertTrue(harness.startNow());
		harness.gainXp(Skill.SLAYER, 120);
		harness.gainXp(Skill.MAGIC, 300);
		harness.tick();
		harness.pause();
		harness.gainXp(Skill.SLAYER, 9_999);
		harness.ticks(2);
		assertTrue("resume", harness.startNow());
		harness.gainXp(Skill.HITPOINTS, 40);
		harness.tick();
		harness.endTask();

		assertEquals(xp("SLAYER", 120, "MAGIC", 300, "HITPOINTS", 40), harness.onlyRecord(ACCOUNT).getXpGained());
	}

	@Test
	public void aReconnectsStatBurstIsNotCounted()
	{
		assertTrue(harness.startNow());
		harness.gainXp(Skill.SLAYER, 100);
		harness.tick();
		// A lost connection stops the session like a logout. The stats read 0 until the login re-sends them, then jump.
		harness.setGameState(GameState.CONNECTION_LOST);
		harness.clearSkillXp();
		harness.setGameState(GameState.LOGGED_IN);
		harness.tick();
		harness.setSkillXp(Skill.SLAYER, 1_000_200);
		harness.setSkillXp(Skill.HITPOINTS, 2_000_000);
		harness.setSkillXp(Skill.MAGIC, 3_000_000);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals(SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertTrue("restarted after the reconnect", harness.startNow());
		harness.gainXp(Skill.SLAYER, 7);
		harness.tick();
		harness.endTask();

		assertEquals(xp("SLAYER", 107), harness.onlyRecord(ACCOUNT).getXpGained());
	}

	@Test
	public void aHopIsNeverAGain()
	{
		assertTrue(harness.startNow());
		harness.gainXp(Skill.SLAYER, 10);
		harness.tick();
		harness.hop();
		harness.gainXp(Skill.SLAYER, 50_000);
		harness.ticks(PluginHarness.SETTLE_TICKS);
		assertEquals("a hop is not a stop", SessionTracker.State.RUNNING, harness.sessionState());
		harness.gainXp(Skill.SLAYER, 5);
		harness.tick();
		harness.endTask();

		assertEquals(xp("SLAYER", 15), harness.onlyRecord(ACCOUNT).getXpGained());
	}

	@Test
	public void anotherAccountsStatsAreNotCounted()
	{
		assertTrue(harness.startNow());
		harness.gainXp(Skill.SLAYER, 10);
		harness.tick();
		harness.logout();
		// The other account has more XP in every skill: a naive diff would count all of it.
		harness.setSkillXp(Skill.SLAYER, 5_000_000);
		harness.setSkillXp(Skill.HITPOINTS, 9_000_000);
		harness.setSkillXp(Skill.MAGIC, 9_000_000);
		harness.loginAndSettle(ACCOUNT + 1);
		assertTrue(harness.startNow());
		harness.gainXp(Skill.MAGIC, 3);
		harness.tick();
		harness.endTask();

		assertEquals(xp("MAGIC", 3), harness.onlyRecord(ACCOUNT + 1).getXpGained());
		SessionSnapshot first = harness.activeSession(ACCOUNT);
		assertNotNull("the first account's session is persisted", first);
		assertEquals(xp("SLAYER", 10), first.getXpGained());
	}

	@Test
	public void theCompletionTickCountsAndTheGraceWindowDoesNot()
	{
		harness.setRemaining(1);
		harness.tick();
		assertEquals("the drop was a kill: it started the session", SessionTracker.State.RUNNING, harness.sessionState());
		harness.tick();
		harness.completeTask();
		harness.gainXp(Skill.SLAYER, 300);
		harness.tick();
		assertTrue("held for late loot", harness.tracker().hasPendingCompletion());
		harness.gainXp(Skill.SLAYER, 999);
		harness.ticks(SessionTracker.COMPLETION_LOOT_GRACE_TICKS);

		LedgerRecord record = harness.onlyRecord(ACCOUNT);
		assertTrue(record.isCompleted());
		assertEquals(xp("SLAYER", 300), record.getXpGained());
	}

	@Test
	public void xpSurvivesLogoutAndARestart()
	{
		assertTrue(harness.startNow());
		harness.gainXp(Skill.SLAYER, 400);
		harness.tick();
		harness.logout();
		assertEquals(xp("SLAYER", 400), harness.activeSession(ACCOUNT).getXpGained());
		harness.shutDown();

		harness.startUp();
		harness.loginAndSettle(ACCOUNT);
		assertEquals("restored as logged out", SessionTracker.State.LOGGED_OUT, harness.sessionState());
		assertEquals(xp("SLAYER", 400), harness.tracker().getXpGained());
		assertTrue(harness.startNow());
		harness.gainXp(Skill.SLAYER, 100);
		harness.tick();
		harness.endTask();

		assertEquals(xp("SLAYER", 500), harness.onlyRecord(ACCOUNT).getXpGained());
		assertNull(harness.activeSession(ACCOUNT));
	}

	@Test
	public void panelShowsTheLiveXpAndTheSavedTasksXp()
	{
		assertTrue(harness.startNow());
		harness.gainXp(Skill.SLAYER, 1_500);
		harness.gainXp(Skill.HITPOINTS, 500);
		harness.tick();
		final String[] live = new String[3];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			live[0] = harness.ui().getXpText();
			live[1] = String.join(" / ", harness.ui().getLiveXp().getLineTexts());
			live[2] = String.join(" / ", harness.ui().getLiveXp().getLineIcons());
		});
		assertEquals("the stats' XP", "2,000", live[0]);
		assertEquals("Slayer | 1,500 / Hitpoints | 500", live[1]);
		// Each line has its skill's small icon from SkillIconManager, asked for on the EDT.
		assertEquals("skill SLAYER 18x16 / skill HITPOINTS 18x16", live[2]);

		harness.endTask();
		final Object[] saved = new Object[2];
		harness.onEdt(() ->
		{
			harness.panel().refresh();
			saved[0] = harness.ui().getXpText();
			// The row has no room for the XP since its tooltip has it.
			saved[1] = harness.ui().getHistory().getTooltips().get(0);
			harness.ui().getHistory().clickRow(0);
		});
		harness.drain();
		final Object[] details = new Object[2];
		harness.onEdt(() ->
		{
			details[0] = harness.ui().getHistory().getDetailsText(0);
			details[1] = harness.ui().getHistory().getDetailsXpIcons(0);
		});
		assertNull("hidden once the session ended", saved[0]);
		// Too little active time for a rate, so none.
		assertTrue(saved[1].toString(), saved[1].toString().contains("<br>XP: 2,000<br>"));
		String text = details[0].toString();
		assertTrue(text, text.contains("XP gained, Slayer | 1,500, Hitpoints | 500"));
		assertEquals(Arrays.asList("skill SLAYER 18x16", "skill HITPOINTS 18x16"), details[1]);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import java.time.ZoneOffset;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * Loot Ground Items hides is left out of the loot value: saved tasks ({@link HistoryPricing}) and everything
 * built on them (Overall totals and their rates, the statistics, the chat line), and the live session
 * ({@link SessionValuation}). The records themselves are never changed, so with nothing hidden the values come back.
 */
public class HiddenLootValuationTest
{
	private static final int RUNE = 1;
	private static final int BONES = 2;
	private static final int UNPRICED = 3;
	private static final int POTION = 4;
	private static final HiddenLoot HIDE_BONES = HiddenLoot.of(Collections.singleton(BONES));

	private static Map<Integer, Long> map(long... idValue)
	{
		Map<Integer, Long> map = new HashMap<>();
		for (int i = 0; i < idValue.length; i += 2)
		{
			map.put((int) idValue[i], idValue[i + 1]);
		}
		return map;
	}

	/**
	 * A completed hour-long task: loot 2 runes (GE 100, HA 60), 10 bones (GE 50, HA 5) and an item without a GE price
	 * (HA 300); supplies 600 gp. Totals as {@link LedgerRecord#captureValues} saves them.
	 */
	private static LedgerRecord record()
	{
		LedgerRecord r = new LedgerRecord();
		r.setId("a");
		r.setMonster("Kurask");
		r.setCreatureId(410);
		r.setKills(10);
		r.setActiveMillis(3_600_000L);
		r.setStartedAt(1_000L);
		r.setEndedAt(3_601_000L);
		r.setCompleted(true);
		r.setPartial(false);
		r.setLoot(map(RUNE, 2, BONES, 10, UNPRICED, 1));
		r.setSupplies(map(POTION, 3));
		r.setSupplyDoses(Collections.singletonMap(POTION, 4));
		r.setUnitGePrices(map(RUNE, 100, BONES, 50, POTION, 800));
		r.setUnitHaPrices(map(RUNE, 60, BONES, 5, UNPRICED, 300, POTION, 100));
		r.setLootGeValue(700L);
		r.setLootHaValue(470L);
		r.setSuppliesGeValue(600L);
		r.setSuppliesHaValue(75L);
		r.setLootUnpricedItems(1);
		return r;
	}

	@Test
	public void savedPricesLeaveHiddenItemsOutOfLootAndProfit()
	{
		HistoryPricing.Values all = HistoryPricing.value(record(), LootPriceMode.GE, null, HiddenLoot.NONE);
		HistoryPricing.Values hidden = HistoryPricing.value(record(), LootPriceMode.GE, null, HIDE_BONES);
		assertEquals(Long.valueOf(700), all.getLootValue());
		assertEquals("10 bones at 50 gp left out", Long.valueOf(200), hidden.getLootValue());
		assertEquals(Long.valueOf(200), hidden.getLootGe());
		assertEquals("high alch too", Long.valueOf(420), hidden.getLootHa());
		assertEquals("supplies unchanged", all.getSuppliesGe(), hidden.getSuppliesGe());
		assertEquals(Long.valueOf(-400), hidden.getProfit());
		assertTrue("the unpriced item still counts", hidden.isLootApproximate());

		HistoryPricing.Values ha = HistoryPricing.value(record(), LootPriceMode.HIGH_ALCH, null, HIDE_BONES);
		assertEquals(Long.valueOf(420), ha.getLootValue());
		assertEquals(Long.valueOf(-180), ha.getProfit());
	}

	@Test
	public void aHiddenUnpricedItemNoLongerMakesTheValueApproximate()
	{
		HistoryPricing.Values v = HistoryPricing.value(record(), LootPriceMode.GE, null,
			HiddenLoot.of(Collections.singleton(UNPRICED)));
		assertEquals(Long.valueOf(700), v.getLootValue());
		assertFalse(v.isLootApproximate());
		assertEquals(Long.valueOf(470 - 300), v.getLootHa());
	}

	@Test
	public void todaysPricesLeaveHiddenItemsOutToo()
	{
		Map<Integer, Long> today = map(RUNE, 150, BONES, 80, POTION, 800);
		assertEquals(Long.valueOf(300 + 800), HistoryPricing.value(record(), LootPriceMode.GE, today,
			HiddenLoot.NONE).getLootValue());
		assertEquals(Long.valueOf(300), HistoryPricing.value(record(), LootPriceMode.GE, today, HIDE_BONES)
			.getLootValue());
	}

	@Test
	public void todaysPricesInHighAlchLeaveHiddenItemsOutOfTheLootNotTheSupplies()
	{
		Map<Integer, Long> today = map(RUNE, 150, BONES, 80, POTION, 1_600);
		HistoryPricing.Values ha = HistoryPricing.value(record(), LootPriceMode.HIGH_ALCH, today, HIDE_BONES);
		assertEquals("2 runes at 60 and the 300 item; the bones (5 each) left out", Long.valueOf(420),
			ha.getLootValue());
		assertEquals("3 doses of a 1,600 gp 4-dose potion, today", Long.valueOf(1_200), ha.getSuppliesGe());
		assertEquals(Long.valueOf(420 - 1_200), ha.getProfit());
		assertEquals(Long.valueOf(470), HistoryPricing.value(record(), LootPriceMode.HIGH_ALCH, today,
			HiddenLoot.NONE).getLootValue());
	}

	@Test
	public void aRecordWithoutUnitPricesLeavesHiddenItemsOutOnlyAtGe()
	{
		LedgerRecord old = record();
		old.setUnitGePrices(null);
		old.setUnitHaPrices(null);
		HistoryPricing.Values v = HistoryPricing.value(old, LootPriceMode.GE, null, HIDE_BONES);
		assertEquals("at saved prices, nothing per item to leave out", Long.valueOf(700), v.getLootValue());
		assertEquals(Long.valueOf(470), v.getLootHa());

		// At today's prices its items are valued, so the bones are left out of the GE value; its high alch
		// value is its saved total, hidden items included.
		HistoryPricing.Values today = HistoryPricing.value(old, LootPriceMode.GE, map(RUNE, 150, BONES, 80),
			HIDE_BONES);
		assertEquals("2 runes at 150; the unpriced item left out and marked", Long.valueOf(300), today.getLootValue());
		assertFalse(today.isSavedTotals());
		assertTrue(today.isLootApproximate());
		assertEquals(Long.valueOf(470), today.getLootHa());

		// Saved without items: its saved totals, hidden items included, marked ~.
		old.setLoot(null);
		old.setSupplies(null);
		HistoryPricing.Values totals = HistoryPricing.value(old, LootPriceMode.GE, map(RUNE, 150, BONES, 80),
			HIDE_BONES);
		assertEquals(Long.valueOf(700), totals.getLootValue());
		assertTrue(totals.isSavedTotals());
		assertTrue(totals.isLootApproximate());
	}

	@Test
	public void nothingHiddenIsTheValueAsBefore()
	{
		for (LootPriceMode mode : LootPriceMode.values())
		{
			HistoryPricing.Values before = HistoryPricing.value(record(), mode, null);
			HistoryPricing.Values none = HistoryPricing.value(record(), mode, null, HiddenLoot.NONE);
			HistoryPricing.Values other = HistoryPricing.value(record(), mode, null,
				HiddenLoot.of(Collections.singleton(995)));
			for (HistoryPricing.Values v : new HistoryPricing.Values[]{none, other})
			{
				assertEquals(before.getLootValue(), v.getLootValue());
				assertEquals(before.getLootHa(), v.getLootHa());
				assertEquals(before.getLootUnpriced(), v.getLootUnpriced());
				assertEquals(before.getLootGeUnpriced(), v.getLootGeUnpriced());
			}
		}
		LedgerRecord record = record();
		HistoryPricing.value(record, LootPriceMode.GE, null, HIDE_BONES);
		assertEquals("the record is not changed", Long.valueOf(10), record.getLoot().get(BONES));
	}

	@Test
	public void totalsAndTheirRatesDropByTheHiddenValue()
	{
		List<LedgerRecord> records = Collections.singletonList(record());
		// Today's prices are the ones the task was saved with.
		Map<Integer, Long> saved = map(RUNE, 100, BONES, 50, POTION, 800);

		List<OverallTotals.Entry> totals = TestTotals.summarize(records, OverallTotals.Grouping.ALL,
			LootPriceMode.GE, saved, HIDE_BONES, ZoneOffset.UTC);
		assertEquals(Long.valueOf(-400), totals.get(0).getProfit());
		assertEquals("profit/h: 200 - 600 over an hour", Long.valueOf(-400), totals.get(0).getProfitPerHour());
		assertEquals("the summed loot items still list the bones (the grid leaves them out)", 3,
			totals.get(0).getLoot().size());
		OverallTotals.Entry all = TestTotals.summarize(records, OverallTotals.Grouping.ALL, LootPriceMode.GE, saved,
			HiddenLoot.NONE, ZoneOffset.UTC).get(0);
		assertEquals(Long.valueOf(100), all.getProfit());
		assertEquals(Long.valueOf(100), all.getProfitPerHour());
	}

	// ---- Coins always count in the value (owner decision, 2026-10-28) ----

	private static final int COINS = ItemValuation.COINS;
	/** Coins and bones hidden, as Ground Items' built-in list hides them. */
	private static final HiddenLoot HIDE_COINS_AND_BONES = HiddenLoot.of(Arrays.asList(COINS, BONES));

	/** {@link #record()} with 500 coins more in the loot, priced at face value as {@link ItemValuation} saves them. */
	private static LedgerRecord recordWithCoins()
	{
		LedgerRecord r = record();
		r.setLoot(map(RUNE, 2, BONES, 10, UNPRICED, 1, COINS, 500));
		r.setUnitGePrices(map(RUNE, 100, BONES, 50, POTION, 800, COINS, 1));
		r.setUnitHaPrices(map(RUNE, 60, BONES, 5, UNPRICED, 300, POTION, 100, COINS, 1));
		r.setLootGeValue(1_200L);
		r.setLootHaValue(970L);
		return r;
	}

	@Test
	public void hiddenCoinsStillCountInSavedTasksValues()
	{
		HistoryPricing.Values ge = HistoryPricing.value(recordWithCoins(), LootPriceMode.GE, null,
			HIDE_COINS_AND_BONES);
		assertEquals("only the 10 bones at 50 gp are left out", Long.valueOf(1_200 - 500), ge.getLootValue());
		assertEquals(Long.valueOf(970 - 50), ge.getLootHa());
		assertEquals(Long.valueOf(700 - 600), ge.getProfit());

		HistoryPricing.Values ha = HistoryPricing.value(recordWithCoins(), LootPriceMode.HIGH_ALCH, null,
			HIDE_COINS_AND_BONES);
		assertEquals(Long.valueOf(920), ha.getLootValue());

		HistoryPricing.Values coinsOnly = HistoryPricing.value(recordWithCoins(), LootPriceMode.GE, null,
			HiddenLoot.of(Collections.singleton(COINS)));
		assertEquals("hidden coins alone change no value", Long.valueOf(1_200), coinsOnly.getLootValue());
		assertEquals(Long.valueOf(970), coinsOnly.getLootHa());

		Map<Integer, Long> today = map(RUNE, 150, BONES, 80, POTION, 800, COINS, 1);
		assertEquals("today's prices: coins at face value, bones left out", Long.valueOf(300 + 500),
			HistoryPricing.value(recordWithCoins(), LootPriceMode.GE, today, HIDE_COINS_AND_BONES).getLootValue());

		String line = TaskCompleteMessage.format(recordWithCoins(), LootPriceMode.GE, HIDE_COINS_AND_BONES, true);
		assertTrue(line, line.endsWith(", ~+100. Gz."));
	}

	@Test
	public void hiddenCoinsStillCountInTheTotals()
	{
		List<LedgerRecord> records = Collections.singletonList(recordWithCoins());
		// Today's prices are the ones the task was saved with.
		Map<Integer, Long> today = map(RUNE, 100, BONES, 50, POTION, 800, COINS, 1);

		OverallTotals.Entry totals = TestTotals.summarize(records, OverallTotals.Grouping.ALL, LootPriceMode.GE,
			today, HIDE_COINS_AND_BONES, ZoneOffset.UTC).get(0);
		assertEquals(Long.valueOf(100), totals.getProfit());
		assertEquals("profit/h: 700 - 600 over an hour", Long.valueOf(100), totals.getProfitPerHour());
		assertEquals("the summed loot items still list coins and bones (the grid hides them)", 4,
			totals.getLoot().size());
	}

	@Test
	public void hiddenCoinsStillCountInTheLiveValues()
	{
		SessionValuation valuation = new SessionValuation();
		ItemTally loot = new ItemTally();
		loot.add(BONES, 10);
		loot.add(RUNE, 1);
		loot.add(COINS, 2_500);
		SessionValuation.Values v = valuation.update("s1", loot, null, null, LootPriceMode.GE,
			HIDE_COINS_AND_BONES, new Lookup(), 0);
		assertEquals("the rune and the coins; the bones are left out", 1_000 + 2_500, v.getLootValue());
		assertEquals(600 + 2_500, v.getLootHa());
		assertEquals(3_500, v.getProfit());
		assertEquals("the grid still gets coins to hide", HIDE_COINS_AND_BONES, v.getHiddenLoot());
		assertEquals(1, HIDE_COINS_AND_BONES.visibleRows(v.getItems().lootRows(LootPriceMode.GE, null)).size());
	}

	@Test
	public void theTaskCompleteLineLeavesHiddenLootOut()
	{
		String all = TaskCompleteMessage.format(record(), LootPriceMode.GE);
		String hidden = TaskCompleteMessage.format(record(), LootPriceMode.GE, HIDE_BONES, true);
		assertTrue(all, all.endsWith(", ~+100. Gz."));
		assertTrue(hidden, hidden.endsWith(", ~-400. Gz."));
	}

	// ---- The live session ----

	/** GE 100 a bone, 1,000 a shark; high alch 5 a bone. */
	private static final class Lookup implements ItemValuation.PriceLookup
	{
		@Override
		public int canonicalize(int itemId)
		{
			return itemId;
		}

		@Override
		public long gePrice(int canonicalId)
		{
			return canonicalId == BONES ? 100 : canonicalId == RUNE ? 1_000 : 0;
		}

		@Override
		public long haPrice(int canonicalId)
		{
			return canonicalId == BONES ? 5 : 600;
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return true;
		}
	}

	@Test
	public void liveValuesLeaveHiddenLootOutAndFollowTheList()
	{
		SessionValuation valuation = new SessionValuation();
		Lookup lookup = new Lookup();
		ItemTally loot = new ItemTally();
		loot.add(BONES, 10);
		loot.add(RUNE, 1);
		SessionValuation.Values all = valuation.update("s1", loot, null, null, LootPriceMode.GE, HiddenLoot.NONE,
			lookup, 0);
		assertEquals(2_000, all.getLootValue());
		assertEquals(HiddenLoot.NONE, all.getHiddenLoot());

		SessionValuation.Values hidden = valuation.update("s1", loot, null, null, LootPriceMode.GE, HIDE_BONES,
			lookup, 1);
		assertNotEquals("another hidden list is valued again", all, hidden);
		assertEquals(1_000, hidden.getLootValue());
		assertEquals(1_000, hidden.getLootGe());
		assertEquals(600, hidden.getLootHa());
		assertEquals(1_000, hidden.getProfit());
		assertEquals(HIDE_BONES, hidden.getHiddenLoot());
		assertEquals("the item details still list the bones", 2,
			hidden.getItems().lootRows(LootPriceMode.GE, null).size());
		assertEquals("the tally is not changed", 10, loot.get(BONES));

		SessionValuation.Values ha = valuation.update("s1", loot, null, null, LootPriceMode.HIGH_ALCH, HIDE_BONES,
			lookup, 2);
		assertEquals(600, ha.getLootValue());

		SessionValuation.Values back = valuation.update("s1", loot, null, null, LootPriceMode.GE, HiddenLoot.NONE,
			lookup, 3);
		assertEquals(all, back);
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.TestSpots.TABLE;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * The Task history's setup filters (V2 plan 5): Task type, Cannon, Style and Gear, each "Any" or one value, on
 * the records' effective tags. A record whose value is unknown shows only under "Any", and an estimated value is its
 * value. The Monster filter's "(cannon)" names follow the same Cannon tag. {@link HistoryFilterTest} covers Monster,
 * Location and Master.
 */
public class HistoryFilterSetupTest
{
	private static final int CREATURE = 42;

	/** A record of {@code master}'s with the detected tags given (none estimated, no overrides). */
	private static LedgerRecord record(String id, Integer master, boolean cannon, SetupStyle style, GearFocus gear)
	{
		final LedgerRecord record = new LedgerRecord();
		record.setId(id);
		record.setMonster("Dust devils");
		record.setCreatureId(CREATURE);
		record.setSlayerMaster(master);
		SetupTags.detected(cannon, style, gear, SetupOverrides.NONE).copyTo(record);
		return record;
	}

	/** Newest first, as the model holds them. */
	private static List<LedgerRecord> history()
	{
		final LedgerRecord boss = record("boss", 6, false, SetupStyle.MELEE, GearFocus.PRAYER);
		boss.setCreatureId(-2 - 7);
		boss.setMonster("Cerberus");
		// A migrated task: an estimated cannon and Barrage, gear Unknown.
		final LedgerRecord migrated = record("migrated", 6, false, SetupStyle.BARRAGE, GearFocus.UNKNOWN);
		SetupTags.estimated(true, SetupStyle.BARRAGE).copyTo(migrated);
		// Detected Magic, set to Ranged by the player.
		final LedgerRecord overridden = record("overridden", 5, false, SetupStyle.MAGIC, GearFocus.STRENGTH);
		overridden.setStyleOverride(SetupStyle.RANGED);
		overridden.setGearOverride(GearFocus.MIXED);
		return Arrays.asList(
			record("regular", 6, true, SetupStyle.MELEE, GearFocus.PRAYER),
			record("konar", SlayerMaster.KONAR, false, SetupStyle.MAGIC, GearFocus.STRENGTH),
			record("wilderness", SlayerMaster.KRYSTILIA, false, SetupStyle.MIXED, GearFocus.MIXED),
			record("noMaster", null, false, SetupStyle.UNKNOWN, GearFocus.UNKNOWN),
			boss,
			migrated,
			overridden);
	}

	private static List<String> ids(HistoryFilter filter)
	{
		final List<String> ids = new ArrayList<>();
		for (LedgerRecord record : filter.apply(history(), TABLE, region -> null))
		{
			ids.add(record.getId());
		}
		return ids;
	}

	private static HistoryFilter any()
	{
		return new HistoryFilter(null, null, null);
	}

	@Test
	public void anyShowsEveryRecordUnknownValuesIncluded()
	{
		assertEquals(7, ids(any().withTaskType(null).withCannon(null).withStyle(null).withGear(null)).size());
	}

	@Test
	public void taskTypeFromTheMasterAndTheCreatureKey()
	{
		assertEquals(Arrays.asList("regular", "migrated", "overridden"), ids(any().withTaskType(TaskType.REGULAR)));
		assertEquals(Arrays.asList("konar"), ids(any().withTaskType(TaskType.KONAR)));
		assertEquals(Arrays.asList("wilderness"), ids(any().withTaskType(TaskType.WILDERNESS)));
		assertEquals("whoever assigned it", Arrays.asList("boss"), ids(any().withTaskType(TaskType.BOSS)));
	}

	@Test
	public void cannonIsTheEffectiveValueAndAnEstimateCountsAsItsValue()
	{
		assertEquals(Arrays.asList("regular", "migrated"), ids(any().withCannon(true)));
		assertEquals(Arrays.asList("konar", "wilderness", "noMaster", "boss", "overridden"),
			ids(any().withCannon(false)));
	}

	@Test
	public void theMonsterFiltersCannonNameFollowsTheCannonTagAsTheCannonFilterDoes()
	{
		// A brief cannon setup: cannonballs fired, but too few cannon kills for the tag.
		final LedgerRecord brief = record("brief", 6, false, SetupStyle.MELEE, GearFocus.PRAYER);
		brief.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 20L));
		// No cannonballs recorded, set to Yes by the player.
		final LedgerRecord setYes = record("setYes", 6, false, SetupStyle.MELEE, GearFocus.PRAYER);
		setYes.setCannonOverride(true);
		// Cannonballs fired, set to No by the player.
		final LedgerRecord setNo = record("setNo", 6, true, SetupStyle.MELEE, GearFocus.PRAYER);
		setNo.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 500L));
		setNo.setCannonOverride(false);
		// A migrated task: its estimated cannon from its cannonballs.
		final LedgerRecord migrated = record("migrated", 6, false, SetupStyle.UNKNOWN, GearFocus.UNKNOWN);
		migrated.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 50L));
		SetupTags.estimated(true, SetupStyle.MELEE).copyTo(migrated);
		final List<LedgerRecord> records = Arrays.asList(brief, setYes, setNo, migrated);

		assertEquals(Arrays.asList("Dust devils", "Dust devils (cannon)", "Dust devils", "Dust devils (cannon)"),
			Arrays.asList(LedgerHistory.monster(brief), LedgerHistory.monster(setYes), LedgerHistory.monster(setNo),
				LedgerHistory.monster(migrated)));
		for (boolean cannon : new boolean[]{true, false})
		{
			final HistoryFilter byName = new HistoryFilter(cannon ? "Dust devils (cannon)" : "Dust devils", null, null);
			assertEquals("cannon " + cannon, any().withCannon(cannon).apply(records, TABLE, region -> null),
				byName.apply(records, TABLE, region -> null));
		}

		// A record built without tags (none is read from the file so) still goes by its cannonballs.
		final LedgerRecord untagged = new LedgerRecord();
		untagged.setMonster("Dust devils");
		untagged.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 50L));
		assertEquals("Dust devils (cannon)", untagged.groupName());
	}

	@Test
	public void styleShowsUnknownOnlyUnderAnyAndAnEstimatedBarrageIsBarrage()
	{
		assertEquals(Arrays.asList("regular", "boss"), ids(any().withStyle(SetupStyle.MELEE)));
		assertEquals("the player's override", Arrays.asList("overridden"), ids(any().withStyle(SetupStyle.RANGED)));
		assertEquals(Arrays.asList("migrated"), ids(any().withStyle(SetupStyle.BARRAGE)));
		assertEquals(Arrays.asList("konar"), ids(any().withStyle(SetupStyle.MAGIC)));
		assertEquals(Arrays.asList("wilderness"), ids(any().withStyle(SetupStyle.MIXED)));
		assertEquals("Unknown is no choice: Any", 7, ids(any().withStyle(SetupStyle.UNKNOWN)).size());
	}

	@Test
	public void gearShowsUnknownOnlyUnderAny()
	{
		assertEquals(Arrays.asList("regular", "boss"), ids(any().withGear(GearFocus.PRAYER)));
		assertEquals(Arrays.asList("konar"), ids(any().withGear(GearFocus.STRENGTH)));
		assertEquals("the override", Arrays.asList("wilderness", "overridden"), ids(any().withGear(GearFocus.MIXED)));
		assertEquals("Unknown is no choice: Any", 7, ids(any().withGear(GearFocus.UNKNOWN)).size());
	}

	@Test
	public void theFiltersCombineWithEachOtherAndTheMonsterFilter()
	{
		assertEquals(Arrays.asList("regular"), ids(any().withTaskType(TaskType.REGULAR).withCannon(true)
			.withStyle(SetupStyle.MELEE).withGear(GearFocus.PRAYER)));
		assertTrue(ids(any().withCannon(true).withStyle(SetupStyle.MAGIC)).isEmpty());
		assertEquals(Arrays.asList("boss"),
			ids(new HistoryFilter("Cerberus", null, null).withGear(GearFocus.PRAYER)));
		assertEquals("a later choice replaces the earlier", Arrays.asList("konar"),
			ids(any().withStyle(SetupStyle.MELEE).withStyle(SetupStyle.MAGIC)));
	}

	@Test
	public void theChoicesAndTheirLabels()
	{
		assertEquals(Arrays.asList(null, TaskType.REGULAR, TaskType.KONAR, TaskType.WILDERNESS, TaskType.BOSS),
			HistoryFilter.TASK_TYPE_CHOICES);
		assertEquals(Arrays.asList(null, true, false), HistoryFilter.CANNON_CHOICES);
		assertEquals(Arrays.asList(null, SetupStyle.MELEE, SetupStyle.RANGED, SetupStyle.BARRAGE, SetupStyle.MAGIC,
			SetupStyle.MIXED), HistoryFilter.STYLE_CHOICES);
		assertEquals(Arrays.asList(null, GearFocus.PRAYER, GearFocus.STRENGTH, GearFocus.MIXED),
			HistoryFilter.GEAR_CHOICES);

		final List<String> labels = new ArrayList<>();
		for (List<?> choices : Arrays.asList(HistoryFilter.TASK_TYPE_CHOICES, HistoryFilter.CANNON_CHOICES,
			HistoryFilter.STYLE_CHOICES, HistoryFilter.GEAR_CHOICES))
		{
			for (Object choice : choices)
			{
				labels.add(HistoryFilter.setupLabel(choice));
			}
		}
		assertEquals(Arrays.asList("Any", "Regular", "Konar", "Wilderness", "Boss", "Any", "Yes", "No", "Any", "Melee",
			"Ranged", "Barrage", "Magic", "Mixed", "Any", "Prayer", "Strength", "Mixed"), labels);
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.TestSpots.CATACOMBS;
import static com.shmayvan.slayerledger.TestSpots.CATACOMBS_ID;
import static com.shmayvan.slayerledger.TestSpots.SMOKE;
import static com.shmayvan.slayerledger.TestSpots.SMOKE_ID;
import static com.shmayvan.slayerledger.TestSpots.STRONGHOLD;
import static com.shmayvan.slayerledger.TestSpots.STRONGHOLD_ID;
import static com.shmayvan.slayerledger.TestSpots.TABLE;
import static com.shmayvan.slayerledger.TestSpots.UNLISTED;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import org.junit.Test;

/**
 * The Task history's Location and Master filters, combined with the Monster filter: the Location filter groups
 * by spot and shows each spot by the location name of its newest task without a name of its own.
 */
public class HistoryFilterTest
{
	private static final String UNLISTED_KEY = "region:" + UNLISTED;
	private static final Map<Integer, String> REGION_NAMES = Collections.singletonMap(UNLISTED, "Edgeville");
	private static final IntFunction<String> NAMES = REGION_NAMES::get;
	private static final IntFunction<String> NO_NAMES = region -> null;

	private static LedgerRecord record(String id, String monster, String location, Integer master)
	{
		LedgerRecord record = new LedgerRecord();
		record.setId(id);
		record.setMonster(monster);
		record.setLocation(location);
		record.setSlayerMaster(master);
		return record;
	}

	private static LedgerRecord at(String id, String monster, int region, String spotId, Integer master)
	{
		LedgerRecord record = record(id, monster, null, master);
		record.setLocationRegion(region);
		record.setSpotId(spotId);
		return record;
	}

	private static List<String> ids(List<LedgerRecord> records)
	{
		List<String> ids = new ArrayList<>();
		for (LedgerRecord record : records)
		{
			ids.add(record.getId());
		}
		return ids;
	}

	private static List<String> filter(String monster, String location, String master, List<LedgerRecord> records)
	{
		return ids(new HistoryFilter(monster, location, master).apply(records, TABLE, NAMES));
	}

	/** Newest first, as the model holds them. */
	private static List<LedgerRecord> history()
	{
		LedgerRecord konar = record("k", "Hydras", null, SlayerMaster.KONAR);
		konar.setTaskLocation("Karuulm Slayer Dungeon");
		// A 1.x record in the Smoke Dungeon, saved with the name its region had then: no spot stored.
		LedgerRecord oneX = record("x", "Dust devils", "Smokey", 5);
		oneX.setLocationRegion(SMOKE);
		return Arrays.asList(
			at("a", "Abyssal demons", CATACOMBS, CATACOMBS_ID, 5),
			at("b", "Dust devils", SMOKE, SMOKE_ID, 6),
			oneX,
			at("e", "Dust devils", UNLISTED, UNLISTED_KEY, null),
			konar,
			record("c", "Abyssal demons", "abyss", 99),
			record("d", "Abyssal demons", null, SlayerMaster.NONE));
	}

	@Test
	public void aRecordsLocationKeyIsItsSpotElseItsOwnNameElseNoLocation()
	{
		List<LedgerRecord> records = history();
		assertEquals(CATACOMBS_ID, HistoryFilter.locationKey(records.get(0), TABLE, NAMES));
		assertEquals("a record saved before spots: its region's", SMOKE_ID,
			HistoryFilter.locationKey(records.get(2), TABLE, NAMES));
		assertEquals(UNLISTED_KEY, HistoryFilter.locationKey(records.get(3), TABLE, NO_NAMES));
		assertEquals("no spot: its assigned area", HistoryFilter.NAME_PREFIX + "karuulm slayer dungeon",
			HistoryFilter.locationKey(records.get(4), TABLE, NAMES));
		assertEquals("no spot: its own name", HistoryFilter.NAME_PREFIX + "abyss",
			HistoryFilter.locationKey(records.get(5), TABLE, NAMES));
		assertEquals(HistoryFilter.NO_LOCATION, HistoryFilter.locationKey(records.get(6), TABLE, NAMES));
		assertEquals("without the table, a stored spot still groups", SMOKE_ID,
			HistoryFilter.locationKey(records.get(1), SlayerSpots.NONE, NAMES));
	}

	@Test
	public void aRecordsMasterIsItsNameOrUnknownMaster()
	{
		List<LedgerRecord> records = history();
		assertEquals("Duradel/Kuradal", HistoryFilter.master(records.get(0)));
		assertEquals("Konar", HistoryFilter.master(records.get(4)));
		assertEquals("no master saved", HistoryFilter.UNKNOWN_MASTER, HistoryFilter.master(records.get(3)));
		assertEquals("a value not in the table", HistoryFilter.UNKNOWN_MASTER, HistoryFilter.master(records.get(5)));
		assertEquals("no task", HistoryFilter.UNKNOWN_MASTER, HistoryFilter.master(records.get(6)));
	}

	@Test
	public void locationChoicesAreAllThenEachSpotByItsNewestNameAlphabeticallyThenNoLocation()
	{
		HistoryFilter.LocationChoices choices = HistoryFilter.locationChoices(history(), TABLE, NAMES);
		assertEquals(Arrays.asList(LedgerHistory.ALL, HistoryFilter.NAME_PREFIX + "abyss", CATACOMBS_ID, UNLISTED_KEY,
			HistoryFilter.NAME_PREFIX + "karuulm slayer dungeon", SMOKE_ID, HistoryFilter.NO_LOCATION),
			choices.getOptions());
		List<String> labels = new ArrayList<>();
		for (String option : choices.getOptions())
		{
			labels.add(choices.label(option));
		}
		assertEquals("the Smoke Dungeon shows its newest task's name", Arrays.asList(LedgerHistory.ALL, "abyss",
			"Catacombs of Kourend", "Edgeville", "Karuulm Slayer Dungeon", "Smoke Dungeon", "No location"), labels);
	}

	@Test
	public void aTaskRenamedOnItsOwnStaysInItsSpotsChoice()
	{
		// The newest Smoke Dungeon task was renamed on its own: the spot is one choice, and that task's name names only
		// that task, so the choice keeps the spot's name.
		LedgerRecord renamed = at("new", "Dust devils", SMOKE, SMOKE_ID, 5);
		renamed.setLocation("West side");
		List<LedgerRecord> records = Arrays.asList(renamed, at("old", "Dust devils", SMOKE, SMOKE_ID, 5),
			at("cata", "Dust devils", CATACOMBS, CATACOMBS_ID, 5));
		HistoryFilter.LocationChoices choices = HistoryFilter.locationChoices(records, TABLE, NAMES);
		assertEquals(Arrays.asList(LedgerHistory.ALL, CATACOMBS_ID, SMOKE_ID), choices.getOptions());
		assertEquals("Smoke Dungeon", choices.label(SMOKE_ID));
		assertEquals(Arrays.asList("new", "old"), filter(null, SMOKE_ID, null, records));
	}

	@Test
	public void aSpotsChoiceIsNamedByItsNewestTaskWithoutANameOfItsOwn()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(CATACOMBS, "Cata");
		LedgerRecord newest = at("new", "Dust devils", CATACOMBS, CATACOMBS_ID, 5);
		newest.setLocation("North end");
		LedgerRecord oldest = at("old", "Dust devils", CATACOMBS, CATACOMBS_ID, 5);
		oldest.setLocation("South end");
		List<LedgerRecord> records = Arrays.asList(newest, at("mid", "Dust devils", CATACOMBS, CATACOMBS_ID, 5), oldest);
		assertEquals("the player's name for the region, not a task's own", "Cata",
			HistoryFilter.locationChoices(records, TABLE, names::get).label(CATACOMBS_ID));
		assertEquals("or the table's", "Catacombs of Kourend",
			HistoryFilter.locationChoices(records, TABLE, NO_NAMES).label(CATACOMBS_ID));

		// 1.x tasks there all named by hand: the newest one's name, so the place is found by a name the player gave.
		LedgerRecord smokey = record("smokey", "Dust devils", "Smokey", 5);
		smokey.setLocationRegion(SMOKE);
		LedgerRecord west = record("west", "Dust devils", "Smoke west", 5);
		west.setLocationRegion(SMOKE);
		HistoryFilter.LocationChoices oneX = HistoryFilter.locationChoices(Arrays.asList(smokey, west), TABLE, NAMES);
		assertEquals(Arrays.asList(LedgerHistory.ALL, SMOKE_ID), oneX.getOptions());
		assertEquals("Smokey", oneX.label(SMOKE_ID));
	}

	@Test
	public void aStoredSpotTheTableNoLongerHasGroupsByItsRegion()
	{
		// An id a later table dropped or renamed: the record takes its region's spot, and groups and is named with it.
		List<LedgerRecord> records = Arrays.asList(at("stale", "Dust devils", SMOKE, "smoke-dungeon-before", 5),
			at("current", "Dust devils", SMOKE, SMOKE_ID, 5));
		assertEquals(SMOKE_ID, HistoryFilter.locationKey(records.get(0), TABLE, NAMES));
		HistoryFilter.LocationChoices choices = HistoryFilter.locationChoices(records, TABLE, NAMES);
		assertEquals(Arrays.asList(LedgerHistory.ALL, SMOKE_ID), choices.getOptions());
		assertEquals("Smoke Dungeon", choices.label(SMOKE_ID));
		assertEquals(Arrays.asList("stale", "current"), filter(null, SMOKE_ID, null, records));
	}

	@Test
	public void theSameNameInTwoSpotsIsTwoChoices()
	{
		// Aberrant spectres in the Catacombs and in the Stronghold Slayer Cave, both shown as "Spectres".
		Map<Integer, String> names = new HashMap<>();
		names.put(CATACOMBS, "Spectres");
		names.put(STRONGHOLD, "Spectres");
		List<LedgerRecord> records = Arrays.asList(at("cata", "Aberrant spectres", CATACOMBS, CATACOMBS_ID, 5),
			at("stronghold", "Aberrant spectres", STRONGHOLD, STRONGHOLD_ID, 5));
		HistoryFilter.LocationChoices choices = HistoryFilter.locationChoices(records, TABLE, names::get);
		assertEquals(Arrays.asList(LedgerHistory.ALL, CATACOMBS_ID, STRONGHOLD_ID), choices.getOptions());
		assertEquals(Collections.singletonList("stronghold"),
			ids(new HistoryFilter(null, STRONGHOLD_ID, null).apply(records, TABLE, names::get)));
	}

	@Test
	public void namesWithoutASpotThatAreTheSamePlaceAreOneChoiceAsTheNewestRecordSpellsIt()
	{
		List<LedgerRecord> records = Arrays.asList(record("new", "Kurask", "Fremennik  slayer dungeon", 5),
			record("old", "Kurask", "Fremennik Slayer Dungeon", 5));
		HistoryFilter.LocationChoices choices = HistoryFilter.locationChoices(records, TABLE, NAMES);
		String key = HistoryFilter.NAME_PREFIX + "fremennik slayer dungeon";
		assertEquals(Arrays.asList(LedgerHistory.ALL, key), choices.getOptions());
		assertEquals("Fremennik slayer dungeon", choices.label(key));
		assertEquals(Arrays.asList("new", "old"), filter(null, key, null, records));
	}

	@Test
	public void masterChoicesAreAllThenEachMasterAlphabeticallyThenUnknownMaster()
	{
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Duradel/Kuradal", "Konar", "Nieve/Steve",
			HistoryFilter.UNKNOWN_MASTER), HistoryFilter.masterOptions(history()));
	}

	@Test
	public void choicesLeaveOutSentinelsNobodyHasAndAreJustAllWithoutRecords()
	{
		List<LedgerRecord> records = Collections.singletonList(at("a", "Kurask", SMOKE, SMOKE_ID, 6));
		assertEquals(Arrays.asList(LedgerHistory.ALL, SMOKE_ID),
			HistoryFilter.locationChoices(records, TABLE, NAMES).getOptions());
		assertEquals(Arrays.asList(LedgerHistory.ALL, "Nieve/Steve"), HistoryFilter.masterOptions(records));
		assertEquals(Collections.singletonList(LedgerHistory.ALL),
			HistoryFilter.locationChoices(Collections.emptyList(), TABLE, NAMES).getOptions());
		assertEquals(Collections.singletonList(LedgerHistory.ALL), HistoryFilter.masterOptions(Collections.emptyList()));
	}

	@Test
	public void eachFilterAloneKeepsTheRecordOrder()
	{
		List<LedgerRecord> records = history();
		assertEquals(Arrays.asList("a", "b", "x", "e", "k", "c", "d"), filter(null, null, null, records));
		assertEquals(Arrays.asList("a", "c", "d"), filter("Abyssal demons", null, null, records));
		assertEquals("a 1.x record with its own name groups by its region's spot", Arrays.asList("b", "x"),
			filter(null, SMOKE_ID, null, records));
		assertEquals(Collections.singletonList("e"), filter(null, UNLISTED_KEY, null, records));
		assertEquals(Collections.singletonList("d"), filter(null, HistoryFilter.NO_LOCATION, null, records));
		assertEquals(Arrays.asList("a", "x"), filter(null, null, "Duradel/Kuradal", records));
		assertEquals(Arrays.asList("e", "c", "d"), filter(null, null, HistoryFilter.UNKNOWN_MASTER, records));
	}

	@Test
	public void filtersCombine()
	{
		List<LedgerRecord> records = history();
		assertEquals(Collections.singletonList("x"), filter("Dust devils", SMOKE_ID, "Duradel/Kuradal", records));
		assertEquals(Collections.singletonList("d"),
			filter("Abyssal demons", HistoryFilter.NO_LOCATION, HistoryFilter.UNKNOWN_MASTER, records));
		assertEquals("each matches alone, not together", Collections.emptyList(),
			filter("Hydras", CATACOMBS_ID, null, records));
	}

	@Test
	public void aLocationSelectionIsKeptWhileItIsAChoice()
	{
		List<String> options = Arrays.asList(LedgerHistory.ALL, CATACOMBS_ID, SMOKE_ID, HistoryFilter.NO_LOCATION);
		assertEquals(SMOKE_ID, HistoryFilter.keepLocation(options, SMOKE_ID));
		assertEquals(HistoryFilter.NO_LOCATION, HistoryFilter.keepLocation(options, HistoryFilter.NO_LOCATION));
		assertNull(HistoryFilter.keepLocation(options, STRONGHOLD_ID));
		assertNull(HistoryFilter.keepLocation(options, null));
		assertNull(HistoryFilter.keepLocation(options, LedgerHistory.ALL));
		assertNull("no record without a location any more",
			HistoryFilter.keepLocation(Arrays.asList(LedgerHistory.ALL, CATACOMBS_ID), HistoryFilter.NO_LOCATION));
	}

	@Test
	public void aPlaceNamedNoLocationIsAChoiceOfItsOwn()
	{
		List<LedgerRecord> records = Arrays.asList(record("named", "Kurask", "No location", 6),
			record("respelled", "Kurask", "no  LOCATION", 6), record("none", "Kurask", null, 6));
		HistoryFilter.LocationChoices choices = HistoryFilter.locationChoices(records, TABLE, NAMES);
		String named = HistoryFilter.NAME_PREFIX + "no location";
		assertEquals(Arrays.asList(LedgerHistory.ALL, named, HistoryFilter.NO_LOCATION), choices.getOptions());
		assertEquals("both show the same", Arrays.asList(LedgerHistory.ALL, "No location", "No location"),
			Arrays.asList(choices.label(LedgerHistory.ALL), choices.label(named),
				choices.label(HistoryFilter.NO_LOCATION)));
		assertEquals(Arrays.asList("named", "respelled"), filter(null, named, null, records));
		assertEquals(Collections.singletonList("none"), filter(null, HistoryFilter.NO_LOCATION, null, records));
	}

	@Test
	public void aRegionNamedLaterRenamesItsChoiceButKeepsIt()
	{
		Map<Integer, String> names = new HashMap<>();
		List<LedgerRecord> records = history();
		HistoryFilter.LocationChoices before = HistoryFilter.locationChoices(records, TABLE, names::get);
		assertEquals("Region 12342", before.label(UNLISTED_KEY));
		names.put(UNLISTED, "Edgeville");
		HistoryFilter.LocationChoices after = HistoryFilter.locationChoices(records, TABLE, names::get);
		assertEquals("Edgeville", after.label(UNLISTED_KEY));
		assertEquals(UNLISTED_KEY, HistoryFilter.keepLocation(after.getOptions(), UNLISTED_KEY));
		assertEquals(Collections.singletonList("e"),
			ids(new HistoryFilter(null, UNLISTED_KEY, null).apply(records, TABLE, names::get)));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeSet;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Saved tasks valued for the history: the price mode at saved prices, and re-pricing at today's GE prices,
 * which is what the sidebar always shows.
 */
public class HistoryPricingTest
{
	private static final int RUNE = 1;
	private static final int NO_GE = 3;
	private static final int POTION = 4;
	private static final int KEY = 23083;

	private static Map<Integer, Long> prices(long... idPrice)
	{
		Map<Integer, Long> map = new HashMap<>();
		for (int i = 0; i < idPrice.length; i += 2)
		{
			map.put((int) idPrice[i], idPrice[i + 1]);
		}
		return map;
	}

	/** The loot value as Task history shows it: the Loot received sub-header of a task's details. */
	private static String loot(HistoryPricing.Values v)
	{
		return LedgerFormat.amount(v.getLootValue(), v.isLootApproximate());
	}

	/** The supplies value as Task history shows it: the Supplies used sub-header of a task's details. */
	private static String supplies(HistoryPricing.Values v)
	{
		return LedgerFormat.amount(v.getSuppliesGe(), v.isSuppliesApproximate());
	}

	/** The profit as a Task history row shows it, signed. */
	private static String profit(HistoryPricing.Values v)
	{
		return LedgerFormat.signed(v.getProfit(), v.isProfitApproximate());
	}

	/** {@code r}'s Task history row tooltip at {@code v}, without a location or an end time. */
	private static String tooltip(LedgerRecord r, HistoryPricing.Values v)
	{
		return LedgerHistory.historyRowTooltip(r, v, null, LedgerHistory.NO_VALUE);
	}

	/**
	 * Loot: 2 runes (GE 100, HA 60) and an item without a GE price (HA 300). Supplies: 3 doses of a 4-dose potion
	 * (GE 800, HA 100). Totals as {@link LedgerRecord#captureValues} saves them.
	 */
	private static LedgerRecord record()
	{
		LedgerRecord r = new LedgerRecord();
		r.setId("a");
		r.setMonster("Kurask");
		r.setLoot(prices(RUNE, 2, NO_GE, 1));
		r.setSupplies(prices(POTION, 3));
		r.setSupplyDoses(Collections.singletonMap(POTION, 4));
		r.setUnitGePrices(prices(RUNE, 100, POTION, 800));
		r.setUnitHaPrices(prices(RUNE, 60, NO_GE, 300, POTION, 100));
		r.setLootGeValue(200L);
		r.setLootHaValue(420L);
		r.setSuppliesGeValue(600L);
		r.setSuppliesHaValue(75L);
		r.setLootUnpricedItems(1);
		return r;
	}

	@Test
	public void geAtSavedPricesUsesTheSavedTotals()
	{
		HistoryPricing.Values v = HistoryPricing.value(record(), LootPriceMode.GE, null);
		assertTrue(v.isValued());
		assertFalse(v.isCurrentPrices());
		assertEquals(Long.valueOf(200), v.getLootValue());
		assertTrue("one loot item had no GE price", v.isLootApproximate());
		assertEquals(Long.valueOf(600), v.getSuppliesGe());
		assertFalse(v.isSuppliesApproximate());
		assertEquals(Long.valueOf(-400), v.getProfit());
		assertTrue(v.isProfitApproximate());
	}

	@Test
	public void highAlchUsesTheSavedHighAlchTotal()
	{
		HistoryPricing.Values v = HistoryPricing.value(record(), LootPriceMode.HIGH_ALCH, null);
		assertEquals(Long.valueOf(420), v.getLootValue());
		assertEquals("every loot item has a high alch value", 0, v.getLootUnpriced());
		assertFalse(v.isLootApproximate());
		assertEquals("supplies stay at GE", Long.valueOf(600), v.getSuppliesGe());
		assertEquals(Long.valueOf(-180), v.getProfit());
	}

	@Test
	public void recordWithoutUnitPricesUsesItsTotals()
	{
		LedgerRecord r = record();
		r.setUnitGePrices(null);
		r.setUnitHaPrices(null);
		r.setLootUnpricedItems(null);
		HistoryPricing.Values ge = HistoryPricing.value(r, LootPriceMode.GE, null);
		assertEquals(Long.valueOf(200), ge.getLootValue());
		assertFalse("the saved GE total is exact", ge.isLootApproximate());
		HistoryPricing.Values ha = HistoryPricing.value(r, LootPriceMode.HIGH_ALCH, null);
		assertEquals(Long.valueOf(420), ha.getLootValue());
		assertTrue("no high alch unit values: its loot items are unpriced, so ~", ha.isLootApproximate());
	}

	@Test
	public void emptyLootIsZeroInEveryMode()
	{
		LedgerRecord r = record();
		r.setLoot(Collections.emptyMap());
		r.setLootGeValue(0L);
		r.setLootHaValue(0L);
		r.setLootUnpricedItems(null);
		for (LootPriceMode mode : LootPriceMode.values())
		{
			HistoryPricing.Values v = HistoryPricing.value(r, mode, prices());
			assertEquals(mode.name(), Long.valueOf(0), v.getLootValue());
			assertFalse(mode.name(), v.isLootApproximate());
		}
	}

	@Test
	public void recordSavedBeforeValuesHasNoneInAnyModeOrPrices()
	{
		LedgerRecord old = new LedgerRecord();
		old.setMonster("Kurask");
		old.setLoot(prices(RUNE, 2));
		for (LootPriceMode mode : LootPriceMode.values())
		{
			for (Map<Integer, Long> current : Arrays.asList(null, prices(RUNE, 100)))
			{
				HistoryPricing.Values v = HistoryPricing.value(old, mode, current);
				assertFalse(v.isValued());
				assertNull(v.getLootValue());
				assertNull(v.getSuppliesGe());
				assertNull(v.getProfit());
				assertEquals("-", loot(v));
				assertEquals("-", profit(v));
			}
		}
	}

	@Test
	public void todaysPricesRepriceLootAndSuppliesAtGe()
	{
		LedgerRecord r = record();
		LedgerRecord saved = record();
		Map<Integer, Long> today = prices(RUNE, 150, NO_GE, 500, POTION, 1_000);
		HistoryPricing.Values v = HistoryPricing.value(r, LootPriceMode.GE, today);
		assertTrue(v.isCurrentPrices());
		assertEquals(Long.valueOf(800), v.getLootValue());
