		assertFalse(ge.isLootApproximate());
	}

	@Test
	public void todaysGePriceOfZeroCountsAtHighAlch()
	{
		Map<Integer, Long> today = prices(KEY, 0, RUNE, 150, POTION, 1_000);
		HistoryPricing.Values ge = HistoryPricing.value(keyRecord(), LootPriceMode.GE, today);
		assertTrue(ge.isCurrentPrices());
		assertEquals("keys at the saved high alch, the rune at today's GE", Long.valueOf(336_150), ge.getLootValue());
		assertEquals(Long.valueOf(336_150), ge.getLootGe());
		assertEquals(0, ge.getLootUnpriced());
		assertEquals("supplies at today's GE, unchanged by the rule", Long.valueOf(1_000), ge.getSuppliesGe());

		// Today's price of the keys not available: unpriced, as before.
		today.remove(KEY);
		HistoryPricing.Values missing = HistoryPricing.value(keyRecord(), LootPriceMode.GE, today);
		assertEquals(Long.valueOf(150), missing.getLootValue());
		assertEquals(1, missing.getLootUnpriced());
	}

	@Test
	public void itemIdsAreTheDistinctLootAndSupplyIds()
	{
		LedgerRecord other = new LedgerRecord();
		other.setLoot(prices(RUNE, 1, 7, 1));
		assertEquals(new TreeSet<>(Arrays.asList(RUNE, NO_GE, POTION, 7)),
			HistoryPricing.itemIds(Arrays.asList(record(), other, null, new LedgerRecord())));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Parsing and matching of the "Ignored loot" setting: ids, case-insensitive names, {@code *} wildcards and noted items.
 */
public class IgnoredLootTest
{
	@Test
	public void emptySettingsIgnoreNothing()
	{
		assertSame(IgnoredLoot.NONE, IgnoredLoot.parse(null));
		assertSame(IgnoredLoot.NONE, IgnoredLoot.parse(""));
		assertSame(IgnoredLoot.NONE, IgnoredLoot.parse("  "));
		assertSame(IgnoredLoot.NONE, IgnoredLoot.parse(" , ,,"));
		assertTrue(IgnoredLoot.NONE.isEmpty());
		assertFalse(IgnoredLoot.NONE.ignores(ItemID.BONES, ItemID.BONES, "Bones"));
	}

	@Test
	public void namesMatchWholeNamesCaseInsensitively()
	{
		IgnoredLoot ignored = IgnoredLoot.parse(" bones ,Coins");
		assertFalse(ignored.isEmpty());
		assertTrue(ignored.hasNames());
		assertTrue(ignored.ignores(ItemID.BONES, ItemID.BONES, "Bones"));
		assertTrue(ignored.ignores(ItemID.COINS, ItemID.COINS, "COINS"));
		assertFalse("not a substring match", ignored.ignores(ItemID.BIG_BONES, ItemID.BIG_BONES, "Big bones"));
		assertFalse("an unknown name matches no name entry", ignored.ignores(ItemID.BONES, ItemID.BONES, null));
	}

	@Test
	public void wildcardsMatchAnyRunOfCharacters()
	{
		IgnoredLoot ignored = IgnoredLoot.parse("*seed, Rune *, *bones*");
		assertTrue(ignored.ignores(5295, 5295, "Ranarr seed"));
		assertTrue(ignored.ignores(1, 1, "Rune full helm"));
		assertTrue(ignored.ignores(ItemID.BIG_BONES, ItemID.BIG_BONES, "Big bones"));
		assertTrue(ignored.ignores(ItemID.BONES, ItemID.BONES, "Bones"));
		assertFalse(ignored.ignores(2, 2, "Seed box"));
		assertFalse(ignored.ignores(3, 3, "Adamant full helm"));
	}

	@Test
	public void regexCharactersInNamesAreLiteral()
	{
		IgnoredLoot ignored = IgnoredLoot.parse("Prayer potion(4), Amulet of glory(?)");
		assertTrue(ignored.ignores(2434, 2434, "Prayer potion(4)"));
		assertFalse(ignored.ignores(139, 139, "Prayer potion(3)"));
		assertFalse(ignored.ignores(1712, 1712, "Amulet of glory(4)"));
	}

	@Test
	public void numbersAreItemIds()
	{
		IgnoredLoot ignored = IgnoredLoot.parse("526");
		assertFalse("ids need no name lookup", ignored.hasNames());
		assertTrue(ignored.ignores(ItemID.BONES, ItemID.BONES, null));
		assertFalse(ignored.ignores(ItemID.BIG_BONES, ItemID.BIG_BONES, "526"));

		IgnoredLoot tooLarge = IgnoredLoot.parse("99999999999");
		assertTrue("too large for an id: only a name could match", tooLarge.hasNames());
		assertFalse(tooLarge.ignores(ItemID.BONES, ItemID.BONES, "Bones"));
	}

	@Test
	public void notedDropsMatchTheirUnnotedItem()
	{
		IgnoredLoot byId = IgnoredLoot.parse(Integer.toString(ItemID.DRAGON_BONES));
		assertTrue(byId.ignores(ItemID.Cert.DRAGON_BONES, ItemID.DRAGON_BONES, "Dragon bones"));
		IgnoredLoot byNotedId = IgnoredLoot.parse(Integer.toString(ItemID.Cert.DRAGON_BONES));
		assertTrue("the noted id itself also matches",
			byNotedId.ignores(ItemID.Cert.DRAGON_BONES, ItemID.DRAGON_BONES, "Dragon bones"));
		assertFalse("but not the unnoted drop", byNotedId.ignores(ItemID.DRAGON_BONES, ItemID.DRAGON_BONES, "Dragon bones"));
		IgnoredLoot byName = IgnoredLoot.parse("dragon bones");
		assertTrue(byName.ignores(ItemID.Cert.DRAGON_BONES, ItemID.DRAGON_BONES, "Dragon bones"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class ItemDetailsTest
{
	private static final int SHARK = ItemID.SHARK;
	private static final int PRAYER_POTION_4 = ItemID._4DOSEPRAYERRESTORE;
	private static final int PRAYER_POTION_3 = ItemID._3DOSEPRAYERRESTORE;
	private static final int SUPER_RESTORE_4 = ItemID._4DOSE2RESTORE;
	private static final int WHIP = ItemID.ABYSSAL_WHIP;
	private static final int RUNE_PLATEBODY = ItemID.RUNE_PLATEBODY;
	private static final int COINS = ItemID.COINS;
	/** An untradeable drop: GE 0, valued at high alch. */
	private static final int KEY = ItemID.KONAR_KEY;
	private static final int UNPRICED = 99_999;

	private static final Map<Integer, String> NAMES = new HashMap<>();

	static
	{
		NAMES.put(SHARK, "Shark");
		NAMES.put(PRAYER_POTION_4, "Prayer potion(4)");
		NAMES.put(PRAYER_POTION_3, "Prayer potion(3)");
		NAMES.put(SUPER_RESTORE_4, "Super restore(4)");
		NAMES.put(WHIP, "Abyssal whip");
		NAMES.put(RUNE_PLATEBODY, "Rune platebody");
		NAMES.put(COINS, "Coins");
		NAMES.put(KEY, "Brimstone key");
		NAMES.put(ItemID.ANCHOVIE_PIZZA, "Anchovy pizza");
		NAMES.put(ItemID.AMULET_OF_GLORY_6, "Amulet of glory(6)");
	}

	/** The nature rune's GE price in these tests. */
	private static final Long NATURE_RUNE = 100L;
	private static final ItemDetails.ItemNames LOOKUP = NAMES::get;

	private static ItemTally tally(long... idQuantity)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQuantity.length; i += 2)
		{
			t.add((int) idQuantity[i], idQuantity[i + 1]);
		}
		return t;
	}

	private static Map<Integer, Long> prices(long... idPrice)
	{
		Map<Integer, Long> m = new TreeMap<>();
		for (int i = 0; i < idPrice.length; i += 2)
		{
			m.put((int) idPrice[i], idPrice[i + 1]);
		}
		return m;
	}

	/** Each row as "name | quantity | value", with " | (alch)" when the hint is shown. */
	private static List<String> texts(List<ItemDetails.Row> rows)
	{
		return rows.stream()
			.map(r -> r.getName() + " | " + r.quantityText() + " | " + r.valueText()
				+ (r.isAlchHint() ? " | " + ItemDetails.ALCH_MARKER : ""))
			.collect(Collectors.toList());
	}

	@Test
	public void suppliesAreSortedByValueWithPotionsInDoses()
	{
		ItemDetails details = ItemDetails.of(new ItemTally(), tally(SHARK, 14, PRAYER_POTION_4, 22),
			Collections.singletonMap(PRAYER_POTION_4, 4), prices(SHARK, 1_000, PRAYER_POTION_4, 8_000),
			prices(SHARK, 50, PRAYER_POTION_4, 100));

		// 22 doses at 8,000 per 4 doses = 44,000; 14 sharks = 14,000.
		assertEquals(Arrays.asList("Prayer potion | 22 doses | 44K", "Shark | x14 | 14K"),
			texts(details.supplyRows(LOOKUP)));
	}

	@Test
	public void rowValuesAddUpToTheTotalsWithDoseRounding()
	{
		ItemTally supplies = tally(SHARK, 3, PRAYER_POTION_4, 7);
		Map<Integer, Integer> doses = Collections.singletonMap(PRAYER_POTION_4, 4);
		Map<Integer, Long> ge = prices(SHARK, 999, PRAYER_POTION_4, 8_003);
		long sum = 0;
		for (ItemDetails.Row row : ItemDetails.of(null, supplies, doses, ge, null).supplyRows(LOOKUP))
		{
			sum += row.getValue();
		}
		assertEquals(ItemValuation.total(supplies, ge, doses), sum);
	}

	@Test
	public void bitesAndChargesHaveTheirOwnWords()
	{
