		assertEquals("2026-01-02 23:30", LedgerHistory.formatEndedAt(r, pattern.withZone(ZoneId.of("UTC"))));
		assertEquals("2026-01-03 08:30", LedgerHistory.formatEndedAt(r, pattern.withZone(ZoneId.of("Asia/Tokyo"))));
