package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * The ledger file's optional {@code assignments} list ({@link AssignmentEntry}): old files load unchanged, every
 * rewrite keeps the entries, entries never come back as records, and the bound and the record check apply.
 */
public class LedgerStoreAssignmentsTest
{
	private static final long ACCOUNT = 123456789L;

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private File dir;
	private LedgerStore store;

	@Before
	public void setUp()
	{
		dir = new File(temp.getRoot(), "slayer-ledger");
		store = new LedgerStore(Filepath.Unchecked.getRooted(dir.toPath()), new Gson());
	}

	private static LedgerRecord record(String id, int creatureId, boolean completed, long endedAt)
	{
		LedgerRecord r = new LedgerRecord();
		r.setId(id);
		r.setMonster("Task " + creatureId);
		r.setCreatureId(creatureId);
		r.setOriginalAmount(120);
		r.setCompleted(completed);
		r.setPartial(!completed);
		r.setEndedAt(endedAt);
		return r;
	}

	private String json() throws IOException
	{
		return new String(Files.readAllBytes(new File(dir, ACCOUNT + ".json").toPath()), StandardCharsets.UTF_8);
	}

	private void writeJson(String json) throws IOException
	{
		dir.mkdirs();
		Files.write(new File(dir, ACCOUNT + ".json").toPath(), json.getBytes(StandardCharsets.UTF_8));
	}

	@Test
	public void anOldFileLoadsWithNoEntriesAndIsRewrittenWithoutTheField() throws IOException
	{
		writeJson("{\"schemaVersion\":2,\"records\":[{\"id\":\"r1\",\"monster\":\"Kraken\",\"creatureId\":42,"
			+ "\"kills\":3,\"endedAt\":1000,\"completed\":true}]}");
		LedgerStore.Contents contents = store.loadContents(ACCOUNT);
		assertEquals(1, contents.getRecords().size());
		assertTrue(contents.getAssignments().isEmpty());

		store.append(ACCOUNT, record("r2", 46, false, 2_000L));
		assertFalse(json(), json().contains("assignments"));
		assertEquals(2, store.load(ACCOUNT).size());
	}

	@Test
	public void entriesAreStoredBesideTheRecordsAndNeverLoadAsRecords() throws IOException
	{
		store.append(ACCOUNT, record("r1", 42, true, 1_000L));
		List<AssignmentEntry> entries = store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e1", 2_000L), false);
		assertEquals(1, entries.size());
		assertEquals(1, store.load(ACCOUNT).size());
		LedgerStore.Contents contents = store.loadContents(ACCOUNT);
		assertEquals(1, contents.getRecords().size());
		assertEquals(entries, contents.getAssignments());
		assertEquals(AssignmentOutcome.SKIPPED, contents.getAssignments().get(0).getOutcome());
		assertTrue(json(), json().contains("\"outcome\":\"SKIPPED\""));
	}

	@Test
	public void appendingAnEntryWithoutAFileCreatesIt() throws IOException
	{
		store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e1", 2_000L), false);
		LedgerStore.Contents contents = store.loadContents(ACCOUNT);
		assertTrue(contents.getRecords().isEmpty());
		assertEquals(1, contents.getAssignments().size());
	}

	@Test
	public void everyRecordRewriteKeepsTheEntries() throws IOException
	{
		store.append(ACCOUNT, record("r1", 42, true, 1_000L));
		store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e1", 2_000L), false);

		store.append(ACCOUNT, record("r2", 46, true, 3_000L));
		assertEquals(1, store.loadContents(ACCOUNT).getAssignments().size());
		store.updateNote(ACCOUNT, "r2", "note");
		assertEquals(1, store.loadContents(ACCOUNT).getAssignments().size());
		store.delete(ACCOUNT, "r1");
		assertEquals(1, store.loadContents(ACCOUNT).getAssignments().size());
		assertEquals(1, store.load(ACCOUNT).size());
	}

	@Test
	public void deleteAssignmentRemovesOnlyThatEntry() throws IOException
	{
		store.append(ACCOUNT, record("r1", 42, true, 1_000L));
		store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e1", 2_000L), false);
		store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e2", 3_000L), false);

		List<AssignmentEntry> left = store.deleteAssignment(ACCOUNT, "e1");
		assertEquals(1, left.size());
		assertEquals("e2", left.get(0).getId());
		assertEquals(1, store.load(ACCOUNT).size());
		assertEquals("unknown id: nothing changes", 1, store.deleteAssignment(ACCOUNT, "nope").size());

		store.deleteAssignment(ACCOUNT, "e2");
		assertFalse("the last one gone: no empty list written", json().contains("assignments"));
	}

	@Test
	public void theNewestEntriesAreKept() throws IOException
	{
		for (int i = 0; i <= AssignmentLog.MAX_ENTRIES; i++)
		{
			store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e" + i, 1_000L + i), false);
		}
		List<AssignmentEntry> entries = store.loadContents(ACCOUNT).getAssignments();
		assertEquals(AssignmentLog.MAX_ENTRIES, entries.size());
		assertEquals("e1", entries.get(0).getId());
	}

	@Test
	public void anEntryLookingPlayedInAnEarlierRunIsSkippedWhenChecked() throws IOException
	{
		// The newest record is a partial session of the same task.
		store.append(ACCOUNT, record("r1", 42, false, 1_000L));
		assertTrue(store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e1", 2_000L), true).isEmpty());
		assertEquals("unchecked: stored", 1,
			store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e2", 2_000L), false).size());
	}

	@Test
	public void aNewerSchemaFileIsNeverOverwritten() throws IOException
	{
		writeJson("{\"schemaVersion\":99,\"records\":[]}");
		try
		{
			store.appendAssignment(ACCOUNT, AssignmentLogTest.entry("e1", 2_000L), false);
			fail();
		}
		catch (LedgerStore.UnsupportedSchemaException expected)
		{
			// The file is left alone.
		}
		try
		{
			store.deleteAssignment(ACCOUNT, "e1");
			fail();
		}
		catch (LedgerStore.UnsupportedSchemaException expected)
		{
			// Likewise.
		}
		assertEquals("{\"schemaVersion\":99,\"records\":[]}", json());
	}

	@Test
	public void anUnknownOutcomeFromANewerBuildReadsAsNull() throws IOException
	{
		writeJson("{\"schemaVersion\":2,\"records\":[],\"assignments\":[{\"id\":\"e1\",\"outcome\":\"SWAPPED\","
			+ "\"endedAt\":5}]}");
		AssignmentEntry e = store.loadContents(ACCOUNT).getAssignments().get(0);
		assertEquals(null, e.getOutcome());
		assertEquals(AssignmentOutcome.UNKNOWN, AssignmentOutcome.orUnknown(e.getOutcome()));
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.client.util.Filepath;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * The 2.0 record fields in {@link LedgerStore}: they round-trip through save and load, the player's setup
 * overrides on saved records ({@link LedgerStore#updateSetup}) win over the detected tags and survive a reload, and the
 * schema bump keeps the policy (a newer file is refused, unknown members survive a migration and every rewrite).
 */
public class LedgerStoreSetupTest
{
	private static final long ACCOUNT = 123456789L;

	/** A 2.0 record with every field this issue adds set, as {@link LedgerStore} writes it (after the 1.x fields). */
	private static final String FULL_RECORD_JSON = "{\"schemaVersion\":3,\"id\":\"r1\",\"monster\":\"Dust devils\","
		+ "\"initialAmount\":10,\"kills\":10,\"activeMillis\":600000,\"startedAt\":1000,\"endedAt\":601000,"
		+ "\"completed\":true,\"partial\":false,\"superiorsSpawned\":0,\"bankTrips\":0,\"deaths\":0,\"xpGained\":{},"
		+ "\"locationRegion\":6556,\"spotId\":\"catacombs\",\"bossKills\":false,"
		+ "\"npcKills\":[{\"name\":\"Dust devil\",\"kills\":10},{\"name\":\"Ankou\",\"kills\":1}],"
		+ "\"cannonKills\":2,\"styleKills\":{\"BARRAGE\":2,\"MAGIC\":1},\"gearKills\":{\"MIXED\":1,\"PRAYER\":2},"
		+ "\"prayerBonusMin\":14,\"prayerBonusMax\":31,\"detectedCannon\":false,\"detectedStyle\":\"BARRAGE\","
		+ "\"detectedGear\":\"PRAYER\",\"gearOverride\":\"STRENGTH\"}";

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private final Gson gson = new Gson();
	private File dir;
	private LedgerStore store;

	@Before
	public void setUp()
	{
		dir = new File(temp.getRoot(), "slayer-ledger");
		store = newStore();
	}

	private LedgerStore newStore()
	{
		return new LedgerStore(Filepath.Unchecked.getRooted(dir.toPath()), gson);
	}

	private File ledgerFile()
	{
		return new File(dir, ACCOUNT + ".json");
	}

	private String ledgerText() throws IOException
	{
		return new String(Files.readAllBytes(ledgerFile().toPath()), StandardCharsets.UTF_8);
	}

	private void writeLedger(String json) throws IOException
	{
		assertTrue(dir.isDirectory() || dir.mkdirs());
		Files.write(ledgerFile().toPath(), json.getBytes(StandardCharsets.UTF_8));
	}

	/** A 2.0 record of a finished session with kills by NPC, kill contexts, detected tags and an override. */
	private static LedgerRecord fullRecord()
	{
		final SetupKills kills = SetupKills.NONE
			.withKill(true, SetupStyle.BARRAGE, GearFocus.PRAYER, 14)
			.withKill(true, SetupStyle.BARRAGE, GearFocus.PRAYER, 31)
			.withKill(false, SetupStyle.MAGIC, GearFocus.MIXED, 20);
		final SessionTracker.Summary summary = SessionTracker.Summary.builder()
			.sessionId("r1")
			.accountHash(ACCOUNT)
			.monster("Dust devils")
			.hasTask(true)
			.initialAmount(10)
			.kills(10)
			.activeMillis(600_000)
			.startedAt(1_000)
			.endedAt(601_000)
			.completed(true)
			.npcKills(Arrays.asList(new NpcKills("Dust devil", 10), new NpcKills("Ankou", 1)))
			.setupKills(kills)
			.setupOverrides(SetupOverrides.of(null, null, GearFocus.STRENGTH))
			.build();
		return LedgerRecord.fromSummary(summary, false);
	}

	@Test
	public void everyNewFieldRoundTripsThroughSaveAndLoad() throws IOException
	{
		final LedgerRecord record = fullRecord();
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, record.getSchemaVersion());
		assertEquals(Arrays.asList(new NpcKills("Dust devil", 10), new NpcKills("Ankou", 1)), record.getNpcKills());
		assertEquals(Integer.valueOf(2), record.getCannonKills());
		assertEquals(Integer.valueOf(14), record.getPrayerBonusMin());
		assertEquals(Integer.valueOf(31), record.getPrayerBonusMax());
		assertEquals("2 cannon kills of 10 is no cannon task", Boolean.FALSE, record.getDetectedCannon());
		assertEquals("2 of 3 styled kills", SetupStyle.BARRAGE, record.getDetectedStyle());
		assertEquals("the focus of most kills", GearFocus.PRAYER, record.getDetectedGear());
		assertEquals(GearFocus.STRENGTH, record.getGearOverride());
		assertNull(record.getCannonEstimated());

		store.append(ACCOUNT, record);
		final LedgerRecord loaded = newStore().load(ACCOUNT).get(0);
		assertEquals(record, loaded);

		// Every field, as written and read back (the spot as phase 6 will fill it).
		record.setSpotId("catacombs");
		record.setLocationRegion(6556);
		store.write(ACCOUNT, Collections.singletonList(record));
		assertEquals("{\"schemaVersion\":3,\"records\":[" + FULL_RECORD_JSON + "]}", ledgerText());
		assertEquals(record, newStore().load(ACCOUNT).get(0));
	}

	@Test
	public void overridesOnASavedRecordWinAndSurviveAReloadAndClearing() throws IOException
	{
		store.append(ACCOUNT, fullRecord());
		final SetupOverrides mine = SetupOverrides.of(true, SetupStyle.MELEE, null);
		assertEquals(1, store.updateSetup(ACCOUNT, "r1", mine).size());

		LedgerRecord loaded = newStore().load(ACCOUNT).get(0);
		SetupTags tags = SetupTags.of(loaded);
		assertEquals(mine, tags.getOverrides());
		assertTrue("the override wins", tags.isCannon());
		assertEquals(SetupStyle.MELEE, tags.getStyle());
		assertEquals("the gear override was cleared", GearFocus.PRAYER, tags.getGear());
		assertFalse("the detected values are kept", tags.isDetectedCannon());
		assertEquals(SetupStyle.BARRAGE, tags.getDetectedStyle());
		assertEquals("only the overrides changed", fullRecord().getNpcKills(), loaded.getNpcKills());
		assertEquals(Integer.valueOf(2), loaded.getCannonKills());

		final String before = ledgerText();
		store.updateSetup(ACCOUNT, "r1", mine);
		assertEquals("the same overrides don't rewrite the file", before, ledgerText());
		assertEquals("a missing record changes nothing", 1, store.updateSetup(ACCOUNT, "nope", SetupOverrides.NONE)
			.size());
		assertEquals(before, ledgerText());

		store.updateSetup(ACCOUNT, "r1", null);
		loaded = newStore().load(ACCOUNT).get(0);
		tags = SetupTags.of(loaded);
		assertEquals(SetupOverrides.NONE, tags.getOverrides());
		assertFalse("back to the detected cannon", tags.isCannon());
		assertFalse(ledgerText().contains("Override"));
	}

	@Test
	public void anOverrideOfAMigratedTagIsNoLongerAnEstimate() throws IOException
	{
		writeLedger("{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"old\",\"monster\":\"Dust devils\","
			+ "\"kills\":100,\"xpGained\":{\"MAGIC\":60000}}]}");
		assertTrue(SetupTags.of(store.load(ACCOUNT).get(0)).isStyleEstimated());

		store.updateSetup(ACCOUNT, "old", SetupOverrides.NONE.withStyle(SetupStyle.BARRAGE));
		final SetupTags tags = SetupTags.of(newStore().load(ACCOUNT).get(0));
		assertEquals(SetupStyle.BARRAGE, tags.getStyle());
		assertFalse("the player confirmed it", tags.isStyleEstimated());
		assertTrue("the cannon is still an estimate", tags.isCannonEstimated());
		assertTrue("the detected style still is one", tags.isDetectedStyleEstimated());
	}

	@Test
	public void aNewerFileIsRefusedForASetupEditAndLeftAlone() throws IOException
	{
		final String newer = "{\"schemaVersion\":" + (LedgerStore.FILE_SCHEMA_VERSION + 1) + ",\"records\":[{\"id\":"
			+ "\"future\",\"monster\":\"Hydras\",\"kills\":9,\"detectedStyle\":\"CHINCHOMPA\"}]}";
		writeLedger(newer);
		try
		{
			store.updateSetup(ACCOUNT, "future", SetupOverrides.of(true, null, null));
			fail("expected UnsupportedSchemaException");
		}
		catch (LedgerStore.UnsupportedSchemaException expected)
		{
			// expected
		}
		try
		{
			store.append(ACCOUNT, fullRecord());
			fail("expected UnsupportedSchemaException");
		}
		catch (LedgerStore.UnsupportedSchemaException expected)
		{
			// expected
		}
		assertEquals(newer, ledgerText());
		// Still read on a best-effort basis: a style this build doesn't know reads as Unknown.
		final LedgerRecord future = store.load(ACCOUNT).get(0);
		assertEquals("Hydras", future.getMonster());
		assertEquals(SetupStyle.UNKNOWN, SetupTags.of(future).getStyle());
	}

	@Test
	public void unknownMembersSurviveTheMigrationAndEveryRewrite() throws IOException
	{
		writeLedger("{\"schemaVersion\":2,\"records\":[{\"schemaVersion\":2,\"id\":\"old\",\"monster\":\"Kurask\","
			+ "\"kills\":50,\"xpGained\":{\"ATTACK\":9000},\"futureRecordField\":[1,2]}],\"futureTopField\":true}");
		final JsonElement recordField = gson.fromJson("[1,2]", JsonElement.class);

		store.updateSetup(ACCOUNT, "old", SetupOverrides.NONE.withGear(GearFocus.PRAYER));
		JsonObject file = gson.fromJson(ledgerText(), JsonObject.class);
		JsonObject old = file.getAsJsonArray("records").get(0).getAsJsonObject();
		assertEquals(LedgerStore.FILE_SCHEMA_VERSION, file.get("schemaVersion").getAsInt());
		assertEquals(3, old.get("schemaVersion").getAsInt());
		assertEquals("MELEE", old.get("detectedStyle").getAsString());
		assertEquals("PRAYER", old.get("gearOverride").getAsString());
		assertEquals(recordField, old.get("futureRecordField"));
		assertTrue(file.get("futureTopField").getAsBoolean());

		// A later build's unknown style value is kept as it was, beside a known override.
		final String withFutureStyle = ledgerText().replace("\"detectedStyle\":\"MELEE\"",
			"\"detectedStyle\":\"CHINCHOMPA\"");
		writeLedger(withFutureStyle);
		assertEquals("unknown style values read as Unknown", SetupStyle.UNKNOWN,
			SetupTags.of(store.load(ACCOUNT).get(0)).getStyle());
		store.updateNote(ACCOUNT, "old", "Leaf-bladed");
		old = gson.fromJson(ledgerText(), JsonObject.class).getAsJsonArray("records").get(0).getAsJsonObject();
		assertEquals("CHINCHOMPA", old.get("detectedStyle").getAsString());
		assertEquals(recordField, old.get("futureRecordField"));
		assertEquals("Leaf-bladed", old.get("note").getAsString());
	}

	@Test
	public void keptSideFilesAreWrittenAtTheNewVersion() throws IOException
	{
		assertTrue(store.writeUnsaved(ACCOUNT, fullRecord()));
		final File kept = new File(dir, ACCOUNT + ".unsaved-r1.json");
		final JsonObject json = gson.fromJson(new String(Files.readAllBytes(kept.toPath()), StandardCharsets.UTF_8),
			JsonObject.class);
		assertEquals(LedgerStore.FILE_SCHEMA_VERSION, json.get("schemaVersion").getAsInt());
		final List<LedgerRecord> saved = store.appendUnsaved(ACCOUNT);
		assertEquals(Collections.singletonList(fullRecord()), saved);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystems;
import java.nio.file.Files;
import java.nio.file.attribute.PosixFilePermission;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

public class LedgerStoreTest
{
	private static final long ACCOUNT_A = 123456789L;
	private static final long ACCOUNT_B = -987654321L;

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private File dir;
	private LedgerStore store;

	@Before
	public void setUp()
	{
		dir = new File(temp.getRoot(), "slayer-ledger");
		store = newStore();
	}

	/** A store over {@code dir}, as after a client restart. */
	private LedgerStore newStore()
	{
		return new LedgerStore(Filepath.Unchecked.getRooted(dir.toPath()), new Gson());
	}

	private static LedgerRecord record(String monster, int kills, boolean completed)
	{
		LedgerRecord r = new LedgerRecord();
		r.setId(monster + "-" + kills);
		r.setMonster(monster);
		r.setCreatureId(7);
		r.setInitialAmount(100);
		r.setKills(kills);
		r.setActiveMillis(60_000L);
		r.setStartedAt(1_000L);
		r.setEndedAt(61_000L);
		r.setCompleted(completed);
		r.setPartial(!completed);
		return r;
	}

	@Test
	public void missingFileLoadsEmpty() throws IOException
	{
		assertTrue(store.load(ACCOUNT_A).isEmpty());
	}

	@Test
	public void roundTrip() throws IOException
	{
		LedgerRecord a = record("Abyssal demons", 100, true);
		LedgerRecord b = record("Black dragons", 12, false);
		b.setCreatureId(null);
		store.write(ACCOUNT_A, Arrays.asList(a, b));

		List<LedgerRecord> loaded = newStore().load(ACCOUNT_A);
		assertEquals(Arrays.asList(a, b), loaded);
		assertNull(loaded.get(1).getCreatureId());
		assertTrue(loaded.get(1).isPartial());
	}

	@Test
	public void appendAddsToExisting() throws IOException
	{
		store.append(ACCOUNT_A, record("Abyssal demons", 100, true));
		List<LedgerRecord> after = store.append(ACCOUNT_A, record("Gargoyles", 5, false));
		assertEquals(2, after.size());
		assertEquals(after, store.load(ACCOUNT_A));
	}

	@Test
	public void accountsAreSeparated() throws IOException
	{
		store.append(ACCOUNT_A, record("Abyssal demons", 100, true));
		store.append(ACCOUNT_B, record("Hellhounds", 40, true));
		store.append(ACCOUNT_B, record("Kurask", 3, false));

		assertEquals(1, store.load(ACCOUNT_A).size());
		assertEquals("Abyssal demons", store.load(ACCOUNT_A).get(0).getMonster());
		assertEquals(2, store.load(ACCOUNT_B).size());
		assertTrue(new File(dir, ACCOUNT_A + ".json").isFile());
		assertTrue(new File(dir, ACCOUNT_B + ".json").isFile());
	}

	@Test
	public void atomicWriteLeavesNoTempFilesAndReplacesContent() throws IOException
	{
		store.write(ACCOUNT_A, Collections.singletonList(record("Abyssal demons", 100, true)));
		store.write(ACCOUNT_A, Collections.singletonList(record("Gargoyles", 5, false)));

		String[] names = dir.list();
		assertEquals(Collections.singletonList(ACCOUNT_A + ".json"), Arrays.asList(names));
		List<LedgerRecord> loaded = store.load(ACCOUNT_A);
		assertEquals(1, loaded.size());
		assertEquals("Gargoyles", loaded.get(0).getMonster());

		String json = new String(Files.readAllBytes(new File(dir, ACCOUNT_A + ".json").toPath()), StandardCharsets.UTF_8);
		assertTrue(json.contains("\"schemaVersion\":" + LedgerStore.FILE_SCHEMA_VERSION));
	}

	@Test
	public void corruptFileIsPreservedOnAppend() throws IOException
	{
		assertTrue(dir.mkdirs());
		File file = new File(dir, ACCOUNT_A + ".json");
		Files.write(file.toPath(), "{not json".getBytes(StandardCharsets.UTF_8));

		try
		{
			store.load(ACCOUNT_A);
			throw new AssertionError("expected IOException");
		}
		catch (IOException expected)
		{
			// expected
		}

		List<LedgerRecord> records = store.append(ACCOUNT_A, record("Abyssal demons", 1, false));
		assertEquals(1, records.size());
		String[] names = dir.list();
		assertEquals(2, names.length);
		assertTrue(Arrays.stream(names).anyMatch(n -> n.startsWith(ACCOUNT_A + ".json.corrupt-")));
	}

	@Test
	public void unknownFieldsAreIgnored() throws IOException
	{
		assertTrue(dir.mkdirs());
		String json = "{\"schemaVersion\":3,\"records\":[{\"schemaVersion\":3,\"id\":\"x\",\"monster\":\"Aberrant spectres\","
			+ "\"kills\":4,\"futureField\":[{\"itemId\":1}]}]}";
		Files.write(new File(dir, ACCOUNT_A + ".json").toPath(), json.getBytes(StandardCharsets.UTF_8));
		List<LedgerRecord> loaded = store.load(ACCOUNT_A);
		assertEquals(1, loaded.size());
		assertEquals("Aberrant spectres", loaded.get(0).getMonster());
		assertEquals(4, loaded.get(0).getKills());
	}

	@Test
	public void newerSchemaIsNeverOverwritten() throws IOException
	{
		assertTrue(dir.mkdirs());
		File file = new File(dir, ACCOUNT_A + ".json");
		String json = "{\"schemaVersion\":99,\"records\":[{\"id\":\"future\",\"monster\":\"Hydras\",\"kills\":9}]}";
		Files.write(file.toPath(), json.getBytes(StandardCharsets.UTF_8));

		try
		{
			store.append(ACCOUNT_A, record("Abyssal demons", 1, true));
			fail("expected UnsupportedSchemaException");
		}
		catch (LedgerStore.UnsupportedSchemaException expected)
		{
			// expected
		}
		try
		{
			store.delete(ACCOUNT_A, "future");
			fail("expected UnsupportedSchemaException");
		}
		catch (LedgerStore.UnsupportedSchemaException expected)
		{
			// expected
		}

		assertEquals(json, new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
		assertEquals(Collections.singletonList(ACCOUNT_A + ".json"), Arrays.asList(dir.list()));
	}

	@Test
	public void nonParseIoFailureDoesNotRenameFile() throws IOException
	{
		boolean supportsPosix = FileSystems.getDefault().supportedFileAttributeViews().contains("posix");
		File blocker = new File(dir, ACCOUNT_A + ".json");
		if (supportsPosix)
		{
			assertTrue(dir.mkdirs());
			Files.write(blocker.toPath(), "ledger".getBytes(StandardCharsets.UTF_8));
			Files.setPosixFilePermissions(blocker.toPath(), Collections.singleton(PosixFilePermission.OWNER_WRITE));
		}
		else
		{
			// On Windows, a directory cannot be opened as a reader.
			assertTrue(blocker.mkdirs());
		}

		try
		{
			store.append(ACCOUNT_A, record("Abyssal demons", 1, true));
			fail("expected IOException");
		}
		catch (LedgerStore.LedgerParseException e)
		{
			fail("not a parse error");
		}
		catch (IOException expected)
		{
			// expected
		}
		finally
		{
			if (supportsPosix)
			{
				Files.setPosixFilePermissions(blocker.toPath(),
					Collections.singleton(PosixFilePermission.OWNER_READ));
			}
		}

		if (supportsPosix)
		{
			assertTrue(blocker.isFile());
			assertEquals("ledger", new String(Files.readAllBytes(blocker.toPath()), StandardCharsets.UTF_8));
		}
		else
		{
			assertTrue(blocker.isDirectory());
		}
		assertEquals(Collections.singletonList(ACCOUNT_A + ".json"), Arrays.asList(dir.list()));
	}

	@Test
	public void deleteRemovesRecordById() throws IOException
	{
		LedgerRecord a = record("Abyssal demons", 100, true);
		LedgerRecord b = record("Gargoyles", 5, false);
		store.append(ACCOUNT_A, a);
		store.append(ACCOUNT_A, b);
		store.append(ACCOUNT_B, record("Gargoyles", 5, false));

		List<LedgerRecord> after = store.delete(ACCOUNT_A, b.getId());
		assertEquals(Collections.singletonList(a), after);
		assertEquals(Collections.singletonList(a), store.load(ACCOUNT_A));
		// other accounts are untouched, unknown ids are a no-op
		assertEquals(1, store.load(ACCOUNT_B).size());
		assertEquals(1, store.delete(ACCOUNT_A, "missing").size());
	}

	@Test
	public void deleteThenReloadFromFreshStore() throws IOException
	{
		LedgerRecord a = record("Abyssal demons", 100, true);
		LedgerRecord b = record("Gargoyles", 5, false);
		LedgerRecord c = record("Kurask", 7, false);
		store.append(ACCOUNT_A, a);
		store.append(ACCOUNT_A, b);
		store.append(ACCOUNT_A, c);

		store.delete(ACCOUNT_A, b.getId());
		// A new store (as after a client restart) reads the deletion from disk; order of the rest is kept.
		assertEquals(Arrays.asList(a, c), newStore().load(ACCOUNT_A));
		store.delete(ACCOUNT_A, a.getId());
		store.delete(ACCOUNT_A, c.getId());
		assertTrue(newStore().load(ACCOUNT_A).isEmpty());
		assertTrue(new File(dir, ACCOUNT_A + ".json").isFile());
	}

	@Test
	public void deleteLeavesActiveSessionFileUntouched() throws IOException
	{
		LedgerRecord a = record("Abyssal demons", 3, false);
		store.append(ACCOUNT_A, a);
		store.writeActive(ACCOUNT_A, snapshot("s1", 3));
		byte[] before = Files.readAllBytes(activeFile(ACCOUNT_A).toPath());

		store.delete(ACCOUNT_A, a.getId());
		// Even an id equal to the active session id only targets ledger records.
		store.delete(ACCOUNT_A, "s1");

		assertTrue(store.load(ACCOUNT_A).isEmpty());
		assertTrue(Arrays.equals(before, Files.readAllBytes(activeFile(ACCOUNT_A).toPath())));
		assertEquals("s1", store.readActive(ACCOUNT_A).getSessionId());
	}

	@Test
	public void deleteAlsoRemovesLeftoverActiveFileForSameSession() throws IOException
	{
		// Crash between appending the record and deleting the active file.
		LedgerRecord record = record("Abyssal demons", 3, false);
		record.setId("s1");
		store.append(ACCOUNT_A, record);
		store.writeActive(ACCOUNT_A, snapshot("s1", 3));
		store.writeActive(ACCOUNT_B, snapshot("s1", 3));

		assertTrue(store.delete(ACCOUNT_A, "s1").isEmpty());
		assertFalse(activeFile(ACCOUNT_A).exists());
		// the deleted task does not come back as a restored session
		assertNull(store.readActive(ACCOUNT_A));
		assertTrue(store.load(ACCOUNT_A).isEmpty());
		// other accounts' active files are untouched
		assertTrue(activeFile(ACCOUNT_B).exists());
	}

	@Test
	public void deleteKeepsActiveFileForOtherSession() throws IOException
	{
		LedgerRecord record = record("Abyssal demons", 3, false);
		record.setId("r1");
		store.append(ACCOUNT_A, record);
		store.writeActive(ACCOUNT_A, snapshot("s1", 3));

		store.delete(ACCOUNT_A, "r1");
		assertEquals("s1", store.readActive(ACCOUNT_A).getSessionId());
	}

	@Test
	public void deleteNeverRemovesUnreadableOrNewerActiveFile() throws IOException
	{
		assertTrue(dir.mkdirs());
		LedgerRecord record = record("Abyssal demons", 3, false);
		record.setId("s1");

		Files.write(activeFile(ACCOUNT_A).toPath(), "{oops".getBytes(StandardCharsets.UTF_8));
		store.append(ACCOUNT_A, record);
		assertTrue(store.delete(ACCOUNT_A, "s1").isEmpty());
		assertEquals("{oops", new String(Files.readAllBytes(activeFile(ACCOUNT_A).toPath()), StandardCharsets.UTF_8));

