package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Color;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.JagexColors;
import org.junit.Assume;
import org.junit.Test;

/**
 * {@link LedgerTheme}'s tokens are direction A's values in docs/DESIGN_PRINCIPLES.md 4.2 (read from the doc itself, so
 * the two can't drift apart, where the doc is in the checkout), RuneLite's constants where the value is one of
 * theirs, and still meet their contrast targets (WCAG 2.x, as {@code scripts/contrast.py} measures them).
 */
public class LedgerThemeTest
{
	private static final String DOC = "docs/DESIGN_PRINCIPLES.md";

	@Test
	public void theTokensAreDirectionAsValuesInTheDoc() throws IOException
	{
		Path path = Paths.get(DOC);
		// The public plugin repository ships only docs/COUNTING_RULES.md (docs/PUBLISHING.md): there the values in
		// theTokensAreDirectionAsValues are the check.
		Assume.assumeTrue(DOC + " is not in this checkout", Files.isRegularFile(path));
		String doc = new String(Files.readAllBytes(path), StandardCharsets.UTF_8);
		Map<String, Color> tokens = new LinkedHashMap<>();
		tokens.put("page", LedgerTheme.PAGE);
		tokens.put("card", LedgerTheme.CARD);
		// A flat row's hover (9d): the card colour, so text keeps the card's ratios.
		tokens.put("hover", LedgerTheme.HOVER);
		tokens.put("track", LedgerTheme.TRACK);
		tokens.put("barFill", LedgerTheme.BAR_FILL);
		tokens.put("heading", LedgerTheme.HEADING);
		tokens.put("label", LedgerTheme.LABEL);
		tokens.put("value", LedgerTheme.VALUE);
		tokens.put("key \\(one per area\\)", LedgerTheme.KEY);
		tokens.put("hint", LedgerTheme.HINT);
		tokens.put("good", LedgerTheme.GOOD);
		tokens.put("alert", LedgerTheme.ALERT);
		// The advisor note's edge and Bring cells: A's only, never text.
		tokens.put("parchmentEdge \\(not text\\)", LedgerTheme.PARCHMENT_EDGE);
		tokens.put("parchmentCell \\(not text\\)", LedgerTheme.PARCHMENT_CELL);
		for (Map.Entry<String, Color> token : tokens.entrySet())
		{
			// The 4.2 table's row: "| page | `#2A241C` | ..." (A is the first value column).
			Matcher row = Pattern.compile("^\\| " + token.getKey() + " \\| `(#[0-9A-F]{6})`", Pattern.MULTILINE)
				.matcher(doc);
			assertTrue(token.getKey() + " is in the table", row.find());
			assertEquals(token.getKey(), row.group(1), hex(token.getValue()));
		}
		assertEquals(docHex(doc, "outer `(#[0-9A-F]{6})`"), hex(LedgerTheme.BEVEL_OUTER));
		assertEquals(docHex(doc, "inner `(#[0-9A-F]{6})`"), hex(LedgerTheme.BEVEL_INNER));
		assertEquals(docHex(doc, "Parchment `(#[0-9A-F]{6})`"), hex(LedgerTheme.PARCHMENT));
		Matcher inks = Pattern.compile("Its ink colours: `(#[0-9A-F]{6})`[^,]*, muted `(#[0-9A-F]{6})`[^,]*, "
			+ "red `(#[0-9A-F]{6})`").matcher(doc);
		assertTrue("the parchment's inks", inks.find());
		assertEquals(inks.group(1), hex(LedgerTheme.INK));
		assertEquals(inks.group(2), hex(LedgerTheme.MUTED_INK));
		assertEquals(inks.group(3), hex(LedgerTheme.RED_INK));
	}

	/** The values themselves, so a change to the doc is a change to this test too; they need no doc to check. */
	@Test
	public void theTokensAreDirectionAsValues()
	{
		assertEquals("#2A241C", hex(LedgerTheme.PAGE));
		assertEquals("#3E3529", hex(LedgerTheme.CARD));
		assertEquals("#3E3529", hex(LedgerTheme.HOVER));
		assertEquals("#322A21", hex(LedgerTheme.BEVEL_OUTER));
		assertEquals("#4A4031", hex(LedgerTheme.BEVEL_INNER));
		assertEquals("#2A241C", hex(LedgerTheme.TRACK));
		assertEquals("#FF981F", hex(LedgerTheme.BAR_FILL));
		assertEquals("#FF981F", hex(LedgerTheme.HEADING));
		assertEquals("#D2BF94", hex(LedgerTheme.LABEL));
		assertEquals("#FFFFFF", hex(LedgerTheme.VALUE));
		assertEquals("#FFFFFF", hex(LedgerTheme.KEY));
		assertEquals("#B3A27E", hex(LedgerTheme.HINT));
		assertEquals("#6EE16E", hex(LedgerTheme.GOOD));
		assertEquals("#FFFF00", hex(LedgerTheme.ALERT));
		assertEquals("#D8C8A0", hex(LedgerTheme.PARCHMENT));
		assertEquals("#3A2A16", hex(LedgerTheme.INK));
		assertEquals("#5E4B2E", hex(LedgerTheme.MUTED_INK));
		assertEquals("#8A1C12", hex(LedgerTheme.RED_INK));
		assertEquals("#B8A678", hex(LedgerTheme.PARCHMENT_EDGE));
		assertEquals("#C2B28D", hex(LedgerTheme.PARCHMENT_CELL));
	}

	@Test
	public void theBringCellIsInkAtFourteenPercentOverParchment()
	{
		// As the chosen mockup draws the note's cells: rgba(58, 42, 22, 0.14) over the parchment.
		assertEquals(LedgerTheme.PARCHMENT_CELL, over(LedgerTheme.INK, 0.14, LedgerTheme.PARCHMENT));
	}

	@Test
	public void runeLitesOwnColoursAreItsConstants()
	{
		assertEquals(JagexColors.DARK_ORANGE_INTERFACE_TEXT, LedgerTheme.HEADING);
		assertEquals(JagexColors.DARK_ORANGE_INTERFACE_TEXT, LedgerTheme.BAR_FILL);
		assertEquals(JagexColors.YELLOW_INTERFACE_TEXT, LedgerTheme.ALERT);
		assertEquals(ColorScheme.GRAND_EXCHANGE_PRICE, LedgerTheme.GOOD);
		assertEquals(LedgerTheme.PAGE, LedgerTheme.TRACK);
		// A flat row's hover is the card's stone (9d), where textMeetsItsContrastTargets checks every text token.
		assertEquals(LedgerTheme.CARD, LedgerTheme.HOVER);
	}

	@Test
	public void theBevelIsTheCardTimesPointEightAndOnePointTwo()
	{
		// RuneLite's BackgroundComponent frames overlays with these offsets.
		assertEquals(scaled(LedgerTheme.CARD, 0.8), LedgerTheme.BEVEL_OUTER);
		assertEquals(scaled(LedgerTheme.CARD, 1.2), LedgerTheme.BEVEL_INNER);
	}

	@Test
	public void textMeetsItsContrastTargets()
	{
		for (Color text : new Color[]{LedgerTheme.HEADING, LedgerTheme.LABEL, LedgerTheme.VALUE, LedgerTheme.KEY,
			LedgerTheme.HINT, LedgerTheme.GOOD, LedgerTheme.ALERT})
		{
			assertTrue(hex(text) + " on the card", contrast(text, LedgerTheme.CARD) >= 4.5);
			assertTrue(hex(text) + " on the page", contrast(text, LedgerTheme.PAGE) >= 4.5);
			// A history or Skipped / blocked row under the mouse (9c and 9d, DESIGN_PRINCIPLES.md 3.7 Hover).
			assertTrue(hex(text) + " on a hovered row", contrast(text, LedgerTheme.HOVER) >= 4.5);
		}
		assertEquals("bar fill on track (doc: 7.14)", 7.14, contrast(LedgerTheme.BAR_FILL, LedgerTheme.TRACK), 0.01);
		assertEquals("alert vs heading (doc: 2.00)", 2.00, contrast(LedgerTheme.ALERT, LedgerTheme.HEADING), 0.01);
		for (Color ink : new Color[]{LedgerTheme.INK, LedgerTheme.MUTED_INK, LedgerTheme.RED_INK})
		{
			assertTrue(hex(ink) + " on parchment", contrast(ink, LedgerTheme.PARCHMENT) >= 4.5);
		}
		// The alch hint's border (DESIGN_PRINCIPLES.md 3.6) on the card's stone, where the live grids' cells are.
		assertTrue(contrast(ItemGridView.ALCH_BORDER_COLOR, LedgerTheme.CARD) >= 3);
	}

	@Test
	public void theFontsAreFontManagersAtTheirNativeSize()
	{
		assertEquals(FontManager.getRunescapeFont(), LedgerTheme.plainFont());
		assertEquals(FontManager.getRunescapeBoldFont(), LedgerTheme.boldFont());
		assertEquals(FontManager.getRunescapeSmallFont(), LedgerTheme.smallFont());
	}

	private static String docHex(String doc, String pattern)
	{
		Matcher m = Pattern.compile(pattern).matcher(doc);
		assertTrue(pattern, m.find());
		return m.group(1);
	}

	private static String hex(Color c)
	{
		return String.format("#%02X%02X%02X", c.getRed(), c.getGreen(), c.getBlue());
	}

	/** {@code fg} at {@code alpha} over {@code bg}, rounded per channel. */
	private static Color over(Color fg, double alpha, Color bg)
	{
		return new Color((int) Math.round(fg.getRed() * alpha + bg.getRed() * (1 - alpha)),
			(int) Math.round(fg.getGreen() * alpha + bg.getGreen() * (1 - alpha)),
			(int) Math.round(fg.getBlue() * alpha + bg.getBlue() * (1 - alpha)));
	}

	private static Color scaled(Color c, double factor)
	{
		return new Color((int) Math.round(c.getRed() * factor), (int) Math.round(c.getGreen() * factor),
			(int) Math.round(c.getBlue() * factor));
	}

	/** WCAG 2.x contrast ratio. */
	private static double contrast(Color a, Color b)
	{
		double la = luminance(a);
		double lb = luminance(b);
		return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
	}

	private static double luminance(Color c)
	{
		return 0.2126 * linear(c.getRed()) + 0.7152 * linear(c.getGreen()) + 0.0722 * linear(c.getBlue());
	}

	private static double linear(int channel)
	{
		double v = channel / 255.0;
		return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

/**
 * The live card's stats grid rules ({@link LiveSessionSection#leftColumnWidth},
 * {@link LiveSessionSection#statTooltip}): how the card's width is split between the two columns, and each stat's
 * tooltip with its whole value first. {@link HarnessLiveCardTest} lays the grid out at the sidebar's width.
 */
public class LiveStatsGridTest
{
	/** The room for both columns inside the card at the sidebar's width: 199 px, less the 6 px between them. */
	private static final int ROOM = 193;

	@Test
	public void bothSteadyWidthsFitSoTheRoomLeftOverIsShared()
	{
		// Elapsed's clock at its widest under 10 hours (87) and the time left's (99): 7 px over, the odd one right.
		assertEquals(90, LiveSessionSection.leftColumnWidth(ROOM, 87, 99, 80, 98));
		assertEquals("exactly full", 89, LiveSessionSection.leftColumnWidth(ROOM, 89, 104, 89, 104));
	}

	@Test
	public void whenTheSteadyWidthsDontFitTheLeftGivesWhatTheRightNeeds()
	{
		// "~10h 00m" (105) beside a short clock: the left keeps only what the right leaves it.
		assertEquals(88, LiveSessionSection.leftColumnWidth(ROOM, 93, 105, 80, 105));
		// A long left value beside a short right one: the left keeps its steady width.
		assertEquals(93, LiveSessionSection.leftColumnWidth(ROOM, 93, 105, 93, 66));
	}

	@Test
	public void whenTheValuesDontFitEachColumnGetsItsShare()
	{
		assertEquals(93 * ROOM / 198, LiveSessionSection.leftColumnWidth(ROOM, 93, 105, 93, 105));
		assertEquals("no room yet", 0, LiveSessionSection.leftColumnWidth(-6, 87, 99, 80, 98));
	}

	@Test
	public void theTooltipStartsWithTheLabelAndTheWholeValue()
	{
		assertEquals("Kills left: 1,985", LiveSessionSection.statTooltip("Kills left", "1,985", null));
		assertEquals("<html>Pace: ?<br>Shown after 3 kills &amp; 1 minute.</html>",
			LiveSessionSection.statTooltip("Pace", "?", "Shown after 3 kills & 1 minute."));
		assertEquals("<html>Time left: ~&lt;1m<br>Kills per hour: 180<br>Assumes the same pace.</html>",
			LiveSessionSection.statTooltip("Time left", "~<1m",
				"<html>Kills per hour: 180<br>Assumes the same pace.</html>"));
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.TestSpots.CATACOMBS;
import static com.shmayvan.slayerledger.TestSpots.CATACOMBS_ID;
import static com.shmayvan.slayerledger.TestSpots.CATACOMBS_WEST;
import static com.shmayvan.slayerledger.TestSpots.KRAKEN_COVE_ID;
import static com.shmayvan.slayerledger.TestSpots.KRAKEN_ROOM_ID;
import static com.shmayvan.slayerledger.TestSpots.KRAKEN_SHARED;
import static com.shmayvan.slayerledger.TestSpots.SMOKE;
import static com.shmayvan.slayerledger.TestSpots.SMOKE_ID;
import static com.shmayvan.slayerledger.TestSpots.TABLE;
import static com.shmayvan.slayerledger.TestSpots.TOWER;
import static com.shmayvan.slayerledger.TestSpots.TOWER_ID;
import static com.shmayvan.slayerledger.TestSpots.UNLISTED;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * The kills per place of a session: adding, cleaning a stored tally, and the task's spot from it with its
 * ties ({@link LocationTally#decide}).
 */
public class LocationTallyTest
{
	private static final String DEVILS = "Dust devils";

	private static List<LocationKills> tally(Object... placeKills)
	{
		List<LocationKills> tally = null;
		for (int i = 0; i < placeKills.length; i += 2)
		{
			tally = LocationTally.add(tally, (KillPlace) placeKills[i], (Integer) placeKills[i + 1]);
		}
		return tally;
	}

	private static KillPlace centre(int region)
	{
		return TestSpots.centre(region);
	}

	@Test
	public void addsKillsPerPlaceTheMostRecentLast()
	{
		List<LocationKills> tally = LocationTally.add(null, centre(SMOKE), 3);
		tally = LocationTally.add(tally, centre(CATACOMBS), 1);
		List<LocationKills> before = tally;
		tally = LocationTally.add(tally, centre(SMOKE), 2);
		assertEquals(Arrays.asList(new LocationKills(CATACOMBS, CATACOMBS_ID, 1), new LocationKills(SMOKE, SMOKE_ID, 5)),
			tally);
		assertEquals("the list passed in is not changed",
			Arrays.asList(new LocationKills(SMOKE, SMOKE_ID, 3), new LocationKills(CATACOMBS, CATACOMBS_ID, 1)), before);
	}

	@Test
	public void aRegionSharedByTwoSpotsIsTwoPlaces()
	{
		List<LocationKills> tally = tally(TestSpots.place(2250, 10000, 0), 2, TestSpots.place(2278, 10034, 0), 3,
			KillPlace.ofRegion(KRAKEN_SHARED), 1);
		assertEquals(Arrays.asList(new LocationKills(KRAKEN_SHARED, KRAKEN_COVE_ID, 2),
			new LocationKills(KRAKEN_SHARED, KRAKEN_ROOM_ID, 3), new LocationKills(KRAKEN_SHARED, 1)), tally);
	}

	@Test
	public void unknownPlacesAndNoKillsAreNotTallied()
	{
		List<LocationKills> tally = LocationTally.add(null, KillPlace.NONE, 4);
		tally = LocationTally.add(tally, LocationTally.NO_REGION, 4);
		assertTrue(tally.isEmpty());
		tally = LocationTally.add(tally, centre(SMOKE), 0);
		tally = LocationTally.add(tally, centre(SMOKE), -2);
		assertTrue(tally.isEmpty());
		assertEquals(TaskSpot.UNKNOWN, LocationTally.decide(tally, TABLE, DEVILS));
		assertEquals(TaskSpot.UNKNOWN, LocationTally.decide(null, TABLE, DEVILS));
	}

	@Test
	public void theSpotWithTheMostKillsWinsAcrossItsRegions()
	{
		// 2 + 2 in the Catacombs' two regions beat 3 in the Smoke Dungeon's one.
		List<LocationKills> tally = tally(centre(CATACOMBS_WEST), 2, centre(SMOKE), 3, centre(CATACOMBS), 2);
		assertEquals("its region is the one with the most kills there, the most recent on a tie",
			new TaskSpot(CATACOMBS_ID, CATACOMBS), LocationTally.decide(tally, TABLE, DEVILS));
		tally = LocationTally.add(tally, centre(CATACOMBS_WEST), 1);
		assertEquals(new TaskSpot(CATACOMBS_ID, CATACOMBS_WEST), LocationTally.decide(tally, TABLE, DEVILS));
	}

	@Test
	public void aTieGoesToTheSpotListingTheTaskThenToTheMostRecentKill()
	{
		// The Slayer Tower lists no dust devils, so the Smoke Dungeon wins the tie although the tower is more recent.
		List<LocationKills> tally = tally(centre(SMOKE), 2, centre(TOWER), 2);
		assertEquals(new TaskSpot(SMOKE_ID, SMOKE), LocationTally.decide(tally, TABLE, DEVILS));
		assertEquals("without the task's name, the most recent", new TaskSpot(TOWER_ID, TOWER),
			LocationTally.decide(tally, TABLE, null));
		// Both list dust devils: the most recent kill decides.
		tally = tally(centre(SMOKE), 2, centre(CATACOMBS), 2);
		assertEquals(new TaskSpot(CATACOMBS_ID, CATACOMBS), LocationTally.decide(tally, TABLE, DEVILS));
		tally = tally(centre(CATACOMBS), 2, centre(SMOKE), 2);
		assertEquals(new TaskSpot(SMOKE_ID, SMOKE), LocationTally.decide(tally, TABLE, DEVILS));
	}

	@Test
	public void killsTalliedByRegionAloneTakeTheirRegionsSpot()
	{
		List<LocationKills> tally = Collections.singletonList(new LocationKills(SMOKE, 3));
		assertEquals(new TaskSpot(SMOKE_ID, SMOKE), LocationTally.decide(tally, TABLE, DEVILS));
		assertEquals("no table: no spot, the region kept", new TaskSpot(null, SMOKE),
			LocationTally.decide(tally, SlayerSpots.NONE, DEVILS));
		assertEquals("an unlisted region is a spot of its own", new TaskSpot("region:" + UNLISTED, UNLISTED),
			LocationTally.decide(Collections.singletonList(new LocationKills(UNLISTED, 1)), TABLE, DEVILS));
	}

	@Test
	public void aSharedRegionAloneIsDecidedByTheTaskOrNotAtAll()
	{
		List<LocationKills> kraken = Collections.singletonList(new LocationKills(KRAKEN_SHARED, 5));
		assertEquals("only Kraken Cove lists waterfiends", new TaskSpot(KRAKEN_COVE_ID, KRAKEN_SHARED),
			LocationTally.decide(kraken, TABLE, "Waterfiends"));
		assertEquals("both list cave kraken: Unknown, the region kept", new TaskSpot(null, KRAKEN_SHARED),
			LocationTally.decide(kraken, TABLE, "Cave kraken"));
		// Kills with no spot count for none: one kill in the Catacombs is the task's spot.
		List<LocationKills> mixed = new ArrayList<>(kraken);
		mixed.add(new LocationKills(CATACOMBS, CATACOMBS_ID, 1));
		assertEquals(new TaskSpot(CATACOMBS_ID, CATACOMBS), LocationTally.decide(mixed, TABLE, "Cave kraken"));
	}

	@Test
	public void killsSaturate()
	{
		List<LocationKills> tally = LocationTally.add(null, centre(SMOKE), Integer.MAX_VALUE - 1);
		tally = LocationTally.add(tally, centre(SMOKE), 5);
		assertEquals(Collections.singletonList(new LocationKills(SMOKE, SMOKE_ID, Integer.MAX_VALUE)), tally);
		tally = LocationTally.add(tally, centre(CATACOMBS), Integer.MAX_VALUE);
		tally = LocationTally.add(tally, centre(CATACOMBS_WEST), 5);
		assertEquals("a spot's sum saturates too", CATACOMBS_ID, LocationTally.decide(tally, TABLE, DEVILS).getSpotId());
	}

	@Test
	public void atMostMaxRegionsAreTallied()
	{
		List<LocationKills> tally = null;
		for (int region = 0; region < LocationTally.MAX_REGIONS + 3; region++)
		{
			tally = LocationTally.add(tally, region, 1);
		}
		assertEquals(LocationTally.MAX_REGIONS, tally.size());
		tally = LocationTally.add(tally, 0, 1);
		assertEquals("a tallied place still counts, and is now the most recent", new LocationKills(0, 2),
			tally.get(LocationTally.MAX_REGIONS - 1));
	}

	@Test
	public void sanitizeDropsBadEntriesAndMergesRepeats()
	{
		List<LocationKills> stored = new ArrayList<>(Arrays.asList(new LocationKills(SMOKE, 2), null,
			new LocationKills(-5, 3), new LocationKills(CATACOMBS, 0), new LocationKills(CATACOMBS, CATACOMBS_ID, 4),
			new LocationKills(SMOKE, " ", 3), new LocationKills(SMOKE, SMOKE_ID, 1)));
		assertEquals("a blank spot reads as none", Arrays.asList(new LocationKills(SMOKE, 5),
			new LocationKills(CATACOMBS, CATACOMBS_ID, 4), new LocationKills(SMOKE, SMOKE_ID, 1)),
			LocationTally.sanitize(stored));
		assertTrue(LocationTally.sanitize(null).isEmpty());
		assertEquals("repeats count together once cleaned", new TaskSpot(SMOKE_ID, SMOKE),
			LocationTally.decide(stored, TABLE, DEVILS));
		assertEquals("a bad entry never wins", new TaskSpot(SMOKE_ID, SMOKE),
			LocationTally.decide(Arrays.asList(new LocationKills(-5, 9), new LocationKills(CATACOMBS, 0),
				new LocationKills(SMOKE, 1)), TABLE, DEVILS));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * The combined capture-time loot filter: crushed bones and ashes ({@link CrushedLootFilter}) and the player's ignored
 * items ({@link IgnoredLoot}).
 */
public class LootFilterTest
{
	private static final Map<Integer, String> NAMES = new HashMap<>();

	static
	{
		NAMES.put(ItemID.WYRM_BONES, "Wyrm bones");
		NAMES.put(ItemID.ABYSSAL_ASHES, "Abyssal ashes");
		NAMES.put(ItemID.COINS, "Coins");
		NAMES.put(ItemID.DRAGON_BONES, "Dragon bones");
		NAMES.put(ItemID.RANARR_SEED, "Ranarr seed");
	}

	/** Item facts as the plugin reads them; records every lookup. */
	private static final class FakeNames implements LootFilter.ItemNames
	{
		final List<String> calls = new ArrayList<>();

		@Override
		public int unnoted(int itemId)
		{
			calls.add("unnoted " + itemId);
			return itemId == ItemID.Cert.DRAGON_BONES ? ItemID.DRAGON_BONES : itemId;
		}

		@Override
		public String name(int itemId)
		{
			calls.add("name " + itemId);
			return NAMES.get(itemId);
		}
	}

	private static ItemTally drop()
	{
		ItemTally loot = new ItemTally();
		loot.add(ItemID.WYRM_BONES, 1);
		loot.add(ItemID.ABYSSAL_ASHES, 1);
		loot.add(ItemID.COINS, 300);
		loot.add(ItemID.Cert.DRAGON_BONES, 5);
		loot.add(ItemID.RANARR_SEED, 2);
		return loot;
	}

	private static CrushedLootFilter crusher()
	{
		return CrushedLootFilter.forDrop(BonecrusherMode.AUTO, Collections.singletonList(ItemID.BONECRUSHER));
	}

	@Test
	public void keepsEverythingWithoutCrusherOrIgnoredItemsAndLooksNothingUp()
	{
		FakeNames names = new FakeNames();
		ItemTally kept = new LootFilter(CrushedLootFilter.KEEP_ALL, IgnoredLoot.NONE).apply(drop(), names);
		assertEquals(drop(), kept);
		assertTrue("no item lookups when nothing is ignored", names.calls.isEmpty());
	}

	@Test
	public void combinesTheCrusherAndTheIgnoredItems()
	{
		ItemTally kept = new LootFilter(crusher(), IgnoredLoot.parse("coins, *seed")).apply(drop(), new FakeNames());
		assertEquals(0, kept.get(ItemID.WYRM_BONES));
		assertEquals(0, kept.get(ItemID.COINS));
		assertEquals(0, kept.get(ItemID.RANARR_SEED));
		assertEquals(1, kept.get(ItemID.ABYSSAL_ASHES));
		assertEquals("noted bones are not crushed", 5, kept.get(ItemID.Cert.DRAGON_BONES));
		assertEquals(2, kept.size());
	}

	@Test
	public void notedDropsAreMatchedByTheUnnotedName()
	{
		ItemTally kept = new LootFilter(CrushedLootFilter.KEEP_ALL, IgnoredLoot.parse("Dragon bones"))
			.apply(drop(), new FakeNames());
		assertEquals(0, kept.get(ItemID.Cert.DRAGON_BONES));
		assertEquals(1, kept.get(ItemID.WYRM_BONES));
	}

	@Test
	public void idOnlyListsLookUpNoNames()
	{
		FakeNames names = new FakeNames();
		ItemTally kept = new LootFilter(CrushedLootFilter.KEEP_ALL, IgnoredLoot.parse(Integer.toString(ItemID.DRAGON_BONES)))
			.apply(drop(), names);
		assertEquals(0, kept.get(ItemID.Cert.DRAGON_BONES));
		assertEquals(4, kept.size());
		for (String call : names.calls)
		{
			assertTrue(call, call.startsWith("unnoted "));
		}
	}

	@Test
	public void eachItemIsLookedUpOnce()
	{
		FakeNames names = new FakeNames();
		new LootFilter(crusher(), IgnoredLoot.parse("coins")).apply(drop(), names);
		// The crushed wyrm bones are never looked up; the other four ids once each (unnoted id, then name).
		assertEquals(8, names.calls.size());
	}

	@Test
	public void failedLookupsLeaveOnlyIdMatches()
	{
		LootFilter.ItemNames failing = new LootFilter.ItemNames()
		{
			@Override
			public int unnoted(int itemId)
			{
				throw new IllegalStateException("not loaded");
			}

			@Override
			public String name(int itemId)
			{
				throw new IllegalStateException("not loaded");
			}
		};
		ItemTally kept = new LootFilter(CrushedLootFilter.KEEP_ALL, IgnoredLoot.parse("Coins, " + ItemID.RANARR_SEED))
			.apply(drop(), failing);
		assertEquals("the name could not be read", 300, kept.get(ItemID.COINS));
		assertEquals(0, kept.get(ItemID.RANARR_SEED));
	}

	@Test
	public void nullLootIsEmpty()
	{
		assertTrue(new LootFilter(crusher(), IgnoredLoot.parse("x")).apply(null, new FakeNames()).isEmpty());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Loot valued in a price mode: GE, high alch, a missing GE price, a GE price of 0 (valued at high alch in every
 * mode), and doses.
 */
public class LootPricingTest
{
	private static final int RUNE = 1;
	private static final int UNTRADEABLE = 2;
	private static final int NO_GE = 3;
	private static final int POTION = 4;

	private static Map<Integer, Long> prices(long... idPrice)
	{
		Map<Integer, Long> map = new HashMap<>();
		for (int i = 0; i < idPrice.length; i += 2)
		{
			map.put((int) idPrice[i], idPrice[i + 1]);
		}
		return map;
	}

	private static ItemTally tally(int... idQty)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQty.length; i += 2)
		{
			t.add(idQty[i], idQty[i + 1]);
		}
		return t;
	}

	/** GE: 100 each, untradeable 0 (known), no GE price for {@link #NO_GE}. */
	private final Map<Integer, Long> ge = prices(RUNE, 100, UNTRADEABLE, 0);
	private final Map<Integer, Long> ha = prices(RUNE, 60, UNTRADEABLE, 50, NO_GE, 300);
	private final ItemTally loot = tally(RUNE, 2, UNTRADEABLE, 1, NO_GE, 1);

	@Test
	public void geValuesAtGeAndLeavesOutAMissingPrice()
	{
		// Runes at GE, the untradeable item (GE 0) at its high alch value, the item without a GE price left out.
		assertEquals(200 + 50, LootPricing.total(loot, LootPriceMode.GE, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(loot, LootPriceMode.GE, ge, ha));
		assertEquals(200, LootPricing.total(loot, LootPriceMode.GE, ge, null, null));
	}

	@Test
	public void aZeroGePriceCountsAtHighAlchInEveryMode()
	{
		// 7 Brimstone keys (untradeable: GE 0, high alch 48,000) and an item at GE 100 / high alch 60.
		int key = 23083;
		ItemTally keys = tally(key, 7, RUNE, 1);
		Map<Integer, Long> keyGe = prices(key, 0, RUNE, 100);
		Map<Integer, Long> keyHa = prices(key, 48_000, RUNE, 60);
		assertEquals(336_100, LootPricing.total(keys, LootPriceMode.GE, keyGe, keyHa, null));
		assertEquals(336_060, LootPricing.total(keys, LootPriceMode.HIGH_ALCH, keyGe, keyHa, null));
		for (LootPriceMode mode : LootPriceMode.values())
		{
			assertEquals("a GE price of 0 is known, not unpriced (" + mode + ")", 0,
				LootPricing.countUnpriced(keys, mode, keyGe, keyHa));
		}
		assertEquals(Long.valueOf(48_000), LootPricing.geUnitPrices(keyGe, keyHa).get(key));
		assertEquals("the input prices are not changed", Long.valueOf(0), keyGe.get(key));
	}

	@Test
	public void aMissingGePriceIsStillUnpricedInGe()
	{
		ItemTally t = tally(NO_GE, 2, RUNE, 1);
		assertEquals(100, LootPricing.total(t, LootPriceMode.GE, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(t, LootPriceMode.GE, ge, ha));
		assertEquals(null, LootPricing.geUnitPrices(ge, ha).get(NO_GE));
	}

	@Test
	public void coinsStayAtFaceValue()
	{
		// Coins are captured at 1 gp for both prices (ItemValuation), so no mode changes them.
		ItemTally coins = tally(ItemValuation.COINS, 5_000);
		Map<Integer, Long> one = prices(ItemValuation.COINS, 1);
		for (LootPriceMode mode : LootPriceMode.values())
		{
			assertEquals(5_000, LootPricing.total(coins, mode, one, one, null));
		}
	}

	@Test
	public void aZeroGePriceWithoutHighAlchStaysZero()
	{
		ItemTally t = tally(UNTRADEABLE, 3);
		assertEquals(0, LootPricing.total(t, LootPriceMode.GE, ge, prices(), null));
		assertEquals(0, LootPricing.countUnpriced(t, LootPriceMode.GE, ge, prices()));
	}

	@Test
	public void highAlchValuesAtHighAlch()
	{
		assertEquals(120 + 50 + 300, LootPricing.total(loot, LootPriceMode.HIGH_ALCH, ge, ha, null));
		assertEquals(0, LootPricing.countUnpriced(loot, LootPriceMode.HIGH_ALCH, ge, ha));
		assertEquals("no high alch values at all", 3,
			LootPricing.countUnpriced(loot, LootPriceMode.HIGH_ALCH, ge, null));
	}

	@Test
	public void anItemWithNeitherPriceIsLeftOut()
	{
		ItemTally t = tally(RUNE, 1, 99, 5);
		assertEquals(100, LootPricing.total(t, LootPriceMode.GE, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(t, LootPriceMode.GE, ge, ha));
		assertEquals(60, LootPricing.total(t, LootPriceMode.HIGH_ALCH, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(t, LootPriceMode.HIGH_ALCH, ge, ha));
		for (LootPriceMode mode : LootPriceMode.values())
		{
			assertEquals(mode.name(), 0, LootPricing.total(t, mode, null, null, null));
		}
	}

	@Test
	public void dosesAreValuedPerDoseInEveryMode()
	{
		// 3 doses of a 4-dose potion: GE 800, high alch 100 per potion.
		ItemTally doses = tally(POTION, 3);
		Map<Integer, Long> potionGe = prices(POTION, 800);
		Map<Integer, Long> potionHa = prices(POTION, 100);
		Map<Integer, Integer> perItem = Collections.singletonMap(POTION, 4);
		assertEquals(600, LootPricing.total(doses, LootPriceMode.GE, potionGe, potionHa, perItem));
		assertEquals(75, LootPricing.total(doses, LootPriceMode.HIGH_ALCH, potionGe, potionHa, perItem));
		assertEquals(2_400, LootPricing.total(doses, LootPriceMode.GE, potionGe, potionHa, null));
	}

	@Test
	public void nullModeIsGe()
	{
		assertEquals(250, LootPricing.total(loot, null, ge, ha, null));
		assertEquals(1, LootPricing.countUnpriced(loot, null, ge, ha));
	}

	@Test
	public void displayNames()
	{
		assertEquals("GE", LootPriceMode.GE.toString());
		assertEquals("High alch", LootPriceMode.HIGH_ALCH.toString());
	}

	@Test
	public void onlyGeAndHighAlchRemain()
	{
		// "Higher of the two" was removed (owner decision, 2026-10-25).
		assertArrayEquals(new LootPriceMode[]{LootPriceMode.GE, LootPriceMode.HIGH_ALCH}, LootPriceMode.values());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Loot tally in the session tracker, snapshots and ledger records.
 */
public class LootTrackingTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};
	private static final int BONES = 526;
	private static final int RUNE_SCIMITAR = 1333;

	/** Fixed prices: bones 100 GE / 0 HA, scimitar 15,000 GE / 15,360 HA, coins at face value via the helper. */
	private static final ItemValuation.PriceLookup PRICES = new ItemValuation.PriceLookup()
	{
		@Override
		public int canonicalize(int itemId)
		{
			return itemId;
		}

		@Override
		public long gePrice(int canonicalId)
		{
			return canonicalId == BONES ? 100 : canonicalId == RUNE_SCIMITAR ? 15_000 : 0;
		}

		@Override
		public long haPrice(int canonicalId)
		{
			return canonicalId == RUNE_SCIMITAR ? 15_360 : 0;
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return true;
		}
	};

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private long now;
	private SessionTracker tracker;
	private final Gson gson = new Gson();

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	private static ItemTally tally(int... idQty)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQty.length; i += 2)
		{
			t.add(idQty[i], idQty[i + 1]);
		}
		return t;
	}

	private void startDemonTask()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertTrue(tracker.startNow(ACCOUNT));
	}

	// ---- Tracker ----

	@Test
	public void lootIsRecordedOnlyWhileRunning()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertFalse("idle", tracker.addLoot(tally(BONES, 1)));
		assertTrue(tracker.startNow(ACCOUNT));
		assertTrue(tracker.addLoot(tally(BONES, 1, ItemValuation.COINS, 300)));
		tracker.pause();
		assertFalse("paused", tracker.addLoot(tally(BONES, 5)));
		tracker.startNow(ACCOUNT);
		assertTrue(tracker.addLoot(tally(BONES, 1)));
		tracker.loggedOut();
		assertFalse("auto-paused", tracker.addLoot(tally(BONES, 5)));

		ItemTally loot = tracker.getLoot();
		assertEquals(2, loot.get(BONES));
		assertEquals(300, loot.get(ItemValuation.COINS));

		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(loot, summary.getLoot());
		assertFalse("stopped/idle", tracker.addLoot(tally(BONES, 1)));
		assertTrue(tracker.getLoot().isEmpty());
	}

	@Test
	public void lootFromAnyNpcCountsAndEmptyLootIsIgnored()
	{
		startDemonTask();
		// Not filtered by task monster: the tracker has no NPC information at all.
		assertTrue(tracker.addLoot(tally(RUNE_SCIMITAR, 1)));
		assertFalse(tracker.addLoot(new ItemTally()));
		assertFalse(tracker.addLoot(null));
		assertEquals(1, tracker.getLoot().size());
	}

	@Test
	public void newSessionStartsWithEmptyLoot()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 3));
		tracker.stopAndReset();
		assertTrue(tracker.startNow(ACCOUNT));
		assertTrue(tracker.getLoot().isEmpty());
		assertTrue(tracker.activeSummary().getLoot().isEmpty());
	}

	@Test
	public void summaryLootIsACopy()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 3));
		SessionTracker.Summary summary = tracker.activeSummary();
		tracker.addLoot(tally(BONES, 3));
		summary.getLoot().add(BONES, 100);
		assertEquals(3, summary.getLoot().get(BONES));
		assertEquals(6, tracker.getLoot().get(BONES));
	}

	// ---- Snapshot and restore ----

	private SessionSnapshot snapshotWithLoot()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 4, ItemValuation.COINS, 1_000));
		now += 30_000;
		tracker.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		tracker.loggedOut();
		return SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
	}

	@Test
	public void snapshotWithLootRoundTripsThroughJson()
	{
		SessionSnapshot s = snapshotWithLoot();
		assertEquals(Long.valueOf(4), s.getLoot().get(BONES));
		String json = gson.toJson(s);
		assertTrue(json, json.contains("\"loot\":{\"526\":4,\"995\":1000}"));
		SessionSnapshot back = gson.fromJson(json, SessionSnapshot.class);
		assertEquals(s, back);
		assertEquals(s.getLoot(), back.getLoot());
	}

	@Test
	public void snapshotWithoutLootOmitsField()
	{
		startDemonTask();
		SessionSnapshot s = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertNull(s.getLoot());
		assertFalse(gson.toJson(s).contains("loot"));
	}

	@Test
	public void oldSnapshotWithoutLootRestores()
	{
		String v1 = "{\"schemaVersion\":1,\"sessionId\":\"s1\",\"accountHash\":555,\"monster\":\"Abyssal demons\","
			+ "\"creatureId\":42,\"initialAmount\":50,\"originalAmount\":150,\"kills\":4,\"activeMillis\":30000,"
			+ "\"startedAt\":1000,\"savedAt\":2000,\"remaining\":46,\"completionCounters\":[100,2,0]}";
		SessionSnapshot s = gson.fromJson(v1, SessionSnapshot.class);
		assertNull(s.getLoot());
		assertTrue(s.toSummary(SlayerSpots.NONE).getLoot().isEmpty());

		tracker.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(s, COUNTERS));
		assertTrue(tracker.getLoot().isEmpty());
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.addLoot(tally(BONES, 1));
		assertEquals(1, tracker.getLoot().get(BONES));
	}

	@Test
	public void fileRestoreKeepsLootAndAddsToIt()
	{
		SessionSnapshot s = gson.fromJson(gson.toJson(snapshotWithLoot()), SessionSnapshot.class);
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(s, COUNTERS));
		assertEquals(4, restored.getLoot().get(BONES));
		assertFalse("restored session is paused", restored.addLoot(tally(BONES, 10)));
		assertTrue(restored.startNow(ACCOUNT));
		restored.addLoot(tally(BONES, 1, RUNE_SCIMITAR, 1));

		LedgerRecord record = LedgerRecord.fromSummary(restored.stopAndReset(), true);
		assertEquals(Long.valueOf(5), record.getLoot().get(BONES));
		assertEquals(Long.valueOf(1_000), record.getLoot().get(ItemValuation.COINS));
		assertEquals(Long.valueOf(1), record.getLoot().get(RUNE_SCIMITAR));
	}

	@Test
	public void restoreClearsLootOfAnyEarlierSession()
	{
		SessionSnapshot s = snapshotWithLoot();
		SessionTracker other = new SessionTracker(() -> now);
		other.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		other.startNow(ACCOUNT);
		other.addLoot(tally(RUNE_SCIMITAR, 9));
		other.stopAndReset();
		assertEquals(SessionTracker.RestoreResult.RESTORED, other.restore(s, COUNTERS));
		assertEquals(0, other.getLoot().get(RUNE_SCIMITAR));
		assertEquals(4, other.getLoot().get(BONES));
	}

	@Test
	public void mismatchedFileRestoreSavesLootInPartialRecord()
	{
		SessionSnapshot s = gson.fromJson(gson.toJson(snapshotWithLoot()), SessionSnapshot.class);
		SessionTracker later = new SessionTracker(() -> now);
		later.observe("Black dragons", DRAGON_ID, 20, 20, false);
		assertEquals(SessionTracker.RestoreResult.MISMATCH, later.restore(s, COUNTERS));
		assertTrue(later.getLoot().isEmpty());

		LedgerRecord record = LedgerRecord.fromSummary(s.toSummary(SlayerSpots.NONE), true);
		assertTrue(record.isPartial());
		assertEquals(Long.valueOf(4), record.getLoot().get(BONES));
		assertEquals(Long.valueOf(1_000), record.getLoot().get(ItemValuation.COINS));
	}

	@Test
	public void inMemoryReloginKeepsLoot()
	{
		SessionSnapshot logout = snapshotWithLoot();
		// Logout: the session stays in memory, auto-paused; the current task is forgotten.
		tracker.clearCurrentTask();
		tracker.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		assertTrue(tracker.activeSessionStillMatches(logout, COUNTERS));
		assertEquals(4, tracker.getLoot().get(BONES));
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.addLoot(tally(BONES, 2));
		assertEquals(6, tracker.getLoot().get(BONES));
	}

	@Test
	public void inMemoryReloginMismatchSavesLootInPartialRecord()
	{
		SessionSnapshot logout = snapshotWithLoot();
		tracker.clearCurrentTask();
		tracker.observe("Black dragons", DRAGON_ID, 20, 20, false);
		assertFalse(tracker.activeSessionStillMatches(logout, COUNTERS));
		// The plugin then ends the session as RESTORE_MISMATCH.
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertNotNull(summary);
		LedgerRecord record = LedgerRecord.fromSummary(summary, true);
		assertEquals(Long.valueOf(4), record.getLoot().get(BONES));
	}

	// ---- Records ----

	@Test
	public void recordCarriesLootAndCapturesValues()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 10, RUNE_SCIMITAR, 2, ItemValuation.COINS, 2_500));
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, record.getSchemaVersion());
		assertEquals(3, record.getLoot().size());
		assertNull("not valued until saved", record.getLootGeValue());

		record.captureValues(PRICES);
		assertEquals(Long.valueOf(10 * 100 + 2 * 15_000 + 2_500), record.getLootGeValue());
		assertEquals(Long.valueOf(2 * 15_360 + 2_500), record.getLootHaValue());
		assertEquals(Long.valueOf(15_000), record.getUnitGePrices().get(RUNE_SCIMITAR));
		assertEquals(Long.valueOf(1), record.getUnitHaPrices().get(ItemValuation.COINS));
		assertEquals(3, record.getUnitGePrices().size());
		assertNull(record.getSupplies());
		assertNull(record.getSuppliesGeValue());
		assertNull(record.getSuppliesHaValue());
	}

	@Test
	public void recordWithoutLootIsValuedAtZero()
	{
		startDemonTask();
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertNull(record.getLoot());
		record.captureValues(PRICES);
		assertEquals(Long.valueOf(0), record.getLootGeValue());
		assertEquals(Long.valueOf(0), record.getLootHaValue());
		assertNull(record.getUnitGePrices());
		assertNull(record.getUnitHaPrices());
	}

	@Test
	public void suppliesAreValuedWhenPresent()
	{
		LedgerRecord record = new LedgerRecord();
		Map<Integer, Long> supplies = new TreeMap<>();
		supplies.put(BONES, 3L);
		record.setSupplies(supplies);
		record.captureValues(PRICES);
		assertEquals(Long.valueOf(300), record.getSuppliesGeValue());
		assertEquals(Long.valueOf(0), record.getSuppliesHaValue());
		assertEquals(Long.valueOf(100), record.getUnitGePrices().get(BONES));
		assertEquals(Long.valueOf(0), record.getLootGeValue());
	}

	@Test
	public void valuedRecordRoundTripsThroughJson()
	{
		startDemonTask();
		tracker.addLoot(tally(BONES, 10, RUNE_SCIMITAR, 2));
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		record.captureValues(PRICES);
		String json = gson.toJson(record);
		assertFalse("null supplies are omitted", json.contains("supplies"));
		LedgerRecord back = gson.fromJson(json, LedgerRecord.class);
		assertEquals(record, back);
		assertEquals(Long.valueOf(31_000), back.getLootGeValue());
	}

	@Test
	public void oldRecordJsonLoadsWithNullItemFields()
	{
		String v1 = "{\"schemaVersion\":1,\"id\":\"old\",\"monster\":\"Kurask\",\"initialAmount\":50,\"kills\":50,"
			+ "\"completed\":true}";
		LedgerRecord r = gson.fromJson(v1, LedgerRecord.class);
		assertEquals(1, r.getSchemaVersion());
		assertEquals(50, r.getKills());
		assertNull(r.getLoot());
		assertNull(r.getSupplies());
		assertNull(r.getUnitGePrices());
		assertNull(r.getUnitHaPrices());
		assertNull(r.getLootGeValue());
		assertNull(r.getLootHaValue());
		assertNull(r.getSuppliesGeValue());
		assertNull(r.getSuppliesHaValue());
	}

	@Test
	public void version1LedgerFileLoadsAndIsUpgradedOnAppend() throws IOException
	{
		File dir = new File(temp.getRoot(), "slayer-ledger");
		assertTrue(dir.mkdirs());
		File file = new File(dir, ACCOUNT + ".json");
		String v1 = "{\"schemaVersion\":1,\"records\":[{\"schemaVersion\":1,\"id\":\"old\",\"monster\":\"Kurask\","
			+ "\"initialAmount\":50,\"kills\":50,\"completed\":true}]}";
		Files.write(file.toPath(), v1.getBytes(StandardCharsets.UTF_8));
		LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(dir.toPath()), gson);

		startDemonTask();
		tracker.addLoot(tally(BONES, 10));
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		record.captureValues(PRICES);
		store.append(ACCOUNT, record);

		String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
		assertTrue(json, json.startsWith("{\"schemaVersion\":" + LedgerStore.FILE_SCHEMA_VERSION + ","));
		List<LedgerRecord> loaded = store.load(ACCOUNT);
		assertEquals(2, loaded.size());
		assertNull(loaded.get(0).getLoot());
		// Migrated when it was read for the append, so it was written back at the current version.
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, loaded.get(0).getSchemaVersion());
		assertEquals(Long.valueOf(10), loaded.get(1).getLoot().get(BONES));
		assertEquals(Long.valueOf(1_000), loaded.get(1).getLootGeValue());
	}

	@Test
	public void activeFileWithLootRoundTripsThroughStore() throws IOException
	{
		LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(temp.getRoot().toPath().resolve("slayer-ledger")), gson);
		SessionSnapshot s = snapshotWithLoot();
		store.writeActive(ACCOUNT, s);
		SessionSnapshot back = store.readActive(ACCOUNT);
		assertEquals(s, back);
		assertEquals(SessionSnapshot.CURRENT_SCHEMA_VERSION, back.getSchemaVersion());
	}

	/** Prices not loaded: every tradeable item reads 0 GE. */
	private static final ItemValuation.PriceLookup UNLOADED = new ItemValuation.PriceLookup()
	{
		@Override
		public int canonicalize(int itemId)
		{
			return itemId;
		}

		@Override
		public long gePrice(int canonicalId)
		{
			return 0;
		}

		@Override
		public long haPrice(int canonicalId)
		{
			return PRICES.haPrice(canonicalId);
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return true;
		}
	};

	@Test
	public void unavailablePricesAreMissingAndCounted()
	{
		LedgerRecord record = new LedgerRecord();
		Map<Integer, Long> loot = new TreeMap<>();
		loot.put(BONES, 10L);
		loot.put(RUNE_SCIMITAR, 1L);
		loot.put(ItemValuation.COINS, 300L);
		record.setLoot(loot);
		Map<Integer, Long> supplies = new TreeMap<>();
		supplies.put(BONES, 2L);
		record.setSupplies(supplies);
		record.captureValues(UNLOADED);

		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, record.getSchemaVersion());
		assertFalse("omitted, not stored as 0", record.getUnitGePrices().containsKey(BONES));
		assertFalse(record.getUnitGePrices().containsKey(RUNE_SCIMITAR));
		assertEquals(Long.valueOf(1), record.getUnitGePrices().get(ItemValuation.COINS));
		assertEquals("known prices still sum", Long.valueOf(300), record.getLootGeValue());
		assertEquals(Long.valueOf(15_360 + 300), record.getLootHaValue());
		assertEquals(Long.valueOf(0), record.getSuppliesGeValue());
		assertEquals(Integer.valueOf(2), record.getLootUnpricedItems());
		assertEquals(Integer.valueOf(1), record.getSuppliesUnpricedItems());

		LedgerRecord back = gson.fromJson(gson.toJson(record), LedgerRecord.class);
		assertEquals(record, back);
	}

	@Test
	public void fullyPricedRecordHasNoUnpricedMarkers()
	{
		LedgerRecord record = new LedgerRecord();
		Map<Integer, Long> loot = new TreeMap<>();
		loot.put(BONES, 10L);
		record.setLoot(loot);
		record.captureValues(PRICES);
		assertNull(record.getLootUnpricedItems());
		assertNull(record.getSuppliesUnpricedItems());
		assertFalse(gson.toJson(record).contains("Unpriced"));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import javax.swing.Icon;
import org.junit.Test;

/**
 * The masters' faces ({@link MasterIcons}): every master name has a file, a missing image is an empty slot, a
 * bundled one is read once and drawn in the 18 by 16 slot.
 */
public class MasterIconsTest
{
	@Test
	public void everyMasterNameHasAFile()
	{
		Map<String, String> expected = new HashMap<>();
		expected.put("Turael/Aya", "turael_chathead.png");
		expected.put("Mazchna", "mazchna_chathead.png");
		expected.put("Vannaka", "vannaka_chathead.png");
		expected.put("Chaeldar", "chaeldar_chathead.png");
		// A shared name uses the first master's face.
		expected.put("Duradel/Kuradal", "duradel_chathead.png");
		expected.put("Nieve/Steve", "nieve_chathead.png");
		expected.put("Krystilia", "krystilia_chathead.png");
		expected.put("Konar", "konar_quo_maten_chathead.png");
		expected.put("Spria", "spria_chathead.png");
		expected.put("Mortimer", "mortimer_chathead.png");
		for (int master = 1; SlayerMaster.hasName(master); master++)
		{
			String name = SlayerMaster.displayName(master);
			assertEquals(name, expected.get(name), MasterIcons.fileName(name));
		}
		assertEquals(expected.size(), SlayerMaster.MORTIMER);
		assertNull(MasterIcons.fileName(SlayerMaster.displayName(42)));
		assertNull(MasterIcons.fileName(null));
	}

	@Test
	public void aMissingImageIsAnEmptySlot()
	{
		// As if the masters/ folder were deleted: no code change, no exception, an empty slot of the same size.
		MasterIcons icons = new MasterIcons("no-such-folder/");
		for (int master = 1; SlayerMaster.hasName(master); master++)
		{
			Icon icon = icons.icon(SlayerMaster.displayName(master));
			assertSame(SmallItemIcon.EMPTY, icon);
			assertEquals(ItemListView.ICON_WIDTH, icon.getIconWidth());
			assertEquals(ItemListView.ICON_HEIGHT, icon.getIconHeight());
		}
		assertSame(SmallItemIcon.EMPTY, new MasterIcons().icon("Unknown master (42)"));
		assertSame(SmallItemIcon.EMPTY, new MasterIcons().icon(null));
	}

	@Test
	public void anUnreadableImageIsAnEmptySlot()
	{
		// A test resource with Konar's file name that is no PNG: an empty slot, no exception.
		MasterIcons icons = new MasterIcons("masters-unreadable/");
		assertNotNull(MasterIcons.class.getResource("masters-unreadable/" + MasterIcons.fileName("Konar")));
		assertSame(SmallItemIcon.EMPTY, icons.icon("Konar"));
		assertSame(SmallItemIcon.EMPTY, icons.icon("Konar"));
	}

	@Test
	public void bundledImagesAreReadOnceAndFitTheSlot()
	{
		MasterIcons icons = new MasterIcons();
		for (int master = 1; SlayerMaster.hasName(master); master++)
		{
			String name = SlayerMaster.displayName(master);
			Icon icon = icons.icon(name);
			if (MasterIcons.class.getResource(MasterIcons.DIRECTORY + MasterIcons.fileName(name)) == null)
			{
				// Removed for the hub: the empty slot.
				assertSame(name, SmallItemIcon.EMPTY, icon);
				continue;
			}
			assertTrue(name, icon instanceof MasterIcons.MasterIcon);
			assertEquals(MasterIcons.fileName(name), ((MasterIcons.MasterIcon) icon).getFile());
			assertEquals(ItemListView.ICON_WIDTH, icon.getIconWidth());
			assertEquals(ItemListView.ICON_HEIGHT, icon.getIconHeight());
			assertSame("kept, not read again", icon, icons.icon(name));
			// Draws inside its slot without throwing.
			BufferedImage canvas = new BufferedImage(40, 40, BufferedImage.TYPE_INT_ARGB);
			Graphics2D g = canvas.createGraphics();
			icon.paintIcon(null, g, 5, 5);
			g.dispose();
			assertEquals(0, canvas.getRGB(4, 4) >>> 24);
			assertEquals(0, canvas.getRGB(5 + ItemListView.ICON_WIDTH, 5 + ItemListView.ICON_HEIGHT) >>> 24);
		}
	}

	@Test
	public void scalingKeepsTheAspectRatio()
	{
		BufferedImage tall = MasterIcons.scaled(new BufferedImage(66, 102, BufferedImage.TYPE_INT_ARGB), 36, 32);
		assertEquals(Arrays.asList(21, 32), Arrays.asList(tall.getWidth(), tall.getHeight()));
		BufferedImage wide = MasterIcons.scaled(new BufferedImage(119, 60, BufferedImage.TYPE_INT_ARGB), 36, 32);
		assertEquals(Arrays.asList(36, 18), Arrays.asList(wide.getWidth(), wide.getHeight()));
		// Already small: kept as it is.
		BufferedImage small = new BufferedImage(10, 8, BufferedImage.TYPE_INT_ARGB);
		assertSame(small, MasterIcons.scaled(small, 36, 32));
	}

}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;

/**
 * Food eaten in parts (pizzas, pies and cakes) is tracked in bites, like potion doses, so eating a whole one costs
 * exactly one item.
 */
public class MultiBiteFoodTest
{
	private static final String[] EAT = {"Eat", null, null, null, "Drop"};
	private static final String[] NONE = {null, null, null, null, "Drop"};

	/** Classifies with the production rules; the pie dish and everything unknown have no "Eat" action. */
	private static final SupplyTracker.Classifier CLASSIFIER = id ->
	{
		if (id == ItemID.PIEDISH)
		{
			return SupplyTracker.classify(id, "Pie dish", NONE, false, false, false);
		}
		if (id == ItemID.SHARK || SupplyTracker.MULTI_BITE_FOOD.containsKey(id))
		{
			return SupplyTracker.classify(id, "Food " + id, EAT, false, false, false);
		}
		return SupplyTracker.classify(id, "Other", NONE, false, false, false);
	};

	private SupplyTracker supplies;

	@Before
	public void setUp()
	{
		supplies = new SupplyTracker(CLASSIFIER);
	}

	private SupplyTracker.Usage tick(int... idQty)
	{
		return supplies.update(SupplyTrackerTest.obs(idQty), true, false, Collections.emptySet());
	}

	@Test
	public void itemIdsMatchTheGameValues()
	{
		// Checked against net.runelite.api.gameval.ItemID in RuneLite 1.13.4.
		assertEquals(2289, ItemID.PLAIN_PIZZA);
		assertEquals(2291, ItemID.HALF_PLAIN_PIZZA);
		assertEquals(2293, ItemID.MEAT_PIZZA);
		assertEquals(2295, ItemID.HALF_MEAT_PIZZA);
		assertEquals(2297, ItemID.ANCHOVIE_PIZZA);
		assertEquals(2299, ItemID.HALF_ANCHOVIE_PIZZA);
		assertEquals(2301, ItemID.PINEAPPLE_PIZZA);
		assertEquals(2303, ItemID.HALF_PINEAPPLE_PIZZA);
		assertEquals(2323, ItemID.APPLE_PIE);
		assertEquals(2325, ItemID.REDBERRY_PIE);
		assertEquals(2327, ItemID.MEAT_PIE);
		assertEquals(2331, ItemID.HALF_A_MEAT_PIE);
		assertEquals(2333, ItemID.HALF_A_REDBERRY_PIE);
		assertEquals(2335, ItemID.HALF_AN_APPLE_PIE);
		assertEquals(7178, ItemID.GARDEN_PIE);
		assertEquals(7180, ItemID.HALF_GARDEN_PIE);
		assertEquals(7188, ItemID.FISH_PIE);
		assertEquals(7190, ItemID.HALF_FISH_PIE);
		assertEquals(7198, ItemID.ADMIRAL_PIE);
		assertEquals(7200, ItemID.HALF_ADMIRAL_PIE);
		assertEquals(7208, ItemID.WILD_PIE);
		assertEquals(7210, ItemID.HALF_WILD_PIE);
		assertEquals(7218, ItemID.SUMMER_PIE);
		assertEquals(7220, ItemID.HALF_SUMMER_PIE);
		assertEquals(19662, ItemID.BOTANICAL_PIE);
		assertEquals(19659, ItemID.HALF_BOTANICAL_PIE);
		assertEquals(21690, ItemID.MUSHROOM_PIE);
		assertEquals(21687, ItemID.HALF_MUSHROOM_PIE);
		assertEquals(22795, ItemID.DRAGONFRUIT_PIE);
		assertEquals(22792, ItemID.HALF_DRAGONFRUIT_PIE);
		assertEquals(1891, ItemID.CAKE);
		assertEquals(1893, ItemID.PARTIAL_CAKE);
		assertEquals(1895, ItemID.CAKE_SLICE);
		assertEquals(1897, ItemID.CHOCOLATE_CAKE);
		assertEquals(1899, ItemID.PARTIAL_CHOCOLATE_CAKE);
		assertEquals(1901, ItemID.CHOCOLATE_SLICE);
		assertEquals(2313, ItemID.PIEDISH);
	}

	@Test
	public void tableHoldsEveryStageWithItsBites()
	{
		assertEquals(4 * 2 + 11 * 2 + 2 * 3, SupplyTracker.MULTI_BITE_FOOD.size());
		assertArrayEquals(new int[]{ItemID.PLAIN_PIZZA, 2, 2}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.PLAIN_PIZZA));
		assertArrayEquals(new int[]{ItemID.PLAIN_PIZZA, 1, 2}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.HALF_PLAIN_PIZZA));
		assertArrayEquals(new int[]{ItemID.MEAT_PIE, 1, 2}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.HALF_A_MEAT_PIE));
		assertArrayEquals(new int[]{ItemID.CAKE, 3, 3}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.CAKE));
		assertArrayEquals(new int[]{ItemID.CAKE, 2, 3}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.PARTIAL_CAKE));
		assertArrayEquals(new int[]{ItemID.CAKE, 1, 3}, SupplyTracker.MULTI_BITE_FOOD.get(ItemID.CAKE_SLICE));
		assertArrayEquals(new int[]{ItemID.CHOCOLATE_CAKE, 1, 3},
			SupplyTracker.MULTI_BITE_FOOD.get(ItemID.CHOCOLATE_SLICE));
		assertFalse("the pie dish is not food", SupplyTracker.MULTI_BITE_FOOD.containsKey(ItemID.PIEDISH));
		assertFalse("noted food is never a supply", SupplyTracker.MULTI_BITE_FOOD.containsKey(ItemID.Cert.PLAIN_PIZZA));
	}

	@Test
	public void classifiedByIdAsFoodInBites()
	{
		SupplyTracker.ItemInfo half = CLASSIFIER.classify(ItemID.HALF_MEAT_PIZZA);
		assertEquals(SupplyTracker.Category.FOOD, half.getCategory());
		assertEquals(1, half.getDoses());
		assertEquals(ItemID.MEAT_PIZZA, half.getFullItemId());
		assertEquals(2, half.getDosesPerItem());
		assertEquals(CLASSIFIER.classify(ItemID.MEAT_PIZZA).getFamily(), half.getFamily());
		SupplyTracker.ItemInfo shark = CLASSIFIER.classify(ItemID.SHARK);
		assertNull("ordinary food is counted per item", shark.getFamily());
		assertEquals(SupplyTracker.Category.OTHER, CLASSIFIER.classify(ItemID.PIEDISH).getCategory());
	}

	@Test
	public void eatingAWholePizzaCostsExactlyOnePizza()
	{
		tick(ItemID.PLAIN_PIZZA, 1);
		SupplyTracker.Usage first = tick(ItemID.HALF_PLAIN_PIZZA, 1);
		SupplyTracker.Usage second = tick();

		ItemTally used = new ItemTally();
		Map<Integer, Integer> doses = new HashMap<>();
		for (SupplyTracker.Usage usage : new SupplyTracker.Usage[]{first, second})
		{
			used.merge(usage.getUsed());
			doses.putAll(usage.getDoses());
		}
		assertEquals("two bites, recorded under the full pizza", 2, used.get(ItemID.PLAIN_PIZZA));
		assertEquals("the half pizza is not an item of its own", 0, used.get(ItemID.HALF_PLAIN_PIZZA));
		assertEquals(1, used.size());
		assertEquals(Integer.valueOf(2), doses.get(ItemID.PLAIN_PIZZA));

		// Valued at exactly one pizza (not a pizza plus a half pizza, as before).
		Map<Integer, Long> prices = new HashMap<>();
		prices.put(ItemID.PLAIN_PIZZA, 300L);
		prices.put(ItemID.HALF_PLAIN_PIZZA, 150L);
		assertEquals(300L, ItemValuation.total(used, prices, doses));
	}

	@Test
	public void aHalfPizzaHeldAtSessionStartCostsHalf()
	{
		tick(ItemID.HALF_ANCHOVIE_PIZZA, 1, ItemID.SHARK, 2);
		SupplyTracker.Usage usage = tick(ItemID.SHARK, 2);
		assertEquals(1, usage.getUsed().get(ItemID.ANCHOVIE_PIZZA));
		assertEquals(Integer.valueOf(2), usage.getDoses().get(ItemID.ANCHOVIE_PIZZA));
		Map<Integer, Long> prices = Collections.singletonMap(ItemID.ANCHOVIE_PIZZA, 401L);
		assertEquals("half of 401, rounded", 201L, ItemValuation.total(usage.getUsed(), prices, usage.getDoses()));
	}

	@Test
	public void eatingAPieLeavesTheDishUncounted()
	{
		tick(ItemID.MEAT_PIE, 2);
		assertEquals(1, tick(ItemID.MEAT_PIE, 1, ItemID.HALF_A_MEAT_PIE, 1).getUsed().get(ItemID.MEAT_PIE));
		SupplyTracker.Usage last = tick(ItemID.MEAT_PIE, 1, ItemID.PIEDISH, 1);
		assertEquals(1, last.getUsed().get(ItemID.MEAT_PIE));
		assertEquals(1, last.getUsed().size());
		assertTrue("the dish is no return", last.getReturned().isEmpty());
	}

	@Test
	public void aCakeIsThreeBites()
	{
		tick(ItemID.CHOCOLATE_CAKE, 1);
		ItemTally used = new ItemTally();
		Map<Integer, Integer> doses = new HashMap<>();
		for (int[] after : new int[][]{{ItemID.PARTIAL_CHOCOLATE_CAKE, 1}, {ItemID.CHOCOLATE_SLICE, 1}, {}})
		{
			SupplyTracker.Usage usage = tick(after);
			used.merge(usage.getUsed());
			doses.putAll(usage.getDoses());
		}
		assertEquals(3, used.get(ItemID.CHOCOLATE_CAKE));
		assertEquals(Integer.valueOf(3), doses.get(ItemID.CHOCOLATE_CAKE));
		assertEquals(900L, ItemValuation.total(used, Collections.singletonMap(ItemID.CHOCOLATE_CAKE, 900L), doses));
	}

	@Test
	public void differentFoodsAreSeparateAndSlicesAreNotCake()
	{
		tick(ItemID.PLAIN_PIZZA, 1, ItemID.MEAT_PIZZA, 1, ItemID.CAKE_SLICE, 1);
		SupplyTracker.Usage usage = tick(ItemID.HALF_PLAIN_PIZZA, 1, ItemID.MEAT_PIZZA, 1);
		assertEquals(1, usage.getUsed().get(ItemID.PLAIN_PIZZA));
		assertEquals(0, usage.getUsed().get(ItemID.MEAT_PIZZA));
		assertEquals("a slice is one bite of a cake", 1, usage.getUsed().get(ItemID.CAKE));
	}

	@Test
	public void droppingAPartNetsNothing()
	{
		tick(ItemID.PLAIN_PIZZA, 1, ItemID.HALF_PLAIN_PIZZA, 1);
		SupplyTracker.Usage usage = supplies.update(SupplyTrackerTest.obs(ItemID.PLAIN_PIZZA, 1), true, false,
			Collections.singleton(ItemID.HALF_PLAIN_PIZZA));
		assertTrue(usage.isEmpty());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

/**
 * The notable drop line ({@link NotableDropMessage}): the two variants by kill number, the "paid for" clause only when
 * it is true, which drop of a kill it names, the NPC's article, quantities, a long name and the chat message's
 * escaping.
 */
public class NotableDropMessageTest
{
	private static final NotableDrop CHAINBODY = NotableDrop.item(3140, "Dragon chainbody", 1, 148_000L, 72_000L, 0);
	private static final NotableDrop WHIP = NotableDrop.item(4151, "Abyssal whip", 1, 1_400_000L, 72_000L, 0);

	@Test
	public void theDesignShapes()
	{
		assertEquals("Dragon chainbody (148K) from a dust devil. That's the task paid for.",
			NotableDropMessage.line(CHAINBODY, LootPriceMode.GE, "Dust devil", 141, 201, true));
		assertEquals("Abyssal whip (1.4M) at kill 140 of 201.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, "Abyssal demon", 140, 201, false));
	}

	@Test
	public void theVariantFollowsTheKillNumber()
	{
		// Odd: where it came from; even: the kill number. The same kill always gives the same line.
		assertEquals("Abyssal whip (1.4M) from an abyssal demon.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, "Abyssal demon", 139, 201, false));
		assertEquals("Abyssal whip (1.4M) at kill 140 of 201.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, "Abyssal demon", 140, 201, false));
		assertEquals("Abyssal whip (1.4M) from an abyssal demon.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, "Abyssal demon", 141, 201, false));
		// Kill numbers have commas.
		assertEquals("Abyssal whip (1.4M) at kill 1,000 of 1,200.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, "Abyssal demon", 1_000, 1_200, false));
		// The kill number unknown (0), or past the task's size: where it came from.
		assertEquals("Abyssal whip (1.4M) from an abyssal demon.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, "Abyssal demon", 0, 0, false));
		assertEquals("Abyssal whip (1.4M) from an abyssal demon.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, "Abyssal demon", 202, 201, false));
	}

	@Test
	public void withoutTheNpcsName()
	{
		assertEquals("the kill number on an odd kill too", "Abyssal whip (1.4M) at kill 139 of 201.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, null, 139, 201, false));
		assertEquals("Abyssal whip (1.4M).", NotableDropMessage.line(WHIP, LootPriceMode.GE, "  ", 0, 0, false));
		assertEquals("Abyssal whip (1.4M). That's the task paid for.",
			NotableDropMessage.line(WHIP, LootPriceMode.GE, null, 0, 0, true));
	}

	@Test
	public void theNpcsArticleAndBosses()
	{
		assertEquals("a dust devil", NotableDropMessage.source("Dust devil"));
		assertEquals("an abyssal demon", NotableDropMessage.source("Abyssal demon"));
		assertEquals("a greater nechryael", NotableDropMessage.source("Greater Nechryael"));
		assertEquals("an ankou", NotableDropMessage.source("<col=ffff00>Ankou</col>"));
		// A Slayer boss goes by its own name.
		assertEquals("Cerberus", NotableDropMessage.source("Cerberus"));
		assertEquals("Abyssal Sire", NotableDropMessage.source("Abyssal Sire"));
		assertNull(NotableDropMessage.source(null));
		assertEquals("Primordial crystal (28.1M) from Cerberus.", NotableDropMessage.line(
			NotableDrop.item(13231, "Primordial crystal", 1, 28_100_000L, 120_000L, 0), LootPriceMode.GE, "Cerberus", 3,
			5, false));
	}

	@Test
	public void quantitiesAndThePriceMode()
	{
		NotableDrop bars = NotableDrop.item(2363, "Runite bar", 25, 300_000L, 192_000L, 0);

		assertEquals("Runite bar x25 (300K) from a kurask.",
			NotableDropMessage.line(bars, LootPriceMode.GE, "Kurask", 1, 0, false));
		assertEquals("Runite bar x25 (192K) from a kurask.",
			NotableDropMessage.line(bars, LootPriceMode.HIGH_ALCH, "Kurask", 1, 0, false));
		assertEquals("Runite bar x1,500 (18M) from a kurask.", NotableDropMessage.line(
			NotableDrop.item(2363, "Runite bar", 1_500, 18_000_000L, null, 0), LootPriceMode.GE, "Kurask", 1, 0, false));
		// No value in the mode or no name: no line.
		assertNull(NotableDropMessage.line(NotableDrop.item(2363, "Runite bar", 25, 300_000L, null, 0),
			LootPriceMode.HIGH_ALCH, "Kurask", 1, 0, false));
		assertNull(NotableDropMessage.line(NotableDrop.item(2363, null, 25, 300_000L, null, 0), LootPriceMode.GE,
			"Kurask", 1, 0, false));
	}

	@Test
	public void theTaskIsPaidForOnlyWhenTheDropCoversTheSuppliesSoFar()
	{
		assertTrue(NotableDropMessage.paysForTask(148_000, 148_000L));
		assertTrue(NotableDropMessage.paysForTask(148_000, 90_000L));
		assertFalse("more than the drop", NotableDropMessage.paysForTask(148_000, 148_001L));
		assertFalse("no supplies used: nothing to pay for", NotableDropMessage.paysForTask(148_000, 0L));
		assertFalse("cost unknown or approximate", NotableDropMessage.paysForTask(148_000, null));

		assertEquals("Dragon chainbody (148K) from a dust devil.",
			NotableDropMessage.line(CHAINBODY, LootPriceMode.GE, "Dust devil", 141, 201, false));
	}

	@Test
	public void oneLinePerKillForItsMostValuableItem()
	{
		NotableDrop pet = NotableDrop.pet(NotableDrop.Pet.RECEIVED, 0);
		NotableDrop unnamed = NotableDrop.item(1, null, 1, 9_000_000L, null, 0);

		assertSame(WHIP, NotableDropMessage.pick(Arrays.asList(CHAINBODY, pet, WHIP, unnamed), LootPriceMode.GE));
		// At high alch the two are equal: the first.
		assertSame(CHAINBODY, NotableDropMessage.pick(Arrays.asList(CHAINBODY, WHIP), LootPriceMode.HIGH_ALCH));
		assertNull("a pet gets no line", NotableDropMessage.pick(Collections.singletonList(pet), LootPriceMode.GE));
		assertNull(NotableDropMessage.pick(null, LootPriceMode.GE));
	}

	@Test
	public void aLongNameStaysWhole()
	{
		NotableDrop drop = NotableDrop.item(1, "Imbued heart", 1, 3_000_000L, null, 0);
		assertEquals("Imbued heart (3M) from a thermonuclear smoke devil's long lost cousin.",
			NotableDropMessage.line(drop, LootPriceMode.GE, "Thermonuclear smoke devil's long lost cousin", 1, 0,
				false));
	}

	@Test
	public void theChatMessageHighlightsTheItemAndEscapesNames()
	{
		assertEquals("<colHIGHLIGHT>Dragon chainbody (148K)<colNORMAL> from a dust devil. That's the task paid for.",
			NotableDropMessage.chatMessage(CHAINBODY, LootPriceMode.GE, "Dust devil", 141, 201, true));
		NotableDrop tagged = NotableDrop.item(1, "Odd <b>item", 1, 200_000L, null, 0);
		assertEquals("<colHIGHLIGHT>Odd <lt>b<gt>item (200K)<colNORMAL> at kill 2 of 10.",
			NotableDropMessage.chatMessage(tagged, LootPriceMode.GE, null, 2, 10, false));
		assertNull(NotableDropMessage.chatMessage(null, LootPriceMode.GE, null, 2, 10, false));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link NotableDrops} and {@link NotableDrop}: which loot stacks are notable at a threshold and price mode, the cap
 * per task, order, text, and how they go through the session, snapshots, records and JSON.
 */
public class NotableDropsTest
{
	private static final int WHIP = 4151;
	private static final int KEY = 23083;
	private static final int BAR = 2363;
	private static final int UNPRICED = 11840;
	private static final long TIME = 1_000L;

	private final Gson gson = new Gson();
	private ItemValuation.UnitPrices prices;

	@Before
	public void setUp()
	{
		prices = new ItemValuation.UnitPrices();
		prices.getGe().put(WHIP, 1_500_000L);
		prices.getHa().put(WHIP, 72_000L);
		// Untradeable: a GE price of 0, valued at its high alch value in GE mode.
		prices.getGe().put(KEY, 0L);
		prices.getHa().put(KEY, 120_000L);
		prices.getGe().put(BAR, 12_000L);
		prices.getHa().put(BAR, 7_500L);
		// GE price unavailable.
		prices.getGeMissing().add(UNPRICED);
		prices.getHa().put(UNPRICED, 300_000L);
	}

	private static ItemTally tally(long... idQuantityPairs)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQuantityPairs.length; i += 2)
		{
			t.add((int) idQuantityPairs[i], idQuantityPairs[i + 1]);
		}
		return t;
	}

	private List<NotableDrop> find(ItemTally drop, LootPriceMode mode, long threshold)
	{
		return NotableDrops.find(drop, prices, mode, threshold, id -> "Item " + id, TIME);
	}

	private static NotableDrop item(int id, long value, long time)
	{
		return NotableDrop.item(id, "Item " + id, 1, value, value, time);
	}

	@Test
	public void stackAtTheThresholdIsNotable()
	{
		assertEquals(1, find(tally(BAR, 25), LootPriceMode.GE, 300_000).size());
		assertTrue("1 gp below", find(tally(BAR, 25), LootPriceMode.GE, 300_001).isEmpty());
		NotableDrop bars = find(tally(BAR, 25), LootPriceMode.GE, 300_000).get(0);
		assertEquals(Integer.valueOf(BAR), bars.getItemId());
		assertEquals("Item " + BAR, bars.getName());
		assertEquals(25, bars.getQuantity());
		assertEquals(Long.valueOf(300_000), bars.getGeValue());
		assertEquals(Long.valueOf(187_500), bars.getHaValue());
		assertEquals(TIME, bars.getTime());
		assertFalse(bars.isPet());
	}

	@Test
	public void valuedInTheLootPriceMode()
	{
		List<NotableDrop> ge = find(tally(WHIP, 1, KEY, 1, BAR, 1, UNPRICED, 1), LootPriceMode.GE, 100_000);
		assertEquals("whip, and the untradeable key at its high alch value; not the unpriced item", 2, ge.size());
		assertEquals(Integer.valueOf(WHIP), ge.get(0).getItemId());
		assertEquals(Integer.valueOf(KEY), ge.get(1).getItemId());
		assertEquals(Long.valueOf(120_000), ge.get(1).getGeValue());

		List<NotableDrop> ha = find(tally(WHIP, 1, KEY, 1, BAR, 1, UNPRICED, 1), LootPriceMode.HIGH_ALCH, 100_000);
		assertEquals(2, ha.size());
		// In item id order.
		assertEquals(Integer.valueOf(UNPRICED), ha.get(0).getItemId());
