		List<OverallTotals.Entry> masters = TestTotals.summarize(Arrays.asList(konar, unknownMasterAndDate),
			OverallTotals.Grouping.MASTER, LootPriceMode.GE, Collections.emptyMap(), ZoneId.of("America/Los_Angeles"));
