		}

		/**
		 * Each visible entry's rows below its title line, as {@code "<label>"}: the left-hand label of each, in order,
		 * so a test can see that a grouping's blocks have the same rows.
		 */
		List<List<String>> getRowLabels()
		{
			List<List<String>> labels = new ArrayList<>();
			for (Component entry : panels(list()))
			{
				List<String> rows = new ArrayList<>();
				Component[] lines = ((Container) entry).getComponents();
				for (int i = 1; i < lines.length; i++)
				{
					if (!"totals.items".equals(lines[i].getName()))
					{
						rows.add(text(((Container) lines[i]).getComponent(0)));
					}
				}
				labels.add(rows);
			}
			return labels;
		}

		/**
		 * The text colours of the visible entry {@code index}'s lines, in the order {@link #getRows} reads them: per
		 * line, the colours of its labels left to right.
		 */
		List<List<Color>> getLineColors(int index)
		{
			List<List<Color>> colors = new ArrayList<>();
			for (Component line : entry(index).getComponents())
			{
				if ("totals.items".equals(line.getName()))
				{
					continue;
				}
				List<Color> parts = new ArrayList<>();
				for (Component part : ((Container) line).getComponents())
				{
					parts.add(part.getForeground());
				}
				colors.add(parts);
			}
			return colors;
		}

		/**
		 * Lays the panel out at the sidebar's width ({@code PluginPanel.PANEL_WIDTH}), as the player sees it, and
		 * returns the totals list's width.
		 */
		int layOut()
		{
			panel.setSize(PluginPanel.PANEL_WIDTH, 4000);
			SwingLookup.layOut(panel);
			return list().getWidth();
		}

		/** After {@link #layOut}: each visible entry's name as shown, whole or cut short with {@link FitLabel#ELLIPSIS}. */
		List<String> getNamesShown()
		{
			List<String> names = new ArrayList<>();
			for (Component entry : panels(list()))
			{
				names.add(((JLabel) find((Container) entry, "totals.name")).getText());
			}
			return names;
		}

		/**
		 * After {@link #layOut}: the lines of the visible entries (title and rows, as {@link #getRows} reads them)
		 * whose parts don't fit side by side in the list: a part past the line's right edge, or the value on the right
		 * over the label on the left. Empty when every line fits.
		 */
		List<String> getLinesThatDontFit()
		{
			List<String> crowded = new ArrayList<>();
			int width = list().getWidth();
			for (Component entry : panels(list()))
			{
				for (Component line : ((Container) entry).getComponents())
				{
					if ("totals.items".equals(line.getName()))
					{
						continue;
					}
					Component[] parts = ((Container) line).getComponents();
					Component first = parts[0];
					Component last = parts[parts.length - 1];
					boolean overlaps = parts.length > 1 && first.getX() + first.getWidth() > last.getX();
					if (overlaps || entry.getX() + line.getX() + last.getX() + last.getWidth() > width)
					{
						crowded.add(lineText(line));
					}
				}
			}
			return crowded;
		}

		/** The Group choices, in order, as the combo box shows them. */
		List<String> getGroupings()
		{
			@SuppressWarnings("unchecked")
			JComboBox<OverallTotals.Grouping> box = (JComboBox<OverallTotals.Grouping>) part("grouping");
			return items(box, String::valueOf);
		}

		/** The visible entry {@code index} (its lines and grids). */
		private Container entry(int index)
		{
			List<Container> entries = new ArrayList<>();
			for (Component component : list().getComponents())
			{
				if (component instanceof JPanel)
				{
					entries.add((Container) component);
				}
			}
			return entries.get(index);
		}

		/** The tooltip of each visible entry. */
		List<String> getTooltips()
		{
			return rowTooltips(list());
		}

		/** How many times the rows were built (performance seam). */
		int getBuildCount()
		{
			return panel.getOverallTotalsBuildCount();
		}
	}

	/** The Skipped / blocked section. */
	static final class AssignmentsProbe extends CollapsibleProbe
	{
		private final Function<Icon, String> iconText;

		AssignmentsProbe(SlayerLedgerPanel panel, Function<Icon, String> iconText)
		{
			super(panel, "assignments");
			this.iconText = iconText;
		}

		/** What the icon before each shown row's monster shows, in order ({@link PanelProbe#iconText}). */
		List<String> getNameIcons()
		{
			return labelIcons(panels(list()), "assignments.name", iconText);
		}

		/** The width the shown rows want, to check that they fit the sidebar ({@code PluginPanel.PANEL_WIDTH}). */
		int getListPreferredWidth()
		{
			return list().getPreferredSize().width;
		}

		/** Skipped / blocked listens on its header only; its title isn't clickable, so use {@link #toggle()}. */
		@Override
		void clickTitle()
		{
			throw new UnsupportedOperationException("Skipped / blocked has no clickable title; use toggle()");
		}

		/** The header, as {@code "Skipped / blocked (n) | Show"}. */
		String getHeaderText()
		{
			return text(part("title")) + " | " + text(part("toggle"));
		}

		/**
		 * Each row shown, in order, as {@code "<monster> | <outcome> | <date · master> | <tooltip>"}: its lines'
		 * labels, the first line's then the second's (when the row has one), then its tooltip; empty while closed.
		 */
		List<String> getRows()
		{
			List<String> rows = new ArrayList<>();
			for (Component c : list().getComponents())
			{
				if (c instanceof JPanel)
				{
					List<String> lines = new ArrayList<>();
					for (Component line : ((Container) c).getComponents())
					{
						lines.add(lineText(line));
					}
					rows.add(String.join(" | ", lines) + " | " + ((JPanel) c).getToolTipText());
				}
			}
			return rows;
		}

		/** The one line shown instead of the rows while there are none, or {@code null} while rows (or none) show. */
		String getEmptyText()
		{
			Component empty = findOrNull(list(), "assignments.empty");
			return empty == null ? null : text(empty);
		}

		/** Whether the hint above the rows ("Not counted as played tasks.", how to delete) is shown (set visible). */
		boolean isHintShown()
		{
			return part("hint").isVisible();
		}

		/**
		 * Lays the panel out at the sidebar's width ({@code PluginPanel.PANEL_WIDTH}), as the player sees it, and
		 * returns the list's width.
		 */
		int layOut()
		{
			panel.setSize(PluginPanel.PANEL_WIDTH, 4000);
			SwingLookup.layOut(panel);
			return list().getWidth();
		}

		/**
		 * After {@link #layOut}: each row's monster as shown, whole or cut short with {@link FitLabel#ELLIPSIS}, then
		 * {@code " | "} and its outcome, with {@code " (fits)"} when the outcome sits right of the monster inside the
		 * row.
		 */
		List<String> getFirstLinesShown()
		{
			List<String> lines = new ArrayList<>();
			for (Component row : panels(list()))
			{
				Container first = (Container) ((Container) row).getComponent(0);
				Component name = first.getComponent(0);
				Component outcome = first.getComponent(1);
				boolean fits = name.getX() + name.getWidth() <= outcome.getX()
					&& outcome.getX() + outcome.getWidth() <= first.getWidth();
				lines.add(text(name) + " | " + text(outcome) + (fits ? " (fits)" : ""));
			}
			return lines;
		}

		/** The text colours of the shown row {@code index}'s labels, in the order {@link #getRows} reads them. */
		List<Color> getRowColors(int index)
		{
			List<Color> colors = new ArrayList<>();
			for (Component line : ((Container) panels(list()).get(index)).getComponents())
			{
				for (Component label : ((Container) line).getComponents())
				{
					colors.add(label.getForeground());
				}
			}
			return colors;
		}

		/**
		 * The right-click menu items of the shown row {@code index}, as {@code "Delete entry"}, or
		 * {@code "-Delete entry"} when disabled.
		 */
		List<String> getMenuItems(int index)
		{
			List<String> items = new ArrayList<>();
			for (Component c : ((JComponent) panels(list()).get(index)).getComponentPopupMenu().getComponents())
			{
				if (c instanceof JMenuItem)
				{
					items.add((c.isEnabled() ? "" : "-") + ((JMenuItem) c).getText());
				}
			}
			return items;
		}

		/**
		 * The menu a right-click on each label of the shown row {@code index} opens (Swing shows a component's
		 * {@link JComponent#getComponentPopupMenu}), in the order {@link #getRows} reads them, as
		 * {@code "<label text>: row menu"} when it is the row's own menu, else {@code ": other menu"} or
		 * {@code ": no menu"}.
		 */
		List<String> getLabelMenus(int index)
		{
			JComponent row = (JComponent) panels(list()).get(index);
			List<String> menus = new ArrayList<>();
			for (Component line : row.getComponents())
			{
				for (Component label : ((Container) line).getComponents())
				{
					JPopupMenu menu = ((JComponent) label).getComponentPopupMenu();
					menus.add(text(label) + ": " + (menu == null ? "no menu"
						: menu == row.getComponentPopupMenu() ? "row menu" : "other menu"));
				}
			}
			return menus;
		}

		/** The background of the shown row {@code index}: the page, or the hover colour under the mouse. */
		Color getRowBackground(int index)
		{
			return panels(list()).get(index).getBackground();
		}

		/** Moves the mouse onto ({@code true}) or off the shown row {@code index}, as the player does. */
		void hoverRow(int index, boolean on)
		{
			Component row = panels(list()).get(index);
			row.dispatchEvent(new MouseEvent(row, on ? MouseEvent.MOUSE_ENTERED : MouseEvent.MOUSE_EXITED,
				System.currentTimeMillis(), 0, 1, 1, 0, false));
		}

		/** How many times the rows were built (performance seam). */
		int getBuildCount()
		{
			return panel.getAssignmentsBuildCount();
		}
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/** {@link PetMessage}: the three pet messages core ScreenshotPlugin uses, with and without colour tags. */
public class PetMessageTest
{
	@Test
	public void recognisesThePetMessages()
	{
		assertEquals(NotableDrop.Pet.RECEIVED, PetMessage.parse(true,
			"<col=ef1020>You have a funny feeling like you're being followed.</col>"));
		assertEquals(NotableDrop.Pet.RECEIVED, PetMessage.parse(true,
			"You feel something weird sneaking into your backpack."));
		assertEquals(NotableDrop.Pet.DUPLICATE, PetMessage.parse(true,
			"<col=ef1020>You have a funny feeling like you would have been followed...</col>"));
	}

	@Test
	public void ignoresJagexColourMarkup()
	{
		assertEquals(NotableDrop.Pet.RECEIVED,
			PetMessage.parse(true, "@mes_hl_red@You have a funny feeling like you're being followed.</col>"));
	}

	@Test
	public void ignoresOtherMessages()
	{
		assertNull("wrong chat type", PetMessage.parse(false, "You have a funny feeling like you're being followed."));
		assertNull(PetMessage.parse(true, null));
		assertNull("quoting it", PetMessage.parse(true, "He said You have a funny feeling like you're being followed"));
		assertNull("another player's broadcast", PetMessage.parse(true,
			"Zezima has a funny feeling like he's being followed: Pet kraken at 1,000 kills."));
		assertNull(PetMessage.parse(true, "A superior foe has appeared..."));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Which of the player's attacks each of their hitsplats is put down to ({@link PlayerAttacks}), with the real hit
 * timing on an NPC (OSRS Wiki, "Hit delay", one tick later than each weapon's own delay): a melee attack's hits on the
 * tick after it (a multi-hit special's last ones the tick after that), a ranged or magic attack's 2 to 6 ticks after
 * it; only an attack on that NPC, apart from a Burst's, Barrage's or chinchompa's splash on the tick its target was hit;
 * and none for a hitsplat with no attack on its NPC around it (a cannon's). Swaps respect the weapons' attack speeds.
 */
public class PlayerAttacksTest
{
	private static final long TARGET = DamagedNpcs.key(-1, 1);
	private static final long OTHER = DamagedNpcs.key(-1, 2);
	private static final long THIRD = DamagedNpcs.key(-1, 3);

	private final PlayerAttacks attacks = new PlayerAttacks();

	private void attack(int tick, SetupStyle style, long target)
	{
		attacks.add(tick, style, tick * 600L, target, style == SetupStyle.BARRAGE);
	}

	private SetupStyle styleFor(int hitTick, long npc)
	{
		final PlayerAttacks.Attack attack = attacks.forHit(hitTick, npc);
		return attack == null ? null : attack.getStyle();
	}

	@Test
	public void aMeleeHitLandsTheTickAfterItsAttack()
	{
		attack(100, SetupStyle.MELEE, TARGET);
		assertNull("not on the attack's own tick", styleFor(100, TARGET));
		assertEquals(SetupStyle.MELEE, styleFor(101, TARGET));
		assertEquals(60_000, attacks.forHit(101, TARGET).getAt());
		assertNull("never before the attack", styleFor(99, TARGET));
	}

	@Test
	public void theDragonClawsHitOnTheTwoTicksAfterTheSpecialAttack()
	{
		attack(100, SetupStyle.MELEE, TARGET);
		for (int hit = 0; hit < 2; hit++)
		{
			assertEquals("the first two hits", SetupStyle.MELEE, styleFor(101, TARGET));
			assertEquals("the last two hits", SetupStyle.MELEE, styleFor(102, TARGET));
		}
		assertNull("not three ticks later", styleFor(103, TARGET));
	}

	@Test
	public void theClawsAfterABlowpipeDartAreMelee()
	{
		// A dart on 98 (its hit on 100), then the claws as soon as the blowpipe allows, 2 ticks later.
		attack(98, SetupStyle.RANGED, TARGET);
		attack(100, SetupStyle.MELEE, TARGET);
		assertEquals("the dart's hit", SetupStyle.RANGED, styleFor(100, TARGET));
		assertEquals(SetupStyle.MELEE, styleFor(101, TARGET));
		assertEquals("the claws' last hits, not the dart", SetupStyle.MELEE, styleFor(102, TARGET));
	}

	@Test
	public void aRangedOrMagicHitLandsTwoToSixTicksAfterItsAttack()
	{
		attack(100, SetupStyle.BARRAGE, TARGET);
		assertNull("not on its own tick", styleFor(100, TARGET));
		assertNull("not the tick after", styleFor(101, TARGET));
		for (int tick = 100 + PlayerAttacks.RANGED_EARLIEST; tick <= 100 + PlayerAttacks.RANGED_LATEST; tick++)
		{
			assertEquals(SetupStyle.BARRAGE, styleFor(tick, TARGET));
		}
		assertNull(styleFor(101 + PlayerAttacks.RANGED_LATEST, TARGET));
		assertEquals(2, PlayerAttacks.RANGED_EARLIEST);
		assertEquals(6, PlayerAttacks.RANGED_LATEST);
	}

	@Test
	public void aDartsHitAfterASwapToAWhipIsStillRanged()
	{
		// A blowpipe dart on 100, a swap, then a whip as soon as the blowpipe allows: 2 ticks later.
		attack(100, SetupStyle.RANGED, TARGET);
		attack(102, SetupStyle.MELEE, TARGET);
		assertEquals("the dart's hit on 102", SetupStyle.RANGED, styleFor(102, TARGET));
		assertEquals("the whip's hit on 103", SetupStyle.MELEE, styleFor(103, TARGET));
	}

	@Test
	public void aWhipsHitAfterATridentsCastIsMelee()
	{
		// A trident's cast on 100, then a whip as soon as the trident allows: 4 ticks later.
		attack(100, SetupStyle.MAGIC, TARGET);
		attack(104, SetupStyle.MELEE, TARGET);
		assertEquals("the trident's hit", SetupStyle.MAGIC, styleFor(103, TARGET));
		assertEquals("the whip's hit on 105", SetupStyle.MELEE, styleFor(105, TARGET));
	}

	@Test
	public void theLatestRangedOrMagicAttackOnTheNpcWins()
	{
		attack(100, SetupStyle.MAGIC, TARGET);
		attack(104, SetupStyle.BARRAGE, TARGET);
		assertEquals(SetupStyle.MAGIC, styleFor(105, TARGET));
		assertEquals(SetupStyle.BARRAGE, styleFor(106, TARGET));
	}

	@Test
	public void onlyAnAttackOnTheNpcLandsItsHits()
	{
		attack(100, SetupStyle.RANGED, TARGET);
		attack(102, SetupStyle.MELEE, OTHER);
		assertNull("the cannon's hit on another NPC while blowpiping", styleFor(102, OTHER));
		assertNull("or on the tick of a melee hit on its target", styleFor(103, THIRD));
		assertEquals(SetupStyle.RANGED, styleFor(103, TARGET));
		assertEquals(SetupStyle.MELEE, styleFor(103, OTHER));
	}

	@Test
	public void aBarragesSplashCountsOnlyOnTheTickItsTargetWasHit()
	{
		attack(100, SetupStyle.BARRAGE, TARGET);
		// Its hits on all the NPCs it hits land together on 103: the target's first.
		assertEquals(SetupStyle.BARRAGE, styleFor(103, TARGET));
		assertNull("no attack on the other NPC", attacks.forHit(103, OTHER));
		assertEquals(SetupStyle.BARRAGE, attacks.forSplashHit(103).getStyle());
		assertNull("the cannon's hit on another NPC on another tick", attacks.forSplashHit(102));
		assertNull(attacks.forSplashHit(104));
	}

	@Test
	public void aChinchompaSplashesAndABlowpipeDoesNot()
	{
		// A chinchompa on 100, then a dart at another NPC when the chinchompa allows (3 ticks on rapid).
		attacks.add(100, SetupStyle.RANGED, 60_000, TARGET, true);
		attacks.add(103, SetupStyle.RANGED, 61_800, OTHER, false);
		assertEquals(SetupStyle.RANGED, styleFor(102, TARGET));
		assertEquals("its splash", 100, attacks.forSplashHit(102).getTick());
		assertEquals(SetupStyle.RANGED, styleFor(105, OTHER));
		assertNull("a dart hits its target alone", attacks.forSplashHit(105));
	}

	@Test
	public void aHitWithNoAttackOnItsNpcAroundItHasNone()
	{
		assertNull("a cannon's hit", attacks.forHit(100, TARGET));
		assertNull(attacks.forSplashHit(100));
		attack(100, SetupStyle.RANGED, TARGET);
		assertNull("long after", attacks.forHit(200, TARGET));
	}

	@Test
	public void attacksWithoutAStyleOrOutOfOrderAreIgnored()
	{
		attacks.add(100, null, 1_000, TARGET, false);
		assertNull(attacks.forHit(101, TARGET));
		attacks.add(100, SetupStyle.MELEE, 1_000, TARGET, false);
		final PlayerAttacks.Attack first = attacks.forHit(101, TARGET);
		attacks.add(100, SetupStyle.RANGED, 1_000, TARGET, false);
		attacks.add(99, SetupStyle.RANGED, 400, TARGET, false);
		assertSame("one attack per tick, in tick order", first, attacks.forHit(101, TARGET));
		attacks.clear();
		assertNull(attacks.forHit(101, TARGET));
	}

	@Test
	public void theXpReadingTellsWhetherItRoseSinceTheLastTick()
	{
		assertFalse("a first reading is a baseline", attacks.xpRose(1_000));
		assertFalse("no XP gained (a block)", attacks.xpRose(1_000));
		assertTrue(attacks.xpRose(1_004));
		assertFalse("not read", attacks.xpRose(PlayerAttacks.NO_XP));
		assertFalse("a baseline again", attacks.xpRose(1_010));
		assertTrue(attacks.xpRose(1_011));
		attacks.forgetXp();
		assertFalse(attacks.xpRose(1_020));
		attacks.clear();
		assertFalse(attacks.xpRose(1_030));
	}
}

