/**
 * The ledger and active-session JSON, pinned byte for byte. The 1.x strings below were produced by the build
 * before the session value objects (SessionLoot, SessionCounters, the Summary builder) were introduced, from the same
 * scenario, so a refactor of how a session is modelled can't change what is written to disk. Every 1.x field of
 * {@link LedgerRecord} and {@link SessionSnapshot} is set at least once. A 2.0 record is the 1.x record at
 * version 3 with its boss flag and setup tags after the 1.x fields; {@link LedgerStoreSetupTest} pins every 2.0
 * field.
 */
public class SessionJsonFormatTest
{
	private static final long ACCOUNT = 123456789L;
	private static final long START = 1_700_000_000_000L;
	private static final int BOSS_TASK = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 5);
	private static final int REGION = 12850;
	private static final int WHIP = 4151;
	private static final int ASHES = 592;
	private static final int COINS = 995;
	/** Tradeable without a GE price, so the record counts it as unpriced. */
	private static final int UNPRICED_LOOT = 11286;
	private static final int PRAYER_POTION = 2434;
	private static final int SHARK = 385;
	private static final int UNPRICED_SUPPLY = 12625;
	/** Task-completion counters when the snapshot was taken. */
	private static final int[] COUNTERS = {3, 0, 1};

	/** A completed record from the scenario, values captured, as a 1.x build wrote it inside the file. */
	private static final String RECORD_JSON_1X =
		"{\"schemaVersion\":2,\"id\":\"session-1\",\"monster\":\"Abyssal Sire\",\"creatureId\":-7,"
		+ "\"initialAmount\":6,\"originalAmount\":6,\"kills\":6,\"activeMillis\":91000,"
		+ "\"startedAt\":1700000000000,\"endedAt\":1700000091000,\"completed\":true,\"partial\":false,"
		+ "\"loot\":{\"592\":3,\"995\":2500,\"4151\":1,\"11286\":1},\"supplies\":{\"385\":5,\"2434\":7,"
		+ "\"12625\":1},\"supplyDoses\":{\"2434\":4},\"unitGePrices\":{\"385\":800,\"592\":120,\"995\":1,"
		+ "\"2434\":9000,\"4151\":1500000},\"unitHaPrices\":{\"385\":150,\"592\":0,\"995\":1,\"2434\":0,"
		+ "\"4151\":72000,\"11286\":0,\"12625\":0},\"lootGeValue\":1502860,\"lootHaValue\":74500,"
		+ "\"suppliesGeValue\":19750,\"suppliesHaValue\":750,\"lootUnpricedItems\":1,"
		+ "\"suppliesUnpricedItems\":1,\"superiorsSpawned\":1,\"bankTrips\":2,\"deaths\":1,"
		+ "\"note\":\"Barrage\",\"slayerMaster\":8,\"slayerArea\":3,\"taskLocation\":\"Catacombs\","
		+ "\"pointsEarned\":15,\"taskStreak\":42,\"notableDrops\":[{\"itemId\":4151,"
		+ "\"name\":\"Abyssal whip\",\"quantity\":1,\"geValue\":1500000,\"haValue\":72000,"
		+ "\"time\":1700000060000},{\"quantity\":1,\"time\":1700000060001,\"pet\":\"RECEIVED\"}],"
		+ "\"bossKillCounts\":[{\"boss\":\"Abyssal Sire\",\"firstKc\":10,\"lastKc\":11,\"kills\":2}],"
		+ "\"xpGained\":{\"HITPOINTS\":700,\"SLAYER\":2500},\"locationRegion\":12850,"
		+ "\"location\":\"Catacombs of Kourend\"}";
	/** The scenario's snapshot taken mid-session, as a 1.x build wrote the active-session file (version 2). */
	private static final String SNAPSHOT_JSON_1X =
		"{\"schemaVersion\":2,\"sessionId\":\"session-1\",\"accountHash\":123456789,"
		+ "\"monster\":\"Abyssal Sire\",\"creatureId\":-7,\"initialAmount\":6,\"originalAmount\":6,"
		+ "\"kills\":4,\"activeMillis\":61000,\"startedAt\":1700000000000,\"savedAt\":1700000061005,"
		+ "\"remaining\":2,\"completionCounters\":[3,0,1],\"loot\":{\"592\":3,\"995\":2500,\"4151\":1,"
		+ "\"11286\":1},\"supplies\":{\"385\":5,\"2434\":7,\"12625\":1},\"supplyDoses\":{\"2434\":4},"
		+ "\"superiorsSpawned\":1,\"bankTrips\":2,\"deaths\":1,\"note\":\"Barrage\",\"slayerMaster\":8,"
		+ "\"slayerArea\":3,\"taskLocation\":\"Catacombs\",\"notableDrops\":[{\"itemId\":4151,"
		+ "\"name\":\"Abyssal whip\",\"quantity\":1,\"geValue\":1500000,\"haValue\":72000,"
		+ "\"time\":1700000060000},{\"quantity\":1,\"time\":1700000060001,\"pet\":\"RECEIVED\"}],"
		+ "\"bossKillCounts\":[{\"boss\":\"Abyssal Sire\",\"firstKc\":10,\"lastKc\":11,\"kills\":2}],"
		+ "\"xpGained\":{\"HITPOINTS\":700,\"SLAYER\":2500},\"locationKills\":[{\"region\":12850,"
		+ "\"kills\":2},{\"region\":12851,\"kills\":2}]}";
	/**
	 * The same snapshot as this build writes it (version 3): the 1.x fields unchanged, then the segment fields.
	 * It was taken while running, so its open segment closes when it is saved; its assignment was first seen at the
	 * start.
	 */
	private static final String SNAPSHOT_JSON = "{\"schemaVersion\":3"
		+ SNAPSHOT_JSON_1X.substring("{\"schemaVersion\":2".length(), SNAPSHOT_JSON_1X.length() - 1)
		+ ",\"trackingState\":\"RUNNING\",\"segmentClosedAt\":1700000061005,\"assignedAt\":1700000000000}";
	/** The snapshot above saved as a partial record (it could not be restored), as a 1.x build wrote it. */
	private static final String PARTIAL_JSON_1X =
		"{\"schemaVersion\":2,\"id\":\"session-1\",\"monster\":\"Abyssal Sire\",\"creatureId\":-7,"
		+ "\"initialAmount\":6,\"originalAmount\":6,\"kills\":4,\"activeMillis\":61000,"
		+ "\"startedAt\":1700000000000,\"endedAt\":1700000061005,\"completed\":false,\"partial\":true,"
		+ "\"loot\":{\"592\":3,\"995\":2500,\"4151\":1,\"11286\":1},\"supplies\":{\"385\":5,\"2434\":7,"
		+ "\"12625\":1},\"supplyDoses\":{\"2434\":4},\"superiorsSpawned\":1,\"bankTrips\":2,\"deaths\":1,"
		+ "\"note\":\"Barrage\",\"slayerMaster\":8,\"slayerArea\":3,\"taskLocation\":\"Catacombs\","
		+ "\"notableDrops\":[{\"itemId\":4151,\"name\":\"Abyssal whip\",\"quantity\":1,\"geValue\":1500000,"
		+ "\"haValue\":72000,\"time\":1700000060000},{\"quantity\":1,\"time\":1700000060001,"
		+ "\"pet\":\"RECEIVED\"}],\"bossKillCounts\":[{\"boss\":\"Abyssal Sire\",\"firstKc\":10,"
		+ "\"lastKc\":11,\"kills\":2}],\"xpGained\":{\"HITPOINTS\":700,\"SLAYER\":2500},"
		+ "\"locationRegion\":12850,\"location\":\"Catacombs\"}";
	/**
	 * The boss flag and the detected setup tags this build adds after the 1.x fields of the scenario's
	 * records: no boss kills (the scenario is a boss task, its own pool), no cannonballs, and the style and gear Unknown
	 * until phase 5 detects them.
	 */
	private static final String DETECTED_TAGS = ",\"bossKills\":false,"
		+ "\"detectedCannon\":false,\"detectedStyle\":\"UNKNOWN\",\"detectedGear\":\"UNKNOWN\"}";
	/**
	 * What a 1.x record of the scenario becomes when it is migrated: no boss kills (a boss task), its
	 * cannon estimated from its cannonballs (none), and its style Unknown, since its only XP is Hitpoints and Slayer.
	 */
	private static final String MIGRATED_TAGS = ",\"bossKills\":false,\"detectedCannon\":false,\"cannonEstimated\":true,"
		+ "\"detectedStyle\":\"UNKNOWN\",\"detectedGear\":\"UNKNOWN\"}";
	/** The completed record as this build writes it: version 3, the 1.x fields, then its detected tags. */
	private static final String RECORD_JSON = twoPointO(RECORD_JSON_1X, DETECTED_TAGS);
	/**
	 * The partial record as this build writes it. Now no location name is saved, and its region is the one its
	 * kills decide: the scenario's two regions tie (its snapshot was read without the spot table), so the most recent.
	 */
	private static final String PARTIAL_JSON = twoPointO(PARTIAL_JSON_1X.replace(
		"\"locationRegion\":12850,\"location\":\"Catacombs\"", "\"locationRegion\":12851"), DETECTED_TAGS);

	/** A 1.x record's JSON at version 3 with {@code tail} (the setup members and the closing brace) after its fields. */
	private static String twoPointO(String oneX, String tail)
	{
		assertEquals(true, oneX.startsWith("{\"schemaVersion\":2,") && oneX.endsWith("}"));
		return "{\"schemaVersion\":3," + oneX.substring("{\"schemaVersion\":2,".length(), oneX.length() - 1) + tail;
	}

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private final Gson gson = new Gson();
	private final AtomicLong now = new AtomicLong(START);
	private File dir;
	private LedgerStore store;

	@Before
	public void setUp()
	{
		dir = new File(temp.getRoot(), "slayer-ledger");
		store = new LedgerStore(Filepath.Unchecked.getRooted(dir.toPath()), gson);
	}

	@Test
	public void completedRecordIsWrittenAsBefore()
	{
		assertEquals(RECORD_JSON, gson.toJson(completedRecord()));
	}

	@Test
	public void snapshotIsWrittenAsBefore()
	{
		assertEquals(SNAPSHOT_JSON, gson.toJson(snapshot()));
	}

	@Test
	public void snapshotSavedAsPartialIsWrittenAsBefore()
	{
		LedgerRecord partial = LedgerRecord.fromSummary(snapshot().toSummary(SlayerSpots.NONE), true);
		assertEquals(PARTIAL_JSON, gson.toJson(partial));
	}

	@Test
	public void restoredSnapshotIsWrittenBackUnchanged()
	{
		SessionSnapshot saved = gson.fromJson(SNAPSHOT_JSON, SessionSnapshot.class);
		SessionTracker tracker = new SessionTracker(now::get);
		tracker.observe("Abyssal Sire", BOSS_TASK, 2, 6, TaskContext.assignment(8, 3, "Catacombs"), REGION, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(saved, COUNTERS.clone()));

		SessionSnapshot again = SessionSnapshot.fromSummary(tracker.summary(), COUNTERS, saved.getSavedAt());
		// A restored session is Logged out until its next kill; nothing else of the session changes.
		assertEquals(SNAPSHOT_JSON.replace("\"trackingState\":\"RUNNING\"", "\"trackingState\":\"LOGGED_OUT\""),
			gson.toJson(again));
	}

	@Test
	public void aOneXActiveFileStillRestores() throws IOException
	{
		assertEquals(true, dir.mkdirs());
		File file = new File(dir, ACCOUNT + ".active.json");
		Files.write(file.toPath(), SNAPSHOT_JSON_1X.getBytes(StandardCharsets.UTF_8));
		SessionSnapshot saved = store.readActive(ACCOUNT);
		assertNotNull("a version 2 file is read", saved);
		assertEquals(false, saved.isEndedMarker());

		now.set(START + 120_000);
		SessionTracker tracker = new SessionTracker(now::get);
		tracker.observe("Abyssal Sire", BOSS_TASK, 2, 6, TaskContext.assignment(8, 3, "Catacombs"), REGION, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(saved, COUNTERS.clone()));
		assertEquals(SessionTracker.State.LOGGED_OUT, tracker.getState());
		assertEquals(4, tracker.getKills());
		assertEquals(61_000, tracker.getActiveMillis());

		// Without the segment fields its last segment closed when it was saved, and its assignment was first seen by
		// this login: a kill backdated before them is clamped to the later, the login's first reading.
		now.addAndGet(10_000);
		tracker.observe("Abyssal Sire", BOSS_TASK, 1, 6, TaskContext.assignment(8, 3, "Catacombs"), REGION, false,
			KillPairing.of(START, null));
		assertEquals(SessionTracker.State.RUNNING, tracker.getState());
		assertEquals(5, tracker.getKills());
		assertEquals(61_000 + 10_000, tracker.getActiveMillis());
	}

	@Test
	public void ledgerFileIsRewrittenByteForByte() throws IOException
	{
		String fixture = "{\"schemaVersion\":3,\"records\":[" + RECORD_JSON + "," + PARTIAL_JSON + "]}";
		assertEquals(true, dir.mkdirs());
		File file = new File(dir, ACCOUNT + ".json");
		Files.write(file.toPath(), fixture.getBytes(StandardCharsets.UTF_8));

		List<LedgerRecord> records = store.load(ACCOUNT);
		assertEquals(2, records.size());
		store.write(ACCOUNT, records);

		assertEquals(fixture, new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
	}

	@Test
	public void aOneXLedgerFileIsMigratedAndWrittenBackWithEvery1xFieldUnchanged() throws IOException
	{
		String fixture = "{\"schemaVersion\":2,\"records\":[" + RECORD_JSON_1X + "," + PARTIAL_JSON_1X + "]}";
		assertEquals(true, dir.mkdirs());
		File file = new File(dir, ACCOUNT + ".json");
		Files.write(file.toPath(), fixture.getBytes(StandardCharsets.UTF_8));

		List<LedgerRecord> records = store.load(ACCOUNT);
		assertEquals(2, records.size());
		assertEquals("reading changes nothing on disk", fixture,
			new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
		store.write(ACCOUNT, records);

		assertEquals("{\"schemaVersion\":3,\"records\":[" + twoPointO(RECORD_JSON_1X, MIGRATED_TAGS) + ","
			+ twoPointO(PARTIAL_JSON_1X, MIGRATED_TAGS) + "]}",
			new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
	}

	@Test
	public void activeFileIsRewrittenByteForByte() throws IOException
	{
		assertEquals(true, dir.mkdirs());
		File file = new File(dir, ACCOUNT + ".active.json");
		Files.write(file.toPath(), SNAPSHOT_JSON.getBytes(StandardCharsets.UTF_8));

		SessionSnapshot read = store.readActive(ACCOUNT);
		assertNotNull(read);
		store.writeActive(ACCOUNT, read);

		assertEquals(SNAPSHOT_JSON, new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));
	}

	/** The scenario's snapshot, taken while the session is running, with a fixed id. */
	private SessionSnapshot snapshot()
	{
		SessionTracker tracker = runningSession();
		SessionSnapshot s = SessionSnapshot.fromSummary(tracker.summary(), COUNTERS, now.get() + 5);
		s.setSessionId("session-1");
		return s;
	}

	/** The scenario's session completed, with completion rewards and captured values, with a fixed id. */
	private LedgerRecord completedRecord()
	{
		SessionTracker tracker = runningSession();
		now.addAndGet(30_000);
		tracker.observe("Abyssal Sire", BOSS_TASK, 0, 6, TaskContext.assignment(8, 3, "Catacombs"), REGION, true);
		assertEquals(true, tracker.isCompleted());
		tracker.setCompletionRewards(tracker.getSessionId(), 15, 42);
		tracker.stop();
		LedgerRecord record = LedgerRecord.fromSummary(tracker.summary(), false);
		record.setId("session-1");
		record.captureValues(new ItemValuation.PriceLookup()
		{
			@Override
			public int canonicalize(int itemId)
			{
				return itemId;
			}

			@Override
			public long gePrice(int canonicalId)
			{
				switch (canonicalId)
				{
					case WHIP:
						return 1_500_000;
					case ASHES:
						return 120;
					case COINS:
						return 1;
					case PRAYER_POTION:
						return 9_000;
					case SHARK:
						return 800;
					default:
						return 0;
				}
			}

			@Override
			public boolean isTradeable(int canonicalId)
			{
				return true;
			}

			@Override
			public long haPrice(int canonicalId)
			{
				return canonicalId == WHIP ? 72_000 : canonicalId == SHARK ? 150 : 0;
			}
		});
		// A name of its own: 1.x saved its region's name; only the player's "Edit location" sets one.
		record.setLocation("Catacombs of Kourend");
		return record;
	}

	/** A running boss task session with every kind of session data: loot, supplies, counters, XP, region, note. */
	private SessionTracker runningSession()
	{
		now.set(START);
		SessionTracker tracker = new SessionTracker(now::get);
		final TaskContext assignment = TaskContext.assignment(8, 3, "Catacombs");
		tracker.observe("Abyssal Sire", BOSS_TASK, 6, 6, assignment, REGION, false);
		tracker.observeXp(xp(1_000, 500));
		assertEquals(true, tracker.startNow(ACCOUNT));
		now.addAndGet(60_000);
		tracker.observe("Abyssal Sire", BOSS_TASK, 4, 6, assignment, REGION, false);
		tracker.observe("Abyssal Sire", BOSS_TASK, 2, 6, assignment, REGION + 1, false);
		tracker.observeXp(xp(3_500, 1_200));

		ItemTally loot = new ItemTally();
		loot.add(WHIP, 1);
		loot.add(ASHES, 3);
		loot.add(COINS, 2_500);
		loot.add(UNPRICED_LOOT, 1);
		tracker.addLoot(loot, Collections.singletonList(
			NotableDrop.item(WHIP, "Abyssal whip", 1, 1_500_000L, 72_000L, now.get())));
		tracker.addPet(NotableDrop.pet(null, now.get() + 1));
		tracker.addBossKillCount("Abyssal Sire", 10);
		tracker.addBossKillCount("Abyssal Sire", 11);

		ItemTally used = new ItemTally();
		used.add(PRAYER_POTION, 7);
		used.add(SHARK, 5);
		used.add(UNPRICED_SUPPLY, 1);
		tracker.addSupplies(used, null, Collections.singletonMap(PRAYER_POTION, 4));

		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addBankTrip();
		tracker.addDeath();
		tracker.setNote(tracker.getSessionId(), "Barrage");
		now.addAndGet(1_000);
		return tracker;
	}

	private static Map<String, Integer> xp(int slayer, int hitpoints)
	{
		Map<String, Integer> reading = new TreeMap<>();
		reading.put("SLAYER", slayer);
		reading.put("HITPOINTS", hitpoints);
		return reading;
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.SessionTracker.RestoreResult;
import static com.shmayvan.slayerledger.SessionTracker.State;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Before;
import org.junit.Test;

/**
 * Snapshot / restore of in-progress sessions (persisted on logout, client exit, plugin shutdown, account switch).
 */
public class SessionRestoreTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	/** A session with 7 kills and 60s of active time, snapshotted while paused at 43 remaining. */
	private SessionSnapshot snapshotOfSession()
	{
		SessionTracker original = new SessionTracker(() -> now);
		original.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		original.startNow(ACCOUNT);
		now += 60_000;
		original.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		original.loggedOut();
		now += 5_000;
		SessionTracker.Summary summary = original.activeSummary();
		assertNotNull(summary);
		return SessionSnapshot.fromSummary(summary, COUNTERS, now);
	}

	@Test
	public void snapshotCapturesSession()
	{
		SessionSnapshot s = snapshotOfSession();
		assertNotNull(s.getSessionId());
		assertEquals(ACCOUNT, s.getAccountHash());
		assertEquals("Abyssal demons", s.getMonster());
		assertEquals(DEMON_ID, s.getCreatureId());
		assertEquals(50, s.getInitialAmount());
		assertEquals(Integer.valueOf(150), s.getOriginalAmount());
		assertEquals(7, s.getKills());
		assertEquals(60_000, s.getActiveMillis());
		assertEquals(1_000_000L, s.getStartedAt());
		assertEquals(43, s.getRemaining());
		assertArrayEquals(COUNTERS, s.getCompletionCounters());
		assertEquals(SessionSnapshot.CURRENT_SCHEMA_VERSION, s.getSchemaVersion());
	}

	@Test
	public void snapshotSurvivesJsonRoundTrip()
	{
		Gson gson = new Gson();
		SessionSnapshot s = snapshotOfSession();
		assertEquals(s, gson.fromJson(gson.toJson(s), SessionSnapshot.class));
	}

	@Test
	public void restoresMatchingTaskAsLoggedOutAndIgnoresUntrackedKills()
	{
		SessionSnapshot s = snapshotOfSession();
		// 3 kills happened while the plugin was not watching
		tracker.observe("Abyssal demons", DEMON_ID, 40, 150, false);
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, COUNTERS));
		assertEquals("restored as after a logout, not Paused", State.LOGGED_OUT, tracker.getState());
		assertEquals(SessionTracker.Status.WAITING_FOR_NEXT_KILL, tracker.getStatus());
		assertFalse("Resume is only for Paused", tracker.canResume(ACCOUNT));
		assertTrue(tracker.isRestoredPending());
		assertEquals(7, tracker.getKills());
		assertEquals(60_000, tracker.getActiveMillis());
		assertEquals(ACCOUNT, tracker.getSessionAccountHash());

		// The next task kill restarts it, backdated to its fight; the baseline is the current remaining count.
		now += 10_000;
		tracker.observe("Abyssal demons", DEMON_ID, 38, 150, TaskContext.NONE, LocationTally.NO_REGION, false,
			KillPairing.of(now - 4_000, null));
		assertEquals(State.RUNNING, tracker.getState());
		assertFalse(tracker.isRestoredPending());
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(9, summary.getKills());
		assertEquals(64_000, summary.getActiveMillis());
		assertEquals(s.getSessionId(), summary.getSessionId());
		assertEquals(50, summary.getInitialAmount());
		assertEquals(150, summary.getOriginalAmount());
		assertEquals(1_000_000L, summary.getStartedAt());
		assertEquals(s.getSessionId(), LedgerRecord.fromSummary(summary, true).getId());
	}

	@Test
	public void restoreRefusedBeforeObservationOrWithActiveSession()
	{
		SessionSnapshot s = snapshotOfSession();
		assertEquals(RestoreResult.REFUSED, tracker.restore(s, COUNTERS));
		tracker.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		tracker.startNow(ACCOUNT);
		assertEquals(RestoreResult.REFUSED, tracker.restore(s, COUNTERS));
		assertEquals(State.RUNNING, tracker.getState());
	}

	@Test
	public void differentCreatureIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Black dragons", DRAGON_ID, 20, 20, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
		assertEquals(State.IDLE, tracker.getState());
	}

	@Test
	public void noTaskIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void higherRemainingIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 44, 150, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void changedAssignedSizeIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 120, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void completionInBetweenIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 150, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, new int[]{101, 2, 0}));
		// unknown counters on either side do not block
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, null));
	}

	@Test
	public void unknownSizeOrCountersStillRestore()
	{
		SessionSnapshot s = snapshotOfSession();
		s.setOriginalAmount(null);
		s.setCompletionCounters(null);
		tracker.observe("Abyssal demons", DEMON_ID, 43, false);
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, COUNTERS));
	}

	@Test
	public void noAccountIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		s.setAccountHash(SessionTracker.NO_ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void mismatchSummaryIsIncompleteWithSnapshotValues()
	{
		SessionSnapshot s = snapshotOfSession();
		SessionTracker.Summary summary = s.toSummary(SlayerSpots.NONE);
		assertTrue(summary.hasTask());
		assertFalse(summary.isCompleted());
		assertEquals(7, summary.getKills());
		assertEquals(s.getSavedAt(), summary.getEndedAt());
		assertEquals(s.getSessionId(), summary.getSessionId());
		assertEquals(SaveDecision.Action.SAVE_PARTIAL_WITH_NOTICE,
			SaveDecision.decide(summary, SaveDecision.EndReason.RESTORE_MISMATCH, true));
		LedgerRecord record = LedgerRecord.fromSummary(summary, true);
		assertEquals(s.getSessionId(), record.getId());
		assertTrue(record.isPartial());
		assertEquals(Integer.valueOf(150), record.getOriginalAmount());
	}

	@Test
	public void activeSummaryIsNullWhenIdleAndKeepsSessionInMemory()
	{
		assertNull(tracker.activeSummary());
		tracker.observe("Abyssal demons", DEMON_ID, 10, false);
		tracker.startNow(ACCOUNT);
		tracker.loggedOut();
		assertNotNull(tracker.activeSummary());
		// taking a snapshot on logout does not end the in-memory session
		assertEquals(State.LOGGED_OUT, tracker.getState());
	}

	@Test
	public void snapshotDuringPendingZeroResumesFromCountBeforeTheZero()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, false);
		tracker.startNow(ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 8, false);
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		SessionSnapshot s = SessionSnapshot.fromSummary(tracker.activeSummary(), null, now);
		assertEquals(8, s.getRemaining());
		assertEquals(2, s.getKills());
	}

	@Test
	public void newSessionsGetDistinctIds()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, false);
		tracker.startNow(ACCOUNT);
		String first = tracker.stopAndReset().getSessionId();
		tracker.startNow(ACCOUNT);
		String second = tracker.stopAndReset().getSessionId();
		assertNotNull(first);
		assertFalse(first.equals(second));
	}

	@Test
	public void completionCounterDecreaseIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 150, false);
		// Turael reset / cancellation lowers the streak
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, new int[]{50, 2, 0}));
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, new int[]{100, 1, 0}));
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, COUNTERS));
	}

	@Test
	public void allZeroCountersAreTreatedAsNotYetSynced()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 150, false);
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, new int[]{0, 0, 0}));
	}

	/** A session kept in memory across logout: log out at 43 left, then log back in. */
	private SessionSnapshot logOutWithSessionInMemory()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		tracker.startNow(ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		tracker.loggedOut();
		SessionSnapshot s = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		tracker.clearCurrentTask();
		return s;
	}

	@Test
	public void reloginWithSameTaskStillMatches()
	{
		SessionSnapshot s = logOutWithSessionInMemory();
		tracker.observe("Abyssal demons", DEMON_ID, 43, 150, false);
		assertTrue(tracker.activeSessionStillMatches(s, COUNTERS));
		assertEquals(State.LOGGED_OUT, tracker.getState());
	}

	@Test
	public void reloginAfterFinishingAndGettingSameCreatureIsMismatch()
	{
		SessionSnapshot s = logOutWithSessionInMemory();
		// finished the task elsewhere, then got the same creature again with a new size
		tracker.observe("Abyssal demons", DEMON_ID, 180, 180, false);
		assertFalse(tracker.activeSessionStillMatches(s, new int[]{101, 2, 0}));
		// even without size or counter evidence, the higher remaining count gives it away
		assertFalse(tracker.activeSessionStillMatches(s, null));
	}

	@Test
	public void reloginWithStreakDecreaseIsMismatch()
	{
		SessionSnapshot s = logOutWithSessionInMemory();
		tracker.observe("Abyssal demons", DEMON_ID, 40, 150, false);
		assertFalse(tracker.activeSessionStillMatches(s, new int[]{60, 2, 0}));
		// a counter reading zero is unknown (possibly unsynced), not a reset
		assertTrue(tracker.activeSessionStillMatches(s, new int[]{0, 2, 0}));
	}

	@Test
	public void perCounterUnknownHandling()
	{
		// zero now, non-zero before: unknown
		assertFalse(SessionTracker.counterChanged(100, 0));
		// unchanged
		assertFalse(SessionTracker.counterChanged(100, 100));
		assertFalse(SessionTracker.counterChanged(0, 0));
		// increases (including from zero) and non-zero decreases are changes
		assertTrue(SessionTracker.counterChanged(100, 101));
		assertTrue(SessionTracker.counterChanged(0, 1));
		assertTrue(SessionTracker.counterChanged(100, 40));
	}

	@Test
	public void oneUnsyncedCounterDoesNotHideAnotherCounterChange()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe("Abyssal demons", DEMON_ID, 30, 150, false);
		assertEquals(RestoreResult.RESTORED, tracker.restore(s, new int[]{0, 2, 0}));
		tracker.stopAndReset();
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, new int[]{0, 3, 0}));
	}

	@Test
	public void restoreCheckDefersWhileCountReadsZeroUpToCap()
	{
		assertTrue(SessionTracker.shouldDeferRestoreCheck(0, 0));
		assertTrue(SessionTracker.shouldDeferRestoreCheck(0, SessionTracker.RESTORE_SYNC_MAX_TICKS - 1));
		assertFalse(SessionTracker.shouldDeferRestoreCheck(0, SessionTracker.RESTORE_SYNC_MAX_TICKS));
		assertFalse(SessionTracker.shouldDeferRestoreCheck(5, 0));
		assertFalse(SessionTracker.shouldDeferRestoreCheck(1, 3));
	}

	@Test
	public void zeroCountAfterCapIsMismatch()
	{
		SessionSnapshot s = snapshotOfSession();
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertFalse(SessionTracker.shouldDeferRestoreCheck(0, SessionTracker.RESTORE_SYNC_MAX_TICKS));
		assertEquals(RestoreResult.MISMATCH, tracker.restore(s, COUNTERS));
	}

	@Test
	public void reloginCheckIgnoresOtherOrNoSession()
	{
		SessionSnapshot s = logOutWithSessionInMemory();
		tracker.observe("Black dragons", DRAGON_ID, 20, false);
		SessionSnapshot other = snapshotOfSession();
		assertTrue(tracker.activeSessionStillMatches(other, COUNTERS));
		assertTrue(tracker.activeSessionStillMatches(null, COUNTERS));
		tracker.stopAndReset();
		assertTrue(tracker.activeSessionStillMatches(s, COUNTERS));
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.SessionTracker.ObserveResult;
import static com.shmayvan.slayerledger.SessionTracker.State;
import static com.shmayvan.slayerledger.SessionTracker.Status;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import org.junit.Before;
import org.junit.Test;

/**
 * The automatic session lifecycle (V2 plan 4.1) on the tracker alone: a session's time is the sum of its
 * segments; a task kill (re)starts it at its resume point, clamped to the assignment, the previous session's end and the
 * close of the previous segment; the stops; Away; End task and Track again. {@code PluginHarness} tests cover the same
 * rules through the plugin's events ({@code HarnessAutomaticTrackingTest}).
 */
public class SessionSegmentsTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final long MINUTE = 60_000L;

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 100 * MINUTE;
		tracker = new SessionTracker(() -> now);
		tracker.setAccount(ACCOUNT);
	}

	private ObserveResult demons(int remaining)
	{
		return demons(remaining, KillPairing.NONE);
	}

	private ObserveResult demons(int remaining, KillPairing pairing)
	{
		return tracker.observe("Abyssal demons", DEMON_ID, remaining, 50, TaskContext.NONE, LocationTally.NO_REGION,
			false, pairing);
	}

	private ObserveResult complete(KillPairing pairing)
	{
		return tracker.observe(null, SessionTracker.NO_CREATURE, 0, SessionTracker.UNKNOWN_AMOUNT, TaskContext.NONE,
			LocationTally.NO_REGION, true, pairing);
	}

	/** NPCs whose earliest engagement started at {@code start}, named Abyssal demon. */
	private static KillPairing fightFrom(long start)
	{
		return KillPairing.of(start, Collections.singletonList("Abyssal demon"));
	}

	// ---- Starts ----

	@Test
	public void theFirstKillStartsTheSessionBackdatedToItsFight()
	{
		demons(50);
		assertEquals(Status.WAITING_FOR_FIRST_KILL, tracker.getStatus());
		assertNull(tracker.liveTask());

		now += 10 * MINUTE;
		demons(49, fightFrom(now - 40_000));
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals(1, tracker.getKills());
		assertEquals("the first fight counts", 40_000, tracker.getActiveMillis());
		assertEquals(now - 40_000, tracker.summary().getStartedAt());
		assertEquals(50, tracker.summary().getInitialAmount());
		assertEquals(ACCOUNT, tracker.getSessionAccountHash());
		assertEquals(Collections.singletonList("abyssal demon"), tracker.summary().getSegments().getTaskNpcs());
	}

	@Test
	public void aKillWithNothingPairedStartsAtTheKill()
	{
		demons(50);
		now += MINUTE;
		// A cannon-only kill: no NPC the player hit died.
		demons(48);
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals(2, tracker.getKills());
		assertEquals(0, tracker.getActiveMillis());
		now += 5_000;
		assertEquals(5_000, tracker.getActiveMillis());
	}

	@Test
	public void theResumePointIsNeverBeforeTheAssignment()
	{
		demons(50);
		final long assigned = now;
		now += MINUTE;
		// Hits from before the assignment (a previous task's fight) never count.
		demons(49, fightFrom(assigned - 5 * MINUTE));
		assertEquals(MINUTE, tracker.getActiveMillis());
		assertEquals(assigned, tracker.summary().getStartedAt());
	}

	@Test
	public void noSessionStartsWithoutAnAccountOrWhileAStartIsBlockedOrOnTheFirstReading()
	{
		SessionTracker noAccount = new SessionTracker(() -> now);
		noAccount.observe("Abyssal demons", DEMON_ID, 50, false);
		noAccount.observe("Abyssal demons", DEMON_ID, 49, false);
		assertEquals(State.IDLE, noAccount.getState());

		demons(50);
		demons(49, KillPairing.NONE.withStartBlocked());
		assertEquals("a restore check is pending", State.IDLE, tracker.getState());

		tracker.clearCurrentTask();
		demons(45);
		assertEquals("the first reading after a login is never a kill", State.IDLE, tracker.getState());
		demons(44);
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals(1, tracker.getKills());
	}

	@Test
	public void aNewAssignmentIsNotAKill()
	{
		demons(3);
		tracker.observe("Black dragons", DRAGON_ID, 2, 40, false);
		assertEquals(State.IDLE, tracker.getState());
		assertEquals(Status.WAITING_FOR_FIRST_KILL, tracker.getStatus());
	}

	@Test
	public void aFirstKillThatCompletesTheTaskStartsAndCompletesTheSession()
	{
		demons(1);
		now += MINUTE;
		assertEquals(ObserveResult.COMPLETED, complete(fightFrom(now - 20_000)));
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals(1, tracker.getKills());
		assertEquals(20_000, tracker.getActiveMillis());
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.takePendingCompletion().isCompleted());
	}

	@Test
	public void aFirstKillToZeroWaitsForItsCompletion()
	{
		demons(1);
		now += MINUTE;
		// The count reads 0 a tick before the completion: a cancelled task does too, so nothing starts yet.
		assertEquals(ObserveResult.NONE, tracker.observe(null, SessionTracker.NO_CREATURE, 0, false));
		assertEquals(State.IDLE, tracker.getState());
		now += 600;
		assertEquals(ObserveResult.COMPLETED, complete(KillPairing.NONE));
		assertEquals(1, tracker.getKills());
		assertEquals("started at the kill, a tick before", 600, tracker.getActiveMillis());

		// A cancelled task (no completion) starts nothing.
		SessionTracker other = new SessionTracker(() -> now);
		other.setAccount(ACCOUNT);
		other.observe("Abyssal demons", DEMON_ID, 30, false);
		other.observe(null, SessionTracker.NO_CREATURE, 0, false);
		other.observe("Black dragons", DRAGON_ID, 20, false);
		assertEquals(State.IDLE, other.getState());
	}

	// ---- The next tick's deaths ----

	@Test
	public void deathsOnTheTickAfterTheKillStillBackdateItsRestart()
	{
		demons(50);
		now += MINUTE;
		demons(49);
		assertEquals(0, tracker.getActiveMillis());
		final long killAt = tracker.getLastKillAt();

		now += 600;
		tracker.pairKill(killAt, fightFrom(killAt - 30_000));
		assertEquals(30_600, tracker.getActiveMillis());
		assertEquals(killAt - 30_000, tracker.summary().getStartedAt());
		assertEquals(Collections.singletonList("abyssal demon"), tracker.summary().getSegments().getTaskNpcs());

		// Still clamped: never before the assignment.
		tracker.pairKill(killAt, fightFrom(0));
		assertEquals(MINUTE + 600, tracker.getActiveMillis());
		// Another kill's pairing never moves it.
		tracker.pairKill(killAt - 1, fightFrom(0));
		assertEquals(MINUTE + 600, tracker.getActiveMillis());
	}

	@Test
	public void deathsOnTheTickAfterTheFinalKillBackdateTheHeldCompletion()
	{
		demons(2);
		assertTrue(tracker.startNow(ACCOUNT));
		now += MINUTE;
		tracker.loggedOut();
		now += 10 * MINUTE;
		assertEquals(ObserveResult.COMPLETED, complete(KillPairing.NONE));
		final long killAt = tracker.getLastKillAt();
		assertTrue(tracker.holdCompletion());

		tracker.pairKill(killAt, fightFrom(killAt - 45_000));
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(MINUTE + 45_000, held.getActiveMillis());
	}

	// ---- Stops and restarts ----

	@Test
	public void pauseThenResumeOpensASegmentAtOnce()
	{
		demons(50);
		demons(49);
		now += MINUTE;
		assertTrue(tracker.pause());
		assertEquals(Status.PAUSED, tracker.getStatus());
		now += 30 * MINUTE;
		assertEquals(MINUTE, tracker.getActiveMillis());
		assertTrue(tracker.resume(ACCOUNT));
		now += MINUTE;
		assertEquals(2 * MINUTE, tracker.getActiveMillis());
	}

	@Test
	public void aKillRestartAfterAPauseIsClampedToThePause()
	{
		demons(50);
		demons(49);
		now += MINUTE;
		tracker.pause();
		final long paused = now;
		now += 5 * MINUTE;
		// The fight began before the pause: only the part after it counts.
		demons(48, fightFrom(paused - 30_000));
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals(2, tracker.getKills());
		assertEquals(MINUTE + 5 * MINUTE, tracker.getActiveMillis());

		tracker.pause();
		now += MINUTE;
		demons(47, fightFrom(now - 20_000));
		assertEquals("after the pause, the fight counts in full", 6 * MINUTE + 20_000, tracker.getActiveMillis());
	}

	@Test
	public void aLoginIsNotARestartAndTheNextKillIsClampedToTheLogout()
	{
		demons(50);
		demons(49);
		now += MINUTE;
		assertTrue(tracker.loggedOut());
		assertEquals(Status.WAITING_FOR_NEXT_KILL, tracker.getStatus());
		tracker.clearCurrentTask();
		assertEquals(Status.LOGGED_OUT, tracker.getStatus());
		now += 60 * MINUTE;

		demons(49);
		assertEquals("a login is not a restart", State.LOGGED_OUT, tracker.getState());
		assertEquals(Status.WAITING_FOR_NEXT_KILL, tracker.getStatus());
		now += MINUTE;
		demons(48, fightFrom(now - 30_000));
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals("the fight after the login counts, the logged-out hour doesn't", MINUTE + 30_000,
			tracker.getActiveMillis());

		// The clamp: a resume point before the logout is held to it. (The plugin forgets every hit at a login, so
		// there it can't happen; after a pause or Away it can.)
		SessionTracker other = new SessionTracker(() -> now);
		other.setAccount(ACCOUNT);
		other.observe("Abyssal demons", DEMON_ID, 10, false);
		other.observe("Abyssal demons", DEMON_ID, 9, false);
		other.loggedOut();
		final long otherLogout = now;
		now += MINUTE;
		other.observe("Abyssal demons", DEMON_ID, 8, 50, TaskContext.NONE, LocationTally.NO_REGION, false,
			fightFrom(otherLogout - 5 * MINUTE));
		assertEquals("clamped to the logout", now - otherLogout, other.getActiveMillis());
	}

	@Test
	public void theFinalKillAfterALogoutRestartsBeforeItCompletes()
	{
		demons(2);
		demons(1);
		now += MINUTE;
		tracker.loggedOut();
		tracker.clearCurrentTask();
		now += 60 * MINUTE;
		demons(1);
		now += 2 * MINUTE;
		assertEquals(ObserveResult.COMPLETED, complete(fightFrom(now - 90_000)));
		assertEquals(2, tracker.getKills());
		assertEquals("the backdated last fight counts", MINUTE + 90_000, tracker.getActiveMillis());
		assertTrue("restarted, so held for its loot", tracker.holdCompletion());
	}

	@Test
	public void aPauseBetweenADropToZeroAndItsCompletionCountsNoTimeTwice()
	{
		demons(2);
		demons(1);
		final long started = now;
		now += MINUTE;
		// The final kill: the count reads 0 before the completion confirms it.
		assertEquals(ObserveResult.TASK_CLEARED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, false));
		now += 300;
		assertTrue(tracker.pause());
		now += 300;
		// The restart for the final kill opens at the pause, not at the kill before it.
		assertEquals(ObserveResult.COMPLETED, complete(KillPairing.NONE));
		assertTrue(tracker.holdCompletion());
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(2, held.getKills());
		assertEquals("no more than the wall clock", now - started, held.getActiveMillis());
	}

	@Test
	public void aBraceletOfSlaughterKillRestartsWithoutCountingAKill()
	{
		demons(50);
		demons(49);
		now += MINUTE;
		tracker.pause();
		now += 10 * MINUTE;
		assertTrue(tracker.braceletKill(fightFrom(now - 15_000)));
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals("the kills follow the task count", 1, tracker.getKills());
		assertEquals(MINUTE + 15_000, tracker.getActiveMillis());

		// While running it is activity: it resets the Away clock.
		now += 9 * MINUTE;
		assertTrue(tracker.braceletKill(KillPairing.NONE));
		now += 9 * MINUTE;
		assertFalse(tracker.checkAway());

		// On an assignment waiting for its first kill it starts the session.
		SessionTracker waiting = new SessionTracker(() -> now);
		waiting.setAccount(ACCOUNT);
		waiting.observe("Abyssal demons", DEMON_ID, 20, false);
		assertTrue(waiting.braceletKill(KillPairing.NONE));
		assertEquals(State.RUNNING, waiting.getState());
		assertEquals(0, waiting.getKills());
		assertEquals(20, waiting.summary().getInitialAmount());
	}

	// ---- Away ----

	@Test
	public void aBreakOverTheLimitGoesAwayAndTheClockStepsBackOnce()
	{
		demons(50);
		demons(49);
		now += 2 * MINUTE;
		demons(48);
		final long lastKill = now;
		now += SessionTracker.DEFAULT_AWAY_MINUTES * MINUTE - 1;
		assertFalse(tracker.checkAway());
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals(12 * MINUTE - 1, tracker.getActiveMillis());

		now += 1;
		assertTrue(tracker.checkAway());
		assertEquals(Status.AWAY, tracker.getStatus());
		assertEquals("the segment closes at the last kill", 2 * MINUTE, tracker.getActiveMillis());
		now += 60 * MINUTE;
		assertFalse("once", tracker.checkAway());
		assertEquals(2 * MINUTE, tracker.getActiveMillis());

		// The next kill restarts it at its fight, held to no earlier than the Away close.
		demons(47, fightFrom(lastKill - MINUTE));
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals("clamped to the Away close", 2 * MINUTE + (now - lastKill), tracker.getActiveMillis());
	}

	@Test
	public void aBankTripUnderTheLimitIsCounted()
	{
		demons(50);
		demons(49);
		now += 9 * MINUTE;
		assertFalse(tracker.checkAway());
		demons(48);
		assertEquals(9 * MINUTE, tracker.getActiveMillis());
	}

	@Test
	public void hitsOnAKnownTaskNpcKeepALongKillFromGoingAway()
	{
		demons(50);
		demons(49, fightFrom(now));
		for (int i = 0; i < 15; i++)
		{
			now += MINUTE;
			assertTrue(tracker.taskNpcHit("Abyssal demon"));
			assertFalse(tracker.checkAway());
		}
		assertFalse("not a known task NPC", tracker.taskNpcHit("Chicken"));
		assertEquals(15 * MINUTE, tracker.getActiveMillis());
		now += 10 * MINUTE;
		assertTrue(tracker.checkAway());
		assertEquals("closed at the last hit", 15 * MINUTE, tracker.getActiveMillis());
	}

	@Test
	public void theAwayLimitIsASetting()
	{
		tracker.setAwayMinutes(2);
		demons(50);
		demons(49);
		now += 2 * MINUTE;
		assertTrue(tracker.checkAway());
		assertEquals(0, tracker.getActiveMillis());
	}

	// ---- End task and Track again ----

	@Test
	public void endTaskStopsTrackingTheAssignmentUntilTrackAgain()
	{
		demons(50);
		now += MINUTE;
		demons(49, fightFrom(now - 10_000));
		now += MINUTE;
		SessionTracker.Summary ended = tracker.endTask();
		assertNotNull(ended);
		assertEquals(1, ended.getKills());
		assertEquals(State.IDLE, tracker.getState());
		assertEquals(Status.ENDED, tracker.getStatus());
		final long endedAt = now;

		now += MINUTE;
		demons(48);
		demons(47);
		assertEquals("no kill restarts an Ended assignment", State.IDLE, tracker.getState());
		assertFalse(tracker.startNow(ACCOUNT));
		assertEquals(Status.ENDED, tracker.getStatus());

		assertTrue(tracker.trackAgain());
		assertEquals(Status.WAITING_FOR_FIRST_KILL, tracker.getStatus());
		now += MINUTE;
		demons(46, fightFrom(endedAt - MINUTE));
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals("never before the ended session's end", now - endedAt, tracker.getActiveMillis());
		assertEquals(1, tracker.getKills());
	}

	@Test
	public void endTaskWithoutASessionEndsTheWaitingAssignment()
	{
		demons(50);
		assertTrue(tracker.canEndTask());
		assertNull(tracker.endTask());
		assertEquals(Status.ENDED, tracker.getStatus());
		assertFalse(tracker.canEndTask());
		demons(49);
		assertEquals(State.IDLE, tracker.getState());
	}

	@Test
	public void aNewAssignmentAfterEndTaskIsTrackedNormally()
	{
		demons(3);
		demons(2);
		tracker.endTask();
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		tracker.observe("Black dragons", DRAGON_ID, 20, 20, false);
		assertEquals("not Ended", Status.WAITING_FOR_FIRST_KILL, tracker.getStatus());
		tracker.observe("Black dragons", DRAGON_ID, 19, 20, false);
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals("Black dragons", tracker.getSessionMonster());

		// The same creature assigned again (a higher count) is a new assignment too.
		tracker.endTask();
		tracker.observe("Black dragons", DRAGON_ID, 25, 25, false);
		assertEquals("not Ended", Status.WAITING_FOR_FIRST_KILL, tracker.getStatus());
	}

	@Test
	public void theEndedFlagSurvivesAClientRestartThroughItsMarker()
	{
		demons(50);
		final long assigned = now;
		demons(49);
		now += MINUTE;
		tracker.endTask();
		final int[] counters = {3, 0, 0};
		SessionSnapshot marker = tracker.endedMarker(counters, now);
		assertNotNull(marker);
		assertTrue(marker.isEndedMarker());
		assertTrue(marker.getSessionId().startsWith(SessionSnapshot.ENDED_ID_PREFIX));
		assertEquals(Long.valueOf(assigned), marker.getAssignedAt());
		assertEquals(Long.valueOf(now), marker.getPreviousSessionEnd());
		assertEquals(49, marker.getRemaining());

		SessionTracker restarted = new SessionTracker(() -> now);
		restarted.setAccount(ACCOUNT);
		restarted.observe("Abyssal demons", DEMON_ID, 49, 50, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restarted.restoreEnded(marker, counters));
		assertEquals(Status.ENDED, restarted.getStatus());
		restarted.observe("Abyssal demons", DEMON_ID, 48, 50, false);
		assertEquals(State.IDLE, restarted.getState());

		// Another task by then: nothing to restore.
		SessionTracker newTask = new SessionTracker(() -> now);
		newTask.observe("Black dragons", DRAGON_ID, 20, false);
		assertEquals(SessionTracker.RestoreResult.MISMATCH, newTask.restoreEnded(marker, counters));
		assertEquals("not Ended", Status.WAITING_FOR_FIRST_KILL, newTask.getStatus());
		assertNull("nothing Ended, no marker", newTask.endedMarker(counters, now));
	}

	@Test
	public void aSnapshotCarriesTheClampsAndTheStateAndRestoresAsLoggedOut()
	{
		demons(50);
		final long assigned = now;
		now += MINUTE;
		demons(49, fightFrom(now - 10_000));
		now += MINUTE;
		tracker.pause();
		final long paused = now;
		now += MINUTE;
		tracker.loggedOut();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), null, now);
		assertEquals("LOGGED_OUT", snapshot.getTrackingState());
		assertEquals(Long.valueOf(paused), snapshot.getSegmentClosedAt());
		assertEquals(Long.valueOf(assigned), snapshot.getAssignedAt());
		assertEquals(Collections.singletonList("abyssal demon"), snapshot.getTaskNpcs());

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 49, 50, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(snapshot, null));
		assertEquals(State.LOGGED_OUT, restored.getState());
		assertEquals(Collections.singletonList("abyssal demon"), restored.summary().getSegments().getTaskNpcs());
		now += MINUTE;
		restored.observe("Abyssal demons", DEMON_ID, 48, 50, TaskContext.NONE, LocationTally.NO_REGION, false,
			fightFrom(paused - MINUTE));
		assertEquals("clamped to the restored segment close", 70_000 + (now - paused), restored.getActiveMillis());
		assertEquals(2, restored.getKills());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Before;
import org.junit.Test;

/**
 * Superior spawns, bank trips and deaths on the session: RUNNING-only counting, the completion grace window, reset on session
 * end, and how they travel through snapshots, restores, records and JSON.
 */
public class SessionTrackerCountersTest
{
	private static final int DEMON_ID = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	private final Gson gson = new Gson();
	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
	}

	@Test
	public void countedOnlyWhileRunning()
	{
		assertFalse("idle", tracker.addSuperiorSpawn());
		assertFalse("idle", tracker.addBankTrip());
		assertFalse("idle", tracker.addDeath());
		assertTrue(tracker.startNow(ACCOUNT));
		assertTrue(tracker.addSuperiorSpawn());
		assertTrue(tracker.addBankTrip());
		assertTrue(tracker.addBankTrip());
		assertTrue(tracker.addDeath());
		tracker.pause();
		assertFalse("paused", tracker.addSuperiorSpawn());
		assertFalse("paused", tracker.addBankTrip());
		assertFalse("paused", tracker.addDeath());
		assertEquals(1, tracker.getSuperiorsSpawned());
		assertEquals(2, tracker.getBankTrips());
		assertEquals(1, tracker.getDeaths());
		SessionTracker.Summary summary = tracker.activeSummary();
		assertEquals(Integer.valueOf(1), summary.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(2), summary.getBankTrips());
		assertEquals(Integer.valueOf(1), summary.getDeaths());
	}

	@Test
	public void resetWhenTheSessionEnds()
	{
		tracker.startNow(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addDeath();
		SessionTracker.Summary ended = tracker.stopAndReset();
		assertEquals(Integer.valueOf(1), ended.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), ended.getBankTrips());
		assertEquals(Integer.valueOf(1), ended.getDeaths());
		assertEquals(0, tracker.getSuperiorsSpawned());
		assertEquals(0, tracker.getBankTrips());
		assertEquals(0, tracker.getDeaths());

		tracker.startNow(ACCOUNT);
		SessionTracker.Summary next = tracker.activeSummary();
		assertEquals("a new session starts at 0, not unknown", Integer.valueOf(0), next.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(0), next.getBankTrips());
		assertEquals(Integer.valueOf(0), next.getDeaths());
	}

	@Test
	public void notAddedToACompletedSessionHeldForLateLoot()
	{
		tracker.startNow(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true);
		tracker.addDeath();
		assertTrue(tracker.holdCompletion());
		assertFalse(tracker.addSuperiorSpawn());
		assertFalse(tracker.addBankTrip());
		assertFalse(tracker.addDeath());
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(Integer.valueOf(1), held.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), held.getBankTrips());
		assertEquals(Integer.valueOf(1), held.getDeaths());
	}

	@Test
	public void lateLootKeepsTheCounts()
	{
		tracker.startNow(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true);
		tracker.holdCompletion();
		ItemTally loot = new ItemTally();
		loot.add(526, 1);
		tracker.addLoot(loot);
		assertEquals(Integer.valueOf(1), tracker.takePendingCompletion().getSuperiorsSpawned());
	}

	@Test
	public void recordCarriesTheCounts()
	{
		tracker.startNow(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addDeath();
		tracker.addDeath();
		tracker.addDeath();
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(2), record.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), record.getBankTrips());
		assertEquals(Integer.valueOf(3), record.getDeaths());
		LedgerRecord read = gson.fromJson(gson.toJson(record), LedgerRecord.class);
		assertEquals(record, read);
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, read.getSchemaVersion());
		assertEquals(3, LedgerRecord.CURRENT_SCHEMA_VERSION);
	}

	@Test
	public void zeroCountsAreSavedAsZeroNotUnknown()
	{
		tracker.startNow(ACCOUNT);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		String json = gson.toJson(record);
		assertTrue(json, json.contains("\"superiorsSpawned\":0"));
		assertTrue(json, json.contains("\"bankTrips\":0"));
		assertTrue(json, json.contains("\"deaths\":0"));
	}

	@Test
	public void olderRecordsReadAsUnknown()
	{
		LedgerRecord old = gson.fromJson("{\"schemaVersion\":2,\"id\":\"x\",\"monster\":\"Abyssal demons\",\"kills\":5}",
			LedgerRecord.class);
		assertNull(old.getSuperiorsSpawned());
		assertNull(old.getBankTrips());
		assertNull(old.getDeaths());
		String json = gson.toJson(old);
		assertFalse("unknown counts are not written", json.contains("superiorsSpawned"));
		assertFalse(json.contains("bankTrips"));
		assertFalse(json.contains("deaths"));
	}

	@Test
	public void snapshotRoundTripAndRestoreCarryTheCounts()
	{
		tracker.startNow(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addBankTrip();
		tracker.addDeath();
		tracker.loggedOut();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(Integer.valueOf(1), snapshot.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(2), snapshot.getBankTrips());
		assertEquals(Integer.valueOf(1), snapshot.getDeaths());
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(snapshot, read);

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertEquals(1, restored.getSuperiorsSpawned());
		assertEquals(2, restored.getBankTrips());
		assertEquals(1, restored.getDeaths());
		assertTrue(restored.startNow(ACCOUNT));
		restored.addSuperiorSpawn();
		restored.addDeath();
		LedgerRecord record = LedgerRecord.fromSummary(restored.stopAndReset(), true);
		assertEquals(Integer.valueOf(2), record.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(2), record.getBankTrips());
		assertEquals(Integer.valueOf(2), record.getDeaths());
	}

	@Test
	public void olderSnapshotRestoresFromZeroAndMismatchKeepsUnknown()
	{
		tracker.startNow(ACCOUNT);
		tracker.loggedOut();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		snapshot.setSuperiorsSpawned(null);
		snapshot.setBankTrips(null);
		snapshot.setDeaths(null);
		SessionSnapshot old = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertNull(old.getSuperiorsSpawned());

		// Saved as a partial record when it cannot be restored: the counts stay unknown.
		LedgerRecord partial = LedgerRecord.fromSummary(old.toSummary(SlayerSpots.NONE), true);
		assertNull(partial.getSuperiorsSpawned());
		assertNull(partial.getBankTrips());
		assertNull(partial.getDeaths());

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(old, COUNTERS));
		assertEquals(0, restored.getSuperiorsSpawned());
		assertEquals(0, restored.getBankTrips());
		assertEquals(0, restored.getDeaths());
		assertNotNull(restored.activeSummary().getBankTrips());
		assertNotNull(restored.activeSummary().getDeaths());
	}

	@Test
	public void snapshotToSummaryKeepsTheCounts()
	{
		tracker.startNow(ACCOUNT);
		tracker.addSuperiorSpawn();
		tracker.addBankTrip();
		tracker.addDeath();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		SessionTracker.Summary summary = snapshot.toSummary(SlayerSpots.NONE);
		assertEquals(Integer.valueOf(1), summary.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(1), summary.getBankTrips());
		assertEquals(Integer.valueOf(1), summary.getDeaths());
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.TestSpots.CATACOMBS;
import static com.shmayvan.slayerledger.TestSpots.CATACOMBS_ID;
import static com.shmayvan.slayerledger.TestSpots.SMOKE;
import static com.shmayvan.slayerledger.TestSpots.SMOKE_ID;
import static com.shmayvan.slayerledger.TestSpots.TABLE;
import static com.shmayvan.slayerledger.TestSpots.TOWER;
import static com.shmayvan.slayerledger.TestSpots.TOWER_ID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Before;
import org.junit.Test;

/**
 * Kills per place in {@link SessionTracker}: tallied exactly when kills are counted, kept by snapshots and
 * restores, and saved as the record's spot and region.
 */
public class SessionTrackerLocationTest
{
	private static final int DEMON_ID = 42;
	private static final String DEMONS = "Abyssal demons";
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};
	private static final TaskContext KONAR = TaskContext.of(SlayerMaster.KONAR, 7, "Kraken Cove", null, null);

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = newTracker();
		observe(50, SMOKE);
	}

	private SessionTracker newTracker()
	{
		SessionTracker t = new SessionTracker(() -> now);
		t.setSpots(TABLE);
		return t;
	}

	/** Observes at the centre of {@code region}, as the plugin reads the player's tile. */
	private SessionTracker.ObserveResult observe(int remaining, int region)
	{
		return observe(remaining, region, TaskContext.NONE, false);
	}

	private SessionTracker.ObserveResult observe(int remaining, int region, TaskContext context, boolean completed)
	{
		KillPlace place = LocationTally.isRegion(region) ? TestSpots.centre(region) : KillPlace.NONE;
		return tracker.observe(DEMONS, DEMON_ID, remaining, 150, context, place, completed, KillPairing.NONE);
	}

	@Test
	public void killsAreTalliedWhereTheyAreCounted()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		observe(47, SMOKE);
		observe(45, CATACOMBS);
		observe(44, SMOKE);
		assertEquals("the most recent place last",
			Arrays.asList(new LocationKills(CATACOMBS, CATACOMBS_ID, 2), new LocationKills(SMOKE, SMOKE_ID, 4)),
			tracker.getLocationKills());
		assertEquals(new TaskSpot(SMOKE_ID, SMOKE), tracker.getTaskSpot());
		assertEquals(6, tracker.getKills());
	}

	@Test
	public void killsWithoutARegionStillCountUntallied()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		observe(48, LocationTally.NO_REGION);
		assertEquals(2, tracker.getKills());
		assertTrue(tracker.getLocationKills().isEmpty());
		assertEquals(TaskSpot.UNKNOWN, tracker.getTaskSpot());
	}

	@Test
	public void killsWithoutASessionAreNotTalliedButAKillThatRestartsOneIs()
	{
		// No account is known, so these kills start no session.
		observe(49, CATACOMBS);
		observe(48, SMOKE);
		assertTrue(tracker.startNow(ACCOUNT));
		observe(47, SMOKE);
		assertEquals(Collections.singletonList(new LocationKills(SMOKE, SMOKE_ID, 1)), tracker.getLocationKills());

		// A kill while paused restarts the session and is tallied where it happened.
		tracker.pause();
		observe(40, CATACOMBS);
		assertEquals(Arrays.asList(new LocationKills(SMOKE, SMOKE_ID, 1), new LocationKills(CATACOMBS, CATACOMBS_ID, 7)),
			tracker.getLocationKills());
		assertEquals(CATACOMBS_ID, tracker.getTaskSpot().getSpotId());
	}

	@Test
	public void theFinalKillIsTalliedWhereTheCountDropped()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		observe(2, SMOKE);
		// The count drops to 0 in the Catacombs; the completion is confirmed a tick later, after walking away.
		assertEquals(SessionTracker.ObserveResult.TASK_CLEARED, observe(0, CATACOMBS));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, SMOKE, TaskContext.NONE, true));
		assertEquals(Arrays.asList(new LocationKills(SMOKE, SMOKE_ID, 48), new LocationKills(CATACOMBS, CATACOMBS_ID, 2)),
			tracker.getLocationKills());

		assertTrue(tracker.holdCompletion());
		assertEquals("the spot is the held session's", new TaskSpot(SMOKE_ID, SMOKE),
			tracker.takePendingCompletion().getTaskSpot());
		assertTrue(tracker.getLocationKills().isEmpty());
	}

	@Test
	public void aCompletionOnTheSameTickIsTallied()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, CATACOMBS, TaskContext.NONE, true));
		assertEquals(Collections.singletonList(new LocationKills(CATACOMBS, CATACOMBS_ID, 50)),
			tracker.getLocationKills());
	}

	@Test
	public void placesPastTheLimitStillCountKills()
	{
		tracker = newTracker();
		observe(140, SMOKE);
		assertTrue(tracker.startNow(ACCOUNT));
		for (int i = 0; i < LocationTally.MAX_REGIONS; i++)
		{
			observe(139 - i, 1_000 + i);
		}
		observe(139 - LocationTally.MAX_REGIONS, SMOKE);
		assertEquals(LocationTally.MAX_REGIONS + 1, tracker.getKills());
		assertEquals(LocationTally.MAX_REGIONS, tracker.getLocationKills().size());
	}

	@Test
	public void aTaskWithAnAssignedAreaIsStillPlacedByItsKills()
	{
		observe(50, SMOKE, KONAR, false);
		assertTrue(tracker.startNow(ACCOUNT));
		observe(49, SMOKE, KONAR, false);
		assertEquals(new TaskSpot(SMOKE_ID, SMOKE), tracker.getTaskSpot());
		assertEquals("Kraken Cove", tracker.getSessionTaskLocation());

		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(SMOKE), record.getLocationRegion());
		assertEquals(SMOKE_ID, record.getSpotId());
		assertNull("no name is saved", record.getLocation());
		assertEquals("the area is kept apart", "Kraken Cove", record.getTaskLocation());
	}

	@Test
	public void theRecordKeepsTheSpotAndItsRegionWithoutAName()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		observe(49, CATACOMBS);
		observe(47, SMOKE);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(SMOKE), record.getLocationRegion());
		assertEquals(SMOKE_ID, record.getSpotId());
		assertNull(record.getLocation());

		tracker.reset();
		assertTrue(tracker.startNow(ACCOUNT));
		LedgerRecord none = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertNull(none.getLocationRegion());
		assertNull(none.getSpotId());
		assertNull(none.getLocation());
	}

	@Test
	public void snapshotsAndRestoresKeepTheTally()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		observe(47, CATACOMBS);
		observe(46, SMOKE);
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(Arrays.asList(new LocationKills(CATACOMBS, CATACOMBS_ID, 3), new LocationKills(SMOKE, SMOKE_ID, 1)),
			snapshot.getLocationKills());
		Gson gson = new Gson();
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(snapshot, read);
		LedgerRecord partial = LedgerRecord.fromSummary(read.toSummary(SlayerSpots.NONE), true);
		assertEquals("a partial from the snapshot keeps its spot", CATACOMBS_ID, partial.getSpotId());
		assertEquals(Integer.valueOf(CATACOMBS), partial.getLocationRegion());

		SessionTracker restored = newTracker();
		restored.observe(DEMONS, DEMON_ID, 46, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertTrue(restored.startNow(ACCOUNT));
		restored.observe(DEMONS, DEMON_ID, 43, 150, TaskContext.NONE, TestSpots.centre(SMOKE), false, KillPairing.NONE);
		assertEquals(Arrays.asList(new LocationKills(CATACOMBS, CATACOMBS_ID, 3), new LocationKills(SMOKE, SMOKE_ID, 4)),
			restored.getLocationKills());
		assertEquals(new TaskSpot(SMOKE_ID, SMOKE), restored.getTaskSpot());
	}

	@Test
	public void aTallyKeptBeforeSpotsIsPlacedByItsRegions()
	{
		// Kills placed by their regions alone, as a 1.x active session kept them.
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.observe(DEMONS, DEMON_ID, 47, 150, TaskContext.NONE, TOWER, false);
		tracker.observe(DEMONS, DEMON_ID, 45, 150, TaskContext.NONE, CATACOMBS, false);
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(Arrays.asList(new LocationKills(TOWER, 3), new LocationKills(CATACOMBS, 2)),
			snapshot.getLocationKills());
		SessionTracker restored = newTracker();
		restored.observe(DEMONS, DEMON_ID, 45, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(snapshot, COUNTERS));
		assertEquals(new TaskSpot(TOWER_ID, TOWER), restored.getTaskSpot());
		assertTrue(restored.startNow(ACCOUNT));
		assertEquals(TOWER_ID, LedgerRecord.fromSummary(restored.stopAndReset(), true).getSpotId());
	}

	@Test
	public void anOlderSnapshotRestoresWithNoTally()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertNull("none yet, so not written", snapshot.getLocationKills());
		SessionTracker restored = newTracker();
		restored.observe(DEMONS, DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(snapshot, COUNTERS));
		assertTrue(restored.getLocationKills().isEmpty());
	}

	@Test
	public void theCurrentPlaceIsTheLatestObservedOneUntilTheTaskIsCleared()
	{
		assertEquals("observed while idle too", SMOKE, tracker.getCurrentRegion());
		assertEquals(SMOKE_ID, tracker.getCurrentSpot());
		observe(50, CATACOMBS);
		assertEquals(CATACOMBS, tracker.getCurrentRegion());
		assertEquals(CATACOMBS_ID, tracker.getCurrentSpot());
		observe(50, LocationTally.NO_REGION);
		assertEquals(LocationTally.NO_REGION, tracker.getCurrentRegion());
		assertNull(tracker.getCurrentSpot());
		// A place known by its region alone takes its region's spot.
		tracker.observe(DEMONS, DEMON_ID, 50, 150, TaskContext.NONE, TOWER, false);
		assertEquals(TOWER_ID, tracker.getCurrentSpot());
		tracker.clearCurrentTask();
		assertEquals(LocationTally.NO_REGION, tracker.getCurrentRegion());
		assertNull(tracker.getCurrentSpot());
	}

	@Test
	public void aNewSessionStartsWithNoTally()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		observe(49, SMOKE);
		tracker.stopAndReset();
		assertTrue(tracker.getLocationKills().isEmpty());
		assertTrue(tracker.startNow(ACCOUNT));
		assertEquals(TaskSpot.UNKNOWN, tracker.getTaskSpot());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import org.junit.Before;
import org.junit.Test;

/**
 * The note on a session: when it can be set (running, paused, or held for late loot), and how it travels through
 * snapshots, restores, records and JSON.
 */
public class SessionTrackerNoteTest
{
	private static final int DEMON_ID = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	private final Gson gson = new Gson();
	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
	}

	@Test
	public void setWhileRunningOrPausedAndNormalized()
	{
		assertFalse("no session", tracker.setNote(null, "Barrage"));
		assertTrue(tracker.startNow(ACCOUNT));
		String id = tracker.getSessionId();
		assertFalse("another session", tracker.setNote("other", "Barrage"));
		assertTrue(tracker.setNote(id, "  Barrage\n "));
		assertEquals("Barrage", tracker.getNote());
		assertEquals("Barrage", tracker.activeSummary().getNote());

		tracker.pause();
		assertTrue(tracker.setNote(id, "Prayer gear"));
		assertEquals("Prayer gear", tracker.getNote());
		assertTrue("cleared", tracker.setNote(id, "   "));
		assertNull(tracker.getNote());
	}

	@Test
	public void clearedWhenTheSessionEndsAndRefusedAfterwards()
	{
		tracker.startNow(ACCOUNT);
		String id = tracker.getSessionId();
		tracker.setNote(id, "Cannon");
		SessionTracker.Summary ended = tracker.stopAndReset();
		assertEquals("Cannon", ended.getNote());
		assertNull(tracker.getNote());
		assertFalse("the session is gone", tracker.setNote(id, "Barrage"));

		tracker.startNow(ACCOUNT);
		assertNull("a new session has no note", tracker.activeSummary().getNote());
	}

	@Test
	public void aNoteSetDuringTheGraceWindowReachesTheHeldSession()
	{
		tracker.startNow(ACCOUNT);
		String id = tracker.getSessionId();
		tracker.setNote(id, "Range pray");
		tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true);
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.setNote(id, "Barrage"));

		// A new session started during the grace window keeps its own note.
		tracker.observe("Abyssal demons", DEMON_ID, 30, 30, false);
		assertTrue(tracker.startNow(ACCOUNT));
		String next = tracker.getSessionId();
		assertTrue(tracker.setNote(next, "Cannon"));
		assertTrue(tracker.setNote(id, "Barrage, burst"));
		ItemTally loot = new ItemTally();
		loot.add(526, 1);
		tracker.addLoot(loot);

		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals("Barrage, burst", held.getNote());
		assertEquals("late loot keeps the note", 1, held.getLoot().get(526));
		assertEquals("Cannon", tracker.getNote());
		assertFalse("no longer held", tracker.setNote(id, "x"));
	}

	@Test
	public void recordCarriesTheNoteThroughJson()
	{
		tracker.startNow(ACCOUNT);
		tracker.setNote(tracker.getSessionId(), "Prayer gear");
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertEquals("Prayer gear", record.getNote());
		String json = gson.toJson(record);
		assertTrue(json, json.contains("\"note\":\"Prayer gear\""));
		LedgerRecord read = gson.fromJson(json, LedgerRecord.class);
		assertEquals(record, read);
		assertEquals(3, read.getSchemaVersion());
	}

	@Test
	public void recordWithoutANoteOmitsIt()
	{
		tracker.startNow(ACCOUNT);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertNull(record.getNote());
		String json = gson.toJson(record);
		assertFalse(json, json.contains("note"));
		assertEquals(record, gson.fromJson(json, LedgerRecord.class));
	}

	@Test
	public void olderRecordsHaveNoNote()
	{
		LedgerRecord old = gson.fromJson("{\"schemaVersion\":2,\"id\":\"x\",\"monster\":\"Abyssal demons\",\"kills\":5}",
			LedgerRecord.class);
		assertNull(old.getNote());
		SessionSnapshot oldSnapshot = gson.fromJson("{\"schemaVersion\":2,\"sessionId\":\"s\",\"accountHash\":555,"
			+ "\"creatureId\":42,\"remaining\":50,\"kills\":3}", SessionSnapshot.class);
		assertNull(oldSnapshot.getNote());
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(oldSnapshot, COUNTERS));
		assertNull(restored.getNote());
		assertTrue("a note can be added after the restore", restored.setNote("s", "Cannon"));
	}

	@Test
	public void snapshotRoundTripAndRestoreCarryTheNote()
	{
		tracker.startNow(ACCOUNT);
		tracker.setNote(tracker.getSessionId(), "Strength gear");
		tracker.loggedOut();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals("Strength gear", snapshot.getNote());
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(snapshot, read);

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertEquals("Strength gear", restored.getNote());
		assertEquals("as a partial record when it cannot be restored", "Strength gear",
			LedgerRecord.fromSummary(read.toSummary(SlayerSpots.NONE), true).getNote());
	}

	@Test
	public void aHandEditedSnapshotNoteIsNormalized()
	{
		tracker.startNow(ACCOUNT);
		tracker.loggedOut();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		snapshot.setNote("  Barrage \n");
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		restored.restore(snapshot, COUNTERS);
		assertEquals("Barrage", restored.getNote());
		assertEquals("Barrage", snapshot.toSummary(SlayerSpots.NONE).getNote());
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.client.util.Filepath;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * The live task's setup: the player's overrides set and cleared through {@link SessionTracker}, carried to
 * the saved record and through the active-session file (a logout and a client restart), the kills by NPC kept beside
 * them, and the kill contexts counted per task kill ({@link SessionTracker#addKillContext}) that the detected tags come
 * from. A session with no kill context falls back to its cannonballs for the cannon.
 */
public class SessionTrackerSetupTest
{
	private static final int DEMON_ID = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private final Gson gson = new Gson();
	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
	}

	private static ItemTally items(int id, long quantity)
	{
		final ItemTally tally = new ItemTally();
		tally.add(id, quantity);
		return tally;
	}

	@Test
	public void overridesAreSetAndClearedOnTheLiveTaskAndWinOverTheDetectedValues()
	{
		assertFalse("no session", tracker.setSetupOverrides(null, SetupOverrides.of(true, null, null)));
		assertTrue(tracker.startNow(ACCOUNT));
		final String id = tracker.getSessionId();
		assertEquals(SetupOverrides.NONE, tracker.getSetupOverrides());
		SetupTags tags = tracker.getSetupTags();
		assertFalse(tags.isCannon());
		assertEquals(SetupStyle.UNKNOWN, tags.getStyle());
		assertEquals(GearFocus.UNKNOWN, tags.getGear());
		assertFalse("live tags are never estimates", tags.isCannonEstimated() || tags.isStyleEstimated());

		assertFalse("another session", tracker.setSetupOverrides("other", SetupOverrides.of(true, null, null)));
		final SetupOverrides mine = SetupOverrides.of(true, SetupStyle.BARRAGE, GearFocus.PRAYER);
		assertTrue(tracker.setSetupOverrides(id, mine));
		tags = tracker.getSetupTags();
		assertTrue(tags.isCannon());
		assertEquals(SetupStyle.BARRAGE, tags.getStyle());
		assertEquals(GearFocus.PRAYER, tags.getGear());
		assertFalse("the detected cannon is kept", tags.isDetectedCannon());

		tracker.pause();
		assertTrue("paused", tracker.setSetupOverrides(id, mine.withCannon(null).withGear(null)));
		tags = tracker.getSetupTags();
		assertFalse("cleared: the detected cannon again", tags.isCannon());
		assertEquals(SetupStyle.BARRAGE, tags.getStyle());
		assertEquals(GearFocus.UNKNOWN, tags.getGear());

		assertTrue("all cleared", tracker.setSetupOverrides(id, null));
		assertEquals(SetupOverrides.NONE, tracker.getSetupOverrides());
	}

	@Test
	public void killContextsAreCountedForTheSessionsLastKillAndDecideItsTags()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		assertFalse("no kill yet", tracker.addKillContext(tracker.getLastKillAt(), true, null, null, null));
		now += 600;
		tracker.observe("Abyssal demons", DEMON_ID, 48, 150, false);
		final long killAt = tracker.getLastKillAt();
		assertEquals(2, tracker.getKills());
		assertTrue(tracker.addKillContext(killAt, true, SetupStyle.BARRAGE, GearFocus.PRAYER, 30));
		assertTrue(tracker.addKillContext(killAt, false, null, GearFocus.PRAYER, 30));
		assertFalse("another kill's", tracker.addKillContext(killAt - 1, true, SetupStyle.MELEE, null, null));

		SetupTags tags = tracker.getSetupTags();
		assertTrue("1 cannon kill of 2", tags.isCannon());
		assertEquals("the only styled kill", SetupStyle.BARRAGE, tags.getStyle());
		assertEquals(GearFocus.PRAYER, tags.getGear());

		now += 600;
		tracker.observe("Abyssal demons", DEMON_ID, 47, 150, false);
		assertTrue(tracker.addKillContext(tracker.getLastKillAt(), false, SetupStyle.MELEE, GearFocus.STRENGTH, 8));
		tags = tracker.getSetupTags();
		assertFalse("1 cannon kill of 3", tags.isCannon());
		assertEquals("a tie between Barrage and Melee", SetupStyle.MIXED, tags.getStyle());
		assertEquals(GearFocus.PRAYER, tags.getGear());

		tracker.pause();
		assertFalse("a context arriving after a later kill is refused", tracker.addKillContext(killAt, true, null,
			null, null));
		assertTrue("a stopped session still takes its last kill's", tracker.addKillContext(tracker.getLastKillAt(),
			false, SetupStyle.MELEE, GearFocus.STRENGTH, 6));
		final LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(1), record.getCannonKills());
		assertEquals(SetupStyle.MELEE, record.getDetectedStyle());
		assertEquals("2 Prayer kills and 2 Strength", GearFocus.MIXED, record.getDetectedGear());
		assertEquals(Integer.valueOf(6), record.getPrayerBonusMin());
		assertEquals(Integer.valueOf(30), record.getPrayerBonusMax());
		assertFalse("no session", tracker.addKillContext(killAt, true, null, null, null));
	}

	@Test
	public void theFinalKillsContextReachesTheCompletionHeldForLateLoot()
	{
		tracker.startNow(ACCOUNT);
		now += 600;
		tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true);
		final long killAt = tracker.getLastKillAt();
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.addKillContext(killAt, true, SetupStyle.RANGED, GearFocus.STRENGTH, 6));
		final LedgerRecord record = LedgerRecord.fromSummary(tracker.takePendingCompletion(), false);
		assertEquals(Integer.valueOf(1), record.getCannonKills());
		assertEquals(SetupStyle.RANGED, record.getDetectedStyle());
		assertFalse("no longer held", tracker.addKillContext(killAt, true, null, null, null));
	}

	/** With no kill context counted, the detected cannon falls back to the cannonballs fired. */
	@Test
	public void theDetectedCannonComesFromTheCannonballsFiredAndTheOverrideStillWins()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.addSupplies(items(SupplyTracker.CANNONBALL, 30), null, null);
		assertTrue(tracker.getSetupTags().isCannon());
		assertTrue(tracker.setSetupOverrides(tracker.getSessionId(), SetupOverrides.of(false, null, null)));
		assertFalse(tracker.getSetupTags().isCannon());
		assertTrue(tracker.getSetupTags().isDetectedCannon());

		final LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Boolean.TRUE, record.getDetectedCannon());
		assertEquals(Boolean.FALSE, record.getCannonOverride());
		assertFalse(SetupTags.of(record).isCannon());
		assertFalse("grouping follows the effective Cannon tag", record.cannonTask());
		assertEquals("Abyssal demons", record.groupName());
	}

	@Test
	public void theOverridesAndKillsByNpcAreCarriedToTheSavedRecord()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.addNpcKill("Abyssal demon");
		tracker.addNpcKill("Abyssal demon");
		tracker.addNpcKill("Ankou");
		tracker.setSetupOverrides(tracker.getSessionId(), SetupOverrides.of(null, SetupStyle.MELEE, null));
		final SessionTracker.Summary ended = tracker.stopAndReset();
		assertEquals(SetupOverrides.of(null, SetupStyle.MELEE, null), ended.getSetupOverrides());

		final LedgerRecord record = LedgerRecord.fromSummary(ended, false);
		assertEquals(Arrays.asList(new NpcKills("Abyssal demon", 2), new NpcKills("Ankou", 1)), record.getNpcKills());
		assertEquals(SetupStyle.MELEE, record.getStyleOverride());
		assertEquals(SetupStyle.UNKNOWN, record.getDetectedStyle());
		assertEquals(SetupStyle.MELEE, SetupTags.of(record).getStyle());
		assertNull("no kill context counted", record.getCannonKills());
		assertEquals(record, gson.fromJson(gson.toJson(record), LedgerRecord.class));

		assertEquals("the next session starts without overrides", SetupOverrides.NONE, tracker.getSetupOverrides());
		assertFalse("the ended session takes none", tracker.setSetupOverrides(ended.getSessionId(),
			SetupOverrides.of(true, null, null)));
	}

	@Test
	public void anOverrideSetDuringTheGraceWindowReachesTheHeldSession()
	{
		tracker.startNow(ACCOUNT);
		final String id = tracker.getSessionId();
		tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true);
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.setSetupOverrides(id, SetupOverrides.of(true, null, null)));
		final SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(Boolean.TRUE, LedgerRecord.fromSummary(held, false).getCannonOverride());
		assertFalse("no longer held", tracker.setSetupOverrides(id, SetupOverrides.NONE));
	}

	@Test
	public void overridesAndKillContextsSurviveTheActiveSessionFileAndARestore() throws IOException
	{
		tracker.startNow(ACCOUNT);
		tracker.addNpcKill("Abyssal demon");
		final SetupOverrides mine = SetupOverrides.of(false, SetupStyle.RANGED, GearFocus.STRENGTH);
		tracker.setSetupOverrides(tracker.getSessionId(), mine);
		tracker.loggedOut();
		final SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(Boolean.FALSE, snapshot.getCannonOverride());
		assertEquals(SetupStyle.RANGED, snapshot.getStyleOverride());
		assertEquals(GearFocus.STRENGTH, snapshot.getGearOverride());
		assertNull(snapshot.getCannonKills());
		// A snapshot holding kill contexts, as the plugin counts them, must keep them.
		final SetupKills kills = SetupKills.NONE.withKill(true, SetupStyle.RANGED, GearFocus.STRENGTH, 3)
			.withKill(false, SetupStyle.RANGED, GearFocus.MIXED, 18);
		kills.copyTo(snapshot);

		// Through the active-session file, as a logout and a client restart write and read it.
		final LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(
			new File(temp.getRoot(), "slayer-ledger").toPath()), gson);
		store.writeActive(ACCOUNT, snapshot);
		final SessionSnapshot read = store.readActive(ACCOUNT);
		assertEquals(snapshot, read);
		assertEquals(SessionSnapshot.CURRENT_SCHEMA_VERSION, read.getSchemaVersion());

		final SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertEquals(mine, restored.getSetupOverrides());
		assertEquals(kills, restored.getSetupKills());
		assertEquals(SetupStyle.RANGED, restored.getSetupTags().getStyle());
		assertEquals("written back unchanged", read,
			SessionSnapshot.fromSummary(restored.activeSummary(), COUNTERS, read.getSavedAt()));

		final LedgerRecord record = LedgerRecord.fromSummary(restored.stopAndReset(), true);
		assertEquals(Integer.valueOf(1), record.getCannonKills());
		assertEquals(Collections.singletonMap("RANGED", 2), record.getStyleKills());
		assertEquals(Integer.valueOf(3), record.getPrayerBonusMin());
		assertEquals(Integer.valueOf(18), record.getPrayerBonusMax());
		assertEquals(mine, SetupOverrides.from(record));

		assertEquals("as a partial record when it cannot be restored", mine,
			SetupOverrides.from(LedgerRecord.fromSummary(read.toSummary(SlayerSpots.NONE), true)));
		assertEquals(kills, SetupKills.from(LedgerRecord.fromSummary(read.toSummary(SlayerSpots.NONE), true)));
	}

	/**
	 * a cannon task a 1.x version started keeps its Cannon tag after its next kill. Its 10 kills recorded no
	 * context, so the cannon share counts only the kills since the restore; the style and gear never counted them.
	 */
	@Test
	public void aCannonTaskRestoredFromA1xFileCountsOnlyTheKillsSinceForItsCannonTag() throws IOException
	{
		final SessionSnapshot oneX = gson.fromJson("{\"schemaVersion\":2,\"sessionId\":\"s\",\"accountHash\":555,"
			+ "\"monster\":\"Abyssal demons\",\"creatureId\":42,\"originalAmount\":150,\"remaining\":50,\"kills\":10,"
			+ "\"supplies\":{\"" + SupplyTracker.CANNONBALL + "\":120}}", SessionSnapshot.class);
		assertEquals(10, oneX.killsWithoutContexts());
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(oneX, COUNTERS));
		assertTrue("no context yet: the cannonballs fired", tracker.getSetupTags().isCannon());
		assertEquals(0, tracker.getContextKills());

		now += 60_000;
		tracker.observe("Abyssal demons", DEMON_ID, 49, 150, false);
		assertTrue(tracker.addKillContext(tracker.getLastKillAt(), true, SetupStyle.MELEE, GearFocus.STRENGTH, 8));
		assertEquals(11, tracker.getKills());
		assertEquals("the live Cannon tooltip's kills", 1, tracker.getContextKills());
		SetupTags tags = tracker.getSetupTags();
		assertTrue("1 cannon kill of the 1 since the restore, not of 11", tags.isCannon());
		assertEquals(SetupStyle.MELEE, tags.getStyle());
		assertEquals(GearFocus.STRENGTH, tags.getGear());

		now += 60_000;
		tracker.observe("Abyssal demons", DEMON_ID, 48, 150, false);
		assertTrue(tracker.addKillContext(tracker.getLastKillAt(), false, SetupStyle.MELEE, GearFocus.STRENGTH, 8));
		assertTrue("1 of 2: half", tracker.getSetupTags().isCannon());
		assertEquals(2, tracker.getContextKills());

		// Logged out and restored after a client restart: the active file keeps the kills without a context.
		tracker.loggedOut();
		final SessionSnapshot persisted = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(Integer.valueOf(10), persisted.getKillsBeforeContexts());
		final LedgerStore store = new LedgerStore(Filepath.Unchecked.getRooted(
			new File(temp.getRoot(), "slayer-ledger").toPath()), gson);
		store.writeActive(ACCOUNT, persisted);
		final SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 48, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(store.readActive(ACCOUNT), COUNTERS));
		assertTrue(restored.getSetupTags().isCannon());
		assertEquals(2, restored.getContextKills());
		assertEquals("as a partial record when it cannot be restored", Boolean.TRUE,
			LedgerRecord.fromSummary(persisted.toSummary(SlayerSpots.NONE), true).getDetectedCannon());

		final LedgerRecord record = LedgerRecord.fromSummary(restored.stopAndReset(), true);
		assertEquals(Boolean.TRUE, record.getDetectedCannon());
		assertEquals(Integer.valueOf(1), record.getCannonKills());
		assertEquals("Abyssal demons (cannon)", record.groupName());

		// A third kill without the cannon: 1 of 3 since the restore, so no longer a cannon task.
		final SessionTracker third = new SessionTracker(() -> now);
		third.observe("Abyssal demons", DEMON_ID, 48, 150, false);
		third.restore(store.readActive(ACCOUNT), COUNTERS);
		now += 60_000;
		third.observe("Abyssal demons", DEMON_ID, 47, 150, false);
		assertTrue(third.addKillContext(third.getLastKillAt(), false, SetupStyle.MELEE, GearFocus.STRENGTH, 8));
		assertFalse(third.getSetupTags().isCannon());
	}

	/** a 2.0 session's kills all count for its cannon share, also those whose context was lost. */
	@Test
	public void aRestored2_0SessionCountsAllItsKillsForItsCannonTag()
	{
		final SessionSnapshot mixed = gson.fromJson("{\"schemaVersion\":3,\"sessionId\":\"s\",\"accountHash\":555,"
			+ "\"monster\":\"Abyssal demons\",\"creatureId\":42,\"originalAmount\":150,\"remaining\":50,\"kills\":4,"
			+ "\"cannonKills\":1,\"styleKills\":{\"MELEE\":3}}", SessionSnapshot.class);
		assertEquals(0, mixed.killsWithoutContexts());
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(mixed, COUNTERS));
		assertFalse("1 of 4", tracker.getSetupTags().isCannon());
		now += 60_000;
		tracker.observe("Abyssal demons", DEMON_ID, 49, 150, false);
		tracker.addKillContext(tracker.getLastKillAt(), true, null, null, null);
		assertFalse("2 of 5", tracker.getSetupTags().isCannon());
		now += 60_000;
		tracker.observe("Abyssal demons", DEMON_ID, 48, 150, false);
		tracker.addKillContext(tracker.getLastKillAt(), true, null, null, null);
		assertTrue("3 of 6", tracker.getSetupTags().isCannon());
		assertEquals(6, tracker.getContextKills());
		assertNull(SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now).getKillsBeforeContexts());

		// A 2.0 session whose kills all lost their context (a logout on the next tick) has none left out either.
		final SessionSnapshot lost = gson.fromJson("{\"schemaVersion\":3,\"sessionId\":\"t\",\"accountHash\":555,"
			+ "\"kills\":4}", SessionSnapshot.class);
		assertEquals(0, lost.killsWithoutContexts());
	}

	@Test
	public void aSnapshotFromBeforeSetupRestoresWithNone()
	{
		final SessionSnapshot old = gson.fromJson("{\"schemaVersion\":2,\"sessionId\":\"s\",\"accountHash\":555,"
			+ "\"creatureId\":42,\"remaining\":50,\"kills\":3}", SessionSnapshot.class);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(old, COUNTERS));
		assertEquals(SetupOverrides.NONE, tracker.getSetupOverrides());
		assertEquals(SetupKills.NONE, tracker.getSetupKills());
		assertTrue("overrides can be set after the restore",
			tracker.setSetupOverrides("s", SetupOverrides.of(true, null, null)));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import org.junit.Before;
import org.junit.Test;

/** {@link SessionTracker#takeSessionTaskKeys()}: which tasks a session held since the last call. */
public class SessionTrackerTaskKeysTest
{
	private static final int DEMONS = 42;
	private static final int GARGOYLES = 46;
	private static final long ACCOUNT = 555L;

	private long now = 1_000_000L;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new SessionTracker(() -> now);
		tracker.observe("Abyssal demons", DEMONS, 100, false);
	}

	@Test
	public void noSessionHoldsNoTask()
	{
		assertTrue(tracker.takeSessionTaskKeys().isEmpty());
	}

	@Test
	public void anActiveSessionsTaskIsReportedEveryCall()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
		tracker.pause();
		assertEquals("paused too", Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
	}

	@Test
	public void aSessionThatEndedBeforeTheCallIsStillReportedOnce()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.stopAndReset();
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
		assertTrue(tracker.takeSessionTaskKeys().isEmpty());
	}

	@Test
	public void aTaskAdoptedLaterIsReported()
	{
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertTrue(tracker.startNow(ACCOUNT));
		assertTrue("no task yet", tracker.takeSessionTaskKeys().isEmpty());
		tracker.observe("Gargoyles", GARGOYLES, 150, false);
		assertEquals(Collections.singleton(GARGOYLES), tracker.takeSessionTaskKeys());
	}

	@Test
	public void aHeldCompletionIsReported()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.takeSessionTaskKeys();
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.holdCompletion());
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
		tracker.takePendingCompletion();
		assertTrue(tracker.takeSessionTaskKeys().isEmpty());
	}

	@Test
	public void aRestoredSessionIsReported()
	{
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(startedSummary(), null, now);
		snapshot.setAccountHash(ACCOUNT);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(snapshot, null));
		assertEquals(Collections.singleton(DEMONS), tracker.takeSessionTaskKeys());
	}

	/** A stopped session on the demons task, as saved at a logout. */
	private SessionTracker.Summary startedSummary()
	{
		SessionTracker other = new SessionTracker(() -> now);
		other.observe("Abyssal demons", DEMONS, 100, false);
		other.startNow(ACCOUNT);
		return other.stopAndReset();
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.SessionTracker.ObserveResult;
import static com.shmayvan.slayerledger.SessionTracker.State;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class SessionTrackerTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final long OTHER_ACCOUNT = 777L;

	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		// Simulates the first post-login observation (no task yet) so Play is allowed.
		noTask();
	}

	private ObserveResult noTask()
	{
		return tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
	}

	private ObserveResult demons(int remaining)
	{
		return tracker.observe("Abyssal demons", DEMON_ID, remaining, false);
	}

	@Test
	public void transitions()
	{
		assertEquals(State.IDLE, tracker.getState());
		assertTrue(tracker.startNow(ACCOUNT));
		assertEquals(State.RUNNING, tracker.getState());
		assertTrue(tracker.pause());
		assertEquals(State.PAUSED, tracker.getState());
		assertTrue(tracker.resume(ACCOUNT));
		assertEquals(State.RUNNING, tracker.getState());
		assertTrue(tracker.loggedOut());
		assertEquals(State.LOGGED_OUT, tracker.getState());
		assertFalse("Resume is only for Paused", tracker.resume(ACCOUNT));
		assertTrue(tracker.stop());
		assertEquals(State.STOPPED, tracker.getState());
		assertTrue(tracker.reset());
		assertEquals(State.IDLE, tracker.getState());
	}

	@Test
	public void stopFromPaused()
	{
		tracker.startNow(ACCOUNT);
		tracker.pause();
		assertTrue(tracker.stop());
		assertEquals(State.STOPPED, tracker.getState());
	}

	@Test
	public void invalidTransitionsAreNoOps()
	{
		assertFalse(tracker.pause());
		assertFalse(tracker.stop());
		assertFalse(tracker.loggedOut());
		assertFalse(tracker.reset());
		assertNull(tracker.stopAndReset());
		assertEquals(State.IDLE, tracker.getState());

		tracker.startNow(ACCOUNT);
		assertFalse(tracker.startNow(ACCOUNT));
		assertFalse(tracker.reset());
		assertEquals(State.RUNNING, tracker.getState());

		tracker.pause();
		assertFalse(tracker.pause());
		assertFalse(tracker.resume(OTHER_ACCOUNT));
		assertFalse(tracker.checkAway());
		assertEquals(State.PAUSED, tracker.getState());

		tracker.loggedOut();
		assertFalse(tracker.loggedOut());
		assertFalse(tracker.pause());
		assertEquals(State.LOGGED_OUT, tracker.getState());

		tracker.stop();
		assertFalse(tracker.startNow(ACCOUNT));
		assertFalse(tracker.pause());
		assertFalse(tracker.stop());
		assertEquals(State.STOPPED, tracker.getState());
	}

	@Test
	public void elapsedOnlyAccumulatesWhileRunning()
	{
		now += 5_000; // idle time is not counted
		tracker.startNow(ACCOUNT);
		now += 10_000;
		assertEquals(10_000, tracker.getActiveMillis());
		tracker.pause();
		now += 60_000;
		assertEquals(10_000, tracker.getActiveMillis());
		tracker.resume(ACCOUNT);
		now += 2_500;
		assertEquals(12_500, tracker.getActiveMillis());
		tracker.stop();
		now += 30_000;
		assertEquals(12_500, tracker.getActiveMillis());
		assertEquals(12_500, tracker.summary().getActiveMillis());
	}

	@Test
	public void countsDecreasesAndAKillRestartsAPausedSession()
	{
		demons(100);
		demons(99); // no account known: no session starts, and the kill is not counted
		assertEquals(State.IDLE, tracker.getState());
		tracker.startNow(ACCOUNT);
		assertEquals(0, tracker.getKills());
		demons(97);
		assertEquals(2, tracker.getKills());
		tracker.pause();
		demons(90); // a task kill while paused restarts the session and counts
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals(9, tracker.getKills());
		demons(89);
		assertEquals(10, tracker.getKills());
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertNotNull(summary);
		assertEquals(99, summary.getInitialAmount());
		assertEquals(10, summary.getKills());
		assertEquals("Abyssal demons", summary.getMonster());
		assertEquals(DEMON_ID, summary.getCreatureId());
		assertFalse(summary.isCompleted());
		assertEquals(State.IDLE, tracker.getState());
		assertEquals(0, tracker.getKills());
	}

	@Test
	public void increasesAreNotKills()
	{
		tracker.startNow(ACCOUNT);
		demons(50); // first observation: baseline only
		assertEquals(0, tracker.getKills());
		demons(60); // e.g. extended task
		assertEquals(0, tracker.getKills());
		demons(58);
		assertEquals(2, tracker.getKills());
	}

	@Test
	public void sessionStartedWithoutTaskAdoptsFirstTask()
	{
		tracker.startNow(ACCOUNT);
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertFalse(tracker.summary().hasTask());
		demons(120);
		assertTrue(tracker.summary().hasTask());
		demons(119);
		assertEquals(1, tracker.getKills());
		assertEquals(120, tracker.summary().getInitialAmount());
	}

	@Test
	public void logoutStopsTheClockUntilTheNextKill()
	{
		demons(10);
		tracker.startNow(ACCOUNT);
		now += 1_000;
		assertTrue(tracker.loggedOut());
		assertEquals(State.LOGGED_OUT, tracker.getState());
		now += 5_000;
		assertEquals(1_000, tracker.getActiveMillis());
		// A reading without a kill (a login) is not a restart.
		demons(10);
		assertEquals(State.LOGGED_OUT, tracker.getState());
		now += 1_000;
		demons(9);
		assertEquals(State.RUNNING, tracker.getState());
		assertEquals(1, tracker.getKills());
		assertEquals("a kill with nothing paired restarts at the kill", 1_000, tracker.getActiveMillis());
	}

	@Test
	public void completionWithSignal()
	{
		demons(3);
		tracker.startNow(ACCOUNT);
		demons(1);
		assertEquals(ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.isCompleted());
		assertEquals(3, tracker.getKills());
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertTrue(summary.isCompleted());
		assertEquals(3, summary.getKills());
	}

	@Test
	public void completionSignalOnLaterObservation()
	{
		demons(2);
		tracker.startNow(ACCOUNT);
		assertEquals(ObserveResult.TASK_CLEARED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, false));
		assertFalse(tracker.isCompleted());
		assertEquals(ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.isCompleted());
		assertEquals(2, tracker.getKills());
	}

	@Test
	public void clearedWithoutCompletionIsNotCompleted()
	{
		demons(80);
		tracker.startNow(ACCOUNT);
		demons(75);
		// cancelled task: count drops to zero without a completion signal
		assertEquals(ObserveResult.TASK_CLEARED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, false));
		assertEquals(5, tracker.getKills());
		assertFalse(tracker.isCompleted());
		// then a new task is assigned
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe("Black dragons", DRAGON_ID, 20, false));
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertFalse(summary.isCompleted());
		assertEquals(5, summary.getKills());
		assertEquals("Abyssal demons", summary.getMonster());
		// the new task is current for the next session
		assertEquals("Black dragons", tracker.getCurrentMonster());
		assertEquals(20, tracker.getCurrentRemaining());
	}

	@Test
	public void taskChangeDuringSession()
	{
		demons(50);
		tracker.startNow(ACCOUNT);
		demons(45);
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe("Black dragons", DRAGON_ID, 30, false));
		// change of task does not count as kills
		assertEquals(5, tracker.getKills());
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals("Abyssal demons", summary.getMonster());
		tracker.startNow(ACCOUNT);
		assertEquals("Black dragons", tracker.summary().getMonster());
		assertEquals(30, tracker.summary().getInitialAmount());
	}

	@Test
	public void finalKillWhilePausedRestartsBeforeItCompletes()
	{
		demons(1);
		tracker.startNow(ACCOUNT);
		tracker.pause();
		assertEquals(ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertTrue(tracker.isCompleted());
		assertEquals(1, tracker.getKills());
		assertEquals("restarted first, so the completion can be held", State.RUNNING, tracker.getState());
		assertTrue(tracker.holdCompletion());
	}

	@Test
	public void partialFlagOnRecord()
	{
		demons(10);
		tracker.startNow(ACCOUNT);
		now += 3_000;
		demons(8);
		SessionTracker.Summary summary = tracker.stopAndReset();

		LedgerRecord partial = LedgerRecord.fromSummary(summary, true);
		assertTrue(partial.isPartial());
		assertFalse(partial.isCompleted());
		assertEquals(2, partial.getKills());
		assertEquals(10, partial.getInitialAmount());
		assertEquals(3_000, partial.getActiveMillis());
		assertEquals(Integer.valueOf(DEMON_ID), partial.getCreatureId());
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, partial.getSchemaVersion());
		assertNotNull(partial.getId());
		assertEquals(1_000_000L, partial.getStartedAt());
		assertEquals(1_003_000L, partial.getEndedAt());
	}

	@Test
	public void startNowRefusedUntilTaskObserved()
	{
		SessionTracker fresh = new SessionTracker(() -> now);
		assertFalse(fresh.startNow(ACCOUNT));
		assertEquals(State.IDLE, fresh.getState());
		fresh.observe("Abyssal demons", DEMON_ID, 10, false);
		assertFalse(fresh.startNow(SessionTracker.NO_ACCOUNT));
		assertTrue(fresh.startNow(ACCOUNT));
	}

	@Test
	public void clearCurrentTaskForgetsStaleTask()
	{
		demons(50);
		tracker.clearCurrentTask();
		assertNull(tracker.getCurrentMonster());
		assertEquals(0, tracker.getCurrentRemaining());
		assertFalse(tracker.isTaskObserved());
		assertFalse(tracker.startNow(ACCOUNT));

		// the first observation on the new login takes the fresh task
		tracker.observe("Black dragons", DRAGON_ID, 12, false);
		assertTrue(tracker.startNow(OTHER_ACCOUNT));
		assertEquals("Black dragons", tracker.summary().getMonster());
		assertEquals(12, tracker.summary().getInitialAmount());
	}

	@Test
	public void clearCurrentTaskBlocksResumeUntilObserved()
	{
		demons(50);
		tracker.startNow(ACCOUNT);
		tracker.pause();
		assertTrue(tracker.canResume(ACCOUNT));
		tracker.clearCurrentTask();
		assertFalse(tracker.canResume(ACCOUNT));
		assertFalse(tracker.resume(ACCOUNT));
		demons(50);
		assertTrue(tracker.resume(ACCOUNT));
	}

	@Test
	public void sessionAccountIsCapturedAtomically()
	{
		demons(50);
		tracker.startNow(ACCOUNT);
		assertEquals(ACCOUNT, tracker.getSessionAccountHash());
		tracker.pause();
		// resuming with another account is refused
		assertFalse(tracker.canResume(OTHER_ACCOUNT));
		assertFalse(tracker.resume(OTHER_ACCOUNT));
		assertFalse(tracker.startNow(OTHER_ACCOUNT));
		assertTrue(tracker.canResume(ACCOUNT));
		assertNull(tracker.stopAndResetIfOtherAccount(ACCOUNT));
		assertEquals(State.PAUSED, tracker.getState());

		SessionTracker.Summary summary = tracker.stopAndResetIfOtherAccount(OTHER_ACCOUNT);
		assertNotNull(summary);
		assertEquals(ACCOUNT, summary.getAccountHash());
		assertEquals(State.IDLE, tracker.getState());
		assertEquals(SessionTracker.NO_ACCOUNT, tracker.getSessionAccountHash());
		assertNull(tracker.stopAndResetIfOtherAccount(OTHER_ACCOUNT));
	}

	@Test
	public void sameTaskReturningAfterTransientZeroResumes()
	{
		demons(10);
		tracker.startNow(ACCOUNT);
		demons(8);
		assertEquals(ObserveResult.TASK_CLEARED, noTask());
		// the same task comes back: not a change, and the drop is not counted
		assertEquals(ObserveResult.NONE, demons(8));
		assertEquals(2, tracker.getKills());
		demons(7);
		assertEquals(3, tracker.getKills());
		// a completion signal while the task is still active is not a completion
		assertEquals(ObserveResult.NONE, tracker.observe("Abyssal demons", DEMON_ID, 7, true));
		assertFalse(tracker.isCompleted());
		assertEquals(ObserveResult.COMPLETED, tracker.observe(null, SessionTracker.NO_CREATURE, 0, true));
		assertEquals(10, tracker.getKills());
	}

	@Test
	public void lateCounterSyncWhileClearedIsNotCompletionAfterTaskReturns()
	{
		demons(10);
		tracker.startNow(ACCOUNT);
		noTask();
		demons(10);
		// even if a signal arrives now, the task is active again so it is not a completion
		assertEquals(ObserveResult.NONE, tracker.observe("Abyssal demons", DEMON_ID, 10, true));
		assertFalse(tracker.isCompleted());
	}

	@Test
	public void originalAmountIsTracked()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 120, 150, false);
		tracker.startNow(ACCOUNT);
		assertEquals(150, tracker.summary().getOriginalAmount());
		// extension changes the assigned size
		tracker.observe("Abyssal demons", DEMON_ID, 119, 200, false);
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(200, summary.getOriginalAmount());
		assertEquals(Integer.valueOf(200), LedgerRecord.fromSummary(summary, false).getOriginalAmount());
	}

	@Test
	public void unknownOriginalAmountIsNullOnRecord()
	{
		demons(20);
		tracker.startNow(ACCOUNT);
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(SessionTracker.UNKNOWN_AMOUNT, summary.getOriginalAmount());
		assertNull(LedgerRecord.fromSummary(summary, true).getOriginalAmount());
	}

	@Test
	public void unknownNameDoesNotLookLikeTaskChange()
	{
		tracker.observe(null, DEMON_ID, 30, false);
		tracker.startNow(ACCOUNT);
		// lookup succeeds later: same creature id, so same task, and the name is filled in
		assertEquals(ObserveResult.NONE, demons(29));
		assertEquals(1, tracker.getKills());
		assertEquals("Abyssal demons", tracker.summary().getMonster());
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe(null, DRAGON_ID, 30, false));
	}

	@Test
	public void unknownNameFallbackOnRecord()
	{
		tracker.observe(null, DEMON_ID, 30, false);
		tracker.startNow(ACCOUNT);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals("Unknown task (" + DEMON_ID + ")", record.getMonster());
	}

	@Test
	public void shortZeroGapResumesSameTask()
	{
		demons(10);
		tracker.startNow(ACCOUNT);
		demons(8);
		for (int i = 0; i < SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS; i++)
		{
			noTask();
		}
		// even with a higher count, a short gap is a glitch rather than a reassignment
		assertEquals(ObserveResult.NONE, demons(9));
		assertEquals(2, tracker.getKills());
	}

	@Test
	public void longZeroGapWithSameCreatureIsTaskChange()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, 150, false);
		tracker.startNow(ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 8, 150, false);
		for (int i = 0; i <= SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS; i++)
		{
			noTask();
		}
		// cancelled then reassigned to the same creature with a new size
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe("Abyssal demons", DEMON_ID, 120, 120, false));
		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(2, summary.getKills());
		assertFalse(summary.isCompleted());
	}

	@Test
	public void longZeroGapWithHigherRemainingIsTaskChangeEvenWithSameSize()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, 150, false);
		tracker.startNow(ACCOUNT);
		for (int i = 0; i <= SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS; i++)
		{
			noTask();
		}
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe("Abyssal demons", DEMON_ID, 150, 150, false));
	}

	@Test
	public void longZeroGapWithUnchangedSizeAndNoIncreaseResumes()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 10, 150, false);
		tracker.startNow(ACCOUNT);
		tracker.observe("Abyssal demons", DEMON_ID, 8, 150, false);
		for (int i = 0; i < 10; i++)
		{
			noTask();
		}
		assertEquals(ObserveResult.NONE, tracker.observe("Abyssal demons", DEMON_ID, 8, 150, false));
		tracker.observe("Abyssal demons", DEMON_ID, 6, 150, false);
		assertEquals(4, tracker.getKills());
	}

	@Test
	public void longZeroGapWithUnknownSizeIsTaskChange()
	{
		demons(10);
		tracker.startNow(ACCOUNT);
		for (int i = 0; i <= SessionTracker.MAX_TRANSIENT_ZERO_OBSERVATIONS; i++)
		{
			noTask();
		}
		assertEquals(ObserveResult.TASK_CHANGED, demons(5));
	}

	@Test
	public void bossTasksUseDistinctCreatureKeys()
	{
		int zulrah = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 21);
		int vorkath = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 22);
		assertEquals(DEMON_ID, SessionTracker.creatureKey(DEMON_ID, 0));
		assertTrue(zulrah != vorkath);
		assertTrue(zulrah < SessionTracker.NO_CREATURE);
		assertTrue(SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 0) != SessionTracker.NO_CREATURE);

		// boss-to-boss change with failed name lookups is still a task change
		tracker.observe(null, zulrah, 5, false);
		tracker.startNow(ACCOUNT);
		assertEquals(ObserveResult.NONE, tracker.observe(null, zulrah, 4, false));
		assertEquals(ObserveResult.TASK_CHANGED, tracker.observe(null, vorkath, 5, false));

		SessionTracker.Summary summary = tracker.stopAndReset();
		LedgerRecord record = LedgerRecord.fromSummary(summary, true);
		assertEquals(Integer.valueOf(zulrah), record.getCreatureId());
		assertEquals("Unknown boss task (21)", record.getMonster());
	}

	@Test
	public void liveTaskKnowsTheKillsLeftOnlyWhileTheSessionsTaskIsObserved()
	{
		assertNull("idle", tracker.liveTask());
		assertTrue(tracker.startNow(ACCOUNT));
		assertNull("a session without a task", tracker.liveTask());

		demons(20);
		now += 60_000;
		demons(17);
		SessionTracker.LiveTask live = tracker.liveTask();
		assertEquals(SessionTracker.Status.RUNNING, live.getStatus());
		assertEquals(tracker.getSessionId(), live.getSessionId());
		assertEquals("Abyssal demons", live.getMonster());
		assertEquals(DEMON_ID, live.getCreatureId());
		assertEquals(3, live.getKills());
		assertEquals(60_000, live.getActiveMillis());
		assertEquals(17, live.getRemaining());

		// Logout: logged out, and the task is not read again until the next observation.
		assertTrue(tracker.loggedOut());
		tracker.clearCurrentTask();
		assertEquals(SessionTracker.Status.LOGGED_OUT, tracker.liveTask().getStatus());
		assertEquals(SessionTracker.LiveTask.UNKNOWN_REMAINING, tracker.liveTask().getRemaining());
		demons(17);
		assertEquals(17, tracker.liveTask().getRemaining());
		assertEquals(SessionTracker.Status.WAITING_FOR_NEXT_KILL, tracker.liveTask().getStatus());

		// Another task observed while logged out is not the session's.
		tracker.observe("Black dragons", DRAGON_ID, 30, false);
		assertEquals(SessionTracker.LiveTask.UNKNOWN_REMAINING, tracker.liveTask().getRemaining());
		demons(17);

		// A cleared count waiting for its completion message.
		assertTrue(tracker.startNow(ACCOUNT));
		assertEquals(ObserveResult.TASK_CLEARED, demons(0));
		assertEquals(SessionTracker.LiveTask.UNKNOWN_REMAINING, tracker.liveTask().getRemaining());

		assertTrue(tracker.stop());
		assertNull("stopped", tracker.liveTask());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Before;
import org.junit.Test;

/**
 * XP gained per task in {@link SessionTracker#observeXp}: counted only while RUNNING, against the previous
 * reading, never across a reset baseline, and carried through summaries, snapshots and records.
 */
public class SessionTrackerXpTest
{
	private static final int DEMON_ID = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};

	private long now;
	private SessionTracker tracker;
	/** The player's XP, as the plugin would read it each tick. */
	private final Map<String, Integer> stats = new HashMap<>();

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
		stats.put("SLAYER", 1_000_000);
		stats.put("HITPOINTS", 2_000_000);
		stats.put("MAGIC", 3_000_000);
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
	}

	/** One tick's reading of {@link #stats}. */
	private boolean read()
	{
		return tracker.observeXp(new HashMap<>(stats));
	}

	private void gain(String skill, int xp)
	{
		stats.merge(skill, xp, Integer::sum);
	}

	private static Map<String, Long> xp(Object... skillAndXp)
	{
		Map<String, Long> map = new TreeMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			map.put((String) skillAndXp[i], ((Number) skillAndXp[i + 1]).longValue());
		}
		return map;
	}

	// ---- Baseline and diff ----

	@Test
	public void xpAfterPlayIsCountedAgainstTheReadingBeforeIt()
	{
		read();
		gain("SLAYER", 500);
		assertFalse("before Play nothing counts", read());
		assertTrue(tracker.startNow(ACCOUNT));
		gain("SLAYER", 120);
		gain("HITPOINTS", 40);
		assertTrue(read());
		gain("SLAYER", 80);
		read();
		assertEquals(xp("SLAYER", 200, "HITPOINTS", 40), tracker.getXpGained());
		assertEquals(xp("SLAYER", 200, "HITPOINTS", 40), tracker.activeSummary().getXpGained());
	}

	@Test
	public void theFirstReadingOnlySetsTheBaseline()
	{
		assertTrue(tracker.startNow(ACCOUNT));
		assertFalse(read());
		gain("SLAYER", 50);
		read();
		assertEquals(xp("SLAYER", 50), tracker.getXpGained());
	}

	@Test
	public void noChangeAddsNothing()
	{
		tracker.startNow(ACCOUNT);
		read();
		assertFalse(read());
		assertTrue(tracker.getXpGained().isEmpty());
	}

	// ---- Pause and resume ----

	@Test
	public void xpWhilePausedIsNotCountedAndResumeCountsFromTheLatestReading()
	{
		tracker.startNow(ACCOUNT);
		read();
		gain("SLAYER", 100);
		read();
		tracker.pause();
		gain("SLAYER", 5_000);
		gain("MAGIC", 9_000);
		assertFalse(read());
		read();
		assertTrue(tracker.startNow(ACCOUNT));
		gain("MAGIC", 30);
		read();
		assertEquals(xp("SLAYER", 100, "MAGIC", 30), tracker.getXpGained());
	}

	@Test
	public void autoPauseStopsCountingToo()
	{
		tracker.startNow(ACCOUNT);
		read();
		tracker.loggedOut();
		gain("SLAYER", 100);
		read();
		assertTrue(tracker.getXpGained().isEmpty());
	}

	// ---- Re-login, hop and account switch ----

	@Test
	public void aResetBaselineNeverCountsTheNextReading()
	{
		tracker.startNow(ACCOUNT);
		read();
		gain("SLAYER", 10);
		read();
		// Login, hop or lost connection: the stats are re-sent, possibly with XP the session never saw being gained.
		tracker.resetXpBaseline();
		gain("SLAYER", 400_000);
		assertFalse(read());
		gain("SLAYER", 25);
		read();
		assertEquals(xp("SLAYER", 35), tracker.getXpGained());
	}

	@Test
	public void anUnsyncedReadingDropsTheBaseline()
	{
		tracker.startNow(ACCOUNT);
		read();
		// Hitpoints XP read 0: the caller passes null and the stats then arrive in a burst.
		assertFalse(tracker.observeXp(null));
		gain("SLAYER", 1_000);
		assertFalse("the login burst is only a baseline", read());
		assertTrue(tracker.getXpGained().isEmpty());
	}

	@Test
	public void aDecreaseIsAnotherAccountAndOnlyMovesTheBaseline()
	{
		tracker.startNow(ACCOUNT);
		read();
		Map<String, Integer> other = new HashMap<>();
		other.put("SLAYER", 13_034_431);
		other.put("HITPOINTS", 1_154);
		other.put("MAGIC", 0);
		assertFalse(tracker.observeXp(other));
		other.put("SLAYER", 13_034_500);
		assertTrue(tracker.observeXp(other));
		assertEquals(xp("SLAYER", 69), tracker.getXpGained());
	}

	// ---- Grace window ----

	@Test
	public void aHeldCompletionGetsNoXpAfterItsCompletionTick()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 1, 150, false);
		tracker.startNow(ACCOUNT);
		read();
		// The completion tick: the plugin reads XP before observing the task, so the final kill's XP counts.
		gain("SLAYER", 300);
		read();
		assertEquals(SessionTracker.ObserveResult.COMPLETED, tracker.observe("Abyssal demons", DEMON_ID, 0, 150, true));
		assertTrue(tracker.holdCompletion());

		gain("SLAYER", 999);
		assertFalse(read());
		assertNull(tracker.tickCompletion());
		gain("PRAYER", 5);
		read();
		SessionTracker.Summary saved = tracker.tickCompletion();
		assertNotNull(saved);
		assertEquals(xp("SLAYER", 300), saved.getXpGained());
		assertEquals(xp("SLAYER", 300), LedgerRecord.fromSummary(saved, false).getXpGained());
	}

	@Test
	public void aNewSessionStartsWithNoXpAndCountsItsOwn()
	{
		tracker.startNow(ACCOUNT);
		read();
		gain("SLAYER", 100);
		read();
		SessionTracker.Summary first = tracker.stopAndReset();
		assertEquals(xp("SLAYER", 100), first.getXpGained());
		assertTrue(tracker.getXpGained().isEmpty());
		gain("SLAYER", 50);
		read();
		tracker.startNow(ACCOUNT);
		gain("SLAYER", 7);
		read();
		assertEquals(xp("SLAYER", 7), tracker.getXpGained());
	}

	// ---- Snapshot and records ----

	@Test
	public void xpSurvivesASnapshotRoundTripAndTheRestoredSessionKeepsCounting()
	{
		tracker.startNow(ACCOUNT);
		read();
		gain("SLAYER", 400);
		gain("MAGIC", 1_200);
		read();
		tracker.loggedOut();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		assertEquals(xp("SLAYER", 400, "MAGIC", 1_200), snapshot.getXpGained());
		Gson gson = new Gson();
		SessionSnapshot read = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(snapshot, read);

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(read, COUNTERS));
		assertEquals(xp("SLAYER", 400, "MAGIC", 1_200), restored.getXpGained());
		// The restored tracker has no baseline: the login's first reading only sets it.
		restored.observeXp(new HashMap<>(stats));
		assertTrue(restored.startNow(ACCOUNT));
		gain("SLAYER", 100);
		restored.observeXp(new HashMap<>(stats));
		assertEquals(xp("SLAYER", 500, "MAGIC", 1_200), LedgerRecord.fromSummary(restored.stopAndReset(), false)
			.getXpGained());
	}

	@Test
	public void aSnapshotFromBeforeXpWasTrackedRestoresWithNoneAndCountsFromThere()
	{
		tracker.startNow(ACCOUNT);
		tracker.loggedOut();
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
		snapshot.setXpGained(null);
		Gson gson = new Gson();
		String json = gson.toJson(snapshot);
		assertFalse("an older file has no field", json.contains("xpGained"));
		SessionSnapshot old = gson.fromJson(json, SessionSnapshot.class);

		// Saved as partial (it no longer matches): the XP is unknown, not 0.
		assertNull(old.toSummary(SlayerSpots.NONE).getXpGained());
		assertNull(LedgerRecord.fromSummary(old.toSummary(SlayerSpots.NONE), true).getXpGained());

		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(old, COUNTERS));
		assertEquals(Collections.emptyMap(), restored.getXpGained());
	}

	@Test
	public void aRecordWithNoXpGainedStoresAnEmptyMap()
	{
		tracker.startNow(ACCOUNT);
		read();
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertEquals(Collections.emptyMap(), record.getXpGained());
		assertEquals("XP: 0", LedgerHistory.formatXpLine(record));
	}

	@Test
	public void anOldRecordShowsADash()
	{
		LedgerRecord old = new Gson().fromJson("{\"schemaVersion\":2,\"id\":\"a\",\"monster\":\"Abyssal demons\","
			+ "\"kills\":5,\"activeMillis\":600000}", LedgerRecord.class);
		assertNull(old.getXpGained());
		assertEquals("no rate either", "XP: -", LedgerHistory.formatXpLine(old));
	}

	@Test
	public void aRecordShowsItsTotalAndRate()
	{
		LedgerRecord record = new Gson().fromJson("{\"schemaVersion\":2,\"id\":\"a\",\"monster\":\"Abyssal demons\","
			+ "\"kills\":5,\"activeMillis\":1800000,\"xpGained\":{\"SLAYER\":15000,\"HITPOINTS\":5000}}",
			LedgerRecord.class);
		assertEquals(xp("SLAYER", 15_000, "HITPOINTS", 5_000), record.getXpGained());
		assertEquals("XP: 20K (40K/h)", LedgerHistory.formatXpLine(record));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Live session valuation for the panel: totals, per-dose potions, unit-price caching, retries and resets.
 */
public class SessionValuationTest
{
	private static final int BONES = 526;
	private static final int SHARK = 385;
	private static final int PRAYER_4 = 2434;

	/** Counts GE lookups per id; prices can be changed or made unavailable (0) between calls. */
	private static final class CountingLookup implements ItemValuation.PriceLookup
	{
		final Map<Integer, Long> ge = new HashMap<>();
		final Map<Integer, Integer> lookups = new HashMap<>();

		CountingLookup()
		{
			ge.put(BONES, 100L);
			ge.put(SHARK, 1_000L);
			ge.put(PRAYER_4, 8_000L);
		}

		@Override
		public int canonicalize(int itemId)
		{
			return itemId;
		}

		@Override
		public long gePrice(int canonicalId)
		{
			lookups.merge(canonicalId, 1, Integer::sum);
			return ge.getOrDefault(canonicalId, 0L);
		}

		@Override
		public long haPrice(int canonicalId)
		{
			return canonicalId == SHARK ? 180 : 0;
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return true;
		}

		int lookups(int id)
		{
			return lookups.getOrDefault(id, 0);
		}
	}

	private static ItemTally tally(int... idQty)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQty.length; i += 2)
		{
			t.add(idQty[i], idQty[i + 1]);
		}
		return t;
	}

	private final SessionValuation valuation = new SessionValuation();
	private final CountingLookup lookup = new CountingLookup();

	@Test
	public void valuesLootSuppliesAndProfitWithPotionsPerDose()
	{
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 10, ItemValuation.COINS, 500),
			tally(SHARK, 3, PRAYER_4, 5), Collections.singletonMap(PRAYER_4, 4), lookup, 0);
		assertEquals(10 * 100 + 500, v.getLootGe());
		assertEquals(500, v.getLootHa());
		// 3 sharks + 5 doses of a 4-dose potion (8,000 * 5 / 4).
		assertEquals(3_000 + 10_000, v.getSuppliesGe());
		assertEquals(540, v.getSuppliesHa());
		assertEquals("a loss", 1_500 - 13_000, v.getProfit());
		assertEquals(0, v.getLootUnpriced());
		assertEquals(0, v.getSuppliesUnpriced());
	}

	@Test
	public void emptySessionIsZero()
	{
		SessionValuation.Values v = valuation.update("s1", null, null, null, lookup, 0);
		assertEquals(SessionValuation.Values.builder().sessionId("s1").build(), v);
	}

	@Test
	public void unitPricesAreCachedForTheSession()
	{
		valuation.update("s1", tally(BONES, 1), tally(SHARK, 1), null, lookup, 0);
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 5), tally(SHARK, 2, PRAYER_4, 1),
			Collections.singletonMap(PRAYER_4, 4), lookup, 2);
		assertEquals(1, lookup.lookups(BONES));
		assertEquals(1, lookup.lookups(SHARK));
		assertEquals(1, lookup.lookups(PRAYER_4));
		assertEquals(500, v.getLootGe());
		assertEquals(2_000 + 2_000, v.getSuppliesGe());
	}

	@Test
	public void unchangedTalliesReturnTheSameValuesWithoutLookups()
	{
		SessionValuation.Values first = valuation.update("s1", tally(BONES, 1), new ItemTally(), null, lookup, 0);
		lookup.ge.put(BONES, 999L);
		SessionValuation.Values second = valuation.update("s1", tally(BONES, 1), new ItemTally(), null, lookup, 50);
		assertSame(first, second);
		assertEquals(1, lookup.lookups(BONES));
	}

	@Test
	public void newSessionDropsTheCache()
	{
		valuation.update("s1", tally(BONES, 1), null, null, lookup, 0);
		lookup.ge.put(BONES, 200L);
		SessionValuation.Values v = valuation.update("s2", tally(BONES, 1), null, null, lookup, 2);
		assertEquals(200, v.getLootGe());
		assertEquals(2, lookup.lookups(BONES));
	}

	@Test
	public void resetDropsTheCache()
	{
		valuation.update("s1", tally(BONES, 1), null, null, lookup, 0);
		valuation.reset();
		lookup.ge.put(BONES, 300L);
		assertEquals(300, valuation.update("s1", tally(BONES, 1), null, null, lookup, 2).getLootGe());
	}

	@Test
	public void unavailablePricesAreCountedAndRetriedOnACadence()
	{
		lookup.ge.put(SHARK, 0L);
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 1), tally(SHARK, 4), null, lookup, 100);
		assertEquals(100, v.getLootGe());
		assertEquals("known prices still sum", 0, v.getSuppliesGe());
		assertEquals(1, v.getSuppliesUnpriced());
		assertEquals(1, lookup.lookups(SHARK));

		// Prices load meanwhile, but nothing changed and the retry window has not passed.
		lookup.ge.put(SHARK, 1_000L);
		valuation.update("s1", tally(BONES, 1), tally(SHARK, 4), null, lookup, 100 + SessionValuation.RETRY_TICKS - 1);
		assertEquals(1, lookup.lookups(SHARK));

		v = valuation.update("s1", tally(BONES, 1), tally(SHARK, 4), null, lookup, 100 + SessionValuation.RETRY_TICKS);
		assertEquals(2, lookup.lookups(SHARK));
		assertEquals(4_000, v.getSuppliesGe());
		assertEquals(0, v.getSuppliesUnpriced());
		assertEquals("found prices are not looked up again", 1, lookup.lookups(BONES));
	}

	@Test
	public void missingItemsNoLongerInTheTalliesAreNotRetried()
	{
		lookup.ge.put(SHARK, 0L);
		valuation.update("s1", tally(BONES, 1), tally(SHARK, 1), null, lookup, 0);
		// The shark was "returned" (supplies back to zero): it is gone from the tally.
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 1), new ItemTally(), null, lookup,
			SessionValuation.RETRY_TICKS);
		assertEquals(1, lookup.lookups(SHARK));
		assertEquals(0, v.getSuppliesUnpriced());
	}

	@Test
	public void profitSaturates()
	{
		SessionValuation.Values v = SessionValuation.Values.builder().sessionId("s1").lootValue(Long.MAX_VALUE)
			.lootGe(Long.MAX_VALUE).suppliesGe(-1).build();
		assertEquals(Long.MAX_VALUE, v.getProfit());
	}

	// ---- Loot price mode ----

	@Test
	public void lootFollowsThePriceModeAndSuppliesStayAtGe()
	{
		// Shark: GE 100, high alch 180. Bones: GE 100, high alch 0.
		lookup.ge.put(SHARK, 100L);
		ItemTally loot = tally(SHARK, 2, BONES, 1);
		ItemTally supplies = tally(SHARK, 1);

		SessionValuation.Values ge = valuation.update("s1", loot, supplies, null, LootPriceMode.GE, lookup, 0);
		assertEquals(LootPriceMode.GE, ge.getLootPriceMode());
		assertEquals(300, ge.getLootValue());
		assertEquals(200, ge.getProfit());

		SessionValuation.Values ha = valuation.update("s1", loot, supplies, null, LootPriceMode.HIGH_ALCH, lookup, 1);
		assertEquals(LootPriceMode.HIGH_ALCH, ha.getLootPriceMode());
		assertEquals(360, ha.getLootValue());
		assertEquals("supplies stay at GE", 100, ha.getSuppliesGe());
		assertEquals(260, ha.getProfit());
		assertEquals("the GE figures are kept", 300, ha.getLootGe());
		assertEquals("so is the GE profit", Long.valueOf(200),
			LedgerHistory.profit(ha.getLootGe(), ha.getSuppliesGe()));

		SessionValuation.Values back = valuation.update("s1", loot, supplies, null, LootPriceMode.GE, lookup, 2);
		assertEquals(LootPriceMode.GE, back.getLootPriceMode());
		assertEquals(300, back.getLootValue());
		assertEquals("a mode change reuses the cached prices", 1, lookup.lookups(SHARK));
		assertEquals(1, lookup.lookups(BONES));

		assertSame("unchanged mode and tallies", back,
			valuation.update("s1", loot, supplies, null, LootPriceMode.GE, lookup, 3));
	}

	@Test
	public void highAlchCountsOnlyItemsWithoutAHighAlchValueAsUnpriced()
	{
		lookup.ge.put(SHARK, 0L);
		SessionValuation.Values v = valuation.update("s1", tally(SHARK, 1, BONES, 1), null, null,
			LootPriceMode.HIGH_ALCH, lookup, 0);
		assertEquals("the shark at its high alch value", 180, v.getLootValue());
		assertEquals("both items have a high alch value", 0, v.getLootValueUnpriced());
		assertEquals("the shark's GE price is unavailable", 1, v.getLootUnpriced());
		assertEquals("the ~ follows the shown (high alch) figure", "180", LiveSessionSection.liveLootText(v));
		String tooltip = LedgerHistory.valuesTooltip(v);
		// The GE figure misses the shark, so it is marked and counted in the note.
		assertTrue(tooltip, tooltip.contains("Loot: ~100 gp GE, 180 gp high alch"));
		assertTrue(tooltip, tooltip.contains("~ Some prices were unavailable (loot at high alch: 0, loot at GE: 1,"
			+ " supplies: 0), so the figures marked ~ may be too low."));

		SessionValuation.Values ge = valuation.update("s1", tally(SHARK, 1, BONES, 1), null, null, LootPriceMode.GE,
			lookup, 1);
		String geTooltip = LedgerHistory.valuesTooltip(ge);
		assertTrue(geTooltip, geTooltip.contains("Loot: ~100 gp GE, 180 gp high alch"));
		assertTrue("GE mode keeps its note", geTooltip.contains("(loot: 1, supplies: 0), so totals may be too low."));
	}

	@Test
	public void highAlchTooltipHasNoGeNoteWhenEveryGePriceIsKnown()
	{
		lookup.ge.put(SHARK, 100L);
		SessionValuation.Values v = valuation.update("s1", tally(SHARK, 1), tally(BONES, 1), null,
			LootPriceMode.HIGH_ALCH, lookup, 0);
		String tooltip = LedgerHistory.valuesTooltip(v);
		assertTrue(tooltip, tooltip.contains("Loot: 100 gp GE, 180 gp high alch"));
		assertFalse(tooltip, tooltip.contains("~"));
	}

	@Test
	public void anUntradeableItemCountsAtHighAlchInEveryMode()
	{
		// 7 Brimstone keys: untradeable (GE 0), high alch 48,000. One more item at GE 100 / high alch 60.
		final int key = 23083;
		final int rune = 1;
		ItemValuation.PriceLookup keys = new ItemValuation.PriceLookup()
		{
			@Override
			public int canonicalize(int itemId)
			{
				return itemId;
			}

			@Override
			public long gePrice(int canonicalId)
			{
				return canonicalId == rune ? 100 : 0;
			}

			@Override
			public boolean isTradeable(int canonicalId)
			{
				return canonicalId != key;
			}

			@Override
			public long haPrice(int canonicalId)
			{
				return canonicalId == key ? 48_000 : 60;
			}
		};
		ItemTally loot = tally(key, 7, rune, 1);
		// An untradeable supply stays at its GE price of 0: supplies are not part of the rule.
		ItemTally supplies = tally(key, 1);

		SessionValuation.Values ge = valuation.update("s1", loot, supplies, null, LootPriceMode.GE, keys, 0);
		assertEquals(336_100, ge.getLootValue());
		assertEquals(336_100, ge.getLootGe());
		assertEquals(0, ge.getLootValueUnpriced());
		assertEquals(0, ge.getLootUnpriced());
		assertEquals(0, ge.getSuppliesGe());
		assertEquals(336_100, ge.getProfit());

		SessionValuation.Values ha = valuation.update("s1", loot, supplies, null, LootPriceMode.HIGH_ALCH, keys, 1);
		assertEquals(336_060, ha.getLootValue());
		assertEquals("no ~", "336K", LiveSessionSection.liveLootText(ha));
		String tooltip = LedgerHistory.valuesTooltip(ha);
		assertTrue(tooltip, tooltip.contains("Loot: 336,100 gp GE, 336,060 gp high alch"));
		assertTrue(tooltip, tooltip.contains("Loot value (High alch): 336,060 gp"));
	}

	@Test
	public void liveLootAndProfitFollowThePriceModeAndTheTooltipNamesIt()
	{
		lookup.ge.put(SHARK, 100L);
		ItemTally loot = tally(SHARK, 2);
		SessionValuation.Values ge = valuation.update("s1", loot, null, null, LootPriceMode.GE, lookup, 0);
		assertEquals("200", LiveSessionSection.liveLootText(ge));
		assertEquals("+200", LiveSessionSection.liveProfitText(ge));
		String geTooltip = LedgerHistory.valuesTooltip(ge);
		assertTrue("both prices stay in the tooltip", geTooltip.contains("Loot: 200 gp GE, 360 gp high alch"));
		assertTrue(geTooltip, geTooltip.contains("Profit: 200 gp GE"));

		SessionValuation.Values ha = valuation.update("s1", loot, null, null, LootPriceMode.HIGH_ALCH, lookup, 1);
		assertEquals("360", LiveSessionSection.liveLootText(ha));
		assertEquals("+360", LiveSessionSection.liveProfitText(ha));
		String tooltip = LedgerHistory.valuesTooltip(ha);
		assertTrue(tooltip, tooltip.contains("Loot: 200 gp GE, 360 gp high alch"));
		assertTrue(tooltip, tooltip.contains("Loot value (High alch): 360 gp"));
		assertTrue(tooltip, tooltip.contains("Profit: 360 gp (loot at high alch, supplies at GE)"));
	}

	@Test
	public void liveProfitIsApproximateWhenASupplyIsUnpriced()
	{
		lookup.ge.put(SHARK, 0L);
		SessionValuation.Values v = valuation.update("s1", tally(BONES, 1), tally(SHARK, 1), null, LootPriceMode.GE,
			lookup, 0);
		assertEquals(1, v.getSuppliesUnpriced());
		String profit = LiveSessionSection.liveProfitText(v);
		assertTrue(profit, profit.startsWith("~"));
	}
}

package com.shmayvan.slayerledger;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** {@link SessionCounters}, {@link SessionLoot} and the {@link SessionTracker.Summary} builder. */
public class SessionValueObjectsTest
{
	@Test
	public void emptySummaryBuilderIsANewSession()
	{
		SessionTracker.Summary s = SessionTracker.Summary.builder().build();
		assertNull(s.getSessionId());
		assertEquals(SessionTracker.NO_ACCOUNT, s.getAccountHash());
		assertEquals(SessionTracker.NO_CREATURE, s.getCreatureId());
		assertEquals(SessionTracker.UNKNOWN_AMOUNT, s.getOriginalAmount());
		assertSame(TaskContext.NONE, s.getContext());
		assertEquals(Integer.valueOf(0), s.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(0), s.getBankTrips());
		assertEquals(Integer.valueOf(0), s.getDeaths());
		assertTrue(s.getLoot().isEmpty());
		assertTrue(s.getNotableDrops().isEmpty());
		assertEquals(Collections.emptyMap(), s.getXpGained());
		assertTrue(s.getLocationKills().isEmpty());
	}

	@Test
	public void nullsInTheSummaryBuilderAreEmptyOrUnknown()
	{
		SessionTracker.Summary s = SessionTracker.Summary.builder()
			.sessionLoot(null)
			.counters(null)
			.context(null)
			.xpGained(null)
			.locationKills(null)
			.build();
		assertSame(SessionLoot.EMPTY, s.getSessionLoot());
		assertSame(SessionCounters.ZERO, s.getCounters());
		assertSame(TaskContext.NONE, s.getContext());
		assertNull("unknown XP stays unknown", s.getXpGained());
		assertTrue(s.getLocationKills().isEmpty());
	}

	@Test
	public void copiesChangeOnlyWhatTheyNameAndKeepTheRest()
	{
		ItemTally loot = new ItemTally();
		loot.add(592, 3);
		SessionTracker.Summary s = SessionTracker.Summary.builder()
			.sessionId("s1")
			.kills(4)
			.counters(SessionCounters.builder().deaths(2).build())
			.sessionLoot(SessionLoot.builder().loot(loot).build())
			.note("Barrage")
			.build();

		SessionTracker.Summary noted = s.withNote("Cannon").withBossKillCount("Abyssal Sire", 10);
		assertEquals("Cannon", noted.getNote());
		assertEquals(1, noted.getBossKillCounts().size());
		assertEquals("s1", noted.getSessionId());
		assertEquals(4, noted.getKills());
		assertEquals(Integer.valueOf(2), noted.getDeaths());
		assertEquals(3, noted.getLoot().get(592));
		assertEquals("Barrage", s.getNote());

		ItemTally extra = new ItemTally();
		extra.add(592, 2);
		assertEquals(5, s.withAddedLoot(extra, null).getLoot().get(592));
		assertEquals(3, s.getLoot().get(592));
	}

	@Test
	public void sessionLootCopiesWhatItIsGiven()
	{
		ItemTally loot = new ItemTally();
		loot.add(592, 3);
		Map<Integer, Integer> doses = new HashMap<>();
		doses.put(2434, 4);
		doses.put(385, 0);
		List<BossKillCount> counts = new ArrayList<>(BossKillCounts.add(null, "Abyssal Sire", 10));
		SessionLoot built = SessionLoot.builder().loot(loot).supplyDoses(doses).bossKillCounts(counts).build();

		loot.add(592, 10);
		doses.put(2434, 3);
		counts.clear();
		assertEquals(3, built.getLoot().get(592));
		assertEquals(Collections.singletonMap(2434, 4), built.getSupplyDoses());
		assertEquals(1, built.getBossKillCounts().size());
		built.getLoot().add(592, 1);
		assertEquals("getters hand out copies", 3, built.getLoot().get(592));
	}

	@Test
	public void restoredCountersCountUnknownAndNegativeAsZero()
	{
		SessionCounters stored = SessionCounters.builder().superiorsSpawned(null).bankTrips(-3).deaths(2).build();
		SessionCounters restored = stored.withUnknownAsZero();
		assertEquals(Integer.valueOf(0), restored.getSuperiorsSpawned());
		assertEquals(Integer.valueOf(0), restored.getBankTrips());
		assertEquals(Integer.valueOf(2), restored.getDeaths());
		assertNull("the stored counters are unchanged", stored.getSuperiorsSpawned());
	}

	@Test
	public void countersAreCopiedToBothPersistedShapesAndBack()
	{
		SessionCounters counters = SessionCounters.builder().superiorsSpawned(1).bankTrips(null).deaths(3).build();
		SessionSnapshot snapshot = new SessionSnapshot();
		counters.copyTo(snapshot);
		LedgerRecord record = new LedgerRecord();
		counters.copyTo(record);

		assertEquals(counters, SessionCounters.from(snapshot));
		assertEquals(Integer.valueOf(1), record.getSuperiorsSpawned());
		assertNull(record.getBankTrips());
		assertEquals(Integer.valueOf(3), record.getDeaths());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * The setup detection rules ({@link SetupDetection}): the gear focus cut-offs, checked against real setups'
 * prayer bonuses from the OSRS Wiki (2026-11-09), each killed NPC's style, and the task's cannon, style and gear focus
 * from its kill contexts.
 */
public class SetupDetectionTest
{
	private static int sum(int... prayer)
	{
		int total = 0;
		for (int p : prayer)
		{
			total += p;
		}
		return total;
	}

	private static Map<String, Integer> counts(Object... keysAndCounts)
	{
		final Map<String, Integer> map = new HashMap<>();
		for (int i = 0; i < keysAndCounts.length; i += 2)
		{
			map.put(keysAndCounts[i].toString(), (Integer) keysAndCounts[i + 1]);
		}
		return map;
	}

	private static int[] hits(int melee, int ranged, int barrage, int magic)
	{
		final int[] hits = new int[SetupStyle.values().length];
		hits[SetupStyle.MELEE.ordinal()] = melee;
		hits[SetupStyle.RANGED.ordinal()] = ranged;
		hits[SetupStyle.BARRAGE.ordinal()] = barrage;
		hits[SetupStyle.MAGIC.ordinal()] = magic;
		return hits;
	}

	// ---- Gear focus ----

	@Test
	public void theCutOffs()
	{
		assertEquals(GearFocus.PRAYER, SetupDetection.gearFocus(SetupDetection.PRAYER_FOCUS_MIN));
		assertEquals(GearFocus.MIXED, SetupDetection.gearFocus(SetupDetection.PRAYER_FOCUS_MIN - 1));
		assertEquals(GearFocus.MIXED, SetupDetection.gearFocus(SetupDetection.STRENGTH_FOCUS_MAX + 1));
		assertEquals(GearFocus.STRENGTH, SetupDetection.gearFocus(SetupDetection.STRENGTH_FOCUS_MAX));
		assertEquals(GearFocus.STRENGTH, SetupDetection.gearFocus(0));
		assertEquals("a negative total", GearFocus.STRENGTH, SetupDetection.gearFocus(-3));
		assertEquals(25, SetupDetection.PRAYER_FOCUS_MIN);
		assertEquals(14, SetupDetection.STRENGTH_FOCUS_MAX);
	}

	/** Damage-focused sets: each item's prayer bonus in slot order, from the OSRS Wiki. */
	@Test
	public void realDamageSetsAreStrength()
	{
		// Torva helm, body, legs; torture; infernal cape; primordial boots; ferocious gloves; ultor ring; avernic
		// defender; Osmumten's fang.
		final int torva = sum(1, 1, 1, 2, 2, 0, 0, 0, 0, 0);
		assertEquals(7, torva);
		assertEquals("with Rada's blessing 4", 9, torva + 2);
		// Neitiznot faceguard, Bandos chestplate and tassets; torture; infernal cape; primordial; ferocious; ultor;
		// avernic; whip.
		final int bandos = sum(3, 1, 1, 2, 2, 0, 0, 0, 0, 0);
		assertEquals(9, bandos);
		// Helm of neitiznot, fighter torso, obsidian platelegs, fury, fire cape, dragon boots, barrows gloves, berserker
		// ring (i), dragon defender, whip.
		final int midLevel = sum(3, 0, 0, 5, 2, 0, 0, 0, 0, 0);
		assertEquals(10, midLevel);
		// Masori (f) mask, body, chaps; anguish; Ava's assembler; zaryte vambraces; pegasian; venator ring; blowpipe.
		final int masori = sum(1, 1, 1, 2, 0, 1, 0, 0, 0);
		assertEquals(6, masori);
		// Armadyl helmet, chestplate, chainskirt; anguish; assembler; zaryte; pegasian; venator; Armadyl crossbow.
		final int armadyl = sum(1, 1, 1, 2, 0, 1, 0, 0, 1);
		assertEquals(7, armadyl);
		// Crystal helm, body, legs; anguish; assembler; zaryte; pegasian; venator; bow of faerdhinen.
		final int crystal = sum(2, 3, 2, 2, 0, 1, 0, 0, 0);
		assertEquals(10, crystal);
		// Ancestral hat, top, bottom; occult; imbued god cape; tormented bracelet; eternal boots; magus ring; kodai
		// wand; Elidinis' ward (f).
		final int ancestral = sum(0, 0, 0, 2, 0, 2, 0, 0, 0, 4);
		assertEquals(8, ancestral);
		// Ahrim's hood, robetop, robeskirt; occult; imbued god cape; tormented; eternal; seers ring (i); Ahrim's staff;
		// arcane spirit shield.
		final int ahrims = sum(0, 0, 0, 2, 0, 2, 0, 0, 0, 3);
		assertEquals(7, ahrims);
		// Virtus mask, top, bottom; occult; imbued god cape; tormented; eternal; magus; kodai; Elidinis' ward (f); Rada's
		// blessing 4: the highest damage set found.
		final int virtus = sum(1, 2, 1, 2, 0, 2, 0, 0, 0, 4, 2);
		assertEquals(14, virtus);

		for (int total : new int[]{torva, torva + 2, bandos, bandos + 2, midLevel, midLevel + 2, masori, armadyl,
			crystal, crystal + 2, ancestral, ahrims, virtus})
		{
			assertEquals("+" + total, GearFocus.STRENGTH, SetupDetection.gearFocus(total));
		}
	}

	@Test
	public void realPrayerSetsArePrayer()
	{
		// Proselyte sallet, hauberk, cuisse; holy wraps; Saradomin cape; holy book; holy blessing; ring of the gods;
		// holy sandals; salve amulet (ei); whip.
		final int proselyte = sum(4, 8, 6, 3, 0, 5, 1, 4, 3, 3, 0);
		assertEquals(37, proselyte);
		assertEquals("a defender in place of the book", 32, proselyte - 5);
		// Justiciar faceguard, chestguard, legguards and the same.
		final int justiciar = sum(2, 4, 4, 3, 0, 5, 1, 4, 3, 3, 0);
		assertEquals(29, justiciar);
		for (int total : new int[]{proselyte, proselyte - 5, justiciar})
		{
			assertEquals("+" + total, GearFocus.PRAYER, SetupDetection.gearFocus(total));
		}
	}

	@Test
	public void aPartlyPrayerSetIsMixed()
	{
		// Bandos with a Proselyte hauberk and cuisse in place of the chestplate and tassets.
		assertEquals(GearFocus.MIXED, SetupDetection.gearFocus(sum(3, 8, 6, 2, 2, 0, 0, 0, 0, 0)));
	}

	@Test
	public void theTasksGearIsTheFocusOfMostKillsAndATieIsMixed()
	{
		assertEquals(GearFocus.PRAYER, SetupDetection.taskGear(counts("PRAYER", 10, "STRENGTH", 3, "MIXED", 2)));
		assertEquals(GearFocus.MIXED, SetupDetection.taskGear(counts("PRAYER", 5, "STRENGTH", 5)));
		assertEquals("a tie for most, not with the rest", GearFocus.MIXED,
			SetupDetection.taskGear(counts("PRAYER", 5, "STRENGTH", 5, "MIXED", 1)));
		assertEquals(GearFocus.STRENGTH, SetupDetection.taskGear(counts("STRENGTH", 1)));
		assertEquals(GearFocus.UNKNOWN, SetupDetection.taskGear(counts()));
		assertEquals(GearFocus.UNKNOWN, SetupDetection.taskGear(null));
		assertEquals("a later build's key is left out", GearFocus.PRAYER,
			SetupDetection.taskGear(counts("PRAYER", 2, "FUTURE", 9)));
	}

	// ---- Styles ----

	@Test
	public void anNpcsStyleIsItsMajorityAndATieIsMixed()
	{
		assertEquals(SetupStyle.MELEE, SetupDetection.npcStyle(hits(3, 1, 0, 0)));
		assertEquals(SetupStyle.MIXED, SetupDetection.npcStyle(hits(2, 2, 0, 0)));
		assertEquals(SetupStyle.BARRAGE, SetupDetection.npcStyle(hits(0, 0, 1, 0)));
		assertNull("only a cannon's hits", SetupDetection.npcStyle(hits(0, 0, 0, 0)));
	}

	@Test
	public void theTasksStyleCoversAtLeastHalfOfItsStyledKills()
	{
		assertEquals(SetupStyle.BARRAGE, SetupDetection.taskStyle(counts("BARRAGE", 50, "MAGIC", 30, "MELEE", 20)));
		assertEquals("45/40/15", SetupStyle.MIXED,
			SetupDetection.taskStyle(counts("MELEE", 45, "RANGED", 40, "BARRAGE", 15)));
		assertEquals("a tie at half", SetupStyle.MIXED, SetupDetection.taskStyle(counts("MELEE", 5, "RANGED", 5)));
		assertEquals(SetupStyle.MELEE, SetupDetection.taskStyle(counts("MELEE", 1)));
		assertEquals("kills that were already mixed", SetupStyle.MIXED,
			SetupDetection.taskStyle(counts("MIXED", 6, "MELEE", 4)));
		assertEquals("no styled kill (a cannon-only task)", SetupStyle.UNKNOWN, SetupDetection.taskStyle(counts()));
		assertEquals(SetupStyle.UNKNOWN, SetupDetection.taskStyle(null));
		assertEquals("a later build's key is left out", SetupStyle.RANGED,
			SetupDetection.taskStyle(counts("RANGED", 2, "MELEE", 1, "THRALL", 9)));
	}

	// ---- Cannon ----

	@Test
	public void aCannonTaskHadAtLeastHalfItsKillsByCannon()
	{
		assertTrue(SetupDetection.cannon(5, 10));
		assertTrue(SetupDetection.cannon(10, 10));
		assertFalse("a brief cannon setup", SetupDetection.cannon(4, 10));
		assertFalse(SetupDetection.cannon(0, 10));
		assertFalse("no kill context", SetupDetection.cannon(null, 10));
		assertFalse("no kills", SetupDetection.cannon(3, 0));
	}

	@Test
	public void eachTagSaysWhatItWasDetectedFrom()
	{
		final SetupKills kills = SetupKills.NONE.withKill(true, SetupStyle.BARRAGE, GearFocus.PRAYER, 31)
			.withKill(false, SetupStyle.BARRAGE, GearFocus.PRAYER, 33)
			.withKill(true, null, GearFocus.STRENGTH, -2);
		assertEquals(Collections.singletonList("Cannon kills: 2 of 3"), SetupDetection.cannonDetails(kills, 3));
		assertEquals(Collections.singletonList("Kills by style: Barrage 2"), SetupDetection.styleDetails(kills));
		assertEquals(Arrays.asList("Kills by gear: Prayer 2, Strength 1", "Prayer bonus: -2 to +33"),
			SetupDetection.gearDetails(kills));
		assertEquals("one prayer bonus seen", Collections.singletonList("Prayer bonus: +31"),
			SetupDetection.gearDetails(SetupKills.NONE.withKill(false, null, null, 31)));
		// Before a kill's context is counted there is nothing to say.
		assertTrue(SetupDetection.cannonDetails(SetupKills.NONE, 0).isEmpty());
		assertTrue(SetupDetection.styleDetails(SetupKills.NONE).isEmpty());
		assertTrue(SetupDetection.gearDetails(SetupKills.NONE).isEmpty());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import org.junit.Test;

/**
 * The sidebar's setup tag images ({@link SetupImages}): each asked for once for every user, an image handed over
 * at once returned, one handed over later announced, and a drawn item icon repainting every user.
 */
public class SetupImagesTest
{
	/** The images asked for, and the callbacks that hand them over or repaint. */
	private final List<SetupTagIcons.Icon> loads = new ArrayList<>();
	private final List<Consumer<Image>> shows = new ArrayList<>();
	private final List<Runnable> repaints = new ArrayList<>();
	/** The cannon barrels come at once (an item icon, maybe still blank); the sprites later. */
	private final BufferedImage barrels = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
	private final SetupImages images = new SetupImages((icon, show, repaint) ->
	{
		loads.add(icon);
		shows.add(show);
		repaints.add(repaint);
		if (icon.isItem())
		{
			show.accept(barrels);
		}
	});

	@Test
	public void eachImageIsAskedForOnceForEveryUser()
	{
		List<SetupTagIcons.Icon> toggles = new ArrayList<>();
		List<SetupTagIcons.Icon> history = new ArrayList<>();
		images.addListener(toggles::add, () -> { });
		images.addListener(history::add, () -> { });

		assertNull("none for no image", images.get(null));
		assertNull("a sprite comes later", images.get(SetupTagIcons.Icon.BARRAGE));
		assertNull(images.get(SetupTagIcons.Icon.BARRAGE));
		assertEquals("asked for once", Collections.singletonList(SetupTagIcons.Icon.BARRAGE), loads);

		BufferedImage sprite = new BufferedImage(25, 25, BufferedImage.TYPE_INT_ARGB);
		shows.get(0).accept(sprite);
		assertEquals("every user is told", Collections.singletonList(SetupTagIcons.Icon.BARRAGE), toggles);
		assertEquals(Collections.singletonList(SetupTagIcons.Icon.BARRAGE), history);
		assertSame(sprite, images.get(SetupTagIcons.Icon.BARRAGE));
		assertEquals("kept, never asked for again", 1, loads.size());

		// No image (a sprite the game lacks) is not kept, and announces nothing.
		images.get(SetupTagIcons.Icon.PRAYER);
		shows.get(1).accept(null);
		assertNull(images.get(SetupTagIcons.Icon.PRAYER));
		assertEquals(Arrays.asList(SetupTagIcons.Icon.BARRAGE, SetupTagIcons.Icon.PRAYER), loads);
		assertEquals(1, toggles.size());
	}

	@Test
	public void anImageHandedOverAtOnceIsReturnedAndADrawnItemIconRepaintsEveryUser()
	{
		List<SetupTagIcons.Icon> told = new ArrayList<>();
		int[] repainted = new int[2];
		images.addListener(told::add, () -> repainted[0]++);
		images.addListener(told::add, () -> repainted[1]++);

		assertSame("at once", barrels, images.get(SetupTagIcons.Icon.CANNON));
		assertTrue("returned, not announced", told.isEmpty());
		assertSame(barrels, images.get(SetupTagIcons.Icon.CANNON));
		assertEquals(Collections.singletonList(SetupTagIcons.Icon.CANNON), loads);

		// The blank icon has been drawn (on the client thread): every user repaints.
		repaints.get(0).run();
		assertEquals(Arrays.asList(1, 1), Arrays.asList(repainted[0], repainted[1]));
	}
}

package com.shmayvan.slayerledger;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Filepath;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * The migration of 1.x records (V2 plan 4.3, {@link SetupMigration}). The ledger below is synthetic: made up for
 * this test in the shape a 1.x build writes (schema 2 file, records at version 2 or 1), never a player's real file.
 * Each record is one documented case, read through {@link LedgerStore} as the plugin reads it.
 */
public class SetupMigrationTest
{
	private static final long ACCOUNT = 987654321L;
	private static final int CANNONBALL = SupplyTracker.CANNONBALL;
	private static final int PRAYER_POTION = 2434;
	private static final int SHARK = 385;
	private static final int ZULRAH_SCALES = 12934;
	private static final int ADAMANT_DART = 810;

	/** One 1.x-shaped record: the members every 1.x record has, then {@code rest} (supplies, XP, ...). */
	private static String record(int version, String id, String monster, int kills, String rest)
	{
		return "{\"schemaVersion\":" + version + ",\"id\":\"" + id + "\",\"monster\":\"" + monster + "\","
			+ "\"creatureId\":42,\"initialAmount\":" + kills + ",\"originalAmount\":" + kills + ",\"kills\":" + kills
			+ ",\"activeMillis\":1800000,\"startedAt\":1762500000000,\"endedAt\":1762501800000,\"completed\":true,"
			+ "\"partial\":false" + rest + "}";
	}

	/** The synthetic 1.x ledger: one record per documented case. */
	private static final String LEDGER_1X = "{\"schemaVersion\":2,\"records\":["
		// A cannon task fought in melee: the cannon's Ranged XP is left out, so the melee XP decides.
		+ record(2, "cannon", "Kalphite", 150, ",\"supplies\":{\"" + CANNONBALL + "\":420,\"" + PRAYER_POTION
			+ "\":8},\"supplyDoses\":{\"" + PRAYER_POTION + "\":4},\"xpGained\":{\"ATTACK\":4000,\"HITPOINTS\":9000,"
			+ "\"RANGED\":21000,\"SLAYER\":12000,\"STRENGTH\":11000}") + ","
		// A melee task with no cannon.
		+ record(2, "melee", "Abyssal demons", 120, ",\"supplies\":{\"" + PRAYER_POTION + "\":20,\"" + SHARK
			+ "\":5},\"supplyDoses\":{\"" + PRAYER_POTION + "\":4},\"xpGained\":{\"ATTACK\":12000,\"DEFENCE\":3000,"
			+ "\"HITPOINTS\":15000,\"SLAYER\":18000,\"STRENGTH\":30000}") + ","
		// A barrage task: death and blood runes, almost all Magic XP.
		+ record(2, "barrage", "Dust devils", 200, ",\"supplies\":{\"" + ItemID.DEATHRUNE + "\":480,\""
			+ ItemID.BLOODRUNE + "\":240},\"xpGained\":{\"HITPOINTS\":22000,\"MAGIC\":95000,\"SLAYER\":26000}") + ","
		// A barrage task whose supplies were not counted (shaped like the 2026-11-08 Dust devils record): no supplies
		// at all and a Magic XP share of about 60%.
		+ record(2, "barrage-no-supplies", "Dust devils", 180, ",\"xpGained\":{\"ATTACK\":12000,\"HITPOINTS\":30000,"
			+ "\"MAGIC\":54000,\"SLAYER\":24000,\"STRENGTH\":24000}") + ","
		// A ranged task on longrange: its Defence XP alone can't be told from melee, so it is left out.
		+ record(2, "ranged", "Kurask", 130, ",\"supplies\":{\"" + ZULRAH_SCALES + "\":260,\"" + ADAMANT_DART
			+ "\":90},\"xpGained\":{\"DEFENCE\":18000,\"HITPOINTS\":12000,\"RANGED\":18000,\"SLAYER\":17000}") + ","
		// A cannon task done with ranged: the Ranged XP is left out, so nothing is left to estimate from.
		+ record(2, "cannon-ranged", "Black demons", 140, ",\"supplies\":{\"" + CANNONBALL + "\":510},"
			+ "\"xpGained\":{\"HITPOINTS\":14000,\"RANGED\":46000,\"SLAYER\":22000}") + ","
		// A version 1 record: no supplies and no XP kept.
		+ record(1, "no-xp", "Kurask", 50, "")
		+ "]}";

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private final Gson gson = new Gson();
	private File dir;
	private File file;

	@Before
	public void setUp() throws IOException
	{
		dir = new File(temp.getRoot(), "slayer-ledger");
		assertTrue(dir.mkdirs());
		file = new File(dir, ACCOUNT + ".json");
		Files.write(file.toPath(), LEDGER_1X.getBytes(StandardCharsets.UTF_8));
	}

	private LedgerStore store()
	{
		return new LedgerStore(Filepath.Unchecked.getRooted(dir.toPath()), gson);
	}

	private Map<String, LedgerRecord> loaded() throws IOException
	{
		final Map<String, LedgerRecord> byId = new HashMap<>();
		for (LedgerRecord r : store().load(ACCOUNT))
		{
			byId.put(r.getId(), r);
		}
		assertEquals(7, byId.size());
		return byId;
	}

	/** The record's effective tags as {@code cannon/style/gear}, an estimate marked {@code ~}. */
	private static String tags(LedgerRecord r)
	{
		final SetupTags tags = SetupTags.of(r);
		return SetupTags.shown(SetupTags.cannonLabel(tags.isCannon()), tags.isCannonEstimated()) + "/"
			+ SetupTags.shown(tags.getStyle().getLabel(), tags.isStyleEstimated()) + "/"
			+ SetupTags.shown(tags.getGear().getLabel(), tags.isGearEstimated());
	}

	@Test
	public void everyDocumentedCaseGetsItsEstimatedTags() throws IOException
	{
		final Map<String, LedgerRecord> records = loaded();
		assertEquals("~Yes/~Melee/Unknown", tags(records.get("cannon")));
		assertEquals("~No/~Melee/Unknown", tags(records.get("melee")));
		assertEquals("~No/~Barrage/Unknown", tags(records.get("barrage")));
		assertEquals("~No/~Barrage/Unknown", tags(records.get("barrage-no-supplies")));
		assertEquals("~No/~Ranged/Unknown", tags(records.get("ranged")));
		assertEquals("Unknown is no estimate", "~Yes/Unknown/Unknown", tags(records.get("cannon-ranged")));
		assertEquals("~No/Unknown/Unknown", tags(records.get("no-xp")));
	}

	@Test
	public void migratedRecordsStoreTheirTagsAtTheCurrentVersionWithNothingElseChanged() throws IOException
	{
		final LedgerRecord barrage = loaded().get("barrage");
		assertEquals(LedgerRecord.CURRENT_SCHEMA_VERSION, barrage.getSchemaVersion());
		assertEquals(Boolean.FALSE, barrage.getDetectedCannon());
		assertEquals(Boolean.TRUE, barrage.getCannonEstimated());
		assertEquals(SetupStyle.BARRAGE, barrage.getDetectedStyle());
		assertEquals(Boolean.TRUE, barrage.getStyleEstimated());
		assertEquals(GearFocus.UNKNOWN, barrage.getDetectedGear());
		assertNull("Unknown is not an estimate", barrage.getGearEstimated());
		assertNull(barrage.getCannonOverride());
		assertNull(barrage.getStyleOverride());
		assertNull(barrage.getGearOverride());
		assertNull("1.x kept no kills by NPC", barrage.getNpcKills());
		assertNull("nor kill contexts", barrage.getCannonKills());
		assertNull(barrage.getStyleKills());
		assertNull("the spot is worked out later (phase 6)", barrage.getSpotId());
		assertEquals("a Dust devils task has no Slayer boss", Boolean.FALSE, barrage.getBossKills());

		final LedgerRecord oneX = gson.fromJson(gson.toJson(barrage), LedgerRecord.class);
		oneX.setSchemaVersion(2);
		oneX.setDetectedCannon(null);
		oneX.setCannonEstimated(null);
		oneX.setDetectedStyle(null);
		oneX.setStyleEstimated(null);
		oneX.setDetectedGear(null);
		oneX.setBossKills(null);
		final LedgerRecord asRead = gson.fromJson(LEDGER_1X, LedgerStore.LedgerFile.class).records.get(2);
		assertEquals("only the version, the tags and the boss flag were added", asRead, oneX);
	}

	@Test
	public void readingChangesNothingOnDiskAndTheNextWriteKeepsTheTags() throws IOException
	{
		loaded();
		assertEquals(LEDGER_1X, new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8));

		store().updateNote(ACCOUNT, "melee", "Whip");
		final String written = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
		assertTrue(written, written.startsWith("{\"schemaVersion\":" + LedgerStore.FILE_SCHEMA_VERSION + ","));
		assertTrue(written, written.contains("\"detectedStyle\":\"BARRAGE\",\"styleEstimated\":true"));
		assertEquals("~No/~Barrage/Unknown", tags(loaded().get("barrage")));
		assertEquals("Whip", loaded().get("melee").getNote());
	}

	@Test
	public void aMigratedRecordIsNeverMigratedAgain() throws IOException
	{
		store().updateNote(ACCOUNT, "cannon", "Cannon");
		// A later edit of the written record: the stored tags are what counts, not its supplies or XP any more.
		final String written = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
		final String edited = written.replace("\"detectedStyle\":\"MELEE\"", "\"detectedStyle\":\"MIXED\"");
		assertFalse(written.equals(edited));
		Files.write(file.toPath(), edited.getBytes(StandardCharsets.UTF_8));
		assertEquals("~Yes/~Mixed/Unknown", tags(loaded().get("cannon")));

		final LedgerRecord again = loaded().get("cannon");
		assertFalse(SetupMigration.migrate(again));
		assertEquals(SetupStyle.MIXED, again.getDetectedStyle());
	}

	@Test
	public void aKeptRecordFromA1xBuildIsMigratedWhenItIsSaved() throws IOException
	{
		final String kept = "{\"schemaVersion\":2,\"record\":" + record(2, "kept", "Dust devils", 100,
			",\"supplies\":{\"" + ItemID.DEATHRUNE + "\":200,\"" + ItemID.BLOODRUNE + "\":100},"
				+ "\"xpGained\":{\"MAGIC\":50000}") + "}";
		Files.write(new File(dir, ACCOUNT + ".unsaved-kept.json").toPath(), kept.getBytes(StandardCharsets.UTF_8));
		final List<LedgerRecord> records = store().appendUnsaved(ACCOUNT);
		assertEquals(8, records.size());
		assertEquals("~No/~Barrage/Unknown", tags(records.get(7)));
		assertEquals("~No/~Barrage/Unknown", tags(store().load(ACCOUNT).get(7)));
	}

	// ---- The rules ----

	private static Map<String, Long> xp(Object... skillAndXp)
	{
		final Map<String, Long> xp = new TreeMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			xp.put((String) skillAndXp[i], ((Number) skillAndXp[i + 1]).longValue());
		}
		return xp;
	}

	private static Map<Integer, Long> supplies(int... idAndQuantity)
	{
		final Map<Integer, Long> supplies = new TreeMap<>();
		for (int i = 0; i < idAndQuantity.length; i += 2)
		{
			supplies.put(idAndQuantity[i], (long) idAndQuantity[i + 1]);
		}
		return supplies;
	}

	@Test
	public void theStyleCoveringAtLeastHalfWinsAndATieOrNoneIsMixed()
	{
		final Map<Integer, Long> food = supplies(SHARK, 3);
		assertEquals(SetupStyle.MELEE, SetupMigration.estimateStyle(xp("STRENGTH", 50, "RANGED", 25, "MAGIC", 25),
			food, false));
		assertEquals("a tie", SetupStyle.MIXED, SetupMigration.estimateStyle(xp("STRENGTH", 50, "RANGED", 50), food,
			false));
		assertEquals("none at half", SetupStyle.MIXED,
			SetupMigration.estimateStyle(xp("ATTACK", 40, "RANGED", 35, "MAGIC", 25), food, false));
		assertEquals("Hitpoints, Slayer and Prayer don't count", SetupStyle.UNKNOWN,
			SetupMigration.estimateStyle(xp("HITPOINTS", 900, "SLAYER", 500, "PRAYER", 100), food, false));
		assertEquals("no XP kept", SetupStyle.UNKNOWN, SetupMigration.estimateStyle(null, food, false));
		assertEquals(SetupStyle.UNKNOWN, SetupMigration.estimateStyle(Collections.emptyMap(), food, false));
	}

	@Test
	public void defenceCountsAsMeleeBesideAttackOrStrengthOrAsADefenceStance()
	{
		final Map<Integer, Long> food = supplies(SHARK, 3);
		assertEquals("controlled melee", SetupStyle.MELEE,
			SetupMigration.estimateStyle(xp("ATTACK", 30, "STRENGTH", 30, "DEFENCE", 30, "RANGED", 80), food, false));
		assertEquals("longrange", SetupStyle.RANGED,
			SetupMigration.estimateStyle(xp("DEFENCE", 100, "RANGED", 100), food, false));
		assertEquals("Defence alone is a melee Defence stance", SetupStyle.MELEE,
			SetupMigration.estimateStyle(xp("DEFENCE", 100), food, false));
		assertEquals("a cannon task on longrange", SetupStyle.UNKNOWN,
			SetupMigration.estimateStyle(xp("DEFENCE", 100, "RANGED", 300), supplies(CANNONBALL, 50), true));
	}

	@Test
	public void magicIsBarrageOnlyWithAncientRunesOrNoSupplies()
	{
		final Map<String, Long> magic = xp("MAGIC", 1000, "HITPOINTS", 300);
		assertEquals("barrage, blitz", SetupStyle.BARRAGE, SetupMigration.estimateStyle(magic,
			supplies(ItemID.DEATHRUNE, 40, ItemID.BLOODRUNE, 20, ItemID.WATERRUNE, 60), false));
		assertEquals("ice burst with a water staff", SetupStyle.BARRAGE, SetupMigration.estimateStyle(magic,
			supplies(ItemID.DEATHRUNE, 40, ItemID.CHAOSRUNE, 80), false));
		assertEquals("a trident: one chaos rune per death rune", SetupStyle.MAGIC, SetupMigration.estimateStyle(magic,
			supplies(ItemID.DEATHRUNE, 40, ItemID.CHAOSRUNE, 40, ItemID.FIRERUNE, 200, ItemID.COINS, 400), false));
		assertEquals("a Sanguinesti staff: blood runes alone", SetupStyle.MAGIC,
			SetupMigration.estimateStyle(magic, supplies(ItemID.BLOODRUNE, 80), false));
		assertEquals("Tumeken's shadow", SetupStyle.MAGIC,
			SetupMigration.estimateStyle(magic, supplies(ItemID.SOULRUNE, 40, ItemID.CHAOSRUNE, 100), false));
		assertEquals("wave spells", SetupStyle.MAGIC,
			SetupMigration.estimateStyle(magic, supplies(ItemID.BLOODRUNE, 40, ItemID.FIRERUNE, 200), false));
		assertEquals("no supplies kept", SetupStyle.BARRAGE, SetupMigration.estimateStyle(magic, null, false));
		assertEquals("supplies counted, none used", SetupStyle.BARRAGE,
			SetupMigration.estimateStyle(magic, supplies(), false));
		assertEquals("cannonballs and no runes", SetupStyle.MAGIC,
			SetupMigration.estimateStyle(magic, supplies(CANNONBALL, 100), true));
	}

	@Test
	public void theCannonComesFromTheCannonballsFired()
	{
		final LedgerRecord granite = gson.fromJson(record(2, "g", "Kalphite", 10, ",\"supplies\":{\""
			+ SupplyTracker.GRANITE_CANNONBALL + "\":30}"), LedgerRecord.class);
		assertTrue(SetupMigration.migrate(granite));
		assertEquals("~Yes/Unknown/Unknown", tags(granite));

		final LedgerRecord none = gson.fromJson(record(2, "n", "Kalphite", 10, ",\"supplies\":{\"" + SHARK + "\":3}"),
			LedgerRecord.class);
		assertTrue(SetupMigration.migrate(none));
		assertEquals("~No/Unknown/Unknown", tags(none));
	}

	@Test
	public void aCurrentRecordIsLeftAlone()
	{
		final LedgerRecord current = new LedgerRecord();
		current.setXpGained(xp("MAGIC", 1000));
		assertFalse(SetupMigration.migrate(current));
		assertNull(current.getDetectedStyle());
		assertFalse(SetupMigration.migrate(null));
	}

	@Test
	public void aMeleeDefenceStanceCountsAsMeleeButLongrangeAndDefensiveCastingDont()
	{
		final Map<Integer, Long> food = supplies(ItemID.SHARK, 5);
		// Defence stance: 4 Defence XP per damage, a few Magic XP from an alch or a thrall.
		assertEquals(SetupStyle.MELEE, SetupMigration.estimateStyle(xp("DEFENCE", 40000, "MAGIC", 600), null, false));
		assertEquals(SetupStyle.MELEE, SetupMigration.estimateStyle(xp("DEFENCE", 40000), food, false));
		// Longrange: as much Ranged XP as Defence XP.
		assertEquals(SetupStyle.RANGED, SetupMigration.estimateStyle(xp("DEFENCE", 100, "RANGED", 100), food, false));
		// Defensive casting: less Defence XP than Magic XP.
		assertEquals(SetupStyle.BARRAGE, SetupMigration.estimateStyle(xp("DEFENCE", 30000, "MAGIC", 70000),
			supplies(ItemID.DEATHRUNE, 400, ItemID.BLOODRUNE, 200), false));
	}

	@Test
	public void aPoweredStaffWithThrallsIsNotBarrage()
	{
		final Map<String, Long> magic = xp("MAGIC", 90000, "HITPOINTS", 20000);
		// Sanguinesti staff (2 blood runes a cast) with a few death runes from Superior thralls.
		assertEquals(SetupStyle.MAGIC, SetupMigration.estimateStyle(magic,
			supplies(ItemID.BLOODRUNE, 1000, ItemID.DEATHRUNE, 40), false));
		// Tumeken's shadow (5 chaos runes a cast) with a few death runes.
		assertEquals(SetupStyle.MAGIC, SetupMigration.estimateStyle(magic,
			supplies(ItemID.CHAOSRUNE, 2500, ItemID.SOULRUNE, 1000, ItemID.DEATHRUNE, 40), false));
		// Ice Barrage (4 death, 2 blood) and Blood Blitz (2 death, 4 blood) are still Barrage; so is Ice Burst.
		assertEquals(SetupStyle.BARRAGE, SetupMigration.estimateStyle(magic,
			supplies(ItemID.DEATHRUNE, 400, ItemID.BLOODRUNE, 200), false));
		assertEquals(SetupStyle.BARRAGE, SetupMigration.estimateStyle(magic,
			supplies(ItemID.DEATHRUNE, 200, ItemID.BLOODRUNE, 400), false));
		assertEquals(SetupStyle.BARRAGE, SetupMigration.estimateStyle(magic,
			supplies(ItemID.DEATHRUNE, 200, ItemID.CHAOSRUNE, 400), false));
	}

	@Test
	public void aMigratedRecordGetsThisStepsOwnVersion()
	{
		final LedgerRecord record = new LedgerRecord();
		record.setSchemaVersion(2);
		assertTrue(SetupMigration.migrate(record));
		assertEquals(SetupMigration.MIGRATED_VERSION, record.getSchemaVersion());
	}

}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.SpriteID;
import org.junit.Test;

/** The setup tags' sprites ({@link SetupTagIcons}). */
public class SetupTagIconsTest
{
	@Test
	public void cannonStyleThenGear()
	{
		assertEquals(Arrays.asList(SetupTagIcons.Icon.CANNON, SetupTagIcons.Icon.BARRAGE, SetupTagIcons.Icon.PRAYER),
			SetupTagIcons.of(SetupTags.detected(true, SetupStyle.BARRAGE, GearFocus.PRAYER, null)));
		assertEquals(Arrays.asList(SetupTagIcons.Icon.RANGED, SetupTagIcons.Icon.STRENGTH),
			SetupTagIcons.of(SetupTags.detected(false, SetupStyle.RANGED, GearFocus.STRENGTH, null)));
		assertEquals(Collections.singletonList(SetupTagIcons.Icon.MELEE),
			SetupTagIcons.of(SetupTags.detected(false, SetupStyle.MELEE, GearFocus.MIXED, null)));
		assertEquals(Collections.singletonList(SetupTagIcons.Icon.MAGIC),
			SetupTagIcons.of(SetupTags.detected(false, SetupStyle.MAGIC, GearFocus.UNKNOWN, null)));
		assertTrue("Mixed and Unknown have no sprite", SetupTagIcons.of(SetupTags.detected(false, SetupStyle.MIXED,
			GearFocus.UNKNOWN, null)).isEmpty());
		assertTrue(SetupTagIcons.of(null).isEmpty());
		assertNull(SetupTagIcons.style(SetupStyle.UNKNOWN));
		assertNull(SetupTagIcons.gear(null));
	}

	@Test
	public void thePlayersOverridesWin()
	{
		SetupTags tags = SetupTags.detected(false, SetupStyle.MELEE, GearFocus.STRENGTH,
			SetupOverrides.NONE.withCannon(true).withStyle(SetupStyle.RANGED));

		assertEquals(Arrays.asList(SetupTagIcons.Icon.CANNON, SetupTagIcons.Icon.RANGED, SetupTagIcons.Icon.STRENGTH),
			SetupTagIcons.of(tags));
	}

	@Test
	public void theGamesOwnImages()
	{
		assertTrue(SetupTagIcons.Icon.CANNON.isItem());
		assertEquals(ItemID.TWPART3, SetupTagIcons.Icon.CANNON.getId());
		assertFalse(SetupTagIcons.Icon.BARRAGE.isItem());
		assertEquals(SpriteID.Magicon2.ICE_BARRAGE, SetupTagIcons.Icon.BARRAGE.getId());
		assertEquals(SpriteID.Staticons.RANGED, SetupTagIcons.Icon.RANGED.getId());
		assertEquals(SpriteID.Staticons.MAGIC, SetupTagIcons.Icon.MAGIC.getId());
		assertEquals(SpriteID.Staticons.ATTACK, SetupTagIcons.Icon.MELEE.getId());
		assertEquals(SpriteID.Staticons.PRAYER, SetupTagIcons.Icon.PRAYER.getId());
