	}

	@Test
	public void eachTagSaysWhetherItIsAnEstimateOrSetByThePlayer()
	{
		// A migrated 1.x task: an estimated cannon and Barrage, gear Unknown (no icon).
		assertEquals(Arrays.asList("Cannon (estimated)", "Barrage (estimated)"),
			tooltips(SetupTags.estimated(true, SetupStyle.BARRAGE)));
		// Detected, then the style and gear set by the player.
		SetupTags tags = SetupTags.detected(true, SetupStyle.MAGIC, GearFocus.STRENGTH,
			SetupOverrides.NONE.withStyle(SetupStyle.RANGED).withGear(GearFocus.PRAYER));
		assertEquals(Arrays.asList("Cannon", "Ranged (set by you)", "Prayer gear (set by you)"), tooltips(tags));
		// An estimate the player overrode is no longer an estimate.
		SetupTags migrated = SetupTags.estimated(false, SetupStyle.BARRAGE)
			.withOverrides(SetupOverrides.NONE.withCannon(true));
		List<SetupTagIcons.Tag> shown = SetupTagIcons.tags(migrated);
		assertEquals(Arrays.asList("Cannon (set by you)", "Barrage (estimated)"), tooltips(migrated));
		assertTrue(shown.get(0).isSetByYou());
		assertFalse(shown.get(0).isEstimated());
		assertTrue(shown.get(1).isEstimated());
		assertFalse(shown.get(1).isSetByYou());
		// The same images as the overlay's, in the same order.
		assertEquals(SetupTagIcons.of(tags), Arrays.asList(SetupTagIcons.Icon.CANNON, SetupTagIcons.Icon.RANGED,
			SetupTagIcons.Icon.PRAYER));
		assertEquals(new SetupTagIcons.Tag(SetupTagIcons.Icon.CANNON, false, false), SetupTagIcons.tags(tags).get(0));
		assertTrue("Mixed set by the player still has no icon", SetupTagIcons.tags(SetupTags.detected(false,
			SetupStyle.MELEE, GearFocus.PRAYER, SetupOverrides.NONE.withStyle(SetupStyle.MIXED)
				.withGear(GearFocus.MIXED))).isEmpty());
		assertTrue(SetupTagIcons.tags(null).isEmpty());
	}

	/**
	 * The sidebar draws each tag's own game image ({@link SmallItemIcon#applyTag}), as the overlay does, in a 16 px box
	 *: Barrage is Ice Barrage's spell icon, not the Magic skill icon. A sprite arrives later: until then the box
	 * is empty, and the same size.
	 */
	@Test
	public void theSidebarDrawsEachTagsOwnGameImage()
	{
		List<SetupTagIcons.Icon> asked = new ArrayList<>();
		List<Consumer<Image>> pending = new ArrayList<>();
		BufferedImage barrels = new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB);
		SetupImages images = new SetupImages((icon, show, repaint) ->
		{
			asked.add(icon);
			if (icon.isItem())
			{
				show.accept(barrels);
			}
			else
			{
				pending.add(show);
			}
		});

		JLabel cannon = new JLabel();
		assertTrue(SmallItemIcon.applyTag(images, cannon, SetupTagIcons.Icon.CANNON));
		assertEquals(SmallItemIcon.TAG_SIZE, cannon.getIcon().getIconWidth());
		assertEquals(SmallItemIcon.TAG_SIZE, cannon.getIcon().getIconHeight());
		assertEquals(barrels, ((ImageIcon) cannon.getIcon()).getImage());

		JLabel barrage = new JLabel();
		assertFalse(SmallItemIcon.applyTag(images, barrage, SetupTagIcons.Icon.BARRAGE));
		assertEquals("not arrived: an empty box of the same size", SmallItemIcon.EMPTY_TAG, barrage.getIcon());
		BufferedImage iceBarrage = new BufferedImage(25, 25, BufferedImage.TYPE_INT_ARGB);
		pending.get(0).accept(iceBarrage);
		assertTrue(SmallItemIcon.applyTag(images, barrage, SetupTagIcons.Icon.BARRAGE));
		assertEquals(iceBarrage, ((ImageIcon) barrage.getIcon()).getImage());
		assertEquals(SmallItemIcon.TAG_SIZE, barrage.getIcon().getIconWidth());
		assertEquals("Ice Barrage's own sprite, asked for once", Arrays.asList(SetupTagIcons.Icon.CANNON,
			SetupTagIcons.Icon.BARRAGE), asked);
	}

	private static List<String> tooltips(SetupTags tags)
	{
		List<String> tooltips = new ArrayList<>();
		for (SetupTagIcons.Tag tag : SetupTagIcons.tags(tags))
		{
			tooltips.add(tag.getTooltip());
		}
		return tooltips;
	}
}

package com.shmayvan.slayerledger;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * The setup tags' value classes: the effective value of each tag ({@link SetupTags}: the override, else the
 * detected value, with whether it is an estimate), the overrides ({@link SetupOverrides}), the kill-context counts
 * ({@link SetupKills}) and the choices of the history row's "Setup..." dialog ({@link SetupChoices}).
 */
public class SetupTagsTest
{
	@Test
	public void theOverrideWinsAndIsNeverAnEstimate()
	{
		final SetupTags migrated = SetupTags.estimated(true, SetupStyle.BARRAGE);
		assertTrue(migrated.isCannon());
		assertTrue(migrated.isCannonEstimated());
		assertEquals(SetupStyle.BARRAGE, migrated.getStyle());
		assertTrue(migrated.isStyleEstimated());
		assertEquals(GearFocus.UNKNOWN, migrated.getGear());
		assertFalse("Unknown is no estimate", migrated.isGearEstimated());

		final SetupTags overridden = migrated.withOverrides(SetupOverrides.of(false, SetupStyle.MELEE, GearFocus.PRAYER));
		assertFalse(overridden.isCannon());
		assertFalse(overridden.isCannonEstimated());
		assertEquals(SetupStyle.MELEE, overridden.getStyle());
		assertFalse(overridden.isStyleEstimated());
		assertEquals(GearFocus.PRAYER, overridden.getGear());
		assertTrue("the detected values are kept", overridden.isDetectedCannon());
		assertTrue(overridden.isDetectedCannonEstimated());
		assertEquals(SetupStyle.BARRAGE, overridden.getDetectedStyle());
		assertTrue(overridden.hasEstimates());
	}

	@Test
	public void unknownIsNeverAnEstimate()
	{
		final SetupTags tags = SetupTags.estimated(false, SetupStyle.UNKNOWN);
		assertEquals(SetupStyle.UNKNOWN, tags.getStyle());
		assertFalse(tags.isStyleEstimated());
		assertTrue("the cannon still is one", tags.isCannonEstimated());
		final SetupTags live = SetupTags.detected(false, null, null, null);
		assertEquals(SetupStyle.UNKNOWN, live.getStyle());
		assertEquals(GearFocus.UNKNOWN, live.getGear());
		assertFalse(live.hasEstimates());
	}

	@Test
	public void aRecordsTagsRoundTripThroughItsFields()
	{
		final SetupTags tags = SetupTags.estimated(true, SetupStyle.RANGED)
			.withOverrides(SetupOverrides.NONE.withGear(GearFocus.STRENGTH));
		final LedgerRecord record = new LedgerRecord();
		tags.copyTo(record);
		assertEquals(Boolean.TRUE, record.getCannonEstimated());
		assertNull("not estimated is left out", record.getGearEstimated());
		assertEquals(tags, SetupTags.of(record));
		assertTrue(SetupTags.of(record).isRecorded());
	}

	@Test
	public void aRecordWithoutStoredTagsFallsBackToItsSupplies()
	{
		final LedgerRecord record = new LedgerRecord();
		assertFalse(SetupTags.of(record).isRecorded());
		assertFalse(SetupTags.of(record).isCannon());
		record.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 40L));
		assertTrue("as 1.x classified it", SetupTags.of(record).isCannon());
		assertFalse(SetupTags.of(record).isCannonEstimated());
		assertEquals(SetupStyle.UNKNOWN, SetupTags.of(record).getStyle());
		assertEquals("no tooltip lines", "", LedgerHistory.setupTooltip(record));
		record.setStyleOverride(SetupStyle.MAGIC);
		assertTrue("an override is stored", SetupTags.of(record).isRecorded());
	}

	@Test
	public void theTooltipLinesMarkEstimatesAndOverrides()
	{
		assertEquals(Arrays.asList("Cannon: ~Yes", "Style: ~Barrage", "Gear: Unknown", SetupTags.ESTIMATE_NOTE),
			SetupTags.estimated(true, SetupStyle.BARRAGE).lines());
		assertEquals(Arrays.asList("Cannon: No (set by you; detected ~Yes)", "Style: ~Barrage",
			"Gear: Prayer (set by you; detected Unknown)", SetupTags.ESTIMATE_NOTE),
			SetupTags.estimated(true, SetupStyle.BARRAGE).withOverrides(SetupOverrides.of(false, null, GearFocus.PRAYER))
				.lines());
		assertEquals(Arrays.asList("Cannon: No", "Style: Unknown", "Gear: Unknown"),
			SetupTags.detected(false, SetupStyle.UNKNOWN, GearFocus.UNKNOWN, null).lines());

		final LedgerRecord record = new LedgerRecord();
		SetupTags.estimated(false, SetupStyle.MIXED).copyTo(record);
		assertEquals("<br>Cannon: ~No<br>Style: ~Mixed<br>Gear: Unknown<br>~ estimated: saved before setup was recorded",
			LedgerHistory.setupTooltip(record));
	}

	@Test
	public void overridesTreatUnknownAsNone()
	{
		assertSame(SetupOverrides.NONE, SetupOverrides.of(null, SetupStyle.UNKNOWN, GearFocus.UNKNOWN));
		assertTrue(SetupOverrides.NONE.isEmpty());
		final SetupOverrides some = SetupOverrides.NONE.withCannon(true).withStyle(SetupStyle.MAGIC);
		assertEquals(SetupOverrides.of(true, SetupStyle.MAGIC, null), some);
		assertNull(some.withStyle(SetupStyle.UNKNOWN).getStyle());
		assertSame(SetupOverrides.NONE, some.withCannon(null).withStyle(null));

		final SessionSnapshot snapshot = new SessionSnapshot();
		some.copyTo(snapshot);
		assertEquals(some, SetupOverrides.from(snapshot));
		snapshot.setGearOverride(GearFocus.UNKNOWN);
		assertEquals("a hand-edited Unknown reads as none", some, SetupOverrides.from(snapshot));
	}

	@Test
	public void killContextsAreCountsWithAPrayerBonusRange()
	{
		assertTrue(SetupKills.NONE.isEmpty());
		assertNull(SetupKills.NONE.getCannonKills());
		final SetupKills kills = SetupKills.NONE
			.withKill(true, null, GearFocus.PRAYER, 30)
			.withKill(false, SetupStyle.BARRAGE, GearFocus.PRAYER, 25)
			.withKill(false, SetupStyle.BARRAGE, GearFocus.MIXED, null)
			.withKill(false, SetupStyle.MELEE, null, 8);
		assertEquals(Integer.valueOf(1), kills.getCannonKills());
		assertEquals(2, kills.styleKills(SetupStyle.BARRAGE));
		assertEquals(1, kills.styleKills(SetupStyle.MELEE));
		assertEquals(0, kills.styleKills(SetupStyle.RANGED));
		assertEquals(2, kills.gearKills(GearFocus.PRAYER));
		assertEquals(Integer.valueOf(8), kills.getPrayerBonusMin());
		assertEquals(Integer.valueOf(30), kills.getPrayerBonusMax());

		final LedgerRecord record = new LedgerRecord();
		kills.copyTo(record);
		assertEquals(kills, SetupKills.from(record));
		final SessionSnapshot snapshot = new SessionSnapshot();
		kills.copyTo(snapshot);
		assertEquals(kills, SetupKills.from(snapshot));

		final SetupKills none = SetupKills.of(0, null, null, null, null);
		assertEquals("counted, but no cannon kill", Integer.valueOf(0), none.getCannonKills());
		assertFalse(none.isEmpty());
	}

	@Test
	public void killContextsReadFromAFileAreCleaned()
	{
		final Map<String, Integer> styles = new HashMap<>();
		styles.put("BARRAGE", 4);
		styles.put("CHINCHOMPA", 2);
		styles.put(" ", 3);
		styles.put("MAGIC", 0);
		final SetupKills kills = SetupKills.of(-1, styles, null, 30, 5);
		assertEquals(Integer.valueOf(0), kills.getCannonKills());
		assertEquals("a later build's style is kept", 2, (int) kills.getStyleKills().get("CHINCHOMPA"));
		assertEquals(2, kills.getStyleKills().size());
		assertNull("a range out of order is dropped", kills.getPrayerBonusMin());
		assertSame(SetupKills.NONE, SetupKills.of(null, Collections.emptyMap(), null, null, 4));
	}

	private static <T> List<String> labels(List<SetupChoices.Choice<T>> choices)
	{
		return choices.stream().map(SetupChoices.Choice::getLabel).collect(Collectors.toList());
	}

	@Test
	public void theDialogsFirstChoiceClearsTheOverrideAndShowsTheDetectedValue()
	{
		final SetupTags tags = SetupTags.estimated(true, SetupStyle.BARRAGE)
			.withOverrides(SetupOverrides.of(null, SetupStyle.MELEE, null));
		final List<SetupChoices.Choice<Boolean>> cannon = SetupChoices.cannon(tags);
		assertEquals(Arrays.asList("Detected: ~Yes", "Yes", "No"), labels(cannon));
		assertNull(cannon.get(0).getValue());
		assertEquals(Boolean.FALSE, cannon.get(2).getValue());
		assertEquals(0, SetupChoices.indexOf(cannon, null));

		final List<SetupChoices.Choice<SetupStyle>> style = SetupChoices.style(tags);
		assertEquals(Arrays.asList("Detected: ~Barrage", "Melee", "Ranged", "Barrage", "Magic", "Mixed"), labels(style));
		assertEquals("the override is selected", 1, SetupChoices.indexOf(style, SetupStyle.MELEE));
		assertEquals("Unknown can't be set", 0, SetupChoices.indexOf(style, SetupStyle.UNKNOWN));

		final List<SetupChoices.Choice<GearFocus>> gear = SetupChoices.gear(tags);
		assertEquals(Arrays.asList("Detected: Unknown", "Prayer", "Strength", "Mixed"), labels(gear));
		assertEquals(GearFocus.STRENGTH, gear.get(2).getValue());

		final LedgerRecord record = new LedgerRecord();
		record.setMonster("Dust devils");
		assertEquals("Setup of this Dust devils task:", SetupChoices.prompt(record));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import java.awt.AWTEvent;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Toolkit;
import java.awt.event.AWTEventListener;
import java.awt.event.InputEvent;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.AbstractButton;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import javax.swing.JComponent;
import javax.swing.JPopupMenu;
import javax.swing.SwingUtilities;
import javax.swing.event.PopupMenuEvent;
import javax.swing.event.PopupMenuListener;
import org.junit.Test;

/**
 * The live card's setup toggles on their own: the word drawn for a value without a sprite, the override mark,
 * the tooltip's lines, the images asked for once each, a click on an open menu's toggle and the row's width in the
 * RuneScape fonts. The plugin-level behaviour (the menus, the overrides reaching the session or record) is in
 * {@link HarnessSetupDetectionTest}.
 */
public class SetupTogglesTest
{
	/** The images asked for, and the callbacks that hand them over. */
	private final List<SetupTagIcons.Icon> loads = new ArrayList<>();
	private final List<Consumer<Image>> pending = new ArrayList<>();
	private final SetupToggles toggles = new SetupToggles(new SetupImages((icon, show, repaint) ->
	{
		loads.add(icon);
		pending.add(show);
	}));

	private static SetupTags tags(boolean cannon, SetupStyle style, GearFocus gear, SetupOverrides overrides)
	{
		return SetupTags.detected(cannon, style, gear, overrides);
	}

	private AbstractButton toggle(SetupToggles.Tag tag)
	{
		return SwingLookup.find(toggles.getComponent(), tag.key(), AbstractButton.class);
	}

	@Test
	public void aValueWithoutASpriteIsAShortWordAndUnknownIsAQuestionMark()
	{
		SetupTags unknown = tags(false, SetupStyle.UNKNOWN, GearFocus.UNKNOWN, null);
		assertEquals("No", SetupToggles.placeholder(SetupToggles.Tag.CANNON, unknown));
		assertEquals("?", SetupToggles.placeholder(SetupToggles.Tag.STYLE, unknown));
		assertEquals("?", SetupToggles.placeholder(SetupToggles.Tag.GEAR, unknown));
		SetupTags mixed = tags(true, SetupStyle.MIXED, GearFocus.MIXED, null);
		assertNull("the cannon barrels", SetupToggles.placeholder(SetupToggles.Tag.CANNON, mixed));
		assertEquals("Mix", SetupToggles.placeholder(SetupToggles.Tag.STYLE, mixed));
		assertEquals("Mix", SetupToggles.placeholder(SetupToggles.Tag.GEAR, mixed));
		SetupTags sprites = tags(false, SetupStyle.BARRAGE, GearFocus.PRAYER, null);
		assertNull(SetupToggles.placeholder(SetupToggles.Tag.STYLE, sprites));
		assertNull(SetupToggles.placeholder(SetupToggles.Tag.GEAR, sprites));
		assertEquals(SetupTagIcons.Icon.BARRAGE, SetupToggles.Tag.STYLE.icon(sprites));
		assertEquals(SetupTagIcons.Icon.PRAYER, SetupToggles.Tag.GEAR.icon(sprites));
		assertEquals(SetupTagIcons.Icon.CANNON, SetupToggles.Tag.CANNON.icon(mixed));
	}

	@Test
	public void theTooltipSaysTheTagItsValueWhoSetItAndAnEstimate()
	{
		SetupKills kills = SetupKills.NONE.withKill(false, SetupStyle.MELEE, GearFocus.STRENGTH, 8);
		SetupTags detected = SetupTags.forSession(null, kills, 1, null);
		assertEquals("<html>Style: Melee<br>Detected<br>Kills by style: Melee 1<br>" + SetupToggles.HINT + "</html>",
			SetupToggles.tooltip(SetupToggles.Tag.STYLE, detected, kills, 1));
		assertEquals("<html>Gear: Strength<br>Detected<br>Kills by gear: Strength 1<br>Prayer bonus: +8<br>"
			+ SetupToggles.HINT + "</html>", SetupToggles.tooltip(SetupToggles.Tag.GEAR, detected, kills, 1));

		SetupTags set = detected.withOverrides(SetupOverrides.of(true, null, null));
		assertEquals("<html>Cannon: Yes<br>Set by you; detected No<br>Cannon kills: 0 of 1<br>" + SetupToggles.HINT
			+ "</html>", SetupToggles.tooltip(SetupToggles.Tag.CANNON, set, kills, 1));
		assertEquals("Yes, set by you", SetupToggles.description(SetupToggles.Tag.CANNON, set));
		assertEquals("Melee", SetupToggles.description(SetupToggles.Tag.STYLE, set));

		// A migrated task's estimate: ~ before the value and the note, also when the player set it.
		SetupTags estimated = SetupTags.estimated(true, SetupStyle.BARRAGE);
		assertEquals("<html>Style: ~Barrage<br>Detected<br>" + SetupTags.ESTIMATE_NOTE + "<br>" + SetupToggles.HINT
			+ "</html>", SetupToggles.tooltip(SetupToggles.Tag.STYLE, estimated, SetupKills.NONE, 0));
		assertEquals("<html>Style: Melee<br>Set by you; detected ~Barrage<br>" + SetupTags.ESTIMATE_NOTE + "<br>"
			+ SetupToggles.HINT + "</html>", SetupToggles.tooltip(SetupToggles.Tag.STYLE,
			estimated.withOverrides(SetupOverrides.of(null, SetupStyle.MELEE, null)), SetupKills.NONE, 0));
		assertEquals("Unknown is no estimate", "<html>Gear: Unknown<br>Detected<br>" + SetupToggles.HINT + "</html>",
			SetupToggles.tooltip(SetupToggles.Tag.GEAR, estimated, SetupKills.NONE, 0));
	}

	@Test
	public void anOverrideHasTheCornerMarkAndUnknownItsQuestionMarkInTheHintColour()
	{
		toggles.show(tags(false, SetupStyle.UNKNOWN, GearFocus.UNKNOWN, SetupOverrides.of(true, null, null)),
			SetupKills.NONE, 0);
		BufferedImage cannon = paint(toggle(SetupToggles.Tag.CANNON).getIcon());
		BufferedImage gear = paint(toggle(SetupToggles.Tag.GEAR).getIcon());
		assertEquals("the mark", LedgerTheme.HEADING.getRGB(), cannon.getRGB(cannon.getWidth() - 1, 0));
		assertEquals("no mark", 0, gear.getRGB(gear.getWidth() - 1, 0) >>> 24);
		assertTrue("the ? is drawn in the hint colour", hasColour(gear, LedgerTheme.HINT.getRGB()));
		assertEquals("Unknown", ((ImageIcon) toggle(SetupToggles.Tag.GEAR).getIcon()).getDescription());
	}

	@Test
	public void eachImageIsAskedForOnceAndDrawnWhenItArrives()
	{
		SetupTags barrage = tags(false, SetupStyle.BARRAGE, GearFocus.PRAYER, null);
		toggles.show(barrage, SetupKills.NONE, 0);
		assertEquals(Arrays.asList(SetupTagIcons.Icon.BARRAGE, SetupTagIcons.Icon.PRAYER), loads);
		assertNull("not arrived yet", ((ImageIcon) toggle(SetupToggles.Tag.STYLE).getIcon()).getImage());

		BufferedImage sprite = new BufferedImage(25, 25, BufferedImage.TYPE_INT_ARGB);
		pending.get(0).accept(sprite);
		Icon icon = toggle(SetupToggles.Tag.STYLE).getIcon();
		assertSame(sprite, ((ImageIcon) icon).getImage());
		assertEquals("fitted into the 18 by 16 slot", Arrays.asList(SetupToggles.SLOT_WIDTH, SetupToggles.SLOT_HEIGHT),
			Arrays.asList(icon.getIconWidth(), icon.getIconHeight()));

		// Back and forth: the images are kept, never asked for again; the same tags redraw nothing.
		int builds = toggles.getBuildCount();
		toggles.show(barrage, SetupKills.NONE, 0);
		assertEquals(builds, toggles.getBuildCount());
		toggles.show(tags(false, SetupStyle.MELEE, GearFocus.PRAYER, null), SetupKills.NONE, 0);
		toggles.show(barrage, SetupKills.NONE, 0);
		assertEquals(Arrays.asList(SetupTagIcons.Icon.BARRAGE, SetupTagIcons.Icon.PRAYER, SetupTagIcons.Icon.MELEE),
			loads);
		assertSame(sprite, ((ImageIcon) toggle(SetupToggles.Tag.STYLE).getIcon()).getImage());
		assertEquals(builds + 2, toggles.getBuildCount());
	}

	/**
	 * A click on the toggle of an open menu only closes it: Swing closes an open menu on a mouse press outside it,
	 * before the component under the mouse gets the press ({@code BasicPopupMenuUI}'s mouse grabber), and the toggle
	 * fires on the release, which used to open the menu again. Headless, no menu can show, so a stand-in for the grabber
	 * closes the menu the test calls open on a press, as Swing does; the toggle gets real mouse events. Whether Swing
	 * does the same in the client is the in-game check. Opening fills the menu, so an empty menu was not opened.
	 */
	@Test
	public void aClickOnTheToggleOfAnOpenMenuOnlyClosesIt() throws Exception
	{
		final AbstractButton style = toggle(SetupToggles.Tag.STYLE);
		final JPopupMenu menu = style.getComponentPopupMenu();
		final boolean[] open = new boolean[1];
		final AWTEventListener grabber = event ->
		{
			if (open[0] && event.getID() == MouseEvent.MOUSE_PRESSED)
			{
				open[0] = false;
				for (PopupMenuListener listener : menu.getPopupMenuListeners())
				{
					listener.popupMenuWillBecomeInvisible(new PopupMenuEvent(menu));
					listener.popupMenuCanceled(new PopupMenuEvent(menu));
				}
			}
		};
		Toolkit.getDefaultToolkit().addAWTEventListener(grabber, AWTEvent.MOUSE_EVENT_MASK);
		try
		{
			SwingUtilities.invokeAndWait(() ->
			{
				toggles.show(tags(false, SetupStyle.MELEE, GearFocus.PRAYER, null), SetupKills.NONE, 0);
				final JComponent row = toggles.getComponent();
				row.setSize(row.getPreferredSize());
				row.doLayout();

				click(style, 1_000);
				assertTrue("a click opens it", menu.getComponentCount() > 0);

				// Open: the press closes it, and the click it starts must not open it again.
				open[0] = true;
				menu.removeAll();
				click(style, 2_000);
				assertFalse("the press closed it", open[0]);
				assertEquals("not opened again", 0, menu.getComponentCount());
				click(style, 3_000);
				assertTrue("the next click opens it", menu.getComponentCount() > 0);

				// A press that closed it and slid off the toggle (no click) leaves nothing behind for the next click.
				open[0] = true;
				menu.removeAll();
				pressAndSlideOff(style, 4_000);
				assertEquals("no click", 0, menu.getComponentCount());
				click(style, 5_000);
				assertTrue(menu.getComponentCount() > 0);

				open[0] = true;
				menu.removeAll();
				pressAndSlideOff(style, 6_000);
			});
			// Nor for Space, a click with no mouse event.
			SwingUtilities.invokeAndWait(style::doClick);
			assertTrue("Space opens it", menu.getComponentCount() > 0);
		}
		finally
		{
			Toolkit.getDefaultToolkit().removeAWTEventListener(grabber);
		}
	}

	/** A left click on {@code button}, as Swing dispatches it: a press, then a release over it, at {@code when}. */
	private static void click(AbstractButton button, long when)
	{
		button.dispatchEvent(mouse(button, MouseEvent.MOUSE_PRESSED, when, InputEvent.BUTTON1_DOWN_MASK,
			MouseEvent.BUTTON1));
		button.dispatchEvent(mouse(button, MouseEvent.MOUSE_RELEASED, when + 50, 0, MouseEvent.BUTTON1));
	}

	/** A left press on {@code button}, then the mouse leaves it and is released elsewhere: no click. */
	private static void pressAndSlideOff(AbstractButton button, long when)
	{
		button.dispatchEvent(mouse(button, MouseEvent.MOUSE_PRESSED, when, InputEvent.BUTTON1_DOWN_MASK,
			MouseEvent.BUTTON1));
		button.dispatchEvent(mouse(button, MouseEvent.MOUSE_EXITED, when + 20, InputEvent.BUTTON1_DOWN_MASK,
			MouseEvent.NOBUTTON));
		button.dispatchEvent(mouse(button, MouseEvent.MOUSE_RELEASED, when + 50, 0, MouseEvent.BUTTON1));
	}

	private static MouseEvent mouse(AbstractButton button, int id, long when, int modifiers, int which)
	{
		return new MouseEvent(button, id, when, modifiers, 2, 2, 1, false, which);
	}

	@Test
	public void theRowFitsTheCardWithItsWidestWords()
	{
		// Mixed style and gear are the widest: "Mix" (18 px in Small) in a 20 px slot.
		toggles.show(tags(false, SetupStyle.MIXED, GearFocus.MIXED, null), SetupKills.NONE, 0);
		int width = toggles.getComponent().getPreferredSize().width;
		assertTrue("wants " + width, width <= 199);
		toggles.show(tags(true, SetupStyle.BARRAGE, GearFocus.STRENGTH, null), SetupKills.NONE, 0);
		assertTrue(toggles.getComponent().getPreferredSize().width <= width);
		assertFalse(toggles.isMenuOpen());
	}

	private static BufferedImage paint(Icon icon)
	{
		BufferedImage canvas = new BufferedImage(icon.getIconWidth(), icon.getIconHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = canvas.createGraphics();
		try
		{
			icon.paintIcon(null, g, 0, 0);
		}
		finally
		{
			g.dispose();
		}
		return canvas;
	}

	private static boolean hasColour(BufferedImage image, int argb)
	{
		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if (image.getRGB(x, y) == argb)
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.junit.Test;

public class SkillXpTest
{
	private static Map<String, Integer> reading(Object... skillAndXp)
	{
		Map<String, Integer> map = new HashMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			map.put((String) skillAndXp[i], (Integer) skillAndXp[i + 1]);
		}
		return map;
	}

	private static Map<String, Long> xp(Object... skillAndXp)
	{
		Map<String, Long> map = new TreeMap<>();
		for (int i = 0; i < skillAndXp.length; i += 2)
		{
			map.put((String) skillAndXp[i], ((Number) skillAndXp[i + 1]).longValue());
		}
		return map;
	}

	@Test
	public void gainsAreTheSkillsThatWentUp()
	{
		Map<String, Long> gains = SkillXp.gains(reading("SLAYER", 1000, "HITPOINTS", 5000, "PRAYER", 300),
			reading("SLAYER", 1250, "HITPOINTS", 5100, "PRAYER", 300));
		assertEquals(xp("SLAYER", 250, "HITPOINTS", 100), gains);
	}

	@Test
	public void noChangeIsNoGain()
	{
		assertEquals(Collections.emptyMap(), SkillXp.gains(reading("SLAYER", 1000), reading("SLAYER", 1000)));
	}

	@Test
	public void anyDecreaseMeansTheReadingsCantBeCompared()
	{
		// Another account, or a reading from before the stats synced: never a gain, even for the skill that went up.
		assertNull(SkillXp.gains(reading("SLAYER", 1000, "HITPOINTS", 5000),
			reading("SLAYER", 900_000, "HITPOINTS", 4000)));
	}

	@Test
	public void aMissingReadingCantBeCompared()
	{
		assertNull(SkillXp.gains(null, reading("SLAYER", 1)));
		assertNull(SkillXp.gains(reading("SLAYER", 1), null));
	}

	@Test
	public void aSkillMissingFromEitherReadingIsLeftOut()
	{
		assertEquals(xp("SLAYER", 5), SkillXp.gains(reading("SLAYER", 10, "PRAYER", 1),
			reading("SLAYER", 15, "MAGIC", 99)));
	}

	@Test
	public void addMergesAndSaturates()
	{
		Map<String, Long> into = xp("SLAYER", 100);
		SkillXp.add(into, xp("SLAYER", 50, "MAGIC", 10));
		SkillXp.add(into, null);
		assertEquals(xp("SLAYER", 150, "MAGIC", 10), into);
		SkillXp.add(into, xp("MAGIC", Long.MAX_VALUE));
		assertEquals(Long.valueOf(Long.MAX_VALUE), into.get("MAGIC"));
	}

	@Test
	public void sanitizeKeepsOnlyPositiveEntries()
	{
		Map<String, Long> raw = new HashMap<>();
		raw.put("SLAYER", 10L);
		raw.put("MAGIC", 0L);
		raw.put("PRAYER", -5L);
		raw.put("RANGED", null);
		raw.put(null, 7L);
		assertEquals(xp("SLAYER", 10), SkillXp.sanitize(raw));
		assertTrue(SkillXp.sanitize(null).isEmpty());
	}

	@Test
	public void totalAddsEverySkill()
	{
		assertEquals(360, SkillXp.total(xp("SLAYER", 250, "HITPOINTS", 100, "PRAYER", 10)));
		assertEquals(0, SkillXp.total(null));
	}

	@Test
	public void perHourNeedsAMinuteOfActiveTime()
	{
		assertNull(SkillXp.perHour(1000, TaskTimeEstimate.MIN_ACTIVE_MILLIS - 1));
		assertEquals(Long.valueOf(60_000), SkillXp.perHour(1000, TaskTimeEstimate.MIN_ACTIVE_MILLIS));
		assertEquals(Long.valueOf(40_000), SkillXp.perHour(20_000, 30 * 60_000));
	}

	@Test
	public void skillNames()
	{
		assertEquals("Hitpoints", SkillXp.skillName("HITPOINTS"));
		assertEquals("Slayer", SkillXp.skillName("SLAYER"));
		assertEquals("Unknown skill", SkillXp.skillName(null));
	}

	@Test
	public void totalTextShowsTheRateOnceThereIsOne()
	{
		Map<String, Long> gained = xp("SLAYER", 15_000, "HITPOINTS", 5_000);
		assertEquals("XP: 20K", SkillXp.totalText(gained, 30_000));
		assertEquals("XP: 20K (40K/h)", SkillXp.totalText(gained, 30 * 60_000));
		assertEquals("XP: 0 (0/h)", SkillXp.totalText(xp(), 30 * 60_000));
	}

	@Test
	public void unrecordedXpShowsADash()
	{
		assertEquals("XP: -", SkillXp.totalText(null, 60_000));
		assertTrue(SkillXp.rows(null, 60_000).isEmpty());
		assertFalse(SkillXp.tooltip(null, 60_000).contains("<html>"));
	}

	@Test
	public void rowsAreHighestFirstThenByName()
	{
		List<SkillXp.Row> rows = SkillXp.rows(xp("PRAYER", 100, "SLAYER", 900, "MAGIC", 100), 60 * 60_000);
		assertEquals(Arrays.asList("Slayer", "Magic", "Prayer"),
			Arrays.asList(rows.get(0).getName(), rows.get(1).getName(), rows.get(2).getName()));
		assertEquals("900", rows.get(0).amountText());
		assertEquals("no trailing zeros (DESIGN_PRINCIPLES 5.5)", "58K",
			SkillXp.rows(xp("SLAYER", 58_000), 60 * 60_000).get(0).amountText());
		assertEquals(Long.valueOf(900), rows.get(0).getPerHour());
		assertEquals("<html>Slayer: 900 XP<br>900 XP per hour</html>", rows.get(0).tooltip());
		assertNull("no rate without enough active time", SkillXp.rows(xp("SLAYER", 1), 0).get(0).getPerHour());
	}

	@Test
	public void tooltipListsEverySkill()
	{
		assertEquals("<html>XP gained: 1,500<br>XP per hour: 1,500<br>Slayer: 1,000<br>Hitpoints: 500"
			+ "<br>Counted only while the session runs.</html>",
			SkillXp.tooltip(xp("SLAYER", 1000, "HITPOINTS", 500), 60 * 60_000));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/**
 * When a long stretch of uncounted supply ticks is due for a debug line.
 */
public class SkippedSupplyTicksTest
{
	private final SkippedSupplyTicks skipped = new SkippedSupplyTicks();

	/** The stretch lengths at which a report is due, over {@code ticks} skipped ticks in a row. */
	private List<Integer> reportsOver(int ticks)
	{
		final List<Integer> reports = new ArrayList<>();
		for (int i = 0; i < ticks; i++)
		{
			if (skipped.skipped())
			{
				reports.add(skipped.length());
			}
		}
		return reports;
	}

	@Test
	public void aShortStretchIsNeverReported()
	{
		assertTrue(reportsOver(SkippedSupplyTicks.FIRST_REPORT_TICKS - 1).isEmpty());
		assertEquals(SkippedSupplyTicks.FIRST_REPORT_TICKS - 1, skipped.length());
	}

	@Test
	public void aLongStretchIsReportedAfterAMinuteThenEveryTenMinutes()
	{
		assertEquals(Arrays.asList(100, 1_100, 2_100), reportsOver(2_500));
	}

	@Test
	public void resetEndsTheStretch()
	{
		reportsOver(SkippedSupplyTicks.FIRST_REPORT_TICKS - 1);
		skipped.reset();
		assertEquals(0, skipped.length());
		assertFalse(skipped.skipped());
		assertEquals("a new stretch starts from one", Arrays.asList(100), reportsOver(99));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import java.util.Collections;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * {@link SlayerBracelets}: which game messages use a charge of the bracelet of slaughter or the expeditious bracelet,
 * and how a charge is valued. {@link HarnessSupplyCoverageTest} covers the plugin's wiring.
 */
public class SlayerBraceletsTest
{
	@Test
	public void itemIdsMatchTheGameValues()
	{
		// Checked against net.runelite.api.gameval.ItemID in RuneLite 1.13.4.
		assertEquals(21183, ItemID.BRACELET_OF_SLAUGHTER);
		assertEquals(21177, ItemID.EXPEDITIOUS_BRACELET);
		assertEquals(30, SlayerBracelets.CHARGES_PER_BRACELET);
	}

	@Test
	public void eachActivationUsesOneCharge()
	{
		assertEquals(ItemID.BRACELET_OF_SLAUGHTER, SlayerBracelets.chargeUsed(
			"Your bracelet of slaughter prevents your slayer count from decreasing. It has 29 charges left."));
		assertEquals(ItemID.BRACELET_OF_SLAUGHTER, SlayerBracelets.chargeUsed(
			"Your bracelet of slaughter prevents your slayer count from decreasing. It has 1 charge left."));
		assertEquals("the last charge", ItemID.BRACELET_OF_SLAUGHTER, SlayerBracelets.chargeUsed(
			"Your bracelet of slaughter prevents your slayer count from decreasing. It then crumbles to dust."));
		assertEquals("the last charge, regenerated", ItemID.BRACELET_OF_SLAUGHTER, SlayerBracelets.chargeUsed(
			"Your bracelet of slaughter prevents your slayer count from decreasing. It then regenerates itself to full "
				+ "charge!"));
		assertEquals(ItemID.EXPEDITIOUS_BRACELET, SlayerBracelets.chargeUsed(
			"Your expeditious bracelet helps you progress your slayer task faster. It has 12 charges left."));
		assertEquals(ItemID.EXPEDITIOUS_BRACELET, SlayerBracelets.chargeUsed(
			"Your expeditious bracelet helps you progress your slayer faster. It then crumbles to dust."));
		assertEquals("with colour tags", ItemID.EXPEDITIOUS_BRACELET, SlayerBracelets.chargeUsed(
			"<col=ef1020>Your expeditious bracelet helps you progress your slayer task faster. It then regenerates "
				+ "itself to full charge!</col>"));
	}

	@Test
	public void ignoresJagexColourMarkup()
	{
		assertEquals(ItemID.BRACELET_OF_SLAUGHTER, SlayerBracelets.chargeUsed(
			"@mes_hl_red@Your bracelet of slaughter prevents your slayer count from decreasing. It has 9 charges left.</col>"));
	}

	@Test
	public void checksAndOtherMessagesUseNothing()
	{
		assertEquals(SlayerBracelets.NONE, SlayerBracelets.chargeUsed("Your bracelet of slaughter has 12 charges left."));
		assertEquals(SlayerBracelets.NONE, SlayerBracelets.chargeUsed("Your expeditious bracelet has 1 charge left."));
		assertEquals(SlayerBracelets.NONE, SlayerBracelets.chargeUsed("Your Bracelet of Slaughter has crumbled to dust."));
		assertEquals(SlayerBracelets.NONE, SlayerBracelets.chargeUsed("You eat the shark."));
		assertEquals(SlayerBracelets.NONE, SlayerBracelets.chargeUsed(""));
		assertEquals(SlayerBracelets.NONE, SlayerBracelets.chargeUsed(null));
	}

	@Test
	public void aChargeIsWorthAThirtiethOfTheBracelet()
	{
		final ItemTally used = new ItemTally();
		used.add(ItemID.BRACELET_OF_SLAUGHTER, 3);
		assertEquals(300L, ItemValuation.total(used, Collections.singletonMap(ItemID.BRACELET_OF_SLAUGHTER, 3_000L),
			Collections.singletonMap(ItemID.BRACELET_OF_SLAUGHTER, SlayerBracelets.CHARGES_PER_BRACELET)));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.CALLS_REAL_METHODS;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.config.ConfigDescriptor;
import net.runelite.client.config.ConfigItemDescriptor;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.ConfigSectionDescriptor;
import net.runelite.client.config.Range;
import org.junit.Test;

/**
 * The "Loot price" setting read through RuneLite's own config proxy handler (the one
 * {@link ConfigManager#getConfig(Class)} uses), so a value saved for the removed "Higher of the two" option is checked
 * against the client's real parsing rather than a stub.
 */
public class SlayerLedgerConfigTest
{
	/** A config proxy whose stored "Loot price" value is {@code saved} ({@code null} for unset). */
	private static SlayerLedgerConfig configWithLootPrice(String saved) throws Exception
	{
		// Only the stored string is stubbed; stringToObject (the enum parsing) is the client's own.
		ConfigManager manager = mock(ConfigManager.class, CALLS_REAL_METHODS);
		doReturn(saved).when(manager).getConfiguration(SlayerLedgerConfig.GROUP, SlayerLedgerConfig.LOOT_PRICE_MODE);
		return config(manager);
	}

	/** The config as {@link ConfigManager#getConfig(Class)} makes it, reading what {@code manager} stores. */
	private static SlayerLedgerConfig config(ConfigManager manager) throws Exception
	{
		// The handler class is package-private in the client.
		Constructor<?> ctor = Class.forName("net.runelite.client.config.ConfigInvocationHandler")
			.getDeclaredConstructor(ConfigManager.class);
		ctor.setAccessible(true);
		InvocationHandler handler = (InvocationHandler) ctor.newInstance(manager);
		return (SlayerLedgerConfig) Proxy.newProxyInstance(SlayerLedgerConfig.class.getClassLoader(),
			new Class<?>[]{SlayerLedgerConfig.class}, handler);
	}

	@Test
	public void savedModesAreRead() throws Exception
	{
		assertEquals(LootPriceMode.GE, configWithLootPrice("GE").lootPriceMode());
		assertEquals(LootPriceMode.HIGH_ALCH, configWithLootPrice("HIGH_ALCH").lootPriceMode());
		assertEquals("unset", LootPriceMode.GE, configWithLootPrice(null).lootPriceMode());
	}

	@Test
	public void defaults()
	{
		SlayerLedgerConfig defaults = new SlayerLedgerConfig()
		{
		};
		assertFalse(defaults.taskCompleteNotification());
		// The chat lines of the personality pass (2.0 phase 11) are on by default.
		assertTrue(defaults.taskCompleteLine());
		assertTrue(defaults.recordTaskLine());
		assertTrue(defaults.notableDropLine());
		assertTrue(defaults.showTaskOverlay());
		// Every overlay group is on (V2 plan 2.1).
		assertTrue(defaults.overlayProgress());
		assertTrue(defaults.overlayPace());
		assertTrue(defaults.overlayHaul());
		assertTrue(defaults.overlayRunway());
		// Every panel section is shown by default.
		assertTrue(defaults.showOverallTotals());
		assertTrue(defaults.showSkippedBlocked());
		// Away after 10 minutes without a task kill or a hit on a task NPC (V2 plan 4.1).
		assertEquals(10, defaults.awayMinutes());
	}

	@Test
	public void awayMinutesIsLimitedToOneToSixtyMinutes() throws Exception
	{
		Range range = SlayerLedgerConfig.class.getMethod("awayMinutes").getAnnotation(Range.class);
		assertEquals(1, range.min());
		assertEquals(60, range.max());

		SessionTracker tracker = new SessionTracker(() -> 0L);
		tracker.setAwayMinutes(0);
		assertEquals(60_000L, tracker.getAwayMillis());
		tracker.setAwayMinutes(500);
		assertEquals(60 * 60_000L, tracker.getAwayMillis());
		tracker.setAwayMinutes(10);
		assertEquals(10 * 60_000L, tracker.getAwayMillis());
	}

	@Test
	public void theAdvisorSettingsBundleCRemovedAreGone() throws Exception
	{
		// The "Task advisor" badge, the "Advisor metric" and the "Advisor chat line" (saved under 1.x's
		// "assignmentPreview") went with bundle C (owner decision 2026-11-16), with their section. A stored
		// value of a removed key is left orphaned, which is harmless: nothing reads it.
		ConfigDescriptor descriptor = mock(ConfigManager.class, CALLS_REAL_METHODS)
			.getConfigDescriptor(configWithLootPrice(null));
		for (ConfigItemDescriptor item : descriptor.getItems())
		{
			assertFalse(item.getItem().keyName(), Arrays.asList("taskAdvisor", "advisorMetric", "assignmentPreview")
				.contains(item.getItem().keyName()));
		}
		for (ConfigSectionDescriptor section : descriptor.getSections())
		{
			assertNotEquals("taskAdvisorSection", section.getKey());
		}
	}

	@Test
	public void theOverlayGroupsKeepTheRowSettingsKeysThatMapToThem() throws Exception
	{
		// 1.x's "Show task row" (the name and kills left) is Progress and identity, and its "Show profit row" Haul.
		assertEquals("overlayTask", SlayerLedgerConfig.OVERLAY_PROGRESS);
		assertEquals("overlayProfit", SlayerLedgerConfig.OVERLAY_HAUL);
		assertEquals("overlayPace", SlayerLedgerConfig.OVERLAY_PACE);
		assertEquals("overlayRunway", SlayerLedgerConfig.OVERLAY_RUNWAY);

		// As 1.x saved both rows turned off: still off.
		ConfigManager manager = mock(ConfigManager.class, CALLS_REAL_METHODS);
		doReturn("false").when(manager).getConfiguration(SlayerLedgerConfig.GROUP, "overlayTask");
		doReturn("false").when(manager).getConfiguration(SlayerLedgerConfig.GROUP, "overlayProfit");
		// 1.x's kills and time-left rows have no group of their own: their keys are no longer read.
		doReturn("false").when(manager).getConfiguration(SlayerLedgerConfig.GROUP, "overlayKills");
		doReturn("false").when(manager).getConfiguration(SlayerLedgerConfig.GROUP, "overlayTimeLeft");
		// Never saved: the defaults.
		doReturn(null).when(manager).getConfiguration(SlayerLedgerConfig.GROUP, "overlayPace");
		doReturn(null).when(manager).getConfiguration(SlayerLedgerConfig.GROUP, "overlayRunway");
		doReturn(null).when(manager).getConfiguration(SlayerLedgerConfig.GROUP, "showTaskOverlay");
		SlayerLedgerConfig config = config(manager);

		assertFalse(config.overlayProgress());
		assertFalse(config.overlayHaul());
		assertTrue("new: on", config.overlayPace());
		assertTrue("new: on", config.overlayRunway());
		assertTrue(config.showTaskOverlay());

		List<String> keys = new ArrayList<>();
		for (ConfigItemDescriptor item : mock(ConfigManager.class, CALLS_REAL_METHODS)
			.getConfigDescriptor(configWithLootPrice(null)).getItems())
		{
			keys.add(item.getItem().keyName());
		}
		assertFalse(keys.contains("overlayKills"));
		assertFalse(keys.contains("overlayTimeLeft"));
	}

	@Test
	public void everySettingIsPlacedInASectionInADeliberateOrder() throws Exception
	{
		// The client's own descriptor (sorted by position, then name), as the config panel lays it out.
		ConfigDescriptor descriptor = mock(ConfigManager.class, CALLS_REAL_METHODS)
			.getConfigDescriptor(configWithLootPrice(null));

		// Core settings first, the niche charged-weapon setting last.
		List<String> sections = new ArrayList<>();
		List<String> sectionNames = new ArrayList<>();
		for (ConfigSectionDescriptor section : descriptor.getSections())
		{
			sections.add(section.getKey());
			sectionNames.add(section.getSection().name());
		}
		assertEquals(Arrays.asList(SlayerLedgerConfig.trackingSection, SlayerLedgerConfig.valuesSection,
			SlayerLedgerConfig.chatSection, SlayerLedgerConfig.taskOverlaySection,
			SlayerLedgerConfig.panelSectionsSection, SlayerLedgerConfig.chargedWeaponsSection), sections);
		assertEquals(Arrays.asList("Tracking", "Values", "Chat", "Task overlay", "Panel sections", "Charged weapons"),
			sectionNames);

		// Every item has a position (no accidental by-name order) and a section; keys in config panel order.
		Map<String, List<String>> bySection = new LinkedHashMap<>();
		for (ConfigItemDescriptor item : descriptor.getItems())
		{
			String key = item.getItem().keyName();
			// -1 is ConfigItem's default: no position given.
			assertNotEquals("no position: " + key, -1, item.getItem().position());
			assertNotEquals("no section: " + key, "", item.getItem().section());
			bySection.computeIfAbsent(item.getItem().section(), k -> new ArrayList<>()).add(key);
		}
		// "Ask again about skipped places" went with the naming prompt.
		assertEquals(Arrays.asList("confirmIncomplete", "bonecrusherHandling", SlayerLedgerConfig.IGNORED_LOOT,
			SlayerLedgerConfig.AWAY_MINUTES),
			bySection.get(SlayerLedgerConfig.trackingSection));
		assertEquals(Arrays.asList(SlayerLedgerConfig.LOOT_PRICE_MODE, SlayerLedgerConfig.NOTABLE_DROP_THRESHOLD,
			SlayerLedgerConfig.HIDE_GROUND_ITEMS_HIDDEN), bySection.get(SlayerLedgerConfig.valuesSection));
		assertEquals(Arrays.asList(SlayerLedgerConfig.TASK_COMPLETE_LINE, "taskCompleteNotification",
			SlayerLedgerConfig.RECORD_TASK_LINE, SlayerLedgerConfig.NOTABLE_DROP_LINE),
			bySection.get(SlayerLedgerConfig.chatSection));
		// The master toggle first, then the four groups in the overlay's order.
		assertEquals(Arrays.asList("showTaskOverlay", SlayerLedgerConfig.OVERLAY_PROGRESS,
			SlayerLedgerConfig.OVERLAY_PACE, SlayerLedgerConfig.OVERLAY_HAUL, SlayerLedgerConfig.OVERLAY_RUNWAY),
			bySection.get(SlayerLedgerConfig.taskOverlaySection));
		// In sidebar order.
		assertEquals(Arrays.asList(SlayerLedgerConfig.SHOW_OVERALL_TOTALS, SlayerLedgerConfig.SHOW_SKIPPED_BLOCKED),
			bySection.get(SlayerLedgerConfig.panelSectionsSection));
		assertEquals(Collections.singletonList(SlayerLedgerConfig.VORKATHS_HEAD_UPGRADE),
			bySection.get(SlayerLedgerConfig.chargedWeaponsSection));
		assertEquals("no other section", 6, bySection.size());
	}

	@Test
	public void panelSectionSettingsAreNamedAsTheSidebarHeadings() throws Exception
	{
		ConfigDescriptor descriptor = mock(ConfigManager.class, CALLS_REAL_METHODS)
			.getConfigDescriptor(configWithLootPrice(null));
		List<String> names = new ArrayList<>();
		for (ConfigItemDescriptor item : descriptor.getItems())
		{
			if (SlayerLedgerConfig.panelSectionsSection.equals(item.getItem().section()))
			{
				names.add(item.getItem().name());
			}
			// Trends and the Luck meter were removed in 2.0, with their settings, and What to bring went into
			// the advisor card, with its setting. A stored value of a removed key is left orphaned,
			// which is harmless: nothing reads it.
			assertFalse(item.getItem().keyName(), Arrays.asList("showTrends", "showLuckMeter", "showWhatToBring")
				.contains(item.getItem().keyName()));
		}
		assertEquals(Arrays.asList("Overall totals", "Skipped / blocked"), names);
	}

	@Test
	public void theRemovedHigherOptionReadsAsGe() throws Exception
	{
		// Saved by clients from before "Higher of the two" was removed (owner decision, 2026-10-25).
		assertEquals(LootPriceMode.GE, configWithLootPrice("HIGHER").lootPriceMode());
	}
}

