		record.setMonster("Dust devils");
		record.setLocationRegion(TestSpots.SMOKE);
		record.setSpotId("smoke-dungeon-before");
		assertFalse(TABLE.knows("smoke-dungeon-before"));
		assertEquals(TestSpots.SMOKE_ID, TABLE.recordSpot(record));
		record.setSpotId("region:abc");
		assertEquals(TestSpots.SMOKE_ID, TABLE.recordSpot(record));
		assertEquals("the record is not changed", "region:abc", record.getSpotId());
		record.setSpotId(" region:" + TestSpots.UNLISTED + " ");
		assertEquals("an unlisted region's key is known", "region:" + TestSpots.UNLISTED, TABLE.recordSpot(record));
		record.setSpotId("region:" + TestSpots.SMOKE);
		assertFalse("a region key of a region the table now lists", TABLE.knows("region:" + TestSpots.SMOKE));
		assertEquals("moves to that region's spot", TestSpots.SMOKE_ID, TABLE.recordSpot(record));
		record.setSpotId(TestSpots.CATACOMBS_ID);
		assertEquals("a known id wins over the region", TestSpots.CATACOMBS_ID, TABLE.recordSpot(record));
		record.setSpotId("gone");
		record.setLocationRegion(null);
		assertNull("no region either: Unknown", TABLE.recordSpot(record));
		assertEquals("without the table, a stored id is kept", "gone", SlayerSpots.NONE.recordSpot(record));
	}

	@Test
	public void withoutTheTableNoSpotIsGiven()
	{
		assertFalse(SlayerSpots.NONE.isAvailable());
		assertTrue(SlayerSpots.NONE.spots().isEmpty());
		assertNull(SlayerSpots.NONE.spotAt(3093, 3491, 0));
		assertNull("listed and unlisted can't be told apart", SlayerSpots.NONE.spotForRegion(TestSpots.UNLISTED, null));
		LedgerRecord record = new LedgerRecord();
		record.setLocationRegion(TestSpots.SMOKE);
		assertNull(SlayerSpots.NONE.recordSpot(record));
		record.setSpotId(TestSpots.SMOKE_ID);
		assertEquals("a stored spot is still the record's", TestSpots.SMOKE_ID, SlayerSpots.NONE.recordSpot(record));
		assertNull(SlayerSpots.NONE.name(TestSpots.SMOKE_ID));
		assertNull(SlayerSpots.NONE.getRetrieved());
	}

	@Test
	public void missingMalformedOrInvalidResourcesLoadAsNone()
	{
		assertSame(SlayerSpots.NONE, SlayerSpots.load(GSON, "no-such-slayer-spots.json"));
		assertSame(SlayerSpots.NONE, SlayerSpots.load(GSON, "slayer-spots-malformed.json"));
		// Valid JSON, but the same id twice.
		assertSame(SlayerSpots.NONE, SlayerSpots.load(GSON, "slayer-spots-invalid.json"));
		assertSame(SlayerSpots.NONE, SlayerSpots.load(null, SlayerSpots.SNAPSHOT_RESOURCE));
	}

	@Test
	public void validationRejectsBadTables()
	{
		assertNotNull(SlayerSpots.parse(GSON, new StringReader(table(1, SPOT))));
		assertRejected("null");
		assertRejected(table(2, SPOT));
		assertRejected(table(1, ""));
		assertRejected(table(1, "null"));
		assertRejected(table(1, SPOT + ", " + SPOT));
		assertRejected(table(1, SPOT.replace("\"id\": \"smoke-dungeon\"", "\"id\": \" \"")));
		assertRejected(table(1, SPOT.replace("\"id\": \"smoke-dungeon\"", "\"id\": \"region:5\"")));
		assertRejected(table(1, SPOT.replace("\"name\": \"Smoke Dungeon\"", "\"name\": \"\"")));
		assertRejected(table(1, SPOT.replace("\"short\": \"Smoke Dungeon\"", "\"short\": \"Smoke Dungeon west\"")));
		assertRejected(table(1, SPOT.replace("[12946]", "[]")));
		assertRejected(table(1, SPOT.replace("[12946]", "[-1]")));
		assertRejected(table(1, SPOT.replace("[\"Dust devils\"]", "[\" \"]")));
		assertRejected(table(1, SPOT.replace("\"sources\": [\"s\"]", "\"sources\": []")));
		assertRejected(table(1, SPOT.replace("\"plane\": null", "\"plane\": 4")));
		assertRejected(table(1, SPOT.replace("\"bounds\": null", "\"bounds\": [[1, 2, 3]]")));
		assertRejected(table(1, SPOT.replace("\"bounds\": null", "\"bounds\": [[5, 2, 3, 4]]")));
		assertRejected(table(1, SPOT).replace("\"matching\": \"m\", ", ""));
	}

	private static final String SPOT = "{ \"id\": \"smoke-dungeon\", \"name\": \"Smoke Dungeon\", "
		+ "\"short\": \"Smoke Dungeon\", \"regions\": [12946], \"plane\": null, \"bounds\": null, "
		+ "\"tasks\": [\"Dust devils\"], \"sources\": [\"s\"], \"confidence\": \"high\" }";

	private static String table(int version, String spots)
	{
		return "{ \"version\": " + version + ", \"source\": \"Old School RuneScape Wiki\", "
			+ "\"license\": \"CC BY-NC-SA 3.0\", \"licenseUrl\": \"https://creativecommons.org/licenses/by-nc-sa/3.0/\", "
			+ "\"contributors\": \"Old School RuneScape Wiki contributors\", \"retrieved\": \"2026-11-09\", "
			+ "\"attribution\": \"Test\", \"matching\": \"m\", \"spots\": [" + spots + "] }";
	}

	private static void assertRejected(String json)
	{
		try
		{
			SlayerSpots.parse(GSON, new StringReader(json));
			fail("Expected the table to be rejected: " + json);
		}
		catch (RuntimeException expected)
		{
			// Rejected, as load() would turn into NONE.
		}
	}

	/** The names in RuneLite's core Slayer {@code Task} enum (package-private, so read by reflection). */
	static Set<String> coreTaskNames() throws Exception
	{
		Class<?> taskClass = Class.forName("net.runelite.client.plugins.slayer.Task");
		Method getName = taskClass.getDeclaredMethod("getName");
		getName.setAccessible(true);
		Set<String> names = new HashSet<>();
		for (Object task : taskClass.getEnumConstants())
		{
			names.add((String) getName.invoke(task));
		}
		assertTrue(names.size() > 100);
		return names;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** {@link StreakMilestone}: the next bonus-points task of a streak and which counter a master's streak is. */
public class StreakMilestoneTest
{
	@Test
	public void nextBonusIsTheNextMultipleOfTen()
	{
		assertEquals("Next bonus: task 10 (in 10)", StreakMilestone.format(0));
		assertEquals("Next bonus: task 10 (in 1)", StreakMilestone.format(9));
		assertEquals("strictly above: task 10 is done", "Next bonus: task 20 (in 10)", StreakMilestone.format(10));
		assertEquals("Next bonus: task 50 (in 3)", StreakMilestone.format(47));
		assertEquals("Next bonus: task 1000 (in 1)", StreakMilestone.format(999));
		assertEquals("Next bonus: task 1010 (in 10)", StreakMilestone.format(1000));
		assertEquals("Next bonus: task 12350 (in 5)", StreakMilestone.format(12345));
	}

	@Test
	public void shortFormForTheTaskBox()
	{
		assertEquals("bonus in 3", StreakMilestone.formatShort(47));
		assertEquals("bonus in 10", StreakMilestone.formatShort(10));
		assertNull(StreakMilestone.formatShort(null));
		assertNull(StreakMilestone.formatShort(Integer.MAX_VALUE));
	}

	@Test
	public void largeStreaksDontOverflow()
	{
		assertEquals(Integer.valueOf(2_000_000_000), StreakMilestone.nextMilestone(1_999_999_999));
		assertEquals(Integer.valueOf(2_147_483_640), StreakMilestone.nextMilestone(Integer.MAX_VALUE - 10));
		assertNull(StreakMilestone.nextMilestone(Integer.MAX_VALUE - 9));
		assertNull(StreakMilestone.format(Integer.MAX_VALUE));
	}

	@Test
	public void unknownStreakHasNoHint()
	{
		assertNull(StreakMilestone.format(null));
		assertNull(StreakMilestone.format(-1));
		assertNull(StreakMilestone.nextMilestone(Integer.MIN_VALUE));
	}

	@Test
	public void milestoneIsAPositiveMultipleOfTen()
	{
		for (int streak : new int[]{10, 50, 100, 250, 1000, 1010})
		{
			assertTrue("streak " + streak, StreakMilestone.isMilestone(streak));
		}
		for (int streak : new int[]{0, 1, 9, 11, 99, 101, -10})
		{
			assertFalse("streak " + streak, StreakMilestone.isMilestone(streak));
		}
		assertFalse("unknown", StreakMilestone.isMilestone(null));
	}

	@Test
	public void counterFollowsTheMaster()
	{
		assertEquals(StreakMilestone.WILDERNESS, StreakMilestone.counterFor(SlayerMaster.KRYSTILIA));
		assertEquals(StreakMilestone.MORTIMER, StreakMilestone.counterFor(SlayerMaster.MORTIMER));
		for (int master : new int[]{1, 2, 3, 4, 5, 6, SlayerMaster.KONAR, 9})
		{
			assertEquals("master " + master, StreakMilestone.REGULAR, StreakMilestone.counterFor(master));
		}
	}

	@Test
	public void unknownMasterHasNoCounter()
	{
		assertEquals(StreakMilestone.NO_COUNTER, StreakMilestone.counterFor(null));
		assertEquals(StreakMilestone.NO_COUNTER, StreakMilestone.counterFor(SlayerMaster.NONE));
		assertEquals("not in the table", StreakMilestone.NO_COUNTER, StreakMilestone.counterFor(11));
		assertEquals(StreakMilestone.NO_COUNTER, StreakMilestone.counterFor(-3));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Recognising the superior spawn game message.
 */
public class SuperiorSpawnMessageTest
{
	@Test
	public void textMatchesCoreSlayerPlugin()
	{
		// net.runelite.client.plugins.slayer.SlayerPlugin.CHAT_SUPERIOR_MESSAGE in RuneLite 1.13.4.
		assertEquals("A superior foe has appeared...", SuperiorSpawnMessage.TEXT);
	}

	@Test
	public void matchesPlainAndColouredText()
	{
		assertTrue(SuperiorSpawnMessage.matches(true, "A superior foe has appeared..."));
		assertTrue(SuperiorSpawnMessage.matches(true, "<col=ef1020>A superior foe has appeared...</col>"));
		assertTrue(SuperiorSpawnMessage.matches(true, " <col=ff0000>A superior foe has appeared...</col> "));
	}

	@Test
	public void matchesJagexColourMarkup()
	{
		// As the game sends it since November 2026.
		assertTrue(SuperiorSpawnMessage.matches(true, "@mes_hl_red@A superior foe has appeared...</col>"));
		assertTrue(SuperiorSpawnMessage.matches(true, "@red@A superior foe has appeared..."));
		assertFalse(SuperiorSpawnMessage.matches(true, "@mes_hl_red@Someone said: A superior foe has appeared...</col>"));
	}

	@Test
	public void otherTextDoesNotMatch()
	{
		assertFalse(SuperiorSpawnMessage.matches(true, "A superior foe has appeared"));
		assertFalse(SuperiorSpawnMessage.matches(true, "a superior foe has appeared..."));
		assertFalse(SuperiorSpawnMessage.matches(true, "Someone said: A superior foe has appeared..."));
		assertFalse(SuperiorSpawnMessage.matches(true, "You have completed your task!"));
		assertFalse(SuperiorSpawnMessage.matches(true, ""));
		assertFalse(SuperiorSpawnMessage.matches(true, null));
	}

	@Test
	public void onlyGameOrSpamMessagesMatch()
	{
		assertFalse(SuperiorSpawnMessage.matches(false, "A superior foe has appeared..."));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.runelite.client.util.Filepath;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/**
 * Supplies in the session tracker, snapshots and ledger records, including per-dose potion valuation.
 */
public class SuppliesSessionTest
{
	private static final int DEMON_ID = 42;
	private static final int DRAGON_ID = 43;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};
	private static final int SHARK = SupplyTrackerTest.SHARK;
	private static final int PRAYER_4 = SupplyTrackerTest.PRAYER_4;
	private static final int PRAYER_3 = SupplyTrackerTest.PRAYER_3;
	private static final int ARROW = SupplyTrackerTest.ADAMANT_ARROW;

	/** Shark 1,000 GE / 180 HA; prayer potion(4) 8,002 GE / 228 HA; arrows 10 GE / 48 HA. */
	private static final ItemValuation.PriceLookup PRICES = new ItemValuation.PriceLookup()
	{
		@Override
		public int canonicalize(int itemId)
		{
			return itemId;
		}

		@Override
		public long gePrice(int id)
		{
			return id == SHARK ? 1_000 : id == PRAYER_4 ? 8_002 : id == ARROW ? 10 : 0;
		}

		@Override
		public long haPrice(int id)
		{
			return id == SHARK ? 180 : id == PRAYER_4 ? 228 : id == ARROW ? 48 : 0;
		}

		@Override
		public boolean isTradeable(int canonicalId)
		{
			return true;
		}
	};

	@Rule
	public TemporaryFolder temp = new TemporaryFolder();

	private long now;
	private SessionTracker tracker;
	private final Gson gson = new Gson();

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	private static ItemTally tally(int... idQty)
	{
		ItemTally t = new ItemTally();
		for (int i = 0; i < idQty.length; i += 2)
		{
			t.add(idQty[i], idQty[i + 1]);
		}
		return t;
	}

	private static Map<Integer, Integer> doses(int id, int n)
	{
		Map<Integer, Integer> m = new TreeMap<>();
		m.put(id, n);
		return m;
	}

	private void startDemonTask()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertTrue(tracker.startNow(ACCOUNT));
	}

	// ---- Tracker ----

	@Test
	public void suppliesAreRecordedOnlyWhileRunning()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 50, 150, false);
		assertFalse("idle", tracker.addSupplies(tally(SHARK, 1), null, null));
		assertTrue(tracker.startNow(ACCOUNT));
		assertTrue(tracker.addSupplies(tally(SHARK, 2, PRAYER_4, 3), null, doses(PRAYER_4, 4)));
		tracker.pause();
		assertFalse("paused", tracker.addSupplies(tally(SHARK, 5), null, null));
		tracker.startNow(ACCOUNT);
		tracker.loggedOut();
		assertFalse("auto-paused", tracker.addSupplies(tally(SHARK, 5), null, null));

		assertEquals(2, tracker.getSupplies().get(SHARK));
		assertEquals(3, tracker.getSupplies().get(PRAYER_4));
		assertEquals(Integer.valueOf(4), tracker.getSupplyDoses().get(PRAYER_4));

		SessionTracker.Summary summary = tracker.stopAndReset();
		assertEquals(2, summary.getSupplies().get(SHARK));
		assertEquals(Integer.valueOf(4), summary.getSupplyDoses().get(PRAYER_4));
		assertFalse("stopped/idle", tracker.addSupplies(tally(SHARK, 1), null, null));
		assertTrue(tracker.getSupplies().isEmpty());
		assertTrue(tracker.getSupplyDoses().isEmpty());
	}

	@Test
	public void returnedAmmoReducesUsedButNeverBelowZero()
	{
		startDemonTask();
		tracker.addSupplies(tally(ARROW, 10, SHARK, 1), null, null);
		assertTrue(tracker.addSupplies(null, tally(ARROW, 4), null));
		assertEquals(6, tracker.getSupplies().get(ARROW));
		tracker.addSupplies(null, tally(ARROW, 50), null);
		assertEquals(0, tracker.getSupplies().get(ARROW));
		assertFalse("nothing left to offset", tracker.addSupplies(null, tally(ARROW, 1), null));
		assertEquals(1, tracker.getSupplies().get(SHARK));
		assertFalse(tracker.getSupplies().itemIds().contains(ARROW));
	}

	/**
	 * a corrected cannon pickup reports the same item as used and returned in one call (the guessed load moved
	 * to granite, and the granite that came back). The used amount must be merged before the returned one is taken
	 * off, or the returned granite would be clamped against nothing and the full load counted as fired.
	 */
	@Test
	public void usedIsMergedBeforeReturnedOfTheSameItemIsSubtracted()
	{
		startDemonTask();
		final int regular = SupplyTracker.CANNONBALL;
		final int granite = SupplyTracker.GRANITE_CANNONBALL;
		// The cannon's varp emptied a tick before the cannonballs came back, under the regular guess.
		assertTrue(tracker.addSupplies(tally(regular, 26), null, null));
		// The pickup shows granite: 30 granite loaded, 26 granite back, and the guessed regular load offset.
		assertTrue(tracker.addSupplies(tally(granite, 30), tally(regular, 30, granite, 26), null));
		assertEquals(4, tracker.getSupplies().get(granite));
		assertEquals(0, tracker.getSupplies().get(regular));
	}

	@Test
	public void heldCompletionGetsNoSuppliesButANewSessionDoes()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 1, 150, false);
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.addSupplies(tally(SHARK, 2), null, null);
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, true);
		assertTrue(tracker.holdCompletion());
		assertFalse("held session is no longer running", tracker.addSupplies(tally(SHARK, 3), null, null));

		tracker.observe("Black dragons", DRAGON_ID, 20, 20, false);
		assertTrue(tracker.startNow(ACCOUNT));
		assertTrue(tracker.addSupplies(tally(SHARK, 4), null, null));
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(2, held.getSupplies().get(SHARK));
		assertEquals(4, tracker.getSupplies().get(SHARK));
	}

	@Test
	public void lateLootKeepsTheHeldSessionsSupplies()
	{
		tracker.observe("Abyssal demons", DEMON_ID, 1, 150, false);
		assertTrue(tracker.startNow(ACCOUNT));
		tracker.addSupplies(tally(PRAYER_4, 2), null, doses(PRAYER_4, 4));
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, true);
		assertTrue(tracker.holdCompletion());
		tracker.addLoot(tally(526, 1));
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(1, held.getLoot().get(526));
		assertEquals(2, held.getSupplies().get(PRAYER_4));
		assertEquals(Integer.valueOf(4), held.getSupplyDoses().get(PRAYER_4));
	}

	@Test
	public void endToEndFromTickDiffsToValuedRecord()
	{
		SupplyTracker supplies = new SupplyTracker(SupplyTrackerTest.CLASSIFIER);
		startDemonTask();
		feed(supplies, SupplyTrackerTest.obs(SHARK, 10, PRAYER_4, 3, ARROW, 100));
		feed(supplies, SupplyTrackerTest.obs(SHARK, 8, PRAYER_4, 2, PRAYER_3, 1, ARROW, 90));
		feed(supplies, SupplyTrackerTest.obs(SHARK, 8, PRAYER_4, 2, PRAYER_3, 1, ARROW, 95));

		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertEquals(Long.valueOf(2), record.getSupplies().get(SHARK));
		assertEquals(Long.valueOf(1), record.getSupplies().get(PRAYER_4));
		assertEquals("10 fired, 5 picked up", Long.valueOf(5), record.getSupplies().get(ARROW));
		assertEquals(Collections.singletonMap(PRAYER_4, 4), record.getSupplyDoses());

		record.captureValues(PRICES);
		// 2 sharks + 1 dose of a 4-dose potion (8,002 / 4 = 2,000.5, rounded) + 5 arrows.
		assertEquals(Long.valueOf(2 * 1_000 + 2_001 + 5 * 10), record.getSuppliesGeValue());
		assertEquals(Long.valueOf(2 * 180 + 57 + 5 * 48), record.getSuppliesHaValue());
		assertEquals("unit prices stay per item", Long.valueOf(8_002), record.getUnitGePrices().get(PRAYER_4));
	}

	private void feed(SupplyTracker supplies, SupplyTracker.Observation o)
	{
		SupplyTracker.Usage usage = supplies.update(o, tracker.getState() == SessionTracker.State.RUNNING, false,
			Collections.emptySet());
		tracker.addSupplies(usage.getUsed(), usage.getReturned(), usage.getDoses());
	}

	// ---- Valuation ----

	@Test
	public void potionSuppliesAreValuedPerDose()
	{
		LedgerRecord record = new LedgerRecord();
		Map<Integer, Long> used = new TreeMap<>();
		used.put(PRAYER_4, 10L);
		used.put(SHARK, 3L);
		record.setSupplies(used);
		record.setSupplyDoses(doses(PRAYER_4, 4));
		record.captureValues(PRICES);
		// 10 doses = 2.5 potions: 8,002 * 10 / 4 = 20,005.
		assertEquals(Long.valueOf(20_005 + 3_000), record.getSuppliesGeValue());
		assertEquals(Long.valueOf(570 + 540), record.getSuppliesHaValue());
	}

	@Test
	public void doseTotalRoundsToTheNearestCoin()
	{
		Map<Integer, Long> prices = Collections.singletonMap(PRAYER_4, 1_001L);
		assertEquals("3,003 / 4 = 750.75", 751, ItemValuation.total(tally(PRAYER_4, 3), prices, doses(PRAYER_4, 4)));
		assertEquals("1,001 / 4 = 250.25", 250, ItemValuation.total(tally(PRAYER_4, 1), prices, doses(PRAYER_4, 4)));
		assertEquals("no dose entry: per item", 3_003, ItemValuation.total(tally(PRAYER_4, 3), prices, null));
	}

	@Test
	public void recordWithoutSuppliesHasNoSupplyValues()
	{
		startDemonTask();
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertNull(record.getSupplies());
		assertNull(record.getSupplyDoses());
		record.captureValues(PRICES);
		assertNull(record.getSuppliesGeValue());
		assertNull(record.getSuppliesHaValue());
		String json = gson.toJson(record);
		assertFalse(json, json.contains("supplies") || json.contains("supplyDoses"));
	}

	@Test
	public void dosesAreKeptOnlyForRecordedSupplies()
	{
		startDemonTask();
		tracker.addSupplies(tally(PRAYER_4, 2, ARROW, 3), null, doses(PRAYER_4, 4));
		tracker.addSupplies(null, tally(PRAYER_4, 5), null);
		// Returns only ever come from ammo and cannonballs, but a fully offset id must not leave a stray dose entry.
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertNull(record.getSupplyDoses());
		assertEquals(Long.valueOf(3), record.getSupplies().get(ARROW));
	}

	// ---- Snapshots and restore ----

	private SessionSnapshot snapshotWithSupplies()
	{
		startDemonTask();
		tracker.addSupplies(tally(SHARK, 4, PRAYER_4, 6), null, doses(PRAYER_4, 4));
		now += 30_000;
		tracker.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		tracker.loggedOut();
		return SessionSnapshot.fromSummary(tracker.activeSummary(), COUNTERS, now);
	}

	@Test
	public void snapshotWithSuppliesRoundTripsThroughJson()
	{
		SessionSnapshot s = snapshotWithSupplies();
		String json = gson.toJson(s);
		assertTrue(json, json.contains("\"supplies\":{\"385\":4,\"2434\":6}"));
		assertTrue(json, json.contains("\"supplyDoses\":{\"2434\":4}"));
		SessionSnapshot back = gson.fromJson(json, SessionSnapshot.class);
		assertEquals(s, back);
		assertEquals(SessionSnapshot.CURRENT_SCHEMA_VERSION, back.getSchemaVersion());
	}

	@Test
	public void fileRestoreKeepsSuppliesAndAddsToThem()
	{
		SessionSnapshot s = gson.fromJson(gson.toJson(snapshotWithSupplies()), SessionSnapshot.class);
		SessionTracker restored = new SessionTracker(() -> now);
		restored.observe("Abyssal demons", DEMON_ID, 46, 150, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(s, COUNTERS));
		assertEquals(4, restored.getSupplies().get(SHARK));
		assertFalse("restored session is paused", restored.addSupplies(tally(SHARK, 10), null, null));
		assertTrue(restored.startNow(ACCOUNT));
		restored.addSupplies(tally(SHARK, 1, PRAYER_4, 1), null, doses(PRAYER_4, 4));

		LedgerRecord record = LedgerRecord.fromSummary(restored.stopAndReset(), true);
