		SupplyTracker.Usage usage = total(new int[]{ItemID.RING_OF_DUELING_8, 1, ItemID.NECKLACE_OF_MINIGAMES_5, 2},
			new int[]{ItemID.RING_OF_DUELING_7, 1, ItemID.NECKLACE_OF_MINIGAMES_5, 2},
			new int[]{ItemID.RING_OF_DUELING_7, 1, ItemID.NECKLACE_OF_MINIGAMES_5, 1, ItemID.NECKLACE_OF_MINIGAMES_4, 1});
		assertEquals(1, usage.getUsed().get(ItemID.RING_OF_DUELING_8));
		assertEquals(1, usage.getUsed().get(ItemID.NECKLACE_OF_MINIGAMES_8));
		assertEquals(Integer.valueOf(8), usage.getDoses().get(ItemID.RING_OF_DUELING_8));
		assertEquals(Integer.valueOf(8), usage.getDoses().get(ItemID.NECKLACE_OF_MINIGAMES_8));
		assertEquals(2, usage.getUsed().size());

		Map<Integer, Long> prices = new HashMap<>();
		prices.put(ItemID.RING_OF_DUELING_8, 800L);
		prices.put(ItemID.NECKLACE_OF_MINIGAMES_8, 1600L);
		assertEquals("one eighth of each", 100L + 200L, ItemValuation.total(usage.getUsed(), prices, usage.getDoses()));
	}

	@Test
	public void wornJewelleryIsCountedAndEquippingItNetsToZero()
	{
		// The plugin adds the worn amulet, ring and gloves slots to the same observation as the inventory.
		tick(ItemID.AMULET_OF_GLORY_4, 1, ItemID.SLAYER_RING_8, 1);
		assertTrue("equipping the ring from the inventory", tick(ItemID.AMULET_OF_GLORY_4, 1, ItemID.SLAYER_RING_8, 1)
			.isEmpty());
		SupplyTracker.Usage glory = tick(ItemID.AMULET_OF_GLORY_3, 1, ItemID.SLAYER_RING_8, 1);
		assertEquals("teleporting from the equipment tab", 1, glory.getUsed().get(ItemID.AMULET_OF_GLORY_6));
		assertEquals(Integer.valueOf(6), glory.getDoses().get(ItemID.AMULET_OF_GLORY_6));
		SupplyTracker.Usage ring = tick(ItemID.AMULET_OF_GLORY_3, 1, ItemID.SLAYER_RING_7, 1);
		assertEquals(1, ring.getUsed().get(ItemID.SLAYER_RING_8));
		assertEquals(Integer.valueOf(8), ring.getDoses().get(ItemID.SLAYER_RING_8));
	}

	@Test
	public void theLastChargeCountsOnceWhenTheItemCrumbles()
	{
		SupplyTracker.Usage usage = total(new int[]{ItemID.RING_OF_DUELING_1, 1, ItemID.NECKLACE_OF_PASSAGE_1, 1},
			new int[]{ItemID.NECKLACE_OF_PASSAGE_1, 1},
			new int[]{});
		assertEquals(1, usage.getUsed().get(ItemID.RING_OF_DUELING_8));
		assertEquals(1, usage.getUsed().get(ItemID.NECKLACE_OF_PASSAGE_5));
		assertEquals(2, usage.getUsed().size());
	}

	@Test
	public void theLastChargeCountsOnceWhenTheItemBecomesUncharged()
	{
		SupplyTracker.Usage usage = total(new int[]{ItemID.AMULET_OF_GLORY_1, 1, ItemID.JEWL_BRACELET_OF_COMBAT_1, 1},
			new int[]{ItemID.AMULET_OF_GLORY, 1, ItemID.JEWL_BRACELET_OF_COMBAT_1, 1},
			new int[]{ItemID.AMULET_OF_GLORY, 1, ItemID.JEWL_BRACELET_OF_COMBAT, 1});
		assertEquals(1, usage.getUsed().get(ItemID.AMULET_OF_GLORY_6));
		assertEquals(1, usage.getUsed().get(ItemID.JEWL_BRACELET_OF_COMBAT_6));
		assertEquals("the uncharged amulet is not used", 0, usage.getUsed().get(ItemID.AMULET_OF_GLORY));
		assertEquals(2, usage.getUsed().size());
	}

	@Test
	public void rechargingIsNotAUseAndLaterChargesCountAgain()
	{
		SupplyTracker.Usage usage = total(new int[]{ItemID.AMULET_OF_GLORY, 3},
			// Fountain of Heroes: every uncharged amulet becomes a glory(4).
			new int[]{ItemID.AMULET_OF_GLORY_4, 3},
			new int[]{ItemID.AMULET_OF_GLORY_4, 2, ItemID.AMULET_OF_GLORY_3, 1});
		assertEquals("only the charge used after recharging", 1, usage.getUsed().get(ItemID.AMULET_OF_GLORY_6));
		assertEquals(1, usage.getUsed().size());
		assertTrue("a recharge is not a return", usage.getReturned().isEmpty());
	}

	@Test
	public void eternalJewelleryIsNeverCounted()
	{
		tick(ItemID.AMULET_OF_GLORY_INF, 1, ItemID.SLAYER_RING_ETERNAL, 1);
		assertTrue(tick().isEmpty());
	}

	@Test
	public void trimmedAndImbuedVariantsAreFamiliesOfTheirOwn()
	{
		SupplyTracker.Usage usage = total(
			new int[]{ItemID.AMULET_OF_GLORY_4, 1, ItemID.TRAIL_AMULET_OF_GLORY_4, 1, ItemID.RING_OF_WEALTH_I5, 1},
			new int[]{ItemID.AMULET_OF_GLORY_4, 1, ItemID.TRAIL_AMULET_OF_GLORY_3, 1, ItemID.RING_OF_WEALTH_I4, 1});
		assertEquals(0, usage.getUsed().get(ItemID.AMULET_OF_GLORY_6));
		assertEquals(1, usage.getUsed().get(ItemID.TRAIL_AMULET_OF_GLORY_6));
		assertEquals(1, usage.getUsed().get(ItemID.RING_OF_WEALTH_I5));
		assertEquals(Integer.valueOf(5), usage.getDoses().get(ItemID.RING_OF_WEALTH_I5));
	}

	// ---- Exclusions ----

	@Test
	public void nothingIsCountedWhilePausedOrExcluded()
	{
		tick(ItemID.RING_OF_DUELING_8, 1, ItemID.SLAYER_BAG_OF_SALT, 10, ItemID.POH_TABLET_VARROCKTELEPORT, 5,
			ItemID.SLAYER_SPRAY_PUMP_10, 1);
		assertTrue("paused", supplies.update(SupplyTrackerTest.obs(ItemID.RING_OF_DUELING_7, 1,
			ItemID.SLAYER_BAG_OF_SALT, 9, ItemID.POH_TABLET_VARROCKTELEPORT, 4, ItemID.SLAYER_SPRAY_PUMP_9, 1),
			false, false, Collections.emptySet()).isEmpty());
		assertTrue("bank open: deposited", supplies.update(SupplyTrackerTest.obs(ItemID.SLAYER_SPRAY_PUMP_9, 1),
			true, true, Collections.emptySet()).isEmpty());
		// Nothing from the paused or banked ticks is counted later either.
		assertTrue(tick(ItemID.SLAYER_SPRAY_PUMP_9, 1).isEmpty());
	}

	@Test
	public void droppingIsNotAUse()
	{
		tick(ItemID.RING_OF_DUELING_3, 1, ItemID.SLAYER_ICY_WATER, 5, ItemID.POH_TABLET_VARROCKTELEPORT, 2);
		Set<Integer> dropped = new HashSet<>(Arrays.asList(ItemID.RING_OF_DUELING_3,
			ItemID.SLAYER_ICY_WATER, ItemID.POH_TABLET_VARROCKTELEPORT));
		assertTrue(supplies.update(SupplyTrackerTest.obs(), true, false, dropped).isEmpty());
	}

	@Test
	public void existingCategoriesAreUnchanged()
	{
		SupplyTracker.Usage usage = total(new int[]{ItemID.SHARK, 5, ItemID.RING_OF_DUELING_8, 1},
			new int[]{ItemID.SHARK, 4, ItemID.RING_OF_DUELING_8, 1});
		assertEquals(1, usage.getUsed().get(ItemID.SHARK));
		assertEquals(1, usage.getUsed().size());
		assertNull(usage.getDoses().get(ItemID.SHARK));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Which ticks and dropped (or stored) items the plugin leaves out of supply counting.
 */
public class SupplyExclusionsTest
{
	private static final int SHARK = 385;
	private static final int ARROW = 890;
	private static final int RUNE_POUCH = 12791;
	/** Not an excluded interface. */
	private static final int OTHER_INTERFACE = 149;

	private final SupplyExclusions exclusions = new SupplyExclusions();

	@Test
	public void nothingIsExcludedByDefault()
	{
		exclusions.beginTick(0, false);
		assertFalse(exclusions.isTickExcluded(0));
		assertFalse(exclusions.isTickExcluded(1_000));
		assertTrue(exclusions.droppedItems().isEmpty());
	}

	@Test
	public void excludedInterfacesAreRecognised()
	{
		for (int group : SupplyExclusions.excludedInterfaces())
		{
			assertTrue(SupplyExclusions.isExcludedInterface(group));
		}
		assertTrue(SupplyExclusions.isExcludedInterface(InterfaceID.BANKMAIN));
		assertTrue(SupplyExclusions.isExcludedInterface(InterfaceID.DEATH_COFFER));
		assertFalse(SupplyExclusions.isExcludedInterface(OTHER_INTERFACE));
		assertEquals(11, SupplyExclusions.excludedInterfaces().length);
	}

	@Test
	public void openInterfaceExcludesItsTickAndTwoMore()
	{
		exclusions.beginTick(100, true);
		assertTrue("+0", exclusions.isTickExcluded(100));
		exclusions.beginTick(101, false);
		assertTrue("+1", exclusions.isTickExcluded(101));
		exclusions.beginTick(102, false);
		assertTrue("+2", exclusions.isTickExcluded(102));
		exclusions.beginTick(103, false);
		assertFalse("+3", exclusions.isTickExcluded(103));
	}

	@Test
	public void interfaceStillOpenKeepsExtendingTheWindow()
	{
		for (int tick = 100; tick <= 110; tick++)
		{
			exclusions.beginTick(tick, true);
			assertTrue(exclusions.isTickExcluded(tick));
		}
		exclusions.beginTick(112, false);
		assertTrue("2 ticks after it was last open", exclusions.isTickExcluded(112));
		exclusions.beginTick(113, false);
		assertFalse(exclusions.isTickExcluded(113));
	}

	@Test
	public void widgetLoadedAndClosedMarkTheTick()
	{
		// Opened and closed between two ticks: never seen open by beginTick.
		exclusions.interfaceChanged(InterfaceID.BANKMAIN, 200);
		exclusions.beginTick(200, false);
		assertTrue(exclusions.isTickExcluded(200));
		assertTrue(exclusions.isTickExcluded(202));
		assertFalse(exclusions.isTickExcluded(203));

		exclusions.interfaceChanged(InterfaceID.SHOPMAIN, 300);
		assertTrue(exclusions.isTickExcluded(302));
		assertFalse(exclusions.isTickExcluded(303));
	}

	@Test
	public void otherInterfacesDoNotExclude()
	{
		exclusions.interfaceChanged(OTHER_INTERFACE, 200);
		assertFalse(exclusions.isTickExcluded(200));
	}

	@Test
	public void dropWindowCoversTwoTicksThenIsPruned()
	{
		exclusions.dropClicked(SHARK, false, 50);
		exclusions.beginTick(50, false);
		assertEquals("+0", Collections.singleton(SHARK), exclusions.droppedItems());
		assertFalse("a drop alone does not exclude the tick", exclusions.isTickExcluded(50));
		exclusions.beginTick(52, false);
		assertEquals("+2", Collections.singleton(SHARK), exclusions.droppedItems());
		exclusions.beginTick(53, false);
		assertTrue("+3: pruned", exclusions.droppedItems().isEmpty());
	}

	@Test
	public void dropsArePrunedPerItem()
	{
		exclusions.dropClicked(SHARK, false, 50);
		exclusions.dropClicked(ARROW, false, 52);
		exclusions.beginTick(53, false);
		assertEquals(Collections.singleton(ARROW), exclusions.droppedItems());
		// A repeated drop moves the item's window forward.
		exclusions.dropClicked(ARROW, false, 54);
		exclusions.beginTick(56, false);
		assertEquals(Collections.singleton(ARROW), exclusions.droppedItems());
		exclusions.beginTick(57, false);
		assertTrue(exclusions.droppedItems().isEmpty());
	}

	@Test
	public void dropFromALaterTickIsPruned()
	{
		// The tick count went backwards (should it ever restart; RuneLite 1.13.4's keeps counting).
		exclusions.dropClicked(SHARK, false, 500);
		exclusions.beginTick(10, false);
		assertTrue(exclusions.droppedItems().isEmpty());
	}

	@Test
	public void droppedItemsIsACopy()
	{
		exclusions.dropClicked(SHARK, false, 50);
		exclusions.beginTick(50, false);
		exclusions.droppedItems().clear();
		assertEquals(Collections.singleton(SHARK), exclusions.droppedItems());
	}

	@Test
	public void aScrollStoredInTheMasterScrollBookIsLeftOutLikeADrop()
	{
		// The plugin passes the target item twice (entry and widget) and the selected item.
		exclusions.useClicked(new int[]{ItemID.BOOKOFSCROLLS_EMPTY, ItemID.BOOKOFSCROLLS_EMPTY,
			ItemID.TELEPORTSCROLL_ZULANDRA}, 80);
		exclusions.beginTick(80, false);
		assertEquals(Collections.singleton(ItemID.TELEPORTSCROLL_ZULANDRA), exclusions.droppedItems());
		assertFalse("the tick itself still counts", exclusions.isTickExcluded(80));
		exclusions.beginTick(83, false);
		assertTrue("+3: pruned", exclusions.droppedItems().isEmpty());

		// The book used on a scroll, a filled book.
		exclusions.useClicked(new int[]{ItemID.TELEPORTSCROLL_CERBERUS, ItemID.TELEPORTSCROLL_CERBERUS,
			ItemID.BOOKOFSCROLLS_CHARGED}, 90);
		exclusions.beginTick(90, false);
		assertEquals(Collections.singleton(ItemID.TELEPORTSCROLL_CERBERUS), exclusions.droppedItems());
	}

	@Test
	public void otherItemOnItemUsesLeaveNothingOut()
	{
		exclusions.useClicked(new int[]{SHARK, SHARK, ItemID.BOOKOFSCROLLS_CHARGED}, 80);
		exclusions.useClicked(new int[]{ItemID.TELEPORTSCROLL_ZULANDRA, ItemID.TELEPORTSCROLL_ZULANDRA, SHARK}, 80);
		exclusions.useClicked(new int[]{ItemID.POH_TABLET_VARROCKTELEPORT, -1, ItemID.BOOKOFSCROLLS_CHARGED}, 80);
		exclusions.useClicked(null, 80);
		exclusions.beginTick(80, false);
		assertTrue(exclusions.droppedItems().isEmpty());
	}

	@Test
	public void runePouchDropExcludesTheWholeTick()
	{
		exclusions.dropClicked(RUNE_POUCH, true, 70);
		exclusions.beginTick(70, false);
		assertTrue(exclusions.isTickExcluded(70));
		assertTrue(exclusions.droppedItems().contains(RUNE_POUCH));
		assertTrue("+2", exclusions.isTickExcluded(72));
		assertFalse("+3", exclusions.isTickExcluded(73));
	}

	@Test
	public void deathExcludesTenTicks()
	{
		exclusions.playerDied(1_000);
		assertTrue("+0", exclusions.isTickExcluded(1_000));
		assertTrue("+3", exclusions.isTickExcluded(1_003));
		assertTrue("+10", exclusions.isTickExcluded(1_010));
		assertFalse("+11", exclusions.isTickExcluded(1_011));
	}

	@Test
	public void resetForgetsEverything()
	{
		exclusions.beginTick(10, true);
		exclusions.dropClicked(SHARK, false, 10);
		exclusions.playerDied(10);
		exclusions.reset();
		assertFalse(exclusions.isTickExcluded(10));
		assertTrue(exclusions.droppedItems().isEmpty());
		// After a reset the tick count may restart at a low value; nothing is excluded.
		assertFalse(exclusions.isTickExcluded(0));
	}

	@Test
	public void anInterfaceWindowFromALaterTickExcludesNothing()
	{
		// a window recorded before the tick count restarted must not cover every tick until it catches up.
		exclusions.interfaceChanged(InterfaceID.BANKMAIN, 5_000);
		exclusions.beginTick(10, false);
		assertFalse(exclusions.isTickExcluded(10));
		assertFalse(exclusions.isTickExcluded(4_999));
		assertTrue("the window itself still applies", exclusions.isTickExcluded(5_000));
		assertNull(exclusions.exclusionReason(10));
	}

	@Test
	public void aRunePouchDropOrDeathFromALaterTickExcludesNothing()
	{
		exclusions.dropClicked(RUNE_POUCH, true, 5_000);
		exclusions.playerDied(6_000);
		exclusions.beginTick(10, false);
		assertFalse(exclusions.isTickExcluded(10));
		assertFalse(exclusions.isTickExcluded(5_999));
		assertTrue(exclusions.isTickExcluded(6_005));
	}

	@Test
	public void windowsFarApartDoNotOverflow()
	{
		exclusions.playerDied(Integer.MIN_VALUE / 2 + 1);
		exclusions.interfaceChanged(InterfaceID.BANKMAIN, Integer.MIN_VALUE / 2 + 1);
		assertFalse(exclusions.isTickExcluded(Integer.MAX_VALUE));
	}

	@Test
	public void theReasonSaysWhyATickIsExcluded()
	{
		exclusions.beginTick(100, false);
		assertNull("not excluded", exclusions.exclusionReason(100));

		exclusions.beginTick(101, true);
		assertEquals("an excluded interface was open, opened or closed (or a rune pouch dropped) on tick 101",
			exclusions.exclusionReason(102));

		exclusions.playerDied(200);
		assertEquals("the local player died on tick 200", exclusions.exclusionReason(205));
		assertNull(exclusions.exclusionReason(211));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link SupplyReader}: how an item definition is classified for supply counting, and which containers are read.
 * The client and item manager are plain Mockito mocks; the counting rules themselves are {@link SupplyTrackerTest}'s.
 */
public class SupplyReaderTest
{
	private static final String[] WIELD = {null, "Wield", null, null, "Drop"};
	private static final String[] NONE = {null, null, null, null, "Drop"};
	private static final int FIRE_RUNE = 554;
	private static final int ODD_POUCH_RUNE = 30000;
	private static final int BOLTS = 9144;
	private static final int DARTS = 811;
	private static final int SWORD = 1277;

	private Client client;
	private ItemManager itemManager;
	private SupplyReader reader;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		itemManager = mock(ItemManager.class);
		reader = new SupplyReader(client, itemManager);
	}

	private ItemComposition item(int id, String name, String[] actions, boolean stackable)
	{
		final ItemComposition comp = mock(ItemComposition.class);
		when(comp.getName()).thenReturn(name);
		when(comp.getNote()).thenReturn(-1);
		when(comp.getPlaceholderTemplateId()).thenReturn(-1);
		when(comp.getInventoryActions()).thenReturn(actions);
		when(comp.isStackable()).thenReturn(stackable);
		when(itemManager.getItemComposition(id)).thenReturn(comp);
		return comp;
	}

	private void stats(int id, EquipmentInventorySlot slot)
	{
		when(itemManager.getItemStats(id)).thenReturn(new ItemStats(true, 0, 0,
			ItemEquipmentStats.builder().slot(slot.getSlotIdx()).build()));
	}

	private EnumComposition runeEnum(int... runeIds)
	{
		final EnumComposition runes = mock(EnumComposition.class);
		when(runes.getIntVals()).thenReturn(runeIds);
		when(client.getEnum(EnumID.RUNEPOUCH_RUNE)).thenReturn(runes);
		return runes;
	}

	private static SupplyTracker.Category category(SupplyTracker.ItemInfo info)
	{
		return info.getCategory();
	}

	@Test
	public void notedItemsAndPlaceholdersAreNeverSupplies()
	{
		when(item(386, "Shark", NONE, false).getNote()).thenReturn(799);
		when(item(14401, "Shark", NONE, false).getPlaceholderTemplateId()).thenReturn(385);

		assertSame(SupplyTracker.ItemInfo.OTHER, reader.classifyItem(386));
		assertSame(SupplyTracker.ItemInfo.OTHER, reader.classifyItem(14401));
	}

	@Test
	public void runesComeFromThePouchEnumOrTheName()
	{
		runeEnum(0, ODD_POUCH_RUNE);
		item(ODD_POUCH_RUNE, "Odd thing", NONE, true);
		item(FIRE_RUNE, "Fire rune", NONE, true);
		item(SWORD, "Bronze sword", NONE, false);

		assertEquals(SupplyTracker.Category.RUNE, category(reader.classifyItem(ODD_POUCH_RUNE)));
		assertEquals(SupplyTracker.Category.RUNE, category(reader.classifyItem(FIRE_RUNE)));
		assertEquals(SupplyTracker.Category.OTHER, category(reader.classifyItem(SWORD)));
	}

	@Test
	public void runePouchIdsAreCachedOnceLoadedAndReloadedAfterReset()
	{
		runeEnum(FIRE_RUNE);
		item(FIRE_RUNE, "Fire rune", NONE, true);

		reader.classifyItem(FIRE_RUNE);
		reader.classifyItem(FIRE_RUNE);
		verify(client, times(1)).getEnum(EnumID.RUNEPOUCH_RUNE);

		reader.reset();
		reader.classifyItem(FIRE_RUNE);
		verify(client, times(2)).getEnum(EnumID.RUNEPOUCH_RUNE);
	}

	@Test
	public void anUnavailablePouchEnumIsRetried()
	{
		item(FIRE_RUNE, "Fire rune", NONE, true);

		reader.classifyItem(FIRE_RUNE);
		reader.classifyItem(FIRE_RUNE);
		verify(client, times(2)).getEnum(EnumID.RUNEPOUCH_RUNE);
	}

	@Test
	public void ammoIsTheAmmoSlotOrAStackableWeapon()
	{
		item(BOLTS, "Steel bolts", WIELD, true);
		stats(BOLTS, EquipmentInventorySlot.AMMO);
		item(DARTS, "Rune dart", WIELD, true);
		stats(DARTS, EquipmentInventorySlot.WEAPON);
		item(SWORD, "Bronze sword", WIELD, false);
		stats(SWORD, EquipmentInventorySlot.WEAPON);

		assertEquals(SupplyTracker.Category.AMMO, category(reader.classifyItem(BOLTS)));
		assertEquals(SupplyTracker.Category.AMMO, category(reader.classifyItem(DARTS)));
		assertEquals(SupplyTracker.Category.OTHER, category(reader.classifyItem(SWORD)));
	}

	@Test
	public void aWieldableItemWithoutStatsYetIsLeftForLater()
	{
		item(DARTS, "Rune dart", WIELD, true);

		assertNull(reader.classifyItem(DARTS));
	}

	@Test
	public void aMembersItemSeenOnAFreeWorldIsLeftForLater()
	{
		// on a free world the game appends " (Members)" to a members item's name, so it wouldn't read as a potion.
		final String[] drink = {"Drink", null, null, "Empty", "Drop"};
		final ItemComposition prayer = item(ItemID._4DOSEPRAYERRESTORE, "Prayer potion(4) (Members)", drink, false);
		item(ItemID.BLOODRUNE, "Blood rune (Members)", NONE, true);
		item(ItemID.SLAYER_BAG_OF_SALT, "Bag of salt (Members)", NONE, true);

		assertNull(reader.classifyItem(ItemID._4DOSEPRAYERRESTORE));
		assertNull(reader.classifyItem(ItemID.BLOODRUNE));
		assertEquals("decided by id alone", SupplyTracker.Category.SLAYER_CONSUMABLE,
			category(reader.classifyItem(ItemID.SLAYER_BAG_OF_SALT)));

		// After a hop to a members world the real definition shows.
		when(prayer.getName()).thenReturn("Prayer potion(4)");
		final SupplyTracker.ItemInfo info = reader.classifyItem(ItemID._4DOSEPRAYERRESTORE);
		assertEquals(SupplyTracker.Category.POTION, category(info));
		assertEquals("Prayer potion", info.getFamily());
		assertEquals(4, info.getDoses());
	}

	@Test
	public void cannonballsAndIdTableItemsNeedNoItemStats()
	{
		item(SupplyTracker.CANNONBALL, "Cannonball", NONE, true);
		item(ItemID.PLAIN_PIZZA, "Plain pizza", new String[]{"Eat", null, null, null, "Drop"}, false);

