	@Test
	public void whatCountsAndItsShortName()
	{
		assertEquals(SupplyRunway.Kind.PRAYER, SupplyRunway.kind(SupplyTracker.Category.POTION, "Prayer potion", 1));
		assertEquals(SupplyRunway.Kind.RESTORES, SupplyRunway.kind(SupplyTracker.Category.POTION, "Super restore", 1));
		assertEquals(SupplyRunway.Kind.RESTORES, SupplyRunway.kind(SupplyTracker.Category.POTION,
			"Blighted super restore", 1));
		assertEquals(SupplyRunway.Kind.RESTORES, SupplyRunway.kind(SupplyTracker.Category.POTION, "Sanfew serum", 1));
		assertNull(SupplyRunway.kind(SupplyTracker.Category.POTION, "Super combat potion", 1));
		assertNull(SupplyRunway.kind(SupplyTracker.Category.POTION, "Prayer regeneration potion", 1));
		assertEquals(SupplyRunway.Kind.FOOD, SupplyRunway.kind(SupplyTracker.Category.FOOD, null, SHARK));
		assertEquals(SupplyRunway.Kind.CANNONBALLS, SupplyRunway.kind(SupplyTracker.Category.CANNONBALL, null, 2));
		assertEquals(SupplyRunway.Kind.RUNES, SupplyRunway.kind(SupplyTracker.Category.RUNE, null, DEATH_RUNE));
		assertEquals(SupplyRunway.Kind.AMMO, SupplyRunway.kind(SupplyTracker.Category.AMMO, null, ADAMANT_ARROW));
		assertEquals(SupplyRunway.Kind.DARTS, SupplyRunway.kind(SupplyTracker.Category.AMMO, null,
			ItemID.AMETHYST_DART));
		assertNull(SupplyRunway.kind(SupplyTracker.Category.TELEPORT_TABLET, null, 1));
		assertNull(SupplyRunway.kind(SupplyTracker.Category.CHARGES, "charges:1712", GLORY_4));
		assertNull(SupplyRunway.kind(SupplyTracker.Category.SLAYER_CONSUMABLE, null, 1));
		assertNull(SupplyRunway.kind(null, null, 1));

		List<String> names = Arrays.asList("Prayer", "Restores", "Food", "Cannonballs", "Runes", "Ammo", "Darts",
			"Scales");
		for (SupplyRunway.Kind kind : SupplyRunway.Kind.values())
		{
			assertEquals(names.get(kind.ordinal()), kind.getShortName());
		}
	}

	@Test
	public void aWornBlowpipesDartsAndScalesCountOnceItWasChecked()
	{
		SupplyRunway.Supply spareDarts = new SupplyRunway.Supply(SupplyTracker.itemKey(ItemID.AMETHYST_DART),
			ItemID.AMETHYST_DART, SupplyRunway.Kind.DARTS, 100);
		List<SupplyRunway.Supply> carried = Arrays.asList(sharks(10), spareDarts);
		BlowpipeContents contents = new BlowpipeContents();

		// Not checked: neither darts nor scales count, as the blowpipe could hold anything.
		List<SupplyRunway.Supply> unknown = SupplyRunway.withBlowpipe(carried, true, contents, 5_000);
		assertEquals(Collections.singletonList(SupplyRunway.Kind.FOOD), kinds(unknown));
		// Without a blowpipe worn, thrown darts count as they are.
		assertEquals(carried, SupplyRunway.withBlowpipe(carried, false, contents, 5_000));

		contents.messageSeen(new BlowpipeMessage.Darts(true, ItemID.AMETHYST_DART, 1_200, 8_000));
		List<SupplyRunway.Supply> known = SupplyRunway.withBlowpipe(carried, true, contents, 5_000);
		assertEquals(Arrays.asList(SupplyRunway.Kind.FOOD, SupplyRunway.Kind.DARTS, SupplyRunway.Kind.SCALES),
			kinds(known));
		assertEquals("the spare darts and the blowpipe's", 1_300, known.get(1).getAmount());
		assertEquals("the blowpipe's scales and the loose ones", 13_000, known.get(2).getAmount());
		assertEquals(SupplyRunway.ZULRAH_SCALES, known.get(2).getItemId());

		// Without spare darts the blowpipe's still count.
		List<SupplyRunway.Supply> onlyInside = SupplyRunway.withBlowpipe(Collections.singletonList(sharks(10)), true,
			contents, 0);
		assertEquals(1_200, onlyInside.get(1).getAmount());
		assertEquals(SupplyTracker.itemKey(ItemID.AMETHYST_DART), onlyInside.get(1).getKey());
	}

	private static List<SupplyRunway.Kind> kinds(List<SupplyRunway.Supply> supplies)
	{
		List<SupplyRunway.Kind> kinds = new java.util.ArrayList<>();
		for (SupplyRunway.Supply supply : supplies)
		{
			kinds.add(supply.getKind());
		}
		return kinds;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

/**
 * The pure per-tick supplies diff: categories, potion doses, container moves netting to zero, and exclusions.
 */
public class SupplyTrackerTest
{
	static final int SHARK = 385;
	static final int JUG_OF_WINE = 1993;
	static final int PRAYER_4 = 2434;
	static final int PRAYER_3 = 139;
	static final int PRAYER_2 = 141;
	static final int PRAYER_1 = 143;
	static final int SUPER_COMBAT_3 = 12697;
	static final int SUPER_COMBAT_2 = 12699;
	static final int VIAL = 229;
	static final int NATURE_RUNE = 561;
	static final int DEATH_RUNE = 560;
	static final int RUNE_POUCH = 12791;
	static final int ADAMANT_ARROW = 890;
	static final int BONES = 526;
	static final int GLORY_4 = 1712;

	private static final String[] EAT = {"Eat", null, null, null, "Drop"};
	private static final String[] DRINK = {"Drink", null, null, "Empty", "Drop"};
	private static final String[] NONE = {null, null, null, null, "Drop"};

	/** Test item definitions, classified with the production rules. */
	static final SupplyTracker.Classifier CLASSIFIER = id ->
	{
		switch (id)
		{
			case SHARK:
				return SupplyTracker.classify("Shark", EAT, false, false, false);
			case JUG_OF_WINE:
				return SupplyTracker.classify("Jug of wine", DRINK, false, false, false);
			case PRAYER_4:
				return SupplyTracker.classify("Prayer potion(4)", DRINK, false, false, false);
			case PRAYER_3:
				return SupplyTracker.classify("Prayer potion(3)", DRINK, false, false, false);
			case PRAYER_2:
				return SupplyTracker.classify("Prayer potion(2)", DRINK, false, false, false);
			case PRAYER_1:
				return SupplyTracker.classify("Prayer potion(1)", DRINK, false, false, false);
			case SUPER_COMBAT_3:
				return SupplyTracker.classify("Super combat potion(3)", DRINK, false, false, false);
			case SUPER_COMBAT_2:
				return SupplyTracker.classify("Super combat potion(2)", DRINK, false, false, false);
			case NATURE_RUNE:
				return SupplyTracker.classify("Nature rune", NONE, true, false, false);
			case DEATH_RUNE:
				return SupplyTracker.classify("Death rune", NONE, true, false, false);
			case ADAMANT_ARROW:
				return SupplyTracker.classify("Adamant arrow", NONE, false, true, false);
			case SupplyTracker.CANNONBALL:
				return SupplyTracker.classify("Cannonball", NONE, false, false, true);
			case SupplyTracker.GRANITE_CANNONBALL:
				return SupplyTracker.classify("Granite cannonball", NONE, false, false, true);
			case GLORY_4:
				return SupplyTracker.classify("Amulet of glory(4)", new String[]{null, null, "Rub", null, "Drop"}, false, false, false);
			default:
				// Vials, bones, the rune pouch and anything else: not a supply.
				return SupplyTracker.classify("Other", NONE, false, false, false);
		}
	};

	private SupplyTracker supplies;

	@Before
	public void setUp()
	{
		supplies = new SupplyTracker(CLASSIFIER);
	}

	static SupplyTracker.Observation obs(int... idQty)
	{
		SupplyTracker.Observation o = new SupplyTracker.Observation();
		for (int i = 0; i < idQty.length; i += 2)
		{
			o.add(idQty[i], idQty[i + 1]);
		}
		return o;
	}

	private SupplyTracker.Usage running(SupplyTracker.Observation o)
	{
		return supplies.update(o, true, false, Collections.emptySet());
	}

	private static Set<Integer> ids(int... ids)
	{
		Set<Integer> set = new HashSet<>();
		for (int id : ids)
		{
			set.add(id);
		}
		return set;
	}

	// ---- Classification ----

	@Test
	public void classifiesByNameActionsAndFlags()
	{
		SupplyTracker.ItemInfo prayer = CLASSIFIER.classify(PRAYER_3);
		assertEquals(SupplyTracker.Category.POTION, prayer.getCategory());
		assertEquals("Prayer potion", prayer.getFamily());
		assertEquals(3, prayer.getDoses());
		assertEquals(SupplyTracker.Category.FOOD, CLASSIFIER.classify(SHARK).getCategory());
		assertEquals("a drink without doses is food", SupplyTracker.Category.FOOD, CLASSIFIER.classify(JUG_OF_WINE).getCategory());
		assertEquals("charged jewellery is not a potion", SupplyTracker.Category.OTHER, CLASSIFIER.classify(GLORY_4).getCategory());
		assertEquals(SupplyTracker.Category.OTHER, SupplyTracker.classify("Prayer potion(4)", null, false, false, false).getCategory());
		assertEquals(SupplyTracker.Category.RUNE, CLASSIFIER.classify(NATURE_RUNE).getCategory());
		assertEquals(SupplyTracker.Category.AMMO, CLASSIFIER.classify(ADAMANT_ARROW).getCategory());
		assertEquals(SupplyTracker.Category.CANNONBALL, CLASSIFIER.classify(SupplyTracker.CANNONBALL).getCategory());
		assertEquals(SupplyTracker.Category.OTHER, CLASSIFIER.classify(BONES).getCategory());
		assertEquals("flags take precedence", SupplyTracker.Category.CANNONBALL,
			SupplyTracker.classify("Odd(4)", DRINK, true, true, true).getCategory());
	}

	// ---- Baseline ----

	@Test
	public void firstUpdateOnlyTakesABaseline()
	{
		assertFalse(supplies.hasBaseline());
		assertTrue(running(obs(SHARK, 10)).isEmpty());
		assertTrue(supplies.hasBaseline());
		assertEquals(1, running(obs(SHARK, 9)).getUsed().get(SHARK));
	}

	@Test
	public void resetForgetsTheBaseline()
	{
		running(obs(SHARK, 10));
		supplies.reset();
		assertTrue("fresh baseline after reset", running(obs(SHARK, 2)).isEmpty());
		assertEquals(1, running(obs(SHARK, 1)).getUsed().get(SHARK));
	}

	@Test
	public void nothingCountsWhileNotRunningButTheBaselineMoves()
	{
		running(obs(SHARK, 10));
		assertTrue(supplies.update(obs(SHARK, 5), false, false, Collections.emptySet()).isEmpty());
		// Resuming: only what changes from the paused tick on counts.
		assertEquals(1, running(obs(SHARK, 4)).getUsed().get(SHARK));
	}

	// ---- Food ----

	@Test
	public void foodEatenIsCountedAndIncreasesAreIgnored()
	{
		running(obs(SHARK, 10, JUG_OF_WINE, 2, BONES, 5));
		SupplyTracker.Usage usage = running(obs(SHARK, 9, JUG_OF_WINE, 1, BONES, 2));
		assertEquals(1, usage.getUsed().get(SHARK));
		assertEquals(1, usage.getUsed().get(JUG_OF_WINE));
		assertEquals("buried bones are not a supply", 0, usage.getUsed().get(BONES));
		assertTrue("no doses for food", usage.getDoses().isEmpty());

		assertTrue("loot pickup", running(obs(SHARK, 12, JUG_OF_WINE, 1)).isEmpty());
		assertEquals(3, running(obs(SHARK, 9, JUG_OF_WINE, 1)).getUsed().get(SHARK));
	}

	// ---- Potions ----

	@Test
	public void potionDrinksCountDosesUnderTheHighestDoseVariant()
	{
		running(obs(PRAYER_4, 2));
		SupplyTracker.Usage usage = running(obs(PRAYER_4, 1, PRAYER_3, 1));
		assertEquals("one dose", 1, usage.getUsed().get(PRAYER_4));
		assertEquals(Integer.valueOf(4), usage.getDoses().get(PRAYER_4));
		assertEquals(1, usage.getUsed().size());

		running(obs(PRAYER_4, 1, PRAYER_2, 1));
		running(obs(PRAYER_4, 1, PRAYER_1, 1));
		usage = running(obs(PRAYER_4, 1, VIAL, 1));
		assertEquals("the last dose leaves a vial", 1, usage.getUsed().get(PRAYER_4));
		assertEquals(0, usage.getUsed().get(VIAL));
	}

	@Test
	public void decantingAndCombiningNetToZero()
	{
		running(obs(PRAYER_3, 1, PRAYER_1, 1));
		assertTrue("3 + 1 into a 4 and a vial", running(obs(PRAYER_4, 1, VIAL, 1)).isEmpty());
		assertTrue("4 into 2 + 2", running(obs(PRAYER_2, 2, VIAL, 0)).isEmpty());
	}

	@Test
	public void familyIsKeyedByTheHighestDoseSeenSoFar()
	{
		running(obs(SUPER_COMBAT_3, 1));
		SupplyTracker.Usage usage = running(obs(SUPER_COMBAT_2, 1));
		assertEquals(1, usage.getUsed().get(SUPER_COMBAT_3));
		assertEquals(Integer.valueOf(3), usage.getDoses().get(SUPER_COMBAT_3));
	}

	@Test
	public void differentPotionFamiliesAreSeparate()
	{
		running(obs(PRAYER_4, 1, SUPER_COMBAT_3, 1));
		SupplyTracker.Usage usage = running(obs(PRAYER_3, 1, SUPER_COMBAT_2, 1));
		assertEquals(1, usage.getUsed().get(PRAYER_4));
		assertEquals(1, usage.getUsed().get(SUPER_COMBAT_3));
	}

	// ---- Runes ----

	@Test
	public void runesCastFromInventoryAndPouchAreCounted()
	{
		// Inventory and pouch together: 100 nature runes and 50 death runes in total.
		running(obs(RUNE_POUCH, 1, NATURE_RUNE, 60, NATURE_RUNE, 40, DEATH_RUNE, 50));
		SupplyTracker.Usage usage = running(obs(RUNE_POUCH, 1, NATURE_RUNE, 60, NATURE_RUNE, 39, DEATH_RUNE, 48));
		assertEquals(1, usage.getUsed().get(NATURE_RUNE));
		assertEquals(2, usage.getUsed().get(DEATH_RUNE));
	}

	@Test
	public void movingRunesIntoOrOutOfThePouchNetsToZero()
	{
		// Inventory 100 nature runes, pouch empty.
		running(obs(RUNE_POUCH, 1, NATURE_RUNE, 100));
		// Fill: inventory 0, pouch 100.
		assertTrue(running(obs(RUNE_POUCH, 1).add(NATURE_RUNE, 100)).isEmpty());
		// Partly empty: inventory 30, pouch 70.
		assertTrue(running(obs(RUNE_POUCH, 1, NATURE_RUNE, 30, NATURE_RUNE, 70)).isEmpty());
	}

	// ---- Ammo ----

	@Test
	public void equippingAmmoNetsToZeroAndFiringCounts()
	{
		running(obs(ADAMANT_ARROW, 500));
		assertTrue("equipped from the inventory", running(obs().add(ADAMANT_ARROW, 500)).isEmpty());
		assertEquals(3, running(obs(ADAMANT_ARROW, 497)).getUsed().get(ADAMANT_ARROW));
		assertTrue("unequipped", running(obs(ADAMANT_ARROW, 497)).isEmpty());
	}

	@Test
	public void pickedUpAmmoIsReportedAsReturned()
	{
		running(obs(ADAMANT_ARROW, 500));
		running(obs(ADAMANT_ARROW, 490));
		SupplyTracker.Usage usage = running(obs(ADAMANT_ARROW, 496));
		assertTrue(usage.getUsed().isEmpty());
		assertEquals(6, usage.getReturned().get(ADAMANT_ARROW));
	}

	@Test
	public void foodPickupIsNotReturned()
	{
		running(obs(SHARK, 5));
		assertTrue(running(obs(SHARK, 6)).isEmpty());
	}

	// ---- Cannon ----

	@Test
	public void cannonLoadFireAndPickUp()
	{
		running(obs(SupplyTracker.CANNONBALL, 100));
		// Load 30 into the cannon.
		assertTrue("loading", running(obs(SupplyTracker.CANNONBALL, 70).setCannonBalls(30)).isEmpty());
		// Fire 5.
		SupplyTracker.Usage fired = running(obs(SupplyTracker.CANNONBALL, 70).setCannonBalls(25));
		assertEquals(5, fired.getUsed().get(SupplyTracker.CANNONBALL));
		// Pick the cannon up: its 25 go back to the inventory.
		assertTrue("pickup", running(obs(SupplyTracker.CANNONBALL, 95).setCannonBalls(0)).isEmpty());
	}

	@Test
	public void cannonLoadSplitOverTwoTicksIsOffsetByReturn()
	{
		running(obs(SupplyTracker.CANNONBALL, 100));
		SupplyTracker.Usage first = running(obs(SupplyTracker.CANNONBALL, 70));
		assertEquals(30, first.getUsed().get(SupplyTracker.CANNONBALL));
		SupplyTracker.Usage second = running(obs(SupplyTracker.CANNONBALL, 70).setCannonBalls(30));
		assertEquals("the session subtracts this back", 30, second.getReturned().get(SupplyTracker.CANNONBALL));
	}

	@Test
	public void graniteCannonballsAreAttributedFromWhatWasLoaded()
	{
		running(obs(SupplyTracker.GRANITE_CANNONBALL, 50, SupplyTracker.CANNONBALL, 10));
		assertTrue(running(obs(SupplyTracker.GRANITE_CANNONBALL, 20, SupplyTracker.CANNONBALL, 10).setCannonBalls(30)).isEmpty());
		assertEquals(SupplyTracker.GRANITE_CANNONBALL, supplies.getCannonBallId());
		SupplyTracker.Usage fired = running(obs(SupplyTracker.GRANITE_CANNONBALL, 20, SupplyTracker.CANNONBALL, 10).setCannonBalls(28));
		assertEquals(2, fired.getUsed().get(SupplyTracker.GRANITE_CANNONBALL));
		assertEquals(0, fired.getUsed().get(SupplyTracker.CANNONBALL));
	}

	private static final int G = SupplyTracker.GRANITE_CANNONBALL;
	private static final int R = SupplyTracker.CANNONBALL;

	/** Tracking starts with 30 granite cannonballs already loaded: the type is a guess (regular). */
	private void startWithLoadedGraniteCannon()
	{
		running(obs(G, 70).setCannonBalls(30));
		assertEquals("guessed", R, supplies.getCannonBallId());
	}

	@Test
	public void aGraniteCannonLoadedBeforeTrackingIsPickedUpWithoutCountingAnything()
	{
		startWithLoadedGraniteCannon();
		// the pickup returns granite, so the cannon held granite; nothing was used.
		assertTrue("pickup", running(obs(G, 100)).isEmpty());
		assertEquals(G, supplies.getCannonBallId());
	}

	@Test
	public void cannonballsFiredFromAGuessedTypeMoveToTheTypePickedUp()
	{
		startWithLoadedGraniteCannon();
		SupplyTracker.Usage fired = running(obs(G, 70).setCannonBalls(26));
		assertEquals("counted under the guess until the type shows", 4, fired.getUsed().get(R));

		SupplyTracker.Usage pickup = running(obs(G, 96));
		assertEquals(4, pickup.getUsed().get(G));
		assertEquals("offsets the guess", 4, pickup.getReturned().get(R));
		assertEquals(0, pickup.getReturned().get(G));
		assertEquals(0, pickup.getUsed().get(R));
	}

	@Test
	public void aGuessedPickupSplitOverTwoTicksIsCorrectedOnTheSecond()
	{
		startWithLoadedGraniteCannon();
		running(obs(G, 70).setCannonBalls(26));
		// The varp goes to 0 a tick before the cannonballs reach the inventory.
		SupplyTracker.Usage emptied = running(obs(G, 70));
		assertEquals(26, emptied.getUsed().get(R));
		SupplyTracker.Usage arrived = running(obs(G, 96));
		// 4 fired and 26 back: the session nets granite to 4 and regular to 0.
		assertEquals(30, arrived.getUsed().get(G));
		assertEquals(30, arrived.getReturned().get(R));
		assertEquals(26, arrived.getReturned().get(G));
		assertEquals(G, supplies.getCannonBallId());
	}

	@Test
	public void aGuessedTypeIsCorrectedByAFurtherLoadOfTheOtherType()
	{
		startWithLoadedGraniteCannon();
		SupplyTracker.Usage fired = running(obs(G, 70).setCannonBalls(28));
		assertEquals(2, fired.getUsed().get(R));
		SupplyTracker.Usage loaded = running(obs(G, 50).setCannonBalls(48));
		assertEquals(2, loaded.getUsed().get(G));
		assertEquals(2, loaded.getReturned().get(R));
		assertEquals(0, loaded.getUsed().get(R));
		assertTrue("pickup", running(obs(G, 98)).isEmpty());
	}

	@Test
	public void aRightGuessIsKeptAndCountsAsBefore()
	{
		running(obs(R, 70).setCannonBalls(30));
		assertEquals(4, running(obs(R, 70).setCannonBalls(26)).getUsed().get(R));
		assertTrue("pickup", running(obs(R, 96)).isEmpty());
		assertEquals(R, supplies.getCannonBallId());
	}

	@Test
	public void aGuessedCannonEmptiedByFiringKeepsItsCountWhenAnotherTypeIsLoadedLater()
	{
		startWithLoadedGraniteCannon();
		assertEquals(30, running(obs(G, 70)).getUsed().get(R));
		running(obs(G, 70));
		running(obs(G, 70));
		// A new load shows granite, but says nothing about what the emptied cannon held.
		SupplyTracker.Usage loaded = running(obs(G, 40).setCannonBalls(30));
		assertTrue(loaded.isEmpty());
		assertEquals(G, supplies.getCannonBallId());
	}

	@Test
	public void graniteLootedAsARegularGuessedCannonEmptiesDoesNotChangeItsType()
	{
		// a regular load, tracked as a guess, empties without its cannonballs coming back (fired or decayed),
		// and 3 granite cannonballs are looted on that tick: fewer than the load, so they are not its type.
		running(obs(R, 70).setCannonBalls(10));
		SupplyTracker.Usage emptied = running(obs(R, 70, G, 3));
		assertEquals(10, emptied.getUsed().get(R));
		assertEquals("loot is no granite cost", 0, emptied.getUsed().get(G));
		assertEquals(0, emptied.getReturned().get(R));
		assertEquals(R, supplies.getCannonBallId());
		// Nor on the next tick, where the pickup split over two ticks would show.
		assertTrue(running(obs(R, 70, G, 3)).isEmpty());
		assertEquals(R, supplies.getCannonBallId());
		// A later granite load shows the new type, without moving the regular cannonballs already fired.
		assertTrue(running(obs(R, 70, G, 3)).isEmpty());
		assertTrue(running(obs(R, 70).setCannonBalls(3)).isEmpty());
		assertEquals(G, supplies.getCannonBallId());
	}

	@Test
	public void aGraniteLoadLargerThanTheLootStillResolvesOnPickup()
	{
		startWithLoadedGraniteCannon();
		running(obs(G, 70).setCannonBalls(26));
		// Picked up with 3 regular cannonballs looted on the same tick: the 26 granite back win.
		SupplyTracker.Usage pickup = running(obs(G, 96, R, 3));
		assertEquals(G, supplies.getCannonBallId());
		assertEquals(4, pickup.getUsed().get(G));
		// The 4 guessed regular cannonballs offset, plus the 3 looted ones, which return like any cannonball pickup.
		assertEquals(7, pickup.getReturned().get(R));
		assertEquals(0, pickup.getReturned().get(G));
	}

	/** What the {@code usages} net to for {@code itemId}: used minus returned, as a session adds them up. */
	private static long net(int itemId, SupplyTracker.Usage... usages)
	{
		long net = 0;
		for (SupplyTracker.Usage usage : usages)
		{
			net += usage.getUsed().get(itemId) - usage.getReturned().get(itemId);
		}
		return net;
	}

	@Test
	public void aGraniteCannonFiringOnItsPickupTickStillResolves()
	{
		startWithLoadedGraniteCannon();
		SupplyTracker.Usage fired = running(obs(G, 70).setCannonBalls(26));
		// The cannon fires once more on the pickup tick, so only 25 of the 26 it held come back: more than half.
		SupplyTracker.Usage pickup = running(obs(G, 95));
		assertEquals(G, supplies.getCannonBallId());
		assertEquals(5, net(G, fired, pickup));
		assertEquals(0, net(R, fired, pickup));
	}

	@Test
	public void aGraniteCannonFiringBeforeAPickupSplitOverTwoTicksStillResolves()
	{
		startWithLoadedGraniteCannon();
		SupplyTracker.Usage fired = running(obs(G, 70).setCannonBalls(26));
		// The varp goes to 0 after one more shot, a tick before the 25 left reach the inventory.
		SupplyTracker.Usage emptied = running(obs(G, 70));
		SupplyTracker.Usage arrived = running(obs(G, 95));
		assertEquals(G, supplies.getCannonBallId());
		assertEquals(5, net(G, fired, emptied, arrived));
		assertEquals(0, net(R, fired, emptied, arrived));
	}

	@Test
	public void aRightGuessCountsTheShotOnItsPickupTick()
	{
		running(obs(R, 70).setCannonBalls(30));
		SupplyTracker.Usage fired = running(obs(R, 70).setCannonBalls(26));
		SupplyTracker.Usage pickup = running(obs(R, 95));
		assertEquals(R, supplies.getCannonBallId());
		assertEquals(5, net(R, fired, pickup));
		assertEquals(0, net(G, fired, pickup));

		// The same, with the pickup split over two ticks.
		setUp();
		running(obs(R, 70).setCannonBalls(30));
		fired = running(obs(R, 70).setCannonBalls(26));
		SupplyTracker.Usage emptied = running(obs(R, 70));
		SupplyTracker.Usage arrived = running(obs(R, 95));
		assertEquals(R, supplies.getCannonBallId());
		assertEquals(5, net(R, fired, emptied, arrived));
		assertEquals(0, net(G, fired, emptied, arrived));
	}

	@Test
	public void aResetDropsTheGuessedCountSoAnotherSessionIsNotCorrected()
	{
		startWithLoadedGraniteCannon();
		running(obs(G, 70).setCannonBalls(26));
		supplies.reset();
		running(obs(G, 70).setCannonBalls(26));
		SupplyTracker.Usage pickup = running(obs(G, 96));
		assertTrue(pickup.isEmpty());
		assertEquals(G, supplies.getCannonBallId());
	}

	// ---- Exclusions ----

	@Test
	public void droppedItemsAreNotCounted()
	{
		running(obs(SHARK, 10, NATURE_RUNE, 100));
		SupplyTracker.Usage usage = supplies.update(obs(SHARK, 8, NATURE_RUNE, 99), true, false, ids(SHARK));
		assertEquals(0, usage.getUsed().get(SHARK));
		assertEquals("other items still count", 1, usage.getUsed().get(NATURE_RUNE));
		// The baseline moved past the drop.
		assertTrue(running(obs(SHARK, 8, NATURE_RUNE, 99)).isEmpty());
	}

	@Test
	public void ignoredItemsCountNeitherWay()
	{
		running(obs(ADAMANT_ARROW, 500, NATURE_RUNE, 100));
		// Loaded into a weapon: not used.
		SupplyTracker.Usage usage = supplies.update(obs(ADAMANT_ARROW, 400, NATURE_RUNE, 99), true, false,
			Collections.emptySet(), ids(ADAMANT_ARROW));
		assertEquals(0, usage.getUsed().get(ADAMANT_ARROW));
		assertEquals("other items still count", 1, usage.getUsed().get(NATURE_RUNE));
		// Unloaded again: not returned.
		usage = supplies.update(obs(ADAMANT_ARROW, 500, NATURE_RUNE, 99), true, false, Collections.emptySet(),
			ids(ADAMANT_ARROW));
		assertTrue(usage.isEmpty());
		// The baseline moved past both.
		assertTrue(running(obs(ADAMANT_ARROW, 500, NATURE_RUNE, 99)).isEmpty());
	}

	@Test
	public void droppingAPotionExcludesItsFamily()
	{
		running(obs(PRAYER_4, 1, PRAYER_3, 1));
		assertTrue(supplies.update(obs(PRAYER_4, 1), true, false, ids(PRAYER_3)).isEmpty());
	}

	@Test
	public void excludedTicksCountNothingAndMoveTheBaseline()
	{
		running(obs(SHARK, 10, PRAYER_4, 4));
		// Bank open: deposit everything, withdraw fresh supplies.
		assertTrue(supplies.update(obs(SHARK, 2), true, true, Collections.emptySet()).isEmpty());
		assertTrue(supplies.update(obs(SHARK, 20, PRAYER_4, 8), true, true, Collections.emptySet()).isEmpty());
		// After the bank closed only real use counts.
		SupplyTracker.Usage usage = running(obs(SHARK, 19, PRAYER_4, 8));
		assertEquals(1, usage.getUsed().get(SHARK));
		assertEquals(0, usage.getUsed().get(PRAYER_4));
	}

	@Test
	public void usageIsACopy()
	{
		running(obs(SHARK, 10));
		SupplyTracker.Usage usage = running(obs(SHARK, 9));
		usage.getUsed().add(SHARK, 100);
		usage.getDoses().put(SHARK, 4);
		assertEquals(1, usage.getUsed().get(SHARK));
		assertNull(usage.getDoses().get(SHARK));
	}

	@Test
	public void classifierFailureMeansNotASupply()
	{
		Map<Integer, Integer> calls = new HashMap<>();
		SupplyTracker failing = new SupplyTracker(id ->
		{
			calls.merge(id, 1, Integer::sum);
			throw new IllegalStateException("not loaded");
		});
		failing.update(obs(SHARK, 10), true, false, Collections.emptySet());
		assertTrue(failing.update(obs(SHARK, 9), true, false, Collections.emptySet()).isEmpty());
		assertEquals("a failed classification is not cached", Integer.valueOf(2), calls.get(SHARK));
	}

	@Test
	public void unavailableClassificationIsRetriedLater()
	{
		// Item stats load asynchronously: ammo classified before they arrive must be counted once they have.
		final boolean[] loaded = {false};
		SupplyTracker tracker = new SupplyTracker(id -> loaded[0]
			? SupplyTracker.classify("Rune arrow", new String[]{null, "Wield", null, null, "Drop"}, false, true, false)
			: null);
		final int runeArrow = 892;
		tracker.update(obs(runeArrow, 100), true, false, Collections.emptySet());
		assertTrue(tracker.update(obs(runeArrow, 99), true, false, Collections.emptySet()).isEmpty());
		loaded[0] = true;
		// The first tick after the data arrives becomes the item's baseline; use is counted from then on.
		tracker.update(obs(runeArrow, 98), true, false, Collections.emptySet());
		assertEquals(1, tracker.update(obs(runeArrow, 97), true, false, Collections.emptySet())
			.getUsed().get(runeArrow));
	}

	@Test
	public void ammoExcludedBeforeItsDataLoadedIsStillReturnedOnceClassified()
	{
		// darts are left out of a blowpipe-loading tick (or dropped) before their item stats arrive. That must not
		// fix their category as "not a supply", or darts picked up later would never offset the ones thrown.
		final boolean[] loaded = {false};
		SupplyTracker tracker = new SupplyTracker(id -> loaded[0]
			? SupplyTracker.classify("Rune dart", new String[]{null, "Wield", null, null, "Drop"}, false, true, false)
			: null);
		final int runeDart = 811;
		tracker.update(obs(runeDart, 100), true, false, Collections.emptySet());
		tracker.update(obs(runeDart, 100), true, false, Collections.emptySet(), ids(runeDart));
		tracker.update(obs(runeDart, 100), true, false, ids(runeDart));
		loaded[0] = true;
		tracker.update(obs(runeDart, 100), true, false, Collections.emptySet());
		assertEquals(10, tracker.update(obs(runeDart, 90), true, false, Collections.emptySet()).getUsed().get(runeDart));
		assertEquals("picked up", 4, tracker.update(obs(runeDart, 94), true, false, Collections.emptySet())
			.getReturned().get(runeDart));
	}

	@Test
	public void aClassificationIsAskedForAgainUntilItIsKnownAndThenKept()
	{
		// a members item on a free world (or a wieldable item without its stats) has no answer yet; once it has
		// one it is kept, so the classifier is not asked every tick.
		final Map<Integer, Integer> calls = new HashMap<>();
		final boolean[] membersWorld = {false};
		SupplyTracker tracker = new SupplyTracker(id ->
		{
			calls.merge(id, 1, Integer::sum);
			return membersWorld[0] ? CLASSIFIER.classify(id) : null;
		});
		tracker.noteVariants(obs(PRAYER_4, 1));
		tracker.update(obs(PRAYER_4, 1), true, false, Collections.emptySet());
		assertTrue("nothing counted on the free world", tracker.update(obs(PRAYER_3, 1), true, false,
			Collections.emptySet()).isEmpty());
		membersWorld[0] = true;
		tracker.update(obs(PRAYER_4, 1), true, false, Collections.emptySet());
		SupplyTracker.Usage usage = tracker.update(obs(PRAYER_3, 1), true, false, Collections.emptySet());
		assertEquals(1, usage.getUsed().get(PRAYER_4));
		assertEquals(Integer.valueOf(4), usage.getDoses().get(PRAYER_4));
		final int askedBefore = calls.get(PRAYER_4);
		tracker.update(obs(PRAYER_4, 1), true, false, Collections.emptySet());
		assertEquals("kept once known", askedBefore, (int) calls.get(PRAYER_4));
	}
}

package com.shmayvan.slayerledger;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import javax.swing.AbstractButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.text.JTextComponent;

/**
 * Finds Swing components by the name production code gives them ({@link Component#setName}) and reads or drives them
 * the way the player sees and uses them, so tests need no getter per label in the panel. A name is unique within the
 * container a test searches: names inside a reused view ({@link ItemListView}, {@link ItemGridView}) repeat, so
 * search from that view's own named root. Only components in the tree are found: a row the panel has removed (rather
 * than hidden) is not there.
 * Use it on the EDT.
 */
final class SwingLookup
{
	private SwingLookup()
	{
	}

	/** The first component named {@code name} in {@code root}'s tree (depth first, {@code root} included). */
	static Component find(Container root, String name)
	{
		Component found = findOrNull(root, name);
		if (found == null)
		{
			throw new AssertionError("no component named " + name);
		}
		return found;
	}

	/** {@link #find}, cast to {@code type}. */
	static <T> T find(Container root, String name, Class<T> type)
	{
		return type.cast(find(root, name));
	}

	/** The first component named {@code name} in {@code root}'s tree, or {@code null} when none is in it. */
	static Component findOrNull(Container root, String name)
	{
		if (name.equals(root.getName()))
		{
			return root;
		}
		for (Component child : root.getComponents())
		{
			if (name.equals(child.getName()))
			{
				return child;
			}
			if (child instanceof Container)
			{
				Component found = findOrNull((Container) child, name);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	/** Whether a component named {@code name} is in {@code root}'s tree (added, visible or not). */
	static boolean isInTree(Container root, String name)
	{
		return findOrNull(root, name) != null;
	}

	/** {@code parent}'s direct children named {@code name}, in order. */
	static List<Component> children(Container parent, String name)
	{
		List<Component> found = new ArrayList<>();
		for (Component child : parent.getComponents())
		{
			if (name.equals(child.getName()))
			{
				found.add(child);
			}
		}
		return found;
	}

	/** The text a label, button or text field shows. */
	static String text(Component component)
	{
		if (component instanceof JLabel)
		{
			return ((JLabel) component).getText();
		}
		if (component instanceof AbstractButton)
		{
			return ((AbstractButton) component).getText();
		}
		if (component instanceof JTextComponent)
		{
			return ((JTextComponent) component).getText();
		}
		throw new AssertionError("no text on " + component);
	}

	/** The text of the component named {@code name} in {@code root}. */
	static String text(Container root, String name)
	{
		return text(find(root, name));
	}

	/** The tooltip of the component named {@code name} in {@code root}. */
	static String tooltip(Container root, String name)
	{
		return find(root, name, JComponent.class).getToolTipText();
	}

	/** Whether the component named {@code name} in {@code root} is set visible (its own flag, as the panel sets it). */
	static boolean isVisible(Container root, String name)
	{
		return find(root, name).isVisible();
	}

	/**
	 * A line of labels (a panel holding only labels, such as a text on the left and a value on the right): their texts,
	 * left to right, joined by {@code " | "}.
	 */
	static String lineText(Component line)
	{
		StringBuilder sb = new StringBuilder();
		for (Component c : ((Container) line).getComponents())
		{
			if (sb.length() > 0)
			{
				sb.append(" | ");
			}
			sb.append(((JLabel) c).getText());
		}
		return sb.toString();
	}

	/** A left click, as the player does it. */
	static void click(Component component)
	{
		click(component, MouseEvent.BUTTON1, 1);
	}

	/** Sends a mouse click with {@code button} and {@code clickCount} to {@code component}, as Swing would. */
	static void click(Component component, int button, int clickCount)
	{
		component.dispatchEvent(new MouseEvent(component, MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(), 0, 1,
			1, clickCount, false, button));
	}

	/** {@code box}'s choices, in order, each as {@code label} shows it. */
	static <T> List<String> items(JComboBox<T> box, Function<T, String> label)
	{
		List<String> items = new ArrayList<>();
		for (int i = 0; i < box.getItemCount(); i++)
		{
			items.add(label.apply(box.getItemAt(i)));
		}
		return items;
	}

	/** Lays out {@code container} and everything in it; {@code validate()} needs a native peer, which a headless test has not. */
	static void layOut(Container container)
	{
		container.doLayout();
		for (Component child : container.getComponents())
		{
			if (child instanceof Container)
			{
				layOut((Container) child);
			}
		}
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import org.junit.Test;

/** {@link TaskCaves}: which task's cave the player is in (V2 plan 4.1). */
public class TaskCavesTest
{
	@Test
	public void eachTaskHasItsOwnCave()
	{
		assertTrue(TaskCaves.isInside("TzTok-Jad", TaskCaves.FIGHT_CAVES_REGION));
		assertTrue(TaskCaves.isInside("TzKal-Zuk", TaskCaves.INFERNO_REGION));
		assertFalse(TaskCaves.isInside("TzTok-Jad", TaskCaves.INFERNO_REGION));
		assertFalse(TaskCaves.isInside("TzKal-Zuk", TaskCaves.FIGHT_CAVES_REGION));
	}

	@Test
	public void namesIgnoreCapitalsAndOuterSpaces()
	{
		assertTrue(TaskCaves.isInside(" tztok-jad ", TaskCaves.FIGHT_CAVES_REGION));
		assertTrue(TaskCaves.isInside("TZKAL-ZUK", TaskCaves.INFERNO_REGION));
	}

	@Test
	public void otherTasksNoTaskAndNoRegionAreNeverInside()
	{
		assertFalse("the TzHaar task is another task", TaskCaves.isInside("Tzhaar", TaskCaves.FIGHT_CAVES_REGION));
		assertFalse(TaskCaves.isInside("Abyssal demons", TaskCaves.INFERNO_REGION));
		assertFalse(TaskCaves.isInside(null, TaskCaves.FIGHT_CAVES_REGION));
		assertFalse(TaskCaves.isInside("", TaskCaves.FIGHT_CAVES_REGION));
		assertFalse(TaskCaves.isInside("TzTok-Jad", LocationTally.NO_REGION));
		assertFalse(TaskCaves.isInside("TzTok-Jad", 9808));
	}

	/**
	 * The regions are core TimersAndBuffsPlugin's, and the task names core SlayerPlugin's. Both are package-private in
	 * RuneLite, so they are read by reflection here (test code only; the plugin can't), so a RuneLite change fails the
	 * build.
	 */
	@Test
	public void theRegionsAndNamesAreRuneLitesOwn() throws ReflectiveOperationException
	{
		final Class<?> timers = Class.forName("net.runelite.client.plugins.timersandbuffs.TimersAndBuffsPlugin");
		assertEquals(TaskCaves.FIGHT_CAVES_REGION, staticInt(timers, "FIGHT_CAVES_REGION_ID"));
		assertEquals(TaskCaves.INFERNO_REGION, staticInt(timers, "INFERNO_REGION_ID"));

		final Class<?> task = Class.forName("net.runelite.client.plugins.slayer.Task");
		final Method getName = task.getDeclaredMethod("getName");
		getName.setAccessible(true);
		assertEquals(TaskCaves.JAD_TASK, getName.invoke(enumConstant(task, "JAD")));
		assertEquals(TaskCaves.ZUK_TASK, getName.invoke(enumConstant(task, "ZUK")));
	}

	private static int staticInt(Class<?> type, String name) throws ReflectiveOperationException
	{
		final Field field = type.getDeclaredField(name);
		field.setAccessible(true);
		return field.getInt(null);
	}

	private static Object enumConstant(Class<?> type, String name)
	{
		for (Object constant : type.getEnumConstants())
		{
			if (((Enum<?>) constant).name().equals(name))
			{
				return constant;
			}
		}
		throw new AssertionError("no " + name + " in " + type);
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/**
 * The task-complete chat line ({@code DESIGN_PRINCIPLES.md} 5.3): facts first, then {@code Gz.}; the singular and
 * plural forms, an approximate or missing profit, a long name, and the chat message's colours.
 */
public class TaskCompleteMessageTest
{
	@Test
	public void theDesignShape()
	{
		LedgerRecord record = record(true);
		record.setMonster("Dust devils");
		record.setKills(201);
		record.setActiveMillis(61 * 60_000L);
		record.setLootGeValue(500_000L);
		record.setSuppliesGeValue(88_000L);

		assertEquals("Dust devils done: 201 kills in 1 h 1 min, +412K. Gz.",
			TaskCompleteMessage.format(record, LootPriceMode.GE));
		assertEquals("without the Gz when a record line follows", "Dust devils done: 201 kills in 1 h 1 min, +412K.",
			TaskCompleteMessage.format(record, LootPriceMode.GE, HiddenLoot.NONE, false));
	}

	@Test
	public void formatsSummaryUsingSelectedLootPriceMode()
	{
		LedgerRecord record = record(true);
		record.setMonster("Wyrms");
		record.setKills(172);
		record.setActiveMillis(6_012_000);
		record.setLootGeValue(2_500_000L);
		record.setLootHaValue(1_500_000L);
		record.setSuppliesGeValue(400_000L);
		record.setSuperiorsSpawned(3);

		assertEquals("Wyrms done: 172 kills in 1 h 40 min, +2.1M, 3 superiors. Gz.",
			TaskCompleteMessage.format(record, LootPriceMode.GE));
		assertEquals("Wyrms done: 172 kills in 1 h 40 min, +1.1M, 3 superiors. Gz.",
			TaskCompleteMessage.format(record, LootPriceMode.HIGH_ALCH));
	}

	@Test
	public void omitsUnavailableProfitAndSuperiorCount()
	{
		LedgerRecord record = record(true);
		record.setMonster("Wyrms");
		record.setKills(172);
		record.setActiveMillis(6_012_000);

		assertEquals("Wyrms done: 172 kills in 1 h 40 min. Gz.", TaskCompleteMessage.format(record, LootPriceMode.GE));
	}

	@Test
	public void singularForms()
	{
		LedgerRecord record = record(true);
		record.setMonster("Cave kraken");
		record.setKills(1);
		record.setActiveMillis(52 * 60_000L);
		record.setLootGeValue(0L);
		record.setSuppliesGeValue(0L);
		record.setSuperiorsSpawned(1);

		assertEquals("Cave kraken done: 1 kill in 52 min, 0, 1 superior. Gz.",
			TaskCompleteMessage.format(record, LootPriceMode.GE));
	}

	@Test
	public void omitsZeroSuperiorsAndShowsApproximateProfit()
	{
		LedgerRecord record = record(true);
		record.setMonster("Wyrms");
		record.setKills(1_412);
		record.setActiveMillis(6_012_000);
		record.setLootGeValue(100L);
		record.setSuppliesGeValue(0L);
		record.setLootUnpricedItems(1);
		record.setSuperiorsSpawned(0);

		assertEquals("Wyrms done: 1,412 kills in 1 h 40 min, ~+100. Gz.",
			TaskCompleteMessage.format(record, LootPriceMode.GE));
	}

	@Test
	public void putsTheSignAfterTheApproximateMarkForLosses()
	{
		LedgerRecord record = record(true);
		record.setMonster("Wyrms");
		record.setKills(172);
		record.setActiveMillis(6_012_000);
		record.setLootGeValue(100L);
		record.setSuppliesGeValue(600L);
		record.setLootUnpricedItems(1);

		assertEquals("Wyrms done: 172 kills in 1 h 40 min, ~-500. Gz.",
			TaskCompleteMessage.format(record, LootPriceMode.GE));
	}

	@Test
	public void aLongNameStaysWholeOnOneLine()
	{
		LedgerRecord record = record(true);
		record.setMonster("Smoke devils");
		record.setVariant("Thermonuclear smoke devil");
		record.setKills(40);
		record.setActiveMillis(30_000);
		record.setLootGeValue(1_000_000L);
		record.setSuppliesGeValue(0L);

		String line = TaskCompleteMessage.format(record, LootPriceMode.GE);
		assertEquals("Thermonuclear smoke devil done: 40 kills in 1 min, +1M. Gz.", line);
		assertEquals(-1, line.indexOf('\n'));
	}

	@Test
	public void doesNotFormatPartialRecords()
	{
		assertNull(TaskCompleteMessage.format(record(false), LootPriceMode.GE));
		assertNull(TaskCompleteMessage.format(null, LootPriceMode.GE));
	}

	@Test
	public void theChatMessageHighlightsTheHeadAndEscapesTheName()
	{
		LedgerRecord record = record(true);
		record.setMonster("Dust <col=ff0000>devils");
		record.setKills(2);
		record.setActiveMillis(120_000);
		String line = TaskCompleteMessage.format(record, LootPriceMode.GE);

		assertEquals("<colHIGHLIGHT>Dust <lt>col=ff0000<gt>devils done:<colNORMAL> 2 kills in 2 min. Gz.",
			TaskCompleteMessage.chatMessage(record, line));
	}

	private static LedgerRecord record(boolean completed)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCompleted(completed);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.Collections;
import org.junit.Before;
import org.junit.Test;

/**
 * {@link TaskContext} (master, area, points earned and streak) on its own and as the session carries it: taken with the
 * task, filled from later readings of the same task, rewards set on completion only, and through snapshots, restores,
 * records, JSON and the history tooltip.
 */
public class TaskContextTest
{
	private static final int TASK = 42;
	private static final long ACCOUNT = 555L;
	private static final int[] COUNTERS = {100, 2, 0};
	private static final TaskContext KONAR_AT_COVE = TaskContext.assignment(SlayerMaster.KONAR, 12, "Kraken Cove");

	private final Gson gson = new Gson();
	private long now;
	private SessionTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SessionTracker(() -> now);
	}

	private SessionTracker.ObserveResult observe(int remaining, TaskContext assignment, boolean completion)
	{
		return tracker.observe("Kraken", TASK, remaining, 100, assignment, completion);
	}

	// ---- TaskContext ----

	@Test
	public void assignmentKeepsOnlyRealValues()
	{
		assertSame(TaskContext.NONE, TaskContext.assignment(SlayerMaster.NONE, 0, "Ignored"));
		TaskContext noArea = TaskContext.assignment(6, 0, null);
		assertEquals(Integer.valueOf(6), noArea.getMaster());
		assertNull(noArea.getArea());
		assertNull(noArea.getLocation());
		TaskContext unnamed = TaskContext.assignment(SlayerMaster.KONAR, 12, "");
		assertEquals(Integer.valueOf(12), unnamed.getArea());
		assertNull(unnamed.getLocation());
		assertEquals(TaskType.KONAR, KONAR_AT_COVE.type(TASK));
	}

	@Test
	public void fillAssignmentOnlyAddsWhatIsMissing()
	{
		TaskContext unsynced = TaskContext.assignment(SlayerMaster.NONE, 12, null);
		TaskContext filled = unsynced.fillAssignment(KONAR_AT_COVE);
		assertEquals(KONAR_AT_COVE, filled);
		TaskContext other = TaskContext.assignment(6, 30, "Elsewhere");
		assertEquals("known parts are kept", KONAR_AT_COVE, KONAR_AT_COVE.fillAssignment(other));
		assertEquals("a name for another area is not taken", TaskContext.assignment(SlayerMaster.KONAR, 12, null),
			TaskContext.assignment(SlayerMaster.KONAR, 12, null).fillAssignment(other));
		assertEquals(KONAR_AT_COVE, KONAR_AT_COVE.fillAssignment(null));
	}

	// ---- Session ----

	@Test
	public void sessionTakesTheAssignmentWithTheTask()
	{
		observe(50, KONAR_AT_COVE, false);
		assertEquals(KONAR_AT_COVE, tracker.getCurrentContext());
		assertTrue(tracker.startNow(ACCOUNT));
		assertEquals(KONAR_AT_COVE, tracker.summary().getContext());
	}

	@Test
	public void laterReadingsOfTheSameTaskFillTheGaps()
	{
		observe(50, TaskContext.assignment(SlayerMaster.NONE, 0, null), false);
		assertTrue(tracker.startNow(ACCOUNT));
		assertNull(tracker.summary().getContext().getMaster());
		observe(49, KONAR_AT_COVE, false);
		assertEquals(KONAR_AT_COVE, tracker.summary().getContext());
	}

	@Test
	public void noTaskClearsTheCurrentAssignment()
	{
		observe(50, KONAR_AT_COVE, false);
		tracker.observe(null, SessionTracker.NO_CREATURE, 0, false);
		assertSame(TaskContext.NONE, tracker.getCurrentContext());
		observe(50, KONAR_AT_COVE, false);
		tracker.clearCurrentTask();
		assertSame(TaskContext.NONE, tracker.getCurrentContext());
	}

	@Test
	public void rewardsAreSetOnlyOnACompletedSession()
	{
		observe(2, KONAR_AT_COVE, false);
		assertTrue(tracker.startNow(ACCOUNT));
		String id = tracker.getSessionId();
		assertFalse("not completed yet", tracker.setCompletionRewards(id, 18, 43));
		assertEquals(SessionTracker.ObserveResult.COMPLETED, observe(0, TaskContext.NONE, true));
		assertFalse("another session", tracker.setCompletionRewards("other", 18, 43));
		assertTrue(tracker.setCompletionRewards(id, 18, 43));
		assertEquals(Integer.valueOf(18), tracker.summary().getContext().getPointsEarned());
		assertEquals(Integer.valueOf(43), tracker.summary().getContext().getTaskStreak());
		assertEquals("the assignment stays", Integer.valueOf(SlayerMaster.KONAR), tracker.summary().getContext().getMaster());
	}

	@Test
	public void heldCompletionTakesCorrectedPoints()
	{
		observe(2, KONAR_AT_COVE, false);
		assertTrue(tracker.startNow(ACCOUNT));
		String id = tracker.getSessionId();
		observe(0, TaskContext.NONE, true);
		assertTrue(tracker.setCompletionRewards(id, 0, 43));
		assertTrue(tracker.holdCompletion());
		assertTrue(tracker.setCompletionRewards(id, 18, 43));
		SessionTracker.Summary held = tracker.takePendingCompletion();
		assertEquals(Integer.valueOf(18), held.getContext().getPointsEarned());
		assertFalse("saved: nothing left to update", tracker.setCompletionRewards(id, 20, 43));
	}

	@Test
	public void recordHasTheContextAndRewardsOnlyWhenCompleted()
	{
		observe(2, KONAR_AT_COVE, false);
		assertTrue(tracker.startNow(ACCOUNT));
		String id = tracker.getSessionId();
		observe(0, TaskContext.NONE, true);
		tracker.setCompletionRewards(id, 18, 43);
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), false);
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), record.getSlayerMaster());
		assertEquals(Integer.valueOf(12), record.getSlayerArea());
		assertEquals("Kraken Cove", record.getTaskLocation());
		assertEquals(Integer.valueOf(18), record.getPointsEarned());
		assertEquals(Integer.valueOf(43), record.getTaskStreak());

		LedgerRecord copy = gson.fromJson(gson.toJson(record), LedgerRecord.class);
		assertEquals(record, copy);
	}

	@Test
	public void partialRecordHasNoRewards()
	{
		observe(50, KONAR_AT_COVE, false);
		assertTrue(tracker.startNow(ACCOUNT));
		LedgerRecord record = LedgerRecord.fromSummary(tracker.stopAndReset(), true);
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), record.getSlayerMaster());
		assertNull(record.getPointsEarned());
		assertNull(record.getTaskStreak());
	}

	@Test
	public void snapshotRestoresTheAssignment()
	{
		observe(50, KONAR_AT_COVE, false);
		assertTrue(tracker.startNow(ACCOUNT));
		SessionSnapshot snapshot = SessionSnapshot.fromSummary(tracker.stopAndReset(), COUNTERS, now);
		SessionSnapshot copy = gson.fromJson(gson.toJson(snapshot), SessionSnapshot.class);
		assertEquals(Integer.valueOf(SlayerMaster.KONAR), copy.getSlayerMaster());

		SessionTracker restored = new SessionTracker(() -> now);
		// The game's reading lacks the area name this time; the snapshot's is kept.
		restored.observe("Kraken", TASK, 50, 100, TaskContext.assignment(SlayerMaster.KONAR, 12, null), false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, restored.restore(copy, COUNTERS));
		assertEquals(KONAR_AT_COVE, restored.summary().getContext());
		assertEquals(KONAR_AT_COVE, copy.toSummary(SlayerSpots.NONE).getContext());
	}

	@Test
	public void olderSnapshotTakesTheAssignmentFromTheMatchingTask()
	{
		String json = "{\"schemaVersion\":2,\"sessionId\":\"s1\",\"accountHash\":555,\"monster\":\"Kraken\","
			+ "\"creatureId\":42,\"initialAmount\":60,\"originalAmount\":100,\"kills\":10,\"remaining\":50}";
		SessionSnapshot old = gson.fromJson(json, SessionSnapshot.class);
		assertNull(old.getSlayerMaster());
		assertSame(TaskContext.NONE, old.toSummary(SlayerSpots.NONE).getContext());
		observe(50, KONAR_AT_COVE, false);
		assertEquals(SessionTracker.RestoreResult.RESTORED, tracker.restore(old, null));
		assertEquals(KONAR_AT_COVE, tracker.summary().getContext());
	}

	@Test
	public void olderRecordLoadsWithEverythingUnknown()
	{
		String json = "{\"schemaVersion\":2,\"id\":\"x\",\"monster\":\"Kraken\",\"creatureId\":42,\"kills\":4,"
			+ "\"completed\":true}";
		LedgerRecord old = gson.fromJson(json, LedgerRecord.class);
		assertNull(old.getSlayerMaster());
		assertNull(old.getSlayerArea());
		assertNull(old.getTaskLocation());
		assertNull(old.getPointsEarned());
		assertNull(old.getTaskStreak());
		assertEquals("no task context lines", "", LedgerHistory.taskContextTooltip(old));
	}

	// ---- Display ----

	@Test
	public void formatsTheContext()
	{
		assertEquals("Master: Konar", LedgerHistory.formatMaster(SlayerMaster.KONAR));
		assertEquals("Unknown master (14)", LedgerHistory.formatMaster(14));
		assertEquals("Master: -", LedgerHistory.formatMaster(null));
		assertEquals("Master: -", LedgerHistory.formatMaster(SlayerMaster.NONE));
		assertEquals("Type: Konar (Kraken Cove)", LedgerHistory.formatTaskType(TaskType.KONAR, "Kraken Cove"));
		assertEquals("Type: Boss", LedgerHistory.formatTaskType(TaskType.BOSS, null));
		assertEquals("Type: -", LedgerHistory.formatTaskType(null, null));
		assertEquals("Points earned: 18", LedgerHistory.formatPointsEarned(18));
		assertEquals("Points earned: -", LedgerHistory.formatPointsEarned(null));
		assertEquals("Task streak: 43", LedgerHistory.formatTaskStreak(43));
	}

	@Test
	public void historyTooltipListsTheKnownParts()
	{
		LedgerRecord r = new LedgerRecord();
		r.setCreatureId(TASK);
		r.setSlayerMaster(SlayerMaster.KONAR);
		r.setTaskLocation("Kraken <Cove>");
		r.setPointsEarned(18);
		r.setTaskStreak(43);
		assertEquals("<br>Master: Konar<br>Type: Konar (Kraken &lt;Cove&gt;)<br>Points earned: 18<br>Task streak: 43",
			LedgerHistory.taskContextTooltip(r));
		String tooltip = LedgerHistory.historyRowTooltip(r, HistoryPricing.value(r, LootPriceMode.GE,
			Collections.emptyMap()), null, LedgerHistory.NO_VALUE);
		assertTrue(tooltip, tooltip.endsWith("<br>Deaths: -<br>Master: Konar<br>Type: Konar (Kraken &lt;Cove&gt;)"
			+ "<br>Points earned: 18<br>Task streak: 43</html>"));

		LedgerRecord boss = new LedgerRecord();
		boss.setCreatureId(SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 3));
		assertEquals("a boss task without a known master", "<br>Type: Boss", LedgerHistory.taskContextTooltip(boss));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import java.lang.reflect.Method;
import java.time.ZoneId;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/** The task icons of Overall totals: {@link TaskIcons} and the task a By monster group shows the icon of. */
public class TaskIconsTest
{
	private static final ZoneId UTC = ZoneId.of("UTC");

	@Test
	public void aKnownTaskHasItsSlayerGuideIcon()
	{
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_DUSTDEVIL), TaskIcons.itemId("Dust devils"));
		// Matched as TaskStatistics.normalize matches names: case and outer spaces don't matter.
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_DUSTDEVIL), TaskIcons.itemId("  dust DEVILS "));
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_ABERRANTSPECTER), TaskIcons.itemId("Aberrant spectres"));
		// A task without a Slayer-guide picture has the core plugin's other item, a boss task its pet.
		assertEquals(Integer.valueOf(ItemID.DRAGONMASK_BLACK), TaskIcons.itemId("Black dragons"));
		assertEquals(Integer.valueOf(ItemID.SNAKEPET), TaskIcons.itemId("Zulrah"));
	}

	@Test
	public void anUnknownTaskHasNone()
	{
		assertNull(TaskIcons.itemId("Lava strykewyrms"));
		assertNull(TaskIcons.itemId(LedgerHistory.UNKNOWN_MONSTER));
		assertNull(TaskIcons.itemId("Unknown task (12)"));
		assertNull(TaskIcons.itemId(""));
		assertNull(TaskIcons.itemId("   "));
		assertNull(TaskIcons.itemId(null));
		// Group names are no task names: the group's task (OverallTotals.Entry#getTask) is looked up instead.
		assertNull(TaskIcons.itemId("Deviant spectres"));
		assertNull(TaskIcons.itemId("Dust devils" + CannonTasks.SUFFIX));
	}

	@Test
	public void aCatacombsVariantGroupShowsItsTasksIcon()
	{
		LedgerRecord newest = record("Aberrant spectres", 1);
		newest.setVariant("Deviant spectres");
		LedgerRecord older = record("Aberrant spectres", 2);
		older.setVariant("Deviant spectres");

		OverallTotals.Entry group = byMonster(Arrays.asList(newest, older)).get(0);

		assertEquals("Deviant spectres", group.getLabel());
		assertEquals("Aberrant spectres", group.getTask());
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_ABERRANTSPECTER), TaskIcons.itemId(group.getTask()));
	}

	@Test
	public void aCannonGroupShowsItsTasksIcon()
	{
		LedgerRecord cannon = record("Dust devils", 1);
		cannon.setSupplies(Collections.singletonMap(SupplyTracker.CANNONBALL, 200L));
		LedgerRecord granite = record("Fire giants", 2);
		granite.setSupplies(Collections.singletonMap(SupplyTracker.GRANITE_CANNONBALL, 50L));

		List<OverallTotals.Entry> groups = byMonster(Arrays.asList(cannon, granite));

		Map<String, String> tasks = new HashMap<>();
		for (OverallTotals.Entry group : groups)
		{
			tasks.put(group.getLabel(), group.getTask());
		}
		assertEquals("Dust devils", tasks.get("Dust devils (cannon)"));
		assertEquals("Fire giants", tasks.get("Fire giants (cannon)"));
		assertEquals(Integer.valueOf(ItemID.SLAYERGUIDE_DUSTDEVIL), TaskIcons.itemId(tasks.get("Dust devils (cannon)")));
	}

	@Test
	public void aGroupWithoutATaskNameHasNoTaskAndOtherGroupingsHaveNone()
	{
		LedgerRecord unnamed = record(null, 1);
		OverallTotals.Entry group = byMonster(Collections.singletonList(unnamed)).get(0);
		assertNull(group.getTask());
		assertNull(TaskIcons.itemId(group.getTask()));

		LedgerRecord named = record("Dust devils", 1);
		for (OverallTotals.Grouping grouping : Arrays.asList(OverallTotals.Grouping.ALL,
			OverallTotals.Grouping.MASTER, OverallTotals.Grouping.MONTH))
		{
			List<OverallTotals.Entry> entries = TestTotals.summarize(Collections.singletonList(named), grouping,
				LootPriceMode.GE, Collections.emptyMap(), UTC);
			assertNull(grouping.toString(), entries.get(0).getTask());
		}
	}

	@Test
	public void everyTaskOfTheBundledSpotTableHasAnIcon()
	{
		assertTrue(TestSpots.TABLE.isAvailable());
		for (SlayerSpots.Spot spot : TestSpots.TABLE.spots())
		{
			for (String task : spot.getTasks())
			{
				assertNotNull("No icon: " + task, TaskIcons.itemId(task));
			}
		}
	}

	/**
	 * The table is RuneLite's core Slayer {@code Task} enum: every task with the same item, and no other. The enum is
	 * package-private, so it is read by reflection (test code only; the plugin can't).
	 */
	@Test
	public void theTableMatchesRuneLitesSlayerTasks() throws Exception
	{
		Class<?> taskClass = Class.forName("net.runelite.client.plugins.slayer.Task");
		Method getName = taskClass.getDeclaredMethod("getName");
		Method getItemSpriteId = taskClass.getDeclaredMethod("getItemSpriteId");
		getName.setAccessible(true);
		getItemSpriteId.setAccessible(true);
		Object[] tasks = taskClass.getEnumConstants();
		assertTrue(tasks.length > 100);
		Set<String> names = new HashSet<>();
		for (Object task : tasks)
		{
			String name = (String) getName.invoke(task);
			names.add(name);
			assertEquals(name, getItemSpriteId.invoke(task), TaskIcons.itemId(name));
		}
		// And no other: each of the bundled file's rows is one of the enum's tasks.
		JsonArray rows = BundledDataTest.file("task-icons.json").getAsJsonArray("tasks");
		for (JsonElement row : rows)
		{
			String name = row.getAsJsonObject().get("task").getAsString();
			assertTrue("Not in the enum: " + name, names.contains(name));
		}
		assertEquals(tasks.length, rows.size());
	}

	private static List<OverallTotals.Entry> byMonster(List<LedgerRecord> records)
	{
		return TestTotals.summarize(records, OverallTotals.Grouping.MONSTER, LootPriceMode.GE,
			Collections.emptyMap(), UTC);
	}

	/** A completed Konar task of {@code monster}, newest first by {@code age}. */
	private static LedgerRecord record(String monster, long age)
	{
		LedgerRecord record = new LedgerRecord();
		record.setMonster(monster);
		record.setSlayerMaster(SlayerMaster.KONAR);
		record.setEndedAt(1_000_000L - age);
		record.setKills(10);
		record.setActiveMillis(60_000L);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.TestSpots.CATACOMBS;
import static com.shmayvan.slayerledger.TestSpots.CATACOMBS_ID;
import static com.shmayvan.slayerledger.TestSpots.CORSAIR;
import static com.shmayvan.slayerledger.TestSpots.CORSAIR_ID;
import static com.shmayvan.slayerledger.TestSpots.HYDRA_LAIR_ID;
import static com.shmayvan.slayerledger.TestSpots.KARUULM_ID;
import static com.shmayvan.slayerledger.TestSpots.KARUULM_SHARED;
import static com.shmayvan.slayerledger.TestSpots.KRAKEN_COVE_ID;
import static com.shmayvan.slayerledger.TestSpots.KRAKEN_ROOM_ID;
import static com.shmayvan.slayerledger.TestSpots.KRAKEN_SHARED;
import static com.shmayvan.slayerledger.TestSpots.SMOKE;
import static com.shmayvan.slayerledger.TestSpots.SMOKE_ID;
import static com.shmayvan.slayerledger.TestSpots.TABLE;
import static com.shmayvan.slayerledger.TestSpots.TOWER;
import static com.shmayvan.slayerledger.TestSpots.TOWER_ID;
import static com.shmayvan.slayerledger.TestSpots.UNLISTED;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

/**
 * Location names: validation, and which name the panel shows for a record, the live session and the
 * current task: the player's own name for the task, then their name for its region, then the spot table's name.
 */
public class TaskLocationTest
{
	private static final String UNLISTED_KEY = "region:" + UNLISTED;

	/** A record of {@code monster} saved with {@code spotId} in {@code region}. */
	private static LedgerRecord at(int region, String spotId, String monster)
	{
		LedgerRecord record = new LedgerRecord();
		record.setMonster(monster);
		record.setLocationRegion(region);
		record.setSpotId(spotId);
		return record;
	}

	@Test
	public void namesAreTrimmedCollapsedAndCut()
	{
		assertEquals("Smoke Dungeon", TaskLocation.normalizeName("  Smoke \t  Dungeon\n"));
		assertNull("empty", TaskLocation.normalizeName(""));
		assertNull("blank", TaskLocation.normalizeName(" \n\t "));
		assertNull(TaskLocation.normalizeName(null));
		String longName = "Catacombs of Kourend, the north-westernmost corner";
		String cut = TaskLocation.normalizeName(longName);
		assertEquals(TaskLocation.MAX_NAME_LENGTH, cut.length());
		assertEquals(longName.substring(0, TaskLocation.MAX_NAME_LENGTH).trim(), cut);
	}

	@Test
	public void historyShowsTheTasksOwnNameThenItsRegionsNameThenItsSpotsName()
	{
		Map<Integer, String> names = new HashMap<>();
		LedgerRecord record = new LedgerRecord();
		record.setMonster("Dust devils");
		assertEquals("no region at all", TaskLocation.UNKNOWN, TaskLocation.displayName(record, names::get, TABLE));

		record.setLocationRegion(SMOKE);
		assertEquals("a record saved before spots: its region's spot", "Smoke Dungeon",
			TaskLocation.displayName(record, names::get, TABLE));
		record.setSpotId(SMOKE_ID);
		assertEquals("Smoke Dungeon", TaskLocation.displayName(record, names::get, TABLE));
		names.put(SMOKE, " Smokey  ");
		assertEquals("the player's name for the region comes first", "Smokey",
			TaskLocation.displayName(record, names::get, TABLE));
		record.setLocation("West bank");
		assertEquals("the task's own name first of all", "West bank",
			TaskLocation.displayName(record, names::get, TABLE));
		assertEquals("the spot is kept", SMOKE_ID, TABLE.recordSpot(record));
	}

	/** A Task history row's second line: the table's short name, a player's name as given. */
	@Test
	public void theHistoryRowShowsTheSpotsShortNameAndThePlayersNamesAsGiven()
	{
		Map<Integer, String> names = new HashMap<>();
		LedgerRecord record = at(CATACOMBS, CATACOMBS_ID, "Dust devils");
		assertEquals("Catacombs of Kourend", TaskLocation.displayName(record, names::get, TABLE));
		assertEquals("Catacombs", TaskLocation.shortName(record, names::get, TABLE));
		assertEquals("Stronghold Cave",
			TaskLocation.shortName(at(TestSpots.STRONGHOLD, TestSpots.STRONGHOLD_ID, "Ankou"), names::get, TABLE));
		assertEquals("Region 12342", TaskLocation.shortName(at(UNLISTED, UNLISTED_KEY, "Cows"), names::get, TABLE));

		names.put(CATACOMBS, "North end");
		assertEquals("the player's name for the region", "North end",
			TaskLocation.shortName(record, names::get, TABLE));
		record.setLocation("Catacombs of Kourend, the far north end");
		assertEquals("the task's own name, cut short on the row only", "Catacombs of Kourend, the far north end",
			TaskLocation.shortName(record, names::get, TABLE));

		LedgerRecord konar = new LedgerRecord();
		konar.setMonster("Cave kraken");
		konar.setTaskLocation("Kraken Cove");
		assertEquals("an older Konar record's assigned area", "Kraken Cove",
			TaskLocation.shortName(konar, names::get, TABLE));
		assertNull("none known", TaskLocation.shortName(new LedgerRecord(), names::get, TABLE));
		assertNull("without the table only the player's names", TaskLocation.shortName(
			at(CATACOMBS, CATACOMBS_ID, "Dust devils"), region -> null, SlayerSpots.NONE));
	}

	@Test
	public void anUnlistedRegionIsNamedRegionNUntilThePlayerNamesIt()
	{
		Map<Integer, String> names = new HashMap<>();
		LedgerRecord record = new LedgerRecord();
		record.setLocationRegion(UNLISTED);
		record.setSpotId(UNLISTED_KEY);
		assertEquals("Region 12342", TaskLocation.displayName(record, names::get, TABLE));
		names.put(UNLISTED, "Edgeville");
		assertEquals("a 1.x name, or a rename since", "Edgeville", TaskLocation.displayName(record, names::get, TABLE));
	}

	@Test
	public void anOwnersNameForARegionStaysTheNameShownForItsSpot()
	{
		// A synthetic 1.x record in region 7820, which the owner named "Myth's Guild" and the table calls the Corsair
		// Cove Dungeon: the name stays, the spot is the table's.
		Map<Integer, String> names = new HashMap<>();
		names.put(CORSAIR, "Myth's Guild");
		LedgerRecord record = new LedgerRecord();
		record.setMonster("Blue dragons");
		record.setLocationRegion(CORSAIR);
		assertEquals("Myth's Guild", TaskLocation.displayName(record, names::get, TABLE));
		assertEquals(CORSAIR_ID, TABLE.recordSpot(record));
		record.setLocation("Myth's Guild");
		assertEquals("as 1.x saved it", "Myth's Guild", TaskLocation.displayName(record, names::get, TABLE));
		names.clear();
		record.setLocation(null);
		assertEquals("without it, the table's name", "Corsair Cove Dungeon",
			TaskLocation.displayName(record, names::get, TABLE));
	}

	@Test
	public void aRegionsNameNamesItsSpotOnlyWhenTheRegionHasOneSpot()
	{
		// 1.x names for two regions that two spots share, and for the owner's region 7820, which has one.
		Map<Integer, String> names = new HashMap<>();
		names.put(KRAKEN_SHARED, "Krakens");
		names.put(KARUULM_SHARED, "Karuulm");
		names.put(CORSAIR, "Myth's Guild");
		assertEquals("each spot of a shared region keeps the table's name", "Kraken Cove boss room",
			TaskLocation.displayName(at(KRAKEN_SHARED, KRAKEN_ROOM_ID, "Cave kraken"), names::get, TABLE));
		assertEquals("Kraken Cove",
			TaskLocation.displayName(at(KRAKEN_SHARED, KRAKEN_COVE_ID, "Waterfiends"), names::get, TABLE));
		assertEquals("Alchemical Hydra's lair",
			TaskLocation.displayName(at(KARUULM_SHARED, HYDRA_LAIR_ID, "Hydras"), names::get, TABLE));
		assertEquals("Karuulm Slayer Dungeon",
			TaskLocation.displayName(at(KARUULM_SHARED, KARUULM_ID, "Hydras"), names::get, TABLE));
		LedgerRecord oneX = at(KRAKEN_SHARED, null, "Waterfiends");
		assertEquals("a record saved before spots, whose region decides its spot", "Kraken Cove",
			TaskLocation.displayName(oneX, names::get, TABLE));
		assertEquals("the live task box too", "Kraken Cove boss room",
			TaskLocation.liveName(new TaskSpot(KRAKEN_ROOM_ID, KRAKEN_SHARED), names::get, TABLE));
		assertEquals("and where the player stands", new TaskLocation.Here(HYDRA_LAIR_ID, "Alchemical Hydra's lair"),
			TaskLocation.current(null, TaskSpot.UNKNOWN, KARUULM_SHARED, HYDRA_LAIR_ID, names::get, TABLE));

		assertEquals("a region with one spot shows the player's name", "Myth's Guild",
			TaskLocation.displayName(at(CORSAIR, CORSAIR_ID, "Blue dragons"), names::get, TABLE));
		assertEquals("an Unknown spot has no table name, so the region's", "Krakens",
			TaskLocation.liveName(new TaskSpot(null, KRAKEN_SHARED), names::get, TABLE));
		LedgerRecord own = at(KRAKEN_SHARED, KRAKEN_ROOM_ID, "Cave kraken");
		own.setLocation("Boss");
		assertEquals("a task's own name still comes first", "Boss", TaskLocation.displayName(own, names::get, TABLE));
	}

	@Test
	public void aStoredSpotTheTableDoesNotKnowIsNamedByItsRegion()
	{
		// An id a later table dropped or renamed.
		Map<Integer, String> names = new HashMap<>();
		LedgerRecord record = at(SMOKE, "smoke-dungeon-before", "Dust devils");
		assertEquals("Smoke Dungeon", TaskLocation.displayName(record, names::get, TABLE));
		record.setLocationRegion(null);
		assertEquals("no region either: Unknown", TaskLocation.UNKNOWN,
			TaskLocation.displayName(record, names::get, TABLE));
	}

	@Test
	public void anAssignedAreaNamesOnlyATaskWithoutASpot()
	{
		Map<Integer, String> names = new HashMap<>();
		LedgerRecord record = new LedgerRecord();
		record.setMonster("Cave kraken");
		record.setTaskLocation("Kraken Cove");
		assertEquals("an older Konar record without a region", "Kraken Cove",
			TaskLocation.displayName(record, names::get, TABLE));
		record.setLocationRegion(KRAKEN_SHARED);
		assertNull("a shared region the task can't decide", TABLE.recordSpot(record));
		assertEquals("Kraken Cove", TaskLocation.displayName(record, names::get, TABLE));
		record.setLocationRegion(SMOKE);
		assertEquals("a spot comes first", "Smoke Dungeon", TaskLocation.displayName(record, names::get, TABLE));
	}

	@Test
	public void withoutTheTableOnlyThePlayersNamesAreKnown()
	{
		Map<Integer, String> names = new HashMap<>();
		LedgerRecord record = new LedgerRecord();
		record.setLocationRegion(SMOKE);
		record.setSpotId(SMOKE_ID);
		assertNull(TaskLocation.recordLocation(record, names::get, SlayerSpots.NONE));
		assertNull(TaskLocation.recordLocation(record, names::get, null));
		names.put(SMOKE, "Smoke Dungeon");
		assertEquals("Smoke Dungeon", TaskLocation.recordLocation(record, names::get, SlayerSpots.NONE));
		record.setSpotId(UNLISTED_KEY);
		record.setLocationRegion(UNLISTED);
		assertEquals("an unlisted region's key still names it", "Region 12342",
			TaskLocation.recordLocation(record, names::get, SlayerSpots.NONE));
	}

	@Test
	public void theLiveNameIsTheSpotsNameAfterTheRegionsName()
	{
		Map<Integer, String> names = new HashMap<>();
		assertNull("no kills yet", TaskLocation.liveName(TaskSpot.UNKNOWN, names::get, TABLE));
		assertNull(TaskLocation.liveName(null, names::get, TABLE));
		TaskSpot spot = new TaskSpot(CATACOMBS_ID, CATACOMBS);
		assertEquals("Catacombs of Kourend", TaskLocation.liveName(spot, names::get, TABLE));
		names.put(CATACOMBS, "Cata");
		assertEquals("Cata", TaskLocation.liveName(spot, names::get, TABLE));
		assertEquals("an Unknown spot in a region the player named", "Kraken",
			TaskLocation.liveName(new TaskSpot(null, KRAKEN_SHARED), k -> k == KRAKEN_SHARED ? "Kraken" : null, TABLE));
		assertEquals("Location: Smoke Dungeon", TaskLocation.format("Smoke Dungeon"));
		assertEquals("Location: Unknown", TaskLocation.format(null));
	}

	@Test
	public void theCurrentLocationIsTheSessionsSpotThenTheAreaThenWhereThePlayerIs()
	{
		Map<Integer, String> names = new HashMap<>();
		TaskLocation.Here nowhere = TaskLocation.current(null, TaskSpot.UNKNOWN, LocationTally.NO_REGION, null,
			names::get, TABLE);
		assertNull(nowhere.getSpot());
		assertNull(nowhere.getName());
		assertFalse(nowhere.isKnown());
		assertEquals("where the player is", new TaskLocation.Here(TOWER_ID, "Slayer Tower"),
			TaskLocation.current(null, TaskSpot.UNKNOWN, TOWER, TOWER_ID, names::get, TABLE));
		assertEquals("the assigned area before where the player stands, with the spot of that name",
			new TaskLocation.Here(KRAKEN_COVE_ID, "Kraken Cove"),
			TaskLocation.current(" Kraken Cove ", TaskSpot.UNKNOWN, TOWER, TOWER_ID, names::get, TABLE));
		TaskLocation.Here noSuchSpot = TaskLocation.current("Somewhere else", TaskSpot.UNKNOWN, TOWER, TOWER_ID,
			names::get, TABLE);
		assertEquals("an area the table has no spot of", new TaskLocation.Here(null, "Somewhere else"), noSuchSpot);
		assertFalse("so no task matches it", noSuchSpot.isKnown());
		assertEquals("the session's spot first", new TaskLocation.Here(SMOKE_ID, "Smoke Dungeon"),
			TaskLocation.current("Kraken Cove", new TaskSpot(SMOKE_ID, SMOKE), TOWER, TOWER_ID, names::get, TABLE));
		assertEquals("a session whose spot is Unknown is passed over", new TaskLocation.Here(TOWER_ID, "Slayer Tower"),
			TaskLocation.current(null, new TaskSpot(null, KRAKEN_SHARED), TOWER, TOWER_ID, names::get, TABLE));
		names.put(TOWER, "Tower");
		assertEquals("the player's name for the region, the same spot", new TaskLocation.Here(TOWER_ID, "Tower"),
			TaskLocation.current(null, TaskSpot.UNKNOWN, TOWER, TOWER_ID, names::get, TABLE));
		assertEquals("an unlisted region where the player is", new TaskLocation.Here(UNLISTED_KEY, "Region 12342"),
			TaskLocation.current(null, TaskSpot.UNKNOWN, UNLISTED, UNLISTED_KEY, names::get, TABLE));
	}

	@Test
	public void aSpotIsFoundByItsFullOrShortNameWhenOnlyOneSpotHasIt()
	{
		assertEquals(KRAKEN_COVE_ID, TABLE.spotNamed("Kraken Cove"));
		assertEquals("case and spacing ignored", KRAKEN_COVE_ID, TABLE.spotNamed("  kraken   COVE "));
		assertEquals("the short name", CATACOMBS_ID, TABLE.spotNamed("Catacombs"));
		assertEquals(CATACOMBS_ID, TABLE.spotNamed("Catacombs of Kourend"));
		assertNull(TABLE.spotNamed("Nowhere"));
		assertNull(TABLE.spotNamed(null));
		assertNull(TABLE.spotNamed(" "));
		assertNull("no table", SlayerSpots.NONE.spotNamed("Kraken Cove"));
	}

	@Test
	public void locationsMatchIgnoringCaseAndSpacing()
	{
		assertEquals(TaskLocation.matchKey("Smoke Dungeon"), TaskLocation.matchKey("  smoke   DUNGEON "));
		assertNotEquals(TaskLocation.matchKey("Smoke Dungeon"), TaskLocation.matchKey("Smoke Devil Dungeon"));
		assertEquals("smoke dungeon", TaskLocation.matchKey(" Smoke\tDungeon "));
		// No name has no key, so it never matches a name or another no name.
		assertNull(TaskLocation.matchKey(null));
		assertNull(TaskLocation.matchKey(" "));
		assertNull(TaskLocation.matchKey(""));
	}

	@Test
	public void theDialogsSayWhatTheyChange()
	{
		LedgerRecord record = new LedgerRecord();
		record.setMonster("Dust devils");
		assertEquals("Location of this Dust devils task only (empty to remove its own name):",
			TaskLocation.editPrompt(record));
		assertEquals("Name of Region 12342, for every task there:", TaskLocation.renamePrompt(UNLISTED));
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/** Note normalization and the recent-notes list. */
public class TaskNoteTest
{
	@Test
	public void trimsAndCollapsesWhitespace()
	{
		assertEquals("Prayer gear", TaskNote.normalize("  Prayer   gear  "));
		assertEquals("Prayer gear", TaskNote.normalize("Prayer\t gear"));
		assertEquals("Barrage", TaskNote.normalize("Barrage"));
	}

	@Test
	public void emptyIsNull()
	{
		assertNull(TaskNote.normalize(null));
		assertNull(TaskNote.normalize(""));
		assertNull(TaskNote.normalize("   \t\n "));
		assertNull(TaskNote.normalize("\u0000\u0007"));
	}

	@Test
	public void controlCharactersAreStripped()
	{
		assertEquals("Range pray", TaskNote.normalize("Range\npray"));
		assertEquals("Range pray", TaskNote.normalize("Range\r\n\u0000pray\u001b"));
		assertEquals("Cannon", TaskNote.normalize("Can​non"));
	}

	@Test
	public void longNotesAreCut()
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < 10; i++)
		{
			sb.append("abcdefghi ");
		}
		String note = TaskNote.normalize(sb.toString());
		assertEquals(TaskNote.MAX_LENGTH, 60);
		// Six 9-letter words and five spaces make 59; a seventh word does not fit, and no trailing space is kept.
		assertEquals("abcdefghi abcdefghi abcdefghi abcdefghi abcdefghi abcdefghi", note);

		String exact = repeat('x', 60);
		assertEquals(exact, TaskNote.normalize(exact));
		assertEquals(exact, TaskNote.normalize(exact + "yz"));
		assertEquals(exact, TaskNote.normalize("   " + exact + "   "));
	}

	@Test
	public void neverSplitsASurrogatePair()
	{
		String emoji = "💀";
		String note = TaskNote.normalize(repeat('x', 59) + emoji);
		assertEquals(repeat('x', 59), note);
		assertEquals(repeat('x', 58) + emoji, TaskNote.normalize(repeat('x', 58) + emoji));
	}

	@Test
	public void recentNotesStartWithTheDefaults()
	{
		assertEquals(TaskNote.DEFAULTS, TaskNote.recentNotes(Collections.<String>emptyList()));
		assertEquals(Arrays.asList("Prayer gear", "Strength gear", "Barrage", "Range pray", "Cannon"),
			TaskNote.DEFAULTS);
	}

	@Test
	public void recentNotesAreNewestFirstDistinctAndKeepTheLatestCasing()
	{
		List<String> notes = Arrays.asList("Burst  ", null, "", "burst", "BARRAGE", "Bursting cannon", "Burst");
		assertEquals(Arrays.asList("Burst", "BARRAGE", "Bursting cannon", "Prayer gear", "Strength gear", "Range pray",
			"Cannon"), TaskNote.recentNotes(notes));
	}

	@Test
	public void recentNotesAreCapped()
	{
		List<String> notes = new ArrayList<>();
		for (int i = 0; i < 12; i++)
		{
			notes.add("Note " + i);
		}
		List<String> recent = TaskNote.recentNotes(notes);
		assertEquals(TaskNote.MAX_RECENT, recent.size());
		assertEquals("Note 0", recent.get(0));
		assertEquals("Note 7", recent.get(7));
	}

	@Test
	public void recentNotesFromRecordsUseTheEndTime()
	{
		LedgerRecord older = record("a", 1_000, "Cannon");
		LedgerRecord newer = record("b", 2_000, "Barrage");
		LedgerRecord none = record("c", 3_000, null);
		LedgerRecord oldest = record("d", 500, "barrage");
		List<String> recent = TaskNote.recentNotes(Arrays.asList(older, none, oldest, newer));
		assertEquals(Arrays.asList("Barrage", "Cannon", "Prayer gear", "Strength gear", "Range pray"), recent);
	}

	private static LedgerRecord record(String id, long endedAt, String note)
	{
		LedgerRecord r = new LedgerRecord();
		r.setId(id);
		r.setEndedAt(endedAt);
		r.setNote(note);
		return r;
	}

	private static String repeat(char c, int n)
	{
		char[] chars = new char[n];
		Arrays.fill(chars, c);
		return new String(chars);
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.TestSpots.CATACOMBS_ID;
import static com.shmayvan.slayerledger.TestSpots.SMOKE_ID;
import static com.shmayvan.slayerledger.TestSpots.TABLE;
import static com.shmayvan.slayerledger.TestSpots.UNLISTED;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.ToIntFunction;
import org.junit.Test;

/**
 * The advisor's words: estimated times and paces and how spots are named ({@code DESIGN_PRINCIPLES.md}
 * section 5); and the advisor card's text: its title, option names, sample sizes and times, the
 * Konar, Wilderness and setup-unknown notes and the Bring tooltips.
 */
public class TaskPlanTextTest
{
	private static final int CREATURE = 42;
	private static final String TASK = "Dust devils";
	private static final long MINUTE = 60_000L;
	private static final int DEATH_RUNE = 560;
	private static final int BLOOD_RUNE = 565;
	private static final IntFunction<String> NO_REGION_NAMES = region -> null;
	private static final Map<Integer, Long> PRICES = new HashMap<>();

	static
	{
		PRICES.put(DEATH_RUNE, 300L);
		PRICES.put(BLOOD_RUNE, 400L);
	}

	private static LedgerRecord task(String spot, boolean cannon, SetupStyle style, double minutes)
	{
		final LedgerRecord record = new LedgerRecord();
		record.setCreatureId(CREATURE);
		record.setMonster(TASK);
		record.setKills(142);
		record.setActiveMillis(Math.round(minutes * MINUTE));
		record.setCompleted(true);
		record.setSpotId(spot);
		SetupTags.detected(cannon, style, GearFocus.UNKNOWN, SetupOverrides.NONE).copyTo(record);
		return record;
	}

	/** Three barrage tasks in the Catacombs (24 minutes, 440 death and 220 blood runes) and two cannon tasks. */
	private static List<LedgerRecord> example()
	{
		final List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			final LedgerRecord barrage = task(CATACOMBS_ID, false, SetupStyle.BARRAGE, 24);
			final Map<Integer, Long> runes = new HashMap<>();
			runes.put(DEATH_RUNE, 440L);
			runes.put(BLOOD_RUNE, 220L);
			barrage.setSupplies(runes);
			records.add(barrage);
		}
		records.add(task(SMOKE_ID, true, SetupStyle.MELEE, 41));
		records.add(task(SMOKE_ID, true, SetupStyle.MELEE, 41));
		return records;
	}

	private static TaskPlan plan(int kills, List<LedgerRecord> records)
	{
		return TaskPlanner.plan(TaskPlanner.Request.builder().creatureId(CREATURE).task(TASK)
			.taskType(TaskType.REGULAR).killsLeft(kills).records(records).prices(PRICES).spots(TABLE).build());
	}

	@Test
	public void anOptionsTimeIsForTheKillsLeftOrAPaceWithThemUnknown()
	{
		final List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < 3; i++)
		{
			// 28.4 minutes for 142 kills: 12 seconds a kill.
			records.add(task(CATACOMBS_ID, false, SetupStyle.BARRAGE, 28.4));
		}
		assertEquals("~28 min", TaskPlanText.time(plan(142, records).getRecommendation().getTime(), false));
		assertEquals("~0:12/kill", TaskPlanText.time(plan(-1, records).getRecommendation().getTime(), true));
		assertEquals("~1 h", TaskPlanText.time(new TaskPlan.Time(12_000, 60 * MINUTE), false));
		assertEquals("~0:12/kill", TaskPlanText.time(new TaskPlan.Time(12_000, 60 * MINUTE), true));
	}

	@Test
	public void paceIsInMinutesAndSecondsAKill()
	{
		assertEquals("~0:12/kill", TaskPlanText.estimatedPace(12_000));
		assertEquals("~0:01/kill", TaskPlanText.estimatedPace(0));
		assertEquals("~0:01/kill", TaskPlanText.estimatedPace(499));
		assertEquals("~1:00/kill", TaskPlanText.estimatedPace(59_500));
		assertEquals("~12:34/kill", TaskPlanText.estimatedPace((12 * 60 + 34) * 1_000L));
		assertEquals("~1:02:05/kill", TaskPlanText.estimatedPace(3_725_000));
	}

	/** {@code records}' plan as a Wilderness task's (Krystilia's) with {@code kills} left. */
	private static TaskPlan wildernessPlan(int kills, List<LedgerRecord> records)
	{
		return TaskPlanner.plan(TaskPlanner.Request.builder().creatureId(CREATURE).task(TASK)
			.taskType(TaskType.WILDERNESS).killsLeft(kills).records(records).prices(PRICES).spots(TABLE).build());
	}

	@Test
	public void estimatedTimesAreInMinutesThenHoursAndMinutes()
	{
		assertEquals("~1 min", TaskPlanText.estimatedTime(0));
		assertEquals("~1 min", TaskPlanText.estimatedTime(29_000));
		assertEquals("~24 min", TaskPlanText.estimatedTime(24 * MINUTE));
		assertEquals("~24 min", TaskPlanText.estimatedTime(24 * MINUTE + 29_999));
		assertEquals("~25 min", TaskPlanText.estimatedTime(24 * MINUTE + 30_000));
		assertEquals("~59 min", TaskPlanText.estimatedTime(59 * MINUTE));
		assertEquals("~1 h", TaskPlanText.estimatedTime(60 * MINUTE));
		assertEquals("~1 h 5 min", TaskPlanText.estimatedTime(65 * MINUTE));
		assertEquals("~2 h", TaskPlanText.estimatedTime(120 * MINUTE));
	}

	// ---- The advisor card ----

	/** A plan's option built directly: {@code tasks} tasks at {@code spot} taking {@code minutes} each. */
	private static TaskPlan.Option option(String spot, boolean cannon, SetupStyle style, int tasks, long minutes)
	{
		return TaskPlan.Option.builder().spot(spot).cannon(cannon).style(style).tasks(tasks)
			.time(new TaskPlan.Time(minutes * MINUTE / 142, minutes * MINUTE))
			.bring(Collections.emptyList()).build();
	}

	@Test
	public void theCardsTitleSaysWhatItIsBasedOn()
	{
		assertEquals("Based on 6 Dust devils tasks", TaskPlanText.cardTitle(TASK, 6));
		assertEquals("Based on 1 Dust devils task", TaskPlanText.cardTitle(TASK, 1));
		assertEquals("Based on 3 tasks", TaskPlanText.cardTitle(null, 3));
	}

	@Test
	public void theCardsNoHistoryKonarAndSetupUnknownLines()
	{
		assertEquals("No completed Dust devils tasks yet, so no estimate.",
			TaskPlanText.noHistoryLine(TASK, plan(142, Collections.emptyList())));
		assertEquals("No completed Wilderness Dust devils tasks yet, so no estimate.",
			TaskPlanText.noHistoryLine(TASK, wildernessPlan(142, example())));
		assertEquals("No completed Wilderness tasks yet, so no estimate.",
			TaskPlanText.noHistoryLine(null, wildernessPlan(142, example())));
		assertEquals("No completed tasks in Catacombs yet, so all areas are used.", TaskPlanText.areaFallback(
			TaskPlanText.shortSpotName(CATACOMBS_ID, TABLE, NO_REGION_NAMES)));
		assertEquals("No completed tasks in the assigned area yet, so all areas are used.",
			TaskPlanText.areaFallback(null));
		assertEquals("Setup unknown for these tasks.", TaskPlanText.SETUP_UNKNOWN);
	}

	@Test
	public void anOptionIsNamedBySetupAndSpotWithItsSampleSize()
	{
		final TaskPlan plan = plan(142, example());
		final TaskPlan.Option best = plan.getRecommendation();
		final TaskPlan.Option other = plan.getOptions().get(1);
		assertEquals("Barrage, Catacombs", TaskPlanText.optionName(best, TASK, TABLE, NO_REGION_NAMES));
		assertEquals("3 tasks", TaskPlanText.optionTasks(best, false));
		assertEquals("Cannon, melee, Smoke Dungeon", TaskPlanText.optionName(other, TASK, TABLE, NO_REGION_NAMES));
		assertEquals("2 tasks", TaskPlanText.optionTasks(other, false));

		// Thin data: one task. An estimated cannon or style (a migrated task) says so beside the sample size, and the
		// name has no "~".
		final LedgerRecord one = task(SMOKE_ID, true, SetupStyle.RANGED, 30);
		one.setStyleEstimated(true);
		final TaskPlan thinPlan = plan(142, Collections.singletonList(one));
		final TaskPlan.Option thin = thinPlan.getRecommendation();
		assertEquals("1 task, estimated", TaskPlanText.optionTasks(thin, false));
		// As a thin recommendation (V2 plan 6): what it is based on.
		assertTrue(thinPlan.isRecommendationThin());
		assertEquals("based on 1 task, estimated", TaskPlanText.optionTasks(thin, true));
		assertEquals("based on 3 tasks", TaskPlanText.optionTasks(best, true));
		assertEquals("Cannon, ranged, Smoke Dungeon", TaskPlanText.optionName(thin, TASK, TABLE, NO_REGION_NAMES));

		// Done on the task's Slayer boss: its name first.
		final TaskPlan.Option boss = TaskPlan.Option.builder().spot(TestSpots.TOWER_ID).boss(true).cannon(false)
			.style(SetupStyle.MELEE).tasks(2).time(new TaskPlan.Time(1, 1)).bring(Collections.emptyList())
			.build();
		assertEquals("Grotesque Guardians, melee, Slayer Tower",
			TaskPlanText.optionName(boss, "Gargoyles", TABLE, NO_REGION_NAMES));
		assertEquals("Boss, melee, Slayer Tower", TaskPlanText.optionName(boss, null, TABLE, NO_REGION_NAMES));
		// An unlisted region the player named.
		assertEquals("Melee, Edgeville", TaskPlanText.optionName(option(SlayerSpots.regionKey(UNLISTED), false,
			SetupStyle.MELEE, 1, 20), TASK, TABLE, region -> "Edgeville"));
	}

	@Test
	public void theCardsRowsAndLines()
	{
		final TaskPlan plan = plan(142, example());
		assertEquals("+2 more", TaskPlanText.bringMore(2));
		assertEquals(Arrays.asList("Prayer potion(4)", "Bring: 1,206", "GE value: 10,854,000 gp"),
			TaskPlanText.bringTooltip("Prayer potion(4)", 1_206, 10_854_000L));
		assertEquals(Arrays.asList("Death rune", "Bring: 440"), TaskPlanText.bringTooltip("Death rune", 440, null));
		// "+N more"'s tooltip: an item a line, worded as its icon's tooltip.
		assertEquals("Soul rune, Bring: 20, GE value: 3,000 gp", TaskPlanText.bringMoreLine("Soul rune", 20, 3_000L));
		assertEquals("Death rune, Bring: 440", TaskPlanText.bringMoreLine("Death rune", 440, null));
		assertEquals("All setups (5 tasks)", TaskPlanText.allSetups(plan.getAllSetups()));
		assertEquals("All setups (1 task)", TaskPlanText.allSetups(new TaskPlan.Summary(1, null)));
	}

	@Test
	public void theCardsSentencesAreBrokenIntoLinesThatFit()
	{
		// One pixel a character, for the test.
		final ToIntFunction<String> measure = String::length;
		assertEquals(Arrays.asList("No completed Dust", "devils tasks yet, so", "no estimate."),
			TaskPlanText.wrap("No completed Dust devils tasks yet, so no estimate.", 20, measure));
		assertEquals("a word too long has a line of its own", Arrays.asList("a", "Hellhounds-and-more", "b"),
			TaskPlanText.wrap("a Hellhounds-and-more b", 5, measure));
		assertEquals(Collections.singletonList("a b"), TaskPlanText.wrap("  a   b ", 10, measure));
	}

	@Test
	public void theTitleAndOptionNamesTakeAtMostTwoLinesTheFirstBesideTheSampleSize()
	{
		final ToIntFunction<String> measure = String::length;
		// The first line has the room the sample size leaves (12), the second the full width (20).
		assertEquals(Arrays.asList("Cannon,", "melee, Smoke Dungeon"),
			TaskPlanText.wrap("Cannon, melee, Smoke Dungeon", 12, 20, 2, measure));
		assertEquals(Arrays.asList("Cannon, melee,", "Smoke Dungeon"),
			TaskPlanText.wrap("Cannon, melee, Smoke Dungeon", 14, 20, 2, measure));
		assertEquals("fits one line", Collections.singletonList("Barrage, Catacombs"),
			TaskPlanText.wrap("Barrage, Catacombs", 18, 20, 2, measure));
		// Past two lines the second holds the rest, which the card cuts short (FitLabel), the whole in the tooltip.
		assertEquals(Arrays.asList("Based on 3 Abyssal", "demons with a name made long tasks"),
			TaskPlanText.wrap("Based on 3 Abyssal demons with a name made long tasks", 20, 20, 2, measure));
		assertEquals("a first word too long keeps its line", Arrays.asList("Hellhounds-and-more", "b c"),
			TaskPlanText.wrap("Hellhounds-and-more b c", 5, 5, 2, measure));
		assertEquals(Collections.singletonList("a b c"), TaskPlanText.wrap("a b c", 1, 1, 1, measure));
	}

	@Test
	public void spotsGoByTheirShortNames()
	{
		assertEquals("Catacombs", TaskPlanText.shortSpotName(CATACOMBS_ID, TABLE, NO_REGION_NAMES));
		assertEquals("Region 12342", TaskPlanText.shortSpotName(SlayerSpots.regionKey(UNLISTED), TABLE,
			NO_REGION_NAMES));
		assertEquals("Edgeville", TaskPlanText.shortSpotName(SlayerSpots.regionKey(UNLISTED), TABLE,
			region -> "Edgeville"));
		assertEquals("a listed spot keeps the table's", "Catacombs",
			TaskPlanText.shortSpotName(CATACOMBS_ID, TABLE, region -> "Mine"));
		assertEquals("an id the table doesn't know", "old-spot",
			TaskPlanText.shortSpotName("old-spot", TABLE, NO_REGION_NAMES));
	}
}

package com.shmayvan.slayerledger;

import static com.shmayvan.slayerledger.TestSpots.CATACOMBS_ID;
import static com.shmayvan.slayerledger.TestSpots.SMOKE;
import static com.shmayvan.slayerledger.TestSpots.SMOKE_ID;
import static com.shmayvan.slayerledger.TestSpots.STRONGHOLD_ID;
import static com.shmayvan.slayerledger.TestSpots.TABLE;
import static com.shmayvan.slayerledger.TestSpots.TOWER_ID;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/**
 * The advisor's planner (V2 plan 5 and 6) on synthetic records: which tasks count, the options and their
 * grouping (estimated values, Unknown spot or style, the boss variant), the n rules of the recommendation, the time,
 * what to bring and the order with its ties.
 */
public class TaskPlannerTest
{
	private static final int CREATURE = 42;
	private static final String TASK = "Dust devils";
	private static final long MINUTE = 60_000L;
	private static final int COINS = ItemValuation.COINS;
	private static final int SUPPLY = 9_000;
	private static final int CANNONBALL = 2;
	private static final int DEATH_RUNE = 560;
	private static final int BLOOD_RUNE = 565;
	/** Prayer potion(4): counted in doses, 4 to a potion. */
	private static final int PRAYER_POTION = 2_434;
	/** Ring of dueling(8): counted in charges, 8 to a ring. */
	private static final int DUELING_RING = 2_552;
	private static final Map<Integer, Long> PRICES = prices();

	private static Map<Integer, Long> prices()
	{
		final Map<Integer, Long> prices = new HashMap<>();
		prices.put(COINS, 1L);
		prices.put(SUPPLY, 100L);
		prices.put(CANNONBALL, 200L);
		prices.put(DEATH_RUNE, 300L);
		prices.put(BLOOD_RUNE, 400L);
		prices.put(PRAYER_POTION, 8_000L);
		return Collections.unmodifiableMap(prices);
	}

	private static int ids;

	/**
	 * A completed Dust devils task of {@code kills} kills in {@code minutes} minutes at the spot {@code spot}
	 * ({@code null}: none), with the detected cannon and style and an Unknown gear focus.
	 */
	private static LedgerRecord task(String spot, boolean cannon, SetupStyle style, int kills, double minutes)
	{
		final LedgerRecord record = new LedgerRecord();
		record.setId("task-" + ids++);
		record.setCreatureId(CREATURE);
		record.setMonster(TASK);
		record.setKills(kills);
		record.setActiveMillis(Math.round(minutes * MINUTE));
		record.setCompleted(true);
		record.setSpotId(spot);
		SetupTags.detected(cannon, style, GearFocus.UNKNOWN, SetupOverrides.NONE).copyTo(record);
		return record;
	}

	/** {@code record}, valued: {@code loot} coins and {@code supplies} of {@link #SUPPLY}. */
	private static LedgerRecord valued(LedgerRecord record, long loot, long supplies)
	{
		record.setLoot(Collections.singletonMap(COINS, loot));
		record.setLootGeValue(loot);
		record.setLootHaValue(loot);
		if (supplies > 0)
		{
			record.setSupplies(Collections.singletonMap(SUPPLY, supplies));
		}
		record.setSuppliesGeValue(supplies * PRICES.get(SUPPLY));
		return record;
	}

	/** {@code record} with {@code supplies} (item id, amount pairs) used. */
	private static LedgerRecord using(LedgerRecord record, long... supplies)
	{
		final Map<Integer, Long> used = new HashMap<>();
		for (int i = 0; i < supplies.length; i += 2)
		{
			used.put((int) supplies[i], supplies[i + 1]);
		}
		record.setSupplies(used);
		return record;
	}

	private static List<LedgerRecord> times(int n, LedgerRecord... templates)
	{
		final List<LedgerRecord> records = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			for (LedgerRecord template : templates)
			{
				records.add(copy(template));
			}
		}
		return records;
	}

	private static LedgerRecord copy(LedgerRecord template)
	{
		final LedgerRecord record = task(template.getSpotId(), template.getDetectedCannon(),
			template.getDetectedStyle(), template.getKills(), template.getActiveMillis() / (double) MINUTE);
		record.setSupplies(template.getSupplies());
		record.setSupplyDoses(template.getSupplyDoses());
		record.setLoot(template.getLoot());
		record.setLootGeValue(template.getLootGeValue());
		record.setLootHaValue(template.getLootHaValue());
		record.setSuppliesGeValue(template.getSuppliesGeValue());
		record.setXpGained(template.getXpGained());
		return record;
	}

	private static TaskPlan plan(int kills, List<LedgerRecord> records)
	{
		return TaskPlanner.plan(TaskPlanner.Request.builder()
			.creatureId(CREATURE)
			.task(TASK)
			.taskType(TaskType.REGULAR)
			.killsLeft(kills)
			.records(records)
			.prices(PRICES)
			.spots(TABLE)
			.build());
	}

	private static TaskPlan plan(int kills, LedgerRecord... records)
	{
		return plan(kills, Arrays.asList(records));
	}

	@SafeVarargs
	private static List<LedgerRecord> all(List<LedgerRecord>... groups)
	{
		final List<LedgerRecord> records = new ArrayList<>();
		for (List<LedgerRecord> group : groups)
		{
			records.addAll(group);
		}
		return records;
	}

	private static long minutes(long millis)
	{
		return Math.round(millis / (double) MINUTE);
	}

