		assertEquals("prayer potion", families.get(PRAYER_POTION_3));
		assertEquals("prayer potion", families.get(PRAYER_POTION));

		// 16 doses in each task: 4 potions of 4 doses per 10 kills.
		final List<TaskPlan.BringItem> merged = TaskPlanner.bring(tasks, 10, PRICES, families);
		assertEquals(1, merged.size());
		assertEquals("keyed by the potion with the most doses", PRAYER_POTION, merged.get(0).getItemId());
		assertEquals(4, merged.get(0).getQuantity());
		assertEquals(Long.valueOf(4 * 8_000L), merged.get(0).getValue());
		assertEquals("without the families, two lines", 2, TaskPlanner.bring(tasks, 10, PRICES, null).size());

		final TaskPlan plan = TaskPlanner.plan(TaskPlanner.Request.builder().creatureId(CREATURE).task(TASK)
			.killsLeft(10).records(tasks).prices(PRICES).spots(TABLE).potionFamilies(families).build());
		assertEquals(merged, plan.getRecommendation().getBring());
	}

	@Test
	public void potionFamiliesAreNamedLikeTheTrackersAndLeaveOtherItemsAlone()
	{
		final int pizza = SupplyTracker.MULTI_BITE_FOOD.keySet().iterator().next();
		final int unnamed = 12_345;
		final LedgerRecord record = using(task(SMOKE_ID, false, SetupStyle.MELEE, 10, 10), PRAYER_POTION, 4,
			DUELING_RING, 2, pizza, 2, unnamed, 3, DEATH_RUNE, 100);
		final Map<Integer, Integer> doses = new HashMap<>();
		doses.put(PRAYER_POTION, 4);
		doses.put(DUELING_RING, 8);
		doses.put(pizza, 2);
		doses.put(unnamed, 4);
		record.setSupplyDoses(doses);
		final Map<Integer, String> names = new HashMap<>();
		names.put(PRAYER_POTION, "Prayer potion(4)");
		names.put(DUELING_RING, "Ring of dueling(8)");
		names.put(pizza, "Some pizza");
		names.put(DEATH_RUNE, "Death rune");

		assertEquals(Collections.singletonMap(PRAYER_POTION, "prayer potion"),
			TaskPlanner.potionFamilies(Arrays.asList(record, null), names::get));
		assertTrue(TaskPlanner.potionFamilies(null, names::get).isEmpty());
		assertTrue(TaskPlanner.potionFamilies(Collections.singletonList(record), null).isEmpty());
	}

	// ---- Wilderness and Konar ----

	@Test
	public void aWildernessTaskUsesOnlyWildernessTasks()
	{
		final List<LedgerRecord> wilderness = times(2, task(TOWER_ID, false, SetupStyle.MELEE, 10, 30));
		for (LedgerRecord record : wilderness)
		{
			record.setSlayerMaster(SlayerMaster.KRYSTILIA);
		}
		final List<LedgerRecord> elsewhere = times(3, task(SMOKE_ID, false, SetupStyle.MELEE, 10, 10));
		elsewhere.get(0).setSlayerMaster(SlayerMaster.KONAR);
		final List<LedgerRecord> records = all(wilderness, elsewhere);

		final TaskPlan plan = TaskPlanner.plan(TaskPlanner.Request.builder().creatureId(CREATURE).task(TASK)
			.taskType(TaskType.WILDERNESS).killsLeft(10).records(records).spots(TABLE).build());
		assertEquals("kills elsewhere don't count for a Wilderness task", 2, plan.getAllSetups().getTasks());
		assertEquals(TOWER_ID, plan.getRecommendation().getSpot());
		assertEquals(1, plan.getOptions().size());
		assertFalse(plan.isWildernessHistoryMissing());

		assertEquals("any other task uses them all", 5, plan(10, records).getAllSetups().getTasks());

		// Only tasks elsewhere: no history for a Wilderness task, noted, since the creature has tasks.
		final TaskPlan none = TaskPlanner.plan(TaskPlanner.Request.builder().creatureId(CREATURE).task(TASK)
			.taskType(TaskType.WILDERNESS).killsLeft(10).records(elsewhere).spots(TABLE).build());
		assertFalse(none.hasHistory());
		assertTrue(none.isWildernessHistoryMissing());
		assertFalse("no task of the creature at all", TaskPlanner.plan(TaskPlanner.Request.builder()
			.creatureId(CREATURE).task(TASK).taskType(TaskType.WILDERNESS).killsLeft(10)
			.records(Collections.emptyList()).spots(TABLE).build()).isWildernessHistoryMissing());
		assertFalse("not a Wilderness task", plan(10, Collections.emptyList()).isWildernessHistoryMissing());
	}

	@Test
	public void aKonarTaskKeepsTheOptionsAtItsAreasSpot()
	{
		final List<LedgerRecord> records = all(
			times(3, task(SMOKE_ID, false, SetupStyle.MELEE, 10, 10)),
			times(3, task(SMOKE_ID, true, SetupStyle.MELEE, 10, 5)),
			times(1, task(CATACOMBS_ID, false, SetupStyle.BARRAGE, 10, 30)));

		final TaskPlan there = konar("Catacombs of Kourend", records);
		assertEquals(CATACOMBS_ID, there.getAreaSpot());
		assertFalse(there.isAreaFallback());
		assertEquals("only the options there", 1, there.getOptions().size());
		assertEquals(CATACOMBS_ID, there.getRecommendation().getSpot());
		assertTrue(there.isRecommendationThin());
		assertEquals("All setups keeps every task", 7, there.getAllSetups().getTasks());
		assertEquals(0, there.getExcludedTasks());
		assertEquals("the short name too", CATACOMBS_ID, konar("catacombs", records).getAreaSpot());

		final TaskPlan none = konar("Slayer Tower", records);
		assertEquals(TOWER_ID, none.getAreaSpot());
		assertTrue("none there: every option, noted", none.isAreaFallback());
		assertEquals(3, none.getOptions().size());
		assertEquals(SMOKE_ID, none.getRecommendation().getSpot());

		final TaskPlan unnamed = konar("Somewhere the table doesn't list", records);
		assertNull(unnamed.getAreaSpot());
		assertFalse(unnamed.isAreaFallback());
		assertEquals(3, unnamed.getOptions().size());
		assertNull(konar(null, records).getAreaSpot());
	}

	@Test
	public void aPlanSaysWhichAssignmentItIsFor()
	{
		final List<LedgerRecord> records = times(3, task(SMOKE_ID, false, SetupStyle.MELEE, 10, 10));
		final TaskPlan plan = konar("Catacombs of Kourend", records);
		assertEquals(CREATURE, plan.getCreatureId());
		assertEquals(TaskType.KONAR, plan.getTaskType());
		assertEquals("Catacombs of Kourend", plan.getArea());
		assertTrue(plan.isFor(CREATURE, TASK, TaskType.KONAR, "Catacombs of Kourend"));
		// The card keeps a plan only for its own assignment: another area, type, creature or name is another's.
		assertFalse("another Konar area", plan.isFor(CREATURE, TASK, TaskType.KONAR, "Slayer Tower"));
		assertFalse(plan.isFor(CREATURE, TASK, TaskType.REGULAR, "Catacombs of Kourend"));
		assertFalse(plan.isFor(CREATURE + 1, TASK, TaskType.KONAR, "Catacombs of Kourend"));
		assertFalse(plan.isFor(CREATURE, "Greater demons", TaskType.KONAR, "Catacombs of Kourend"));

		// The plan without history too.
		final TaskPlan none = konar(null, Collections.emptyList());
		assertFalse(none.hasHistory());
		assertTrue(none.isFor(CREATURE, TASK, TaskType.KONAR, null));
		assertFalse(none.isFor(CREATURE, TASK, TaskType.KONAR, "Slayer Tower"));
	}

	private static TaskPlan konar(String area, List<LedgerRecord> records)
	{
		return TaskPlanner.plan(TaskPlanner.Request.builder().creatureId(CREATURE).task(TASK).taskType(TaskType.KONAR)
			.area(area).killsLeft(10).records(records).spots(TABLE).build());
	}

	@Test
	public void theMostValuableEightShowAndTheRestAreCounted()
	{
		final Map<Integer, Long> prices = new HashMap<>();
		final long[] used = new long[22];
		for (int i = 0; i < 11; i++)
		{
			used[2 * i] = 1_000 + i;
			used[2 * i + 1] = 1;
			if (i < 10)
			{
				prices.put(1_000 + i, 10L * (i + 1));
			}
		}
		final LedgerRecord record = using(task(SMOKE_ID, false, SetupStyle.MELEE, 1, 1), used);
		final TaskPlan plan = TaskPlanner.plan(TaskPlanner.Request.builder().creatureId(CREATURE).task(TASK)
			.killsLeft(1).records(Collections.singletonList(record)).prices(prices).spots(TABLE).build());
		final TaskPlan.Option option = plan.getRecommendation();
		assertEquals(TaskPlanner.MAX_BRING_ITEMS, option.getBring().size());
		assertEquals(3, option.getBringMore());
		assertEquals("most valuable first", 1_009, option.getBring().get(0).getItemId());
		assertEquals(1_002, option.getBring().get(7).getItemId());
		// The rest, for "+3 more"'s tooltip: in the same order, the unpriced one last.
		final List<Integer> rest = new ArrayList<>();
		for (TaskPlan.BringItem item : option.getBringRest())
		{
			rest.add(item.getItemId());
		}
		assertEquals(Arrays.asList(1_001, 1_000, 1_010), rest);

		// Unpriced items last, then the larger amount, then the lower id.
		final LedgerRecord unpriced = using(task(SMOKE_ID, false, SetupStyle.MELEE, 1, 1), 7, 3, 8, 5, 6, 3,
			CANNONBALL, 1);
		final List<TaskPlan.BringItem> order = TaskPlanner.bring(Collections.singletonList(unpriced), 1, PRICES, null);
		assertEquals(Arrays.asList(CANNONBALL, 8, 6, 7), Arrays.asList(order.get(0).getItemId(),
			order.get(1).getItemId(), order.get(2).getItemId(), order.get(3).getItemId()));
		assertNull(order.get(1).getValue());
	}

	// ---- Order ----

	@Test
	public void theFastestComesFirstThenMoreTasksThenTheKey()
	{
		final TaskPlan.Option fewer = option(SMOKE_ID, 3, 20);
		final TaskPlan.Option more = option(TOWER_ID, 4, 20);
		final TaskPlan.Option slower = option(CATACOMBS_ID, 4, 30);
		final TaskPlan.Option fastest = option(STRONGHOLD_ID, 1, 10);
		// The same time and tasks as "more": the spot decides.
		final TaskPlan.Option sameAsMore = option(CATACOMBS_ID, 4, 20);
		final List<TaskPlan.Option> options = new ArrayList<>(Arrays.asList(sameAsMore, fastest, slower, fewer, more));
		options.sort(TaskPlanner.ORDER);
		assertEquals(Arrays.asList(STRONGHOLD_ID, CATACOMBS_ID, TOWER_ID, SMOKE_ID, CATACOMBS_ID), spots(options));
		assertEquals(30, minutes(options.get(4).getTime().getMillis()));
	}

	private static TaskPlan.Option option(String spot, int tasks, long minutes)
	{
		return TaskPlan.Option.builder()
			.spot(spot)
			.style(SetupStyle.MELEE)
			.tasks(tasks)
			.time(new TaskPlan.Time(minutes * MINUTE / 10, minutes * MINUTE))
			.bring(Collections.emptyList())
			.build();
	}

	private static List<String> spots(List<TaskPlan.Option> options)
	{
		final List<String> spots = new ArrayList<>();
		for (TaskPlan.Option option : options)
		{
			spots.add(option.getSpot());
		}
		return spots;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** {@link TaskRewards}: points earned and streak of a completion, and {@link CompletionSignal#incrementedCounter()}. */
public class TaskRewardsTest
{
	private static final int[] COUNTERS = {43, 7, 2};

	@Test
	public void pointsEarnedIsTheIncrease()
	{
		assertEquals(Integer.valueOf(15), TaskRewards.pointsEarned(100, 115));
		assertEquals("Turael's tasks and early streaks give none", Integer.valueOf(0), TaskRewards.pointsEarned(100, 100));
	}

	@Test
	public void pointsEarnedIsNeverNegativeOrGuessed()
	{
		assertNull(TaskRewards.pointsEarned(100, 40));
		assertNull(TaskRewards.pointsEarned(null, 40));
		assertNull(TaskRewards.pointsEarned(40, null));
	}

	@Test
	public void completionUsesTheReadingBeforeTheCompletionTick()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.update(115);
		rewards.startCompletion("s1", COUNTERS, 0);
		assertTrue(rewards.isFollowing());
		assertEquals("s1", rewards.getSessionId());
		assertEquals(Integer.valueOf(15), rewards.earned());
		assertEquals(Integer.valueOf(43), rewards.streak());
	}

	@Test
	public void pointsSpentEarlierInTheTaskDontMatter()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(500);
		// Spent 400 points at a master mid-task.
		rewards.update(100);
		rewards.update(100);
		rewards.update(118);
		rewards.startCompletion("s1", COUNTERS, 0);
		assertEquals(Integer.valueOf(18), rewards.earned());
	}

	@Test
	public void pointsArrivingAfterTheCompletionTickAreFollowed()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.update(100);
		rewards.startCompletion("s1", COUNTERS, 0);
		assertEquals(Integer.valueOf(0), rewards.earned());
		rewards.update(115);
		assertEquals(Integer.valueOf(15), rewards.earned());
		assertEquals("the streak is fixed at the completion", Integer.valueOf(43), rewards.streak());
	}

	@Test
	public void spendingRightAfterTheCompletionIsNotTrusted()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.update(115);
		rewards.startCompletion("s1", COUNTERS, 0);
		rewards.update(10);
		assertNull(rewards.earned());
	}

	@Test
	public void firstReadingAfterResetIsOnlyABaseline()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.reset();
		// Login resync: the first reading has nothing before it.
		rewards.update(900);
		rewards.startCompletion("s1", COUNTERS, 0);
		assertNull(rewards.earned());
		rewards.reset();
		assertFalse("reset also stops following", rewards.isFollowing());
	}

	@Test
	public void stoppedFollowingReportsNothing()
	{
		TaskRewards rewards = new TaskRewards();
		rewards.update(100);
		rewards.update(115);
		rewards.startCompletion("s1", COUNTERS, 1);
		rewards.stopFollowing();
		assertFalse(rewards.isFollowing());
		assertNull(rewards.getSessionId());
		assertNull(rewards.earned());
		assertNull(rewards.streak());
	}

	@Test
	public void streakIsTheCounterThatWentUp()
	{
		assertEquals(Integer.valueOf(43), TaskRewards.streakAfter(COUNTERS, 0));
		assertEquals(Integer.valueOf(7), TaskRewards.streakAfter(COUNTERS, 1));
		assertEquals(Integer.valueOf(2), TaskRewards.streakAfter(COUNTERS, 2));
		assertNull(TaskRewards.streakAfter(COUNTERS, CompletionSignal.NO_COUNTER));
		assertNull(TaskRewards.streakAfter(COUNTERS, 3));
		assertNull(TaskRewards.streakAfter(null, 0));
	}

	@Test
	public void completionSignalNamesTheIncrementedCounter()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(42, 6, 2);
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
		assertTrue(signal.update(42, 7, 2));
		assertEquals("Wilderness", 1, signal.incrementedCounter());
		assertFalse(signal.update(42, 7, 2));
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
		assertTrue(signal.update(42, 7, 3));
		assertEquals("Mortimer", 2, signal.incrementedCounter());
		assertTrue(signal.update(43, 7, 3));
		assertEquals("regular", 0, signal.incrementedCounter());
	}

	@Test
	public void completionSignalHasNoCounterWhenTwoWentUp()
	{
		CompletionSignal signal = new CompletionSignal();
		signal.update(42, 6, 2);
		assertTrue(signal.update(43, 7, 2));
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
		assertFalse("a resync", signal.update(50, 7, 2));
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
		signal.reset();
		assertEquals(CompletionSignal.NO_COUNTER, signal.incrementedCounter());
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.Locale;
import org.junit.Test;

/**
 * The per-task statistics the live card's time left and the overlay's time left and supply runway read: the sample
 * count, the time per kill, the location and the supplies per kill (the 2.0 rebuild trimmed them to these).
 */
public class TaskStatisticsTest
{
	private static final int CREATURE = 42;
	private static final String MONSTER = "Abyssal demons";
	private static final long MINUTE = 60_000L;

	@Test
	public void averagesCompletedRecordsAndKeepsOutliers()
	{
		LedgerRecord usual = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		usual.setSupplies(Collections.singletonMap(100, 10L));
		usual.setSupplyDoses(Collections.singletonMap(100, 4));

		LedgerRecord outlier = record(CREATURE, MONSTER, 20, 60 * MINUTE);
		outlier.setSupplies(Collections.singletonMap(100, 60L));
		outlier.setSupplyDoses(Collections.singletonMap(100, 4));

		LedgerRecord partial = record(CREATURE, MONSTER, 100, 100 * MINUTE);
		partial.setPartial(true);
		LedgerRecord otherCreature = record(43, MONSTER, 100, 100 * MINUTE);
		TaskStatistics stats = stats(Arrays.asList(usual, outlier, partial, otherCreature));

		assertEquals(2, stats.getSampleCount());
		assertEquals(Long.valueOf(140_000), stats.getMillisPerKill());
		assertEquals("70 doses over 30 kills", 70d / 30d, stats.getSuppliesPerKill().get(100), 1e-9);
		assertNull("from every location", stats.getLocation());
	}

	@Test
	public void handlesLegacyMissingSuppliesWithoutTreatingThemAsZero()
	{
		LedgerRecord legacy = record(CREATURE, MONSTER, 5, 10 * MINUTE);
		legacy.setSupplies(Collections.singletonMap(100, 5L));
		legacy.setXpGained(null);

		TaskStatistics stats = stats(Collections.singletonList(legacy));
		assertEquals(1, stats.getSampleCount());
		assertEquals(Long.valueOf(120_000), stats.getMillisPerKill());
		assertEquals(Double.valueOf(1d), stats.getSuppliesPerKill().get(100));

		// Valued with no supplies: it used none, so it counts for the supplies per kill.
		LedgerRecord valuedWithoutSupplies = record(CREATURE, MONSTER, 5, 10 * MINUTE);
		valuedWithoutSupplies.setLootGeValue(500L);
		TaskStatistics mixed = stats(Arrays.asList(legacy, valuedWithoutSupplies));
		assertEquals(Double.valueOf(0.5), mixed.getSuppliesPerKill().get(100));
	}

	@Test
	public void supportsLegacyNameMatching()
	{
		LedgerRecord legacy = record(null, "  ABYSSAL DEMONS ", 2, MINUTE);
		TaskStatistics stats = stats(Collections.singletonList(legacy));

		assertEquals(1, stats.getSampleCount());
		assertEquals(Long.valueOf(30_000), stats.getMillisPerKill());
	}

	@Test
	public void excludesRecordsThatAreNeitherCompletedNorPartial()
	{
		LedgerRecord stopped = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		stopped.setCompleted(false);
		stopped.setPartial(false);
		LedgerRecord noKills = record(CREATURE, MONSTER, 0, 10 * MINUTE);

		TaskStatistics none = stats(Arrays.asList(stopped, noKills));
		assertEquals(0, none.getSampleCount());
		assertNull(none.getMillisPerKill());
		assertTrue(none.getSuppliesPerKill().isEmpty());
	}

	@Test
	public void aOneXTaskSavedWithoutSuppliesIsLeftOutOfTheSuppliesPerKill()
	{
		// A 2.0 task: 10 kills, 100K of loot, 20 manta rays.
		LedgerRecord tracked = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		tracked.setLootGeValue(100_000L);
		tracked.setLootHaValue(100_000L);
		tracked.setSuppliesGeValue(1_000L);
		SavedItems.withItems(tracked);
		// A 1.x task saved with no supplies: its supply counting may have stopped, so what it used is unknown.
		LedgerRecord oneX = record(CREATURE, MONSTER, 30, 30 * MINUTE);
		oneX.setLootGeValue(300_000L);
		oneX.setLootHaValue(300_000L);
		oneX.setSuppliesGeValue(0L);
		SavedItems.withItems(oneX);
		oneX.setSchemaVersion(2);

		TaskStatistics stats = stats(Arrays.asList(tracked, oneX));
		assertEquals("both count for the time", 2, stats.getSampleCount());
		assertEquals(Long.valueOf(MINUTE), stats.getMillisPerKill());
		// The 2.0 task's 20 manta rays, over its own 10 kills, not over the 40 of both.
		assertEquals(2d, stats.getSuppliesPerKill().get(SavedItems.SUPPLY), 1e-9);

		// A 1.x task migrated in memory reads schema version 3; its estimated cannon tag says it is one.
		oneX.setSchemaVersion(SetupMigration.MIGRATED_VERSION);
		oneX.setCannonEstimated(true);
		assertEquals(2d, stats(Arrays.asList(tracked, oneX)).getSuppliesPerKill().get(SavedItems.SUPPLY), 1e-9);
		// A task 2.0 saved without supplies used none.
		oneX.setCannonEstimated(null);
		assertEquals("20 over 40 kills", 0.5d, stats(Arrays.asList(tracked, oneX)).getSuppliesPerKill()
			.get(SavedItems.SUPPLY), 1e-9);
	}

	@Test
	public void bossKeysMatchByIdAndLegacyNamesOnlyWithoutAnId()
	{
		int cerberus = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 3);
		int otherBoss = SessionTracker.creatureKey(SessionTracker.BOSS_TASK_TARGET, 4);
		LedgerRecord same = record(cerberus, "Cerberus", 5, 5 * MINUTE);
		// A record with an id is matched by id only, even when its name is the same.
		LedgerRecord otherKeySameName = record(otherBoss, "Cerberus", 7, 7 * MINUTE);
		LedgerRecord legacy = record(null, "cerberus", 2, 2 * MINUTE);
		LedgerRecord legacyOther = record(null, "Kraken", 9, 9 * MINUTE);

		TaskStatistics stats = TaskStatistics.forTask(Arrays.asList(same, otherKeySameName, legacy, legacyOther),
			cerberus, "Cerberus", TaskSelection.ANY, null, null);
		assertEquals(2, stats.getSampleCount());
		assertEquals(Long.valueOf(MINUTE), stats.getMillisPerKill());
	}

	@Test
	public void currentTaskWithoutACreatureKeyMatchesEveryRecordByName()
	{
		// Without the current task's key there is nothing to compare ids with, so every record (with or without an
		// id) is matched by its name.
		LedgerRecord withId = record(CREATURE, MONSTER, 4, 4 * MINUTE);
		LedgerRecord legacy = record(null, MONSTER, 6, 12 * MINUTE);
		LedgerRecord otherName = record(CREATURE, "Kraken", 10, 10 * MINUTE);

		TaskStatistics stats = TaskStatistics.forTask(Arrays.asList(withId, legacy, otherName),
			SessionTracker.NO_CREATURE, MONSTER, TaskSelection.ANY, null, null);
		assertEquals(2, stats.getSampleCount());
		assertEquals("16 minutes over 10 kills", Long.valueOf(96_000), stats.getMillisPerKill());
	}

	@Test
	public void sameLocationFirstUsesOnlyTheTasksAtTheSpotAndSaysWhere()
	{
		LedgerRecord smoke = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		smoke.setSpotId(TestSpots.SMOKE_ID);
		LedgerRecord catacombs = record(CREATURE, MONSTER, 10, 30 * MINUTE);
		catacombs.setSpotId(TestSpots.CATACOMBS_ID);
		// Its own name (Edit location) says Smoke Dungeon, but its spot is the Catacombs: tasks match by spot.
		catacombs.setLocation("Smoke Dungeon");
		LedgerRecord partialHere = record(CREATURE, MONSTER, 10, 100 * MINUTE);
		partialHere.setSpotId(TestSpots.SMOKE_ID);
		partialHere.setPartial(true);
		LedgerRecord otherMonsterHere = record(43, "Dust devils", 10, 100 * MINUTE);
		otherMonsterHere.setSpotId(TestSpots.SMOKE_ID);
		java.util.List<LedgerRecord> records = Arrays.asList(smoke, catacombs, partialHere, otherMonsterHere);

		TaskStatistics here = atSpot(records, smoke("Smoke Dungeon"));
		assertEquals("samples at the spot only", 1, here.getSampleCount());
		assertEquals(Long.valueOf(MINUTE), here.getMillisPerKill());
		assertEquals("the name the current location was given", "Smoke Dungeon", here.getLocation());
	}

	@Test
	public void withNoTaskAtTheLocationEveryLocationCounts()
	{
		LedgerRecord smoke = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		smoke.setSpotId(TestSpots.SMOKE_ID);
		LedgerRecord unknown = record(CREATURE, MONSTER, 10, 30 * MINUTE);
		java.util.List<LedgerRecord> records = Arrays.asList(smoke, unknown);

		TaskLocation.Here[] elsewhere = {new TaskLocation.Here(TestSpots.CATACOMBS_ID, "Catacombs of Kourend"), null,
			TaskLocation.Here.UNKNOWN, new TaskLocation.Here(null, "Smoke Dungeon"), smoke(null)};
		for (TaskLocation.Here location : elsewhere)
		{
			TaskStatistics all = atSpot(records, location);
			assertEquals(String.valueOf(location), 2, all.getSampleCount());
			assertEquals(String.valueOf(location), Long.valueOf(2 * MINUTE), all.getMillisPerKill());
			assertNull(String.valueOf(location), all.getLocation());
		}
		LedgerRecord partial = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		partial.setPartial(true);
		partial.setSpotId(TestSpots.CATACOMBS_ID);
		TaskStatistics onlyPartialThere = atSpot(Arrays.asList(smoke, unknown, partial),
			new TaskLocation.Here(TestSpots.CATACOMBS_ID, "Catacombs of Kourend"));
		assertNull("a partial task is no sample there", onlyPartialThere.getLocation());
		assertEquals(2, onlyPartialThere.getSampleCount());
	}

	@Test
	public void aRecordSavedWithOnlyARegionMatchesByItsRegionsSpotAndANameAloneNever()
	{
		// Saved before spots: its region decides its spot, with no name needed.
		LedgerRecord regionOnly = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		regionOnly.setLocationRegion(TestSpots.SMOKE);
		// A 1.x task named by hand, with no region: no spot, so it never matches a location.
		LedgerRecord nameOnly = record(CREATURE, MONSTER, 10, 50 * MINUTE);
		nameOnly.setLocation("Smoke Dungeon");
		LedgerRecord elsewhere = record(CREATURE, MONSTER, 10, 30 * MINUTE);
		elsewhere.setSpotId(TestSpots.CATACOMBS_ID);
		java.util.List<LedgerRecord> records = Arrays.asList(regionOnly, nameOnly, elsewhere);

		TaskStatistics here = atSpot(records, smoke("Smoke"));
		assertEquals("Smoke", here.getLocation());
		assertEquals(1, here.getSampleCount());
		assertEquals(Long.valueOf(MINUTE), here.getMillisPerKill());
	}

	@Test
	public void theSameLocationSamplesFeedTheSuppliesPerKill()
	{
		LedgerRecord smoke = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		smoke.setSpotId(TestSpots.SMOKE_ID);
		smoke.setSupplies(Collections.singletonMap(100, 10L));
		LedgerRecord catacombs = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		catacombs.setSpotId(TestSpots.CATACOMBS_ID);
		catacombs.setSupplies(Collections.singletonMap(100, 90L));

		TaskStatistics here = atSpot(Arrays.asList(smoke, catacombs), smoke("Smoke Dungeon"));
		assertEquals(Double.valueOf(1d), here.getSuppliesPerKill().get(100));
		assertEquals("every location", Double.valueOf(5d),
			atSpot(Arrays.asList(smoke, catacombs), null).getSuppliesPerKill().get(100));
	}

	@Test
	public void poolsTheSuppliesPerKillOverTheRecordsThatHaveThem()
	{
		LedgerRecord first = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		first.setSupplies(map(100, 12, 101, 30));
		first.setSupplyDoses(Collections.singletonMap(100, 4));
		LedgerRecord second = record(CREATURE, MONSTER, 20, 20 * MINUTE);
		second.setSupplies(map(100, 40, 101, 60));
		second.setSupplyDoses(Collections.singletonMap(100, 4));

		TaskStatistics stats = stats(Arrays.asList(first, second));
		// 52 doses and 90 items over 30 kills.
		assertEquals(52d / 30d, stats.getSuppliesPerKill().get(100), 1e-9);
		assertEquals(3d, stats.getSuppliesPerKill().get(101), 1e-9);
	}

	@Test
	public void aKnownNoUseCountsAsNoSuppliesAndAnUnknownOneStaysUnknown()
	{
		LedgerRecord used = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		used.setSupplies(map(100, 10));
		// A partial task is no sample; a task saved without supplies or values says nothing of them.
		LedgerRecord partial = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		partial.setPartial(true);
		partial.setSupplies(map(100, 1_000));
		LedgerRecord legacy = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		legacy.setSupplies(null);
		TaskStatistics unknown = stats(Arrays.asList(used, partial, legacy));
		assertEquals(2, unknown.getSampleCount());
		assertEquals("10 over the 10 kills that say what they used", Double.valueOf(1d),
			unknown.getSuppliesPerKill().get(100));

		// Valued with no supplies: it used none.
		LedgerRecord noSupplies = record(CREATURE, MONSTER, 10, 10 * MINUTE);
		noSupplies.setLootGeValue(0L);
		noSupplies.setSupplies(Collections.emptyMap());
		assertEquals("10 over 20 kills", Double.valueOf(0.5d),
			stats(Arrays.asList(used, legacy, noSupplies)).getSuppliesPerKill().get(100));
		assertTrue(stats(Collections.singletonList(noSupplies)).getSuppliesPerKill().isEmpty());
	}

	/** The Smoke Dungeon's spot as the current location, shown as {@code name}. */
	private static TaskLocation.Here smoke(String name)
	{
		return new TaskLocation.Here(TestSpots.SMOKE_ID, name);
	}

	@Test
	public void normalizeIsTheOneNameKeyAndBlankIsNull()
	{
		assertEquals("abyssal demons", TaskStatistics.normalize("  Abyssal Demons "));
		assertNull(TaskStatistics.normalize(null));
		assertNull(TaskStatistics.normalize(""));
		assertNull(TaskStatistics.normalize("   "));
	}

	@Test
	public void blankNamesMatchNothing()
	{
		LedgerRecord blank = record(null, "  ", 10, 10 * MINUTE);
		LedgerRecord unnamed = record(null, null, 10, 10 * MINUTE);
		for (String monster : new String[]{"", " ", null})
		{
			assertEquals(0, TaskStatistics.forTask(Arrays.asList(blank, unnamed), SessionTracker.NO_CREATURE, monster,
				TaskSelection.ANY, null, null).getSampleCount());
		}
	}

	@Test
	public void namesNormalizeTheSameUnderATurkishDefaultLocale()
	{
		Locale original = Locale.getDefault();
		try
		{
			// In Turkish, "I".toLowerCase() is a dotless i and "i".toUpperCase() a dotted capital I.
			Locale.setDefault(new Locale("tr", "TR"));
			assertEquals("iron dragons", TaskStatistics.normalize("IRON DRAGONS"));
			assertEquals("Hitpoints", SkillXp.skillName("HITPOINTS"));
			assertEquals("Mining", SkillXp.skillName("mINING"));
			LedgerRecord iron = record(null, "Iron dragons", 10, 10 * MINUTE);
			assertEquals(1, TaskStatistics.forTask(Collections.singletonList(iron), SessionTracker.NO_CREATURE,
				"IRON DRAGONS", TaskSelection.ANY, null, null).getSampleCount());
		}
		finally
		{
			Locale.setDefault(original);
		}
	}

	/** The task's statistics over every location. */
	private static TaskStatistics stats(java.util.List<LedgerRecord> records)
	{
		return TaskStatistics.forTask(records, CREATURE, MONSTER, TaskSelection.ANY, null, null);
	}

	/** The task's statistics at {@code here}'s spot first. */
	private static TaskStatistics atSpot(java.util.List<LedgerRecord> records, TaskLocation.Here here)
	{
		return TaskStatistics.forTask(records, CREATURE, MONSTER, TaskSelection.ANY, here, TestSpots.TABLE::recordSpot);
	}

	private static java.util.Map<Integer, Long> map(int... values)
	{
		java.util.Map<Integer, Long> result = new java.util.HashMap<>();
		for (int i = 0; i < values.length; i += 2)
		{
			result.put(values[i], (long) values[i + 1]);
		}
		return result;
	}

	private static LedgerRecord record(Integer creatureId, String monster, int kills, long activeMillis)
	{
		LedgerRecord record = new LedgerRecord();
		record.setCreatureId(creatureId);
		record.setMonster(monster);
		record.setKills(kills);
		record.setActiveMillis(activeMillis);
		record.setCompleted(true);
		record.setPartial(false);
		return record;
	}
}

package com.shmayvan.slayerledger;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.OptionalLong;
import org.junit.Test;

/**
 * The live "time left" estimate ({@link TaskTimeEstimate}) and how the panel words it.
 */
public class TaskTimeEstimateTest
{
	private static final long MINUTE = 60_000;

	@Test
	public void noKillsGivesNoEstimate()
	{
		assertFalse(TaskTimeEstimate.remainingMillis(10 * MINUTE, 0, 100).isPresent());
		assertFalse(TaskTimeEstimate.killsPerHour(10 * MINUTE, 0).isPresent());
		assertFalse(TaskTimeEstimate.averageKillMillis(10 * MINUTE, 0).isPresent());
	}

	@Test
	public void belowKillThresholdGivesNoEstimate()
	{
		assertFalse(TaskTimeEstimate.remainingMillis(10 * MINUTE, TaskTimeEstimate.MIN_KILLS - 1, 100).isPresent());
		assertTrue(TaskTimeEstimate.remainingMillis(10 * MINUTE, TaskTimeEstimate.MIN_KILLS, 100).isPresent());
	}

	@Test
	public void belowTimeThresholdGivesNoEstimate()
	{
		assertFalse(TaskTimeEstimate.remainingMillis(TaskTimeEstimate.MIN_ACTIVE_MILLIS - 1, 10, 100).isPresent());
		assertTrue(TaskTimeEstimate.remainingMillis(TaskTimeEstimate.MIN_ACTIVE_MILLIS, 10, 100).isPresent());
	}

	@Test
	public void normalCaseIsAverageKillTimesKillsLeft()
	{
		// 10 kills in 5 minutes: 30 s a kill, 120 kills/hour; 40 left is 20 minutes.
		assertEquals(OptionalLong.of(20 * MINUTE), TaskTimeEstimate.remainingMillis(5 * MINUTE, 10, 40));
		assertEquals(120d, TaskTimeEstimate.killsPerHour(5 * MINUTE, 10).getAsDouble(), 1e-9);
		assertEquals(OptionalLong.of(30_000), TaskTimeEstimate.averageKillMillis(5 * MINUTE, 10));
	}

	@Test
	public void resultIsRounded()
	{
		// 100,000 ms / 3 kills * 1 = 33,333.33 ms.
		assertEquals(OptionalLong.of(33_333), TaskTimeEstimate.remainingMillis(100_000, 3, 1));
		// 100,000 ms / 3 kills * 2 = 66,666.67 ms.
		assertEquals(OptionalLong.of(66_667), TaskTimeEstimate.remainingMillis(100_000, 3, 2));
	}

	@Test
	public void nothingRemainingGivesNoEstimate()
	{
		assertFalse(TaskTimeEstimate.remainingMillis(10 * MINUTE, 10, 0).isPresent());
		assertFalse(TaskTimeEstimate.remainingMillis(10 * MINUTE, 10, -1).isPresent());
	}

	@Test
	public void hugeValuesSaturate()
	{
		assertEquals(OptionalLong.of(Long.MAX_VALUE),
			TaskTimeEstimate.remainingMillis(Long.MAX_VALUE, TaskTimeEstimate.MIN_KILLS, Integer.MAX_VALUE));
		// Large but representable: one kill an hour over 1,000 kills, Integer.MAX_VALUE left.
		long hour = 60 * MINUTE;
		assertEquals(OptionalLong.of(hour * Integer.MAX_VALUE),
			TaskTimeEstimate.remainingMillis(1_000 * hour, 1_000, Integer.MAX_VALUE));
		assertTrue(TaskTimeEstimate.averageKillMillis(Long.MAX_VALUE, TaskTimeEstimate.MIN_KILLS).getAsLong() > 0);
		// The panel still formats a saturated estimate.
		assertTrue(LiveSessionSection.timeLeftText(Long.MAX_VALUE, TaskTimeEstimate.MIN_KILLS, Integer.MAX_VALUE, null)
			.startsWith("~"));
	}

	@Test
	public void restoredSessionUsesItsRestoredKillsAndTime()
	{
		// A session restored after a logout: 60 kills in 45 minutes of active time, 90 left. Only the inputs differ.
		assertEquals(OptionalLong.of(67 * MINUTE + 30_000), TaskTimeEstimate.remainingMillis(45 * MINUTE, 60, 90));
	}

	@Test
	public void taskExtensionRaisesTheEstimate()
	{
		// 20 kills in 10 minutes; the task count goes from 30 left to 130 left after an extension.
		OptionalLong before = TaskTimeEstimate.remainingMillis(10 * MINUTE, 20, 30);
		OptionalLong after = TaskTimeEstimate.remainingMillis(10 * MINUTE, 20, 130);
		assertEquals(OptionalLong.of(15 * MINUTE), before);
		assertEquals(OptionalLong.of(65 * MINUTE), after);
	}

	@Test
	public void panelTextEstimatesThenCountsDown()
	{
		assertEquals(LiveSessionSection.TIME_LEFT_UNKNOWN, LiveSessionSection.timeLeftText(MINUTE, 2, 50, null));
		assertEquals(LiveSessionSection.TIME_LEFT_UNKNOWN, LiveSessionSection.timeLeftText(30_000, 5, 50, null));
		assertEquals("~20m", LiveSessionSection.timeLeftText(5 * MINUTE, 10, 40, null));
		assertEquals("~1h 08m", LiveSessionSection.timeLeftText(45 * MINUTE, 60, 90, null));
	}

	@Test
	public void panelTextAfterCompletionOrWithoutTask()
	{
		assertEquals(LedgerHistory.NO_VALUE, LiveSessionSection.timeLeftText(10 * MINUTE, 40, 0, null));
		assertEquals("no task: nothing to estimate even with no kills", LedgerHistory.NO_VALUE,
			LiveSessionSection.timeLeftText(0, 0, 0, null));
	}

	@Test
	public void panelTooltipShowsPace()
	{
		String tooltip = LiveSessionSection.timeLeftTooltip(5 * MINUTE, 10);
		assertTrue(tooltip, tooltip.contains("Kills per hour: 120"));
		assertTrue(tooltip, tooltip.contains("Average kill: 30s"));
		assertEquals("Estimated after 3 kills and 1 minute of active time.",
			LiveSessionSection.timeLeftTooltip(30_000, 10));
	}
}

