	/** A place at the centre tile of {@code region}, on plane 0, as the harness's {@code setPlayerRegion} puts it. */
	static KillPlace centre(int region)
	{
		return place(((region >> 8) << 6) + 32, ((region & 0xFF) << 6) + 32, 0);
	}
